const TRACKS = [
  {id:"acct", name:"Accounting"},
  {id:"beh", name:"Behavioral"},
  {id:"val", name:"Valuation"},
  {id:"deal", name:"M&A and LBO"},
  {id:"mkt", name:"Markets and brainteasers"},
  {id:"sector", name:"Sector & product"},
  {id:"mine", name:"My material"},
];
const BANK = [
 // Accounting — basic
 {id:"a1",t:"acct",l:"Basic",s:90,q:"Walk me through the 3 financial statements.",k:["Income Statement: revenue and expenses over a period, down to Net Income","Balance Sheet: Assets, Liabilities and Shareholders' Equity at a point in time; Assets = Liabilities + Equity","Cash Flow Statement: starts with Net Income, adjusts for non-cash items and changes in working capital, then Cash Flow from Investing and Financing; ends with net change in cash"]},
 {id:"a2",t:"acct",l:"Basic",s:60,q:"Give me examples of major line items on each of the three financial statements.",k:["IS: Revenue, COGS, SG&A, Operating Income, Pre-Tax Income, Net Income","BS: Cash, Accounts Receivable, Inventory, PP&E, Accounts Payable, Accrued Expenses, Debt, Shareholders' Equity","CFS: CFO (Net Income, D&A, SBC, changes in operating assets and liabilities), CFI (CapEx, sale of PP&E, buying/selling investments), CFF (dividends, debt raised/repaid, shares issued/repurchased)"]},
 {id:"a3",t:"acct",l:"Basic",s:90,q:"How do the 3 statements link together?",k:["Net Income from the IS becomes the top line of the CFS","Add back non-cash charges like D&A","Reflect changes in operational Balance Sheet items (working capital) to get CFO","Add investing and financing activities to get net change in cash","Ending cash = beginning cash + net change in cash, flows to top of the BS","Net Income flows into Retained Earnings in Shareholders' Equity; Assets = Liabilities + Equity"]},
 {id:"a4",t:"acct",l:"Basic",s:60,q:"What are the criteria for an item to appear on the Income Statement?",k:["It must correspond only to the period shown (CapEx for a 10-20 year asset does not appear)","It must affect the company's taxes (interest is tax-deductible so it appears; repaying debt principal is not, so it doesn't)"]},
 {id:"a5",t:"acct",l:"Basic",s:60,q:"Name items that never appear on the Income Statement, and explain why.",k:["CapEx, buying/selling investments and PP&E, dividends, issuing or repaying debt principal, issuing or repurchasing shares, changes in BS items like AR or AP","They either don't affect taxes (e.g. dividends, buying inventory) or don't correspond to the period (CapEx buys long-lived assets)"]},
 {id:"a6",t:"acct",l:"Basic",s:45,q:"What's the difference between an Asset and a Liability?",k:["Asset: will result in more cash in the future, directly or indirectly","Liability: will result in less cash in the future; usually owed to external parties and used to fund the business","Equity is also funding but relates to the company's own internal operations / owners"]},
 {id:"a7",t:"acct",l:"Basic",s:45,q:"Why might a company's Net Income differ from its cash flow?",k:["Non-cash expenses like Depreciation, Amortization and Stock-Based Compensation reduce NI but not cash","Revenue and expenses are recorded before cash is received or paid (AR, AP, accrued expenses, deferred revenue)","Cash items that never hit the IS: CapEx, dividends, debt and equity issuance or repayment"]},
 {id:"a8",t:"acct",l:"Basic",s:60,q:"Explain the three sections of the Cash Flow Statement and why the 'current vs. long-term' rule of thumb isn't fully accurate.",k:["CFO: Net Income, non-cash adjustments, changes in operating assets and liabilities","CFI: investments, acquisitions, PP&E / CapEx","CFF: debt, dividends, issuing or repurchasing shares","Exceptions: Deferred Revenue can be long-term but sits in CFO; Short-Term Investments are current but sit in CFI; the Revolver is current but sits in CFF"]},
 {id:"a9",t:"acct",l:"Basic",s:45,q:"What's the difference between Accounts Payable and Accrued Expenses?",k:["Both: expense recorded on the IS but not yet paid in cash; both liabilities","AP: one-time items with specific invoices (e.g. legal services)","Accrued Expenses: recurring monthly items without invoices (wages, utilities, rent)"]},
 {id:"a10",t:"acct",l:"Basic",s:45,q:"What is Deferred Revenue, and is it an asset or a liability?",k:["Cash collected in advance from customers for products/services not yet delivered","It's a liability: the company owes the product/service","Recognized as real revenue over time as it is delivered"]},
 {id:"a11",t:"acct",l:"Basic",s:45,q:"What are Goodwill and Other Intangible Assets, and how do they differ?",k:["Goodwill: premium paid over the target's Shareholders' Equity in an acquisition","Other Intangibles: patents, trademarks, IP, usually from acquisitions","Intangibles amortize (decrease) over time; Goodwill does not amortize (it can be impaired)"]},
 {id:"a12",t:"acct",l:"Basic",s:45,q:"What is Treasury Stock and what is Common Stock and APIC?",k:["Common Stock & APIC: market value of shares at the time they were issued; doesn't change with later share price moves","Treasury Stock: cumulative value of shares the company has repurchased; shown as a negative in equity; also doesn't change with share price"]},
 {id:"a13",t:"acct",l:"Basic",s:45,q:"What is a Deferred Tax Liability?",k:["The company has paid lower taxes than it really owes (book vs. tax differences, e.g. accelerated depreciation)","It must make up the difference with higher tax payments in the future"]},
 // Accounting — changes
 {id:"a20",t:"acct",l:"Intermediate",s:90,q:"Depreciation goes up by $10. Walk me through the three statements. Assume a 40% tax rate.",k:["IS: Operating Income down $10, Net Income down $6 (10 × (1 – 40%))","CFS: Net Income down $6, add back $10 Depreciation, so cash up $4","BS: Cash up $4, PP&E down $10, total Assets down $6","Retained Earnings / Shareholders' Equity down $6, so both sides down $6 and it balances"]},
 {id:"a21",t:"acct",l:"Intermediate",s:90,q:"Accounts Receivable goes up by $100. Walk me through the statements, 40% tax rate.",k:["AR up means revenue recorded but not collected in cash","IS: Revenue up $100, Pre-Tax Income up $100, Net Income up $60","CFS: Net Income up $60, increase in AR is a –$100 cash flow, cash down $40","BS: Cash down $40, AR up $100, Assets up $60; Retained Earnings up $60; balances","AR going down instead = cash collection only: Cash up, AR down, no IS change"]},
 {id:"a22",t:"acct",l:"Intermediate",s:90,q:"Prepaid Expenses goes down by $100. What happens on the statements? 40% tax rate.",k:["We now recognize on the IS an expense already paid in cash","IS: expense up $100, Pre-Tax Income down $100, Net Income down $60","CFS: Net Income down $60, decrease in Prepaid (an asset) is +$100, cash up $40","BS: Cash up $40, Prepaid down $100, Assets down $60; Retained Earnings down $60","Prepaid going up = paying cash in advance: Cash down, Prepaid up, no IS change"]},
 {id:"a23",t:"acct",l:"Intermediate",s:90,q:"Inventory goes up by $100, paid for in cash. Then what if Inventory goes down by $100 because it's sold?",k:["Inventory up: Cash down $100, Inventory up $100, no IS change","Inventory down: COGS up $100 (ask whether there's revenue too), Pre-Tax Income down $100, Net Income down $60 at 40%","CFS: NI –$60, decrease in Inventory +$100, cash up $40","BS: Cash +$40, Inventory –$100, Assets –$60; Retained Earnings –$60"]},
 {id:"a24",t:"acct",l:"Intermediate",s:90,q:"Accrued Expenses goes up by $100. Walk me through it, 40% tax rate.",k:["Expense recorded on the IS but not paid in cash yet (e.g. wages accrued weekly, paid monthly)","IS: Pre-Tax Income –$100, Net Income –$60","CFS: NI –$60, increase in Accrued Expenses (a liability) +$100, cash +$40","BS: Cash +$40; Accrued Expenses +$100, Retained Earnings –$60, L+E +$40; balances","When it goes down: cash payout only, Cash and Accrued Expenses both down"]},
 {id:"a25",t:"acct",l:"Intermediate",s:90,q:"Deferred Revenue decreases by $100. Walk me through the statements at a 40% tax rate.",k:["Previously collected cash is now recognized as revenue","IS: Revenue +$100, Pre-Tax Income +$100, Net Income +$60","CFS: NI +$60, decrease in Deferred Revenue (liability) –$100, cash –$40","BS: Cash –$40; Deferred Revenue –$100, Retained Earnings +$60, L+E –$40","Deferred Revenue going up = cash collected in advance: Cash up, Deferred Revenue up, no IS change"]},
 {id:"a26",t:"acct",l:"Intermediate",s:75,q:"Stock-Based Compensation goes up by $10. What happens, 40% tax rate?",k:["IS: Operating Income –$10, Net Income –$6","CFS: add back $10 SBC as non-cash, cash +$4","BS: Cash +$4; Common Stock & APIC +$10, Retained Earnings –$6, equity +$4; balances"]},
 {id:"a27",t:"acct",l:"Intermediate",s:75,q:"A company raises $100 of debt and uses it to buy $100 of PP&E. Walk me through the statements.",k:["No IS change at the moment of the transaction","CFS: CapEx –$100 in CFI, debt issued +$100 in CFF, net change in cash $0","BS: PP&E +$100, Debt +$100; balances","Afterwards: depreciation and interest expense hit the IS in later periods"]},
 {id:"a28",t:"acct",l:"Advanced",s:90,q:"A company sells PP&E with a book value of $100 for $120. Walk me through the statements at 40% tax.",k:["IS: $20 gain, Pre-Tax Income +$20, Net Income +$12","CFS: NI +$12, subtract the $20 gain in CFO (reclassify it), CFI +$120 for full sale proceeds, net cash +$112","BS: Cash +$112, PP&E –$100, Assets +$12; Retained Earnings +$12; balances","Gain is reclassified from CFO to CFI as part of the full sale price"]},
 {id:"a29",t:"acct",l:"Intermediate",s:60,q:"The company issues $10 in dividends. What happens on the statements?",k:["No IS change: dividends are not tax-deductible","CFS: –$10 in Cash Flow from Financing","BS: Cash –$10, Retained Earnings –$10; balances"]},
 {id:"a30",t:"acct",l:"Intermediate",s:60,q:"Why does the Revolver show up in Cash Flow from Financing even though it's a current liability?",k:["The Revolver is short-term borrowing like a company credit card","It relates to how the company finances itself, not its operations","So it goes in CFF, an exception to the current/long-term rule of thumb"]},
 // Behavioral
 {id:"b1",t:"beh",l:"Must know",s:120,q:"Walk me through your resume. Tell me about yourself.",k:["Clear chronological story in 90 seconds to 2 minutes, not a list","Hook: where you're from or what started your interest","2–3 key experiences with what you did and learned, each linked to finance","A turning point that explains why investment banking","Close with why you're here today / why this role now"]},
 {id:"b2",t:"beh",l:"Must know",s:75,q:"Why investment banking?",k:["Specific, personal reasons, not just money or prestige","Learning curve: exposure to deals, modeling, valuation and senior clients early","Teamwork, intensity and transaction work you've seen or done (cite an experience)","Ties to long-term goals without sounding like you'll leave immediately"]},
 {id:"b3",t:"beh",l:"Must know",s:60,q:"Why our bank in particular?",k:["Specific to the firm: groups, recent deals, culture, size of analyst classes","Mention people you've spoken with and what they said","Connect firm strengths to your interests","Avoid generic answers that fit any bank"]},
 {id:"b4",t:"beh",l:"Must know",s:60,q:"What are your greatest strengths?",k:["2–3 strengths relevant to banking: work ethic, attention to detail, teamwork, quantitative skill","Each backed by a short concrete example","Concise and confident, not arrogant"]},
 {id:"b5",t:"beh",l:"Must know",s:60,q:"What's your biggest weakness?",k:["A real weakness, not a disguised strength like 'I work too hard'","Not a core requirement of the job (e.g. not 'attention to detail')","Specific steps you've taken to improve, with evidence of progress"]},
 {id:"b6",t:"beh",l:"Story",s:120,q:"Tell me about a time you led a team.",k:["STAR structure: Situation, Task, Action, Result","Specific actions you personally took","Quantified result if possible","What you learned and how it applies to an analyst role"]},
 {id:"b7",t:"beh",l:"Story",s:120,q:"Tell me about a time you had a conflict with a teammate and how you resolved it.",k:["STAR structure","Show empathy and you understood the other side","Constructive resolution focused on the team goal","Positive outcome and lesson; don't blame the other person"]},
 {id:"b8",t:"beh",l:"Story",s:120,q:"Tell me about a time you failed.",k:["A real failure with real stakes","Own it; don't blame others","What you changed afterwards","Evidence the lesson stuck (a later success)"]},
 {id:"b9",t:"beh",l:"Story",s:120,q:"Tell me about a deal you've been following.",k:["Name the buyer, target, size, multiple and date","Strategic rationale: why the buyer did it (synergies, growth, market share)","How it was financed (cash, stock, debt) and premium paid","Your view: was it a good deal and why; risks"]},
 {id:"b10",t:"beh",l:"Must know",s:60,q:"Where do you see yourself in five years?",k:["Shows commitment to banking / finance and growth into associate-level responsibilities","Realistic and humble","Doesn't signal leaving for buy-side immediately"]},
 {id:"b11",t:"beh",l:"Must know",s:60,q:"Why should we hire you over the other candidates?",k:["2–3 differentiators with proof","Link to what analysts actually do: detail, hard work, quick learning, teamwork","Confident close"]},
 // Valuation
 {id:"v1",t:"val",l:"Must know",s:120,q:"Walk me through a DCF.",k:["Project the company's unlevered free cash flow for 5–10 years (EBIT × (1 – tax rate) + D&A – CapEx – change in working capital)","Calculate a discount rate, usually WACC","Calculate Terminal Value with the Multiples Method or Gordon Growth Method","Discount the FCFs and Terminal Value to present value and sum them to get Enterprise Value","Bridge to Equity Value and divide by diluted shares for implied share price"]},
 {id:"v2",t:"val",l:"Must know",s:75,q:"What's the difference between Enterprise Value and Equity Value?",k:["Equity Value: value of the whole company to common shareholders only (market cap)","Enterprise Value: value of core operations to all investors (debt, preferred, equity)","EV = Equity Value + Debt + Preferred Stock + Noncontrolling Interest – Cash"]},
 {id:"v3",t:"val",l:"Must know",s:60,q:"Why do you subtract cash when going from Equity Value to Enterprise Value?",k:["Cash is a non-operating asset; EV reflects core operations only","An acquirer effectively gets the cash back, so it reduces the net cost","Equity Value already includes the cash"]},
 {id:"v4",t:"val",l:"Must know",s:75,q:"What are the three main valuation methodologies, and which gives the highest value?",k:["Comparable public companies, precedent transactions, DCF","Precedent transactions usually highest because of the control premium","DCF is most variable and sensitive to assumptions; trading comps often lowest","Mention 'it depends' with reasons"]},
 {id:"v5",t:"val",l:"Must know",s:75,q:"How do you calculate WACC?",k:["WACC = Cost of Equity × % Equity + Cost of Debt × (1 – tax rate) × % Debt + Cost of Preferred × % Preferred","Cost of Equity from CAPM: Risk-free rate + Beta × Equity Risk Premium","Cost of Debt is tax-effected because interest is deductible","Use market values for the weights"]},
 {id:"v6",t:"val",l:"Intermediate",s:75,q:"How do you calculate Terminal Value, and which method is better?",k:["Multiples Method: final-year EBITDA × an exit multiple","Gordon Growth: final-year FCF × (1 + g) / (discount rate – g)","Use one to cross-check the other (implied growth rate / implied multiple)","Gordon Growth is more theoretical; multiples more market-based"]},
 {id:"v7",t:"val",l:"Intermediate",s:60,q:"How do you get from EBITDA to Unlevered Free Cash Flow?",k:["EBITDA – D&A = EBIT","EBIT × (1 – tax rate) = NOPAT","+ D&A (and other non-cash charges) – CapEx – increase in Net Working Capital"]},
 // M&A / LBO
 {id:"d1",t:"deal",l:"Must know",s:120,q:"Walk me through a basic LBO model.",k:["Make assumptions for purchase price, debt and equity funding, interest rates, operations","Create Sources and Uses: how much equity the PE firm contributes","Adjust the Balance Sheet for the new debt and equity","Project the statements and use cash flow to pay down debt","Assume an exit after 3–5 years at a multiple; calculate IRR and money-on-money multiple"]},
 {id:"d2",t:"deal",l:"Must know",s:60,q:"Why do private equity firms use leverage in an LBO?",k:["Reduces the equity check, which magnifies returns (IRR)","Interest is tax-deductible","Debt paydown increases equity value over time","Downside: more risk of default"]},
 {id:"d3",t:"deal",l:"Must know",s:60,q:"What makes a good LBO candidate?",k:["Stable, predictable cash flows","Low CapEx needs","Opportunities to cut costs / improve operations","Strong management team","Reasonable valuation and a credible exit path","Assets that can serve as collateral"]},
 {id:"d4",t:"deal",l:"Must know",s:90,q:"Walk me through a basic merger model, an accretion/dilution analysis.",k:["Project both companies' financials","Determine purchase price and financing mix (cash, debt, stock)","Combine income statements, adding foregone interest on cash, new interest on debt, and synergies","Divide combined Net Income by the new share count (including new shares issued)","Compare combined EPS to buyer's standalone EPS: higher = accretive, lower = dilutive"]},
 {id:"d5",t:"deal",l:"Must know",s:60,q:"Why would a company want to acquire another company?",k:["Growth: faster than organic","Synergies: revenue and cost","Gain market share, eliminate a competitor","Acquire technology, IP, talent or customers","Undervalued target"]},
 {id:"d6",t:"deal",l:"Intermediate",s:60,q:"Shortcut: when is an all-stock deal accretive?",k:["Compare the buyer's P/E to the seller's P/E (at the purchase price)","If buyer's P/E is higher than the seller's, the deal is accretive","Equivalently compare cost of acquisition (seller earnings yield) to cost of stock"]},
 // Markets / brainteasers
 {id:"m1",t:"mkt",l:"Must know",s:120,q:"Pitch me a stock.",k:["Name, ticker, price and a one-line thesis","2–3 specific reasons with numbers (growth, margins, catalysts)","Valuation: why it's mispriced vs. comps or history","Key risks and what would make you wrong","Price target or expected return"]},
 {id:"m2",t:"mkt",l:"Must know",s:60,q:"Where are interest rates and the S&P 500 roughly right now, and what's been moving them?",k:["Approximate current levels (Fed funds, 10-year Treasury, S&P 500)","Recent drivers: inflation data, Fed policy, earnings, macro","Show you follow the markets daily"]},
 {id:"m3",t:"mkt",l:"Brainteaser",s:60,q:"What's the angle between the hour and minute hands at 3:15?",k:["Minute hand at 90 degrees","Hour hand moves 0.5 degrees per minute: 90 + 7.5 = 97.5 degrees","Answer: 7.5 degrees","Talk through the reasoning out loud"]},
 {id:"m4",t:"mkt",l:"Brainteaser",s:60,q:"What's 15% of 360? And what's 1.08 to the 3rd power, roughly?",k:["15% of 360 = 54 (10% = 36, 5% = 18)","1.08³ ≈ 1.26 (1.08 × 1.08 = 1.1664, × 1.08 ≈ 1.2597)","Show quick mental math steps"]},
 {id:"m5",t:"mkt",l:"Must know",s:60,q:"If rates go up, what happens to a company's valuation in a DCF?",k:["Higher risk-free rate raises cost of equity and cost of debt, so WACC rises","Higher discount rate lowers present value, so valuation falls","Also mention possible effects on multiples and growth"]},
];

const PRACTICE_BANK = [{"id":"q-0001","t":"acct","l":"Basic","s":90,"q":"What are the three main financial statements, and what does each one show?","k":["The three main financial statements are:","Income Statement – Shows revenues, expenses, and net profit (or loss) over a period.","Balance Sheet – Presents assets, liabilities, and shareholders’ equity at a point in time.","Cash Flow Statement – Details the company’s cash inflows and outflows, categorized into operating, investing, and financing activities."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0002","t":"acct","l":"Basic","s":90,"q":"How are the three main financial statements interconnected?","k":["The three financial statements are closely linked to provide a full picture of a company's financial health.","Net Income from the Income Statement connects to both the Balance Sheet and the Cash Flow Statement. It flows into the Shareholders’ Equity section on the Balance Sheet under Retained Earnings, and it is the starting point for the Cash Flow Statement.","Changes in Balance Sheet items, such as inventory or accounts receivable, are reflected as adjustments in the operating activities section of the Cash Flow Statement.","Investing and financing activities, such as capital expenditures or issuing debt, affect Balance Sheet items like PP&E, debt balances, and Shareholders’ Equity.","The ending cash balance on the Cash Flow Statement flows back to the Balance Sheet, ensuring that all three statements reconcile."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0003","t":"acct","l":"Basic","s":90,"q":"How does net income flow into the Balance Sheet?","k":["Net income from the Income Statement flows into the retained earnings line under Shareholders’ Equity.","The formula is:","New Retained Earnings = Previous Retained Earnings + Net Income – Dividends Paid"],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0004","t":"acct","l":"Basic","s":90,"q":"If you could only look at one financial statement, which would it be? If you could only look at two, which would they be?","k":["One financial statement: You'd choose the Cash Flow Statement because it provides a clear view of the company's cash inflows and outflows, which are crucial for assessing liquidity and financial health.","Two financial statements: You’d choose the Income Statement and Balance Sheet, since the Cash Flow Statement can be derived from them (provided you have beginning and ending Balance Sheets that align with the period covered by the Income Statement)."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0005","t":"acct","l":"Basic","s":90,"q":"What does the Income Statement typically include?","k":["Revenue (sales)","Cost of Goods Sold (COGS)","Operating Expenses (e.g., SG&A)","Other Income/Expenses (e.g., interest expense)","Taxes","Net Income (bottom line)"],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0006","t":"acct","l":"Basic","s":90,"q":"How is the Balance Sheet organized, and what does it tell you?","k":["It follows the equation: Assets = Liabilities + Shareholders’ Equity.","Assets are listed in order of liquidity, while liabilities are listed by maturity.","Equity represents what’s left over for the owners after liabilities are subtracted from assets.","The balance sheet provides a snapshot of a company’s resources (Assets) and shows how those assets were financed (Liabilities and Shareholders’ Equity) at a given date."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0007","t":"acct","l":"Basic","s":90,"q":"How is the Cash Flow Statement structured?","k":["It has three sections:","Operating Activities – Starts with net income and adjusts for non-cash items and changes in working capital.","Investing Activities – Relates to purchase or sale of long-term assets like equipment or investments.","Financing Activities – Involves issuing or repaying debt/equity and paying dividends."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0008","t":"acct","l":"Basic","s":90,"q":"Under what circumstances might a company record revenue before actually receiving cash?","k":["Under accrual accounting, revenue is recognized when it’s earned and collection is reasonably assured.","Examples include credit sales, subscription services billed before receipt of cash, and long-term contracts that recognize revenue over the service period."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0009","t":"acct","l":"Basic","s":90,"q":"What is the fundamental difference between cash-based accounting and accrual-based accounting?","k":["Cash-based – Recognizes revenue and expenses only when cash changes hands.","Accrual-based – Recognizes revenue when earned and expenses when incurred, regardless of when cash is exchanged."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0010","t":"acct","l":"Basic","s":90,"q":"Can a company be profitable but still run out of cash? How?","k":["Yes.","Under accrual accounting, revenue can be recorded before the cash is received, and expenses can be recorded before the cash is paid out.","Common reasons include:","Significant investment in Working Capital (Inventory, A/R).","High Capital Expenditures (Capex).","Large debt principal repayments.","Dividend payments to shareholders."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0011","t":"acct","l":"Basic","s":90,"q":"Can you provide an example of a scenario where an asset increases but it doesn’t immediately affect the Income Statement?","k":["Buying inventory (whether with cash or on credit) increases the inventory asset on the Balance Sheet but doesn’t affect the Income Statement until that inventory is sold (at which point it appears under COGS)."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0012","t":"acct","l":"Basic","s":90,"q":"How does depreciation affect each financial statement?","k":["Income Statement – Depreciation is an expense that reduces operating income and net income.","Cash Flow Statement – Depreciation is added back in the operating section since it’s non-cash.","Balance Sheet – Accumulated depreciation reduces the value of fixed assets (PP&E)."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0013","t":"acct","l":"Basic","s":90,"q":"If depreciation expense increases by $10 and the tax rate is 30%, how is net income impacted?","k":["Pre-tax income falls by $10, so tax expense is $3 lower (30% of $10).","Net income decreases by $7 overall."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0014","t":"acct","l":"Basic","s":90,"q":"What is working capital, and why is it important?","k":["Working Capital = Current Assets – Current Liabilities.","It measures a company’s short-term liquidity and ability to meet near-term obligations.","A positive working capital suggests the firm can comfortably pay off its short-term liabilities."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0015","t":"acct","l":"Basic","s":90,"q":"When might negative operating net working capital (NWC) be a good thing?","k":["Negative operating NWC can be healthy when customers pay before delivery while suppliers/landlords are paid later—so A/P and accruals exceed A/R and inventory (e.g., fast-food, grocery, big-box retail, certain e-commerce).","The supplier/customer float funds the business, improving cash conversion and reducing external capital needs—as long as it’s durable (high turns, predictable demand, bargaining power)."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0016","t":"acct","l":"Basic","s":90,"q":"Name some non-cash expenses and explain why they’re added back on the Cash Flow Statement.","k":["Depreciation","Amortization","Stock-based compensation","Asset write-downs","These reduce net income but do not require an actual cash outflow during the period, so adding them back restores the true cash position."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0017","t":"acct","l":"Basic","s":90,"q":"How do changes in inventory generally affect the Income Statement?","k":["Simply buying more inventory has no immediate effect on the Income Statement until the inventory is sold.","Once sold, it is recorded as Cost of Goods Sold, reducing the company’s gross profit."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0018","t":"acct","l":"Basic","s":90,"q":"What is the relationship between accounts receivable, accounts payable, and cash flow?","k":["Accounts Receivable – Revenue recognized but not yet collected; an increase in AR can reduce short-term cash flow.","Accounts Payable – Expenses incurred but not yet paid; an increase in AP can boost short-term cash flow."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0019","t":"acct","l":"Basic","s":90,"q":"What is deferred revenue, and how does it arise?","k":["Deferred revenue appears when a company receives payment before providing a product or service.","It is recorded as a liability on the Balance Sheet until the revenue is actually earned."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0020","t":"acct","l":"Basic","s":90,"q":"A client pays $10,000 in advance for a service next quarter. Does that immediately raise net income?","k":["No.","The $10,000 is recorded as deferred revenue on the Balance Sheet until the service is performed.","Only then is it recognized as revenue on the Income Statement, affecting net income."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0021","t":"acct","l":"Basic","s":90,"q":"What does it mean to capitalize an expense rather than expense it immediately?","k":["Capitalizing places the cost on the Balance Sheet as an asset if it confers future economic benefit (lasting more than one year).","It is then depreciated or amortized over time, rather than reducing net income in a single period."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0022","t":"acct","l":"Basic","s":90,"q":"How would you derive the Cash Flow Statement from the Income Statement and Balance Sheet?","k":["Begin with net income, add back non-cash expenses (like depreciation) and adjust for changes in working capital (derived from current assets and liabilities).","Then incorporate cash flows from investing and financing activities. The ending result is the net change in cash."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0023","t":"acct","l":"Basic","s":90,"q":"Can shareholders’ equity go negative, and if so, under what circumstances?","k":["Yes.","Persistent losses can drive retained earnings negative. Also, leveraged buyouts or dividend recapitalizations can deplete equity if owners take out large cash amounts."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0024","t":"acct","l":"Basic","s":90,"q":"What do intangible assets represent on the Balance Sheet?","k":["They are non-physical assets such as patents, trademarks, and customer relationships, often recognized through acquisitions.","Intangible assets are recorded separately from goodwill and may be amortized depending on their useful lives."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0025","t":"acct","l":"Basic","s":90,"q":"Why might EBITDA be an imperfect measure of cash flow?","k":["EBITDA omits capital expenditures, changes in working capital, interest, and tax payments.","These items can significantly affect actual cash flow, making EBITDA an incomplete measure of liquidity."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0026","t":"acct","l":"Basic","s":90,"q":"What are treasury shares (treasury stock), and how do they show up in shareholders’ equity?","k":["Treasury shares are previously issued shares repurchased by the company.","They appear as a contra-equity account in shareholders’ equity, reducing total equity."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0027","t":"acct","l":"Basic","s":90,"q":"What is the difference between depreciation and amortization?","k":["Depreciation applies to tangible assets (e.g., PP&E), while amortization applies to intangible assets (e.g., patents, trademarks).","Both spread the asset’s cost over its useful life, but they differ in terms of the asset type."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Basic"]},{"id":"q-0028","t":"acct","l":"Advanced","s":90,"q":"How would you forecast depreciation for a multi-year model if the company only provides total PP&E figures?","k":["You might estimate a historical depreciation rate (depreciation as a percentage of beginning PP&E).","If available, refine with management guidance on capex plans and asset life, or build a schedule splitting out different asset classes."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0029","t":"acct","l":"Advanced","s":90,"q":"What are deferred tax assets (DTAs) and deferred tax liabilities (DTLs), and when do they arise?","k":["These result from timing discrepancies between deductions recognized for cash-based taxes versus deductions reported for accounting purposes.","Deferred Tax Liabilities (DTLs) occur when tax expense is recognized on the Income Statement, but the actual cash payment hasn't yet occurred.","Deferred Tax Assets (DTAs) occur when taxes are paid in cash before being recognized as expenses on the Income Statement.","Most commonly, these arise from asset write-ups and write-downs during M&A transactions: asset write-ups create deferred tax liabilities, while asset write-downs create deferred tax assets."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0030","t":"acct","l":"Advanced","s":90,"q":"Under what circumstances might goodwill be written down, and how is that shown in the financial statements?","k":["Goodwill is written down if a review shows the fair value of the acquired business (or intangible assets) is below its carrying amount.","The write-down appears as an impairment charge on the Income Statement and reduces the Goodwill line item on the Balance Sheet."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0031","t":"acct","l":"Advanced","s":90,"q":"If a company raises $100 of debt to purchase manufacturing equipment, how does that affect the statements immediately?","k":["Balance Sheet: PP&E up $100, Debt up $100; Cash no change (debt is raised and spent immediately).","Income Statement: No initial impact; interest and depreciation hit later periods.","Cash Flow Statement: +$100 from financing (debt issuance), −$100 from investing (equipment); net $0."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0032","t":"acct","l":"Advanced","s":90,"q":"A company raises $100 of debt to purchase manufacturing equipment.\n\n\n\n\nOne year later, that equipment has 10% depreciation, and the debt carries 5% interest (no principal repayment).\n\n\n\n\nWalk through the changes to the 3 statements after the one year has passed. Assume a 40% tax rate.","k":["Starting on the IS...","Depreciation expense of $10 and interest expense of $5 reduce pre-tax income by $15.","With a 40% tax rate, you pay $6 in taxes, so net income is down by $9.","Moving onto the SCF...","Net income is down $9.","Add back the $10 of non-cash depreciation.","Net cash from operations is therefore up $1 (‑$9 + $10).","No other changes in financing or investing this period, so overall net change in cash is +$1.","Finally, on the BS...","Assets: Cash is up $1. PP&E is down $10 due to depreciation. Net change in assets is ‑$9.","Liabilities: Debt remains at $100, since no principal repayment was made.","Shareholders' Equity: Retained Earnings is down $9, matching the decrease in net income.","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0033","t":"acct","l":"Advanced","s":90,"q":"How does stock-based compensation expense flow through each financial statement?","k":["Income Statement:","SBC appears as an operating expense, lowering pre-tax income and net income.","Cash Flow Statement:","Net income is down, while SBC is added back in CFO, because it’s non-cash. Net increase in cash.","Balance Sheet:","A: On the asset side, cash is up.","L: No change in liabilities.","SE: On the shareholder's equity side, SBC increases Additional Paid-In Capital (APIC) by the full amount and reduces Retained Earnings due to the decrease in net income."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0034","t":"acct","l":"Advanced","s":90,"q":"When is a charge added back to EBITDA as non-recurring, and when would you leave it in?","k":["Add it back only if it is both truly one-time and already inside EBITDA — that is, an operating expense. A single large restructuring or a one-off legal settlement are the standard add-backs.","You leave it in when:","It recurs. A company booking restructuring charges every year is telling you it is a normal cost of doing business.","It never hit EBITDA to begin with. Interest, taxes, and D&A are excluded by definition, so there is nothing to add back.","It is tied to ongoing operations even if non-cash or lumpy — recurring stock-based comp or routine inventory write-downs.","The test is whether the underlying cost is expected to repeat, not what management labels it."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0035","t":"acct","l":"Advanced","s":90,"q":"Why is a capital lease accounted for differently than an operating lease?","k":["A capital lease effectively transfers ownership rights for a longer term, often covering most of an asset’s useful life.","It is capitalized on the Balance Sheet as both an asset and a corresponding lease liability, incurring depreciation and interest expenses.","An operating lease is treated more like a rental, though updated accounting rules often require capitalizing many leases anyway."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0036","t":"acct","l":"Advanced","s":90,"q":"If the Cash Flow Statement shows higher depreciation than the Income Statement, why might that happen?","k":["Some depreciation may be embedded across various Income Statement line items (e.g., part in COGS, part in SG&A).","The footnotes or the Cash Flow Statement might combine these amounts, leading to a higher total depreciation number than what is explicitly shown on the Income Statement."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0037","t":"acct","l":"Advanced","s":90,"q":"How do you typically model items such as accounts payable or deferred revenue in a 3-statement forecast?","k":["Drive each balance off a turnover assumption tied to the line item it relates to:","Accounts payable: Days Payable Outstanding. AP = (DPO / 365) × COGS, holding DPO flat or trending it toward a peer benchmark.","Same logic across working capital — DSO drives AR off revenue, DIO drives inventory off COGS.","Deferred revenue: tied to billings, or as a percentage of revenue, since it is cash collected ahead of performance.","A flat percentage of the associated line item is mathematically equivalent and common in quick models, but days-based drivers benchmark cleanly across companies. Either way, the change in these balances flows through working capital in operating cash flow."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0038","t":"acct","l":"Advanced","s":90,"q":"Describe a bottom-up vs. top-down approach for revenue forecasting.","k":["Bottom-up – Start with individual products/customers, unit volumes, prices, or subscription rates, then aggregate upward.","Top-down – Begin with the total addressable market, estimate market share, and derive revenue from that broader metric."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0039","t":"acct","l":"Advanced","s":90,"q":"Besides losses, what else might cause retained earnings to decrease?","k":["Retained earnings can also decrease due to dividends paid or certain accounting restatements that lower previously reported net income."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0040","t":"acct","l":"Advanced","s":90,"q":"How should significant one-time gains or losses be handled when evaluating a company’s ongoing profitability?","k":["They are typically removed or adjusted out to show normalized earnings (like adjusted EBITDA or adjusted net income).","This approach highlights recurring profitability rather than one-off events."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0041","t":"acct","l":"Advanced","s":90,"q":"Explain the concept of the mid-year convention in depreciation and why it might be used.","k":["The mid-year convention assumes assets are placed in service (or disposed of) halfway through the year, so only a half-year’s depreciation is recorded in the first and last years.","It can increase accuracy for capital-intensive firms purchasing assets continuously throughout the year."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0042","t":"acct","l":"Advanced","s":90,"q":"Under what circumstances might a company have positive net income but be unable to pay its bills?","k":["Large accounts receivable that delay actual cash inflows.","High interest or principal due immediately on debt.","Significant capital expenditures not reflected in net income timing."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0043","t":"acct","l":"Advanced","s":90,"q":"If a company divests a portion of a subsidiary but still retains majority ownership, how are the statements affected?","k":["If control is retained (e.g., 80% → 60%), the sale is an equity transaction: no gain/loss on the Income Statement and no asset remeasurement. Cash increases by proceeds; on the Balance Sheet, Non-controlling Interest (NCI) is adjusted to reflect the new minority share and the plug goes to parent equity/APIC.","On the Cash Flow Statement, proceeds are a financing inflow (changes in ownership interests without a loss of control are financing, not investing). Going forward, “Net income attributable to NCI” rises and “to the parent” falls.","Note on CFO: the statement starts from consolidated net income, which already includes the NCI share — adding NCI income back on top would double count it. You only add it back if you build up from parent-only net income. Either way the ownership change has no direct operating cash impact."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0044","t":"acct","l":"Advanced","s":90,"q":"What is other comprehensive income (OCI), and how is it different from net income?","k":["OCI includes items like foreign currency translation adjustments, unrealized gains/losses on certain securities, and pension adjustments that bypass the Income Statement.","Net income reflects the operating profitability, while OCI accumulates in shareholders’ equity (Accumulated OCI)."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0045","t":"acct","l":"Advanced","s":90,"q":"How might net operating losses (NOLs) factor into a company’s financial projections?","k":["NOLs can offset future taxable income, reducing cash taxes.","You reduce forecasted taxable income by the available NOLs until they’re used up, lowering tax expense and boosting cash flow in those periods."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0046","t":"acct","l":"Advanced","s":90,"q":"Where might you see intangible asset amortization on the Income Statement, and how do you project it?","k":["It could be combined with operating expenses (often SG&A) or shown as a separate line item.","Projection methods vary: a straightforward approach uses straight-line over the asset’s life, whereas a detailed model may allocate different assets distinct amortization schedules."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0047","t":"acct","l":"Advanced","s":90,"q":"If you see a large jump in deferred revenue, what would you want to investigate?","k":["Check if billing practices changed, new subscription deals were introduced, or recognized revenue lagged new billings.","A surge in deferred revenue often means customers have paid upfront for services not yet delivered."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0048","t":"acct","l":"Advanced","s":90,"q":"How do you treat convertible debt on the financial statements, and under what circumstances might it be considered equity?","k":["Convertible debt is initially a liability, with interest expense recognized.","If conversion triggers (e.g., a certain stock price), the debt may convert to equity. Some standards split convertible instruments into debt and equity portions from the start, depending on conversion likelihood."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0049","t":"acct","l":"Advanced","s":90,"q":"Why might a company use accelerated depreciation for tax purposes but straight-line for GAAP reporting?","k":["Accelerated depreciation lowers taxable income sooner, deferring cash tax payments and improving short-term cash flow.","Straight-line depreciation smooths earnings for GAAP, reducing volatility in reported financial statements.","This timing difference creates deferred tax liabilities."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0050","t":"acct","l":"Advanced","s":90,"q":"What is a bill-and-hold arrangement, and how does it affect revenue recognition?","k":["In a bill-and-hold arrangement, the customer is billed but the seller retains possession until a future date.","Revenue recognition may be delayed until the customer obtains control under specific criteria, because delivery is typically a key factor in recognizing revenue."],"collection":"practice","topic":"Accounting","tags":["IB Fundamentals","Accounting","Advanced"]},{"id":"q-0051","t":"val","l":"Basic","s":90,"q":"Why do we look at both Enterprise Value and Equity Value?","k":["They answer different questions.","Enterprise Value is the value of the operating business to all capital providers. Being capital-structure neutral, it pairs with pre-interest metrics: EV/EBITDA, EV/EBIT, EV/Revenue.","Equity Value is the residual claim of common shareholders after debt and other claims. It pairs with post-interest, shareholder-level metrics: P/E and Price/Book.","Equity Value (market cap) is what the public sees and what a buyer pays for the shares, while Enterprise Value lets you compare companies with very different leverage on an operating basis."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0052","t":"val","l":"Basic","s":90,"q":"When evaluating an acquisition, should you focus on Enterprise Value or Equity Value?","k":["You focus on Enterprise Value, because it reflects the total amount that all investors (debt and equity) are entitled to.","Equity Value ignores debt and other obligations that an acquirer will likely have to assume or refinance."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0053","t":"val","l":"Basic","s":90,"q":"What is the basic formula for Enterprise Value?","k":["Enterprise Value = Equity Value + Debt + Preferred Stock + Minority Interest – Cash","Sometimes, other items like capital leases and unfunded pension obligations are added, but this is the standard starting formula."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0054","t":"val","l":"Basic","s":90,"q":"Why is Minority Interest added in the calculation of Enterprise Value?","k":["When a company owns more than 50% of another entity, it consolidates 100% of that subsidiary’s financial results in its own statements.","Metrics like revenue and EBITDA then reflect the entire subsidiary, so you add Minority Interest to align the ownership value with those consolidated figures."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0055","t":"val","l":"Basic","s":90,"q":"How do you calculate fully diluted shares?","k":["Start with the basic share count and add the dilutive effect of options, warrants, or convertible securities.","Use the Treasury Stock Method for options and warrants: assume in-the-money instruments are exercised and any proceeds buy back shares."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0056","t":"val","l":"Basic","s":90,"q":"A company has 100 shares at $10 each and 10 options at a $5 strike. What is its fully diluted Equity Value?","k":["Basic Equity Value is 100 × $10 = $1,000.","Those 10 in-the-money options generate $5 × 10 = $50 if exercised. The company uses that $50 to repurchase 5 shares at $10 each, so net new shares = 5.","Fully diluted share count is 105. Fully diluted Equity Value is 105 × $10 = $1,050."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0057","t":"val","l":"Basic","s":90,"q":"Another company has 100 shares at $10 each and 10 options at a $15 strike. What is its fully diluted Equity Value?","k":["Since the exercise price ($15) exceeds the current share price ($10), the options are out-of-the-money.","No dilution occurs, so fully diluted Equity Value remains 100 × $10 = $1,000."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0058","t":"val","l":"Basic","s":90,"q":"Why subtract cash when calculating Enterprise Value? Is it always correct?","k":["Cash is subtracted because it’s seen as a non-operating asset that can reduce the net purchase price.","In reality, you should subtract only excess cash beyond what’s needed for daily operations, but most models subtract total cash for simplicity."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0059","t":"val","l":"Basic","s":90,"q":"Should Debt always be added to Equity Value when calculating Enterprise Value?","k":["In almost all cases, yes. Debt typically has to be repaid or assumed by the acquirer, so it increases the effective price of the target.","Very rare exceptions exist if the acquirer doesn’t pay off the debt, but that’s uncommon in M&A."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0060","t":"val","l":"Basic","s":90,"q":"Can Enterprise Value be negative? What does that imply?","k":["Yes. If a company has very large cash balances or a minuscule market capitalization, the result can be negative.","This situation typically arises for distressed companies or certain financial institutions with huge cash holdings."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0061","t":"val","l":"Basic","s":90,"q":"Can a company have a negative Equity Value?","k":["A company's market equity value (i.e., its market cap) cannot be negative, as share prices and share counts cannot be negative.","However, a company's book equity value (from the balance sheet) can be negative if it has sustained significant losses over time.","Additionally, a company's implied equity value (calculated from Enterprise Value) can be negative in a valuation or restructuring scenario. This occurs if the company's total debt and other senior claims exceed its enterprise value, indicating that equity holders would receive nothing in a sale."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0062","t":"val","l":"Basic","s":90,"q":"Why do we add Preferred Stock to Equity Value when calculating Enterprise Value?","k":["Preferred Stock has debt-like characteristics: fixed dividends and a higher claim on assets than common equity.","From an acquirer’s viewpoint, it’s more like debt than equity, so it’s included in Enterprise Value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0063","t":"val","l":"Basic","s":90,"q":"A company has 1 million shares at $100 each and $10 million in convertible bonds, par $1,000, conversion price $50. How many diluted shares are there?","k":["Each $1,000 bond converts into $1,000 ÷ $50 = 20 shares. There are $10 million ÷ $1,000 = 10,000 bonds, for 10,000 × 20 = 200,000 new shares.","Total shares = 1,000,000 + 200,000 = 1.2 million (since the bonds are in-the-money)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0064","t":"val","l":"Basic","s":90,"q":"How is Equity Value different from Shareholders’ Equity?","k":["Equity Value is a market-based measure (share price × shares), while Shareholders’ Equity is the book value from the Balance Sheet.","Equity Value can’t be negative, but Shareholders’ Equity can be, depending on a company’s assets and liabilities."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0065","t":"val","l":"Basic","s":90,"q":"Besides Cash, Debt, Preferred Stock, and Minority Interest, which other items might appear in Enterprise Value?","k":["You might adjust for capital leases, unfunded pension obligations, equity investments, or other non-operating assets or liabilities.","Different banks treat these differently, but the main idea is “add debt-like items, subtract cash-like items.”"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0066","t":"val","l":"Basic","s":90,"q":"Why do you add Non-Controlling Interest (Minority Interest) when moving from Equity Value to Enterprise Value?","k":["Minority Interest pertains to a subsidiary that you partially own and fully consolidate. It’s not truly your “equity,” but you still recognize 100% of the subsidiary’s performance (EBITDA).","Hence, you add Minority Interest separately to Enterprise Value so that the numerator (EV) captures the full value of the subsidiary, matching the denominator (EBITDA) which captures the full earnings."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0067","t":"val","l":"Basic","s":90,"q":"In an acquisition, do you value a target based on basic shares or fully diluted shares?","k":["You typically use the fully diluted share count, because any in-the-money options or convertible securities will likely vest or convert in a change-of-control scenario.","That increases the effective purchase price."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0068","t":"val","l":"Basic","s":90,"q":"Could a company's Enterprise Value ever match its Equity Value exactly?","k":["Yes, in theory EV can equal Equity Value when all bridge items sum to zero:","Net Debt = Debt – Cash = 0 (either both are zero or they offset)","No preferred stock","No non-controlling (minority) interests","Because most companies carry some net debt, preferred stock, or minority interest, exact parity is uncommon in practice."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0069","t":"val","l":"Basic","s":90,"q":"Why might you subtract “long-term investments” in the Enterprise Value formula?","k":["If the company owns sizable non-core investments (like minority stakes or securities) that generate returns unrelated to its main operations, some argue those should be subtracted (like cash) to reflect net operating value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0070","t":"val","l":"Basic","s":90,"q":"Is the Enterprise Value the same as the purchase price in an acquisition?","k":["It’s generally close to the purchase price, but not the same.","Control premium: an EV based on the target’s unaffected share price contains no premium. The buyer pays above that for control, which lifts Equity Value and pushes the offer EV above the pre-deal figure.","Cash and debt true-ups: deals are struck cash-free, debt-free, and closing balances differ from what you modeled.","Working capital pegs, earnouts, and rollover equity all shift the final consideration.","So the final purchase price can differ meaningfully from the initially calculated EV."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0071","t":"val","l":"Basic","s":90,"q":"Would you consider “marketable securities” similarly to cash when calculating Enterprise Value?","k":["Generally yes, if they are liquid and can be easily converted to cash. They’re often treated as cash equivalents and subtracted from Equity Value in arriving at Enterprise Value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0072","t":"val","l":"Basic","s":90,"q":"How might unfunded pension obligations affect Enterprise Value?","k":["Unfunded pension obligations represent additional liabilities and are added to Enterprise Value as they signify future cash outflows and financial obligations."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0073","t":"val","l":"Basic","s":90,"q":"What role does preferred stock play in Enterprise Value calculations?","k":["Preferred stock has debt-like characteristics, such as fixed dividends and higher claim on assets than common equity. Therefore, it is added to Equity Value when calculating Enterprise Value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Basic"]},{"id":"q-0074","t":"val","l":"Advanced","s":90,"q":"Why might you add Unfunded Pension Obligations but not Accounts Payable in Enterprise Value?","k":["Accounts Payable is usually a short-term, operational liability that doesn’t require separate financing.","Unfunded Pension Obligations are larger, long-term obligations that often demand external financing. They’re more “debt-like.”"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0075","t":"val","l":"Advanced","s":90,"q":"How might you treat Equity Interests when calculating Enterprise Value?","k":["If a company’s metrics (like revenue or EBITDA) exclude the affiliate company’s performance, you subtract the Equity Interest from the parent’s EV.","The logic: you don’t want to “pay” for a business whose revenue or EBITDA you aren’t actually consolidating."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0076","t":"val","l":"Advanced","s":90,"q":"Should you use the market or book value for Debt in Enterprise Value?","k":["Ideally, use market value if it's available (especially if the debt trades significantly above or below par).","In practice, many models just use the book value from the Balance Sheet for simplicity."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0077","t":"val","l":"Advanced","s":90,"q":"Could the dilution from stock options exceed 10% of the company’s market cap?","k":["Theoretically yes, especially for tech or startup companies with significant option pools.","Such large dilution is uncommon but not impossible."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0078","t":"val","l":"Advanced","s":90,"q":"How do you factor in Convertible Preferred Stock in the Enterprise Value calculation?","k":["If it’s in-the-money, treat it like additional shares. If it’s out of the money, consider it more like debt (since it pays a fixed dividend and ranks above common equity)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0079","t":"val","l":"Advanced","s":90,"q":"How do RSUs and Performance Shares affect the diluted share count?","k":["RSUs are effectively common shares that vest, so you add them to the share count once they’re granted.","Performance Shares convert if certain targets are met (e.g. share price, EPS), so you include them in the diluted count if they are in-the-money."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0080","t":"val","l":"Advanced","s":90,"q":"How are Options Exercisable vs. Options Outstanding handled for share dilution?","k":["If not all options are exercisable yet, you might only consider the portion that’s exercisable.","However, in an acquisition, typically all outstanding options become exercisable, so you might use the total."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0081","t":"val","l":"Advanced","s":90,"q":"Why might we not apply the Treasury Stock Method to convertible bonds?","k":["Convertible bonds don’t generate cash proceeds for the company upon conversion, unlike stock options with an exercise price.","They’re treated as either 100% debt (if out-of-the-money) or additional shares (if in-the-money)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0082","t":"val","l":"Advanced","s":90,"q":"Does free cash flow (FCF) calculation impact how Equity Interests are handled in Enterprise Value?","k":["Yes. If your EBITDA or other operational metrics exclude the affiliate’s performance, you subtract the Equity Interest.","If you included affiliate earnings in FCF, you wouldn’t subtract the Equity Interest in EV to remain consistent."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0083","t":"val","l":"Advanced","s":90,"q":"How do you treat performance-based stock options in the share count?","k":["Similar to standard options, but with an extra hurdle. You only count them in the diluted share count if the performance conditions (e.g., hitting an EBITDA or Revenue target) are met or are highly likely to be met.","If the performance targets are not met, you ignore them, even if the strike price is otherwise in-the-money."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0084","t":"val","l":"Advanced","s":90,"q":"Can convertible debt ever be subtracted from Equity Value?","k":["No. Convertible debt is never subtracted from Equity Value.","Out-of-the-money: treat it as ordinary debt. It is added when bridging from Equity Value to Enterprise Value and subtracted going the other way — never from Equity Value itself.","In-the-money: treat it as equity under the if-converted method. The underlying shares go into the diluted count and the debt comes off, which raises Equity Value rather than reducing it.","Equity Value is built as share price × diluted shares. Debt claims sit in the EV bridge, not inside the equity calculation."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0085","t":"val","l":"Advanced","s":90,"q":"What if a company's debt trades at a discount? Does that affect Enterprise Value?","k":["Technically yes, if you use market values. The “true” debt liability is lower.","Practically, most models use book values for Debt, so it usually doesn’t alter the Enterprise Value in standard practice."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0086","t":"val","l":"Advanced","s":90,"q":"How do capital leases factor into Enterprise Value?","k":["They are generally treated like debt, since they represent a contractual obligation. So you add them to Equity Value to arrive at Enterprise Value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0087","t":"val","l":"Advanced","s":90,"q":"How do you treat operating leases for Enterprise Value under new accounting standards?","k":["Under ASC 842 and IFRS 16, essentially all leases are capitalized: a right-of-use asset and a lease liability on the Balance Sheet.","The liability is generally treated as debt-like and added to Enterprise Value, but you have to stay consistent with the metric you pair it with:","IFRS 16: rent is split into ROU depreciation and interest, so it is already out of EBITDA. Adding the liability to EV is consistent.","ASC 842: operating leases keep a single lease cost in operating expenses, so EBITDA is still net of rent. Add the liability to EV without adding rent back and the multiple is overstated versus an IFRS filer. Finance leases behave like IFRS 16.","The alternative is to exclude operating lease liabilities from EV and leave rent in EBITDA. Either works, as long as it is applied consistently across the comp set."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0088","t":"val","l":"Advanced","s":90,"q":"Why do you subtract equity investments (20-50% ownership) when calculating Enterprise Value from Equity Value?","k":["The parent doesn’t consolidate those financials in its top-line metrics (Revenue/EBITDA).","So you remove the value of that ownership stake from Equity Value to keep the resulting Enterprise Value aligned with the portion of revenue/EBITDA being captured (Operating Value)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0089","t":"val","l":"Advanced","s":90,"q":"How might you handle Net Operating Losses (NOLs) in Enterprise Value?","k":["NOLs can be viewed as an asset that reduces future taxes, so some practitioners subtract them (like cash).","Many ignore them because they’re less liquid than cash and may expire. Treatment varies by bank and scenario."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0090","t":"val","l":"Advanced","s":90,"q":"Do options always create more dilution than warrants?","k":["Not necessarily. It depends on strike prices, volumes, and structures.","Either can be more dilutive if they are deeply in-the-money and represent many potential shares."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0091","t":"val","l":"Advanced","s":90,"q":"What if only part of a convertible issue is in-the-money?","k":["You would split it proportionally. The in-the-money portion converts into equity, and the rest remains as debt."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0092","t":"val","l":"Advanced","s":90,"q":"How are minority interests treated when consolidating financial statements?","k":["Minority interests represent the portion of subsidiary equity not owned by the parent. In EV calculations, minority interests are added to reflect the full consolidated financial performance."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["IB Fundamentals","Enterprise & Equity Value","Advanced"]},{"id":"q-0093","t":"val","l":"Basic","s":90,"q":"What are the four main valuation methodologies?","k":["The four primary approaches are Comparable Companies, Precedent Transactions, Discounted Cash Flow (DCF) Analysis, and Leveraged Buyout (LBO) analysis."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0094","t":"val","l":"Basic","s":90,"q":"Rank the 4 main methodologies from highest to lowest valuation. Is there a strict order?","k":["Typically, Precedent Transactions might yield the highest valuations due to control premiums.","Comparable Companies often yield a bit lower valuation.","A DCF can be higher or lower depending on assumptions, so there's no absolute ranking.","An LBO analysis establishes a \"floor valuation\" for a company, as it represents the value required to generate a required internal rate of return (IRR). This valuation should be lower than a DCF since your discount rate (the firm's IRR in case of an LBO) is higher."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0095","t":"val","l":"Basic","s":90,"q":"When might you not use a DCF in valuation?","k":["If a company's cash flows are highly unpredictable or if debt and working capital are integral to operations, as in banks.","Early-stage firms and biotech with uncertain future cash flows might also make a DCF less reliable."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0096","t":"val","l":"Basic","s":90,"q":"Aside from the “big three,” what other valuation methodologies exist?","k":["Additional methods include:","Liquidation Valuation","Sum-of-the-Parts","LBO Analysis","Replacement Value","M&A Premiums Analysis","Future Share Price Analysis"],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0097","t":"val","l":"Basic","s":90,"q":"When would a Liquidation Valuation be most relevant?","k":["It's frequently used in bankruptcy scenarios to see if equity holders receive any leftover value.","It can also help decide if selling assets individually yields more than a going-concern sale."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0098","t":"val","l":"Basic","s":90,"q":"How does a Sum-of-the-Parts valuation work?","k":["You value each division or segment separately, then add those valuations together for the total.","It's common for conglomerates that have multiple unrelated divisions."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0099","t":"val","l":"Basic","s":90,"q":"Why might you use an LBO Analysis in valuing a company that isn’t being sold to a private equity firm?","k":["An LBO can establish a “floor” valuation, reflecting what a financial buyer could pay to achieve a target IRR.","Strategic buyers might pay more, but the LBO sets a lower bound."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0100","t":"val","l":"Basic","s":90,"q":"What are the most commonly used valuation multiples?","k":["EV/Revenue, EV/EBITDA, EV/EBIT, P/E, and P/BV are commonly used."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0101","t":"val","l":"Basic","s":90,"q":"Give a few examples of industry-specific multiples. Why do they matter?","k":["Examples include EV/Unique Visitors for Internet, EV/Proven Reserves for Oil & Gas, and Price/FFO for REITs.","They are crucial because different industries have unique key value drivers not captured by standard multiples."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0102","t":"val","l":"Basic","s":90,"q":"If we use an industry-specific multiple like EV/Scientists or EV/Subscribers, do we typically use Equity Value or Enterprise Value?","k":["You generally use Enterprise Value because these operational metrics apply to all capital providers."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0103","t":"val","l":"Basic","s":90,"q":"Does an LBO or a DCF typically produce a higher valuation for a given company?","k":["A DCF analysis often results in a higher valuation because it estimates the intrinsic value of a business by discounting all future free cash flows plus a terminal value, capturing long- term growth potential. An LBO model, on the other hand, focuses on the returns required by financial sponsors given leverage, debt paydown, and exit multiples, which tends to set a “floor” valuation based on achievable outcomes.","However, there’s no absolute rule that one will always be higher — either model can produce a higher valuation depending on the assumptions used.","Key differences:","A DCF is an intrinsic valuation that captures the present value of projected cash flows plus a terminal value reflecting long-term expectations.","An LBO valuation focuses on expected returns to equity holders given leverage, exit multiples, debt paydown, and a target IRR; its valuation tends to reflect what a financial sponsor can realistically pay to hit those return hurdles, which is why it is referred to as a \"floor valuation\"."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0104","t":"val","l":"Basic","s":90,"q":"How do you usually present different valuation methods to a client or investor?","k":["Typically with a “football field” chart that shows a range of values derived from each method.","This visually communicates how various methodologies imply different valuations."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0105","t":"val","l":"Basic","s":90,"q":"How might you value a company with no revenue or profit, like a pre-revenue startup?","k":["You would rely on “creative” multiples such as EV/Users or EV/Traffic.","A DCF might be too speculative if you cannot reliably forecast future cash flows."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0106","t":"val","l":"Basic","s":90,"q":"When using Free Cash Flow multiples, do you pair FCF with Enterprise Value or Equity Value?","k":["If it is Unlevered FCF, pair it with Enterprise Value.","If it is Levered FCF, pair it with Equity Value."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0107","t":"val","l":"Basic","s":90,"q":"Are there scenarios where you might see Equity Value / Revenue used?","k":["It's unusual, but might apply to large banks or financial institutions with heavy debt usage or negative enterprise value.","Also possibly if you're comparing both financial and non-financial companies together on a single slide."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0108","t":"val","l":"Basic","s":90,"q":"How do you select Comparable Companies or Precedent Transactions?","k":["Most commonly, you screen by:","Industry","Financial metrics (Revenue, EBITDA, etc.)","Geography","For transactions, also timeframe","Industry is often the key factor, and then you refine from there."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0109","t":"val","l":"Basic","s":90,"q":"Once you select your comps and transactions, how do you use them to value a company?","k":["You take the median multiples from each set and multiply by the relevant metric for the target.","For instance, if the median EV/EBITDA is 7x and your firm's EBITDA is 100 million, its implied EV is 700 million."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0110","t":"val","l":"Basic","s":90,"q":"What do bankers use valuations for in real life?","k":["They’re used in pitch books and client presentations to guide expected valuation ranges.","They also appear in deal documents (like Fairness Opinions) and feed into merger and LBO models."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0111","t":"val","l":"Basic","s":90,"q":"A company and its peer have similar growth and margins. Why might one trade at a premium multiple?","k":["Possibilities include recent earnings beats, patent advantages, or being the market leader.","It could also have intangible reasons that cause the market to price it higher."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0112","t":"val","l":"Basic","s":90,"q":"What are some downsides of using public comps for valuation?","k":["No two companies are perfectly comparable, so results can be skewed.","The stock market can fluctuate or be driven by sentiment.","Thinly traded stocks may not reflect true investor views."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0113","t":"val","l":"Basic","s":90,"q":"How would you account for a strong competitive advantage in your valuation?","k":["You might use multiples at the higher end of the range.","You might add a premium to comps or use more optimistic projections in a DCF."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0114","t":"val","l":"Basic","s":90,"q":"Do you always pick the median multiple for a group of comps or transactions?","k":["Usually yes, but not strictly. If your target is underperforming, you might use the 25th percentile. If it’s outperforming, you might use the 75th."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0115","t":"val","l":"Basic","s":90,"q":"Typically, Precedent Transactions produce higher values than public comps. Any scenario where that might not be true?","k":["If recent M&A deals were at very low multiples or if the M&A market conditions differ significantly from the public market, transactions might be lower or similar."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0116","t":"val","l":"Basic","s":90,"q":"What are some flaws with Precedent Transactions?","k":["They may not be perfectly comparable due to differing deal sizes, structures, and market conditions.","Data can be limited, especially for small private deals.","Deal prices can be influenced by one-off motivations or synergy assumptions."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0117","t":"val","l":"Basic","s":90,"q":"Two identical companies are sold to the same buyer at drastically different multiples. Why?","k":["One may have had more competition in the bidding process.","Or perhaps it had recent bad news depressed stock price, or different market sentiment at deal time."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0118","t":"val","l":"Basic","s":90,"q":"Why might investors prefer EV/EBIT over EV/EBITDA for certain investments?","k":["Investors may dislike EBITDA because it excludes capital expenditures, which can be significant.","EBIT includes depreciation & amortization (D&A), providing a more realistic measure of operating expenses.","While EBIT also excludes CapEx, D&A is still a practical proxy for CapEx; it forces you to at least account for asset maintenance.","Investors care deeply about the true cash the business generates after reinvestment (which EBIT approximates better than EBITDA)."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0119","t":"val","l":"Basic","s":90,"q":"Compare EV/EBIT, EV/EBITDA, and P/E in terms of what they measure and when you use them.","k":["EV/EBIT and EV/EBITDA are capital-structure neutral, reflecting value available to both debt and equity investors.","P/E factors in capital structure since net income is after interest.","EV/EBIT is more relevant if depreciation is sizable, while EV/EBITDA is common where depreciation is smaller."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0120","t":"val","l":"Basic","s":90,"q":"If you were buying a vending machine company, would you pay more for one that owns or leases machines (same cost)?","k":["The leased scenario might lead to higher EV/EBITDA because lease costs hit EBITDA, making the multiple appear higher.","Owned machines use depreciation (below EBITDA), so EBITDA is higher and the multiple appears lower, potentially making it look cheaper."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0121","t":"val","l":"Basic","s":90,"q":"How do you value a private company?","k":["You can still use Comps, Precedents, and a DCF.","You might apply a discount to public comps to reflect illiquidity. Data like Beta or share price won't exist, so you estimate from public peers."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0122","t":"val","l":"Basic","s":90,"q":"Why might we discount public comps for a private target but not discount Precedent Transactions?","k":["In M&A deals, the buyer acquires the entire company, so shares become illiquid regardless.","Public comps assume liquid public shares. For a private firm, you'd discount that because its shares are not publicly traded."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0123","t":"val","l":"Basic","s":90,"q":"In general, can you use private companies as comps or for WACC in a DCF?","k":["Not usually, because private firms lack market caps or Betas. You can use them in Precedent Transactions if data is disclosed."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0124","t":"val","l":"Basic","s":90,"q":"How does the EV/EBITDA multiple help in valuing companies?","k":["EV/EBITDA provides a capital-structure neutral metric that compares a company's enterprise value to its earnings before interest, taxes, depreciation, and amortization. It's useful for comparing companies within the same industry regardless of their debt levels."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0125","t":"val","l":"Basic","s":90,"q":"In what industries is EV/EBITDA commonly used and why?","k":["Industries with similar capital structures, such as manufacturing, technology, and consumer goods, often use EV/EBITDA because it allows for comparison of operational efficiency without the distortion of financing choices."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0126","t":"val","l":"Basic","s":90,"q":"What impact do Stock Options have on the overall valuation of a company?","k":["Stock Options can dilute share count upon exercise, potentially lowering EPS. When modeling, they should be included in the diluted share count to provide a more accurate Equity Value."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0127","t":"val","l":"Basic","s":90,"q":"Why might you prefer using a trailing twelve months (TTM) multiple over a forward multiple in comparable companies analysis?","k":["TTM multiples are based on actual past performance, providing a concrete basis for comparison. Forward multiples rely on forecasts, which can be uncertain and vary based on analyst assumptions."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0128","t":"val","l":"Basic","s":90,"q":"How does a change in the company’s tax rate affect its DCF valuation?","k":["Taxes hit both levers in a DCF. Decrease in taxes leads to a higher FCF (good) but also a higher WACC (bad), and vice-versa.","FCF:","NOPAT = EBIT * (1 − T). Lower T ↑ FCF; higher T ↓ FCF.","WACC:","Cost of Debt (CoD): kd(1 − T). Lower T ↑ after-tax kd; higher T ↓ it.","Cost of Equity (CoE): βL = βU * [1 + (1 − T) * D/E]. Lower T ↑ βL & ke; higher T ↓ both.","The overall effect depends on the magnitude of the opposing moves.","Typically, for a profitable company, the benefit of higher free cash flows from a tax cut outweighs the negative impact of a higher WACC, leading to an increase in valuation, but it's crucial to model both effects."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0129","t":"val","l":"Basic","s":90,"q":"What are some key factors to consider when selecting Comparable Companies?","k":["Key factors include industry sector, size, growth rate, capital structure, geographic location, and profitability metrics to ensure comparability."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Basic"]},{"id":"q-0130","t":"val","l":"Advanced","s":90,"q":"How do you handle valuation for banks and financial institutions?","k":["You often use P/E or P/BV instead of EV-based multiples because debt is central to their business model.","You also might use a Dividend Discount Model (DDM) rather than a standard DCF."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0131","t":"val","l":"Advanced","s":90,"q":"Walk me through an IPO valuation. How is it different from a standard private valuation?","k":["First, you rely on public comps (no Precedents or typical DCF in many cases).","You pick a valuation multiple, apply it to the company’s metrics to get implied Equity Value.","Then you might subtract IPO proceeds or factor them in to get a per-share price based on total shares (existing plus new)."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0132","t":"val","l":"Advanced","s":90,"q":"How do you “calendarize” a public company’s financials if their fiscal year doesn’t match the calendar year?","k":["Use the trailing 12 months approach: TTM = Most recent FY + New partial period – Old partial period.","Likewise, for forward periods, you adjust their projections to align with the calendar months, often using quarterly filings."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0133","t":"val","l":"Advanced","s":90,"q":"How do you do an M&A premiums analysis?","k":["You select public deals, focusing on the share price premium paid over the seller's pre-announcement price.","For each transaction, calculate the 1-day, 20-day premium, etc. Find medians and apply them to your company’s share price to gauge a possible takeover premium."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0134","t":"val","l":"Advanced","s":90,"q":"Explain a future share price analysis.","k":["Project the company’s share price in 1 or 2 years using a median P/E from comps.","Multiply that median P/E by the future EPS to get future share price, then discount back to Present Value at the Cost of Equity."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0135","t":"val","l":"Advanced","s":90,"q":"Both M&A premiums analysis and Precedent Transactions look at past deals. How do they differ in practice?","k":["M&A premiums analysis focuses on how much above the seller’s stock price was paid.","Precedent transactions look more at valuation multiples like EV/EBITDA rather than per-share premiums."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0136","t":"val","l":"Advanced","s":90,"q":"Walk me through a Sum-of-the-Parts valuation.","k":["You value each division individually, often using different sets of comps or a mini-DCF per segment.","Then you add them up for a total combined valuation."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0137","t":"val","l":"Advanced","s":90,"q":"How do you handle NOLs in a valuation, and why might you include them?","k":["You project how they offset taxable income, discounting tax savings to today.","If they’re significant, you might treat them like a non-operating asset that adds value (similar to cash), although approaches vary."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0138","t":"val","l":"Advanced","s":90,"q":"When pulling equity research, how do you decide whose estimates to use?","k":["You might use a consensus from multiple analysts or pick the most detailed “middle-of-the-road” forecast.","You avoid using only your bank’s research to limit bias."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0139","t":"val","l":"Advanced","s":90,"q":"You have missing info (like EBITDA) for several Precedent Transactions. How do you find it?","k":["Try press releases, news articles, or deal reports that mention the seller’s numbers.","Look at buyer’s equity research or databases like Capital IQ for estimates."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0140","t":"val","l":"Advanced","s":90,"q":"How far back and forward would you go for multiples in Comps or Precedents?","k":["Typically TTM and then 1–2 years forward.","Going beyond 2 years forward is less common, especially for transactions data which is often limited."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0141","t":"val","l":"Advanced","s":90,"q":"Company A has a 40% EBITDA margin, trading at 8x EBITDA. Company B has a 10% margin, trading at 16x. Why is comparing them tricky?","k":["Huge margin differences can distort multiples.","The lower-margin business may show a higher multiple, but it doesn’t necessarily mean it’s overvalued."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0142","t":"val","l":"Advanced","s":90,"q":"How do you approach valuing an oil and gas company?","k":["You might use multiples like P/MCFE or P/NAV and rely on Reserve Reports for production forecasts.","Often you do a Net Asset Value model rather than a traditional DCF, given the importance of commodity prices and reserve depletion."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0143","t":"val","l":"Advanced","s":90,"q":"How do you value a REIT, and why is it different from a normal company?","k":["REITs often use Price/FFO or Price/AFFO because depreciation is high yet not truly economic.","Cap rates and NAV are also key. You may also do property-by-property valuation rather than a corporate-level DCF."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0144","t":"val","l":"Advanced","s":90,"q":"What are the limitations of using EV/EBITDA as a valuation metric?","k":["EV/EBITDA does not account for capital expenditures, changes in working capital, or differences in depreciation and amortization policies. It may also ignore non-operating income or expenses, making it an incomplete measure of financial health."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0145","t":"val","l":"Advanced","s":90,"q":"How can differences in capital structure between companies affect the EV/EBITDA multiple?","k":["While EV/EBITDA is designed to be capital-structure neutral, significant differences in debt levels can indicate underlying financial stability or risk. This qualitative aspect can influence investor perceptions and, consequently, the relative multiples."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0146","t":"val","l":"Advanced","s":90,"q":"What is a driver behind choosing an appropriate discount rate in a DCF?","k":["The discount rate should reflect the company’s cost of capital, incorporating both the cost of equity and the cost of debt, adjusted for the company’s capital structure."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0147","t":"val","l":"Advanced","s":90,"q":"Would you apply a control premium when using Precedent Transactions to value a company? Why or why not?","k":["No, you would not. Precedent transactions already represent past acquisitions where buyers paid for control, so the control premium is inherently built into the multiples.","You only apply a control premium to Public Comps, as public market valuations reflect minority, non-controlling stakes."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0148","t":"val","l":"Advanced","s":90,"q":"How do you incorporate market sentiment into a Comparable Companies Analysis?","k":["In Public Comps, sentiment is already embedded in trading multiples at the valuation date—you don’t add a separate “sentiment input.”","Make it explicit by using a recent pricing date or short VWAP window, leaning on NTM multiples if estimates better capture current conditions, and benchmarking against sector/company historical multiple bands to flag froth or dislocation.","For cyclicals, normalize to mid-cycle margins so temporary swings don’t overstate value, show valuation ranges/sensitivities, and triangulate with DCF and precedents."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0149","t":"val","l":"Advanced","s":90,"q":"How does multiple expansion influence Precedent Transactions valuations?","k":["Precedent Transactions are based on historical deals. If the broader market has experienced multiple expansion (rising valuation multiples) since those deals occurred, the precedent multiples might understate the current value of the target.","Conversely, if multiples have contracted, historical precedents might imply an unrealistically high valuation. Analysts must adjust for market conditions between the transaction date and the current date."],"collection":"practice","topic":"Valuation","tags":["IB Fundamentals","Valuation","Advanced"]},{"id":"q-0150","t":"val","l":"Basic","s":90,"q":"Can you explain, in simple terms, how a DCF provides a company's value?","k":["A DCF values a company by forecasting its cash flows and determining how much those cash flows are worth today.","You project free cash flow each year and discount it at an appropriate rate, then estimate a terminal value at the end and discount that as well.","Summing these discounted values yields the company’s total present value."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0151","t":"val","l":"Basic","s":90,"q":"How do you define free cash flow in a DCF context?","k":["Free cash flow is the cash flow available to all providers of capital, after operating expenses, taxes, and reinvestment needs.","It’s typically EBIT × (1 – Tax Rate), plus non-cash items, minus CapEx, minus changes in working capital."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0152","t":"val","l":"Basic","s":90,"q":"What is the purpose of discounting future cash flows?","k":["Money in the future is worth less than money today because of factors like inflation and opportunity cost.","Discounting adjusts those future amounts back to a present value so you can compare them on an apples-to-apples basis."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0153","t":"val","l":"Basic","s":90,"q":"What is the typical projection period for a DCF, and why?","k":["Usually it's around 5 to 10 years.","Anything shorter than 5 years might be too little time, and beyond 10 years becomes too speculative."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0154","t":"val","l":"Basic","s":90,"q":"How do you estimate the discount rate used in a standard DCF?","k":["You typically use the Weighted Average Cost of Capital (WACC), which reflects the required returns of both debt and equity holders.","It includes factors like the cost of equity, the cost of debt, and the capital structure mix."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0155","t":"val","l":"Basic","s":90,"q":"Can you describe how to get from revenue to unlevered free cash flow?","k":["Start with revenue and subtract operating costs to get EBIT.","Then multiply by (1 – Tax Rate), add back depreciation and other non-cash items.","Finally, subtract CapEx and any increases in working capital."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0156","t":"val","l":"Basic","s":90,"q":"What are two ways to estimate the terminal value in a DCF?","k":["The first is the Multiples Method, applying an exit multiple to the final year's EBITDA or EBIT.","The second is the Gordon Growth Method, using a perpetual growth rate formula."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0157","t":"val","l":"Basic","s":90,"q":"How is the terminal value calculated under the Gordon Growth Method?","k":["You take the final year’s free cash flow, multiply by (1 + growth rate), then divide by (discount rate – growth rate)."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0158","t":"val","l":"Basic","s":90,"q":"Which typically produces a higher valuation: the Multiples Method or the Gordon Growth Method for Terminal Value?","k":["It varies. Multiples can be more volatile due to changing market sentiment, while Gordon Growth depends on a stable long-term rate.","No strict rule says which is higher; it depends on assumptions."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0159","t":"val","l":"Basic","s":90,"q":"How would you respond if the terminal value makes up 80% of the DCF’s total value? Is that too high?","k":["Many DCFs yield high reliance on the terminal value. If it's above 70–80%, you might review assumptions, but it’s not necessarily wrong."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0160","t":"val","l":"Basic","s":90,"q":"Why might you use levered free cash flow instead of unlevered free cash flow in your DCF?","k":["If you're only interested in equity value, you can use levered FCF to reflect cash flow available after debt payments.","This approach discounts at the cost of equity rather than WACC."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0161","t":"val","l":"Basic","s":90,"q":"How would you switch from enterprise value to equity value in a DCF model?","k":["The unlevered (FCFF) DCF (discounted at WACC) gives you Enterprise Value (TEV).","You then apply the standard TEV formula to get to equity value (EqV):","TEV = EqV - Cash + Debt + Preferred Stock + Minority Interest","EqV = TEV + Cash - Debt - Preferred Stock - Minority Interest","Once you have your equity value, you can then divide that by fully diluted shares outstanding to obtain the implied share price.","One key difference to understand is:","TEV = unlevered (FCFF) DCF discounted at WACC","EqV = levered (FCFE) DCF discounted at cost of equity","However, if you already have the output of the unlevered DCF (TEV), you don't need to worry about discount rates; you can just apply the standard bridge to get to equity value."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0162","t":"val","l":"Basic","s":90,"q":"If cost of equity rises, does that necessarily mean WACC rises as well?","k":["WACC might rise if the debt portion doesn’t change. But if the company’s debt ratio is large, or cost of debt changes, it may offset the equity changes.","So it’s not guaranteed, but often a higher cost of equity increases WACC."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0163","t":"val","l":"Basic","s":90,"q":"How do you handle working capital changes in a DCF forecast?","k":["If working capital increases, it’s a cash outflow, so you subtract it from free cash flow.","If working capital decreases, it releases cash, so it’s an inflow you add to free cash flow."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0164","t":"val","l":"Basic","s":90,"q":"In what scenario might a DCF not be very useful?","k":["It’s less useful for companies with unpredictable cash flows or for financial institutions where debt is integral to operations (working capital).","In these cases, other valuation methods like comps or transaction multiples, or a dividend discount model, might be preferred."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0165","t":"val","l":"Basic","s":90,"q":"If a company's growth is expected to slow drastically after year 3, what does that mean for your DCF model?","k":["You’d likely project higher growth in initial years, then reflect a step-down to a lower growth rate afterward.","It underscores the importance of carefully modeling revenue growth and margins each year, not just a uniform growth assumption."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0166","t":"val","l":"Basic","s":90,"q":"What are some ways to sanity-check your DCF results?","k":["Compare implied multiples (like EV/EBITDA) to the current market or comps.","Run sensitivity analyses on key inputs and see if valuations seem reasonable.","Check if terminal value is dominating too large a portion of total value."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0167","t":"val","l":"Basic","s":90,"q":"How do you factor cyclical industries, like steel or semiconductors, into a DCF?","k":["It’s tricky. You might project through an entire cycle or normalize earnings over an average cycle to avoid overstating or understating any single year.","You could also do scenario analyses for boom vs. bust conditions."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0168","t":"val","l":"Basic","s":90,"q":"How do you treat stock-based compensation in a DCF?","k":["Some view it as a real expense and subtract it from cash flow, then factor in additional share count as well.","Others might add it back as a non-cash expense but increase diluted shares outstanding, thus adjusting equity value."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0169","t":"val","l":"Basic","s":90,"q":"Why do you typically use 5-10 years for the projection period?","k":["Need enough time before terminal value to achieve steady state","Less than 5 years is too short, more than 10 is too speculative"],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Basic"]},{"id":"q-0170","t":"val","l":"Advanced","s":90,"q":"What is the relationship between Debt and the Cost of Equity?","k":["More debt raises a company’s levered beta, increasing its Cost of Equity."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0171","t":"val","l":"Advanced","s":90,"q":"How do you calculate WACC for a private company?","k":["Use comparables to estimate the cost of equity and debt, and approximate capital structure from similar companies."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0172","t":"val","l":"Advanced","s":90,"q":"What is a mid-year convention in a DCF, and why might you use it?","k":["Mid-year convention assumes cash flows are generated evenly throughout the year, rather than all at period-end.","It shifts discount periods by 0.5 for each year, slightly increasing present value because you discount less heavily."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0173","t":"val","l":"Advanced","s":90,"q":"How do you adjust the terminal value if you use the mid-year convention?","k":["When using the mid-year convention, projection period cash flows are discounted using (n - 0.5) to reflect mid-year timing.","For the Terminal Value using the Exit Multiple Method, the sale is assumed to occur at the end of the year. Therefore, you must discount the Terminal Value using the full period \"n\" rather than \"n-0.5\"."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0174","t":"val","l":"Advanced","s":90,"q":"How would you implement a partial stub period (like 6 months) in a mid-year convention DCF?","k":["You’d split the initial period into that half-year, discounting at 0.5 / 2 = 0.25 if truly mid-quarter.","Then for subsequent full years, the mid-point would be the end of the stub period plus half a year (0.5 + 0.5 = 1.0), then 2.0, 3.0, etc."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0175","t":"val","l":"Advanced","s":90,"q":"How would you value a company that’s planning a major acquisition in Year 3 of your DCF forecast?","k":["You might either model the combined company’s free cash flow from Year 3 onward, adjusting for synergy assumptions and purchase price.","Or you could keep it simpler by showing an outflow (or negative CapEx line item) in Year 3 if it’s purely a cash purchase, though more detailed M&A modeling might be needed for accuracy."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0176","t":"val","l":"Advanced","s":90,"q":"If you’re using leveraged free cash flow (LFCF) in a DCF, what discount rate should you use?","k":["You’d use the cost of equity, because leveraged free cash flow is cash available only to equity holders."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0177","t":"val","l":"Advanced","s":90,"q":"How would you handle a significant debt repayment each year in a levered DCF model?","k":["Since levered FCF includes interest and debt principal payments, you’d explicitly subtract the mandatory principal repayment each period.","This reduces the free cash flow available to equity holders each year."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0178","t":"val","l":"Advanced","s":90,"q":"Explain why a DCF might not be accurate for certain cyclical sectors like airlines.","k":["Airlines can have large swings in revenue and expenses due to fuel costs, demand cycles, and labor contracts.","Projecting stable growth or margins is difficult, and a small assumption error can greatly skew valuation."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0179","t":"val","l":"Advanced","s":90,"q":"If your mid-year convention DCF is yielding a much higher value than the standard approach, is that logical?","k":["It can be higher, but typically the difference is modest. If it’s dramatically higher, you might be double-counting or applying mid-year discounting incorrectly for the terminal value."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0180","t":"val","l":"Advanced","s":90,"q":"When does using a Dividend Discount Model (DDM) make more sense than a typical DCF?","k":["DDM is often used for financial institutions or firms that pay out a stable dividend tied closely to earnings, such as certain utilities.","These companies’ capital structures rely heavily on deposits or insurance float, making standard unlevered FCF analysis less relevant."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0181","t":"val","l":"Advanced","s":90,"q":"In a Dividend Discount Model, how do you calculate the terminal value?","k":["You typically use a P/E-based approach for the final projected year.","Multiply that year’s estimated EPS by an appropriate P/E multiple, or use a Gordon Growth approach on dividends."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0182","t":"val","l":"Advanced","s":90,"q":"If two companies share identical WACC, cash flows, and growth, but one has convertible debt and the other does not, do they have the same enterprise value in a DCF?","k":["Enterprise value from the DCF might be similar initially, but the convertible debt may convert to equity if in-the-money, affecting final equity calculations.","On a purely enterprise value basis, they could appear similar, but final per-share equity might differ."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0183","t":"val","l":"Advanced","s":90,"q":"Does a high beta necessarily mean a higher WACC?","k":["Yes, because beta influences cost of equity, so a higher beta typically increases that.","Since equity is part of WACC, a higher beta usually raises the overall discount rate unless debt is large enough to offset it."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0184","t":"val","l":"Advanced","s":90,"q":"How do you reflect a rapidly changing capital structure (e.g., repeated share issuances) in a DCF?","k":["You might do a levered DCF, factoring new equity issuances into the share count each year.","Alternatively, if using unlevered FCF, you still note changes that might affect WACC or net debt. Some advanced models recalc WACC yearly."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0185","t":"val","l":"Advanced","s":90,"q":"If a company has intangible assets that amortize over time, how does that factor into a DCF?","k":["Amortization is a non-cash expense, so you add it back if it’s lowering EBIT.","However, watch for any real cash costs tied to intangible maintenance or renewal that might not appear as standard CapEx."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0186","t":"val","l":"Advanced","s":90,"q":"If your DCF's implied value is far below a public company's current share price, what are possible reasons?","k":["You might have used overly conservative forecasts or a too-high discount rate.","The market may be factoring intangible positives or synergy prospects not captured in your model.","Or the stock might be overvalued, at least from a pure fundamental standpoint."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0187","t":"val","l":"Advanced","s":90,"q":"Why might you unlever and re-lever beta when looking at comparable companies for a DCF?","k":["Each company has a unique capital structure, so you unlever betas to remove the effect of debt.","Then you re-lever with your target’s structure to reflect its specific risk profile."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0188","t":"val","l":"Advanced","s":90,"q":"How do you handle capital leases or operating leases in the DCF discount rate calculation?","k":["Capital leases are typically treated like debt, which can slightly affect WACC.","Operating leases might be off-balance historically, but under new standards, they appear as lease liabilities, so they can also be seen as debt-like."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0189","t":"val","l":"Advanced","s":90,"q":"If your discount rate is 10% and your terminal growth is 3%, does a 3% perpetual growth automatically mean you’re assuming infinite expansion in real terms?","k":["Mathematically, yes, a 3% growth rate into perpetuity implies the company grows forever.","Practically, we keep that rate modest (like GDP or inflation) to avoid unrealistically large values."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0190","t":"val","l":"Advanced","s":90,"q":"Could we use a negative growth rate for terminal value in a DCF if the business is declining?","k":["Technically yes. If the company's cash flows are expected to shrink perpetually, you could model a small negative rate.","However, negative indefinite growth often implies the business goes to zero, so you must be cautious."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0191","t":"val","l":"Advanced","s":90,"q":"In your final output, do you present a single figure for your DCF valuation or a range?","k":["Typically, you present a range using sensitivity tables for the discount rate and terminal multiples (or growth rates).","You rarely rely on a single “magic number” but rather show best-case, base-case, and worst-case scenarios."],"collection":"practice","topic":"DCF","tags":["IB Fundamentals","DCF","Advanced"]},{"id":"q-0192","t":"deal","l":"Basic","s":90,"q":"What is the primary goal of creating a merger model for two companies?","k":["The main goal is to determine whether the buyer's Earnings Per Share (EPS) will increase or decrease after the transaction.","You do this by combining the buyer's and seller's financials and accounting for acquisition effects such as synergies, financing expenses, and new shares issued."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0193","t":"deal","l":"Basic","s":90,"q":"Can you summarize the basic steps you'd follow when creating a simple merger model?","k":["First, project the buyer and seller's income statements separately.","Next, decide on the purchase price and how it will be financed (cash, debt, stock, or a mix).","Then, combine their statements, adjusting for interest expense, foregone interest on cash, new shares, and any deal-related fees.","Finally, calculate the combined net income and divide by the new share count to see the post-deal EPS and compare it to the buyer’s standalone EPS."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0194","t":"deal","l":"Basic","s":90,"q":"How do you distinguish a merger from an acquisition in practical terms?","k":["In a merger, companies are typically closer in size, and often perceive the deal as a “merger of equals.”","In an acquisition, the buyer is generally larger, and the seller is effectively absorbed into the buyer's operations."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0195","t":"deal","l":"Basic","s":90,"q":"Why might a company choose to acquire a competitor?","k":["Potential reasons include increasing market share, eliminating a rival’s presence, and realizing cost synergies from combining overlapping processes.","By integrating the competitor’s customer base, the acquirer may also achieve stronger pricing power or cross-selling benefits."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0196","t":"deal","l":"Basic","s":90,"q":"If a deal is financed entirely with stock, how can you quickly judge if it's accretive or dilutive?","k":["Look at each company's Price/Earnings (P/E) ratio. If the buyer's P/E is higher than the seller’s, the deal is likely accretive.","If the buyer’s P/E is lower, it’s likely dilutive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0197","t":"deal","l":"Basic","s":90,"q":"What are some reasons a deal might be accretive?","k":["The seller’s net income adds more to the buyer’s bottom line than the buyer loses from foregone interest, interest on new debt, or new share issuance.","Also, strong cost or revenue synergies can boost combined EPS."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0198","t":"deal","l":"Basic","s":90,"q":"What are some reasons a deal might be dilutive?","k":["If the buyer’s foregone interest on cash is high, or the interest on new debt or the issuance of many new shares outweigh the seller’s net income contribution.","Also, any intangible amortization or other acquisition costs might reduce the combined net income."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0199","t":"deal","l":"Basic","s":90,"q":"List the primary acquisition financing methods.","k":["Cash","Debt","Stock","Sometimes there is a mix of these, plus more unusual features like seller notes or earn-outs."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0200","t":"deal","l":"Basic","s":90,"q":"Why might a buyer choose not to use all cash if they have enough on hand?","k":["They could want to maintain a buffer for operations or future opportunities.","They may also believe their stock is favorably valued, making a partial-stock deal more enticing."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0201","t":"deal","l":"Basic","s":90,"q":"What are the main line items you would add or adjust in a merged income statement?","k":["Combined Revenue and Operating Expenses (incorporating cost synergies)","Incremental D&A from asset write-ups (Purchase Price Allocation)","New Interest Expense (from debt used to fund the deal) or Foregone Interest Income (if cash was used)","Tax impact from the new combined pre-tax income","Calculate Pro Forma Net Income, then divide by the new Pro Forma Diluted Share Count to get Pro Forma EPS"],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0202","t":"deal","l":"Basic","s":90,"q":"What is goodwill, in the context of M&A?","k":["Goodwill is an intangible asset representing the amount paid over the fair value of the seller’s identifiable net assets.","It is not amortized but can be impaired if the buyer determines it has overpaid."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0203","t":"deal","l":"Basic","s":90,"q":"How is intangible amortization different from goodwill impairment?","k":["Intangible amortization is a systematic expense over the life of intangible assets like patents or trademarks.","Goodwill impairment happens if the buyer later decides goodwill is overstated, causing a one-time charge."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0204","t":"deal","l":"Basic","s":90,"q":"What are the two main types of synergies?","k":["Revenue synergies, where combined sales or cross-selling opportunities increase total revenues.","Cost synergies, where operations are streamlined, overhead is reduced, or redundant functions are cut, lowering expenses."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0205","t":"deal","l":"Basic","s":90,"q":"Which type of synergy is easier to forecast?","k":["Cost synergies are usually considered more realistic because you can identify overlapping positions or facilities.","Revenue synergies depend on marketing, pricing, or product fit, which are less certain to materialize."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0206","t":"deal","l":"Basic","s":90,"q":"How can a merger model help in negotiations between buyer and seller?","k":["It quantifies the financial impact on EPS and value creation or dilution.","It can guide the buyer’s willingness to pay and highlight synergy targets, influencing deal terms and structure."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0207","t":"deal","l":"Basic","s":90,"q":"Why do most M&A deals not achieve their expected synergies?","k":["Integration challenges, cultural clashes, overoptimistic synergy estimates, and unforeseen market shifts often reduce synergy impact.","Execution risks can prevent cost savings or revenue enhancements from fully materializing."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0208","t":"deal","l":"Basic","s":90,"q":"If two companies have drastically different tax rates, how does that factor into the merger model?","k":["The combined entity might adopt the buyer’s tax rate if that’s where its headquarters or main operations are located.","Alternatively, certain cross-border deals keep separate legal entities with different local tax rates. Modeling requires careful assumption of final integrated tax rates."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0209","t":"deal","l":"Basic","s":90,"q":"What happens to the seller's shareholders' equity in a merger?","k":["In a standard purchase method, the seller’s equity is removed from the combined balance sheet.","Any difference between equity purchase price and the fair value of net assets typically goes to goodwill or other intangible assets."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0210","t":"deal","l":"Basic","s":90,"q":"What is the buyer's main incentive to pay a higher premium in an all-stock deal?","k":["If the buyer believes its stock is overvalued, issuing shares lets it fund a higher headline premium while giving up less intrinsic value.","The more inflated the acquirer’s shares relative to the target, the greater the effective “discount,” making a sizable stock premium affordable."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0211","t":"deal","l":"Basic","s":90,"q":"Does a high purchase premium automatically mean a deal is bad?","k":["No. A high premium might reflect significant synergies or intangible assets.","However, if synergy assumptions are unrealistic, or if market conditions shift, the buyer might face goodwill impairment later."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Basic"]},{"id":"q-0212","t":"deal","l":"Advanced","s":90,"q":"Can you describe how deferred revenue might be adjusted in a merger model?","k":["Historically the buyer wrote the seller’s deferred revenue down to the fair value of the remaining performance obligation — roughly cost to fulfill plus a normal margin. The buyer could then recognize less revenue post-close than the seller would have, depressing reported revenue and EBITDA even though cash collected was unchanged. That is the classic deferred revenue haircut.","Under current US GAAP it is much less common. ASU 2021-08 requires the acquirer to measure acquired contract liabilities under ASC 606, as if it had originated the contract, so the balance generally carries over at the seller’s book value rather than being marked to fair value.","Mention the haircut, since it still appears in older precedents, but note it is now the exception. Either way it is a presentation issue — it never changes the cash the buyer collects."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0213","t":"deal","l":"Advanced","s":90,"q":"What is the difference between a stock purchase and an asset purchase?","k":["In a stock purchase, the buyer acquires all assets and liabilities (including off-balance-sheet items) of the seller.","In an asset purchase, the buyer picks certain assets and assumes chosen liabilities, often avoiding unwanted obligations."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0214","t":"deal","l":"Advanced","s":90,"q":"How does a Section 338(h)(10) election blend aspects of stock and asset deals?","k":["Legally, it’s a stock purchase, so the seller is taxed on any gains.","However, from a tax perspective for the buyer, the assets get a step-up in basis, which can be depreciated, providing tax benefits akin to an asset deal."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0215","t":"deal","l":"Advanced","s":90,"q":"Can you explain how to calculate “break-even synergies” in a merger?","k":["You set the combined EPS accretion or dilution to zero, then back into the synergy amount needed to make it neutral.","Essentially, you solve for how much cost savings (or additional revenue) is required so that EPS neither increases nor decreases."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0216","t":"deal","l":"Advanced","s":90,"q":"How do you handle intangible assets differently from tangible assets in a purchase?","k":["Tangible asset write-ups typically lead to depreciation. Intangible write-ups lead to amortization.","Intangibles might include patents, trademarks, or customer lists, each with different useful lives."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0217","t":"deal","l":"Advanced","s":90,"q":"What is an earn-out, and why might it be included in a deal structure?","k":["An earn-out is a provision that pays the seller additional consideration if performance targets are met post-acquisition.","It bridges valuation gaps between buyer and seller, incentivizing the seller to maintain growth and stability after the deal closes."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0218","t":"deal","l":"Advanced","s":90,"q":"When combining three financial statements in a merger model, what additional complexities arise?","k":["Beyond the income statement, you must merge balance sheets, reconciling the seller’s assets and liabilities with the buyer’s.","You also handle items like goodwill creation, intangible amortization, and possibly reevaluate the cash flow statement for new debt or capital structure changes."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0219","t":"deal","l":"Advanced","s":90,"q":"What is the difference between a buyer's stand-alone valuation vs. its valuation including synergies?","k":["Stand-alone valuation uses the buyer’s existing revenue, expenses, and cash flows.","Including synergies adds potential cost savings or revenue gains from the acquisition, potentially increasing the buyer's implied value."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0220","t":"deal","l":"Advanced","s":90,"q":"If you add 100% of a seller's financials to the buyer’s, is that realistic for pro-forma combined revenue and expenses?","k":["Usually, yes, because post-acquisition, the buyer controls the seller’s entire operations.","However, you may adjust for lost revenue if customers defect, or reduce overlapping costs if there are redundancies."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0221","t":"deal","l":"Advanced","s":90,"q":"How do you account for convertible debt in an M&A scenario?","k":["If it’s in the money, you usually treat it as equity, thus increasing share count.","If out of the money, it remains debt, and you add the interest expense. The purchase agreement may determine how these notes are handled post-merger."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0222","t":"deal","l":"Advanced","s":90,"q":"Why might a buyer assume the seller’s existing options, rather than cashing them out?","k":["The buyer may want to retain the seller’s employees, preserving their vested interests.","Also, it might be cheaper or simpler to let the options remain if the strike price is far above current market value, making them unlikely to be exercised."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0223","t":"deal","l":"Advanced","s":90,"q":"If the buyer’s P/E is 10x and the seller’s P/E is 12x, is an all-stock deal automatically dilutive?","k":["Usually yes, because the buyer is “paying” a higher multiple than its own. But you must also consider synergy contributions or other factors that might offset the higher multiple."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0224","t":"deal","l":"Advanced","s":90,"q":"If the buyer has a significantly lower tax rate than the seller, how might that influence the combined net income?","k":["Post-transaction, the seller’s income might be taxed at the buyer’s lower rate, boosting net income and potentially making the deal more accretive.","However, cross-border or structural complexities could keep the seller’s historical tax structure partially in place."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0225","t":"deal","l":"Advanced","s":90,"q":"How do you treat transaction fees and financing fees in the balance sheet adjustments?","k":["Transaction fees (advisory, legal, accounting) are expensed immediately and reduce retained earnings.","Financing fees on new debt are capitalized and amortized over the life of the debt, but under ASU 2015-03 they are presented as a direct deduction from the carrying amount of that debt — a contra-liability, not an asset. The amortization runs through interest expense.","Exception: fees on a revolving credit facility are still capitalized as a deferred charge on the asset side."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0226","t":"deal","l":"Advanced","s":90,"q":"Can you give an example of how an acquirer might benefit from the seller’s NOLs?","k":["If the seller has large net operating losses, the buyer can use a portion each year (subject to Section 382 limits) to offset the combined entity’s taxable income.","This effectively reduces the buyer’s cash taxes, enhancing net income."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0227","t":"deal","l":"Advanced","s":90,"q":"What might you do if a buyer is uncertain about future performance of the target but still wants to close the deal?","k":["They could include an earn-out or performance-based payouts to tie the final price to actual results.","They might also structure a portion of the consideration in stock, so risk is partially shared if performance disappoints."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0228","t":"deal","l":"Advanced","s":90,"q":"How might you reflect integration costs in your merger model forecasts?","k":["You could model them as a separate line item in the combined income statement, reducing net income for a certain period.","You might also treat them as non-recurring or adjust your synergy timeline if those costs offset synergy benefits in early years."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0229","t":"deal","l":"Advanced","s":90,"q":"Why would a PE buyer’s approach to synergy assumptions differ from a strategic acquirer’s?","k":["Private equity focuses on standalone returns and is less likely to include synergy benefits unless it combines the target with another portfolio company.","Strategic buyers often have direct synergy opportunities like cross-selling or cost elimination across business lines."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0230","t":"deal","l":"Advanced","s":90,"q":"How would you build a sensitivity table for purchase price vs. synergy assumptions?","k":["You set a range for purchase price (like $500M to $700M) and a range for synergy levels (like $10M to $30M), then calculate EPS accretion or dilution under each scenario."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0231","t":"deal","l":"Advanced","s":90,"q":"If the buyer’s share price drops significantly after the deal is announced, how does that affect the total purchase price in a stock deal?","k":["If it’s a fixed exchange ratio, the total dollar purchase price changes, and the seller ends up receiving fewer effective proceeds unless negotiated otherwise.","If it’s a fixed-value structure, the buyer must issue more shares to meet the same total equity price."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0232","t":"deal","l":"Advanced","s":90,"q":"Why might the buyer’s EPS in the first year post-merger be affected by intangible amortization?","k":["Amortization from write-ups of intangible assets reduces operating income.","This non-cash expense can make the deal look more dilutive initially unless you consider adjusted or cash EPS."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0233","t":"deal","l":"Advanced","s":90,"q":"What might happen if the buyer has to refinance all the seller’s debt at a higher rate post-acquisition?","k":["The buyer’s combined interest expense could rise significantly, potentially making the transaction dilutive.","This is common if the seller’s debt has change-of-control provisions requiring immediate repayment or renegotiation."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0234","t":"deal","l":"Advanced","s":90,"q":"Could you see a negative synergy? How would that appear?","k":["Yes. Sometimes acquisitions add complexity or cost structures that reduce overall efficiency.","This would appear as higher combined costs or lost revenue, making the combined entity less profitable than the buyer alone."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0235","t":"deal","l":"Advanced","s":90,"q":"If a buyer is projecting that the combined entity will sell off a portion of the seller's business later, how do you incorporate this?","k":["You might treat that portion as a discontinued operation or build in an assumed divestiture gain/loss at the projected time.","It requires partial pro forma analysis for the segment’s removal and how the net proceeds or lost EBITDA affect the model."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0236","t":"deal","l":"Advanced","s":90,"q":"Why might the buyer recast the seller's financials before merging them?","k":["Recasting removes non-recurring items, adjusts accounting policies to match the buyer’s, and ensures consistent reporting.","It makes the combined forecasts more accurate for synergy calculations and EPS impact."],"collection":"practice","topic":"Merger Model (M&A)","tags":["IB Fundamentals","Merger Model (M&A)","Advanced"]},{"id":"q-0237","t":"deal","l":"Basic","s":90,"q":"What is a leveraged buyout (LBO), in simple terms?","k":["In an LBO, a private equity (PE) firm acquires a company using a high percentage of borrowed funds.","The company’s future cash flows and assets serve as collateral for the debt, and the PE firm contributes a smaller portion of equity.","Over time, the acquired company’s cash flows are used to pay down the debt, ideally generating a strong return upon exit."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0238","t":"deal","l":"Basic","s":90,"q":"Why do PE firms use leverage when acquiring a company?","k":["Using borrowed funds (debt) allows the PE firm to invest less of its own equity.","This smaller equity outlay can significantly boost returns (Internal Rate of Return, or IRR) if the company’s value grows and the debt is paid down successfully."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0239","t":"deal","l":"Basic","s":90,"q":"Can you walk me through a simple LBO model at a high level?","k":["First, you assume a purchase price and determine how much debt and equity the buyer will contribute.","Next, you adjust the company’s balance sheet for the new capital structure, recognizing new debt and wiping out the old shareholders’ equity.","Then, you project the company’s cash flows, use them to pay down the debt over time, and eventually sell or exit at a chosen multiple, calculating the PE firm’s return."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0240","t":"deal","l":"Basic","s":90,"q":"How does an LBO differ from a typical acquisition by a strategic buyer?","k":["A strategic buyer typically integrates the target into its own operations and uses mainly cash or stock, often looking for synergies.","A PE firm, by contrast, uses high leverage, invests less equity, and focuses on improving returns rather than operational integration."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0241","t":"deal","l":"Basic","s":90,"q":"What are the main sources of value creation in an LBO?","k":["Key drivers often include:","EBITDA growth","Debt paydown using cash flows","Multiple expansion at exit","Expense reductions, operational improvements, and add-on acquisitions can also create additional value."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0242","t":"deal","l":"Basic","s":90,"q":"What characteristics make a company a good LBO candidate?","k":["Typically, good LBO candidates have:","Stable and predictable cash flows","Low ongoing CapEx needs","Limited cyclical risk","Potential to cut costs or increase efficiency","Strong asset base for collateral"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0243","t":"deal","l":"Basic","s":90,"q":"How do you figure out how much debt a PE firm can raise for a given buyout?","k":["You analyze comparable LBO deals and credit statistics, such as Debt-to-EBITDA ratios and interest coverage.","Bankers also assess market appetite, the company’s stability, and potential collateral or asset support."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0244","t":"deal","l":"Basic","s":90,"q":"What is the “tax shield” benefit in an LBO?","k":["Interest on the LBO debt is tax-deductible, reducing the company’s taxable income and effectively boosting cash flow.","However, this benefit does not fully offset the added interest expense."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0245","t":"deal","l":"Basic","s":90,"q":"What is the typical exit strategy for a PE firm after an LBO?","k":["Common exits include selling to a strategic buyer, selling to another PE firm, or taking the company public via an IPO.","The goal is to realize a gain on the equity portion of the investment in 3-7 years, on average."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0246","t":"deal","l":"Basic","s":90,"q":"How do you project debt paydown in an LBO?","k":["You start with the company’s projected free cash flow each year (after interest) and allocate as much as possible to mandatory debt repayments first.","Then, if the structure allows optional repayments, you apply any leftover cash flow to reduce the outstanding debt beyond required minimums."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0247","t":"deal","l":"Basic","s":90,"q":"What is a “dividend recap” and why might a PE firm pursue it?","k":["In a dividend recap, the PE-owned company issues additional debt and uses those proceeds to pay a large dividend to the PE sponsor.","This allows the sponsor to “take money off the table” before a formal exit, boosting returns if the company remains stable under higher leverage."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0248","t":"deal","l":"Basic","s":90,"q":"How does an LBO model help establish a “floor valuation” for a company?","k":["A PE firm values the target based on its required IRR and the company’s expected cash flows.","That price is typically lower than what a strategic buyer might pay, serving as a conservative “floor” in valuation discussions."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0249","t":"deal","l":"Basic","s":90,"q":"In an LBO model, what happens to the existing shareholders’ equity?","k":["It’s generally wiped out, replaced by new equity from the PE sponsor and possibly management rollover equity.","On the balance sheet, you remove old equity and insert the new sponsor equity line item."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0250","t":"deal","l":"Basic","s":90,"q":"Why might increasing leverage sometimes reduce the IRR, which is counterintuitive?","k":["If debt service burdens become too large and the company’s growth stagnates or declines, returns can suffer.","Excessive interest costs or principal repayments can overshadow operational improvements."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0251","t":"deal","l":"Basic","s":90,"q":"Does the tax shield fully offset the negative impact of higher interest expense in an LBO?","k":["Not entirely. While tax-deductible interest provides some benefit, the added interest can still overwhelm cash flows if leverage is too high."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0252","t":"deal","l":"Basic","s":90,"q":"Give an example of a real-life scenario that mirrors an LBO structure.","k":["Buying a house with a mortgage is often cited: You pay a down payment (equity) and borrow the rest.","Mortgage interest is tax-deductible, and if you sell the house for a gain, your return on the down payment can be substantial."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0253","t":"deal","l":"Basic","s":90,"q":"How does the IRR (Internal Rate of Return) differ from the company’s growth rate in an LBO model?","k":["IRR measures the annualized return on the PE firm’s equity investment.","Company growth rate affects cash flow and debt paydown, influencing IRR, but IRR also depends on exit multiple, timing, and initial leverage."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0254","t":"deal","l":"Basic","s":90,"q":"How does an LBO model capture the idea of “time value of money?”","k":["By calculating IRR, the model accounts for the fact that money today is worth more than money in the future.","The IRR formula effectively discounts future cash flows or proceeds at a rate that reflects return expectations."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-0255","t":"deal","l":"Advanced","s":90,"q":"How would you model multiple tranches of debt (e.g., Revolver, Term Loan A, Term Loan B) in an LBO?","k":["You create a debt schedule for each tranche, detailing starting balances, mandatory amortization, interest payments, and optional repayments in order of seniority.","Revolver is typically drawn/paid first, followed by Term Loan A (amortizing), then Term Loan B (bullet or minimal amortization)."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0256","t":"deal","l":"Advanced","s":90,"q":"How do maintenance covenants differ from incurrence covenants in an LBO context?","k":["Maintenance covenants require the company to maintain certain financial ratios (e.g., Debt/EBITDA) each quarter.","Incurrence covenants restrict specific actions (e.g., paying dividends or making acquisitions) without lender permission."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0257","t":"deal","l":"Advanced","s":90,"q":"Why might a company issue PIK (Payment In Kind) debt in an LBO, and how do you model it?","k":["PIK debt doesn't require cash interest payments. Instead, interest accrues to the principal, reducing short-term cash needs but raising total debt.","In your model, record PIK interest as an expense but add it back as a non-cash item on the cash flow statement, and increase the debt balance accordingly."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0258","t":"deal","l":"Advanced","s":90,"q":"How do you handle intangible write-ups or write-downs in an LBO scenario?","k":["Similar to a typical M&A process, you adjust assets upward or downward, which affects goodwill and intangible assets on the balance sheet.","The resulting depreciation or amortization flows through the income statement, reducing net income (and potentially affecting tax calculations)."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0259","t":"deal","l":"Advanced","s":90,"q":"Explain how you might adjust the income statement for synergy assumptions in an LBO.","k":["Cost synergies and revenue synergies may be considered:","Cost synergies reduce operating costs or COGS, boosting operating income.","Revenue synergies increase sales, though you must account for additional expenses to get net benefit."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0260","t":"deal","l":"Advanced","s":90,"q":"If the PE firm places management stock options or a management equity rollover in the LBO, how does that affect returns?","k":["Some equity value is shared with management, reducing the sponsor’s portion of the exit proceeds.","However, incentivized management may drive stronger performance, potentially boosting overall exit valuation and partially offsetting that dilution."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0261","t":"deal","l":"Advanced","s":90,"q":"In an LBO, how do you decide whether to model a full balance sheet or a simplified approach?","k":["It depends on the level of detail needed, time constraints, and the audience.","For a quick approach, you can omit a detailed balance sheet, focusing on debt schedules and cash flow. For a more robust analysis, you reconcile all balance sheet accounts post-transaction."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0262","t":"deal","l":"Advanced","s":90,"q":"How do you calculate the IRR for a mezzanine or high-yield debt investor?","k":["Tally the debt’s initial principal as a negative outflow and each year’s interest/principal repayments as positive inflows.","At maturity or exit, consider the final principal repayment. Calculate IRR using these cash flows in Excel."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0263","t":"deal","l":"Advanced","s":90,"q":"In an LBO with multiple tranches, how do you prioritize optional debt repayments?","k":["Typically, you repay the most senior tranche with any extra cash first (like a revolver or Term Loan A).","Then you move to lower seniority loans (like Term Loan B). High-yield debt often lacks optional prepayment."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0264","t":"deal","l":"Advanced","s":90,"q":"How do you handle the revolver in an LBO if the company doesn’t have enough cash to meet mandatory debt payments?","k":["You draw on the revolver up to its limit to cover the shortfall. This borrowing increases debt, but ensures payments are met.","In subsequent periods, available cash flow first repays the revolver balance before paying down other tranches."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0265","t":"deal","l":"Advanced","s":90,"q":"Why might debt investors in an LBO achieve a higher return than equity investors?","k":["If the exit multiple contracts or business performance is weaker, the equity holders’ upside may be minimal or negative.","Meanwhile, debt investors receive steady interest payments and principal repayment, yielding a higher IRR if equity returns are lackluster."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0266","t":"deal","l":"Advanced","s":90,"q":"Why might an LBO sponsor willingly pay a slightly higher purchase multiple if the financing is favorable?","k":["Cheap financing (lower interest, flexible covenants) can offset a higher entry price, preserving or enhancing the sponsor’s returns.","If the sponsor believes operational improvements or synergies will still drive strong IRR, they might pay up for a competitive asset."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0267","t":"deal","l":"Advanced","s":90,"q":"Walk me through how you might stress-test an LBO model for downside scenarios.","k":["You lower revenue growth, EBITDA margins, or assume higher interest rates. Then check if the company can still service debt and what the IRR becomes.","You may also reduce the exit multiple or assume a delay in exit timing to see how returns suffer."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0268","t":"deal","l":"Advanced","s":90,"q":"Can you explain why a PE firm might maintain a minimum cash balance in an LBO model?","k":["The sweep is an annual, end-of-period mechanic, but the business needs cash every day. Sweep the balance to zero on December 31 and the company still has payroll, suppliers, and inventory to fund in January.","Intra-year working capital swings. Cash builds and drains with seasonality and collection timing, so a business that is cash-generative annually can be deeply negative in a given month.","Liquidity and covenant cushion. Sponsors and lenders want headroom so a small miss does not force a revolver draw or trip a covenant.","Model mechanics. Without a floor the sweep can drive cash negative.","The minimum is sized off operating needs — often a few weeks of operating expenses or a percentage of revenue — and only cash above it is swept."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0269","t":"deal","l":"Advanced","s":90,"q":"What are some common “exit assumptions” you would see in an LBO, and how do they affect returns?","k":["You might assume an exit after 3–7 years at an EBITDA multiple similar to or higher/lower than purchase.","Changes in exit multiple or timing directly affect the IRR; selling sooner or at a higher multiple generally yields higher returns."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0270","t":"deal","l":"Advanced","s":90,"q":"If you have to build a complex LBO model quickly, what are the key areas you’d focus on?","k":["Areas typically include:","Sources & Uses (financing structure)","Debt schedules (mandatory and optional repayments)","High-level operating projections (EBITDA, FCF)","Exit assumptions to compute IRR","A fully integrated model can be built later, but these elements are critical first."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0271","t":"deal","l":"Advanced","s":90,"q":"What are some advanced ways you could fine-tune an LBO model to be more accurate?","k":["Potential refinements include:","Monthly or quarterly debt paydown for precise interest","Comprehensive covenant checks each period","Full balance sheet integration with working capital details","Modeling partial dividend recaps or incremental acquisitions","Incorporating seasonality in revenue or expenses"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0272","t":"deal","l":"Advanced","s":90,"q":"If the sponsor wants to compute a certain IRR for partial exits or recapitalizations, how would you modify the LBO model?","k":["You’d include “cash out” events when the sponsor takes partial proceeds (e.g., via dividend recap or partial share sale).","Each distribution is treated as a positive cash flow to the sponsor in the IRR calculation, adjusting the overall return timeline."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0273","t":"deal","l":"Advanced","s":90,"q":"Can you use an LBO model to price an asset even if you’re not a PE firm intending to do a leveraged buyout?","k":["Yes. You could use the LBO methodology to see what IRR a hypothetical leveraged buyer would require, effectively setting a floor on valuation.","However, strategic or other buyers might pay more if synergies or other strategic considerations exist."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0274","t":"deal","l":"Advanced","s":90,"q":"If the target’s EBITDA unexpectedly declines post-buyout, how does that affect the debt structure?","k":["Lower EBITDA may breach covenants if it’s bank debt with maintenance ratios.","It also means less free cash flow to service or repay debt, increasing the risk of default or forced restructuring."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0275","t":"deal","l":"Advanced","s":90,"q":"If a PE firm invests $200 million of equity and sells the company for $400 million in equity value after 5 years, what’s the approximate IRR, ignoring any cash flow distributions?","k":["Doubling in 5 years is roughly a 15% IRR (actual is close to 14.9%).","As a rule of thumb, doubling in 3 years is ~26%, in 4 years ~19%, in 5 years ~15%, and in 6 years ~12%."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0276","t":"deal","l":"Advanced","s":90,"q":"If a PE firm implements a series of add-on acquisitions, how do you model that in the LBO?","k":["You treat each add-on as a mini-acquisition, adjusting the financing structure for more debt or equity.","You then integrate each add-on’s EBITDA/revenue into the core forecasts, updating the debt schedules and synergies accordingly."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0277","t":"deal","l":"Advanced","s":90,"q":"Could the sponsor do a Section 338(h)(10) election in a leveraged buyout?","k":["Typically no. That election requires the buyer to be a C corporation, while PE deals are often done through LLCs or partnership structures."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0278","t":"deal","l":"Advanced","s":90,"q":"What is a “stub period” in an LBO model, and how do you handle it?","k":["A stub period is a partial year between closing and the company’s fiscal year-end.","You adjust interest and debt paydown calculations proportionally. For instance, if it’s a 3-month stub, you accrue a quarter’s interest expense and partial principal repayment."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0279","t":"deal","l":"Advanced","s":90,"q":"Why might a mezzanine investor accept equity “kickers” or warrants in an LBO?","k":["These provide upside if the equity value appreciates, compensating for higher risk in mezzanine positions.","Warrants allow them to purchase shares at a set price, boosting returns if the company does well."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0280","t":"deal","l":"Advanced","s":90,"q":"How does a “management rollover” of equity affect the purchase price and IRR in an LBO?","k":["Management reinvests a portion of their existing equity into the new structure at closing, reducing the net equity the PE firm must fund.","This can improve IRR since less new equity is contributed, but management also shares in the eventual upside at exit."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0281","t":"deal","l":"Advanced","s":90,"q":"Can the IRR in an LBO model reach extremely high levels if the holding period is very short?","k":["Potentially, yes. Selling quickly at a premium can yield an extraordinarily high annualized IRR.","But short flips are rare unless a buyer is found quickly, or circumstances allow for a rapid multiple expansion or strategic sale."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0282","t":"deal","l":"Advanced","s":90,"q":"Why might a sponsor re-leverage the business before exit instead of just selling it outright?","k":["They may do a recap or dividend recap to pull out cash if market conditions aren’t prime for a full sale or IPO.","This allows them to realize partial returns while waiting for a more favorable exit environment."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0283","t":"deal","l":"Advanced","s":90,"q":"Suppose you have 3x senior leverage and 5x junior leverage on a deal. What happens if you sell the business for 9x EBITDA, and what if you sell it for 8x EBITDA?","k":["Exit at 9× EBITDA (Enterprise Value): repay 3× senior first, then 5× junior (total 8×). All debt is covered, leaving 1× EBITDA for equity.","Exit at 8× EBITDA: the 8× sale value exactly equals total debt (3× senior + 5× junior). Equity receives 0×; senior is paid in full, junior is paid in full, nothing remains for shareholders."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["IB Fundamentals","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0284","t":"acct","l":"Advanced","s":90,"q":"Assuming a 30% tax rate, walk me through 3 statements with a:\n\n\n\n\n$50 increase in stock-based compensation","k":["Starting on the IS...","Pre-tax income down by 50","NI down by 35","Moving onto the SCF...","NI down by 35","Add back 50 in CFO since stock-based compensation is a non-cash expense","Net change in cash is up 15","Finally, on the BS...","A: Assets up by 15 (cash up 15)","L: No change in liabilities","SE: Shareholder's Equity up by 15 (stock-based comp up 50, NI down 35)","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0285","t":"acct","l":"Advanced","s":90,"q":"Assuming a 30% tax rate, walk me through 3 statements with a:\n\n\n\n\n$120 decrease in depreciation","k":["Starting on the IS...","Pre-tax income up $120","NI up $84","Moving onto the SCF...","NI +84","Depreciation is down by 120, meaning you lose that 120 non-cash add-back","Net cash down 36","Finally, on the BS...","A: Cash down 36, PP&E up 120, net +84","L: No change","SE: +84 from NI","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0286","t":"acct","l":"Advanced","s":90,"q":"Assuming a 30% tax rate, walk me through 3 statements with a:\n\n\n\n\n$100 interest expense (50% cash interest / 50% PIK interest) and $50 interest income","k":["Starting on the IS...","Net interest expense is 50 (100 expense - 50 income)","Pre-tax income down 50","NI down 35","Moving onto the SCF...","NI -35","Add back 50 PIK in CFO","Net +15 in cash","Finally, on the BS...","A: Cash +15","L: Debt +50 (PIK portion), offset by no other changes in L","SE: -35 in Retained Earnings","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0287","t":"acct","l":"Advanced","s":90,"q":"Assuming a 30% tax rate, walk me through 3 statements with a:\n\n\n\n\n$20 decrease in Deferred Revenue","k":["A decrease in Deferred Revenue means the performance obligation has been satisfied — the product was delivered or the service performed — so the liability comes off the Balance Sheet and is recognized as revenue. You are not putting deferred revenue on the IS; you are converting previously collected cash into earned revenue, which is what the matching principle requires. No new cash arrives here.","Starting on the IS...","Revenue +20 (obligation now satisfied)","Pre-tax income +20","NI +14","Moving onto the SCF...","NI +14","Subtract 20 for the decrease in Deferred Revenue (no new cash collected)","Net -6 in cash (Taxes paid)","Finally, on the BS...","A: Cash -6","L: Deferred Revenue -20","SE: +14 in Retained Earnings","...and the Balance Sheet balances (-6 = -20 + 14)"],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0288","t":"acct","l":"Advanced","s":90,"q":"MULTI-STEP: Assuming a 20% tax rate, walk me through 3 statements with a:\n\n\n\n\nYear 0: Buy PP&E for $100 using Debt.\n\n\n\n\nYear 2: PP&E depreciates over 10-year period using straight-line depreciation. After two years, you sell the PP&E for $120. Walk me through the statements for the sale transaction only.","k":["Year 0","Starting on the IS...","No change","Moving onto the SCF...","CFI -100 for PP&E","CFF +100 from debt","Net change in cash 0","Finally, on the BS...","A: PP&E +100","L: Debt +100","SE: No change","...and the Balance Sheet balances","Year 2","Starting on the IS...","Book value is 80 (2 yrs x 10/yr depreciation)","Sale at 120 = gain of 40","Pre-tax +40","NI +32","Moving onto the SCF...","NI +32","Subtract gain of 40","Add 120 from sale","Net +112 in cash","Finally, on the BS...","A: Cash +112, PP&E -80, net +32","L: No change (assuming debt remains the same)","SE: +32 from NI","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0289","t":"acct","l":"Advanced","s":90,"q":"MULTI-STEP: Assuming a 20% tax rate, walk me through 3 statements with a:\n\n\n\n\nYear 0: Buy Land for $90 using cash on hand.\n\n\n\n\nYear 2: Straight-line depreciation occurs over a 10-year period. After two years, you sell the land for $90.","k":["YEAR 0","Starting on the IS...","No change","Moving onto the SCF...","CFI -90 for land","Net cash -90","Finally, on the BS...","A: Land +90, Cash -90","L: No change","SE: No change","YEAR 2","Trick: Land typically does not depreciate.","Starting on the IS...","No gain/loss if sold at cost → NI unchanged","Moving onto the SCF...","+90 in CFI from sale","Net +90 to cash","Finally, on the BS...","A: Cash +90, Land -90","L, SE: Unchanged"],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0290","t":"acct","l":"Advanced","s":90,"q":"MULTI-STEP: Assuming a 20% tax rate, walk me through 3 statements with a:\n\n\n\n\nYou raise $100 debt with 5% interest and 10% yearly principal repayment. You use that money to purchase $100 of short-term assets that have 10% yearly interest income attached.\n\n\n\n\nPart 1) Right when you raise the debt and purchase short-term assets\n\n\n\n\nPart 2) After one year","k":["Part 1","IS: No change","SCF: CFI -100 for assets, CFF +100 debt, net 0","BS: A +100 (assets), L +100 (debt), SE no change","Part 2","IS: +10 interest income, -5 interest expense = +5 pre-tax, +4 NI","SCF: NI +4, repay 10 principal, net -6 cash","BS: Cash -6, Debt -10, SE +4 from NI"],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0291","t":"acct","l":"Advanced","s":90,"q":"Suppose your model shows Year 2 revenue at $100 million with an EBITDA of $10 million, and 50% of the cost base is variable. If revenue drops by 10% next year, what happens to EBITDA?","k":["At $100 million revenue and $10 million EBITDA, total costs are $90 million.","If half of those costs ($45 million) vary directly with sales, and revenue falls 10% to $90 million, variable costs drop to $40.5 million (10% less).","Fixed costs remain $45 million, for total costs of $85.5 million.","EBITDA is $90 million revenue minus $85.5 million cost = $4.5 million.","EBITDA declines by $5.5 million (from $10.0 to $4.5)."],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0292","t":"acct","l":"Advanced","s":90,"q":"How do you calculate DSO (days sales outstanding), inventory days, and days payable?","k":["DSO = (Accounts Receivable / Revenue) x 365","Inventory Days = (Inventory / COGS) x 365","Days Payable = (Accounts Payable / COGS) x 365"],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0293","t":"acct","l":"Advanced","s":90,"q":"If you are the CFO and about to miss earnings by $0.01, what levers can you pull to avoid that miss?","k":["You can manipulate short-term timing of revenue or expenses, such as:","Early recognition of some revenue if permissible","Delay certain expenses (e.g., marketing or SG&A)","Change inventory accounting methods","Adjust depreciation assumptions","Repurchase a small number of shares to reduce share count","All subject to legal and accounting constraints."],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0294","t":"acct","l":"Advanced","s":90,"q":"What is Sarbanes-Oxley (SOX) and what impact does it have?","k":["SOX is a 2002 U.S. law passed in response to major accounting scandals (Enron, WorldCom).","It mandates stricter internal controls, audits, and CEO/CFO certification of financial statements, increasing corporate governance, transparency, and compliance costs."],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0295","t":"acct","l":"Advanced","s":90,"q":"What are the differences in impact on the financial statements when you compare the Write-Down of an Asset vs. the Write-Down of a Liability?","k":["An Asset Write-Down is recorded as a non-cash impairment charge on the Income Statement, which reduces net income. It is then added back to net income in the Cash Flow from Operations (CFO) section.","A Liability Write-Down (e.g., gain on debt extinguishment) is recorded as a non-cash gain on the Income Statement, which increases net income. This gain is then subtracted from net income in the CFO section."],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0296","t":"acct","l":"Advanced","s":90,"q":"Days Payable Outstanding goes from 30 days to 90 days. Is that a source or use of cash?","k":["It is a source of cash because you delay paying suppliers.","Explanation: By postponing payables, you keep the cash longer and can reinvest it until you must pay the bills."],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0297","t":"acct","l":"Advanced","s":90,"q":"You have Revenue of 100 with a 20% margin and a 50/50 split of variable and fixed costs. How does EBITDA change if volume increases 10%?","k":["EBITDA increases from 20 to 26.","Calculation:","Total Costs = Revenue (100) - EBITDA (20) = 80.","50/50 split: Fixed Costs = 40, Variable Costs = 40.","Volume increases 10%: Revenue = 110, Variable Costs = 44 (40 * 1.1).","Fixed Costs stay at 40.","New EBITDA = 110 - 44 - 40 = 26."],"collection":"practice","topic":"Accounting","tags":["Accounting","Advanced"]},{"id":"q-0298","t":"val","l":"Basic","s":90,"q":"Would you rather buy a company with a high or low P/E multiple?","k":["Typically, you'd prefer buying at a lower P/E for better value. But it’s relative to growth and risk; sometimes a high P/E might still be worthwhile if growth justifies it."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Basic"]},{"id":"q-0299","t":"val","l":"Advanced","s":90,"q":"A company has a stock price of $20 a share and a P/E of 20x (so EPS is 1). The company has 10M shares outstanding. How does a 2-for-1 stock split affect EV?","k":["Does not affect EV.","There are now 20m shares outstanding, and EPS is now 0.5, but EV stays unchanged."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0300","t":"val","l":"Advanced","s":90,"q":"How does the following affect Enterprise Value?\n\n\n\n\nRaise $200m in Debt, use cash to buy a new piece of equipment.","k":["EV up by 200.","EV = EqV + Debt - Cash etc.","+200 debt (from raise)","-200 cash (borrowing in form of debt)","+200 cash (equipment purchase is a decrease in cash, which gets subtracted from EV, thereby boosting it)"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0301","t":"val","l":"Advanced","s":90,"q":"How does the following affect Enterprise Value?\n\n\n\n\nIssue $200m in Equity for an IPO.","k":["EV stays unchanged.","Equity +200, Cash +200, net zero effect on EV formula."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0302","t":"val","l":"Advanced","s":90,"q":"Two companies are 100% comparable. Why might one trade at a premium (e.g. higher EV/EBITDA multiple)?","k":["Differences in margins, growth rates, investor sentiment, management strength, capex, capital structure, or working capital needs can all drive a higher multiple for one over the other."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0303","t":"val","l":"Advanced","s":90,"q":"What are some multiples you could use for a company with a negative Net Income?","k":["EV / Revenue","Industry-specific metrics, e.g. EV / Unique Visitors"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0304","t":"val","l":"Advanced","s":90,"q":"Company A and Company B have identical EV/EBITDA. Company A has a higher P/E multiple. Why might this be the case?","k":["The difference often lies in:","Capital structure (e.g. varying interest expense)","Tax rates","Different non-cash charges affecting net income but not EBITDA"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0305","t":"val","l":"Advanced","s":90,"q":"You have a company with an EV/Revenue of 2x and an EV/EBITDA of 10x. What is the EBITDA margin?","k":["20%","Because an EV/Revenue of 2x and EV/EBITDA of 10x implies EBITDA is 1/5th of revenue (i.e. 20% margin)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0306","t":"val","l":"Advanced","s":90,"q":"A company has 10,000 shares at $20 a share. There are 100 call options at an exercise price of $10, 50 restricted stock units (RSUs), and 100 convertible bonds at a price of $10 and par value of $100. What is the diluted equity value?","k":["Basic shares: 10,000 x $20 = $200,000 nominal market cap perspective.","Options: 100 options @ $10 = $1,000 in proceeds. At $20 share price, you buy back 50 shares, net 50 new shares.","RSUs add 50 shares, total +100 so far.","Convertibles: $100 par / $10 convert price = 10 shares per bond x 100 bonds = 1,000 shares.","Total new shares = 1,100, so diluted shares = 11,100.","11,100 x $20 = $222,000 diluted equity value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0307","t":"val","l":"Advanced","s":90,"q":"How does paying down $100M debt affect a company's enterprise value?","k":["Debt -100, Cash -100, net zero on the EV formula. EV remains unchanged."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0308","t":"val","l":"Advanced","s":90,"q":"If two companies have the same growth prospects, market capitalizations and industries, why might you value one using EV/Sales and the other using EV/EBITDA?","k":["Possibly one has negative or unreliable EBITDA, so EV/EBITDA isn’t meaningful. Or large non-cash/one-time items might distort EBITDA, pushing you toward a top-line multiple like EV/Sales."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0309","t":"val","l":"Advanced","s":90,"q":"What characteristics of a company would generate a higher valuation multiple?","k":["Common reasons include:","Higher revenue/EBITDA growth than peers","Market leadership or strong moat","Valuable patents/IP","Favorable geography/resources","Exceptional management team"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0310","t":"val","l":"Advanced","s":90,"q":"What are limitations of using the Exit Multiple Method when conducting valuation?","k":["It assumes you can sell the company at a chosen multiple in the future, which may be unpredictable (especially in cyclical industries).","Often you mitigate by providing a range of exit multiples and compare with a Gordon Growth approach for cross-checking."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0311","t":"val","l":"Advanced","s":90,"q":"You serve on a company's board and own a significant stake. The CEO claims the stock is up 20% this year. Does that mean it's performing well?","k":["You need context: if the market or sector is up 50%, then a 20% gain is an underperformance. It’s about relative returns, not just absolute percentage change."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0312","t":"val","l":"Advanced","s":90,"q":"What items are sometimes considered “debt-like” and added back when calculating enterprise value?","k":["Capital leases","Unfunded pension obligations","Legal or environmental liabilities","Some forms of preferred stock or near-debt instruments"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0313","t":"val","l":"Advanced","s":90,"q":"What items might be considered “cash-like” and therefore subtracted from enterprise value?","k":["Short-term investments or marketable securities","Excess cash beyond operating needs","Some equity investments or JV stakes, if easily liquidated","Potentially net operating loss carryforwards under certain assumptions"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Enterprise & Equity Value","Advanced"]},{"id":"q-0314","t":"val","l":"Basic","s":90,"q":"Why is EBITDA commonly used in finance?","k":["It approximates operating cash flow","Removes capital structure effects (interest, taxes)","It’s widely recognized for comparable valuations using EV/EBITDA","Strips out some non-cash or one-time items, although not a perfect measure"],"collection":"practice","topic":"Valuation","tags":["Valuation","Basic"]},{"id":"q-0315","t":"val","l":"Advanced","s":90,"q":"Is a company with a 50x P/E overvalued or undervalued? Why?","k":["You can't know from P/E alone. Must compare with industry, growth expectations, risk, etc. 50x might be too high if growth doesn’t warrant it, or fair if it’s a fast-growing firm."],"collection":"practice","topic":"Valuation","tags":["Valuation","Advanced"]},{"id":"q-0316","t":"val","l":"Advanced","s":90,"q":"What is the difference between intrinsic value and relative value?","k":["Intrinsic value uses company-specific cash flows/risk (DCF). Relative value compares multiples to similar companies or deals (Comps, Precedents)."],"collection":"practice","topic":"Valuation","tags":["Valuation","Advanced"]},{"id":"q-0317","t":"val","l":"Advanced","s":90,"q":"Is relying on an EBITDA multiple always the best approach to value a business? What about P/E?","k":["It depends on the company’s capital intensity, accounting peculiarities, and industry norms.","EBITDA excludes CapEx and changes in working capital, so it can gloss over cash needs.","P/E is also influenced by capital structure and tax strategies. The right multiple varies by situation."],"collection":"practice","topic":"Valuation","tags":["Valuation","Advanced"]},{"id":"q-0318","t":"val","l":"Advanced","s":90,"q":"If you were deciding on a new investment, what three financial figures would you look at first?","k":["Revenue history and forecast","EBITDA (or net income) trends","CapEx or overall FCF requirements","These help gauge size, profitability, and how much cash is needed to maintain or grow the business."],"collection":"practice","topic":"Valuation","tags":["Valuation","Advanced"]},{"id":"q-0319","t":"val","l":"Advanced","s":90,"q":"What are the differences between EBITDA and FCF?","k":["EBITDA excludes CapEx, interest, and changes in working capital, while FCF factors them in."],"collection":"practice","topic":"Valuation","tags":["Valuation","Advanced"]},{"id":"q-0320","t":"val","l":"Advanced","s":90,"q":"Why would you use EBITDA instead of FCF or EBIT?","k":["EBITDA normalizes for CapEx and D&A among similar companies, removing financing effects.","EBIT might be better for industries where D&A is material, and FCF includes differences in capital structure and CapEx that can muddy comparisons."],"collection":"practice","topic":"Valuation","tags":["Valuation","Advanced"]},{"id":"q-0321","t":"val","l":"Advanced","s":90,"q":"Would you pay more for a company with Operating Assets or Operating Leases, assuming the same Enterprise Value?","k":["You would pay more for the one with operating leases because those lease expenses lower EBITDA, inflating the multiple."],"collection":"practice","topic":"Valuation","tags":["Valuation","Advanced"]},{"id":"q-0322","t":"val","l":"Advanced","s":90,"q":"Would you pay a higher multiple for a business that owns its machines (depreciating them) or one that leases them?","k":["Technically, you would pay a higher multiple for the leasing business because lease payments get deducted from EBITDA, resulting in lower EBITDA and a higher multiple, assuming the same EV. In a business that owns its machines, the D&A costs are not included in EBITDA, so you would pay a lower multiple.","Simple Example:","Leased Business: $10M gross profit, $5m lease expense, $5m EBITDA","Owned Business: $10M gross profit, $5m D&A, $10m EBITDA","If you paid the same for both businesses (i.e. $50M), you're paying 10x for the \"lease\" business and 5x for the \"own\" business.","In the real world, analysts often use EBITDAR (which adds rent back) to neutralize capital-structure differences before comparing multiples. In the example above, by using EBITDAR, both companies would have a comparable profitability metric of $10M; thus, if they have the same Enterprise Value, their normalized multiples would be identical."],"collection":"practice","topic":"Valuation","tags":["Valuation","Advanced"]},{"id":"q-0323","t":"val","l":"Advanced","s":90,"q":"How can you decrease a company’s Equity Value?","k":["By distributing cash to shareholders through dividends, buying back shares, or increasing net debt. Large investments in cash can also reduce share price perception."],"collection":"practice","topic":"Valuation","tags":["Valuation","Advanced"]},{"id":"q-0324","t":"val","l":"Advanced","s":90,"q":"Can Equity Value ever be negative?","k":["Market Cap (current Equity Value) cannot be negative.","However, Shareholders’ Equity on the balance sheet can be negative."],"collection":"practice","topic":"Valuation","tags":["Valuation","Advanced"]},{"id":"q-0325","t":"val","l":"Advanced","s":90,"q":"Company A has $30M in EBITDA with a multiple of 10x. It has $250M in senior debt and $100M in subordinated debt. What are these trading at in dollar terms?","k":["EV = 300M. Senior is fully covered at par (250M). Only 50M remains for the subordinated piece, so it's at 50% of par (50M)."],"collection":"practice","topic":"Valuation","tags":["Valuation","Advanced"]},{"id":"q-0326","t":"val","l":"Basic","s":90,"q":"What is a DCF/can you walk me through a DCF in under 60 seconds?","k":["You project and discount a company’s FCF plus its terminal value:","Forecast free cash flow 5-10 years","Discount at WACC","Find terminal value (exit multiple or perpetuity growth)","Discount terminal value back and sum for enterprise value"],"collection":"practice","topic":"DCF","tags":["DCF","Basic"]},{"id":"q-0327","t":"val","l":"Basic","s":90,"q":"What is WACC, conceptually? How do you calculate it?","k":["WACC is the required return on the company’s capital structure, weighted by each capital slice’s proportion.","WACC = Cost of Equity x % Equity + Cost of Debt x % Debt x (1 - Tax Rate) + Cost of Preferred x % Preferred."],"collection":"practice","topic":"DCF","tags":["DCF","Basic"]},{"id":"q-0328","t":"val","l":"Advanced","s":90,"q":"Tell me 3 places where taxes affect a DCF.","k":["Calculating Beta (conversion from unlevered to levered)","Calculating FCF (NOPAT)","Calculating Cost of Debt (interest is tax deductible)"],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0329","t":"val","l":"Advanced","s":90,"q":"If you are valuing a coal mine company, would you use the Gordon Growth Method or the Multiples Method to calculate the TV? Explain.","k":["Would use the multiples method, since Gordon Growth assumes cash flows exist into perpetuity and coal is a depleting resource."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0330","t":"val","l":"Advanced","s":90,"q":"How would you change a DCF to value a highly speculative technology company?","k":["Longer projection horizon, as it may take longer to stabilize","Higher discount rate to reflect higher risk","Adjust growth/margin assumptions for uncertainty"],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0331","t":"val","l":"Advanced","s":90,"q":"A company buys a factory for $100 in its 4th year. How would the DCF/Enterprise Value change for the company?","k":["Add $100 of CapEx in Year 4, reducing that year’s FCF by $100 and lowering EV by its PV: 100 / (1 + r)^4."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0332","t":"val","l":"Advanced","s":90,"q":"How would you calculate the long-term growth rate for the GGM?","k":["Typically choose a conservative rate (e.g. inflation or GDP ~ 2-3%). Anything above 5% is aggressive for most developed markets."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0333","t":"val","l":"Advanced","s":90,"q":"What are the three ways that lowering tax can affect a DCF valuation?","k":["Boosts net income → higher FCF","Raises cost of debt (less tax shield) → WACC up","Lowers tax shield in levered beta → cost of equity up","Net effect depends on which is stronger: FCF increase or WACC increase."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0334","t":"val","l":"Advanced","s":90,"q":"What are common alterations that one can make to the basic WACC formula to make it more company-specific?","k":["Add a size premium or liquidity discount for smaller/private entities","Include preferred stock if part of the capital structure","Use alternative cost of equity formulas if Beta is unusable"],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0335","t":"val","l":"Advanced","s":90,"q":"Ignoring the effect of taxes, how would changing from LIFO to FIFO affect FCF during a period of rising costs?","k":["Lower COGS via FIFO increases net income, but also increases inventory, which is a use of cash. The two effects offset, so FCF is neutral (in a simplified scenario)."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0336","t":"val","l":"Advanced","s":90,"q":"In a DCF valuation, which of the following actions increases the valuation the most:\n\n$10 decrease in capital expenditures\n$10 decrease in expenses\n$10 increase in revenues","k":["The $10 decrease in CapEx has the most significant impact on valuation.","Decreasing CapEx by $10 directly increases FCF by $10 with no tax effect.","Reducing expenses by $10 increases FCF by $10 x (1 - tax rate), which is less than $10.","Increasing revenues by $10 also increases FCF by $10 x (1 - tax rate), which is less than $10."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0337","t":"val","l":"Advanced","s":90,"q":"What is the difference between asset beta and equity beta?","k":["Asset beta (unlevered) measures business risk excluding debt. Equity beta (levered) includes debt risk, making it higher if leverage exists."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0338","t":"val","l":"Advanced","s":90,"q":"How would raising $100M debt in Year 3 affect the DCF valuation of a company?","k":["Unlevered FCF is unaffected by new interest costs, but the capital structure changes after Year 3 could alter WACC. You might recalc WACC post-Year 3, discounting from that point onward."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0339","t":"val","l":"Advanced","s":90,"q":"How do you categorize maintenance, growth, and acquisition CapEx when analyzing a company's spending?","k":["Maintenance CapEx is the baseline amount needed to sustain operations.","Growth CapEx supports expansion into new products or markets and can often be deferred if necessary.","Acquisition CapEx is funding used for M&A activity. In valuation, mandatory maintenance spending is more critical to subtract from operating cash flow, while other categories can be more discretionary."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0340","t":"val","l":"Advanced","s":90,"q":"What is cheaper – debt or equity?","k":["Debt is cheaper because interest is tax-deductible, and debt sits above equity in a firm’s capital structure."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0341","t":"val","l":"Advanced","s":90,"q":"Within WACC, can the cost of debt ever be higher than the cost of equity?","k":["Typically, no. Debt ranks above equity in the capital structure, so it carries a lower required return. However, in extreme distress, yields on debt can spike, but rational equity investors would still demand a higher return than debt holders."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0342","t":"val","l":"Advanced","s":90,"q":"How does changing an asset affect the DCF?","k":["If an asset decreases, the change in NWC is lower, so FCF is higher.","If an asset increases, the change in NWC is higher, so FCF is lower."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0343","t":"val","l":"Advanced","s":90,"q":"Calculate stub-year discount factors with mid-year convention for the end of Q1, Q2, Q3, and Q4.","k":["Answer:","Q1: First = 0.375, Second = 1.25","Q2: First = 0.25, Second = 1","Q3: First = 0.125, Second = 0.75","Q4: First = 0.5, Second = 1.5","Explanation:","Stub period = months to 12/31 ÷ 12 (Q1 0.75 yr, Q2 0.5 yr, Q3 0.25 yr, Q4 0 yr).","Mid-year convention discounts the stub cash flow at half the stub length (s / 2).","First full-year cash flow arrives six months into the next year → exponent = s + 0.5.","Each subsequent year’s midpoint is one year later (add 1.0 to the exponent)."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0344","t":"val","l":"Advanced","s":90,"q":"If a company has 11% NWC/Sales and another has 12% NWC/Sales, which is valued higher if sales are increasing?","k":["The company with the lower NWC ratio (11%) is generally valued higher because it ties up less cash in working capital as sales grow."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0345","t":"val","l":"Advanced","s":90,"q":"Can you describe a company with a beta close to zero?","k":["A government utilities company (or extremely non-cyclical, regulated entity) typically has a near-zero market beta."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0346","t":"val","l":"Advanced","s":90,"q":"How do you get from Unlevered FCF to Levered FCF?","k":["Subtract interest expense (net of tax) and mandatory debt repayments from Unlevered FCF."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0347","t":"val","l":"Advanced","s":90,"q":"If debt of a company is going down, how does that affect the cost of equity and the cost of capital?","k":["Less debt lowers beta, theoretically reducing cost of equity. Overall WACC could move either way, but typically, if you reduce cheaper debt, cost of capital may rise slightly."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0348","t":"val","l":"Advanced","s":90,"q":"Rank these three changes from biggest to smallest impact on FCF: 10% increase in Revenue, 10% decrease in COGS, 10% decrease in Working Capital.","k":["Biggest: 10% decrease in Working Capital (no tax effect).","Next: 10% decrease in COGS.","Least: 10% increase in Revenue."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0349","t":"val","l":"Advanced","s":90,"q":"What are three questions you would ask the CEO of a company to do a DCF?","k":["Ask about business outlook, model assumptions, and competitive landscape."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0350","t":"val","l":"Advanced","s":90,"q":"What are ways you could have negative free cash flow in a DCF?","k":["High capex, large changes in net working capital, or low/zero sales can push FCF negative."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0351","t":"val","l":"Advanced","s":90,"q":"How can you calculate the Equity Value of a company using a DCF?","k":["Either use a Levered DCF directly to calculate Equity Value, or find Implied Enterprise Value from an Unlevered DCF and then subtract net debt (subtract debt, add cash)."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0352","t":"val","l":"Advanced","s":90,"q":"Let's say you have WACC on the y-axis and the debt/equity ratio on the x-axis. What does the graph look like?","k":["It is a U-shaped parabola, where moderate leverage can minimize WACC, but too much or too little raises it."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0353","t":"val","l":"Advanced","s":90,"q":"You are valuing a company. How do you increase the valuation only using NWC?","k":["Increase current liabilities (or reduce current assets) so that the changes in NWC are smaller and FCF is higher, boosting valuation."],"collection":"practice","topic":"DCF","tags":["DCF","Advanced"]},{"id":"q-0354","t":"deal","l":"Advanced","s":90,"q":"Company E has an EBITDA of $200M and Company F has an EBITDA of $100M. Let's say that Company E acquires Company F and realizes $100M in revenue synergies from additional unit sales and $100M from cost synergies. What is the pro forma EBITDA? Assume that the pro forma company has a gross margin of 70%.","k":["To determine the pro forma EBITDA:","Combine Company E’s $200M and Company F’s $100M of EBITDA = $300M.","Add $100M of cost synergies directly to EBITDA, resulting in $400M.","Add revenue synergies of $100M multiplied by a 70% margin = $70M. So total is $470M.","Thus, the pro forma EBITDA is $470M."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0355","t":"deal","l":"Advanced","s":90,"q":"Company A has a P/E of 5x and Company B has a P/E of 8x. If Company A purchases Company B in an all-stock deal, is the deal accretive or dilutive?","k":["Company A’s cost of equity is 1/5 = 20%, while B’s earnings yield is 1/8 = 12.5%.","Since cost > yield, the deal is dilutive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0356","t":"deal","l":"Advanced","s":90,"q":"Company A has a P/E of 5x and Company B has a P/E of 8x. Company A's cost of debt is 5%, cost of cash interest is 2%, and tax rate is 50%.\n\n\n\n\nIf Company A purchases Company B using:\n\n50% stock\n25% debt\n25% cash\n\n\n\nIs the deal accretive or dilutive?","k":["Since the weighted cost of acquisition (10.875%) is less than Company B’s yield (12.5%), the deal is accretive.","Cost of equity = 20% (1 ÷ P/E of 5x).","After-tax cost of debt = 2.5% (5% x (1 - 50% tax rate)).","After-tax cost of cash = 1% (2% x (1 - 50% tax rate)).","Weighted cost of acquisition =","(0.5 x 20%) + (0.25 x 2.5%) + (0.25 x 1%) = 10% + 0.625% + 0.25% = 10.875%.","Yield of Company B = 12.5% (1 ÷ P/E of 8x)."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0357","t":"deal","l":"Advanced","s":90,"q":"Company C has the following financials:\n\nNet Income: $200\nShare Price: $6\nShares Outstanding: 10\n\n\n\nCompany D has the following financials:\n\nNet Income: $200\nShare Price: $5\nShares Outstanding: 6\n\n\n\nIf Company C purchases Company D in an all-stock deal at a 20% premium, what is the percentage change in accretion or dilution?","k":["The deal results in +25% accretion.","Company D’s market cap = $5 x 6 = $30. With a 20% premium, the purchase price = $36.","Company C’s share price = $6. To pay $36, it must issue $36 ÷ $6 = 6 new shares.","Pro forma shares outstanding = Company C’s 10 shares + 6 new shares = 16 shares.","Combined Net Income = $200 (Company C) + $200 (Company D) = $400.","Pro forma EPS = $400 ÷ 16 shares = $25 per share.","Original EPS = $200 ÷ 10 shares = $20 per share.","Percentage change in EPS = (($25 - $20) ÷ $20) x 100 = +25%."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0358","t":"deal","l":"Advanced","s":90,"q":"Under what circumstances would $100M in revenue synergies be a straight addition to the pro forma company's EBITDA?","k":["Only if there’s no incremental cost (e.g., pure price lift). Typically, there’s some cost, so rarely 100% flows to EBITDA in real scenarios."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0359","t":"deal","l":"Advanced","s":90,"q":"How can you calculate break-even synergies in an M&A deal?","k":["You’d set the combined EPS to equal the buyer’s standalone EPS, then solve for how much synergy is needed to offset any dilution from the deal."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0360","t":"deal","l":"Advanced","s":90,"q":"How much debt could a company raise for a merger or acquisition?","k":["Typically based on leverage ratios (Debt/EBITDA) and coverage ratios (EBITDA/Interest).","You check comps, market conditions, synergy-based EBITDA.","Lenders rarely exceed ~5-6x in many markets."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0361","t":"deal","l":"Advanced","s":90,"q":"What is contribution analysis?","k":["It’s a quick check of how much each party “contributes” to the combined entity’s revenue, EBITDA, etc. Often used in MOE deals to determine relative ownership."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0362","t":"deal","l":"Advanced","s":90,"q":"Company A has an Equity Value of $1000 and Net Income of $100. Company B has an Equity Value of $2000 and Net Income of $50. How would this all-stock deal be accretive?","k":["Company A’s P/E is 10x, Company B’s is 40x. To be accretive, the effective seller’s yield must exceed 10%. You’d need sufficient after-tax synergies (e.g., $150) to bring the seller’s yield above 10% of the purchase price."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0363","t":"deal","l":"Advanced","s":90,"q":"What factors can lead to dilution of EPS in an acquisition?","k":["Negative net income at target, higher P/E target than acquirer, intangible amortization, higher interest expense, lower interest income, and weak or unrealized synergies."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0364","t":"deal","l":"Advanced","s":90,"q":"How can a merger be accretive on paper, but value destructive?","k":["Cash deals often appear accretive, but you can overpay. If synergies never materialize, real value is destroyed despite EPS accretion."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0365","t":"deal","l":"Advanced","s":90,"q":"Company A has a P/E of 30x, Company B has a P/E of 25x. Will an all-stock deal be accretive or dilutive?","k":["It will be accretive since the seller’s yield (1/25 = 4%) is higher than the buyer’s cost of equity implied by 1/30 ~ 3.3%."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0366","t":"deal","l":"Advanced","s":90,"q":"Company A (P/E 30x) acquires Company B (P/E 25x) with 100% debt at a tax rate of 20% and cost of debt of 5%.\n\n\n\n\nWill it be accretive or dilutive?","k":["Seller’s yield is 4%. After tax, cost of debt is 4%. The deal is roughly neutral."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0367","t":"deal","l":"Advanced","s":90,"q":"Company A is $20/share with $100 NI, 100 shares outstanding. Company B is $5/share with $50 NI, 100 shares outstanding.\n\n\n\n\nA buys B with 60% stock and 40% cash.\n\n\n\n\nAssume the 40% cash portion is funded with new debt at 10% pre-tax interest, a 20% corporate tax rate, and no synergies.\n\n\n\n\nWhat is the pro-forma ownership, and is the deal accretive? By how much?","k":["Pro-forma ownership:","Purchase price (no premium) = $5×100 = $500.","60% stock = $300 → new A shares = $300 / $20 = 15.","40% cash = $200 (funded by raising new debt) @ 10% pre-tax; 20% tax ⇒ after-tax interest = $16.","Pro-forma shares = 100 + 15 = 115 → B holders own 15 / 115 ≈ 13%.","Accretion calculation:","Pro-forma NI = 100 + 50 − 16 = 134.","Pre-deal EPS = 100 / 100 = $1.00.","Pro-forma EPS = 134 / 115 ≈ $1.17.","Accretion = (1.17 / 1.00 − 1) ≈ +17%.","Why accretive: A trades at 20× P/E (5% earnings yield); you’re buying B at 10× and funding 40% with ~8% after-tax debt, so the blended yield > 5%."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0368","t":"deal","l":"Advanced","s":90,"q":"Part I: Company A has a P/E of 10x and buys Company B, which has a P/E of 5x, in an all-stock deal. Will this deal be accretive?\n\n\n\n\nPart II: Company A has a market cap of $100 million (10 million shares at $10/share) and $10 million in NI. Company B has a market cap of $50 million and $10 million in NI. There are $10 million in cost synergies. How accretive is the deal?","k":["Part I:","Yes, if the acquiring company has a higher P/E ratio than the target company in an all-stock transaction, the acquisition is accretive.","You're effectively purchasing the target with shares valued at a premium compared to the target's earnings yield.","Part II:","Clarifying question: ask if $10M in cost synergies are pre-tax or post-tax. The below answer will assume that they are post-tax. If the $10M of synergies are stated pre-tax, you’d need to multiply by (1 – tax rate) before adding to net income","Purchase price / new shares issued: Pay $50M for B using A stock at $10/share = 5M new shares.","Total shares post-merger: 10M (A) + 5M (new) = 15M.","Combined net income: 10M (A) + 10M (B) + 10M (synergies) = $30M.","Pro-forma EPS: $30M / 15M ≈ $2.00.","Accretion: Old EPS = $10M / 10M = $1.00 → ($2.00 PF EPS / $1.00 Old EPS) – 1 = 100% accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Merger Model (M&A)","Advanced"]},{"id":"q-0369","t":"deal","l":"Advanced","s":90,"q":"Why would a revolver have the lowest interest rate?","k":["A revolver is the cheapest form of debt in an LBO. It acts similarly to a credit card, drawn upon only if the company has cash shortfalls and is also the first thing paid down.","Revolvers typically carry the lowest interest rate because they are backed by collateral and are often arranged by banks competing to offer attractive terms."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0370","t":"deal","l":"Advanced","s":90,"q":"Why would an LBO not be relevant for the metals and mining industry?","k":["An ideal LBO candidate has dependable cash flows, low capital expenditures, and limited commodity risk.","The metals and mining industry often has large initial investments, frequent CapEx, and exposure to unpredictable commodity price fluctuations.","During downturns, high-cost mines may be forced to sell assets, and juniors may lack capital to expand, so mergers are more common than classic LBOs."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0371","t":"deal","l":"Advanced","s":90,"q":"What is the interest tax shield?","k":["Interest expense is tax-deductible, effectively lowering the cost of debt. In an LBO, that can boost returns by reducing taxes.","Often approximated as Debt x Tax Rate in PV terms."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0372","t":"deal","l":"Advanced","s":90,"q":"What is leverage and how do its mechanics amplify returns in an LBO?","k":["Less equity up front means higher potential ROI","Debt is paid with the company’s cash flow","Upon exit, a small equity slice might see big gains if the business has grown"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0373","t":"deal","l":"Advanced","s":90,"q":"What are the three ways investors can retrieve funds or capital in an LBO?","k":["Exit the investment by selling the company","Dividend recap (raise debt to pay a dividend)","Ongoing dividends (less common in PE deals)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0374","t":"deal","l":"Advanced","s":90,"q":"What is the internal rate of return (IRR)?","k":["It’s the discount rate that makes an investment’s NPV = 0, effectively the annualized return on the PE firm’s equity over the holding period."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0375","t":"deal","l":"Advanced","s":90,"q":"What actions or strategies can you take to improve the IRR in an LBO?","k":["Lower purchase price","Use more debt (less equity)","Grow EBITDA / margins faster","Pay down debt quickly","Sell at a higher multiple","Exit sooner (improve annualized returns)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0376","t":"deal","l":"Advanced","s":90,"q":"What are factors that would make an LBO more difficult to perform on a private company?","k":["Lack of audited financials or transparency","No public float (must negotiate with owners)","Potentially smaller scale / unknown creditworthiness"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0377","t":"deal","l":"Advanced","s":90,"q":"What is the rule of 72? What is the rule of 114?","k":["The rule of 72 estimates years to double = 72 ÷ interest rate. The rule of 114 estimates years to triple = 114 ÷ interest rate."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0378","t":"deal","l":"Advanced","s":90,"q":"If you purchased a company for $100M and sold it for $200M after 5 years, what was your IRR?","k":["Approximately 15% IRR (technically around 14.87%). Doubling in 5 years ~15%."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0379","t":"deal","l":"Advanced","s":90,"q":"If a company could service debt up to 7X EBITDA, why would it only take debt up to 5X EBITDA?","k":["More debt increases default risk, costs, and covenants. Even if 7x is possible, 5x might be safer or more flexible from a risk/reward standpoint."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0380","t":"deal","l":"Advanced","s":90,"q":"You have the option of either receiving $200M now or $40M each year for 5 years. What IRR would you need to make the value of these two options equal?","k":["If you sum $40M x 5 = $200M, only at 0% discount rate would that be equal to $200M upfront. Any positive IRR would favor the upfront sum."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0381","t":"deal","l":"Advanced","s":90,"q":"There are two companies with identical growth prospects, margins, business models, etc. The only difference is that one company has 50% debt-to-total capitalization, while the other has 0%.\n\n\n\n\nIf you were a PE firm and were going to acquire them and bring the company's debt-to-total capitalization to 70% in both cases, which investment would yield a higher IRR (assuming that the equity purchase price is the same)?","k":["The Unlevered company (0% debt) yields the higher IRR.","Since the equity purchase price is the same, the unlevered company has a significantly lower Enterprise Value (Entry Price) than the levered company (where EV = Equity + Debt). Acquiring the same cash flows (EBITDA) for a lower total entry price results in a higher return."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0382","t":"deal","l":"Advanced","s":90,"q":"Company XYZ has $50M EBITDA, a 6X EBITDA multiple, $200M in bank debt, and $200M in high yield debt. What is the value of the debt? What dollar value is the debt trading at?","k":["EV = 6 x 50M = 300M total enterprise value.","400M total debt. Underwater by 100M.","Bank debt is senior, so 200M is fully covered. 100M remains for the 200M high yield, so that’s 50 cents on the dollar."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0383","t":"deal","l":"Advanced","s":90,"q":"Two companies have the same EBITDA and IRR. Which one is the better investment, and what qualitative factors do you consider?","k":["Even if EBITDA and IRR look identical on paper, you would examine qualitative and risk-related factors.","CapEx needs and free cash flow conversion","Reliability of projections and downside risk","Industry stability and competitive environment","Customer or commodity concentration","Management team capabilities"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0384","t":"deal","l":"Advanced","s":90,"q":"How do the following affect IRR?\n\n\n\nLarger asset write-up\nUsing less excess cash\nTax shield","k":["Larger asset write-up: In a standard stock purchase, this creates a Deferred Tax Liability (DTL) because the higher depreciation isn't tax-deductible for cash purposes, meaning it has no effect on IRR. However, in an asset purchase (or 338(h)(10)), the step-up is tax-deductible, creating a cash tax shield that improves IRR.","Using less excess cash: Using less of the target's cash to fund the deal creates a funding shortfall. If the sponsor plugs this gap with more equity, IRR decreases. If they plug it with more debt, IRR could increase due to higher leverage, but the risk profile rises.","Tax shield: A larger tax shield, whether from higher depreciation (in an asset purchase) or greater interest expense, reduces cash taxes and increases free cash flow, thus improving IRR."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0385","t":"deal","l":"Advanced","s":90,"q":"Can you outline the typical layers of a company's capital structure?","k":["Revolver (secured, floating-rate, short-term)","Term Loans (secured debt, e.g., TLA/TLB)","Mezzanine or subordinated debt","High-yield bonds (often unsecured)","Preferred equity","Common equity (which may include options/warrants)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0386","t":"deal","l":"Advanced","s":90,"q":"Explain the concept of \"Sources and Uses\" in a transaction.\n\n\n\n\nProvide four main items for each.","k":["Sources: These indicate where the financing or capital is coming from in the transaction.","New debt issuance","Sponsor equity","Rollover equity from management","Seller notes","Uses: These detail how the capital is deployed in the transaction.","Buying out existing equity","Refinancing old debt","Paying transaction fees","Funding cash on the balance sheet"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0387","t":"deal","l":"Advanced","s":90,"q":"How does taking on leverage benefit equity holders in an LBO?","k":["They invest less equity capital upfront.","If the company grows and repays debt, the equity slice can realize outsized returns.","Interest is tax-deductible, boosting after-tax cash flow."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0388","t":"deal","l":"Advanced","s":90,"q":"Why might a manufacturing company be able to tolerate higher leverage?","k":["Because manufacturing often has more stable demand (depending on the niche) and tangible assets (plants, equipment) for collateral. Lenders view these factors as reducing risk, thus allowing for higher debt levels."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0389","t":"deal","l":"Advanced","s":90,"q":"When should a company lean toward issuing debt instead of equity for financing?","k":["When its cash flows can comfortably cover interest payments, and the after-tax cost of debt is lower than the cost of equity.","Debt issuance is also preferred if management wants to avoid diluting ownership, though it raises default risk."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0390","t":"deal","l":"Advanced","s":90,"q":"What EBITDA and gross margin levels do sponsors often seek in an LBO target?","k":["It varies by industry, but many PE firms prefer at least ~20% EBITDA margins and 50%+ gross margin for a safety cushion. The actual metrics depend heavily on the sector and business model."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0391","t":"deal","l":"Advanced","s":90,"q":"How is an LBO model different from a standard DCF?","k":["A DCF values the business as a going concern, discounting unlevered FCF, whereas an LBO focuses on a sponsor's IRR, factoring in leverage, debt repayment, and an eventual exit. The LBO sets a “floor” on value because of the required equity return."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0392","t":"deal","l":"Advanced","s":90,"q":"What factors typically drive a company's debt capacity?","k":["Predictability and stability of cash flow","Industry cyclicality or resilience","Value and liquidity of collateral","Leverage/coverage thresholds in the credit market","Interest rate environment"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0393","t":"deal","l":"Advanced","s":90,"q":"What are the pros and cons of an M&A exit for a PE sponsor?","k":["Pros: Possibly faster sale, strategic buyer might pay a premium for synergies.","Cons: Need a willing buyer, might not fetch the highest multiple if sector sentiment is down."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0394","t":"deal","l":"Advanced","s":90,"q":"What are the pros and cons of exiting via an IPO?","k":["Pros: Potentially higher valuation in bullish markets, broad investor base, brand enhancement.","Cons: Costly and lengthy process, lock-up periods, more volatility and disclosure requirements."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0395","t":"deal","l":"Advanced","s":90,"q":"Which financing multiples matter most? What multiples are you seeing in the market lately?","k":["Key metrics often include:","Total Debt / EBITDA (often 4–6x range)","EBITDA / Interest Coverage (2–3x+)","FCF / Debt for more detailed analysis","Actual multiples vary by industry and economic conditions. In tighter markets, lenders often demand lower leverage ratios."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0396","t":"deal","l":"Advanced","s":90,"q":"How do private equity firms generate revenue?","k":["Management fees (usually ~1–2% of committed or invested capital per year)","Carried interest (around 20% of profits after hitting an IRR hurdle)","GP co-investment returns (if they invest alongside the LPs)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0397","t":"deal","l":"Advanced","s":90,"q":"Why might an investor choose to put money into private equity?","k":["PE historically can yield higher returns than public markets if in the top quartile funds.","It also provides portfolio diversification and access to private deals that aren’t available via public equities."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0398","t":"deal","l":"Advanced","s":90,"q":"Of four common debt covenants (minimum EBITDA, max CapEx, minimum interest coverage, max leverage), which is most critical and why?","k":["Often the minimum EBITDA covenant is key, because it directly measures operating performance. If EBITDA dips below a threshold, it can violate the covenant even if other metrics are on track."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0399","t":"deal","l":"Advanced","s":90,"q":"If there is no multiple expansion and EBITDA stays flat, how can you still earn returns in an LBO?","k":["Paying down principal over time","Leveraging the tax shield from debt","Improving working capital or CapEx efficiency","Dividend recaps (less common for pure growth, but possible)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0400","t":"deal","l":"Advanced","s":90,"q":"Would you rather have one extra dollar of debt repayment or $1 of EBITDA?","k":["Generally, $1 of EBITDA is more valuable because it can be multiplied by the exit multiple. A $1 of debt paydown adds exactly $1 to equity, while $1 of EBITDA might add $1 x (exit multiple) to equity value."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0401","t":"deal","l":"Advanced","s":90,"q":"If the cost of debt is 10% and the tax rate is 30%, what is the minimum equity return you'd need just to break even in an LBO?","k":["After-tax cost of debt is 10% x (1 - 30%) = 7%. Your equity returns should at least surpass 7% or you might as well not use debt."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0402","t":"deal","l":"Advanced","s":90,"q":"A company has $30M in EBITDA, the purchase multiple is 10x, and you use $100M of debt. FCF is $30M/year. After 2 years, what is the breakeven Exit EBITDA multiple if EBITDA stays constant?","k":["Purchase Price = $300M, with $100M debt, $200M equity. After 2 years, $60M of FCF pays down debt to $40M. To break even on the $200M equity, EV must be $240M. $240M / $30M = 8x."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0403","t":"deal","l":"Advanced","s":90,"q":"What variable impacts an LBO model the most?","k":["Purchase and exit multiples tend to drive returns the most, followed by leverage and operating assumptions."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0404","t":"deal","l":"Advanced","s":90,"q":"How could a PE firm boost its returns in an LBO?","k":["Use more leverage, lower purchase multiple, increase exit multiple, improve margins, pay down debt, shorten holding period, dividend recap, and find synergies."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0405","t":"deal","l":"Advanced","s":90,"q":"How would you determine how much debt can be raised in an LBO and how many tranches there would be?","k":["Look at comparable LBO transactions (debt comps), typical Debt/EBITDA levels, and market appetite for different debt tranches."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0406","t":"deal","l":"Advanced","s":90,"q":"What is a cash flow sweep?","k":["It's using excess cash (beyond mandatory payments) to pay down outstanding debt instead of distributing it to equity holders."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0407","t":"deal","l":"Advanced","s":90,"q":"What is the difference between PIK, a bond, and a loan?","k":["PIK accrues interest to principal. A bond is publicly traded, can be bullet or amortizing. A loan is typically from banks, not publicly traded, and usually amortized."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0408","t":"deal","l":"Advanced","s":90,"q":"What is the circularity in an LBO model?","k":["Interest expense depends on debt outstanding, but debt paydown depends on cash flow and thus net income, which again is affected by interest expense. This creates a circular reference."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0409","t":"deal","l":"Advanced","s":90,"q":"How much equity contribution do you usually see in LBOs?","k":["Often 35–40% of the purchase price, though it varies with market conditions and deal specifics."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0410","t":"deal","l":"Advanced","s":90,"q":"What is the difference between a Levered DCF and an LBO?","k":["A Levered DCF discounts free cash flow to equity at the cost of equity, asking “What is the intrinsic value?”","An LBO sets a target IRR, backing into a purchase price based on leverage and exit assumptions."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0411","t":"deal","l":"Advanced","s":90,"q":"Why is IRR greater than the cost of equity (besides the fact that PE investors expect a higher return)?","k":["Private companies are less liquid, so investors demand a higher return premium for that liquidity risk."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0412","t":"deal","l":"Advanced","s":90,"q":"You are performing an LBO on two companies with the same entry and exit prices, same EBITDA. Why might one have a higher IRR?","k":["Differences in CapEx, NWC, taxes, debt terms, or holding period can affect how quickly debt is repaid and thus boost IRR."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0413","t":"deal","l":"Advanced","s":90,"q":"Give me 8 ways to increase IRR in an LBO.","k":["Lower purchase multiple","Raise exit multiple","Boost margins","Use more leverage","Pay down debt faster","Dividend recap","Shorten holding period","Recognize synergies"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0414","t":"deal","l":"Advanced","s":90,"q":"Part I: You purchase a company at Year 0 with $100M EBITDA at a 10x multiple, using 4x leverage. You sell at 11x and EBITDA grows to $200M. You also have $200M in net cash at exit. Calculate MoM and approximate IRR over 5 years.\n\n\n\n\nPart II: Rank the impact of operating improvements, multiple expansion, and debt paydown.","k":["Part I:","Purchase = $1B ($100M x 10). Debt = $400M, equity = $600M.","Exit Enterprise Value = 11 x $200M = $2.2B.","Exit Equity Value = EV - Net Debt. Since Net Cash is $200M, Net Debt is -$200M.","Exit Equity = $2.2B - (-$200M) = $2.4B.","MoM = $2.4B / $600M = 4.0x.","Roughly 33% IRR over 5 years.","Part II: Greatest impact usually comes from EBITDA growth, then multiple expansion, then debt paydown. However, in this specific case, the massive deleveraging (generating $600M in value) outweighs the 1-turn multiple expansion ($200M in value)."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0415","t":"deal","l":"Advanced","s":90,"q":"Part I: Company A has $200M revenue, 50% EBITDA margin, constant $40M FCF/year, bought at 5x with 3x leverage, held for 5 years and sold at 5x. Assume a 100% FCF cash sweep to debt. What are MOIC and IRR?\n\n\n\n\nPart II: Is this a good investment?","k":["Part I","Purchase EV = 5 × $100 M EBITDA = $500 M.","Capitalised with $300 M debt (3x) and $200 M equity.","Five years of $40 M FCF (= $200 M) pay down debt to $100 M.","Exit EV = 5x $100 M = $500 M; less $100 M debt ⇒ equity proceeds = $400 M.","MOIC = $400 M / $200 M = 2.0x.","IRR ≈ (2.0)^(1/5) – 1 ≈ 15 %.","Part II","A 2.0x MOIC and a 15% IRR are generally considered mediocre for a traditional private equity LBO, which often targets returns of 2.5x-3.0x and 20-25% IRR.","Acceptable for a lower-risk deal but far from a home-run; whether it’s “good” depends on the fund’s targets and risk appetite."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-0416","t":"mkt","l":"Basic","s":90,"q":"Explain the concept of duration for a bond.","k":["Duration measures the sensitivity of a bond’s price to interest rate changes.","For example, a duration of 5 implies that if rates rise by 1%, the bond’s price drops ~5%."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Finance Brain Teasers","Basic"]},{"id":"q-0417","t":"mkt","l":"Advanced","s":90,"q":"Company A has a market capitalization of $6B and purchases Company B at a market capitalization of $3B.\n\n\n\n\nIf Company A owns 75% of the pro forma company, how much cash did it use in the transaction?","k":["Company A used $1B in cash for the transaction.","Explanation:","If the transaction were purely stock-based, the total pro forma company value would be $9B (Company A’s $6B market cap + Company B’s $3B market cap).","However, Company A owning 75% of the pro forma company implies that the total value must be $6B / 0.75 = $8B.","The difference between the $9B (pure stock transaction) and $8B (actual pro forma value) is $1B. This $1B must have been paid in cash."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Finance Brain Teasers","Advanced"]},{"id":"q-0418","t":"mkt","l":"Advanced","s":90,"q":"Would you rather receive $1,000 today or $100 every year into perpetuity?","k":["It depends on the discount rate (r). If r < 10%, the perpetuity is worth more than $1,000. If r > 10%, $1,000 today is better.","Explanation:","The present value (PV) of a perpetuity is calculated as: PV = Cash Flow / Discount Rate = $100 / r.","If the discount rate is less than 10%, the PV of the perpetuity exceeds $1,000. For example, at r = 5%, PV = $100 / 0.05 = $2,000.","If the discount rate is greater than 10%, the PV of the perpetuity is less than $1,000. For example, at r = 15%, PV = $100 / 0.15 = $667.","Therefore, the choice depends on your required rate of return or discount rate."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Finance Brain Teasers","Advanced"]},{"id":"q-0419","t":"mkt","l":"Advanced","s":90,"q":"What is the Beta of a gambling ring?","k":["0. No correlation with public markets."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Finance Brain Teasers","Advanced"]},{"id":"q-0420","t":"mkt","l":"Advanced","s":90,"q":"What are the 2 ways to return capital to shareholders, and what are some considerations for each?","k":["Dividends – Dividends are taxed twice, and shareholders have to pay taxes immediately","Share buybacks - Buybacks are typically seen as a signal to shareholders that the company thinks it is undervalued, and shareholders don't need to pay taxes right away (capital gains)"],"collection":"practice","topic":"Finance Brain Teasers","tags":["Finance Brain Teasers","Advanced"]},{"id":"q-0421","t":"mkt","l":"Advanced","s":90,"q":"What is the P/E of cash?","k":["Cash yield might be 1-3%. Its P/E is roughly 1 / 0.01 to 1 / 0.03, or 33-100x."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Finance Brain Teasers","Advanced"]},{"id":"q-0422","t":"mkt","l":"Advanced","s":90,"q":"What are 5 things a company can do with cash?","k":["Invest in growth (CapEx, R&D)","Pay down debt","Make acquisitions","Buy back shares","Pay dividends"],"collection":"practice","topic":"Finance Brain Teasers","tags":["Finance Brain Teasers","Advanced"]},{"id":"q-0423","t":"mkt","l":"Advanced","s":90,"q":"Negative news surfaces about a company. What typically happens to the stock price vs. the senior debt?","k":["Equity (being riskier and junior) usually falls more dramatically, while senior debt has priority in a default scenario and may drop less in price."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Finance Brain Teasers","Advanced"]},{"id":"q-0424","t":"acct","l":"Basic","s":90,"q":"You sell PP&E for $100 cash for a gain of $20. Assume a 25% tax rate.\n\n\n\n\nWalk through the 3 statements at sale.","k":["Starting on the IS...","Pretax income +20","Assuming 25 % tax, NI +15","Moving onto the SCF...","NI +15 in CFO","Subtract non-cash gain 20","Add sale proceeds in CFI (+100)","Net cash +95","Finally, on the BS...","A: Cash +95, PP&E −80","L: No change","SE: +15 retained earnings","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Ardea Partners Interview","SA 2025, off-cycle, London office","Accounting","Basic"]},{"id":"q-0425","t":"acct","l":"Basic","s":90,"q":"A parcel of land with a book value of $300 is sold for $400 in cash.\n\n\n\n\nAssuming a 25% tax rate, walk me through the impact on the three financial statements.","k":["Starting on the IS...","Gain on Sale = $400 - $300 = $100","Tax on Gain = $100 * 25% = $25","Net Income increases by $75","Moving onto the SCF...","Net Income +$75","Subtract $100 gain (non-operating)","Add $400 cash proceeds in CFI","Net change in cash is +$375","Finally, on the BS...","A: Cash +$375, Land -$300. Net Assets +$75","L: No change","SE: Retained Earnings +$75","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Bank of America Interview","Superday","Accounting","Basic"]},{"id":"q-0426","t":"acct","l":"Basic","s":90,"q":"A company with $500 in cash and $500 in shareholder's equity on its balance sheet purchases $1,000 of PP&E, financing it with the existing $500 in cash and $500 of new debt.\n\n\n\n\nWalk me through the 3 financial statements at the time of purchase.","k":["Starting on the IS...","No change (asset purchases don't affect the IS).","Moving onto the SCF...","CFI -$1,000 for PP&E purchase.","CFF +$500 from new debt issuance.","Net change in cash -$500.","Finally, on the BS...","Assets: Cash -$500, PP&E +$1,000. Net Assets +$500.","Liabilities: Debt +$500.","SE: No change.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Bank of America Interview","M&A, Power, First round","Accounting","Basic"]},{"id":"q-0427","t":"acct","l":"Basic","s":90,"q":"What do you call it when you take out $100 in debt and use that money to buy your family a boat? Walk me through the impact on the three financial statements. Assume a 25% tax rate.","k":["This is called a dividend recapitalization (or leveraged dividend). The company takes on debt and distributes the proceeds to shareholders (in this case, buying the boat is analogous to a distribution).","Starting on the IS...","No immediate impact (dividends and debt issuance do not hit the IS)","Moving onto the SCF...","CFF: +100 from debt issuance","CFF: -100 from dividend/distribution","Net change in cash is 0","Finally, on the BS...","A: No change (cash in and out nets to 0)","L: Debt up 100","SE: Retained Earnings down 100 (from the dividend)","...and the Balance Sheet balances (A 0 = L +100 + SE -100 = 0)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Bank of America Interview","SA 2027, New York Office, Superday","Accounting","Basic"]},{"id":"q-0428","t":"acct","l":"Basic","s":90,"q":"A company has $25 in cost of goods sold and sells its product for $50 in revenue. Assume a 50% tax rate and $5 in interest expense. Walk me through the three financial statements.","k":["Starting on the IS...","Revenue: $50","Less COGS: $25","Gross Profit: $25","Less Interest Expense: $5","Pre-tax Income: $20","Taxes (50%): $10","NI: $10","Moving onto the SCF...","NI +10","Assuming no non-cash charges or working capital changes","Net change in cash is up $10","Finally, on the BS...","A: Cash up $10","L: No change","SE: Retained Earnings up $10 from NI","...and the Balance Sheet balances (+10 = 0 + 10)","Flag the inventory assumption: the above treats the $25 of COGS as paid in cash this period. If the goods were already in inventory, COGS is non-cash and you relieve inventory instead — SCF: NI +10 plus a $25 decrease in Inventory, so cash up $35; BS: Cash +35, Inventory -25, net assets +10. Either is fine, just state which you are assuming."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Bank of America Interview","SA 2027, Superday","Accounting","Basic"]},{"id":"q-0429","t":"acct","l":"Basic","s":90,"q":"A company issues $100 million in debt to fund a $100 million dividend payment. Assume a 25% tax rate. Walk me through the impact on the three financial statements.","k":["Starting on the IS...","No impact. Issuing debt and paying dividends are financing activities, not income statement items.","Moving onto the SCF...","CFF: +$100M from debt issuance","CFF: -$100M for dividend payment","Net change in cash is $0","Finally, on the BS...","A: No change (cash is net zero)","L: Debt up $100M","SE: Retained Earnings down $100M (dividends reduce RE)","...and the Balance Sheet balances (0 = +100 + (-100))"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Bank of America Interview","SA 2027, Superday","Accounting","Basic"]},{"id":"q-0430","t":"acct","l":"Basic","s":90,"q":"A company sells PP&E and uses the proceeds to pay down debt. Walk me through the Year 1 impact on the three financial statements.","k":["Assuming the PP&E is sold at book value (no gain or loss):","Starting on the IS...","No impact (no gain or loss on sale)","Moving onto the SCF...","CFI: + proceeds from sale of PP&E","CFF: - same amount for debt repayment","Net change in cash is 0","Finally, on the BS...","A: PP&E decreases by book value, cash unchanged","L: Debt decreases by the same amount","SE: No change","...and the Balance Sheet balances","Going forward, the IS would also be affected: lower depreciation expense (higher pre-tax income) and lower interest expense (from reduced debt), both increasing NI."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Bank of America Interview","SA 2026, First round","Accounting","Basic"]},{"id":"q-0431","t":"acct","l":"Basic","s":90,"q":"If you could get only one GAAP line to assess a company, which one would you choose and why?","k":["Many prefer cash flow from operations (CFO) on the cash flow statement, since it’s a pure measure of cash generated from core operations, less impacted by accounting assumptions than net income alone.","However, some might choose net income if they want a clean measure of profitability after all expenses (including interest and taxes). Answers can vary, but CFO is often considered most indicative of a firm’s health."],"collection":"practice","topic":"Accounting","tags":["Reported in Barclays Interview","Accounting","Basic"]},{"id":"q-0432","t":"acct","l":"Basic","s":90,"q":"How do you calculate how much in dividends a company has paid out?","k":["Dividends Paid = Beginning Retained Earnings + Net Income - Ending Retained Earnings.","This formula works because retained earnings increases by net income and decreases by dividends each period. You can also find dividends directly on the Cash Flow Statement under Cash Flow from Financing (CFF), where dividends paid is a separate line item. Additionally, you can calculate it as Dividends per Share x Shares Outstanding if per-share data is available."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Barclays Interview","SA 2026, New York Office, Superday","Accounting","Basic"]},{"id":"q-0433","t":"acct","l":"Basic","s":90,"q":"You buy $10 of inventory with cash and then sell it for $20. Assume a 25% tax rate. Walk me through the impact on the three financial statements.","k":["Starting on the IS...","Revenue +20","COGS +10","Pre-tax income +10","NI +7.50","Moving onto the SCF...","NI +7.50","Inventory decreased by 10 (sold), which is a source of cash in working capital","But we originally purchased inventory for 10 cash (use of cash)","Net: Cash from customer +20, cash paid for inventory -10, taxes -2.50, net cash +7.50","Finally, on the BS...","A: Cash +7.50, Inventory net 0 (bought and sold), net assets up $7.50","L: No change","SE: +7.50 from NI","...and the Balance Sheet balances (+7.50 = 0 + 7.50)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Barclays Interview","SA 2025","Accounting","Basic"]},{"id":"q-0434","t":"acct","l":"Basic","s":90,"q":"Assume a 25% tax rate. Walk me through the 3-statement impact of a $100 inventory write-down.","k":["Starting on the IS...","Write-down recorded as an expense (COGS or impairment charge) of $100","Pre-tax income down $100","NI down $75","Moving onto the SCF...","NI -75","Add back $100 (inventory write-down is a non-cash charge)","Net change in cash is up $25","Finally, on the BS...","A: Cash +25, Inventory -100, net assets down $75","L: No change","SE: -75 from NI","...and the Balance Sheet balances (-75 = 0 + -75)","One nuance: the above assumes the write-down is deductible this period, which is the standard answer. For tax it generally is not deductible until the inventory is sold or disposed of. On that treatment NI is still down $75, but the $25 is a deferred tax asset rather than a cash tax saving, so cash is unchanged and the BS shows Inventory -100, DTA +25, SE -75."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Barclays Interview","SF Office, First round","Accounting","Basic"]},{"id":"q-0435","t":"acct","l":"Basic","s":90,"q":"Walk me through the impact on the three financial statements if a company sells PP&E for more than its book value. Assume a 25% tax rate.","k":["Assume book value = BV and sale price = SP, where SP > BV. Gain = SP - BV.","Starting on the IS...","Record a gain of (SP - BV)","Pre-tax income up by (SP - BV)","NI up by (SP - BV) x 0.75","Moving onto the SCF...","NI up by (SP - BV) x 0.75","Subtract the gain on sale in CFO (non-operating)","Add SP in CFI (proceeds from sale of asset)","Net change in cash is up by SP - (SP - BV) x 0.25 = SP x 0.75 + BV x 0.25","Finally, on the BS...","A: Cash up, PP&E down by BV, net up by (SP - BV) x 0.75","L: No change","SE: Up by (SP - BV) x 0.75 from Retained Earnings","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Barclays Interview","SA 2025","Accounting","Basic"]},{"id":"q-0436","t":"acct","l":"Basic","s":90,"q":"If you were a CEO, would you prefer $10 of incremental revenue or $10 of cost savings? Why?","k":["$10 of cost savings is more valuable.","$10 of revenue only adds $10 x net margin to the bottom line. If net margin is 10%, that is only $1 of profit.","$10 of cost savings flows directly to the bottom line as $10 x (1 - tax rate) of additional net income.","At a 25% tax rate, $10 cost savings = $7.50 of NI, far more than $1 from revenue.","Cost savings are also generally more certain and immediate, while revenue growth requires sales effort and has execution risk."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Barclays Interview","SF Office, Superday","Accounting","Basic"]},{"id":"q-0437","t":"acct","l":"Basic","s":90,"q":"What could cause an increase in goodwill on the balance sheet?","k":["Goodwill increases when a company acquires another company for more than the fair value of its identifiable net assets.","Goodwill = Purchase Price - Fair Value of Net Identifiable Assets (tangible assets + identifiable intangibles - liabilities assumed).","An increase in goodwill on the balance sheet means the company completed an acquisition where it paid a premium above the fair value of net assets.","Goodwill is not amortized but is tested annually for impairment. It can decrease through impairment charges but can only increase through new acquisitions."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Barclays Interview","SA 2025","Accounting","Basic"]},{"id":"q-0438","t":"acct","l":"Basic","s":90,"q":"What are some examples of non-recurring charges?","k":["Examples include restructuring costs, asset write-downs, goodwill impairments, and legal settlements. These are items that occur outside the normal course of business and are usually excluded from metrics like EBITDA when analyzing core performance."],"collection":"practice","topic":"Accounting","tags":["Reported in BMO Interview","Accounting","Basic"]},{"id":"q-0439","t":"acct","l":"Basic","s":90,"q":"What is a stock option?","k":["A derivative contract giving the holder the right, but not the obligation, to buy (call) or sell (put) a set number of shares at a predetermined strike price before or at expiration."],"collection":"practice","topic":"Accounting","tags":["Reported in Centerview Partners Interview","SA 2026, New York office, Superday","Accounting","Basic"]},{"id":"q-0440","t":"acct","l":"Basic","s":90,"q":"Can a company have negative shareholders' equity? What does it mean?","k":["Yes. Negative shareholders' equity means a company's total liabilities exceed its total assets.","Common causes:","Accumulated losses: Years of net losses erode retained earnings (e.g., early-stage companies).","Excessive share buybacks: Large buyback programs funded with debt can drive treasury stock higher than contributed capital plus retained earnings (e.g., Starbucks, McDonald's).","Large dividend payments: Paying out more than earnings over time depletes equity.","Leveraged recapitalizations: Taking on debt to fund special dividends.","Negative book equity does not necessarily mean the company is insolvent -- it often has significant intangible value not captured on the balance sheet."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Citi Interview","SA 2026, New York Office, First round","Accounting","Basic"]},{"id":"q-0441","t":"acct","l":"Basic","s":90,"q":"In the P/E ratio formula (Market Price per Share / Earnings per Share), should the number of shares used to calculate EPS be based on a point in time or an average over a period?","k":["The number of shares should be an average over the period (weighted average shares outstanding).","EPS is calculated using Net Income (which accumulates over a period) divided by weighted average shares outstanding during that period. This matches the timing of earnings generation with share count.","Using a point-in-time share count would misstate EPS if the company issued or repurchased shares during the period. The P/E ratio's numerator (current share price) is point-in-time, but the denominator (EPS) uses period-average shares for consistency with income statement reporting."],"collection":"practice","topic":"Accounting","tags":["Reported in Credit Suisse Interview","SF office","Accounting","Basic"]},{"id":"q-0442","t":"acct","l":"Basic","s":90,"q":"If a company wants to boost its EPS, what are some actions it can take?","k":["Actions to increase EPS:","Increase net income through revenue growth or cost reductions","Repurchase shares to reduce shares outstanding","Improve operating margins through efficiency gains","Divest underperforming or non-core assets","Acquire accretive businesses","Optimize capital structure (e.g., use cheap debt to buy back expensive equity)","Reduce tax burden through restructuring or credits","Cut dividend to retain more earnings (though may harm stock price)","Recognize deferred tax assets or one-time gains","Note: Some actions provide sustainable EPS growth while others are one-time or financial engineering. The market values sustainable operational improvements more highly."],"collection":"practice","topic":"Accounting","tags":["Reported in Credit Suisse Interview","Superday","Accounting","Basic"]},{"id":"q-0443","t":"acct","l":"Basic","s":90,"q":"Assuming a 25% tax rate, walk me through the 3 statements for the sale of an asset for $500, which has a book value of $400.","k":["Starting on the IS...","Gain on Sale = $500 - $400 = $100.","Pre-tax income up $100.","NI up $75.","Moving onto the SCF...","NI +$75.","Subtract $100 gain on sale.","Add $500 proceeds in CFI.","Net change in cash +$475.","Finally, on the BS...","A: Cash +$475, Asset -$400, net +$75.","L: No change.","SE: Retained Earnings +$75.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Credit Suisse Interview","Energy & Infrastructure group, First round","Accounting","Basic"]},{"id":"q-0444","t":"acct","l":"Basic","s":90,"q":"Assuming a 25% tax rate and 10-year straight-line depreciation, walk me through the 3-statement impact of a $100 increase in Capex financed with cash.\n\n\n\n\nPart 1: At the time of purchase.\n\n\n\n\nPart 2: After one year.","k":["Part 1: At Purchase","IS: No change.","CFS: CFI -$100. Net cash -$100.","BS: Cash -$100, PP&E +$100.","Part 2: After One Year","Starting on the IS...","Depreciation Expense +$10 ($100 / 10 years).","Pre-tax income down $10.","NI down $7.5.","Moving onto the SCF...","NI -$7.5.","Add back $10 depreciation.","Net change in cash +$2.5.","Finally, on the BS...","A: Cash +$2.5, PP&E -$10, net -$7.5.","L: No change.","SE: Retained Earnings -$7.5.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Credit Suisse Interview","LFO group, First round","Accounting","Basic"]},{"id":"q-0445","t":"acct","l":"Basic","s":90,"q":"Which financial statement shows a snapshot in time and which shows activity over a period? Why?","k":["Snapshot in Time","The Balance Sheet. It shows what a company owns (assets), owes (liabilities), and the residual equity at a specific date. It reflects cumulative balances, not flows.","Activity Over a Period","The Income Statement and Statement of Cash Flows. Both capture activity over a defined period (quarter, year). The IS shows revenue earned and expenses incurred, and the SCF shows cash inflows and outflows during that period.","This is why the BS is dated \"as of\" a specific date, while the IS and SCF are \"for the period ended\" a specific date."],"collection":"practice","topic":"Accounting","tags":["New","Reported in DC Advisory Interview","Generalist group, New York Office, Superday","Accounting","Basic"]},{"id":"q-0446","t":"acct","l":"Basic","s":90,"q":"Walk me through a $10 inventory purchase with cash. Then, walk me through what happens when you sell it for $20. Assume no taxes.","k":["Purchase (Inventory Acquisition)","Starting on the IS...","No impact on the income statement","Moving onto the SCF...","CFO: -$10 for the inventory purchase","Net change in cash: -$10","Finally, on the BS...","A: Inventory +$10, Cash -$10","L: No change","SE: No change","...and the Balance Sheet balances","Sale (Inventory Disposition)","Starting on the IS...","Revenue +$20","COGS +$10","Net Income +$10","Moving onto the SCF...","NI +$10","Inventory decrease of $10 → +$10 to CFO","Net +$20 in cash from operations","Finally, on the BS...","A: Cash +$20, Inventory -$10","L: No change","SE: Retained Earnings +$10","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Basic"]},{"id":"q-0447","t":"acct","l":"Basic","s":90,"q":"What is the accounting treatment when you receive $10 but haven’t provided the service yet? What happens when you finally provide the service?","k":["When $10 is received (but service not yet provided)","Starting on the IS...","No changes (revenue not yet recognized)","Moving onto the SCF...","CFO: +$10 (cash inflow from advance payment)","Finally, on the BS...","A: Cash +$10","L: Deferred Revenue +$10","SE: No change","...and the Balance Sheet balances","When the service is provided","Starting on the IS...","Revenue +$10","Assuming no associated expenses, Net Income +$10","Moving onto the SCF...","NI +$10","Reduction of Deferred Revenue (non-cash item) offsets in CFO → no net cash impact this period","Finally, on the BS...","A: No net change in Cash here","L: Deferred Revenue -$10","SE: Retained Earnings +$10","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Basic"]},{"id":"q-0448","t":"acct","l":"Basic","s":90,"q":"Assuming a 25% tax rate, walk me through the 3 statements after inventory is sold for $20 in cash. The cost of the inventory was $10.","k":["Starting on the IS...","Revenue +$20.","COGS +$10.","Gross Profit +$10.","Pre-tax income +$10.","NI +$7.5.","Moving onto the SCF...","NI +$7.5.","Inventory down $10 (use of working capital adds to CFO).","Net change in cash +$17.5.","Finally, on the BS...","A: Cash +$17.5, Inventory -$10, net +$7.5.","L: No change.","SE: Retained Earnings +$7.5.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Superday","Accounting","Basic"]},{"id":"q-0449","t":"acct","l":"Basic","s":90,"q":"How can you look at D&A and CapEx to determine whether a company is growing or shrinking?","k":["Compare CapEx to D&A:","If CapEx > D&A: The company is investing more in new assets than the rate at which existing assets are wearing out. This signals the company is growing its asset base and likely expanding.","If CapEx < D&A: The company is not replacing its assets fast enough. Its asset base is shrinking, which typically indicates maintenance mode or decline.","If CapEx ≈ D&A: The company is roughly maintaining its existing asset base with no net growth.","This is a quick and useful heuristic, but it has limits. For example, a company shifting to an asset-light model may have CapEx < D&A while still growing revenue. Always consider it alongside revenue trends and management commentary."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2027","Accounting","Basic"]},{"id":"q-0450","t":"acct","l":"Basic","s":90,"q":"What items are typically added back to EBITDA?","k":["Common EBITDA add-backs (adjustments to arrive at \"Adjusted EBITDA\"):","Stock-based compensation (non-cash).","One-time restructuring charges or severance costs.","Non-recurring litigation or settlement costs.","Transaction-related expenses (M&A advisory fees, integration costs).","Non-cash impairment charges or write-downs.","Management fees paid to PE sponsors.","Run-rate cost savings from completed or planned initiatives.","Non-recurring gain/loss on asset sales.","Be cautious with add-backs: some companies aggressively adjust EBITDA to inflate metrics. Scrutinize whether items are truly non-recurring."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2025, First round","Accounting","Basic"]},{"id":"q-0451","t":"acct","l":"Basic","s":90,"q":"Walk me through the cash flow statement and describe some of its key line items.","k":["The CFS has three sections:","Cash Flow from Operations (CFO):","Starts with Net Income.","Adds back non-cash charges: D&A, SBC, deferred taxes.","Adjusts for changes in working capital (AR, inventory, AP, accrued liabilities).","Cash Flow from Investing (CFI):","CapEx (purchases of PP&E).","Acquisitions or divestitures.","Purchases/sales of investments or securities.","Cash Flow from Financing (CFF):","Debt issuance or repayment.","Equity issuance or share buybacks.","Dividends paid.","Net change in cash = CFO + CFI + CFF. This updates the cash balance on the BS."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","M&A group, New York Office, Superday","Accounting","Basic"]},{"id":"q-0452","t":"acct","l":"Basic","s":90,"q":"What could a company do with its excess free cash flows?","k":["A company has several options for deploying excess FCF:","Reinvest in the business through capital expenditures, R&D, or organic growth initiatives.","Make acquisitions (M&A) to expand into new markets, add capabilities, or consolidate the industry.","Pay down debt to reduce leverage and lower interest expense.","Return cash to shareholders through dividends (regular or special).","Repurchase shares, which increases EPS by reducing shares outstanding and signals management confidence in the stock.","Build cash reserves on the balance sheet for future opportunities or as a buffer against downturns.","The optimal use depends on the company's growth stage, leverage, cost of capital, and shareholder expectations. High-growth companies typically reinvest; mature companies with limited organic opportunities tend to return cash to shareholders."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, First round","Accounting","Basic"]},{"id":"q-0453","t":"acct","l":"Basic","s":90,"q":"How could you tell if a company has too much debt?","k":["Compare the company's leverage ratio (Debt / EBITDA) to industry peers. If it is significantly above the median for its sector, the company may be overleveraged.","Examine the interest coverage ratio (EBITDA / Interest Expense). A low or declining coverage ratio indicates the company is struggling to service its debt from operating earnings.","Check credit ratings. A low or declining credit rating from agencies like S&P or Moody's signals elevated default risk.","Look at credit spreads on the company's bonds. Widening spreads indicate the market is demanding a higher premium for lending to the company, reflecting increased perceived risk.","Assess whether free cash flow comfortably covers debt service obligations (interest payments plus mandatory principal repayments). If FCF is insufficient, the company may need to refinance or restructure.","Review debt covenants. If the company is approaching or violating covenant thresholds, it is a sign that debt levels are unsustainable."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, Superday","Accounting","Basic"]},{"id":"q-0454","t":"acct","l":"Basic","s":90,"q":"Walk me through the impact of a $100 capital raise using equity on the three financial statements.","k":["Starting on the IS...","No impact. Issuing equity does not flow through the income statement.","Moving onto the SCF...","CFF: +100 from equity issuance","Net change in cash is +100","Finally, on the BS...","A: Cash +100","L: No change","SE: Common Stock / Additional Paid-In Capital +100","...and the Balance Sheet balances (A +100 = L 0 + SE +100)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, Superday","Accounting","Basic"]},{"id":"q-0455","t":"acct","l":"Basic","s":90,"q":"Walk me through the impact of deferred revenue on the three financial statements. Assume a 25% tax rate.","k":["Deferred revenue has two phases: when cash is received upfront and when the revenue is recognized.","Phase 1: Cash Received (Service Not Yet Delivered)","Starting on the IS...","No change (revenue is not recognized until earned)","Moving onto the SCF...","Deferred Revenue increases (a source of cash in working capital)","Net change in cash is up by the amount received","Finally, on the BS...","A: Cash up","L: Deferred Revenue up (same amount)","SE: No change","...and the Balance Sheet balances","Phase 2: Revenue Recognized (Service Delivered)","This is equivalent to a decrease in Deferred Revenue.","Starting on the IS...","Revenue increases","Pre-tax income increases","NI increases (by revenue x (1 - 25%))","Moving onto the SCF...","NI up","Deferred Revenue decreases (uses cash in working capital)","Net change in cash is down (the NI gain is partially offset by the working capital reduction)","Finally, on the BS...","A: Cash decreases by the tax amount (25% of revenue recognized)","L: Deferred Revenue down","SE: Retained Earnings up from NI","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in FT Partners Interview","Accounting","Basic"]},{"id":"q-0456","t":"acct","l":"Basic","s":90,"q":"Accounts Receivable increases by $2. Walk me through the impact on the three financial statements, assuming a 40% tax rate.","k":["Starting on the IS...","$2 increase in revenue/pre-tax income","Net Income is up by $1.2","Moving onto the SCF...","Net Income is up by $1.2, but the rise in AR reduces cash flow by $2 since the revenue hasn't been received in cash yet","Thus, the cash balance decreases by $0.8","Finally, on the BS...","A: Accounts Receivable increases by $2, Cash decreases by $0.8, resulting in a $1.2 increase in total assets.","L: No changes to liabilities.","SE: Retained earnings increases by $1.2.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Goldman Sachs Interview","Accounting","Basic"]},{"id":"q-0457","t":"acct","l":"Basic","s":90,"q":"A company has an EBIT larger than its EBITDA. Why would that be puzzling?","k":["EBITDA = EBIT + D&A, and D&A is a positive value (reducing income).","If D&A appears as a negative expense, this is unusual and usually indicates an error, a reversal, or an accounting adjustment."],"collection":"practice","topic":"Accounting","tags":["Reported in Goldman Sachs Interview","SA 2025, New York office, Superday","Accounting","Basic"]},{"id":"q-0458","t":"acct","l":"Basic","s":90,"q":"Walk me through the 3 financial statements right after a company issues $100 million of debt.","k":["Starting on the IS...","No change.","Moving onto the SCF...","CFF +$100M from debt issuance.","Net change in cash +$100M.","Finally, on the BS...","A: Cash +$100M.","L: Debt +$100M.","SE: No change.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Goldman Sachs Interview","First round","Accounting","Basic"]},{"id":"q-0459","t":"acct","l":"Basic","s":90,"q":"What is the difference between a current asset and a non-current asset?","k":["A current asset is expected to be converted to cash or consumed within one year (e.g., cash, accounts receivable, inventory, prepaid expenses). A non-current asset has a useful life beyond one year (e.g., PP&E, intangible assets, goodwill, long-term investments).","The distinction matters for liquidity analysis. Current assets support day-to-day operations and short-term obligations, while non-current assets represent long-term investments in the business."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Goldman Sachs Interview","SA 2026, First round","Accounting","Basic"]},{"id":"q-0460","t":"acct","l":"Basic","s":90,"q":"If accounts receivable increases, what happens to the cash flow statement?","k":["An increase in accounts receivable reduces cash flow from operations.","When AR increases, the company has recognized revenue on the IS (boosting net income) but has not yet collected the cash. On the SCF, this increase in AR is subtracted from CFO as a use of cash (or more precisely, as a working capital adjustment that reduces operating cash flow relative to net income)."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Goldman Sachs Interview","SA 2026, First round","Accounting","Basic"]},{"id":"q-0461","t":"acct","l":"Basic","s":90,"q":"How does revenue recognition affect the balance sheet?","k":["Revenue recognition determines when revenue appears on the IS and directly impacts the BS:","Revenue recognized before cash collected: Accounts Receivable (asset) increases.","Cash collected before revenue recognized: Deferred Revenue (liability) increases. As the obligation is fulfilled, Deferred Revenue decreases and Revenue is recognized.","Revenue recognized and cash collected simultaneously: Cash increases with no receivable or deferred revenue created.","In all cases, Retained Earnings in SE increases by the after-tax amount of recognized revenue."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Goldman Sachs Interview","SA 2026, First round","Accounting","Basic"]},{"id":"q-0462","t":"acct","l":"Basic","s":90,"q":"Does a 10% increase in revenue result in a 10% increase in profits?","k":["Only if costs scale 100% with revenue.","With fixed costs, operating leverage makes profit grow >10%; if margins compress, profit could grow <10% or even fall."],"collection":"practice","topic":"Accounting","tags":["Reported in Greenhill & Co. Interview","SA 2024, Industrials M&A, Chicago office","Accounting","Basic"]},{"id":"q-0463","t":"acct","l":"Basic","s":90,"q":"Intuitively, why does an increase in net working capital reduce cash on the cash‑flow statement?","k":["An increase either builds current assets or pays down current liabilities, both of which use cash.","Growing inventories, receivables or prepaids ties up cash before revenue is collected.","Reducing payables or accrued expenses sends cash out the door sooner."],"collection":"practice","topic":"Accounting","tags":["Reported in Guggenheim Partners Interview","Accounting","Basic"]},{"id":"q-0464","t":"acct","l":"Basic","s":90,"q":"Beginning with revenue, how do you calculate EBITDA?","k":["EBITDA = Revenue − COGS − Operating Expenses + Depreciation & Amortization (if D&A was included in either COGS or OpEx buckets)","Start with revenue.","Subtract cost of goods sold to reach gross profit.","Subtract SG&A, R&D and other operating expenses to get to operating income.","Add back any D&A included in COGS or OpEx buckets."],"collection":"practice","topic":"Accounting","tags":["Reported in Guggenheim Partners Interview","Accounting","Basic"]},{"id":"q-0465","t":"acct","l":"Basic","s":90,"q":"Explain EBITDA to me as if I were a 5-year-old.","k":["EBITDA is how much money a business makes from selling things, after paying for what it needs to make those things, but before paying interest on loans, taxes to the government, or accounting for its stuff getting old.","It's like your lemonade stand's profits before you pay back money you borrowed from your parents, pay allowance tax, or count that your pitcher got a crack in it."],"collection":"practice","topic":"Accounting","tags":["Reported in Guggenheim Partners Interview","M&A group, First round","Accounting","Basic"]},{"id":"q-0466","t":"acct","l":"Basic","s":90,"q":"What financial metric does EBITDA approximate?","k":["EBITDA approximates cash flow from operations before changes in working capital.","It represents the operating cash generation of a business by excluding non-cash charges (D&A), financing costs (interest), and taxes.","However, EBITDA is not true cash flow since it ignores working capital changes and capital expenditures."],"collection":"practice","topic":"Accounting","tags":["Reported in Guggenheim Partners Interview","M&A group, First round","Accounting","Basic"]},{"id":"q-0467","t":"acct","l":"Basic","s":90,"q":"How does Accounts Receivable and Accounts Payable impact Net Working Capital and Unlevered Free Cash Flow? How is cash affected by those items, and why do you add or subtract them?","k":["Accounts Receivable (AR)","An increase in AR increases NWC and reduces FCF. Revenue was recorded but cash not yet collected. Subtract the increase from FCF.","A decrease in AR decreases NWC and increases FCF - cash collected from prior-period sales.","Accounts Payable (AP)","An increase in AP decreases NWC and increases FCF. An expense was recorded but cash not yet paid. Add the increase to FCF.","A decrease in AP increases NWC and reduces FCF - you paid off amounts owed.","Working capital adjustments convert net income from accrual to cash basis."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Guggenheim Partners Interview","SA 2027, Business Services group, Atlanta Office, Phone screen","Accounting","Basic"]},{"id":"q-0468","t":"acct","l":"Basic","s":90,"q":"Walk me through the three financial statements if you hire a consultant for $500. Assume a 25% tax rate.","k":["Starting on the IS...","Operating expense (consulting fee) +500","Pre-tax income down 500","NI down 375","Moving onto the SCF...","NI -375","No non-cash add-backs (consulting is a cash expense)","Net change in cash is -375","Finally, on the BS...","A: Cash -375","L: No change","SE: -375 from NI","...and the Balance Sheet balances","Note: Cash decreases by only 375 (not 500) because the 500 expense creates a tax shield of 125 (500 x 25%), reducing taxes paid."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Guggenheim Partners Interview","SA 2025","Accounting","Basic"]},{"id":"q-0469","t":"acct","l":"Basic","s":90,"q":"Now walk me through the three financial statements if you capitalize the $500 consulting expense instead. What account does it impact?","k":["If capitalized, the $500 goes to an intangible asset on the balance sheet (e.g., capitalized consulting/project costs) rather than being expensed immediately.","Starting on the IS...","No impact on the IS in Year 0 (the cost is not expensed yet)","Moving onto the SCF...","NI unchanged","CFI -500 (capitalized as an investing activity)","Net change in cash is -500","Finally, on the BS...","A: Cash -500, Intangible Asset +500, net 0","L: No change","SE: No change","...and the Balance Sheet balances","In subsequent years, the capitalized asset will be amortized, creating an expense on the IS similar to depreciation. Note that capitalizing results in worse near-term cash flow (cash down 500 vs. 375 when expensed) because there is no immediate tax shield."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Guggenheim Partners Interview","SA 2025","Accounting","Basic"]},{"id":"q-0470","t":"acct","l":"Basic","s":90,"q":"What is net working capital? What does negative net working capital mean, and is it necessarily a bad thing?","k":["Net working capital (NWC) = Current Assets - Current Liabilities. It measures a company's short-term liquidity and operational efficiency.","Negative NWC means current liabilities exceed current assets. This is not necessarily bad. Companies like Amazon and Walmart have negative NWC because they collect cash from customers before paying suppliers, effectively using supplier financing to fund operations. This is actually a sign of strong bargaining power and efficient cash conversion.","However, negative NWC can be concerning if it results from an inability to pay obligations, excessive short-term borrowing, or deteriorating collections."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Guggenheim Partners Interview","SA 2027, Superday","Accounting","Basic"]},{"id":"q-0471","t":"acct","l":"Basic","s":90,"q":"A company purchases PP&E. Conceptually (no numbers), what happens to the three financial statements in Year 0 and in Year 1?","k":["Year 0 (Purchase)","IS: No change (CapEx is capitalized, not expensed)","SCF: CFI decreases by the purchase amount. If debt-funded, CFF increases to offset.","BS: PP&E increases. Cash decreases (if cash-funded) or Debt increases (if debt-funded).","Year 1 (Depreciation begins)","IS: Depreciation expense reduces pre-tax income and NI.","SCF: NI decreases, but D&A is added back. Net cash effect is a small increase from the tax shield (D&A x Tax Rate).","BS: PP&E decreases by depreciation. Cash up slightly. RE decreases by NI reduction."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Harris Williams Interview","SA 2026, Superday","Accounting","Basic"]},{"id":"q-0472","t":"acct","l":"Basic","s":90,"q":"Assuming a 30% tax rate, walk me through the 3 financial statements for a $10 million increase in depreciation expense.","k":["Starting on the IS...","Depreciation up $10M","Pre-tax income down $10M","NI down $7M","Moving onto the SCF...","NI -$7M","Add back $10M depreciation (non-cash)","Net change in cash is +$3M","Finally, on the BS...","A: Cash +$3M, PP&E -$10M, net -$7M","L: No change","SE: Retained Earnings -$7M","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Houlihan Lokey Interview","New York office","Accounting","Basic"]},{"id":"q-0473","t":"acct","l":"Basic","s":90,"q":"What are the key differences between a 10-K and a 10-Q?","k":["Key differences:","10-K: Annual report with audited financial statements.","10-Q: Quarterly report with unaudited financial statements.","10-K is more comprehensive (business overview, risk factors, MD&A).","10-Q provides updates on quarterly performance and changes.","10-K filed once per year; 10-Q filed three times per year.","10-K has stricter disclosure requirements."],"collection":"practice","topic":"Accounting","tags":["Reported in Houlihan Lokey Interview","FIG Second round","Accounting","Basic"]},{"id":"q-0474","t":"acct","l":"Basic","s":90,"q":"Walk me through the impact on the three financial statements when a company records $10 of PIK (Payment-In-Kind) interest expense. Assume a 25% tax rate.","k":["Starting on the IS...","Interest expense up by 10","Pre-tax income down by 10","NI down by 7.50","Moving onto the SCF...","NI -7.50","Add back 10 in CFO since PIK interest is a non-cash expense","Net change in cash is up 2.50","Finally, on the BS...","A: Cash up 2.50","L: Debt up 10 (PIK accrues to the debt balance)","SE: Retained Earnings down 7.50","...and the Balance Sheet balances (A +2.50 = L +10 + SE -7.50 = +2.50)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Houlihan Lokey Interview","SA 2027, Business Services group, LA Office, First round","Accounting","Basic"]},{"id":"q-0475","t":"acct","l":"Basic","s":90,"q":"How do you calculate the change in Net Working Capital, and what does it signify?","k":["Net Working Capital (NWC) = Current Operating Assets - Current Operating Liabilities = (Accounts Receivable + Inventory + Prepaid Expenses) - (Accounts Payable + Accrued Liabilities).","Change in NWC = Current Period NWC - Prior Period NWC.","An increase in NWC means the company is tying up more cash in operations (e.g., building inventory or extending more credit to customers). This is a use of cash and reduces Free Cash Flow.","A decrease in NWC means the company is freeing up cash (e.g., collecting receivables faster, running down inventory, or delaying payments to suppliers). This is a source of cash and increases Free Cash Flow.","The change in NWC is critical in FCF calculations because it bridges the gap between accrual-based Net Income and actual cash generation. A company can be profitable on paper but cash-poor if NWC is increasing rapidly."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Houlihan Lokey Interview","SA 2027, Industrials group, First round","Accounting","Basic"]},{"id":"q-0476","t":"acct","l":"Basic","s":90,"q":"What is a net working capital peg?","k":["A net working capital (NWC) peg is a target level of NWC agreed upon in an M&A purchase agreement. It represents the \"normal\" amount of working capital needed to operate the business.","How it works:","The buyer and seller agree on a target NWC amount (the \"peg\") based on historical averages, typically trailing 6-12 months.","At closing, the actual NWC is measured. If actual NWC exceeds the peg, the seller receives an upward adjustment to the purchase price. If it falls below, the buyer receives a downward adjustment.","This ensures the buyer receives a business with a \"normal\" level of working capital and prevents the seller from manipulating working capital (e.g., drawing down inventory or accelerating collections) before closing to extract extra cash.","The NWC peg is one of the most negotiated items in a purchase agreement because it directly affects the effective purchase price."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Houlihan Lokey Interview","SA 2027, Superday","Accounting","Basic"]},{"id":"q-0477","t":"acct","l":"Basic","s":90,"q":"How can a company have negative cash flow but still report positive EBITDA?","k":["EBITDA excludes several real cash outlays that reduce actual cash flow:","Cash taxes: EBITDA is pre-tax, but the company must pay taxes in cash.","Capital expenditures: Heavy CapEx spending (e.g., building factories, buying equipment) is not captured in EBITDA.","Interest payments: Debt service is excluded from EBITDA but consumes cash.","Working capital increases: Growth in AR or inventory ties up cash that EBITDA does not reflect.","Debt repayment: Mandatory principal repayments reduce cash but do not affect EBITDA.","A capital-intensive, highly leveraged, or fast-growing company can easily have positive EBITDA while burning cash."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Houlihan Lokey Interview","SA 2027, Technology group, New York Office","Accounting","Basic"]},{"id":"q-0478","t":"acct","l":"Basic","s":90,"q":"What is the difference between an operating lease and a financing lease?","k":["Under ASC 842, both types are on the balance sheet, but they differ in expense recognition:","Operating Lease: A single straight-line lease expense is recognized in operating expenses. The ROU asset and lease liability appear on the BS, but the IS treatment resembles renting -- one line item each period.","Financing Lease (formerly Capital Lease): Treated like a financed asset purchase. The IS shows depreciation on the ROU asset and interest expense on the lease liability separately. This front-loads total expense because interest is higher in early periods.","A lease is classified as a financing lease if it meets any of these criteria: transfers ownership, contains a bargain purchase option, the lease term is for the major part of the asset's useful life, or the PV of lease payments equals substantially all of the asset's fair value."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, First round","Accounting","Basic"]},{"id":"q-0479","t":"acct","l":"Basic","s":90,"q":"Assuming a 25% tax rate, walk me through the 3 statements if revenue increases by $100 and Gross Margin is 50%.","k":["Starting on the IS...","Revenue +$100.","COGS +$50 (since Gross Margin is 50%).","Gross Profit +$50.","Assuming no change in OpEx, Pre-tax income +$50.","Net Income +$37.50 ($50 * (1 - 25%)).","Moving onto the SCF...","Net Income +$37.50.","Assuming the COGS relates to inventory sold, we add back the Inventory Decrease of $50 (Source of cash).","Net change in cash +$87.50.","Finally, on the BS...","Assets: Cash +$87.50, Inventory -$50. Net Assets +$37.50.","Liabilities: No change.","SE: Retained Earnings +$37.50.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in J.P. Morgan Interview","SA 2025","Accounting","Basic"]},{"id":"q-0480","t":"acct","l":"Basic","s":90,"q":"Walk me through each section of the Cash Flow Statement.","k":["Cash Flow from Operations (CFO)","Starts with Net Income.","Adds back non-cash charges: D&A, stock-based compensation, amortization of intangibles, deferred taxes.","Adjusts for changes in working capital: increases in current assets (AR, inventory) reduce cash; increases in current liabilities (AP, accrued expenses) increase cash.","This section measures cash generated from the core business operations.","Cash Flow from Investing (CFI)","Capital expenditures (CapEx) for PP&E and intangible assets.","Acquisitions of businesses (cash paid net of cash acquired).","Proceeds from asset sales or divestitures.","Purchases and sales of investments and securities.","Cash Flow from Financing (CFF)","Debt issuance (proceeds) and debt repayment (outflows).","Equity issuance (IPO, follow-on) and share repurchases.","Dividend payments to shareholders.","Net change in cash = CFO + CFI + CFF. This is added to the beginning cash balance to get the ending cash balance on the Balance Sheet."],"collection":"practice","topic":"Accounting","tags":["New","Reported in J.P. Morgan Interview","SA 2025, Healthcare group, SF Office, Superday","Accounting","Basic"]},{"id":"q-0481","t":"acct","l":"Basic","s":90,"q":"Walk me through the 3-statement impact of a company buying a factory for $100 using 50% debt and 50% cash. Assume a 25% tax rate.","k":["Starting on the IS...","No impact at the time of purchase. Buying a factory is a capital expenditure, not an expense.","Moving onto the SCF...","CFI: -$100 for the factory purchase","CFF: +$50 from debt issuance","Net change in cash is down $50","Finally, on the BS...","A: Cash -50, PP&E +100, net assets up $50","L: Debt +50","SE: No change","...and the Balance Sheet balances (+50 = +50 + 0)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in J.P. Morgan Interview","SA 2027","Accounting","Basic"]},{"id":"q-0482","t":"acct","l":"Basic","s":90,"q":"What specific balance sheet items do you look at when considering net working capital?","k":["NWC = Operating Current Assets − Operating Current Liabilities.","Assets: Accounts Receivable, Inventory, Prepaids","Liabilities: Accounts Payable, Accrued Expenses, Deferred Revenue","Exclude cash, debt, and other financing items."],"collection":"practice","topic":"Accounting","tags":["Reported in Jefferies Interview","Restructuring group","Accounting","Basic"]},{"id":"q-0483","t":"acct","l":"Basic","s":90,"q":"What is EBITDA, conceptually?","k":["A proxy for recurring operating cash flow before non‑cash charges and capital‑structure effects.","It strips out D&A, interest, taxes and one‑offs to facilitate comparability across companies."],"collection":"practice","topic":"Accounting","tags":["Reported in Jefferies Interview","SA 2026","Accounting","Basic"]},{"id":"q-0484","t":"acct","l":"Basic","s":90,"q":"Given Revenue = 1000, COGS + SG&A = 600, D&A = 200. Calculate EBITDA.\n\n\n\n\nNote that COGS + SG&A does not include D&A.","k":["Answer: 400","EBITDA = Revenue – COGS – SG&A = 1,000 – 600 = 400 (D&A excluded).","Common mistake: adding D&A to cash OPEX. You add D&A back only when starting from EBIT or if the 600 includes D&A. Here it does not."],"collection":"practice","topic":"Accounting","tags":["Reported in Jefferies Interview","SA 2026","Accounting","Basic"]},{"id":"q-0485","t":"acct","l":"Basic","s":90,"q":"Walk me through the three financial statements and the impact of a $10 decrease in accounts payable.","k":["The Three Financial Statements","The Income Statement shows revenues, expenses, and net income over a period.","The Cash Flow Statement reconciles net income to actual cash generated, broken into operating, investing, and financing activities.","The Balance Sheet shows assets, liabilities, and shareholders' equity at a point in time (A = L + SE).","$10 Decrease in Accounts Payable","Starting on the IS...","No impact","Moving onto the SCF...","A decrease in AP is a use of cash (you paid suppliers)","Net change in cash is down $10","Finally, on the BS...","A: Cash down $10","L: AP down $10","SE: No change","...and the Balance Sheet balances (-10 = -10 + 0)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Jefferies Interview","SA 2027, Aerospace & Defense group, Charlotte Office, First round","Accounting","Basic"]},{"id":"q-0486","t":"acct","l":"Basic","s":90,"q":"What metrics would you use to compare two companies' uses of cash?","k":["Key metrics to compare cash usage:","CapEx as a % of Revenue: Shows how much the company reinvests in its asset base.","Dividend Payout Ratio (Dividends / Net Income): Shows how much earnings are returned to shareholders.","Share Repurchase Yield: Dollar amount of buybacks relative to market cap.","Debt Repayment / Total Debt: Indicates pace of deleveraging.","M&A Spend: Cash deployed on acquisitions as a percentage of revenue or total assets.","FCF Conversion (FCF / Net Income): Shows efficiency of converting earnings to cash.","Cash & Equivalents / Total Assets: Shows how much cash the company retains on the balance sheet."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Jefferies Interview","SA 2027, Aerospace & Defense group, Charlotte Office, First round","Accounting","Basic"]},{"id":"q-0487","t":"acct","l":"Basic","s":90,"q":"Part 1: Is it better to have low or high days sales outstanding (DSO), and why?\n\n\n\n\nPart 2: If a company moved from typically 20 days sales outstanding to 80 days sales outstanding, is that a good or bad thing and why?","k":["Part 1","Lower DSO is generally better. DSO measures how quickly a company collects cash from customers after making a sale. A lower DSO means faster cash collection, improved liquidity, and less capital tied up in receivables.","Part 2","Moving from 20 to 80 days is a significant negative signal. It means the company is taking 4x longer to collect from customers. This could indicate:","Customers are struggling to pay (credit quality deterioration)","The company is offering more lenient payment terms to win business, which could signal competitive pressure","Potential revenue recognition issues or channel stuffing","This shift ties up significant cash in AR and hurts free cash flow"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Jefferies Interview","SA 2027, Aerospace & Defense group, Charlotte Office, First round","Accounting","Basic"]},{"id":"q-0488","t":"acct","l":"Basic","s":90,"q":"Calculate EPS given the following: Revenue of $500 million, a Net Margin of 12%, Market Cap of $3 billion, and Share Price of $30.","k":["Step-by-step:","Net Income = Revenue x Net Margin = $500M x 12% = $60 million.","Shares Outstanding = Market Cap / Share Price = $3,000M / $30 = 100 million shares.","EPS = Net Income / Shares Outstanding = $60M / 100M = $0.60 per share.","Key takeaway:","To calculate EPS, you always need Net Income and Shares Outstanding. If you are given Revenue but not NI directly, you need a profitability metric (net margin, P/E ratio, or another bridge) to derive NI. If you are given Market Cap and Share Price, you can back into Shares Outstanding."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Jefferies Interview","SA 2025, TMT group, SF Office, Superday","Accounting","Basic"]},{"id":"q-0489","t":"acct","l":"Basic","s":90,"q":"What's the difference between cash and GAAP EPS?","k":["GAAP EPS follows accounting rules and includes non-cash expenses like depreciation, amortization, stock-based comp, and sometimes intangible write-downs.","Cash EPS (or sometimes “cash earnings”) often excludes non-cash charges to show a closer approximation of actual cash flow generation per share."],"collection":"practice","topic":"Accounting","tags":["Reported in Lazard Interview","Accounting","Basic"]},{"id":"q-0490","t":"acct","l":"Basic","s":90,"q":"Where on a company's 10-K filing would you typically find the number of shares outstanding?","k":["On the cover page, typically right above \"DOCUMENTS INCORPORATED BY REFERENCE\"."],"collection":"practice","topic":"Accounting","tags":["Reported in Lazard Interview","Accounting","Basic"]},{"id":"q-0491","t":"acct","l":"Basic","s":90,"q":"How does Net Working Capital impact cash flow?","k":["Net Working Capital (NWC) = Current Operating Assets - Current Operating Liabilities = (Accounts Receivable + Inventory + Prepaid Expenses) - (Accounts Payable + Accrued Liabilities + Deferred Revenue)","Impact on Cash Flow:","An increase in NWC is a use of cash (negative on the SCF). The company is tying up more cash in operations.","A decrease in NWC is a source of cash (positive on the SCF). The company is freeing up cash from operations.","Key Relationships:","AR increases = cash outflow (you are owed more but haven't collected).","Inventory increases = cash outflow (you bought more inventory).","AP increases = cash inflow (you owe more but haven't paid yet).","Deferred Revenue increases = cash inflow (you collected cash before delivering the service).","In a DCF, changes in NWC are subtracted from NOPAT when calculating Free Cash Flow. Companies with growing NWC needs (asset-heavy, inventory-intensive businesses) convert less of their EBITDA to cash."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Lazard Interview","SA 2025, Houston Office, First round","Accounting","Basic"]},{"id":"q-0492","t":"acct","l":"Basic","s":90,"q":"Would you rather have $100 in inventory or $100 in receivables?","k":["$100 in receivables.","Receivables convert to cash faster and carry no storage or obsolescence risk, improving liquidity and working‑capital efficiency.","Note: While inventory might be sold for a profit (e.g., $150), interviews typically prioritize liquidity and asset quality, making receivables the standard answer."],"collection":"practice","topic":"Accounting","tags":["Reported in LionTree Interview","SA 2026","Accounting","Basic"]},{"id":"q-0493","t":"acct","l":"Basic","s":90,"q":"How does a $10 increase in unearned revenue flow through the 3 statements?","k":["Starting on the IS...","No change; revenue not yet earned.","Moving onto the SCF...","CFO + 10 from the increase in unearned revenue.","Net cash up 10.","Finally, on the BS...","A: Cash + 10.","L: Deferred Revenue + 10.","SE: No change.","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in M. Klein & Co. Interview","SA 2026","Accounting","Basic"]},{"id":"q-0494","t":"acct","l":"Basic","s":90,"q":"Walk me from EBITDA to Levered FCF.","k":["EBITDA − Cash Taxes (after interest shield) − CapEx − Change in NWC − Cash Interest − Mandatory Debt Principal Repayments = Levered Free Cash Flow","Start above D&A, so you don’t subtract and add it back; D&A only affects taxable income, which is captured in Cash Taxes. LFCF is cash to equity after interest and required amortization."],"collection":"practice","topic":"Accounting","tags":["Reported in M. Klein & Co. Interview","SA 2026","Accounting","Basic"]},{"id":"q-0495","t":"acct","l":"Basic","s":90,"q":"Revenue is growing at 10%. Under what circumstances would EBITDA grow at a different percentage?","k":["If margins change.","Examples: Operating leverage, price increases, cost cuts, or rising input costs can drive EBITDA growth faster or slower than the top line."],"collection":"practice","topic":"Accounting","tags":["Reported in M. Klein & Co. Interview","SA 2026","Accounting","Basic"]},{"id":"q-0496","t":"acct","l":"Basic","s":90,"q":"Part 1: If revenue increases by 10%, what happens to EBITDA?\n\n\n\n\nFollow-up: Explain the difference between fixed and variable costs and how they affect EBITDA when revenue changes.\n\n\n\n\nFollow-up: Can you think of a company with no fixed costs where EBITDA increases by more than revenue?","k":["Part 1: Revenue Up 10%","EBITDA increases by more than 10% due to operating leverage. Fixed costs stay constant while revenue grows, so a greater proportion of the incremental revenue falls to EBITDA.","Follow-up: Fixed vs. Variable Costs","Fixed costs (rent, salaries, depreciation) do not change with production volume. Variable costs (raw materials, commissions, shipping) scale with revenue. When revenue increases, fixed costs are spread over a larger base, improving margins and causing EBITDA to grow faster than revenue. The higher the proportion of fixed costs, the greater the operating leverage.","Follow-up: No Fixed Costs, EBITDA Still Grows More?","This is a trick question. If a company has 100% variable costs, EBITDA margins remain constant and EBITDA increases by exactly the same percentage as revenue (10%). For EBITDA to increase by more than revenue, the company needs some fixed cost component or the ability to increase prices faster than costs (i.e., improving unit economics or pricing power). A company with no fixed costs cannot have EBITDA grow faster than revenue in percentage terms, by definition."],"collection":"practice","topic":"Accounting","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, First round","Accounting","Basic"]},{"id":"q-0497","t":"acct","l":"Basic","s":90,"q":"You sell a $100 gift card with $20 of associated COGS and a 20% tax rate.\n\n\n\n\nWalk through the 3 statements first at sale and then at full redemption.","k":["Sale of Gift Card — no IS impact.","SCF: Cash +100 in CFO.","BS: Cash +100; Deferred Revenue +100.","Redemption","Starting on the IS...","Revenue +100","COGS 20 ⇒ Pre-tax +80","Tax −16","NI +64","Moving onto the SCF...","NI +64","Decrease Deferred Revenue −100 (working-capital outflow)","Decrease Inventory +20 (working-capital inflow)","Net Cash −16","Finally, on the BS...","A: Cash −16; Inventory −20","L: Deferred Revenue −100","SE: Retained Earnings +64","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","First round","Accounting","Basic"]},{"id":"q-0498","t":"acct","l":"Basic","s":90,"q":"Assume a $200 sale, with book value of $40, and a 60% tax rate.\n\n\n\n\nWalk through the impact on the 3 statements.","k":["Starting on the IS...","Gain = 200 − 40 = 160","Pre‑tax income +160","Tax −96","NI +64","Moving onto the SCF...","NI +64","Subtract non‑cash gain 160","Add sale proceeds +200 in CFI","Net Cash +104","Finally, on the BS...","A: Cash +104, PP&E −40","L: No change","SE: Retained Earnings +64","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","First round","Accounting","Basic"]},{"id":"q-0499","t":"acct","l":"Basic","s":90,"q":"From a net income perspective, would you rather have an additional dollar of revenue or cut an additional dollar of an operating expense? Why?","k":["Cutting $1 of expense increases net income by $1 × (1−tax), whereas $1 of extra revenue only increases NI by $1 × margin × (1−tax).","Expense ↓ $1 ⇒ NI ↑ $1 × (1−tax).","Revenue ↑ $1 ⇒ NI ↑ $1 × margin × (1−tax), lower unless margin = 100%."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","Accounting","Basic"]},{"id":"q-0500","t":"acct","l":"Basic","s":90,"q":"Assume a 40% tax rate. Walk me through the impact of a $10 write-down of PP&E on the three financial statements.","k":["Starting on the IS...","Pre‑tax income down 10","NI down 6","Moving onto the SCF...","NI −6","Add back 10 non‑cash write‑down","Net +4 cash","Finally, on the BS...","A: Cash +4, PP&E −10 → net −6","L: No change","SE: −6 in Retained Earnings","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","Accounting","Basic"]},{"id":"q-0501","t":"acct","l":"Basic","s":90,"q":"As a CFO during a period of rising prices, would you prefer to use the FIFO or LIFO inventory accounting method, and why?","k":["It depends on the CFO's priorities.","FIFO (First-In, First-Out)","Shows higher Net Income (older, cheaper inventory expensed first).","Results in higher taxes paid.","Balance Sheet reflects current market value of inventory.","Preferred if goal is to report stronger earnings to investors.","LIFO (Last-In, First-Out)","Shows lower Net Income (newer, more expensive inventory expensed first).","Results in lower taxes paid, preserving cash.","Balance Sheet shows outdated inventory values.","Preferred if goal is to minimize tax burden and maximize cash flow.","Most CFOs prefer LIFO during inflation to reduce taxes, though IFRS prohibits LIFO."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","Accounting","Basic"]},{"id":"q-0502","t":"acct","l":"Basic","s":90,"q":"If Depreciation and Amortization (D&A) is included within the SG&A line item, how would you calculate the implied D&A given other financial metrics like EBITDA and EBIT?","k":["Answer: D&A = EBITDA - EBIT","Since EBITDA represents earnings before interest, taxes, depreciation, and amortization, while EBIT represents earnings before interest and taxes, the difference between the two is precisely the D&A amount."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","First round","Accounting","Basic"]},{"id":"q-0503","t":"acct","l":"Basic","s":90,"q":"Can book value be negative?","k":["Yes. Book value (shareholders' equity) can be negative. This occurs when accumulated losses (negative retained earnings) exceed the contributed capital and other equity components.","Common reasons:","Years of accumulated net losses eroding retained earnings.","Large share buybacks financed with debt (e.g., McDonald's, Starbucks).","Significant goodwill impairments or write-downs.","Large dividend payments exceeding earnings over time.","A negative book value does not necessarily mean the company is in distress. Many profitable companies with strong cash flows have negative book value due to aggressive buyback programs."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Moelis & Co. Interview","SA 2025, Cleantech group","Accounting","Basic"]},{"id":"q-0504","t":"acct","l":"Basic","s":90,"q":"You have the balance sheets for Year 1 and Year 2 plus the cash-flow statement.\n\n\n\n\nHow would you calculate depreciation for Year 2?","k":["Using CapEx from the CFS and PP&E from the balance sheet (assuming no asset sales or other PP&E adjustments):","CapEx = Year 2 PP&E – Year 1 PP&E + Depreciation","Depreciation = CapEx – Year 2 PP&E + Year 1 PP&E"],"collection":"practice","topic":"Accounting","tags":["Reported in Morgan Stanley Interview","Accounting","Basic"]},{"id":"q-0505","t":"acct","l":"Basic","s":90,"q":"How does a negative change in Net Working Capital affect a company's cash flow?","k":["A negative change in NWC (decrease in NWC) increases cash flow.","Explanation:","NWC = Current Assets (excl. Cash) - Current Liabilities (excl. Debt).","Decrease in NWC means: accounts receivable collected faster, inventory reduced, or payables increased.","All these actions free up cash for the company.","In the Cash Flow Statement, a negative change in NWC is added back to operating cash flow."],"collection":"practice","topic":"Accounting","tags":["Reported in Morgan Stanley Interview","Generalist First round","Accounting","Basic"]},{"id":"q-0506","t":"acct","l":"Basic","s":90,"q":"If a business sells a coffee for $10 that costs $3 to make, walk me through the impact on the income statement and the cash flow statement.\n\n\n\n\nAssume a 25% tax rate.","k":["Income Statement","Revenue increases by $10.","COGS increases by $3.","Pre-tax income up by $7.","Assuming a 25% tax rate, net income up by $5.25.","Cash Flow Statement","CFO starts with NI of +$5.25.","Inventory decreases by $3 (a source of cash), so CFO is +$8.25.","If inventory is immediately replenished, the inventory change nets to zero and CFO simply equals NI of $5.25."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Morgan Stanley Interview","SA 2027","Accounting","Basic"]},{"id":"q-0507","t":"acct","l":"Basic","s":90,"q":"Why would EBIT and Net Income be the same for a company?","k":["EBIT and Net Income would be the same if the company has zero interest expense, zero interest income, and a 0% effective tax rate.","This could occur if the company:","Has no debt (so no interest expense) and no cash investments (so no interest income)","Has a 0% tax rate, perhaps due to Net Operating Loss (NOL) carryforwards fully offsetting taxable income, or operates in a tax-free jurisdiction","Since Net Income = EBIT - Interest Expense + Interest Income - Taxes, if all three components below EBIT are zero, EBIT equals Net Income."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Morgan Stanley Interview","SA 2027, TMT group, Menlo Park Office, First round","Accounting","Basic"]},{"id":"q-0508","t":"acct","l":"Basic","s":90,"q":"Is net working capital typically positive or negative for SaaS companies, and why?","k":["Net working capital is typically negative for SaaS companies.","SaaS companies often collect annual or multi-year subscription payments upfront from customers, creating large Deferred Revenue balances (a current liability). Meanwhile, they tend to have low Accounts Receivable (since customers prepay) and minimal inventory.","Since NWC = Current Assets - Current Liabilities, the large Deferred Revenue liability often exceeds current assets, resulting in negative NWC. This is actually favorable because it means the company is effectively funded by its customers."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Morgan Stanley Interview","SA 2027, TMT group, Menlo Park Office, First round","Accounting","Basic"]},{"id":"q-0509","t":"acct","l":"Basic","s":90,"q":"How does an increase in accounts payable affect unlevered free cash flow?","k":["It raises it dollar‑for‑dollar.","Higher AP is a source of cash, lowering ΔNWC in the FCF formula and boosting unlevered FCF."],"collection":"practice","topic":"Accounting","tags":["Reported in Perella Weinberg Interview","First round","Accounting","Basic"]},{"id":"q-0510","t":"acct","l":"Basic","s":90,"q":"A company sells $100 of goods on account, which cost $50, at a 20% tax rate.\n\n\n\n\nWalk me through the three statements.","k":["Income Statement:","Revenue +100","COGS –50","Pretax +50","Taxes –10","NI +40","Cash Flow Statement:","NI +40","ΔAR –100 (use of cash)","ΔInventory +50 (source of cash)","CFO –10 → Cash –10","Balance Sheet:","AR +100","Inventory –50","Cash –10","Retained Earnings +40","Total Assets +40 equals Equity +40—balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Perella Weinberg Interview","Superday","Accounting","Basic"]},{"id":"q-0511","t":"acct","l":"Basic","s":90,"q":"An ice cream shop has revenues of $100 in Year 1 and grows to $500 in Year 2.\n\n\n\n\nHow would you expect its Gross Margin and Operating Margin to change between Year 1 and Year 2?\n\n\n\n\nWithin SG&A, which specific expense line item would you expect to increase the most to support this growth?","k":["Both Gross Margin and Operating Margin would likely improve.","Margin improvements driven by:","Economies of scale in production and purchasing.","Better fixed cost absorption over higher revenue base.","Improved operational efficiency.","Within SG&A, Sales & Marketing would likely increase the most to drive 5x revenue growth, including advertising, promotions, and headcount for new locations."],"collection":"practice","topic":"Accounting","tags":["Reported in Perella Weinberg Interview","New York Office, Second round","Accounting","Basic"]},{"id":"q-0512","t":"acct","l":"Basic","s":90,"q":"Walk me through the 3-statement impact of $25M in credit sales. Assume a 40% tax rate.","k":["Starting on the IS...","Revenue up 25","Pre-tax income up 25 (assuming no incremental COGS for simplicity)","NI up 15","Moving onto the SCF...","NI +15","Accounts Receivable increases by 25 (cash not yet collected), which is a use of cash in working capital","Net change in cash is -10","Finally, on the BS...","A: Cash -10, Accounts Receivable +25, net +15","L: No change","SE: +15 from retained earnings","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Perella Weinberg Interview","SA 2026, First round","Accounting","Basic"]},{"id":"q-0513","t":"acct","l":"Basic","s":90,"q":"Walk me through the 3-statement impact of $100M in debt issuance in Year 0 and Year 1. Assume a 5% interest rate and a 40% tax rate.","k":["Year 0","Starting on the IS...","No change","Moving onto the SCF...","CFF +100 from debt issuance","Net change in cash is +100","Finally, on the BS...","A: Cash +100","L: Debt +100","SE: No change","...and the Balance Sheet balances","Year 1","Starting on the IS...","Interest expense +5 ($100 x 5%)","Pre-tax income down 5","NI down 3","Moving onto the SCF...","NI -3","Net change in cash is -3","Finally, on the BS...","A: Cash -3","L: No change (debt still outstanding)","SE: -3 from retained earnings","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Perella Weinberg Interview","SA 2026, First round","Accounting","Basic"]},{"id":"q-0514","t":"acct","l":"Basic","s":90,"q":"You have 100 in revenue, 30% in EBITDA margin, $10 in D&A, and a tax rate of 25%.\n\n\n\n\nWhat is net income?","k":["Net income = $15.","EBITDA = $30","EBIT = $30 – $10 = $20","Taxes = 25 % × $20 = $5","NI = $20 – $5 = $15"],"collection":"practice","topic":"Accounting","tags":["Reported in PJT Partners Interview","SA 2025, off-cycle, London office","Accounting","Basic"]},{"id":"q-0515","t":"acct","l":"Basic","s":90,"q":"Walk me through the 3-statement impact of a company purchasing $50 million of equipment using cash on hand.","k":["Starting on the IS...","No immediate impact (asset purchase is not an expense).","Moving onto the SCF...","CFI -$50M for equipment purchase.","Net change in cash is -$50M.","Finally, on the BS...","A: Cash -$50M, PP&E +$50M. Net Assets unchanged.","L: No change.","SE: No change.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in PJT Partners Interview","New York Office","Accounting","Basic"]},{"id":"q-0516","t":"acct","l":"Basic","s":90,"q":"A company issues $50M in debt and immediately uses the proceeds to pay a special dividend of the same amount.\n\n\n\n\nAssuming a 25% tax rate, walk me through the 3 statements.","k":["Starting on the IS...","No change.","Moving onto the SCF...","CFF +$50M from debt issuance.","CFF -$50M for dividend payment.","Net change in cash is $0.","Finally, on the BS...","Assets: No change (cash in and out).","Liabilities: Debt +$50M.","SE: Retained Earnings -$50M.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in PJT Partners Interview","First round","Accounting","Basic"]},{"id":"q-0517","t":"acct","l":"Basic","s":90,"q":"A company makes a sale that generates $4 in gross profit. Assuming revenue of $10 and COGS of $6, and a 25% tax rate, walk me through the three financial statements.","k":["Starting on the IS...","Revenue +$10","COGS -$6","Gross Profit +$4","Assuming no other expenses, Pre-tax income +$4","Tax = $4 * 25% = $1","Net Income +$3","Moving onto the SCF...","Net Income +$3","Add Decrease in Inventory +$6 (Source of cash)","Net change in cash is +$9","Finally, on the BS...","Assets: Cash +$9, Inventory -$6. Net Assets +$3.","Liabilities: No change","SE: Retained Earnings +$3","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in PJT Partners Interview","First round","Accounting","Basic"]},{"id":"q-0518","t":"acct","l":"Basic","s":90,"q":"A company sells an asset at a 20% loss. The book value of the asset is $100. The tax rate is 10%. Walk me through the impact on the three financial statements.","k":["Sale price = $100 x (1 - 20%) = $80. Loss on sale = $20. Tax rate = 10%.","Starting on the IS...","Loss on sale of 20","Pre-tax income down 20","Taxes down 2","NI down 18","Moving onto the SCF...","NI down 18","Add back loss on sale of 20 in CFO (non-cash reclassification)","Add 80 in CFI from sale proceeds","Net change in cash is up 82","Finally, on the BS...","A: Cash up 82, Asset down 100, net down 18","L: No change","SE: Down 18 from Retained Earnings","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in PJT Partners Interview","SA 2025, Houston Office, First round","Accounting","Basic"]},{"id":"q-0519","t":"acct","l":"Basic","s":90,"q":"How can a company have negative net income but positive unlevered free cash flow?","k":["This occurs when large non-cash charges or below-the-line items depress net income, but operating cash generation remains strong.","High D&A: A capital-intensive company with large depreciation charges may show negative net income, but since D&A is non-cash, UFCF adds it back.","High interest expense: Interest reduces NI but is excluded from UFCF (which is pre-debt service). A highly levered company can have negative NI but positive UFCF.","Large impairment or write-down: One-time non-cash charges like goodwill impairment crush NI but do not affect cash flow.","Stock-based compensation: SBC reduces NI but is a non-cash expense added back in cash flow calculations.","Working capital improvements: Favorable NWC changes (collecting receivables faster, extending payables) boost operating cash flow even if NI is negative."],"collection":"practice","topic":"Accounting","tags":["New","Reported in RBC Interview","SA 2025, SF Office, First round","Accounting","Basic"]},{"id":"q-0520","t":"acct","l":"Basic","s":90,"q":"Looking at a company's Income Statement: Which affects Net Income most?\n\n\n\n10% increase in Price\n10% increase in Volume\n10% reduction in COGS\n\n\n\nFollow-up: Could there be a situation where COGS has a larger impact than price?","k":["The 10% price increase usually has the biggest impact.","Price rises boost revenue dollar‑for‑dollar with no extra cost, so the entire uplift flows to Net Income.","Volume increases add variable costs, diluting the benefit.","COGS cuts save only the cost line.","If gross margins are extremely thin or demand is highly price‑elastic, a COGS cut could outweigh a price hike."],"collection":"practice","topic":"Accounting","tags":["Reported in Rothschild Interview","SA 2026","Accounting","Basic"]},{"id":"q-0521","t":"acct","l":"Basic","s":90,"q":"Explain FIFO versus LIFO inventory accounting. What are the effects of each on the three financial statements, and which method would you prefer?","k":["Definitions","FIFO (First In, First Out): The oldest inventory is sold first. COGS reflects older (usually lower) costs.","LIFO (Last In, First Out): The newest inventory is sold first. COGS reflects newer (usually higher) costs.","Impact in a Rising Price Environment","IS: LIFO has higher COGS, lower pre-tax income, and lower NI. FIFO has lower COGS, higher pre-tax income, and higher NI.","SCF: LIFO has lower NI but lower taxes paid, resulting in higher cash flow. FIFO has higher NI but higher taxes.","BS: FIFO shows higher inventory on the BS (closer to current replacement cost). LIFO shows lower, older inventory values. FIFO has higher retained earnings; LIFO has lower.","Preference","LIFO is generally preferable in a rising price environment because it minimizes taxes paid, maximizing cash flow. However, FIFO provides a more accurate balance sheet representation of inventory value. Most international companies use FIFO (LIFO is not permitted under IFRS). In an interview, note the tax benefit of LIFO while acknowledging FIFO provides better balance sheet accuracy."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Rothschild Interview","SA 2027, First round","Accounting","Basic"]},{"id":"q-0522","t":"acct","l":"Basic","s":90,"q":"Would you rather use FIFO or LIFO, if costs in the current market are increasing?","k":["LIFO is preferable in a rising cost environment because it reduces taxable income and maximizes cash flow.","Why LIFO Wins on Cash Flow","Under LIFO, the most recently purchased (higher-cost) inventory hits COGS first. Higher COGS means lower pre-tax income and lower taxes paid.","Under FIFO, the oldest (lower-cost) inventory hits COGS first. Lower COGS means higher reported net income — but also a higher tax bill.","Trade-Off","FIFO produces a more accurate balance sheet (inventory is carried at near-current costs) and higher reported earnings, which can matter for covenants or investor optics.","LIFO produces a stale, understated inventory balance on the BS but preserves real cash by deferring taxes.","Bottom line: cash is king. LIFO keeps more cash in the business. Note that LIFO is only permitted under US GAAP — IFRS requires FIFO or weighted average cost."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Rothschild Interview","SA 2027, Global Advisory group, New York Office, First round","Accounting","Basic"]},{"id":"q-0523","t":"acct","l":"Basic","s":90,"q":"What is the difference between straight-line depreciation and accelerated depreciation? Why would you want to use accelerated depreciation on your financial statements?","k":["Straight-Line Depreciation","Allocates the cost of an asset evenly over its useful life. Formula: (Cost - Salvage Value) / Useful Life. Example: a $100K asset with a 10-year life and zero salvage = $10K/year in depreciation expense every year.","Accelerated Depreciation","Front-loads depreciation expense into the earlier years of an asset's life. Common methods include Double Declining Balance (2x the straight-line rate applied to the declining book value) and MACRS (used for US tax purposes). The same total depreciation is recognized over the asset's life — it is just shifted earlier.","Why Use Accelerated Depreciation?","Tax deferral: Higher depreciation in early years reduces taxable income, lowering taxes paid now. This creates a tax shield that increases near-term free cash flow.","Time value of money: A dollar of tax savings today is worth more than a dollar of tax savings in year 10. Accelerated depreciation shifts the tax benefit forward.","On the flip side, reported net income is lower in early years, which can affect earnings-based metrics and covenants.","In practice, many companies use straight-line for GAAP/book reporting (smoother earnings) and accelerated depreciation for tax reporting (maximize cash flow). This creates a deferred tax liability on the balance sheet."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Rothschild Interview","SA 2027, Global Advisory group, New York Office, First round","Accounting","Basic"]},{"id":"q-0524","t":"acct","l":"Basic","s":90,"q":"A company earns $10 in cash revenue with a 50% gross margin. Assuming a 20% tax rate, walk me through the three financial statements. Assume no other expenses and that COGS is paid in cash.","k":["Starting on the IS...","Revenue +10","COGS -5 (50% gross margin)","Gross Profit +5","Pre-tax income +5 (assuming no other expenses)","Taxes -1 (20% x 5)","NI +4","Moving onto the SCF...","NI +4","No non-cash adjustments or working capital changes (cash revenue, cash COGS)","Net change in cash is +4","Finally, on the BS...","A: Cash +4","L: No change","SE: +4 from Retained Earnings (NI)","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Solomon Partners Interview","SA 2027, Generalist group, New York Office, Second round","Accounting","Basic"]},{"id":"q-0525","t":"acct","l":"Basic","s":90,"q":"How can a company generate cash from its working capital? Please provide specific examples.","k":["Companies generate cash from working capital by:","Collecting receivables faster: Offer early payment discounts, improve collections processes, or factor receivables.","Reducing inventory: Implement just-in-time systems, improve demand forecasting, or liquidate slow-moving stock.","Extending payables: Negotiate longer payment terms with suppliers without damaging relationships.","Example: A retailer collects from customers in 10 days but pays suppliers in 60 days, generating a 50-day cash benefit used to fund operations without external financing."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Basic"]},{"id":"q-0526","t":"acct","l":"Basic","s":90,"q":"A company starts the year with a PP&E balance of $600.\n\n\n\n\nDuring the year, it records $500 in Capital Expenditures.\n\n\n\n\nAt the end of the year, its PP&E balance is $800.\n\n\n\n\nWhat could explain this change?","k":["Depreciation of $300 during the year.","Reconciliation:","Beginning PP&E: $600","Add: CapEx: +$500","Less: Depreciation: -$300","Ending PP&E: $800","Other possibilities (less common):","Asset sales or disposals reducing gross PP&E.","Impairment charges.","Foreign currency translation adjustments."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Basic"]},{"id":"q-0527","t":"acct","l":"Basic","s":90,"q":"Construct an Income Statement down to Net Income using the following information:\n\n\n\nRevenue: $100\nGross Margin: 80%\nDepreciable Assets (PP&E): $50\nDepreciation Rate: 10% (straight-line)\nTotal Debt: $100\nInterest Rate: 15%\nTax Rate: 20%","k":["Income Statement:","Revenue: $100","COGS: $20 (Revenue * (1 - 80%))","Gross Profit: $80","Depreciation: $5 ($50 * 10%)","EBIT: $75 ($80 - $5)","Interest Expense: $15 ($100 * 15%)","Pre-tax Income: $60 ($75 - $15)","Tax: $12 ($60 * 20%)","Net Income: $48"],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Basic"]},{"id":"q-0528","t":"acct","l":"Basic","s":90,"q":"Walk me through the 3 financial statements at the time a company buys a $200 machine using $100 of debt and $100 of cash.","k":["Starting on the IS...","No impact (asset purchase is not an expense).","Moving onto the SCF...","CFI -$200 (machine purchase).","CFF +$100 (debt proceeds).","Net change in cash is -$100.","Finally, on the BS...","A: PP&E +$200, Cash -$100. Net Assets +$100.","L: Debt +$100.","SE: No change.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Basic"]},{"id":"q-0529","t":"acct","l":"Basic","s":90,"q":"Please walk me through the Income Statement of the last company you worked for or studied.","k":["This is a personal experience question requiring preparation of a specific company you've analyzed.","Structure your answer as follows:","Revenue: Sources and growth drivers.","COGS: Major cost components and margins.","Gross Profit: Trends and margin analysis.","Operating Expenses: SG&A, R&D breakdown.","EBITDA: Key profitability metric.","D&A: Depreciation and amortization.","Interest Expense: Debt service costs.","Taxes: Effective tax rate.","Net Income: Bottom line performance.","Include specific numbers and explain any notable trends or one-time items."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Basic"]},{"id":"q-0530","t":"acct","l":"Basic","s":90,"q":"Assuming a 25% tax rate, walk me through the 3-statement impact of a company selling an asset. The asset had a book value of $500 and was sold for $400 in cash, resulting in a $100 loss.","k":["Starting on the IS...","Pre-tax loss on sale = $100.","Tax benefit = $25 ($100 * 25%).","Net Income decreases by $75.","Moving onto the SCF...","Net Income -$75.","Add back $100 loss on sale (non-cash/non-operating).","CFI: Cash from sale of asset = +$400.","Net change in cash = -$75 + $100 + $400 = +$425.","Finally, on the BS...","A: Cash +$425; Asset -$500 (removed at book value).","L: No change.","SE: Retained Earnings -$75.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Superday","Accounting","Basic"]},{"id":"q-0531","t":"acct","l":"Basic","s":90,"q":"Assuming a 25% tax rate, walk me through what happens to the 3 financial statements following an inventory write-down of $5 million.","k":["Starting on the IS...","COGS increases by $5M (or inventory write-down expense).","Pre-tax income down $5M.","Tax benefit = $1.25M ($5M * 25%).","Net Income down $3.75M.","Moving onto the SCF...","Net Income -$3.75M.","Add back $5M inventory write-down (non-cash charge).","Net change in cash +$1.25M.","Finally, on the BS...","A: Cash +$1.25M, Inventory -$5M. Net Assets -$3.75M.","L: No change.","SE: Retained Earnings -$3.75M.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Superday","Accounting","Basic"]},{"id":"q-0532","t":"acct","l":"Basic","s":90,"q":"How would the income statement of an auto manufacturer differ from that of a software company? Assume the companies are of a similar size and growth stage.","k":["Auto Manufacturer","High COGS (materials, labor, manufacturing) resulting in lower gross margins (typically 15-25%).","Significant D&A from plants and equipment.","Higher working capital needs (inventory, receivables).","Cyclical revenue patterns.","Software Company","Low COGS (primarily hosting, support) resulting in high gross margins (typically 70-90%).","Lower D&A; more amortization of intangibles.","Higher R&D and S&M expenses as % of revenue.","Deferred revenue liability common (subscription model).","More predictable, recurring revenue."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Superday","Accounting","Basic"]},{"id":"q-0533","t":"acct","l":"Basic","s":90,"q":"A company raises $200 of debt with a 10% interest rate.\n\n\n\n\nWalk me through the 3 statements for the first year, assuming a 20% tax rate.","k":["Starting on the IS...","Interest expense = $20 ($200 * 10%).","Pre-tax income -$20.","Tax benefit = $4 ($20 * 20%).","Net Income -$16.","Moving onto the SCF...","Net Income -$16.","CFF +$200 (debt issuance).","Net change in cash +$184.","Finally, on the BS...","A: Cash +$184.","L: Debt +$200.","SE: Retained Earnings -$16.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Superday","Accounting","Basic"]},{"id":"q-0534","t":"acct","l":"Basic","s":90,"q":"How does Goodwill impairment impact Net Income?","k":["Goodwill impairment is a non-cash charge that reduces Net Income dollar-for-dollar (after tax effects).","When goodwill is written down, the impairment charge flows through the income statement as an expense, reducing pre-tax income. This results in a lower tax expense and ultimately lower net income.","On the cash flow statement, the impairment is added back to net income in the CFO section since it's non-cash, resulting in no impact on actual cash flow."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Superday","Accounting","Basic"]},{"id":"q-0535","t":"acct","l":"Basic","s":90,"q":"What happens when a company buys an asset for $100 but the market value of the asset is $150?","k":["Under U.S. GAAP, assets are recorded at their historical cost (the price actually paid), not market value. So the asset goes on the balance sheet at $100.","The $50 difference between the market value ($150) and purchase price ($100) represents a bargain purchase or unrealized gain. However, it is not recognized on the financial statements at the time of purchase. The asset remains at $100 and is depreciated based on that cost basis. The company effectively received a good deal, but accounting conservatism prevents marking it up to fair value.","Exception: In a business acquisition (not a single asset purchase), if the purchase price is below the fair value of net identifiable assets, the difference is recorded as a \"bargain purchase gain\" on the income statement under ASC 805."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Unspecified Interview","SA 2027, Superday","Accounting","Basic"]},{"id":"q-0536","t":"acct","l":"Basic","s":90,"q":"You purchase $50 of inventory using cash on hand.\n\n\n\n\nHow do the three financial statements change?","k":["Starting on the IS...","No impact on the income statement (expensed only when sold)","Moving onto the SCF...","CFO: -$50 for the inventory purchase","Net change in cash: -$50","Finally, on the BS...","A: Inventory +$50, Cash -$50","L: No change","SE: No change","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Wells Fargo Interview","Accounting","Basic"]},{"id":"q-0537","t":"acct","l":"Basic","s":90,"q":"Define working capital and list its core components.\n\n\n\n\nQualitatively, what would Walmart’s working-capital profile look like?","k":["Working Capital measures a company's short-term liquidity and ability to meet near-term obligations.","Working Capital = Current Assets - Current Liabilities (often focusing on operating items).","Core components generally include: Cash and equivalents, accounts receivable, inventory, accounts payable, and accrued expenses.","Walmart: Likely negative working capital: quick customer payments, slower payables, high inventory turnover."],"collection":"practice","topic":"Accounting","tags":["Reported in Wells Fargo Interview","Accounting","Basic"]},{"id":"q-0538","t":"acct","l":"Basic","s":90,"q":"Describe the difference between financial accounting and managerial accounting. Which are you more familiar with?","k":["Financial Accounting","External reporting for investors, creditors, regulators.","Follows GAAP/IFRS standards.","Historical, backward-looking.","Mandatory and audited (for public companies).","Examples: Income Statement, Balance Sheet, Cash Flow Statement.","Managerial Accounting","Internal reporting for management decision-making.","No required standards; flexible format.","Forward-looking; includes budgets and forecasts.","Not audited or publicly disclosed.","Examples: Cost analysis, variance reports, departmental budgets.","In investment banking, financial accounting is more relevant as it forms the basis for valuation, due diligence, and transaction analysis."],"collection":"practice","topic":"Accounting","tags":["Reported in Wells Fargo Interview","Superday","Accounting","Basic"]},{"id":"q-0539","t":"acct","l":"Advanced","s":90,"q":"You buy $100 in PPE using all debt with a 10% interest rate, assume 10% depreciation and 25% tax. Walk through the three financial statements in Year 0 and Year 1.","k":["Year 0","Starting on the IS...","No change","Moving onto the SCF...","CFI: -$100 for the PP&E purchase","CFF: +$100 from debt","Net change in cash: $0","Finally, on the BS...","A: PP&E +$100","L: Debt +$100","SE: No change","...and the Balance Sheet balances","Year 1","Starting on the IS...","Depreciation: -$10 (10% on $100 PP&E)","Interest Expense (10% on $100 debt): -$10","Pre-tax Income: -$20","Taxes (25%): +$5 (tax shield)","Net Income: -$15","Moving onto the SCF...","CFO: Net Income -$15 + Depreciation +$10 = -$5","Net change in cash: -$5","Finally, on the BS...","A: Cash -$5, PP&E -$10 (from depreciation), net -$15 in total assets","L: No change in debt","SE: Retained Earnings -$15","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Ares Management Interview","Accounting","Advanced"]},{"id":"q-0540","t":"acct","l":"Advanced","s":90,"q":"Salesforce sells a $100 contract upfront for a 1-year service.\n\n\n\n\nWalk through the three statements at signing, and again six months later assuming no expense other than taxes.\n\n\n\n\nAssume a tax rate of 25%.","k":["At Signing","Starting on the IS...","No revenue is recognized yet as the service has not been delivered.","No change to Net Income.","Moving onto the SCF...","Cash is up by $100 in CFO from the customer payment.","Net change in cash is up $100.","Finally, on the BS...","A: Assets up by $100 (Cash up $100).","L: Liabilities up by $100 (Deferred Revenue up $100).","SE: No change in Shareholder’s Equity.","...and the Balance Sheet balances.","Six Months Later","Assuming the $100 service is delivered evenly over one year, after six months, $50 of service has been delivered and can be recognized as revenue.","Starting on the IS...","Revenue up by $50.","Pre-tax income up by $50 (assuming no other expenses).","Taxes (at 25%) are $12.5 ($50 * 0.25).","Net Income up by $37.5 ($50 - $12.5).","Moving onto the SCF...","Net Income up by $37.5.","Subtract $50 decrease in Deferred Revenue from CFO (non-cash).","Net change in cash is down $12.5 ($37.5 - $50).","Finally, on the BS...","A: Assets down by $12.5 (Cash down $12.5).","L: Liabilities down by $50 (Deferred Revenue down $50).","SE: Shareholder’s Equity up by $37.5 (Retained Earnings up $37.5 due to Net Income).","...and the Balance Sheet balances (Assets -$12.5 = Liabilities -$50 + Equity +$37.5)."],"collection":"practice","topic":"Accounting","tags":["Reported in Bank of America Interview","Accounting","Advanced"]},{"id":"q-0541","t":"acct","l":"Advanced","s":90,"q":"MULTI-STEP: A company buys PP&E in Year 1 for $800. The asset has a 20-year useful life, uses straight-line depreciation, and has no salvage value.\n\n\n\n\nAt the end of Year 4, the company sells the PP&E for $700.\n\n\n\n\nAssuming a 20% tax rate, walk me through the 3 financial statements at the time of sale in Year 4.","k":["Annual depreciation = $800 / 20 = $40. Four years taken, so accumulated depreciation = $160 and net book value at sale = $640. Year 4 is a full operating year, so that year's depreciation runs through alongside the sale.","Starting on the IS (full Year 4)...","Depreciation expense -$40.","Gain on sale = $700 - $640 = +$60.","Pre-tax income +$20.","Net Income +$16 ($20 × (1 - 20%)).","Moving onto the SCF...","Net Income +$16.","Add back $40 depreciation (non-cash).","Subtract the $60 gain (proceeds show up in CFI).","CFO = -$4, the cash taxes paid on the gain.","CFI +$700 of sale proceeds.","Net change in cash +$696.","Finally, on the BS...","A: Cash +$696; PP&E -$680 (-$40 depreciation, -$640 written off at disposal). Net Assets +$16.","L: No change.","SE: Retained Earnings +$16.","...and the Balance Sheet balances.","For the incremental impact of the sale alone, strip the depreciation: pre-tax +$60, NI +$48, CFO -$12, CFI +$700, cash +$688, PP&E -$640."],"collection":"practice","topic":"Accounting","tags":["Reported in Bank of America Interview","M&A, Power, First round","Accounting","Advanced"]},{"id":"q-0542","t":"acct","l":"Advanced","s":90,"q":"A company purchased PP&E for $100M with a 5-year useful life (straight-line depreciation). After 2 years, it sells the PP&E for $80M. Walk me through the impact on the three financial statements. Assume a 25% tax rate.","k":["Depreciation = $100M / 5 = $20M/yr. After 2 years: Book Value = $100M - (2 x $20M) = $60M. Sale at $80M = gain of $20M.","Starting on the IS...","Gain on sale of $20M","Pre-tax income up $20M","NI up $15M","Moving onto the SCF...","NI +15M","Subtract gain of 20M in CFO (non-cash reclassification)","Add 80M in CFI from sale proceeds","Net change in cash is up 75M","Finally, on the BS...","A: Cash +75M, PP&E -60M (remove net book value), net +15M","L: No change","SE: Retained Earnings +15M","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Bank of America Interview","SA 2026, New York Office, Superday","Accounting","Advanced"]},{"id":"q-0543","t":"acct","l":"Advanced","s":90,"q":"You have PP&E on the books for $100 but sell it for $80. Assuming a 25% tax rate, walk me through the three financial statements.","k":["Starting on the IS...","Loss on sale of $20 (sold for $80, book value was $100)","Pre-tax income down by $20","NI down by $15","Moving onto the SCF...","NI -15","Add back $20 loss on sale in CFO (reclassify to investing)","+80 in CFI from sale proceeds","Net change in cash is +85","Finally, on the BS...","A: Cash +85, PP&E -100, net -15","L: No change","SE: -15 from NI","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Bank of America Interview","LA Office, Superday","Accounting","Advanced"]},{"id":"q-0544","t":"acct","l":"Advanced","s":90,"q":"A company has PP&E with a book value of $100 and sells it for $150. Assume a 20% tax rate. Walk me through the 3-statement impact.","k":["Starting on the IS...","Gain on sale = $150 - $100 book value = $50","Pre-tax income up $50","Taxes = $50 x 20% = $10","NI up $40","Moving onto the SCF...","NI +40","Subtract the $50 gain in CFO (non-cash reclassification to CFI)","Add $150 sale proceeds in CFI","Net change in cash is up $140","Finally, on the BS...","A: Cash +140, PP&E -100, net assets up $40","L: No change","SE: Retained Earnings +40 from NI","...and the Balance Sheet balances (+40 = 0 + 40)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Bank of America Interview","SA 2026, First round","Accounting","Advanced"]},{"id":"q-0545","t":"acct","l":"Advanced","s":90,"q":"You are the CEO of a company that normally capitalizes R&D expenditures. Your new CFO wants to expense R&D instead. How will switching from capitalizing to expensing R&D impact the three financial statements?","k":["Starting on the IS...","R&D expense hits the IS immediately (previously capitalized and amortized over time)","Current-period pre-tax income decreases by the full R&D spend (but you lose the amortization of previously capitalized R&D, which partially offsets)","Net effect: NI decreases in the current period","Moving onto the SCF...","NI is lower, but the R&D CapEx line in CFI disappears (no longer capitalizing)","The expense is now in CFO rather than CFI","Total cash flow is unchanged -- it is a reclassification between CFO and CFI","Finally, on the BS...","A: Capitalized R&D asset no longer created (or existing asset is amortized down without new additions). Net assets decrease over time.","L: No change","SE: Lower due to reduced NI in retained earnings","...and the Balance Sheet balances","Key insight: Total cash impact is the same -- it is an accounting presentation change. But it reduces reported earnings and makes the company look less profitable in the near term."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Bank of America Interview","SA 2025, Superday","Accounting","Advanced"]},{"id":"q-0546","t":"acct","l":"Advanced","s":90,"q":"Given a set of financial statements, identify when a dividend was paid and calculate the dividend amount.","k":["To identify a dividend payment and calculate the amount:","Check the Cash Flow Statement: Look in the Financing Activities (CFF) section for a line item labeled \"Dividends Paid\" or \"Distributions to Shareholders.\" This directly tells you the cash outflow.","Check the Balance Sheet: Compare Retained Earnings from one period to the next. Retained Earnings should increase by Net Income and decrease by dividends: Ending RE = Beginning RE + Net Income - Dividends.","Dividend = Beginning RE + Net Income - Ending RE.","If Retained Earnings decreased by more than Net Income would explain, the difference is the dividend paid."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Barclays Interview","SA 2026, FIG group, New York Office, Superday","Accounting","Advanced"]},{"id":"q-0547","t":"acct","l":"Advanced","s":90,"q":"Part 1: A company purchases $100 of PP&E financed entirely with debt. Walk me through the impact on the three financial statements at Year 0.\n\n\n\n\nPart 2: Walk me through the impact at the end of Year 1. Assume a 10% interest rate on the debt, a 10-year straight-line depreciation schedule, and a 25% tax rate.\n\n\n\n\nPart 3: The asset is sold in Year 2. Walk me through the three financial statement impact if it is sold at book value, above book value, and below book value.","k":["Part 1: Year 0","Starting on the IS...","No change","Moving onto the SCF...","CFI -100 for PP&E purchase","CFF +100 from debt issuance","Net change in cash is 0","Finally, on the BS...","A: PP&E +100","L: Debt +100","SE: No change","...and the Balance Sheet balances","Part 2: End of Year 1","Starting on the IS...","Depreciation expense of 10 (100/10 years)","Interest expense of 10 (100 x 10%)","Pre-tax income down 20","NI down 15 (20 x 75%)","Moving onto the SCF...","NI -15","Add back depreciation +10","Net change in cash is -5","Finally, on the BS...","A: Cash -5, PP&E -10, net -15","L: Debt +100 (still outstanding, no change from Year 0 balance)","SE: -15 from NI","...and the Balance Sheet balances (cumulative from Year 0: A = +85, L = +100, SE = -15; 85 = 100 + (-15))","Part 3: Asset Sold in Year 2","Book value of the asset at the end of Year 2 = $100 - 2 x $10 depreciation = $80. The answer depends on whether the sale price is above, below, or at book value.","Scenario A: Sold at Book Value ($80) - No Gain or Loss","IS: Depreciation expense of 10 (Year 2). Interest expense of 10. No gain or loss on sale. Pre-tax income down 20, NI down 15.","SCF: NI -15. Add back depreciation +10 (non-cash). CFI +80 from asset sale. Net change in cash +75.","BS: A: Cash +75, PP&E -90 (depreciation -10 and sold at BV -80), net assets -15. L: No change. SE: -15 from NI. The balance sheet balances (-15 = 0 + -15).","Scenario B: Sold Above Book Value (e.g., $100) - Gain of $20","IS: Depreciation expense of 10. Gain on sale of $20. Interest expense of 10. Pre-tax income: -10 - 10 + 20 = 0, NI = 0.","SCF: NI 0. Add back depreciation +10. Subtract gain on sale -20 (non-cash, reclassified to CFI). CFI +100 from sale proceeds. Net change in cash +90.","BS: A: Cash +90, PP&E -90, net assets unchanged. L: No change. SE: Unchanged (NI = 0). The balance sheet balances (0 = 0 + 0).","Scenario C: Sold Below Book Value (e.g., $60) - Loss of $20","IS: Depreciation expense of 10. Loss on sale of $20. Interest expense of 10. Pre-tax income down 40, NI down 30.","SCF: NI -30. Add back depreciation +10 (non-cash). Add back loss on sale +20 (non-cash). CFI +60 from sale proceeds. Net change in cash +60.","BS: A: Cash +60, PP&E -90, net assets -30. L: No change. SE: -30 from NI. The balance sheet balances (-30 = 0 + -30)."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Barclays Interview","SA 2026, New York Office, Superday","Accounting","Advanced"]},{"id":"q-0548","t":"acct","l":"Advanced","s":90,"q":"Given a balance sheet and income statement, identify the year an acquisition took place. Then calculate the unlevered cash flow by figuring out the capital expenditure spend using the PP&E balance and D&A expense.","k":["Identifying the Acquisition Year:","Look for a sudden jump in goodwill or intangible assets on the BS. A large increase signals an acquisition occurred that year.","Also look for step-ups in total assets, debt (acquisition financing), or non-controlling interests.","Calculating CapEx from PP&E and D&A:","CapEx = Ending PP&E - Beginning PP&E + D&A","This formula works because: Beginning PP&E + CapEx - D&A = Ending PP&E, solved for CapEx.","Be careful to exclude any PP&E acquired through M&A (which would show up as a non-CapEx increase). If an acquisition occurred, back out the acquired PP&E.","Unlevered Free Cash Flow:","UFCF = EBIT x (1 - Tax Rate) + D&A - CapEx - Change in NWC","Use the CapEx figure calculated above."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Barclays Interview","SA 2025","Accounting","Advanced"]},{"id":"q-0549","t":"acct","l":"Advanced","s":90,"q":"How do PIK (Payment-in-Kind) bonds affect the 3 financial statements?","k":["PIK interest is non-cash. On the income statement, you still record interest expense, reducing pre-tax income and net income.","On the cash flow statement, add back the non-cash interest in CFO. The net effect is that Cash increases by the tax shield amount (Net Income decreases by Interest * (1-t), then adding back the full Interest results in a net positive change of Interest * t).","On the balance sheet, debt principal increases by the PIK amount, retained earnings decreases by the after-tax interest, and Cash is up by the tax shield."],"collection":"practice","topic":"Accounting","tags":["Reported in BMO Interview","Accounting","Advanced"]},{"id":"q-0550","t":"acct","l":"Advanced","s":90,"q":"If Company A, a U.S. company, owns a foreign subsidiary in South America, what happens to the financial statements when the South American currency weakens?","k":["When the foreign currency weakens relative to the USD:","Income Statement: The subsidiary's revenue and expenses, when translated to USD, will be lower. This reduces reported consolidated revenue and net income (translation effect).","Balance Sheet: The subsidiary's assets and liabilities, translated at the current (weaker) exchange rate, will be lower in USD terms. This creates a negative foreign currency translation adjustment in Accumulated Other Comprehensive Income (AOCI), a component of Shareholders' Equity.","Cash Flow Statement: Operating, investing, and financing cash flows from the subsidiary translate to fewer USD. The effect appears as a foreign exchange adjustment line item.","The cumulative translation adjustment sits in AOCI (not the IS) until the subsidiary is sold, at which point it is reclassified into earnings. This is a non-cash accounting adjustment -- the subsidiary's local-currency performance may be unchanged."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Centerview Partners Interview","New York Office, First round","Accounting","Advanced"]},{"id":"q-0551","t":"acct","l":"Advanced","s":90,"q":"A company is interested in investing in factories and buildings for its operations. Should it use operating or capital leases?","k":["A company should use a capital lease for factories and buildings.","Factories and buildings are long-term assets, so a capital lease transfers ownership rights or most of the economic benefits to the lessee.","Under a capital lease, the leased asset and corresponding liability appear on the balance sheet.","Lease expenses are split into depreciation (for the asset) and interest (on the liability), rather than recorded as operating rent.","An operating lease suits short-term rentals without ownership transfer and records lease payments entirely as operating expense."],"collection":"practice","topic":"Accounting","tags":["Reported in CIBC Capital Markets Interview","SA 2026, Toronto office, First round","Accounting","Advanced"]},{"id":"q-0552","t":"acct","l":"Advanced","s":90,"q":"In a tax-free world, what is the effect on financial statements when a company moves from FIFO to LIFO? What if it’s not tax-free?","k":["In a tax-free scenario, switching cost-flow assumptions primarily affects COGS and inventory but not taxes. Under LIFO in a rising cost environment, COGS is higher, net income is lower, and inventory is lower.","In a normal (not tax-free) scenario, you’d also see the tax implications of lower/higher net income and potentially a LIFO reserve adjustment that impacts deferred taxes."],"collection":"practice","topic":"Accounting","tags":["Reported in Citi Interview","Accounting","Advanced"]},{"id":"q-0553","t":"acct","l":"Advanced","s":90,"q":"Assume a company purchases an asset for $100 and later sells it for $110. Walk me through the impact on the three financial statements, assuming a 20% tax rate.","k":["Starting on the Income Statement...","The gain on sale is $10 ($110 sale price - $100 purchase price).","With a 20% tax rate, taxes on the gain are $2.","Net Income increases by $8.","Moving onto the Cash Flow Statement...","Net Income increases by $8 under Cash Flow from Operations.","The $10 gain is subtracted as it is non-cash under Cash Flow from Operations.","The full sale proceeds of $110 are recorded under Cash Flow from Investing.","Total cash increases by $108 ($110 proceeds - $2 taxes).","Finally, on the Balance Sheet...","A: Cash increases by $108, and PP&E decreases by $100, for a net increase of $8 in assets.","L: No change in liabilities.","SE: Retained Earnings increase by $8 from Net Income.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Citi Interview","Accounting","Advanced"]},{"id":"q-0554","t":"acct","l":"Advanced","s":90,"q":"MULTI-STEP: Assume a 25% tax rate, a 10-year straight-line depreciation schedule, and no interest expense for simplicity.\n\n\n\n\nPart 1) In Year 0, a company acquires $100M of PP&E, financed with 50% debt and 50% equity. Walk through the 3 statements.\n\n\n\n\nPart 2) In Year 1, after one year of depreciation, the company sells the PP&E for $100M. Walk through the 3 statements for Year 1.","k":["Part 1: Year 0 (Acquisition)","Starting on the IS...","No change.","Moving onto the SCF...","CFI -$100M for PP&E purchase.","CFF +$50M debt, +$50M equity.","Net change in cash is $0.","Finally, on the BS...","A: PP&E +$100M.","L: Debt +$50M.","SE: Common Stock +$50M.","...and the Balance Sheet balances.","Part 2: Year 1 (Sale)","Note: The depreciation expense incurred during the year offsets the gain on sale.","Starting on the IS...","Depreciation Expense is $10M ($100M / 10).","Book Value at time of sale = $90M.","Gain on Sale = $10M ($100M Proceeds - $90M Book Value).","Pre-tax Income impact is $0 (Gain of $10M cancels Depreciation of -$10M).","Net Income impact is $0.","Moving onto the SCF...","Net Income $0.","Add back Depreciation +$10M.","Subtract Gain on Sale -$10M.","CFI: Add Proceeds from Sale +$100M.","Net change in cash +$100M.","Finally, on the BS (changes from beginning of Year 1)...","A: Cash +$100M. PP&E -$100M (Asset removed). Net Assets $0.","L: No change.","SE: Retained Earnings $0 (since Net Income was $0).","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Citi Interview","First round","Accounting","Advanced"]},{"id":"q-0555","t":"acct","l":"Advanced","s":90,"q":"Walk me through the impact on the three financial statements when a company issues $5,000 of debt to fund a $5,000 equity buyback. Assume a 10% interest rate, 10% annual principal repayment, and a 40% tax rate. Walk through Year 0 and Year 1.","k":["Year 0","Starting on the IS...","No change","Moving onto the SCF...","CFF +5,000 from debt issuance","CFF -5,000 for share buyback","Net change in cash is 0","Finally, on the BS...","A: No change","L: Debt +5,000","SE: Treasury stock -5,000 (or common equity down 5,000)","...and the Balance Sheet balances","Year 1","Starting on the IS...","Interest expense of 500 (10% x 5,000)","Pre-tax income down 500","NI down 300","Moving onto the SCF...","NI -300","CFF: -500 principal repayment (10% x 5,000)","Net change in cash is -800","Finally, on the BS...","A: Cash -800","L: Debt -500 (principal repayment)","SE: Retained earnings -300 (from NI)","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Citi Interview","SA 2026, First round","Accounting","Advanced"]},{"id":"q-0556","t":"acct","l":"Advanced","s":90,"q":"Suppose you bought PP&E for $200, financed 75% with cash and 25% with debt. Assume a 20% tax rate, a 10% interest rate, and a 10-year useful life for the asset. Walk me through the three financial statements for Year 0 and Year 1.","k":["Year 0","Starting on the IS...","No change","Moving onto the SCF...","CFI -200 for PP&E purchase","CFF +50 from debt raised (25% x $200)","Net change in cash is -150","Finally, on the BS...","A: Cash -150, PP&E +200, net +50","L: Debt +50","SE: No change","...and the Balance Sheet balances (+50 = +50 + 0)","Year 1","Starting on the IS...","Depreciation of $20 ($200 / 10 years)","Interest expense of $5 ($50 debt x 10%)","Pre-tax income down $25","Tax savings of $5 (20% x $25)","NI down $20","Moving onto the SCF...","NI -20","Add back depreciation +20","Net change in cash is 0","Finally, on the BS...","A: Cash 0, PP&E -20 (accumulated depreciation), net -20","L: No change","SE: Retained Earnings -20 from NI","...and the Balance Sheet balances (-20 = 0 + -20)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Citi Interview","SA 2026, First round","Accounting","Advanced"]},{"id":"q-0557","t":"acct","l":"Advanced","s":90,"q":"Part 1: Under what circumstances would you capitalize versus expense the costs associated with software engineers?\n\n\n\n\nPart 2: Walk through the 3-statement impact of capitalizing these costs versus expensing them immediately.","k":["Part 1: Capitalize vs. Expense","Capitalize when:","Software is developed for internal use and has future economic benefits.","Costs are incurred during the application development stage (after preliminary stage).","Project is technically feasible and management intends to complete it.","Expense when:","Costs are for maintenance, training, or data conversion.","Incurred during preliminary planning or post-implementation stages.","Software is developed for external sale (R&D expense until technological feasibility).","Part 2: 3-Statement Impact","Assume $100 in software engineer costs and 25% tax rate:","Capitalizing:","IS: No immediate impact on NI (no expense recognized).","CFS: CFO unchanged, CFI -$100 (capitalized asset).","BS: Assets +$100 (capitalized software), Cash -$100.","Expensing:","IS: Expense +$100, Pre-tax income -$100, NI -$75.","CFS: NI -$75. Net cash from operations decreases by $75, which is the net effect of the $100 cash salary payment partially offset by a $25 reduction in cash taxes paid (the tax shield).","BS: Cash -$75, Retained Earnings -$75.","Over time, capitalized costs are amortized, creating similar total expense but different timing."],"collection":"practice","topic":"Accounting","tags":["Reported in Credit Suisse Interview","Chicago Office","Accounting","Advanced"]},{"id":"q-0558","t":"acct","l":"Advanced","s":90,"q":"Company A and Company B are identical, except for their depreciation method. Each company purchases $200 of PP&E.\n\n\n\n\nCompany A uses a 10-year straight-line depreciation schedule, while Company B uses a 5-year schedule.\n\n\n\n\nAssuming a 25% tax rate, walk through the impact on the three financial statements for both companies in the first year after the purchase.","k":["Company A (10-Year Depreciation)","Starting on the IS...","Depreciation Expense = $200 / 10 = $20.","Pre-tax income down $20.","NI down $15 ($20 * (1 - 25%)).","Moving onto the SCF...","NI -$15.","Add back $20 depreciation.","Net change in cash is +$5.","Finally, on the BS...","A: Cash +$5, PP&E -$20 (accumulated depreciation), net -$15.","L: No change.","SE: Retained Earnings -$15.","Company B (5-Year Depreciation)","Starting on the IS...","Depreciation Expense = $200 / 5 = $40.","Pre-tax income down $40.","NI down $30 ($40 * (1 - 25%)).","Moving onto the SCF...","NI -$30.","Add back $40 depreciation.","Net change in cash is +$10.","Finally, on the BS...","A: Cash +$10, PP&E -$40, net -$30.","L: No change.","SE: Retained Earnings -$30.","Company B has higher cash flow in Year 1 (+$10 vs +$5) due to greater tax shield from accelerated depreciation, despite lower reported NI."],"collection":"practice","topic":"Accounting","tags":["Reported in Credit Suisse Interview","SF office","Accounting","Advanced"]},{"id":"q-0559","t":"acct","l":"Advanced","s":90,"q":"A software company records $1.2 million in deferred revenue from a subscription. Walk me through the impact on the three financial statements.","k":["This is a two-step question: first when cash is collected and deferred revenue is recorded, then when the revenue is recognized.","Step 1: Cash Collected, Revenue Deferred","Starting on the IS...","No impact — revenue is not yet recognized","Moving onto the SCF...","Cash from operations +$1.2M (increase in deferred revenue is a source of cash)","Net change in cash is up $1.2M","Finally, on the BS...","A: Cash +$1.2M","L: Deferred Revenue +$1.2M","SE: No change","...and the Balance Sheet balances","Step 2: Revenue Recognized (assume full recognition and a 25% tax rate)","Starting on the IS...","Revenue +$1.2M as the performance obligation is satisfied","Assuming no incremental expenses, pre-tax income +$1.2M","Taxes of $0.3M, so NI +$0.9M","Moving onto the SCF...","NI +$0.9M. This is already after tax, so do not subtract taxes again here — that is the most common mistake on this question.","Subtract the $1.2M decrease in Deferred Revenue (revenue recognized with no new cash collected)","Net change in cash -$0.3M, which is exactly the cash taxes paid","Finally, on the BS...","A: Cash -$0.3M","L: Deferred Revenue -$1.2M","SE: Retained Earnings +$0.9M","...and the Balance Sheet balances (-0.3 = -1.2 + 0.9)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Deutsche Bank Interview","Technology group, SF Office, First round","Accounting","Advanced"]},{"id":"q-0560","t":"acct","l":"Advanced","s":90,"q":"MULTI-STEP: Walk me through how purchasing PP&E for $100, financed with $50 debt and $50 equity, impacts the three financial statements in:\n\n\n\n\nYear 0: Initial purchase.\n\n\n\n\nYear 1: Operations generate $20 EBITDA, a 40% tax rate, a 10% interest rate, and straight-line depreciation over 10 years.","k":["Year 0","Starting on the IS...","No change","Moving onto the SCF...","CFI: -$100 for the PP&E purchase","CFF: +$50 from debt, +$50 from equity","Net change in cash: $0","Finally, on the BS...","A: PP&E +$100","L: Debt +$50","SE: +$50 (new equity issued)","...and the Balance Sheet balances","Year 1","Starting on the IS...","EBITDA: +$20","Depreciation: -$10 (10-year straight-line on $100)","EBIT: +$10","Interest Expense (10% on $50 debt): -$5","EBT: +$5","Taxes (40%): -$2","Net Income: +$3","Moving onto the SCF...","CFO: Net Income +$3 + Depreciation +$10 = +$13","Net change in cash: +$13","Finally, on the BS...","A: Cash +$13, PP&E -$10 (from depreciation), net +$3 in total assets","L: No change in debt","SE: Retained Earnings +$3","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Advanced"]},{"id":"q-0561","t":"acct","l":"Advanced","s":90,"q":"If I give you two balance sheets, one at the beginning of the year and one at the end of the year, how would you be able to calculate the EBITDA for that fiscal year?\n\n\n\n\nState any assumptions you have to make to back into all components.","k":["You could infer Net Income by the change in Retained Earnings (assuming no dividends), then back into Pre-Tax Income, add Interest (from debt balances), and add D&A (from changes in PP&E and Intangibles, assuming no other adjustments). This yields EBITDA.","Assumptions: You must assume no dividends, no write-downs, no capex, no disposals, and a consistent tax rate to back into all components properly."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Advanced"]},{"id":"q-0562","t":"acct","l":"Advanced","s":90,"q":"A company is buying a truck for $100 with 50% debt and 50% equity.\n\n\n\n\nThe truck depreciates using the straight-line method over 20 years.\n\n\n\n\nAssume the debt is non-amortizing with a 10% coupon and a 20% tax rate.\n\n\n\n\nWalk me through the 3 financial statements after 1 year.","k":["Starting on the IS...","Depreciation expense = $5 ($100 / 20)","Interest expense = $5 ($50 debt * 10%)","Pre-tax income decreases by $10","Net Income decreases by $8 ($10 * (1 - 20%))","Moving onto the SCF (cumulative from purchase)...","CFO: NI -$8, add back $5 Depreciation → -$3","CFI: -$100 for the truck, a Day 1 item rather than Year 1 operations","CFF: +$100 raised on Day 1 ($50 debt, $50 equity)","CFI and CFF net to zero, so net change in cash is -$3, all from Year 1 operations","Finally, on the BS (showing cumulative changes after 1 year)...","Assets: Cash -3, PP&E +95 (initial $100 less $5 depreciation) → Net Assets +92","Liabilities: Debt +50 (from initial financing)","SE: Initial Equity +50, Retained Earnings -8 → Net SE +42","...and the Balance Sheet balances (Assets +92, L+E +92)","If the interviewer wants Year 1 in isolation, with the truck bought in a prior period, CFI and CFF drop out and the answer is just CFO of -$3."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Advanced"]},{"id":"q-0563","t":"acct","l":"Advanced","s":90,"q":"A company has $30 in A/R, $50 in Inventory, and $20 in A/P at year-end.\n\n\n\n\nIn Q1 next year, revenue is $90 with an 80% gross margin.\n\n\n\n\nDSO is 90, DIO is 45, DPO is 60 (AR based on revenue; Inv/AP based on COGS; 90 days in Q1).\n\n\n\n\nHow much did cash flow change due to changes in working capital?","k":["Cash flow decreased by $27 due to changes in working capital.","Calculation:","Previous Operating Working Capital (OWC) = $30 + $50 - $20 = $60","Q1 Revenue = $90","Q1 COGS = $90 * (1 - 0.80) = $18","New A/R = $90 * (90 / 90) = $90","New Inventory = $18 * (45 / 90) = $9","New A/P = $18 * (60 / 90) = $12","New Operating Working Capital = $90 + $9 - $12 = $87","Change in Working Capital = $87 - $60 = +$27","Increase in OWC means cash flow decreased by $27."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Advanced"]},{"id":"q-0564","t":"acct","l":"Advanced","s":90,"q":"A company issues $200M PIK debt at 10% interest.\n\n\n\n\nAssume a 40% tax rate.\n\n\n\n\nWalk through the 3 statements at Year 0 (issuance) and Year 1.","k":["Year 0 (Issuance)","IS: No change.","CFS: CFF +$200M. Net cash +$200M.","BS: Cash +$200M, Debt +$200M.","Year 1","Starting on the IS...","Interest Expense +$20M ($200M * 10%).","Pre-tax income down $20M.","Net Income down $12M ($20M * (1 - 40%)).","Moving onto the SCF...","Net Income down $12M.","Add back $20M PIK interest (non-cash).","Net change in cash is +$8M.","Finally, on the BS...","Assets: Cash +$8M.","Liabilities: Debt +$20M.","SE: Retained Earnings -$12M.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Advanced"]},{"id":"q-0565","t":"acct","l":"Advanced","s":90,"q":"A company sells an asset (book value $100M) for $120M.\n\n\n\n\nAssume a 25% tax rate.\n\n\n\n\nWalk through the 3 statements.","k":["Starting on the IS...","Pre-tax gain on sale = $20M ($120M - $100M).","Tax on gain = $5M ($20M * 25%).","Net Income increases by $15M.","Moving onto the SCF...","Net Income +$15M.","Subtract $20M gain on sale (non-operating).","Add $120M cash proceeds in CFI.","Net change in cash is +$115M.","Finally, on the BS...","Assets: Cash +$115M, Asset (PP&E) -$100M. Net Assets +$15M.","Liabilities: No change.","SE: Retained Earnings +$15M.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Advanced"]},{"id":"q-0566","t":"acct","l":"Advanced","s":90,"q":"What happens on the 3 statements for a $1,000 debt write-down?\n\n\n\n\nAssume a 25% tax rate.","k":["Starting on the IS...","Pre-tax gain from debt extinguishment = $1,000.","Tax on gain = $250 ($1,000 * 25%).","Net Income increases by $750.","Moving onto the SCF...","Net Income +$750.","Subtract $1,000 debt write-down.","Net change in cash is -$250.","Finally, on the BS...","Assets: Cash -$250.","Liabilities: Debt -$1,000.","SE: Retained Earnings +$750.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Advanced"]},{"id":"q-0567","t":"acct","l":"Advanced","s":90,"q":"You buy a widget machine for $100 financed 50% with new debt and 50% with new equity.\n\n\n\n\nPurchase price implies a 5x multiple on the annual EBITDA the machine is expected to generate.\n\n\n\n\nDebt interest is 10% and tax rate is 40%.\n\n\n\n\nStraight-line depreciation over 10 years.\n\n\n\n\nHow are the three statements impacted at purchase and after 1 year?","k":["At Purchase","Starting on the IS...","No impact, as the purchase of an asset is not an expense.","Moving onto the SCF...","CFI -$100 for the purchase of the machine.","CFF +100 from new debt issuance and new equity issuance","Net change in cash is $0 (-$100 + $100).","Finally, on the BS...","A: Assets up by $100 (PP&E up $100). Cash is unchanged.","L: Liabilities up by $50 (Debt up $50).","SE: Shareholder’s Equity up by $50 (Common Stock/APIC up $50).","...and the Balance Sheet balances.","Cumulative Changes (Purchase + Year 1 Operations)","Assumptions for Year 1: Depreciation is $100 / 10 years = $10. Interest expense is $50 Debt * 10% = $5.","Starting on the IS...","EBITDA is up $20 (given 5x purchase multiple of $100)","Depreciation Expense is $10.","Interest Expense is $5.","Pre-tax income up by $5 ($20 - $10 - $5).","Taxes are $2 ($5 * 0.40).","Net Income up by $3 ($5 - $2).","Moving onto the SCF...","Net Income up by $3.","Add back Depreciation of $10 (non-cash expense).","Net change in cash is up $13 ($3 + $10).","Finally, on the BS...","A: Assets up by $13 (Cash up $13). PP&E down by $10 (due to depreciation). Net change in Assets is $3.","L: Liabilities unchanged (assuming no debt repayment in Year 1).","SE: Shareholder’s Equity up by $3 (Retained Earnings up $3 due to Net Income).","...and the Balance Sheet balances (Assets $3 = Liabilities $0 + Equity $3)."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Advanced"]},{"id":"q-0568","t":"acct","l":"Advanced","s":90,"q":"A factory was purchased 10 years ago for $500 and is depreciated straight-line over 40 years.\n\n\n\n\nAfter 10 years it is written down to $125.\n\n\n\n\nAssume a 20% tax rate.\n\n\n\n\nWalk through the three statements for the write-down.","k":["First, calculate the book value before write-down:","Annual Depreciation = $500 / 40 years = $12.5 per year.","Accumulated Depreciation after 10 years = $12.5 * 10 = $125.","Book Value after 10 years = Original Cost - Accumulated Depreciation = $500 - $125 = $375.","The factory is written down TO $125. So, the impairment loss is:","Impairment Loss = Book Value - Fair Value = $375 - $125 = $250.","Now, walk through the three statements for the impact of this $250 write-down:","Starting on the IS...","Impairment Loss (a pre-tax expense) of $250 is recorded.","Pre-tax income down by $250.","Tax benefit (at 20%) is $50 ($250 * 0.20).","Net Income down by $200 ($250 - $50).","Moving onto the SCF...","Net Income down by $200.","Add back the Impairment Loss of $250 (non-cash expense).","Net change in cash is up $50 (Tax shield).","Finally, on the BS...","A: Assets: Cash up by $50. PP&E down by $250. Net change in Assets is -$200.","L: No change in Liabilities.","SE: Shareholder’s Equity down by $200 (Retained Earnings).","...and the Balance Sheet balances (Assets -$200 = Liabilities $0 + Equity -$200)."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Advanced"]},{"id":"q-0569","t":"acct","l":"Advanced","s":90,"q":"$50 million of principal is impaired and extinguished with no repurchase. Assuming a 25% tax rate (and that the gain is fully taxable and paid in cash this period), walk through the three statements.","k":["Starting on the IS...","A Gain on Debt Extinguishment of $50 million is recorded. This is a pre-tax gain.","Pre-tax income up by $50 million.","Taxes (at 25%) on this gain are $12.5 million ($50M * 0.25).","Net Income up by $37.5 million ($50M - $12.5M).","Moving onto the SCF...","Net Income up by $37.5 million.","Subtract Gain on Debt Extinguishment of $50 million (as it is a non-cash gain).","Net change in cash is down $12.5 million ($37.5M - $50M).","Finally, on the BS...","A: Assets down by $12.5 million (Cash down $12.5 million).","L: Liabilities down by $50 million (Debt principal extinguished).","SE: Shareholder’s Equity up by $37.5 million (Retained Earnings up $37.5 million due to Net Income).","...and the Balance Sheet balances (Assets -$12.5M = Liabilities -$50M + Equity +$37.5M)."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Accounting","Advanced"]},{"id":"q-0570","t":"acct","l":"Advanced","s":90,"q":"MULTI-STEP:\n\n\n\n\nYear 1: A company buys $50 of inventory, all cash. Walk through the three statements at the time of purchase.\n\n\n\n\nYear 2: The company sells the inventory for $100. Assuming a 30% tax rate, walk through the three statements in year 2.\n\n\n\n\nHow would your answer change if the customers bought the inventory on credit (Accounts Receivable)?","k":["Year 1 — Purchase","Starting on the IS...","No change","Moving onto the SCF...","CFO −50 (inventory build)","Net cash −50","Finally, on the BS...","A: Cash −50, Inventory +50","L: No change","SE: No change","Year 2 — Cash Sale","Starting on the IS...","Revenue +100, COGS −50 → EBIT +50","Tax −15","NI +35","Moving onto the SCF...","NI +35","Decrease in Inventory +50 (source of cash)","Net cash +85","Finally, on the BS...","A: Cash +85, Inventory −50","L: No change","SE: +35","...and the Balance Sheet balances.","Key Differences if Customers Pay on Credit (AR):","Accounts Receivable +100 instead of Cash +100","CFO: +35 (NI) +50 (inventory decrease) −100 (AR increase) = −15","BS shows Δ: Cash −15, AR +100, Inventory −50, SE +35"],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","SA 2026, New York office, First round","Accounting","Advanced"]},{"id":"q-0571","t":"acct","l":"Advanced","s":90,"q":"You have 20% EBITDA margin, 15% EBIT margin, 10% NI margin.\n\n\n\n\nWhich of the following would increase net income the most?\n\n\n\n\nA $50 increase in revenue, an $11 increase in EBITDA, or a $6 increase in EBIT?","k":["The $11 EBITDA increase.","Revenue +50 → NI +5 (50 × 10% NI margin)","EBITDA +11 → NI +5.5 ( 11 × (10% NI margin / 20% EBITDA margin))","EBIT +6 → NI ≈ 4.0 (6 × (10% NI margin / 15% EBIT margin))","5.5 > 5 > 4, so the EBITDA bump wins."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","SA 2025, New York Office, First round","Accounting","Advanced"]},{"id":"q-0572","t":"acct","l":"Advanced","s":90,"q":"Assuming a 25% tax rate, walk me through the 3 financial statements after a company sells an asset with a book value of $1,000 for $800 in cash. The company then uses half of the proceeds to repay outstanding debt.","k":["Starting on the IS...","Loss on Sale = $800 - $1,000 = -$200.","Pre-tax income down $200.","Tax benefit = $50 ($200 * 25%).","NI down $150.","Moving onto the SCF...","NI -$150.","Add back $200 loss on sale.","Add $800 proceeds in CFI.","Subtract $400 debt repayment in CFF.","Net change in cash +$450.","Finally, on the BS...","A: Cash +$450, Asset -$1,000, net -$550.","L: Debt -$400.","SE: Retained Earnings -$150.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Superday","Accounting","Advanced"]},{"id":"q-0573","t":"acct","l":"Advanced","s":90,"q":"What are some accounting changes a company could make to artificially increase its reported EBITDA?","k":["Companies can manipulate EBITDA through various accounting tactics:","Capitalizing expenses that should be expensed (e.g., R&D, marketing costs).","Aggressive revenue recognition (recognizing revenue too early).","Reclassifying operating expenses as non-operating or one-time items.","Reducing reserves for bad debts or warranties.","Changing inventory accounting methods (FIFO to LIFO or vice versa).","Extending useful lives of assets to reduce depreciation (though this only affects EBIT, not EBITDA, unless it shifts capitalization).","Adding back unusual items as \"adjustments\" (creating adjusted EBITDA)."],"collection":"practice","topic":"Accounting","tags":["Reported in Evercore Interview","Superday","Accounting","Advanced"]},{"id":"q-0574","t":"acct","l":"Advanced","s":90,"q":"You are given the following financial data for a company:\n\n\n\nEBITDA: $500\nD&A: $100\nDebt Outstanding: $2,000\nInterest Rate: 5%\nCapital Expenditures: $150\nTax Rate: 25%\n\n\n\nWhat is the maximum change in Net Working Capital that allows the company to maintain a positive cash balance?","k":["You need to back into Levered Free Cash Flow and set it equal to zero.","Steps:","EBIT = $500 - $100 = $400","Interest Expense = $2,000 x 5% = $100","EBT = $400 - $100 = $300","Taxes = $300 x 25% = $75","Net Income = $300 - $75 = $225","Cash Flow = $225 + $100 - $150 - Change in NWC","Set Cash Flow = 0 and solve for Change in NWC:","Maximum Change in NWC = $225 + $100 - $150 = $175","If Change in NWC exceeds $175 (i.e., more cash is tied up in working capital), the company would have negative cash flow. Note that an increase in NWC uses cash, so a positive change in NWC is a cash outflow."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2027","Accounting","Advanced"]},{"id":"q-0575","t":"acct","l":"Advanced","s":90,"q":"At the beginning of Year 1, a company issues $100 in PIK Debt at 10% interest to buy a factory with a 5-year useful life. Assume a 20% tax rate. Walk me through the three financial statements at the end of Year 1 and Year 2.","k":["Year 1","Starting on the IS...","Depreciation: $100 / 5 = $20","PIK Interest: $100 x 10% = $10 (non-cash, accrues to debt balance)","Pre-tax income down $30","Tax savings: $30 x 20% = $6","NI down $24","Moving onto the SCF...","NI -24","Add back depreciation +20 (non-cash)","Add back PIK interest +10 (non-cash)","Net change in cash: +6","Finally, on the BS...","A: Cash +6, PP&E -20 (depreciation), net assets -14","L: Debt increases by $10 (PIK accrual, balance now $110)","SE: -24 from NI","...and the Balance Sheet balances (-14 = +10 + -24)","Year 2","Starting on the IS...","Depreciation: $20 (same straight-line)","PIK Interest: $110 x 10% = $11 (accrues on new balance)","Pre-tax income down $31","Tax savings: $31 x 20% = $6.20","NI down $24.80","Moving onto the SCF...","NI -24.80","Add back depreciation +20","Add back PIK interest +11","Net change in cash: +6.20","Finally, on the BS...","A: Cash +6.20, PP&E -20, net assets -13.80","L: Debt increases by $11 (PIK accrual, balance now $121)","SE: -24.80 from NI","...and the Balance Sheet balances (-13.80 = +11 + -24.80)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","M&A group, New York Office, Second round","Accounting","Advanced"]},{"id":"q-0576","t":"acct","l":"Advanced","s":90,"q":"What happens to the three financial statements when there is an increase in deferred tax liabilities (DTL)?","k":["An increase in DTL means the company is paying less in cash taxes now than its book tax expense, deferring the difference to the future.","Starting on the IS...","No direct impact. The IS reflects book tax expense, which remains the same.","Moving onto the SCF...","The increase in DTL is added back in CFO as a non-cash adjustment (cash taxes paid were lower than book tax expense).","Net change in cash is up by the DTL increase.","Finally, on the BS...","A: Cash up by the DTL increase","L: DTL up by the same amount","SE: No change","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2027, Superday","Accounting","Advanced"]},{"id":"q-0577","t":"acct","l":"Advanced","s":90,"q":"Part 1: A company purchases a $100 truck, financed 50% with debt and 50% with equity. The truck has a 20-year useful life. Assume a 10% interest rate and a 20% tax rate. Walk me through the impact on the three financial statements in Year 0 and Year 1.\n\n\n\n\nPart 2: Now assume the asset is written down in Year 2. Continue calculating the depreciation and interest expense impacts on the statements.","k":["Part 1 - Year 0","Starting on the IS...","No impact","Moving onto the SCF...","CFI: -100 for truck purchase","CFF: +50 from debt, +50 from equity issuance","Net change in cash is 0","Finally, on the BS...","A: PP&E +100","L: Debt +50","SE: +50 from equity issuance","...and the Balance Sheet balances","Part 1 - Year 1","Starting on the IS...","Depreciation expense of 5 (100 / 20 years)","Interest expense of 5 (50 debt x 10%)","Pre-tax income down 10","NI down 8","Moving onto the SCF...","NI -8","Add back depreciation of 5","Net change in cash is -3","Finally, on the BS...","A: Cash -3, PP&E -5, net -8","L: No change","SE: -8 from Retained Earnings","...and the Balance Sheet balances","Part 2 - Year 2 Write-Down","A write-down means the remaining book value of the truck (95 after Year 1 depreciation) is impaired. Assume a full write-down to 0.","Starting on the IS...","Impairment charge of 95","Interest expense of 5","Pre-tax income down 100","NI down 80","Moving onto the SCF...","NI -80","Add back impairment of 95 (non-cash)","Net change in cash is +15","Finally, on the BS...","A: Cash +15, PP&E -95, net -80","L: No change","SE: -80 from Retained Earnings","...and the Balance Sheet balances","After the write-down, there is no further depreciation since the asset's book value is zero. Interest expense continues at $5/year."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2026, First round","Accounting","Advanced"]},{"id":"q-0578","t":"acct","l":"Advanced","s":90,"q":"A company purchases a $100 factory financed entirely with debt at a 10% interest rate. The factory has a 10-year useful life, no salvage value, and the tax rate is 20%. Walk me through the impact on the three financial statements.","k":["Year 0 (Purchase)","Starting on the IS...","No impact","Moving onto the SCF...","CFI: -100 for factory","CFF: +100 from debt","Net change in cash is 0","Finally, on the BS...","A: PP&E +100","L: Debt +100","SE: No change","...and the Balance Sheet balances","Year 1 (Ongoing)","Starting on the IS...","Depreciation of 10 (100/10 years)","Interest expense of 10 (100 x 10%)","Pre-tax income down 20","NI down 16","Moving onto the SCF...","NI -16","Add back depreciation of 10","Net change in cash is -6","Finally, on the BS...","A: Cash -6, PP&E -10, net -16","L: No change","SE: -16 from Retained Earnings","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","M&A group, New York Office, Superday","Accounting","Advanced"]},{"id":"q-0579","t":"acct","l":"Advanced","s":90,"q":"Part 1: A company purchases a $100 truck financed with 50% debt and 50% equity. The truck has a 5-year useful life. Assume a 10% interest rate and a 20% tax rate. Walk me through what happens on the three financial statements in Year 0.\n\n\n\n\nPart 2: Now walk me through what happens at the end of Year 1.","k":["Part 1: Year 0","Starting on the IS...","No change","Moving onto the SCF...","CFI -100 for truck purchase","CFF +50 from debt, +50 from equity issuance","Net change in cash is 0","Finally, on the BS...","A: PP&E +100","L: Debt +50","SE: +50 from equity issuance","...and the Balance Sheet balances","Part 2: Year 1","Starting on the IS...","Depreciation expense +20 ($100 / 5 years), interest expense +5 ($50 x 10%)","Pre-tax income down 25","NI down 20","Moving onto the SCF...","NI -20","Add back depreciation +20 (non-cash)","Net change in cash is 0","Finally, on the BS...","A: PP&E -20 (depreciation), net -20","L: No change (assuming no principal repayment)","SE: -20 from retained earnings","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2026, First round","Accounting","Advanced"]},{"id":"q-0580","t":"acct","l":"Advanced","s":90,"q":"A company has $200 million of debt with a 5% PIK interest rate and a 5% cash interest rate. Walk me through the impact on the three financial statements in Year 0 and Year 1.\n\n\n\n\nAssume no taxes.","k":["Year 0 (Debt Issuance)","Starting on the IS...","No change","Moving onto the SCF...","CFF +200 from debt raised","Net change in cash is +200","Finally, on the BS...","A: Cash +200","L: Debt +200","SE: No change","...and the Balance Sheet balances (+200 = +200 + 0)","Year 1","Total interest = 5% PIK + 5% cash = 10% total, or $20M.","Starting on the IS...","Interest expense of $20 ($10 cash + $10 PIK)","Pre-tax income down $20","NI down $20 (no taxes)","Moving onto the SCF...","NI -20","Add back $10 PIK (non-cash expense)","Net change in cash is -10","Finally, on the BS...","A: Cash -10","L: Debt +10 (PIK interest accrues to debt balance)","SE: Retained Earnings -20 from NI","...and the Balance Sheet balances (-10 = +10 + -20)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2026, First round","Accounting","Advanced"]},{"id":"q-0581","t":"acct","l":"Advanced","s":90,"q":"Part 1: A company buys $100 of PP&E with debt. Assume a 20% tax rate and a 10% interest rate. Walk me through the three financial statements for Year 0 and Year 1.\n\n\n\n\nPart 2: Now assume the same scenario, but the PP&E was bought with cash and is sold at Year 3 for a loss. Walk me through the impact on the three financial statements.","k":["Part 1 - Year 0 (Purchase with Debt)","Starting on the IS...","No change","Moving onto the SCF...","CFI -100 for PP&E","CFF +100 from debt","Net change in cash is 0","Finally, on the BS...","A: PP&E +100","L: Debt +100","SE: No change","...and the Balance Sheet balances (+100 = +100 + 0)","Part 1 - Year 1","Assume 10-year straight-line depreciation ($10/yr). Interest = $100 x 10% = $10.","Starting on the IS...","Depreciation -10, Interest -10","Pre-tax income down 20","NI down 16 (after 20% tax savings of 4)","Moving onto the SCF...","NI -16","Add back D&A +10","Net change in cash is -6","Finally, on the BS...","A: Cash -6, PP&E -10, net -16","L: No change (assuming no debt repayment)","SE: RE -16 from NI","...and the Balance Sheet balances (-16 = 0 + -16)","Part 2 - Year 3 Sale at a Loss (PP&E bought with cash)","Assume no depreciation schedule was specified, so use the same 10-year SL. After 3 years: Book value = $100 - 3 x $10 = $70. Assume sold for $50 (loss of $20).","Starting on the IS...","Loss on sale of $20","Pre-tax income down 20","NI down 16 (after 20% tax benefit of 4)","Moving onto the SCF...","NI -16","Add back loss of 20 (non-cash)","+50 sale proceeds in CFI","Net change in cash is +54","Finally, on the BS...","A: Cash +54, PP&E -70, net -16","L: No change","SE: RE -16 from NI","...and the Balance Sheet balances (-16 = 0 + -16)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2025, Superday","Accounting","Advanced"]},{"id":"q-0582","t":"acct","l":"Advanced","s":90,"q":"Which is better: a $100 increase in revenue or a $50 decrease in COGS?\n\n\n\n\nFollow-up 1: Explain your answer conditional on gross margins.\n\n\n\n\nFollow-up 2: Qualitatively, which is better if the gross margin is 50%?","k":["It depends on the company's gross margin.","A $100 increase in revenue adds $100 x Gross Margin to gross profit (the rest is consumed by COGS).","A $50 decrease in COGS adds $50 directly to gross profit.","If Gross Margin > 50%: the $100 revenue increase adds more than $50 to gross profit. Revenue increase is better.","If Gross Margin < 50%: the $100 revenue increase adds less than $50 to gross profit. COGS decrease is better.","If Gross Margin = 50%: both add exactly $50 to gross profit. They are financially equivalent.","Follow-up 1: Conditional on Gross Margins","The breakeven gross margin is 50%. Above 50%, revenue growth generates more incremental profit per dollar than cost reduction. Below 50%, cost reduction is more impactful because the majority of each revenue dollar is consumed by COGS.","Follow-up 2: Qualitatively at 50% Gross Margin","At 50% gross margin, both produce the same $50 gross profit impact. However, qualitatively, a strong argument can be made for either:","The $50 COGS decrease may be preferable because it does not require additional selling or operating expenses to generate, represents improved operational efficiency, and is more within management's control.","The $100 revenue increase may be preferable because revenue growth signals market demand, is typically valued more highly by investors (higher revenue multiples), and is more scalable over time.","The strongest answer acknowledges both perspectives and states which you would prioritize with a brief justification."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, First round","Accounting","Advanced"]},{"id":"q-0583","t":"acct","l":"Advanced","s":90,"q":"Now assume that the company has a $100 increase in revenue at a 50% gross margin. The revenue was generated using materials already in the inventory. Walk me through what happens to the three financial statements. Assume a tax rate of 20%.","k":["The key insight is that COGS comes from existing inventory (already paid for in a prior period), so there is no new cash outflow for cost of goods sold.","Starting on the IS...","Revenue +100","COGS -50 (50% gross margin, sourced from inventory)","Gross Profit +50","Pre-tax income +50","Tax -10 (20% x 50)","NI +40","Moving onto the SCF...","NI +40","Working capital: Inventory decreased by 50 (decrease in current asset is a source of cash) +50","Net change in cash is +90","Finally, on the BS...","A: Cash +90, Inventory -50, net +40","L: No change","SE: Retained Earnings +40","...and the Balance Sheet balances (A +40 = L 0 + SE +40)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, First round","Accounting","Advanced"]},{"id":"q-0584","t":"acct","l":"Advanced","s":90,"q":"Walk me through the impact on the three financial statements when Subway sells a $5 sandwich for cash, assuming $1 in wages, $1 in inventory cost, $0.50 in depreciation, and a 40% tax rate.","k":["Starting on the Income Statement...","Revenue increases by $5.","Cost of Goods Sold (COGS) increases by $1 (inventory cost).","Operating expenses increase by $1 (wages).","Depreciation expense increases by $0.50.","Operating income (EBIT) is $2.50.","After 40% taxes, Net Income increases by $1.50.","Moving onto the Cash Flow Statement...","Net Income increases by $1.50.","Add back $0.50 of depreciation (a non-cash expense).","Inventory decreases by $1, reflected in CFO.","Total Cash Flow from Operations (CFO) increases by $3.","No changes in Cash Flow from Investing (CFI) or Cash Flow from Financing (CFF).","Net increase in cash is $3.","Finally, on the Balance Sheet...","Assets: Cash increases by $3, and inventory decreases by $1. PP&E decreases by $0.50 due to depreciation. Net assets increase by $1.50.","Liabilities: No changes.","Shareholders' Equity: Retained Earnings increase by $1.50, reflecting the Net Income.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Goldman Sachs Interview","Accounting","Advanced"]},{"id":"q-0585","t":"acct","l":"Advanced","s":90,"q":"It is January 1st of next year. A company sells a piece of PP&E with a book value of $100 for $80 in cash. Assume there is no incremental depreciation and a 25% tax rate. Walk me through the impact on the three financial statements.","k":["The PP&E has a book value of $100 and is sold for $80, resulting in a pre-tax loss on sale of $20.","Starting on the IS...","Loss on sale of -20 (pre-tax)","Taxes decrease by 5 (25% × 20)","Net Income decreases by 15","Moving onto the SCF...","CFO: NI -15, add back non-cash loss on sale +20, net CFO +5","CFI: +80 from PP&E sale proceeds","Net change in cash is up 85","Finally, on the BS...","A: Cash +85, PP&E -100, net A -15","L: No change","SE: Retained Earnings -15 (from NI)","...and the Balance Sheet balances: A -15 = L + SE (0 + -15) ✓"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","Accounting","Advanced"]},{"id":"q-0586","t":"acct","l":"Advanced","s":90,"q":"You buy back $100M of debt at 90 cents on the dollar. How does that flow through the three financial statements? Assume a 30% tax rate.","k":["The $100M debt buyback at 90 cents on the dollar results in a $10M gain on debt extinguishment.","Here's how it flows through the statements:","Starting on the IS...","$10M gain on debt extinguishment increases pre-tax income by $10M.","With a 30% tax rate, net income increases by $7M.","Moving onto the SCF...","CFO: Begin with Net Income of +$7M.","Subtract the $10M gain (non-cash), resulting in -$3M in CFO from this transaction.","CFF: Record the $90M cash outflow to buy back the debt.","Total net cash decreases by $93M.","Finally, on the BS...","A: Cash -$93M.","L: Debt -$100M.","SE: Retained Earnings +$7M (from the after-tax gain).","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Greenhill & Co. Interview","Accounting","Advanced"]},{"id":"q-0587","t":"acct","l":"Advanced","s":90,"q":"What are the differences between operating leases and capital leases?","k":["Under current accounting standards (ASC 842 / IFRS 16), the distinction has changed significantly. Previously, operating leases were off-balance-sheet expenses, while capital leases were treated like assets and debt.","Now, most leases (both operating and finance/capital) must be capitalized on the balance sheet. This involves recognizing a \"Right-of-Use\" (ROU) asset and a corresponding lease liability.","The primary difference now lies in the income statement recognition:","Finance (Capital) Leases: Interest and amortization are recorded as separate expenses.","Operating Leases: A single lease expense is recorded, typically on a straight-line basis."],"collection":"practice","topic":"Accounting","tags":["Reported in Greenhill & Co. Interview","SA 2024, Industrials M&A, Chicago office","Accounting","Advanced"]},{"id":"q-0588","t":"acct","l":"Advanced","s":90,"q":"You sell a subscription for $240 per year. Walk through the initial sale,\n\n\n\n\nthen after one month passes, assuming a 20% tax rate.","k":["At Signing","IS: no revenue.","SCF:","CFO +240 (cash in)","BS:","Cash +240","Deferred Revenue +240","After 1 Month","IS:","Revenue +20","Pretax +20","Taxes –4","NI +16","SCF:","NI +16","ΔDeferred Revenue –20","CFO –4 → Cash –4","BS:","Cash –4 (net +236 vs day 0)","Deferred Revenue –20 → 220","Retained Earnings +16","Assets down 4 equal L+E down 4—balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Greenhill & Co. Interview","First round","Accounting","Advanced"]},{"id":"q-0589","t":"acct","l":"Advanced","s":90,"q":"MULTI-STEP: Assume a 25% tax rate.\n\n\n\n\nA company buys a machine for $200, financed with $100 of cash and a $100 5-year bond with a 10% annual cash interest payment.\n\n\n\n\nThe machine is depreciated straight-line over 5 years with no salvage value.\n\n\n\n\nWalk me through the impact on the three financial statements at:\n\n\n\n\nPart 1) Time 0, at the moment of purchase.\n\n\n\n\nPart 2) The end of Year 1.","k":["Part 1: Time 0","Starting on the IS...","No change.","Moving onto the SCF...","CFI -$200 for machine purchase.","CFF +$100 from debt issuance.","Net change in cash -$100.","Finally, on the BS...","A: PP&E +$200, Cash -$100, net +$100.","L: Debt +$100.","SE: No change.","...and the Balance Sheet balances.","Part 2: Year 1","Starting on the IS...","Depreciation expense $40 ($200 / 5 years).","Interest expense $10 ($100 × 10%).","Pre-tax income down $50.","NI down $37.50 ($50 × (1 - 25%)).","Moving onto the SCF...","NI -$37.50.","Add back $40 depreciation.","Cash Flow from Operations: +$2.50.","Net Change in Cash: +$2.50.","Finally, on the BS...","A: Cash +$2.50, PP&E -$40. Net change in Assets is -$37.50.","L: Debt is unchanged.","SE: Retained Earnings -$37.50.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Greenhill & Co. Interview","M&A group, First round","Accounting","Advanced"]},{"id":"q-0590","t":"acct","l":"Advanced","s":90,"q":"Your firm hires a consultant for 500 in year 0.\n\n\n\n\nWalk through the 3 statements. Then assume you capitalize it. Now what happens to the statements?","k":["Expense Immediately (assume 30% tax)","Income Statement:","Pretax –500","NI –350","Cash Flow Statement:","NI –350","No non‑cash add‑backs","CFO –350 → Cash –350","Balance Sheet:","Cash –350","Retained Earnings –350","Capitalize (5‑year straight‑line)","Year 0 IS: no change.","SCF:","CFI –500 (purchase intangible)","Cash –500","BS:","Intangible Asset +500","Cash –500","Future years show $100 amortization expense, lowering NI by 70 after tax, adding back 100 in CFO."],"collection":"practice","topic":"Accounting","tags":["Reported in Guggenheim Partners Interview","SA 2025, New York Office, First round","Accounting","Advanced"]},{"id":"q-0591","t":"acct","l":"Advanced","s":90,"q":"A company hires an IT consultant for a software‑upgrade project costing $500.\n\n\n\n\nAssume a 50% tax rate.\n\n\n\n\nPart 1 – Expense the $500 immediately.\n\n\n\n\nPart 2 – Capitalize the $500 cost.\n\n\n\n\nWalk through the Year 0 impact on the three financial statements for each case.","k":["Part 1 – Expensed","Starting on the IS...","Pre‑tax income down 500 via SG&A expense","Net income down 250","Moving onto the SCF...","Net income −250","Net cash −250","Finally, on the BS...","Assets: Cash −250","Liabilities: No change","SE: Retained earnings −250","Part 2 – Capitalized","Starting on the IS...","No impact in Year 0 (it will get depreciated in following years, but no impact in Year 0","Moving onto the SCF...","Cash flow from investing −500","Net cash −500","Finally, on the BS...","Assets: Cash −500, PP&E +500 for investment","Liabilities: No change","SE: No change"],"collection":"practice","topic":"Accounting","tags":["Reported in Guggenheim Partners Interview","Accounting","Advanced"]},{"id":"q-0592","t":"acct","l":"Advanced","s":90,"q":"What is a convertible bond and how does it work?","k":["A convertible bond is debt with an embedded option allowing the holder to exchange the bond for a fixed number of shares.","Pays a lower coupon than straight debt because of the conversion feature.","Acts like debt when the share price is below the strike and like equity when > the strike.","Gives investors downside protection (principal) plus upside equity participation."],"collection":"practice","topic":"Accounting","tags":["Reported in Guggenheim Partners Interview","Accounting","Advanced"]},{"id":"q-0593","t":"acct","l":"Advanced","s":90,"q":"A company receives $100 in cash upfront for a one-year subscription.\n\n\n\n\nAssuming a 25% tax rate, walk through the impact on the three financial statements:\n\n\n\n\nPart 1) At the time of the cash receipt.\n\n\n\n\nPart 2) After one month of the subscription has passed.","k":["Part 1: Cash Receipt","Starting on the IS...","No change.","Moving onto the SCF...","Cash from operations +$100 (increase in Deferred Revenue).","Net change in cash +$100.","Finally, on the BS...","A: Cash +$100.","L: Deferred Revenue +$100.","SE: No change.","...and the Balance Sheet balances.","Part 2: After One Month","Starting on the IS...","Revenue +$8.33 ($100 / 12 months).","Pre-tax income +$8.33.","NI +$6.25 ($8.33 × (1 - 25%)).","Moving onto the SCF...","NI +$6.25.","Deferred Revenue -$8.33.","Net change in cash -$2.08.","Finally, on the BS...","A: Cash -$2.08.","L: Deferred Revenue -$8.33.","SE: Retained Earnings +$6.25.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Guggenheim Partners Interview","M&A group, First round","Accounting","Advanced"]},{"id":"q-0594","t":"acct","l":"Advanced","s":90,"q":"Depreciation was overstated by $10. Walk me through the adjustments needed to fix this, assuming a 10% tax rate.","k":["Starting on the Income Statement...","Reduce depreciation expense by $10.","This increases Operating Income (EBIT) by $10.","Pre-tax income also increases by $10.","After applying the 10% tax rate, Net Income increases by $9.","Moving onto the Cash Flow Statement...","Net Income increases by $9.","Depreciation is a non-cash expense, so reducing it by $10 decreases the add-back in Cash Flow from Operations (CFO).","Total cash flow impact is $-1.","Finally, on the Balance Sheet...","Assets: Cash decreases by $1, and PP&E increases by $10 due to reduced accumulated depreciation. Net assets increase by $9.","Liabilities: No changes.","Shareholders' Equity: Retained Earnings increase by $9, reflecting the higher Net Income.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Houlihan Lokey Interview","Accounting","Advanced"]},{"id":"q-0595","t":"acct","l":"Advanced","s":90,"q":"A company's primary input is a natural resource that has experienced a sharp price increase this year.\n\n\n\n\nIn this inflationary environment, would the company's cash flow be higher if it used the LIFO or FIFO inventory accounting method?","k":["LIFO would result in higher cash flow.","Reasoning:","In an inflationary environment, inventory costs are rising.","LIFO (Last-In, First-Out): This method expenses the most recently purchased (and therefore most expensive) inventory first. This leads to a higher Cost of Goods Sold (COGS).","Impact on Taxes and Cash Flow: A higher COGS results in lower reported pre-tax income. Lower taxable income means the company pays less in cash taxes. This tax saving directly results in higher operating cash flow compared to FIFO."],"collection":"practice","topic":"Accounting","tags":["Reported in Houlihan Lokey Interview","Chicago office, First round","Accounting","Advanced"]},{"id":"q-0596","t":"acct","l":"Advanced","s":90,"q":"A company raises $100 in debt and uses $50 for a stock buyback and $50 for dividends. Walk me through the three financial statements. Assume a 25% tax rate.","k":["Starting on the IS...","No immediate impact (debt issuance, buybacks, and dividends do not flow through the IS).","Moving onto the SCF...","CFF: +100 from debt issuance, -50 for stock buyback, -50 for dividends","Net change in cash is 0","Finally, on the BS...","A: Cash unchanged (net 0)","L: Debt +100","SE: Treasury stock -50 (buyback), Retained Earnings -50 (dividend), net SE -100","...and the Balance Sheet balances (A: 0 = L: +100 + SE: -100)","Note: Going forward, interest expense on the new debt will reduce pre-tax income. At 25% tax rate with, say, 5% interest: $5 interest expense, NI down $3.75 per year."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, First round","Accounting","Advanced"]},{"id":"q-0597","t":"acct","l":"Advanced","s":90,"q":"Walk me through the accounting for a convertible bond at the time of issuance and upon conversion into common stock.","k":["At Issuance","Under current ASC 470-20 (as amended by ASU 2020-06), most convertible debt is NOT bifurcated:","Record the entire proceeds as a debt liability (at par plus/minus any discount or premium); amortize using the effective interest method.","No separate equity component for the embedded conversion feature unless there is a distinct equity element (e.g., substantial premium or detachable equity instrument) allocated to APIC.","BS: Debt (liability) and Cash (asset); APIC only if a separate equity component exists.","Upon Conversion","When bondholders convert under the original contractual terms:","Remove the carrying value of the debt (including any unamortized discount/issuance costs) from the balance sheet.","Issue common stock at par value.","Any difference between the debt's carrying amount and common stock at par is credited to APIC (no gain or loss recognized).","BS: Debt decreases; Common Stock and APIC together increase by the total carrying value reclassified to equity.","Note: Simplified answer assumes a plain-vanilla convertible (no derivative bifurcation) and book-value conversion accounting."],"collection":"practice","topic":"Accounting","tags":["Reported in J.P. Morgan Interview","Chicago office","Accounting","Advanced"]},{"id":"q-0598","t":"acct","l":"Advanced","s":90,"q":"A company has the following transactions during the year:\n\n\n\nPurchases $300k of inventory using cash.\n\n\n\nAt the end of the year, the company writes off 50% of the purchased inventory. Assuming a 20% tax rate (and that the write-off is immediately tax-deductible), walk me through the 3-statement impact of the inventory purchase and subsequent write-off.","k":["Inventory Purchase","IS: No change (inventory is an asset, not an expense).","CFS: CFO -$300k (cash outflow for inventory purchase).","BS: Cash -$300k, Inventory +$300k.","Inventory Write-Off (50% = $150k)","Starting on the IS...","Inventory write-off (COGS or impairment) +$150k.","Pre-tax income down $150k.","Net Income down $120k ($150k * (1 - 20%)).","Moving onto the SCF...","Net Income -$120k.","Add back $150k inventory write-off (non-cash).","Net change in cash is +$30k.","Finally, on the BS...","A: Cash +$30k, Inventory -$150k. Net Assets -$120k.","L: No change.","SE: Retained Earnings -$120k.","...and the Balance Sheet balances.","Combined Net Impact for the Year:","Cash -$270k, Inventory +$150k, Retained Earnings -$120k."],"collection":"practice","topic":"Accounting","tags":["Reported in J.P. Morgan Interview","Chicago office, Superday","Accounting","Advanced"]},{"id":"q-0599","t":"acct","l":"Advanced","s":90,"q":"A company purchases $100 of PP&E with a 10-year useful life. The purchase is financed 50% with cash and 50% with debt at a 10% interest rate. Assume a 20% tax rate. Walk me through the three financial statements.","k":["Year 0 — Purchase Date","Starting on the IS...","No change (the purchase of PP&E is a capital expenditure, not an expense)","Moving onto the SCF...","CFI: -$100 for PP&E purchase","CFF: +$50 from debt issuance","Net change in cash: -$50","Finally, on the BS...","A: Cash -$50, PP&E +$100 → net Assets +$50","L: Debt +$50","SE: No change","...and the Balance Sheet balances (A +$50 = L +$50 + SE $0)","Year 1 — Ongoing Impact","Now the PP&E depreciates and the debt accrues interest. D&A = $100 / 10 years = $10/year. Interest = $50 x 10% = $5/year.","Starting on the IS...","D&A expense: +$10","Interest expense: +$5","Pre-tax income: -$15","Tax savings (at 20% rate): +$3","Net Income: -$12","Moving onto the SCF...","CFO: NI -$12, add back D&A +$10 (non-cash) → CFO = -$2","No CFI or CFF activity in Year 1 (assuming no debt repayment)","Net change in cash: -$2","Finally, on the BS...","A: Cash -$2, PP&E -$10 (accumulated depreciation) → net Assets -$12","L: No change (debt remains at $50; interest was paid in cash)","SE: Retained Earnings -$12 (from lower NI)","...and the Balance Sheet balances (A -$12 = L $0 + SE -$12)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in J.P. Morgan Interview","SA 2025, Healthcare group, SF Office, Superday","Accounting","Advanced"]},{"id":"q-0600","t":"acct","l":"Advanced","s":90,"q":"What is the difference between capital leases and operating leases, and how does this distinction affect how you analyze a company's leverage?","k":["Under current accounting standards (ASC 842), both finance (capital) leases and operating leases are recorded on the balance sheet as a right-of-use (ROU) asset and lease liability. The key differences:","Finance (Capital) Lease: Treated like a debt-financed purchase. The asset is depreciated and interest expense is recognized separately. On the IS, you see depreciation + interest (front-loaded expense). The liability is treated like debt in leverage analysis.","Operating Lease: The lease payment is recorded as a single operating expense (rent/lease expense) on the IS. The ROU asset and liability still appear on the BS, but the expense pattern is straight-line.","For leverage analysis, finance leases are typically included in debt. Operating lease liabilities may or may not be included depending on the analyst's approach. Many practitioners add capitalized operating leases to debt (or treat the lease payments as a debt-like obligation) to get a more accurate picture of total leverage, especially for asset-heavy industries like retail and airlines."],"collection":"practice","topic":"Accounting","tags":["New","Reported in J.P. Morgan Interview","SA 2025","Accounting","Advanced"]},{"id":"q-0601","t":"acct","l":"Advanced","s":90,"q":"One company capitalizes its leases and another company expenses them. What is the impact on the financial statements, and how does this affect comparability between the two companies?","k":["Capitalized Lease (Finance Lease / ASC 842)","BS: Right-of-use asset and lease liability recorded on the balance sheet.","IS: Depreciation on the asset + interest expense on the liability (front-loaded total expense).","SCF: Depreciation adds back to CFO; principal portion of lease payments classified in CFF.","Result: Higher EBITDA (lease payments split between depreciation and interest, both excluded from EBITDA), higher debt, higher assets.","Expensed Lease (Operating Lease - pre-ASC 842 treatment)","BS: No asset or liability recorded (off-balance-sheet).","IS: Full lease payment recorded as an operating expense (rent expense).","SCF: Entire lease payment is a CFO outflow.","Result: Lower EBITDA (lease expense hits above EBITDA), lower reported debt, lower assets.","Comparability Impact:","To compare the two companies on an apples-to-apples basis, you should either capitalize all leases for both companies or add back operating lease expenses to EBITDA.","EV/EBITDA comparisons are distorted: the company capitalizing leases will appear to have higher EBITDA and higher debt, while the other will have lower EBITDA and lower debt.","Under ASC 842 / IFRS 16, most leases are now capitalized, reducing this comparability issue for newer financials."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Accounting","Advanced"]},{"id":"q-0602","t":"acct","l":"Advanced","s":90,"q":"Walk me through how a capital lease affects the three financial statements upon its inception.","k":["No immediate Income Statement impact at inception.","Cash Flow Statement:","CFF - no cash in or out because the asset is financed by the lessor.","Balance Sheet:","Assets ↑ by right‑of‑use asset (present value of lease payments).","Liabilities ↑ by the same amount (lease liability).","Shareholders’ Equity unchanged.","The lease then generates depreciation (IS, non‑cash add‑back) and interest expense (IS, cash) over its life."],"collection":"practice","topic":"Accounting","tags":["Reported in Lazard Interview","Accounting","Advanced"]},{"id":"q-0603","t":"acct","l":"Advanced","s":90,"q":"Assume a tax rate of 40%. Walk me through how a $10 increase in warranty expense affects the three financial statements.","k":["Starting on the IS...","Pre‑tax income down 10","Net income down 6","Moving onto the SCF...","NI −6","Add back 10 non‑cash warranty accrual in CFO","Net +4 cash","Finally, on the BS...","A: Cash +4","L: Warranty liability +10","SE: −6 retained earnings","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Lazard Interview","Accounting","Advanced"]},{"id":"q-0604","t":"acct","l":"Advanced","s":90,"q":"What happens to a company's financial statements if it moves from a 6-month upfront subscription of $60 to a monthly subscription of $10?","k":["The shift delays revenue recognition and reduces upfront cash collection.","Income Statement:","Revenue recognized monthly ($10/month) vs. ratably over 6 months ($10/month from $60 upfront). Timing changes but total over 6 months is the same.","Near-term revenue may decline if upfront payments previously pulled forward cash.","Cash Flow Statement:","Cash collected monthly ($10) instead of $60 upfront, significantly reducing operating cash flow in early periods.","Working capital impact: less deferred revenue on the balance sheet.","Balance Sheet:","Lower cash in early periods.","Deferred revenue decreases (less upfront cash means less obligation to deliver future services)."],"collection":"practice","topic":"Accounting","tags":["Reported in Lazard Interview","SF Office","Accounting","Advanced"]},{"id":"q-0605","t":"acct","l":"Advanced","s":90,"q":"What are some of the effects of stock-based compensation on equity holders?","k":["Dilution: SBC increases the number of shares outstanding (through option exercises, RSU vesting), diluting existing shareholders' ownership percentage and EPS.","Reduced cash taxes: SBC is tax-deductible when options are exercised or RSUs vest, creating a tax shield. However, the accounting expense under ASC 718 is a non-cash charge.","Overstated cash flow: Since SBC is added back as a non-cash expense on the CFS, operating cash flow may appear inflated relative to the true economic cost of compensating employees.","Equity value transfer: SBC effectively transfers value from existing shareholders to employees, as new shares are issued below market value (for options) or at no cost (for RSUs)."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Lazard Interview","SA 2025, SF Office, First round","Accounting","Advanced"]},{"id":"q-0606","t":"acct","l":"Advanced","s":90,"q":"Walk me through the impact on the three financial statements when a company issues $100 of debt at a 10% interest rate and, as a result of a new capital investment, annual depreciation increases by $20. Assume a 40% tax rate and that the debt is not amortized.","k":["Year 0 (Issuance and Purchase)","Starting on the IS...","No change","Moving onto the SCF...","CFF +100 from debt issuance","CFI -100 for capital investment","Net change in cash is 0","Finally, on the BS...","A: PP&E +100","L: Debt +100","SE: No change","...and the Balance Sheet balances","Year 1 (Ongoing Impact)","Starting on the IS...","Depreciation expense +20, interest expense +10","Pre-tax income down 30","NI down 18","Moving onto the SCF...","NI -18","Add back depreciation +20 (non-cash)","Net change in cash is +2","Finally, on the BS...","A: Cash +2, PP&E -20, net -18","L: Debt unchanged (no amortization)","SE: -18 from retained earnings","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Lazard Interview","SA 2027, Superday","Accounting","Advanced"]},{"id":"q-0607","t":"acct","l":"Advanced","s":90,"q":"A company issues $500 BV debt at par. Walk through the 3 statements at issuance.\n\n\n\n\nFollow-up: Assume the debt now trades at $400 FMV. What does this tell you about the interest rate environment at those two points in time?","k":["Year 0","Starting on the IS…","No change (debt issuance is a financing activity, not an expense)","Moving onto the SCF…","CFF: +$500 cash from debt issuance","Net change in cash: +$500","Finally, on the BS…","Assets (Cash) +$500","Liabilities (Debt) +$500","Equity: No change","... and the Balance Sheet balances.","Follow-up","The fact that the bond’s market price fell from $500 to $400 indicates that market interest rates have risen above the bond’s coupon rate, so it now trades at a discount.","Additionally, a worsening view of the company’s credit profile (credit-rating downgrade or adverse news about its leverage, cash flows, litigation risk, etc) could drive a bond to trade at a deeper discount beyond just general rate moves.","In practice, corporate bond yields = risk-free rate + company's credit spread."],"collection":"practice","topic":"Accounting","tags":["Reported in LionTree Interview","SA 2026","Accounting","Advanced"]},{"id":"q-0608","t":"acct","l":"Advanced","s":90,"q":"A $50 increase in interest expense, with 50% PIK and 50% cash interest.\n\n\n\n\nAssume a 30% tax rate.\n\n\n\n\nWalk through the 3 statements.","k":["Income Statement:","Pre‑tax income − 50.","Net Income − 35.","Cash Flow Statement:","Net Income − 35.","Add back 25 PIK.","Net change in cash − 10.","Balance Sheet:","Cash − 10.","Debt + 25.","Retained earnings − 35.","Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in LionTree Interview","SA 2026","Accounting","Advanced"]},{"id":"q-0609","t":"acct","l":"Advanced","s":90,"q":"Assuming a 40% tax rate, walk me through the three financial statements when a company sells a factory with a book value of $100 for $80.","k":["Starting on the IS...","Record a $20 pre-tax loss (sale price of $80 - book value of $100).","The $20 loss saves $8 in taxes (assuming 40% rate).","Net Income decreases by $12.","Moving onto the SCF...","NI is down $12.","Add back the $20 loss as it is non-cash. CFO increases by $8.","CFI shows +$80 from the cash proceeds of the sale.","Net cash increases by $88.","Finally, on the BS...","A: Cash is up $88, PP&E is down $100. Net change in assets is -$12.","L: No change.","SE: Retained Earnings is down $12 from the Net Income loss.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in M. Klein & Co. Interview","Accounting","Advanced"]},{"id":"q-0610","t":"acct","l":"Advanced","s":90,"q":"Part 1: A company has $120 of PP&E with an 8-year useful life and a 25% tax rate. Walk me through the impact on the three financial statements immediately after purchase.\n\n\n\n\nPart 2: After 4 years, the PP&E is sold for $120. Walk me through the impact on the three financial statements at the time of the sale.","k":["Part 1: Purchase (Year 0)","Assume purchased with cash.","Starting on the IS...","No impact","Moving onto the SCF...","CFI: -120","Net change in cash is -120","Finally, on the BS...","A: Cash -120, PP&E +120, net 0","L: No change","SE: No change","...and the Balance Sheet balances","Part 2: Sale After 4 Years","Annual depreciation = $120 / 8 = $15/year.","Accumulated depreciation after 4 years = $60.","Book value at sale = $120 - $60 = $60.","Sale price = $120. Gain = $120 - $60 = $60.","Starting on the IS...","Gain on sale of 60","Pre-tax income up 60","NI up 45","Moving onto the SCF...","NI +45","Subtract gain of 60 in CFO","Add 120 in CFI from sale proceeds","Net change in cash is +105","Finally, on the BS...","A: Cash +105, PP&E -60 (book value removed), net +45","L: No change","SE: +45 from Retained Earnings","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, Second round","Accounting","Advanced"]},{"id":"q-0611","t":"acct","l":"Advanced","s":90,"q":"What happens when taxes are deferred? Walk me through the impact on the three financial statements. What happens to the deferred tax liability (DTL) over time?","k":["Deferred taxes arise when there is a timing difference between book taxes (IS) and cash taxes (actually paid). A DTL is created when book taxes exceed cash taxes paid today (taxes are deferred to the future).","Starting on the IS...","Tax expense on the IS reflects the full book tax amount (higher).","NI is reduced by the full book tax.","Moving onto the SCF...","NI reflects full tax expense.","The increase in DTL is added back in CFO (since cash taxes paid were lower than book taxes).","Net effect: Cash is higher than NI would suggest.","Finally, on the BS...","A: Cash is higher (saved cash from lower actual taxes)","L: DTL increases","SE: Retained Earnings reflects the lower NI (from higher book tax)","...and the Balance Sheet balances.","Over time, the DTL reverses as cash taxes exceed book taxes in future periods. Common example: accelerated depreciation for tax vs. straight-line for book creates a DTL that reverses as the asset ages."],"collection":"practice","topic":"Accounting","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, Second round","Accounting","Advanced"]},{"id":"q-0612","t":"acct","l":"Advanced","s":90,"q":"Assuming a 25% tax rate, walk me through the 3 statements with a:\n\n\n\n\n$20 increase in interest expense, with $10 as PIK interest and $10 as cash interest.","k":["Starting on the IS...","Interest expense up $20 ($10 cash + $10 PIK)","Pre-tax income down $20","NI down $15 ($20 * (1 - 25%))","Moving onto the SCF...","NI down $15","Add back $10 PIK interest (non-cash)","Net change in cash is down $5","Finally, on the BS...","Assets: Cash down $5","Liabilities: Debt up $10 (PIK portion)","SE: Retained Earnings down $15","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Miller Buckfire Interview","First round","Accounting","Advanced"]},{"id":"q-0613","t":"acct","l":"Advanced","s":90,"q":"Company A buys Company B for $230 in equity value.\n\n\n\n\nB has $120 in assets, $35 in existing goodwill, $80 in liabilities,\n\n\n\n\nand identifiable assets have fair value $50 higher than book value.\n\n\n\n\nWhat is the new goodwill?","k":["Fair‑value net identifiable assets = (120 − 35) + 50 − 80 = 55.","Goodwill = Purchase Price − 55 = 175."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","First round","Accounting","Advanced"]},{"id":"q-0614","t":"acct","l":"Advanced","s":90,"q":"Company A owns 70% of Company B, which generates $700 in net income.\n\n\n\n\nWalk me through the three statements.","k":["Income Statement:","Consolidate full 700.","Show 210 as non‑controlling interest (NCI); 490 to parent NI.","Cash‑Flow Statement:","Start with consolidated NI 700; NCI adjustment only if dividends paid.","Balance Sheet:","A: Cash +700.","SE: Retained Earnings +490.","NCI (Equity) +210.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","SA 2026","Accounting","Advanced"]},{"id":"q-0615","t":"acct","l":"Advanced","s":90,"q":"Purchase an asset for 400 at 5x EBITDA that generates revenue, funded 50% by debt and 50% by cash.\n\n\n\n\nThe debt is 50% PIK interest and 50% regular interest at 10% cost. Depreciate over 10 years with zero salvage.\n\n\n\n\nAssume a 25% tax rate. In year 1, you write off the debt. Walk me through the statements.","k":["Income Statement:","EBITDA = 80","Depreciation 40 ⇒ EBIT 40","Interest = 20 (10 cash, 10 PIK)","Debt-forgiveness gain = 210","Pre-tax = 230; Tax (25%) 57.5; NI 172.5","Cash-Flow Statement:","NI 172.5","+ D&A 40; + PIK 10; – non-cash gain 210","CFO = +12.5","CFF: No change (no cash debt service)","Net Cash change +12.5","Balance Sheet:","Assets: Cash +12.5; PP&E −40","Liabilities: Debt −200","Equity: Retained Earnings +172.5","Assets Δ (−27.5) = Liab + SE Δ (−27.5) ⇒ Balanced."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","SA 2026","Accounting","Advanced"]},{"id":"q-0616","t":"acct","l":"Advanced","s":90,"q":"In 2023: A/R = 150, Inventory = 100, A/P = 150.\n\n\n\n\nIn 2024: A/R = 250, Inventory = 200, A/P = 250.\n\n\n\n\nRevenue is 2000, gross profit is 1000. Calculate the cash conversion cycle.","k":["≈ 18 days.","COGS = 1,000.","DSO ≈ 36.5.","DIO ≈ 54.8.","DPO ≈ 73.0.","CCC = 36.5 + 54.8 − 73.0 ≈ 18."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","SA 2026","Accounting","Advanced"]},{"id":"q-0617","t":"acct","l":"Advanced","s":90,"q":"Company A owns 70% of Company B, which had net income of $700 this past year.\n\n\n\n\nWalk me through the 3 statements for Company A.","k":["Starting on the IS...","Consolidated NI includes all $700.","Subtract 30% Non-Controlling Interest (210) → NI attributable to parent = 490.","Moving onto the SCF...","Begin with NI to parent 490.","Add back 210 NCI (non‑cash).","Net cash +700.","Finally, on the BS...","A: Cash +700.","SE: Non-Controlling Interest (Equity) +210. Retained Earnings +490.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","First round","Accounting","Advanced"]},{"id":"q-0618","t":"acct","l":"Advanced","s":90,"q":"A firm has EBITDA of 120, trades at 10x EV/EBITDA, 20% EBITDA margin, 10% interest expense, 5x Debt/EBITDA, and 20x P/E.\n\n\n\n\nWhat is the effective tax rate?","k":["Answer: 50%.","EV = 120 × 10 = 1,200.","Debt = 5 × 120 = 600 → Equity = 1,200 − 600 = 600.","NI = Equity / P‑E = 600 / 20 = 30.","Interest = 10% × 600 = 60.","EBT = NI / (1 − t) with EBITDA ≈ EBIT gives 120 − 60 = EBT.","30 = (1 − t) × 60 ⇒ t = 50%."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","First round","Accounting","Advanced"]},{"id":"q-0619","t":"acct","l":"Advanced","s":90,"q":"A company purchases a $100 piece of equipment with a 10-year useful life and no salvage value. The company uses straight-line depreciation. Assume a 40% tax rate.\n\n\n\n\nWalk me through the impact on the three financial statements at two points in time:\n\n\n\nIn Year 0, immediately after the purchase (assuming it was paid for with cash).\nIn Year 1, after one year of depreciation has been recorded.","k":["Year 0","IS: No impact","SCF: CFI −100.","BS: Cash −100, PP&E +100.","... and the Balance Sheet balances.","Year 1","IS:","Depreciation expense 10 ⇒ Pre‑tax −10 ⇒ NI −6.","SCF:","NI −6, add back 10 Depreciation ⇒ +4 cash.","BS:","Assets: Cash +4, PP&E −10 → Net −6.","Liabilities: No impact","Shareholder's Equity: Retained Earnings −6.","... and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","Accounting","Advanced"]},{"id":"q-0620","t":"acct","l":"Advanced","s":90,"q":"What are Net Operating Losses (NOLs) and how can a company use them?","k":["A Net Operating Loss (NOL) occurs when a company’s expenses and deductions exceed its revenues in a period.","That loss generates an NOL carryforward that can be applied against taxable income in future periods to lower cash tax payments.","On the balance sheet, unused NOLs are recorded as deferred tax assets.","The tax benefit of an NOL is only realized when it actually reduces cash taxes, often years after the loss is incurred.","Because the value of that future benefit is discounted to present value, companies aim to use NOLs as soon as they have sufficient taxable income to maximize their benefit."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","Accounting","Advanced"]},{"id":"q-0621","t":"acct","l":"Advanced","s":90,"q":"During a period of rising prices, what is the effect on a company's cash flow if it switches its inventory accounting method from FIFO to LIFO? Why?","k":["In an inflationary environment, LIFO yields a higher COGS charge—reducing taxable income and cash taxes paid—so operating cash flow increases; FIFO has the opposite effect.","How it works:","LIFO assigns the most recent (higher-cost) inventory to COGS, lowering gross profit and taxable income, which reduces cash tax payments and boosts cash flow.","FIFO uses older (lower-cost) inventory first, resulting in lower COGS, higher taxable income, increased cash tax payments, and thus lower operating cash flow."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","Accounting","Advanced"]},{"id":"q-0622","t":"acct","l":"Advanced","s":90,"q":"How do Net Operating Losses (NOLs) affect a company's three financial statements when they are generated and when they are used?","k":["NOLs generate a deferred tax asset on a loss, then later consume it to offset taxable income and save cash taxes.","When generated:","Income Statement: Records a tax benefit (reducing the Net Loss), creating a Deferred Tax Asset.","Cash Flow Statement: Subtract the \"Deferred Tax Benefit\" (non-cash) from Net Income (since you didn't actually receive cash).","Balance Sheet: Deferred Tax Asset ↑; Retained Earnings ↓ by the net loss.","When used:","Income Statement: Records a \"Deferred Tax Expense\" (reducing Net Income) as the asset is used up, even though cash taxes are 0.","Cash Flow Statement: Add back the \"Deferred Tax Expense\" (non-cash) to Net Income, showing that cash flow is higher than NI suggests.","Balance Sheet: Deferred Tax Asset ↓; Cash ↑ (relative to paying taxes)."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","Accounting","Advanced"]},{"id":"q-0623","t":"acct","l":"Advanced","s":90,"q":"Assuming a 40% tax rate, walk me through the three financial statements for a $100 million non-cash impairment charge.","k":["Assuming the $100M impairment is not immediately tax-deductible, creating a temporary difference (e.g., an impairment of PP&E)...","Starting on the IS...","Pre-tax income decreases by $100M from the impairment expense.","A $40M Deferred Tax Asset is created due to the temporary difference, creating a tax benefit that reduces tax expense.","Net Income decreases by $60M.","Moving onto the SCF...","Net Income is down $60M.","Add back the $100M non-cash impairment charge.","Subtract the $40M increase in Deferred Tax Assets (a use of cash).","Net change in cash is $0.","Finally, on the BS...","Assets: Cash is unchanged, Deferred Tax Asset increases by $40M, PP&E decreases by $100M. Total Assets decrease by $60M.","Liabilities: No change.","SE: Retained Earnings decreases by $60M.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Moelis & Co. Interview","Accounting","Advanced"]},{"id":"q-0624","t":"acct","l":"Advanced","s":90,"q":"Part 1: A company purchases a factory for $100M in all cash. The factory has a 5-year useful life. Assume a 20% tax rate. Walk me through the three financial statements at the beginning of Year 1 and at the end of Year 1.\n\n\n\n\nPart 2: Now assume the company sells the factory for $90M at the beginning of Year 2. Walk me through the three financial statements.","k":["Part 1: Beginning of Year 1 (Purchase)","Starting on the IS...","No change","Moving onto the SCF...","CFI: -100M for factory purchase","Net change in cash is down 100M","Finally, on the BS...","A: Cash -100M, PP&E +100M, net 0","L: No change","SE: No change","...and the Balance Sheet balances","End of Year 1 (Depreciation)","Starting on the IS...","Depreciation = 100M / 5 = 20M","Pre-tax income down 20M","NI down 16M","Moving onto the SCF...","NI -16M","Add back D&A of 20M","Net change in cash is up 4M","Finally, on the BS...","A: Cash +4M, PP&E -20M, net -16M","L: No change","SE: Retained Earnings -16M","...and the Balance Sheet balances","Part 2: Beginning of Year 2 (Sale)","Book value after 1 year of depreciation = 100M - 20M = 80M. Sale at 90M = gain of 10M.","Starting on the IS...","Gain on sale of 10M","Pre-tax income up 10M","NI up 8M","Moving onto the SCF...","NI +8M","Subtract gain of 10M in CFO","Add 90M in CFI from sale proceeds","Net change in cash is up 88M","Finally, on the BS...","A: Cash +88M, PP&E -80M (remove net book value), net +8M","L: No change","SE: Retained Earnings +8M","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Moelis & Co. Interview","SA 2026, Chicago Office, First round","Accounting","Advanced"]},{"id":"q-0625","t":"acct","l":"Advanced","s":90,"q":"A company increases inventory by $10. It pays $5 in cash and finances the remaining $5 on credit (accounts payable). Walk me through the 3-statement impact.","k":["Starting on the IS...","No impact. Purchasing inventory is a balance sheet transaction, not an expense (it becomes COGS only when sold).","Moving onto the SCF...","Inventory +10 (use of cash in working capital)","AP +5 (source of cash in working capital)","Net working capital impact: -10 + 5 = -5","Net change in cash is down $5","Finally, on the BS...","A: Cash -5, Inventory +10, net assets up $5","L: AP +5","SE: No change","...and the Balance Sheet balances (+5 = +5 + 0)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Moelis & Co. Interview","SA 2025","Accounting","Advanced"]},{"id":"q-0626","t":"acct","l":"Advanced","s":90,"q":"A parent company owns 70% of Company A. Company A reports Net Income of $210 million. Walk me through the impact on the parent company's three financial statements, including the treatment of minority interest.","k":["Under consolidation accounting, the parent consolidates 100% of Company A's financials but recognizes 30% as minority interest (non-controlling interest).","Starting on the IS...","The parent consolidates 100% of Company A's revenue and expenses, flowing $210M of subsidiary NI into the consolidated IS","Subtract Minority Interest of $63M (30% * $210M) to arrive at NI attributable to the parent of $147M","Moving onto the SCF...","Consolidated NI of $210M (the full amount flows through the consolidated SCF)","No non-cash adjustments specific to this transaction","Net change in cash depends on whether Company A distributes dividends; assuming no dividends, cash increases by the full amount of Company A's cash earnings","Finally, on the BS...","A: Consolidated assets include 100% of Company A's assets (including the cash generated)","L: No change to liabilities from this transaction","SE: Retained Earnings increases by $147M (parent's 70% share). Minority Interest (within equity) increases by $63M (the 30% non-controlling interest share)","Total equity increases by $210M ($147M to parent + $63M to minority interest), matching the consolidated net income.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Moelis & Co. Interview","SA 2027","Accounting","Advanced"]},{"id":"q-0627","t":"acct","l":"Advanced","s":90,"q":"You are reviewing a balance sheet and notice it does not balance. What would your approach be to identify and resolve the discrepancy?","k":["Verify the equation: Total Assets = Total Liabilities + Shareholders' Equity. Quantify the imbalance.","Check the cash link: Ensure ending cash on the SCF ties to cash on the BS. A broken cash link is the most common cause.","Check retained earnings: RE = Prior RE + NI - Dividends. If NI isn't flowing correctly from the IS, the BS won't balance.","Review recent transactions for entries that affected only one side of the BS.","Check for sign errors in working capital items.","Examine non-cash items: D&A, SBC, deferred taxes must be consistently treated across all three statements.","Round-trip the debt schedule: Beginning balance + issuances - repayments = ending balance."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Moelis & Co. Interview","SA 2026, First round","Accounting","Advanced"]},{"id":"q-0628","t":"acct","l":"Advanced","s":90,"q":"Given a Levered FCF Yield of 10%, $100M EBITDA, $5M CapEx, $25M Interest Expense,\n\n\n\n\n$10M decrease in NWC, $5M Tax Expense, $500M Net Debt, and 100M FDSO, find LFCF.","k":["LFCF = $75 mm.","EBITDA 100 – CapEx 5 = 95","+10 NWC decrease = 105","–25 interest –5 taxes = 75"],"collection":"practice","topic":"Accounting","tags":["Reported in Morgan Stanley Interview","SA 2026, Houston office, Superday","Accounting","Advanced"]},{"id":"q-0629","t":"acct","l":"Advanced","s":90,"q":"Year 1: Walk through the 3 statements for $100 equipment purchased with 50% cash and 50% debt.\n\n\n\n\nYear 2: $10 increase in depreciation, $10 interest expense. Walk through the statements.\n\n\n\n\nAssume a tax rate of 30%.","k":["Year 1","Starting on the IS...","No change","Moving onto the SCF...","CFI −100 for equipment","CFF +50 from debt","Net cash −50","Finally, on the BS...","A: Cash −50, PP&E +100 → +50","L: Debt +50","SE: No change","...and the Balance Sheet balances","Year 2","Starting on the IS...","Depreciation +10 → EBIT −10","Interest −10 → Pre‑tax −20","Tax +6 → NI −14","Moving onto the SCF...","NI −14","Add back 10 depreciation","Net cash −4","Finally, on the BS...","A: Cash −4, PP&E −10 → net −14","L: No change","SE: −14","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Morgan Stanley Interview","SA 2026","Accounting","Advanced"]},{"id":"q-0630","t":"acct","l":"Advanced","s":90,"q":"A company issues $100 of equity and uses the proceeds to pay down an equivalent amount of debt.\n\n\n\n\nPart 1: Walk me through the impact on the three financial statements at the time of the transaction.\n\n\n\n\nPart 2: How would this transaction affect the company's valuation?","k":["Part 1: Impact on Statements","Starting on the IS...","No immediate impact.","Moving onto the SCF...","CFF: +$100 from equity issuance, -$100 from debt repayment.","Net change in cash is $0.","Finally, on the BS...","Assets: No change (cash in, cash out).","Liabilities: Debt down $100.","SE: Common Stock/APIC up $100.","...and the Balance Sheet balances.","Part 2: Valuation Impact","Enterprise Value is unchanged (Equity Value +$100, Debt -$100 offset).","However, reduced interest expense will increase future Net Income, potentially improving equity value over time."],"collection":"practice","topic":"Accounting","tags":["Reported in Morgan Stanley Interview","New York Office, First round","Accounting","Advanced"]},{"id":"q-0631","t":"acct","l":"Advanced","s":90,"q":"A SaaS company signs a $300 million contract that is paid upfront and recognized over 3 years. Walk me through the impact on the three financial statements at the end of Year 1 and Year 2.\n\n\n\n\nAssume a 25% tax rate and no incremental expenses.","k":["Year 0 (Contract Signing)","The company receives $300M cash upfront. Since the service has not yet been delivered, the full $300M is recorded as Deferred Revenue (a liability).","Year 1","Starting on the IS...","Revenue recognized: $100M (300 / 3 years)","Assuming no incremental expenses, pre-tax income up $100M","Assuming a 25% tax rate, NI up $75M","Moving onto the SCF...","NI +75M","Deferred Revenue decreased by 100M (a use of cash in working capital)","Net change in cash is down $25M","Finally, on the BS...","A: Cash -25M (note: the $300M cash inflow happened at signing in Year 0)","L: Deferred Revenue -100M","SE: Retained Earnings +75M from NI","...and the Balance Sheet balances (-25 = -100 + 75)","Year 2","Starting on the IS...","Revenue recognized: another $100M","NI up $75M (same logic)","Moving onto the SCF...","NI +75M","Deferred Revenue decreased by 100M","Net change in cash is down $25M","Finally, on the BS...","A: Cash -25M","L: Deferred Revenue -100M","SE: Retained Earnings +75M","...and the Balance Sheet balances (-25 = -100 + 75)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Morgan Stanley Interview","SA 2027, TMT group, Menlo Park Office, First round","Accounting","Advanced"]},{"id":"q-0632","t":"acct","l":"Advanced","s":90,"q":"Walk me through the impact on the three financial statements of a $100 million perpetual software license sale (such as IBM infrastructure software).\n\n\n\n\nAssume no associated COGS and a 25% tax rate.","k":["A perpetual license is recognized upfront at the point of sale because the customer receives the right to use the software indefinitely.","Starting on the IS...","Revenue +100M recognized immediately","Assuming no incremental COGS and a 25% tax rate, NI up $75M","Moving onto the SCF...","NI +75M","Assuming cash is collected at sale, no working capital adjustment needed","Net change in cash is up $75M","Finally, on the BS...","A: Cash +75M","L: No change","SE: Retained Earnings +75M","...and the Balance Sheet balances (+75 = 0 + 75)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Morgan Stanley Interview","SA 2027, TMT group, Menlo Park Office, First round","Accounting","Advanced"]},{"id":"q-0633","t":"acct","l":"Advanced","s":90,"q":"You discover that depreciation was overstated by $50. How do you account for the correction, and what happens to the three financial statements? Assume a 25% tax rate.","k":["This is equivalent to a $50 decrease in depreciation. The correction reverses the overstatement:","Starting on the IS...","Depreciation expense down $50","Pre-tax income up $50","NI up $37.50","Moving onto the SCF...","NI +37.50","Depreciation add-back down $50 (lose the non-cash add-back)","Net change in cash is down $12.50","Finally, on the BS...","A: Cash -12.50, PP&E +50 (less accumulated depreciation), net assets up $37.50","L: No change","SE: +37.50 from NI","...and the Balance Sheet balances (+37.50 = 0 + 37.50)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Generalist group, New York Office, First round","Accounting","Advanced"]},{"id":"q-0634","t":"acct","l":"Advanced","s":90,"q":"A company buys a factory in Year 0 for $100, funded entirely with debt at a 10% interest rate. Depreciation is $10 in Year 2, and the company repays $20 of principal at the end of Year 2. Assume a 30% tax rate.\n\n\n\n\nWalk me through the impact on the three statements in Year 0 (at purchase) and in Year 2.","k":["Year 0","IS: no change.","SCF:","CFI –100 (PP&E)","CFF +100 (debt draw)","Net Cash 0","BS:","PP&E +100","Debt +100","Year 2","Note the $20 is a principal repayment, not interest — principal never touches the income statement. Interest is a full year on the $100 balance because the repayment happens at year-end.","IS:","Depreciation 10","Interest 10 ($100 × 10%)","Pretax –20","Tax +6 @ 30%","NI –14","SCF:","NI –14","Add back 10 Depreciation","CFO –4","CFF –20 (principal repayment)","Net Cash –24","BS:","Cash –24","PP&E –10 (net)","Debt –20","Retained Earnings –14","Assets down 34 match L+E down 34—balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Perella Weinberg Interview","First round","Accounting","Advanced"]},{"id":"q-0635","t":"acct","l":"Advanced","s":90,"q":"Part 1: You start a company with $100 in cash and an expected return of 10%. What happens on the three financial statements?\n\n\n\n\nPart 2: A customer prepays $500 for an offering delivered over the next 5 years. The annual expense is $50 and the tax rate is 0%. What is the impact on the financial statements?\n\n\n\n\nPart 3: Given the above, how would you value the company?\n\n\n\n\nPart 4: If the expected return went from 10% to 15%, what would happen to the valuation?","k":["Part 1: Starting the Company","IS: No change (no revenue or expenses yet)","SCF: CFF +100 from equity contribution","BS: Cash +100 (A), Common Stock/Paid-in Capital +100 (SE)","Part 2: Customer Prepayment ($500 over 5 years)","At time of payment:","IS: No revenue recognized yet","SCF: Cash +500 (operating -- change in deferred revenue)","BS: Cash +500 (A), Deferred Revenue +500 (L)","Each year (recognizing 1/5 = $100 revenue, $50 expense):","IS: Revenue +100, Expense -50, NI +50 (0% tax)","SCF: NI +50, Deferred Revenue -100 (cash already received), net -50","BS: Cash -50, Deferred Revenue -100 (L), Retained Earnings +50 (SE)","Part 3: Valuation","Annual FCF = $50 (NI at 0% tax with no CapEx or NWC changes beyond deferred revenue). Using a perpetuity at 10% discount: Value = $50 / 0.10 = $500. Plus initial cash of $100 gives $600 total, though the prepaid contract is only 5 years, so a DCF of 5 years of $50 FCF + terminal value is more appropriate.","Part 4: Discount Rate from 10% to 15%","Valuation decreases. A higher discount rate reduces the present value of future cash flows. Using the perpetuity: $50 / 0.15 = $333, down from $500."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Perella Weinberg Interview","SA 2025, First round","Accounting","Advanced"]},{"id":"q-0636","t":"acct","l":"Advanced","s":90,"q":"Part 1: A company purchases $100 of PP&E with cash. Assume a 10-year useful life, no salvage value, and a 25% tax rate. Walk me through the impact on the three financial statements in Year 0 and Year 1.\n\n\n\n\nPart 2: The company then sells the PP&E after two years for $50. Walk me through the impact on the three financial statements.","k":["Part 1 - Year 0 (Purchase)","Starting on the IS...","No change","Moving onto the SCF...","CFI -100 for PP&E","Net change in cash is -100","Finally, on the BS...","A: Cash -100, PP&E +100, net 0","L: No change","SE: No change","...and the Balance Sheet balances","Part 1 - Year 1 (Depreciation)","Starting on the IS...","Depreciation expense of $10 ($100 / 10 years)","Pre-tax income down $10","NI down $7.50 (25% tax savings on $10)","Moving onto the SCF...","NI -7.50","Add back D&A +10","Net change in cash is +2.50","Finally, on the BS...","A: Cash +2.50, PP&E -10, net -7.50","L: No change","SE: RE -7.50 from NI","...and the Balance Sheet balances (-7.50 = 0 + -7.50)","Part 2 - Year 2 (Sale for $50)","After 2 years of depreciation: Book value = $100 - 2 x $10 = $80. Sale at $50 = loss of $30.","Starting on the IS...","Loss on sale of $30","Pre-tax income down $30","NI down $22.50 (after 25% tax benefit of $7.50)","Moving onto the SCF...","NI -22.50","Add back loss of $30 (non-cash)","Add $50 from sale proceeds in CFI","Net change in cash is +57.50","Finally, on the BS...","A: Cash +57.50, PP&E -80 (remove remaining book value), net -22.50","L: No change","SE: RE -22.50 from NI","...and the Balance Sheet balances (-22.50 = 0 + -22.50)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in Perella Weinberg Interview","SA 2026, Superday","Accounting","Advanced"]},{"id":"q-0637","t":"acct","l":"Advanced","s":90,"q":"A company currently has $200M in Revenue and $100M in EBITDA. Which of the following would affect EBITDA the most: a 20% increase in volume, a 20% increase in price, or a $15M decrease in expenses?","k":["A 20% increase in price affects EBITDA the most.","Analysis (assume Revenue = Price x Quantity and EBITDA = Revenue - Expenses):","20% increase in price: Revenue increases by 20%, and since there is no corresponding increase in variable costs (same volume), the entire revenue increase flows directly to EBITDA. If Revenue is $200M (implying $100M expenses), new Revenue = $240M, new EBITDA = $140M (+$40M).","20% increase in volume: Revenue increases by 20%, but variable costs also increase proportionally. If variable costs are 50% of COGS, the EBITDA increase is less than the full revenue increase. New EBITDA might be ~$120-130M depending on cost structure.","$15M decrease in expenses: EBITDA increases by exactly $15M to $115M.","Price increases are the most powerful lever because they flow 100% to the bottom line with no incremental costs. Volume increases carry incremental variable costs. The expense reduction is a fixed dollar amount."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Piper Sandler Interview","SA 2026, Superday","Accounting","Advanced"]},{"id":"q-0638","t":"acct","l":"Advanced","s":90,"q":"The fair market value of an asset was increased by $50. How do the three financial statements change?","k":["No change under US GAAP.","Under US GAAP, companies cannot write up the value of fixed assets (PP&E, intangibles) above historical cost. An increase in fair market value alone has no impact on any of the three financial statements. This is a key difference from IFRS.","Under IFRS (revaluation model):","IFRS allows companies to elect the revaluation model for PP&E, in which case a $50 write-up would:","IS: No impact (the gain bypasses the income statement).","SCF: No cash impact.","BS: Asset increases by $50; a Revaluation Surplus of $50 is recorded in Other Comprehensive Income within equity.","The only context where a write-up occurs under US GAAP is in purchase price allocation during an acquisition, where assets are marked to fair value as part of acquisition accounting."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Piper Sandler Interview","SA 2025, Houston Office, First round","Accounting","Advanced"]},{"id":"q-0639","t":"acct","l":"Advanced","s":90,"q":"Assuming a 25% tax rate, walk me through the 3-statement impact of a company repurchasing $100 of its bonds for $80 in cash.","k":["Starting on the IS...","Gain on debt extinguishment = $20 ($100 par - $80 paid).","Pre-tax income up $20.","Tax on gain = $5 ($20 * 25%).","Net Income up $15.","Moving onto the SCF...","Net Income +$15.","Subtract $20 gain (non-cash, non-operating).","CFF -$80 (cash paid for debt repurchase).","Net change in cash is -$85 ($15 - $20 - $80).","Finally, on the BS...","A: Cash -$85.","L: Debt -$100.","SE: Retained Earnings +$15.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in PJT Partners Interview","New York Office","Accounting","Advanced"]},{"id":"q-0640","t":"acct","l":"Advanced","s":90,"q":"Walk me through the three financial statements assuming a company sells a TV for $100 in revenue, with a 30% gross margin, a 33.3% tax rate, and the customer pays with $60 on accounts receivable and $40 in cash.","k":["Starting on the IS...","Revenue $100, COGS $70, Gross Profit $30","Pre-tax income $30, Taxes $10, NI $20","Moving onto the SCF...","NI +$20","AR increase of -$60","Inventory decrease of +$70","Net change in cash is +$30","Finally, on the BS...","A: Cash +$30, AR +$60, Inventory -$70, net +$20","L: No change","SE: Retained Earnings +$20 from NI","...and the Balance Sheet balances (+$20 = +$0 + +$20)"],"collection":"practice","topic":"Accounting","tags":["New","Reported in PJT Partners Interview","SA 2027, First round","Accounting","Advanced"]},{"id":"q-0641","t":"acct","l":"Advanced","s":90,"q":"A company sells a product for $300 in revenue, receiving $250 in cash and $50 on credit. Cost of Goods Sold is $60, of which $30 came from existing inventory on hand and $30 was purchased on credit at the time of sale. Depreciation expense is $30. Assuming a 25% tax rate, walk me through the impact on the three financial statements.\n\n\n\n\nFollow-up: Using the same information, calculate the company's Unlevered Free Cash Flow.","k":["Starting on the IS...","Revenue +300","COGS -60","Depreciation -30","Pre-tax income = 210","Taxes at 25% = 52.5","NI = 157.5","Moving onto the SCF...","NI +157.5","Add back depreciation +30","AR increase -50 (sold on credit)","Inventory decrease +30 (used existing inventory)","AP increase +30 (purchased COGS on credit)","Net change in cash = 157.5 + 30 - 50 + 30 + 30 = +197.5","Finally, on the BS...","A: Cash +197.5, AR +50, Inventory -30, PP&E -30, net +187.5","L: AP +30","SE: +157.5 from Retained Earnings (NI)","...and the Balance Sheet balances (187.5 = 30 + 157.5)","Follow-up: UFCF","EBIT = Revenue - COGS - D&A = 300 - 60 - 30 = 210","EBIT x (1 - Tax Rate) = 210 x 0.75 = 157.5","Plus D&A: +30","Less CapEx: 0","Less Change in NWC: AR +50, Inventory -30, AP +30, so Change in NWC = +50 - 30 - 30 = -10 (NWC decreased by 10, a source of cash)","UFCF = 157.5 + 30 - 0 + 10 = 197.5"],"collection":"practice","topic":"Accounting","tags":["New","Reported in PJT Partners Interview","SA 2027, First round","Accounting","Advanced"]},{"id":"q-0642","t":"acct","l":"Advanced","s":90,"q":"Leverage Ratio of 4x, Interest Coverage of 5x, and EBIT of $80m.\n\n\n\n\nIf its taxes paid in the year were $19.2 million, what is the tax rate?","k":["Answer: 30%","Interest Expense = EBIT/coverage ratio = 80/5 = 16","Pre-Tax Income (EBT) = EBIT - Interest Expense = 80 - 16 = 64","Tax Rate = Tax Expense / Pre-Tax Income = 19.2 / 64 = 30%","Note that the leverage ratio is just a distraction here; you don't need it to calculate the tax rate."],"collection":"practice","topic":"Accounting","tags":["Reported in Rothschild Interview","SA 2026","Accounting","Advanced"]},{"id":"q-0643","t":"acct","l":"Advanced","s":90,"q":"What is operating leverage and how does a decrease in sales affect a company with high operating leverage?\n\n\n\n\nFollow-up: What type of companies would have high operating leverage?","k":["Operating Leverage","Operating leverage measures the proportion of fixed costs in a company's cost structure relative to variable costs. A company with high operating leverage has a large base of fixed costs (rent, salaries, depreciation, R&D) and relatively low variable costs per unit sold.","Impact of a Sales Decrease","A sales decline disproportionately crushes profitability. Fixed costs remain constant regardless of revenue, so when sales fall, the company cannot reduce its cost base in proportion to the revenue decline. Every dollar of lost revenue drops almost entirely to the bottom line as lost profit. For example, if a company has 70% fixed costs and revenue drops 10%, EBITDA could decline 25-30% or more depending on the margin structure. This is the downside of operating leverage — it amplifies losses just as it amplifies gains.","Follow-up: High Operating Leverage Companies","Software / SaaS: Near-zero marginal cost per additional user; almost all costs are fixed (engineering, servers, sales team).","Airlines: Massive fixed costs (aircraft leases, crew salaries, airport gates) with relatively low variable cost per passenger.","Hotels & Hospitality: Fixed property costs, staffing, and maintenance regardless of occupancy.","Telecom: Heavy infrastructure investment (cell towers, fiber) with low marginal cost per subscriber.","Manufacturing with heavy capital investment: Auto manufacturers, semiconductor fabs — high fixed costs in plant and equipment.","The common thread: businesses that require large upfront or ongoing fixed investments to operate, where the incremental cost of serving one more customer is minimal."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Stellex Capital Interview","SA 2027","Accounting","Advanced"]},{"id":"q-0644","t":"acct","l":"Advanced","s":90,"q":"Part 1: How can a supermarket improve its working capital?\n\n\n\n\nPart 2: How would your answer change for a healthcare IT (HCIT) company?","k":["Part 1: Supermarket","Negotiate longer payment terms with suppliers (increase accounts payable).","Reduce inventory levels through better demand forecasting and just-in-time inventory management.","Accelerate cash collection (though supermarkets typically operate on cash basis).","Part 2: Healthcare IT Company","Negotiate shorter payment cycles with hospital/healthcare customers (reduce days sales outstanding).","Implement milestone-based billing to accelerate cash collection.","Extend payment terms with software vendors and service providers.","Minimize inventory (less relevant for software/services business).","The key difference: supermarkets focus on physical inventory management and supplier terms, while HCIT companies focus on receivables collection and service delivery timing."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Advanced"]},{"id":"q-0645","t":"acct","l":"Advanced","s":90,"q":"A company raises $100 of preferred stock with a 9% coupon. The proceeds are invested in $100 of long-term assets that yield 10% annually. Assume a 30% corporate tax rate.\n\n\n\n\nPart 1: Walk me through the 3 statements at the time of the transaction (Year 0).\n\n\n\n\nPart 2: Walk me through the 3 statements after one year has passed (Year 1).","k":["Year 0 (Issuance)","Starting on the IS...","No change.","Moving onto the SCF...","CFI -$100 for long-term assets.","CFF +$100 from preferred stock issuance.","Net change in cash is $0.","Finally, on the BS...","A: Long-term assets +$100.","L: No change.","SE: Preferred Stock +$100.","...and the Balance Sheet balances.","Year 1","Starting on the IS...","Interest/Investment Income +$10 ($100 * 10%).","Pre-tax income +$10.","Taxes +$3 ($10 * 30%).","Net Income +$7.","Less: Preferred Dividends $9 (not tax-deductible).","Net Income to Common -$2.","Moving onto the SCF...","Net Income +$7.","Cash from Operations is $7 (after tax).","CFF -$9 for preferred dividend payment.","Net change in cash is -$2.","Finally, on the BS...","A: Cash -$2.","L: No change.","SE: Retained Earnings -$2, Preferred Stock unchanged. Net -$2.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Advanced"]},{"id":"q-0646","t":"acct","l":"Advanced","s":90,"q":"MULTI-STEP: Assume a 30% tax rate. Walk me through the 3 statements for the following events:\n\n\n\n\nPart 1) In Year 0, a company raises $100m of debt with 10% annual cash interest.\n\n\n\n\nPart 2) Trace the impact in Year 1, after one year of interest has accrued and been paid.","k":["Year 0 (Issuance)","IS: No change","CFS: CFF +$100m, net cash +$100m","BS: Cash +$100m, Debt +$100m","Year 1","Starting on the IS...","Interest expense +$10m ($100m * 10%)","Pre-tax income down $10m","NI down $7m ($10m * (1 - 30%))","Moving onto the SCF...","NI down $7m","There are no non-cash charges to add back. The cash interest payment is already reflected in the Net Income figure.","Net change in cash is -$7m","Finally, on the BS...","A: Cash -$7m","L: Debt unchanged at $100m","SE: Retained Earnings -$7m","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Advanced"]},{"id":"q-0647","t":"acct","l":"Advanced","s":90,"q":"Assuming a 40% tax rate, walk me through the impact on the 3 financial statements after one year of a $300m loan with 10% PIK interest.","k":["Starting on the IS...","Interest expense +$30m ($300m * 10%)","Pre-tax income down $30m","NI down $18m ($30m * (1 - 40%))","Moving onto the SCF...","NI down $18m","Add back $30m PIK interest (non-cash)","Net change in cash is +$12m","Finally, on the BS...","A: Cash +$12m","L: Debt +$30m (PIK portion capitalized)","SE: Retained Earnings -$18m","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Advanced"]},{"id":"q-0648","t":"acct","l":"Advanced","s":90,"q":"MULTI-STEP:\n\n\n\n\nPart 1: How do you account for a 40% ownership stake in a joint venture versus a 60% ownership stake?\n\n\n\n\nPart 2: Now, assume the JV you own 40% of generates $100m in net income and pays out $30m in dividends to its owners. Walk through the 3-statement impact on your company from your share of these events. Assume a 25% tax rate on dividends received.","k":["Part 1: Accounting Method","40% Ownership: Accounted for using the Equity Method. Your investment is a single line item on the asset side of the Balance Sheet. You recognize your proportionate share (40%) of the JV's net income on your Income Statement as a single line, \"Equity Method Earnings.\"","60% Ownership: This is a controlling stake, requiring Consolidation. You would combine 100% of the JV's financial statements with your own and then create a \"Noncontrolling Interest\" (NCI) line item on your statements to account for the 40% you don't own.","Part 2: 3-Statement Impact (40% Ownership)","Your share is: 40% of $100M NI = $40M; 40% of $30M dividend = $12M.","Income Statement:","A single line item, \"Earnings from Equity Method Investment,\" appears, increasing Pre-Tax Income by +$40M.","Your overall Tax Expense will increase by $3M (25% tax on the $12M dividend received, per the problem's assumption). Note: In practice under U.S. GAAP, corporate investors may qualify for a Dividends Received Deduction, which would reduce the taxable portion.","Assuming no other income, Net Income increases by $37M ($40M - $3M).","Cash Flow Statement:","Start with Net Income: +$37M.","Subtract the non-cash Earnings from Equity Method Investment: -$40M.","The cash dividend received ($12M) is classified under Cash Flow from Operations under U.S. GAAP.","Cash Flow from Operations: -$3M + $12M = +$9M.","Net Change in Cash is +$9M.","Balance Sheet:","Assets: Cash increases by +$9M. The \"Investment in Affiliate\" account increases by your share of NI ($40M) and decreases by the dividend received ($12M), for a net increase of +$28M. Total assets increase by $37M.","Liabilities & Equity: Retained Earnings increases by Net Income, which is +$37M.","The Balance Sheet remains balanced (Assets +$37M, L+SE +$37M)."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Advanced"]},{"id":"q-0649","t":"acct","l":"Advanced","s":90,"q":"Assume a 25% tax rate.\n\n\n\n\nPart 1: Walk me through the 3 statements for a SaaS company at the point of sale for a $120 annual subscription paid in cash upfront.\n\n\n\n\nPart 2: Now, walk me through the 3 statements after one month has passed.","k":["Part 1: At Point of Sale","Starting on the IS...","No revenue recognized yet (deferred revenue created)","Moving onto the SCF...","Cash from operations +$120","Net change in cash +$120","Finally, on the BS...","A: Cash +$120","L: Deferred Revenue +$120","SE: No change","Part 2: After One Month","Starting on the IS...","Revenue recognized: $120 / 12 = $10","Pre-tax income +$10","NI +$7.50 ($10 * (1 - 25%))","Moving onto the SCF...","NI +$7.50","Decrease in Deferred Revenue: -$10","Net change in cash -$2.50 (taxes paid)","Finally, on the BS...","A: Cash -$2.50","L: Deferred Revenue -$10","SE: Retained Earnings +$7.50","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Advanced"]},{"id":"q-0650","t":"acct","l":"Advanced","s":90,"q":"A company receives $10 million in cash upfront for a 2-year subscription.\n\n\n\n\nAssume revenue is recognized straight-line and the tax rate is 20%.\n\n\n\n\nWalk me through the 3 financial statements for Year 0 (at inception), Year 1, and Year 2.","k":["Year 0 (At Inception)","IS: No change (revenue not yet recognized).","CFS: CFO +$10M (cash collected upfront). Net cash +$10M.","BS: Cash +$10M, Deferred Revenue (Liability) +$10M.","Year 1","Starting on the IS...","Revenue +$5M ($10M / 2 years).","Assuming no COGS, Pre-tax income +$5M.","Tax +$1M ($5M * 20%).","Net Income +$4M.","Moving onto the SCF...","Net Income +$4M.","Deferred Revenue decreases by $5M (subtract in CFO).","Net change in cash is -$1M.","Finally, on the BS...","A: Cash -$1M.","L: Deferred Revenue -$5M.","SE: Retained Earnings +$4M.","...and the Balance Sheet balances.","Year 2","Starting on the IS...","Revenue +$5M (remaining half).","Pre-tax income +$5M.","Tax +$1M.","Net Income +$4M.","Moving onto the SCF...","Net Income +$4M.","Deferred Revenue decreases by $5M (subtract in CFO).","Net change in cash is -$1M.","Finally, on the BS...","A: Cash -$1M.","L: Deferred Revenue -$5M (now zero).","SE: Retained Earnings +$4M.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Advanced"]},{"id":"q-0651","t":"acct","l":"Advanced","s":90,"q":"What is operating leverage?\n\n\n\n\nUsing Peloton as an example, how would you analyze its degree of operating leverage?","k":["Operating leverage measures how revenue changes affect EBIT. High operating leverage means high fixed costs relative to variable costs, so revenue growth drives disproportionate profit growth (and vice versa).","Degree of Operating Leverage = % Change in EBIT / % Change in Revenue","Peloton analysis:","High fixed costs: Content production, studios, technology infrastructure","Variable costs: Bike manufacturing, shipping (partially variable)","During growth: Strong operating leverage as subscription revenue scales","During decline: Negative leverage exposed - revenue drops caused larger EBIT declines","Calculate by comparing period-over-period EBIT % change vs. revenue % change."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Advanced"]},{"id":"q-0652","t":"acct","l":"Advanced","s":90,"q":"Assuming a 20% tax rate, walk me through the 3-statement impact of a company recognizing $10 in Revenue by selling inventory that had a COGS of $5.","k":["Starting on the IS...","Revenue +$10.","COGS +$5.","Gross Profit +$5.","Pre-tax income +$5.","Taxes +$1 ($5 * 20%).","NI +$4.","Moving onto the SCF...","Cash received from sale = +$10.","Cash paid for taxes = -$1.","Net change in cash = +$9. (Alternatively, using the indirect method: NI +$4, Change in Inventory +$5 = +$9).","Finally, on the BS...","A: Cash +$9, Inventory -$5, net +$4.","L: No change.","SE: Retained Earnings +$4.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Accounting","Advanced"]},{"id":"q-0653","t":"acct","l":"Advanced","s":90,"q":"MULTI-STEP: A company undertakes the following transactions. Assume a 40% tax rate.\n\n\n\n\nPart 1) A company issues $100 in Preferred Stock to purchase $100 in long-term real estate investments. The Preferred Stock has an 8% coupon rate, and the investments yield 10%. Walk me through the 3 statements immediately after the initial purchase.\n\n\n\n\nPart 2) Now, walk me through the 3 statements after one year has passed.\n\n\n\n\nPart 3) At the end of Year 2, the real estate investments have doubled in value. The company sells them for $200 and uses the proceeds to repay the Preferred Stock. Walk me through the 3 statements reflecting all activity during Year 2.","k":["Part 1: Initial Purchase","IS: No change.","CFS: CFI -$100 (investment), CFF +$100 (preferred stock). Net cash unchanged.","BS: A +$100 (investments), L +$100 (preferred stock), SE unchanged.","Part 2: After One Year","Starting on the IS...","Investment income +$10 ($100 * 10%).","Pre-tax income +$10.","Tax -$4 ($10 * 40%).","Net Income +$6.","Less Preferred dividends -$8 ($100 * 8%, reduces net income available to common).","Net Income to Common -$2.","Moving onto the SCF...","Net Income +$6.","Cash from Operations is $6 (after tax).","CFF -$8 (preferred dividend payment).","Net change in cash is -$2.","Finally, on the BS...","A: Cash -$2.","L: No change.","SE: Retained Earnings -$2, Preferred Stock unchanged. Net -$2.","...and the Balance Sheet balances.","Part 3: Year 2 (Sale and Repayment)","Starting on the IS...","Investment Income: +$10.","Gain on Sale of Investment: +$100 ($200 proceeds - $100 book value).","Pre-Tax Income: +$110.","Taxes (40%): -$44.","Net Income: +$66.","Less: Preferred Dividends -$8.","Net Income to Common: +$58.","Moving onto the SCF...","Start with Net Income: +$66.","Adjust for non-cash items: Subtract Gain on Sale (-$100).","Cash Flow from Operations: -$34.","Cash Flow from Investing: +$200 (Proceeds from sale).","Cash Flow from Financing: -$100 (Repayment of Preferred Stock) and -$8 (Preferred dividend).","Net Change in Cash: -$34 + $200 - $108 = +$58.","Finally, on the BS...","A: Cash +$58, Investments -$100. Net change in Assets is -$42.","L: No change.","SE: Preferred Stock -$100 (repaid), Retained Earnings +$58. Net change in SE is -$42.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Superday","Accounting","Advanced"]},{"id":"q-0654","t":"acct","l":"Advanced","s":90,"q":"An M&A transaction causes book depreciation to increase by $200m, but this additional depreciation is not tax-deductible (i.e., cash taxes do not change).\n\n\n\n\nAssuming a 40% tax rate, walk me through the impact on the three financial statements in the first year after the acquisition.","k":["Starting on the IS...","D&A expense increases by $200M.","Pre-tax income decreases by $200M.","Book tax expense decreases by $80M ($200M * 40%) due to lower book income, but cash taxes are unchanged.","This creates a Deferred Tax Asset (DTA) of $80M (since Cash Tax > Book Tax).","Net Income decreases by $120M.","Moving onto the SCF...","Net Income -$120M.","Add back D&A of $200M (non-cash).","Subtract increase in DTA -$80M (Non-cash tax benefit in NI).","Net change in cash is 0.","Finally, on the BS...","A: Cash 0, PP&E -$200M, DTA +$80M. Net Assets -$120M.","SE: Retained Earnings -$120M.","...and the Balance Sheet balances."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Superday","Accounting","Advanced"]},{"id":"q-0655","t":"acct","l":"Advanced","s":90,"q":"At the beginning of the year, a company has $200 in Net Operating Losses (NOLs). In the current year, the company generates $100 in pre-tax income.\n\n\n\n\nAssuming a 20% tax rate, walk me through the 3 statements for the current year.","k":["Starting on the IS...","Pre-tax income = $100.","Company utilizes $100 of NOLs to offset taxable income.","Cash taxes paid = $0.","Book tax expense = $20 ($100 * 20%).","Net Income = $80.","Moving onto the SCF...","Net Income +$80.","Add back $20 (DTA utilization/non-cash tax expense).","Net change in cash +$100.","Finally, on the BS...","A: Cash +$100. DTA decreases by $20 (NOLs utilized: $100 * 20%). Net +$80.","L: No change.","SE: Retained Earnings +$80.","...and the Balance Sheet balances.","Remaining NOLs: $200 - $100 = $100 (DTA of $20 remains)."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Superday","Accounting","Advanced"]},{"id":"q-0656","t":"acct","l":"Advanced","s":90,"q":"Part 1: A company owns 30% of another company. How is this investment accounted for on the balance sheet, and how does it factor into the Enterprise Value calculation?\n\n\n\n\nPart 2: Now, assume the ownership increases to 80%. The financials are now consolidated, but an analyst forgets to include the subsidiary's EBITDA in the consolidated EBITDA figure. How would this error impact the calculated EV/EBITDA multiple?","k":["Part 1: 30% Ownership","Accounted for using equity method on the balance sheet.","Investment shown as a single line item (Equity Method Investment).","Parent's share of investee's earnings flows through IS below EBITDA.","In EV calculation, subtract the fair value of this minority investment (it's a non-operating asset).","Part 2: 80% Ownership with Error","At 80%, subsidiary is consolidated (100% of financials included).","If analyst forgets subsidiary's EBITDA, the denominator is understated.","EV in the numerator is correct (reflects market value).","Result: EV/EBITDA multiple appears artificially high.","Additionally, Noncontrolling Interest (20%) must be added to EV, but the error is primarily in EBITDA understatement."],"collection":"practice","topic":"Accounting","tags":["Reported in Unspecified Interview","Superday","Accounting","Advanced"]},{"id":"q-0657","t":"acct","l":"Advanced","s":90,"q":"What has the greatest effect on Net Income: a 10% change in volume, a 10% change in price, or a 10% change in SG&A?","k":["A 10% change in price has the greatest effect on Net Income.","Price flows directly to revenue at 100% margin - every dollar of price increase drops straight to the bottom line with no incremental cost. A 10% increase in volume also increases revenue, but it carries associated variable costs (COGS), so only the incremental gross profit flows through. A 10% change in SG&A affects only the SG&A line, which is typically smaller than total revenue, so the absolute dollar impact is smaller.","Ranking by impact on NI: Price > Volume > SG&A (in most cases). This is a core concept in operating leverage and pricing strategy."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Unspecified Interview","SA 2027, Superday","Accounting","Advanced"]},{"id":"q-0658","t":"acct","l":"Advanced","s":90,"q":"Walk me through the 3 financial statements with $100 debt at 10% interest and $100 PPE at 10% depreciation with a 40% tax rate.\n\n\n\n\nWalk through this at Time 0 and then at Year 1.","k":["Time 0","Starting on the IS...","No changes, as the transaction is just recorded.","Moving onto the SCF...","No cash flow impact since it’s only recorded.","Finally, on the BS...","A: PPE +100","L: Debt +100","SE: No change","Year 1","Starting on the IS...","$10 interest expense and $10 depreciation reduce pre-tax income by $20.","Assuming a 40% tax rate, Net Income decreases by $12.","Moving onto the SCF...","Start with NI down $12.","Add back $10 depreciation as a non-cash expense in CFO.","Net cash decreases by $2 if the $10 interest was paid in cash.","Finally, on the BS...","A: PPE down $10 (depreciation), Cash down $2; net assets down $12.","L: Debt unchanged.","SE: Retained Earnings down $12.","...and the Balance Sheet balances"],"collection":"practice","topic":"Accounting","tags":["Reported in Wells Fargo Interview","Accounting","Advanced"]},{"id":"q-0659","t":"acct","l":"Advanced","s":90,"q":"How can a company have positive Net Income but negative Cash Flow in the same year? Give as many reasons as you can.","k":["Large CapEx: Heavy investment in PP&E or acquisitions reduces cash but does not reduce NI (CapEx is capitalized, not expensed).","Working capital build: Increases in accounts receivable (sales on credit not yet collected), inventory buildup, or decreases in accounts payable all consume cash without affecting NI.","Debt principal repayment: Mandatory amortization or refinancing reduces cash but does not hit the Income Statement (only interest expense does).","Large dividend payments or share buybacks: These reduce cash in CFF but do not affect NI.","One-time non-cash gains: Gain on sale of assets inflates NI but the actual cash proceeds may be less than the NI boost (and the gain is reclassified to CFI).","Prepaid expenses: Paying upfront for multi-year contracts reduces cash but the expense is recognized over time.","Tax timing differences: Accrued tax expense on the IS may be less than actual cash taxes paid."],"collection":"practice","topic":"Accounting","tags":["New","Reported in Wells Fargo Interview","SA 2026, First round","Accounting","Advanced"]},{"id":"q-0660","t":"val","l":"Basic","s":90,"q":"How do we find the diluted share count?","k":["Pull basic shares from the latest filing, then adjust:","Add net in‑the‑money options/warrants via the Treasury Stock Method.","Add all RSUs.","Add shares from in‑the‑money convertibles using the if‑converted method.","The sum equals diluted shares."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Allen & Company Interview","SA 2026","Enterprise & Equity Value","Basic"]},{"id":"q-0661","t":"val","l":"Basic","s":90,"q":"When would you focus on valuing a company's equity rather than their enterprise value, and why?","k":["You focus on equity value when you care about the portion of value attributable specifically to shareholders, such as evaluating stock price performance or assessing per-share metrics.","Enterprise value is more relevant when you’re comparing operating performance across companies that have different capital structures.","In situations like acquisitions that affect the entire capital structure, enterprise value is often the starting point. But if your primary consideration is the shareholder impact or any equity-based return, you focus on equity value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Bank of America Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0662","t":"val","l":"Basic","s":90,"q":"Where do we find Non-Controlling Interest (NCI) on the Income Statement?","k":["Non-Controlling Interest appears at the bottom of the Income Statement, below Net Income. The IS shows \"Net Income Attributable to Non-Controlling Interests\" as a separate line item that is subtracted from consolidated Net Income to arrive at \"Net Income Attributable to Common Shareholders.\"","The consolidated IS includes 100% of the subsidiary's revenue and expenses, but the NCI line item at the bottom allocates the minority's share of earnings away from the parent's shareholders."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Bank of America Interview","SA 2026, New York Office, Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0663","t":"val","l":"Basic","s":90,"q":"How could two companies have the same financial profile (e.g., revenue, EBITDA) but different Enterprise Values?","k":["Enterprise Value reflects the market's assessment of a company's future prospects, not just current financials. Two companies with identical revenue and EBITDA can have different EVs due to:","Growth rates - higher expected growth commands a premium.","Margin trajectory - improving vs. declining margins.","Revenue quality - recurring/contractual vs. one-time revenue.","Industry and competitive positioning.","FCF conversion - same EBITDA but different CapEx and working capital needs.","Risk profile - customer concentration, regulatory risk, geographic exposure.","Management quality and track record.","TAM (Total Addressable Market) and market share potential."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Barclays Interview","SA 2026, New York Office, Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0664","t":"val","l":"Basic","s":90,"q":"How do you find a company's market cap using only its 10-K?","k":["The cover page discloses “aggregate market value of common stock held by non‑affiliates” as of the last business day of the second fiscal quarter—effectively the market cap on that date."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Centerview Partners Interview","SA 2026, New York office, Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0665","t":"val","l":"Basic","s":90,"q":"What will happen to equity value as net debt increases?","k":["If net debt rises, the enterprise value could stay the same (theoretically), so equity value could decrease to keep EV constant (assuming no other changes).","Another way to see it: higher net debt often signals more financial risk, possibly reducing the market's valuation of equity."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Citi Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0666","t":"val","l":"Basic","s":90,"q":"Is enterprise value or equity value more important in an M&A transaction? Why?","k":["Enterprise value is more important in M&A because it represents the total cost of acquiring the business, including the assumption of debt and the benefit of acquiring cash.","An acquirer must pay off or assume existing debt and receives any cash on hand.","EV provides a capital-structure-neutral view, making it easier to compare bids across different financing structures.","EV-based multiples (EV/EBITDA) are the standard for benchmarking deal pricing.","Equity value matters for determining the per-share offer price to shareholders, but EV is the more meaningful metric for evaluating the total transaction cost."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in DC Advisory Interview","New York Office, Second round","Enterprise & Equity Value","Basic"]},{"id":"q-0667","t":"val","l":"Basic","s":90,"q":"If a company has $6 per share with 50 shares outstanding, $100 in cash, and an Enterprise Value (EV) of $500, what is the company's debt?","k":["First, calculate the Equity Value: $6/share * 50 shares = $300.","Using the EV formula: EV = Equity Value + Debt - Cash","$500 = $300 + Debt - $100 ⇒ Debt = $300"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0668","t":"val","l":"Basic","s":90,"q":"How does paying down $300 of debt affect the Enterprise Value?","k":["No change.","Remember: EV = Equity Value + Debt - Cash","According to the enterprise value formula, the changes in debt and cash offset each other.","Since paying down debt is a capital structure change, it’s important to recognize that this action does not impact the company's enterprise value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0669","t":"val","l":"Basic","s":90,"q":"A company trades at 7x EV/EBITDA with $100M in EBITDA, $100M in cash, $300M in debt, and 100M shares outstanding.\n\n\n\n\nWhat is the implied share price?","k":["Answer: $5","Calculation:","Enterprise Value (EV) = Multiple x EBITDA = 7 x $100M = $700M","Equity Value = EV + Cash – Debt = $700M + $100M - $300M = $500M","Implied Share Price = Equity Value / Shares Outstanding = $500M / 100M = $5"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0670","t":"val","l":"Basic","s":90,"q":"You have an EPS of $2, 100 shares outstanding, a P/E of 4x, $200 in debt, $75 in NCI, $50 in cash and $100 in inventory.\n\n\n\n\nWhat is the Enterprise Value (EV)?","k":["Answer: $1,025","Calculation:","Net Income (NI) = EPS * Shares Outstanding = $2 * 100 = $200","Equity Value = P/E * NI = 4 * $200 = $800","EV = Equity Value + Debt + NCI – Cash = $800 + $200 + $75 - $50 = $1,025"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0671","t":"val","l":"Basic","s":90,"q":"A company issues $500m in new shares.\n\n\n\n\nHow do equity value, enterprise value, EV/EBITDA, and P/E change?","k":["Impacts:","Equity Value: Increases by $500m (cash raised).","Enterprise Value: Unchanged (Equity +$500m, Cash +$500m offset).","EV/EBITDA: Unchanged (EV and EBITDA unchanged).","P/E: Increases (Equity Value increases, Net Income initially unchanged)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0672","t":"val","l":"Basic","s":90,"q":"Why add Noncontrolling Interest (NCI) to Enterprise Value?","k":["When a company owns more than 50% of another company, it must consolidate the entire financial performance of that subsidiary into its own financial statements (even if it doesn't own 100%).","This means the parent company reports the subsidiary’s full (100%) financial results. When consolidating a subsidiary not fully owned, metrics like EBITDA reflect 100% of the sub.","Therefore, to make EV comparable to metrics like EBITDA, you need to include Noncontrolling Interest when calculating Enterprise Value to ensure that both your numerator and denominator fully reflect 100% ownership of the subsidiary."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0673","t":"val","l":"Basic","s":90,"q":"A company trades at 11x EV/EBITDA with $100M EBITDA, $100M cash, $300M debt, 100M shares.\n\n\n\n\nWhat is the implied share price?","k":["Answer: $9","Calculation:","EV = 11 * $100M = $1,100M","Equity Value = $1,100M + $100M - $300M = $900M","Share Price = $900M / 100M Shares Outstanding = $9"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0674","t":"val","l":"Basic","s":90,"q":"A firm shows share price of $6, cash of $100 million, total enterprise value of $500 million, and 100 million shares outstanding.\n\n\n\n\nWhat is its current debt balance?","k":["Answer: $0","EqV = Share Price * Shares Outstanding = $6 * 100m = $600m","TEV = EqV + Debt - Cash","$500 = $600 + Debt - $100","Debt = $500 - $600 + $100 = $0"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0675","t":"val","l":"Basic","s":90,"q":"A company has share price $6, 50 million shares, and $100 million cash.\n\n\n\n\nWhat is enterprise value (assuming no debt)?","k":["Answer: $200m","EqV = 6 x 50m = $300m.","Basic EV formula = EqV + Debt - Cash","EV = 300 + 0 - 100.","EV = $200m."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0676","t":"val","l":"Basic","s":90,"q":"The company issues $300 million of new equity that is not invested in the business.\n\n\n\n\nWhat happens to enterprise value?","k":["EV is unchanged. Equity +300, Cash +300, net zero on EV formula."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0677","t":"val","l":"Basic","s":90,"q":"A $100 fine is announced.\n\n\n\n\nWhat is the impact on enterprise value?","k":["No impact on TEV.","Either reduces cash (if immediately paid) or is recognized as a liability (fine payable), offsetting the decrease in equity value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0678","t":"val","l":"Basic","s":90,"q":"You are given a company's share price, number of shares outstanding, cash balance, and a relevant peer-derived EV/EBITDA multiple.\n\n\n\n\nHow would you calculate the implied value of the company's debt?","k":["Steps:","Calculate Equity Value: Share Price × Shares Outstanding.","Estimate EBITDA from comparable analysis or financial statements.","Calculate Enterprise Value: EBITDA × Peer EV/EBITDA Multiple.","Solve for Debt: EV = Equity Value + Debt - Cash → Debt = EV - Equity Value + Cash."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","First round","Enterprise & Equity Value","Basic"]},{"id":"q-0679","t":"val","l":"Basic","s":90,"q":"In a public comparables analysis, why is the EV/Earnings multiple conceptually flawed and therefore not used?","k":["EV/Earnings is conceptually flawed due to a mismatch between numerator and denominator:","Enterprise Value represents value to all stakeholders (debt and equity holders).","Earnings (Net Income) is after interest expense, representing value only to equity holders.","This creates inconsistency: EV should be paired with pre-interest metrics (EBITDA, EBIT, Unlevered FCF), while Earnings should be paired with equity value (P/E ratio).","Using EV/Earnings would make companies with different capital structures incomparable, defeating the purpose of using capital structure-neutral metrics."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0680","t":"val","l":"Basic","s":90,"q":"When bridging from Enterprise Value to Equity Value, why are Non-Controlling Interest (NCI) and Preferred Stock subtracted?","k":["Both NCI and Preferred Stock are subtracted because:","Non-Controlling Interest (NCI):","When a company consolidates a majority-owned subsidiary, it includes 100% of the subsidiary's value in Enterprise Value.","However, the parent doesn't own 100% of the equity - minority shareholders own a portion.","NCI represents the claim that minority shareholders have on the consolidated entity.","Must subtract NCI to arrive at equity value attributable only to common shareholders of the parent.","Preferred Stock:","Preferred shareholders have a claim senior to common equity but junior to debt.","Enterprise Value includes all claims, but equity value refers specifically to common equity.","Must subtract preferred stock value to isolate value for common shareholders."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0681","t":"val","l":"Basic","s":90,"q":"A company has $50 in cash, $20 in short-term investments, a $500 loan, $20 in minority interest, and 200 shares outstanding at $10 per share. What is the Enterprise Value?","k":["Answer: $2,450","Calculation:","Equity Value = 200 shares x $10 = $2,000","EV = Equity Value + Debt - Cash - Short-Term Investments + Minority Interest","EV = $2,000 + $500 - $50 - $20 + $20 = $2,450","Short-term investments are subtracted because, like cash, they are non-operating liquid assets. Minority interest is added because EV represents the value of the entire enterprise, including portions owned by minority shareholders."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Evercore Interview","M&A group, New York Office, First round","Enterprise & Equity Value","Basic"]},{"id":"q-0682","t":"val","l":"Basic","s":90,"q":"How does raising $200 million in debt affect Enterprise Value?","k":["Raising $200M in debt has no immediate impact on Enterprise Value.","When a company raises debt, it receives $200M in cash and adds $200M in debt. In the EV bridge:","EV = Equity Value + Debt - Cash","Debt increases by $200M, Cash increases by $200M.","The two offset, so EV is unchanged.","Equity Value also remains unchanged at the moment of issuance (assuming no immediate market reaction). However, what the company does with the cash (acquisitions, buybacks, dividends, operations) will affect EV and Equity Value going forward."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Evercore Interview","M&A group, New York Office, First round","Enterprise & Equity Value","Basic"]},{"id":"q-0683","t":"val","l":"Basic","s":90,"q":"Walk me from Enterprise Value to a per-share stock price.","k":["Steps:","Start with Enterprise Value.","Subtract Net Debt (Debt - Cash).","Subtract Noncontrolling Interest and Preferred Stock.","This gives you Equity Value.","Divide Equity Value by Diluted Shares Outstanding.","Result is the per-share stock price."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Goldman Sachs Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0684","t":"val","l":"Basic","s":90,"q":"A company has an Enterprise Value (EV) of $200 and a face value of debt of $300. What is the equity value? Why?","k":["Equity Value can be calculated using the formula: EV = Equity Value + Debt - Cash.","However, since no cash is mentioned, we can rearrange the formula to find Equity Value:","Equity Value = EV - Debt","Equity Value = $200 - $300 = -$100","The negative result means creditors’ claims exceed EV. Common equity is effectively out-of-the-money and would be worth ≈ $0 in practice, indicating distress.","In practice, a company's market cap can’t be negative (shares would trade at (or near) zero), but an implied negative number like this is common in distress modeling exercises."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Greenhill & Co. Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0685","t":"val","l":"Basic","s":90,"q":"A company with an Enterprise Value of $5 billion has no debt and no cash.\n\n\n\n\nIf it issues $2 billion in new debt and holds the proceeds as cash, what is its new Enterprise Value and Equity Value?","k":["Answer: EV = $5B, Equity Value = $5B","EV = Equity Value + Debt - Cash.","Initially: $5B = Equity Value + $0 - $0, so Equity Value = $5B.","After issuance: EV = Equity Value + $2B - $2B = Equity Value.","Enterprise Value remains $5B (debt and cash offset).","Equity Value remains $5B (no change to underlying business value)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Greenhill & Co. Interview","M&A group, First round","Enterprise & Equity Value","Basic"]},{"id":"q-0686","t":"val","l":"Basic","s":90,"q":"How would raising capital through a primary share issuance affect earnings per share (EPS)? Assume proceeds are held in cash.","k":["EPS declines because the share count rises while net income remains relatively flat.","The higher denominator dilutes EPS.","Interest income on the new cash slightly lifts net income but rarely offsets the dilution."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Guggenheim Partners Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0687","t":"val","l":"Basic","s":90,"q":"You are evaluating two potential acquisition targets with identical financial performance and the same equity value.\n\n\n\nCompany A has $100 in cash and no debt.\nCompany B has no cash and $100 in debt.\n\n\n\nWhich company would you prefer to acquire and why?","k":["Company A is preferable.","Since both have the same Equity Value (Price), Company A has a significantly lower Enterprise Value (effectively $200 less than B).","Assuming Equity Value = X:","EV(A) = X - 100 Cash.","EV(B) = X + 100 Debt.","You are paying the same upfront price for both (Equity Value), but with Company A you get $100 cash, whereas with B you assume $100 debt. A is much cheaper."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Guggenheim Partners Interview","New York office","Enterprise & Equity Value","Basic"]},{"id":"q-0688","t":"val","l":"Basic","s":90,"q":"Walk me from Enterprise Value to Equity Value for the following two companies:\n\n\n\nCompany A: EV of $1.5B, Debt of $500M, Cash of $200M\nCompany B: EV of $1.0B, Debt of $100M, Cash of $500M","k":["Equity Value = EV - Debt + Cash","Company A:","Equity Value = $1.5B - $500M + $200M = $1.2B","Company B:","Equity Value = $1.0B - $100M + $500M = $1.4B"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Guggenheim Partners Interview","M&A group, First round","Enterprise & Equity Value","Basic"]},{"id":"q-0689","t":"val","l":"Basic","s":90,"q":"Part 1: If a company finds $1,000 in cash on the ground, what happens to its Enterprise Value?\n\n\n\n\nPart 2: If EBITDA declines by 50%, what happens to the EV/EBITDA multiple?","k":["Part 1","Enterprise Value does not change. EV = Equity Value + Debt - Cash. The $1,000 in cash increases Equity Value by $1,000 (assets increase), but it also increases the Cash subtraction by $1,000. The two effects cancel out, leaving EV unchanged.","Part 2","Assuming EV stays constant (same market cap and debt), the EV/EBITDA multiple doubles. If EBITDA was $100 and EV was $1,000 (10x), after a 50% decline EBITDA = $50, and EV/EBITDA = $1,000 / $50 = 20x. However, in practice, EV would likely decline as the market reprices the company, partially offsetting the multiple expansion."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Houlihan Lokey Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0690","t":"val","l":"Basic","s":90,"q":"After an acquisition, how are the pro-forma Enterprise Value and Equity Value of the combined company calculated?","k":["Pro-Forma Equity Value","Acquirer Equity Value + Value of Consideration Paid (cash, stock, or both).","If all-stock: Acquirer EqV + (shares issued × acquirer share price).","If cash/debt: Typically just acquirer's standalone equity value (no dilution).","Pro-Forma Enterprise Value","Sum of standalone Enterprise Values: Acquirer TEV + Target TEV.","Alternatively: PF Equity Value + PF Net Debt + PF Preferred Stock + PF NCI.","PF Net Debt = (Acquirer Debt + Target Debt + New Debt Issued) - (Acquirer Cash + Target Cash - Cash Used).","Key: Account for new debt issued for financing and cash used to fund the deal when calculating pro-forma metrics."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in J.P. Morgan Interview","SA 2025","Enterprise & Equity Value","Basic"]},{"id":"q-0691","t":"val","l":"Basic","s":90,"q":"What is the difference between diluted and basic shares outstanding? What securities get converted in an acquisition?","k":["Basic vs. Diluted Shares","Basic shares: The actual number of common shares currently issued and outstanding.","Diluted shares: Basic shares plus the impact of all potentially dilutive securities (options, warrants, RSUs, convertible debt, convertible preferred stock) using the Treasury Stock Method for options/warrants and the if-converted method for convertibles.","The Treasury Stock Method assumes in-the-money options are exercised, the company receives the exercise proceeds, and buys back shares at the current market price. Net dilution = options exercised - shares repurchased.","What Gets Converted in an Acquisition?","All in-the-money options and warrants are typically exercised or cashed out (using the TSM at the offer price, not the current market price).","Convertible debt and convertible preferred stock are typically converted to equity or redeemed for cash, depending on the deal terms.","RSUs and restricted stock vest (accelerated vesting is common in change-of-control provisions).","Out-of-the-money options may be cancelled or converted into acquirer options."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in J.P. Morgan Interview","SA 2025, Healthcare group, SF Office, Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0692","t":"val","l":"Basic","s":90,"q":"A company trades at 8x EV/EBITDA. What additional information do you need to calculate the implied share price?\n\n\n\n\nFollow-up: Given the information, calculate the implied share price.","k":["You need the following additional information:","EBITDA (to calculate Enterprise Value = 8x x EBITDA)","Net Debt (Total Debt minus Cash) to bridge from EV to Equity Value","Minority Interest and Preferred Stock (if any)","Diluted Shares Outstanding","Calculation:","Enterprise Value = EBITDA x 8x","Equity Value = EV - Net Debt - Minority Interest - Preferred Stock","Implied Share Price = Equity Value / Diluted Shares Outstanding"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Enterprise & Equity Value","Basic"]},{"id":"q-0693","t":"val","l":"Basic","s":90,"q":"100 shares outstanding at $5 a share, $600 debt, $300 cash. Calculate EV.","k":["Answer: $800","Enterprise Value = Equity Value (100 × $5 = $500) + Debt ($600) − Cash ($300)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Jefferies Interview","SA 2026","Enterprise & Equity Value","Basic"]},{"id":"q-0694","t":"val","l":"Basic","s":90,"q":"A company has $10 million of EBITDA and trades at a 2x EV/EBITDA multiple. It has $60 million of debt. What is the equity trading at?","k":["Answer: Negative equity value (-$40 million).","Calculation:","EV = 2x x $10M EBITDA = $20M","Equity Value = EV - Debt = $20M - $60M = -$40M","The company's debt exceeds its enterprise value, meaning the equity is effectively worthless (or negative). The company is likely distressed or insolvent."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0695","t":"val","l":"Basic","s":90,"q":"What metric is used in the numerator of the EBITDA multiple, and what is the underlying principle for pairing them?","k":["Enterprise Value.","Principle: pair a capital‐structure‑neutral numerator (EV) with a capital‐structure‑neutral denominator (EBITDA) so both reflect value available to all stakeholders before interest."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Lazard Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0696","t":"val","l":"Basic","s":90,"q":"What are the primary benefits and drawbacks of using the EV/EBITDA multiple compared to the P/E multiple for valuation?","k":["EV/EBITDA","Neutral to capital structure and taxes.","Useful across sectors and leverage levels.","Ignores capex - can overvalue capital-intensive firms.","P/E","Directly reflects equity return after all expenses.","Simple and widely quoted.","Distorted by leverage, tax strategies, and non‑cash items."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Lazard Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0697","t":"val","l":"Basic","s":90,"q":"A company has an EBITDA of $200 million and is valued at a 10.0x EV/EBITDA multiple. It has $500 million in debt, $100 million in cash, and 50 million shares outstanding. What is the company's implied share price?","k":["Answer: $32","Enterprise Value = $200 × 10 = $2,000.","Equity Value = $2,000 − $500 + $100 = $1,600.","Share Price = $1,600 / 50 = $32."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Lazard Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0698","t":"val","l":"Basic","s":90,"q":"Part 1: If you had to explain Enterprise Value to a 10-year-old, how would you do it?\n\n\n\n\nPart 2: What's the formula?\n\n\n\n\nPart 3: Bridge to equity value.\n\n\n\n\nPart 4: What are some other non-equity claims subtracted out to get to equity?\n\n\n\n\nPart 5: Why do we add minority interest?","k":["Part 1:","Imagine buying a lemonade stand: you pay for the stand plus any IOUs the owner owes (debt), but you keep the cash in the jar.","Part 2:","Formula: EV = Equity + Debt + Preferred Stock + Minority Interest − Cash.","Part 3:","Bridge: Equity = EV − Debt − Preferred Stock − Minority Interest + Cash.","Part 4:","Other claims:","Pension obligations","Operating lease liabilities (capitalized)","Deferred tax liabilities","Part 5:","Minority Interest is added because consolidated financials include 100% of a subsidiary’s results; adding the minority piece keeps valuation consistent."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in LionTree Interview","SA 2026","Enterprise & Equity Value","Basic"]},{"id":"q-0699","t":"val","l":"Basic","s":90,"q":"What is enterprise value, conceptually?","k":["The value of a firm’s core operations attributable to all capital providers."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in LionTree Interview","SA 2026","Enterprise & Equity Value","Basic"]},{"id":"q-0700","t":"val","l":"Basic","s":90,"q":"If equity value doubles with debt and cash unchanged, what happens to enterprise value?","k":["EV rises by the same absolute amount as the equity increase.","Formula EV = Equity + Debt – Cash; only equity changed."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in M. Klein & Co. Interview","SA 2026","Enterprise & Equity Value","Basic"]},{"id":"q-0701","t":"val","l":"Basic","s":90,"q":"A company has $80 million in EBITDA and is valued at 7x EBITDA. It has $200 million in cash and $600 million in debt. Calculate the Enterprise Value and Equity Value.","k":["Enterprise Value = EBITDA x Multiple = $80M x 7 = $560 million.","Equity Value = EV - Net Debt = EV - Debt + Cash = $560M - $600M + $200M = $160 million."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, First round","Enterprise & Equity Value","Basic"]},{"id":"q-0702","t":"val","l":"Basic","s":90,"q":"If a company's share price increases by 5x, what happens to Enterprise Value?","k":["Enterprise Value increases, but not necessarily by 5x.","EV = Equity Value + Debt - Cash. If the share price increases by 5x, Equity Value (Market Cap) increases by 5x. Since EV = Equity Value + Net Debt, and net debt stays the same, EV increases by the change in Equity Value.","For example, if a company had a Market Cap of $100M, Debt of $50M, and Cash of $10M: Original EV = $100 + $50 - $10 = $140M. New Market Cap = $500M. New EV = $500 + $50 - $10 = $540M. EV increased by $400M (roughly 3.86x), not 5x, because debt and cash dilute the share price effect on EV."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, First round","Enterprise & Equity Value","Basic"]},{"id":"q-0703","t":"val","l":"Basic","s":90,"q":"Please provide the standard formula for Enterprise Value. Then, discuss what other items you might add to create a more comprehensive or fully-loaded Enterprise Value calculation.","k":["Simple EV Formula","EV = Equity Value + Debt + Minority Interest + Preferred Stock - Cash","More comprehensive EV Formula","EV = Equity Value + Debt + Minority Interest + Preferred Stock - Cash - Net Operating Losses - Investments + Capital Leases + Pension Obligations","The more comprehensive version simply adjusts for other non-operating assets and off-balance-sheet obligations that behave just like debt or cash","In short, you add anything you’re assuming that acts like debt or a claim on the business, and subtract everything you’re acquiring that acts like cash or a receivable"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Moelis & Co. Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0704","t":"val","l":"Basic","s":90,"q":"Consider the following list of valuation multiples. Which of them are conceptually valid?\n\n\n\nEV/Sales\nPrice/Sales\nEV/EBITDA\nP/E","k":["EV/Sales, EV/EBITDA, and P/E are valid; Price/Sales is conceptually flawed.","Enterprise numerator (EV) should pair with pre‑interest denominators (Sales, EBITDA).","Equity numerator (Price) must pair with post‑interest Net Income.","Price/Sales mixes equity value with a metric available to all capital providers."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Moelis & Co. Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0705","t":"val","l":"Basic","s":90,"q":"From the following list, which valuation multiples are conceptually flawed because they mismatch capital structure claims? Explain why.\n\n\n\nEV/EBITDA\nPrice/EBITDA\nEV/Net Income\nP/E","k":["Price/EBITDA and EV/Net Income are flawed.","Price/EBITDA pairs equity value with a pre‑interest metric.","EV/Net Income pairs enterprise value with a post‑interest metric.","EV/EBITDA and P/E are correctly matched."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Moelis & Co. Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0706","t":"val","l":"Basic","s":90,"q":"What are five reasons you might prefer using an EV/EBITDA multiple over a P/E multiple for valuation?","k":["EV∕EBITDA is capital‑structure neutral and more reflective of core operating performance.","Advantages:","Ignores financing choices (debt vs equity) and share‑count differences.","Excludes non‑cash depreciation and amortisation distortions.","Not affected by jurisdiction‑specific tax rates or NOL utilisation.","Can value pre‑tax loss‑making companies if EBITDA is positive.","More comparable across industries with different accounting standards."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Moelis & Co. Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0707","t":"val","l":"Basic","s":90,"q":"A company has $50 million of EBITDA and is valued at a 4.0x multiple. It has $100 million of senior debt and $200 million of junior debt.\n\n\n\n\nWhat is the value of the company's equity?","k":["Answer: -$100 million (negative equity / underwater)","Calculation:","EV = $50M EBITDA * 4.0x = $200M.","Total Debt = $100M + $200M = $300M.","Equity Value = EV - Debt = $200M - $300M = -$100M.","The company is over-leveraged. Equity holders would receive nothing; even junior debt holders may face losses in liquidation."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Moelis & Co. Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0708","t":"val","l":"Basic","s":90,"q":"When using valuation multiples, why does an EBITDA multiple yield Enterprise Value while an Earnings multiple yields Equity Value?","k":["The difference lies in what each metric represents in the capital structure.","EBITDA: Earnings before interest, taxes, depreciation, and amortization. It's an operating metric available to all investors (debt and equity), so it corresponds to Enterprise Value.","Earnings (Net Income): Bottom-line profit after interest and taxes, belonging only to equity holders. Therefore, it corresponds to Equity Value.","Multiples must match: enterprise-level metrics (EBITDA) pair with EV, while equity-level metrics (Earnings) pair with Equity Value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Moelis & Co. Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0709","t":"val","l":"Basic","s":90,"q":"Given shares outstanding and share price, what is the market cap? Given net debt, what is the enterprise value? Can either of these be negative?","k":["Market Cap = Shares Outstanding x Share Price.","Enterprise Value = Market Cap + Net Debt (where Net Debt = Total Debt - Cash).","Can Market Cap be negative?","No. Share price and shares outstanding are both positive, so market cap cannot be negative.","Can Enterprise Value be negative?","Yes. If a company has more cash than the sum of its market cap and debt (i.e., the company has very large net cash relative to its equity value), EV can be negative. This is rare but can occur with cash-rich companies trading at low valuations, sometimes seen in distressed or micro-cap situations."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Moelis & Co. Interview","SA 2025, Cleantech group","Enterprise & Equity Value","Basic"]},{"id":"q-0710","t":"val","l":"Basic","s":90,"q":"A company has an enterprise value of $100 but a market cap of $50.\n\n\n\n\nDoes that mean the firm is undervalued?","k":["Not necessarily. Market cap (equity value) is one of multiple components that make up total enterprise value.","Whether the firm is undervalued depends on fundamental/intrinsic analysis, not just TEV vs. EqV."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Morgan Stanley Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0711","t":"val","l":"Basic","s":90,"q":"Would a company generally prefer to finance with debt or equity, and why?","k":["There's no one right answer; it depends.","Debt can be preferred due to lower cost (tax deductibility) and no ownership dilution. But too much debt is risky.","Equity financing can be preferable if the company is early-stage or experiencing unstable cash flows, making regular debt payments risky. Equity doesn't require repayment, provides financial flexibility, and can strengthen the balance sheet, despite diluting existing ownership."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Morgan Stanley Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0712","t":"val","l":"Basic","s":90,"q":"How does paying cash dividends impact enterprise value?","k":["A cash dividend reduces Cash and Equity Value by the same amount, so EV is unchanged."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Morgan Stanley Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0713","t":"val","l":"Basic","s":90,"q":"Given the following information, what is the company's share price?\n\n\n\nEBITDA: $100 million\nEV/EBITDA Multiple: 7.0x\nNet Debt: $400 million\nShares Outstanding: 50 million","k":["Answer: $6 per share","Calculation:","Enterprise Value = $100m × 7.0x = $700m.","Equity Value = $700m - $400m Net Debt = $300m.","Share Price = $300m / 50m shares = $6."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Morgan Stanley Interview","New York Office, First round","Enterprise & Equity Value","Basic"]},{"id":"q-0714","t":"val","l":"Basic","s":90,"q":"How do share buybacks affect a company's Earnings Per Share (EPS)?","k":["Share buybacks typically increase EPS.","Mechanics:","Company repurchases shares, reducing shares outstanding.","If Net Income remains constant, EPS = NI / Shares Outstanding increases.","However, if buyback is debt-financed, increased interest expense reduces NI, partially offsetting EPS benefit.","If cash-financed, company loses interest income on that cash, slightly reducing NI.","Net effect is usually accretive to EPS, especially if company buys back shares at prices below intrinsic value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Morgan Stanley Interview","Generalist Second round","Enterprise & Equity Value","Basic"]},{"id":"q-0715","t":"val","l":"Basic","s":90,"q":"A company's comparable set trades at 8x EV/EBITDA. The company has EBITDA of $120 million, minority interest of $20 million, cash of $500 million, and debt of $100 million. What is the implied equity value?","k":["Answer: $1,340 million","Calculation:","Enterprise Value = 8x x $120M = $960M","Equity Value = EV - Debt + Cash - Minority Interest","Equity Value = $960M - $100M + $500M - $20M = $1,340M"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Morgan Stanley Interview","SA 2027, TMT group, Menlo Park Office, First round","Enterprise & Equity Value","Basic"]},{"id":"q-0716","t":"val","l":"Basic","s":90,"q":"If you were the CEO and picked $100 up off the ground, how would that impact the value of your business?","k":["Equity Value increases by $100. Enterprise Value does not change.","Picking up $100 in cash simply increases the company's cash balance by $100. This is not operating income — finding cash on the ground is not a business activity, so it does not flow through the Income Statement as revenue or operating income. The cash balance on the BS increases by $100, with a corresponding increase to equity (think of it as a non-operating windfall that directly increases net assets). Since Equity Value = Enterprise Value - Net Debt, and cash increased by $100 (reducing net debt by $100), Equity Value rises by $100. However, Enterprise Value = Equity Value + Net Debt, so the $100 increase in equity is exactly offset by the $100 decrease in net debt — EV stays the same. EV measures the core operating value of the business, and finding cash on the ground is not an operating activity."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Morgan Stanley Interview","SA 2025, Healthcare group, SF Office, Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0717","t":"val","l":"Basic","s":90,"q":"Why do you add back Non-Controlling Interests in your Enterprise Value calculation, and what specifically are you adding?","k":["You add Non-Controlling Interest (NCI, also called Minority Interest) to Enterprise Value because the company's consolidated financial statements include 100% of the subsidiary's revenue, EBITDA, and other financials, even though the parent does not own 100% of that subsidiary.","Since EV-based multiples (like EV/EBITDA) use the full consolidated EBITDA in the denominator, you must include the value of the minority stake in the numerator to keep the ratio consistent. What you add is the market value of the minority shareholders' ownership in the subsidiary -- typically approximated by the NCI balance on the balance sheet (within the equity section) if market value is not available."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Morgan Stanley Interview","SA 2025, Healthcare group, SF Office, Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0718","t":"val","l":"Basic","s":90,"q":"A company's share price is $51. It has 30 shares authorized and 20 shares outstanding.\n\n\n\n\nWhat is its equity value?","k":["$1,020 (51 × 20).","Authorized shares are irrelevant to market cap."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Perella Weinberg Interview","Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0719","t":"val","l":"Basic","s":90,"q":"A company has $200 in equity value, $300 in debt, $50 in cash, preferred stock of 25, and goodwill of 100.\n\n\n\n\nWhat is enterprise value?","k":["$475.","EV = 200 + 300 + 25 – 50 = 475. Goodwill is already embedded in equity value and need not be adjusted."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Perella Weinberg Interview","Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0720","t":"val","l":"Basic","s":90,"q":"Beyond the standard components of debt, cash, preferred stock, and minority interest, what are some less-common items you might consider when calculating a company's Enterprise Value?","k":["Less-common EV adjustments:","Operating Leases: Under new accounting standards (ASC 842), these may need adjustment.","Pension Obligations: Unfunded pension liabilities can be added to EV.","Contingent Liabilities: Pending litigation or environmental liabilities.","Equity Investments in Affiliates: Non-controlling stakes in other companies.","Earnout Obligations: Future payments contingent on performance.","Non-Core Assets: Excess real estate or investments held for sale may be subtracted like cash.","Deferred Tax Assets/Liabilities: In certain contexts, material DTLs may be added."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Perella Weinberg Interview","SF Office","Enterprise & Equity Value","Basic"]},{"id":"q-0721","t":"val","l":"Basic","s":90,"q":"A company has $55M in EBITDA and trades at a 10x EV/EBITDA multiple.\n\n\n\n\nAssuming the company has $150M in debt, $50M in cash, and 20M shares outstanding, what is its share price?","k":["Answer: $22.50","Calculation:","EV = 10x * $55M = $550M","Equity Value = EV - Debt + Cash = $550M - $150M + $50M = $450M","Share Price = $450M / 20M shares = $22.50"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in PJT Partners Interview","First round","Enterprise & Equity Value","Basic"]},{"id":"q-0722","t":"val","l":"Basic","s":90,"q":"Explain why valuation multiples such as EV/Net Income and Equity Value/EBITDA are conceptually flawed.","k":["These multiples mismatch numerator and denominator.","EV/Net Income:","EV represents value to all capital providers (debt + equity).","Net Income is value to equity holders only (after interest and taxes).","Mismatch makes comparison across companies invalid.","Equity Value/EBITDA:","Equity Value represents value to equity holders only.","EBITDA is operating profit available to all capital providers (debt + equity).","Different capital structures distort the multiple, making comparisons meaningless.","Correct pairings: EV with operating metrics (EBITDA, EBIT, Revenue), Equity Value with equity metrics (Net Income, EPS)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in PJT Partners Interview","Second round","Enterprise & Equity Value","Basic"]},{"id":"q-0723","t":"val","l":"Basic","s":90,"q":"Conceptually, what is enterprise value?","k":["Total value of a company’s core operations available to all investors (debt and equity)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Raine Group Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0724","t":"val","l":"Basic","s":90,"q":"Why would a company prefer to take out debt instead of equity?","k":["Debt financing can be cheaper than equity (tax-deductible interest), and it avoids diluting existing shareholders.","Also, if the company generates stable cash flows, servicing debt is feasible, and it potentially boosts ROE through leverage."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in RBC Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0725","t":"val","l":"Basic","s":90,"q":"What does Minority Interest (Non-Controlling Interest) signify in the Enterprise Value calculation, and how is it included?","k":["Minority Interest (Non-Controlling Interest) represents the equity ownership in a subsidiary that is not held by the parent company.","It is added to Enterprise Value because the parent's consolidated financials include 100% of the subsidiary's operating metrics (revenue, EBITDA, etc.). To maintain consistency between the EV numerator and the EBITDA denominator, you must account for the value of the minority stake. Without adding NCI, the EV/EBITDA multiple would be understated.","In the EV bridge: EV = Equity Value + Total Debt + Minority Interest + Preferred Stock - Cash & Cash Equivalents. The NCI value used is typically the book value from the balance sheet (equity section) unless a market value is readily available."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Rothschild Interview","SA 2027, First round","Enterprise & Equity Value","Basic"]},{"id":"q-0726","t":"val","l":"Basic","s":90,"q":"An oil field has a present value of unlevered free cash flows of $100, debt of $150, and cash of $50. What is the equity value?","k":["Equity Value = $0.","The PV of unlevered FCFs represents the enterprise value of the oil field ($100). Equity Value = EV - Debt + Cash = $100 - $150 + $50 = $0.","The equity is worthless. Net debt is $100 ($150 debt - $50 cash), which equals the entire enterprise value, leaving zero residual value for equity holders. In practice, this company would be at the edge of insolvency — any deterioration in cash flows or commodity prices would push it into restructuring."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Rothschild Interview","SA 2027, Global Advisory group, New York Office, First round","Enterprise & Equity Value","Basic"]},{"id":"q-0727","t":"val","l":"Basic","s":90,"q":"A company's stock trades at $15 per share, and it has 100 shares outstanding. The company also has $600 in debt, $100 in cash, and generated $200 in EBITDA.\n\n\n\n\nWhat is the company's EV/EBITDA multiple?","k":["Answer: 10.0x","Calculation:","Equity Value = $15 * 100 = $1,500","EV = $1,500 + $600 - $100 = $2,000","EV/EBITDA = $2,000 / $200 = 10.0x"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Unspecified Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0728","t":"val","l":"Basic","s":90,"q":"What is the difference between total cash and excess cash?","k":["Total Cash is all cash and cash equivalents on the balance sheet.","Excess Cash is cash beyond what the company needs for day-to-day operations (working capital requirements).","In Enterprise Value calculations, only excess cash is subtracted, as operating cash is necessary for the business. Determining excess cash requires judgment about minimum cash needs."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Unspecified Interview","Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0729","t":"val","l":"Basic","s":90,"q":"If a company finds $1,000 in cash, what is the impact on its Enterprise Value and Equity Value?","k":["Equity Value increases by $1,000 (cash is an asset belonging to equity holders).","Enterprise Value remains unchanged (EV = Equity Value + Debt - Cash; cash increase offsets equity value increase)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Unspecified Interview","Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0730","t":"val","l":"Basic","s":90,"q":"Why is a multiple such as Equity Value / Sales conceptually flawed?","k":["Equity Value / Sales is flawed because it compares an equity metric (Equity Value) to an enterprise metric (Sales).","Sales benefits all stakeholders (debt and equity holders), not just equity.","Companies with different capital structures would be incomparable.","A highly leveraged company would appear cheaper despite higher financial risk.","The correct multiple is EV/Sales, which compares enterprise-level value to enterprise-level revenue."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Unspecified Interview","Superday","Enterprise & Equity Value","Basic"]},{"id":"q-0731","t":"val","l":"Basic","s":90,"q":"A firm with $500 million EV issues $100 million of new debt to invest in a project with $100 million NPV.\n\n\n\n\nWhat is the new enterprise value?","k":["EV goes up by $100m.","$100m of debt has no impact on TEV (increase in debt is offset by increase in cash)","Positive NPV project adds $100m to operational value"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in William Blair Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0732","t":"val","l":"Basic","s":90,"q":"In a tax-free world, a firm with $500 million EV issues $100 million of new debt.\n\n\n\n\nWhat is the new EV?","k":["Enterprise value remains $500 million, assuming the cash is retained on the balance sheet and not spent.","TEV = Equity Value + Debt - Cash. Adding debt and adding the same amount of cash cancels out."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in William Blair Interview","Enterprise & Equity Value","Basic"]},{"id":"q-0733","t":"val","l":"Basic","s":90,"q":"A company has a share price of $40, 50 million shares outstanding, $100M in cash, $50M in debt, $100M in preferred stock, and $100M in noncontrolling interest. What is the Enterprise Value?","k":["Answer: $2,150M.","Equity Value = $40 x 50M shares = $2,000M.","EV = Equity Value + Debt - Cash + Preferred Stock + Noncontrolling Interest.","EV = $2,000M + $50M - $100M + $100M + $100M = $2,150M.","Preferred stock is added because it represents a claim senior to common equity that must be satisfied before equity holders. Noncontrolling interest is added because the company's consolidated financials include 100% of the subsidiary's operating metrics (revenue, EBITDA), so the EV must reflect the full enterprise, including the portion owned by minority shareholders."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in William Blair Interview","SA 2027, Chicago Office","Enterprise & Equity Value","Basic"]},{"id":"q-0734","t":"val","l":"Basic","s":90,"q":"A Company's share price is $20, and it has 50 million common shares outstanding. What is the Company's enterprise value if it has $100 million of excess cash, $50 million of debt, $100 million of preferred stock, and $50 million of non-controlling interest?","k":["Answer: Enterprise Value = $1,100M.","Equity Value","Share Price x Shares Outstanding = $20 x 50M = $1,000M","Enterprise Value","EV = Equity Value - Cash + Debt + Preferred Stock + Non-Controlling Interest","EV = $1,000M - $100M + $50M + $100M + $50M = $1,100M"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in William Blair Interview","SA 2027, Financial Sponsors group, New York Office","Enterprise & Equity Value","Basic"]},{"id":"q-0735","t":"val","l":"Advanced","s":90,"q":"Company has 100 common shares at $10 each, with 10 options at a $20 strike price. What is the fully diluted equity value?","k":["$1,000","The options are out‑of‑the‑money (strike $20 > share price $10), so no dilution. Diluted shares = 100; equity value = 100 × $10."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Allen & Company Interview","SA 2026","Enterprise & Equity Value","Advanced"]},{"id":"q-0736","t":"val","l":"Advanced","s":90,"q":"What is unusual about a company with an EV/EBITDA multiple of 15x and an EV/EBIT multiple of 12x?","k":["This implies negative Depreciation & Amortization, which is impossible under normal accounting.","Analysis:","If EV/EBITDA = 15x, then EBITDA = EV / 15.","If EV/EBIT = 12x, then EBIT = EV / 12.","Since EBITDA = EBIT + D&A, we have: EV / 15 = EV / 12 + D&A.","Solving: D&A = EV / 15 - EV / 12 = -EV / 60.","This implies negative D&A, which is not possible.","The situation is unusual because EV/EBIT should always exceed EV/EBITDA since EBIT is smaller than EBITDA. The data likely contains an error or special accounting treatment."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Bank of America Interview","SF office","Enterprise & Equity Value","Advanced"]},{"id":"q-0737","t":"val","l":"Advanced","s":90,"q":"A company has 1 million shares outstanding with a current share price of $100. It has $10M in convertible notes with a par value of $1,000 and a conversion price of $50. Walk me through how you calculate the company's fully diluted shares outstanding.","k":["Answer: 1,200,000 fully diluted shares.","Calculation:","Basic shares outstanding: 1,000,000","Number of convertible notes: $10M / $1,000 par = 10,000 notes","Shares per note: $1,000 par / $50 conversion price = 20 shares per note","Total shares from conversion: 10,000 x 20 = 200,000 shares","Since current share price ($100) > conversion price ($50), the notes are in-the-money and would be converted.","Using the if-converted method: assume all notes convert to equity. Add 200,000 shares.","Fully diluted shares = 1,000,000 + 200,000 = 1,200,000"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Bank of America Interview","Second round","Enterprise & Equity Value","Advanced"]},{"id":"q-0738","t":"val","l":"Advanced","s":90,"q":"You are given the following information for a company:\n\n\n\nShare Price = $10\nP/E Multiple = 10x\nShares Outstanding = 10\nNet Debt = $200\nEV/EBITDA = 15x\n\n\n\nCalculate the EPS, Market Value (Equity Value), and EBITDA.","k":["Answer: EPS = $1.00, Equity Value = $100, EBITDA = $20","Calculation:","EPS = Share Price / P/E = $10 / 10x = $1.00","Equity Value = Share Price x Shares = $10 x 10 = $100","Enterprise Value = Equity Value + Net Debt = $100 + $200 = $300","EBITDA = EV / (EV/EBITDA) = $300 / 15x = $20"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Bank of America Interview","SA 2027, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0739","t":"val","l":"Advanced","s":90,"q":"A company has Net Income of $40 million, a P/E of 15x, Debt of $300 million, Cash of $0, and an EV/EBITDA of 9x. What is the leverage ratio (Debt/EBITDA)?","k":["Answer: 3.0x","Calculation:","Equity Value = NI x P/E = $40M x 15 = $600M","EV = Equity Value + Debt - Cash = $600M + $300M - $0 = $900M","EBITDA = EV / (EV/EBITDA) = $900M / 9 = $100M","Leverage Ratio = Debt / EBITDA = $300M / $100M = 3.0x"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Bank of America Interview","Emerging Growth & Regional Coverage group, SF Office, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0740","t":"val","l":"Advanced","s":90,"q":"Given a simplified income statement and market data for a company, calculate EBITDA (the IS does not include an explicit EBITDA line), Enterprise Value, EV/EBITDA, P/E, and the impact to EV/EBITDA when adjusting for stock-based compensation.\n\n\n\nRevenue: $1,000M, COGS: $600M, SG&A: $100M, D&A: $50M\nInterest Expense: $50M (on $500M of bonds outstanding)\nTax Rate: 25%, Stock-Based Compensation: $60M\nShares Outstanding: 100M, Share Price: $15, Cash: $200M","k":["Step 1: EBITDA","Gross Profit = Revenue - COGS = $1,000 - $600 = $400M. Subtract SG&A: $400 - $100 = $300M. Note: SBC ($60M) is listed as a separate operating expense, not embedded in SG&A. Including SBC as an operating cost: EBITDA = $300 - $60 = $240M. Cross-check: EBIT = $240 - $50 D&A = $190M; EBITDA = $190 + $50 = $240M.","Step 2: Enterprise Value","Equity Value = 100M shares x $15 = $1,500M. Bonds are debt instruments — include them. EV = Equity Value + Debt - Cash = $1,500 + $500 - $200 = $1,800M.","Step 3: Multiples","EV/EBITDA = $1,800 / $240 = 7.5x.","Net Income = (EBIT - Interest) x (1 - Tax) = ($190 - $50) x 0.75 = $105M. EPS = $105 / 100 = $1.05. P/E = $15 / $1.05 = 14.3x.","Step 4: SBC-Adjusted EBITDA (Adding Back SBC)","In practice, many analysts add back SBC as a non-cash expense to get \"SBC-Adjusted EBITDA\" = $240 + $60 = $300M. Adjusted EV/EBITDA = $1,800 / $300 = 6.0x. The multiple decreases from 7.5x to 6.0x, making the company appear cheaper. However, SBC is a real economic cost (it dilutes shareholders), so the unadjusted 7.5x better reflects the true expense structure. Always note which EBITDA definition you are using."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Bank of America Interview","SA 2025, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0741","t":"val","l":"Advanced","s":90,"q":"An oil company has 500 shares outstanding, a share price of $5, cash of $500, debt of $750, EBITDA of $500, cash taxes of $125, interest of $75, D&A of $100, shareholders' equity of $750, preferred stock of $400, and non-controlling interests of $100. Calculate the enterprise value and the EV/EBITDA multiple. If a comparable Company B has an EV/EBITDA multiple of 8x, would the deal be accretive or dilutive?","k":["Enterprise Value Calculation","Equity Value = 500 shares x $5 = $2,500","EV = Equity Value + Debt + Preferred Stock + Non-Controlling Interests - Cash","EV = $2,500 + $750 + $400 + $100 - $500 = $3,250","Sanity check: Interest of $75 on $750 debt implies a 10% cost of debt, which is reasonable.","EV/EBITDA Multiple","EV/EBITDA = $3,250 / $500 = 6.5x","Accretion / Dilution","Company A trades at 6.5x EV/EBITDA, while comparable Company B trades at 8.0x EV/EBITDA.","If Company A acquires Company B at 8.0x, it is paying a higher multiple than its own trading multiple. This means Company A is acquiring more expensive earnings, which is dilutive.","Conversely, if Company B acquires Company A at 6.5x, the deal would be accretive to Company B."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Bank of America Interview","SA 2026, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0742","t":"val","l":"Advanced","s":90,"q":"A company has $10 in Revenue, $10 in Operating Expenses, and $10 in Capital Expenditures. Which of these items impacts Enterprise Value the most?","k":["It depends on the valuation methodology.","Under a multiple (EV/EBITDA)","Revenue and OpEx have equal absolute impact — each moves EBITDA by $10, so $100 of EV at a 10x multiple, in opposite directions.","Caveat on revenue: it only reaches EBITDA at the incremental margin. $10 of revenue is $10 of EBITDA only if it carries no cost; at a 40% margin it is $4, and OpEx becomes the larger lever. OpEx is always dollar-for-dollar, revenue is not.","CapEx never touches EBITDA, so on this basis it has no impact.","Under a DCF","CapEx has the largest immediate impact: it reduces unlevered FCF one-for-one with no tax offset.","Revenue and OpEx are tax-affected — $10 through EBITDA is $10 × (1 - tax rate), roughly $7.50 at 25%, and less for revenue after margin.","But CapEx is a single-period item that also generates depreciation shields and, if growth CapEx, future cash flows. Recurring revenue and OpEx changes get capitalized into terminal value, so their total EV impact is far larger.","If the changes are recurring, revenue and OpEx dominate because they run through EBITDA and get multiplied. For a single period's cash flow, CapEx is the biggest hit."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Barclays Interview","SF Office, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0743","t":"val","l":"Advanced","s":90,"q":"A company has 200 million basic shares outstanding at a current share price of $10, with 50 million options at a $4 strike price. Walk me through the treasury stock method to calculate diluted equity value.","k":["The Treasury Stock Method (TSM) calculates the net dilutive effect of in-the-money options, warrants, and convertible securities:","Identify all in-the-money options: The 50 million options have a $4 strike price, which is below the $10 current share price, so they are in the money.","Assume all 50 million options are exercised. The company receives proceeds = 50M x $4 = $200 million.","The company uses those proceeds to repurchase shares at the current market price: $200M / $10 = 20 million shares repurchased.","Net new shares = 50M options exercised - 20M shares repurchased = 30 million net new shares.","Diluted shares = 200M basic + 30M net new = 230 million diluted shares.","Diluted Equity Value = 230M shares x $10 = $2.3 billion."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Barclays Interview","SF Office, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0744","t":"val","l":"Advanced","s":90,"q":"Debt/EBITDA = 8x, Debt/Equity = 1x. What is EV/EBITDA?","k":["Answer: 16x.","Debt (E) = Equity (E)","EV = D + E → EV = 2D","Debt/EBITDA = 8x → D = 8 x EBITDA","EV / EBITDA = (2D) / EBITDA = 2D / EBITDA = 2 * 8 = 16x"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in CIBC Capital Markets Interview","SA 2026, Toronto office, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0745","t":"val","l":"Advanced","s":90,"q":"You are given the following information for a company:\n\n\n\nEPS = $1.00\nP/E Multiple = 15x\nShares Outstanding = 100\nTotal Debt = $500\nCash = $0\n\n\n\nPart 1: Calculate the Equity Value and Enterprise Value.\n\n\n\n\nPart 2: Now, assume the following:\n\n\n\nTax Rate = 20%\nInterest Rate on Debt = 10%\nD&A = $25\n\n\n\nCalculate the EV/EBITDA multiple.","k":["Part 1: Equity Value and Enterprise Value","Equity Value = $1,500","Enterprise Value = $2,000","Share Price = EPS × P/E = $1.00 × 15 = $15","Equity Value = Share Price × Shares = $15 × 100 = $1,500","EV = Equity Value + Debt - Cash = $1,500 + $500 - $0 = $2,000","Part 2: EV/EBITDA Multiple","Answer: 10.0x","Net Income = EPS × Shares = $1.00 × 100 = $100","Pre-Tax Income = NI / (1 - Tax Rate) = $100 / 0.80 = $125","Interest Expense = Debt × Interest Rate = $500 × 10% = $50","EBIT = Pre-Tax Income + Interest Expense = $125 + $50 = $175","EBITDA = EBIT + D&A = $175 + $25 = $200","EV/EBITDA = $2,000 / $200 = 10.0x"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Citi Interview","New York Office","Enterprise & Equity Value","Advanced"]},{"id":"q-0746","t":"val","l":"Advanced","s":90,"q":"Company A has an EV/EBITDA multiple of 10x, and Company B has a multiple of 12x. Which company is more leveraged?","k":["Cannot determine leverage from EV/EBITDA multiples alone.","EV/EBITDA is a capital structure-neutral metric. A higher multiple typically indicates higher growth expectations, better margins, lower risk, or superior market position - not leverage levels.","To assess leverage, you need to examine Debt/EBITDA, Debt/Equity, Interest Coverage, or review the balance sheet directly."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Citi Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0747","t":"val","l":"Advanced","s":90,"q":"A company has the following financial data: Revenue of $500M, EBITDA of $100M, Net Debt of $200M, 50 million Shares Outstanding, a Share Price of $20, and a Levered Free Cash Flow yield of 5%. Calculate the Levered Free Cash Flow, Equity Value, Enterprise Value, EBITDA Margin, EV/Revenue, and EV/EBITDA.","k":["Step-by-step solution:","Equity Value = Share Price x Shares Outstanding = $20 x 50M = $1,000M ($1 billion).","Levered Free Cash Flow = LFCF Yield x Equity Value = 5% x $1,000M = $50 million.","Enterprise Value = Equity Value + Net Debt = $1,000M + $200M = $1,200M ($1.2 billion).","EBITDA Margin = EBITDA / Revenue = $100M / $500M = 20%.","EV/Revenue = $1,200M / $500M = 2.4x.","EV/EBITDA = $1,200M / $100M = 12.0x.","Key takeaway:","Start with what you know (share price and shares outstanding) to calculate Equity Value, then bridge to Enterprise Value by adding Net Debt. From there, you can compute all the requested multiples and margins."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Citi Interview","SA 2026, New York Office, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0748","t":"val","l":"Advanced","s":90,"q":"Calculate the Fully Diluted Equity Value for a company with the following details:\n\n\n\nBasic Shares Outstanding: 1 billion\nCurrent Share Price: $50\nRestricted Stock Units (RSUs): 50 million\nOptions: 40 million outstanding at a $25 strike price","k":["Answer: $53.5 billion","Calculation:","RSUs convert 1:1 into shares, adding 50 million shares.","Options are in-the-money ($25 strike < $50 price). Using TSM: 40m - (40m * $25 / $50) = 40m - 20m = 20m net new shares.","Total Diluted Shares = 1,000m + 50m + 20m = 1,070m.","Fully Diluted Equity Value = 1,070m * $50 = $53.5 billion."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Credit Suisse Interview","SF office","Enterprise & Equity Value","Advanced"]},{"id":"q-0749","t":"val","l":"Advanced","s":90,"q":"A company has $100M EBITDA, is comparable at 5x EV/EBITDA, has $200M in Debt, and issues $100M in Equity. What is the impact on EV and Equity Value? How does ownership change?","k":["Enterprise Value is unchanged at $500M, Equity Value increases to $400M, and existing shareholders are diluted to 75% ownership (25% dilution).","Pre-Raise Analysis:","EBITDA = $100M and EV/EBITDA = 5x ⟹ Enterprise Value (EV) = $500M","Total Debt = $200M ⟹ Equity Value = $300M (since EV = Equity + Net Debt)","After Raising $100M in Equity:","Equity Value increases from $300M to $400M","Net Debt becomes $200M (existing debt) - $100M (new cash) = $100M","EV remains $500M (Equity + Net Debt = $400M + $100M)","New investors own $100M / $400M = 25% dilution"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0750","t":"val","l":"Advanced","s":90,"q":"Company EV/EBITDA goes from 10x to 20x, and EV/Revenue goes from 2x to 4x. What happened to EBITDA margin and revenue?","k":["The EBITDA margin remained perfectly unchanged (at 20%).","You calculate this via: EV/Revenue divided by EV/EBITDA (4x / 20x = 20% margin, which is the same as the initial 2x / 10x = 20%).","While the absolute level of revenue cannot be determined from the ratios alone, a common interview interpretation is that valuation expanded (multiple expansion) while underlying operations and margins stayed roughly flat."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0751","t":"val","l":"Advanced","s":90,"q":"Net Income: $100, EBITDA: $350, P/E: 8x, EV/EBITDA: 4x. What is net debt?","k":["First, calculate Equity Value using P/E:","Equity Value = P/E * Net Income = 8 * $100 = $800","Next, calculate Enterprise Value using EV/EBITDA:","EV = EV/EBITDA * EBITDA = 4 * $350 = $1,400","Finally, Net Debt = EV - Equity Value = $1,400 - $800 = $600"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0752","t":"val","l":"Advanced","s":90,"q":"A company has the following information. Calculate the share price:\n\nP/E = 25x\nEV/EBITDA = 12x\nTax Rate = 25%\nRevenue = $2,000M\nShares Outstanding = 150M\nGross Margin = 50%\n$1,000M debt at 10% interest\nSG&A (including D&A) = $500M\n\n\n\nAssume no other liabilities or equity line items besides debt and common shareholders' equity.","k":["The answer is $50 per share.","First, build an Income Statement:","Revenue: $2,000M","Gross Profit: $1,000M (given Gross Margin of 50%)","SG&A: $(500M)","EBIT: $500M","Interest: $(100M)","Pre-Tax Income: $400M","Taxes: $(100M)","Net Income: $300M","Then, calculate the valuation:","P/E Ratio = Equity Value / Net Income = 25x","Equity Value = 25 * $300M = $7.5B","Share Price = Equity Value / Shares Outstanding = $7.5B / 150M shares = $50 / share"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0753","t":"val","l":"Advanced","s":90,"q":"In FY1, EV/EBITDA = 5x and EV/Revenue = 2x. In FY2, EV/EBITDA = 6x and EV/Revenue = 1x. Assume EV remains constant. How do EBITDA margins change between FY1 and FY2?","k":["EBITDA margins decrease from 40% in FY1 to approximately 16.7% in FY2.","Here’s the calculation:","FY1:","EBITDA = EV / 5","EBITDA = EV / 5","Revenue = EV / 2","EBITDA Margin = (EV / 5) / (EV / 2) = 2/5 = 40%","FY2:","EBITDA = EV / 6","Revenue = EV","EBITDA Margin = (EV / 6) / EV = 1/6 ≈ 16.7%"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0754","t":"val","l":"Advanced","s":90,"q":"In FY1, EV/EBITDA = 5x and EV/Revenue = 2x.\n\n\n\n\nIn FY2, EV/EBITDA = 6x and EV/Revenue = 1x.\n\n\n\n\nAssume EV remains constant. How much does revenue change between FY1 and FY2?","k":["Revenue doubles from FY1 to FY2, increasing by 100%.","Here’s the calculation:","FY1:","EV/Revenue = 2x → Revenue = EV / 2","FY2:","EV/Revenue = 1x → Revenue = EV","Change in Revenue:","Revenue in FY2 = 2 x Revenue in FY1"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0755","t":"val","l":"Advanced","s":90,"q":"Share price=$50, Basic shares=200.\n\n\n\n\nSecurities: 50 options (strike $20), 30 RSUs, $6k converts ($1k par, $40 conversion price).\n\n\n\n\nWhat is the fully diluted equity value?","k":["Answer: $20,500","Calculation:","The options are in-the-money since the exercise price ($20) is below the current price ($50). Exercising 50 options at $20 each generates $1,000 for the company, which it uses to buy back shares at the current price of $50 per share ($1,000 / $50 = 20 shares repurchased). Thus, there is a net issuance of 30 new shares.","RSUs lead to the creation of 30 additional shares.","Each convertible bond ($1,000 par value) converts at $40 per share, resulting in 25 new shares per bond ($1,000 / $40). With a total bond value of $6,000, the total new shares issued are 150 ($6,000 / $1,000 x 25).","The total diluted shares outstanding are 200 (original) + 30 (options) + 30 (RSUs) + 150 (convertibles) = 410 shares.","At the current share price of $50, the diluted equity value equals 410 x $50 = $20,500.","Common mistake: options add 30, not 20 — TSM = 50 − (50×20)/50 = 30."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0756","t":"val","l":"Advanced","s":90,"q":"If a company has 10 options outstanding with a $50 average strike and the stock trades at $100, what happens to net income when they are all exercised?","k":["Net income is not directly impacted by a plain vanilla option exercise because the company issues shares for cash.","The direct effect is on share count (dilution) rather than NI.","However, any associated stock-based comp expense would have already been recognized earlier, not at exercise.","The company receives cash equal to the strike price × options exercised (here, $50 × 10 = $500), which increases Assets (Cash) and Additional Paid-In Capital."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0757","t":"val","l":"Advanced","s":90,"q":"You acquire 60% of a company for $1.5bn in equity.\n\n\n\n\nIt has $400m revenue, $200m EBITDA, $175m cash, and $75m debt.\n\n\n\n\nWhat is the equity value, what is the net debt, and what is the EV?","k":["Equity Value = $2.5 bn.","Net Debt = $75 m – $175 m = –$100 m (net cash).","Enterprise Value = 2.5 – 0.1 = $2.4 bn."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","SA 2025, New York Office, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0758","t":"val","l":"Advanced","s":90,"q":"Why might a company with the same P/E ratio as its peers have a lower EV/EBITDA multiple?","k":["This wedge occurs when a company has a different capital structure or D&A profile.","Key drivers:","Higher Depreciation & Amortization: This depresses Net Income (raising P/E) but is added back to EBITDA (lowering EV/EBITDA).","Different Tax Rates: A higher tax rate depresses Net Income without affecting EBITDA.","Different Interest Expenses: Higher leverage/interest lowers Net Income, keeping P/E high, while EV/EBITDA is capital structure neutral."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","New York office","Enterprise & Equity Value","Advanced"]},{"id":"q-0759","t":"val","l":"Advanced","s":90,"q":"A company has a Market Cap of $500 million, Debt of $700 million, and Cash of $200 million.\n\n\n\n\nPart 1: What is its Enterprise Value?\n\n\n\n\nPart 2: The company then uses all its cash to repurchase debt at 50 cents on the dollar. Walk me through the impact on Enterprise Value. Assume a 25% tax rate.","k":["Part 1: Initial Enterprise Value is $1,000 million.","EV = Market Cap + Debt - Cash","EV = $500M + $700M - $200M = $1,000M","Part 2: The new Enterprise Value is $950 million.","Analysis:","The company uses $200M cash to repurchase debt at a 50% discount, retiring $400M of face value ($200M / 0.50).","This creates a $200M pre-tax gain on debt extinguishment ($400M face value - $200M cash paid).","This gain is taxed at 25%, resulting in a $50M tax payment ($200M * 25%). This tax is a cash outflow that reduces the total value of the firm.","The after-tax gain is $150M ($200M - $50M), which flows to Retained Earnings and increases Market Cap by $150M to $650M.","New Debt = $700M - $400M = $300M","New Cash = $200M - $200M = $0","New EV = $650M (New Mkt Cap) + $300M (New Debt) - $0 (New Cash) = $950M","Enterprise value decreases by $50M, which is the amount of value lost to the government via taxes on the gain."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Evercore Interview","New York Office, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0760","t":"val","l":"Advanced","s":90,"q":"How do you calculate fully diluted equity value after accounting for convertible bonds?","k":["You use the \"if-converted\" method:","Determine if the convertible bonds are \"in the money\" - i.e., whether the current share price exceeds the conversion price.","If in the money: assume the bonds are converted to equity. Add the additional shares from conversion to diluted shares outstanding. Remove the convertible debt from the EV bridge (since it is now equity, not debt).","If out of the money: treat the convertible bonds as straight debt. No additional diluted shares are added.","Fully Diluted Equity Value = Share Price x Fully Diluted Shares (including converted shares from in-the-money convertibles, plus shares from options/warrants via the treasury stock method)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Evercore Interview","SA 2025","Enterprise & Equity Value","Advanced"]},{"id":"q-0761","t":"val","l":"Advanced","s":90,"q":"A company is purchased at a 10x EV/EBITDA multiple. It has EBITDA of $120, $200 in cash, $700 in debt, and 20 shares outstanding at $30 per share. What is the implied Equity Value of the purchase and the control premium?","k":["Answer: Implied Equity Value = $700, Control Premium = 16.7%","Calculation:","Enterprise Value = 10x x $120 EBITDA = $1,200","Implied Equity Value = EV - Debt + Cash = $1,200 - $700 + $200 = $700","Current Equity Value = 20 shares x $30 = $600","Control Premium = ($700 - $600) / $600 = 16.7%"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Evercore Interview","M&A group, New York Office, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0762","t":"val","l":"Advanced","s":90,"q":"Part 1: A company has 100 shares outstanding and 20 options with a $20 strike price. The current share price is $10. What is the diluted equity value?\n\n\n\n\nPart 2: Now assume the share price is $100. What is the diluted equity value?","k":["Part 1: Share Price = $10","Options are out of the money ($20 strike > $10 share price).","No dilution under the treasury stock method.","Diluted Equity Value = 100 shares x $10 = $1,000.","Part 2: Share Price = $100","Options are in the money ($20 strike < $100 share price).","Treasury Stock Method: 20 options exercised, company receives 20 x $20 = $400.","Shares repurchased = $400 / $100 = 4 shares.","Net new shares = 20 - 4 = 16 shares.","Diluted shares = 100 + 16 = 116.","Diluted Equity Value = 116 x $100 = $11,600."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Evercore Interview","SA 2025, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0763","t":"val","l":"Advanced","s":90,"q":"What happens to total Enterprise Value when you issue debt?","k":["It depends on what you do with the proceeds. There are two scenarios:","Scenario 1: Issue Debt and Hold Proceeds as Cash","EV = Equity Value + Debt - Cash. Both Debt and Cash increase by the same amount, so the two effects cancel out.","EV is unchanged.","Scenario 2: Issue Debt and Use Proceeds to Acquire an Asset","Debt increases, but Cash does not (it was spent immediately on the acquisition). The acquired asset replaces cash with an operating asset that is captured in EV.","EV increases by the amount of debt issued.","The distinction is that cash is subtracted in the EV bridge, so holding debt proceeds as cash creates an offsetting effect. Only when cash leaves the balance sheet (used for an operating purpose) does EV increase."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0764","t":"val","l":"Advanced","s":90,"q":"What happens to total Enterprise Value when you issue debt to pay out a dividend?\n\n\n\n\nFollow-up 1: What happens to Equity Value when you repurchase shares?\n\n\n\n\nFollow-up 2: Why would a company repurchase shares?","k":["EV is unchanged.","Issuing debt: Debt +X, Cash +X (temporarily).","Paying the dividend: Cash -X, Equity Value -X (market cap drops by the dividend amount on ex-date).","Net effect: Debt +X, Equity Value -X, Cash unchanged.","EV = (Equity - X) + (Debt + X) - Cash = original EV.","Follow-up 1: Equity Value When Repurchasing Shares","Cash decreases by the amount spent on repurchases. Shares outstanding decrease.","Total Equity Value (market cap) decreases by the amount of cash spent, since cash has left the company.","However, EPS increases (fewer shares, same earnings), and per-share value remains roughly the same or increases slightly.","EV is unchanged: EV = (Equity - X) + Debt - (Cash - X) = original EV.","Follow-up 2: Why Repurchase Shares?","Return excess cash to shareholders in a tax-efficient manner (capital gains may be taxed more favorably than dividends).","Signal that management believes the stock is undervalued.","Increase EPS by reducing the denominator (fewer shares outstanding).","Offset dilution from employee stock-based compensation.","Greater flexibility than dividends: buybacks are discretionary and do not create an expectation of recurring payments."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0765","t":"val","l":"Advanced","s":90,"q":"You own 60% of a company for $1.5 billion in equity (the 60% stake is worth $1.5 billion). The company has $400 million in revenue, $200 million in EBITDA, $175 million in cash, and $75 million in debt.\n\n\n\n\nPart 1: What is the total Equity Value of this company?\n\n\n\n\nPart 2: What is net debt?\n\n\n\n\nPart 3: What is total Enterprise Value?\n\n\n\n\nPart 4: What is the EV/EBITDA multiple?","k":["Part 1: Total Equity Value","60% stake = $1.5B, so 100% Equity Value = $1.5B / 0.60 = $2.5B","Part 2: Net Debt","Net Debt = Debt - Cash = $75M - $175M = -$100M (net cash position of $100M)","Part 3: Enterprise Value","EV = Equity Value + Debt - Cash = $2.5B + $75M - $175M = $2.4B","Part 4: EV/EBITDA","EV / EBITDA = $2.4B / $200M = 12.0x"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0766","t":"val","l":"Advanced","s":90,"q":"A company has $1 billion in EBITDA. It is an upstream (exploration and production) company. Assume the company carries $2 billion in net debt. What will the equity value be?","k":["Upstream E&P companies typically trade at 4-6x EV/EBITDA (lower than average due to commodity price volatility and high capital intensity).","Assume 5x EV/EBITDA: EV = $1B x 5 = $5B.","To get Equity Value, subtract Net Debt: Equity Value = EV - Net Debt = $5B - $2B = $3B.","The key is to state your assumed multiple, justify it, and clearly bridge from EV to Equity Value. Be prepared to discuss why E&P multiples are lower (commodity risk, high CapEx, reserve depletion)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0767","t":"val","l":"Advanced","s":90,"q":"The same upstream company has a recent Non-GAAP mid-year earnings report that has been very positive. How will the Equity Value change, and what will drive that change from the equation?","k":["Equity Value will increase, driven primarily by a higher share price.","A positive Non-GAAP earnings report signals stronger-than-expected operational performance (higher production volumes, better realizations, lower costs). This can affect Equity Value through:","Higher EBITDA expectations: If the market revises EBITDA estimates upward, EV increases (higher multiple x higher EBITDA), which flows through to higher Equity Value.","Multiple expansion: Positive surprise may cause investors to assign a higher multiple, reflecting increased confidence in the company.","Share price reaction: The market will bid up the stock price, directly increasing Equity Value (= Share Price x Shares Outstanding)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0768","t":"val","l":"Advanced","s":90,"q":"If you acquire another company for $100, funded 50% with debt and 50% with cash, what happens to enterprise value and equity value?","k":["Assuming the acquisition price equals the fair value of the target (no overpayment):","Enterprise Value: Increases by $100 (you added $100 of operating assets).","Debt: Increases by $50.","Cash: Decreases by $50.","Net Debt change: +$50 (debt) + $50 (less cash) = +$100.","Equity Value: EV increased by $100, Net Debt increased by $100, so Equity Value = EV - Net Debt is unchanged.","In short: EV increases by the purchase price. Equity value is unchanged because the increase in EV is fully offset by the increase in net debt."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","Enterprise & Equity Value","Advanced"]},{"id":"q-0769","t":"val","l":"Advanced","s":90,"q":"A company has an Equity Value of $5 billion, $2 billion of debt, and $2 billion of cash.\n\n\n\n\nIf the company uses all of its cash for operations, what happens to its Enterprise Value?","k":["Answer: EV increases to $7 billion","Calculation:","Initial EV = $5B + $2B - $2B = $5B.","After using cash: EV = $5B + $2B - $0 = $7B.","Cash decreases by $2B, increasing EV by $2B.","Note: Equity Value remains unchanged initially, but the use of cash for operations may impact future value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Greenhill & Co. Interview","M&A group, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0770","t":"val","l":"Advanced","s":90,"q":"How does a dividend recapitalization of $100 affect Enterprise Value?","k":["Enterprise Value does not change.","In a dividend recapitalization, a company raises new debt ($100) and uses the proceeds to pay a special dividend to equity holders ($100).","Debt increases by $100.","Cash goes up by $100 (from debt) and down by $100 (paid as dividend). Net cash change is zero.","EV = Equity Value + Debt - Cash. Debt +100 and Equity Value -100 offset, so EV is unchanged.","The dividend recap transfers value from the enterprise (via increased leverage) to equity holders. It is commonly used in LBOs to return capital to PE sponsors without selling the company."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Greenhill & Co. Interview","SF Office, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0771","t":"val","l":"Advanced","s":90,"q":"Use the following information:\n\n\n\nEnterprise value – $1,500\nMarket value of equity – $1,000\nBook value of equity – $500\nNon‑controlling interest – $50\nNet income – $100\nNet income margin – 25%\nEPS – $2\n\n\n\nAnswer the following:\n\nNet debt\nCurrent share price\nP/E multiple\nRevenue\nEV / Revenue multiple\nWhy might you use P/E instead of EV / Revenue?","k":["Part 1 – Net Debt: $450","Net debt = EV − Equity value − NCI = 1,500 − 1,000 − 50 = 450.","Part 2 – Share Price: $20","Shares = Net income / EPS = 100 / 2 = 50.","Price = Market cap / Shares = 1,000 / 50 = 20.","Part 3 – P/E Multiple: 10×","P/E = Price / EPS = 20 / 2 = 10×.","Part 4 – Revenue: $400","Revenue = Net income / Margin = 100 / 25% = 400.","Part 5 – EV / Revenue: 3.75×","1,500 / 400 = 3.75×.","Part 6 – P/E vs. EV / Revenue","P/E is widely available for profitable public companies and reflects equity‑holder economics.","EV / Revenue is useful when earnings are negative or distorted but is a cruder measure because it ignores margins and capital structure."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Guggenheim Partners Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0772","t":"val","l":"Advanced","s":90,"q":"Do we look at any equity value metrics for pre-revenue companies? If so, which ones?","k":["Yes, but the traditional equity value metrics (P/E, Price/Earnings) are not applicable since there are no earnings. Instead:","Market Cap / Cash on Hand: Shows how much the market values the pipeline above the company's cash. If market cap is $500M and cash is $300M, the market is assigning $200M to pipeline assets.","Price / Book Value: Useful as a floor, especially for biotech companies with significant cash from recent fundraising.","Implied value per pipeline asset: Divide equity value by the number of clinical-stage programs to benchmark against comparable deals.","For tech companies: Price / Monthly Active Users, Price / Gross Merchandise Value, or Price / ARR (if early revenue exists)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0773","t":"val","l":"Advanced","s":90,"q":"You are given the following information:\n\n\n\nEV/EBITDA: 12x\nLeverage: 6x\nNet Debt: $300M\n\n\n\nPart 1: Calculate the Enterprise Value and EBITDA.\n\n\n\n\nPart 2: Given Net Income of $25M, calculate the P/E multiple and Equity Value.\n\n\n\n\nPart 3: The company is raising capital via an IPO. The industry average leverage is 3x. How much should the IPO raise?\n\n\n\n\nPart 4: What is the original equity holders' ownership post-IPO?\n\n\n\n\nPart 5: What is the new P/E multiple after the IPO? Assume you ask for a 5% interest rate on the debt and a 0% tax rate.","k":["Part 1","Leverage = Net Debt / EBITDA = 6x, so EBITDA = $300M / 6 = $50M","EV = EV/EBITDA x EBITDA = 12 x $50M = $600M","Part 2","Equity Value = EV - Net Debt = $600M - $300M = $300M","P/E = Equity Value / NI = $300M / $25M = 12.0x","Part 3","Target Net Debt at 3x leverage = 3 x $50M = $150M","Current Net Debt = $300M. Need to reduce by $150M.","IPO should raise $150M (used to pay down debt to reach 3x leverage).","Part 4","Pre-IPO Equity Value = $300M. New equity raised = $150M.","Post-IPO Equity Value = $300M + $150M = $450M","Original holders' ownership = $300M / $450M = 66.7%","Part 5","Original interest expense: EBITDA - NI = $50M - $25M = $25M (at 0% tax, pre-tax income = NI). Implied original rate = $25M / $300M = 8.33%.","After IPO, remaining debt = $150M. New interest rate = 5%. New interest expense = $150M x 5% = $7.5M.","New NI = EBITDA - New Interest = $50M - $7.5M = $42.5M (at 0% tax rate).","New Equity Value = EV - New Net Debt = $600M - $150M = $450M","New P/E = $450M / $42.5M = 10.6x"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in J.P. Morgan Interview","SA 2025","Enterprise & Equity Value","Advanced"]},{"id":"q-0774","t":"val","l":"Advanced","s":90,"q":"Part 1: What are fully diluted shares? Explain this concept.\n\n\n\n\nPart 2: If a company's share price goes down, does its EPS change?","k":["Part 1: Fully Diluted Shares","Fully diluted shares represent the total number of shares that would be outstanding if all dilutive securities were exercised or converted. This includes basic shares plus the net impact of in-the-money stock options and warrants (using the Treasury Stock Method), RSUs, and shares from convertible debt and preferred stock (using the if-converted method).","Part 2: Share Price Decline and EPS","Basic EPS does not change -- it equals Net Income / Basic Shares Outstanding, and neither numerator is affected by the share price. However, diluted EPS can change: a lower share price means fewer options and warrants are in-the-money, reducing dilution from the Treasury Stock Method. With fewer dilutive shares, diluted share count decreases, which would actually increase diluted EPS (all else equal)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in J.P. Morgan Interview","SA 2025","Enterprise & Equity Value","Advanced"]},{"id":"q-0775","t":"val","l":"Advanced","s":90,"q":"How does a $100 million secondary sale of shares by existing investors impact TEV and equity value?","k":["No change in either.","Shares simply move from existing holders to new investors; the company raises no cash and issues no new shares → equity value and TEV stay flat."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Jefferies Interview","SA 2026, New York office, M&A group","Enterprise & Equity Value","Advanced"]},{"id":"q-0776","t":"val","l":"Advanced","s":90,"q":"Part 1: Using the treasury stock method, calculate the dilutive effect of 1,000 options with a $10 strike price when the current share price is $5.\n\n\n\n\nPart 2: Now assume the share price is $10 and the strike price is $5. What is the dilutive effect?","k":["Part 1: Share Price $5, Strike $10","Options are out of the money ($10 strike > $5 share price).","No dilution. Net new shares = 0.","Part 2: Share Price $10, Strike $5","Options are in the money.","1,000 options exercised. Proceeds = 1,000 x $5 = $5,000.","Shares repurchased = $5,000 / $10 = 500 shares.","Net new shares = 1,000 - 500 = 500 shares.","Dilutive effect = 500 additional shares."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Jefferies Interview","SA 2025, TMT group, SF Office, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0777","t":"val","l":"Advanced","s":90,"q":"Company A has $100 in unlevered free cash flow (UFCF) and $100 in levered free cash flow (LFCF). Company B has $100 in UFCF and $95 in LFCF. Which company has the higher Enterprise Value and which has the higher Equity Value?","k":["Enterprise Value","Both have the same Enterprise Value. UFCF is the same ($100), and since EV is derived from UFCF (which is capital structure-neutral), both companies have the same EV assuming identical growth, risk, and discount rates.","Equity Value","Company A has the higher Equity Value. Company A has LFCF = UFCF, implying zero debt service costs (no interest, no mandatory repayments). Company B's LFCF is $5 lower, meaning it has debt with associated interest/repayment costs. Since EV = Equity Value + Net Debt, and both have the same EV, Company B must have higher net debt and therefore lower Equity Value."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0778","t":"val","l":"Advanced","s":90,"q":"A company has the following characteristics:\n\n\n\nTotal Assets: $3,000\nLeverage (Total Debt / Book Equity): 3.0x\nPrice to Book Value (P/BV): 2.0x\n\n\n\nAnswer the following questions based on this data:\n\n\n\nWhat are the company's Total Debt, Book Equity, and Market Cap?\nAssuming zero cash on the balance sheet, what is the company's Enterprise Value?\nIf the company trades at a 15.0x P/E multiple, what is its Net Income?\nIn a separate scenario, if this company has an EBITDA of $200 and is sold for an 8.0x EV/EBITDA multiple, what is the implied Enterprise Value of the transaction?\nFollowing on from the previous part, what is the implied P/E ratio of the transaction?","k":["Key Outputs","Total Debt $2,250","Book Equity $750","Market Cap $1,500","Enterprise Value $3,750","Net Income $100","Transaction EV $1,600","Implied P ÷ E ≈ −6.5× (equity underwater)","Calculations:","Assets = Debt + Equity ⇒ 3,000 = 4E ⇒ E = 750.","Debt = 3× 750 = 2,250.","Market Cap = 2.0× 750 = 1,500.","EV = 1,500 + 2,250 = 3,750.","NI = 1,500 ÷ 15 = 100.","Transaction EV = 8× 200 = 1,600.","Equity Value at exit = 1,600 − 2,250 = −650 ⇒ P ÷ E = −650 ÷ 100."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Lazard Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0779","t":"val","l":"Advanced","s":90,"q":"What is the impact on a company's EV/EBITDA and P/E multiples from the following actions?\n\n\n\n\nPart 1: The company issues debt to buy back shares.\n\n\n\n\nPart 2: The company issues new shares and holds the proceeds as cash on its balance sheet.","k":["Part 1: Debt-Financed Buyback","EV/EBITDA: Generally unchanged (EV remains constant as Debt rises and Equity falls by similar amounts; EBITDA is unaffected).","P/E: Usually decreases. Mechanically, if Cost of Debt (after-tax) is lower than Earnings Yield, EPS increases. Higher EPS with same share price = lower P/E. The P/E may also contract because the company is now more leveraged and riskier, increasing the cost of equity.","Part 2: Equity Issuance","EV/EBITDA: Unchanged (Equity up, Cash up; EV = Equity + Debt - Cash remains constant).","P/E: Increases. Equity Value rises immediately due to new shares, but Net Income only increases slightly (interest income on cash), causing P/E to rise (or EPS to dilute)."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Lazard Interview","FIG First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0780","t":"val","l":"Advanced","s":90,"q":"What has a greater impact on equity value: using $1 to pay down debt, or a $1 increase in EBITDA?","k":["A $1 increase in EBITDA has a far greater impact on equity value.","$1 debt paydown: Reduces debt by $1, which increases equity value by exactly $1 (since EV = Equity + Net Debt, and EV stays the same).","$1 EBITDA increase: If the company trades at 10x EV/EBITDA, enterprise value increases by $10. Assuming no change in debt, equity value increases by $10.","The EBITDA increase is amplified by the valuation multiple, making it far more impactful than a dollar-for-dollar debt reduction."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Lazard Interview","SA 2025, SF Office, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0781","t":"val","l":"Advanced","s":90,"q":"Company A has a share price of $30, 800K common shares, 450K options with a $20 strike price, and a $1.25M convertible bond at $25. Find the diluted shares outstanding.","k":["Answer: 1,000K (1,000,000) diluted shares","Basic shares: 800K","Options (Treasury Stock Method): 450K options at $20 strike. Proceeds = 450K x $20 = $9M. Shares repurchased = $9M / $30 = 300K. Net new shares = 450K - 300K = 150K.","Convertible bond: $1.25M convertible at $25 per share. Shares from conversion = $1.25M / $25 = 50K. Since share price ($30) > conversion price ($25), the bond is in-the-money and dilutive.","Diluted shares = 800K + 150K + 50K = 1,000K"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Lazard Interview","SA 2025, Healthcare group, SF Office, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0782","t":"val","l":"Advanced","s":90,"q":"If all cash is needed for operations, is it included in Enterprise Value?","k":["Yes.","Operating cash is an operating asset, so it remains inside EV just like working capital."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in LionTree Interview","SA 2026","Enterprise & Equity Value","Advanced"]},{"id":"q-0783","t":"val","l":"Advanced","s":90,"q":"Why is NCI (Non-Controlling Interest) included in EV?","k":["Because the parent consolidates 100% of the subsidiary’s revenue and EBITDA, you add NCI so Enterprise Value reflects 100% of those earnings."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in LionTree Interview","SA 2026","Enterprise & Equity Value","Advanced"]},{"id":"q-0784","t":"val","l":"Advanced","s":90,"q":"Enterprise Value is 500, senior debt 100, undrawn revolver 50, cash 50, equity investments 50, and unfunded pension obligations of 100.\n\n\n\n\nWhat is the equity value?","k":["$400.","Net Debt = 100 – 50 = 50","Debt‑like Pension Obligation = 100","Non‑core Equity Investments (cash‑like) = -50","EV = Eq Value + 50 + 100 – 50 = Eq Value + 100","Set 500 = Eq Value + 100 → Eq Value = 400."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Moelis & Co. Interview","SA 2025, Los Angeles Office, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0785","t":"val","l":"Advanced","s":90,"q":"If a company has an EV of 900, debt of 300, and cash of 100, what is the equity value, and what is it after a 3-for-1 stock split?","k":["Equity value = EV − Net Debt = 900 − 300 + 100 = 700.","After a 3‑for‑1 split, equity value remains 700; share price divides by 3 while share count triples."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Moelis & Co. Interview","First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0786","t":"val","l":"Advanced","s":90,"q":"A company provides the following financial data:\n\n\n\nRevenue: $2,000\nSG&A: $500\nTotal Debt: $1,000\nInterest Rate on Debt: 10%\nTax Rate: 25%\nShares Outstanding: 100\nP/E Multiple: 20.0x\n\n\n\nWhat is the company's current share price?","k":["$210","EBIT = 2,000 − 500 = 1,500.","Interest = 1,000 × 10% = 100.","Pre‑tax = 1,400 ⇒ NI = 1,400 × (1 − 25%) = 1,050.","EPS = 1,050 / 100 = 10.5.","Price = EPS × P/E = 10.5 × 20 = 210."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Moelis & Co. Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0787","t":"val","l":"Advanced","s":90,"q":"If two companies are in the same industry and have the exact same Enterprise Value, why might one have a significantly different EBITDA than the other?","k":["The market assigns a higher EV∕EBITDA multiple to the perceived higher‑quality firm, so identical EVs translate into different EBITDA levels.","Drivers of multiple variation:","Growth prospects and margin durability.","Recurring versus transactional revenue mix.","Regulatory or geographic risk profile.","Capital‑expenditure intensity and free‑cash conversion.","Potential synergies or strategic value to acquirers."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Moelis & Co. Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0788","t":"val","l":"Advanced","s":90,"q":"How would you calculate a company's equity value given its P/E ratio, tax rate, revenue, shares outstanding, gross margin, debt, interest rate, and SG&A expenses?","k":["Calculation steps:","Gross Profit = Revenue * Gross Margin","EBIT = Gross Profit - SG&A","Interest Expense = Debt * Interest Rate","EBT = EBIT - Interest Expense","Net Income = EBT * (1 - Tax Rate)","Equity Value = Net Income * P/E Ratio","Alternatively: EPS = Net Income / Shares Outstanding. Share Price = EPS * P/E. Equity Value = Share Price * Shares Outstanding."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Moelis & Co. Interview","First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0789","t":"val","l":"Advanced","s":90,"q":"You are given the following financial data for a company:\n\n\n\nRevenue: $90M\nEBITDA Margin: 50%\nD&A: $6M\nTax Rate: 20%\nDebt/EBITDA: 2x\nInterest Rate on Debt: 10%\nShares Outstanding: 40M\nCash Balance: $15M\nP/E: 5x\n\n\n\nCalculate the following: Net Income, Market Capitalization, Stock Price, EPS, and Enterprise Value.","k":["Calculation:","EBITDA = $90M x 50% = $45M","Debt = 2x x $45M = $90M","Interest Expense = $90M x 10% = $9M","EBIT = EBITDA - D&A = $45M - $6M = $39M","Pre-Tax Income = EBIT - Interest = $39M - $9M = $30M","Net Income = $30M x (1 - 20%) = $24M","EPS = $24M / 40M shares = $0.60","Market Cap = P/E x NI = 5 x $24M = $120M (or EPS x P/E x Shares = $0.60 x 5 x 40M = $120M)","Stock Price = $120M / 40M shares = $3.00","Enterprise Value = Market Cap + Debt - Cash = $120M + $90M - $15M = $195M"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Moelis & Co. Interview","SA 2026, Chicago Office, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0790","t":"val","l":"Advanced","s":90,"q":"You are given the following information for a company:\n\n\n\n$100M EBITDA\n8x EV/EBITDA\n20% EBITDA Margin\n10% Interest Rate\n5x Leverage (Debt/EBITDA)\n10x P/E\n$0 D&A\n$0 Cash\n\n\n\nWhat is the implied tax rate?\n\n\n\n\nFollow-up: If the EV/EBITDA multiple increases, what mathematically happens to the implied tax rate?","k":["Answer: 40% implied tax rate.","Calculation:","EV = 8 x $100M = $800M","Debt = 5 x $100M = $500M","Interest Expense = $500M x 10% = $50M","EBITDA = $100M, D&A = $0, so EBIT = $100M","Pre-Tax Income = EBIT - Interest = $100M - $50M = $50M","Equity Value = EV - Debt = $800M - $500M = $300M (assuming no cash)","Net Income = Equity Value / P/E = $300M / 10 = $30M","Tax = Pre-Tax Income - NI = $50M - $30M = $20M","Tax Rate = $20M / $50M = 40%","Follow-up: If EV/EBITDA increases","A higher EV/EBITDA increases EV, which increases Equity Value (since Debt is fixed). A higher Equity Value means higher implied NI (since P/E is fixed at 10x). Higher NI with the same Pre-Tax Income means lower taxes, which means a lower implied tax rate. So as EV/EBITDA increases, the implied tax rate decreases."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Moelis & Co. Interview","SA 2027","Enterprise & Equity Value","Advanced"]},{"id":"q-0791","t":"val","l":"Advanced","s":90,"q":"Part 1: You are given the following data:\n\n\n\nTax Rate = 25%\nRevenue = $2 billion\nShares Outstanding = 100 million\nEV/EBITDA = 7.5x\nNet Debt = $1 billion\nInterest Rate = 10%\nEBITDA = $400 million\n\n\n\nCalculate the share price.\n\n\n\n\nPart 2: Assuming the company trades at a 20x P/E, what is its implied Depreciation & Amortization?","k":["Part 1: Share Price","Answer: $20 per share","EV = 7.5 x $400M = $3,000M","Equity Value = EV - Net Debt = $3,000M - $1,000M = $2,000M","Share Price = $2,000M / 100M shares = $20","Part 2: Implied D&A","Answer: $166.7 million","From Part 1, Share Price = $20 and Shares = 100M, so Equity Value = $2,000M","Net Income = Equity Value / P/E = $2,000M / 20 = $100M","Pre-Tax Income = $100M / (1 - 0.25) = $133.3M","Interest Expense = 10% x $1,000M = $100M","EBIT = Pre-Tax Income + Interest = $133.3M + $100M = $233.3M","D&A = EBITDA - EBIT = $400M - $233.3M = $166.7M"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Moelis & Co. Interview","SA 2025","Enterprise & Equity Value","Advanced"]},{"id":"q-0792","t":"val","l":"Advanced","s":90,"q":"A company has $500 million in enterprise value, 50 million shares trading at $6 per share, and $100 million in cash. What is the cost of debt?","k":["This is a trick question. You cannot determine the cost of debt from this information alone. You can only calculate the total debt balance.","Calculation:","Equity Value = 50M shares x $6 = $300M","EV = Equity Value + Debt - Cash","$500M = $300M + Debt - $100M","Debt = $300M","To calculate the cost of debt, you would need additional information such as interest expense or the interest rate on the debt."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Moelis & Co. Interview","SA 2027","Enterprise & Equity Value","Advanced"]},{"id":"q-0793","t":"val","l":"Advanced","s":90,"q":"Calculate the fully diluted share count given the following information:\n\n\n\nShare Price: $100\nClass A Shares: 500\nClass C Shares: 100\nRSUs: 100 (grant price: $120)\nStock Options: 100 (exercise price: $50)\nClass A Warrants: 100 (exercise price: $80)\nClass B Warrants: 100 (exercise price: $105)\nConvertible Notes: $1,000 (conversion price: $125)\nConvertible Preferred: $1,500 (conversion price: $50)","k":["Answer: 800 fully diluted shares","Using the Treasury Stock Method (TSM) for options/warrants, and conversion method for convertibles:","Basic shares: 500 (Class A) + 100 (Class C) = 600","RSUs: 100 shares (RSUs are always included regardless of grant price -- no exercise price to pay)","Stock Options (exercise $50 < $100 share price -- in the money): 100 options issued - (100 x $50 / $100) = 100 - 50 = 50 net new shares","Class A Warrants (exercise $80 < $100 -- in the money): 100 warrants - (100 x $80 / $100) = 100 - 80 = 20 net new shares","Class B Warrants (exercise $105 > $100 -- out of the money): 0 net new shares","Convertible Notes ($125 conversion price > $100 -- out of the money): 0 shares","Convertible Preferred ($50 conversion price < $100 share price -- in the money): $1,500 / $50 = 30 shares added via the if-converted method.","Fully Diluted Shares = 600 + 100 + 50 + 20 + 0 + 0 + 30 = 800","Note: Some interpretations exclude the Convertible Preferred from a basic TSM diluted count if a separate if-converted test is required. Under the straightforward approach above, the answer is 800. If only equity-like dilutive securities using TSM are included (excluding convertible preferred which requires a separate if-converted analysis), the answer is 770."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Moelis & Co. Interview","SA 2026, Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0794","t":"val","l":"Advanced","s":90,"q":"How do enterprise value and equity value change if $50 in cash is stolen?\n\n\n\n\nWhat if that cash was operational?","k":["Excess Cash","Equity Value –50, EV unchanged (cash is subtracted in the EV bridge).","Operational Cash","Both Equity Value and EV drop 50 because operating cash is part of core assets and not deducted from EV."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Perella Weinberg Interview","Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0795","t":"val","l":"Advanced","s":90,"q":"A company has an Enterprise Value of $1B, EBITDA of $100M, cash of $200M, debt of $300M, non-controlling interest (NCI) of $60M, and Net Income of $40M. Solve for the P/E multiple.","k":["Answer: 21.0x","EV = Equity Value + Debt - Cash + NCI","$1,000 = Equity Value + $300 - $200 + $60","Equity Value = $1,000 - $300 + $200 - $60 = $840M","P/E = Equity Value / Net Income = $840 / $40 = 21.0x"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in Perella Weinberg Interview","SA 2026, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0796","t":"val","l":"Advanced","s":90,"q":"A firm has Net Debt / EBITDA = 3x, EV / EBITDA = 10x, and market cap = $560 million.\n\n\n\n\nWhat is its enterprise value?","k":["Answer: $800m","Net Debt = 3x EBITDA → EV = 10x EBITDA.","EV = EqV + Net Debt → 10x EBITDA = 560 + 3x EBITDA → 7x EBITDA = 560 → EBITDA = 80m","EV = 10 x $80m = $800m."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in PJT Partners Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0797","t":"val","l":"Advanced","s":90,"q":"Two companies have the same EV/EBITDA multiple but different P/E multiples. What could explain this difference?","k":["Key factors explaining the difference:","Capital structure: Different debt levels affect equity value (P/E numerator) but not enterprise value (EV/EBITDA numerator).","Depreciation & Amortization: Higher D&A reduces Net Income (lowering EPS, raising P/E) but doesn't affect EBITDA.","Interest expense: Higher debt means more interest, reducing NI and EPS, thus raising P/E, while EBITDA is unaffected.","Tax rates: Different effective tax rates impact NI but not EBITDA.","Non-operating items: One-time gains/losses, investments in associates affect NI but not EBITDA."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in PJT Partners Interview","New York Office","Enterprise & Equity Value","Advanced"]},{"id":"q-0798","t":"val","l":"Advanced","s":90,"q":"A company has the following metrics:\n\n\n\nGross Debt / EBITDA = 5.0x\nEV / EBITDA = 10.0x\nMarket Cap = $400M\nCash = $100M\n\n\n\nCalculate its Total Enterprise Value (TEV).","k":["Answer: $600M","Calculation:","Debt = 5.0x * EBITDA and EV = $400M + 5.0x * EBITDA - $100M = 10.0x * EBITDA","$300M + 5.0x * EBITDA = 10.0x * EBITDA","$300M = 5.0x * EBITDA","EBITDA = $60M","TEV = 10.0x * $60M = $600M"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in PJT Partners Interview","First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0799","t":"val","l":"Advanced","s":90,"q":"You are given the following information for a company:\n\n\n\nEBITDA: $55 million\nEV/EBITDA: 10x\nDebt: $65 million\nCash: $10 million\nEquity Investments: $5 million\nShares Outstanding: 10 million\n\n\n\nThe company raises $100 million in new debt. For each of the following scenarios, determine the impact on Enterprise Value, Market Capitalization, and Share Price:\n\n\n\n\nScenario A: The company uses the $100 million to pay a dividend.\n\n\n\n\nScenario B: The company uses the $100 million to buy back shares.\n\n\n\n\nScenario C: The company does nothing with the $100 million cash.","k":["First, calculate baseline values:","EV = 10 x $55M = $550M","Equity Value = EV - Debt + Cash - Minority Interest (= $0 in this case) + Equity Investments = $550 - $65 + $10 + $5 = $500M","Share Price = $500M / 10M = $50","Raising the debt on its own changes nothing: Debt goes to $165M and Cash to $110M, which offset in the bridge. No scenario touches the operating business, so EV is $550M in all three.","Scenario A: $100M Dividend","Debt $165M, Cash back to $10M (the $100M was paid out).","Market Cap: $500M - $100M = $400M, since $100M of value left the firm.","EV: $400M + $165M - $10M - $5M = $550M. The cash paid out does not reduce EV — less cash pushes EV up, and the lower Market Cap brings it back.","Share Price: $400M / 10M = $40, share count unchanged. Shareholders are whole: a $40 share plus $10/share of cash received.","Scenario B: $100M Buyback","Debt $165M, Cash back to $10M. Shares repurchased = $100M / $50 = 2M, leaving 8M.","Market Cap: $500M - $100M = $400M. EV: $400M + $165M - $10M - $5M = $550M.","Share Price: $400M / 8M = $50. No change — Market Cap and share count fall proportionally.","Scenario C: Does Nothing","Debt $165M, Cash $110M. Market Cap: $500M, unchanged as debt and cash offset.","EV: $500M + $165M - $110M - $5M = $550M. Share Price: $50. No change."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in PJT Partners Interview","SA 2026, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0800","t":"val","l":"Advanced","s":90,"q":"Given the following information, calculate the stock price of the company: P/E = 20x, Tax Rate = 25%, Revenue = $2,000, Gross Margin = 50%, SG&A (includes D&A) = $500, Outstanding Shares = 100, EV/EBITDA = 7.5x, Debt = $1,000, Interest Rate = 10%.","k":["Answer: $60.00. The key insight is that the EV/EBITDA multiple is a distractor — since SG&A includes D&A, there is no way to independently compute EBITDA. You must use the P/E approach instead.","Gross Profit = $2,000 x 50% = $1,000.","EBIT = Gross Profit - SG&A = $1,000 - $500 = $500.","Interest Expense = $1,000 x 10% = $100.","Pre-Tax Income = $500 - $100 = $400.","Taxes = $400 x 25% = $100.","Net Income = $300.","EPS = $300 / 100 = $3.00.","Stock Price = EPS x P/E = $3.00 x 20 = $60.00."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["New","Reported in PJT Partners Interview","SA 2025, Houston Office, First round","Enterprise & Equity Value","Advanced"]},{"id":"q-0801","t":"val","l":"Advanced","s":90,"q":"Can a company have a negative EV? What does that mean?\n\n\n\n\nFollow-up: How would you value a company with negative EV?","k":["Yes — it happens when cash and equivalents exceed market cap plus debt and other claims.","It often signals distress, excess cash or market mispricing.","Valuation approach:","Value cash at face and debt at par.","Use relative or asset‑based methods for operations.","Cross‑check with liquidation analysis if distress is likely."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Rothschild Interview","SA 2026","Enterprise & Equity Value","Advanced"]},{"id":"q-0802","t":"val","l":"Advanced","s":90,"q":"If the EV/EBIT of a company is 3x and its EV/EBITDA is 4x, what does that tell you about the company?","k":["EBITDA is < EBIT, so D&A is negative.","Because EV is constant, a higher EV/EBITDA multiple means the EBITDA denominator is smaller than EBIT, which only happens if D&A is recorded as a credit (e.g., reversal of impairment, amortization of negative goodwill, or other non-recurring income).","It's worth noting that this scenario is unusual and likely reflects an accounting anomaly rather than normal operations."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Union Square Advisors Interview","SA 2026, Pre-first round Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0803","t":"val","l":"Advanced","s":90,"q":"You have two identical companies, except for their capital structure.\n\n\n\n\nCompany A is capitalized with 30% debt and 70% equity, while Company B is capitalized with 100% equity.\n\n\n\n\nWhich company has the higher Net Income, WACC, and Enterprise Value?","k":["Comparison:","Net Income: Company B is higher. Company A has interest expense reducing NI, while B has none.","WACC: Company A is lower. Debt is cheaper than equity (due to tax shield), lowering overall WACC.","Enterprise Value: Company A is higher. Due to the tax-deductibility of interest, using debt creates a \"tax shield\" that adds value to the firm. Therefore, the levered firm's Enterprise Value will be greater than the unlevered firm's value by the present value of this tax shield, assuming all else is equal."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Unspecified Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0804","t":"val","l":"Advanced","s":90,"q":"Part 1: A company has an Enterprise Value of $550, Debt of $60, Cash of $10, and 10 shares outstanding. What is its share price?\n\n\n\n\nPart 2: The company then raises $50 of new debt and holds it as cash. What is the new share price?\n\n\n\n\nPart 3: Instead, the company raises $50 of debt and uses the proceeds to pay a dividend. What is the new share price?\n\n\n\n\nPart 4: As another alternative, the company raises $50 of debt and uses the proceeds to repurchase stock. What is the new share price?\n\n\n\n\nPart 5: Comparing the dividend and share repurchase scenarios, in which case are investors better off?","k":["Part 1: Share Price","Answer: $50","Equity Value = EV - Debt + Cash = $550 - $60 + $10 = $500","Share Price = $500 / 10 shares = $50","Part 2: Raise Debt, Hold Cash","Answer: $50","New Cash = $10 + $50 = $60","New Debt = $60 + $50 = $110","Equity Value = $550 - $110 + $60 = $500","Share Price = $500 / 10 shares = $50 (unchanged)","Part 3: Raise Debt, Pay Dividend","Answer: $45","New Debt = $60 + $50 = $110","Cash unchanged at $10 (raised cash paid out)","Equity Value = $550 - $110 + $10 = $450","Share Price = $450 / 10 shares = $45","Part 4: Raise Debt, Repurchase Stock","Answer: $50","New Debt = $60 + $50 = $110","Shares Repurchased = $50 / $50 = 1 share","New Shares Outstanding = 10 - 1 = 9 shares","Equity Value = $550 - $110 + $10 = $450","Share Price = $450 / 9 shares = $50","Part 5: Investor Comparison","Investors are economically indifferent in a perfect market with no taxes.","Dividend: Investors receive $5/share cash, hold shares worth $45 = $50 total value","Buyback: Investors hold shares worth $50","However, in practice, buybacks are often preferable due to tax efficiency (capital gains vs. dividend taxation)"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Unspecified Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0805","t":"val","l":"Advanced","s":90,"q":"Calculate Enterprise Value given the following information. Assume a 20% tax rate.\n\n\n\nAnnual Interest Expense = $20\nEquity Value = $1,000\nEV/EBITDA = 12x\nP/E = 25x\nCost of Debt = 10%\nAnnual D&A = $30","k":["Answer: $1,200","Method 1 (Shortcut):","Total Debt = Interest Expense / Cost of Debt = $20 / 10% = $200","EV = Equity Value + Debt = $1,000 + $200 = $1,200 (assuming no cash)","Method 2 (Income Statement walk):","From P/E = 25x and Equity Value = $1,000, find Net Income:","NI = $1,000 / 25 = $40","Find Pre-Tax Income (EBT):","EBT = NI / (1 - Tax Rate) = $40 / (1 - 0.20) = $50","Find EBIT:","EBIT = EBT + Interest Expense = $50 + $20 = $70","Find EBITDA:","EBITDA = EBIT + D&A = $70 + $30 = $100","Calculate Enterprise Value:","EV = EBITDA * EV/EBITDA Multiple = $100 * 12x = $1,200"],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Unspecified Interview","Enterprise & Equity Value","Advanced"]},{"id":"q-0806","t":"val","l":"Advanced","s":90,"q":"Part 1: Given a company's EBITDA, EV/EBITDA multiple, net debt, shares outstanding, and a list of options with their strike prices, how would you calculate the price per share?\n\n\n\n\nPart 2: How would your approach change if you were given Net Income and a P/E multiple instead of EBITDA and an EV/EBITDA multiple?","k":["Part 1: Using EV/EBITDA","Calculate EV = EBITDA * EV/EBITDA multiple.","Calculate Equity Value = EV - Net Debt.","Apply Treasury Stock Method for options to get diluted shares.","Share Price = Equity Value / Diluted Shares Outstanding.","Part 2: Using P/E","Calculate Equity Value = NI * P/E multiple.","Apply Treasury Stock Method for options to get diluted shares.","Share Price = Equity Value / Diluted Shares.","Key difference: With P/E, you start at equity value directly; with EV/EBITDA, you must bridge from EV to equity value by subtracting net debt."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Unspecified Interview","Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0807","t":"val","l":"Advanced","s":90,"q":"If you have two companies with the same Enterprise Value, but one has higher leverage than the other, which one has the higher P/E ratio?","k":["The company with lower leverage (less debt) will have the higher P/E ratio.","Reasoning:","Risk: Higher leverage increases the financial risk for equity holders. Investors demand a higher rate of return to compensate for this increased risk.","Cost of Equity and P/E: A higher required return on equity (Cost of Equity) translates directly to a lower P/E multiple an investor is willing to pay for a dollar of earnings.","Conclusion: Therefore, the company with higher leverage will be perceived as riskier and will trade at a lower P/E multiple, all else being equal."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Unspecified Interview","Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0808","t":"val","l":"Advanced","s":90,"q":"What is the net impact on a company's Enterprise Value if it raises $50m in equity, raises $75m in debt, and pays out a $100m dividend?","k":["Answer: No change to Enterprise Value.","Analysis:","Raise $50M equity: Cash +$50M, Equity Value +$50M. EV unchanged (EqV +$50M, Cash +$50M offset).","Raise $75M debt: Cash +$75M, Debt +$75M. EV unchanged (Debt +$75M, Cash +$75M offset).","Pay $100M dividend: Cash -$100M, Equity Value -$100M. EV unchanged (EqV -$100M, Cash -$100M offset).","Net: Cash +$25M ($50M + $75M - $100M), Debt +$75M, Equity Value -$50M. Enterprise Value = unchanged."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Unspecified Interview","Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0809","t":"val","l":"Advanced","s":90,"q":"Two companies have the same Enterprise Value, but one has a higher debt-to-equity ratio. Which company will have the higher P/E multiple?","k":["The company with lower leverage (less debt) will have the higher P/E ratio.","Reasoning:","Same Enterprise Value: Both companies have the same total value available to all capital providers.","Risk Effect (Dominant Factor): Higher leverage increases financial risk for equity holders. This increased risk leads to a higher cost of equity.","Valuation Impact: Investors will pay less for a dollar of riskier earnings, which directly translates to a lower P/E multiple.","Net Result: The risk effect dominates the mechanical effects on the P/E formula. Higher financial risk commands a lower valuation multiple, resulting in a lower P/E for the more leveraged company."],"collection":"practice","topic":"Enterprise & Equity Value","tags":["Reported in Unspecified Interview","Superday","Enterprise & Equity Value","Advanced"]},{"id":"q-0810","t":"val","l":"Basic","s":90,"q":"Two companies have the same financial statements, growth projections, same industry, but trade at different EV/EBITDA multiples.\n\n\n\n\nWhy could that happen?","k":["Qualitative factors the numbers miss:","Perceived risk (contract quality, customer concentration)","Management credibility or governance","Liquidity of the float or index inclusion","M&A rumors or takeover premium","Differing ESG profiles or regulatory risks"],"collection":"practice","topic":"Valuation","tags":["Reported in Allen & Company Interview","SA 2026","Valuation","Basic"]},{"id":"q-0811","t":"val","l":"Basic","s":90,"q":"If you can't find EBITDA for a company (for example, a private comp), where might you look?","k":["Sources and proxies:","Add D&A from the cash‑flow statement to EBIT from the income statement.","Use management presentations or lender information memos.","Check equity research or industry reports.","Ask management directly or infer using peer margins."],"collection":"practice","topic":"Valuation","tags":["Reported in Allen & Company Interview","SA 2026","Valuation","Basic"]},{"id":"q-0812","t":"val","l":"Basic","s":90,"q":"What is Beta? Would Bitcoin have a high or low Beta?","k":["Beta measures how much an asset’s returns move relative to the market; it captures systematic risk.","Because Bitcoin is highly volatile and tends to swing more than the equity market, it would have a Beta well above 1."],"collection":"practice","topic":"Valuation","tags":["Reported in Allen & Company Interview","SA 2026","Valuation","Basic"]},{"id":"q-0813","t":"val","l":"Basic","s":90,"q":"How do rising central bank rates affect the cost of equity?","k":["They raise the risk‑free rate in CAPM and typically widen equity risk premia, so the cost of equity increases."],"collection":"practice","topic":"Valuation","tags":["Reported in Ardea Partners Interview","SA 2025, off-cycle, London office","Valuation","Basic"]},{"id":"q-0814","t":"val","l":"Basic","s":90,"q":"If you have two companies, same EBIT and same Revenue, and one has 90% Debt while the other has 10% Debt, which company has a higher P/E ratio?","k":["The company with 90% debt is likely to have higher interest expenses, which reduces net income, holding EBIT constant.","With lower net income, for a given share price, the P/E ratio would be higher.","Conceptually: P/E = Share Price / (Net Income per share). A smaller denominator (Net Income) makes the ratio higher, all else being equal."],"collection":"practice","topic":"Valuation","tags":["Reported in Bank of America Interview","Valuation","Basic"]},{"id":"q-0815","t":"val","l":"Basic","s":90,"q":"How would you explain the valuation of a private car wash to the car wash owner?","k":["You could use a market-based approach (comparable company analysis with local or similar small businesses) and an income-based approach (a simplified DCF).","For the DCF, forecast the car wash’s cash flow (revenue from car washes and add-on services, minus operating costs and maintenance expenses) and discount those cash flows at a rate that reflects the business’s risk profile.","Because it’s private and possibly small-scale, you might look at local transaction multiples or industry rules of thumb (e.g., a multiple of EBITDA or SDE, Seller’s Discretionary Earnings)."],"collection":"practice","topic":"Valuation","tags":["Reported in Bank of America Interview","Valuation","Basic"]},{"id":"q-0816","t":"val","l":"Basic","s":90,"q":"How does a reduction in the corporate tax rate affect a company's valuation?","k":["A lower corporate tax rate generally increases a company's valuation.","Key Impacts:","Higher After-Tax Cash Flows: The primary benefit is that lower taxes lead to higher net income and free cash flow for each period. This directly increases the present value of the company in a DCF analysis.","Higher WACC (Slightly): A lower tax rate reduces the benefit of the interest tax shield on debt (as deductions are worth less), which increases the after-tax cost of debt. This will cause a slight increase in the WACC. Note: this effect is only meaningful for companies with significant debt; companies with little to no leverage will see minimal WACC impact.","Net Effect: The positive impact of significantly higher after-tax cash flows almost always outweighs the negative impact of a slightly higher WACC, resulting in a higher overall valuation.","Higher Trading Multiples: Public markets may assign higher multiples as investors are willing to pay more for a company that retains more of its earnings."],"collection":"practice","topic":"Valuation","tags":["Reported in Bank of America Interview","New York Office, Superday","Valuation","Basic"]},{"id":"q-0817","t":"val","l":"Basic","s":90,"q":"If two companies have the same EBITDA, why might they have different P/E multiples?","k":["P/E multiples differ based on what's below EBITDA:","Depreciation & Amortization: Higher D&A reduces EBIT and Net Income, increasing P/E.","Interest Expense: More leverage increases interest, reduces NI, raises P/E.","Tax Rate: Higher effective tax rates reduce NI, increasing P/E.","Non-Operating Items: One-time gains/losses, equity income, minority interest affect NI but not EBITDA.","Share Count: More shares outstanding increase P/E even with same absolute NI.","Growth Expectations: Market may value one company's earnings growth prospects more highly.","EBITDA is capital structure-neutral; P/E reflects financing decisions, tax efficiency, and growth expectations."],"collection":"practice","topic":"Valuation","tags":["Reported in Bank of America Interview","M&A, First round","Valuation","Basic"]},{"id":"q-0818","t":"val","l":"Basic","s":90,"q":"What factors might affect a company's valuation given the current market environment?","k":["Current market factors affecting valuation:","Interest Rates: Higher rates compress multiples by increasing discount rates and reducing PV of future cash flows.","Inflation: Erodes purchasing power and margins; investors demand higher returns.","Economic Growth: Slower growth reduces revenue expectations and multiples.","Market Sentiment: Risk-on vs. risk-off environments affect investor appetite for growth vs. value stocks.","Sector Trends: AI, energy transition, healthcare innovation drive premium multiples in certain sectors.","Geopolitical Risk: Trade tensions, conflicts create uncertainty, compressing valuations.","Credit Markets: Tighter credit conditions increase cost of capital and reduce leverage availability.","M&A Activity: Robust deal flow can drive multiples higher; quiet markets compress them."],"collection":"practice","topic":"Valuation","tags":["Reported in Bank of America Interview","M&A, First round","Valuation","Basic"]},{"id":"q-0819","t":"val","l":"Basic","s":90,"q":"When you look at a company's stock price, how do you decide if it's undervalued or overvalued?","k":["Steps to assess valuation:","Intrinsic Valuation: Conduct DCF to determine fair value based on fundamentals.","Relative Valuation: Compare multiples (P/E, EV/EBITDA, EV/Revenue) to comparable companies and historical ranges.","Growth Analysis: Assess if current multiple is justified by growth rate (PEG ratio).","Margin Analysis: Evaluate profitability trends and operating leverage.","Qualitative Factors: Competitive position, management quality, industry dynamics.","Market Sentiment: Understand if stock trades at premium/discount to sector due to temporary factors.","If DCF and comps both suggest stock is trading significantly below fair value, and fundamentals support it, the stock is likely undervalued."],"collection":"practice","topic":"Valuation","tags":["Reported in Bank of America Interview","LevFin, First round","Valuation","Basic"]},{"id":"q-0820","t":"val","l":"Basic","s":90,"q":"What are the differences between the EV/EBITDA, EV/EBIT, and P/E valuation multiples?","k":["EV/EBITDA: Enterprise value to earnings before interest, taxes, depreciation, and amortization. Capital structure-neutral, excludes D&A and interest.","EV/EBIT: Enterprise value to earnings before interest and taxes. Includes D&A impact, still capital structure-neutral (excludes interest).","P/E: Price to Net Income (earnings). Equity-based multiple, reflects capital structure (interest expense) and taxes.","Key differences:","EV/EBITDA most commonly used for comparing companies with different leverage and capex intensity.","EV/EBIT accounts for D&A differences but still excludes financing impact.","P/E reflects full capital structure and tax impact, making it less comparable across different leverage profiles."],"collection":"practice","topic":"Valuation","tags":["Reported in Bank of America Interview","M&A, Second round","Valuation","Basic"]},{"id":"q-0821","t":"val","l":"Basic","s":90,"q":"Why might two companies with the same revenue trade at different valuation multiples?","k":["Reasons for multiple disparity:","Profitability: One has higher EBITDA or net margins, generating more value per dollar of revenue.","Growth Rate: Faster-growing company commands premium multiple.","Business Model: Recurring revenue (SaaS) valued higher than transactional revenue.","Customer Concentration: Diversified customer base reduces risk, supports higher multiple.","Competitive Position: Strong moat, brand, or market leadership justifies premium.","Capital Intensity: Asset-light business requires less capex, higher FCF conversion, higher multiple.","Leverage: Less debt reduces risk and can support higher equity multiple.","Industry Dynamics: One operates in higher-growth or more attractive end market."],"collection":"practice","topic":"Valuation","tags":["Reported in Bank of America Interview","M&A, Second round","Valuation","Basic"]},{"id":"q-0822","t":"val","l":"Basic","s":90,"q":"If one company trades at a P/E of 15x and another at 10x, which would you recommend an investor buy, and what other factors would you consider?","k":["The P/E ratio alone is insufficient to determine which company to buy.","Key factors to consider:","Growth Rates: Higher growth justifies higher P/E multiples.","Risk Profile: Lower risk businesses command higher multiples.","Profitability Quality: Sustainable vs. one-time earnings.","Industry Dynamics: Sector average multiples and trends.","Capital Structure: Debt levels affecting equity value.","Market Position: Competitive advantages and market share.","The 10x P/E company could be a value opportunity or reflect poor prospects. The 15x company could be fairly valued for growth or overvalued."],"collection":"practice","topic":"Valuation","tags":["Reported in Bank of America Interview","M&A, Second round","Valuation","Basic"]},{"id":"q-0823","t":"val","l":"Basic","s":90,"q":"Which company would you expect to have a higher beta: a high-growth tech startup or a mature, established company? Why?","k":["The high-growth tech startup would have a higher beta.","Beta measures a stock's sensitivity to overall market movements. A high-growth tech startup has higher beta because:","Its revenues are less predictable and more sensitive to economic cycles","Its valuation relies heavily on future growth expectations, which fluctuate with market sentiment","It likely has higher operating leverage (high fixed costs relative to revenue)","It may have limited diversification across products, customers, or geographies","A mature, established company has lower beta due to stable cash flows, diversified revenue, and less sensitivity to market swings."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Bank of America Interview","SA 2027, Superday","Valuation","Basic"]},{"id":"q-0824","t":"val","l":"Basic","s":90,"q":"What is CAGR, and how do you calculate the CAGR from one year to the next?","k":["CAGR (compound annual growth rate) is the annualized rate assuming compounding that takes a beginning value to an ending value over n periods (typically n ≥ 2).","Formula: (Ending ÷ Beginning)^(1⁄n) − 1.","For adjacent years (n = 1), it equals (Ending ÷ Beginning) − 1 (i.e., simple YoY growth)."],"collection":"practice","topic":"Valuation","tags":["Reported in Barclays Interview","Valuation","Basic"]},{"id":"q-0825","t":"val","l":"Basic","s":90,"q":"Can you explain what a \"football field\" valuation chart is and what it shows?","k":["A football field chart is a visual summary of valuation ranges from different methodologies, displayed as horizontal bars resembling a football field.","Key features:","Each bar represents valuation range from one method (DCF, comparable companies, precedent transactions, etc.)","X-axis shows enterprise value or equity value per share","Y-axis lists different valuation methodologies","Allows quick comparison of how different methods value the company","Helps identify consensus valuation range where methods overlap","Typically includes current trading price for reference","The chart is commonly used in pitch books and fairness opinions to present a comprehensive view of valuation to clients and boards."],"collection":"practice","topic":"Valuation","tags":["Reported in Barclays Interview","Superday","Valuation","Basic"]},{"id":"q-0826","t":"val","l":"Basic","s":90,"q":"Given a set of financial statements, identify the trading multiples that can be derived from them.","k":["From the financial statements, you can derive:","Enterprise Value Multiples (require calculating EV from the BS):","EV / Revenue","EV / EBITDA","EV / EBIT","Equity Value Multiples (require market cap):","P / E (Price / Earnings per Share)","P / B (Price / Book Value per Share)","Other Metrics Derivable from the Statements:","Dividend Yield (if dividends are disclosed)","FCF Yield (FCF / Market Cap)","Debt / EBITDA (leverage ratio)","Note: You need the market share price (not on the financial statements) to calculate equity value-based multiples."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Barclays Interview","SA 2026, FIG group, New York Office, First round","Valuation","Basic"]},{"id":"q-0827","t":"val","l":"Basic","s":90,"q":"Company A has a market cap of $5 billion and Company B has a market cap of $500 million. Which should have a higher cost of equity, and why?","k":["Company B ($500M market cap) should have a higher cost of equity.","Smaller companies typically carry a size premium in their cost of equity because they have: higher business risk, less diversification, lower liquidity in public markets, less analyst coverage, and greater vulnerability to economic downturns. In the CAPM framework, this is captured through a higher beta and/or an additional size premium (as in the Fama-French model). Empirically, small-cap companies have historically required returns 2-4% higher than large-cap companies."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Barclays Interview","SA 2025","Valuation","Basic"]},{"id":"q-0828","t":"val","l":"Basic","s":90,"q":"What valuation method would you use if you were taking a company public in an IPO?","k":["Comparable companies analysis (trading comps) is the primary valuation method for an IPO.","You identify publicly traded peers and apply their trading multiples to the IPO candidate's financials to derive an implied valuation range.","An IPO discount of 10-15% is typically applied to account for illiquidity risk and to generate first-day trading demand.","A DCF may be used as a supplementary check, but comps drive the pricing because institutional investors benchmark against the public peer set.","Precedent transactions are less relevant since an IPO is not a change-of-control event and does not include a control premium."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Barclays Interview","SF Office, Superday","Valuation","Basic"]},{"id":"q-0829","t":"val","l":"Basic","s":90,"q":"What are the pros and cons of using the perpetuity growth method vs. the exit multiple method when calculating terminal value?","k":["The perpetuity growth method ties the terminal value to a theoretically infinite series of cash flows growing at a stable rate. It’s more theoretical and heavily dependent on the chosen growth rate, which can significantly change the terminal value.","The exit multiple method bases the terminal value on current market conditions and comparable company multiples. It’s often more aligned with how real transactions happen but can be less forward-looking since it relies on a single multiple that might fluctuate over time."],"collection":"practice","topic":"Valuation","tags":["Reported in BMO Interview","Valuation","Basic"]},{"id":"q-0830","t":"val","l":"Basic","s":90,"q":"What are the three main valuation methods?\n\n\n\n\nFollow-up: Which valuation method would you use if you only had two years of limited financial data?","k":["The three main valuation methods are:","Comparable Companies Analysis (Trading Comps)","Precedent Transactions Analysis","Discounted Cash Flow (DCF)","Follow-up","With only two years of limited financial data, you would rely most heavily on Comparable Companies Analysis. Trading comps require only current financial metrics (revenue, EBITDA) to apply peer multiples. A DCF is less reliable with only two years of data because you lack the historical basis to confidently project 5-10 years of cash flows. Precedent transactions could also work since you only need the company's current metrics to apply deal multiples."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Cain Brothers Interview","New York Office","Valuation","Basic"]},{"id":"q-0831","t":"val","l":"Basic","s":90,"q":"What would you do if your company had $100M in revenue but the comparable companies all had $1B in revenue?","k":["Apply a size discount: Smaller companies typically trade at lower multiples due to higher risk, lower liquidity, and less diversification. Apply a 10-30% discount to peer multiples.","Find better comps: Search for smaller publicly traded companies in the same or adjacent sectors. Expand the search to include international peers or adjacent industries.","Use precedent transactions: Look for M&A deals involving companies of similar size, which may better reflect the valuation of a $100M revenue company.","Adjust the DCF: Use a higher discount rate (add a size premium to the cost of equity) to reflect the additional risk of a smaller company.","Consider growth rate: If the $100M company is growing faster than the $1B peers, it may deserve a premium on revenue multiples despite the size difference."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Cain Brothers Interview","New York Office","Valuation","Basic"]},{"id":"q-0832","t":"val","l":"Basic","s":90,"q":"Would you expect a smaller or larger company to grow faster?","k":["A smaller company is generally expected to grow faster on a percentage basis.","Law of large numbers: A $100M company can double revenue more easily than a $10B company. Smaller base makes high percentage growth more achievable.","Market opportunity: Smaller companies are often earlier in capturing their addressable market, with more room for penetration.","Agility: Smaller companies can pivot faster, enter new markets, and adopt new technologies more quickly.","However, larger companies have advantages in absolute dollar growth due to scale, brand, distribution, and M&A capacity.","This is why high-growth small companies trade at higher revenue multiples -- the market pays a premium for faster growth."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Cain Brothers Interview","New York Office","Valuation","Basic"]},{"id":"q-0833","t":"val","l":"Basic","s":90,"q":"How do you think a company should be valued?","k":["A company should be valued using multiple methodologies to triangulate a range, not a single point estimate.","Use comparable companies for a market-based reference point.","Use precedent transactions if an M&A context is relevant.","Use a DCF to understand the intrinsic value based on the company's own cash flow generation.","Use an LBO analysis to establish a floor valuation.","Present the results in a football field chart showing the valuation range from each method. The overlap across methodologies gives the most defensible range.","Weight each method based on the situation: DCF is most relevant for unique companies with few peers, comps are best when strong peers exist, and precedent transactions matter most in an active sale process."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Cain Brothers Interview","SF Office, Superday","Valuation","Basic"]},{"id":"q-0834","t":"val","l":"Basic","s":90,"q":"How does having a higher percentage of the capital structure in debt change the WACC?","k":["It lowers WACC up to a optimal leverage point, then raises it.","Debt is cheaper than equity (tax shield + seniority), so replacing equity with debt pushes WACC down.","Beyond a certain leverage, rising default risk drives up the cost of debt and the cost of equity, causing the familiar U‑shape."],"collection":"practice","topic":"Valuation","tags":["Reported in Centerview Partners Interview","SA 2025, off-cycle, London office","Valuation","Basic"]},{"id":"q-0835","t":"val","l":"Basic","s":90,"q":"If you had two identical companies, each with the same products, and one traded at 10x EBITDA and another at 20x, which one would you choose to invest in?","k":["At first glance, the cheaper (10x) might seem more attractive. But you need to investigate reasons why one trades at a higher multiple: better management, higher margins, better growth prospects, or lower risk?","If all truly is identical, the lower multiple could suggest undervaluation, but in reality, there might be intangible differences justifying the higher multiple."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Valuation","Basic"]},{"id":"q-0836","t":"val","l":"Basic","s":90,"q":"Company has Equity Value of $100m, and P/E = 10x. The company reduces operational costs by $10m/year. What is the new Equity Value?","k":["If the P/E is 10x, $10m/year in additional net income (assuming no change in taxes or anything else) translates to an extra $100m in equity value (10 x $10m).","So, you’d add that to the existing $100m, resulting in $200m new equity value. In practice, you'd adjust for taxes, but that's the high-level approach."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Valuation","Basic"]},{"id":"q-0837","t":"val","l":"Basic","s":90,"q":"Two companies have different EV/EBITDA multiples but identical financials. How can that happen?","k":["It could be due to qualitative factors like brand strength, management quality, or growth expectations that aren’t reflected in the current numbers.","Also, liquidity and market sentiment can cause one to trade at a higher multiple. Different capital structures or projected changes in margins can drive a divergence in multiples as well."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Valuation","Basic"]},{"id":"q-0838","t":"val","l":"Basic","s":90,"q":"Strengths and weaknesses of each valuation methodology (DCF, Comps, Precedents, etc.)?","k":["DCF: Theoretically most sound, but heavily dependent on assumptions (WACC, terminal growth rate).","Comps: Market-based and easy to calculate, but can be skewed if comps are not truly comparable or the market is over/undervalued.","Precedent Transactions: Captures real premiums paid, but every deal is unique in timing, synergy assumptions, and market conditions."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Valuation","Basic"]},{"id":"q-0839","t":"val","l":"Basic","s":90,"q":"Let's say you have two tech companies with different growth rates. What would be a good ratio to compare these companies?","k":["You might use EV/Revenue or EV/Growth (like EV/EBITDA-growth), especially if they aren’t profitable. Some also look at PEG ratios (P/E to Growth).","In high-growth SaaS, EV/ARR (Annual Recurring Revenue) can be more relevant than EV/EBITDA if EBIT is minimal or negative."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Valuation","Basic"]},{"id":"q-0840","t":"val","l":"Basic","s":90,"q":"Which would have a higher cost of equity – Lyft or Meta?","k":["Lyft.","Lyft is smaller and has a higher beta, so its required return is higher than a large, diversified tech company like Meta."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Valuation","Basic"]},{"id":"q-0841","t":"val","l":"Basic","s":90,"q":"What valuation methodologies are most appropriate for an Initial Public Offering (IPO)?","k":["Primary valuation methods for IPOs:","Comparable Company Analysis: Compare to publicly traded peers using multiples like P/E, EV/Revenue, EV/EBITDA. Most commonly used for IPO pricing.","Precedent Transaction Analysis: Review recent IPOs in the same sector to establish market-clearing valuation ranges.","DCF Analysis: Less emphasis for IPOs due to uncertainty in forecasts for newly public companies, but used as a supplementary check.","Comparable companies are most heavily weighted since investors will directly compare the IPO to existing public market alternatives."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Chicago Office","Valuation","Basic"]},{"id":"q-0842","t":"val","l":"Basic","s":90,"q":"Think about a company you are familiar with, perhaps from a previous job. How would you approach valuing that company?","k":["Comprehensive valuation approach:","Understand the business: Revenue model, cost structure, competitive position, growth drivers.","Comparable Company Analysis: Identify public peers, select appropriate multiples based on business model.","Precedent Transactions: Research M&A activity in the sector for acquisition multiples.","DCF Analysis: Build financial projections, determine WACC, calculate terminal value, discount to present value.","Triangulate: Synthesize results from multiple methodologies to arrive at a valuation range.","Tailor your answer to the specific company, highlighting industry-specific considerations."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Chicago Office","Valuation","Basic"]},{"id":"q-0843","t":"val","l":"Basic","s":90,"q":"Company A has a Net Debt of $500 and trades at an EV/EBITDA multiple of 12.5x, while its direct peers trade at an average of 13.0x.\n\n\n\n\nWhat are some potential reasons for this valuation discount?","k":["Potential reasons for the discount:","Lower growth prospects: Slower revenue or EBITDA growth than peers.","Higher risk profile: More cyclical business, geographic concentration, customer concentration.","Weaker margins: Lower or declining profitability.","Higher leverage: $500 Net Debt may represent higher Debt/EBITDA compared to peers, increasing financial risk.","Management or governance concerns: Weak leadership, poor capital allocation.","Smaller size: Less liquidity, smaller scale disadvantages.","Industry headwinds: Company-specific competitive disadvantages or secular decline."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Chicago office, First round","Valuation","Basic"]},{"id":"q-0844","t":"val","l":"Basic","s":90,"q":"A company has the following metrics:\n\n\n\nEBITDA Margin: 20%\nEV/Revenue Multiple: 3.0x\nRevenue: $30\n\n\n\nWhat is the company's EV/EBITDA multiple?","k":["Answer: 15x","Calculation:","EBITDA = Revenue * EBITDA Margin = $30 * 20% = $6.","EV = Revenue * EV/Revenue = $30 * 3.0 = $90.","EV/EBITDA = $90 / $6 = 15x."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Chicago office, First round","Valuation","Basic"]},{"id":"q-0845","t":"val","l":"Basic","s":90,"q":"Let's say we give you a random business, business model, or industry. How would you go about evaluating the business?","k":["Framework for evaluating any business:","Understand the business model: What does the company sell? Who are its customers? How does it make money (subscription, transaction, project-based)? What is the revenue model?","Analyze the financials: Revenue growth, gross margin, EBITDA margin, FCF conversion, CapEx intensity, leverage. Compare to industry benchmarks.","Assess competitive positioning: Market share, barriers to entry, customer switching costs, brand strength, pricing power. Use Porter's Five Forces as a framework.","Evaluate growth drivers: TAM (total addressable market), organic growth levers (new products, geographies, pricing), and inorganic growth (M&A potential).","Identify risks: Customer concentration, regulatory exposure, cyclicality, technology disruption, key person risk.","Determine valuation: Select appropriate comps and multiples for the industry. Run a DCF if cash flows are projectable. Consider precedent transactions if M&A is relevant.","Always start with \"What does this business do and how does it make money?\" before diving into numbers."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Citi Interview","SA 2027","Valuation","Basic"]},{"id":"q-0846","t":"val","l":"Basic","s":90,"q":"How would you perform a precedent transactions analysis and a comparable companies analysis, step by step? Which methodology would typically yield a higher valuation?","k":["Comparable Companies Analysis:","Select a peer group of publicly traded companies with similar size, growth, margins, and end markets.","Gather financial data: EV, Equity Value, Revenue, EBITDA, Net Income.","Calculate relevant multiples: EV/Revenue, EV/EBITDA, P/E.","Determine the median or mean multiples from the peer set.","Apply those multiples to the target company's metrics to get an implied valuation range.","Precedent Transactions Analysis:","Identify recent M&A transactions involving similar target companies.","Gather transaction data: deal value, implied EV, target financials at the time of the deal.","Calculate transaction multiples: EV/Revenue, EV/EBITDA at the time of the deal.","Determine the median or mean multiples from the transaction set.","Apply those multiples to the target company's metrics to get an implied valuation range.","Precedent transactions typically yields a higher valuation because the transaction multiples include a control premium (20-40%) paid by acquirers to gain control of the target. Trading comps reflect minority, non-controlling share prices without a premium."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Citi Interview","SA 2027","Valuation","Basic"]},{"id":"q-0847","t":"val","l":"Basic","s":90,"q":"What is a Net Asset Value (NAV) model, and when would you use it?","k":["A NAV model values a company by summing the market values of its individual assets and subtracting its liabilities. The result is the net value attributable to equity holders.","NAV = Market Value of Assets - Total Liabilities","Used primarily for:","REITs: Value individual properties using NOI / cap rate, then sum and subtract net debt.","Asset holding companies: Conglomerates, investment companies, or natural resource companies where the sum of the parts is more meaningful than consolidated earnings.","Financial institutions: Banks and insurance companies where book value of assets and liabilities is a primary valuation anchor.","Liquidation analysis: When evaluating a distressed company's value in a wind-down scenario."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Citi Interview","SA 2026, First round","Valuation","Basic"]},{"id":"q-0848","t":"val","l":"Basic","s":90,"q":"A company has an enterprise value of $1,000, revenue of $5,000, and EBITDA of $100. What is the EV/Revenue multiple and the EV/EBITDA multiple?","k":["EV/Revenue = $1,000 / $5,000 = 0.2x.","EV/EBITDA = $1,000 / $100 = 10.0x."],"collection":"practice","topic":"Valuation","tags":["New","Reported in DC Advisory Interview","New York Office, Second round","Valuation","Basic"]},{"id":"q-0849","t":"val","l":"Basic","s":90,"q":"Should you use forecast or historical multiples for public comps and precedent transactions?\n\n\n\n\nWhy?","k":["Public Comps: Forward Multiples","Use forward (forecast) multiples because they reflect market expectations and future growth. Investors value companies based on future earnings potential, not historical performance.","Precedent Transactions: Historical Multiples","Use historical (LTM or last twelve months) multiples because transactions are priced on actual, verifiable results at deal announcement. Buyers typically base valuations on achieved performance rather than projections.","Note: Some practitioners use NTM (next twelve months) for both if forward visibility is strong."],"collection":"practice","topic":"Valuation","tags":["Reported in Deutsche Bank Interview","New York office, First round","Valuation","Basic"]},{"id":"q-0850","t":"val","l":"Basic","s":90,"q":"Two identical companies (revenue, growth, risk etc.), one public, one private. Which is valued higher?","k":["The public company is typically valued higher.","This is due to:","Liquidity Premium: Public shares are easily traded.","Transparency: Greater disclosure and reporting requirements.","Access to Capital: Easier access to public markets for funding.","Private companies often have a valuation discount for lack of marketability (DLOM)."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","Valuation","Basic"]},{"id":"q-0851","t":"val","l":"Basic","s":90,"q":"A pharmaceutical company and an auto manufacturer have identical financials.\n\n\n\n\nWhich has the larger equity value, and why?","k":["The pharma company likely has the higher equity value.","Pharma typically trades at higher multiples due to growth potential, IP, and less cyclicality."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","Valuation","Basic"]},{"id":"q-0852","t":"val","l":"Basic","s":90,"q":"What are the four most commonly used valuation methods?\n\n\n\n\nExplain each one briefly and rank them from highest to lowest valuation.","k":["Typical ranking (highest headline price to lowest):","Precedent Transactions – includes control premiums and expected synergies","Discounted Cash Flow – intrinsic value based on future free cash flow","Public Trading Comparables – current market sentiment for similar companies","Leveraged Buy‑Out – what a financial sponsor can pay while hitting its IRR hurdle","Order can shift by cycle or sector, but this is the common rule of thumb."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","SA 2026, New York office, First round","Valuation","Basic"]},{"id":"q-0853","t":"val","l":"Basic","s":90,"q":"How can you tell if a company has consistent cash flows?","k":["Look at several indicators across multiple periods:","Examine 3-5 years of Cash Flow from Operations (CFO) and Free Cash Flow (FCF) to see if they are stable and positive.","Compare FCF to Net Income - a consistent, high conversion ratio indicates quality, cash-generative earnings.","Check revenue mix: recurring/subscription revenue and long-term contracts produce more predictable cash flows than one-time or project-based revenue.","Low working capital volatility - stable changes in AR, inventory, and AP suggest predictable cash cycles.","Consistent CapEx as a percentage of revenue (not lumpy).","Low customer concentration - diversified revenue reduces cash flow volatility.","Minimal one-time items or restructuring charges that distort operating cash flow."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2027","Valuation","Basic"]},{"id":"q-0854","t":"val","l":"Basic","s":90,"q":"Pick a company. How would you value it? Which valuation method would yield the highest valuation? What about the lowest?","k":["Framework for answering:","Pick a well-known company you can speak to confidently (e.g., Apple, Nike, Starbucks).","Name the three main valuation methods: comparable companies analysis, precedent transactions analysis, and DCF analysis.","Explain which you would use and why (sector-specific multiples, availability of comps, cash flow predictability).","Typical Ranking (Highest to Lowest Valuation):","Precedent Transactions: Typically yields the highest valuation because transaction multiples include a control premium (usually 20-40% above trading levels).","DCF: Can yield a wide range depending on assumptions, but typically falls in the middle. Sensitive to terminal growth rate and WACC.","Comparable Companies: Usually yields the lowest valuation because it reflects current trading multiples without a control premium.","Prepare a specific company with actual multiples and metrics before your interview."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","M&A group, New York Office, First round","Valuation","Basic"]},{"id":"q-0855","t":"val","l":"Basic","s":90,"q":"A company has 200 shares outstanding at $10 per share, $500 in debt, $50 in cash, $20 in short-term investments, and $20 in minority interest. The company has $100 in EBITDA and $50 in Net Income. What is the EV/EBITDA multiple, the leverage ratio, and the P/E multiple?","k":["First, calculate the key values: Equity Value = 200 x $10 = $2,000. EV = $2,000 + $500 - $50 - $20 + $20 = $2,450.","EV/EBITDA = $2,450 / $100 = 24.5x","Leverage Ratio (Debt/EBITDA) = $500 / $100 = 5.0x","P/E = Equity Value / Net Income = $2,000 / $50 = 40.0x"],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","M&A group, New York Office, First round","Valuation","Basic"]},{"id":"q-0856","t":"val","l":"Basic","s":90,"q":"What are four things you could do with excess cash on the balance sheet?","k":["Pay down debt: Reduces leverage, lowers interest expense, and improves credit profile.","Return capital to shareholders: Through share buybacks (reduces share count, increases EPS) or dividends (direct cash return).","Reinvest in the business: Fund CapEx, R&D, or organic growth initiatives to drive future revenue and earnings.","Make acquisitions: Deploy capital to acquire companies that provide strategic value, synergies, or new capabilities (M&A)."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","M&A group, New York Office, First round","Valuation","Basic"]},{"id":"q-0857","t":"val","l":"Basic","s":90,"q":"What are some common valuation multiples? Can you use EV/Net Income as a multiple? Why or why not?","k":["Common Valuation Multiples","Enterprise Value multiples: EV/Revenue, EV/EBITDA, EV/EBIT","Equity Value multiples: P/E, Price/Book, Price/Earnings Growth (PEG)","Why Not EV/Net Income?","EV/Net Income is not a valid multiple because it mixes the numerator and denominator across capital structure claims. Enterprise Value represents the value to all capital providers (debt + equity), while Net Income is available only to equity holders (it is calculated after interest expense to debt holders). To maintain consistency, EV multiples must use pre-interest metrics (Revenue, EBITDA, EBIT), and equity multiples must use post-interest metrics (Net Income, Earnings)."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","M&A group, New York Office, Second round","Valuation","Basic"]},{"id":"q-0858","t":"val","l":"Basic","s":90,"q":"What are some examples of unlevered and levered valuation multiples?","k":["Unlevered (Enterprise Value) Multiples:","EV/Revenue","EV/EBITDA","EV/EBIT","EV/Unlevered Free Cash Flow","These use enterprise value in the numerator and a pre-debt metric in the denominator, making them capital-structure neutral.","Levered (Equity Value) Multiples:","P/E (Price / Earnings per Share)","Price / Book Value","Price / Levered Free Cash Flow","Dividend Yield","These use equity value (or share price) in the numerator and a post-debt metric in the denominator, reflecting the impact of capital structure."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2027, Superday","Valuation","Basic"]},{"id":"q-0859","t":"val","l":"Basic","s":90,"q":"What is the difference between cost of equity and return on equity?","k":["Cost of equity is the minimum return equity investors require to invest in a company. It is forward-looking and calculated using CAPM: Rf + Beta x (Rm - Rf). It represents the opportunity cost of investing in that stock versus similar-risk alternatives.","Return on equity (ROE) is a backward-looking profitability measure: Net Income / Shareholders' Equity. It shows how much profit a company generated relative to equity invested.","If ROE exceeds cost of equity, the company is creating value for shareholders. If ROE is below cost of equity, the company is destroying value."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2026, First round","Valuation","Basic"]},{"id":"q-0860","t":"val","l":"Basic","s":90,"q":"What are some valuation multiples that are unique to specific industries?","k":["Technology/SaaS: EV/Revenue, EV/ARR (Annual Recurring Revenue).","Financial Institutions (Banks): P/B (Price/Book Value), P/TBV (Price/Tangible Book).","Real Estate (REITs): P/FFO (Funds From Operations), P/NAV (Net Asset Value).","Oil & Gas: EV/EBITDAX (excludes exploration costs), EV/Proved Reserves, EV/Production.","Retail: EV/EBITDAR (excludes rent expense).","Telecom/Cable: EV/Subscriber.","Healthcare/Biotech: EV/Pipeline Value, EV/Beds (hospitals)."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2025, First round","Valuation","Basic"]},{"id":"q-0861","t":"val","l":"Basic","s":90,"q":"Walk me through how you would value your favorite healthcare or consumer company.","k":["Structure your answer using the standard valuation framework applied to a specific company:","Trading comps: Identify 5-8 comparable public companies in the same sub-sector. Use EV/EBITDA and EV/Revenue (or P/E for consumer). Apply the median multiple to the target's metrics.","Precedent transactions: Look at recent M&A deals in the space. Note any control premiums paid.","DCF: Project 5-10 years of free cash flows. For healthcare, consider patent cliffs and pipeline optionality. For consumer, consider brand strength and same-store growth. Discount at WACC and add terminal value.","LBO (if applicable): Determine what a PE sponsor could pay and still achieve 20%+ IRR.","Pick a company you know well and be ready to discuss its specific revenue drivers, margin profile, and comparable set."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2026, First round","Valuation","Basic"]},{"id":"q-0862","t":"val","l":"Basic","s":90,"q":"How would you present valuations to a client if you are in a very volatile market?","k":["Use wider valuation ranges rather than point estimates to reflect uncertainty.","Emphasize sensitivity analysis: Show how the valuation changes under different assumptions for growth, margins, and discount rates.","Rely more on intrinsic methods (DCF) over market-based methods, since trading comps and precedent transactions may reflect temporary market dislocations.","Present a football field chart showing the range from each methodology so the client can see where values converge.","Use normalized or through-the-cycle metrics (e.g., average EBITDA over 3 years) rather than spot figures that may be distorted.","Distinguish between short-term market noise and long-term fundamental value."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2026, First round","Valuation","Basic"]},{"id":"q-0863","t":"val","l":"Basic","s":90,"q":"When would you use a sum-of-the-parts valuation, and how is it useful?","k":["A sum-of-the-parts (SOTP) valuation is used when a company operates in multiple distinct business segments that have different growth profiles, risk characteristics, and valuation multiples.","Each segment is valued independently using the most appropriate method (separate comps, DCFs, or multiples for each division).","The segment values are summed to get total Enterprise Value, then subtract net debt for Equity Value.","SOTP is useful for conglomerates, diversified holding companies, or companies with a mix of high-growth and mature businesses.","It helps identify a \"conglomerate discount\" -- if the SOTP value exceeds the market cap, it suggests the market is undervaluing the company, and an activist investor might push for a breakup or spinoff.","Examples: A company with both a SaaS business (valued at EV/Revenue) and a hardware business (valued at EV/EBITDA) would be poorly served by a single blended multiple."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2025, Superday","Valuation","Basic"]},{"id":"q-0864","t":"val","l":"Basic","s":90,"q":"Tell me about a company you like. How would you value it and what multiples would you consider?","k":["Structure your answer with the following framework:","Pick a company: Choose one you genuinely follow and can speak to in depth. State the company, its industry, and what it does.","Why you like it: 2-3 reasons (e.g., market leadership, secular tailwinds, strong management, competitive moat).","Valuation approach: Which methodologies you would use and why -- trading comps (EV/EBITDA, EV/Revenue, P/E), precedent transactions, and DCF.","Relevant multiples: Pick multiples appropriate to the industry. For a SaaS company, emphasize EV/Revenue and EV/ARR. For industrials, EV/EBITDA. For financials, P/E and P/TBV.","Key risks: 1-2 risks to show balanced thinking.","Prepare a specific company with actual metrics before your interview."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2027","Valuation","Basic"]},{"id":"q-0865","t":"val","l":"Basic","s":90,"q":"A company trades at 10x EBITDA and its EV is $5B. What is its EBITDA?","k":["EBITDA = $500M.","EV / EBITDA = 10x and EV = $5B, so EBITDA = $5B / 10 = $500M."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, First round","Valuation","Basic"]},{"id":"q-0866","t":"val","l":"Basic","s":90,"q":"Why is there a control premium in precedent transactions?","k":["Precedent transactions involve acquiring a controlling stake in a company, which grants the buyer rights that minority shareholders do not have. The control premium compensates target shareholders for giving up these rights.","Control gives the buyer the ability to make strategic decisions (pursue M&A, divest assets, change strategy), set capital allocation policy, replace management, and realize synergies.","The buyer is paying for the present value of improvements it can make to the business that it could not achieve as a passive minority investor.","Target shareholders must be offered a price above the current trading price to incentivize them to sell — otherwise, they would simply hold their shares.","This is why precedent transactions typically produce higher valuations than trading comparables, which reflect minority, non-control share prices."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, First round","Valuation","Basic"]},{"id":"q-0867","t":"val","l":"Basic","s":90,"q":"Describe a lesser-known valuation methodology.\n\n\n\n\nExplain how it works and when you would use it.","k":["One lesser-known approach is the “Sum of the Parts” (SOTP) analysis for conglomerates or multi-segment companies. You value each division separately using a suitable methodology (Comps, DCF, etc.) and then add them, adjusting for net debt/corporate overhead.","It’s used when segments have very different business models, growth rates, or risk profiles."],"collection":"practice","topic":"Valuation","tags":["Reported in FT Partners Interview","Valuation","Basic"]},{"id":"q-0868","t":"val","l":"Basic","s":90,"q":"How do you build a public-company comparables set?","k":["You would look at a few factors:","Industry","Financials (i.e. Revenue, EBITDA)","Geography","The industry is the most important factor. Some examples of screens:","Retail apparel brands with market caps above $2 billion","Enterprise SaaS companies with growth rates above 30%"],"collection":"practice","topic":"Valuation","tags":["Reported in FT Partners Interview","Valuation","Basic"]},{"id":"q-0869","t":"val","l":"Basic","s":90,"q":"Part 1: Name three valuation methods. Then name as many additional valuation methods as you can.\n\n\n\n\nPart 2: Rank the following four valuation methodologies from highest to lowest: Precedent Transactions, Comparable Companies, DCF, and LBO.","k":["Part 1: Valuation Methods","Core three:","Comparable Companies (Trading Comps)","Precedent Transactions","Discounted Cash Flow (DCF)","Additional methods:","LBO Analysis","Sum-of-the-Parts","Dividend Discount Model","Net Asset Value (NAV)","Liquidation Value","52-Week High/Low Analysis","Analyst Price Targets","Risk-Adjusted DCF (rDCF) for biotech/pharma","Part 2: Ranking (Highest to Lowest)","Precedent Transactions (includes control premium and synergies)","DCF (can be high depending on assumptions)","Comparable Companies (current market pricing, no premium)","LBO (floor valuation, constrained by return hurdles)"],"collection":"practice","topic":"Valuation","tags":["New","Reported in FT Partners Interview","Second round","Valuation","Basic"]},{"id":"q-0870","t":"val","l":"Basic","s":90,"q":"What multiples would you use to value a company with negative EBITDA versus a company with positive EBITDA?","k":["Positive EBITDA Company:","EV/EBITDA is the standard go-to multiple.","EV/EBIT if D&A is meaningful and you want to capture capital intensity differences.","P/E if comparing equity values directly.","Negative EBITDA Company:","EV/Revenue: The most common fallback since revenue is almost always positive.","EV/Gross Profit: If the company has positive gross margins but negative EBITDA due to high OpEx (common in growth-stage tech).","EV/Subscribers, EV/Users, EV/GMV: Industry-specific operational metrics that capture scale.","EV/ARR or EV/Bookings: For SaaS companies with recurring revenue.","The key principle: move up the income statement or use operational metrics until you find a positive, meaningful metric to normalize valuation."],"collection":"practice","topic":"Valuation","tags":["New","Reported in FT Partners Interview","Second round","Valuation","Basic"]},{"id":"q-0871","t":"val","l":"Basic","s":90,"q":"Why might two direct competitors with the same net income trade at different valuation multiples (e.g., P/E)?","k":["Multiple factors can cause valuation differences:","Growth expectations (higher growth commands higher multiples).","Quality of earnings (recurring vs. one-time items).","Capital structure (different leverage levels affect risk).","Market position and competitive advantages.","Management quality and execution track record.","Investor sentiment and liquidity."],"collection":"practice","topic":"Valuation","tags":["Reported in Goldman Sachs Interview","Valuation","Basic"]},{"id":"q-0872","t":"val","l":"Basic","s":90,"q":"A company has $175 million of debt and $175 million of cash. What valuation multiples would you prioritize for this company, and how would you typically rank their output from highest to lowest?","k":["Prioritize EV-based multiples (EV/EBITDA, EV/Sales) since debt and cash offset.","Rank from highest to lowest typically: P/E > EV/EBITDA > EV/Sales.","EV/Sales is lowest because Sales is the largest number.","EV/EBITDA is higher than EV/Sales but lower than P/E, as EBITDA >Net Income.","P/E is usually the highest multiple because Net Income is the smallest denominator (bottom line)."],"collection":"practice","topic":"Valuation","tags":["Reported in Goldman Sachs Interview","Valuation","Basic"]},{"id":"q-0873","t":"val","l":"Basic","s":90,"q":"When comparing two companies, which multiple is more appropriate to use: EV/EBITDA or EV/EBIT? Under what circumstances would you prefer one over the other?","k":["EV/EBITDA is the more commonly used multiple, but EV/EBIT is preferred in certain situations.","Use EV/EBITDA when: Comparing companies with different D&A policies, capital structures, or depreciation methods. EBITDA normalizes for these differences and is a closer proxy for cash flow.","Use EV/EBIT when: Comparing companies with significantly different capital intensity. EBIT captures depreciation, which is a real economic cost for asset-heavy businesses (e.g., manufacturing, airlines, telecom). Using EBITDA for capital-intensive firms overstates their cash-generating ability by ignoring the cost of maintaining assets.","In general, EV/EBIT is more appropriate when CapEx is a meaningful and recurring expense. EV/EBITDA is better for asset-light businesses or when comparing across different accounting regimes."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","Valuation","Basic"]},{"id":"q-0874","t":"val","l":"Basic","s":90,"q":"What could a CEO do with an influx of cash to create value? List in order of least to most discretionary.","k":["From least to most discretionary:","Maintain required cash for operations","Pay down existing debt","Invest in core business (capex, R&D)","Make acquisitions","Pay dividends or repurchase shares"],"collection":"practice","topic":"Valuation","tags":["Reported in Greenhill & Co. Interview","Valuation","Basic"]},{"id":"q-0875","t":"val","l":"Basic","s":90,"q":"Explain the relationship amongst P/E, EPS, Price/Share, Market Cap, Net Income, and Share Count.","k":["EPS = Net Income / Shares Outstanding.","Price per Share x Shares Outstanding = Market Cap (Equity Value).","P/E = Price per Share / EPS = Market Cap / Net Income."],"collection":"practice","topic":"Valuation","tags":["Reported in Greenhill & Co. Interview","Valuation","Basic"]},{"id":"q-0876","t":"val","l":"Basic","s":90,"q":"Let's say you have a money tree that produces $100 in perpetuity. How would you value it?","k":["In a simplistic view, value = Cash Flow / Discount Rate.","If the discount rate is, say, 5%, the value is $100 / 0.05 = $2,000."],"collection":"practice","topic":"Valuation","tags":["Reported in Greenhill & Co. Interview","Valuation","Basic"]},{"id":"q-0877","t":"val","l":"Basic","s":90,"q":"How does increasing taxes impact valuation?","k":["Reduces Free Cash Flow","Higher statutory taxes reduce after-tax profit/NOPAT, lowering free cash flow and intrinsic value (all else equal).","Lowers WACC (with fixed D/E)","Bigger interest tax shield lowers after-tax cost of debt (rd × (1–T) ↓).","Levering formula βL = βU[1 + (1–T)·D/E]: higher T → smaller (1–T) → lower βL → lower Cost of Equity via CAPM.","Net: holding D/E, pre-tax rd, βU, and MRP constant, WACC falls; overall valuation impact usually declines because the FCF hit typically outweighs the discount-rate benefit.","Common pitfall: don’t double-count the tax shield—if you add PV(Debt Tax Shield) separately, discount unlevered FCF at the asset rate (no tax in WACC); otherwise use after-tax WACC and don’t add PV(Debt Tax Shield)."],"collection":"practice","topic":"Valuation","tags":["Reported in Greenhill & Co. Interview","First round","Valuation","Basic"]},{"id":"q-0878","t":"val","l":"Basic","s":90,"q":"If a company trades at 2.0x EV/Sales and 5.0x EV/EBITDA, what is its EBITDA margin?","k":["Answer: 40%","Calculation:","EV/Sales = 2.0x means EV = 2.0 × Sales.","EV/EBITDA = 5.0x means EV = 5.0 × EBITDA.","Therefore: 2.0 × Sales = 5.0 × EBITDA.","EBITDA / Sales = 2.0 / 5.0 = 0.40 = 40%."],"collection":"practice","topic":"Valuation","tags":["Reported in Greenhill & Co. Interview","M&A group, First round","Valuation","Basic"]},{"id":"q-0879","t":"val","l":"Basic","s":90,"q":"How could you tell from a company’s trading multiple whether it is attractive to pitch to a potential acquirer?","k":["A lower multiple vs. peers might suggest undervaluation, especially if fundamentals are comparable.","Of course, you'd also consider synergy potential, strategic fit, and discount to precedent deals."],"collection":"practice","topic":"Valuation","tags":["Reported in Guggenheim Partners Interview","Valuation","Basic"]},{"id":"q-0880","t":"val","l":"Basic","s":90,"q":"A company traded at a 10x EV/EBITDA in 2023 and 12x EV/EBITDA in 2024.\n\n\n\n\nWhat does that imply about the company's cash flows?","k":["Investors now pay more for each dollar of EBITDA.","The expansion signals either higher expected growth or lower perceived risk; EV rose faster than EBITDA (or EBITDA fell) even before any new cash flows materialized."],"collection":"practice","topic":"Valuation","tags":["Reported in Guggenheim Partners Interview","M&A, superday","Valuation","Basic"]},{"id":"q-0881","t":"val","l":"Basic","s":90,"q":"Walk through how to calculate a company's Weighted Average Cost of Capital (WACC), and explain why the cost of debt is tax‑affected.","k":["WACC = Cost of Equity * (% Equity) + Cost of Debt * (% Debt) * (1 - Tax Rate).","Cost of Equity via CAPM = Risk‑free rate + β × Equity risk premium.","Cost of Debt from current or implied borrowing cost.","Interest expense is tax‑deductible, so the after‑tax cost of debt is Cost of Debt × (1 − t), lowering the firm’s effective financing cost."],"collection":"practice","topic":"Valuation","tags":["Reported in Guggenheim Partners Interview","Valuation","Basic"]},{"id":"q-0882","t":"val","l":"Basic","s":90,"q":"Back-to-back questions on Beta:\n\n\n\nWhat does beta measure, and how is it calculated?\nWhat does a beta of −1 or 2 indicate?\nWhat does a beta of 0 signify?","k":["Beta measures an asset's systematic risk relative to the market.","β = Covariance(stock, market) / Variance(market).","Interpretation:","β = −1 → moves opposite the market one‑for‑one.","β = 2 → twice as volatile as the market in the same direction.","β = 0 → no correlation with market movements."],"collection":"practice","topic":"Valuation","tags":["Reported in Guggenheim Partners Interview","Valuation","Basic"]},{"id":"q-0883","t":"val","l":"Basic","s":90,"q":"Is Amazon more valuable as a consolidated company, or would shareholder value be maximized by selling off some of its business segments?","k":["Amazon is likely more valuable consolidated due to synergies and strategic integration.","Arguments for staying together:","AWS subsidizes retail investments and provides technology backbone for e-commerce operations.","Prime ecosystem creates powerful flywheel effects across retail, streaming, and devices.","Shared infrastructure, logistics, and data analytics capabilities.","Cross-promotional opportunities and customer insights.","Arguments for breaking up:","AWS might command higher multiples as standalone cloud business.","Eliminates conglomerate discount that may exist due to business complexity.","Reduces regulatory scrutiny and antitrust risk.","Allows pure-play investors to access preferred segments.","On balance, synergies likely exceed conglomerate discount, favoring integration."],"collection":"practice","topic":"Valuation","tags":["Reported in Guggenheim Partners Interview","New York office, Superday","Valuation","Basic"]},{"id":"q-0884","t":"val","l":"Basic","s":90,"q":"When is it most appropriate to use EV/EBITDA vs. P/E vs. EV/Revenue for valuation?","k":["EV/EBITDA: Best for comparing companies with different capital structures. Normalizes for leverage. Most common in M&A and LBO analysis.","P/E: Best for profitable companies with comparable capital structures. Equity-focused metric. Common in public market analysis.","EV/Revenue: Best for unprofitable or early-stage companies. Useful when EBITDA is negative or not meaningful. Common in high-growth tech sectors."],"collection":"practice","topic":"Valuation","tags":["Reported in Guggenheim Partners Interview","M&A group, First round","Valuation","Basic"]},{"id":"q-0885","t":"val","l":"Basic","s":90,"q":"When would you value a company on a revenue multiple versus an EBITDA basis? Why?","k":["Use Revenue Multiples When:","The company has negative or minimal EBITDA (early-stage, high-growth companies).","EBITDA margins vary widely among peers, making EBITDA-based comps inconsistent.","The company is in a high-growth industry where revenue trajectory matters more than current profitability (SaaS, biotech, early-stage tech).","Use EBITDA Multiples When:","The company is profitable and has stable, positive EBITDA.","Peers have comparable capital structures and margin profiles.","The company is in a mature industry where cash flow generation is the primary value driver.","EBITDA multiples are generally preferred because they account for cost structure differences. Revenue multiples ignore profitability entirely, so a company with 10% margins and one with 40% margins could appear similarly valued on EV/Revenue despite very different economics."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Guggenheim Partners Interview","SA 2025","Valuation","Basic"]},{"id":"q-0886","t":"val","l":"Basic","s":90,"q":"What is cheaper for a company to raise: debt or equity? Is this always the case?","k":["Debt is generally cheaper than equity for two reasons:","Interest payments on debt are tax-deductible, reducing the effective cost.","Debt holders have priority in the capital structure, so they accept a lower return than equity investors who bear more risk.","This is not always the case. If a company is highly leveraged, additional debt becomes increasingly expensive as lenders demand higher interest rates to compensate for default risk. At extreme leverage levels, the marginal cost of debt can exceed the cost of equity. Additionally, distressed or highly volatile companies may find debt prohibitively expensive or unavailable."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Guggenheim Partners Interview","SA 2027, Superday","Valuation","Basic"]},{"id":"q-0887","t":"val","l":"Basic","s":90,"q":"A company has a $1 billion top line and a 20% EBITDA margin. Comparable companies are valued at 6x EV/EBITDA. What is the company's Enterprise Value (EV)?","k":["To calculate the Enterprise Value (EV):","First, calculate EBITDA: $1 billion * 20% = $200 million.","Next, apply the EV/EBITDA multiple: EV = 6 * $200 million = $1.2 billion.","Therefore, the company's Enterprise Value is $1.2 billion."],"collection":"practice","topic":"Valuation","tags":["Reported in Houlihan Lokey Interview","Valuation","Basic"]},{"id":"q-0888","t":"val","l":"Basic","s":90,"q":"Two companies have the same valuation multiple. What factors could explain why they are trading at similar levels despite potentially different underlying characteristics?","k":["Companies can arrive at the same multiple through offsetting factors:","Growth vs. margins: One may have higher growth but lower margins, while the other has lower growth but higher margins -- the multiple reflects the net effect.","Risk vs. return tradeoff: A riskier company with higher expected returns may trade similarly to a safer company with lower expected returns.","Industry classification: The market may bucket them in the same peer group and apply a sector-average multiple.","Size and liquidity: Similar market cap and float can lead to similar institutional demand and pricing.","Capital structure: Different leverage levels affect equity multiples differently than EV multiples, potentially equalizing at one metric even if diverging at another.","Cyclical positioning: Both may be at similar points in their industry cycle.","Coincidence: Markets are not perfectly efficient, and temporary pricing alignment can occur."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, First round","Valuation","Basic"]},{"id":"q-0889","t":"val","l":"Basic","s":90,"q":"Is EBITDA always the best metric to use for multiples? What are other options?","k":["EBITDA is popular because it’s a proxy for operating cash flow, but it can ignore capex, working capital needs, and interest.","Alternatives include EBIT, which accounts for depreciation, or EBITDA–Capex, which factors in maintenance spending. For banks, you might use P/E or P/B."],"collection":"practice","topic":"Valuation","tags":["Reported in J.P. Morgan Interview","Valuation","Basic"]},{"id":"q-0890","t":"val","l":"Basic","s":90,"q":"When is it more appropriate to use an EV/EBITDA multiple versus an EV/EBIT multiple in a comparable company analysis, and what are the key considerations?","k":["Use EV/EBITDA when:","Comparing companies with different D&A policies (useful when D&A is accounting-driven rather than economic).","Standard practice for most \"capital-light\" industries.","Use EV/EBIT when:","Analyzing capital-intensive industries (e.g., Manufacturing, Airlines) where D&A represents a real capital cost (proxy for Capex).","Companies have similar capital structures.","Want a metric closer to operating profit (EBITDA overstates cash flow for Capex-heavy firms)."],"collection":"practice","topic":"Valuation","tags":["Reported in J.P. Morgan Interview","New York Office, Second round","Valuation","Basic"]},{"id":"q-0891","t":"val","l":"Basic","s":90,"q":"Select two similar, publicly traded companies in an industry you follow.\n\n\n\n\nWhy does one trade at a higher valuation multiple than the other?","k":["Sample answer framework:","Company A trades at higher multiples than Company B because:","Higher revenue growth rate (20% vs. 10%).","Superior profit margins (30% vs. 20% EBITDA margin).","Stronger market position and brand recognition.","Better management execution track record.","More recurring revenue and customer retention.","Lower capital intensity and higher ROIC.","Note: Provide specific companies and metrics based on your industry knowledge."],"collection":"practice","topic":"Valuation","tags":["Reported in J.P. Morgan Interview","Second round","Valuation","Basic"]},{"id":"q-0892","t":"val","l":"Basic","s":90,"q":"How would you value a local coffee shop, and what financial information would you ask for from the owners to inform your valuation?","k":["Financial Information to Request","3-5 years of revenue and profit margins (operating income, net income)","Owner's discretionary earnings (add back owner salary, personal expenses run through the business)","Lease terms and rent expense","CapEx requirements (equipment replacement, renovations)","Customer traffic trends and seasonality","Outstanding debt or liabilities","Valuation Approach","Small business multiple: Apply a 2-4x multiple to owner's discretionary earnings (SDE). Coffee shops typically trade at 2-3x SDE.","Asset-based approach: Value equipment, inventory, and lease value as a floor.","Simple DCF: Project 5 years of cash flows and discount at a high rate (20-30%) to reflect small business risk.","No public comps or precedent transactions available for a local shop, so rely on industry rules of thumb and SDE multiples."],"collection":"practice","topic":"Valuation","tags":["New","Reported in J.P. Morgan Interview","SA 2027, SF Office, Superday","Valuation","Basic"]},{"id":"q-0893","t":"val","l":"Basic","s":90,"q":"How do you select public comparable companies?","k":["Screen for companies that are most similar across these dimensions:","Industry and sub-sector: Same products, services, and end markets.","Size: Similar revenue, EBITDA, and market cap.","Growth profile: Comparable revenue and earnings growth rates.","Margin profile: Similar gross, EBITDA, and operating margins.","Geography: Similar geographic revenue exposure.","Business model: Recurring vs. project-based revenue, B2B vs. B2C.","Capital structure: Similar leverage and capital intensity.","Start with a broad universe (industry classification, equity research peer groups) and narrow down to 8-12 companies that are the most comparable based on the criteria above. Eliminate companies in distress, undergoing M&A, or with one-time items."],"collection":"practice","topic":"Valuation","tags":["New","Reported in J.P. Morgan Interview","SA 2026, New York Office, Superday","Valuation","Basic"]},{"id":"q-0894","t":"val","l":"Basic","s":90,"q":"How do you screen for comparable companies (Comps)?","k":["Use objective filters first, then qualitative judgment.","Industry / business model","Geography","Size (revenue, EBITDA, market cap)","Growth and margin profile","Capital structure / leverage","Pull the universe from databases (CapIQ, FactSet), apply the filters, then read filings to confirm comparability."],"collection":"practice","topic":"Valuation","tags":["Reported in Jefferies Interview","SA 2026","Valuation","Basic"]},{"id":"q-0895","t":"val","l":"Basic","s":90,"q":"What is a sum-of-the-parts analysis, and why might you use it?","k":["SOTP values each business segment separately and adds them to arrive at total enterprise value.","It is useful for conglomerates with divisions that trade on different multiples or have distinct risk/growth profiles and can reveal hidden value or break‑up potential."],"collection":"practice","topic":"Valuation","tags":["Reported in Jefferies Interview","SA 2026","Valuation","Basic"]},{"id":"q-0896","t":"val","l":"Basic","s":90,"q":"What is the relationship between Cost of Debt and WACC?","k":["Because after‑tax Cost of Debt is usually below Cost of Equity, adding reasonable leverage lowers WACC up to an optimal point.","Beyond that point, default risk lifts both the Cost of Debt and the equity risk premium, causing WACC to rise."],"collection":"practice","topic":"Valuation","tags":["Reported in Jefferies Interview","SA 2026","Valuation","Basic"]},{"id":"q-0897","t":"val","l":"Basic","s":90,"q":"A company has $100 million of revenue in 2024, grows 50% in 2025 and 20% in 2026, has a 50% EBITDA margin, and trades at 10x EV/EBITDA. What is the enterprise value?\n\n\n\n\nAssume the company trades at 10x 2026 EV/EBITDA.","k":["Answer: $900 million","Calculation:","2024 Revenue = $100M","2025 Revenue = $100M x 1.50 = $150M","2026 Revenue = $150M x 1.20 = $180M","2026 EBITDA = $180M x 50% = $90M","EV = 10x x $90M = $900M"],"collection":"practice","topic":"Valuation","tags":["New","Reported in Jefferies Interview","SA 2027, Aerospace & Defense group, Charlotte Office, First round","Valuation","Basic"]},{"id":"q-0898","t":"val","l":"Basic","s":90,"q":"How would you value a local laundromat?","k":["For a small, private business like a laundromat, the most practical valuation methods are:","Multiples of Seller's Discretionary Earnings (SDE): SDE = Net Income + Owner's Salary + Owner Benefits + D&A. Small businesses typically trade at 2-4x SDE.","Comparable transactions: Look at recent sales of similar laundromats in the area. Laundromats often sell for 3-5x annual cash flow or ~1x revenue.","Asset-based approach: Value the equipment (washers, dryers, HVAC) and lease terms. Useful as a floor valuation.","Simple DCF: Project free cash flows and discount at a high rate (15-25%) to reflect the risk of a single-location, owner-dependent business.","A full-blown institutional DCF or public comps would be less practical, but a simplified DCF can serve as a useful cross-check."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Jefferies Interview","SA 2026, First round","Valuation","Basic"]},{"id":"q-0899","t":"val","l":"Basic","s":90,"q":"What is wrong with EBITDA as a metric?","k":["Ignores capital expenditures: EBITDA adds back D&A but ignores the ongoing CapEx required to maintain or grow the business. A capital-intensive company can have strong EBITDA but weak free cash flow.","Ignores working capital needs: Changes in receivables, inventory, and payables consume or release cash but are not reflected in EBITDA.","Ignores differences in capital structure: EBITDA excludes interest, so it does not reflect the true cost of leverage. Two companies with the same EBITDA but different debt levels have very different risk profiles.","Ignores taxes: Tax rates vary by jurisdiction and structure, and EBITDA does not capture these differences.","Can be manipulated: Companies may classify expenses to inflate EBITDA (e.g., capitalizing costs that should be expensed, or using \"adjusted EBITDA\" with aggressive add-backs).","Not a GAAP metric: There is no standardized definition, making cross-company comparisons potentially misleading."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Valuation","Basic"]},{"id":"q-0900","t":"val","l":"Basic","s":90,"q":"How would you value cash sitting on a company's balance sheet?","k":["Cash is valued at face value (dollar for dollar) in most cases.","In the enterprise value bridge, cash is subtracted from EV to arrive at equity value. This implicitly values each dollar of cash at $1.","However, the market may value cash at less than $1 if investors believe management will deploy it poorly (value-destroying acquisitions, wasteful spending). This is common in companies with poor capital allocation track records.","Conversely, cash may be valued at a premium if the company is in a distressed industry and liquidity provides a survival advantage.","Trapped cash (e.g., held overseas with repatriation tax implications, or restricted cash in regulated subsidiaries) may be valued at a discount since it is not freely available to shareholders."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Valuation","Basic"]},{"id":"q-0901","t":"val","l":"Basic","s":90,"q":"What is the difference between EBITDA and unlevered free cash flow?","k":["EBITDA = Earnings Before Interest, Taxes, Depreciation & Amortization. It is a proxy for operating cash generation but is not actual cash flow.","Unlevered Free Cash Flow (UFCF) = EBIT x (1 - Tax Rate) + D&A - CapEx - Change in Net Working Capital.","Key differences:","Taxes: EBITDA ignores taxes entirely. UFCF accounts for cash taxes (at the unlevered level).","CapEx: EBITDA does not deduct capital expenditures. UFCF subtracts CapEx, reflecting the actual investment needed to maintain or grow the business.","Working capital: EBITDA ignores changes in working capital. UFCF accounts for cash tied up in receivables, inventory, and payables.","UFCF represents the actual cash available to all capital providers (debt and equity) after reinvestment, making it more accurate for valuation purposes."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Valuation","Basic"]},{"id":"q-0902","t":"val","l":"Basic","s":90,"q":"Why would a company with a higher growth rate typically command higher valuation multiples?","k":["Higher growth rates increase the present value of future cash flows, justifying higher multiples.","Key reasons:","Faster earnings growth leads to higher terminal value in DCF analysis.","Investors pay premium for companies that can compound returns faster.","Growth companies reinvest more efficiently, generating higher ROI.","Higher growth often signals competitive advantages, market leadership, or innovation."],"collection":"practice","topic":"Valuation","tags":["Reported in Lazard Interview","FIG First round","Valuation","Basic"]},{"id":"q-0903","t":"val","l":"Basic","s":90,"q":"Which do you think is better for increasing revenue: an increase in price or an increase in volume?","k":["An increase in price is generally better for profitability. A price increase flows almost entirely to the bottom line since there is typically no incremental cost associated with charging more. A volume increase drives more revenue but also increases variable costs (COGS, distribution, etc.), so the margin impact is smaller.","However, the answer depends on context:","Price increases work best when the company has pricing power (strong brand, low elasticity, few substitutes).","Volume increases are preferable for companies with high fixed costs and low variable costs (software, media) since they have high operating leverage and incremental volume is very high-margin.","Price increases risk reducing demand if the product is price-elastic.","In most cases, price is the stronger lever for value creation."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Lincoln International Interview","SA 2026, Superday","Valuation","Basic"]},{"id":"q-0904","t":"val","l":"Basic","s":90,"q":"If you only know a company's EBITDA, how would you value the company?","k":["Apply an EV/EBITDA multiple from comparable companies to the target's EBITDA to derive an implied enterprise value.","For example, if the company has $50M EBITDA and comparable companies trade at 10x EV/EBITDA, the implied EV is $500M. You would then subtract net debt to get equity value.","To refine the analysis, you would select the appropriate multiple based on the company's industry, growth profile, margin characteristics, and size relative to peers."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Lincoln International Interview","SA 2026, First round","Valuation","Basic"]},{"id":"q-0905","t":"val","l":"Basic","s":90,"q":"Why is EBITDA such a commonly used metric for valuing companies?","k":["EBITDA is widely used because:","It is capital structure neutral: excludes interest, making it comparable across companies with different leverage levels.","It removes non-cash charges (D&A) that vary based on accounting policies and asset age, improving comparability.","It serves as a proxy for operating cash flow generation before reinvestment.","It is tax-agnostic, enabling cross-border comparisons across different tax jurisdictions.","That said, EBITDA has limitations: it ignores CapEx requirements, working capital needs, and can overstate cash flow for capital-intensive businesses."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Lincoln International Interview","SA 2026, First round","Valuation","Basic"]},{"id":"q-0906","t":"val","l":"Basic","s":90,"q":"How would a company taking on more debt impact WACC?","k":["Initially WACC falls because after‑tax debt is cheaper than equity.","Beyond an optimal point, rising default risk pushes up the cost of both debt and equity, so WACC rises."],"collection":"practice","topic":"Valuation","tags":["Reported in LionTree Interview","SA 2026","Valuation","Basic"]},{"id":"q-0907","t":"val","l":"Basic","s":90,"q":"What is a sum of parts valuation, and how does it work?","k":["Value each business segment independently with the most appropriate method (DCF or multiples), then sum the segment values and subtract net debt and corporate adjustments.","This isolates businesses with different growth, risk and capital‑intensity profiles, producing a more precise consolidated valuation."],"collection":"practice","topic":"Valuation","tags":["Reported in LionTree Interview","SA 2026","Valuation","Basic"]},{"id":"q-0908","t":"val","l":"Basic","s":90,"q":"Why would the market value a company with recurring revenue at a high EV/EBITDA multiple?\n\n\n\n\nFollow-up: In what scenario would the market value it lower, even with recurring revenue?","k":["High multiple drivers:","Visibility and stability of cash flow","Low churn and strong pricing power","Scalable, asset‑light model yielding high margins","Lower multiple scenarios:","Decelerating growth or rising churn","Contractual price resets reducing margin","Customer concentration or weak competitive moat","Regulatory overhang or high capital needs"],"collection":"practice","topic":"Valuation","tags":["Reported in LionTree Interview","SA 2026","Valuation","Basic"]},{"id":"q-0909","t":"val","l":"Basic","s":90,"q":"A company's EV/EBITDA multiple decreases from 10x to 9x. What does that mean?\n\n\n\n\nFollow-up: What if the multiple increases from 10x to 11x?","k":["If EV/EBITDA decreases from 10x to 9x, there are two possible explanations:","EV decreased while EBITDA stayed constant: The market is valuing the company's operations at a lower premium, possibly due to declining growth expectations, sector headwinds, or increased risk.","EBITDA increased while EV stayed constant: The company grew earnings but the market has not re-priced the stock upward, suggesting the market expects growth to slow or has other concerns.","Either way, a lower multiple means the company is relatively cheaper per dollar of EBITDA.","Follow-up: Multiple increases from 10x to 11x","EV increased faster than EBITDA: Market is assigning a higher premium, reflecting improved growth expectations, favorable sector trends, or reduced risk.","EBITDA declined while EV held steady: Earnings are contracting but the market still has confidence in recovery or long-term value.","A higher multiple means the company is relatively more expensive per dollar of EBITDA."],"collection":"practice","topic":"Valuation","tags":["New","Reported in LionTree Interview","SA 2027, New York Office, First round","Valuation","Basic"]},{"id":"q-0910","t":"val","l":"Basic","s":90,"q":"Would you rather invest in a company with 30% margins and 10% market share or a company with 10% margins and 30% market share? What if the industry is nascent and growing?","k":["Typically, higher margins are preferable as they indicate better profitability. However, a higher market share can provide economies of scale and stronger competitive positioning. If the industry is nascent and growing, prioritizing market share might be advantageous to establish a dominant position early on, even if current margins are lower."],"collection":"practice","topic":"Valuation","tags":["Reported in M. Klein & Co. Interview","Valuation","Basic"]},{"id":"q-0911","t":"val","l":"Basic","s":90,"q":"What is the problem with the ratio EV/Net Income? What would be a better ratio?","k":["EV/Net Income can be problematic because net income is affected by non-cash items, taxes, and financing decisions, making it less comparable across companies. A better ratio is EV/EBITDA, which focuses on operational performance and is less influenced by capital structure and accounting differences."],"collection":"practice","topic":"Valuation","tags":["Reported in M. Klein & Co. Interview","Valuation","Basic"]},{"id":"q-0912","t":"val","l":"Basic","s":90,"q":"Why do bankers use EBITDA to compare businesses? What are some of the drawbacks of EBITDA?","k":["Bankers use EBITDA because it provides a measure of operational performance that excludes the effects of financing and accounting decisions, allowing for easier comparison between companies. However, EBITDA has drawbacks, including ignoring capital expenditures, working capital changes, and not accounting for debt, which can lead to an incomplete view of a company's financial health."],"collection":"practice","topic":"Valuation","tags":["Reported in M. Klein & Co. Interview","Valuation","Basic"]},{"id":"q-0913","t":"val","l":"Basic","s":90,"q":"$400mm EBITDA @ 6x multiple, $600mm debt, $200mm cash. What is equity value?","k":["$2.0 B","EV = 6 × 400 = 2,400.","Equity = EV – Debt + Cash = 2,400 – 600 + 200 = 2,000."],"collection":"practice","topic":"Valuation","tags":["Reported in M. Klein & Co. Interview","SA 2026","Valuation","Basic"]},{"id":"q-0914","t":"val","l":"Basic","s":90,"q":"P/E of Nvidia vs. GM — which is higher?","k":["Nvidia.","Its rapid growth and capital‑light model command a materially higher earnings multiple than GM’s cyclical, asset‑heavy auto business."],"collection":"practice","topic":"Valuation","tags":["Reported in M. Klein & Co. Interview","SA 2026","Valuation","Basic"]},{"id":"q-0915","t":"val","l":"Basic","s":90,"q":"Debt/EBITDA of 5x and Interest Coverage of 4x. What is the interest rate?","k":["5 %.","Interest expense = EBITDA / 4.","Debt = 5 × EBITDA.","Interest rate = (EBITDA / 4) ÷ (5 × EBITDA) = 1 / 20 = 5%."],"collection":"practice","topic":"Valuation","tags":["Reported in M. Klein & Co. Interview","SA 2026","Valuation","Basic"]},{"id":"q-0916","t":"val","l":"Basic","s":90,"q":"When analyzing a company's revenue, how do you determine whether it is price-driven or quantity-driven? Why does this distinction matter?","k":["Revenue = Price x Quantity. To determine the driver, compare average selling price (ASP) trends vs. unit volume trends over time. Company filings and earnings calls often disclose this breakdown explicitly.","Why It Matters","Price-driven growth signals pricing power and flows directly to EBITDA with no incremental costs.","Volume-driven growth carries incremental variable costs, so margins may not expand as much.","Companies with pricing power typically command higher valuation multiples."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Mizuho Interview","SA 2027, Superday","Valuation","Basic"]},{"id":"q-0917","t":"val","l":"Basic","s":90,"q":"Imagine you have a standard x vs. y plot of WACC vs. Leverage.\n\n\n\n\nWhat is the shape of that plot?","k":["A U‑shaped curve.","WACC falls at first as tax‑advantaged debt replaces costlier equity, bottoms out at the optimal capital structure, then climbs as financial distress risk overwhelms the tax benefit."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","SA 2025, Los Angeles Office, First round","Valuation","Basic"]},{"id":"q-0918","t":"val","l":"Basic","s":90,"q":"In the context of evaluating a project or investment, what is the fundamental difference between the Internal Rate of Return (IRR) and the Weighted Average Cost of Capital (WACC)?","k":["IRR is the discount rate that makes a project’s NPV zero based solely on its cash flows, whereas WACC is the firm’s overall hurdle rate that compensates investors for debt-service risk, equity risk, and potential liquidity constraints.","Explanation:","IRR is derived strictly from the project’s own cash-flow pattern, without regard to how the project is financed or its liquidity needs.","WACC reflects the market-determined cost of debt and equity, including compensation for default risk on debt payments and liquidity premiums.","It also accounts for the firm’s capital structure and any potential liquidity issues arising from servicing that debt."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","Valuation","Basic"]},{"id":"q-0919","t":"val","l":"Basic","s":90,"q":"Would you expect the cost of equity to be higher in a typical LBO model or a standard DCF model for the same company? Why?","k":["Higher in the LBO because extreme leverage magnifies equity risk, so sponsors target 20–30 % returns versus the 8–12 % required by diversified public investors.","Explanation:","Greater debt ↑ levered beta and equity volatility.","Private‑equity funds demand an illiquidity and control premium.","Public DCF uses market‑based ke reflecting lower leverage and diversification."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","Valuation","Basic"]},{"id":"q-0920","t":"val","l":"Basic","s":90,"q":"Please answer the following questions:\n\n\n\nHow much of a premium is typically paid when acquiring a public company?\nHow does tax reform affect valuation and M&A trends?\nWhat is your outlook on the M&A market for the upcoming year?","k":["Part 1: Typical Acquisition Premium","Acquisition premiums for public companies typically range from 20-40% over the unaffected stock price (pre-announcement). Premiums vary by industry, deal rationale, competitive dynamics, and strategic value.","Part 2: Tax Reform Impact","Lower corporate tax rates increase after-tax cash flows, raising DCF valuations and making acquisitions more attractive. Changes to interest deductibility affect LBO financing. Repatriation rules influence cross-border M&A and use of offshore cash.","Part 3: M&A Outlook","This requires current market knowledge. Structure your answer around: interest rate environment, financing availability, strategic vs. financial buyer activity, regulatory climate, sector-specific trends, and geopolitical factors. Support with recent deal flow data."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","New York Office, First round","Valuation","Basic"]},{"id":"q-0921","t":"val","l":"Basic","s":90,"q":"What are the four main valuation methodologies?\n\n\n\n\nFollow-up 1: What are the key components for each, and how do you derive them?\n\n\n\n\nFollow-up 2: Rank them from highest to lowest valuation, and explain why.","k":["Four Main Methodologies","Comparable Company Analysis (Comps)","Precedent Transaction Analysis (Precedents)","Discounted Cash Flow (DCF)","Leveraged Buyout (LBO)","Follow-up 1: Key Components","Comps: Trading multiples (EV/EBITDA, P/E) from similar public companies applied to target metrics.","Precedents: Acquisition multiples from comparable M&A transactions applied to target.","DCF: Project unlevered FCF, discount at WACC, add Terminal Value.","LBO: Maximum price a PE firm can pay to achieve target IRR (typically 20-25%).","Follow-up 2: Valuation Ranking","Highest to Lowest: Precedents > DCF > Comps > LBO","Precedents: Include control premium and synergies from actual deals.","DCF: Reflects intrinsic value based on cash flows; can be optimistic with aggressive assumptions.","Comps: Reflects current market trading (no control premium).","LBO: Conservative floor; PE firms need margin of safety for target returns."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","Valuation","Basic"]},{"id":"q-0922","t":"val","l":"Basic","s":90,"q":"Given the following four multiples, which can you use as a valuation metric and which can you not? Why?\n\n\n\nEV / Earnings\nEV / EBITDA\nPrice / EBITDA\nPrice / Earnings","k":["Valid Multiples:","EV / EBITDA: ✓ Enterprise metric (EV) to enterprise metric (EBITDA).","Price / Earnings: ✓ Equity metric (Price) to equity metric (Earnings).","Invalid Multiples:","EV / Earnings: ✗ Mismatch. EV is enterprise-level, Earnings is equity-level (post-interest).","Price / EBITDA: ✗ Mismatch. Price is equity-level, EBITDA is enterprise-level (pre-interest).","Valid multiples compare metrics at the same capital structure level (both enterprise or both equity). Mismatched multiples are conceptually flawed."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","Valuation","Basic"]},{"id":"q-0923","t":"val","l":"Basic","s":90,"q":"What are some different valuation multiples that can be used to value a company?\n\n\n\n\nFollow-up 1: Which multiples would be most appropriate for a high-growth technology company?\n\n\n\n\nFollow-up 2: What about for a mature industrial company?","k":["Common valuation multiples:","EV/Revenue, EV/EBITDA, EV/EBIT","P/E, P/B, P/S","EV/Subscribers, EV/Users (for tech/media)","Follow-up 1: High-Growth Tech Company","EV/Revenue: Often pre-profitable, so revenue multiples are primary.","EV/Gross Profit: If scaling with improving unit economics.","EV/Users or EV/ARR: For SaaS or subscription models.","Follow-up 2: Mature Industrial Company","EV/EBITDA: Standard for cash flow-generating businesses.","P/E: Reflects earnings stability.","EV/EBIT: For capital-intensive businesses with significant D&A."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","Valuation","Basic"]},{"id":"q-0924","t":"val","l":"Basic","s":90,"q":"Pick an industry sector.\n\n\n\n\nHow would you create a comparable company set for a company in that sector, and what are some of the key factors you would consider?","k":["This is an open-ended question. Below is a sample framework applicable to any sector.","Steps to create a comparable company set:","Industry / Sector: Companies in the same or closely related industry.","Business Model: Similar revenue streams, cost structures, and operations.","Size: Comparable revenue, EBITDA, or market cap (avoid huge size mismatches).","Geography: Similar markets or regions if relevant to business dynamics.","Growth Profile: Similar growth rates and stage of maturity.","Profitability: Comparable margins and returns.","End Markets: Similar customer bases or cyclical exposure.","Tailor criteria to the sector. For example, in healthcare, consider therapeutic areas; in retail, consider brick-and-mortar vs. e-commerce."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","Valuation","Basic"]},{"id":"q-0925","t":"val","l":"Basic","s":90,"q":"If you observed two apparently identical companies in the same industry, but one traded at a significantly higher valuation multiple, what are two or three reasons that could explain this difference?","k":["Potential reasons for valuation disparity:","Growth Prospects: Higher-multiple company has superior revenue/earnings growth trajectory.","Profitability & Margins: Better operating leverage, higher EBITDA or net margins.","Competitive Position: Stronger brand, market share, or competitive moat.","Capital Structure: Lower leverage provides less financial risk.","Management Quality: Track record of execution and capital allocation.","Market Perception: Better ESG profile, investor sentiment, or sector positioning.","Even \"identical\" companies differ in quality of earnings, growth sustainability, risk profile, and strategic positioning—all reflected in valuation."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","Valuation","Basic"]},{"id":"q-0926","t":"val","l":"Basic","s":90,"q":"If one company trades at a 10x multiple and another comparable company trades at 30x, what are some reasons that could explain this difference?","k":["Potential explanations for multiple disparity:","Growth expectations (30x company likely has much higher growth rate).","Profitability and margins (higher quality earnings command premiums).","Risk profile (lower risk, more predictable cash flows increase multiples).","Market positioning and competitive moats.","Size and scale differences (larger = liquidity premium).","Sector dynamics (one may be in declining industry, other in growth sector).","Capital efficiency and ROIC differences.","Management quality and execution track record.","Cyclicality (defensive businesses command higher multiples than cyclical ones)."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","First round","Valuation","Basic"]},{"id":"q-0927","t":"val","l":"Basic","s":90,"q":"Why would a firm prefer precedent transactions over public comparable companies, and vice versa?","k":["Prefer Precedent Transactions:","The company is likely to be acquired, so transaction multiples (including control premiums) are more relevant.","Many recent comparable deals exist in the sector.","Few publicly traded peers are available for trading comps.","Prefer Public Comparables:","Need current, real-time market data. Trading comps reflect today's conditions.","A robust set of publicly traded peers exists with similar profiles.","Valuing a minority stake (no control premium needed).","Recent M&A transactions were done in unusual conditions that distort multiples."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Moelis & Co. Interview","SA 2026, First round","Valuation","Basic"]},{"id":"q-0928","t":"val","l":"Basic","s":90,"q":"If you were trying to decide between selling a machine today or in one year, what would you consider?","k":["Compare the present value of the sale price now vs. the expected sale price in one year discounted back, factoring in potential depreciation or usage cost, plus any opportunity cost or additional income from using the machine for that year."],"collection":"practice","topic":"Valuation","tags":["Reported in Morgan Stanley Interview","Valuation","Basic"]},{"id":"q-0929","t":"val","l":"Basic","s":90,"q":"What happens to the cost of debt as a company’s rating improves?","k":["As credit ratings improve, lenders perceive lower default risk, which generally lowers the interest rate demanded.","Thus, cost of debt decreases, improving the company’s overall WACC if it’s using debt financing."],"collection":"practice","topic":"Valuation","tags":["Reported in Morgan Stanley Interview","Valuation","Basic"]},{"id":"q-0930","t":"val","l":"Basic","s":90,"q":"Tell me about different valuation methods and the pros and cons of each.","k":["Public Comps – quick and market‑based; subject to sentiment swings.","Precedent Transactions – includes control premium; past deals may be stale or incomparable.","Discounted Cash Flow – theoretically sound; highly sensitive to long‑term assumptions.","Leveraged Buy‑Out – floors value via IRR constraints; only relevant if sponsors are realistic buyers."],"collection":"practice","topic":"Valuation","tags":["Reported in Morgan Stanley Interview","SA 2026, New York office, First round","Valuation","Basic"]},{"id":"q-0931","t":"val","l":"Basic","s":90,"q":"Why are some companies valued based on EV/Revenue, EV/EBITDA, versus P/E or EPS?","k":["The appropriate multiple depends on the company's profitability stage and industry:","EV/Revenue: Used for high-growth companies that are pre-profit or have minimal EBITDA (e.g., early-stage SaaS, biotech). Revenue is the only meaningful financial metric available.","EV/EBITDA: The most commonly used multiple in IB. Works for profitable companies and normalizes for differences in capital structure, tax rates, and D&A policies. Preferred for most M&A and comparable company analyses.","P/E or EPS: Used for mature, profitable companies where bottom-line earnings are stable and meaningful. Common for financial institutions (where EV-based metrics do not work) and large-cap public companies. P/E incorporates capital structure and taxes, making it useful for equity investors.","The general rule: use the lowest line item on the income statement that is still positive and meaningful for the company."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Morgan Stanley Interview","SA 2027","Valuation","Basic"]},{"id":"q-0932","t":"val","l":"Basic","s":90,"q":"How much is your company worth? Share both the market view and your personal view.","k":["This is a framework question. Structure your response around a company you know well (ideally one from a past internship, club, or personal investment).","Market View:","Current market cap / equity value based on today's share price.","Enterprise value using the EV bridge.","Where it trades on key multiples (EV/EBITDA, P/E) versus peers.","Personal View:","State whether you think the company is overvalued, fairly valued, or undervalued.","Support with a thesis: Is the market missing a growth driver, overestimating risk, or mispricing a catalyst?","Reference a simple DCF or comparable analysis to ground your view in numbers.","Prepare this with a specific company and concrete data points before your interview."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Superday","Valuation","Basic"]},{"id":"q-0933","t":"val","l":"Basic","s":90,"q":"Why do Precedent Transactions sometimes yield a higher valuation than comparable companies, and why is it sometimes lower?","k":["Why higher (typical case):","Precedent transactions include a control premium (typically 20-40%) since the acquirer is buying control of the target.","Buyers may pay for expected synergies not reflected in public trading multiples.","Competitive auction dynamics can bid up the price.","Why lower (less common):","If precedent deals occurred during a market downturn or recession, those multiples may be depressed relative to current trading levels.","Distressed or forced sales may have been completed at below-market multiples.","If the public markets are currently in a period of inflated valuations (e.g., a bubble), trading comps may exceed historical deal multiples."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Morgan Stanley Interview","SA 2027, New York Office, Superday","Valuation","Basic"]},{"id":"q-0934","t":"val","l":"Basic","s":90,"q":"You are shown a list of public comparable companies. Which would you exclude from the set, and why?","k":["Exclude companies that would distort the comparable analysis:","Companies undergoing M&A: Their stock price reflects a deal premium, not standalone trading value.","Distressed or bankrupt companies: Abnormally low multiples that are not representative of healthy peers.","Significant size mismatches: A $500M revenue company is not comparable to a $50B revenue company -- they face different growth constraints and market dynamics.","Different business models: Even within the same industry, a subscription-based company is not comparable to a project-based company.","Recent IPOs: May not have sufficient trading history and could be subject to lockup expirations or volatile pricing.","Companies with one-time items: Large impairments, restructuring charges, or windfalls that distort current financials.","Different geographic exposure: A U.S.-only company vs. a company with 70% international revenue may not be comparable."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Morgan Stanley Interview","SA 2025, Menlo Park Office, First round","Valuation","Basic"]},{"id":"q-0935","t":"val","l":"Basic","s":90,"q":"Companies A, B, and C all have the same EBITDA this year.\n\n\n\n\nTheir EV / EBITDA multiples are 8x, 9x, and 10x now, but forward multiples are 10x, 9x, and 8x respectively.\n\n\n\n\nWhich company would you invest in?","k":["Answer: Company C is the most attractive investment.","Here's why:","Company A is expected to have declining EBITDA, since its forward multiple rises (8x → 10x). This suggests deteriorating future earnings.","Company B is expected to have stable EBITDA, since its forward multiple remains the same (9x). This suggests limited upside compared to growth-oriented peers.","Company C is expected to have growing EBITDA, since its forward multiple falls (10x → 8x). This suggests strong EBITDA growth.","The market pays a premium for future growth."],"collection":"practice","topic":"Valuation","tags":["Reported in Nomura Greentech Interview","Valuation","Basic"]},{"id":"q-0936","t":"val","l":"Basic","s":90,"q":"Aside from standard metrics like EV/EBITDA or EV/Revenue, what is another key metric you could use to evaluate a company's efficiency?\n\n\n\n\nHow is it calculated and what does it tell you?","k":["Return on Invested Capital (ROIC)","ROIC = NOPAT / Invested Capital, where Invested Capital = Total Debt + Total Equity - Cash.","ROIC measures how efficiently a company generates returns from its capital investments. A higher ROIC indicates better capital allocation and operational efficiency.","Companies with ROIC > WACC create value; those with ROIC < WACC destroy value.","Other Metrics:","Cash Conversion Cycle: Measures efficiency in managing working capital.","Asset Turnover: Revenue / Total Assets—shows how efficiently assets generate revenue."],"collection":"practice","topic":"Valuation","tags":["Reported in Perella Weinberg Interview","SF Office","Valuation","Basic"]},{"id":"q-0937","t":"val","l":"Basic","s":90,"q":"How would a greater proportion of debt affect WACC?","k":["Initially lowers WACC thanks to cheaper after‑tax debt, but beyond an optimal leverage point distress risk pushes WACC back up."],"collection":"practice","topic":"Valuation","tags":["Reported in Piper Sandler Interview","SA 2025, off-cycle, London office","Valuation","Basic"]},{"id":"q-0938","t":"val","l":"Basic","s":90,"q":"A company has a $200M market cap and trades at 10x P/E.\n\n\n\n\nWhat is its net income?","k":["$20 mm (because $200 mm ÷ 10 = $20 mm)."],"collection":"practice","topic":"Valuation","tags":["Reported in PJT Partners Interview","SA 2025, off-cycle, London office","Valuation","Basic"]},{"id":"q-0939","t":"val","l":"Basic","s":90,"q":"You have a coverage ratio of 4 and a debt ratio of 2 and need the interest rate.\n\n\n\n\nHow do you compute it?","k":["Let EBIT = 100.","Interest = EBIT ÷ Coverage = 100 ÷ 4 = 25.","Debt = Ratio × EBIT = 2 × 100 = 200.","Cost of debt = Interest ÷ Debt = 25 ÷ 200 = 0.125 (12.5%)."],"collection":"practice","topic":"Valuation","tags":["Reported in PJT Partners Interview","SA 2025, off-cycle, London office","Valuation","Basic"]},{"id":"q-0940","t":"val","l":"Basic","s":90,"q":"How do higher central bank rates affect the cost of equity?","k":["They raise it.","Under CAPM, Cost of Equity = Risk‑free Rate + β × Equity‑Risk‑Premium.","When a central bank hikes policy rates, government bond yields—your risk‑free proxy—move up.","Holding β and the ERP constant, the higher risk‑free rate flows straight through to a higher cost of equity, raising discount rates and lowering valuations."],"collection":"practice","topic":"Valuation","tags":["Reported in PJT Partners Interview","SA 2025, off-cycle, London office","Valuation","Basic"]},{"id":"q-0941","t":"val","l":"Basic","s":90,"q":"What is the Capital Asset Pricing Model (CAPM) formula?\n\n\n\n\nFollow-up: What is the relationship between a project's Internal Rate of Return (IRR) and the company's Weighted Average Cost of Capital (WACC)?","k":["CAPM Formula","Cost of Equity = Risk-Free Rate + Beta * (Market Return - Risk-Free Rate)","Where Beta measures systematic risk relative to the market, and (Market Return - Risk-Free Rate) is the equity risk premium.","IRR vs. WACC Relationship","A project should be accepted if its IRR exceeds the company's WACC.","WACC represents the minimum required return for the company. IRR is the project's expected return. If IRR > WACC, the project creates value. If IRR < WACC, it destroys value."],"collection":"practice","topic":"Valuation","tags":["Reported in PJT Partners Interview","New York Office","Valuation","Basic"]},{"id":"q-0942","t":"val","l":"Basic","s":90,"q":"If two companies in the same industry trade at different EV/EBITDA multiples (e.g., one at 15x and another at 10x), what could explain this discrepancy?","k":["Key factors that explain valuation multiple differences:","Growth rates (higher growth commands higher multiples).","Profitability and margins (better margins justify premiums).","Risk profile (lower risk, more stable cash flows increase multiples).","Market position and competitive advantages.","Size and scale (larger firms often trade at premiums).","Capital structure and leverage differences.","Management quality and execution track record.","Market sentiment and investor perception."],"collection":"practice","topic":"Valuation","tags":["Reported in PJT Partners Interview","First round","Valuation","Basic"]},{"id":"q-0943","t":"val","l":"Basic","s":90,"q":"How would you value a company if you had very little financial data available?","k":["Comparable companies: Identify similar businesses and apply industry-standard multiples to any available metric (revenue, EBITDA, subscribers, users).","Comparable transactions: Look at what similar companies sold for in M&A deals.","Asset-based approach: Sum the fair market value of the company's tangible and intangible assets.","Revenue-based multiples: If you only have revenue, use EV/Revenue comps.","Industry rules of thumb: Some industries have standard valuation metrics (e.g., $ per subscriber, $ per bed, $ per acre).","A DCF is difficult with limited data since it requires detailed projections. Focus on market-based approaches when data is scarce."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Raymond James Interview","SA 2027, First round","Valuation","Basic"]},{"id":"q-0944","t":"val","l":"Basic","s":90,"q":"A company has an equity value of 200M and debt of 300M. It has a purchase price multiple of 10. What is EBITDA?","k":["EBITDA is $50M.","If the purchase price multiple is 10x EBITDA, the purchase price refers to enterprise value in many cases. EV = 200 equity + 300 debt = 500.","500 / 10 = 50."],"collection":"practice","topic":"Valuation","tags":["Reported in RBC Interview","Valuation","Basic"]},{"id":"q-0945","t":"val","l":"Basic","s":90,"q":"How would you value a coffin company?","k":["Standard approaches: DCF (project stable demand, typical margins), comparable company multiples (other funeral/casket businesses), and precedent transactions in the death-care industry.","A coffin company might have stable, non-cyclical cash flows, so DCF can be quite reliable if you assume consistent mortality rates and cost structure."],"collection":"practice","topic":"Valuation","tags":["Reported in Rothschild Interview","Valuation","Basic"]},{"id":"q-0946","t":"val","l":"Basic","s":90,"q":"When selecting precedent transactions, how far back in time would you typically look for comparable M&A deals?\n\n\n\n\nIn what situations might you justify looking further back?","k":["Typical lookback period: 2-3 years for most industries to capture recent market conditions and valuation trends.","Situations justifying longer lookback:","Limited deal activity (niche industries with infrequent transactions).","Market dislocation (recent downturn makes older deals more representative).","Cyclical industries (include full cycle to capture normalized multiples).","Mega-deals or transformational transactions (few comparables, landmark deals relevant even if older).","Stable industry dynamics (if fundamentals unchanged, older deals remain relevant).","Always adjust for changes in market conditions, interest rates, and industry dynamics when using older precedents."],"collection":"practice","topic":"Valuation","tags":["Reported in Rothschild Interview","First round","Valuation","Basic"]},{"id":"q-0947","t":"val","l":"Basic","s":90,"q":"How would you value the property that a local Korean restaurant sits on?","k":["Three approaches to value the property:","1. Income Approach (DCF / Cap Rate):","Estimate annual rental income the property could generate (either current lease or market rent for the area).","Subtract operating expenses (property taxes, insurance, maintenance) to get Net Operating Income (NOI).","Apply a capitalization rate (NOI / Property Value). Cap rates for restaurant/retail properties in urban areas typically range 5-8%.","Property Value = NOI / Cap Rate.","2. Comparable Sales Approach:","Look at recent sale prices of similar commercial properties in the same neighborhood.","Adjust for differences in size, condition, location, and zoning.","Price per square foot is a common metric.","3. Replacement Cost Approach:","Estimate the cost to purchase the land and rebuild the structure from scratch.","Land value + Construction costs - Depreciation of existing structure.","The income approach is most relevant for investment purposes; comps are most practical for a quick estimate."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Rothschild Interview","SA 2027, First round","Valuation","Basic"]},{"id":"q-0948","t":"val","l":"Basic","s":90,"q":"A company has an EV/Sales multiple of 5x and an EBITDA margin of 20%.\n\n\n\n\nWhat is its EV/EBITDA multiple?","k":["Answer: 25x","Calculation:","EBITDA = Revenue × EBITDA Margin = Revenue × 20% = 0.2 × Revenue.","EV = 5x × Revenue.","EV/EBITDA = (5 × Revenue) / (0.2 × Revenue) = 5 / 0.2 = 25x."],"collection":"practice","topic":"Valuation","tags":["Reported in Solomon Partners Interview","Full-Time Analyst 2026, NYC Office","Valuation","Basic"]},{"id":"q-0949","t":"val","l":"Basic","s":90,"q":"Other than the control premium, what are some reasons that precedent transaction analysis often yields a higher valuation than comparable company analysis?","k":["Reasons for higher transaction multiples:","Synergy value: Buyers pay premium for expected cost or revenue synergies.","Strategic value: Acquisitions can unlock value not reflected in public trading (market access, technology, talent).","Competitive bidding: Multiple bidders drive up price in auctions.","Lack of liquidity discount: Private companies trade at discount for illiquidity, but buyers pay for control and eliminate this discount.","Tax benefits: Asset step-up and NOL utilization can justify higher prices.","Scarcity value: Limited availability of attractive targets in consolidating industries."],"collection":"practice","topic":"Valuation","tags":["Reported in TAP Advisors Interview","First round","Valuation","Basic"]},{"id":"q-0950","t":"val","l":"Basic","s":90,"q":"Why is debt cheaper than equity?\n\n\n\n\nWhat is the correlation with interest rates?","k":["Debt sits higher in the capital stack and receives fixed coupons, so investors demand lower returns than residual equity holders.","Interest rates set the risk‑free baseline; as central‑bank rates rise, the absolute cost of debt climbs and the after‑tax advantage versus equity narrows."],"collection":"practice","topic":"Valuation","tags":["Reported in UBS Interview","SA 2026, New York office, Superday","Valuation","Basic"]},{"id":"q-0951","t":"val","l":"Basic","s":90,"q":"Is the WACC for a company financed with 100% debt higher than for a company with a mix of debt and equity?","k":["Yes, typically it is higher.","The instinct is that because debt is cheaper than equity, more debt keeps pushing WACC down. That only holds over a moderate range of leverage.","At 100% debt there is no equity cushion beneath the lenders, so they absorb all of the business risk and price for it: rates spike, covenants tighten, and expected default and distress costs climb. That cost of debt converges on — and can exceed — what equity holders would have demanded, and the tax shield no longer offsets it (and is worth nothing without taxable income).","WACC against leverage is U-shaped: falling as you add cheap debt and capture the shield, bottoming at an optimal structure, then rising as distress costs dominate. A balanced structure sits near that minimum. In practice 100% debt is unrealistic anyway — lenders require an equity cushion."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Basic"]},{"id":"q-0952","t":"val","l":"Basic","s":90,"q":"If debt is cheaper than equity, why would a company ever raise capital with equity?","k":["Several reasons to use equity despite higher cost:","Debt capacity constraints: Lenders limit leverage ratios","Financial flexibility: Equity has no mandatory payments, reducing default risk","Covenant restrictions: Too much debt limits operational flexibility","Credit rating concerns: Excessive debt downgrades ratings","Market timing: High stock prices make equity attractive","Growth companies: Unstable cash flows make debt risky","Beyond a certain point, additional debt becomes prohibitively expensive due to financial distress costs."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Basic"]},{"id":"q-0953","t":"val","l":"Basic","s":90,"q":"Under what circumstances might a valuation from Precedent Transactions be lower than a valuation from Comparable Companies?","k":["Scenarios where transaction multiples < trading multiples:","Distressed sales: Transactions during downturns or forced sales at discounts","Stale precedents: Old transactions when valuations were depressed","Current market exuberance: Trading multiples elevated vs. historical M&A","Strategic vs. financial buyers: Recent deals dominated by PE with lower prices","Market timing: Precedents from bear market, comps from bull market","Smaller/lower quality targets: Transaction set includes inferior assets","Generally, precedents include control premium, so this situation is less common."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Basic"]},{"id":"q-0954","t":"val","l":"Basic","s":90,"q":"Calculate the EV/Revenue multiple for the following two companies:\n\n\n\n\nCompany A: $100M Revenue, 30% EBITDA Margin, 8x EV/EBITDA multiple.\n\n\n\n\nCompany B: $50M Revenue, 20% EBITDA Margin, 10x EV/EBITDA multiple.","k":["Company A:","EBITDA = $100M * 30% = $30M","EV = $30M * 8x = $240M","EV/Revenue = $240M / $100M = 2.4x","Company B:","EBITDA = $50M * 20% = $10M","EV = $10M * 10x = $100M","EV/Revenue = $100M / $50M = 2.0x"],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Basic"]},{"id":"q-0955","t":"val","l":"Basic","s":90,"q":"Why would two companies with identical financial statements trade at different P/E ratios?","k":["Multiple factors beyond current financials drive P/E:","Growth expectations: Higher expected growth commands higher P/E","Risk profile: Lower risk (stable industry) supports higher P/E","Management quality: Better leadership drives premium valuation","Competitive position: Stronger moat/market share justifies higher P/E","Capital structure: Different leverage levels affect equity risk and P/E","Market sentiment: Sector rotation, investor preferences","Liquidity: More liquid stocks trade at premium","Accounting quality: One-time items, aggressive accounting can depress P/E"],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Basic"]},{"id":"q-0956","t":"val","l":"Basic","s":90,"q":"A company's WACC is 12%, and its after-tax cost of debt is 7%. Its capital structure is 50% debt and 50% equity.\n\n\n\n\nWhat is the company's cost of equity? (Note: the provided tax rate of 30% is not needed).","k":["Answer: 17%","Calculation:","WACC = (Weight of Debt * Cost of Debt) + (Weight of Equity * Cost of Equity)","12% = (50% * 7%) + (50% * Cost of Equity)","12% = 3.5% + (50% * Cost of Equity)","8.5% = 50% * Cost of Equity","Cost of Equity = 17%"],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Basic"]},{"id":"q-0957","t":"val","l":"Basic","s":90,"q":"You are reviewing a comparable companies analysis with five companies. Four of them trade in an 8-10x EV/EBITDA range, but one trades at 20x.\n\n\n\n\nWhat are the possible reasons for this outlier, and what steps would you take to investigate?","k":["Possible reasons for the outlier:","Higher growth expectations or superior growth profile vs. peers","Better margins, ROIC, or competitive positioning","Recent M&A speculation or takeover premium","Unique technology, IP, or strategic assets","Temporarily depressed EBITDA (one-time charges, restructuring costs)","Different business model or revenue streams","Market inefficiency or lack of liquidity","Investigation steps:","Review financial metrics: growth rates, margins, ROIC, leverage","Analyze EBITDA quality: check for one-time items or adjustments","Compare business models and end-market exposure","Review recent news for M&A activity or strategic announcements","Assess whether the company truly belongs in the comp set","Consider excluding the outlier or creating a separate category if justified"],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Basic"]},{"id":"q-0958","t":"val","l":"Basic","s":90,"q":"Two companies are the same size, in the same industry, and have the same revenue, but different EBITDAs.\n\n\n\n\nWhat are some possible reasons for this discrepancy?","k":["Possible reasons for different EBITDA despite same revenue:","Different cost structures (COGS, labor efficiency).","Different operating expense levels (SG&A, R&D).","Different business models (e.g., asset-light vs. asset-heavy).","Different pricing strategies affecting margins.","Geographic or customer mix differences.","Different stages of growth (mature vs. high-growth investing heavily).","One-time charges or unusual items affecting operating expenses."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Superday","Valuation","Basic"]},{"id":"q-0959","t":"val","l":"Basic","s":90,"q":"For a high-growth 'Magnificent Seven' company with a positive market outlook, what would you expect its EV/Sales multiple to do over the next few years and why?","k":["The EV/Sales multiple would likely decline over time.","Growth Maturation: As revenue grows, the denominator increases faster than valuations can expand.","Margin Expansion: High-growth companies typically improve profitability over time, making metrics like EV/EBITDA more relevant.","Multiple Compression: Markets pay premium multiples for growth; as growth moderates, multiples contract.","Base Effect: With a larger revenue base, maintaining extremely high multiples becomes unsustainable.","However, if innovation or market dominance accelerates beyond expectations, multiples could remain elevated."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Superday","Valuation","Basic"]},{"id":"q-0960","t":"val","l":"Basic","s":90,"q":"You are given three companies, each with an EBITDA of $100M, and EV/EBITDA multiples of 2.0x, 3.0x, and 4.0x, respectively.\n\n\n\n\nPart 1: Plot the Enterprise Value for the three companies on a graph.\n\n\n\n\nPart 2: Explain the shape of the graph and your rationale.","k":["Part 1: Enterprise Values","Company 1: EV = $100M * 2.0x = $200M","Company 2: EV = $100M * 3.0x = $300M","Company 3: EV = $100M * 4.0x = $400M","Part 2: Graph Shape and Rationale","The graph shows a linear relationship between EV/EBITDA multiples and Enterprise Value.","Each 1.0x increase in multiple adds $100M to Enterprise Value.","Higher multiples reflect better growth prospects, margins, or lower risk.","The linear relationship demonstrates that valuation scales proportionally with the multiple applied."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Superday","Valuation","Basic"]},{"id":"q-0961","t":"val","l":"Basic","s":90,"q":"Part 1: How does beta typically vary across different industries?\n\n\n\n\nPart 2: Which company would you expect to have a higher beta: American Airlines or Amazon? Why?","k":["Part 1: Beta by Industry","High Beta (> 1.0): Technology, retail, airlines (cyclical, volatile earnings).","Low Beta (< 1.0): Utilities, consumer staples, healthcare (stable, defensive).","Beta ~1.0: Broad market average.","Part 2: American Airlines vs. Amazon","American Airlines would have higher beta.","American Airlines: Highly cyclical, sensitive to fuel costs, economic downturns, high operational leverage.","Amazon: Diversified revenue streams (e-commerce, AWS, advertising), less cyclical, more stable cash flows.","Airlines have historically higher betas due to volatility and fixed cost structure."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Superday","Valuation","Basic"]},{"id":"q-0962","t":"val","l":"Basic","s":90,"q":"Why is the tax rate an important consideration in the context of valuation?","k":["The tax rate directly impacts valuation in several ways:","DCF: Tax rate affects after-tax cash flows and WACC (through after-tax cost of debt).","Net Income: Higher tax rates reduce NI, lowering equity value in P/E-based valuations.","After-Tax Cost of Debt: Debt provides a tax shield; lower tax rates reduce this benefit.","Comparability: Companies in different jurisdictions with varying tax rates require adjustments for accurate comparisons.","M&A: Tax structure of the deal (asset vs. stock purchase) significantly impacts value to buyer and seller."],"collection":"practice","topic":"Valuation","tags":["Reported in Wells Fargo Interview","Superday","Valuation","Basic"]},{"id":"q-0963","t":"val","l":"Basic","s":90,"q":"On a conceptual level, how does a firm create economic value?","k":["If a firm invests capital at a return that exceeds its cost of capital, it’s creating economic value.","In other words, ROIC > WACC means every dollar invested returns more than it costs, leading to value creation for shareholders."],"collection":"practice","topic":"Valuation","tags":["Reported in William Blair Interview","Valuation","Basic"]},{"id":"q-0964","t":"val","l":"Advanced","s":90,"q":"For a company in the Dow 30, would you expect a valuation from public comps or a DCF to be higher?","k":["Public comps would typically be higher for a Dow 30 name, though it turns on the DCF assumptions.","Why comps screen higher here:","Dow 30 constituents carry a liquidity and quality premium. They are mega-cap, heavily traded, and widely covered, so investors accept a lower required return, which shows up as a higher multiple.","Index inclusion creates structural demand from passive vehicles that hold the name regardless of valuation.","A DCF captures none of that. It values projected cash flows only, so any premium for liquidity, index membership, or brand is absent.","These are mature, low-growth businesses, so a terminal value built off a 2-3% perpetuity rate leaves little room for a high number.","The DCF can come out higher in a drawdown, when comps reflect depressed sentiment, or with favorable inputs — 50bps on WACC or terminal growth moves the value 10-15%."],"collection":"practice","topic":"Valuation","tags":["Reported in Bank of America Interview","GIG, First round","Valuation","Advanced"]},{"id":"q-0965","t":"val","l":"Advanced","s":90,"q":"How would you value Sony after they announced their entry into the electric vehicle space?","k":["Use Sum-of-the-Parts (SOTP) valuation:","Value Core Businesses: Gaming, entertainment, electronics, financial services using comparable company multiples or DCF.","Value EV Business Separately: Use pure-play EV comparable companies (Tesla, Rivian, Lucid) to derive EV/Revenue or EV/Unit multiples. Apply to Sony's projected EV revenue or unit sales.","Apply Discount: Sony's EV business is nascent with high uncertainty. Apply 30-50% discount to reflect execution risk and lack of scale.","Sum Components: Add discounted EV business value to core business value.","Alternatively, use DCF with separate revenue/margin assumptions for EV division. Account for significant capex and cash burn during ramp-up phase. EV business may initially drag on overall valuation but offers long-term optionality."],"collection":"practice","topic":"Valuation","tags":["Reported in Bank of America Interview","FSG, First round","Valuation","Advanced"]},{"id":"q-0966","t":"val","l":"Advanced","s":90,"q":"A company has EV/Revenue of 3x, EV/EBITDA of 5x, and EV/EBIT of 12x. What type of business is this?","k":["This is likely a capital-intensive, mature business with significant D&A.","Analysis of the multiples:","EV/Revenue of 3x with EV/EBITDA of 5x implies an EBITDA margin of 60% (3/5 = 60%). This is a very high-margin business.","EV/EBITDA of 5x vs. EV/EBIT of 12x implies heavy depreciation & amortization, since EBIT is much lower than EBITDA. D&A margin = 60% - (3/12 = 25%) = 35% of revenue.","This profile suggests a capital-intensive infrastructure or telecom business (high EBITDA margins but heavy D&A from large asset bases), or a recently-acquired company with high purchase price amortization of intangibles."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Bank of America Interview","Emerging Growth & Regional Coverage group, SF Office, Superday","Valuation","Advanced"]},{"id":"q-0967","t":"val","l":"Advanced","s":90,"q":"Can a DCF ever produce a higher value than a precedent transaction analysis?","k":["Yes. A DCF can produce a higher value than precedent transactions in several scenarios:","The company has exceptionally high projected growth that is not reflected in historical deal multiples.","Precedent transactions are stale or occurred during a downturn when multiples were depressed.","Very aggressive DCF assumptions are used (low WACC, high terminal growth rate, optimistic projections).","The company operates in a rapidly growing sector where forward-looking cash flows significantly exceed what historical deal multiples would imply.","This is why it is important to present a range of valuations and sensitize key assumptions."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Bank of America Interview","SA 2025, First round","Valuation","Advanced"]},{"id":"q-0968","t":"val","l":"Advanced","s":90,"q":"You are evaluating a burger restaurant in a college town. How would you estimate its revenue? If a Burger King opens across the street, how would you stay competitive? How would you estimate costs? How would you value the restaurant?","k":["Revenue Estimation:","Estimate daily customer traffic (seats x turns per day x occupancy rate).","Multiply by average ticket size.","Annualize with seasonal adjustments (e.g., lower during summer if students leave).","Competitive Response to Burger King:","Differentiate on quality, local branding, and customization.","Loyalty programs, student discounts, delivery partnerships.","Focus on menu items Burger King does not offer.","Cost Estimation:","Food costs (~30% of revenue), labor (~25-30%), rent, utilities, insurance.","Valuation:","Apply a DCF using projected cash flows.","Or use comparable restaurant transaction multiples (typically 3-5x EBITDA for small restaurants).","Or asset-based approach if the restaurant owns its property."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Bank of America Interview","EGRC group, Superday","Valuation","Advanced"]},{"id":"q-0969","t":"val","l":"Advanced","s":90,"q":"A company has Year 1 projected multiples of EV/EBITDA 17x and P/E 30x. In Year 2, the projected multiples are EV/EBITDA 15x and P/E 35x. What can you tell me about this company?","k":["The multiples reveal important dynamics about the company:","EV/EBITDA declining from 17x to 15x: EBITDA is growing faster than EV, meaning the company is expected to grow EBITDA from Year 1 to Year 2. This is a sign of operational improvement.","P/E increasing from 30x to 35x: Net income is declining relative to equity value, meaning NI is expected to decrease from Year 1 to Year 2 even as EBITDA grows.","The divergence (growing EBITDA but falling NI) indicates increasing below-the-line costs: higher interest expense (the company is taking on more debt), higher D&A (significant CapEx or recent acquisitions), or increasing tax expense.","This profile is consistent with a company making large capital investments or acquisitions that boost EBITDA but generate significant interest and depreciation costs that compress net income."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Bank of America Interview","SA 2025, Superday","Valuation","Advanced"]},{"id":"q-0970","t":"val","l":"Advanced","s":90,"q":"If you were comparing a semiconductor company, a software company, and an internet company, what key financial characteristics would distinguish each? How would you determine whether each is early stage or mature, and which valuation multiples would you use?","k":["Framework for identifying companies by financial profile:","Semiconductor Company","High gross margins (50-70%) but significant R&D and CapEx (capital-intensive fabs).","Cyclical revenue patterns. Moderate to high EBITDA margins.","Valuation: EV/EBITDA, EV/Revenue, P/E. If mature and profitable, use EV/EBITDA.","Software Company","Very high gross margins (70-90%), low CapEx, high R&D spend.","Recurring revenue (SaaS) with high retention rates. May have negative or low EBITDA if in growth mode.","Valuation: EV/Revenue for high-growth/early-stage, EV/EBITDA or Rule of 40 (growth rate + margin) for mature companies.","Internet Company","High revenue growth, variable margins, low CapEx. Revenue may be ad-driven or transaction-based.","Valuation: EV/Revenue, EV/Users, or EV/GMV for early-stage. EV/EBITDA for mature platforms."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Bank of America Interview","SA 2025, Superday","Valuation","Advanced"]},{"id":"q-0971","t":"val","l":"Advanced","s":90,"q":"An energy transition company is planning to do an IPO in 2034, but it has negative cash flow right now. What methods can you use to value the IPO for the company?","k":["DCF with long-term projections: Project cash flows until the company reaches profitability and steady state. Use scenario analysis and higher discount rates to reflect uncertainty.","Comparable company analysis: Use revenue-based multiples (EV/Revenue) since EBITDA is negative. Compare to public peers in similar energy transition subsectors.","Comparable transactions / recent funding rounds: Look at valuations from recent private placements, Series rounds, or M&A transactions for similar companies.","Sum-of-the-parts: If the company has multiple projects or technologies, value each project's future cash flows independently using a risk-adjusted NPV.","Real options analysis: Value the optionality embedded in early-stage technology or undeveloped projects (useful for companies with significant unproven upside).","Backsolve from target returns: Determine what IPO valuation gives institutional investors their required return based on projected financials at a future exit."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Bank of America Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-0972","t":"val","l":"Advanced","s":90,"q":"Compare the following two companies and share your thoughts:\n\n\n\n\nCompany 1: EV/Revenue of 9.5x, EV/Net Income of 23.2x\n\n\n\n\nCompany 2: EV/Revenue of 12.5x, EV/Net Income of 10.9x","k":["First, flag the metric: EV/Net Income is a mismatched multiple — EV is an unlevered metric (available to all capital providers) while Net Income is a levered metric (available only to equity holders). In practice, you would use EV/EBITDA or P/E instead. Flagging this to the interviewer demonstrates strong analytical thinking.","With that caveat in mind, here is the directional analysis:","Company 2 is significantly more profitable. It trades at a higher revenue multiple (12.5x vs. 9.5x) but a much lower EV/NI multiple (10.9x vs. 23.2x), implying a much higher net income margin.","Company 1 has lower profitability: The high EV/NI multiple (23.2x) relative to its EV/Revenue (9.5x) implies low net income margins. Investors may be paying for anticipated margin expansion or future growth.","Company 2 may be a more mature, cash-generative business, while Company 1 may be a higher-growth company reinvesting heavily and sacrificing current profitability.","Note: The EV/NI mismatch can create impossible-looking numbers. Company 2's multiples imply a net income margin above 100% (EV/Revenue 12.5x vs. EV/NI 10.9x), which is impossible for an operating company. This distortion arises because EV and NI are mismatched — if Company 2 has significant net cash, EV would be lower than Equity Value, making EV-based multiples appear compressed."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Barclays Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-0973","t":"val","l":"Advanced","s":90,"q":"Company A has an EV/Revenue of 9.5x and an EV/EBITDA of 23.2x. Company B has an EV/Revenue of 12.5x and an EV/EBITDA of 10.9x. What is wrong with this data?","k":["The implied EBITDA margins are inconsistent with what you would expect.","Company A: EBITDA Margin = EV/Revenue / EV/EBITDA = 9.5 / 23.2 = ~41%","Company B: EBITDA Margin = 12.5 / 10.9 = ~115%","An EBITDA margin above 100% is impossible -- it would mean EBITDA exceeds revenue. This indicates Company B's data is erroneous. Either the EV/Revenue is too high, the EV/EBITDA is too low, or the enterprise values used for each multiple are inconsistent (e.g., different dates or different adjustments to EV)."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Barclays Interview","SA 2025, SF Office, First round","Valuation","Advanced"]},{"id":"q-0974","t":"val","l":"Advanced","s":90,"q":"A company is growing at 10% into perpetuity and has a 4% dividend yield. What should you buy it at?","k":["Use Gordon Growth: required return = yield + growth = 14%. Pay 1 / (14% − 10%) = 25× the current dividend to achieve that return."],"collection":"practice","topic":"Valuation","tags":["Reported in BMO Interview","SA 2026, Toronto office, First round","Valuation","Advanced"]},{"id":"q-0975","t":"val","l":"Advanced","s":90,"q":"How would you value Tesla, and what key items would you include in a pitchbook for its valuation?","k":["Valuation approaches for Tesla:","DCF Analysis: Project vehicle deliveries, ASPs, margins, and potential new revenue streams (energy, autonomy, software). Use scenario analysis given high uncertainty.","Trading Comps: Traditional auto OEMs (Ford, GM) and EV pure-plays (Rivian, Lucid). Note Tesla often trades at premium multiples.","Precedent Transactions: Limited relevant precedents in EV space.","Key Pitchbook Items:","Production capacity and delivery forecasts by model.","Margin trajectory and cost reduction initiatives.","Market share analysis by geography.","Regulatory credits and sustainability.","Adjacent businesses: energy storage, solar, FSD software.","Competitive landscape: traditional OEMs, Chinese EV makers, startups."],"collection":"practice","topic":"Valuation","tags":["Reported in Centerview Partners Interview","First round","Valuation","Advanced"]},{"id":"q-0976","t":"val","l":"Advanced","s":90,"q":"Two companies, same sizes, industry, growth, but one is American and publicly listed, and the other is private in Colombia. Which has a higher valuation, or are they the same? What factors affect that?","k":["The publicly listed U.S. company often trades at a higher multiple due to greater liquidity, regulatory transparency, and perceived lower risk. The private Colombian company might be discounted for less liquidity, potential political/currency risk, and less disclosure."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Valuation","Advanced"]},{"id":"q-0977","t":"val","l":"Advanced","s":90,"q":"A company provides the following financial data:\n\n\n\nLevered Free Cash Flow (LFCF) Yield: 10%\nEBITDA: $100\nCapital Expenditures: $5\nInterest Expense: $25\nDecrease in Working Capital: $10\nTax Expense: $5\n\n\n\nWhat is the company's market capitalization?","k":["Answer: $750","Calculation:","LFCF = EBITDA - Cash Interest - Cash Taxes - CapEx - Change in NWC.","LFCF = $100 - $25 - $5 - $5 - (-$10) = $75.","Note: We add back the decrease in NWC since it represents a source of cash.","Market Cap = LFCF / LFCF Yield = $75 / 10% = $750."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Chicago office, First round","Valuation","Advanced"]},{"id":"q-0978","t":"val","l":"Advanced","s":90,"q":"Calculate Beta given the following information:\n\n\n\nThe correlation coefficient between a stock and the market is 0.5.\nThe ratio of the standard deviation of the stock to the standard deviation of the market is 2.0.","k":["Answer: 1.0","Calculation:","Beta = Correlation * (Std Dev Stock / Std Dev Market)","Beta = 0.5 * 2.0 = 1.0","A beta of 1.0 means the stock moves in line with the market on average, despite having twice the volatility, because the correlation is only 0.5."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","Superday","Valuation","Advanced"]},{"id":"q-0979","t":"val","l":"Advanced","s":90,"q":"Company A and Company B have identical balance sheets. What are six reasons Company A could have a higher valuation?","k":["Six reasons for higher valuation:","Higher Revenue Growth: Faster top-line expansion prospects.","Better Margins: Superior unit economics or pricing power despite same asset base.","Stronger Market Position: Greater competitive moat or brand value.","Superior Management: Track record of execution and capital allocation.","Lower Risk Profile: More stable, predictable cash flows.","Better Industry Dynamics: Operating in more attractive sector with higher growth or profitability."],"collection":"practice","topic":"Valuation","tags":["Reported in Citi Interview","First round","Valuation","Advanced"]},{"id":"q-0980","t":"val","l":"Advanced","s":90,"q":"Calculate the share price given the following information: EBITDA of $100M, CapEx of $5M, interest expense of $25M, decrease in net working capital of $10M, tax expense of $5M, net debt of $500M, fully diluted shares of 100M, and an LFCF Yield of 10% (where LFCF Yield = LFCF / Equity Value).","k":["Answer: $7.50 per share","LFCF = EBITDA - CapEx - Interest Expense + Decrease in NWC - Tax Expense","LFCF = $100M - $5M - $25M + $10M - $5M = $75M","Decrease in NWC is a source of cash, so it adds to FCF.","Equity Value = LFCF / LFCF Yield = $75M / 0.10 = $750M","Since LFCF is already after interest (levered), it directly implies Equity Value -- do not subtract net debt again.","Share Price = Equity Value / Diluted Shares = $750M / 100M = $7.50"],"collection":"practice","topic":"Valuation","tags":["New","Reported in Citi Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-0981","t":"val","l":"Advanced","s":90,"q":"If you were valuing a company in Mexico instead of Brazil, what would be the key differences in your approach?","k":["Key differences when valuing a company in Mexico vs. Brazil:","Currency: You would project cash flows in Mexican Pesos (MXN) instead of Brazilian Reais (BRL), and use USD/MXN exchange rate assumptions for translation.","Country Risk Premium: Mexico and Brazil have different sovereign risk profiles. You would use Mexico's country risk premium (based on its CDS spread or EMBI spread) instead of Brazil's. Historically Brazil has carried a higher country risk premium.","Risk-Free Rate: Use Mexico's local government bond yield if doing a local currency DCF, or the U.S. Treasury yield plus Mexico's country risk premium for a USD-denominated DCF.","Tax Rate: Mexico's corporate tax rate is 30% vs. Brazil's 34% (combined federal/social contribution). This affects after-tax cash flows and the tax shield on debt.","Comparable Companies: Use Mexican and Latin American peers listed on the BMV rather than Bovespa-listed comps.","Regulatory Environment: Different industry regulations, FDI rules, and trade dynamics (Mexico benefits from USMCA/nearshoring trends)."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Citi Interview","SA 2025, Latam group, First round","Valuation","Advanced"]},{"id":"q-0982","t":"val","l":"Advanced","s":90,"q":"A company has a market cap of $100 million and a P/E multiple of 10x. Assume the company's revenue is $20 million and costs are $10 million. If costs are cut in half and the multiple stays the same, what is the new market cap?","k":["Answer: $150 million","Calculation:","Original: Market Cap = $100M, P/E = 10x, so NI = $100M / 10 = $10M","Original: Revenue $20M - Costs $10M = $10M NI (confirms)","New costs = $10M / 2 = $5M","New NI = $20M - $5M = $15M","New Market Cap = P/E x NI = 10 x $15M = $150M","Note: This assumes no taxes for simplicity, consistent with the question's framing where Revenue - Costs = NI."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Citi Interview","SA 2025, Latam group, First round","Valuation","Advanced"]},{"id":"q-0983","t":"val","l":"Advanced","s":90,"q":"How would you approach the valuation of a leveraged loan?","k":["Key approaches for leveraged loan valuation:","Discounted Cash Flow: Discount contractual loan payments (principal and interest) at appropriate risk-adjusted rate.","Market Comparables: Reference trading prices of similar loans in secondary market.","Credit Analysis: Assess borrower's creditworthiness, covenant package, collateral, and recovery prospects.","Yield Analysis: Compare yield-to-maturity to market benchmarks for similar credit quality.","Consider seniority, security, covenants, and company performance when determining appropriate discount rate."],"collection":"practice","topic":"Valuation","tags":["Reported in Credit Suisse Interview","Financial Sponsors group, New York Office, Second round","Valuation","Advanced"]},{"id":"q-0984","t":"val","l":"Advanced","s":90,"q":"Walk me through some factors about why a company would be valued greater than its peers, both quantitatively and qualitatively.","k":["Companies may be valued higher than peers due to a combination of quantitative and qualitative factors:","Quantitative Factors:","Higher revenue growth, indicating faster expansion.","Superior profit margins (gross, operating, or net), reflecting greater efficiency.","Strong and consistent free cash flows, enhancing valuation.","Lower debt levels, reducing financial risk.","Higher return metrics like Return on Equity (ROE) or Return on Invested Capital (ROIC).","Qualitative Factors:","Strong brand recognition and market presence.","Competitive advantages such as unique products, technologies, or patents.","Experienced and effective management inspiring investor confidence.","Strategic partnerships that enhance market reach or operations.","Positive market perception due to innovation or growth prospects.","Geographic diversification reducing risk and increasing growth opportunities.","These factors contribute to higher valuation by demonstrating superior performance, reduced risk, and greater growth potential compared to peers."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","Valuation","Advanced"]},{"id":"q-0985","t":"val","l":"Advanced","s":90,"q":"ParentCo owns 100% of CoffeeCo (private, $100m EBITDA) and 80% of DonutCo (public, $200m EBITDA, trades at 5x EBITDA).\n\n\n\n\nParentCo: $10/share, 100m shares, $500m debt, $200m cash.\n\n\n\n\nWhat is the implied multiple for CoffeeCo?","k":["Answer: 5x","Calculation:","ParentCo Equity Value = $10 * 100m = $1,000m","Because ParentCo consolidates DonutCo, we must add Non-Controlling Interest (NCI) to find Total Enterprise Value (TEV).","DonutCo TEV = $200m * 5x = $1,000m.","NCI = 20% of DonutCo's Equity Value. Assuming DonutCo has no net debt for simplicity, NCI = 20% * $1,000m = $200m.","ParentCo TEV = EqV ($1,000m) + Debt ($500m) + NCI ($200m) - Cash ($200m) = $1,500m.","Implied CoffeeCo TEV = ParentCo TEV – DonutCo TEV = $1,500m - $1,000m = $500m","Implied CoffeeCo Multiple = $500m / $100m = 5x"],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","Valuation","Advanced"]},{"id":"q-0986","t":"val","l":"Advanced","s":90,"q":"Given: P/E=20x, EV/EBITDA=10x, Int Exp=$20M, Int Rate=5%, Dep=$20M, Market Cap=$200M.\n\n\n\n\nWhat is the effective tax rate?","k":["Answer: 50%","Calculation:","NI = Market Cap / (P/E) = $200m / 20x = $10M.","Debt = Int Exp / Int Rate = $20m / 5% = $400M.","EV = Market Cap + Debt = $200m + $400m = $600M (assume no cash, preferred or NCI).","EBITDA = EV / (EV/EBITDA) = $600m / 10x = $60M.","Pre-Tax Income (EBT) = EBITDA - D&A - Int Exp = $60m - $20m - $20m = $20M.","Tax = EBT - NI = $20m - $10m = $10M.","Tax Rate = Tax / EBT = $10m / $20m = 50%."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","Valuation","Advanced"]},{"id":"q-0987","t":"val","l":"Advanced","s":90,"q":"Two airlines have the same enterprise value.\n\n\n\n\nOne uses capital leases, the other operating leases.\n\n\n\n\nWhich trades at a higher EBITDA multiple?","k":["The airline with operating leases trades at a higher EBITDA multiple because lease expense reduces EBITDA, making the multiple higher."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","Valuation","Advanced"]},{"id":"q-0988","t":"val","l":"Advanced","s":90,"q":"P/E is 40x, EV/Revenue is 10x, net income is $15mm, $400mm in debt, no cash.\n\n\n\n\nDepreciation is $10mm, EBITDA margin is 50%, and tax rate is 25%. What is the interest rate?","k":["Equity value = 40 × 15 = $600 mm; EV = 600 + 400 = $1,000 mm.","Revenue = 1,000 ÷ 10 = $100 mm; EBITDA = 50% × 100 = $50 mm.","EBIT = 50 − 10 = $40 mm; EBT = 15 ÷ 0.75 = $20 mm.","Interest expense = 40 − 20 = $20 mm.","Interest rate = 20 ÷ 400 = 5%."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","SA 2026, New York office, First round","Valuation","Advanced"]},{"id":"q-0989","t":"val","l":"Advanced","s":90,"q":"Why might two companies in the same industry with very similar operations trade at different EV/EBITDA multiples?","k":["Multiples embed growth, risk and cash‑flow quality; small differences here drive valuation gaps.","Key factors:","Different forward growth rates.","Margin and cost‑structure resilience.","Capital intensity and FCF conversion.","Return on invested capital.","Business‑risk profile: cyclicality, regulatory, concentration.","Size, liquidity and trading float.","Scarcity value or strategic buyer interest."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","Valuation","Advanced"]},{"id":"q-0990","t":"val","l":"Advanced","s":90,"q":"A company reports the following financials:\n\n\n\nRevenue: $100\nGross Margin: 60%\nSG&A: $20 (includes all D&A)\nP/E Multiple: 25x\nEV/EBITDA Multiple: 10x\nTax Rate: 20%\nCash: $0\nDebt: $200 at 5% interest\nBonds: $200 at 10% interest\n\n\n\nWhat is the company's Depreciation & Amortization expense?","k":["Answer: $20","Calculation:","Gross Profit = Revenue * Gross Margin = $100 * 60% = $60.","EBIT = GP - SG&A = $60 - $20 = $40.","Interest Expense = ($200 * 5%) + ($200 * 10%) = $10 + $20 = $30.","EBT = EBIT - Interest = $40 - $30 = $10.","NI = EBT * (1 - Tax Rate) = $10 * (1 - 20%) = $8.","Equity Value = NI * P/E = $8 * 25x = $200.","EV = Equity Value + Debt - Cash = $200 + $400 - $0 = $600.","EBITDA = EV / (EV/EBITDA) = $600 / 10x = $60.","Since SG&A includes D&A, EBIT = GP - SG&A already reflects D&A.","EBITDA = EBIT + D&A, so D&A = EBITDA - EBIT = $60 - $40 = $20."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","SF office","Valuation","Advanced"]},{"id":"q-0991","t":"val","l":"Advanced","s":90,"q":"Explain the appropriate use cases for EV/EBIT, EV/EBITDA, and EV/EBITDAR valuation multiples.\n\n\n\n\nFollow-up: What are the potential drawbacks or limitations of using EV/EBITDAR?","k":["Part 1: Use Cases","EV/EBIT: When D&A is consistent across comparables or immaterial. Closer to actual profitability.","EV/EBITDA: Standard for most industries. Neutralizes depreciation policy differences and capital intensity variations.","EV/EBITDAR: For companies with significant operating leases (airlines, retail). Adds back rent to compare companies with different lease vs. own decisions.","Part 2: EBITDAR Limitations","Less commonly used, making comparables harder to find.","Can overstate profitability by excluding real operating costs.","Rent is typically a genuine cash expense unlike D&A.","Modern accounting (ASC 842/IFRS 16) capitalizes leases, reducing need for EBITDAR."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","New York Office, First round","Valuation","Advanced"]},{"id":"q-0992","t":"val","l":"Advanced","s":90,"q":"You are advising a publicly traded client with two businesses: broadcasting and digital media. The facts are as follows:\n\n\n\nBroadcasting peers trade at 7x EBITDA.\nDigital media peers trade at 14x EBITDA.\nYour client's consolidated company trades at 8x EBITDA.\nThere are no synergies between the two businesses.\n\n\n\nWhat strategic recommendation would you make to the client to create value? If they decide to sell a business, which one should they sell and why?","k":["Recommendation: Spin off or sell the digital media business.","Rationale:","The conglomerate trades at 8x, below the 14x multiple for pure-play digital media companies.","Market is applying a conglomerate discount, undervaluing the digital media segment.","Separating allows digital media to trade at its natural 14x multiple.","Broadcasting would trade at 7x standalone.","Sum-of-the-parts valuation exceeds current consolidated 8x multiple.","Sell the digital media business to capture the 14x multiple arbitrage and unlock shareholder value."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","New York Office, Second round","Valuation","Advanced"]},{"id":"q-0993","t":"val","l":"Advanced","s":90,"q":"Part 1: Given a bond's price, par value, coupon rate, and maturity, how do you calculate its Yield to Maturity (YTM)?\n\n\n\n\nPart 2: How would the YTM be impacted if the coupon payments were changed from annual to semi-annual?","k":["Part 1: YTM Calculation","YTM is the internal rate of return (IRR) that equates the present value of all future cash flows to the current bond price.","Approximation Formula: YTM = [C + (F - P) / n] / [(F + P) / 2]","C = Annual coupon payment","F = Face value","P = Current price","n = Years to maturity","Precise calculation requires iterative solving or financial calculator.","Part 2: Semi-Annual Impact","Semi-annual coupons typically result in slightly higher effective YTM due to more frequent compounding and reinvestment of coupon payments.","The stated YTM with semi-annual payments must be doubled to get the annual rate (bond equivalent yield), but the effective annual rate will be marginally higher than with annual payments."],"collection":"practice","topic":"Valuation","tags":["Reported in Evercore Interview","First round","Valuation","Advanced"]},{"id":"q-0994","t":"val","l":"Advanced","s":90,"q":"Given EBITDA, an interest rate, EV/EBITDA multiples, and a Debt/EBITDA leverage ratio, calculate the interest coverage ratio.","k":["Interest Coverage Ratio = EBITDA / Interest Expense","Steps to calculate from the given inputs:","Debt = EBITDA x Debt/EBITDA leverage ratio (this gives you the total debt balance)","Interest Expense = Debt x Interest Rate","Interest Coverage = EBITDA / Interest Expense","Note: The EV/EBITDA multiple is not needed for this calculation — the leverage ratio (Debt/EBITDA) directly gives you the debt balance. The EV/EBITDA multiple would be useful if you needed to calculate total enterprise value or equity value, but for interest coverage, EBITDA and the leverage ratio are sufficient.","For example: EBITDA = $100, leverage ratio = 4.0x, so Debt = $400. At a 5% interest rate, Interest Expense = $20. Interest Coverage = $100 / $20 = 5.0x."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2025","Valuation","Advanced"]},{"id":"q-0995","t":"val","l":"Advanced","s":90,"q":"What are some ways to adjust EBITDA, particularly for industry-specific items?","k":["Industry-specific EBITDA adjustments:","Retail: Add back rent/lease expenses to get EBITDAR, since leasing structures vary across companies.","Oil & Gas: Add back exploration costs to get EBITDAX.","Technology: Add back stock-based compensation (common for SaaS companies with heavy SBC).","Mining: Add back depletion charges.","Healthcare: Adjust for non-recurring regulatory or compliance costs.","General: Add back one-time restructuring, non-recurring litigation, and M&A transaction costs.","The purpose is to normalize EBITDA to reflect the ongoing, recurring earnings power of the business."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Evercore Interview","SA 2025, First round","Valuation","Advanced"]},{"id":"q-0996","t":"val","l":"Advanced","s":90,"q":"How would you value a bank such as Goldman Sachs?","k":["Banks are often valued using P/B (Price to Book) and P/E multiples. You also look at the Return on Equity (ROE), net interest margin, and capital ratios.","A Dividend Discount Model (DDM) is also common, discounting the future dividends (or residual income) by the cost of equity. DCF is less common due to the complexity of bank balance sheets and regulatory capital requirements."],"collection":"practice","topic":"Valuation","tags":["Reported in Goldman Sachs Interview","Valuation","Advanced"]},{"id":"q-0997","t":"val","l":"Advanced","s":90,"q":"A company believes its forward earnings will be significantly higher than what the market is projecting, resulting in a lower internal forecast for its forward multiple.\n\n\n\n\nHow would you advise this company?","k":["If the company has credible information that forward earnings will exceed market expectations, advisory recommendations include:","Enhanced disclosure: Increase transparency through detailed guidance to help the market understand earnings drivers.","Investor outreach: Conduct roadshows and investor meetings to communicate the earnings story directly.","Management credibility: Ensure track record of meeting/beating guidance to build trust.","Strategic communication: Highlight sustainable competitive advantages and growth catalysts.","Consider buybacks: If stock is undervalued, share repurchases can signal confidence.","Improve business mix: Highlight higher-margin, faster-growing segments that may command premium multiples."],"collection":"practice","topic":"Valuation","tags":["Reported in Goldman Sachs Interview","New York office","Valuation","Advanced"]},{"id":"q-0998","t":"val","l":"Advanced","s":90,"q":"A company's EV/Revenue multiple drops by half from one year to the next. What does that mean for the company?","k":["Two possible explanations (or a combination):","Revenue doubled while EV stayed the same: The company grew significantly, but the market did not revalue it higher. This could mean the market views the growth as unsustainable or low-quality.","EV dropped by half while revenue stayed the same: The market lost confidence in the company, perhaps due to deteriorating growth outlook, margin compression, competitive threats, or broader market sell-off.","A blend: Revenue increased somewhat while EV decreased, combining to cut the ratio in half.","A halving of EV/Revenue is a significant de-rating and typically signals the market has become much more pessimistic about the company's future growth, profitability, or risk profile. You should investigate the cause -- was it company-specific (missed earnings, lost customers) or sector-wide (multiple compression across the industry)?"],"collection":"practice","topic":"Valuation","tags":["New","Reported in Goldman Sachs Interview","SA 2027, Superday","Valuation","Advanced"]},{"id":"q-0999","t":"val","l":"Advanced","s":90,"q":"What type of asset has a negative beta? You cannot say gold, silver, or shorting a stock.","k":["U.S. Treasury bonds (particularly long-duration Treasuries) exhibit negative beta during periods of market stress. When equities sell off, investors flee to the safety of government bonds, driving up their prices. This flight-to-quality dynamic creates an inverse relationship with the stock market.","Other examples include put options on equity indices (their value increases as markets decline) and certain volatility-linked products (e.g., long VIX positions), which appreciate when market volatility spikes during downturns."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","Valuation","Advanced"]},{"id":"q-1000","t":"val","l":"Advanced","s":90,"q":"A company has $100m in sales with a 10% EBITDA margin. Which would you prefer: a 10% increase in quantity sold, a 5% increase in price, or a 5% reduction in cost?","k":["The 5% increase in price yields the highest absolute EBITDA ($15M), making it the most attractive (assuming costs scale proportionally and customers are perfectly price inelastic).","10% Increase in Quantity (assuming costs scale proportionally): Revenue = $110M, Costs = $99M → EBITDA = $11M","5% Increase in Price (assuming no drop in volume): Revenue = $105M, Costs = $90M → EBITDA = $15M","5% Reduction in Costs: Revenue = $100M, Costs = $85.5M → EBITDA = $14.5M","In practice, if we assume any meaningful price sensitivity on customers, the 5% increase in price would correspond to a drop in volume. Depending on how big that drop in volume is, the 5% reduction in cost may become more desirable."],"collection":"practice","topic":"Valuation","tags":["Reported in Greenhill & Co. Interview","Valuation","Advanced"]},{"id":"q-1001","t":"val","l":"Advanced","s":90,"q":"With a 2x sales multiple and a 5x EBITDA multiple, what is the EBITDA margin?","k":["EV/Sales = 2x and EV/EBITDA = 5x.","EBITDA Margin = EBITDA / Sales = (EV / Sales) / (EV / EBITDA) = 2 / 5 = 40%"],"collection":"practice","topic":"Valuation","tags":["Reported in Greenhill & Co. Interview","Valuation","Advanced"]},{"id":"q-1002","t":"val","l":"Advanced","s":90,"q":"Forward revenue multiple is 5x, forward EBITDA multiple is 10x.\n\n\n\n\nTwo-year forward revenue multiple is 10x, two-year forward EBITDA multiple is 25x.\n\n\n\n\nWhat does this tell you about the business? If EV is 200m, do some calculations.","k":["Next Year:","Revenue₁ = 200 / 5 = 40","EBITDA₁ = 200 / 10 = 20","Two Years Out:","Revenue₂ = 200 / 10 = 20","EBITDA₂ = 200 / 25 = 8","The steep jump in multiples implies earnings are expected to fall sharply—investors think the current downturn is temporary or the company is highly cyclical."],"collection":"practice","topic":"Valuation","tags":["Reported in Greenhill & Co. Interview","First round","Valuation","Advanced"]},{"id":"q-1003","t":"val","l":"Advanced","s":90,"q":"Rank in terms of EV impact: $10 decrease in expenses, $10 decrease in CapEx, or $10 increase in revenue.","k":["Most to least accretive:","$10 CapEx decrease","$10 expense decrease","$10 revenue increase","CapEx cuts lift FCF dollar‑for‑dollar.","Expense savings boost EBIT, but only by 10 × (1–tax).","Revenue gains flow through at the after‑tax margin, so impact is smallest."],"collection":"practice","topic":"Valuation","tags":["Reported in Greenhill & Co. Interview","First round","Valuation","Advanced"]},{"id":"q-1004","t":"val","l":"Advanced","s":90,"q":"Why might a company's EV/EBITDA multiple trade at a discount to its peers while its P/E multiple trades at a premium?","k":["This suggests the company has a favorable capital structure:","Lower debt levels reduce EV but not equity value.","Less interest expense means higher net income.","Lower EV/EBITDA (due to less debt) but higher P/E (due to higher NI).","Company may also have significant cash holdings.","Example: Low-leveraged company with strong cash generation trades at premium P/E but discount EV/EBITDA."],"collection":"practice","topic":"Valuation","tags":["Reported in Greenhill & Co. Interview","M&A group, First round","Valuation","Advanced"]},{"id":"q-1005","t":"val","l":"Advanced","s":90,"q":"A company has perpetual free cash flow of $100 million, which is expected to grow at 5% annually.\n\n\n\n\nThe appropriate discount rate is 10%.\n\n\n\n\nThe company's market capitalization is $2 billion, based on 100 million shares outstanding at a price of $20 per share.\n\n\n\n\nWhat does this information tell you about the company's valuation?","k":["The company appears undervalued based on DCF analysis.","Calculation:","DCF Enterprise Value = FCF × (1 + g) / (WACC - g) = $100M × 1.05 / (0.10 - 0.05) = $105M / 0.05 = $2,100M","Current Market Cap = $2,000M","Implied undervaluation = $100M or 5%","Interpretation:","Assuming no debt, the intrinsic equity value ($2.1B) exceeds market cap ($2.0B).","This could indicate market skepticism about growth assumptions, higher perceived risk, or temporary mispricing.","Alternatively, the company may have net debt, which would reconcile the difference."],"collection":"practice","topic":"Valuation","tags":["Reported in Guggenheim Partners Interview","New York office, First round","Valuation","Advanced"]},{"id":"q-1006","t":"val","l":"Advanced","s":90,"q":"A company has a 10x EV/EBITDA multiple, a 6x P/E multiple, and $200 in Net Income with an interest coverage ratio of 4x. Assume a 0% tax rate, D&A = 0, and Cash = 0. What are the debt balance and interest rate?","k":["Answer: Debt = $1,466.67 and Interest Rate ≈ 4.55%.","Step 1: Find Interest Expense","At 0% tax rate, Pre-tax Income = Net Income = $200","Interest Coverage = EBIT / Interest Expense = 4x, so EBIT = 4 x IE","Pre-tax Income = EBIT - IE = 4 x IE - IE = 3 x IE = $200","Interest Expense = $200 / 3 = $66.67","Step 2: Find EBIT and EBITDA","EBIT = 4 x $66.67 = $266.67","D&A = 0, so EBITDA = EBIT = $266.67","Step 3: Find Enterprise Value","EV/EBITDA = 10x, so EV = 10 x $266.67 = $2,666.67","Step 4: Find Debt","Equity Value = P/E x NI = 6 x $200 = $1,200","EV = Equity Value + Debt (Cash = 0)","Debt = EV - Equity Value = $2,666.67 - $1,200 = $1,466.67","Step 5: Find Interest Rate","Interest Rate = Interest Expense / Debt = $66.67 / $1,466.67 ≈ 4.55%"],"collection":"practice","topic":"Valuation","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, First round","Valuation","Advanced"]},{"id":"q-1007","t":"val","l":"Advanced","s":90,"q":"You are given a company's historical P/E, EV/EBITDA, and EV/EBIT ratios over the past five years.\n\n\n\n\nWhat factors would you analyze to understand the trends in these multiples and what might they indicate about the company's performance and market perception?","k":["Analyze the following factors to understand multiple trends:","Financial Performance:","Revenue and earnings growth rates.","Margin expansion or contraction (gross, EBITDA, net).","Changes in capital intensity (CapEx, D&A levels).","Capital Structure:","Leverage trends affecting EV/EBITDA vs. P/E divergence (debt increases inflate EV).","Interest coverage and debt service capacity.","Market Perception:","Sector rotation or industry sentiment shifts.","Competitive positioning changes.","Growth expectations relative to peers.","Operational Factors:","D&A intensity (high D&A widens gap between EBITDA and EBIT multiples).","Quality of earnings and sustainability.","Rising multiples generally indicate improving growth prospects or market sentiment; declining multiples suggest deteriorating fundamentals or increased risk."],"collection":"practice","topic":"Valuation","tags":["Reported in J.P. Morgan Interview","Chicago office","Valuation","Advanced"]},{"id":"q-1008","t":"val","l":"Advanced","s":90,"q":"Under what circumstances could a company's cost of debt exceed its cost of equity?","k":["On a true expected-return basis it essentially never happens — equity is subordinate, so its required return has to be higher. Where you observe it, it is almost always a measurement artifact:","YTM overstates the expected return on distressed debt. Cost of debt is proxied by current yield to maturity, a promised yield that assumes full repayment. A bond at 40 cents yielding 25% has a far lower probability-weighted return once you haircut for default and recovery. Cost of equity is already an expected return, so the two are not comparable.","CAPM understates cost of equity in distress. Beta is estimated on trailing data and misses the leverage and default risk in the current capital structure.","With no taxable income the interest tax shield is worthless, so the after-tax cost of debt does not step down as it normally would.","The equity-as-an-option framing is often stated backwards: distressed equity behaves like a deeply out-of-the-money call on enterprise value, and an out-of-the-money option is more volatile and riskier than the claim beneath it. That pushes the required return on equity up, not down."],"collection":"practice","topic":"Valuation","tags":["Reported in J.P. Morgan Interview","Chicago office, Superday","Valuation","Advanced"]},{"id":"q-1009","t":"val","l":"Advanced","s":90,"q":"You are given a table of a company's valuation multiples (EV/EBITDA, EV/EBIT, and P/E) from 2019 to 2020.\n\n\n\n\nWhat would you look for to determine if one of the multiples might not make sense in relation to the others?","k":["Check for internal consistency across multiples:","EV/EBITDA should be lower than EV/EBIT (since EBITDA > EBIT).","If D&A is significant, a large gap between EV/EBIT and EV/EBITDA is expected.","Compare P/E movement to EV/EBITDA—divergence may indicate changing leverage or tax rates.","Look for anomalies: if EBITDA turned negative while EBIT stayed positive, or unusual changes in capital structure affecting equity vs. enterprise value.","Check if Net Debt changed significantly, affecting the relationship between enterprise and equity multiples."],"collection":"practice","topic":"Valuation","tags":["Reported in J.P. Morgan Interview","Chicago office, Superday","Valuation","Advanced"]},{"id":"q-1010","t":"val","l":"Advanced","s":90,"q":"If I were opening a sandwich shop, how should you value it?\n\n\n\n\nFollow-up 1: What would you use as the discount rate if you are using a DCF?\n\n\n\n\nFollow-up 2: What makes a good sandwich or coffee shop, and how can it be made more competitive?","k":["Main Question: Valuation Approach","Comparable Company Analysis: Use multiples from similar food service businesses (EV/Revenue, EV/EBITDA).","DCF: Project cash flows based on foot traffic, average ticket size, operating margins, and growth assumptions.","Asset-Based: Consider real estate, equipment, and working capital.","Precedent transactions in the quick-service restaurant space.","Follow-up 1: Discount Rate","Use a high discount rate (15-25%) reflecting small business risk, limited diversification, operational risk, and lack of liquidity. Higher than typical corporate WACC due to concentrated business risk.","Follow-up 2: Competitive Advantages","Prime location with high foot traffic.","Differentiated menu or unique value proposition.","Strong brand and customer loyalty.","Operational efficiency and cost management.","Quality ingredients and consistent execution."],"collection":"practice","topic":"Valuation","tags":["Reported in J.P. Morgan Interview","Chicago office, Superday","Valuation","Advanced"]},{"id":"q-1011","t":"val","l":"Advanced","s":90,"q":"You are comparing two companies, A and B, which are operationally identical except for their size.\n\n\n\n\nCompany A: Share price of $10, 100 shares, Net Debt of $100, EBITDA of $100.\n\nCompany B: Share price of $100, 100 shares, Net Debt of $1,000, EBITDA of $1,100.\n\n\n\n\nBased on this information, which company would you prefer to invest in and why?","k":["The choice between Company A and Company B involves a trade-off between value and risk.","Analysis:","Company A: EV = ($10 × 100) + $100 = $1,100. EV/EBITDA = $1,100 / $100 = 11.0x. Debt/EBITDA = $100 / $100 = 1.0x.","Company B: EV = ($100 × 100) + $1,000 = $11,000. EV/EBITDA = $11,000 / $1,100 = 10.0x. Debt/EBITDA = $1,000 / $1,100 = 0.91x.","Conclusion:","Company B is the superior investment based on these metrics. It trades at a lower valuation multiple (10.0x vs. 11.0x), suggesting it is cheaper, and it also has lower leverage (0.91x vs. 1.0x), indicating it is less risky. Therefore, an investor would prefer Company B as it offers better value with a stronger credit profile."],"collection":"practice","topic":"Valuation","tags":["Reported in J.P. Morgan Interview","New York Office, First round","Valuation","Advanced"]},{"id":"q-1012","t":"val","l":"Advanced","s":90,"q":"Two similar companies trade at 15x and 20x EV/EBITDA, respectively.\n\n\n\n\nWhy might you argue in favor of acquiring the company with the higher multiple?","k":["Reasons to acquire the 20x company:","Superior Growth: Higher multiple reflects stronger revenue/earnings growth prospects.","Quality of Earnings: More recurring revenue, higher margins, better cash conversion.","Competitive Advantages: Stronger brand, technology, or market position justifies premium.","Synergy Potential: May offer greater cost or revenue synergies post-acquisition.","Strategic Fit: Better alignment with acquirer's long-term strategy or capabilities.","Lower Risk Profile: More diversified customer base, less cyclical, stronger balance sheet.","While the 20x target is more expensive, if it generates superior long-term value through growth and synergies, the higher multiple may be justified."],"collection":"practice","topic":"Valuation","tags":["Reported in J.P. Morgan Interview","SA 2025","Valuation","Advanced"]},{"id":"q-1013","t":"val","l":"Advanced","s":90,"q":"Answer the following questions:\n\n\n\nWhat is your favorite and least favorite valuation method?\nWhat happens to WACC if the cost of debt increases? What about the cost of equity?\nWhy would one company have a higher valuation multiple than another?\nWhy might a financial sponsor pay a higher multiple for a company than a strategic acquirer?","k":["Part 1: Favorite/Least Favorite Method","Sample response:","Favorite: DCF (fundamental, captures company-specific growth and risk).","Least Favorite: Precedent Transactions (outdated, influenced by market timing).","Part 2: WACC Changes","Higher cost of debt: WACC increases (debt is now more expensive).","Higher cost of equity: WACC increases (equity is now more expensive).","Part 3: Multiple Differences","Growth prospects, profitability, competitive position, management quality, and risk profile.","Part 4: Sponsor Paying More","Unusual scenario. Possible reasons: superior operational capabilities, access to cheaper capital, competitive auction, or market timing (hot PE market)."],"collection":"practice","topic":"Valuation","tags":["Reported in J.P. Morgan Interview","Financial Institutions group, Second round","Valuation","Advanced"]},{"id":"q-1014","t":"val","l":"Advanced","s":90,"q":"Part 1: Walk me through an IPO deck. What slides would you include?\n\n\n\n\nPart 2: Would intrinsic valuation methodologies be useful for IPO pricing?","k":["Part 1: IPO Deck","Executive summary & investment highlights.","Industry overview & market opportunity.","Company overview, business model, and competitive positioning.","Financial summary (historical & projected).","Comparable company analysis & preliminary valuation range.","Use of proceeds.","Proposed deal structure, timeline, and underwriter syndicate.","Risk factors.","Part 2: Intrinsic Valuation for IPO Pricing","A DCF can serve as a reference point, but IPO pricing is primarily driven by comparable company multiples and investor demand through the bookbuilding process. A DCF is less useful because projections for a newly public company carry more uncertainty, and the market ultimately prices IPOs on relative valuation and momentum."],"collection":"practice","topic":"Valuation","tags":["New","Reported in J.P. Morgan Interview","SA 2027, FIG group, New York Office, Superday","Valuation","Advanced"]},{"id":"q-1015","t":"val","l":"Advanced","s":90,"q":"Walk me through the main valuation methods presented on a football field chart.\n\n\n\n\nFollow-up: How would a change in the Federal Funds rate impact each of these valuation methods?","k":["Football Field Valuation Methods (typical ordering from lowest to highest):","52-Week Trading Range: Historical share price range over the past year.","Comparable Companies Analysis: Applies trading multiples from public peers to the target's financials.","DCF Analysis: Discounts projected free cash flows at WACC to arrive at intrinsic value.","Precedent Transactions: Applies multiples from prior M&A deals, which include a control premium.","LBO Analysis: Determines the maximum price a financial sponsor would pay to achieve target returns.","Impact of a Fed Funds Rate Increase:","DCF: Higher WACC lowers the present value of future cash flows, reducing valuation.","Comps: Trading multiples may compress as discount rates rise, lowering peer valuations.","Precedent Transactions: Historical deal multiples are fixed, but current applicability weakens as market conditions shift.","LBO: Higher cost of debt reduces leverage capacity and sponsor returns, lowering the price a PE firm can pay.","52-Week Range: Likely shifts downward as equities reprice in a higher-rate environment."],"collection":"practice","topic":"Valuation","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-1016","t":"val","l":"Advanced","s":90,"q":"How would you value a hypergrowth company like OpenAI?","k":["Traditional valuation methods need adaptation for hypergrowth companies:","DCF with extended projection period: Use a 10-15 year forecast to capture the transition from hypergrowth to steady state. Terminal value assumptions are critical.","Revenue multiples: EV/Revenue or EV/ARR is most appropriate since the company may be pre-profit. Compare to publicly traded hypergrowth peers.","Comparable transactions: Look at recent funding rounds and secondary market transactions for private company benchmarks.","TAM-based analysis: Estimate the total addressable market and the company's potential market share to back into a revenue target, then apply a multiple.","EBITDA-based multiples and LBO analysis are typically less useful because the company may have negative or minimal EBITDA."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Jefferies Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-1017","t":"val","l":"Advanced","s":90,"q":"When building a comparable companies analysis with financial multiples, are those multiples the target goal or the criteria used to determine if a comp is appropriate?","k":["The multiples are the output (target goal), not the selection criteria.","You select comps based on qualitative and quantitative criteria: industry, business model, size, growth profile, margins, geographic focus, and end markets. Once you identify the peer set, you calculate their trading multiples and apply them to the target's financials to derive an implied valuation range.","Selecting comps based on their multiples introduces circular logic. The multiples are the result of the analysis, not an input to peer selection."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Jefferies Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-1018","t":"val","l":"Advanced","s":90,"q":"Part 1: Let's say you had 50 comparable companies and you are trying to narrow it down to 10 comps. What would you look at? What specifically within financials?\n\n\n\n\nPart 2: Besides multiples, what else do you look at when analyzing a comps spread? How would you screen for that within CapIQ?","k":["Part 1: Narrowing from 50 to 10","Industry and sub-sector: Same products/services, end markets, and business model.","Size: Similar revenue, EBITDA, and market cap range.","Growth profile: Comparable revenue and EBITDA growth rates.","Margin profile: Similar gross, EBITDA, and operating margins.","Geographic mix: Domestic vs. international revenue exposure.","Capital structure: Similar leverage levels and capital intensity.","Eliminate outliers: Companies in distress, undergoing M&A, or with one-time items that distort metrics.","Part 2: Beyond Multiples","Revenue growth rates (historical and projected), margin trends, return on invested capital (ROIC), free cash flow conversion.","Capital structure: Debt/EBITDA, interest coverage ratios.","In CapIQ: Use screening criteria to filter by industry classification (GICS/SIC), revenue range, market cap range, EBITDA margins, and geography. Export to Excel and rank by the key financial metrics."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Valuation","Advanced"]},{"id":"q-1019","t":"val","l":"Advanced","s":90,"q":"What is beta? Why is it relevant to our work in investment banking? What is the inherent problem with beta? How should you think about beta differently based on different types of companies?","k":["Beta measures a stock's sensitivity to overall market movements. A beta of 1.0 means the stock moves in line with the market; above 1.0 indicates higher volatility, below 1.0 indicates lower volatility.","Relevance to IB:","Beta is a key input in CAPM (Cost of Equity = Rf + Beta x MRP), which feeds into WACC, which is the discount rate in a DCF. Getting beta wrong directly impacts valuation.","Inherent Problems:","Beta is backward-looking, based on historical stock returns (typically 2-5 years). Past volatility may not reflect future risk.","It is sensitive to the time period, frequency (daily vs. weekly), and benchmark index chosen.","For thinly traded or recently IPO'd companies, beta may be unreliable.","Company-Specific Considerations:","Cyclical companies (industrials, commodities): Higher beta due to earnings sensitivity to economic cycles.","Defensive companies (utilities, staples): Lower beta due to stable demand regardless of economic conditions.","High-growth tech: Higher beta reflecting longer cash flow duration and greater uncertainty.","Highly levered companies: Higher equity beta due to financial risk amplifying business risk.","In practice, we unlever the betas of comparable companies and relever at the target's capital structure to get a more appropriate estimate."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Valuation","Advanced"]},{"id":"q-1020","t":"val","l":"Advanced","s":90,"q":"A company has $10M of EBITDA, a 2x EV/EBITDA multiple, and $60M of debt, implying negative equity value. How would you value the equity?","k":["When equity value is negative on a fundamentals basis, you need to consider alternative approaches:","Option value: Equity can still trade above zero because it functions like a call option on the company's assets. Even if the company is currently insolvent, there is optionality that EBITDA could recover, reducing debt or increasing EV enough to create positive equity value.","Recovery analysis: Model different scenarios (base, upside, downside) for EBITDA recovery and debt paydown to determine the probability-weighted equity value.","Restructuring / distressed valuation: Perform a waterfall analysis on the capital structure to determine where the fulcrum security sits. If the fulcrum is above equity, the equity is likely wiped out in a restructuring.","Liquidation analysis: Estimate the proceeds from liquidating the company's assets and determine if any residual value flows to equity after satisfying all creditor claims.","In practice, the equity may still trade at a positive price in public markets due to speculative interest, short squeezes, or restructuring optionality."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Valuation","Advanced"]},{"id":"q-1021","t":"val","l":"Advanced","s":90,"q":"What is the relationship between a company's Price-to-Book (P/B) ratio and its Return on Equity (ROE)?","k":["P/B ≈ ROE × (Payout Ratio) ÷ (Cost of Equity - NI Growth Rate).","Higher ROE typically drives a higher P/B because investors pay more per book dollar when equity earns superior returns.","Terms:","P/B (Price-to-Book Ratio): Market price per share divided by book value per share; shows how much investors pay for each dollar of net assets.","ROE (Return on Equity): Net income divided by average shareholders’ equity; measures how efficiently a company generates profit from its equity base.","Payout Ratio: Dividends paid divided by net income; percentage of earnings returned to shareholders as dividends.","NI Growth Rate (g): Sustainable growth rate of net income, calculated as ROE × (1 – Payout Ratio); shows how fast earnings can grow without new equity.","Cost of Equity (k): Required return for equity investors, reflecting the risk of the company; often estimated via the Capital Asset Pricing Model (CAPM) or other methods."],"collection":"practice","topic":"Valuation","tags":["Reported in Lazard Interview","Valuation","Advanced"]},{"id":"q-1022","t":"val","l":"Advanced","s":90,"q":"Part 1: How would you value your prior employer?\n\n\n\n\nPart 2: How would you value one of its specific product lines or business segments?","k":["Part 1: Valuing Prior Employer","Use standard valuation approaches: DCF (project cash flows, determine WACC, calculate terminal value), comparable company analysis (select public peers, analyze trading multiples), and precedent transactions (review recent M&A deals in the sector).","Consider company-specific factors: business model, competitive position, growth profile, margin structure, and capital intensity.","Part 2: Valuing Product Line/Segment","Segment-level valuation requires allocating or carving out financials:","Standalone DCF: Isolate segment revenues, EBITDA, CapEx, and working capital needs. Apply segment-specific risk (adjusted WACC).","Comparable approach: Identify pure-play peers in that product category and apply relevant multiples.","Consider synergies, shared costs, and whether the segment could operate independently."],"collection":"practice","topic":"Valuation","tags":["Reported in Lazard Interview","New York Office","Valuation","Advanced"]},{"id":"q-1023","t":"val","l":"Advanced","s":90,"q":"What would the WACC be for a company with a beta of 0 and no debt?\n\n\n\n\nFollow-up: Given this company with a beta of 0 is very risky, but has a low WACC, how would you proceed with a DCF?","k":["Main Question","WACC would equal the risk-free rate.","WACC = Cost of Equity (no debt).","Cost of Equity = Risk-Free Rate + Beta * Market Risk Premium.","With Beta = 0: Cost of Equity = Risk-Free Rate.","Follow-up","Beta of 0 indicates no correlation with market returns, not low risk. The company may have significant idiosyncratic risk not captured by beta.","Approaches:","Add a company-specific risk premium to the discount rate to reflect operational risks.","Adjust cash flow projections to reflect higher uncertainty (use more conservative assumptions or scenario analysis).","Use comparable company analysis to cross-check valuation rather than relying solely on DCF."],"collection":"practice","topic":"Valuation","tags":["Reported in Lazard Interview","SF Office","Valuation","Advanced"]},{"id":"q-1024","t":"val","l":"Advanced","s":90,"q":"Company A has an EPS of $7 and a P/E of 15x. If the tax rate drops from 30% to 15%, what is the company's new share price?","k":["Answer: $127.50","Calculation:","Current Share Price = EPS * P/E = $7 * 15x = $105.","Current NI after-tax = $7 per share. Pre-tax income = $7 / (1 - 30%) = $10 per share.","New NI = $10 * (1 - 15%) = $8.50 per share (assumes P/E remains constant).","New Share Price = $8.50 * 15x = $127.50."],"collection":"practice","topic":"Valuation","tags":["Reported in Lazard Interview","SF Office","Valuation","Advanced"]},{"id":"q-1025","t":"val","l":"Advanced","s":90,"q":"NAV Modelling exercise: Choose your favorite company and frame a detailed Net Asset Value (NAV) model. Walk me through each line item in detail.","k":["Framework for a NAV model (using a REIT as an example):","Segment NOI by property type: Calculate Net Operating Income for each asset class (office, retail, multifamily, etc.) by taking property revenues less operating expenses.","Apply appropriate cap rates: Use market cap rates for each property type and geography to capitalize NOI into gross asset values.","Add development pipeline: Value land and properties under development at estimated completion value less remaining costs, discounted for time and risk.","Add other assets: Joint venture interests (mark to market or proportional NAV), cash, receivables.","Subtract liabilities: Mortgage debt (at market value), unsecured debt, preferred equity, and other obligations.","Adjustments: G&A capitalization (capitalize corporate overhead as a liability using a multiple), promote/fee income value.","Net Asset Value = Gross Assets - Total Liabilities - G&A Capitalization.","NAV per share = NAV / Diluted Shares Outstanding."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Lazard Interview","SA 2025, Houston Office, Superday","Valuation","Advanced"]},{"id":"q-1026","t":"val","l":"Advanced","s":90,"q":"Company A has EBITDA of $10M, CapEx of $5M, and an EV/EBITDA multiple of 5x. Company B has EBITDA of $10M, CapEx of $1M, and an EV/EBITDA multiple of 8x. Which company is more valuable?","k":["Company B is more valuable.","Company A: EV = 5 x $10M = $50M.","Company B: EV = 8 x $10M = $80M.","Company B trades at a higher multiple because it requires much less CapEx ($1M vs. $5M) to generate the same EBITDA, meaning it converts more EBITDA into free cash flow. Company B's FCF proxy = $10M - $1M = $9M vs. Company A's $10M - $5M = $5M. The market assigns a premium to capital-light, high-FCF-conversion businesses."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Lazard Interview","SA 2025, SF Office, First round","Valuation","Advanced"]},{"id":"q-1027","t":"val","l":"Advanced","s":90,"q":"How would you value a company with negative EBITDA or an early-stage company?","k":["For companies with negative EBITDA or early-stage companies, traditional EV/EBITDA multiples do not work. Alternatives include:","EV/Revenue: Most common for high-growth, pre-profit companies.","DCF with longer projection period: Project out until the company reaches profitability, then apply a terminal value.","Comparable transactions: Use revenue-based multiples from M&A deals in the same sector.","User/subscriber-based metrics: EV per user, EV per subscriber for platform businesses.","Venture capital method: Work backward from expected exit value and apply a target return.","Sum-of-the-parts / rNPV: For biotech or companies with discrete, identifiable assets."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Lincoln International Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-1028","t":"val","l":"Advanced","s":90,"q":"If two companies have the same revenue ($500M) and the same EBITDA ($50M), what characteristics could cause one to trade at a higher valuation multiple than the other?","k":["Factors that could cause one company to trade at a higher multiple:","Higher revenue growth rate or stronger growth outlook.","Better margin trajectory or improving profitability trends.","More recurring or subscription-based revenue (higher predictability).","Stronger competitive positioning or market leadership.","Lower capital intensity (less CapEx required to sustain growth).","Better management team or corporate governance.","Lower leverage or stronger balance sheet.","More favorable end-market dynamics or secular tailwinds.","Higher free cash flow conversion (less working capital drag).","Greater geographic or customer diversification."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Lincoln International Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-1029","t":"val","l":"Advanced","s":90,"q":"Company has $120M in perpetual unlevered free cash flow; no debt initially.\n\n\n\n\nRFR = 4%, Beta = 1, ERP = 6%.\n\n\n\n\nPart 1: What is EV?\n\n\n\n\nPart 2: Company raises $800M debt, tax rate 25%, interest 10%. What is EV now?\n\n\n\n\nPart 3: Assume CoD is 5% and the target capital structure mix is 60% equity / 40% debt. What is WACC?","k":["Part 1:","Cost of Equity = 4% + 1 × 6% = 10%.","EV = 120 ÷ 0.10 = $1.2 billion.","Part 2:","Raising $800 million debt and holding the cash leaves EV unchanged at $1.2 billion (Debt and Cash offset).","Part 3:","WACC (60% equity, 40% debt):","After‑tax Cost of Debt = 5% × (1 − 25%) = 3.75%.","WACC = 0.6 × 10% + 0.4 × 3.75% = 7.5%."],"collection":"practice","topic":"Valuation","tags":["Reported in LionTree Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1030","t":"val","l":"Advanced","s":90,"q":"What are the key value drivers in a DCF versus an LBO model?","k":["DCF drivers:","Free Cash Flow growth.","Discount rate (WACC).","Terminal value assumptions.","LBO drivers:","Entry valuation.","Leverage and cost of debt.","Cash‑flow growth and margin expansion.","Exit multiple and timing."],"collection":"practice","topic":"Valuation","tags":["Reported in LionTree Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1031","t":"val","l":"Advanced","s":90,"q":"Company H has $150 M unlevered FCF, a 2% risk-free rate, a 4%market risk premium, and a beta of 2.\n\n\n\n\nWhat is the EV if the company is all equity?","k":["Answer: $1.5 B","Cost of equity = 2% + (2 × 4%)= 10%.","With zero-growth perpetuity formula, EV = 150 / 0.10 = 1,500 M ≈ 1.5B."],"collection":"practice","topic":"Valuation","tags":["Reported in LionTree Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1032","t":"val","l":"Advanced","s":90,"q":"What are levered and unlevered beta? Why do you adjust beta in that way?","k":["Unlevered beta isolates business risk; levered beta adds financial risk from debt.","We un‑lever peers to strip out capital‑structure effects, average them, then re‑lever at target debt‑to‑equity to derive a beta consistent with the firm’s planned leverage in a CAPM cost‑of‑equity."],"collection":"practice","topic":"Valuation","tags":["Reported in LionTree Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1033","t":"val","l":"Advanced","s":90,"q":"Two companies, A and B, both trade at 10x EV/EBITDA now. Next year, A is projected to trade at 9x, B at 11x. How is the main driver of returns different between them?","k":["Company A’s return must come primarily from EBITDA growth and debt pay‑down because the multiple is contracting.","Company B benefits from multiple expansion, so valuation re‑rating—not operating growth—will drive a larger share of returns."],"collection":"practice","topic":"Valuation","tags":["Reported in LionTree Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1034","t":"val","l":"Advanced","s":90,"q":"One company trades at 10x EBITDA and is growing faster. Another trades at 6x EBITDA and is growing slower. Which one should you buy?","k":["It depends on whether the growth premium is justified. Consider:","PEG-like analysis: Compare the multiple/growth rate ratio. If Company A (10x, 20% growth) has a ratio of 0.5x while Company B (6x, 5% growth) has a ratio of 1.2x, Company A may be the better value despite the higher multiple.","Quality of growth: Is the growth organic or acquisition-driven? Recurring or one-time?","Sustainability: Can the faster grower maintain its trajectory?","FCF conversion: Higher growth does not help if it requires massive reinvestment.","Risk profile: Faster growth may come with more volatility.","In most cases, paying a premium for faster, sustainable, high-quality growth is worthwhile. But if the growth is unsustainable or the multiple is unjustifiable, the slower grower at 6x may offer better value."],"collection":"practice","topic":"Valuation","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, Second round","Valuation","Advanced"]},{"id":"q-1035","t":"val","l":"Advanced","s":90,"q":"What valuation method would you use for a coal mine that will cease operations in ten years?","k":["Build a finite‑life DCF model that forecasts yearly cash flows until shutdown and adds a salvage value, with no perpetuity.","A perpetual multiple or Gordon Growth approach would overstate value because production stops after year 10."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","First round","Valuation","Advanced"]},{"id":"q-1036","t":"val","l":"Advanced","s":90,"q":"Equity risk premium is 5%, risk-free rate is 5%, unlevered beta is 1, D/E ratio is 1x, and tax rate is 50%.\n\n\n\n\nCalculate the cost of equity.","k":["Levered β = 1 × [1 + (1 − 50%) × 1] = 1.5.","Cost of Equity = 5% + 1.5 × 5% = 12.5%."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1037","t":"val","l":"Advanced","s":90,"q":"A company has $120 in EBITDA at a 10x multiple and a 20% EBITDA margin.\n\n\n\n\nDebt/EBITDA is 5x, interest rate is 10%, P/E is 20x.\n\n\n\n\nWhat is the tax rate?","k":["50%.","EV = 1,200; Debt = 600 ⇒ Equity = 600.","NI = 600/20 = 30.","EBIT ≈ 120 (assume no D&A).","Interest = 60.","EBT = 60 ⇒ Taxes = 30 ⇒ 30/60 = 50%."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1038","t":"val","l":"Advanced","s":90,"q":"Assume 100 EBITDA at an 8x multiple, 20% margin, 10% cost of debt, 5x Debt/EBITDA, 10x P/E, and 5 in D&A.\n\n\n\n\nCalculate the implied tax rate.","k":["≈ 33%.","EV = 800; Debt = 500 ⇒ Equity = 300.","NI = 300/10 = 30.","EBIT = 95.","Interest = 50.","EBT = 45 ⇒ Taxes = 15 ⇒ 15/45 ≈ 33%."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1039","t":"val","l":"Advanced","s":90,"q":"Calculate EV given:\n\n\n\n\nLFCF yield = 10%, EBITDA = 150, D&A = 50, interest expense = 10, capex = 30,\n\n\n\n\nIncrease in A/R = 20, Decrease in A/P = 10, Increase in Inventory = 5, taxes = 25, debt = 300, cash = 75.","k":["EV ≈ 725.","EBIT = 100.","NI = 65.","LFCF = 50 (CFO [65 NI + 50 D&A - 35 NWC] - 30 Capex).","Equity Value = 50/0.10 = 500.","EV = 500 + 300 − 75 = 725."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1040","t":"val","l":"Advanced","s":90,"q":"Two companies appear very similar, yet one trades at a higher EV/EBITDA multiple.\n\n\n\n\nWhy might this be the case?\n\n\n\n\nWhat other metrics could you look at?\n\n\n\n\nWould a company investing more in Capex have a higher or lower multiple?","k":["Possible drivers of multiple divergence:","Growth, margin, or cyclicality differences","Leverage or liquidity risk","IP quality or regulatory moats","Geographic or customer concentration","Other metrics: EV/Sales, EV/EBIT, P/E, FCF yield, ROIC, leverage ratios.","Heavy ongoing Capex depresses FCF, usually leading to a lower EV/EBITDA multiple."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1041","t":"val","l":"Advanced","s":90,"q":"If net interest coverage is 5x and gross debt ratio is 5x, what is the interest rate on the debt?","k":["≈ 4%.","Interest = EBITDA/5.","Debt = 5 × EBITDA.","Interest rate = (EBITDA/5)/(5 × EBITDA) = 1/25 ≈ 4%."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1042","t":"val","l":"Advanced","s":90,"q":"How would you value an avocado tree?","k":["You can use all the usual valuation approaches—analyzing precedent transactions; running a DCF with alternative model assumptions as benchmarks; assessing liquidation value based on land; and performing comparables analysis.","Comparable Analysis: Look at what publicly-traded avocado or citrus farms are valued at on a per-acre or per-tree basis.","Precedent Transactions: Analyze recent sales of similar trees or orchards to find a comparable transaction value.","Discounted Cash Flow (DCF): Project the cash flows from future avocado harvests, then discount them back to their present value.","Liquidation Value: As a floor, calculate the value of the land plus the salvage value of the tree itself (e.g., as timber)."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","Valuation","Advanced"]},{"id":"q-1043","t":"val","l":"Advanced","s":90,"q":"A company provides the following financial data:\n\n\n\nRevenue: $2,000\nGross Margin: 50%\nOperating Expenses (including D&A): $500\nTotal Debt: $1,000\nInterest Rate on Debt: 10%\nEV/EBITDA = 7.5x\nTax Rate: 25%\nShares Outstanding: 100\nP/E Multiple: 20.0x\n\n\n\nGiven this information, what is the company's share price?","k":["Answer: $60 per share","Calculation:","Gross Profit = $2,000 × 50% = $1,000.","EBIT = $1,000 - $500 = $500.","Interest Expense = $1,000 × 10% = $100.","EBT = $500 - $100 = $400.","Tax = $400 × 25% = $100.","Net Income = $400 - $100 = $300.","EPS = $300 / 100 shares = $3.","Share Price = $3 × 20.0x P/E = $60.","Note: The EV/EBITDA multiple of 7.5x is not needed for this calculation."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","New York Office, First round","Valuation","Advanced"]},{"id":"q-1044","t":"val","l":"Advanced","s":90,"q":"You are advising a U.S. firm that is considering an acquisition of a Chinese oil field services firm.\n\n\n\n\nHow would you value the target, and how would you determine if it's a good deal?","k":["Use standard valuation methods with cross-border adjustments:","DCF: Forecast cash flows in local currency, apply appropriate discount rate reflecting country risk premium, convert to USD.","Comparable Companies: Use global and regional oil field services peers, adjust for market differences.","Precedent Transactions: Review similar cross-border deals in the sector.","Key considerations for determining if it's a good deal:","Regulatory approval risk (CFIUS, Chinese authorities).","Currency risk and hedging strategies.","Political and operational risks in China.","Synergies: Access to Chinese market, technology transfer, cost savings.","Strategic fit: Does it enhance competitive position?","Integration challenges and cultural differences."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","Houston office, Superday","Valuation","Advanced"]},{"id":"q-1045","t":"val","l":"Advanced","s":90,"q":"Why would a company with higher leverage have a higher beta than an otherwise identical company with lower leverage?","k":["Higher leverage increases financial risk, which increases equity beta.","Explanation:","Debt obligations are fixed, so equity holders absorb all volatility in earnings.","With more debt, small changes in operating income create larger percentage swings in net income available to equity.","This amplifies equity volatility and systematic risk, raising levered beta.","Formula: Levered Beta = Unlevered Beta * [1 + (1 - Tax Rate) * (Debt / Equity)]","As Debt/Equity increases, levered beta rises, reflecting higher equity risk."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","Valuation","Advanced"]},{"id":"q-1046","t":"val","l":"Advanced","s":90,"q":"How would you calculate the Terminal Value for a forestry company?","k":["For a forestry company, Terminal Value should reflect the long-term, sustainable harvest and regrowth cycles.","Approaches:","Perpetuity Growth Method: Use a low, stable growth rate (0-2%) reflecting sustainable timber yields and inflation.","Exit Multiple: Apply EV/EBITDA multiple from comparable forestry companies at maturity.","Asset-Based Approach: Value standing timber inventory and land at terminal year using per-acre or per-ton metrics.","Forestry is capital-intensive with long growth cycles, so Terminal Value often represents significant portion of DCF. Use conservative assumptions given commodity price volatility and biological constraints."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","Valuation","Advanced"]},{"id":"q-1047","t":"val","l":"Advanced","s":90,"q":"How would you value Tesla, and how would you select an appropriate set of comparable companies?\n\n\n\n\nFollow-up: In your opinion, what is the best method to value Tesla?","k":["Valuation Approaches:","DCF: Project vehicle deliveries, ASPs, margins, energy business, services. High uncertainty in growth assumptions.","Comparable Companies: Mix of auto OEMs (Ford, GM, Toyota) for vehicle business and tech companies (growth comparables) for software/AI capabilities.","Sum-of-the-Parts: Value automotive, energy storage, solar, and potential autonomous driving businesses separately.","Comparable Selection Challenge:","Traditional auto companies trade at lower multiples (mature, capital-intensive).","Tech companies trade at higher multiples but lack physical production complexity.","Consider EV-only manufacturers (Rivian, Lucid) for closer fit.","Best Method:","DCF is most appropriate given Tesla's unique profile, but requires sensitivity analysis on key assumptions (delivery growth, margin expansion, autonomous driving monetization). Triangulate with comparables for sanity check."],"collection":"practice","topic":"Valuation","tags":["Reported in Moelis & Co. Interview","First round","Valuation","Advanced"]},{"id":"q-1048","t":"val","l":"Advanced","s":90,"q":"Why would a seller prefer precedent transactions over public comparables, and why would a buyer prefer public comparables over precedent transactions? What could be their rationale?","k":["Seller Prefers Precedent Transactions:","Precedent transactions include a control premium (20-40%), resulting in higher implied valuations.","Rich recent deal multiples set a high negotiation anchor.","Buyer Prefers Public Comparables:","Trading multiples lack a control premium, yielding lower valuations.","Buyers can argue current market conditions are the appropriate benchmark, not historical deal premiums.","If prior deals were done in frothy markets, buyers can argue those multiples are inflated.","The final price typically falls between the two ranges as the parties negotiate."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Moelis & Co. Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-1049","t":"val","l":"Advanced","s":90,"q":"A company has a P/E of 20x, an EV/EBITDA of 10x, Interest Expense of $20 million, a 5% interest rate, Depreciation of $20 million, and a Market Cap of $200 million. What is the company's tax rate?","k":["Answer: 50%","Calculation:","P/E = 20x, Market Cap = $200M, so Net Income = $200M / 20 = $10M","Interest Expense = $20M at 5%, so Debt = $20M / 5% = $400M","EV = Market Cap + Debt - Cash. Assume Cash = 0: EV = $200M + $400M = $600M","EV/EBITDA = 10x, so EBITDA = $600M / 10 = $60M","EBIT = EBITDA - D&A = $60M - $20M = $40M","Pre-Tax Income = EBIT - Interest = $40M - $20M = $20M","Tax Rate = 1 - (NI / Pre-Tax Income) = 1 - ($10M / $20M) = 50%"],"collection":"practice","topic":"Valuation","tags":["New","Reported in Moelis & Co. Interview","SA 2026, Superday","Valuation","Advanced"]},{"id":"q-1050","t":"val","l":"Advanced","s":90,"q":"Why would an acquiror pay 30x revenue for a target with no profit? How do you value such a company?","k":["Possibly for strategic value, rapid user growth, or a unique product that can become profitable at scale.","You might use revenue multiples, user metrics, or a long-term DCF projection that models eventual profitability. The high multiple reflects growth expectations and potential network effects."],"collection":"practice","topic":"Valuation","tags":["Reported in Morgan Stanley Interview","Valuation","Advanced"]},{"id":"q-1051","t":"val","l":"Advanced","s":90,"q":"Walk me through a DCF, then walk me through an LBO.\n\n\n\n\nFollow-up 1: If we change the discount rate, what happens to both?\n\n\n\n\nFollow-up 2: If we increase taxes, what happens to both?\n\n\n\n\nFollow-up 3: If we do a dividend recap, how does that affect the LBO?\n\n\n\n\nFollow-up 4: Compare high yield debt vs. bank debt in an LBO.","k":["DCF summary:","Project unlevered FCF for 5–10 years.","Calculate terminal value (Gordon Growth or exit multiple).","Discount both at WACC.","Sum to enterprise value.","LBO summary:","Determine purchase price and sources/uses.","Project operations and the debt schedule.","Apply exit multiple to EBITDA for exit EV.","Subtract remaining net debt for exit equity.","Compute IRR and MOIC.","Follow‑ups:","Higher discount rate lowers DCF value; in an LBO it lowers the price you can pay to hit the target IRR.","Higher taxes reduce FCF, decreasing DCF value and slowing debt pay‑down, which hurts LBO returns.","A dividend recap raises new debt to pay a dividend, increasing leverage and boosting equity IRR if the company can service the debt.","High‑yield: unsecured, higher coupons, bullet maturity, loose covenants. Bank debt: secured, lower rates, amortizing, maintenance covenants."],"collection":"practice","topic":"Valuation","tags":["Reported in Morgan Stanley Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1052","t":"val","l":"Advanced","s":90,"q":"The cybersecurity company has now received an offer for $35 per share from a financial sponsor. The offer is on the lower end of the public comparable multiples. Should the company take it?","k":["The company should likely reject the $35 offer. Key considerations:","Below current price: The stock is at $40, so $35 represents a 12.5% discount to the current market price. Take-privates typically require a 20-40% premium.","Trough valuation: The stock is already depressed from an earnings miss. Selling at the low end of comps means selling at a cyclical or temporary trough.","Board fiduciary duty: The board has a duty to maximize shareholder value. Accepting a below-market offer could expose the board to shareholder lawsuits.","Negotiate or run a process: Counter at a higher price, or invite other buyers to create competitive tension. A broader auction could yield a significantly higher offer.","Standalone alternative: If the earnings miss is temporary, the company may generate more long-term value by staying independent and executing a turnaround."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Morgan Stanley Interview","SA 2025, Menlo Park Office, First round","Valuation","Advanced"]},{"id":"q-1053","t":"val","l":"Advanced","s":90,"q":"A cybersecurity company missed earnings and its stock dropped 35% to $40. The company wants to sell, and Morgan Stanley has found five potential buyers, including both strategics and sponsors. How would you value this company? How would you determine whether the stock drop is temporary or permanent?","k":["Valuation Approach:","Trading comps: Use cybersecurity peer multiples (EV/Revenue, EV/ARR for SaaS) applied to both LTM and NTM metrics. Consider whether the miss reflects a one-time issue or a trend.","Precedent transactions: Look at recent cybersecurity M&A deals for relevant multiples.","DCF: Model two scenarios: (1) the miss is temporary and growth resumes, (2) the miss signals a permanent slowdown. Weight the scenarios.","LBO: Determine what a sponsor could pay given the company's cash flow profile and leverage capacity.","Temporary vs. Permanent Stock Drop:","Analyze the cause of the miss: Was it a one-time event (deal slippage, large contract timing) or structural (market share loss, competitive displacement, product obsolescence)?","Customer churn and renewal rates: If churn is spiking, the issue is likely structural.","Pipeline and bookings: A healthy pipeline suggests the miss is timing-related.","Management credibility: Has the team missed before? Is there a pattern?","Industry context: Are peers also slowing, or is this company-specific?"],"collection":"practice","topic":"Valuation","tags":["New","Reported in Morgan Stanley Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-1054","t":"val","l":"Advanced","s":90,"q":"Using the cybersecurity company scenario above (stock dropped 35% to $40 after missing earnings), apply each of the main valuation methods specifically to this case. How would each methodology need to be adjusted given the circumstances?","k":["Comparable Companies:","Use EV/NTM Revenue or EV/ARR multiples from cybersecurity peers. Adjust for the company's now-lower growth profile versus peers. If the miss was idiosyncratic, the company should trade at a discount to peers.","Precedent Transactions:","Look at recent cybersecurity M&A deals. Adjust for the fact that acquirers may demand a discount given the earnings miss. Consider whether deals were done at revenue or EBITDA multiples.","DCF:","Run multiple scenarios with different recovery assumptions. Use a higher discount rate to reflect increased uncertainty. The terminal value assumptions are critical: does the company return to normalized growth or permanently operate at a lower trajectory?","LBO:","Sponsors may see an opportunity to buy at a depressed valuation if they believe the miss is temporary. However, they will underwrite conservative cash flow projections and may require a lower entry multiple to protect downside. Leverage capacity may be limited if lenders are cautious post-miss."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Morgan Stanley Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-1055","t":"val","l":"Advanced","s":90,"q":"What are Net Operating Losses (NOLs)?\n\n\n\n\nAssume you are valuing a shell company whose only asset is $1 million in NOLs. How much would you be willing to pay for this company?","k":["NOLs Definition","Net Operating Losses are accumulated tax losses that can be carried forward to offset future taxable income, reducing future tax liabilities.","Valuation","Maximum value = $1M NOL * Tax Rate. At a 25% tax rate, the NOL saves $250k in future taxes.","However, practical value is lower due to:","Limitations on usage (Section 382 limits NOL usage after ownership changes).","Time value of money (future tax savings must be discounted).","Uncertainty about generating sufficient taxable income to utilize NOLs.","Expiration risk (though recent law changes reduced this risk).","Realistic valuation: 15-25% of face value, or $150k-$250k, depending on ability to utilize and discount rate applied."],"collection":"practice","topic":"Valuation","tags":["Reported in Perella Weinberg Interview","SF Office","Valuation","Advanced"]},{"id":"q-1056","t":"val","l":"Advanced","s":90,"q":"What types of companies might have a negative beta?\n\n\n\n\nFollow-up: If a company's beta is -1, is it possible to have a negative WACC? What would be the implication for a DCF valuation?","k":["Part 1: Negative Beta Companies","Companies with negative beta include:","Gold mining companies (flight to safety during downturns).","Discount retailers (benefit from economic weakness).","Certain utilities or defensive consumer staples.","Treasury securities and gold itself.","Part 2: Negative WACC","Yes, negative WACC is theoretically possible if beta is sufficiently negative.","Using CAPM: Cost of Equity = Risk-Free Rate + Beta × (Market Return - Risk-Free Rate). If beta = -1 and equity risk premium is large enough, cost of equity could be negative.","DCF implication: A negative discount rate would make the valuation mathematically undefined or infinite, suggesting the model breaks down for extreme negative beta scenarios."],"collection":"practice","topic":"Valuation","tags":["Reported in Perella Weinberg Interview","New York Office, Second round","Valuation","Advanced"]},{"id":"q-1057","t":"val","l":"Advanced","s":90,"q":"A company has a P/E of 30x, revenue of $1,500, shares outstanding of 900, gross margin of 60%, EV/EBITDA of 12x, debt of $2,000, cost of debt of 5%, operating expenses of $400, and a tax rate of 25%. Solve for the share price. Assume D&A is 0.","k":["Answer: $10.00 per share","Gross Profit = Revenue x Gross Margin = $1,500 x 60% = $900","EBITDA = Gross Profit - Operating Expenses = $900 - $400 = $500","Interest Expense = Debt x Cost of Debt = $2,000 x 5% = $100","With D&A = 0, EBIT = EBITDA = $500","Pre-Tax Income = EBIT - Interest = $500 - $100 = $400","NI = $400 x (1 - 25%) = $300","EPS = NI / Shares = $300 / 900 = $0.33","Share Price = EPS x P/E = $0.33 x 30 = $10.00"],"collection":"practice","topic":"Valuation","tags":["New","Reported in Perella Weinberg Interview","SA 2026, First round","Valuation","Advanced"]},{"id":"q-1058","t":"val","l":"Advanced","s":90,"q":"What is the theoretical upper limit of a company's WACC, and what does this imply about its capital structure?","k":["The theoretical upper limit of WACC is the company's cost of equity (unlevered).","This occurs when the company has zero debt (100% equity financing).","Implication:","As debt increases, WACC initially decreases due to tax shield benefits (interest is tax-deductible) and lower cost of debt versus equity.","However, excessive leverage increases financial risk, raising both cost of debt and cost of equity.","Optimal capital structure minimizes WACC, maximizing firm value."],"collection":"practice","topic":"Valuation","tags":["Reported in PJT Partners Interview","Second round","Valuation","Advanced"]},{"id":"q-1059","t":"val","l":"Advanced","s":90,"q":"A company has the following trading multiples: LTM EV/Revenue of 5x, LTM EV/EBITDA of 30x, NTM EV/Revenue of 4x, and NTM EV/EBITDA of 40x. What is the implied revenue growth? What is the implied EBITDA margin?","k":["Implied Revenue Growth:","EV is constant (same company). LTM EV/Revenue = 5x, NTM EV/Revenue = 4x.","If EV = 5 x LTM Revenue = 4 x NTM Revenue, then NTM Revenue / LTM Revenue = 5/4 = 1.25.","Implied revenue growth = 25%.","Implied EBITDA Margin:","LTM: EV/EBITDA = 30x and EV/Revenue = 5x. EBITDA Margin = EBITDA/Revenue = (EV/Revenue) / (EV/EBITDA) = 5/30 = 16.7%.","NTM: EV/EBITDA = 40x and EV/Revenue = 4x. EBITDA Margin = 4x / 40x = 10.0%.","NTM EBITDA margin is lower than LTM despite revenue growth, which implies EBITDA is declining (NTM EBITDA < LTM EBITDA). LTM EBITDA = EV / 30, NTM EBITDA = EV / 40. NTM EBITDA = 30 / 40 x LTM EBITDA = 75% of LTM. EBITDA is expected to decline ~25% despite 25% revenue growth, indicating heavy margin compression (likely due to investment spending)."],"collection":"practice","topic":"Valuation","tags":["New","Reported in RBC Interview","SA 2025, SF Office, First round","Valuation","Advanced"]},{"id":"q-1060","t":"val","l":"Advanced","s":90,"q":"What's the problem with EBITDA? What's the problem with EBIT? What's another metric that helps solve both?","k":["EBITDA: Ignores capex (no reflection of ongoing maintenance or growth investments).","EBIT: Includes depreciation (a non-cash item) but might still not reflect actual cash outflows for capex.","EBITDA – Capex: Helps account for ongoing reinvestment needs, offering a closer proxy to true cash flow."],"collection":"practice","topic":"Valuation","tags":["Reported in Rothschild Interview","Valuation","Advanced"]},{"id":"q-1061","t":"val","l":"Advanced","s":90,"q":"Where does the cost of preferred stock range vs. Cost of Equity and Cost of Debt?","k":["Between them.","Preferred dividends are contractually senior to common equity but junior to debt, so investors demand a return higher than debt yet lower than equity."],"collection":"practice","topic":"Valuation","tags":["Reported in Rothschild Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1062","t":"val","l":"Advanced","s":90,"q":"What is the difference between a levered DCF and an LBO?","k":["Both value equity but use different mechanics and solve for different things.","Levered DCF projects Levered Free Cash Flow and discounts it at the Cost of Equity to tell you what the equity is worth today.","An LBO projects the same cash flows but solves for the IRR a sponsor earns given a purchase price, leverage and exit multiple; it doesn’t discount cash flows."],"collection":"practice","topic":"Valuation","tags":["Reported in Rothschild Interview","SA 2026","Valuation","Advanced"]},{"id":"q-1063","t":"val","l":"Advanced","s":90,"q":"Rank the valuation methodologies on a football field and get creative with it.","k":["A football field chart displays valuation ranges from each methodology as horizontal bars. Typical ranking from lowest to highest implied valuation:","LBO Analysis — Typically the floor. Shows the maximum price a PE buyer can pay and still hit a target IRR (usually 20%+), constrained by leverage capacity and required equity returns.","52-Week Trading Range — Backward-looking, reflects where the stock has traded. Sentiment-driven, not fundamentally anchored.","Comparable Companies (Trading Comps) — Reflects the market's current view of similar businesses on an uncontrolled, minority basis. No control premium.","DCF — Widest range depending on assumptions (WACC, terminal growth rate, margin trajectory). Can produce both the lowest and highest values on the field.","Precedent Transactions — Usually the highest because transaction multiples embed a control premium (typically 20-40% above trading levels).","Getting Creative","Sum-of-the-Parts (SOTP): Value each business segment separately using segment-specific comps or DCFs. Useful for diversified companies where a blended multiple masks the value of high-growth divisions.","Dividend Discount Model (DDM): Relevant for mature, dividend-paying businesses (banks, utilities, REITs).","Asset-Based Valuation (NAV): Liquidation or replacement cost — relevant for asset-heavy businesses (real estate, natural resources).","Premiums Paid Analysis: Look at premiums in comparable M&A deals to triangulate a takeover price.","The football field is a triangulation tool — no single methodology gives the \"right\" answer. Where the ranges cluster gives confidence in the valuation zone."],"collection":"practice","topic":"Valuation","tags":["New","Reported in Rothschild Interview","SA 2027, Global Advisory group, New York Office, Superday","Valuation","Advanced"]},{"id":"q-1064","t":"val","l":"Advanced","s":90,"q":"A target company has the following characteristics:\n\n\n\nEV/EBITDA Multiple: 10x\nEBITDA: $200 million\nTotal Debt: $900 million\nCash: $100 million\n\n\n\nAn acquirer purchases the company at a 25% premium to its standalone equity value.\n\n\n\n\nAnswer the following:\n\nWhat is the total equity purchase price?\nWhat is the enterprise value of the transaction?","k":["Part 1: Total Equity Purchase Price","Answer: $1,500M","Standalone EV = 10x * $200M = $2,000M","Standalone Equity Value = $2,000M - $900M + $100M = $1,200M","Purchase Price = $1,200M * 1.25 = $1,500M","Part 2: Enterprise Value of Transaction","Answer: $2,300M","Transaction EV = Equity Purchase Price + Debt - Cash","Transaction EV = $1,500M + $900M - $100M = $2,300M"],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1065","t":"val","l":"Advanced","s":90,"q":"How would you value a celebrity?","k":["Apply standard valuation approaches adapted to the context:","DCF: Project future cash flows from endorsements, appearances, media deals, and royalties. Discount at appropriate rate reflecting career longevity and stability risks.","Comparable Approach: Analyze compensation for similar celebrities in same industry (sports, entertainment, etc.) with similar audience reach.","Precedent Transactions: Review deals for similar celebrity partnerships or acquisitions of celebrity brands/likeness rights.","Key considerations:","Brand strength and audience demographics.","Career stage and longevity.","Diversification of income streams.","Reputational risk and controversy exposure."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1066","t":"val","l":"Advanced","s":90,"q":"If a company could sell for 10x EBITDA in a private sale or IPO at a 12x EBITDA multiple, how would you determine which is the better option?","k":["Key considerations beyond valuation multiple:","Timing & Certainty: Private sale offers faster execution and deal certainty; IPO has market risk and longer timeline","Transaction Costs: IPO involves underwriting fees (5-7%), legal costs, and ongoing compliance expenses","Liquidity: IPO may have lock-up periods; private sale provides immediate full liquidity","Market Conditions: IPO valuation depends on market receptivity and timing risk","Strategic Value: Buyer in private sale may pay premium for synergies beyond stated multiple","Future Optionality: IPO maintains independence and future strategic flexibility","After adjusting for costs and risks, compare net proceeds and execution probability."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1067","t":"val","l":"Advanced","s":90,"q":"Company A has a 1-year forward EV/Revenue multiple of 5x and a 2-year forward multiple of 3x.\n\n\n\n\nCompany B has a 1-year forward multiple of 5x and a 2-year forward multiple of 4x.\n\n\n\n\nAssuming all else is equal, which company represents a better investment and why?","k":["Company A represents the better investment.","The decline in forward multiples indicates expected revenue growth. Company A's multiple compresses from 5x to 3x, implying 67% revenue growth over the period (5x / 3x = 1.67x growth).","Company B's multiple compresses from 5x to 4x, implying only 25% revenue growth (5x / 4x = 1.25x growth).","Assuming the same EV in both periods, Company A demonstrates significantly stronger revenue growth prospects, making it the more attractive investment."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1068","t":"val","l":"Advanced","s":90,"q":"Calculate the implied tax rate for a company with the following metrics:\n\n\n\nP/E Multiple: 20x\nEV/EBITDA Multiple: 10x\nMarket Cap: $200\nInterest Expense: $20\nPre-tax Cost of Debt: 5%\nD&A: $20\nThe company has no cash on its balance sheet.","k":["Answer: 50%","Calculation:","NI = Market Cap / P/E = $200 / 20x = $10","Debt = Interest Expense / Cost of Debt = $20 / 5% = $400","EV = Market Cap + Debt = $200 + $400 = $600 (no cash, preferred, NCI)","EBITDA = EV / (EV/EBITDA) = $600 / 10x = $60","EBIT = EBITDA - D&A = $60 - $20 = $40","Pre-tax Income (EBT) = EBIT - Interest = $40 - $20 = $20","Tax = EBT - NI = $20 - $10 = $10","Tax Rate = Tax / EBT = $10 / $20 = 50%"],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1069","t":"val","l":"Advanced","s":90,"q":"Given the following forward multiples for a company:\n\n\n\n1Y Forward EV/EBITDA = 12x\n2Y Forward EV/EBITDA = 10x\n1Y Forward P/E = 18x\n2Y Forward P/E = 20x\n\n\n\nPart 1: What is implied by the change in each multiple from Year 1 to Year 2?\n\n\n\n\nPart 2: What is the likely cause for the change in the denominators (i.e., EBITDA and Earnings) between the two periods?","k":["Part 1:","EV/EBITDA compression (12x to 10x) implies EBITDA growth outpacing EV growth, suggesting strong operational improvement","P/E expansion (18x to 20x) implies earnings growth lagging equity value growth, or market assigning higher valuation to future earnings","Part 2:","The divergence suggests the company is experiencing EBITDA growth but margin compression or increased expenses below the EBITDA line.","Likely causes:","Increased D&A from capital investments (reduces earnings relative to EBITDA)","Rising interest expense from new debt (widens gap between EBITDA and earnings)","Higher tax rate or one-time charges impacting net income disproportionately","The company is growing EBITDA faster than net income, causing P/E to rise while EV/EBITDA falls."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1070","t":"val","l":"Advanced","s":90,"q":"Consider two identical companies, except Company A is financed with a mix of debt and equity, while Company B is 100% equity-financed.\n\n\n\n\nAnswer the following:\n\nWhich company has a higher P/E multiple?\nIf both companies' operations outperform expectations, which will provide a greater return to equity holders?\nWhich company has a higher WACC?","k":["Part 1: P/E Multiple","Company B (100% equity) has the higher P/E.","Leverage increases financial risk for equity holders, leading to a higher cost of equity.","Investors demand a higher return for this risk and will pay less per dollar of earnings, compressing the P/E multiple.","Part 2: Returns to Equity","Company A (with debt) provides greater returns.","Leverage magnifies equity returns (both positive and negative).","Fixed debt costs mean incremental operating profit flows entirely to equity holders.","Part 3: WACC","Company B (100% equity) has a higher WACC.","Debt is a cheaper source of capital than equity and its interest is tax-deductible.","Company A's capital structure includes cheaper debt, lowering its overall WACC."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1071","t":"val","l":"Advanced","s":90,"q":"Company A is financed with debt, while identical Company B has no debt.\n\n\n\n\nAnswer the following:\n\nHow would you expect their P/E multiples to differ?\nIf both companies' revenues increase by 30%, how might their respective multiples react?\nWhich company has a higher cost of capital?","k":["Part 1: P/E Multiples","Company B (unlevered) has a higher P/E multiple.","Leverage adds risk, causing investors to demand a higher return on equity.","A higher required return results in a lower P/E multiple.","Part 2: Multiple Reaction to Growth","Company A's P/E could compress or expand.","Mechanically, NI grows faster for levered companies (fixed interest), which could lower the P/E ratio.","However, strong growth also leads to de-leveraging and de-risking, which could cause the market to award a higher multiple.","Part 3: Cost of Capital","Company B (unlevered) has a higher cost of capital.","Its capital structure is 100% equity, which is more expensive than debt.","Company A benefits from cheaper, tax-advantaged debt in its WACC."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1072","t":"val","l":"Advanced","s":90,"q":"If you had a few minutes on a plane with a CEO, what key questions would you ask to quickly form a high-level valuation of their company?","k":["Essential questions to ask:","What is your current annual revenue and EBITDA margin?","What is your revenue growth rate over the past 2-3 years?","What is your net debt position (or cash balance)?","Who are your closest public comparables?","What are your key value drivers and competitive advantages?","What is your capital intensity (annual capex as % of revenue)?","With these answers, you can quickly apply a trading comp multiple to EBITDA and triangulate an approximate Enterprise Value and Equity Value."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1073","t":"val","l":"Advanced","s":90,"q":"A company has an EPS of $7 and a P/E multiple of 15x. The corporate tax rate then drops from 30% to 15%.\n\n\n\n\nAssuming the P/E multiple remains constant, what is the new share price?","k":["Answer: $127.50","Calculation:","Current Share Price = EPS * P/E = $7 * 15x = $105.","Current Pre-Tax Income = $7 / (1 - 30%) = $10.","New Net Income = $10 * (1 - 15%) = $8.50.","New Share Price = $8.50 * 15x = $127.50.","Note: The lower tax rate increases NI and EPS, which flows through to a higher share price even with the same multiple."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1074","t":"val","l":"Advanced","s":90,"q":"A bond has the following characteristics:\n\n\n\nFace Value: $1,000\nAnnual Coupon Rate: 10%\nPurchase Price: $500\nYears to Maturity: 3\n\n\n\nWhat is the bond's Yield to Maturity (YTM)? Use the approximation formula.","k":["Answer: ~35.6%","Calculation (using approximation formula):","Annual Coupon = $1,000 * 10% = $100.","YTM = [C + ((F - P) / n)] / [(F + P) / 2]","YTM = [$100 + (($1,000 - $500) / 3)] / [($1,000 + $500) / 2]","YTM = [$100 + $166.67] / $750","YTM = $266.67 / $750 = ~35.6%","The approximate Yield to Maturity using the standard approximation formula is 35.6%."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1075","t":"val","l":"Advanced","s":90,"q":"Two companies have the same EV/EBITDA multiple, but one is significantly more leveraged. How would you expect their P/E ratios to compare?","k":["The more leveraged company will have a lower P/E ratio.","Reasoning:","Same EV/EBITDA implies similar operating value before capital structure effects.","Higher Leverage = Higher Risk: The company with more debt has a riskier equity stub. Investors demand a higher return for this risk.","Higher Risk = Lower Multiple: A higher required return on equity (cost of equity) translates directly to a lower P/E multiple investors are willing to pay.","Conclusion: The risk effect of leverage outweighs the mechanical impact on Net Income, leading to a lower P/E for the more leveraged company."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Valuation","Advanced"]},{"id":"q-1076","t":"val","l":"Advanced","s":90,"q":"How does Capital Expenditure (CapEx) affect the following valuation multiples: EV/EBIT, EV/EBITDA, and P/E?","k":["EV/EBITDA: No direct impact, as EBITDA excludes D&A (which results from past CapEx).","EV/EBIT: Higher CapEx leads to higher D&A, which lowers EBIT, increasing the EV/EBIT multiple.","P/E: Higher CapEx leads to higher D&A, which lowers pre-tax income and NI, increasing the P/E multiple (assuming EV/equity value held constant).","Note: While CapEx itself doesn't appear in these metrics directly, it drives depreciation which impacts EBIT and NI."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Superday","Valuation","Advanced"]},{"id":"q-1077","t":"val","l":"Advanced","s":90,"q":"Beyond the four main valuation methodologies (Comps, Precedents, DCF, LBO), what is a fifth methodology and how does it work?","k":["Sum-of-the-Parts (SOTP) Valuation","SOTP values a company by separately valuing each business segment or division, then summing them to derive total Enterprise Value.","Process:","Segment the company into distinct business units.","Apply appropriate valuation methodology to each segment (DCF, Comps, etc.).","Sum segment values to calculate total Enterprise Value.","Subtract Net Debt to arrive at Equity Value.","SOTP is useful for conglomerates or companies with diverse operations where a single multiple doesn't capture the full value."],"collection":"practice","topic":"Valuation","tags":["Reported in Unspecified Interview","Superday","Valuation","Advanced"]},{"id":"q-1078","t":"val","l":"Basic","s":90,"q":"What is the greatest driver of value in a DCF?","k":["The terminal value is typically the greatest driver.","Terminal value usually represents 50-80% of total enterprise value in a DCF. It captures the value of all cash flows beyond the explicit forecast period in perpetuity.","Within terminal value, the perpetuity growth rate and terminal multiple assumptions have outsized impact. Small changes in these inputs dramatically affect valuation.","Other key drivers include discount rate (WACC) and near-term cash flow growth, but terminal value sensitivity dominates due to its magnitude and long time horizon."],"collection":"practice","topic":"DCF","tags":["Reported in Bank of America Interview","GIG, First round","DCF","Basic"]},{"id":"q-1079","t":"val","l":"Basic","s":90,"q":"What is the beta of the NASDAQ?","k":["The NASDAQ does not have a single \"beta\" in the traditional sense, since beta measures a stock's sensitivity relative to a market benchmark.","If measured against the S&P 500, the NASDAQ Composite historically has a beta greater than 1.0 (typically around 1.1-1.3) because it is heavily weighted toward technology and growth stocks, which are more volatile than the broader market. If you measured the NASDAQ against itself, its beta would be exactly 1.0 by definition.","The key insight the interviewer is testing: beta depends on what benchmark you measure against. The S&P 500 is the standard benchmark for beta in CAPM, not the NASDAQ."],"collection":"practice","topic":"DCF","tags":["New","Reported in Bank of America Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1080","t":"val","l":"Basic","s":90,"q":"What happens to a valuation when the cost of debt goes up? How does it affect the buyer?","k":["When the cost of debt rises, WACC increases (the Kd x (1-t) component rises), which lowers the present value of future cash flows in a DCF, reducing the implied enterprise value.","Impact on the buyer:","Higher financing costs reduce the amount a buyer can pay while maintaining acceptable returns.","In an LBO, higher interest expense reduces free cash flow available for debt paydown, lowering sponsor returns at a given price.","For strategic buyers using debt, higher interest costs make the deal more dilutive.","Overall, higher cost of debt compresses deal activity and purchase price multiples."],"collection":"practice","topic":"DCF","tags":["New","Reported in Barclays Interview","SA 2025","DCF","Basic"]},{"id":"q-1081","t":"val","l":"Basic","s":90,"q":"Do you use book value or market value when calculating WACC?","k":["Market value. WACC should reflect the current cost of capital based on how the market values the company's debt and equity today.","Equity weighting: Use market capitalization (share price x diluted shares), not book value of equity.","Debt weighting: Ideally use market value of debt, though book value is often used as a proxy when debt is not publicly traded or trades close to par.","Rationale: Book values are historical and do not reflect current investor expectations, risk perceptions, or the actual cost of raising new capital. Market values capture what investors require today."],"collection":"practice","topic":"DCF","tags":["New","Reported in Barclays Interview","SF Office, Superday","DCF","Basic"]},{"id":"q-1082","t":"val","l":"Basic","s":90,"q":"Explain the concept of the Time Value of Money to me like I'm a child.","k":["Imagine someone offers you $10 today or $10 a year from now. You should always take the $10 today because you can put it in a piggy bank that earns interest, and by next year you will have more than $10.","That is the Time Value of Money: a dollar today is worth more than a dollar in the future because you can invest it and earn a return. This is why in finance we discount future cash flows back to the present to figure out what they are worth today."],"collection":"practice","topic":"DCF","tags":["New","Reported in BNP Paribas Interview","SA 2026, New York Office, Superday","DCF","Basic"]},{"id":"q-1083","t":"val","l":"Basic","s":90,"q":"Explain the concept of WACC as if you were talking to a 6-year-old.","k":["Imagine you want to buy a lemonade stand. You need money, so you ask your parents for some and borrow the rest from your piggy bank.","Your parents want you to share some of your lemonade profits with them as a thank you. Your piggy bank doesn't care about profits, but you have to put a little money back each week.","WACC is like figuring out how much, on average, it costs you to get all that money from both places. You need to make sure your lemonade stand earns more than what it costs to borrow the money, so you can keep some profit for yourself."],"collection":"practice","topic":"DCF","tags":["Reported in Citi Interview","New York Office, Superday","DCF","Basic"]},{"id":"q-1084","t":"val","l":"Basic","s":90,"q":"What impacts a DCF valuation more: the terminal value or the projected cash flows?","k":["The terminal value typically has a greater impact. It usually represents 60-80% of the total enterprise value in a DCF because it captures all cash flows beyond the explicit forecast period in perpetuity.","However, the projected cash flows matter because they form the base from which the terminal value is calculated. If the final-year cash flows are wrong, the terminal value will be wrong too. The projected period also matters more for companies in a high-growth phase where near-term cash flows are growing rapidly."],"collection":"practice","topic":"DCF","tags":["New","Reported in Citi Interview","SA 2026, New York Office, First round","DCF","Basic"]},{"id":"q-1085","t":"val","l":"Basic","s":90,"q":"A utilities company versus flipping a coin: what is the beta of each?","k":["A utilities company has a beta less than 1.0 (typically 0.3-0.6). Utilities provide essential services with regulated, predictable revenue streams that are largely insensitive to economic cycles and market movements.","Flipping a coin has a beta of 0. The outcome of a coin flip is completely random and has zero correlation with the stock market. Beta measures correlation with the market, and since a coin flip has no relationship to market returns, its beta is zero. This does not mean the coin flip is riskless - it has variance - but that risk is entirely idiosyncratic and uncorrelated with the market."],"collection":"practice","topic":"DCF","tags":["New","Reported in Citi Interview","SA 2026, New York Office, First round","DCF","Basic"]},{"id":"q-1086","t":"val","l":"Basic","s":90,"q":"Why do you multiply by (1 - Tax Rate) when calculating the after-tax cost of debt?","k":["Because interest expense is tax-deductible. When a company pays interest on its debt, it reduces taxable income, which lowers the company's tax bill. This tax savings (the \"interest tax shield\") reduces the effective cost of borrowing.","For example, if a company has a 10% interest rate and a 25% tax rate: Pre-tax cost = 10%. After-tax cost = 10% x (1 - 25%) = 7.5%. The company effectively saves 2.5% due to the tax deduction on interest. Dividends to equity holders, by contrast, are not tax-deductible, which is one reason why debt is cheaper than equity."],"collection":"practice","topic":"DCF","tags":["New","Reported in Citi Interview","SA 2026, New York Office, First round","DCF","Basic"]},{"id":"q-1087","t":"val","l":"Basic","s":90,"q":"What has the biggest impact on a DCF valuation outside of your topline revenue and margins?","k":["The discount rate (WACC) and the terminal value assumptions.","Terminal value typically represents 60-80% of total enterprise value in a DCF, so the terminal growth rate or exit multiple has an outsized effect on the output. Similarly, even small changes to WACC (e.g., 0.5% change) can significantly move the implied valuation because every future cash flow is discounted at that rate. This is why DCF sensitivity tables typically center on WACC and terminal growth rate / exit multiple."],"collection":"practice","topic":"DCF","tags":["New","Reported in Citi Interview","SA 2026, New York Office, First round","DCF","Basic"]},{"id":"q-1088","t":"val","l":"Basic","s":90,"q":"What impact does a low interest rate environment have on a DCF valuation?","k":["A low interest rate environment increases DCF valuations.","Lower risk-free rate reduces the cost of equity (via CAPM: Re = Rf + Beta x ERP) and the cost of debt, both lowering WACC.","A lower WACC increases the present value of all future cash flows, since you are discounting at a smaller rate.","The terminal value is particularly sensitive: in the Gordon Growth Model (FCF x (1+g) / (WACC - g)), a lower WACC dramatically increases TV since the denominator shrinks.","Since terminal value typically represents 60-80% of total DCF value, the impact is significant."],"collection":"practice","topic":"DCF","tags":["New","Reported in Citi Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1089","t":"val","l":"Basic","s":90,"q":"Between a small-cap and a large-cap company, which will have a longer near-future cash flow duration?","k":["The small-cap company will typically have a longer cash flow duration.","Small-cap companies are generally growth-stage businesses where most of the value is derived from cash flows far in the future (similar to a long-duration bond).","Large-cap companies are typically mature, generating significant cash flows today (dividends, buybacks), giving them a shorter duration because more value is concentrated in near-term cash flows.","This means small-cap companies are more sensitive to changes in interest rates / discount rates, since the present value of distant cash flows moves more with rate changes."],"collection":"practice","topic":"DCF","tags":["New","Reported in Citi Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1090","t":"val","l":"Basic","s":90,"q":"How does a decrease in the tax rate impact a Discounted Cash Flow (DCF) analysis?","k":["A decrease in the tax rate impacts a DCF analysis in the following ways:","Increased Net Income: Lower taxes result in higher net income, enhancing profitability.","Higher Free Cash Flows: With lower taxes, more cash is available for operations, investments, and distributions, leading to higher free cash flows.","Higher WACC (reduces the tax shield): The cost of debt is adjusted by the tax rate (Rd * (1 - Tax Rate)), so a lower tax rate increases the after-tax cost of debt.","Higher Enterprise Value: Increased free cash flows typically lead to a higher present value of cash flows, thus increasing Enterprise Value.","Overall, a decrease in the tax rate generally increases the valuation derived from a DCF analysis due to higher free cash flows."],"collection":"practice","topic":"DCF","tags":["Reported in Evercore Interview","DCF","Basic"]},{"id":"q-1091","t":"val","l":"Basic","s":90,"q":"Walk from revenue to levered free cash flow (FCFE).","k":["Conceptually, levered free cash flow (free cash flow to equity) represents the remaining cash available to equity holders once the company has satisfied its reinvestment requirements (including net capital expenditures and working capital adjustments) and met all debt obligations (interest payments and principal repayments).","Steps to Levered Free Cash Flow (FCFE):","Revenue – COGS = Gross Profit (GP)","GP – OpEx = Operating Income (EBIT)","EBIT – Interest Expense - Taxes = Net Income","Net Income + D&A – CapEx – Increase in NWC + Net Borrowing (Debt Issued - Debt Repayments) = Levered Free Cash Flow (FCF)"],"collection":"practice","topic":"DCF","tags":["Reported in Evercore Interview","DCF","Basic"]},{"id":"q-1092","t":"val","l":"Basic","s":90,"q":"If WACC is 10% and the perpetuity growth rate (g) is 5%, what is the implied perpetuity exit multiple?","k":["Answer: 21x","Calculation:","Terminal Value = FCF * (1 + g) / (WACC - g)","TV / FCF = (1 + g) / (WACC - g)","TV / FCF = (1.05) / (0.10 - 0.05) = 1.05 / 0.05 = 21x","The implied exit multiple is 21x the terminal year's FCF (not next year's)."],"collection":"practice","topic":"DCF","tags":["Reported in Evercore Interview","First round","DCF","Basic"]},{"id":"q-1093","t":"val","l":"Basic","s":90,"q":"How would an increase in the tax rate affect a DCF?","k":["An increase in the tax rate decreases the DCF valuation.","Higher taxes reduce after-tax earnings and Free Cash Flow (FCF = NOPAT + D&A - CapEx - Change in NWC, where NOPAT = EBIT x (1 - Tax Rate)). Lower FCF directly reduces the present value of projected cash flows.","Higher taxes also reduce the terminal value, since terminal FCF is lower.","Partially offsetting: the tax shield on debt increases (cost of debt x tax rate), which slightly lowers WACC. However, this effect is typically much smaller than the reduction in cash flows.","Net effect: Lower enterprise value from a DCF."],"collection":"practice","topic":"DCF","tags":["New","Reported in Evercore Interview","M&A group, New York Office, First round","DCF","Basic"]},{"id":"q-1094","t":"val","l":"Basic","s":90,"q":"How do you sensitize a DCF?","k":["You sensitize a DCF by creating data tables that vary the key assumptions driving the output.","The two most common sensitivity analyses are:","WACC vs. terminal growth rate (for perpetuity growth method)","WACC vs. exit multiple (for exit multiple method)","You can also sensitize revenue growth rates, EBITDA margins, or CapEx assumptions. The goal is to show how the implied share price or enterprise value changes across a range of reasonable assumptions, giving the client a valuation range rather than a single point estimate."],"collection":"practice","topic":"DCF","tags":["New","Reported in Evercore Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1095","t":"val","l":"Basic","s":90,"q":"What would happen to a company's valuation if the WACC went up? Does this make intuitive sense?","k":["The valuation would decrease. A higher WACC means future cash flows are discounted at a higher rate, reducing their present value.","This makes intuitive sense: a higher WACC reflects higher risk (either from more expensive debt, higher equity risk, or a riskier capital structure). Investors require a higher return to compensate for that risk, which means they are willing to pay less today for the same future cash flows."],"collection":"practice","topic":"DCF","tags":["New","Reported in Evercore Interview","SA 2025, First round","DCF","Basic"]},{"id":"q-1096","t":"val","l":"Basic","s":90,"q":"What would happen to a company's valuation if the Fed decides to cut interest rates?","k":["Valuation would generally increase.","Lower WACC: The risk-free rate feeds into both cost of equity (via CAPM) and cost of debt. A lower discount rate increases the present value of future cash flows in a DCF.","Higher trading multiples: Lower rates make future earnings more valuable, pushing up P/E and EV/EBITDA multiples across the market.","Improved cash flows: Companies with floating-rate debt see lower interest expense, boosting net income and FCF.","Increased deal activity: Cheaper debt financing supports higher LBO valuations and more M&A activity, providing additional valuation support."],"collection":"practice","topic":"DCF","tags":["New","Reported in Evercore Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1097","t":"val","l":"Basic","s":90,"q":"How do you set key assumptions when building a DCF?","k":["You analyze historical performance, discuss management guidance, examine industry benchmarks for growth, margins, capex, and working capital. Then form best estimates for revenue growth rates, operating margins, tax rates, capex, and WACC or discount rate."],"collection":"practice","topic":"DCF","tags":["Reported in FT Partners Interview","DCF","Basic"]},{"id":"q-1098","t":"val","l":"Basic","s":90,"q":"How does the tax shield on the cost of debt affect debt and WACC?","k":["The tax shield reduces the effective cost of debt, which lowers WACC.","Interest payments on debt are tax-deductible, meaning the government effectively subsidizes a portion of the interest cost. The after-tax cost of debt = Kd x (1 - Tax Rate).","If the pre-tax cost of debt is 6% and the tax rate is 25%, the after-tax cost of debt is only 4.5%. The 1.5% difference is the tax shield benefit.","Since WACC uses the after-tax cost of debt: WACC = (E/V x Ke) + (D/V x Kd x (1-T)), the tax shield makes the debt component cheaper, reducing overall WACC.","A lower WACC increases the present value of cash flows in a DCF, increasing Enterprise Value.","This is one reason companies use some debt in their capital structure -- the tax benefit of debt reduces the overall cost of capital (up to a point, before financial distress costs offset the benefit)."],"collection":"practice","topic":"DCF","tags":["New","Reported in FT Partners Interview","DCF","Basic"]},{"id":"q-1099","t":"val","l":"Basic","s":90,"q":"Walk me through a DCF. How do you calculate the cost of equity? What is beta, and how do you unlever and re-lever beta?","k":["DCF","Project UFCF over 5-10 years, calculate terminal value, discount everything at WACC, sum to get Enterprise Value.","Cost of Equity","Calculated via CAPM: Re = Rf + Beta x ERP, where Rf is the risk-free rate (10-year Treasury), Beta measures the stock's sensitivity to market movements, and ERP is the equity risk premium (~5-7%).","Beta","Beta measures systematic risk -- how much a stock moves relative to the overall market. A beta of 1.0 means the stock moves in line with the market. Above 1.0 is more volatile, below 1.0 is less volatile.","Unlevering and Re-levering Beta","Unlever to remove the effect of a company's capital structure: Unlevered Beta = Levered Beta / (1 + (1 - T) x (D/E))","Take the median unlevered beta of comparable companies.","Re-lever to reflect the target company's capital structure: Levered Beta = Unlevered Beta x (1 + (1 - T) x (D/E))","This ensures the beta used in CAPM reflects the target's specific leverage, not the peers'."],"collection":"practice","topic":"DCF","tags":["New","Reported in FT Partners Interview","Second round","DCF","Basic"]},{"id":"q-1100","t":"val","l":"Basic","s":90,"q":"What would make the cost of equity low for a company?","k":["A lower beta (less volatile stock relative to the market), lower risk-free rate environment, or a lower equity risk premium can bring down cost of equity.","Also, stable, diversified business models or strong brand moats lead to lower perceived risk, reducing the required return by investors."],"collection":"practice","topic":"DCF","tags":["Reported in Goldman Sachs Interview","DCF","Basic"]},{"id":"q-1101","t":"val","l":"Basic","s":90,"q":"Assuming a 5% discount rate, how much would you pay to receive $1 per day, every day, forever?","k":["Answer: $7,300","Calculation:","Annual cash flow = $1/day × 365 days = $365","Perpetuity Value = Annual Cash Flow / Discount Rate","PV = $365 / 0.05 = $7,300"],"collection":"practice","topic":"DCF","tags":["Reported in Goldman Sachs Interview","New York office","DCF","Basic"]},{"id":"q-1102","t":"val","l":"Basic","s":90,"q":"Answer the following questions about a DCF analysis:\n\n\n\nWhat are the two most important drivers of value in a DCF?\nHow do you calculate the Weighted Average Cost of Capital (WACC), Cost of Equity, and Beta?\nHow do you determine the Beta for a private company?","k":["Part 1: Key Drivers","The two most important value drivers are:","Cash flow growth (revenue growth, margins, working capital).","Discount rate (WACC) and terminal value assumptions.","Part 2: Formulas","WACC = (E/V × Cost of Equity) + (D/V × Cost of Debt × (1 - Tax Rate)).","Cost of Equity = Risk-Free Rate + Beta × Equity Risk Premium.","Beta = Covariance(Stock, Market) / Variance(Market).","Part 3: Private Company Beta","Use comparable public companies:","Find betas of similar public companies.","Unlever each beta: Unlevered Beta = Levered Beta / [1 + (1 - Tax Rate) × (D/E)].","Average the unlevered betas.","Relever using the private company's target capital structure."],"collection":"practice","topic":"DCF","tags":["Reported in Goldman Sachs Interview","First round","DCF","Basic"]},{"id":"q-1103","t":"val","l":"Basic","s":90,"q":"What is the impact of a rising risk-free rate on a company's WACC and its valuation from a DCF?","k":["A rising risk-free rate increases WACC, which decreases DCF valuation.","Mechanism:","Cost of Equity = Risk-Free Rate + Beta × Equity Risk Premium.","Higher risk-free rate directly increases Cost of Equity.","Cost of Debt also typically rises with risk-free rates.","Higher WACC means future cash flows are discounted more heavily.","Lower present value of cash flows results in lower valuation."],"collection":"practice","topic":"DCF","tags":["Reported in Goldman Sachs Interview","DCF","Basic"]},{"id":"q-1104","t":"val","l":"Basic","s":90,"q":"What happens to Unlevered Free Cash Flow (UFCF) if depreciation increases by $10 in a DCF?","k":["Assuming a 25% tax rate, Unlevered Free Cash Flow increases by $2.50.","UFCF = EBIT x (1 - t) + D&A - CapEx - Change in NWC","EBIT decreases by $10 (higher depreciation expense).","EBIT x (1 - t) decreases by $7.50.","D&A add-back increases by $10.","Net effect on UFCF: -$7.50 + $10 = +$2.50.","Higher depreciation increases free cash flow (and thus DCF valuation) by the amount of the tax shield: $10 x 25% = $2.50."],"collection":"practice","topic":"DCF","tags":["New","Reported in Goldman Sachs Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1105","t":"val","l":"Basic","s":90,"q":"Rank the following by their beta, from highest to lowest: a tech company, the S&P 500 (SPY), a dollar bill, and a utilities company.","k":["From highest to lowest beta:","Tech company (beta typically 1.2-1.8): High growth, high volatility, cyclical demand. Most sensitive to market movements.","S&P 500 / SPY (beta = 1.0): By definition, the market has a beta of exactly 1.","Utilities company (beta typically 0.3-0.6): Regulated, stable cash flows, defensive sector. Low sensitivity to market swings.","Dollar bill (beta = 0): A dollar bill has no correlation to the stock market. Its value is fixed in nominal terms."],"collection":"practice","topic":"DCF","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, First round","DCF","Basic"]},{"id":"q-1106","t":"val","l":"Basic","s":90,"q":"Given a company like Dell, would you rather use a 25-year or a 5-year DCF? Why?","k":["A 5-year DCF is more appropriate for Dell.","Dell operates in the technology hardware sector, where product cycles are short (3-5 years) and disruption risk is high. Projecting cash flows 25 years out would require assumptions about technology trends that are highly uncertain.","A 5-year projection captures the near-term growth trajectory and current business dynamics, then uses a terminal value to capture long-term value without making overly specific long-range assumptions.","25-year DCFs are more appropriate for businesses with very long-lived, predictable cash flows like infrastructure, utilities, or real estate with long-term contracts.","In general, 5-10 year projection periods are standard for most DCFs. The terminal value captures value beyond the explicit forecast period."],"collection":"practice","topic":"DCF","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","DCF","Basic"]},{"id":"q-1107","t":"val","l":"Basic","s":90,"q":"Rank the betas of the following: the S&P 500, a utilities company, a dollar bill, a tech startup, and cryptocurrency.","k":["From highest to lowest beta:","Cryptocurrency: Highest. Extremely volatile and increasingly correlated with risk-on market sentiment, though correlation is inconsistent.","Tech startup: Very high beta. Speculative, high growth sensitivity, strongly correlated with market risk appetite.","S&P 500: Beta = 1.0 by definition (it is the market).","Utilities company: Low beta (~0.3-0.6). Regulated, stable cash flows, defensive sector.","Dollar bill: Beta = 0. No correlation with the stock market; its value is fixed in nominal terms."],"collection":"practice","topic":"DCF","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027","DCF","Basic"]},{"id":"q-1108","t":"val","l":"Basic","s":90,"q":"If you are using the exit multiple method to calculate terminal value, how would you adjust the terminal value?","k":["The terminal value calculated via exit multiple must be discounted back to present value:","TV = Terminal Year EBITDA x Exit Multiple. This gives the terminal value as of the end of the projection period.","Discount to present: PV of TV = TV / (1 + WACC)^n, where n is the number of years in the projection period.","Exit multiple selection: Use the current trading multiple of comparable companies, or the median of precedent transaction multiples. Consider whether the company will be more or less mature at exit and adjust accordingly.","Sanity check: Convert the exit multiple-derived terminal value to an implied perpetuity growth rate to ensure it is reasonable (typically 2-4%)."],"collection":"practice","topic":"DCF","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","DCF","Basic"]},{"id":"q-1109","t":"val","l":"Basic","s":90,"q":"Walk me from revenue down to unlevered free cash flow.","k":["Revenue - COGS - OpEx = EBIT (operating income)","EBIT * (1 - tax rate) = NOPAT","NOPAT + D&A and other non-cash charges - CapEx - Change in Working Capital = Unlevered Free Cash Flow"],"collection":"practice","topic":"DCF","tags":["Reported in Greenhill & Co. Interview","SA 2024, Industrials M&A, Chicago office","DCF","Basic"]},{"id":"q-1110","t":"val","l":"Basic","s":90,"q":"What is the effect of using the mid-year convention in a DCF?","k":["Shifts each cash‑flow discount date back half a period, raising present value and enterprise value.","The uplift reflects the fact that cash is earned throughout the year, not just at year‑end."],"collection":"practice","topic":"DCF","tags":["Reported in Greenhill & Co. Interview","SA 2024, Industrials M&A, Chicago office","DCF","Basic"]},{"id":"q-1111","t":"val","l":"Basic","s":90,"q":"How would you find beta for a public company? What about a private company?","k":["Public Company","Regress the company's historical stock returns against a market index (typically the S&P 500) over 2-5 years. The slope of the regression is the levered beta. You can also pull it from Bloomberg, Capital IQ, or FactSet.","Private Company","Identify comparable public companies.","Unlever each comp's beta: Unlevered Beta = Levered Beta / (1 + (1 - Tax Rate) x (D/E)).","Take the median unlevered beta.","Re-lever using the private company's target D/E: Levered Beta = Unlevered Beta x (1 + (1 - Tax Rate) x (D/E))."],"collection":"practice","topic":"DCF","tags":["New","Reported in Guggenheim Partners Interview","SA 2027, Business Services group, Atlanta Office, Phone screen","DCF","Basic"]},{"id":"q-1112","t":"val","l":"Basic","s":90,"q":"What is the difference between levered beta and unlevered beta?","k":["Levered beta (equity beta) reflects both business risk and financial risk from leverage. Unlevered beta (asset beta) strips out leverage and isolates pure operating risk.","Levered Beta = Unlevered Beta x (1 + (1 - Tax Rate) x (D/E)). Adding debt increases levered beta because leverage amplifies equity returns in both directions. Unlevered beta is used to compare companies with different capital structures on an apples-to-apples basis."],"collection":"practice","topic":"DCF","tags":["New","Reported in Guggenheim Partners Interview","SA 2027, Business Services group, Atlanta Office, Phone screen","DCF","Basic"]},{"id":"q-1113","t":"val","l":"Basic","s":90,"q":"How do you calculate cost of debt?","k":["Cost of debt is the effective interest rate a company pays on its debt obligations, adjusted for the tax benefit of interest deductions.","Pre-Tax Cost of Debt can be estimated by:","Yield to maturity (YTM) on the company's outstanding bonds.","Interest rate on recent debt issuances.","Yield on debt of comparably rated companies if no public debt exists.","After-Tax Cost of Debt = Pre-Tax Cost of Debt x (1 - Tax Rate)","The tax adjustment reflects that interest expense is tax-deductible, making debt cheaper on an after-tax basis. This is the figure used in the WACC calculation."],"collection":"practice","topic":"DCF","tags":["New","Reported in Guggenheim Partners Interview","SA 2025","DCF","Basic"]},{"id":"q-1114","t":"val","l":"Basic","s":90,"q":"What is beta? What does a beta of -1, 2, and 0 mean?","k":["Beta measures a stock's sensitivity to movements in the overall market (typically the S&P 500).","Beta of -1: The stock moves inversely to the market. If the market goes up 10%, this stock would go down 10%. Rare in practice, but some inverse ETFs or gold miners can exhibit negative beta.","Beta of 2: The stock is twice as volatile as the market. If the market goes up 10%, the stock goes up ~20%, and vice versa. Common for high-growth tech or highly leveraged companies.","Beta of 0: The stock's returns are uncorrelated with the market. It has no systematic risk. Cash or a risk-free asset would have a beta of 0.","A beta of 1 means the stock moves in line with the market (e.g., an S&P 500 index fund)."],"collection":"practice","topic":"DCF","tags":["New","Reported in Guggenheim Partners Interview","SA 2025","DCF","Basic"]},{"id":"q-1115","t":"val","l":"Basic","s":90,"q":"What are the two methods for calculating terminal value, and what types of companies are better suited for each method?","k":["1. Perpetuity Growth Method (Gordon Growth Model)","Formula: TV = FCF x (1 + g) / (WACC - g)","Best for: Mature, stable companies with predictable, steady-state cash flows (e.g., utilities, consumer staples).","Requires a reasonable long-term growth rate assumption (typically 2-3%, in line with GDP growth).","2. Exit Multiple Method","Formula: TV = Terminal Year EBITDA x Exit Multiple","Best for: Companies with strong comparable companies or in sectors where market multiples are well-established (e.g., tech, industrials).","More commonly used in practice because it is easier to benchmark against observable market data."],"collection":"practice","topic":"DCF","tags":["New","Reported in Guggenheim Partners Interview","SA 2027, Superday","DCF","Basic"]},{"id":"q-1116","t":"val","l":"Basic","s":90,"q":"If interest rates increase, what happens to a company's WACC and its implied DCF valuation?","k":["WACC increases and the implied DCF valuation decreases.","Higher interest rates affect WACC through two channels:","Cost of Debt rises because new borrowing rates increase.","Cost of Equity rises because the risk-free rate (a key input in CAPM: Rf + Beta x ERP) increases.","A higher WACC means future cash flows are discounted at a higher rate, reducing their present value and lowering the implied enterprise value from the DCF."],"collection":"practice","topic":"DCF","tags":["New","Reported in Houlihan Lokey Interview","SA 2027, Business Services group, LA Office, First round","DCF","Basic"]},{"id":"q-1117","t":"val","l":"Basic","s":90,"q":"Where does Stock-Based Compensation get added in the Free Cash Flow calculation? Is it in Unlevered Free Cash Flow or Levered Free Cash Flow?","k":["Stock-Based Compensation (SBC) is a non-cash expense that reduces Net Income but does not consume cash. It appears in both UFCF and LFCF calculations, but how it is treated is debated.","On the Cash Flow Statement, SBC is added back in CFO because it is non-cash. If you build UFCF from Net Income or NOPAT, you add SBC back (just like D&A).","However, SBC is a real economic cost (it dilutes existing shareholders), so many analysts do NOT add it back when calculating FCF for valuation purposes.","Best practice: Exclude SBC from the add-back (treat it as a real cash expense) to avoid overstating FCF. Alternatively, add it back but account for the dilution by using a higher diluted share count.","SBC affects both UFCF and LFCF equally -- the treatment is the same regardless of whether the DCF is levered or unlevered."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1118","t":"val","l":"Basic","s":90,"q":"Why would we use Levered Free Cash Flow in a DCF?","k":["You would use Levered Free Cash Flow in a DCF when you want to value the equity directly, rather than the entire enterprise.","A levered DCF discounts LFCF at the Cost of Equity (not WACC) and produces Equity Value directly, without needing to subtract net debt at the end.","This approach is common for financial institutions (banks, insurance companies) where debt is integral to operations and separating operating vs. financing cash flows is impractical.","It is also used when the capital structure is expected to change significantly over the projection period, since LFCF naturally captures the impact of debt paydown or issuance each year.","Most standard DCFs use UFCF discounted at WACC because it separates operating performance from capital structure decisions."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1119","t":"val","l":"Basic","s":90,"q":"How would an increase in interest rates affect the cost of capital?","k":["An increase in interest rates increases both components of WACC:","Cost of Debt increases: Higher benchmark rates (e.g., SOFR, Treasury yields) raise the interest rate on new and variable-rate borrowings. Even with the tax shield, after-tax cost of debt rises.","Cost of Equity increases: The risk-free rate is a key input in CAPM (Ke = Rf + Beta x ERP). A higher risk-free rate directly increases the cost of equity.","Since both components increase, WACC rises, which reduces the present value of future cash flows in a DCF and lowers enterprise value."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1120","t":"val","l":"Basic","s":90,"q":"Does the cost of equity change if interest rates change?","k":["Yes. The Cost of Equity is directly affected by interest rates through the CAPM formula: Ke = Risk-Free Rate + Beta x Equity Risk Premium.","The risk-free rate (typically the 10-year U.S. Treasury yield) is a direct input. When interest rates rise, the risk-free rate increases, which increases the cost of equity dollar-for-dollar (holding beta and ERP constant).","There is a secondary effect as well: higher interest rates can increase the equity risk premium if investors become more risk-averse, or decrease it if higher rates signal economic strength. But the primary and most direct channel is through the risk-free rate."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1121","t":"val","l":"Basic","s":90,"q":"Part 1: How do you calculate WACC?\n\n\n\n\nPart 2: How do you calculate the cost of equity?\n\n\n\n\nPart 3: What is the risk-free rate and equity risk premium?","k":["Part 1: WACC Formula","WACC = (E/V) x Ke + (D/V) x Kd x (1 - t)","Where E = equity value, D = debt, V = E + D, Ke = cost of equity, Kd = cost of debt, t = tax rate.","Part 2: Cost of Equity (CAPM)","Ke = Rf + Beta x (Rm - Rf)","Where Rf = risk-free rate, Beta = measure of systematic risk, and (Rm - Rf) = equity risk premium (ERP).","Part 3: Risk-Free Rate and ERP","The risk-free rate is the return on a risk-free investment, typically the yield on the 10-year U.S. Treasury bond. The equity risk premium is the additional return investors demand for holding equities over risk-free assets, typically estimated at 4-7% based on historical market data. The ERP compensates investors for the extra risk of equities relative to government bonds."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1122","t":"val","l":"Basic","s":90,"q":"How does risk come into play in a DCF valuation?","k":["Risk is captured in the discount rate (WACC) used to present-value future cash flows:","Cost of equity (via CAPM): Higher beta (market risk), higher equity risk premium, or higher risk-free rate all increase the cost of equity and lower the valuation.","Cost of debt: Riskier companies pay higher interest rates, increasing WACC.","Company-specific risk: Smaller companies may warrant a size premium or company-specific risk premium added to the cost of equity.","Cash flow uncertainty: Riskier cash flow projections should use more conservative growth and margin assumptions, or a wider range of scenarios.","Terminal value sensitivity: A higher discount rate dramatically reduces the terminal value, which typically represents 60-80% of total DCF value."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2026, New York Office, Superday","DCF","Basic"]},{"id":"q-1123","t":"val","l":"Basic","s":90,"q":"What is terminal value and how do you calculate it in a DCF?","k":["Terminal value captures the value of all cash flows beyond the explicit forecast period, reflecting the company's ongoing value into perpetuity. It typically represents 60-80% of total DCF value.","Two methods:","Perpetuity Growth Method: TV = Final Year FCF x (1 + g) / (WACC - g), where g is the long-term growth rate (typically 2-3%, in line with GDP growth).","Exit Multiple Method: TV = Final Year EBITDA x Exit EV/EBITDA Multiple, where the exit multiple is based on comparable company trading multiples.","Best practice is to use both methods as a cross-check. The terminal value is then discounted back to the present using WACC."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2025","DCF","Basic"]},{"id":"q-1124","t":"val","l":"Basic","s":90,"q":"What is Free Cash Flow, and why do we focus on it?","k":["Free Cash Flow is the discretionary cash a company generates after funding operations and maintenance capex.","Unlevered FCF = EBIT × (1 − tax rate) + D&A − Capex − ΔNWC","It matters because it is the cash available to all capital providers and drives intrinsic value in a DCF."],"collection":"practice","topic":"DCF","tags":["Reported in Jefferies Interview","SA 2026","DCF","Basic"]},{"id":"q-1125","t":"val","l":"Basic","s":90,"q":"How can you sense-check the terminal value in a DCF?","k":["Cross-check methods: If using the perpetuity growth method, calculate the implied exit multiple. If using the exit multiple method, calculate the implied perpetuity growth rate. Both should produce reasonable results.","Terminal value as a % of total EV: Typically 60-80%. If it is 90%+, your near-term projections may be too low or your terminal assumptions too aggressive.","Implied perpetuity growth rate should be at or below long-term GDP growth (2-3%). A rate above this implies the company will eventually become larger than the economy.","Implied exit multiple should be in line with comparable company trading multiples. If it is significantly higher, the terminal value may be overstated.","Run a sensitivity table on WACC and terminal growth rate (or exit multiple) to see the range of outcomes."],"collection":"practice","topic":"DCF","tags":["New","Reported in Jefferies Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1126","t":"val","l":"Basic","s":90,"q":"Why might you use a longer forecast period in a DCF model, for example if the company has changing growth rates during the projection period?","k":["You would use a longer forecast period when the company has not yet reached a steady state. A terminal value assumes stable, perpetual growth, so the company must be at a normalized level of growth and margins before the terminal year.","Reasons for a longer forecast period:","High-growth companies that need time for growth rates to decelerate to a sustainable long-term rate","Cyclical businesses that need a full cycle captured in the projection","Companies undergoing major transitions (restructuring, product launches, regulatory changes)","Businesses with known contract expirations, patent cliffs, or finite-life assets","The projection period should be long enough that the terminal value assumption of stable growth is reasonable."],"collection":"practice","topic":"DCF","tags":["New","Reported in Jefferies Interview","SA 2027","DCF","Basic"]},{"id":"q-1127","t":"val","l":"Basic","s":90,"q":"Walk me through how you go from revenue to unlevered free cash flow. Then walk me through how you go from cash flow from operations to unlevered free cash flow.","k":["Revenue to UFCF:","Revenue - COGS = Gross Profit.","- OpEx = EBIT.","EBIT x (1 - Tax Rate) = NOPAT.","+ D&A.","- CapEx.","+/- Changes in NWC.","= UFCF.","CFO to UFCF:","Start with Cash Flow from Operations (CFO).","Add back after-tax interest expense (since CFO is levered and includes interest).","Subtract CapEx.","= UFCF.","The key difference: CFO starts from Net Income (which is after interest and taxes), so you must add back the after-tax interest expense to unlever it."],"collection":"practice","topic":"DCF","tags":["New","Reported in Jefferies Interview","SA 2025, TMT group, SF Office, Superday","DCF","Basic"]},{"id":"q-1128","t":"val","l":"Basic","s":90,"q":"What happens to a DCF valuation if the tax rate increases?","k":["Higher taxes reduce after-tax EBIT (NOPAT), and thus reduce unlevered free cash flow. The lower cash flows lead to a lower DCF valuation, all else being equal.","You might also adjust WACC if the capital structure is affected, but typically the direct effect is on lower free cash flow."],"collection":"practice","topic":"DCF","tags":["Reported in Lazard Interview","DCF","Basic"]},{"id":"q-1129","t":"val","l":"Basic","s":90,"q":"When valuing an apple tree using a DCF, would you prefer to use the Gordon Growth Model or the Exit Multiple Method for the terminal value, and why?","k":["Gordon Growth Model.","The tree is a stand‑alone, non‑traded asset whose cash flows are expected to grow at a steady, biologically limited rate rather than be sold at a market multiple.","Using a perpetual growth assumption:","Aligns with the asset’s economic reality (ongoing harvests).","Avoids arbitrary selection of exit multiples that have no observable market comps.","Reduces valuation noise—growth rate and discount rate are easier to justify than comparables for trees."],"collection":"practice","topic":"DCF","tags":["Reported in Lazard Interview","DCF","Basic"]},{"id":"q-1130","t":"val","l":"Basic","s":90,"q":"Is the cost of equity always greater than the cost of debt? Explain your reasoning.","k":["Yes in theory; usually in practice.","Equity holders are residual claimants and face greater risk of loss than debt holders.","Debt enjoys contractual coupons, seniority, and often collateral.","Tax deductibility of interest lowers the after‑tax cost of debt further.","Exceptions arise in distress situations (very high debt yields) or when models break down (e.g. negative earnings), so cost of debt can technically exceed cost of equity."],"collection":"practice","topic":"DCF","tags":["Reported in Lazard Interview","DCF","Basic"]},{"id":"q-1131","t":"val","l":"Basic","s":90,"q":"Back-to-back DCF questions:\n\n\n\nWhy do we typically use unlevered free cash flow in a DCF instead of levered free cash flow?\nHow do you calculate the Weighted Average Cost of Capital (WACC)?\nHow do you calculate the cost of equity? Explain the Capital Asset Pricing Model (CAPM).","k":["UFCF:","UFCF represents cash flow available to all investors (equity and debt) and is used to produce an Enterprise Value, which is typically the output of a DCF.","WACC:","WACC = Cost of Equity * (% Equity) + Cost of Debt * (% Debt) * (1 – Tax Rate) + Cost of Preferred * (% Preferred).","Cost of Equity using CAPM:","Cost of Equity = Risk-Free Rate + Beta * Equity Risk Premium.","The Risk-Free Rate reflects the return on long-term government bonds (typically 10–20 year U.S. Treasuries).","Beta measures how volatile the stock is relative to the market, based on peer companies.","The Equity Risk Premium is the market’s expected return above the risk-free rate","You may also add a size premium (for smaller, riskier companies) and an industry premium (for sector-specific outperformance expectations)","Intuitively, CAPM says investors need to be compensated for both the time value of money (via the risk-free rate) and the risk they’re taking (via beta × equity risk premium). In short, the riskier the stock relative to the market, the higher the return investors will demand."],"collection":"practice","topic":"DCF","tags":["Reported in Lazard Interview","DCF","Basic"]},{"id":"q-1132","t":"val","l":"Basic","s":90,"q":"Why is the yield on the 10-year U.S. Treasury note often used as the risk-free rate?\n\n\n\n\nIn practice, how do you determine a company's actual cost of debt?","k":["Risk‑Free Rate","Backed by the U.S. government > negligible default risk.","10‑year matches long‑term corporate cash‑flow horizon.","Highly liquid benchmark traded daily.","Cost of Debt","Use the yield‐to‑maturity on existing traded bonds.","If private, add credit‑spread from rating comps to risk‑free rate.","Adjust for tax shield: after‑tax cost = pretax × (1 − tax rate)."],"collection":"practice","topic":"DCF","tags":["Reported in Lazard Interview","DCF","Basic"]},{"id":"q-1133","t":"val","l":"Basic","s":90,"q":"Which has a higher cost of equity: a large company or a small company?","k":["A small company has a higher cost of equity.","Small companies are riskier: less diversified revenue, thinner management teams, lower liquidity, and greater vulnerability to economic downturns.","Small companies typically have higher betas, reflecting greater sensitivity to market movements.","In CAPM, a size premium is often added for small-cap companies to reflect the additional risk not captured by beta alone (the Fama-French size factor).","Investors demand a higher return to compensate for these risks, translating to a higher cost of equity."],"collection":"practice","topic":"DCF","tags":["New","Reported in Lincoln International Interview","SA 2025, Superday","DCF","Basic"]},{"id":"q-1134","t":"val","l":"Basic","s":90,"q":"$10 in revenue, Opex, and Capex: Which has the biggest impact on a DCF?\n\n\n\n\n(Rank order in terms of magnitude of effect)","k":["Greatest negative to least:","$10 increase in CapEx (full $10 cash outflow).","$10 increase in Operating Expenses (hits EBIT but is partly offset by lower taxes).","$10 increase in Revenue actually raises value; a decrease would mirror OpEx.","CapEx directly reduces Free Cash Flow dollar‑for‑dollar, so its impact is largest."],"collection":"practice","topic":"DCF","tags":["Reported in LionTree Interview","SA 2026","DCF","Basic"]},{"id":"q-1135","t":"val","l":"Basic","s":90,"q":"Which has the bigger impact on valuation in a DCF: $10 increase in revenue, $10 decrease in operating expenses, or $10 decrease in Capex?","k":["$10 lower Capex.","Capex reduction raises free cash flow dollar‑for‑dollar (no tax). Operating‑expense savings add $10 × (1 – tax), and extra revenue lifts FCF by margin × (1 – tax); both smaller than the Capex impact."],"collection":"practice","topic":"DCF","tags":["Reported in LionTree Interview","SA 2026","DCF","Basic"]},{"id":"q-1136","t":"val","l":"Basic","s":90,"q":"A company has a market capitalization of $700 million, $300 million in debt, a cost of equity of 9%, a pre-tax cost of debt of 5%, and a tax rate of 25%. Calculate the WACC.","k":["Answer: 7.43%","Total Capital = Equity + Debt = $700M + $300M = $1,000M","Equity Weight = 700 / 1,000 = 70%","Debt Weight = 300 / 1,000 = 30%","After-tax cost of debt = 5% * (1 - 0.25) = 3.75%","WACC = (70% * 9%) + (30% * 3.75%) = 6.30% + 1.125% = 7.425%, or approximately 7.43%."],"collection":"practice","topic":"DCF","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, First round","DCF","Basic"]},{"id":"q-1137","t":"val","l":"Basic","s":90,"q":"If the discount rate increases, what happens to revenue and cash flow projections in a DCF?","k":["The revenue and cash flow projections themselves do not change when the discount rate increases. The projections are based on the company's expected operating performance and are independent of the discount rate.","What changes is the present value of those cash flows. A higher discount rate means each future cash flow is worth less today, reducing the DCF valuation. The terminal value is also impacted significantly since it represents the bulk of the DCF value and is discounted over the longest period. The net result is a lower implied enterprise value, even though the projected cash flows are identical."],"collection":"practice","topic":"DCF","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, First round","DCF","Basic"]},{"id":"q-1138","t":"val","l":"Basic","s":90,"q":"What does the cost of equity represent in a valuation context?\n\n\n\n\nFollow up 1: How is it calculated?\n\n\n\n\nFollow up 2: Can you explain each component of the formula.","k":["The cost of equity represents the annual return investors require to compensate for the risk of investing in a company's equity.","Follow up 1: Formula","The cost of equity can be calculated using the Capital Asset Pricing Model (CAPM)","Cost of Equity = Risk-Free Rate + (Beta * Equity Risk Premium)","Follow up 2: Components of the formula","Risk-Free Rate: The rate of return on a risk-free investment, such as a government bond.","Beta: Measure of sensitivity to systematic risk (volatility) relative to broader market.","Equity Risk Premium: The additional return investors demand for investing in stocks compared to risk-free investments."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","DCF","Basic"]},{"id":"q-1139","t":"val","l":"Basic","s":90,"q":"Walk me through the calculation from EBITDA to Unlevered Free Cash Flow (UFCF).","k":["Walk through:","EBITDA - D&A and other non-cash charges = EBIT","EBIT * (1 - tax rate) = NOPAT","NOPAT + D&A and other non-cash charges - Capex - Changes in WC = UFCF"],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","DCF","Basic"]},{"id":"q-1140","t":"val","l":"Basic","s":90,"q":"In a DCF model, what are three key levers you could adjust to increase the company's valuation?","k":["Raise revenue/margin growth, lower the discount rate, and use a higher terminal growth or exit multiple.","Why they work:","Higher cash flows in explicit forecast period.","Lower WACC increases the present value of each dollar.","Higher terminal value boosts the perpetuity portion, often the largest slice of intrinsic value."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","DCF","Basic"]},{"id":"q-1141","t":"val","l":"Basic","s":90,"q":"What is unlevered free cash flow, and how do you calculate it?","k":["Unlevered Free Cash Flow (UFCF) is the cash flow available to all investors (debt and equity) before debt payments.","Calculation:","Start with EBIT (Earnings Before Interest and Taxes).","Subtract Taxes on EBIT = EBIT * (1 - Tax Rate) = NOPAT.","Add back Depreciation & Amortization (non-cash).","Subtract Capital Expenditures (CapEx).","Subtract Increase in Net Working Capital (NWC).","Formula: UFCF = NOPAT + D&A - CapEx - Δ NWC","UFCF represents cash generated by operations available to all capital providers, making it appropriate for enterprise valuation (DCF)."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","DCF","Basic"]},{"id":"q-1142","t":"val","l":"Basic","s":90,"q":"If WACC is used to discount unlevered free cash flow, what rate would you use to discount levered free cash flow?","k":["Cost of Equity","Levered Free Cash Flow (FCFE) represents cash available to equity holders after debt obligations are met.","Since FCFE is an equity-level cash flow, it should be discounted at the Cost of Equity, which reflects the return required by equity investors.","WACC is inappropriate because it reflects the blended cost of all capital (debt and equity), while FCFE only accrues to equity holders."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","DCF","Basic"]},{"id":"q-1143","t":"val","l":"Basic","s":90,"q":"How would you explain the Cost of Equity to someone with no finance background?","k":["Cost of Equity is the return that investors expect for investing in a company's stock, given the risk involved.","Simple analogy:","If you lend money to a friend, you might expect them to pay you back with some interest as compensation for the risk.","Similarly, when investors buy stock, they expect returns (dividends, price appreciation) as compensation for the risk of owning that company.","Riskier companies require higher returns to attract investors—that's their Cost of Equity.","For the company, this represents the minimum return it must generate to satisfy equity investors."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","DCF","Basic"]},{"id":"q-1144","t":"val","l":"Basic","s":90,"q":"Why would one company have a higher WACC than another?","k":["A company would have a higher WACC due to:","Higher Business Risk: More volatile cash flows, cyclical industry, or uncertain outlook increases Cost of Equity.","Higher Financial Risk: More leverage increases Cost of Debt and Cost of Equity (higher beta).","Lower Credit Rating: Riskier companies pay higher interest rates on debt.","Less Debt in Capital Structure: Less tax shield from interest, raising blended WACC.","Smaller Size: Smaller companies often have higher cost of capital due to liquidity and risk premiums.","Industry: Some industries (e.g., tech startups) have inherently higher WACC than stable utilities."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","DCF","Basic"]},{"id":"q-1145","t":"val","l":"Basic","s":90,"q":"Theoretically, how is a company's ability to generate cash linked to its value?\n\n\n\n\nIf you were given a company's cash flow for each of the next 30 years, how would you derive its value?","k":["A company's value equals the present value of all future cash flows it can generate for investors.","To derive value from 30 years of projected cash flows, discount each year's cash flow to present value using an appropriate discount rate (typically WACC), then sum all discounted values.","Formula: Value = Σ (CFₜ / (1 + r)ᵗ) for t = 1 to 30.","This is the foundation of DCF valuation. In practice, you'd also add a terminal value beyond year 30 to capture perpetual cash flows."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","DCF","Basic"]},{"id":"q-1146","t":"val","l":"Basic","s":90,"q":"How would changing the corporate tax rate affect the valuation in a DCF?","k":["A lower corporate tax rate generally increases DCF valuation, and a higher tax rate decreases it.","Key impacts:","Higher after-tax cash flows: Lower taxes mean higher net income and free cash flow, increasing the present value of projected cash flows.","Slightly higher WACC: A lower tax rate reduces the interest tax shield, increasing the after-tax cost of debt and therefore WACC. However, this effect is typically small.","Net effect: The increase in cash flows almost always outweighs the slight increase in WACC, resulting in a higher valuation."],"collection":"practice","topic":"DCF","tags":["New","Reported in Moelis & Co. Interview","SA 2027","DCF","Basic"]},{"id":"q-1147","t":"val","l":"Basic","s":90,"q":"Please answer the following questions about the Discounted Cash Flow (DCF) valuation method:\n\n\n\nWalk me through a DCF.\nHow is Free Cash Flow (FCF) impacted by an increase in capital expenditures?\nHow is FCF impacted by an increase in depreciation?\nHow do you calculate a company's terminal value?","k":["Part 1: DCF Walkthrough","Project unlevered free cash flows (UFCF) over 5-10 years: Revenue → EBITDA → EBIT → NOPAT (EBIT * (1-tax rate)) → add back D&A → subtract CapEx → subtract increase in NWC = UFCF. Discount UFCF to present value using WACC. Calculate terminal value, discount to present. Enterprise Value = PV of UFCFs + PV of Terminal Value.","Part 2: CapEx Increase Impact","FCF decreases dollar-for-dollar. Higher CapEx directly reduces cash available after reinvestment needs.","Part 3: Depreciation Increase Impact","FCF increases. Higher D&A reduces taxable income (creating tax shield), then D&A is added back as non-cash expense, resulting in net cash flow increase equal to the tax savings (D&A * tax rate).","Part 4: Terminal Value Calculation","Two methods:","Perpetuity Growth: TV = Final Year FCF * (1+g) / (WACC - g), where g is perpetual growth rate.","Exit Multiple: TV = Final Year EBITDA (or EBIT) * Exit Multiple."],"collection":"practice","topic":"DCF","tags":["Reported in Morgan Stanley Interview","London office","DCF","Basic"]},{"id":"q-1148","t":"val","l":"Basic","s":90,"q":"What is the difference between an unlevered DCF and a levered DCF?","k":["An unlevered DCF discounts Unlevered Free Cash Flow (UFCF) at WACC to arrive at Enterprise Value. UFCF is cash flow available to all capital providers (debt and equity) and excludes interest expense. This is the standard approach used in investment banking.","A levered DCF discounts Levered Free Cash Flow (LFCF) at the cost of equity to arrive at Equity Value directly. LFCF is cash flow available only to equity holders after debt service (interest and mandatory principal repayments).","Key Differences","Unlevered DCF: UFCF discounted at WACC = Enterprise Value. Then subtract net debt to get Equity Value.","Levered DCF: LFCF discounted at Cost of Equity = Equity Value directly.","The unlevered DCF is more common because it separates operating performance from capital structure decisions.","A levered DCF is used more in LBOs, project finance, and financial institutions where the capital structure is integral to the business."],"collection":"practice","topic":"DCF","tags":["New","Reported in Morgan Stanley Interview","SA 2027","DCF","Basic"]},{"id":"q-1149","t":"val","l":"Basic","s":90,"q":"Is there always a terminal value in a DCF?","k":["Almost always, but not when the company has a finite life. Examples where terminal value is excluded:","A natural resource company with a finite reserve (e.g., a mine).","A project finance asset with a defined concession period.","A liquidating trust with a set wind-down date.","In the vast majority of DCFs, a terminal value is included since companies are assumed to operate indefinitely. Terminal value typically represents 60-80% of total enterprise value."],"collection":"practice","topic":"DCF","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Generalist group, New York Office, First round","DCF","Basic"]},{"id":"q-1150","t":"val","l":"Basic","s":90,"q":"Why do we add back non-cash charges in a DCF?","k":["Non-cash charges (D&A, SBC, impairments) reduce net income but do not represent actual cash outflows. Since a DCF values actual cash flows, we add back these items to reflect the true cash-generating ability of the business. Depreciation, for example, is an accounting allocation of a past CapEx, not a current cash outflow."],"collection":"practice","topic":"DCF","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Generalist group, New York Office, First round","DCF","Basic"]},{"id":"q-1151","t":"val","l":"Basic","s":90,"q":"What are the different components of the Capital Asset Pricing Model (CAPM)?","k":["CAPM: Cost of Equity = Risk-Free Rate + Beta x (Market Return - Risk-Free Rate)","Risk-Free Rate: Typically the 10-year U.S. Treasury yield. Represents the return on a zero-default-risk investment.","Beta: Measures the stock's sensitivity to overall market movements. A beta of 1.0 means it moves in line with the market.","Equity Risk Premium (ERP): The Market Return minus the Risk-Free Rate. Represents the incremental return investors demand for holding equities over risk-free assets. Typically 5-7%.","Some practitioners also add a size premium for smaller companies."],"collection":"practice","topic":"DCF","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Superday","DCF","Basic"]},{"id":"q-1152","t":"val","l":"Basic","s":90,"q":"What is the risk-free rate?\n\n\n\n\nFollow-up: Why do we use the 10-year Treasury yield as the risk-free rate?","k":["The risk-free rate is the theoretical return on an investment with zero default risk. In practice, it is proxied by U.S. Treasury yields because the U.S. government is considered to have negligible default risk.","We use the 10-year Treasury yield specifically because its duration roughly matches the duration of a typical DCF's projected cash flows (5-10 year forecast plus terminal value). Short-term T-bills are too volatile and don't match the investment horizon. The 30-year is less liquid and more sensitive to term premium. The 10-year strikes the best balance between maturity matching and market liquidity."],"collection":"practice","topic":"DCF","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Superday","DCF","Basic"]},{"id":"q-1153","t":"val","l":"Basic","s":90,"q":"If you and I were to enter into a contract where I paid you $100 every year forever, how much would you pay me right now to receive the upfront payment instead?","k":["This is a perpetuity valuation. PV = Annual Payment / Discount Rate.","If we assume a discount rate of 10%, you would pay $100 / 0.10 = $1,000. At a 5% rate, $100 / 0.05 = $2,000. The answer depends entirely on the appropriate discount rate, which reflects the risk of the cash flows and the opportunity cost of capital. The interviewer wants to see that you identify this as a perpetuity and state the formula: PV = C / r."],"collection":"practice","topic":"DCF","tags":["New","Reported in Morgan Stanley Interview","SA 2025, Healthcare group, SF Office, Superday","DCF","Basic"]},{"id":"q-1154","t":"val","l":"Basic","s":90,"q":"How does an increase in leverage affect unlevered free cash flow?","k":["No direct impact.","Unlevered FCF excludes interest and debt principal, so changing the capital structure leaves the metric unchanged."],"collection":"practice","topic":"DCF","tags":["Reported in Perella Weinberg Interview","First round","DCF","Basic"]},{"id":"q-1155","t":"val","l":"Basic","s":90,"q":"Given a WACC of 10%, a terminal growth rate of 5%, and Year 5 free cash flow of $100, solve for the terminal value.","k":["Answer: $2,100","Terminal Value = FCF x (1 + g) / (WACC - g)","TV = $100 x (1.05) / (0.10 - 0.05)","TV = $105 / 0.05 = $2,100","This is the terminal value as of the end of Year 5. It would still need to be discounted back to present value in a full DCF."],"collection":"practice","topic":"DCF","tags":["New","Reported in Perella Weinberg Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1156","t":"val","l":"Basic","s":90,"q":"How does leverage affect a DCF valuation?","k":["In an unlevered DCF (the standard approach), leverage affects the valuation through the discount rate (WACC), not through the cash flows themselves.","Adding debt reduces WACC (up to a point) because debt is cheaper than equity due to the interest tax shield. A lower WACC increases the present value of future cash flows, increasing Enterprise Value.","However, excessive leverage increases the risk of financial distress, causing both the cost of debt and cost of equity to rise, eventually increasing WACC.","The unlevered free cash flows themselves are capital-structure neutral (they exclude interest expense), so leverage only enters through the discount rate.","In a levered DCF, leverage directly affects the cash flows (interest expense reduces LFCF) and the discount rate is the cost of equity rather than WACC."],"collection":"practice","topic":"DCF","tags":["New","Reported in Perella Weinberg Interview","SA 2026, Superday","DCF","Basic"]},{"id":"q-1157","t":"val","l":"Basic","s":90,"q":"A company's equity beta is 1.3. If the S&P 500 goes up 13%, what will be the change in the stock price of that company?","k":["Answer: Approximately 16.9%.","Beta measures the sensitivity of a stock's returns to market returns.","Expected stock return = Beta x Market Return = 1.3 x 13% = 16.9%.","Note: In an interview, it is best to clarify that this is quick mental math. Technically, under CAPM, beta applies to the premium over the risk-free rate (E(R) = Rf + β(Rm - Rf)), so if the risk-free rate is greater than 0%, the actual expected return would be slightly lower. For example, with a 4% risk-free rate: 4% + 1.3 x (13% - 4%) = 15.7%."],"collection":"practice","topic":"DCF","tags":["New","Reported in PJT Partners Interview","SA 2025, Houston Office, First round","DCF","Basic"]},{"id":"q-1158","t":"val","l":"Basic","s":90,"q":"Comparing a utilities company to a coin flip, what would you expect the beta of each to be?","k":["A utilities company would have a low positive beta (around 0.3-0.5), while a coin flip would have a beta of 0.","A utilities company has stable, regulated cash flows with low correlation to the market, so its beta is low but still positive because it is not completely immune to economic conditions. A coin flip, by contrast, has a purely random outcome with zero correlation to the stock market, so its beta is exactly 0. This is a key distinction: low volatility is not the same as zero beta -- beta measures correlation with the market, not standalone risk."],"collection":"practice","topic":"DCF","tags":["New","Reported in RBC Interview","SA 2026, First round","DCF","Basic"]},{"id":"q-1159","t":"val","l":"Basic","s":90,"q":"How does an increase in A/R affect valuation in a DCF?","k":["It lowers the valuation.","An A/R build is a use of cash, raising ΔNWC and reducing Free Cash Flow in every forecast period.","Lower FCF, when discounted, translates into a smaller present value and lower enterprise (and equity) value."],"collection":"practice","topic":"DCF","tags":["Reported in Rothschild Interview","SA 2026","DCF","Basic"]},{"id":"q-1160","t":"val","l":"Basic","s":90,"q":"An asset is expected to generate $100 in cash flow each year into perpetuity.\n\n\n\n\nIf the appropriate discount rate is 10%, what is this asset worth today?","k":["Answer: $1,000","Calculation:","Perpetuity Value = Annual Cash Flow / Discount Rate","Perpetuity Value = $100 / 10% = $1,000"],"collection":"practice","topic":"DCF","tags":["Reported in Rothschild Interview","First round","DCF","Basic"]},{"id":"q-1161","t":"val","l":"Basic","s":90,"q":"What has a beta of 1?","k":["The market itself has a beta of 1. The S&P 500 (or whichever benchmark index is used as the market proxy) has a beta of exactly 1.0 by definition, since beta measures a stock's volatility relative to the overall market.","A stock with a beta of 1 moves in lockstep with the market. Beta > 1 means more volatile than the market (e.g., tech stocks, small caps). Beta < 1 means less volatile (e.g., utilities, consumer staples). Beta of 0 means no correlation to the market (e.g., a risk-free asset like a Treasury bill)."],"collection":"practice","topic":"DCF","tags":["New","Reported in Solomon Partners Interview","SA 2027, Generalist group, New York Office, Second round","DCF","Basic"]},{"id":"q-1162","t":"val","l":"Basic","s":90,"q":"Walk me through a DCF, and conceptually explain what WACC is.","k":["DCF steps:","Project unlevered FCF out over a reasonable horizon (i.e. 5-10 years).","Discount and sum those cash flows at WACC.","Calculate and add PV of terminal value (Gordon Growth or exit multiple).","WACC = blended opportunity cost to all capital providers weighted by their market value shares.","It reflects required return on a like‑risk asset and is the discount rate for enterprise‑level cash flows."],"collection":"practice","topic":"DCF","tags":["Reported in UBS Interview","SA 2026, New York office, Superday","DCF","Basic"]},{"id":"q-1163","t":"val","l":"Basic","s":90,"q":"Can a Discounted Cash Flow (DCF) analysis be used to calculate the value of synergies in a transaction? If so, how?","k":["Yes, DCF can value synergies.","Approach:","Build standalone DCF for target without synergies.","Separately forecast incremental cash flows from synergies (revenue growth, cost savings, reduced CapEx, working capital benefits).","Apply appropriate timing (e.g., phase in over 2-3 years).","Discount synergy cash flows at appropriate rate (potentially higher rate for execution risk).","Present value of synergy cash flows represents synergy value.","The sum of standalone value plus synergy value equals the combined company value. The difference between this and the acquisition price determines value creation."],"collection":"practice","topic":"DCF","tags":["Reported in Unspecified Interview","DCF","Basic"]},{"id":"q-1164","t":"val","l":"Basic","s":90,"q":"What is the effect of using the mid-year convention in a DCF analysis on the company's valuation?","k":["The mid-year convention assumes cash flows occur in the middle of each year rather than at year-end.","This results in a higher valuation because cash flows are discounted for 0.5 fewer years, increasing their present value.","The mid-year convention is generally more accurate as companies generate cash throughout the year, not just on December 31st.","Formula adjustment: Discount factor becomes 1/(1+r)^(n-0.5) instead of 1/(1+r)^n."],"collection":"practice","topic":"DCF","tags":["Reported in Unspecified Interview","Superday","DCF","Basic"]},{"id":"q-1165","t":"val","l":"Basic","s":90,"q":"What are the key drivers you would sensitize in a DCF model to see the impact on valuation?","k":["Key sensitivity drivers in a DCF:","Revenue growth rate (most impactful top-line driver).","EBITDA margin or operating margin (profitability).","WACC (discount rate reflecting risk).","Terminal growth rate (perpetuity value assumption).","Terminal multiple (alternative exit assumption).","CapEx as % of revenue (reinvestment needs).","Working capital changes (cash conversion).","Tax rate (affects after-tax cash flows).","Typically create 2-way sensitivity tables for WACC vs. terminal growth rate or terminal multiple."],"collection":"practice","topic":"DCF","tags":["Reported in Unspecified Interview","Superday","DCF","Basic"]},{"id":"q-1166","t":"val","l":"Advanced","s":90,"q":"Walk me through a DCF.\n\n\n\n\nFollow-up 1: Why use a 5-10 year projection?\n\n\n\n\nFollow-up 2: Could we do a 25-year DCF?","k":["DCF steps:","Project unlevered FCF for 5–10 years.","Estimate terminal value (Gordon Growth or exit multiple).","Discount both at WACC and sum to get enterprise value.","Follow‑ups:","Forecast accuracy drops sharply beyond 5–10 years; using that range balances visibility and value capture.","A 25‑year DCF is theoretically possible but small forecasting errors compound, so most value practitioners rely on a shorter explicit period plus a terminal value."],"collection":"practice","topic":"DCF","tags":["Reported in Allen & Company Interview","SA 2026","DCF","Advanced"]},{"id":"q-1167","t":"val","l":"Advanced","s":90,"q":"What is a levered DCF?\n\n\n\n\nFollow-up 1: What discount rate do you use?\n\n\n\n\nFollow-up 2: How do you calculate cost of equity?","k":["A levered DCF discounts cash flows after interest and mandatory principal at the Cost of Equity to value equity directly.","Follow‑ups:","The discount rate is the company’s Cost of Equity.","Cost of Equity = Risk‑free rate + Beta × Equity risk premium ± size/sector adjustments (CAPM)."],"collection":"practice","topic":"DCF","tags":["Reported in Allen & Company Interview","SA 2026","DCF","Advanced"]},{"id":"q-1168","t":"val","l":"Advanced","s":90,"q":"How would you factor cross-border risk in a DCF?","k":["To account for cross-border risk, you might add a country risk premium to the cost of equity. This premium reflects political, economic, and currency risks in the target country.","You also might adjust the discount rate to reflect higher uncertainty or incorporate scenario analyses to account for potential currency swings, regulatory changes, or macroeconomic volatility."],"collection":"practice","topic":"DCF","tags":["Reported in Bank of America Interview","DCF","Advanced"]},{"id":"q-1169","t":"val","l":"Advanced","s":90,"q":"A stable utility company shifts to renewables and a new business model.\n\n\n\n\nHow far out would you project cash flows, and what is the risk of using a shorter projection period?","k":["Project 10–15 years to capture the full transition, ramping renewables build-out and new model adoption. Longer asset useful lives in renewables (20–30 years) mean benefits accrue well beyond a 10-year window, which is another reason for a longer projection.","A shorter period pushes too much value into the terminal, making your valuation overly sensitive to exit assumptions. You risk missing multi-year capex and operational inflection points unique to the shift."],"collection":"practice","topic":"DCF","tags":["Reported in Bank of America Interview","DCF","Advanced"]},{"id":"q-1170","t":"val","l":"Advanced","s":90,"q":"You’re valuing a high-growth SaaS firm (30% growth, 30% margin) in a DCF.\n\n\n\n\nHow do you build projections, choose an EBITDA exit multiple for terminal value, and should you base the multiple on the final projected year or the following year?","k":["Key steps & guidance:","Build projections: Model revenue ramp from 30% toward a long-term stable rate (e.g. 3–5%), gradually expand margins from 30% to mature levels (40–45%) as fixed costs leverage out.","Choose exit multiple: Use public & M&A comps in a stable-growth SaaS group (e.g. 12–15× EBITDA), adjusted for size, growth differential, and margin profile.","Which year: If applying an LTM (Last Twelve Months) exit multiple, anchor it on the final year of your projection period (Year N). If applying an NTM (Next Twelve Months) forward multiple, apply it to the year after your projection period (Year N+1). Either way, it yields the Terminal Value at Year N."],"collection":"practice","topic":"DCF","tags":["Reported in Bank of America Interview","DCF","Advanced"]},{"id":"q-1171","t":"val","l":"Advanced","s":90,"q":"A company switches accounting from LIFO to FIFO.\n\n\n\n\nHow does that affect a DCF valuation?","k":["In an inflationary environment (rising costs), FIFO lowers cost of goods sold, raising EBITDA but also increasing taxes; inventory balances increase, which ties up cash in working capital and reduces free cash flow.","In a deflationary environment (falling costs), FIFO raises cost of goods sold, lowering EBITDA and taxes; inventory balances decrease, which releases working capital and increases free cash flow.","In your DCF you must project the new EBITDA, adjust the cash‐tax line accordingly, model the working capital changes, and base terminal value on the resulting free cash flow profile.","The net impact on enterprise value therefore depends on the relative size of the EBITDA change versus the changes in taxes and working‐capital cash flow","Keep in mind that these are simply different ways of recording the value of inventory (LIFO (last-in-first-out) = most recent inventory additions; FIFO (first-in-first-out) = oldest inventory additions). Revenue stays the same for both LIFO and FIFO."],"collection":"practice","topic":"DCF","tags":["Reported in Bank of America Interview","DCF","Advanced"]},{"id":"q-1172","t":"val","l":"Advanced","s":90,"q":"A video game company launches a game every 3 years. How would you approach doing a DCF for that company? And what about public comps?","k":["DCF Approach:","Use a longer projection period (9-12 years) to capture multiple full game cycles, ensuring the model reflects the cyclical revenue pattern.","Model the launch year with a revenue spike, followed by declining revenue in off-years as game sales tail off.","Separately project development costs (capitalized during development, then amortized post-launch) versus steady-state operating costs.","Normalize the terminal value by using an average of a full cycle's cash flows rather than a single peak or trough year.","Apply a higher discount rate or wider sensitivity range to reflect execution risk on future game launches.","Public Comps Approach:","Use NTM (next twelve months) or multi-year average multiples to smooth out cyclicality.","Select comps with similar release cadences (e.g., Take-Two, CD Projekt) rather than diversified publishers with annual franchises (e.g., EA, Activision).","Consider EV/Revenue on a normalized basis rather than current-year EBITDA if the company is in an off-cycle year with depressed earnings."],"collection":"practice","topic":"DCF","tags":["New","Reported in Bank of America Interview","SA 2025, First round","DCF","Advanced"]},{"id":"q-1173","t":"val","l":"Advanced","s":90,"q":"Why can't we use a DCF to value an oil and gas company?","k":["You can use a DCF, but a traditional DCF is problematic for E&P companies because:","Cash flows are heavily dependent on commodity prices, which are notoriously difficult to forecast over a 5-10 year projection period.","Oil and gas reserves are depleting assets with finite lives, so the perpetuity growth assumption in a terminal value calculation is inappropriate since reserves will eventually run out.","Production profiles are non-linear. Wells have steep initial decline curves followed by long tails, making simple growth-rate projections inaccurate.","Reserve replacement and exploration success are uncertain, making future production volumes speculative.","Instead, analysts typically use a Net Asset Value (NAV) model, which values each reserve category separately based on discounted future production at strip pricing."],"collection":"practice","topic":"DCF","tags":["New","Reported in Bank of America Interview","SA 2026, First round","DCF","Advanced"]},{"id":"q-1174","t":"val","l":"Advanced","s":90,"q":"Walk me from Net Income to EBIT, then EBITDA, then back to EBIT and get me to FCF, then walk me through a DCF.","k":["Net Income to EBIT: Add back interest and taxes to Net Income.","EBIT to EBITDA: Add back depreciation and amortization.","EBITDA back down to EBIT: Subtract depreciation and amortization again.","EBIT to FCF: Subtract taxes, add non-cash expenses, adjust for changes in working capital, and subtract capex to get unlevered free cash flow.","DCF: Project free cash flows over 5-10 years, discount them at WACC, and calculate a terminal value (exit multiple or perpetuity method). Discount the terminal value as well, sum to get enterprise value, then adjust for net debt to arrive at equity value."],"collection":"practice","topic":"DCF","tags":["Reported in BMO Interview","DCF","Advanced"]},{"id":"q-1175","t":"val","l":"Advanced","s":90,"q":"How do you account for Stock-Based Compensation (SBC) in a DCF?","k":["Stock-Based Compensation is a non-cash expense that should be added back in the cash flow statement when calculating unlevered free cash flow.","However, SBC creates real economic dilution to shareholders.","Two approaches to account for this dilution:","Add back SBC in cash flows but use diluted share count (including in-the-money options using treasury stock method) when calculating equity value per share.","Treat SBC as a real cash expense by not adding it back, keeping the basic share count.","Most practitioners use approach #1, as it better reflects the economic reality of dilution while maintaining consistency with accounting treatment."],"collection":"practice","topic":"DCF","tags":["Reported in Centerview Partners Interview","First round","DCF","Advanced"]},{"id":"q-1176","t":"val","l":"Advanced","s":90,"q":"How would you calculate cost of equity for a company whose cash flows are in a foreign currency?","k":["You could use CAPM but factor in a country risk premium if it’s an emerging market, or if currency risk is significant. Alternatively, you’d convert the cash flows to USD (if using USD-based CAPM) or use a local risk-free rate, local market risk premium, and local beta to do it in the foreign currency, then convert final values back to USD."],"collection":"practice","topic":"DCF","tags":["Reported in Citi Interview","DCF","Advanced"]},{"id":"q-1177","t":"val","l":"Advanced","s":90,"q":"What if you're 90% terminal value in a DCF?","k":["That suggests the company’s value is heavily in the terminal period, typical of high-growth or long-duration cash flows.","It also indicates forecasting uncertainty in earlier years and that small changes in the terminal assumptions (multiple or growth rate) can dramatically affect the valuation."],"collection":"practice","topic":"DCF","tags":["Reported in Citi Interview","DCF","Advanced"]},{"id":"q-1178","t":"val","l":"Advanced","s":90,"q":"Answer the following questions:\n\n\n\nWhat is Net Working Capital (NWC) given: Accounts Receivable = $100, Inventory = $20, and Accounts Payable = $20?\nWalk me from Revenue to Unlevered Free Cash Flow (UFCF).\nCalculate UFCF given: Revenue = $2,000, Gross Margin = 50%, SG&A = $500, Tax Rate = 25%, Capex = $100, D&A = $50, and NWC in the current year = $40. Assume the NWC from the previous part was for the prior year.","k":["Part 1: Net Working Capital","Answer: $100","NWC = AR + Inventory - AP","NWC = $100 + $20 - $20 = $100","Part 2: Revenue to UFCF","Revenue - COGS = Gross Profit","Gross Profit - SG&A - D&A = EBIT","EBIT * (1 - Tax Rate) = NOPAT","NOPAT + D&A - Capex - Increase in NWC = UFCF","Part 3: Calculate UFCF","Answer: $347.50","Revenue = $2,000","Gross Profit = $2,000 * 50% = $1,000","EBIT = $1,000 - $500 - $50 = $450","NOPAT = $450 * (1 - 25%) = $337.50","Change in NWC = $40 - $100 = -$60 (decrease)","UFCF = $337.50 + $50 - $100 - (-$60) = $347.50","Note: The decrease in NWC is a source of cash, so we add it back in the UFCF calculation."],"collection":"practice","topic":"DCF","tags":["Reported in Citi Interview","Superday","DCF","Advanced"]},{"id":"q-1179","t":"val","l":"Advanced","s":90,"q":"What can you tell us about a company where the cost of debt is greater than the WACC?","k":["This is highly unusual under normal circumstances, since WACC is a weighted average of the cost of debt and cost of equity, and the cost of equity is virtually always higher than the cost of debt.","If this scenario appears to hold, it likely indicates:","The company has convertible debt that has been misclassified or mispriced. Convertible debt has a lower stated yield than straight debt because of the embedded equity option, which can distort the apparent cost of debt.","The company's equity beta is very low or negative (possible for certain counter-cyclical industries), compressing the cost of equity below the cost of debt.","The capital structure is almost entirely equity with negligible debt, so even expensive debt barely moves the WACC above the cost of equity.","This is a trick question: in practice, the cost of debt should always be below WACC since equity carries higher risk."],"collection":"practice","topic":"DCF","tags":["New","Reported in Citi Interview","SA 2026, First round","DCF","Advanced"]},{"id":"q-1180","t":"val","l":"Advanced","s":90,"q":"A company has convertible bonds where the cost of debt appears to exceed its WACC. Which is a better option moving forward: selling the convertible bonds or exercising them into equity?","k":["It depends on whether the convertible bond is in-the-money.","If the convertible is in-the-money (stock price exceeds conversion price): Exercising into equity is likely better. The company eliminates the expensive debt obligation, reduces interest expense, and the equity dilution is offset by the favorable conversion economics.","If the convertible is out-of-the-money: Selling the bond in the open market is preferable. The holder receives the bond's market value (which includes the time value of the conversion option) without taking on equity at an unfavorable conversion ratio.","From the company's perspective, if it wants to reduce its cost of capital, forcing conversion (via a call provision) when the bond is in-the-money is the best route since it replaces high-cost debt with equity and lowers overall WACC."],"collection":"practice","topic":"DCF","tags":["New","Reported in Citi Interview","SA 2026, First round","DCF","Advanced"]},{"id":"q-1181","t":"val","l":"Advanced","s":90,"q":"Walk me through a DCF for a solar farm, starting with how you would project revenue and cash flows.","k":["Revenue Projection:","Capacity (MW) * Capacity Factor (%) * Hours per Year * Power Price ($/MWh).","Consider Power Purchase Agreements (PPAs) with fixed pricing or merchant exposure to spot prices.","Account for degradation (typically 0.5% annually).","Cash Flow Projection:","Revenue - Operating Costs (O&M, insurance, land lease).","Subtract taxes (consider ITC or PTC benefits).","Subtract minimal maintenance CapEx.","Minimal working capital needs.","Terminal Value:","Use perpetuity with low/zero growth or asset salvage value.","Consider useful life (typically 25-30 years).","Discount Rate:","Use project WACC reflecting contracted cash flows and asset-backed financing."],"collection":"practice","topic":"DCF","tags":["Reported in Credit Suisse Interview","Energy & Infrastructure group, First round","DCF","Advanced"]},{"id":"q-1182","t":"val","l":"Advanced","s":90,"q":"Which of the following has a greater impact in a DCF valuation? A $1 increase in revenue, a $1 increase in cash OpEx, or a $1 increase in changes in NWC?\n\n\n\n\nRank them from greatest to least impact.","k":["NWC > OpEx > Revenue.","The greatest impact is from changes in NWC, followed by cash OpEx, and then revenue.","NWC has the largest effect because it impacts cash flows directly without influencing taxes (it is applied after taxes in the model).","Cash OpEx ranks higher than revenue because increasing revenue also drives up COGS, partially offsetting its effect.","Caveat: This ranking assumes the changes occur during the explicit projection period. If the change occurs in the terminal year (assuming an Exit Multiple method), the order flips to OpEx > Revenue > NWC, because OpEx and Revenue permanently affect EBITDA (the driver of Terminal Value), whereas NWC changes do not."],"collection":"practice","topic":"DCF","tags":["Reported in Evercore Interview","DCF","Advanced"]},{"id":"q-1183","t":"val","l":"Advanced","s":90,"q":"As an investor who uses a DCF, would you rather have a $10 increase in revenue, a $10 increase in gross profit, or a $10 decrease in CapEx?\n\n\n\n\nRank them from greatest to least impact.","k":["The most impactful would be a decrease in CapEx (no tax impact), followed by an increase in gross profit, and then an increase in revenue (since revenue growth also drives up COGS)."],"collection":"practice","topic":"DCF","tags":["Reported in Evercore Interview","DCF","Advanced"]},{"id":"q-1184","t":"val","l":"Advanced","s":90,"q":"Assuming a 40% tax rate, which of the following three scenarios has the biggest impact on Free Cash Flow?\n\n\n\nA $10 increase in Revenue\nA $10 decrease in Depreciation\nA $10 decrease in CapEx\n\n\n\nFollow-up: Which of these would have the biggest impact on the terminal value in a DCF?","k":["Part 1: FCF Impact","A $10 decrease in CapEx has the biggest positive impact on FCF.","Impact Analysis:","$10 Decrease in CapEx: This is a direct cash savings. FCF increases by +$10.","$10 Increase in Revenue: This increases after-tax profit. Assuming for simplicity a 100% margin, Pre-tax Income rises by $10, and Net Income rises by $6 ($10 × (1-40%)). FCF increases by +$6. (The actual impact would be lower depending on the company's true operating margin).","$10 Decrease in Depreciation: This increases Pre-tax Income by $10, which increases taxes by $4 ($10 × 40%). Because depreciation is a non-cash expense that is added back, the net impact is the loss of the tax shield. FCF decreases by -$4.","Ranking by Impact: The ranking from most positive to most negative impact on FCF is: (3) CapEx Decrease > (1) Revenue Increase > (2) Depreciation Decrease.","Part 2: Terminal Value Impact","The $10 increase in Revenue has the biggest impact on the terminal value.","Terminal value calculations (both perpetuity growth and exit multiple methods) are based on the final year's cash flow or EBITDA. A revenue increase grows the base for all future periods, compounding its effect into perpetuity, whereas a change in CapEx or Depreciation is a one-time adjustment in the terminal year calculation."],"collection":"practice","topic":"DCF","tags":["Reported in Evercore Interview","New York Office, Second round","DCF","Advanced"]},{"id":"q-1185","t":"val","l":"Advanced","s":90,"q":"If WACC increases, can the Present Value in a DCF also increase?","k":["Yes, in rare cases where future cash flows are negative (cash outflows).","Typically, higher WACC reduces PV since future positive cash flows are discounted more heavily. However, if a project has significant upfront investment followed by negative terminal cash flows (e.g., decommissioning costs), a higher discount rate would reduce the PV of those negative flows, potentially increasing net present value.","In practice, this is extremely rare and DCF valuations almost always decrease with higher WACC."],"collection":"practice","topic":"DCF","tags":["Reported in Evercore Interview","First round","DCF","Advanced"]},{"id":"q-1186","t":"val","l":"Advanced","s":90,"q":"Part 1: If one company generates 90% of its free cash flow in Year 1 and the remainder over the next 9 years, and another company generates 10% of its free cash flow evenly each year for 10 years, which company would you rather invest in?\n\n\n\n\nPart 2: Which company would produce a higher DCF valuation, and why?","k":["Part 1","You would rather invest in the first company (90% in Year 1). Receiving cash sooner is more valuable due to the time value of money. Earlier cash flows can be reinvested for compounding returns, and there is less uncertainty around near-term cash flows.","Part 2","The first company produces a higher DCF valuation, assuming the same total undiscounted cash flows. Since the majority of cash flows arrive in Year 1, they are discounted by only one year. The second company's cash flows arrive later and are discounted more heavily, reducing their present value. The farther out cash flows are, the more they are penalized by the discount rate."],"collection":"practice","topic":"DCF","tags":["New","Reported in Evercore Interview","SA 2025, Second round","DCF","Advanced"]},{"id":"q-1187","t":"val","l":"Advanced","s":90,"q":"How would you perform a DCF for a company that only has one year of operating history?","k":["Rely heavily on industry benchmarks and comparable company data to build projections, since one year of history is insufficient to establish trends.","Use management guidance and business plan projections as the basis for the forecast, but stress-test assumptions aggressively.","Extend the projection period (e.g., 10+ years instead of 5) to allow the company to reach steady state before applying a terminal value.","Use scenario analysis (bull, base, bear) to capture the wide range of potential outcomes, since there is limited historical data to anchor on.","Apply a higher discount rate or add a size premium / company-specific risk premium to WACC to reflect the elevated uncertainty.","Consider supplementing the DCF with other valuation methods (comparable companies, comparable transactions) that may be more reliable when historical data is sparse."],"collection":"practice","topic":"DCF","tags":["New","Reported in Evercore Interview","SA 2025, Superday","DCF","Advanced"]},{"id":"q-1188","t":"val","l":"Advanced","s":90,"q":"If you increase the pre-tax cost of debt by 200 basis points from 8% and simultaneously decrease the tax rate from 25% to 15%, does WACC increase by more or less than 200 basis points?","k":["The WACC impact on the debt component depends on the after-tax cost of debt.","Before: After-tax cost of debt = 8% x (1 - 25%) = 6.00%","After: After-tax cost of debt = 10% x (1 - 15%) = 8.50%","Change in after-tax cost of debt = 8.50% - 6.00% = 2.50%, or 250 bps","The after-tax cost of debt increases by 250 bps, which is more than 200 bps. The cost of equity is not directly affected by the tax rate (CAPM does not include a tax rate input), so it stays the same. However, the lower tax rate reduces the tax shield on debt, amplifying the WACC increase. Overall, the WACC increase on the debt component exceeds 200 bps. The total WACC change depends on the capital structure weights, but the debt portion alone increases by more than 200 bps."],"collection":"practice","topic":"DCF","tags":["New","Reported in Evercore Interview","SA 2027","DCF","Advanced"]},{"id":"q-1189","t":"val","l":"Advanced","s":90,"q":"In Year 1, a company had a pre-tax cost of debt of 8% and a 25% tax rate. In Year 2, it had a pre-tax cost of debt that was 200 basis points higher (10%) and a 15% tax rate. What is the effect on WACC?\n\n\n\n\nFollow-up: Is the effect on WACC larger or smaller than the 200 basis point increase in pre-tax cost of debt?","k":["The after-tax cost of debt increased by 250 basis points, which increases WACC (holding capital structure and cost of equity constant).","Calculation:","Year 1 after-tax cost of debt = 8% x (1 - 25%) = 8% x 0.75 = 6.0%","Year 2 after-tax cost of debt = 10% x (1 - 15%) = 10% x 0.85 = 8.5%","Change in after-tax cost of debt = 8.5% - 6.0% = +2.5 percentage points (250 bps)","Follow-up: Larger or Smaller Than 200 bps?","The effect is larger than the 200 basis point increase in pre-tax cost of debt. Two forces compound in the same direction:","The pre-tax cost of debt increased by 200 bps (from 8% to 10%).","The tax rate decreased from 25% to 15%, reducing the value of the tax shield on interest expense.","Both effects increase the after-tax cost of debt. The lower tax rate means less of the interest expense is deductible, amplifying the impact beyond the 200 bps pre-tax increase. The net result is a 250 bps increase in the after-tax cost of debt."],"collection":"practice","topic":"DCF","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, Superday","DCF","Advanced"]},{"id":"q-1190","t":"val","l":"Advanced","s":90,"q":"If you could only see one number from an analyst's DCF model to determine the Enterprise Value, which number would you choose?","k":["The terminal value.","Terminal value typically represents 60-80% of total enterprise value in a DCF model, as it captures all cash flows beyond the explicit forecast period. Knowing the terminal value and assuming a reasonable PV of forecast period cash flows would give you a strong approximation of enterprise value.","Alternative answer: WACC, since combined with cash flow assumptions you could reconstruct the valuation."],"collection":"practice","topic":"DCF","tags":["Reported in Goldman Sachs Interview","New York office","DCF","Advanced"]},{"id":"q-1191","t":"val","l":"Advanced","s":90,"q":"If your terminal value assumptions in a DCF imply a perpetuity growth rate of 6%, what does that signify and what adjustments should you make?","k":["A 6% perpetuity growth rate is unrealistically high and implies the company will grow faster than GDP indefinitely.","Adjustments:","Reduce the growth rate to 2-3% (closer to long-term GDP growth).","Alternatively, use an exit multiple approach instead of perpetuity growth.","Review your terminal year assumptions to ensure they're sustainable.","Consider if you're in a high-growth year that shouldn't be perpetualized."],"collection":"practice","topic":"DCF","tags":["Reported in Goldman Sachs Interview","Superday","DCF","Advanced"]},{"id":"q-1192","t":"val","l":"Advanced","s":90,"q":"A company discovers its annual depreciation was understated by $10 million. After correcting this accounting error, what is the net impact on its Unlevered Free Cash Flow? Assume a 40% tax rate.","k":["Answer: +$4M increase","Correcting the depreciation error increases depreciation expense, which reduces pre-tax income and taxes, but depreciation is a non-cash expense that gets added back in the cash flow calculation.","Higher Depreciation reduces Pre-Tax Income by $10M","This reduces Taxes by $10M * 40% = $4M","Net Income decreases by $10M * (1 - 40%) = $6M","In UFCF: Start with lower NI (-$6M)","Add back higher Depreciation (+$10M)","Net impact = -$6M + $10M = +$4M","The tax shield from additional depreciation increases UFCF by $4M."],"collection":"practice","topic":"DCF","tags":["Reported in Goldman Sachs Interview","Superday","DCF","Advanced"]},{"id":"q-1193","t":"val","l":"Advanced","s":90,"q":"Part 1: Walk me through the top-down and bottom-up approaches to calculating Unlevered Free Cash Flow.\n\n\n\n\nPart 2: What is the impact on each approach if interest expenses become non-tax-deductible in nature?","k":["Part 1","Top-Down (starts from EBITDA):","EBITDA - D&A = EBIT","EBIT x (1 - Tax Rate) = NOPAT (tax-effect at the unlevered level)","NOPAT + D&A - CapEx - Change in NWC = UFCF","Bottom-Up (starts from Net Income):","Net Income + Interest Expense x (1 - Tax Rate) + D&A - CapEx - Change in NWC = UFCF","We add back after-tax interest to \"unlever\" Net Income (removing the impact of the capital structure).","Part 2: If Interest Becomes Non-Tax-Deductible","Top-Down: No change. The top-down approach starts above interest expense (at EBITDA or EBIT) and applies a hypothetical tax rate to EBIT. It never references actual interest expense, so it is unaffected.","Bottom-Up: You would add back the full interest expense (not after-tax). The formula changes to: Net Income + Interest Expense (full amount, no tax shield) + D&A - CapEx - Change in NWC. Since interest is no longer tax-deductible, Net Income is lower (higher taxes), but you add back a larger interest amount, and the result is the same UFCF."],"collection":"practice","topic":"DCF","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","DCF","Advanced"]},{"id":"q-1194","t":"val","l":"Advanced","s":90,"q":"If depreciation increases, what is the impact on a DCF valuation versus an LBO?","k":["DCF Impact:","Higher depreciation increases UFCF by the depreciation tax shield (D&A increase x Tax Rate). EBIT falls, but the D&A add-back more than offsets the NOPAT reduction, creating a net cash benefit from lower taxes. This increases the DCF valuation.","LBO Impact:","Higher depreciation increases the LBO valuation. The tax shield from depreciation reduces taxes and increases free cash flow available for debt repayment. More debt paydown means higher exit equity and returns, allowing the sponsor to pay a higher entry price for the same target IRR."],"collection":"practice","topic":"DCF","tags":["New","Reported in Goldman Sachs Interview","SA 2026, First round","DCF","Advanced"]},{"id":"q-1195","t":"val","l":"Advanced","s":90,"q":"Why would two companies with identical cash flows have different DCF values using the Gordon Growth Method?","k":["Two companies with identical current cash flows can have different DCF values due to differences in:","Discount rate (WACC): A company with higher risk (higher beta, more leverage, smaller size) has a higher WACC, which reduces the present value of its cash flows. The Gordon Growth formula (FCF x (1+g) / (WACC - g)) is extremely sensitive to WACC.","Growth rate (g): Even with the same current cash flows, if one company is expected to grow faster in perpetuity, it will have a higher Terminal Value and thus a higher DCF value.","Different WACCs and growth rates produce dramatically different denominators in the Gordon Growth formula. A small change in (WACC - g) causes a large change in Terminal Value.","Example: Company A (WACC 10%, g 3%) TV denominator = 7%. Company B (WACC 12%, g 2%) TV denominator = 10%. Company A's TV is ~43% higher per dollar of FCF."],"collection":"practice","topic":"DCF","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, First round","DCF","Advanced"]},{"id":"q-1196","t":"val","l":"Advanced","s":90,"q":"Part 1: Kevin gives you $25 a year for the rest of your life. What is this money worth to you?\n\n\n\n\nPart 2: What would your personal discount rate be? Justify it.\n\n\n\n\nPart 3: He gives you a discount rate of 4%. Calculate the net present value.","k":["Part 1:","This is a perpetuity. The value = Annual Payment / Discount Rate = $25 / r. The answer depends on your discount rate.","Part 2:","A reasonable personal discount rate might be 8-12%. Justification: you could invest in a diversified equity portfolio returning ~8-10% annually, and there is counterparty risk that Kevin might stop paying. A higher discount rate reflects the uncertainty and opportunity cost of tying up capital in this stream.","Part 3:","Answer: $625","Perpetuity Value = $25 / 0.04 = $625","You would pay up to $625 today for this perpetual cash flow stream."],"collection":"practice","topic":"DCF","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027","DCF","Advanced"]},{"id":"q-1197","t":"val","l":"Advanced","s":90,"q":"If Company A starts taking on some debt, how will its WACC change compared to Company B, which has no debt? At what point does the WACC stop decreasing?","k":["Initially, Company A's WACC will decrease below Company B's because debt is cheaper than equity due to the tax shield (interest is tax-deductible).","WACC stops decreasing at the optimal capital structure, the point where the marginal benefit of the tax shield is offset by the increasing costs of financial distress. Beyond this point:","Lenders demand higher interest rates due to increased default risk.","Equity investors require a higher return to compensate for the risk of leverage.","Both cost of debt and cost of equity rise, causing WACC to increase.","This is the trade-off theory of capital structure. The exact tipping point depends on the company's cash flow stability, asset base, and industry norms."],"collection":"practice","topic":"DCF","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, First round","DCF","Advanced"]},{"id":"q-1198","t":"val","l":"Advanced","s":90,"q":"If you are performing a DCF for a company in a cyclical industry, what are the complications and how would you adjust your approach?","k":["Complications:","Revenue and margins fluctuate significantly with economic cycles, making projections unreliable.","If the company is at a peak, projections may overstate long-term cash flows. If at a trough, they may understate them.","Terminal value assumptions (growth rate, multiple) are difficult to set.","Adjustments:","Use a longer projection period (10+ years) to capture a full cycle.","Normalize EBITDA and margins to mid-cycle levels rather than using peak or trough figures.","Apply a mid-cycle exit multiple for terminal value.","Sensitize heavily around commodity prices, volumes, and margin assumptions.","Consider using EV/EBITDA comps at different points in the cycle for context."],"collection":"practice","topic":"DCF","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","DCF","Advanced"]},{"id":"q-1199","t":"val","l":"Advanced","s":90,"q":"Part 1: You have two companies that are identical except one has 100% equity and the other has a significant amount of debt. Which company has a lower WACC?\n\n\n\n\nFollow-up: At what point would the company with debt start to have a higher WACC than the all-equity company?","k":["Part 1","The company with debt has a lower WACC, up to a point. Debt is cheaper than equity due to the tax deductibility of interest (interest tax shield). Adding debt to the capital structure lowers WACC because you are replacing expensive equity with cheaper after-tax debt.","Follow-up","At excessive leverage levels, the company with debt will have a higher WACC. As debt increases:","Cost of debt rises as lenders demand higher interest rates to compensate for increased default risk.","Cost of equity rises as equity holders face greater financial risk (higher beta) from the levered capital structure.","At the point where the incremental increase in both Rd and Re outweighs the tax benefit of additional debt, WACC begins to rise.","This is the essence of the trade-off theory of capital structure -- there is an optimal leverage ratio that minimizes WACC."],"collection":"practice","topic":"DCF","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027","DCF","Advanced"]},{"id":"q-1200","t":"val","l":"Advanced","s":90,"q":"You are working on a DCF in September 2025 and then you set it aside. You pick it back up in December 2025 and the projections for future cash flows are exactly the same. Is the valuation higher or lower than before?","k":["The valuation is higher in December 2025.","The DCF discounts future cash flows back to the present date. When you move from September to December, three months have passed, meaning:","All future cash flows are now 3 months closer in time. Closer cash flows are discounted less, so their present values increase.","If projections are identical, the first projected year's cash flow is now only 9 months away instead of 12 months, and every subsequent cash flow is similarly 3 months closer.","This \"rolling forward\" effect increases the present value of every future cash flow, resulting in a higher overall valuation.","This is analogous to the time value of money: the same future dollar is worth more today when it is closer to being received."],"collection":"practice","topic":"DCF","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027","DCF","Advanced"]},{"id":"q-1201","t":"val","l":"Advanced","s":90,"q":"How do you handle changes to debt levels in your cost of debt and WACC for an all-equity company that “matures” in 10 years?","k":["Even if the company is all equity now, you might assume it will add debt as it matures. You can model a target capital structure for year 10 and gradually move the WACC toward that.","Alternatively, you keep a pure equity discount rate but mention that if the company leverages, the cost of debt would be factored in once it’s introduced."],"collection":"practice","topic":"DCF","tags":["Reported in Greenhill & Co. Interview","DCF","Advanced"]},{"id":"q-1202","t":"val","l":"Advanced","s":90,"q":"If WACC is 10%, the Cost of Equity is 15%, and a project's IRR is 10%, would you make the investment? Why or why not?","k":["The company would be indifferent — but would likely accept the project.","The correct hurdle rate for evaluating a project is WACC (10%), not the Cost of Equity alone. WACC represents the blended cost of all capital (debt and equity) used to fund the project. Since the project's IRR of 10% exactly equals the WACC of 10%, the project's NPV is zero — it earns exactly the cost of capital and creates zero incremental value for shareholders.","An NPV of zero means the company is economically indifferent: the project returns just enough to compensate all capital providers. In practice, most firms would still accept the project since it meets the minimum hurdle rate, but it is not a strong \"yes\" — there is no margin of safety, and any execution shortfall would destroy value. This is meaningfully different from a project with IRR above WACC, which would have a positive NPV and clearly create value.","You would only use the Cost of Equity (15%) as the hurdle rate if the project were funded entirely with equity and no debt."],"collection":"practice","topic":"DCF","tags":["New","Reported in Houlihan Lokey Interview","SA 2027, Business Services group, LA Office, First round","DCF","Advanced"]},{"id":"q-1203","t":"val","l":"Advanced","s":90,"q":"What are three ways that a change in interest rates can affect a DCF valuation?","k":["Three ways interest rates impact DCF:","Discount Rate (WACC): Higher rates increase WACC (both risk-free rate and cost of debt rise), reducing PV of cash flows and lowering valuation.","Cash Flows (Interest Expense): Higher rates increase interest expense on debt, reducing Net Income and Free Cash Flow, lowering valuation.","Terminal Value: Higher discount rate reduces the present value of terminal value, which typically comprises 50-80% of total DCF value, materially lowering valuation.","Net effect: Rising interest rates compress valuations through multiple channels. Falling rates have the opposite effect."],"collection":"practice","topic":"DCF","tags":["Reported in J.P. Morgan Interview","SA 2025","DCF","Advanced"]},{"id":"q-1204","t":"val","l":"Advanced","s":90,"q":"If an analyst miscalculates Depreciation & Amortization to be 50% too low, how would correcting this error affect a DCF valuation?","k":["Valuation would increase.","Analysis:","Correcting D&A upward increases the D&A add-back in FCF.","EBIT decreases, but the tax shield increases (lower taxes).","Net effect: Higher FCF due to the non-cash add-back exceeding the tax impact.","Higher FCF leads to higher present value and thus higher valuation."],"collection":"practice","topic":"DCF","tags":["Reported in J.P. Morgan Interview","Second round","DCF","Advanced"]},{"id":"q-1205","t":"val","l":"Advanced","s":90,"q":"When would it be appropriate to use a negative growth rate in the perpetuity calculation of a DCF?","k":["Use a negative growth rate when the company is in structural decline:","Obsolete technology or products (e.g., print newspapers, DVDs).","Shrinking end markets with no pivot strategy.","Regulated industries facing phase-outs (e.g., coal power plants).","Companies with depleting natural resources.","A negative growth rate reflects the reality that cash flows will decline perpetually."],"collection":"practice","topic":"DCF","tags":["Reported in J.P. Morgan Interview","Second round","DCF","Advanced"]},{"id":"q-1206","t":"val","l":"Advanced","s":90,"q":"What does a DCF look like for a pre-revenue company?","k":["A DCF for a pre-revenue company differs from a standard DCF in several key ways:","Longer projection period: You may need 10-15+ years to capture the ramp from zero revenue through commercialization to steady-state profitability.","Negative near-term cash flows: The company is burning cash on R&D and operations, so early-year FCFs are negative.","Higher discount rate: A higher WACC or cost of equity reflects the elevated risk of a company with no proven revenue. Some analysts use venture-level discount rates (20-40%).","Probability weighting: In biotech, you probability-weight cash flows by the likelihood of clinical trial success (risk-adjusted NPV or \"rNPV\").","Terminal value is uncertain: The growth rate assumption is harder to justify. Some use an exit multiple on projected steady-state EBITDA; others use the perpetuity growth method with conservative assumptions."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","DCF","Advanced"]},{"id":"q-1207","t":"val","l":"Advanced","s":90,"q":"Why would Terminal Value be negative for a company that has an expiring patent?","k":["Terminal Value could be negative if the company's cash flows are expected to decline permanently after the patent expires and the perpetuity growth rate used in the Gordon Growth Method is negative enough to produce a negative value.","More practically, when a key patent expires, generic competitors enter the market and revenue can drop 80-90%. If the company has no other meaningful products in its pipeline, its terminal year free cash flow could be near zero or negative (operating costs exceed dwindling revenue). Using the Gordon Growth Method with a significantly negative growth rate, or simply projecting the business declining to zero, the Terminal Value approaches zero or turns negative.","This is why single-drug biotech companies are often valued using a finite projection DCF with no terminal value, rather than assuming a perpetuity. The company's value is entirely captured in the finite patent life cash flows."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","DCF","Advanced"]},{"id":"q-1208","t":"val","l":"Advanced","s":90,"q":"Walk me from Levered Free Cash Flow to share price in a DCF.","k":["Project Levered Free Cash Flows over the forecast period (5-10 years).","Calculate Terminal Value using the Gordon Growth Method or Exit Multiple, applied to terminal year LFCF or Net Income.","Discount all projected LFCFs and the Terminal Value back to the present using the Cost of Equity (not WACC, since LFCF already accounts for debt).","Sum the PV of LFCFs + PV of Terminal Value = Equity Value directly.","Divide Equity Value by Diluted Shares Outstanding = Implied Share Price.","The key difference from an unlevered DCF: you skip the EV-to-equity bridge (subtracting net debt) because LFCF already reflects debt service costs, so the output is Equity Value directly."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","DCF","Advanced"]},{"id":"q-1209","t":"val","l":"Advanced","s":90,"q":"Whose WACC would change more if interest rates changed: a mature company with 25% debt in its capital structure, or a pre-revenue company with no debt? Does this conceptually make sense?","k":["The pre-revenue company with no debt (100% equity) would see a larger change in WACC.","Assume a 25% tax rate. If interest rates rise by 1%:","100% equity company: WACC = 100% x Ke. The cost of equity rises by 1% (via the risk-free rate in CAPM), so WACC rises by the full 1.0% (1.0x sensitivity).","25% debt company: WACC = 75% x Ke + 25% x Kd x (1 - 25%). Ke rises by 1% (contributing 0.75%), and Kd rises by 1% (contributing 0.25 x 0.75 = 0.1875%). Total WACC increase = 0.9375% (0.9375x sensitivity).","The 100% equity company has higher sensitivity (1.0x vs. 0.9375x) because the tax shield on debt dampens the impact of rising rates on the debt portion of WACC. The after-tax cost of debt rises by less than the pre-tax rate increase, so having debt in the capital structure actually provides a small buffer against interest rate changes.","Conceptually this makes sense: the tax deductibility of interest partially offsets the rate increase on the debt side, so a company with some debt is slightly less exposed to rate changes than a pure-equity company."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","DCF","Advanced"]},{"id":"q-1210","t":"val","l":"Advanced","s":90,"q":"Walk me from Revenue to a DCF valuation. Explain the key assumptions you would make at each step.","k":["Revenue: Forecast based on market size, growth rate, pricing assumptions, and competitive dynamics. Key assumption: revenue growth rate.","Less: COGS (gross margin assumption based on industry benchmarks and company trends) = Gross Profit.","Less: Operating Expenses (SG&A, R&D as % of revenue) = EBITDA. Key assumption: margin trajectory.","Less: D&A (based on existing asset base + new CapEx) = EBIT.","Less: Taxes on EBIT at the effective tax rate = NOPAT.","Plus: D&A (non-cash add-back).","Less: CapEx (assumption: maintenance vs. growth CapEx as % of revenue).","Less: Increase in Net Working Capital (driven by DSO, DIO, DPO assumptions) = UFCF.","Discount UFCF at WACC. Key assumptions: risk-free rate, beta, ERP for cost of equity; credit spread for cost of debt; target capital structure weights.","Calculate Terminal Value using Gordon Growth (long-term growth rate, typically 2-3%) or Exit Multiple (based on comparable multiples). Discount TV to present.","Sum PV of FCFs + PV of TV = Enterprise Value. Subtract net debt = Equity Value. Divide by diluted shares = Implied Share Price."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2025, Healthcare group, SF Office, Superday","DCF","Advanced"]},{"id":"q-1211","t":"val","l":"Advanced","s":90,"q":"How would you perform a DCF without forward projections from management, using only past financials?","k":["You would build your own projections using historical financials as the foundation:","Revenue: Use historical revenue growth rates (3-5 year CAGR) and apply them forward, adjusted for industry trends and competitive position.","Margins: Use historical EBITDA and operating margins as a baseline, adjusting for any known one-time items or structural changes.","CapEx & D&A: Use CapEx as a % of revenue or as a ratio to D&A based on historical patterns.","Working Capital: Model changes in NWC based on historical days sales outstanding, days payable outstanding, and inventory turnover.","Tax Rate: Use the effective tax rate from recent years.","You can also supplement with sell-side analyst estimates (consensus), industry benchmarks, and comparable company performance. The key is being transparent about your assumptions and running sensitivity analysis on key drivers."],"collection":"practice","topic":"DCF","tags":["New","Reported in J.P. Morgan Interview","SA 2025","DCF","Advanced"]},{"id":"q-1212","t":"val","l":"Advanced","s":90,"q":"What does a levered DCF represent, conceptually?","k":["It discounts the cash flows left after debt service to equity holders at the Cost of Equity, giving equity value directly and therefore embedding the capital structure in the valuation."],"collection":"practice","topic":"DCF","tags":["Reported in Jefferies Interview","SA 2026","DCF","Advanced"]},{"id":"q-1213","t":"val","l":"Advanced","s":90,"q":"Revenues = 1000, COGS + SG&A = 400, D&A = 200, Capex = 100, tax rate = 10%.\n\n\n\n\nLast year NWC was 150; this year it's 175. Calculate FCF.","k":["Answer: $435","EBIT = 1000 − 400 − 200 = 400","NOPAT = 400 × 0.9 = 360","Add back D&A: +200","Less Capex: −100","Less ΔNWC: 175 − 150 = 25","FCF = 360 + 200 − 100 − 25 = 435"],"collection":"practice","topic":"DCF","tags":["Reported in Jefferies Interview","SA 2026","DCF","Advanced"]},{"id":"q-1214","t":"val","l":"Advanced","s":90,"q":"Why is WACC U-shaped?","k":["As you initially add debt to a capital structure, WACC decreases due to the tax shield on debt (lower cost than equity). But if you add too much debt, financial distress risk rises, pushing the cost of both debt and equity higher.","So at low leverage, adding debt lowers WACC; at high leverage, adding debt raises WACC. This creates a U-shaped curve."],"collection":"practice","topic":"DCF","tags":["Reported in Lazard Interview","DCF","Advanced"]},{"id":"q-1215","t":"val","l":"Advanced","s":90,"q":"Discuss the key components and assumptions involved in deriving a discount rate for a DCF analysis.\n\n\n\n\nSpecifically address the risk-free rate, equity risk premium (ERP), size premium, and country risk premium.","k":["Key discount rate components:","Risk-Free Rate: Typically 10-year government bond yield, representing time value of money without risk.","Equity Risk Premium (ERP): Additional return investors demand for equity vs. risk-free assets (typically 5-7%).","Beta: Measures systematic risk relative to market, multiplied by ERP in CAPM.","Size Premium: Small-cap stocks require higher returns due to liquidity and risk (0-3%).","Country Risk Premium: Additional return for emerging market or political risk, added for non-US companies.","Cost of Equity = Risk-Free Rate + (Beta × ERP) + Size Premium + Country Risk Premium","WACC then blends Cost of Equity with after-tax Cost of Debt based on target capital structure."],"collection":"practice","topic":"DCF","tags":["Reported in Lazard Interview","New York Office, Second round","DCF","Advanced"]},{"id":"q-1216","t":"val","l":"Advanced","s":90,"q":"What are two ways stock-based compensation affects a DCF valuation?","k":["Free cash flow: SBC is a non-cash expense added back when calculating UFCF, which increases projected cash flows and, all else equal, increases the DCF valuation. However, many analysts argue SBC should not be added back because it represents a real economic cost (dilution).","Share count dilution: Options and RSUs increase the diluted share count used to calculate implied share price (Equity Value / Diluted Shares). A higher diluted share count reduces the per-share value even if total equity value is higher.","The net effect depends on how SBC is treated. If SBC is added back to FCF but the diluted share count is increased, the two effects partially offset each other."],"collection":"practice","topic":"DCF","tags":["New","Reported in Lazard Interview","SA 2025, SF Office, First round","DCF","Advanced"]},{"id":"q-1217","t":"val","l":"Advanced","s":90,"q":"What is the difference between DCF and LBO cash flows, from revenue down?\n\n\n\n\n(UFCF vs. LFCF)","k":["From Revenue Down:","DCF: EBIT × (1 − Tax) + D&A and other non-cash items − CapEx − ΔNWC → Unlevered Free Cash Flow.","LBO: Net Income + D&A and other non-cash items − CapEx − ΔNWC − Debt service → Levered Free Cash Flow to equity.","UFCF vs LFCF","UFCF ignores the capital structure; it’s cash available to all providers of capital and is discounted at WACC.","LFCF reflects interest expense & principal pay-down; it’s cash only to equity holders and feeds an IRR calculation in the LBO context."],"collection":"practice","topic":"DCF","tags":["Reported in LionTree Interview","SA 2026","DCF","Advanced"]},{"id":"q-1218","t":"val","l":"Advanced","s":90,"q":"Walk me through a DCF over 3 years using the exit multiple method. Calculate the implied share price.","k":["This is a framework question without specific numbers. The approach:","Project UFCF for Years 1-3.","Calculate terminal value at end of Year 3: TV = Year 3 EBITDA x Exit Multiple.","Discount Years 1-3 UFCF and TV to present at WACC: PV = FCF1/(1+WACC) + FCF2/(1+WACC)^2 + (FCF3+TV)/(1+WACC)^3.","Sum all PVs to get Enterprise Value.","Subtract net debt to get Equity Value.","Divide by diluted shares = Implied Share Price."],"collection":"practice","topic":"DCF","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, Second round","DCF","Advanced"]},{"id":"q-1219","t":"val","l":"Advanced","s":90,"q":"Revenue is 1000, EBITDA margin 20%, tax rate 20%, depreciation 50, capex 60, inventory up 10, accounts payable up 50.\n\n\n\n\nCalculate unlevered free cash flow (UFCF).","k":["EBITDA = 200.","EBIT = 200 − 50 = 150.","NOPAT = 150 × (1 − 20%) = 120.","ΔNWC = 10 − 50 = −40 (source of cash).","UFCF = 120 + 50 − 60 + 40 = 150."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","First round","DCF","Advanced"]},{"id":"q-1220","t":"val","l":"Advanced","s":90,"q":"Two companies:\n\n\n\n\n1 - A coal company whose cash flows go from 100 down to 0 over 10 years.\n\n\n\n\n2 - A tech company whose cash flows go from 0 up to 100 over 10 years.\n\n\n\n\nOver this time, the FED rate goes from 3% to 8%. Which company is valued higher?","k":["At 8%, the coal company may be valued higher.","Its cash is front‑loaded, so higher discount rates hurt less.","Tech’s long‑duration cash flows get heavily discounted, crushing terminal value.","At low rates the result reverses; duration drives sensitivity."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","SA 2026","DCF","Advanced"]},{"id":"q-1221","t":"val","l":"Advanced","s":90,"q":"How would you determine the cost of equity for a gold mine, and what would be unusual about its beta?","k":["Apply CAPM using an un‑levered average of publicly traded gold‑miner betas, then re‑lever for the target capital structure.","The beta is often low or even slightly negative because gold prices can move counter‑cyclically to equities."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","DCF","Advanced"]},{"id":"q-1222","t":"val","l":"Advanced","s":90,"q":"How do you incorporate considerations of risk into a DCF analysis?","k":["Risk is incorporated into a DCF through:","Discount Rate (WACC): Higher risk → higher WACC → lower valuation. Risk reflected in Cost of Equity (beta) and Cost of Debt.","Cash Flow Projections: Conservative assumptions for uncertain scenarios reduce projected cash flows.","Terminal Growth Rate: Lower perpetual growth rates reflect maturity and competitive pressures.","Scenario Analysis: Model base, upside, and downside cases to assess range of outcomes.","Probability Weighting: Assign probabilities to different scenarios for expected value.","Sensitivity Analysis: Test impact of key variables (revenue growth, margins, WACC) on valuation."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","DCF","Advanced"]},{"id":"q-1223","t":"val","l":"Advanced","s":90,"q":"Walk me through how you would perform a DCF valuation for a gold mine.","k":["Key steps for gold mine DCF:","Forecast Production: Estimate annual gold production (ounces) based on reserves, extraction rates, and mine life.","Gold Price Assumptions: Project gold prices (spot, futures curve, or long-term average).","Revenue: Annual production * gold price forecast.","Operating Costs: Cash costs per ounce (mining, processing, admin) + capital expenditures (development, equipment, reclamation).","Calculate Unlevered Free Cash Flow: Revenue - Operating Costs - CapEx - Taxes.","Discount Rate: Use WACC reflecting mining sector risk, commodity price volatility, and geopolitical factors.","Terminal Value: Typically zero (finite reserves) or residual land value.","Sum discounted cash flows to get NPV."],"collection":"practice","topic":"DCF","tags":["Reported in Moelis & Co. Interview","First round","DCF","Advanced"]},{"id":"q-1224","t":"val","l":"Advanced","s":90,"q":"Part 1: Consider two companies, both with a $6 billion market cap and all-equity financing. The first is a tech company that generates zero cash flow today but expects high cash flow in 10 years. The second is a coal plant that generates high cash flow today but expects zero cash flow in 10 years. If the Fed raises rates by 5% tomorrow, what happens to the value of each company? Which one moves more?\n\n\n\n\nPart 2: Which company would have the higher beta, and how would that affect the change in value when rates rise?\n\n\n\n\nPart 3: Now assume the tech company is levered to 7x. How would that impact its sensitivity to interest rate changes?","k":["Part 1: Interest Rate Impact","Both companies decline in value, but the tech company declines significantly more.","The tech company's value is derived from distant cash flows (10+ years out). A higher discount rate disproportionately reduces the present value of far-future cash flows due to compounding.","The coal plant's value comes from near-term cash flows, which are less sensitive to discount rate changes since they are discounted over fewer periods.","This is analogous to bond duration: the tech company is like a long-duration bond, while the coal plant is like a short-duration bond.","Part 2: Beta","The tech company would have a higher beta.","Growth companies with distant cash flows have more uncertainty and higher sensitivity to market conditions, resulting in higher beta.","The higher beta means a higher cost of equity via CAPM, compounding the negative valuation effect when rates rise since the discount rate increases even further.","Part 3: Leverage at 7x","Adding 7x leverage amplifies the tech company's sensitivity to rate changes in two ways.","First, higher rates increase interest expense, reducing the already-zero near-term cash flows and potentially creating cash burn.","Second, leverage increases equity beta (levered beta = unlevered beta x (1 + (1-t) x D/E)), further raising the cost of equity and discount rate.","The equity value of the levered tech company would be devastated by a 5% rate hike."],"collection":"practice","topic":"DCF","tags":["New","Reported in Moelis & Co. Interview","SA 2027, New York Office","DCF","Advanced"]},{"id":"q-1225","t":"val","l":"Advanced","s":90,"q":"If a company has a changing capital structure over the forecast period, should you use levered or unlevered free cash flow for a DCF valuation?","k":["Use unlevered free cash flow (FCFF).","Unlevered FCF isolates operating performance from financing decisions. When capital structure changes, levered FCF becomes inconsistent as it reflects varying interest expenses and debt levels.","By using unlevered FCF and WACC, you value the enterprise independent of capital structure changes. The changing debt levels are captured in the WACC calculation, which should be updated annually to reflect the evolving capital structure.","Alternatively, if using levered FCF, you must use a flow-to-equity approach with a changing cost of equity, which is more complex."],"collection":"practice","topic":"DCF","tags":["Reported in Morgan Stanley Interview","SF Office","DCF","Advanced"]},{"id":"q-1226","t":"val","l":"Advanced","s":90,"q":"Rank the betas of the following: an early-stage biotech company, a utilities company, a restructuring law firm, and flipping a coin.","k":["From highest to lowest beta:","Early-stage biotech: Highest. Highly speculative, sensitive to market risk appetite.","Utilities company: Low positive beta (~0.3-0.6). Regulated, stable cash flows, but still positively correlated with the market.","Flipping a coin: Beta = 0. Completely random, zero correlation with the market.","Restructuring law firm: Near 0 or slightly negative. Countercyclical (revenue rises during downturns), so lowest beta."],"collection":"practice","topic":"DCF","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Generalist group, New York Office, First round","DCF","Advanced"]},{"id":"q-1227","t":"val","l":"Advanced","s":90,"q":"Your DCF produces an implied share price of $100, but the stock currently trades at $50. What things in the DCF would you look at to double check?","k":["A 2x discrepancy suggests aggressive assumptions. Key areas to scrutinize:","Terminal value assumptions: Is the terminal growth rate too high (above long-term GDP growth of ~2-3%)? Is the exit multiple too aggressive relative to current trading comps?","Discount rate (WACC): Is the WACC too low? Check beta assumptions, equity risk premium, and capital structure weighting.","Revenue growth projections: Are top-line growth rates realistic compared to historical performance and consensus estimates?","Margin expansion: Are projected EBITDA or operating margins significantly above historical levels without clear justification?","Working capital and CapEx: Are future CapEx or working capital needs understated, inflating free cash flows?","Projection period length: A longer explicit forecast period with high growth can inflate the valuation.","Run a sensitivity analysis on WACC and terminal growth rate to see how the implied price changes under more conservative assumptions."],"collection":"practice","topic":"DCF","tags":["New","Reported in Morgan Stanley Interview","SA 2027, New York Office, Superday","DCF","Advanced"]},{"id":"q-1228","t":"val","l":"Advanced","s":90,"q":"If a DCF analysis produces an implied equity value that is significantly lower than the company's current market price, does that mean your DCF is wrong?","k":["Not necessarily. Several explanations exist:","The market may be pricing in growth expectations, synergies, or strategic value that your projections do not capture.","Your assumptions may be too conservative -- revenue growth, margins, or terminal value could be understated.","Your WACC may be too high, excessively discounting future cash flows.","The market could genuinely be overvaluing the stock due to speculation, momentum, or sentiment.","The correct response is to sensitize key assumptions (growth, margins, WACC, terminal multiple) and present a range of values. A DCF is one data point, not a definitive answer."],"collection":"practice","topic":"DCF","tags":["New","Reported in Morgan Stanley Interview","SA 2027, Superday","DCF","Advanced"]},{"id":"q-1229","t":"val","l":"Advanced","s":90,"q":"What is an example of a company that has a negative beta?","k":["Gold mining companies (e.g., Newmont, Barrick Gold) often exhibit negative or near-zero betas.","Gold is a classic safe-haven asset. When the broader equity market declines (recessions, crises), investors flock to gold, driving up gold prices and gold miners' stock prices. This inverse relationship with the market produces a negative beta. Other examples include certain inverse ETFs by design, though those are not operating companies."],"collection":"practice","topic":"DCF","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Superday","DCF","Advanced"]},{"id":"q-1230","t":"val","l":"Advanced","s":90,"q":"Outside of the time value of money, why do you discount future cash flows back to their present value?","k":["Beyond the time value of money, you discount future cash flows for two additional reasons:","Risk / Uncertainty: Future cash flows are not guaranteed. The further out they are, the more uncertain they become. Discounting compensates investors for bearing that uncertainty -- a dollar you might receive in 10 years is worth less than a dollar today because there is meaningful risk you may never receive it.","Opportunity Cost: Capital deployed in one investment cannot be deployed elsewhere. The discount rate reflects the return you could earn on alternative investments of comparable risk. Discounting ensures you are comparing the investment to its next-best alternative."],"collection":"practice","topic":"DCF","tags":["New","Reported in Morgan Stanley Interview","SA 2025, Healthcare group, SF Office, Superday","DCF","Advanced"]},{"id":"q-1231","t":"val","l":"Advanced","s":90,"q":"If given a 100-year DCF, what would you expect about CAPEX and D&A at the 100th year?","k":["They should converge: maintenance CAPEX ≈ D&A, both growing at or below inflation, reflecting a steady‑state business with no incremental growth spend."],"collection":"practice","topic":"DCF","tags":["Reported in Nomura Greentech Interview","Full-Time Analyst 2024, SF Office, Superday","DCF","Advanced"]},{"id":"q-1232","t":"val","l":"Advanced","s":90,"q":"Holding all else equal, which depreciation method results in a higher DCF valuation: straight-line or accelerated depreciation?","k":["Accelerated depreciation results in higher DCF valuation.","Accelerated depreciation front-loads tax deductions, creating larger tax shields in earlier years. This increases near-term free cash flows, which are more valuable in a DCF due to time value of money (earlier cash flows are discounted less).","While total depreciation over the asset's life is identical under both methods, the present value of tax savings is higher with accelerated depreciation."],"collection":"practice","topic":"DCF","tags":["Reported in Perella Weinberg Interview","New York Office","DCF","Advanced"]},{"id":"q-1233","t":"val","l":"Advanced","s":90,"q":"Part 1: How would your DCF approach differ for a Starbucks located on a college campus, in a downtown city area, and in an airport terminal?\n\n\n\n\nPart 2: For each location, what are the key supply-side constraints you would need to consider in your forecast?","k":["Part 1: DCF Approach by Location","College campus: Seasonal demand (lower during breaks), predictable customer base, moderate pricing. Forecast adjusted for academic calendar.","Downtown city: Steady weekday traffic, commuter-driven, premium pricing. Higher rent, stable cash flows with strong morning/lunch peaks.","Airport terminal: High volume, captive customers, premium pricing. Volatile based on flight schedules and travel trends. Very high rent and operating costs.","Part 2: Supply-Side Constraints","College campus: Limited operating hours, restricted access during breaks, lease terms tied to university contracts.","Downtown city: Commercial lease terms, zoning restrictions, labor availability and costs, parking/accessibility.","Airport terminal: Concession agreements, strict operating hours tied to terminal schedules, very high rent as % of sales, security and regulatory compliance costs."],"collection":"practice","topic":"DCF","tags":["Reported in Perella Weinberg Interview","New York Office","DCF","Advanced"]},{"id":"q-1234","t":"val","l":"Advanced","s":90,"q":"You are comparing two companies with the same EBITDA: a management consulting firm (asset-light) and a heavy manufacturing firm (capital-intensive).\n\n\n\n\nWhich company's DCF would likely yield a higher valuation, and why?","k":["The consulting firm would likely have a higher DCF valuation.","Key reasons:","Lower CapEx requirements mean higher Free Cash Flow despite same EBITDA.","Less working capital investment needed for growth.","Higher cash conversion ratio.","Lower reinvestment needs to maintain operations.","The manufacturing firm requires significant ongoing CapEx for equipment maintenance and replacement, reducing FCF available to equity holders."],"collection":"practice","topic":"DCF","tags":["Reported in Perella Weinberg Interview","New York Office, Second round","DCF","Advanced"]},{"id":"q-1235","t":"val","l":"Advanced","s":90,"q":"Which has a higher WACC: a company trading at 10x EV/EBITDA or a company trading at 15x EV/EBITDA?","k":["The company trading at 10x EV/EBITDA likely has a higher WACC.","A lower EV/EBITDA multiple implies the market is discounting the company's cash flows at a higher rate (higher WACC), which reduces the present value of those cash flows.","Companies with higher risk, lower growth, or less predictable cash flows trade at lower multiples because investors demand a higher return (higher WACC) to compensate for that risk.","The 15x company trades at a premium because the market views it as higher quality (stronger growth, lower risk, more predictable cash flows), implying a lower discount rate."],"collection":"practice","topic":"DCF","tags":["New","Reported in Perella Weinberg Interview","SA 2026, Superday","DCF","Advanced"]},{"id":"q-1236","t":"val","l":"Advanced","s":90,"q":"Where is there a circularity in a DCF with an implied share price?","k":["The circularity arises from the diluted share count calculation.","In a DCF, you calculate Enterprise Value, subtract net debt to get Equity Value, and divide by diluted shares to get the implied share price. However, the number of diluted shares depends on the share price (via the Treasury Stock Method): a higher share price means more options are in-the-money, increasing the diluted share count. But the share price is the output of the DCF.","So the circularity is: Share Price depends on Diluted Shares, but Diluted Shares depend on Share Price.","To resolve this, you can: (1) use Excel's iterative calculation feature, (2) use the current market share price as a proxy for TSM calculations, or (3) use goal seek to solve for the price at which the implied price equals the price used in the TSM calculation."],"collection":"practice","topic":"DCF","tags":["New","Reported in Piper Sandler Interview","SA 2025","DCF","Advanced"]},{"id":"q-1237","t":"val","l":"Advanced","s":90,"q":"Calculate free cash flow given the following: $500M in revenue, 20% EBITDA margin, D&A is 5% of revenue, CapEx is $35M, inventory decreases by $25M, accounts payable increases by $25M, and the tax rate is 20%.","k":["Answer: $100M","EBITDA = $500M x 20% = $100M.","D&A = $500M x 5% = $25M.","EBIT = $100M - $25M = $75M.","Taxes on EBIT = $75M x 20% = $15M.","NOPAT = $60M.","+ D&A: +$25M.","- CapEx: -$35M.","+ Inventory decrease (source of cash): +$25M.","+ AP increase (source of cash): +$25M.","UFCF = $60M + $25M - $35M + $25M + $25M = $100M."],"collection":"practice","topic":"DCF","tags":["New","Reported in PJT Partners Interview","SA 2026, Superday","DCF","Advanced"]},{"id":"q-1238","t":"val","l":"Advanced","s":90,"q":"3 places taxes affect the DCF?\n\n\n\n\nFollow-up: How does each place get affected if taxes increase?","k":["NOPAT in FCF — higher taxes cut NOPAT and FCF.","Cost of Debt — higher taxes increase the shield, lowering the after‑tax cost and WACC.","Levered Beta — conversion from Unlevered to Levered.","Overall, FCF falls and the discount rate may fall; valuation typically declines."],"collection":"practice","topic":"DCF","tags":["Reported in Rothschild Interview","SA 2026","DCF","Advanced"]},{"id":"q-1239","t":"val","l":"Advanced","s":90,"q":"Walk me through a DCF for a sandwich shop in your university town.","k":["Revenue forecast: Estimate daily customers (e.g., 200/day), average ticket size ($10), and operating days (350/year). Year 1 Revenue = 200 x $10 x 350 = $700K. Assume 3-5% annual growth from foot traffic growth and price increases.","Expenses: COGS (~30-35% of revenue for food costs), labor (~25-30%), rent, utilities, and other overhead. EBITDA margin for a well-run sandwich shop might be 15-20%.","CapEx: Minimal ongoing CapEx (equipment maintenance, periodic renovations). Maybe $10-15K/year.","Working capital: Minimal -- food inventory turns quickly, and most sales are cash/card (low AR). NWC change is negligible.","Discount rate: Use a high rate (15-25%) reflecting the risk of a single small business. No debt assumed, so use cost of equity only.","Terminal Value: Use the Gordon Growth Method with 2-3% perpetuity growth, or an exit multiple of 3-5x EBITDA (typical for small food service businesses).","Sum PV of FCFs + PV of TV = Enterprise Value of the sandwich shop."],"collection":"practice","topic":"DCF","tags":["New","Reported in Rothschild Interview","SA 2027, First round","DCF","Advanced"]},{"id":"q-1240","t":"val","l":"Advanced","s":90,"q":"After running a discounted cash flow model, which would you rather do and why — increase revenue, increase EBITDA, or decrease capital expenditures?","k":["It depends whether you mean a dollar of each or a sustained improvement in each.","Dollar-for-dollar","Decrease CapEx wins. CapEx sits below EBITDA in the UFCF bridge and is not tax-affected, so $1 less CapEx is a full $1 of UFCF.","Increase EBITDA is next: $1 x (1 - Tax Rate), roughly $0.75 at a 25% rate.","Increase revenue is last. Revenue only reaches EBITDA at the incremental margin — at 30%, $1 of revenue is $0.30 of EBITDA and about $0.23 of UFCF. A dollar of EBITDA always beats a dollar of revenue.","As a sustained improvement","Revenue growth is most valuable. It compounds — a higher base lifts every forecast year and the terminal value, typically 60-80% of DCF value.","Margin expansion also reaches terminal value but works off an unchanged top line, so it compounds less.","CapEx reduction is weakest strategically. Underinvesting impairs asset quality and growth, which can cut terminal value by more than the cash saved, and it is a one-time benefit.","So a dollar of CapEx reduction has the largest immediate UFCF impact, but as a business improvement revenue growth wins because it compounds through the forecast and the terminal value."],"collection":"practice","topic":"DCF","tags":["New","Reported in Rothschild Interview","SA 2027, Global Advisory group, New York Office, Superday","DCF","Advanced"]},{"id":"q-1241","t":"val","l":"Advanced","s":90,"q":"In a DCF analysis, where is idiosyncratic (company-specific) risk accounted for: in the numerator (projected cash flows) or the denominator (WACC)?","k":["Idiosyncratic risk is primarily accounted for in the numerator through probability-weighted cash flow projections and scenario analysis.","The denominator (WACC) reflects systematic market risk via beta, not company-specific risk. Under CAPM theory, idiosyncratic risk can be diversified away and thus is not priced in the discount rate.","In practice, company-specific risks are addressed by adjusting cash flow assumptions, creating downside cases, or applying appropriate probability weightings to different scenarios."],"collection":"practice","topic":"DCF","tags":["Reported in Unspecified Interview","DCF","Advanced"]},{"id":"q-1242","t":"val","l":"Advanced","s":90,"q":"How would you adjust a DCF for a major, unexpected economic shock (e.g., a global pandemic)?\n\n\n\n\nHow would this affect your assumptions for the terminal growth rate?","k":["Key adjustments to near-term forecasts:","Model severe revenue declines in shock years","Adjust margins for operational disruptions","Incorporate government support or liquidity needs","Extend recovery period before normalization","Increase discount rate to reflect heightened risk","Terminal growth rate impact:","Typically unchanged if shock is temporary and doesn't alter long-term structural economics","Reduce if shock permanently impairs industry (e.g., retail shift to e-commerce)","Consider scenario analysis with multiple terminal assumptions given uncertainty"],"collection":"practice","topic":"DCF","tags":["Reported in Unspecified Interview","DCF","Advanced"]},{"id":"q-1243","t":"val","l":"Advanced","s":90,"q":"How would an increase in employee stock-based compensation impact unlevered free cash flow?","k":["Mechanically, Stock-Based Compensation (SBC) is a non-cash operating expense, so it is added back in the calculation of unlevered free cash flow, which increases reported UFCF relative to cash compensation.","However, many practitioners prefer to treat SBC as a cash expense (do not add it back) to reflect the real economic dilution to shareholders, which results in a lower UFCF."],"collection":"practice","topic":"DCF","tags":["Reported in Unspecified Interview","DCF","Advanced"]},{"id":"q-1244","t":"val","l":"Advanced","s":90,"q":"In the final year of a DCF projection, a company has the following metrics:\n\n\n\nEBITDA: $125\nD&A: $25\nTaxes: $25\nCapital Expenditures: $25\nChange in Working Capital: $0\n\n\n\nAssuming a perpetual cash flow growth rate of 3% and a required rate of return of 13%, what is the company's Terminal Value?","k":["Answer: $773","Calculation:","EBIT = EBITDA - D&A = $125 - $25 = $100.","NOPAT = EBIT - Taxes = $100 - $25 = $75.","Unlevered FCF = NOPAT + D&A - CapEx - Change in NWC.","Unlevered FCF = $75 + $25 - $25 - $0 = $75.","Terminal Value = FCF * (1 + g) / (WACC - g).","Terminal Value = $75 * (1.03) / (0.13 - 0.03) = $77.25 / 0.10 = $772.50."],"collection":"practice","topic":"DCF","tags":["Reported in Unspecified Interview","DCF","Advanced"]},{"id":"q-1245","t":"val","l":"Advanced","s":90,"q":"In a DCF analysis, Company A and Company B are identical in every way, except Company A has a terminal multiple of 20x EBITDA and Company B has a terminal multiple of 12x EBITDA.\n\n\n\n\nWhat could justify this difference?","k":["Factors that could justify higher terminal multiples for Company A:","Higher expected perpetual growth rate beyond the forecast period","Superior competitive positioning or sustainable competitive advantages","Lower risk profile or more stable cash flows","Better management quality or corporate governance","Operating in a more attractive industry with better long-term dynamics","Higher barriers to entry or network effects","Better capital efficiency or higher returns on invested capital","Lower capital intensity or working capital requirements","The terminal multiple should reflect the company's long-term competitive position and growth prospects at steady state. Market multiples at the time of exit also play a role in selecting appropriate terminal multiples."],"collection":"practice","topic":"DCF","tags":["Reported in Unspecified Interview","DCF","Advanced"]},{"id":"q-1246","t":"val","l":"Advanced","s":90,"q":"Part 1: A pre-revenue startup is expected to take 20 years to reach maturity. Your boss asks for a 5-year DCF. What are the challenges with this approach?\n\n\n\n\nPart 2: If a DCF is not suitable, what valuation methods could you use instead?","k":["Part 1: DCF Challenges","No Historical Financials: Difficult to project cash flows without revenue history.","High Uncertainty: 20-year maturity means 5-year forecast misses most value creation.","Terminal Value Dominance: TV would represent nearly 100% of value, making DCF unreliable.","Discount Rate Complexity: High risk and no comparable betas make WACC calculation difficult.","Part 2: Alternative Methods","Venture Capital Method: Value at exit based on comparable exits, discount back at target IRR.","Precedent Transactions: Value based on prices paid for similar early-stage companies.","Comparable Company Analysis: Use EV/Revenue or EV/Users for similar pre-revenue firms.","Scorecard/Checklist Method: Adjust average startup valuations based on qualitative factors."],"collection":"practice","topic":"DCF","tags":["Reported in Unspecified Interview","Superday","DCF","Advanced"]},{"id":"q-1247","t":"val","l":"Advanced","s":90,"q":"Let's say you are building a DCF analysis. If a company only gave you one year of financials, how would you calculate FCF for the remaining four years?","k":["You’d still project revenue growth, operating margins, and capex assumptions for years 2–5, even if they’re estimates.","For year 1, use the actuals. Then apply logical assumptions or benchmarks for subsequent years (e.g., industry growth rates, historical trends, management guidance) to forecast free cash flows and discount them back."],"collection":"practice","topic":"DCF","tags":["Reported in Wells Fargo Interview","DCF","Advanced"]},{"id":"q-1248","t":"val","l":"Advanced","s":90,"q":"How do you go from revenue to unlevered free cash flow?\n\n\n\n\nFollow-up: Would applying a valuation multiple to unlevered free cash flow inform enterprise value or equity value?","k":["Revenue to Unlevered Free Cash Flow","Start with Revenue","Subtract COGS and Operating Expenses to get EBITDA","Subtract Depreciation & Amortization to get EBIT","Apply taxes to EBIT to get NOPAT (Net Operating Profit After Tax)","Add back Depreciation & Amortization (and other non-cash charges like Stock-Based Compensation or Deferred Taxes)","Subtract Capital Expenditures","Subtract Changes in Net Working Capital","= Unlevered Free Cash Flow","The key is that taxes are applied to EBIT, not EBT — you ignore interest expense entirely because unlevered FCF is calculated as if the company has no debt.","Follow-up: Enterprise Value","Applying a multiple to unlevered free cash flow gives you Enterprise Value. Unlevered FCF represents cash flow available to all capital providers — both debt and equity holders — before any debt service. Because it is capital-structure-neutral, it maps to Enterprise Value. To arrive at Equity Value, you would subtract net debt (and other EV bridge items like preferred stock and non-controlling interest) from that Enterprise Value."],"collection":"practice","topic":"DCF","tags":["New","Reported in William Blair Interview","SA 2027, Financial Sponsors group, New York Office","DCF","Advanced"]},{"id":"q-1249","t":"deal","l":"Basic","s":90,"q":"A company announces it will acquire another for $80 per share.\n\n\n\n\nWhy might the seller's stock price not be at $80 after the announcement?\n\n\n\n\nFollow up: If it was now 100% certain this company would be acquired in a couple of months, proven somehow, would the shares trade at the $80 acquisition price?","k":["Closing risk – regulators, financing, or shareholder vote could derail the deal.","Time value – payment is months away; discount it back.","Market volatility widens spreads.","Shares should trade very close to $80, less a small discount for the time value of money and execution mechanics."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Ardea Partners Interview","SA 2025, off-cycle, London office","Merger Model (M&A)","Basic"]},{"id":"q-1250","t":"deal","l":"Basic","s":90,"q":"Would I add a target's Net Income to an acquiring company's EBITDA in a merger model?","k":["No, you wouldn’t directly add Net Income to EBITDA. They measure different things: Net Income includes interest and taxes, while EBITDA is an operating metric excluding them.","You’d typically consolidate revenue, expenses, and other line items consistently. For example, you’d add the target’s revenue and operating costs to the acquirer’s to arrive at combined EBIT or EBITDA, then factor in interest and taxes for net income."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Bank of America Interview","Merger Model (M&A)","Basic"]},{"id":"q-1251","t":"deal","l":"Basic","s":90,"q":"The cost of debt is 5%, and the target company’s P/E is 20. If you do an all-debt deal, is it accretive or dilutive?","k":["A P/E of 20 implies an earnings yield of 1/20 = 5%. If your after-tax cost of debt is less than 5%, the deal is accretive. If it’s more, it’s dilutive.","Here, if the cost of debt is 5%, you must also apply the tax shield. For example, if the tax rate is 25%, the after-tax cost is 5%*(1–0.25) = 3.75%, which is less than the target’s earnings yield of 5%, so it should be accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Bank of America Interview","Merger Model (M&A)","Basic"]},{"id":"q-1252","t":"deal","l":"Basic","s":90,"q":"A company with a P/E ratio of 20x considers repurchasing its own shares using debt that costs 10% before taxes.\n\n\n\n\nAssuming a 25% tax rate, is this transaction accretive or dilutive to the company's EPS?","k":["The transaction is dilutive.","Analysis:","Earnings Yield = 1 / P/E = 1 / 20x = 5%.","Cost of Debt (After-Tax) = 10% * (1 - 25%) = 7.5%.","Since Earnings Yield (5%) < Cost of Debt (7.5%), the transaction is dilutive.","When a company buys back shares using debt, the transaction is accretive only if the earnings yield is greater than the after-tax cost of debt. Here, the 5% yield is less than the 7.5% cost, making it dilutive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Bank of America Interview","Chicago office, First round","Merger Model (M&A)","Basic"]},{"id":"q-1253","t":"deal","l":"Basic","s":90,"q":"What are five common strategic reasons for two companies to merge?","k":["Common strategic rationales for M&A:","Cost Synergies: Eliminate redundant functions, achieve economies of scale.","Revenue Synergies: Cross-selling, expanded distribution, complementary products.","Market Consolidation: Gain market share and pricing power.","Geographic Expansion: Enter new markets or regions.","Vertical Integration: Control supply chain, reduce costs, improve margins."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Bank of America Interview","New York Office, First round","Merger Model (M&A)","Basic"]},{"id":"q-1254","t":"deal","l":"Basic","s":90,"q":"If a company with a P/E multiple of 15x acquires a company with a P/E multiple of 18x in an all-stock transaction, is the deal accretive or dilutive?\n\n\n\n\nWhy?","k":["The deal is dilutive.","In an all-stock transaction, the acquirer's cost of equity is implied by its P/E multiple. An acquirer with 15x P/E has an earnings yield (cost of equity) of 1/15 = 6.67%.","The target with 18x P/E has an earnings yield of 1/18 = 5.56%.","Since the acquirer's cost (6.67%) is higher than the target's yield (5.56%), the deal is dilutive to the acquirer's EPS.","Rule: Acquiring a company at a higher P/E (lower yield) than your own P/E using stock is dilutive. Acquiring at a lower P/E (higher yield) is accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Bank of America Interview","M&A, Second round","Merger Model (M&A)","Basic"]},{"id":"q-1255","t":"deal","l":"Basic","s":90,"q":"What does it mean for an acquisition to be 'accretive'?","k":["An acquisition is accretive when the acquirer's pro forma EPS after the deal is higher than its standalone EPS before the deal.","This occurs when the earnings yield of the target exceeds the weighted average cost of the financing used (debt, cash, and/or stock)."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Bank of America Interview","M&A, Second round","Merger Model (M&A)","Basic"]},{"id":"q-1256","t":"deal","l":"Basic","s":90,"q":"What makes a company a good acquisition candidate for a strategic buyer?","k":["Strong strategic fit: Complementary products, geographies, or customer bases that create synergies.","Revenue and cost synergy potential: Cross-selling opportunities, elimination of redundant overhead.","Attractive financial profile: Strong margins, growth trajectory, and manageable leverage.","Defensible market position: Brand strength, intellectual property, or regulatory moats.","Accretive to the acquirer's EPS at a reasonable price.","Management team and cultural alignment."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Bank of America Interview","SA 2025, First round","Merger Model (M&A)","Basic"]},{"id":"q-1257","t":"deal","l":"Basic","s":90,"q":"How would you advise a client on selling their business when you receive a call from a potential buyer willing to pay $2 billion?","k":["Do not accept or reject immediately. As an advisor, you would:","Assess fair value: Run a full valuation (comps, precedent transactions, DCF) to determine the company's intrinsic value range and whether $2B is a fair price.","Understand the buyer's motivation: Why are they bidding? Are there synergies that would justify a higher price?","Create competitive tension: Consider running a broader process (auction) to attract additional bidders and maximize the sale price.","Evaluate deal terms: Price is only one factor. Consider structure (cash vs. stock), certainty of close, regulatory risk, employee protections, and timeline.","Consider alternatives: Compare selling to other strategic options (remaining independent, IPO, partial sale, dividend recapitalization).","Advise the board: Present the analysis with a recommendation and let the board and shareholders decide."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Bank of America Interview","SA 2025, First round","Merger Model (M&A)","Basic"]},{"id":"q-1258","t":"deal","l":"Basic","s":90,"q":"What else would you ask for to evaluate an acquisition besides the income statement and balance sheet that you already have?","k":["Cash Flow Statement - to understand actual cash generation, CapEx needs, and working capital dynamics.","Management projections and a detailed financial model with assumptions.","Customer and revenue breakdown (concentration, contract terms, churn rates).","Debt schedule with covenants, maturities, and change-of-control provisions.","Due diligence reports (commercial, legal, environmental, IT).","Quality of earnings (QoE) report to identify non-recurring or adjusted items.","Comparable company and precedent transaction data for valuation benchmarking.","Industry and competitive landscape analysis.","Tax structure and any NOLs or tax attributes.","Off-balance sheet liabilities (operating leases, pension obligations, litigation)."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Barclays Interview","SA 2026, New York Office, Superday","Merger Model (M&A)","Basic"]},{"id":"q-1259","t":"deal","l":"Basic","s":90,"q":"You are pitching a public company on acquiring another public company. What key sections would you include in the pitch book?","k":["Standard M&A pitch book structure:","Executive Summary: Deal rationale, key highlights, valuation range.","Strategic Rationale: Synergies, market positioning, competitive advantages.","Target Overview: Business description, financials, market position.","Industry Analysis: Trends, competitive landscape, growth drivers.","Valuation Analysis: Precedent transactions, comparable companies, DCF.","Accretion/Dilution: Pro forma impact on EPS and key metrics.","Transaction Structure: Financing mix, consideration type, timing.","Risk Factors: Integration challenges, regulatory hurdles, market risks."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in BMO Interview","New York Office","Merger Model (M&A)","Basic"]},{"id":"q-1260","t":"deal","l":"Basic","s":90,"q":"Why would two companies choose to enter into a joint venture?","k":["Joint ventures allow companies to collaborate while maintaining independence.","Common motivations:","Risk sharing: Split capital requirements and operational risks for large projects.","Complementary capabilities: Combine different expertise, technology, or market access.","Market entry: Partner with local company to navigate foreign regulations or distribution.","Resource pooling: Share R&D costs or manufacturing infrastructure.","Strategic testing: Explore partnership benefits before full merger.","Regulatory considerations: Satisfy antitrust requirements or ownership restrictions."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in BMO Interview","New York Office","Merger Model (M&A)","Basic"]},{"id":"q-1261","t":"deal","l":"Basic","s":90,"q":"Part 1: Why would a company decide to acquire another company?\n\n\n\n\nPart 2: What slides would you include in an M&A pitchbook, and in what order?","k":["Part 1: Acquisition Rationale","Common motivations for acquisitions:","Revenue synergies: Cross-selling, expanded customer base.","Cost synergies: Eliminate redundancies, economies of scale.","Market share: Consolidate industry position, reduce competition.","Capabilities: Acquire technology, talent, IP, or distribution.","Geographic expansion: Enter new markets quickly.","Financial engineering: Utilize tax benefits or excess cash.","Part 2: M&A Pitch Book Structure","Executive Summary","Strategic Rationale and Synergies","Target Company Overview","Industry and Market Analysis","Valuation Analysis","Accretion/Dilution Analysis","Transaction Structure and Financing","Risk Factors and Next Steps"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in BMO Interview","Chicago Office","Merger Model (M&A)","Basic"]},{"id":"q-1262","t":"deal","l":"Basic","s":90,"q":"Company A has $100 million in net income, 20 shares outstanding, and an EPS of $5. Company B has $25 million in net income and 25 shares outstanding. What is the EPS of Company B?\n\n\n\n\nFollow-up: Company A buys Company B at a 15x P/E multiple in an all-cash deal. How much do they pay?","k":["EPS of Company B","Answer: $1.00","EPS = Net Income / Shares = $25M / 25 = $1.00","Follow-up: Purchase Price","Answer: $375 million","Company B NI = $25M","Purchase Price = P/E x NI = 15 x $25M = $375M"],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Centerview Partners Interview","New York Office, First round","Merger Model (M&A)","Basic"]},{"id":"q-1263","t":"deal","l":"Basic","s":90,"q":"What are the types of synergies in an M&A transaction? Please give examples.","k":["Revenue Synergies: Cross-selling, expanding product lines, geographic expansion.","Cost Synergies: Shared overhead, reduced headcount, consolidated facilities.","Financial Synergies: Better debt terms due to a stronger combined balance sheet."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Citi Interview","Merger Model (M&A)","Basic"]},{"id":"q-1264","t":"deal","l":"Basic","s":90,"q":"An acquirer with a P/E multiple of 15x is buying a target with a P/E multiple of 20x in an all-stock transaction. Is this deal accretive or dilutive?","k":["The deal is dilutive.","In an all-stock transaction, accretion/dilution depends on comparing the acquirer's P/E to the target's P/E.","Acquirer P/E = 15x (implies earnings yield of 1/15 = 6.67%)","Target P/E = 20x (implies earnings yield of 1/20 = 5.00%)","Since the acquirer is paying a higher multiple (20x) than its own trading multiple (15x), it is paying more per dollar of earnings than its stock is valued at.","This results in EPS dilution for the acquirer's shareholders."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Citi Interview","New York Office, Superday","Merger Model (M&A)","Basic"]},{"id":"q-1265","t":"deal","l":"Basic","s":90,"q":"Why might regulators seek to deter or block M&A transactions?","k":["Antitrust / Competition concerns: The combined entity could have excessive market share, reducing competition and enabling price increases that harm consumers.","Market concentration: The deal could create a monopoly or oligopoly in a critical industry, reducing choice and innovation.","National security: Acquisitions by foreign entities (especially in defense, technology, or critical infrastructure) may pose national security risks. CFIUS reviews are common for cross-border deals.","Consumer protection: Regulators may worry the combined company would reduce product quality, service levels, or consumer choice.","Systemic risk: In financial services, regulators may block deals that create \"too big to fail\" institutions.","Labor market impact: Large mergers can lead to significant job losses, which draws political and regulatory scrutiny.","Data privacy: In tech deals, regulators may be concerned about the concentration of user data."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Citi Interview","SA 2027","Merger Model (M&A)","Basic"]},{"id":"q-1266","t":"deal","l":"Basic","s":90,"q":"What are the pros and cons of a spin-off versus an outright sale of a business unit?","k":["Spin-Off","Pros:","Tax-free to shareholders if structured properly.","Shareholders retain exposure to both entities.","No buyer needed; certainty of execution.","Unlocks hidden value through separate valuations.","Cons:","No immediate cash proceeds to parent.","Spun entity must be viable standalone.","Execution complexity and costs.","Potential loss of synergies.","Outright Sale","Pros:","Immediate cash proceeds.","Clean separation; no ongoing involvement.","Potential premium from strategic buyer.","Definitive valuation.","Cons:","Taxable transaction.","Shareholders lose exposure to divested business.","Requires willing buyer at acceptable price.","Execution uncertainty."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Credit Suisse Interview","M&A group, First round","Merger Model (M&A)","Basic"]},{"id":"q-1267","t":"deal","l":"Basic","s":90,"q":"In a merger model, accretion looks too high. What assumptions might you adjust downwards?","k":["To reduce calculated accretion:","Decrease synergy estimates.","Increase the purchase price / multiple.","Increase the cost of debt/cash financing (interest rate).","Reduce target's projected earnings."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Evercore Interview","Merger Model (M&A)","Basic"]},{"id":"q-1268","t":"deal","l":"Basic","s":90,"q":"What is good about companies divesting divisions?","k":["Focus on core business: Management can allocate more time and resources to the strongest business lines.","Unlock value: The market may apply a conglomerate discount. Divesting allows each business to be valued on its own merits, often at a higher total valuation (sum-of-the-parts).","Improve margins: Shedding lower-margin or underperforming divisions improves the company's overall profitability metrics.","Generate cash: Proceeds can be used to pay down debt, fund buybacks, or reinvest in higher-return opportunities.","Strategic flexibility: A leaner company is more attractive as an M&A target or better positioned for a strategic transaction.","Reduce complexity: Simplifies the organizational structure, reporting, and investor narrative."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","SA 2025, Second round","Merger Model (M&A)","Basic"]},{"id":"q-1269","t":"deal","l":"Basic","s":90,"q":"What are the three ways to finance an acquisition and why would a firm use each one?","k":["The three ways to finance an acquisition are cash, debt, and stock.","Cash: No dilution to existing shareholders and no new interest expense. Fastest execution. Used when the acquirer has a strong cash balance and wants to avoid dilution or additional leverage. Downside: depletes cash reserves and the acquirer forgoes the return it was earning on that cash.","Debt: Interest expense is tax-deductible, lowering the effective cost. No dilution to existing shareholders. Used when the acquirer has stable cash flows to service debt, available borrowing capacity, and favorable credit markets. Downside: increases leverage, financial risk, and may trigger rating downgrades.","Stock (Equity): No cash outflow and no increase in leverage. Used when the acquirer's stock price is high (making equity a \"cheap\" currency), the deal is very large relative to the acquirer's balance sheet, or the acquirer wants to share risk with the target's shareholders. Downside: dilutes existing shareholders' ownership and EPS.","Most acquisitions use a combination of these three sources, optimizing for cost of capital, balance sheet capacity, and shareholder impact."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, First round","Merger Model (M&A)","Basic"]},{"id":"q-1270","t":"deal","l":"Basic","s":90,"q":"Is it problematic for one overvalued company to acquire another overvalued company since the currency is the same?","k":["Using overvalued shares as deal currency lowers the effective price you pay, since each share issued buys more earnings than it is truly worth.","It helps only if your stock is more overvalued than the target’s and the consideration is mainly stock. If this is the case, then the deal can be EPS-accretive even at a high headline multiple.","Key risks: You may still overpay in absolute dollars, creating goodwill that could be impaired. Additionally, any multiple compression or missed synergies can quickly erase the perceived benefit."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Goldman Sachs Interview","Merger Model (M&A)","Basic"]},{"id":"q-1271","t":"deal","l":"Basic","s":90,"q":"Assume you are speaking to a client. Explain in simple terms why acquiring a company with a P/E multiple higher than your own is dilutive in an all-stock transaction.","k":["When you pay more per dollar of earnings than your stock is worth, you dilute your shareholders.","Example:","Your company: 10x P/E (you earn $1 for every $10 of stock).","Target: 15x P/E (they earn $1 for every $15 of stock).","You issue $15 of stock to buy $1 of their earnings.","Your shareholders gave up $15 but only got $1 of earnings back.","This reduces earnings per share for your shareholders."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Goldman Sachs Interview","Merger Model (M&A)","Basic"]},{"id":"q-1272","t":"deal","l":"Basic","s":90,"q":"How would you distribute synergies between a buyer and a seller in an M&A transaction?","k":["Synergies are typically shared through the acquisition premium. The seller captures a portion of the synergies upfront via the premium paid above the target's standalone value, and the buyer retains the remaining synergies as incremental value post-close.","Buyer's perspective: Wants to pay a premium that is less than the total NPV of expected synergies, keeping the difference as value creation for its shareholders.","Seller's perspective: Wants to capture as much of the synergy value as possible through a higher premium.","In practice, sellers typically capture 25-50% of total synergies through the premium, depending on competitive dynamics in the process (more bidders = more synergies captured by the seller).","A banker would run synergy analysis and compare the premium paid to the present value of synergies to advise the client on whether the deal creates value."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","Merger Model (M&A)","Basic"]},{"id":"q-1273","t":"deal","l":"Basic","s":90,"q":"What is included in a fairness opinion?","k":["A fairness opinion is a letter from an independent financial advisor to a company's board of directors stating whether the consideration in a proposed transaction is fair from a financial point of view.","It typically includes:","Summary of the transaction terms and consideration.","Valuation analyses performed: comparable companies, precedent transactions, DCF, and sometimes LBO analysis.","Range of implied values from each methodology compared to the offer price.","Assumptions, limitations, and qualifications (e.g., reliance on management projections, no independent verification of data).","The advisor's conclusion on whether the price is fair from a financial standpoint.","Fairness opinions protect the board from shareholder lawsuits by demonstrating they fulfilled their fiduciary duty."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","Merger Model (M&A)","Basic"]},{"id":"q-1274","t":"deal","l":"Basic","s":90,"q":"What are the different types of financing considerations used in M&A transactions?","k":["The three main forms of consideration in M&A are:","Cash: Funded from balance sheet cash, new debt issuance, or a combination. Provides certainty of value to the target. Creates foregone interest expense or new interest expense for the acquirer.","Stock: Acquirer issues new shares to target shareholders. No cash outlay but dilutes existing shareholders. Target shareholders share in upside/downside of the combined entity.","Debt: Acquirer raises new debt to fund the cash portion. Increases leverage and interest expense. Most common in LBOs and leveraged acquisitions.","Additional considerations include:","Earnouts: Contingent payments tied to post-closing performance metrics.","Seller financing: Target provides a loan to the buyer as part of the deal.","Assumed liabilities: Buyer takes on the target's existing debt, which effectively reduces the cash purchase price."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","Merger Model (M&A)","Basic"]},{"id":"q-1275","t":"deal","l":"Basic","s":90,"q":"What makes a good M&A candidate? What characteristics would you look for in a potential acquisition target?","k":["Strategic fit: The target fills a gap in the acquirer's product portfolio, geographic reach, or capabilities.","Strong market position: Leading or defensible position in its niche with high barriers to entry.","Synergy potential: Clear cost synergies (overlapping functions, supply chain) or revenue synergies (cross-selling, distribution).","Stable and predictable cash flows: Facilitates deal financing and integration planning.","Reasonable valuation: Target is priced at a level where the acquirer can achieve accretion or a compelling ROIC after synergies.","Scalable platform: The target provides a foundation for future bolt-on acquisitions or organic growth.","Competent management team: Retaining key talent post-close is critical for integration success.","Clean regulatory profile: No antitrust or regulatory obstacles that could delay or block the deal."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","Merger Model (M&A)","Basic"]},{"id":"q-1276","t":"deal","l":"Basic","s":90,"q":"What goes into the sources and uses schedule?","k":["Sources list how the deal is funded; uses show where the money goes.","Typical Sources:","New debt tranches","Equity contribution","Target cash or seller financing","Rollover equity","Typical Uses:","Equity purchase price","Debt payoff/refinancing","Transaction and financing fees","Balance‑sheet cash or working‑capital adjustments"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Greenhill & Co. Interview","SA 2024, Industrials M&A, Chicago office","Merger Model (M&A)","Basic"]},{"id":"q-1277","t":"deal","l":"Basic","s":90,"q":"How are strategic buyers different from financial buyers?","k":["Strategics seek operating synergies and can pay more using cash/stock; financial buyers (PE) focus on levered returns and an eventual exit.","Strategics accept lower IRR, while PE sponsors target 20%+ IRR via debt pay‑down and multiple expansion."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Greenhill & Co. Interview","SA 2024, Industrials M&A, Chicago office","Merger Model (M&A)","Basic"]},{"id":"q-1278","t":"deal","l":"Basic","s":90,"q":"What are the pros and cons of financing an acquisition with 100% cash versus 100% stock?","k":["100% Cash Acquisition","Pros:","Seller receives immediate, guaranteed payment.","No exposure for seller to buyer’s future performance or stock volatility.","Simple, clear valuation upfront.","Cons:","Buyer must have sufficient cash or borrow, potentially increasing debt.","Seller faces immediate taxable event.","Reduces buyer’s flexibility due to decreased cash reserves.","100% Stock Acquisition","Pros:","Buyer conserves cash and avoids debt financing.","Seller participates in potential future upside.","Seller can defer tax liabilities.","Cons:","Seller exposed to acquirer's stock fluctuations and performance risk.","Seller loses control, becoming minority owner.","Uncertain final deal value due to stock price changes before closing."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Guggenheim Partners Interview","Merger Model (M&A)","Basic"]},{"id":"q-1279","t":"deal","l":"Basic","s":90,"q":"Two companies each report $10 million of net income.\n\n\n\n\nAfter merging, combined net income is not $20 million. Why?","k":["Synergies and deal costs change earnings.","Differences on the upside: operating, financial (i.e. borrowing costs) and tax synergies; CapEx synergies are not included in net income conversation.","Differences on the downside: one‑time integration costs, dis-synergies (i.e. customer loss on revenue side, inefficient integration leading to higher costs than sum of individual costs), and interest on incremental borrowing."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Guggenheim Partners Interview","Merger Model (M&A)","Basic"]},{"id":"q-1280","t":"deal","l":"Basic","s":90,"q":"You are comparing otherwise identical targets. For each example below, which option is more accretive to the acquirer, and why?\n\n\n\nExample 1 - Target trading at 15× P/E versus 10× P/E.\nExample 2 - Same equity value, but one has $200 million cash and no debt, the other $1 billion debt and no cash.\nExample 3 - 100% cash financing versus 100% stock financing.","k":["Example 1 - 10× P/E is more accretive as it is less expensive for the same exact value.","Example 2 - $200m cash and no debt target is more accretive because enterprise value is lower for the same equity price.","Example 3 - 100% cash is more accretive since cash or debt would be less expensive than stock consideration."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Guggenheim Partners Interview","Merger Model (M&A)","Basic"]},{"id":"q-1281","t":"deal","l":"Basic","s":90,"q":"What two companies would you merge right now and why?","k":["Select two companies with clear strategic fit and articulate:","Strategic rationale: Complementary products, geographic expansion, vertical integration, scale benefits.","Synergy opportunities: Specific cost savings (overlapping functions, procurement) and revenue synergies (cross-selling, bundling).","Market dynamics: Industry consolidation trends, competitive pressures, regulatory environment.","Financial impact: Potential for accretion, improved margins, balance sheet optimization.","Integration feasibility: Cultural fit, systems compatibility, management quality.","Choose companies you're knowledgeable about with a compelling, defensible thesis."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Guggenheim Partners Interview","New York office, Superday","Merger Model (M&A)","Basic"]},{"id":"q-1282","t":"deal","l":"Basic","s":90,"q":"An acquirer has a P/E of 10x. There are two potential targets, both being considered for an all-stock transaction:\n\n\n\nTarget A has a P/E of 15x.\nTarget B has a P/E of 5x.\n\n\n\nWhich acquisition would be more accretive to the acquirer's EPS?","k":["Target B would be more accretive.","In an all-stock deal, a transaction is accretive if the acquirer's cost of equity (its earnings yield) is less than the target's earnings yield.","Acquirer's Cost of Equity: 1 / 10x = 10%.","Target A's Yield: 1 / 15x = 6.67%. Since the cost (10%) is greater than the yield, this is dilutive.","Target B's Yield: 1 / 5x = 20%. Since the cost (10%) is less than the yield, this is accretive.","Therefore, acquiring Target B is the more accretive option."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Guggenheim Partners Interview","New York office","Merger Model (M&A)","Basic"]},{"id":"q-1283","t":"deal","l":"Basic","s":90,"q":"Is it better to acquire a company with 100% cash or 100% stock? Why?","k":["There is no universally better option - it depends on the acquirer's circumstances:","100% Cash:","No dilution to existing shareholders.","Faster and simpler to execute.","Better when the acquirer believes its stock is undervalued.","Signals confidence in the deal's value creation.","Downside: May require taking on debt, increasing leverage and interest expense. Uses up cash that could be deployed elsewhere.","100% Stock:","Preserves cash and balance sheet flexibility.","Better when the acquirer believes its stock is overvalued (using expensive currency to buy real assets).","Shares risk with the target's shareholders (they participate in post-deal upside and downside).","Downside: Dilutes existing shareholders. May signal that management thinks the stock is overvalued.","Most deals use a mix of both to balance these considerations."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Guggenheim Partners Interview","SA 2025","Merger Model (M&A)","Basic"]},{"id":"q-1284","t":"deal","l":"Basic","s":90,"q":"Walk me through a Merger Model. Any rules of thumb for knowing if it’s accretive or dilutive?","k":["In a merger model, you combine the buyer’s and target’s financials: revenue, operating expenses, and other items. You then factor in deal financing (cash, debt, stock), potential synergies (cost/revenue), and any one-time transaction costs or new intangible amortization.","To assess accretion/dilution, you compare the combined EPS to the buyer’s standalone EPS. If the combined EPS is higher, it’s accretive; if it’s lower, it’s dilutive.","A quick rule of thumb: If the buyer’s P/E ratio is higher than the target’s P/E ratio (especially in an all-stock deal), the deal is likely accretive because you’re “paying” with shares valued more highly than the target’s earnings yield."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in J.P. Morgan Interview","Merger Model (M&A)","Basic"]},{"id":"q-1285","t":"deal","l":"Basic","s":90,"q":"If a company with a P/E ratio of 10 acquires another company (all stock) with a P/E ratio of 5, will it be accretive or dilutive?","k":["Generally, if the acquirer’s P/E is higher than the target’s P/E (especially in an all-stock deal), the transaction is likely accretive because the acquirer is effectively “buying earnings” more cheaply than the market values its own earnings.","However, you also factor in financing, synergies, and any one-time costs to confirm the final EPS impact."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in J.P. Morgan Interview","Merger Model (M&A)","Basic"]},{"id":"q-1286","t":"deal","l":"Basic","s":90,"q":"When financing an acquisition, why would a company choose to use debt?\n\n\n\n\nWhy might it choose to use equity instead?","k":["Reasons to Use Debt","Tax Shield: Interest expense is tax-deductible, reducing after-tax cost.","Preserve Ownership: Avoids diluting existing shareholders.","Leverage Returns: Amplifies returns if acquisition generates ROI > cost of debt.","Lower Cost of Capital: Debt is typically cheaper than equity.","Reasons to Use Equity","Avoid Leverage Risk: No mandatory interest/principal payments; preserves financial flexibility.","Share Risk with Target: Seller participates in combined company's future performance.","Balance Sheet Constraints: Company already highly levered or lacks debt capacity.","Tax Efficiency for Seller: Stock deals can be tax-deferred for selling shareholders.","Alignment: Stock consideration aligns seller incentives with long-term success."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in J.P. Morgan Interview","SA 2025","Merger Model (M&A)","Basic"]},{"id":"q-1287","t":"deal","l":"Basic","s":90,"q":"A company is acquired for $1.8 billion using 50% debt and 50% equity. Over five years, $450 million of cash flow is used to pay down debt, and the company is exited at 10x $200 million of EBITDA. Would this acquisition likely be pursued by a financial sponsor or a strategic acquirer, and why?","k":["This acquisition structure (50% debt / 50% equity, with debt paydown from cash flows and an exit via sale) is characteristic of a financial sponsor (private equity firm).","Key indicators:","High leverage (50% debt) to amplify returns, typical of PE","Focus on debt paydown using the target's cash flows","Defined hold period (5 years) with a planned exit","Returns measured by MOIC and IRR, which are PE metrics","A strategic acquirer would typically use less leverage, focus on synergies and integration rather than debt paydown, and would not plan to exit the investment."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Jefferies Interview","SA 2027, Aerospace & Defense group, Charlotte Office, First round","Merger Model (M&A)","Basic"]},{"id":"q-1288","t":"deal","l":"Basic","s":90,"q":"Explain the two types of synergies (revenue and cost). If a deal has a $10 increase in revenue synergies versus a $10 decrease in COGS, which would make the deal more accretive, and why?","k":["Revenue synergies come from cross-selling, new market access, or pricing power. Cost synergies come from eliminating redundancies (headcount, facilities, systems).","A $10 decrease in COGS is more accretive than a $10 increase in revenue.","Revenue synergies have associated costs (COGS, SG&A) so $10 in additional revenue does not flow entirely to the bottom line -- only the incremental margin does. A $10 cost reduction, however, flows directly to pre-tax income dollar-for-dollar. Additionally, cost synergies are more certain and faster to realize, which is why the market and buyers place greater confidence in them."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Jefferies Interview","SA 2026, First round","Merger Model (M&A)","Basic"]},{"id":"q-1289","t":"deal","l":"Basic","s":90,"q":"How would you advise a company on whether to raise debt or equity to finance an acquisition?","k":["Key factors to consider:","Current leverage: If the company is already highly levered, additional debt may be impractical or too expensive. Equity may be necessary.","Cost of capital: Debt is cheaper than equity (interest is tax-deductible, and debt holders bear less risk). If the company can comfortably service additional debt, it is typically the preferred financing source.","Stock valuation: If the company's stock is overvalued, issuing equity is attractive since you are using expensive currency. If undervalued, avoid equity dilution and use debt instead.","Cash flow stability: Companies with predictable, recurring cash flows (e.g., subscription businesses) can support more debt. Cyclical businesses should be more conservative.","Target's risk profile: A riskier acquisition may warrant equity to avoid overleveraging.","Market conditions: Credit market availability, interest rate environment, and investor appetite all influence the choice.","EPS impact: Debt financing avoids share dilution and is often more accretive. Stock financing dilutes existing shareholders."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Merger Model (M&A)","Basic"]},{"id":"q-1290","t":"deal","l":"Basic","s":90,"q":"What would you want to evaluate other than the financials when assessing a potential acquisition target?","k":["Management team quality: Track record, depth, retention risk, and willingness to stay post-acquisition.","Strategic fit: Product/service overlap, geographic complementarity, cross-selling opportunities, and alignment with the acquirer's long-term strategy.","Market position: Market share, competitive moat, brand strength, and customer concentration risk.","Cultural compatibility: Differences in corporate culture, management style, and employee expectations that could impede integration.","Regulatory and legal risks: Antitrust concerns, pending litigation, regulatory approvals required, and compliance track record.","Synergy feasibility: Realistic assessment of cost and revenue synergies, integration timeline, and execution risk.","Customer and supplier relationships: Key contract terms, renewal rates, switching costs, and dependency on a small number of counterparties.","Technology and IP: Proprietary technology, patents, data assets, and technical debt."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Merger Model (M&A)","Basic"]},{"id":"q-1291","t":"deal","l":"Basic","s":90,"q":"What are the primary strategic reasons a company would choose to acquire another company?","k":["Core motives:","Cost synergies and scale economics.","Revenue synergies—cross‑selling, new markets.","Access to technology, IP, or talent.","Vertical integration to secure supply or distribution.","Diversification of products or geography.","Defensive move to pre‑empt competitors."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Lazard Interview","Merger Model (M&A)","Basic"]},{"id":"q-1292","t":"deal","l":"Basic","s":90,"q":"In an acquisition involving a low-risk acquirer and a high-risk target, whose WACC should be used to discount the target's cash flows?","k":["Use the target's WACC (or a risk-adjusted rate reflecting the target's risk profile).","The discount rate should reflect the risk of the cash flows being discounted. Since the target's cash flows carry its own business and operational risks, the target's WACC is appropriate.","However, if the acquirer's lower cost of capital will be applied post-acquisition (e.g., refinancing target's debt), you might use the acquirer's WACC for synergies or combined entity valuation, but the standalone target valuation should use target's risk-adjusted rate."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Lazard Interview","SF Office","Merger Model (M&A)","Basic"]},{"id":"q-1293","t":"deal","l":"Basic","s":90,"q":"What are the key considerations if you are on the buy side of an acquisition?","k":["Valuation: Is the price fair relative to comps, precedent transactions, and a DCF? What premium is being paid?","Strategic fit: Does the target complement the acquirer's business? Are there clear synergies (cost savings, revenue growth, market expansion)?","Financing: How will the deal be funded (cash, debt, stock, or a combination)? What is the impact on the balance sheet and credit profile?","Accretion/dilution: Is the deal accretive or dilutive to EPS? If dilutive, how quickly do synergies make it accretive?","Due diligence: Financial, legal, operational, tax, IT, and HR diligence to identify risks and liabilities.","Integration plan: How will the businesses be combined? Cultural fit, technology integration, and potential employee attrition.","Regulatory approval: Antitrust review, industry-specific regulatory hurdles, and timeline to close.","Downside protection: What happens if the thesis doesn't play out? Are there breakup fees, MAE clauses, or other protections?"],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Lincoln International Interview","SA 2025, Superday","Merger Model (M&A)","Basic"]},{"id":"q-1294","t":"deal","l":"Basic","s":90,"q":"Company A has a P/E of 4x, Company B has a P/E of 2x. If A acquires B in an all-stock deal, is it accretive or dilutive?\n\n\n\n\nFollow-up: What if Company B had a P/E of 4x?","k":["Accretive at 2x; neutral at 4x.","B’s 50% earnings yield exceeds A’s 25% cost of equity, boosting EPS; equal P/Es yield neutrality."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in LionTree Interview","SA 2026","Merger Model (M&A)","Basic"]},{"id":"q-1295","t":"deal","l":"Basic","s":90,"q":"How do you find Goodwill in an acquisition?","k":["Goodwill = Purchase Price – Fair Value of identifiable net assets (tangible assets + intangibles – liabilities).","It captures the premium paid for synergies, brand and other unidentifiable assets."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in LionTree Interview","SA 2026","Merger Model (M&A)","Basic"]},{"id":"q-1296","t":"deal","l":"Basic","s":90,"q":"Would a strategic buyer or a financial sponsor be willing to pay more for the same company? Why?","k":["A strategic buyer can typically pay more than a financial sponsor.","Strategic buyers can realize synergies (cost savings, revenue enhancement, elimination of redundant functions) that a financial sponsor cannot. These synergies effectively reduce the net cost of the acquisition.","Strategic buyers do not need to achieve a specific IRR threshold. They can justify a higher price based on long-term strategic value, market share gains, or competitive positioning.","Financial sponsors must hit a target IRR (typically 20-25%) and rely heavily on leverage to generate returns. This constrains the price they can pay.","Financial sponsors also need management to run the business post-acquisition, while strategics can integrate and manage it themselves.","Exception: A financial sponsor may pay more in competitive auctions if they have a strong proprietary angle, a platform company that creates synergies, or if they use more aggressive leverage assumptions."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in LionTree Interview","SA 2027, New York Office, First round","Merger Model (M&A)","Basic"]},{"id":"q-1297","t":"deal","l":"Basic","s":90,"q":"What should a company consider when deciding whether to pursue M&A now or six months down the line?","k":["Market conditions: Are valuations favorable now? Could multiples change?","Interest rate environment: Financing costs may rise or fall.","Regulatory landscape: Potential changes in antitrust scrutiny or industry regulations.","Competitive dynamics: Another buyer may act first if you wait.","Target's performance trajectory: Is the target's valuation likely to increase or decrease?","Integration readiness: Does the acquirer have the bandwidth and resources to integrate now?","Stock price: If paying with stock, is the acquirer's share price at a favorable level?","Strategic urgency: How critical is the acquisition to the company's strategic plan?"],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Mizuho Interview","SA 2027, Superday","Merger Model (M&A)","Basic"]},{"id":"q-1298","t":"deal","l":"Basic","s":90,"q":"What does it mean for an M&A transaction to be accretive or dilutive, and what is the basic calculation to determine this?","k":["Accretive if pro‑forma EPS exceeds the acquirer’s standalone EPS; dilutive if it falls.","Calculation:","% Δ EPS = (PF EPS ∕ Standalone EPS) − 1.","Positive result → accretion; negative → dilution."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Moelis & Co. Interview","Merger Model (M&A)","Basic"]},{"id":"q-1299","t":"deal","l":"Basic","s":90,"q":"What are the primary pros and cons of selling a company to a financial sponsor versus a strategic buyer?","k":["Financial Sponsor (PE Firm)","Pros:","Faster deal execution and higher certainty of close.","Less regulatory scrutiny (no antitrust concerns).","Confidentiality maintained.","Cons:","Lower purchase price (no synergies to pay for).","Financing contingency risk.","Strategic Buyer","Pros:","Higher valuation (can pay for cost and revenue synergies).","Balance sheet financing (no financing risk).","Cons:","Longer timeline and regulatory approval needed.","Integration risk and potential job losses.","Confidential information shared with competitor."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Moelis & Co. Interview","New York Office, First round","Merger Model (M&A)","Basic"]},{"id":"q-1300","t":"deal","l":"Basic","s":90,"q":"What does it mean for a transaction to be accretive or dilutive?\n\n\n\n\nFollow-up 1: What are the key factors that impact the accretion or dilution of a transaction? Please explain each.","k":["A transaction is accretive if the acquirer's pro-forma EPS increases, and dilutive if it decreases.","Follow-up 1: Key Factors","Purchase Price / Target's Earnings: Higher price relative to earnings makes dilution more likely.","Form of Consideration: Stock dilutes shares; cash/debt avoids dilution but has other costs.","Cost of Financing: Higher interest rates (debt) or expensive equity reduces accretion.","Synergies: Cost savings or revenue synergies improve pro-forma earnings.","Relative Valuations: Acquirer's P/E vs. Target's P/E (or earnings yield) determines accretion/dilution.","General rule: If Cost of Financing < Target's Earnings Yield, deal is accretive. If Cost > Yield, dilutive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Moelis & Co. Interview","Merger Model (M&A)","Basic"]},{"id":"q-1301","t":"deal","l":"Basic","s":90,"q":"Company A is considering acquiring Company B in an all-stock transaction. Company A's P/E ratio is 55x, whereas Company B's P/E ratio is 30x.\n\n\n\n\nAfter the acquisition, will Company A's EPS rise, fall, or stay the same?","k":["Company A's EPS will rise (accretive).","Reasoning:","A's P/E (55x) > B's P/E (30x).","A's Cost of Equity = 1/55 = 1.82%.","B's Earnings Yield = 1/30 = 3.33%.","Since Cost (1.82%) < Yield (3.33%), the deal is accretive.","When an acquirer with a higher P/E buys a target with a lower P/E using stock, it's typically accretive because the acquirer is using \"expensive\" currency to buy \"cheaper\" earnings."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Moelis & Co. Interview","Merger Model (M&A)","Basic"]},{"id":"q-1302","t":"deal","l":"Basic","s":90,"q":"If you were the CEO of a company and could acquire either Company A or Company B for the same price of $100 million, how would you decide which one to acquire?","k":["Key considerations for choosing between A and B:","Strategic Fit: Which aligns better with our long-term strategy, core competencies, and market positioning?","Synergies: Which offers greater cost savings, revenue synergies, or operational efficiencies?","Financial Performance: Compare profitability, growth rates, cash flow generation, and returns.","Risk Profile: Assess industry volatility, customer concentration, regulatory exposure.","Cultural Fit: Compatibility of management teams, corporate cultures, and values.","Integration Complexity: Which is easier to integrate (systems, processes, people)?","Market Opportunity: Which provides access to faster-growing or more attractive markets?","The decision balances financial returns, strategic value, execution risk, and long-term competitive advantage."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Moelis & Co. Interview","Merger Model (M&A)","Basic"]},{"id":"q-1303","t":"deal","l":"Basic","s":90,"q":"Walk me through a basic merger model. Assume a 100% cash deal. Calculate the pro forma EPS and determine whether the deal is accretive or dilutive.","k":["Start with the acquirer's standalone EPS (Net Income / Shares Outstanding).","Determine the purchase price and financing. In a 100% cash deal, the acquirer uses cash or raises debt.","Calculate the lost interest income on cash (or new interest expense on debt), after tax.","Pro Forma NI = Acquirer NI + Target NI - After-Tax Financing Cost (+/- synergies).","Pro Forma EPS = Pro Forma NI / Acquirer Shares (no new shares in a cash deal).","If Pro Forma EPS > standalone EPS, the deal is accretive. If lower, dilutive.","Quick test: Compare the target's earnings yield (NI / Purchase Price) to the after-tax cost of financing. If the yield exceeds the cost, the deal is accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Moelis & Co. Interview","SA 2026, First round","Merger Model (M&A)","Basic"]},{"id":"q-1304","t":"deal","l":"Basic","s":90,"q":"If you’re projecting a deal is dilutive, how can you adjust the considerations to make it accretive?","k":["Pay more cash instead of stock (if the cost of cash/debt is lower)","Negotiate a lower purchase price / multiple","Realize more cost or revenue synergies","Change the capital structure (e.g., reduce expensive debt)"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Morgan Stanley Interview","Merger Model (M&A)","Basic"]},{"id":"q-1305","t":"deal","l":"Basic","s":90,"q":"What is a CIM, and what are the typical sections or components of it?","k":["A Confidential Information Memorandum is the primary sell‑side marketing document.","Executive summary & investment highlights.","Industry overview and competitive landscape.","Company history, products, customers, and strategy.","Historical & projected financials.","Management biographies.","Transaction structure, timeline, and contacts."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Morgan Stanley Interview","Merger Model (M&A)","Basic"]},{"id":"q-1306","t":"deal","l":"Basic","s":90,"q":"What are the two primary ways an acquisition can create value for the acquirer's shareholders?","k":["Pay less than intrinsic value and realize synergies.","Value arbitrage – buying a business below its standalone NPV or at a lower multiple than the acquirer trades.","Synergies – capturing cost savings and revenue enhancements that raise combined free cash flow."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Morgan Stanley Interview","Merger Model (M&A)","Basic"]},{"id":"q-1307","t":"deal","l":"Basic","s":90,"q":"In an M&A transaction, would a buyer typically pay a higher premium in an all-stock deal or an all-cash deal?","k":["Typically, buyers pay higher premiums in all-stock deals.","Stock consideration allows buyers to share risk with target shareholders—if synergies don't materialize or integration fails, target shareholders bear some downside as equity holders.","Cash deals place all risk on the buyer, making them more disciplined on valuation. Additionally, stock deals may signal buyer's shares are overvalued, so sellers demand higher premiums as compensation.","However, in practice, deal dynamics vary: cash deals provide certainty and immediate liquidity to sellers, which may justify different pricing depending on market conditions and seller preferences."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Morgan Stanley Interview","SF Office","Merger Model (M&A)","Basic"]},{"id":"q-1308","t":"deal","l":"Basic","s":90,"q":"What is the difference between a strategic acquirer and a financial sponsor? As a company owner, which would you prefer to sell to? As a banker, which type of buyer would you rather advise?","k":["Strategic Acquirer","An operating company acquiring another company for synergies, market share, technology, or vertical integration.","Typically pays a higher price because it can realize cost and revenue synergies that justify a premium.","Holds the asset indefinitely as part of its operations.","Financial Sponsor (PE Firm)","A private equity firm acquiring a company primarily for financial returns.","Uses significant leverage, focuses on operational improvements, and targets an exit in 5-7 years.","Typically pays less than a strategic because synergies are limited and return requirements (20%+ IRR) constrain the price.","As a Seller:","Prefer a strategic buyer for the higher price. However, a sponsor may be preferred if the owner wants to retain a stake and participate in future upside (e.g., a management rollover).","As a Banker:","Advising strategics often involves larger, more complex deals with higher fees. Advising sponsors generates repeat business since PE firms do many transactions. Both are attractive for different reasons."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Morgan Stanley Interview","SA 2026, First round","Merger Model (M&A)","Basic"]},{"id":"q-1309","t":"deal","l":"Basic","s":90,"q":"What is the difference between a Strategic Buyer and a PE firm when looking at a company?","k":["Strategic Buyer","An operating company acquiring a target to realize synergies (revenue or cost) with its existing business.","Can pay a higher price because the combined entity is worth more than the sum of the parts — synergies justify a premium.","Typically uses a mix of cash and stock. Often integrates the target fully and retains limited existing management.","Evaluates the deal on accretion/dilution to EPS and strategic fit.","Private Equity (Financial Buyer)","A financial sponsor acquiring the target primarily to generate a return on invested equity, typically targeting a 20%+ IRR over a 3-7 year hold period.","Uses significant leverage (debt) to amplify equity returns — paying a lower equity check for the same enterprise value.","Retains and incentivizes existing management with equity rollover. Does not realize traditional operating synergies.","Evaluates the deal on IRR, MOIC, and the ability to de-lever and grow EBITDA for a higher exit multiple.","Strategics generally pay more because synergies offset the premium. PE firms are disciplined on price because returns are driven by the entry multiple, leverage, and operational improvement — overpaying kills the IRR."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Rothschild Interview","SA 2027, Global Advisory group, New York Office, First round","Merger Model (M&A)","Basic"]},{"id":"q-1310","t":"deal","l":"Basic","s":90,"q":"You are tasked with preparing a pitch book for a CEO whose company is considering a sale.\n\n\n\n\nWhat key topics and analyses would you include in this presentation?","k":["Key sections:","Executive Summary: Transaction rationale and process overview.","Company Overview: Business description, products/services, competitive positioning.","Industry Analysis: Market size, growth trends, competitive landscape.","Financial Analysis: Historical performance, projections, key metrics.","Valuation: Comparable companies, precedent transactions, DCF analysis.","Potential Buyers: Strategic and financial buyer universe with rationale.","Process & Timing: Auction vs. targeted process, timeline, confidentiality considerations.","Transaction Considerations: Tax, regulatory, antitrust issues.","Bank Credentials: Relevant experience and qualifications."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Basic"]},{"id":"q-1311","t":"deal","l":"Basic","s":90,"q":"Would a CEO ever pursue a dilutive acquisition? If so, why?","k":["Yes, CEOs may pursue dilutive deals for strategic reasons:","Long-term synergies expected to create future accretion","Acquiring critical technology, IP, or talent","Achieving market leadership or strategic positioning","Entering high-growth markets or verticals","Defensive necessity to prevent competitor acquisition","Near-term dilution offset by long-term value creation","Short-term EPS dilution may be acceptable if the strategic rationale drives long-term shareholder value."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Basic"]},{"id":"q-1312","t":"deal","l":"Basic","s":90,"q":"Company A has a P/E multiple of 10x, a pre-tax cost of debt of 5%, and a 40% tax rate. It is acquiring Company B, which has a P/E multiple lower than A's.\n\n\n\n\nTo maximize accretion, should Company A finance the deal with debt or stock? Explain your reasoning.","k":["Company A should use debt financing to maximize accretion, assuming B's P/E is meaningfully lower than A's.","Analysis:","A's cost of equity (earnings yield): 1 / 10x = 10%","A's after-tax cost of debt: 5% * (1 - 40%) = 3%","Since debt (3%) is cheaper than equity (10%), debt financing maximizes accretion","This holds true as long as B's earnings yield (1 / P/E) exceeds 3%","Given B's P/E < 10x, B's yield > 10% > 3%, so debt financing is optimal"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Basic"]},{"id":"q-1313","t":"deal","l":"Basic","s":90,"q":"Walk me through the sell-side M&A process, including the names of key legal documents.","k":["Key stages and documents:","Preparation: Financial and legal due diligence, create Confidential Information Memorandum (CIM)","Marketing: Distribute CIM to qualified buyers under Non-Disclosure Agreement (NDA)","Initial bids: Buyers submit non-binding Indications of Interest (IOI)","Management presentations: Selected buyers meet management, access data room","Final bids: Buyers submit binding Letters of Intent (LOI) or Purchase Agreement drafts","Negotiation: Finalize Purchase Agreement, negotiate reps/warranties, indemnities","Signing: Execute definitive Purchase Agreement","Closing: Satisfy closing conditions, obtain regulatory approvals, fund transaction"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Basic"]},{"id":"q-1314","t":"deal","l":"Basic","s":90,"q":"Walk me through how you would take a coffee mug company to market in a sell-side M&A process.\n\n\n\n\nAs a follow-up, what types of buyers would you target?","k":["Process:","Preparation: Quality of earnings, normalized EBITDA, growth story, create CIM","Positioning: Emphasize brand, customer relationships, manufacturing capabilities","Marketing: Targeted outreach to strategic and financial buyers","Buyer meetings: Management presentations, facility tours","Bids and negotiation: IOIs, LOIs, final purchase agreement","Target Buyers:","Strategic: Larger consumer products companies (P&G, Newell), drinkware players (Tervis, YETI)","PE: Consumer-focused funds seeking platform or add-on acquisition","International: Foreign manufacturers seeking US market entry or distribution","Competitors: Direct competitors looking to consolidate"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Basic"]},{"id":"q-1315","t":"deal","l":"Basic","s":90,"q":"You are analyzing a potential acquisition with the following details:\n\n\n\nAcquirer (Company A): 25x P/E ratio, 10 shares outstanding, $25 share price, $10 of Net Income.\nTarget (Company B): 15x P/E ratio, $10 of Net Income.\nTransaction: Company A acquires Company B for a purchase price of $150.\n\n\n\nAssuming the transaction is financed with 100% cash, answer the following:\n\n\n\n\nPart 1: Is this transaction accretive or dilutive?\n\nPart 2: By what percentage?","k":["Part 1: Accretion / Dilution","The deal is accretive.","Target Yield = 1 / 15x P/E = 6.67%.","A's Cost of Cash = 0% (no interest foregone).","Since Cost (0%) < Yield (6.67%), it's accretive.","Part 2: Accretion Percentage","Answer: 100% accretive","A's Standalone EPS = $10 / 10 shares = $1.00.","Pro Forma NI = $10 + $10 = $20.","Pro Forma Shares = 10 (unchanged in cash deal).","Pro Forma EPS = $20 / 10 = $2.00.","Accretion = ($2.00 / $1.00) - 1 = 100%.","Note: This assumes no financing costs and full contribution from target NI."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Basic"]},{"id":"q-1316","t":"deal","l":"Basic","s":90,"q":"In which scenario would an acquirer typically pay a higher premium: an all-stock deal or an all-cash deal? Why?","k":["All-cash deals typically command higher premiums.","Reasons:","Certainty of Value: Cash is guaranteed. Sellers take on no risk regarding the future performance of the buyer's stock.","Immediate taxation: Sellers are taxed immediately on cash proceeds, so they demand a higher price to offset the tax hit.","No future upside: Sellers in a cash deal are bought out entirely and cannot participate in the combined company's future synergies.","Conversely, stock deals allow sellers to share in the risk/reward of the newly combined entity and can defer taxes (depending on deal structure), often lowering the required premium."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Basic"]},{"id":"q-1317","t":"deal","l":"Basic","s":90,"q":"Part 1: Would a seller prefer a stock purchase or an asset purchase? Why?\n\n\n\n\nPart 2: Would a buyer prefer a stock purchase or an asset purchase? Why?","k":["Part 1: Seller Preference","Sellers typically prefer stock purchases.","Tax treatment: Capital gains tax (often lower) vs. ordinary income tax on assets.","Simplicity: Transfer ownership of entire entity rather than individual assets.","No recapture: Avoids depreciation recapture on assets sold.","Part 2: Buyer Preference","Buyers typically prefer asset purchases.","Tax benefit: Step-up in asset basis allows higher depreciation/amortization deductions.","Liability protection: Buyer avoids inheriting unknown or contingent liabilities.","Flexibility: Cherry-pick specific assets and liabilities to acquire."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Superday","Merger Model (M&A)","Basic"]},{"id":"q-1318","t":"deal","l":"Basic","s":90,"q":"Why is Earnings Per Share (EPS) a key metric in M&A deals?","k":["EPS is a key metric because it directly impacts shareholder value and stock price perception.","Market Signal: Accretive deals (higher EPS) are viewed positively by investors.","Management Incentives: Executive compensation often tied to EPS targets.","Valuation Impact: EPS growth can drive higher P/E multiples and stock prices.","Shareholder Focus: Investors closely monitor EPS impact when evaluating deals.","However, EPS doesn't capture cash flow, debt levels, or long-term strategic value, so it shouldn't be the only consideration."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Superday","Merger Model (M&A)","Basic"]},{"id":"q-1319","t":"deal","l":"Basic","s":90,"q":"Part 1: As the CFO of a target company, what are your thoughts on accepting a 100% stock deal from an acquirer in the current market environment?\n\n\n\n\nPart 2: As the CFO of the acquirer, what form of consideration (cash, debt, stock) would you prefer to use and why?","k":["Part 1: Target CFO Perspective","Considerations for accepting 100% stock:","Market Volatility: Stock consideration exposes seller to acquirer's price fluctuations.","Tax Deferral: Stock deals can defer capital gains taxes.","Upside Participation: Shareholders benefit from combined company's future performance.","Acquirer Quality: Depends on acquirer's financial health and growth prospects.","Part 2: Acquirer CFO Perspective","Preferred consideration depends on circumstances:","Stock: Conserves cash, avoids leverage, shares risk with target shareholders. Best when acquirer's stock is overvalued.","Cash: Provides certainty to seller, faster close. Best when acquirer has excess cash or cheap financing.","Debt: Preserves equity, tax-deductible interest. Best when rates are low and cash flows are strong."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Superday","Merger Model (M&A)","Basic"]},{"id":"q-1320","t":"deal","l":"Basic","s":90,"q":"If you owned a business, what would be your ideal method for it to be purchased? Discuss the pros and cons of different acquisition methods.","k":["As a seller, the ideal method depends on objectives:","All-Cash Acquisition","Pros:","Immediate liquidity and certainty of value.","No exposure to buyer's future performance.","Clean exit.","Cons:","Immediate taxable event.","No upside if buyer creates significant value.","All-Stock Acquisition","Pros:","Tax deferral benefits.","Continued participation in combined entity's upside.","Cons:","Exposure to buyer's stock volatility and execution risk.","Less immediate liquidity.","Mixed Consideration","Often ideal: Provides immediate cash while retaining upside through equity rollover. Balances liquidity, tax efficiency, and ongoing participation."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Wells Fargo Interview","Superday","Merger Model (M&A)","Basic"]},{"id":"q-1321","t":"deal","l":"Advanced","s":90,"q":"How do you think about short-term accretion/dilution vs. long-term synergies? Would you ever buy a dilutive deal?","k":["In the short term, you look at whether the deal is accretive or dilutive to EPS. That’s often driven by the relative P/E ratios (acquirer vs. target), deal financing (cash, debt, or stock), and near-term cost synergies.","In the long term, a deal might initially appear dilutive—e.g., if the target trades at a higher P/E in a stock deal, or if the after-tax interest cost on new debt exceeds the target’s earnings yield—but could still create strategic value through revenue or cost synergies over time.","Companies sometimes buy a dilutive deal if longer-term synergies and strategic benefits outweigh immediate EPS dilution; rule of thumb: stock deals hinge on relative P/Es, while cash/debt deals hinge on earnings yield vs. after-tax financing cost."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Bank of America Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1322","t":"deal","l":"Advanced","s":90,"q":"Company A and Company B each have revenue of $100.\n\n\n\n\nWhen combined, their total revenue is $220, without synergies.\n\n\n\n\nHow is that possible?","k":["The two companies report on different fiscal calendars, so their last‑twelve‑month periods overlap.","Adding both LTM figures double‑counts six months of sales, creating the apparent $20 “extra” revenue without any operational synergy."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Bank of America Interview","Chicago office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1323","t":"deal","l":"Advanced","s":90,"q":"You are analyzing a potential M&A transaction with the following facts:\n\n\n\nBuyer: Share Price = $10, EPS = $2, 50 shares outstanding.\nTarget: EPS = $0.50, P/E = 10x, 50 shares outstanding.\n\n\n\nAnswer the following questions:\n\n\n\nWhat is the Buyer's P/E ratio?\nWhat is the Target's stock price?\nIf the Buyer acquires the Target in a 100% stock deal with no premium, what is the pro-forma EPS? Is the deal accretive or dilutive?\nGiven that the deal is dilutive, why might the Buyer still pursue it?\nAfter including synergies, the pro-forma EPS is expected to be $1.90 in perpetuity. As a board member of the Buyer, what would you care about most?\nWhat will the P/E ratio of the combined company likely be after the transaction?","k":["Part 1: Buyer's P/E Ratio","Answer: 5x","P/E = Share Price / EPS = $10 / $2 = 5x","Part 2: Target's Stock Price","Answer: $5","Stock Price = EPS * P/E = $0.50 * 10x = $5","Part 3: Pro-Forma EPS & Accretion","Answer: $1.67 EPS, Dilutive","Buyer NI = $2 * 50 = $100","Target NI = $0.50 * 50 = $25","Target Market Cap = $5 * 50 = $250","Shares Issued = $250 / $10 = 25 shares","PF Shares = 50 + 25 = 75 shares","PF NI = $100 + $25 = $125","PF EPS = $125 / 75 = $1.67","Since $1.67 < $2.00, the deal is dilutive","Part 4: Why Pursue Dilutive Deal?","Strategic reasons:","Long-term synergies or revenue growth opportunities","Strategic market positioning or competitive advantages","Access to new markets, customers, or technologies","Defensive necessity or preventing competitor acquisition","Part 5: Board Member Priorities","Key concerns:","Whether the synergies are achievable and timeline for realization","Integration risks and execution capabilities","Impact on long-term shareholder value creation","Alternative uses of capital and opportunity cost","Strategic fit and cultural compatibility","Part 6: Pro-Forma P/E Ratio","Answer: Between 5x and 10x, likely closer to buyer's 5x","PF EPS (with synergies) = $1.90","The market will likely assign a P/E closer to the buyer's multiple (5x) given its larger size","Implied PF Stock Price = $1.90 * 5x = $9.50","However, the actual multiple depends on market perception"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Bank of America Interview","Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1324","t":"deal","l":"Advanced","s":90,"q":"What factors should a company consider when deciding between a spin-off and a divestiture?","k":["Key considerations:","Spin-off advantages:","Tax-free to shareholders if structured properly (vs. taxable sale in divestiture)","Shareholders retain exposure to both entities","No immediate cash proceeds but unlocks shareholder value","Avoids need to find buyer or negotiate price","Divestiture advantages:","Generates immediate cash for debt paydown or reinvestment","Clean break from divested business","Can sell to strategic buyer at premium valuation","Faster execution if buyer identified","Decision factors:","Need for cash vs. shareholder value creation","Tax implications for company and shareholders","Strategic fit and potential buyer universe","Business standalone viability and scale","Market conditions and valuation environment","Regulatory and antitrust considerations"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Bank of America Interview","Industrials group, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1325","t":"deal","l":"Advanced","s":90,"q":"An acquirer has a P/E of 10x, 100 shares outstanding, a share price of $100, and a 20% tax rate. The target has a P/E of 15x, 100 shares outstanding, and a share price of $30.\n\n\n\n\nPart 1: In an all-stock deal, is this transaction accretive or dilutive?\n\n\n\n\nPart 2: How much additional pre-tax income (EBT) would be needed to make the deal accretive?","k":["Part 1: Accretive or Dilutive?","Dilutive.","Acquirer P/E = 10x (earnings yield = 10%). Target P/E = 15x (earnings yield = 6.67%).","The acquirer is buying at a higher P/E than its own, meaning it is paying more per dollar of target earnings than the market values its own earnings. This is dilutive.","Part 2: Additional EBT to Break Even","Acquirer EPS = Share Price / P/E = $100 / 10 = $10. Acquirer NI = $10 x 100 = $1,000.","Target Equity Value = $30 x 100 = $3,000. Exchange ratio = $30 / $100 = 0.30. New shares issued = 100 x 0.30 = 30.","Target NI = Share Price x Shares / P/E = $3,000 / 15 = $200.","Pro forma: Combined NI = $1,000 + $200 = $1,200. Pro forma shares = 130. Pro forma EPS = $1,200 / 130 = $9.23.","To be accretive, need pro forma EPS > $10. Need combined NI > $10 x 130 = $1,300.","Shortfall = $1,300 - $1,200 = $100 of additional NI needed.","Additional pre-tax income (EBT) = $100 / (1 - 20%) = $125."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Bank of America Interview","SA 2026, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1326","t":"deal","l":"Advanced","s":90,"q":"Company A acquires Company B using 50% cash and 50% debt. Company B has a P/E of 16x. The pre-tax cost of cash (foregone interest income) is 5% and the cost of debt is 10%. Assume a 20% tax rate. Is this deal accretive or dilutive?","k":["Answer: Marginally accretive.","Target earnings yield = 1 / P/E = 1/16 = 6.25%","After-tax cost of cash = 5% x (1 - 20%) = 4% (foregone interest income is taxable)","After-tax cost of debt = 10% x (1 - 20%) = 8%","Blended after-tax cost of financing = 50% x 4% + 50% x 8% = 2.0% + 4.0% = 6.0%","6.0% < 6.25% → the deal is marginally accretive","The key insight is that the cost of cash must be tax-affected because foregone interest income is taxable. This is what makes the deal accretive rather than dilutive — without the tax adjustment on cash, the blended cost would be 6.5%, which would exceed the 6.25% earnings yield."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Bank of America Interview","Emerging Growth & Regional Coverage group, SF Office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1327","t":"deal","l":"Advanced","s":90,"q":"Company A acquires Company B. The purchase price is $150 million. Company A has 10 million shares outstanding, a share price of $25, and net income of $10 million. Company B has net income of $10 million. If the deal is 100% stock, is the deal accretive or dilutive? If it is accretive, what are three reasons it could become dilutive instead?","k":["The deal is accretive.","Calculation:","Acquirer pre-deal EPS = $10M / 10M shares = $1.00","Acquirer P/E = $25 / $1.00 = 25.0x","Target implied P/E = $150M / $10M = 15.0x","New shares issued = $150M / $25 = 6M shares","Pro forma NI = $10M + $10M = $20M","Pro forma shares = 10M + 6M = 16M","Pro forma EPS = $20M / 16M = $1.25 vs. pre-deal $1.00","Since the acquirer's P/E (25x) is higher than the target's effective P/E (15x), the deal is accretive.","Three reasons it could become dilutive:","Integration costs and restructuring charges reduce combined net income in the near term.","Revenue dis-synergies (e.g., customer attrition, key employee departures) cause the target's earnings to decline post-acquisition.","Financing structure changes: If the acquirer takes on debt to fund part of the deal, interest expense could erode the combined earnings enough to make it dilutive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Bank of America Interview","SA 2026, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1328","t":"deal","l":"Advanced","s":90,"q":"Company A has 10 shares outstanding at $25 per share and Net Income of $10. It acquires Company B, which has Net Income of $10, for $150 in an all-stock deal. What is the percentage accretion or dilution?","k":["Answer: 25% accretive","Calculation:","Company A pre-deal EPS = $10 NI / 10 shares = $1.00","New shares issued = $150 / $25 per share = 6 new shares","Combined NI = $10 + $10 = $20","New share count = 10 + 6 = 16 shares","Pro forma EPS = $20 / 16 = $1.25","Accretion = ($1.25 - $1.00) / $1.00 = 25%","The deal is accretive because the acquirer's P/E of 25.0x ($250 / $10) exceeds the effective target P/E of 15.0x ($150 / $10). In an all-stock deal, buying a company at a lower P/E than your own is accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Barclays Interview","SF Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1329","t":"deal","l":"Advanced","s":90,"q":"You are given the following information for a merger:\n\n\n\nCompany A: Net Income $100M, EPS $0.50, Share Price $10, EBITDA $200M\nCompany B: Net Income $50M, EPS $1.00, Share Price $30, EBITDA $150M\nPurchase Price: $2B, 50% stock / 50% cash\nAssume a 2% pre-tax return on cash and a 20% tax rate.\n\n\n\nPart 1: What is the premium paid?\n\n\n\n\nPart 2: Is the transaction accretive or dilutive to Company A?","k":["Part 1: Premium Paid","Answer: 33.3% premium","Company B shares outstanding = NI / EPS = $50M / $1.00 = 50M shares","Company B equity value = 50M x $30 = $1,500M","Premium = ($2,000M - $1,500M) / $1,500M = 33.3%","Part 2: Accretive or Dilutive","The deal is dilutive.","Company A shares outstanding = NI / EPS = $100M / $0.50 = 200M shares","Company A P/E = $10 / $0.50 = 20x","Implied acquisition P/E = $2,000M / $50M = 40x","Company A is paying 40x for Company B's earnings vs. its own 20x P/E -- dilutive.","New shares issued = $1B stock / $10 = 100M new shares","Foregone after-tax interest on $1B cash = $1,000M x 2% x (1 - 20%) = $16M.","Combined NI = $100M (Acquirer) + $50M (Target) - $16M (foregone interest) = $134M","New shares = 200M + 100M = 300M","Pro forma EPS = $134M / 300M = $0.45. Deal is dilutive ($0.45 vs. $0.50 standalone, or ~10% dilutive). The dilution is driven by the high acquisition P/E (40x) relative to the acquirer's P/E (20x), compounded by the foregone interest on the cash portion."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Barclays Interview","SA 2026, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1330","t":"deal","l":"Advanced","s":90,"q":"Company A has $40 in earnings and 10 shares outstanding. It buys Company B, which has $25 in earnings and 5 shares outstanding. The purchase price is 12.0x Company B's earnings, paid for with cash raised from new debt at a 6% interest rate. The tax rate for both companies is 40%. What is the accretion per share for Company A?","k":["≈ $1.42 accretive per share.","Steps:","Purchase price = 12 × 25 = 300.","Interest expense = 300 × 6% = 18; after‑tax cost = 10.8.","Incremental NI = 25 − 10.8 = 14.2.","Pro‑forma NI = 40 + 14.2 = 54.2.","EPS goes from 4.0 to 5.42 ⇒ +1.42."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Centerview Partners Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1331","t":"deal","l":"Advanced","s":90,"q":"If I give you a company with a P/E ratio that suggests an M&A deal is neither accretive nor dilutive, what else would you want to know to figure out if it’s a good idea?","k":["You'd want to see the target’s growth prospects, margins, synergy potential, cultural fit, and any one-time integration costs.","Also, financing structure matters. For example, if the acquirer uses debt (and at what cost), how the combined capital structure looks, and whether there are intangible benefits like new technology or market expansion that might justify a deal even if it’s not immediately accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Citi Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1332","t":"deal","l":"Advanced","s":90,"q":"Company A is considering acquiring Company B in an all-stock transaction. The financial data for each company is as follows:\n\n\n\nCompany A: 100 shares outstanding, $5/share, $50 Net Income\nCompany B: 50 shares outstanding, $10/share, $20 Net Income\n\n\n\nAnswer the following:\n\nIs the transaction accretive or dilutive for Company A?\nIf the combined company could achieve $50 in after-tax synergies, would the deal become accretive or dilutive, and by how much per share?","k":["Part 1: Accretion/Dilution Analysis","A's Standalone EPS = $50 NI / 100 shares = $0.50.","B's Equity Value = $10 * 50 shares = $500.","Shares Issued = $500 / $5 (A share price) = 100 shares.","Pro Forma Shares = 100 + 100 = 200.","Pro Forma NI = $50 + $20 = $70.","Pro Forma EPS = $70 / 200 = $0.35.","The deal is dilutive ($0.35 < $0.50).","Part 2: With $50 Synergies","Pro Forma NI with Synergies = $70 + $50 = $120.","Pro Forma EPS = $120 / 200 = $0.60.","The deal becomes accretive ($0.60 > $0.50), with $0.10 accretion per share."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Citi Interview","Chicago office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1333","t":"deal","l":"Advanced","s":90,"q":"Company A is acquiring Company B. Calculate the pro-forma EPS given the following:\n\n\n\n\nAcquirer A:\n\nEPS = $1.00\nP/E = 20x\nShares Outstanding = 10\n\n\n\nTarget B:\n\nEPS = $2.00\nP/E = 4x\nShares Outstanding = 5\n\n\n\nDeal Terms & Assumptions:\n\nPremium: 25%\nFinancing: 50% debt, 50% stock\nCost of Debt: 10%\nTax Rate: 25%","k":["Answer: $1.61 PF EPS","Calculation:","A's NI = $1.00 * 10 = $10","B's NI = $2.00 * 5 = $10","B's Stock Price = $2.00 * 4x = $8","B's Market Cap = $8 * 5 = $40","Purchase Price = $40 * (1 + 25%) = $50","Debt Financing = $50 * 50% = $25","Stock Financing = $50 * 50% = $25","A's Stock Price = $1.00 * 20x = $20","Shares Issued = $25 / $20 = 1.25 shares","PF Shares = 10 + 1.25 = 11.25 shares","Interest Expense = $25 * 10% = $2.50","After-Tax Interest = $2.50 * (1 - 25%) = $1.875","PF NI = $10 + $10 - $1.875 = $18.125","PF EPS = $18.125 / 11.25 = $1.61"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Citi Interview","Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1334","t":"deal","l":"Advanced","s":90,"q":"If a company has a leverage ratio of 3x Total Debt / EBITDA, how could it structure an acquisition to lower its leverage ratio?","k":["Ways to lower leverage ratio post-acquisition:","Use cash or equity financing instead of debt to fund the acquisition","Acquire a company with higher EBITDA to increase denominator (if using minimal debt)","Target a company with low or no debt to avoid adding to numerator","Generate synergies that increase combined EBITDA","Use target's excess cash to pay down acquirer's existing debt","Structure earn-outs or deferred payments to reduce upfront debt financing","Divest non-core assets post-acquisition to pay down debt","The key is ensuring the combined EBITDA increases more than the combined debt, improving the overall leverage ratio."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Citi Interview","Houston office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1335","t":"deal","l":"Advanced","s":90,"q":"You are analyzing a potential acquisition with the following details:\n\n\n\nAcquirer A: Sales $100, NI Margin 10%, Share Price $20, Shares Outstanding 10\nTarget B: Sales $200, NI Margin 10%, Share Price $10, Shares Outstanding 20\n\n\n\nPart 1: Is a 100% stock-financed acquisition accretive or dilutive?\n\n\n\n\nPart 2: Assuming a 5% cost of debt and a 25% tax rate, is a 100% debt-financed acquisition accretive or dilutive?","k":["Part 1: Stock-Financed Acquisition","The deal is accretive.","A's NI = $100 * 10% = $10","A's Standalone EPS = $10 / 10 = $1.00","B's NI = $200 * 10% = $20","B's Market Cap = $10 * 20 = $200","Shares Issued = $200 / $20 = 10 shares","PF Shares = 10 + 10 = 20","PF NI = $10 + $20 = $30","PF EPS = $30 / 20 = $1.50","Accretion = ($1.50 / $1.00) - 1 = 50%","Part 2: Debt-Financed Acquisition","The deal is accretive.","Purchase Price = $200 (B's Market Cap)","New Debt = $200","Interest Expense = $200 * 5% = $10","After-Tax Interest = $10 * (1 - 25%) = $7.50","PF NI = $10 + $20 - $7.50 = $22.50","PF EPS = $22.50 / 10 = $2.25","Accretion = ($2.25 / $1.00) - 1 = 125%"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Citi Interview","First round","Merger Model (M&A)","Advanced"]},{"id":"q-1336","t":"deal","l":"Advanced","s":90,"q":"You are given the following information:\n\n\n\nCompany A: 100 shares outstanding, $50 share price, $50 Net Income\nCompany B: 50 shares outstanding, $10 share price, $20 Net Income\n$50 in after-tax synergies\n\n\n\nCompany A acquires Company B in an all-stock deal. Is this transaction accretive or dilutive, and by how much?","k":["The deal is accretive by approximately $0.59 per share (118%).","Company A pre-deal EPS = $50 / 100 = $0.50","Company B equity value = 50 x $10 = $500","New shares issued by A = $500 / $50 = 10 shares","Combined NI = $50 + $20 + $50 synergies = $120","Pro forma shares = 100 + 10 = 110","Pro forma EPS = $120 / 110 = $1.09","Accretion = $1.09 - $0.50 = $0.59 per share, or +118%","Even without synergies: EPS = $70 / 110 = $0.64, still accretive by $0.14 per share. This is because Company A's P/E (100x) is higher than Company B's implied acquisition P/E ($500 / $20 = 25x)."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Citi Interview","SA 2026, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1337","t":"deal","l":"Advanced","s":90,"q":"Company A is considering acquiring Company B.\n\n\n\n\nCompany A has a P/E of 8x and can issue debt at a 10% interest rate. The tax rate is 40%.\n\n\n\n\nCompany B has a P/E of 10x.\n\n\n\n\nIs the deal accretive or dilutive if it is a 100% stock deal? What about a 100% debt deal?","k":["100% Stock Deal","A's P/E = 8x (lower).","B's P/E = 10x (higher).","Since A's P/E (8x) < B's P/E (10x), dilutive.","100% Debt Deal","After-Tax Cost of Debt = 10% * (1 - 40%) = 6%.","B's Earnings Yield = 1 / 10 = 10%.","Since Cost (6%) < Yield (10%), accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Credit Suisse Interview","SF office","Merger Model (M&A)","Advanced"]},{"id":"q-1338","t":"deal","l":"Advanced","s":90,"q":"You are analyzing an acquisition with the following facts:\n\n\n\nTarget: 100 shares outstanding, trading at $20 per share, 20x PE ratio.\nAcquirer: 100 shares outstanding, trading at $100 per share, 10x PE ratio.\nAcquisition Details: 25% premium paid, 100% stock financing.\n\n\n\nAnswer the following:\n\nWhat is the purchase Price?\nWhat is the Pro-Forma Target Company Ownership?\nWhat is the Pro-Forma EPS (one decimal place)?\nHow accretive or dilutive is this transaction (%)?\nWhat cost synergies make this break-even (assume 40% tax rate)?","k":["Part 1: Purchase Price","Answer: $2,500","Purchase Price/Share = $20 * (1 + 0.25 premium) = $25","Total Purchase Price = $25 * 100 shares = $2,500","Part 2: Pro-Forma Target Ownership","Answer: 20%","Shares Issued = $2,500 purchase price / $100 per share (acquirer share price)= 25 shares","Total PF Shares = 100 + 25 = 125","PF Target Ownership = 25 / 125 = 20%","Part 3: Pro-Forma EPS","Answer: $8.8","Acquirer NI = ($100 per share / 10 PE) = $10 EPS * 100 shares = $1,000","Target NI = ($20 per share / 20 PE) = $1 EPS * 100 shares = $100","PF NI = $1,000 + $100 = $1,100","PF Shares = 125 (from Part 2)","PF EPS = $1,100 / 125 = $8.8","Part 4: Accretion / Dilution","Answer: 12% Dilutive","PF EPS = $8.8 (calculated in Part 3)","Standalone EPS = $10.0 (calculated in Part 3)","% Change = (PF EPS / Standalone EPS) - 1","% Change = ($8.8 / $10.0) = -12%","Part 5: Break-Even Cost Synergies","Answer: $250","Required PF NI for Break-even = $10.0 EPS * 125 shares = $1,250","Required NI Increase (Post-Tax Synergies) = $1,250 - $1,100 = $150","Required Pre-Tax Synergies = $150 / (1 - 40%) = $150 / 0.6 = $250"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Evercore Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1339","t":"deal","l":"Advanced","s":90,"q":"We are advising Company A on an acquisition of Company B.\n\n\n\n\nCompany A: $10/share, 32 shares, $60 EBITDA, 4x leverage @ 10% interest, $16 D&A, 20% tax.\n\n\n\n\nCompany B: $20 EBITDA, acquired at 8x EBITDA, $12 D&A.\n\n\n\n\nFinancing: 50% stock, 50% debt (assume 10% interest).\n\n\n\n\nAnswer the following:\n\nWhat is the Pro Forma EPS of the combined company?\nWhat amount of cost synergies (pre-tax) are needed for this deal to break even?\nIf Company B trades at 2x EV/Revenue, what amount of revenue synergies are needed for break-even?","k":["Part 1: Pro Forma EPS","Answer: $0.40","Assumption: Use the same interest rate on debt as the acquirer’s interest rate. Since financing is raised (or guaranteed) under the acquirer’s credit profile, lenders price the new debt at the acquirer’s cost of capital, so you assume the same interest rate.","Company A Standalone:","Debt = 4 * $60 = $240. Interest = $24.","EBT = EBITDA - D&A - Interest = $60 - $16 - $24 = $20.","NI = EBT * (1 - Tax Rate) = $20 * (1 - 20%) = $16.","EPS = NI / Shares Outstanding = $16 / 32 = $0.50.","Pro Forma Calculation:","Purchase Price = 8 * $20 = $160.","New Debt = $80. New Stock = $80.","New Shares = $80 / $10 = 8. PF Shares = 32 + 8 = 40.","Incremental Interest = $80 * 10% = $8.","B's Pre-Tax Contribution = $20 EBITDA - $12 D&A - $8 Interest = $0.","PF EBT = $20 (A's EBT) + $0 = $20.","PF NI = $20 * (1 - 20%) = $16.","PF EPS = $16 / 40 = $0.40.","Part 2: Break-Even Cost Synergies","Answer: $5","Required PF NI = $0.50 * 40 = $20.","Current PF NI = $16.","Required NI Increase = $20 - $16 = $4.","Required Pre-Tax Cost Synergies = $4 / (1 - 20%) = $4 / 0.8 = $5.","Part 3: Break-Even Revenue Synergies","Answer: $20","Company B Revenue = $160 Purchase Price / 2x EV/Rev = $80.","Company B EBITDA Margin = $20 / $80 = 25%.","Required Pre-Tax Synergies = $5 (from Part 2).","Required Revenue Synergies = $5 / 25% = $20."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Evercore Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1340","t":"deal","l":"Advanced","s":90,"q":"Company A: $10m EBITDA, 10x EV/EBITDA, $10m Cash, $30m Debt, $10m NCI, $7m NI, 5% int rate, 20% tax.\n\n\n\n\nA buys target (8x P/E) using 50% stock / 50% debt.\n\n\n\n\nIs the deal accretive?","k":["The deal is accretive.","Analysis:","A's TEV = $10M EBITDA x 10x EV/EBITDA = $100M.","A's Equity Value = $100M - $30M Debt - $10M NCI + $10M cash = $70m.","A's P/E = $70M / $7M NI = 10x.","A's Cost of Equity = 1/10 = 10%.","A's After-Tax Cost of Debt = 5% * (1-20%) = 4%.","WACC = 50%*10% + 50%*4% = 7%.","Target Yield = 1 / Target P/E = 1 / 8x = 12.5%.","Since Cost (7%) < Yield (12.5%), it's accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Evercore Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1341","t":"deal","l":"Advanced","s":90,"q":"Company A acquires B using 50% debt, 25% cash, 25% stock.\n\n\n\n\nA: $10/share, 100 shares, $300 debt, $100 cash, $200 NI.\n\n\n\n\nB: $10/share, 25 shares, $75 debt, $25 cash, $25 NI.\n\n\n\n\nAssumptions: Tax=25%, Cost of Debt=12%, Cost of Cash=4%.\n\n\n\n\nPart 1: Is it accretive?\n\nPart 2: Why might A still do the deal if dilutive?","k":["Part 1: Accretion / Dilution","The deal is dilutive.","Target B P/E = $10 / ($25 NI / 25 Shares Outstanding) = 10x. Yield = 1/10 = 10%.","A's Cost of Debt (After-Tax) = 12% * (1-25%) = 9%.","A's Cost of Cash (After-Tax) = 4% * (1-25%) = 3%.","A's P/E = $10 / ($200 NI / 100 Shares Outstanding) = 5x. Cost of Equity = 1/5 = 20%.","WACC of Financing = (50% * 9%) + (25% * 3%) + (25% * 20%) = 4.5% + 0.75% + 5.0% = 10.25%.","Since Cost (10.25%) > Yield (10.0%), it's dilutive.","Part 2: Rationale for Dilutive Deal","Companies might pursue dilutive deals for strategic reasons:","Significant long-term synergies (revenue/cost).","Acquisition of critical technology or IP.","Achieving scale or market leadership.","Entering new, high-growth markets.","Defensive necessity (preventing competitor acquisition).","Talent acquisition."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Evercore Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1342","t":"deal","l":"Advanced","s":90,"q":"Company A is acquiring Company B. Assume all figures are inclusive of any premium and synergies.\n\n\n\n\nPart 1: Basic Accretion / Dilution\n\nCompany A has a P/E of 10× and Company B has a P/E of 8×. If this is an all-stock deal, is the transaction accretive or dilutive for Company A?\n\n\n\n\nPart 2: Earnings Yield\n\nNow assume Company A uses 100% debt with an after-tax cost of 5% to acquire Company B, which still has a P/E of 8×.\n\nA. Is the deal accretive or dilutive? Is it more or less accretive than the all-stock deal?\nB. What after-tax cost of debt would make this deal breakeven from an accretion/dilution perspective?\n\n\n\nPart 3: Merger of Equals\n\nReverting to the all-stock deal from Part 1, assume the companies are the same size (i.e., same market cap).\n\nA. Without performing calculations, what are the reasonable boundaries for the pro-forma P/E ratio of the combined entity?\nB. As a percentage, how accretive is the deal? Does the resulting pro-forma P/E ratio fall within the bounds you expected?\n\n\n\nPart 4: Full Merger Math\n\nUse the all-stock scenario, but now assume Company A is twice the size of Company B by market cap.\n\nA. Without performing calculations, do you expect this deal to be more or less accretive than the merger of equals? What are the new boundaries for the pro-forma P/E?\nB. Calculate the exact accretion percentage. Does your answer make sense?","k":["Part 1: All-Stock","Accretive.","Target yield = 1 ⁄ 8 = 12.5%.","Acquirer cost of equity = 1 ⁄ 10 = 10%.","12.5% > 10% → accretive.","Part 2: 100% Debt","A. Accretive and more accretive than Part 1.","After-tax debt cost = 5% < 12.5% yield.","Spread (7.5 pp) > stock spread (2.5 pp) → greater accretion.","B. Breakeven after-tax debt cost = 12.5%.","Part 3: Merger of Equals (MOE)","A. PF P/E must lie between 8× and 10×.","B. Accretion ≈ 12.5%; PF P/E ≈ 8.9× — inside the expected range.","Part 4: A Twice Size of B","A. Less accretive than the MOE; PF P/E skews toward 10× (bounds ≈ 9×–10×).","B. Exact accretion ≈ 8.3%; PF P/E ≈ 9.2× — result fits intuition."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Evercore Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1343","t":"deal","l":"Advanced","s":90,"q":"You are analyzing an acquisition of Company B by Company A with the following facts:\n\n\n\n\nCompany A: Stock price of $20/share, Net Income of $20m, EPS of $2.50.\n\nCompany B: Stock price of $10/share, Net Income of $15m, EPS of $1.50.\n\n\n\n\nTransaction Details:\n\nAcquisition premium of 10%.\nFinancing: 50% cash, 50% stock.\nSynergies: None.\nAssumptions: Foregone interest on cash is 0%, interest on new debt is 10%, tax rate is 25%.\n\n\n\nAnswer the following:\n\nIs the initial deal accretive or dilutive, and by what new EPS amount?\nIf $50m of the $55m cash portion is instead financed with new debt, what is the new pro-forma EPS?","k":["Part 1: Initial Accretion/Dilution","Answer: Accretive. Pro-forma EPS = $3.26.","Calculation:","A Shares Outstanding = $20m NI / $2.50 EPS = 8m shares.","B Shares Outstanding = $15m NI / $1.50 EPS = 10m shares.","B Equity Value = 10m shares * $10 = $100m.","Purchase Price = $100m * (1 + 10%) = $110m.","Stock Consideration = $110m * 50% = $55m.","New Shares Issued = $55m / $20 = 2.75m shares.","PF Shares = 8m + 2.75m = 10.75m shares.","PF NI = $20m + $15m = $35m (no synergies, foregone interest on cash is 0%).","PF EPS = $35m / 10.75m = $3.26.","Since $3.26 > $2.50 standalone EPS, the deal is accretive.","Part 2: New PF EPS with Debt Financing","Answer: $2.91.","Calculation:","Additional Debt = $50m at 10% interest = $5m interest expense.","After-Tax Interest = $5m * (1 - 25%) = $3.75m.","New PF NI = $35m - $3.75m = $31.25m.","New PF EPS = $31.25m / 10.75m = $2.91."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Evercore Interview","New York Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1344","t":"deal","l":"Advanced","s":90,"q":"How does a merger differ from an acquisition, specifically regarding the treatment of control premiums in the offer price?","k":["In a true merger, two companies combine as relative equals, often creating a new entity. Control premiums are typically lower or shared more equally between parties.","In an acquisition, one company purchases another, with a clear acquirer and target. The acquirer pays a control premium above the target's trading price to gain ownership and control rights.","Key differences in control premium treatment:","Merger: Premium split or smaller, as both parties have negotiating power.","Acquisition: Full premium paid by acquirer for control (typically 20-40% above trading price).","Merger: Often structured as stock-for-stock at negotiated exchange ratio.","Acquisition: Can be cash, stock, or mixed consideration with premium explicitly priced."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Evercore Interview","Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1345","t":"deal","l":"Advanced","s":90,"q":"Part 1: What are the primary ways a company can finance an acquisition?\n\n\n\n\nPart 2: How might a company with no EBITDA (or negative EBITDA) finance an acquisition?","k":["Part 1: Primary Financing Methods","Cash: Use existing cash on balance sheet.","Debt: Raise new debt (term loans, bonds).","Stock: Issue new shares to target shareholders (stock-for-stock).","Combination: Mix of cash, debt, and stock.","Part 2: No EBITDA Company Options","Companies with no or negative EBITDA have limited financing options:","Equity Financing: Issue new stock (dilutive but no debt service burden).","Existing Cash: If sufficient cash reserves available.","Asset-Based Lending: Secured against specific assets or target's cash flows.","Convertible Debt: Hybrid security with lower interest burden.","Strategic Investors: Raise capital from PE or strategic partners.","Traditional debt markets are largely unavailable without positive EBITDA and cash flow coverage."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Evercore Interview","Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1346","t":"deal","l":"Advanced","s":90,"q":"Company A acquired 60% of Company B for $600 million. Company B has $100 million in debt and $50 million in EBITDA. What is the implied EV/EBITDA multiple for this deal?","k":["Answer: 22.0x","Calculation:","$600M buys 60% of Company B's equity, so implied total Equity Value = $600M / 0.60 = $1,000M","Enterprise Value = Equity Value + Debt = $1,000M + $100M = $1,100M","EV/EBITDA = $1,100M / $50M = 22.0x"],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","SA 2025","Merger Model (M&A)","Advanced"]},{"id":"q-1347","t":"deal","l":"Advanced","s":90,"q":"A company has a P/E of 20x and a cost of debt of 5%. Assuming a 0% tax rate, which form of financing is cheaper: equity or debt?","k":["Debt is cheaper, even though both appear to be 5% at first glance.","Cost of equity implied by P/E = Earnings Yield = 1/20 = 5.0%","Cost of debt = 5.0%","At a 0% tax rate, the after-tax cost of debt = 5.0% x (1 - 0%) = 5.0%","The earnings yield of 5% understates the true cost of equity. Here is why: a P/E of 20x reflects the market pricing in future earnings growth. If the market expects, say, 5% annual earnings growth, the true required return on equity is approximately the earnings yield plus the expected growth rate: 5% + 5% = ~10%. This is consistent with a dividend discount / Gordon Growth framework where Cost of Equity = (E/P) + g.","In contrast, the 5% cost of debt is the actual contractual interest rate — it does not embed growth expectations. Additionally, debt holders have a senior claim on assets, meaning they bear less risk and require a lower return. For any company, the cost of equity should always exceed the cost of debt, since equity is structurally riskier (residual claim, no guaranteed payments)."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","M&A group, New York Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1348","t":"deal","l":"Advanced","s":90,"q":"Company A has Net Income of $100, 50 shares outstanding at $100 per share. Company B has a market cap of $1,000, a share price of $50, pre-tax earnings of $50, and a tax rate of 30%. There are $15 in post-tax synergies. If Company A acquires Company B in an all-stock deal, is this transaction dilutive or accretive, and by what percentage?","k":["Answer: 25% accretive","Calculation:","Company A EPS = $100 / 50 = $2.00","Company B Net Income = $50 x (1 - 0.30) = $35","New shares issued = $1,000 market cap / $100 per share = 10 new shares","Combined NI = $100 + $35 + $15 synergies = $150","New share count = 50 + 10 = 60","Pro forma EPS = $150 / 60 = $2.50","Accretion = ($2.50 - $2.00) / $2.00 = 25%","Company A's P/E is 50x ($5,000 / $100) vs. Company B's effective P/E of ~28.6x ($1,000 / $35). Since Company A's P/E exceeds Company B's, the all-stock deal is accretive even before synergies."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","M&A group, New York Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1349","t":"deal","l":"Advanced","s":90,"q":"Company A has an equity value of $800 and Net Income of $80. Company B is purchased for $200 and has Net Income of $10. This is a 100% stock deal with a 20% tax rate. What are the break-even pre-tax synergies?","k":["Answer: $12.50 in pre-tax synergies.","Company A: EPS = $80 / (assume shares = S). P/E = $800 / $80 = 10x. Share price = $800/S.","New shares issued = $200 / ($800/S) = 0.25S.","Pro Forma Shares = S + 0.25S = 1.25S.","Standalone EPS = $80 / S.","Pro Forma NI (without synergies) = $80 + $10 = $90.","Pro Forma EPS (without synergies) = $90 / 1.25S = $72/S.","This is dilutive since $72/S < $80/S.","EPS shortfall = $80/S - $72/S = $8/S. Total NI needed = $8/S x 1.25S = $10.","After-tax synergies needed = $10. Pre-tax synergies = $10 / (1 - 20%) = $12.50."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","M&A group, New York Office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1350","t":"deal","l":"Advanced","s":90,"q":"Company A has 25 shares outstanding at $40 per share with a P/E of 20x. Company B has 40 shares outstanding at $10 per share with a P/E of 10x. Company A acquires Company B at a 50% premium, financed 50% with stock, 30% with debt, and 20% with cash. Assume a 5% pre-tax cost of debt, a 2% pre-tax return on cash, and a 25% tax rate. Is this transaction accretive or dilutive?","k":["The deal is accretive.","Company A: Equity Value = 25 x $40 = $1,000. NI = $1,000 / 20 = $50. EPS = $50/25 = $2.00.","Company B: Equity Value = 40 x $10 = $400. NI = $400 / 10 = $40.","Purchase Price = $400 x 1.50 = $600.","Stock: 50% x $600 = $300. New shares = $300 / $40 = 7.5 shares.","Debt: 30% x $600 = $180. After-tax interest = $180 x 5% x (1 - 25%) = $6.75.","Cash: 20% x $600 = $120. Foregone after-tax interest = $120 x 2% x (1 - 25%) = $1.80.","Pro Forma NI = $50 + $40 - $6.75 - $1.80 = $81.45.","Pro Forma Shares = 25 + 7.5 = 32.5.","Pro Forma EPS = $81.45 / 32.5 = $2.51.","$2.51 > $2.00, so the deal is accretive.","The deal is accretive primarily because Company A's P/E (20x) is higher than Company B's acquisition P/E (effectively 15x = $600/$40)."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","M&A group, New York Office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1351","t":"deal","l":"Advanced","s":90,"q":"Part 1: Which tax rate do you use in a merger model?\n\n\n\n\nPart 2: How do you apply the buyer's tax rate to the seller in the merger model?","k":["Part 1","You typically use the acquirer's marginal tax rate for the combined entity. This is because the acquirer will consolidate the target's financials and apply its own tax structure. However, in practice, you may use a blended rate or the target's standalone rate for specific adjustments (like synergies).","Part 2","Tax-affect the target's pre-tax income at the buyer's tax rate to get the target's pro forma net income contribution.","Apply the buyer's tax rate to synergies (both cost and revenue) to determine after-tax synergy contribution.","Apply the buyer's tax rate to the interest expense on acquisition-related debt to calculate the tax shield.","If the target had a different tax rate pre-acquisition, the change in tax rate creates an adjustment in the pro forma combined income statement."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","SA 2025, Second round","Merger Model (M&A)","Advanced"]},{"id":"q-1352","t":"deal","l":"Advanced","s":90,"q":"If you were on the sell side and your company was trading at a 20x P/E multiple, and a buyer offered a 25x P/E multiple with a 30% premium, would this deal be accretive or dilutive for the buyer?","k":["The deal is dilutive for the buyer (in an all-stock deal).","The buyer's P/E is 25x (earnings yield = 1/25 = 4.0%).","The target is being acquired at a 30% premium to its 20x P/E, meaning the effective acquisition P/E = 20x x 1.30 = 26x (earnings yield = 1/26 = 3.85%).","Since the buyer is paying a higher P/E (26x) than its own (25x), it is buying more expensive earnings than its stock is valued at.","In an all-stock deal, this results in EPS dilution for the buyer's shareholders.","If the deal were financed with cash or debt, accretion/dilution would depend on the after-tax cost of financing vs. the target's earnings yield."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","SA 2025, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1353","t":"deal","l":"Advanced","s":90,"q":"Why might a financial buyer pay more for a company than a strategic buyer?","k":["Conventionally, strategic buyers are expected to pay more because they can realize synergies that a financial buyer cannot. However, there are several scenarios where a financial buyer may outbid a strategic:","Leverage: Financial buyers (PE sponsors) typically use significantly more debt to finance acquisitions. Higher leverage amplifies equity returns, allowing the sponsor to pay a higher total price while still meeting its return hurdle (e.g., 20%+ IRR).","Portfolio synergies: The sponsor may own a portfolio company in the same or adjacent sector, enabling it to realize synergies similar to a strategic buyer (a \"buy-and-build\" strategy).","Competitive auction dynamics: Multiple financial buyers bidding against each other in a competitive process can drive the price above what a single strategic buyer is willing to pay.","Deployment pressure: Sponsors with significant uninvested capital (\"dry powder\") approaching the end of their investment period may be willing to pay a higher price to deploy capital.","Strategic buyer discipline: Public strategics face shareholder scrutiny and may be more conservative on price to avoid EPS dilution, while a private sponsor faces less public pressure on short-term accretion metrics."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1354","t":"deal","l":"Advanced","s":90,"q":"You are given the following information:\n\n\n\nAcquirer: 100M shares outstanding, $10/share, $100M Net Income (P/E = 10x)\nTarget: $500M purchase price, $40M Net Income\nPre-tax cost of debt: 8%\nTax rate: 25%\n\n\n\nWhat percentage of the deal should be financed with stock versus debt to make this acquisition EPS-neutral (breakeven)?","k":["Answer: 50% stock ($250M) and 50% debt ($250M).","Calculation:","Standalone EPS = $100M / 100M = $1.00","Let S = stock percentage. New shares issued = ($500M x S) / $10 = 50M x S","After-tax interest on debt = $500M x (1 - S) x 8% x (1 - 25%) = $30M x (1 - S)","Pro forma NI = $100M + $40M - $30M x (1 - S) = $110M + $30M x S","Pro forma shares = 100M + 50M x S","Setting pro forma EPS equal to standalone EPS of $1.00:","($110M + $30M x S) / (100M + 50M x S) = $1.00","$110M + $30M x S = $100M + $50M x S","$10M = $20M x S","S = 50%","Verification: New shares = 25M. After-tax interest = $15M. Pro forma NI = $125M. Pro forma shares = 125M. EPS = $1.00 = standalone EPS."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1355","t":"deal","l":"Advanced","s":90,"q":"You are given the following information:\n\n\n\nCompany A (Acquirer): $1B Equity Value, $100M Net Income, 100M shares outstanding, $10/share\nCompany B (Target): $600M Equity Value, $30M Net Income\nAll-stock deal with no premium\nTax rate: 25%\n\n\n\nWhat are the breakeven synergies required to make this deal EPS-neutral?","k":["Answer: $30M in post-tax synergies ($40M pre-tax).","Calculation:","Acquirer P/E = $1B / $100M = 10x. Target P/E = $600M / $30M = 20x.","Acquirer P/E (10x) < Target P/E (20x), so this all-stock deal is dilutive.","New shares issued = $600M / $10 = 60M","Pro forma NI = $100M + $30M = $130M","Pro forma shares = 100M + 60M = 160M","Pro forma EPS = $130M / 160M = $0.8125","Standalone EPS = $100M / 100M = $1.00","Breakeven requires pro forma EPS = $1.00:","Required NI = $1.00 x 160M = $160M","Post-tax synergies needed = $160M - $130M = $30M","Pre-tax synergies = $30M / (1 - 25%) = $40M"],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1356","t":"deal","l":"Advanced","s":90,"q":"You are given the following information:\n\n\n\nCompany A (Acquirer): 100M shares outstanding, $20/share, $200M Net Income (P/E = 10x)\nCompany B (Target): 50M shares outstanding, $8/share, $20M Net Income (P/E = 20x)\nAll-stock deal with a 25% purchase premium\nTax rate: 25%\n\n\n\nPart 1: What is the purchase equity value (with premium)?\n\n\n\n\nPart 2: What is the target's pro-forma ownership of the combined company?\n\n\n\n\nPart 3: How accretive or dilutive is this deal (in dollars per share)?\n\n\n\n\nPart 4: What are the breakeven post-tax synergies?\n\n\n\n\nPart 5: How would the answers to all of these questions change if it were an all-cash deal?","k":["Part 1: Purchase Equity Value","Target Equity Value = 50M shares x $8 = $400M","Purchase Equity Value = $400M x 1.25 = $500M","Part 2: Pro-Forma Ownership","New shares issued = $500M / $20 = 25M","Pro forma shares = 100M + 25M = 125M","Target's pro-forma ownership = 25M / 125M = 20%","Part 3: Accretion / Dilution","Pro forma NI = $200M + $20M = $220M","Pro forma EPS = $220M / 125M = $1.76","Standalone EPS = $200M / 100M = $2.00","Dilutive by $0.24 per share. The deal is dilutive because the acquirer's P/E (10x) is lower than the target's purchase P/E ($500M / $20M = 25x).","Part 4: Breakeven Post-Tax Synergies","Required NI for breakeven = $2.00 x 125M = $250M","Post-tax synergies needed = $250M - $220M = $30M","Pre-tax synergies = $30M / (1 - 25%) = $40M","Part 5: All-Cash Deal","Purchase Equity Value: unchanged at $500M.","Target pro-forma ownership: 0% (no equity issued in a cash deal).","No new shares issued, so pro forma shares = 100M. Pro forma NI = $200M + $20M = $220M. Pro forma EPS = $220M / 100M = $2.20. Accretive by $0.20 per share.","Breakeven synergies: the deal is already accretive without synergies. The deal can absorb up to $20M in dis-synergies before becoming dilutive ($2.20 - $2.00 = $0.20 x 100M = $20M)."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1357","t":"deal","l":"Advanced","s":90,"q":"Company A acquires Company B in an all-stock deal. Company A has a P/E of 20x, 100 million shares outstanding, and $100 million in Net Income. Company B has a share price of $10/share, 50 million shares outstanding, and $100 million in Net Income. Assume $175 million in post-tax synergies and a tax rate of 35%. How accretive is this deal?","k":["Answer: The deal is accretive by $2.00 per share.","Calculation:","Company A: EPS = $100M / 100M = $1.00. Share price = EPS x P/E = $1.00 x 20 = $20. Equity Value = $2B.","Company B: Equity Value = $10 x 50M = $500M. P/E = $500M / $100M = 5x.","Exchange ratio = B share price / A share price = $10 / $20 = 0.50","New shares issued = 50M x 0.50 = 25M","Pro forma shares = 100M + 25M = 125M","Combined NI = $100M + $100M + $175M post-tax synergies = $375M","Pro forma EPS = $375M / 125M = $3.00","Standalone A EPS = $1.00","Accretion = $3.00 - $1.00 = $2.00 per share","The deal is highly accretive for two reasons: (1) the acquirer's P/E (20x) is significantly higher than the target's P/E (5x), meaning A is using expensive stock to buy cheap earnings, and (2) the $175M in post-tax synergies further increase combined earnings."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1358","t":"deal","l":"Advanced","s":90,"q":"Company A is acquiring Company B. Company B has a higher P/E ratio than Company A.\n\n\n\n\nPart 1: If the transaction is 100% stock-financed, is it accretive or dilutive?\n\n\n\n\nPart 2: Now, assume a 50% stock and 50% debt financing structure. Given a specific cost of debt, how would you determine if the transaction is accretive or dilutive?","k":["Part 1: 100% Stock","The deal is dilutive.","When the target has a higher P/E than the acquirer, paying with stock is dilutive because you're exchanging lower-valued shares for higher-valued earnings.","Part 2: 50% Stock / 50% Debt","Compare the blended cost of financing to target's earnings yield:","Target Yield = 1 / Target P/E.","Acquirer Cost of Equity = 1 / Acquirer P/E.","After-Tax Cost of Debt = Interest Rate × (1 - Tax Rate).","Blended Cost = (50% × Cost of Equity) + (50% × After-Tax Cost of Debt).","If Blended Cost < Target Yield, accretive. If >, dilutive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Goldman Sachs Interview","New York Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1359","t":"deal","l":"Advanced","s":90,"q":"What are the alternatives to a fixed exchange ratio in a stock-for-stock M&A transaction?","k":["Floating exchange ratio (fixed value): The exchange ratio adjusts based on the acquirer's share price so the target receives a fixed dollar value per share. Protects the target from declines in the acquirer's stock.","Collar mechanism: Sets a range (collar) around the exchange ratio. If the acquirer's stock moves within the range, the ratio is fixed; if it moves outside, the ratio adjusts. Provides partial protection to both parties.","Walk-away rights: Either party can terminate the deal if the acquirer's stock price falls below a threshold.","Cash election / mix-and-match: Allows target shareholders to choose between cash and stock consideration, subject to proration.","Contingent Value Rights (CVRs): Provide additional consideration to target shareholders if certain milestones are met post-closing."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1360","t":"deal","l":"Advanced","s":90,"q":"How would a floating exchange ratio change your analysis of an M&A transaction compared to a fixed exchange ratio? Is it better or worse for the buyer?","k":["A floating exchange ratio (fixed value) means the buyer issues however many shares are needed to deliver a fixed dollar value to the target.","If the buyer's stock rises: Fewer shares are issued, meaning less dilution for existing shareholders. Better for the buyer.","If the buyer's stock falls: More shares must be issued, increasing dilution. Worse for the buyer.","A floating ratio shifts stock price risk to the buyer. The deal value to the target is certain, but the dilution to the buyer is uncertain. This is generally worse for the buyer because it removes their upside from stock appreciation between signing and closing, while exposing them to additional dilution if their stock declines.","In the accretion/dilution analysis, a floating ratio means the number of new shares changes with the buyer's stock price, so you must sensitize the analysis across different stock prices."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1361","t":"deal","l":"Advanced","s":90,"q":"Why would a merger that initially looks accretive ultimately fail or destroy value?","k":["Synergies fail to materialize: The projected cost savings or revenue synergies were overly optimistic. Integration costs exceed expectations, or customer attrition offsets revenue gains.","Integration challenges: Cultural clashes, incompatible IT systems, loss of key employees, or management distraction from core operations.","Overpayment: The acquirer paid a premium exceeding the actual value of synergies, destroying value on a net basis even though EPS was accretive.","EPS accretion is not the same as value creation: A deal can be EPS-accretive simply because the target's P/E is lower than the acquirer's, but this does not mean the underlying business is worth more combined. Accretion from financial engineering (low P/E target) without real operational improvement destroys value.","Revenue decline: The target's business deteriorates post-acquisition due to customer defections, competitive response, or loss of entrepreneurial culture.","Hidden liabilities: Undisclosed legal, regulatory, or environmental liabilities surface after closing."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","Merger Model (M&A)","Advanced"]},{"id":"q-1362","t":"deal","l":"Advanced","s":90,"q":"Company A acquires Company B, which has a market cap of $200, for a 30% premium. They generate $15 in cost synergies and Company A trades at 10x EV/EBITDA. Does this acquisition create or destroy value?","k":["The acquisition creates value.","Calculation:","Premium paid = $200 x 30% = $60. Total purchase price = $260.","The premium is the \"cost\" of the acquisition above standalone value.","Value of synergies: $15 in annual cost synergies valued at Company A's 10x EV/EBITDA multiple = $15 x 10 = $150.","Net value creation = Synergy value - Premium = $150 - $60 = $90.","Since the present value of synergies ($150) exceeds the premium paid ($60), the deal creates $90 of value for Company A's shareholders. The deal would only destroy value if the premium exceeded the capitalized value of synergies.","Important caveat: Applying an EV/EBITDA multiple to value synergies assumes the $15M in cost synergies are permanent and recurring every year in perpetuity. If the synergies are one-time in nature (e.g., a one-time inventory liquidation gain) or take several years to fully realize, the capitalized value would be significantly lower and the value-creation conclusion could change. In practice, analysts should distinguish between run-rate synergies (which can be capitalized) and one-time savings, and should also consider the time and cost required to achieve the synergies."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027","Merger Model (M&A)","Advanced"]},{"id":"q-1363","t":"deal","l":"Advanced","s":90,"q":"Company A has a WACC of 10% and acquires Company B, which has a WACC of 6%. The acquisition generates an IRR of 8%. Does this create or destroy value?","k":["The acquisition creates value.","The relevant hurdle rate for the acquisition is Company B's WACC (6%), not Company A's WACC (10%). The acquisition should be evaluated based on the risk profile of the target's cash flows, not the acquirer's overall cost of capital.","The acquisition IRR of 8% exceeds Company B's WACC of 6%, meaning the acquisition generates positive NPV when discounted at the appropriate risk-adjusted rate.","If you incorrectly used Company A's WACC of 10% as the hurdle, you would conclude the deal destroys value (8% < 10%). But this would be wrong because Company B's cash flows may be lower-risk than Company A's overall business.","The key principle: evaluate each investment at a discount rate reflecting its own risk, not the acquirer's blended cost of capital."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027","Merger Model (M&A)","Advanced"]},{"id":"q-1364","t":"deal","l":"Advanced","s":90,"q":"Company B has a P/E of 25x and a stock price of $50. Company B was acquired for a purchase equity value of $500. What additional net income would need to be recognized to break even?","k":["Answer: $0 of additional net income.","\"Break even\" here means: how much additional NI would the acquirer need to generate so that the purchase price is justified at the target's current P/E multiple (i.e., the acquirer earns back its investment on a net-income basis, excluding financing costs).","EPS = Stock Price / P/E = $50 / 25 = $2","Shares Outstanding = Purchase Equity Value / Stock Price = $500 / $50 = 10 shares","Current NI = EPS x Shares = $2 x 10 = $20","Required NI to justify purchase price at 25x P/E = $500 / 25 = $20","Additional NI needed = $20 - $20 = $0","The purchase equity value of $500 exactly equals the current market cap ($50 x 10 shares), meaning no premium was paid. At the same 25x P/E, no additional net income is required to break even. Note: this analysis is purely on an earnings-multiple basis and does not account for acquisition financing costs (e.g., debt interest or dilution from stock issuance), which would increase the actual break-even threshold."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1365","t":"deal","l":"Advanced","s":90,"q":"You finance a $100m equity repurchase with debt.\n\n\n\nCoupon = 5%\nTax rate = 40%\nShare price = $20/share\nEPS = $2 per share\nShares outstanding before repurchase = 50 million\n\n\n\nDetermine if the repurchase is accretive or dilutive to EPS.","k":["Answer: Accretive","P / E = Stock Price / EPS = $20 / $2 = 10x","Cost of equity = 1 / (P/E) = 1 / 10 = 10%","Cost of debt = 5% x (1 - 40%) = 3%","Since the cost of debt (3%) is less than the cost of equity (10%), EPS post-buyback increases, making this transaction accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Greenhill & Co. Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1366","t":"deal","l":"Advanced","s":90,"q":"Company A has 1 million shares and an EPS of $1. What is net income?\n\n\n\n\nCompany B has 800,000 shares and an EPS of $0.50. What is net income?\n\n\n\n\nCompany A issues 500,000 shares in an all-stock deal to acquire Company B.\n\n\n\n\nIs the deal accretive or dilutive?","k":["Company A NI $1.0 mm; Company B NI $0.4 mm.","Pro‑forma EPS = $1.4 mm ÷ 1.5 mm shares ≈ $0.93.","Since $0.93<$1.00, the transaction is ≈7% dilutive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Greenhill & Co. Interview","SA 2024, Industrials M&A, Chicago office","Merger Model (M&A)","Advanced"]},{"id":"q-1367","t":"deal","l":"Advanced","s":90,"q":"Company A buys Company B, which has a 10x P/E, using 50% cash and 50% debt.\n\n\n\n\nInterest on cash is 10%, interest on debt is 20%, tax rate is 20%.\n\n\n\n\nIs this accretive or dilutive?","k":["Dilutive.","Target earnings yield = 1/10 = 10%","Cost of Cash (after‑tax) = 10% × (1–20%) = 8%","Cost of Debt (after‑tax) = 20% × (1–20%) = 16%","Weighted Cost = 0.5 × 8% + 0.5 × 16% = 12%","Because 12% > 10%, EPS falls post‑deal."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Greenhill & Co. Interview","First round","Merger Model (M&A)","Advanced"]},{"id":"q-1368","t":"deal","l":"Advanced","s":90,"q":"Company A has an EPS of 3, a P/E of 10x, and 1000 shares.\n\n\n\n\nCompany B has an EPS of 5, a P/E of 15x, and 100 shares.\n\n\n\n\nA acquires B at no premium, no synergies, zero taxes, in an all-stock transaction.\n\n\n\n\nCalculate the accretion or dilution. How much post-tax synergy is needed for break-even?","k":["Dilution of ≈ 6.7% ― EPS falls from 3.0 to 2.8.","Post‑tax synergy of 250 is required for break‑even.","Explanation:","A share price = EPS × P/E ⇒ 30; B share price = 75.","Purchase price = 75 × 100 = 7,500, paid with 7,500/30 = 250 new A shares.","Pro‑forma shares = 1,000 + 250 = 1,250.","Combined NI = 3 × 1,000 + 5 × 100 = 3,500 ⇒ PF EPS ≈ 2.8.","Accretion ⁄ dilution = (2.8/3.0) − 1 ≈ −6.7%.","Break‑even NI = 3.0 × 1,250 = 3,750 ⇒ shortfall = 250; zero tax → 250 post‑tax synergy."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Greenhill & Co. Interview","Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1369","t":"deal","l":"Advanced","s":90,"q":"Merger Model: Company A acquires Company B, 100% debt deal. A's PE = 10x, B's PE = 20x, 0% interest rate. Is it accretive or dilutive, and why?","k":["Accretive.","Cost of financing = 0%; Target earnings yield = 1/20 = 5%.","Adding earnings at zero financing cost boosts A’s EPS with no share issuance → accretion."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Guggenheim Partners Interview","SA 2026, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1370","t":"deal","l":"Advanced","s":90,"q":"Company A and Company B both have Net Income of $10 million. Their combined Net Income is not $20 million. Why? List all possible reasons.","k":["The combined Net Income could be higher or lower than $20M for several reasons:","Transaction costs: M&A advisory fees, legal fees, integration costs, and financing costs reduce combined NI.","Foregone interest income on cash used for the acquisition.","New interest expense if debt is raised to fund the deal.","Amortization of intangible assets created in purchase accounting (customer relationships, technology, etc.).","Cost synergies (headcount reduction, facility consolidation) could increase combined NI above $20M.","Revenue synergies (cross-selling, pricing power) could also increase NI.","Intercompany transactions that previously generated revenue for one and expense for the other are eliminated in consolidation.","New shares issued in a stock deal dilute EPS but do not reduce NI; however, the question asks about NI, not EPS.","Tax implications - a change in the tax structure of the combined entity."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Guggenheim Partners Interview","SA 2025","Merger Model (M&A)","Advanced"]},{"id":"q-1371","t":"deal","l":"Advanced","s":90,"q":"Company A has a P/E of 15x and Company B has a P/E of 10x. If both are looking to acquire the same target in an all-stock deal, which acquirer will experience less EPS dilution (or more accretion)?","k":["Company A (15x P/E) will experience less EPS dilution (or more accretion).","In an all-stock deal, the acquirer with the higher P/E multiple issues fewer shares to buy the same amount of target earnings because its stock is valued more richly. Since Company A uses a more valuable currency, it gives up less equity to fund the purchase, resulting in a more favorable accretion/dilution profile for its existing shareholders compared to Company B.","The key rule: an all-stock deal is accretive to the acquirer when the acquirer's P/E exceeds the target's P/E, because the acquirer is buying earnings at a cheaper multiple than the market assigns to its own earnings."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Guggenheim Partners Interview","SA 2025","Merger Model (M&A)","Advanced"]},{"id":"q-1372","t":"deal","l":"Advanced","s":90,"q":"Company A and Company B both have the same equity value. Company A has $200 million in cash and no debt. Company B has no cash and $1 billion in debt. Which acquisition is more accretive?","k":["Acquiring Company A is more likely to be accretive.","Same equity value means the same purchase price in an all-stock or all-cash deal.","Company A: You acquire its earnings plus $200M in cash (which can be used to pay down acquisition debt or fund operations). There is no debt to service.","Company B: You acquire its earnings but also assume $1B in debt, which carries significant interest expense that directly reduces combined net income.","Even if Company B has higher EBITDA (needed to support the debt), the after-interest earnings contribution is much lower.","Company A provides more accretive earnings to the combined entity because it brings cash rather than debt obligations."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Guggenheim Partners Interview","SA 2025","Merger Model (M&A)","Advanced"]},{"id":"q-1373","t":"deal","l":"Advanced","s":90,"q":"What is the after-tax cost of debt required to make an all-debt acquisition neither accretive nor dilutive?","k":["You look at the target’s earnings yield (1 / P/E). If after-tax cost of debt equals the target’s earnings yield, it’s breakeven.","For example, if the target trades at 10x earnings (10% yield), and the tax rate is 25%, you need the pre-tax cost of debt to be 13.3% so that after-tax cost of 10% matches the 10% earnings yield."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in J.P. Morgan Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1374","t":"deal","l":"Advanced","s":90,"q":"A company with a P/E ratio of 10x is considering a debt-funded share repurchase. Assume a 25% tax rate.\n\n\n\n\nAnswer the following:\n\nWhat is the maximum after-tax cost of debt for the repurchase to be accretive?\nWhat is the maximum pre-tax cost of debt for the repurchase to be accretive?","k":["Part 1: Maximum After-Tax Cost of Debt","Answer: 10%","Earnings Yield = 1 / P/E = 1 / 10x = 10%.","For accretion, after-tax cost of debt must be < earnings yield.","Maximum after-tax cost of debt = 10%.","Part 2: Maximum Pre-Tax Cost of Debt","Answer: 13.33%","After-tax cost of debt = Pre-tax cost * (1 - Tax Rate).","10% = Pre-tax cost * (1 - 25%).","Pre-tax cost = 10% / 0.75 = 13.33%."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in J.P. Morgan Interview","Chicago office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1375","t":"deal","l":"Advanced","s":90,"q":"You are given the following information:\n\n\n\nCompany A: $100M Net Income, 20x P/E, 100 shares outstanding\nCompany B: $1.4B in assets, $700M in liabilities, $50M Net Income, 16x P/E\n25% tax rate, 25% acquisition premium, all-stock deal\n\n\n\nPart 1: Is this deal accretive or dilutive?\n\n\n\n\nPart 2: How can you make a deal more accretive?\n\n\n\n\nPart 3: Why would a company use debt in a deal? Why cash?","k":["Part 1: Accretive or Dilutive?","The deal is roughly breakeven (neither accretive nor dilutive).","Acquirer (A) P/E = 20x. Target (B) P/E with premium = 16x x 1.25 = 20x.","Quick check: In an all-stock deal, if acquirer P/E > target P/E (including premium), the deal is accretive. Here they are equal, so the deal is roughly breakeven on EPS.","Detailed math: A share price = $100M NI / 100 shares x 20 P/E = $20/share. A equity value = $2,000M. B equity value = $50M x 16 = $800M. Purchase price = $800M x 1.25 = $1,000M. New shares issued = $1,000M / $20 = 50 shares. Pro forma NI = $100M + $50M = $150M. Pro forma shares = 100 + 50 = 150. Pro forma EPS = $1.00. Standalone EPS = $100M / 100 = $1.00. The deal is breakeven (neither accretive nor dilutive).","Part 2: Making a Deal More Accretive","Use debt instead of stock (avoids dilution from issuing shares).","Realize cost synergies that increase combined Net Income.","Negotiate a lower purchase price or premium.","Use cash on hand (no dilution, no interest expense).","Part 3: Why Debt? Why Cash?","Debt: Lower cost of capital due to tax-deductible interest, does not dilute existing shareholders, signals confidence in stable cash flows. Downside: increases leverage and financial risk.","Cash: No dilution and no new interest expense. However, the acquirer loses the return it was earning on that cash (foregone interest income), and large cash balances are often held overseas with tax repatriation implications."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1376","t":"deal","l":"Advanced","s":90,"q":"You are an acquirer with Net Income of $100, EPS of $1, and a P/E of 10x. The Purchase Price for the target is $500. The target has EBIT of $50 and Net Income of $10. The deal is financed 50% with equity, 25% with cash, and 25% with debt. Assume a 10% interest rate on new debt and a 2% foregone interest rate on cash. The tax rate is 20%. Find the pro forma EPS.","k":["Accretion/Dilution Analysis","Acquirer shares = NI / EPS = $100 / $1 = 100 shares. Share Price = EPS x P/E = $1 x 10 = $10.","Financing: 50% equity = $250, 25% cash = $125, 25% debt = $125.","New shares issued = $250 / $10 = 25 shares.","New interest expense on debt: $125 x 10% = $12.50, after-tax (at 20%) = $10.","Foregone interest on cash: $125 x 2% = $2.50, after-tax = $2.","Pro forma NI = $100 + $10 - $10 - $2 = $98.","Pro forma shares = 100 + 25 = 125.","Pro forma EPS = $98 / 125 = $0.78. Deal is dilutive ($0.78 vs. $1.00 standalone)."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in J.P. Morgan Interview","SA 2025, Healthcare group, SF Office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1377","t":"deal","l":"Advanced","s":90,"q":"A utility company with a 13x P/E is acquiring another utility with an 11x P/E at a 20% premium. The deal is all stock. Is this transaction accretive or dilutive?","k":["The deal is slightly dilutive.","In an all-stock deal, you compare the acquirer's P/E to the effective P/E paid for the target.","Target's current P/E = 11x","With a 20% premium, the effective P/E paid = 11x x 1.20 = 13.2x","Acquirer's P/E = 13x","Since the effective acquisition P/E (13.2x) is higher than the acquirer's own P/E (13x), the acquirer is paying more per dollar of earnings than its own stock is valued at. The acquirer's earnings yield is 7.7% (1/13) while it is buying earnings at a 7.6% yield (1/13.2). This results in marginal EPS dilution."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1378","t":"deal","l":"Advanced","s":90,"q":"Company A has a P/E of 10x and Company B has a P/E of 20x. Assume a 25% tax rate. In an all-debt transaction where A acquires B, what is the breakeven accretion/dilution analysis?","k":["In an all-debt deal, the deal is accretive if the target's earnings yield (inverse P/E) exceeds the after-tax cost of debt.","Target P/E = 20x, so earnings yield = 1/20 = 5.0%.","The deal breaks even when the after-tax cost of debt equals 5.0%.","If the tax rate is 25%, the breakeven pre-tax cost of debt = 5.0% / (1 - 0.25) = 6.67%.","If the after-tax cost of debt is below 5.0%, the deal is accretive (the acquired earnings exceed the after-tax interest cost).","If the after-tax cost of debt is above 5.0%, the deal is dilutive.","Note: The acquirer's P/E of 10x is not directly relevant in an all-debt deal since no shares are issued. It only matters for determining the impact on the acquirer's per-share metrics."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1379","t":"deal","l":"Advanced","s":90,"q":"Part 1: Company A has $100 in Net Income, a $10 share price, $50 in debt, $10 in cash, a 5x P/E ratio, a 10% interest rate, and a 25% tax rate. What is the EPS? What is the enterprise value?\n\n\n\n\nPart 2: Company A acquires Company B for a $400 purchase price. Company B has $50 in Net Income. The acquisition is financed 50% with stock and 50% with debt. Is the deal accretive or dilutive?","k":["Part 1: EPS and Enterprise Value","Share Price = $10, P/E = 5x, so EPS = $10 / 5 = $2.00.","Shares Outstanding = NI / EPS = $100 / $2 = 50 shares.","Equity Value = $10 x 50 = $500.","EV = $500 + $50 - $10 = $540.","Part 2: Accretion/Dilution","Purchase Price = $400. 50% stock ($200), 50% debt ($200).","New shares issued = $200 / $10 = 20 shares.","After-tax interest cost = $200 x 10% x (1 - 25%) = $15.","Pro Forma NI = $100 + $50 - $15 = $135.","Pro Forma Shares = 50 + 20 = 70.","Pro Forma EPS = $135 / 70 = $1.93.","Standalone EPS = $2.00.","$1.93 < $2.00, so the deal is dilutive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in J.P. Morgan Interview","SA 2026, New York Office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1380","t":"deal","l":"Advanced","s":90,"q":"When financing an acquisition, under what circumstances would an acquirer prefer to use cash, debt, or stock?","k":["Cash - when the acquirer has excess cash, limited alternative uses, and believes its own shares are undervalued.","Debt - when interest rates are attractive, the target’s cash flows are stable, and the acquirer’s leverage headroom is ample.","Stock - when the acquirer’s equity is richly valued, cash is scarce, or leverage is already high."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Lazard Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1381","t":"deal","l":"Advanced","s":90,"q":"Company A has a P/E of 20x and Company B has a P/E of 10x. Company A acquires Company B at no premium, financed 50% with stock and 50% with debt. Assuming a 50% tax rate, is the deal accretive or dilutive?","k":["The deal is accretive.","Analysis by financing component:","Stock portion (50%): Company A P/E (20x) > Company B P/E (10x). The stock portion alone is accretive because Company A's earnings yield (5%) is lower than Company B's (10%), so each share of stock issued buys proportionally more earnings.","Debt portion (50%): Company B's earnings yield = 1/10 = 10%. We need the after-tax cost of debt to compare. As long as the after-tax interest rate on the debt is less than 10%, the debt portion is also accretive. At a 50% tax rate, the pre-tax cost of debt would need to exceed 20% for the debt portion to be dilutive, which is unlikely.","Both components are accretive, so the overall deal is accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Lazard Interview","SA 2025, SF Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1382","t":"deal","l":"Advanced","s":90,"q":"Two buyers offer to acquire Company A. The financial sponsor offers 1.7x Revenue, and the strategic buyer offers 15x EBITDA but is willing to go to an EBITDA multiple that includes cost synergies of 2% of revenue. Company A's EBITDA margin is 10%. Which offer should Company A accept?","k":["The strategic buyer's offer is higher.","Financial sponsor: 1.7x Revenue. If Revenue = R, offer = 1.7R.","Strategic buyer: 15x EBITDA including synergies. EBITDA = 10% x R = 0.10R. Cost synergies = 2% x R = 0.02R. Adjusted EBITDA = 0.10R + 0.02R = 0.12R.","Strategic offer = 15 x 0.12R = 1.8R.","1.8R > 1.7R, so the strategic buyer's offer is higher.","However, Company A should also consider deal certainty, regulatory risk, cultural fit, and how likely the synergies are to materialize."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Lazard Interview","SA 2025, SF Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1383","t":"deal","l":"Advanced","s":90,"q":"Company A has a share price of $30, 1,000K diluted shares outstanding, and Net Income of $2.0M (EPS of $2.00). Company A acquires Company B for $10 per share for 600K shares. Company B has $300K in net income. The deal is financed with 30% equity and 70% debt. Assume a 7.5% interest rate and a 20% tax rate. Find the new EPS for the combined entity.","k":["Answer: ~$1.93 per share (dilutive)","Purchase Price = $10 x 600K = $6M","Equity financing = 30% x $6M = $1.8M. New shares issued = $1.8M / $30 = 60K shares.","Debt financing = 70% x $6M = $4.2M","Pro forma diluted shares = 1,000K + 60K = 1,060K","Combined NI = Company A NI ($2.0M) + Company B NI ($0.3M) - after-tax interest on new debt","After-tax interest = $4.2M x 7.5% x (1 - 20%) = $0.252M","Pro forma NI = $2.0M + $0.3M - $0.252M = $2.048M","Pro forma EPS = $2.048M / 1,060K = ~$1.93","This is dilutive compared to Company A's standalone EPS of ~$2.00."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Lazard Interview","SA 2025, Healthcare group, SF Office, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1384","t":"deal","l":"Advanced","s":90,"q":"Walk me through the sell-side M&A advisory process, including the effects of cash flow, capital expenditures, working capital, and investment recommendations on the analysis.","k":["The sell-side M&A process typically follows these steps:","Engagement and preparation: Retain the sell-side advisor, negotiate engagement terms, and assemble the deal team.","Due diligence and marketing materials: Prepare a Confidential Information Memorandum (CIM), management presentation, and financial model. Analyze historical and projected cash flows, CapEx requirements, and working capital trends.","Buyer outreach: Create a buyer universe (strategic and financial), send teasers, execute NDAs, and distribute the CIM.","First-round bids: Receive Indications of Interest (IOIs). Evaluate bids on price, certainty of close, structure, and conditionality.","Management presentations and diligence: Invite shortlisted bidders to meet management. Open a data room for detailed due diligence.","Final bids: Receive binding offers. The analysis focuses heavily on normalized EBITDA, quality of earnings (adjusting for one-time items), sustainable CapEx (maintenance vs. growth), working capital normalization, and free cash flow conversion.","Negotiation and signing: Negotiate definitive agreements (SPA), representations, warranties, and indemnities.","Closing: Satisfy conditions, obtain regulatory approvals, and close the transaction.","Cash flow, CapEx, and working capital are critical because buyers ultimately value the target based on its sustainable free cash flow generation. Quality of earnings adjustments ensure EBITDA reflects recurring profitability, and working capital is typically normalized with a peg established for the closing adjustment."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Lazard Interview","SA 2026, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1385","t":"deal","l":"Advanced","s":90,"q":"I am going to describe a company to you: a luxury soap brand that manufactures in-house in the U.S. and sells through big-box retailers, Amazon, and direct-to-consumer channels. How would you position this company for sale? Does vertical or horizontal integration make more sense? Who would be an ideal strategic buyer?","k":["Positioning for Sale:","Emphasize the premium brand positioning and pricing power in the luxury personal care segment.","Highlight the domestic manufacturing capability as a supply chain advantage (quality control, speed to market, \"Made in USA\" branding).","Showcase the diversified channel mix (retail, e-commerce, DTC) as a de-risked revenue base.","Present DTC data as a valuable customer insights and margin advantage.","Vertical vs. Horizontal Integration:","Horizontal integration makes more sense. The company already has vertical integration (in-house manufacturing). A horizontal acquirer can leverage the brand across adjacent product categories (body care, skincare, candles) and expand distribution globally.","Ideal Strategic Buyers:","Large CPG companies looking to expand premium/luxury portfolios (e.g., Procter & Gamble, Unilever, L'Oreal, Estee Lauder).","Mid-market beauty/personal care platforms backed by PE sponsors rolling up brands.","A retailer looking for vertical integration into private-label luxury goods."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Lincoln International Interview","SA 2026, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1386","t":"deal","l":"Advanced","s":90,"q":"Company A has an equity value of $10B and acquires Company B. The seller receives 100% cash consideration. Company A then raises $5B in equity from a PE firm.\n\n\n\n\nAssume Company A's equity value remains exactly $10B immediately prior to the PE firm's investment. If Company A funds the acquisition using either (i) 100% cash on hand or (ii) 50% cash and 50% newly issued debt, what is the ownership split in each scenario?","k":["Both scenarios produce the same split.","Pre‑investment equity = $10 billion (A shareholders).","PE firm adds $5 billion; total equity = $15 billion.","A shareholders: 10 ÷ 15 = 66.7%.","PE firm: 5 ÷ 15 = 33.3%.","Using debt versus cash for the M&A transaction's funding changes leverage, not the equity base, so the PE firm's equity ownership percentage is identical."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in LionTree Interview","SA 2026","Merger Model (M&A)","Advanced"]},{"id":"q-1387","t":"deal","l":"Advanced","s":90,"q":"Company A has $200 in net income, a stock price of $6, and 10 shares outstanding.\n\n\n\n\nCompany B has $200 in net income, a stock price of $5, and 6 shares outstanding.\n\n\n\n\nB is purchased at a 20% premium in an all-stock deal. By what percent is the deal accretive or dilutive?","k":["25% accretive.","Purchase price = 5 × 1.2 = 6 per share ⇒ 36 total.","A shares issued = 36/6 = 6.","PF shares = 10 + 6 = 16.","PF NI = 400 ⇒ PF EPS = 25.","Standalone A EPS = 20.","Accretion = 25/20 − 1 = +25%."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Moelis & Co. Interview","SA 2026","Merger Model (M&A)","Advanced"]},{"id":"q-1388","t":"deal","l":"Advanced","s":90,"q":"Graph the relationship between exchange ratio and accretion/dilution in an M&A deal.\n\n\n\n\nExplain how different scenarios move the point on the graph.","k":["The curve slopes downward and crosses zero at the break‑even exchange ratio.","x‑axis = exchange ratio; y‑axis = % EPS change.","Left of break‑even → accretive.","Right of break‑even → dilutive.","Break‑even ratio equals Target P/E divided by Acquirer P/E.","Higher synergies shift the curve up.","Higher cost of debt shifts it down.","A stock‑price run‑up (higher acquirer valuation) moves break‑even left.","Moving a point right increases dilution; moving left increases accretion."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Moelis & Co. Interview","SA 2026","Merger Model (M&A)","Advanced"]},{"id":"q-1389","t":"deal","l":"Advanced","s":90,"q":"Company A trades at $6/share, 10 shares outstanding, $200 net income. Company B trades at $5/share, 6 shares outstanding, $200 net income.\n\n\n\n\nIf A buys B in an all-stock transaction at a 20% premium, is it accretive or dilutive, and by how much?","k":["25% accretive.","Purchase price per B share = $5 × 1.2 = $6, matching A’s price → exchange ratio 1:1.","Shares issued = 6; PF shares = 16.","PF NI = 200 + 200 = 400 → PF EPS = 400 / 16 = 25.","Standalone EPS (A) = 200 / 10 = 20.","(25 / 20) − 1 = +25% accretion."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Moelis & Co. Interview","First round","Merger Model (M&A)","Advanced"]},{"id":"q-1390","t":"deal","l":"Advanced","s":90,"q":"What are the key adjustments you would need to make to the acquirer's balance sheet in a merger model after a transaction closes?","k":["Post-close, you adjust the acquirer’s balance sheet to reflect how the deal is paid for (cash out, new debt, new shares), revalue target assets/liabilities to fair value (creating goodwill, DTLs, and extra D&A), record NCI if less than 100% acquired, expense transaction fees, capitalize financing fees, and clean up intercompany and working-capital items.","Key adjustments:","Cash ↓ – purchase price + transaction fees (net of target cash); model foregone interest income.","Debt ↑/↓ – add new deal debt (net issuance costs); repay, refinance, or assume target debt.","Equity ↑ – issue shares; increase Common Stock/APIC & diluted share count; eliminate target equity.","PP&E & Identifiable Intangibles Write-Ups – step to fair value; new D&A; create DTLs.","Goodwill Plug – Equity Purchase Price – FV net assets (post step-ups) ± DTA/DTL – NCI.","Deferred Taxes – create DTLs on all step-ups; write off unusable DTAs (e.g., expired NOLs).","Non-Controlling Interest – book NCI at fair value for stakes <100% acquired.","Fees – expense advisory/legal fees (hit Retained Earnings); capitalize & amortize financing fees.","Eliminations & Other – clear intercompany balances; adjust deferred revenue, leases, pensions, contingencies, working capital."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Moelis & Co. Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1391","t":"deal","l":"Advanced","s":90,"q":"Company A is acquiring Company B. Analyze the transaction's accretion/dilution based on the following:\n\n\n\n\nCompany A:\n\nShare Price: $50\nShares Outstanding: 1,000,000\nNet Income: $6,000,000\nTax Rate: 40%\n\n\n\nCompany B:\n\nShare Price: $11\nShares Outstanding: 500,000\nNet Income: $1,500,000\n\n\n\nDeal Assumptions:\n\nAcquisition price for B: $15 per share\nFinancing: 50% stock, 50% debt\nPre-tax synergies: $500,000\nInterest rate on new debt: 6%","k":["The deal is accretive.","Calculation:","Purchase Price = $15 * 500,000 shares = $7,500,000.","Debt Financing = $7,500,000 * 50% = $3,750,000.","Stock Financing = $3,750,000 / $50 = 75,000 new shares.","PF Shares = 1,000,000 + 75,000 = 1,075,000.","Interest Expense = $3,750,000 * 6% = $225,000.","After-Tax Interest = $225,000 * (1 - 40%) = $135,000.","After-Tax Synergies = $500,000 * (1 - 40%) = $300,000.","PF NI = $6,000,000 (A) + $1,500,000 (B) - $135,000 (interest) + $300,000 (synergies) = $7,665,000.","PF EPS = $7,665,000 / 1,075,000 = $7.13.","Standalone EPS = $6,000,000 / 1,000,000 = $6.00.","Accretion = ($7.13 - $6.00) / $6.00 = 18.8% accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Moelis & Co. Interview","SF Office","Merger Model (M&A)","Advanced"]},{"id":"q-1392","t":"deal","l":"Advanced","s":90,"q":"If a company has a P/E of 10x and a deal is financed entirely with debt, what is the breakeven interest rate?\n\n\n\n\nAssume a tax rate of 25%.","k":["The deal is accretive as long as the after-tax cost of debt is less than the target's earnings yield.","Target earnings yield = 1/10 = 10%.","Breakeven: After-tax cost of debt = 10%.","Pre-tax breakeven rate = 10% / (1 - T).","At a 25% tax rate: 10% / 0.75 = 13.3%.","At a 40% tax rate: 10% / 0.60 = 16.7%.","If the actual interest rate exceeds this breakeven, the deal becomes dilutive because the financing cost exceeds the acquired earnings."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Moelis & Co. Interview","SA 2025, Cleantech group","Merger Model (M&A)","Advanced"]},{"id":"q-1393","t":"deal","l":"Advanced","s":90,"q":"If you want to use stock to purchase a company, but the target's owners refuse to hold your securities, what could you do to complete the transaction? What are some risks?","k":["One approach is to issue stock, sell it in the market, and then use the cash proceeds for the acquisition. Alternatively, raise debt or find alternative financing.","Risks: market risk if the stock price drops, higher interest costs if using debt, or losing out if the capital raise can’t be executed on favorable terms."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Morgan Stanley Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1394","t":"deal","l":"Advanced","s":90,"q":"Target has $100mm in net income and a P/E of 20x.\n\n\n\n\nBuyer has $200mm in net income and a P/E of 10x with 1mm shares outstanding.\n\n\n\n\nIn an all-stock deal, would this be accretive or dilutive?\n\n\n\n\nBy how much in dollar value?","k":["25% dilutive; EPS falls by $50 per share.","Buyer price / share = (10 × $200 mm) ÷ 1 mm = $2,000","Purchase price = 20 × $100 mm = $2,000 mm","Shares issued = $2,000 mm ÷ $2,000 = 1 mm","Pro‑forma shares = 1 mm existing + 1 mm new = 2 mm","Pro‑forma NI = $200 mm + $100 mm = $300 mm → PF EPS = $150","Standalone EPS = $200 mm ÷ 1 mm = $200 → dilution = ($150 / $200) – 1 = ‑25%","Dollar drop per share = $200 – $150 = $50"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Morgan Stanley Interview","SA 2026, New York office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1395","t":"deal","l":"Advanced","s":90,"q":"You are analyzing a potential acquisition with the following data:\n\n\n\nCompany A: 8x EV/EBITDA, $200M EBITDA, 3x Debt/EBITDA, 100 shares outstanding.\nCompany B: 6x EV/EBITDA, $100M EBITDA, 4x Debt/EBITDA, 50 shares outstanding.\n\n\n\nPlease answer the following:\n\n\n\nWhat is Company A's equity value and share price?\nWhat is Company B's equity value and share price?\nIf A acquires B in an all-stock deal and pays 7x EBITDA for B, how many new shares must A issue?\nHow would the deal change if A pays a 20% premium to B's standalone share price instead?","k":["Part 1: Company A Equity Value and Share Price","A EV = 8x * $200M = $1,600M","A Debt = 3x * $200M = $600M","A Equity Value = $1,600M - $600M = $1,000M","A Share Price = $1,000M / 100 shares = $10/share","Part 2: Company B Equity Value and Share Price","B EV = 6x * $100M = $600M","B Debt = 4x * $100M = $400M","B Equity Value = $600M - $400M = $200M","B Share Price = $200M / 50 shares = $4/share","Part 3: All-Stock Deal at 7x EBITDA","Purchase Price (Equity) = (7x * $100M) - $400M debt = $300M","New Shares Issued = $300M / $10 (A share price) = 30 shares","Part 4: 20% Premium to B Share Price","Premium Price = $4 * 1.20 = $4.80/share","Total Purchase Price = $4.80 * 50 shares = $240M","New Shares Issued = $240M / $10 = 24 shares","This is lower than Part 3 ($240M vs $300M), requiring fewer shares issued."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Morgan Stanley Interview","New York Office","Merger Model (M&A)","Advanced"]},{"id":"q-1396","t":"deal","l":"Advanced","s":90,"q":"An acquirer has a standalone EPS of $2.00, 100 shares outstanding, and a share price of $60. The target has Net Income of $50 million and a purchase equity value of $300 million. The deal is 100% stock-financed. Is this deal accretive or dilutive, and what is the pro forma EPS?","k":["The deal is accretive. Pro forma EPS is $2.38 vs. standalone EPS of $2.00.","Calculation:","Acquirer NI = EPS x Shares = $2.00 x 100M = $200M","Target NI = $50M","Pro forma NI = $200M + $50M = $250M","New shares issued = $300M / $60 = 5M shares","Pro forma shares = 100M + 5M = 105M","Pro forma EPS = $250M / 105M = $2.38","Quick check: Acquirer P/E = 30x, Target P/E = 6x. In an all-stock deal, buying a lower P/E target is accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Morgan Stanley Interview","SA 2027, TMT group, Menlo Park Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1397","t":"deal","l":"Advanced","s":90,"q":"Two assets are being combined. One produces $100M in EBITDA and has 4x leverage, and the other produces $50M in EBITDA and has 2x leverage. What is the pro forma leverage ratio?","k":["Answer: 3.33x","Asset 1: Debt = 4 x $100M = $400M.","Asset 2: Debt = 2 x $50M = $100M.","Pro Forma EBITDA = $150M. Pro Forma Debt = $500M.","Pro Forma Leverage = $500M / $150M = 3.33x."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Generalist group, New York Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1398","t":"deal","l":"Advanced","s":90,"q":"Cisco acquired Splunk for $28B. What metrics would you need to calculate the minimum amount of synergies that would make this deal accretive?\n\n\n\n\nFollow-up: Cisco has Net Income of $18B and EPS of $4.50. Splunk has Net Income of $1B. It is a 100% cash transaction with a 5% cost of cash and a 20% tax rate. Calculate the pre-tax amount of synergies needed to make the deal accretive.","k":["Metrics Needed","Acquirer's EPS and shares outstanding","Target's net income","Deal consideration (cash, stock, or mix) and financing terms","Cost of cash (foregone interest income) or cost of new debt","Tax rate for synergy calculations","Follow-up Calculation","Cisco shares = NI / EPS = $18B / $4.50 = 4B shares","Cisco pre-deal EPS = $4.50","Foregone after-tax interest income on cash = $28B x 5% x (1 - 20%) = $1.12B","Pro forma NI (no synergies) = $18B + $1B - $1.12B = $17.88B","Pro forma EPS (no synergies) = $17.88B / 4B = $4.47 -- dilutive by $0.03","After-tax synergies needed = ($4.50 - $4.47) x 4B = $0.12B = $120M","Pre-tax synergies = $120M / (1 - 20%) = $150M","The deal needs at least $150M in pre-tax synergies to break even on an EPS basis."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Morgan Stanley Interview","SA 2025, Menlo Park Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1399","t":"deal","l":"Advanced","s":90,"q":"What is the formula for break-even synergies in an accretion/dilution analysis? Walk me through a numeric example.","k":["Break-even synergies are the minimum pre-tax synergies needed to make a dilutive deal break even (i.e., pro forma EPS equals standalone EPS).","Formula: Break-Even Synergies = Dilution / (1 - Tax Rate)","Numeric Example:","Acquirer: 100M shares, $2.00 EPS, $200M NI. Share price $30.","Target: Purchase price $500M, NI = $10M. 100% stock deal.","New shares issued: $500M / $30 = 16.67M shares.","Pro forma NI (before synergies): $200M + $10M = $210M.","Pro forma shares: 100M + 16.67M = 116.67M.","Pro forma EPS: $210M / 116.67M = $1.80 vs. standalone $2.00.","Dilution = ($2.00 - $1.80) x 116.67M shares = $23.3M after-tax.","Break-even synergies (pre-tax) = $23.3M / (1 - 0.25) = $31.1M (assuming 25% tax rate).","The acquirer needs at least $31.1M in pre-tax synergies for the deal to be EPS-neutral."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Morgan Stanley Interview","SA 2026, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1400","t":"deal","l":"Advanced","s":90,"q":"You are analyzing a potential acquisition with the following details:\n\n\n\n\nTarget Company:\n\nEBIT: $80 million\nAssumed Tax Rate: 25%\nAssumed Cost of Debt: 4%\n\n\n\nAcquirer Company:\n\nShares Outstanding: 200 million\nP/E Multiple: 20x\nShare Price: $20\n\n\n\nAnswer the following:\n\nWhat is the maximum amount of debt that can be used to acquire the target such that the interest expense is fully covered by the target's EBIT (i.e., the deal is breakeven on a pre-tax basis)?\nUsing the value from Part 1 as the purchase price, if the deal is financed with 50% stock and 50% debt, is the transaction accretive or dilutive?","k":["Part 1: Maximum Debt for Breakeven","Answer: $2,000M","For breakeven pre-tax: Interest Expense = EBIT, so $80M = Debt * 4%.","Debt = $80M / 4% = $2,000M.","Part 2: Accretion/Dilution Analysis","The deal is dilutive.","Purchase Price = $2,000M (from Part 1).","Stock Financing = $2,000M * 50% = $1,000M.","New Shares Issued = $1,000M / $20 = 50M shares.","PF Shares = 200M + 50M = 250M.","Debt Financing = $1,000M.","Interest Expense = $1,000M * 4% = $40M.","Target EBIT = $80M.","Target NI Contribution = ($80M - $40M interest) * (1 - 25%) = $30M.","Acquirer Standalone NI = Market Cap / P/E = ($20 * 200M) / 20 = $200M.","PF NI = $200M + $30M = $230M.","PF EPS = $230M / 250M = $0.92.","Standalone EPS = $200M / 200M = $1.00.","The transaction is 8% dilutive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Perella Weinberg Interview","New York Office","Merger Model (M&A)","Advanced"]},{"id":"q-1401","t":"deal","l":"Advanced","s":90,"q":"Company A has 100M shares outstanding and a $50 share price. It purchases Company B for $2B using 50% stock and 50% cash. What will the ownership split be after the deal?","k":["Answer: Original Company A shareholders own 83.3%, Company B shareholders own 16.7%.","Company A pre-deal Equity Value = 100M shares x $50 = $5B","Stock consideration = 50% x $2B = $1B","New shares issued = $1B / $50 per share = 20M shares","Total shares post-deal = 100M + 20M = 120M","Company A shareholders: 100M / 120M = 83.3%","Company B shareholders: 20M / 120M = 16.7%"],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Perella Weinberg Interview","SA 2026, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1402","t":"deal","l":"Advanced","s":90,"q":"You are given the following information:\n\n\n\nCompany A: Equity Value $1B, Net Income $100M, Shares Outstanding 10M\nCompany B: Equity Value $2B, Net Income $50M, Shares Outstanding 10M\n\n\n\nIn a 100% stock deal, how much in operating profit synergies would need to be realized in order for the deal to break even on an EPS basis? Assume a 25% tax rate.","k":["Answer: $150M in after-tax synergies, or $200M in pre-tax operating profit synergies (at a 25% tax rate).","Company A pre-deal EPS = $100M / 10M = $10.00","Company A share price = $1B / 10M = $100","Company B Equity Value = $2B. New shares issued = $2B / $100 = 20M shares","Pro forma shares = 10M + 20M = 30M","Pro forma NI (without synergies) = $100M + $50M = $150M","Pro forma EPS (without synergies) = $150M / 30M = $5.00 -- dilutive vs. $10.00","To break even: Need EPS = $10.00, so NI = $10.00 x 30M = $300M","After-tax synergies needed = $300M - $150M = $150M","Since the question asks for operating profit synergies (pre-tax), divide by (1 - tax rate): $150M / 0.75 = $200M in pre-tax operating profit synergies."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Perella Weinberg Interview","SA 2026, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1403","t":"deal","l":"Advanced","s":90,"q":"How can you quantitatively determine whether an acquisition has been successful?","k":["EPS accretion/dilution: Did pro forma EPS increase relative to standalone? This is the most immediate test.","Stock price performance: Compare the acquirer's stock price post-deal to its pre-announcement price and to a relevant index. Underperformance suggests value destruction.","Synergy realization: Did the company achieve the cost and revenue synergies it projected at announcement? Track reported synergies vs. targets.","ROIC vs. WACC: Does the return on invested capital from the acquisition exceed the company's WACC? If ROIC < WACC, the deal destroyed value.","Revenue and margin trends: Did the combined entity grow revenue faster and achieve better margins than standalone projections?","Customer and employee retention: High attrition post-close signals integration problems and potential value destruction."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Perella Weinberg Interview","SA 2026, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1404","t":"deal","l":"Advanced","s":90,"q":"What is a working capital peg and why is it important in an M&A transaction? Does the buyer want a higher or lower working capital peg? How about the seller?","k":["A working capital peg (or target) is an agreed-upon level of net working capital that the seller must deliver at closing. It is typically based on an average of the trailing 12 months of NWC to reflect a normalized operating level.","Why It Matters:","Without a peg, the seller could manipulate NWC before closing (e.g., collecting receivables aggressively, delaying payables) to extract extra cash, leaving the buyer with an undercapitalized business.","The peg ensures the buyer receives a business with adequate working capital to operate normally from day one.","Buyer vs. Seller Preferences:","The buyer wants a higher peg, because a higher NWC target means more current assets (cash, receivables, inventory) are included in the deal at no extra cost beyond the purchase price.","The seller wants a lower peg, because any NWC above the peg at closing is returned to the seller as a dollar-for-dollar adjustment. A lower target makes it easier to exceed the peg and receive a payment at close."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Piper Sandler Interview","SA 2025, Houston Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1405","t":"deal","l":"Advanced","s":90,"q":"Company A, with an equity value of $200M and a P/E of 10x, acquires Company B, which has an equity value of $100M. Assume an all-stock transaction where Company A issues its own stock to acquire Company B at its current equity value (no premium).\n\n\n\n\nPart 1: If Company B also has a P/E of 10x, is the deal accretive or dilutive?\n\n\n\n\nPart 2: If Company B's P/E is 5x, is the deal accretive or dilutive? By what percentage?","k":["Part 1: Break-even","The deal is neither accretive nor dilutive.","A's Cost of Equity = 1 / P/E = 1 / 10x = 10%","B's Earnings Yield = 1 / P/E = 1 / 10x = 10%","Since Cost (10%) = Yield (10%), it's break-even.","Part 2: Accretion","The deal is accretive by 33%.","Calculation:","A's NI = $200M / 10x = $20M","B's NI = $100M / 5x = $20M","Pro-Forma NI = $20M + $20M = $40M","New shares issued = $100M / ($200M / existing shares), but shares cancel in EPS calc","A issues $100M worth of stock at $200M market cap. If A had 100 shares initially, A issues 50 shares ($100M / $2 per share)","Pro-Forma shares = 100 + 50 = 150","Pro-Forma EPS = $40M / 150 = $0.267","Standalone EPS = $20M / 100 = $0.20","Accretion = ($0.267 / $0.20) - 1 = 33%"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in PJT Partners Interview","First round","Merger Model (M&A)","Advanced"]},{"id":"q-1406","t":"deal","l":"Advanced","s":90,"q":"Part 1: Company B acquires Company A. Company A trades at $10 per share with 60 million shares outstanding and is acquired at a 50% premium. Company B trades at $30 per share with 70 million shares outstanding. In an all-stock transaction, what is the exchange ratio and how much of the pro forma company do Company A's shareholders own?\n\n\n\n\nPart 2: The transaction is now structured as $5 in cash and $10 in stock per share. What is the new exchange ratio and how much of the pro forma company do Company A's shareholders own?\n\n\n\n\nPart 3: Would Company A's shareholders prefer the all-stock transaction or the split cash/stock transaction?","k":["Part 1: All-Stock","Offer = $10 x 1.50 = $15/share.","Exchange ratio = $15 / $30 = 0.50x.","New shares = 60M x 0.50 = 30M.","Pro forma shares = 70M + 30M = 100M.","Company A ownership = 30M / 100M = 30%.","Part 2: $5 Cash + $10 Stock","Stock exchange ratio = $10 / $30 = 0.333x.","New shares = 60M x 0.333 = 20M.","Pro forma shares = 70M + 20M = 90M.","Company A ownership = 20M / 90M = 22.2%.","Part 3: Preference","Depends on outlook. All-stock gives 30% ownership and more upside if the combined entity performs well. Cash/stock gives immediate liquidity ($5/share) but less ownership (22.2%). Risk-averse shareholders prefer cash; those bullish on the combined entity prefer all-stock."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in PJT Partners Interview","SA 2026, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1407","t":"deal","l":"Advanced","s":90,"q":"Company A trades at 10x P/E with 10M shares and $2 EPS. Company B trades at 20x P/E with 10M shares and $0.50 EPS. Company A acquires Company B in an all-debt transaction at a 50% premium with $12M in pre-tax synergies. Assume a 20% tax rate and a 6% interest rate on the acquisition debt. Is the deal accretive or dilutive?","k":["The deal is accretive — pro forma EPS increases to $2.74 from $2.00, roughly 37% accretion.","Company A standalone NI = $2 x 10M = $20M. EPS = $2.00.","Company B NI = $0.50 x 10M = $5M.","Company B Equity Value = $0.50 x 20 x 10M = $100M. With 50% premium: Purchase Price = $150M.","All-debt financing at 6%: Pre-tax interest = $150M x 6% = $9M. After-tax interest = $9M x (1 - 20%) = $7.2M.","After-tax synergies = $12M x (1 - 20%) = $9.6M.","Pro Forma NI = $20M (A) + $5M (B) + $9.6M (synergies) - $7.2M (interest) = $27.4M.","No new shares issued (all-debt deal), so shares remain at 10M.","Pro Forma EPS = $27.4M / 10M = $2.74. Accretion = ($2.74 - $2.00) / $2.00 = 37% accretive.","Breakeven interest rate: the deal remains accretive at any pre-tax rate below ~12.2% ($14.6M added earnings / $120M after-tax debt cost factor)."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in PJT Partners Interview","SA 2025, Houston Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1408","t":"deal","l":"Advanced","s":90,"q":"A company with a 10x P/E multiple buys a company with a 20x P/E multiple.\n\n\n\n\nWhat is the breakeven cost of debt that would cancel out the difference?","k":["Conceptually, you want the overall financing cost to match or be below the yield implied by the target’s earnings. The target’s yield is 1/20 = 5%. The acquirer’s cost of equity is 1/10 = 10%.","So, to break even, the after-tax cost of debt must be at or below 5% to offset the “overpayment” relative to the acquirer’s 10% cost of equity.","Note the above assumes an all-debt deal (which should be said outloud as an assumption)."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Qatalyst Partners Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1409","t":"deal","l":"Advanced","s":90,"q":"The acquirer has a P/E of 10x, a debt interest rate of 8%, and is financing the deal with 50% debt and 50% stock. Assume a 20% tax rate. The target has a P/E of 8x. Calculate the acquirer's WACC. Is the deal accretive or dilutive?","k":["WACC Calculation (of the acquisition financing):","Cost of Equity (implied) ≈ Earnings Yield = 1 / P/E = 1/10 = 10%. Note: earnings yield (E/P) is a rough approximation for cost of equity. It does not account for growth - a company reinvesting earnings at high returns will have a higher true cost of equity than E/P implies. In practice, CAPM is used for a more precise estimate.","After-Tax Cost of Debt = 8% x (1 - 20%) = 6.4%","WACC = 50% x 10% + 50% x 6.4% = 5% + 3.2% = 8.2%","Accretion / Dilution:","The target's earnings yield = 1/8 = 12.5%.","The acquirer's blended cost of financing = 8.2%.","Since the target's earnings yield (12.5%) exceeds the cost of financing (8.2%), the deal is accretive.","Intuitively: the acquirer is buying cheaper earnings (8x P/E) using a more expensive currency (10x P/E equity + 6.4% after-tax debt). The target generates more earnings per dollar of purchase price than the acquirer's cost of capital."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in RBC Interview","SA 2025, SF Office, First round","Merger Model (M&A)","Advanced"]},{"id":"q-1410","t":"deal","l":"Advanced","s":90,"q":"Company A (P/E = 15x) buys Company B (P/E = 10x) in an all-stock deal — is it accretive or dilutive?\n\n\n\n\nNow imagine it's an all-debt deal. What cost of debt would make it dilutive? Assume a 50% tax rate.","k":["Part 1:","Accretive.","Target earnings yield = 10%; Acquirer equity cost = 6.7%; swapping cheaper equity for higher‑yield earnings lifts EPS.","Part 2:","20%.","Break‑even after‑tax cost = target earnings yield = 10%.","Pre‑tax cost = 10% ÷ (1 − 0.5) = 20%; anything higher turns the deal dilutive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Rothschild Interview","SA 2026","Merger Model (M&A)","Advanced"]},{"id":"q-1411","t":"deal","l":"Advanced","s":90,"q":"How would you go through a full sell-side deal process in a short amount of time? Walk me through the key steps and considerations.","k":["An accelerated sell-side process compresses the typical 6-9 month timeline into 3-4 months. Key steps:","Preparation (Week 1-3): Prepare the Confidential Information Memorandum (CIM), management presentation, and data room simultaneously. Develop the buyer list (both strategic and financial) and create the teaser.","Market outreach (Week 3-5): Send teasers to a targeted buyer universe. Focus on the most likely bidders rather than a broad auction to save time. Have NDAs ready for immediate execution.","First round (Week 5-8): Distribute the CIM and grant data room access to interested parties. Receive initial indications of interest (IOIs) with preliminary valuations and deal structures.","Second round (Week 8-12): Select 3-5 bidders for management presentations. Provide detailed due diligence access. Request final binding bids with markup of the purchase agreement.","Final negotiations (Week 12-14): Select the winning bidder, negotiate final terms, and sign the definitive agreement.","Key considerations in an accelerated process: prioritize deal certainty (focus on well-capitalized buyers), maintain competitive tension among bidders, ensure management bandwidth is protected, and keep fallback options alive in case the lead bidder drops out."],"collection":"practice","topic":"Merger Model (M&A)","tags":["New","Reported in Rothschild Interview","SA 2027, Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1412","t":"deal","l":"Advanced","s":90,"q":"Would a buyer's willingness to pay (WTP) generally be higher for cost synergies or for revenue synergies?\n\n\n\n\nFollow-up 1: Which type of synergy, cost or revenue, would result in a greater increase to pro-forma EBITDA?\n\n\n\n\nFollow-up 2: If you were presented with $10 million in potential revenue synergies versus $10 million in potential cost synergies, which would you prefer and why?","k":["Part 1: Willingness to Pay","Buyers typically have higher WTP for cost synergies because they are more certain and easier to execute (headcount reduction, facility consolidation, procurement savings).","Part 2: EBITDA Impact","Cost synergies result in a greater increase to pro-forma EBITDA per dollar of synergy because they flow directly to EBITDA (100% impact).","Revenue synergies must first cover COGS and variable expenses, so only the gross margin portion flows to EBITDA (e.g., 30-50% impact depending on margin).","Part 3: Preference","Cost synergies are preferable because they have higher certainty, faster realization timeline, and greater EBITDA impact per dollar.","Revenue synergies are less predictable (depend on customer behavior, integration execution, and market conditions) and take longer to materialize."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in TAP Advisors Interview","First round","Merger Model (M&A)","Advanced"]},{"id":"q-1413","t":"deal","l":"Advanced","s":90,"q":"We often discuss revenue and cost synergies in a transaction.\n\n\n\n\nWhat are some examples of dis-synergies that could occur as a result of a merger?","k":["Common dis-synergies include:","Customer attrition due to uncertainty or competitive concerns during integration.","Key employee departures and loss of institutional knowledge.","Cultural clashes reducing productivity and morale.","Distraction of management from core operations during integration.","IT system integration costs and operational disruptions.","Loss of supplier discounts or favorable contract terms.","Regulatory costs or required divestitures.","Overlapping product portfolios cannibalizing sales.","Integration expenses exceeding initial estimates."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1414","t":"deal","l":"Advanced","s":90,"q":"You are analyzing a potential acquisition with the following details:\n\n\n\nAcquirer A: $100 NI, 20 shares outstanding, 10x P/E multiple.\nTarget B: $25 NI, 25 shares outstanding.\n\n\n\nCompany A acquires Company B at a 15x P/E multiple in an all-cash transaction financed with new debt at a 5% interest rate.\n\n\n\n\nAssuming a 20% tax rate, is this deal accretive or dilutive, and by how much?","k":["The deal is accretive by $0.50 per share.","Calculation:","Purchase Price = $25 NI * 15x P/E = $375.","Interest Expense on Debt = $375 * 5% = $18.75.","After-Tax Interest = $18.75 * (1 - 20%) = $15.","PF NI = $100 (A) + $25 (B) - $15 (interest) = $110.","PF Shares = 20 (no new shares issued in cash deal).","PF EPS = $110 / 20 = $5.50.","Standalone EPS = $100 / 20 = $5.00.","Accretion = $5.50 - $5.00 = $0.50 per share."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1415","t":"deal","l":"Advanced","s":90,"q":"Company A, with $18M in Net Income and 6M shares outstanding, acquires Company B, which has $12.5M in Net Income.\n\n\n\n\nThe deal is financed with a $40M bond at a 20% interest rate, and Company A issues 2M new shares.\n\n\n\n\nAssume $10M in pre-tax synergies and a 25% tax rate.\n\n\n\n\nIs this transaction accretive, and by how much in both dollar and percentage terms?","k":["The deal is accretive by $1.00 per share or 33.3%.","Calculation:","Standalone EPS: $18M / 6M shares = $3.00","Interest expense: $40M * 20% = $8M","After-tax interest: $8M * (1 - 25%) = $6M","After-tax synergies: $10M * (1 - 25%) = $7.5M","Pro-forma NI: $18M + $12.5M - $6M + $7.5M = $32M","Pro-forma shares: 6M + 2M = 8M","Pro-forma EPS: $32M / 8M = $4.00","Accretion: $4.00 - $3.00 = $1.00 per share","% Accretion: ($4.00 / $3.00) - 1 = 33.3%"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1416","t":"deal","l":"Advanced","s":90,"q":"Company A has a Net Income of $18M and 6M shares outstanding.\n\n\n\n\nIt acquires Company B, which has a Net Income of $12.5M.\n\n\n\n\nThe transaction is financed entirely with $40M of new debt at a 20% interest rate.\n\n\n\n\nAssuming $10M in pre-tax synergies and a 25% tax rate, how accretive or dilutive is this deal in both dollar and percentage terms?","k":["The deal is accretive by $2.33 per share or 77.7%.","Calculation:","Standalone EPS: $18M / 6M shares = $3.00","Interest expense: $40M * 20% = $8M","After-tax interest: $8M * (1 - 25%) = $6M","After-tax synergies: $10M * (1 - 25%) = $7.5M","Pro-forma NI: $18M + $12.5M - $6M + $7.5M = $32M","Pro-forma shares: 6M (no new shares issued)","Pro-forma EPS: $32M / 6M = $5.33","Accretion: $5.33 - $3.00 = $2.33 per share","% Accretion: ($5.33 / $3.00) - 1 = 77.7%"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1417","t":"deal","l":"Advanced","s":90,"q":"You are analyzing a potential acquisition with the following details:\n\n\n\nAcquirer A: $200m Revenue, 40% EBITDA margin, 20% NI margin, $10 share price, 60m shares outstanding, $800m debt, $100m cash.\nTarget B: $100m Revenue, 40% EBITDA margin, 20% NI margin, $5 share price, 50m shares outstanding, $500m debt, $100m cash.\n\n\n\nAnswer the following questions:\n\n\n\nCalculate the standalone EBITDA and Net Income for both companies.\nCalculate the standalone Equity Value and Enterprise Value for both companies.\nAssuming Acquirer A buys Target B for a 40% premium using 100% stock, what is the pro-forma EPS? Is the deal accretive or dilutive? Assume no synergies.","k":["Part 1: EBITDA and Net Income","A EBITDA: $200m * 40% = $80m","A NI: $200m * 20% = $40m","B EBITDA: $100m * 40% = $40m","B NI: $100m * 20% = $20m","Part 2: Equity Value and Enterprise Value","A Equity Value: $10 * 60m = $600m","A EV: $600m + $800m - $100m = $1,300m","B Equity Value: $5 * 50m = $250m","B EV: $250m + $500m - $100m = $650m","Part 3: Accretion/Dilution Analysis","The deal is dilutive by $0.04 per share or -6%.","Calculation:","Standalone A EPS: $40m / 60m = $0.67","Purchase price: $250m * 1.40 = $350m","Shares issued: $350m / $10 = 35m shares","Pro-forma shares: 60m + 35m = 95m","Pro-forma NI: $40m + $20m = $60m","Pro-forma EPS: $60m / 95m = $0.63","Dilution: $0.63 - $0.67 = -$0.04 per share or -6%"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1418","t":"deal","l":"Advanced","s":90,"q":"Company A has $100 of revenue. It acquires Company B, which also has $100 of revenue. Post-acquisition, with no revenue synergies, the combined entity reports $300 in revenue. How is this possible?","k":["The most likely explanation is that Company B was already a customer or supplier of Company A, creating intercompany revenue that was eliminated in consolidation.","Example scenario:","Company A: $100 standalone revenue","Company B: $100 standalone revenue, including $100 sold to A","Pre-acquisition, A's standalone revenue already included the value chain from B","Post-acquisition, consolidation reveals $300 gross revenue ($100 + $200 from B's other customers + $100 intercompany, which nets to $300 after elimination adjustments)","This occurs in vertical integration scenarios where related-party transactions become visible post-consolidation."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1419","t":"deal","l":"Advanced","s":90,"q":"You are analyzing an acquisition of Company B by Company A.\n\n\n\nCompany A: 10 shares outstanding, $25 share price, $10 Net Income, 40% tax rate.\nCompany B: $150 market cap, $10 Net Income, 40% tax rate.\n\n\n\nPart 1: If A acquires B using 100% stock, is the deal accretive or dilutive?\n\n\n\n\nPart 2: If A acquires B using 100% debt at a 10% pre-tax interest rate, and there are $5 in pre-tax synergies, is the deal accretive or dilutive?","k":["Part 1: 100% Stock","The deal is accretive by $0.25 per share or 25%.","A Standalone EPS: $10 / 10 shares = $1.00","Shares issued: $150 / $25 = 6 shares","Pro-forma shares: 10 + 6 = 16 shares","Pro-forma NI: $10 + $10 = $20","Pro-forma EPS: $20 / 16 = $1.25","Accretion: $1.25 - $1.00 = $0.25 or 25%","Part 2: 100% Debt with Synergies","The deal is accretive by $0.40 per share or 40%.","Interest expense: $150 * 10% = $15","After-tax interest: $15 * (1 - 40%) = $9","After-tax synergies: $5 * (1 - 40%) = $3","Pro-forma NI: $10 + $10 - $9 + $3 = $14","Pro-forma shares: 10 (no dilution)","Pro-forma EPS: $14 / 10 = $1.40","Accretion: $1.40 - $1.00 = $0.40 or 40%"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1420","t":"deal","l":"Advanced","s":90,"q":"You are analyzing two companies. Assume Gross Profit - SG&A = EBITDA.\n\n\n\nCompany A: EV/EBITDA = 15x, Revenue = $200, Gross Margin = 50%, SG&A = $20, D&A = $10, Total Debt = $300.\nCompany B: EV/EBITDA = 13x, Revenue = $100, Gross Margin = 60%, SG&A = $10, D&A = $5, Total Debt = $150.\n\n\n\nPart 1: Calculate the EBITDA and Enterprise Value for both companies.\n\n\n\n\nPart 2: Company A acquires Company B using 100% debt financing to cover the purchase of B's equity. Assume B's debt is refinanced. There are $10 in annual synergies. What was Company A's standalone leverage ratio (Debt/EBITDA) and what is the pro-forma leverage ratio post-acquisition?","k":["Part 1: EBITDA and Enterprise Value","A EBITDA: ($200 * 50%) - $20 = $80","A EV: $80 * 15x = $1,200","B EBITDA: ($100 * 60%) - $10 = $50","B EV: $50 * 13x = $650","Part 2: Leverage Analysis","A Standalone Leverage: $300 / $80 = 3.75x","B Equity Value: $650 - $150 = $500","New debt to purchase B's equity: $500","New debt to refinance B's existing debt: $150","Total new debt raised: $500 + $150 = $650","Pro-forma debt: $300 + $650 = $950","Pro-forma EBITDA: $80 + $50 + $10 = $140","Pro-forma Leverage: $950 / $140 = 6.79x"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1421","t":"deal","l":"Advanced","s":90,"q":"You are analyzing a potential 100% stock acquisition of Company B by Company A.\n\n\n\nCompany A: 10 shares outstanding, $25 share price, $25 Net Income.\nCompany B: $150 Market Cap, $11 Net Income.\n\n\n\nAnswer the following:\n\nIs the transaction accretive or dilutive?\nWhat amount of post-tax synergies would be required for the deal to be breakeven?","k":["Part 1: Accretion / Dilution","The deal is dilutive.","A's Standalone EPS = $25 NI / 10 shares = $2.50","Shares Issued = $150 / $25 = 6 shares","PF Shares = 10 + 6 = 16 shares","PF NI = $25 + $11 = $36","PF EPS = $36 / 16 = $2.25","Dilution = ($2.25 / $2.50) - 1 = -10%","Part 2: Breakeven Synergies","Answer: $4","Required PF EPS = $2.50 (A's standalone)","Required PF NI = $2.50 * 16 shares = $40","Current PF NI = $36","Required Post-Tax Synergies = $40 - $36 = $4"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1422","t":"deal","l":"Advanced","s":90,"q":"Company A acquires Company B in an all-stock deal. The details are as follows:\n\n\n\nCompany A: $10 share price, 50 shares outstanding, $50 Net Income.\nCompany B: $10 share price, 50 shares outstanding, $25 Net Income.\n\n\n\nPart 1: Is the transaction accretive or dilutive?\n\nPart 2: What amount of pre-tax synergies would be required for the deal to be breakeven? Assume a 40% tax rate.","k":["Part 1: Accretion / Dilution","The deal is dilutive.","A's Standalone EPS = $50 / 50 = $1.00.","B's Equity Value = $10 * 50 = $500.","Shares Issued = $500 / $10 = 50 shares.","Pro Forma Shares = 50 + 50 = 100.","Pro Forma NI = $50 + $25 = $75.","Pro Forma EPS = $75 / 100 = $0.75.","Change = ($0.75 / $1.00) - 1 = -25% (dilutive).","Part 2: Breakeven Synergies","Answer: $41.67","Required PF EPS = $1.00 (to break even).","Required PF NI = $1.00 * 100 = $100.","Required After-Tax Synergies = $100 - $75 = $25.","Pre-Tax Synergies = $25 / (1 - 40%) = $25 / 0.6 = $41.67."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1423","t":"deal","l":"Advanced","s":90,"q":"You are comparing two companies in the same industry and with similar business models:\n\n\n\nCompany A: EBITDA $200M, Leverage 3.0x, EV/EBITDA 8.0x, 100M shares outstanding.\nCompany B: EBITDA $100M, Leverage 4.0x, EV/EBITDA 6.0x, 50M shares outstanding.\n\n\n\nAnswer the following questions:\n\n\n\nWhat are some reasons the multiples might be different?\nWhat is Company A's share price?\nAssume A acquires B using new debt, and Company B's existing debt is rolled over. What is the combined leverage ratio?\nIf the combined company trades at an 8.0x multiple, what is the new share price, and is the transaction accretive to Company A's original share price?","k":["Part 1: Multiple Differences","Possible reasons:","Growth rates: A may have higher growth prospects.","Profitability: A has better margins or returns.","Risk: B's higher leverage increases risk, lowering multiple.","Size: A's scale provides advantages.","Part 2: Company A Share Price","Answer: $10","A's EV = $200M * 8.0x = $1,600M.","A's Debt = $200M * 3.0x = $600M.","A's Equity Value = $1,600M - $600M = $1,000M.","Share Price = $1,000M / 100M = $10.","Part 3: Combined Leverage","Answer: 4.0x","B's EV = $100M * 6.0x = $600M.","B's Existing Debt = $100M * 4.0x = $400M.","B's Equity Value = $600M - $400M = $200M.","New Debt for Acquisition = $200M.","Total Combined Debt = $600M (A) + $400M (B) + $200M (new) = $1,200M.","Combined EBITDA = $200M + $100M = $300M.","Combined Leverage = $1,200M / $300M = 4.0x.","Part 4: New Share Price","Answer: $12 (accretive)","Combined EV = $300M * 8.0x = $2,400M.","Combined Equity = $2,400M - $1,200M = $1,200M.","New Share Price = $1,200M / 100M = $12.","Change = ($12 / $10) - 1 = 20% accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1424","t":"deal","l":"Advanced","s":90,"q":"Part 1: An acquirer with a P/E of 40x acquires a target with a P/E of 20x in an all-stock transaction. Is the deal accretive or dilutive?\n\n\n\n\nPart 2: Now, assume the following for a 100% stock deal:\n\n\n\nAcquirer: 10 shares, $25/share, $10 NI.\nTarget: $150 equity value, $10 NI.\n\n\n\nAssuming no taxes, how accretive is the deal?","k":["Part 1: Accretion / Dilution","The deal is accretive.","Acquirer Cost of Equity = 1 / 40x = 2.5%.","Target Yield = 1 / 20x = 5.0%.","Since Cost (2.5%) < Yield (5.0%), it's accretive.","Part 2: Accretion Percentage","Answer: 25% accretive","Standalone EPS = $10 / 10 = $1.00.","Shares Issued = $150 / $25 = 6 shares.","Pro Forma Shares = 10 + 6 = 16.","Pro Forma NI = $10 + $10 = $20.","Pro Forma EPS = $20 / 16 = $1.25.","Accretion = ($1.25 / $1.00) - 1 = 25%."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1425","t":"deal","l":"Advanced","s":90,"q":"Company A acquires Company B in an all-debt deal at B's market price.\n\n\n\n\nGiven the following data, is the transaction accretive?\n\n\n\nCompany A: Market Cap $200m, P/E 20x, 100m shares outstanding\nCompany B: Market Cap $100m, P/E 10x\nAssumptions: 5% pre-tax cost of debt, $5m pre-tax synergies, 20% tax rate\n\n\n\nFollow-up 1: What if the deal was financed with 50% debt and 50% equity?\n\n\n\n\nFollow-up 2: At a high level, what does accretion/dilution signify in this context?","k":["The deal is accretive.","Analysis:","A's Net Income = Market Cap / P/E = $200m / 20x = $10m","A's Standalone EPS = Net Income / Shares = $10m / 100m = $0.10","B's Net Income = $100m / 10x = $10m","After-Tax Cost of Debt = 5% * (1 - 20%) = 4%","Target's Earnings Yield = 1 / 10x = 10%","Since the cost of acquisition (4%) is less than the target's yield (10%), the deal is accretive, even before considering synergies","Accretion Calculation:","After-Tax Synergies = $5m * (1 - 20%) = $4m","After-Tax Interest Expense = $100m * 5% * (1 - 20%) = $4m","Pro Forma NI = $10m (A's NI) + $10m (B's NI) + $4m (Synergies) - $4m (Interest) = $20m","Pro Forma EPS = $20m / 100m shares = $0.20 (vs. $0.10 standalone)","Follow-up 1: 50% Debt / 50% Equity","The deal remains accretive but less so.","Debt Raised = $50m, Equity Raised = $50m","A's Cost of Equity = 1 / 20x P/E = 5%","WACC = (50% * 4%) + (50% * 5%) = 4.5%","Since Cost (4.5%) < Yield (10%), still accretive","New Shares = $50m / $2 = 25m shares","Interest = $50m * 5% * (1 - 20%) = $2m after-tax","PF NI = $10m + $10m + $4m - $2m = $22m","PF EPS = $22m / 125m shares = $0.176 (vs. $0.10 standalone)","Follow-up 2: What Does It Signify?","Accretion/dilution measures the immediate impact on EPS. Accretion indicates the buyer is acquiring earnings at a lower cost than its own earnings multiple. However, it doesn't capture strategic value, synergies, or long-term growth, so companies may pursue dilutive deals for strategic reasons."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1426","t":"deal","l":"Advanced","s":90,"q":"Company A acquires Company B in an all-stock deal with no premium.\n\n\n\n\nGiven the data below, what are the after-tax synergies required to make the deal break-even on an EPS basis?\n\n\n\nCompany A: P/E 10x, EPS $5, 10,000 shares outstanding\nCompany B: P/E 20x, EPS $2, 5,000 shares outstanding","k":["Answer: $10,000","Calculation:","A's NI = $5 * 10,000 = $50,000","B's NI = $2 * 5,000 = $10,000","B's Share Price = $2 * 20x = $40","B's Market Cap = $40 * 5,000 = $200,000","A's Share Price = $5 * 10x = $50","Shares Issued = $200,000 / $50 = 4,000 shares","PF Shares Outstanding = 10,000 + 4,000 = 14,000 shares","Break-Even PF EPS = $5 (must equal standalone EPS to break-even)","Required PF NI = $5 * 14,000 = $70,000","Combined NI without synergies = $50,000 + $10,000 = $60,000","Required After-Tax Synergies = $70,000 - $60,000 = $10,000"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1427","t":"deal","l":"Advanced","s":90,"q":"Company A is acquiring Company B. Given the data below, what financing mix (cash, debt, stock) would make the deal accretive?\n\n\n\nAcquirer Cost of Cash (pre-tax) = 4%\nAcquirer Cost of Debt (pre-tax) = 8%\nAcquirer P/E = 20x\nAcquirer Tax Rate = 40%\nTarget P/E = 15x\n\n\n\nWhat are the practical limits for each funding source?","k":["Any financing mix where the WACC is less than the target yield will be accretive.","Analysis:","Target Yield = 1 / 15x = 6.67%","Cost of Cash (after-tax) = 4% * (1 - 40%) = 2.4%","Cost of Debt (after-tax) = 8% * (1 - 40%) = 4.8%","Cost of Equity = 1 / 20x = 5%","Since all financing costs (2.4%, 4.8%, 5%) < Target Yield (6.67%), any mix is accretive","Most accretive: 100% cash (lowest cost at 2.4%), followed by debt (4.8%), then stock (5%)","Practical limits:","Cash: Limited by available cash reserves and minimum liquidity requirements","Debt: Constrained by leverage ratios, debt covenants, and lender willingness","Stock: Limited by shareholder dilution tolerance and potential control implications","Market conditions and company-specific factors determine optimal mix"],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Merger Model (M&A)","Advanced"]},{"id":"q-1428","t":"deal","l":"Advanced","s":90,"q":"A company achieves $100 million in cost synergies, with $50 million from reductions in operating costs and $50 million from reductions in Capex.\n\n\n\n\nAssuming a 25% tax rate, walk me through the changes in cash flow for Year 1.","k":["Operating Cost Synergies ($50M):","Pre-tax income increases by $50M.","After-tax benefit = $50M * (1 - 0.25) = $37.5M increase in NI.","Cash flow from operations increases by $37.5M.","CapEx Synergies ($50M):","CapEx decreases by $50M.","No immediate tax impact (Capex is not expensed).","Cash flow from investing improves by $50M (less outflow).","Total Cash Flow Impact:","Operating cash flow: +$37.5M.","Investing cash flow: +$50M.","Net cash flow increases by $87.5M."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1429","t":"deal","l":"Advanced","s":90,"q":"What are the effects of a Deferred Tax Liability (DTL) and a Deferred Tax Asset (DTA) in a merger model?","k":["Deferred Tax Liability (DTL)","Created when book income > taxable income (e.g., accelerated tax depreciation).","Represents future tax payments.","In M&A: Purchase accounting may create new DTLs from asset write-ups.","Reduces net assets acquired, increasing goodwill.","Deferred Tax Asset (DTA)","Created when taxable income > book income (e.g., NOLs, accruals).","Represents future tax benefits.","In M&A: Target's DTAs (like NOLs) may have limited value due to Section 382 limitations.","Valuation adjustment may be needed for unusable DTAs.","In merger models, DTLs and DTAs affect purchase price allocation, goodwill calculation, and pro forma tax rate."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1430","t":"deal","l":"Advanced","s":90,"q":"Company A (P/E of 10x) acquires Company B (P/E of 8x). The two companies are similarly sized and earn the same net income.\n\n\n\n\nIn an all-stock deal at no premium, answer the following:\n\n\n\nHow accretive is the transaction?\nWhat is the pro-forma P/E ratio?","k":["Part 1: Accretion","The deal is 11.1% accretive.","Assume both companies have $100 of NI (similar size).","A's Equity Value = $100 * 10x = $1,000.","B's Equity Value = $100 * 8x = $800.","Assume A has 100 shares at $10/share ($1,000 / 100 = $10).","A's standalone EPS = $100 NI / 100 shares = $1.00.","A issues $800 / $10 = 80 new shares to acquire B.","Pro-forma shares = 100 + 80 = 180 shares.","Pro-forma NI = $100 + $100 = $200.","Pro-forma EPS = $200 / 180 = $1.11.","Accretion = ($1.11 / $1.00) - 1 = 11.1%.","Part 2: Pro-Forma P/E","Answer: 9x","Pro-Forma Equity Value = $1,000 + $800 = $1,800.","Pro-Forma NI = $200.","Pro-Forma P/E = $1,800 / $200 = 9x."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1431","t":"deal","l":"Advanced","s":90,"q":"Company A acquires Company B in an all-stock deal with the following facts:\n\n\n\nCompany A P/E: 25x\nCompany A Shares Outstanding: 10\nCompany A Share Price: $25.00\nCompany A Net Income: $10\nCompany B Purchase Equity Value: $150\nCompany B Net Income: $10\n\n\n\nAssuming no cash or debt is used and tax rates are the same, how accretive is this deal?","k":["Answer: 25% accretive","Calculation:","A's Standalone EPS = $10 NI / 10 shares = $1.00.","Shares Issued = $150 / $25 share price = 6 shares.","Pro-Forma Shares = 10 + 6 = 16 shares.","Pro-Forma NI = $10 + $10 = $20.","Pro-Forma EPS = $20 / 16 = $1.25.","% Change = ($1.25 / $1.00) - 1 = 25% (accretive).","The deal is accretive because the pro-forma EPS ($1.25) is higher than the standalone EPS ($1.00)."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1432","t":"deal","l":"Advanced","s":90,"q":"Company A acquires Company B using 100% debt.\n\n\n\nCompany A P/E Multiple: 15x\nCompany B Purchase P/E Multiple: 10x\n\n\n\nAssuming a 40% tax rate, what is the breakeven interest rate on the debt to make the deal dilutive?","k":["Answer: 16.67%","The deal becomes dilutive when the after-tax cost of debt equals the earnings yield of the target.","Target Earnings Yield = 1 / 10x P/E = 10%","After-Tax Cost of Debt = Interest Rate * (1 - 40%)","Breakeven: Interest Rate * 0.6 = 10%","Interest Rate = 10% / 0.6 = 16.67%","At interest rates above 16.67%, the deal becomes dilutive. Below this rate, it is accretive."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1433","t":"deal","l":"Advanced","s":90,"q":"Company A acquires Company B in a 100% stock deal with the following facts:\n\n\n\nCompany A Equity Value: $1,000\nCompany A Net Income: $100\nCompany A Shares Outstanding: 100\nCompany B Purchase Equity Value: $2,000\nCompany B Net Income: $50\n\n\n\nAssuming a 40% tax rate, how much in pre-tax synergies are required for the deal to be accretive?","k":["Answer: $250 in pre-tax synergies are required for the deal to be break-even.","Calculation:","Determine Acquirer A's standalone EPS. Assuming A has 100 shares outstanding at a price of $10/share to get its $1,000 equity value, its EPS is $100 NI / 100 shares = $1.00.","Calculate shares issued: To purchase $2,000 of equity value, A issues $2,000 / $10 per share = 200 new shares.","Calculate pro-forma shares: 100 (A's old shares) + 200 (new shares) = 300 shares.","To be break-even, the pro-forma EPS must equal A's standalone EPS of $1.00.","Required pro-forma Net Income = Break-even EPS * Pro-Forma Shares = $1.00 * 300 = $300.","Current combined Net Income = $100 (A's NI) + $50 (B's NI) = $150.","Required after-tax synergies = $300 - $150 = $150.","Required pre-tax synergies = After-tax synergies / (1 - Tax Rate) = $150 / (1 - 40%) = $250."],"collection":"practice","topic":"Merger Model (M&A)","tags":["Reported in Unspecified Interview","Superday","Merger Model (M&A)","Advanced"]},{"id":"q-1434","t":"deal","l":"Basic","s":90,"q":"What is considered a good IRR and MoM (Multiple on Money) for a private equity firm?","k":["Target returns for PE firms:","IRR: 20-25%+ considered strong","Minimum acceptable IRR typically 15-20% (must exceed hurdle rate)","MoM: 2.0-3.0x+ over typical 5-7 year hold period","Top-quartile funds target 25%+ IRR and 3.0x+ MoM or higher","These targets reflect the need to compensate Limited Partners (LPs) for illiquidity, risk, and management fees. Actual returns vary by fund vintage, sector, and market conditions. Mega-funds may target slightly lower IRRs (15-20%) due to scale and deployment challenges."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Bank of America Interview","Financial Sponsors group, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1435","t":"deal","l":"Basic","s":90,"q":"Are IRRs for private equity firms currently trending up or down?","k":["IRRs are generally trending down.","Reasons:","Higher Interest Rates: Increased cost of debt financing reduces leverage returns.","Elevated Entry Multiples: Competition for deals has driven up purchase prices.","Exit Environment: Public market volatility and lower exit multiples compress returns.","Dry Powder Overhang: Record capital raised creates intense competition and valuation pressure.","Macro Headwinds: Slower economic growth, inflation concerns impact portfolio company performance.","While top-quartile funds still generate strong returns, industry average IRRs have declined from 2010s highs of 15-20%+ to low teens today."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Bank of America Interview","GIG, First round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1436","t":"deal","l":"Basic","s":90,"q":"Walk me through an LBO from the seller's perspective. Why would a seller consider selling to a financial sponsor?","k":["Reasons a seller would sell to a financial sponsor (PE firm):","Liquidity event: Founders or early investors can monetize their ownership, especially if the company is private with no public market for shares.","Management rollover: PE firms often allow management to retain 10-30% equity, giving them upside in a second bite of the apple at exit.","Operational partnership: Sponsors bring operational expertise, strategic resources, and a network to accelerate growth.","Maintain independence: Unlike selling to a strategic acquirer, the company often continues operating as a standalone entity, preserving brand, culture, and jobs.","Competitive valuation: In a well-run auction process, PE firms can pay competitive prices, especially with access to cheap debt financing.","Succession planning: For founder-led businesses, a PE sale provides a transition path without an outright merger or loss of identity."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Bank of America Interview","SA 2025, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1437","t":"deal","l":"Basic","s":90,"q":"How do you assess credit risk for a company?","k":["Assess credit risk across several dimensions:","Leverage ratios: Debt/EBITDA, Net Debt/EBITDA -- higher leverage means higher default risk.","Coverage ratios: EBITDA/Interest Expense (interest coverage), (EBITDA - CapEx)/Interest -- measures ability to service debt.","Free cash flow generation: Consistent, positive FCF indicates the company can meet obligations.","Liquidity: Cash on hand, revolver availability, and near-term maturities.","Business quality: Revenue predictability, customer concentration, competitive positioning, and cyclicality.","Debt maturity profile: Concentration of near-term maturities creates refinancing risk.","Credit ratings: Moody's, S&P, and Fitch ratings provide a benchmark for relative credit quality."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Bank of America Interview","SA 2026, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1438","t":"deal","l":"Basic","s":90,"q":"How do you calculate the price a PE firm wants to pay for an LBO candidate?","k":["Back‑solve entry valuation that delivers target IRR.","Project cash flows, leverage, and exit multiple","Model debt pay‑down and exit equity","Iterate purchase price until IRR meets hurdle (e.g., 20%)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Barclays Interview","Coverage/M&A group","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1439","t":"deal","l":"Basic","s":90,"q":"Part 1: What are the principal variables in an LBO?\n\n\n\n\nPart 2: What makes a company a good LBO target?","k":["Part 1: Principal LBO Variables","Entry multiple (purchase price)","Leverage level (debt/equity split)","EBITDA growth rate over the hold period","Free cash flow generation (for debt paydown)","Exit multiple","Hold period","Interest rate on debt","Part 2: Good LBO Characteristics","Stable, predictable cash flows to service debt.","Strong EBITDA margins and low CapEx (high FCF conversion).","Defensible market position with recurring revenue.","Opportunities for operational improvement or growth.","Low cyclicality and limited customer concentration.","Strong management team or ability to recruit one."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Barclays Interview","SA 2025","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1440","t":"deal","l":"Basic","s":90,"q":"What is a Payment-in-Kind (PIK) bond or PIK interest?","k":["Debt whose coupon is paid by issuing additional principal instead of cash until maturity or a toggle date.","Increases outstanding balance each period.","Appeals to sponsors seeking cash conservation.","Investors demand higher yields for compounding credit risk."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Centerview Partners Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1441","t":"deal","l":"Basic","s":90,"q":"A private equity firm is considering an exit for one of its portfolio companies. Compare and contrast the three primary exit options: an IPO, a sale to a strategic acquirer, and a sale to another financial sponsor. How do market dynamics influence this decision?","k":["IPO","Pros: Liquidity, brand recognition, currency for acquisitions, partial exit flexibility.","Cons: Market volatility risk, lock-up periods, ongoing disclosure requirements, underpricing.","Market dynamics: Requires strong equity markets and investor appetite.","Sale to Strategic Acquirer","Pros: Highest valuation potential (synergies), certainty of exit, no ongoing involvement.","Cons: Integration complexity, regulatory scrutiny, limited buyer universe.","Market dynamics: Attractive when strategics are pursuing consolidation.","Sale to Financial Sponsor","Pros: Quick execution, certain pricing, management continuity.","Cons: Lower valuation (no synergies), multiple compression, competitive process.","Market dynamics: Favorable when debt markets are accommodative and PE dry powder is high.","Decision factors include company size, growth profile, market conditions, and sponsor timeline."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Credit Suisse Interview","Chicago Office","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1442","t":"deal","l":"Basic","s":90,"q":"What are the key differences between a loan and a bond?","k":["Key differences:","Negotiation: Loans are privately negotiated with lenders; bonds are issued to public/institutional markets.","Flexibility: Loans are more flexible (can be amended); bonds have fixed terms in indenture.","Seniority: Loans typically senior secured; bonds often senior unsecured or subordinated.","Amortization: Loans often require periodic principal repayment; bonds typically bullet maturity.","Interest Rate: Loans usually floating rate; bonds typically fixed rate.","Covenants: Loans have stricter maintenance covenants; bonds have lighter incurrence covenants.","Documentation: Loans have credit agreements; bonds have indentures."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Credit Suisse Interview","LFO group, First round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1443","t":"deal","l":"Basic","s":90,"q":"What key credit metrics and qualitative factors would you analyze to assess a company's creditworthiness?","k":["Key Credit Metrics:","Leverage Ratios: Total Debt/EBITDA, Net Debt/EBITDA.","Coverage Ratios: EBITDA/Interest Expense, EBIT/Interest Expense.","FCF/Debt: Ability to delever through cash generation.","Liquidity: Current Ratio, Cash on Hand.","Qualitative Factors:","Business Model: Stability and predictability of cash flows.","Industry Dynamics: Cyclicality, competitive intensity.","Management Quality: Track record and financial discipline.","Asset Quality: Collateral value and liquidation potential.","Covenants: Flexibility and cushion to financial covenants.","Market Position: Competitive advantages and market share."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Credit Suisse Interview","LFO group, First round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1444","t":"deal","l":"Basic","s":90,"q":"What is a financial buyer? Why do they use debt? What are the benefits of using leverage in an LBO?","k":["Financial Buyer","A financial buyer (typically a private equity firm) acquires companies primarily to generate investment returns over a defined holding period (3-7 years), as opposed to a strategic buyer that acquires for operational synergies.","Why Use Debt","Amplifies equity returns: With leverage, the sponsor invests less equity for the same enterprise value. If the investment performs well, the return on equity is magnified.","Tax shield: Interest payments are tax-deductible, reducing the company's tax burden and increasing after-tax cash flow.","Debt is cheaper than equity: The after-tax cost of debt is typically lower than the cost of equity.","Benefits of Leverage","Higher IRR and MOIC on the equity investment.","Forced discipline: Mandatory debt service payments force management to operate efficiently and prioritize cash flow.","Preserves dry powder: Less equity per deal allows the sponsor to diversify across more investments."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in DC Advisory Interview","Generalist group, New York Office, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1445","t":"deal","l":"Basic","s":90,"q":"Walk me through a basic LBO model.","k":["Key steps in an LBO model:","Assumptions: Purchase price (entry multiple), Debt/Equity mix, Interest rates, Operating forecasts.","Sources & Uses: Outline funding sources (Debt, Sponsor Equity) and uses (Equity Purchase, Fees, Debt Refinancing). Determines required Sponsor Equity.","Adjust BS: Update Balance Sheet for new Debt & Equity, create Goodwill.","Project Statements: Forecast IS, BS, CFS. Model debt paydown based on FCF generation.","Exit & Returns: Assume exit year and multiple, calculate Exit EV, subtract Net Debt to get Equity Proceeds. Calculate IRR and MOIC based on initial Sponsor Equity."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Evercore Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1446","t":"deal","l":"Basic","s":90,"q":"How can a PE sponsor reduce the upfront equity needed for an LBO?","k":["Three ways to reduce upfront equity:","Increase leverage.","Reduce the purchase price.","Co-invest with another PE firm."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Evercore Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1447","t":"deal","l":"Basic","s":90,"q":"If a company has $150 million of debt and $50 million of EBITDA, what is its leverage ratio?","k":["Leverage ratio is Debt / EBITDA = 150 / 50 = 3x."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Evercore Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1448","t":"deal","l":"Basic","s":90,"q":"If a company has $150 million of debt, $50 million of cash, and $50 million of EBITDA, what is its net leverage ratio?\n\n\n\n\nIs that level concerning?\n\n\n\n\nFollow-up: The same company has a $50 million undrawn revolver. What is its total liquidity, and do you find that comfortable?","k":["Part 1:","Net leverage = (Debt - Cash) / EBITDA = (150 - 50) / 50 = 2x.","Whether 2x is concerning depends on industry norms, stability of cashflow, and growth prospects. For many companies, 2x net leverage is moderate.","Part 2:","Total liquidity = Cash ($50 million) + undrawn revolver ($50 million) = $100 million.","Whether that’s comfortable depends on operational needs, upcoming maturities, and CapEx. $100 million might be sufficient for a moderate operation."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Evercore Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1449","t":"deal","l":"Basic","s":90,"q":"A company has $150 million of debt at 10% interest, $50 million of EBITDA, $10 million of cash taxes, $20 million of capex, and a $10 million increase in working capital.\n\n\n\n\nWhat is its annual cash burn?","k":["Answer: $5M per year","EBITDA = $50M. Subtract interest ($15M), taxes ($10M), capex ($20M), and working capital ($10M).","$50M - 15M - 10M - 20M - 10M = negative $5M."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Evercore Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1450","t":"deal","l":"Basic","s":90,"q":"Interest coverage is 5x.\n\n\n\n\nLeverage ratio is 5x.\n\n\n\n\nWhat is the implied interest rate on debt?","k":["Answer: 4%","Interest Coverage Ratio = EBIT / Interest Expense = 5x → EBIT = 5x Interest Expense.","Assume EBIT = EBITDA.","Leverage Ratio = Debt / EBITDA → 5x = Debt / (5x Interest Expense)","Debt = 25x Interest Expense","Interest Expense / Debt = 1 / 25 = 4%"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Evercore Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1451","t":"deal","l":"Basic","s":90,"q":"Both DCF and LBO are calculated using the same projections. Why does one provide the floor valuation and the other possibly the highest value?","k":["An LBO valuation is driven by the required IRR of a financial sponsor, which tends to be conservative and results in a lower “floor” price they’d pay.","A DCF can produce a higher figure if the business’s cash flows and terminal value are significant. The sponsor’s cost of capital in an LBO is typically higher than the company’s WACC in a DCF, driving the DCF valuation higher."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Goldman Sachs Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1452","t":"deal","l":"Basic","s":90,"q":"Two companies, same EV, but one is 50% debt / 50% equity, and the other is 100% equity. As a PE firm, which would you acquire?","k":["It should not make a difference. In a leveraged buyout, the acquirer must fund the entire purchase of the company's enterprise value.","The existing capital structure (both debt and equity) is almost always completely replaced by a new capital structure consisting of the PE firm's equity contribution and new debt tranches. Therefore, whether the company starts with 0% debt or 50% debt, the PE firm still needs to raise capital to cover the full enterprise value and will apply its own desired leverage level post-transaction."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Goldman Sachs Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1453","t":"deal","l":"Basic","s":90,"q":"What happens if depreciation increases by $10 in an LBO?","k":["Returns improve slightly due to higher free cash flow available for debt paydown.","The logic is the same as in a DCF -- higher depreciation creates a tax shield. Assuming a 25% tax rate, free cash flow increases by $2.50 ($10 x 25%). This additional cash can be used to pay down more debt over the hold period, increasing equity value at exit and boosting MOIC and IRR.","Note: Depreciation does not affect EBITDA (it is added back), so the exit enterprise value (based on EBITDA x exit multiple) is unchanged. The benefit flows entirely through increased deleveraging."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Goldman Sachs Interview","SA 2026, First round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1454","t":"deal","l":"Basic","s":90,"q":"What information would you ask for if you were told to build an LBO model?","k":["Purchase price and entry multiple (EV/EBITDA)","Historical and projected financials: revenue, EBITDA, CapEx, D&A, changes in NWC","Debt structure: amount, interest rates, amortization schedules, covenants for each tranche","Transaction fees and financing fees","Tax rate","Exit assumptions: holding period, exit multiple","Management rollover or co-invest (if any)","Target return thresholds (IRR, MOIC)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Goldman Sachs Interview","SA 2027, New York Office, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1455","t":"deal","l":"Basic","s":90,"q":"In the context of a leveraged buyout, why does leverage magnify returns?","k":["Leverage magnifies returns because the PE sponsor only contributes a fraction of the purchase price as equity, while using debt for the rest. Any increase in enterprise value accrues entirely to equity holders (since debt claims are fixed), amplifying the return on the smaller equity base.","For example, if you buy a company for $1B using $400M equity and $600M debt, and the company's value grows to $1.2B, the equity value is now $600M ($1.2B - $600M debt). That is a 50% return on equity ($200M gain / $400M invested), even though the enterprise value only grew 20%.","Additionally, debt is repaid over the holding period using the company's cash flows, further increasing equity value without additional investment. The flip side is that leverage also magnifies losses -- if the company's value declines, equity is wiped out first."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1456","t":"deal","l":"Basic","s":90,"q":"Walk me through what an LBO is and how returns are calculated.\n\n\n\n\nAlso, what qualities make an ideal LBO candidate?","k":["LBO:","An LBO is the purchase of a company using mostly debt, with debt service funded by the target’s cash flow.","Returns:","Returns on LBO (Leveraged Buyout) investments are typically measured using two key metrics: Internal Rate of Return (IRR) and Multiple on Invested Capital (MOIC).","IRR represents the annualized return on investment, while MOIC indicates the total return relative to the initial investment.","Additionally, returns can be analyzed by breaking down value creation into its components: EBITDA growth, multiple expansion, and debt paydown.","Ideal candidate:","Stable, predictable cash flow","Low capex and working‑capital needs","Strong asset base for collateral","Opportunity for cost cuts or multiple expansion","Capable management team"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Greenhill & Co. Interview","SA 2024, Industrials M&A, Chicago office","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1457","t":"deal","l":"Basic","s":90,"q":"A company's IRR for an LBO candidate increases in the model.\n\n\n\n\nWhat does that tell you about the price of the company being acquired?","k":["Entry equity price fell (or exit price rose) relative to projected cash flows.","Lower initial outlay boosts the multiple‑on‑money and compounds into a higher IRR."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Greenhill & Co. Interview","SA 2024, Industrials M&A, Chicago office","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1458","t":"deal","l":"Basic","s":90,"q":"What is Payment-in-Kind (PIK) interest, and how does it differ from cash interest on a loan?","k":["PIK interest is paid by issuing additional debt rather than cash.","Key differences:","Cash interest: Paid in cash, reduces company cash flow.","PIK interest: Added to principal balance, no immediate cash outflow.","PIK preserves liquidity but increases total debt burden.","PIK typically carries higher interest rates due to increased risk.","Common in leveraged buyouts and distressed situations."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Greenhill & Co. Interview","M&A group, First round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1459","t":"deal","l":"Basic","s":90,"q":"What is a dividend recap, who benefits from it, and why?\n\n\n\n\nFollow-up: In what situations would a dividend recap not benefit the sponsor?","k":["Part 1:","A dividend recap is when a company raises new debt (and thus increases leverage) specifically to pay a special dividend to its private equity owners.","The primary beneficiary of a dividend recap is the PE firm, as the company takes on new debt to issue the sponsor a special dividend.","This allows the sponsor to recover part of its initial equity investment early, reducing invested capital and thus boosting returns (alongside leverage).","Part 2:","A dividend recap won't benefit the sponsor if the company's performance declines or the investment is already expected to yield a negative return.","Increased leverage magnifies returns, meaning poor outcomes become even worse when additional debt is taken on."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Guggenheim Partners Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1460","t":"deal","l":"Basic","s":90,"q":"What are the differences between a leveraged loan and a high-yield bond?","k":["Leveraged loans are senior, secured, floating‑rate, and amortizing; high‑yield bonds are usually unsecured or subordinated, fixed‑rate, and bullet‑maturity.","Collateral: loans secured; bonds generally not","Coupon: loans L+spread; bonds fixed","Repayment: loans amortize; bonds repay at maturity","Covenants: loans maintenance; bonds incurrence","Call protection: bonds have premiums; loans prepayable anytime"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Guggenheim Partners Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1461","t":"deal","l":"Basic","s":90,"q":"In an LBO, would you prefer payments each year or one lump sum at the end?","k":["Annual payments.","Earlier cash flows boost IRR because you redeploy or distribute money sooner; the time‑value of money means a dollar today is worth more than a dollar five years from now.","A bullet repayment or dividend only at exit drags IRR even if MOIC is unchanged."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Guggenheim Partners Interview","SA 2025, New York Office, First round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1462","t":"deal","l":"Basic","s":90,"q":"When does a dividend recapitalization typically occur?\n\n\n\n\nSelect the most likely scenario(s):\n\nWhen a company is performing very well.\nWhen a company is performing poorly, and owners want to extract capital.","k":["Scenario 1: When a company is performing very well.","Dividend recaps typically occur when a portfolio company is performing strongly and generating robust cash flows, allowing it to take on additional debt to pay a special dividend to the PE sponsor.","Strong performance provides debt capacity and lender confidence. A poorly performing company would struggle to raise new debt and lenders would be unwilling to finance a dividend to equity holders."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Guggenheim Partners Interview","New York office","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1463","t":"deal","l":"Basic","s":90,"q":"What is PIK debt?","k":["PIK (Payment-in-Kind) debt is debt where interest is not paid in cash but instead accrues and is added to the principal balance each period. For example, $100 of PIK debt at 10% grows to $110 after one year with no cash outflow.","PIK interest is a non-cash expense on the IS and gets added back on the SCF. It is common in LBOs because it preserves cash flow during early years. The trade-off is a higher rate and growing indebtedness over time."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Guggenheim Partners Interview","SA 2027, Business Services group, Atlanta Office, Phone screen","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1464","t":"deal","l":"Basic","s":90,"q":"Why would a company choose to undergo a leveraged buyout (LBO)?","k":["A company does not typically \"choose\" an LBO; rather, the company's shareholders or board accept a buyout offer. Reasons include:","Attractive premium to current share price, providing immediate value realization for shareholders.","Going-private to escape short-term public market pressures and focus on long-term value creation.","Access to PE operational expertise, strategic guidance, and industry connections.","Founder/family succession: Provides a liquidity event while maintaining some ongoing involvement.","Undervalued public company: Management or the board believes the company is undervalued by public markets."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Guggenheim Partners Interview","SA 2027, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1465","t":"deal","l":"Basic","s":90,"q":"If EBITDA does not increase in 5 years, nor do EBITDA multiples, does a financial sponsor still make money in an LBO?","k":["Potentially, yes. Even if EBITDA and multiples remain constant, the sponsor can still generate returns by paying down debt over time. The principal reduction increases the sponsor’s equity stake in the company, boosting the equity value at exit.","However, if there’s no EBITDA growth or multiple expansion, returns may be lower than in a scenario where the business improves operationally."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in J.P. Morgan Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1466","t":"deal","l":"Basic","s":90,"q":"Over a 5-year hold period in an LBO, how does aggressively paying down debt versus making minimum payments affect the investment's returns?","k":["Aggressive debt paydown generally increases returns, but the impact depends on exit multiple expansion and alternative uses of cash.","Benefits of aggressive paydown:","Higher exit equity value as net debt is lower at exit, directly increasing proceeds to the sponsor.","Reduced interest expense improves cash flow over time.","Lower leverage reduces risk and may support higher exit multiples.","Potential trade-offs:","If EBITDA growth generates higher returns than debt paydown (multiplied by exit multiple), reinvesting in the business may be better.","Minimal paydown preserves optionality for dividend recaps or growth investments.","Generally, aggressive paydown is preferred when growth opportunities are limited and deleveraging supports exit valuation."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in J.P. Morgan Interview","New York office","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1467","t":"deal","l":"Basic","s":90,"q":"How do you calculate Free Cash Flow in an LBO model?","k":["In an LBO model, Free Cash Flow represents the cash available for debt repayment after all operating expenses, taxes, and reinvestment needs:","Start with EBITDA","Less: D&A = EBIT","Less: Interest Expense (on all tranches of debt)","Less: Taxes (on EBT, reflecting the interest tax shield)","= Net Income","Plus: D&A (add back non-cash charge)","Less: CapEx","Less: Increase in Net Working Capital","Less: Mandatory Debt Amortization (if not counted separately)","= Free Cash Flow Available for Debt Repayment","This FCF is levered (includes interest expense) because the LBO model needs to track how much cash is available after debt service to pay down additional debt. This is different from the UFCF used in a DCF."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in J.P. Morgan Interview","SA 2027, Hirevue","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1468","t":"deal","l":"Basic","s":90,"q":"Part 1: Walk me through a leveraged buyout (LBO).\n\n\n\n\nPart 2: How do you increase returns in an LBO?","k":["Part 1: LBO Walk-Through","Determine the purchase price (typically EV/EBITDA multiple).","Structure the financing: ~60-80% debt, ~20-40% sponsor equity.","Over a 5-7 year hold period, use the company's free cash flow to service and pay down debt.","At exit, sell the company and the remaining equity value goes to the sponsor.","Part 2: Increase LBO Returns","Increase leverage: More debt means less equity invested, boosting returns (but increases risk).","Grow EBITDA: Revenue growth and margin expansion increase exit enterprise value.","Multiple expansion: Exit at a higher multiple than entry.","Accelerate debt paydown: Faster deleveraging increases equity value at exit.","Reduce purchase price: Lower entry price means less equity needed and a higher MOIC."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1469","t":"deal","l":"Basic","s":90,"q":"What are some levers to generate a higher IRR in an LBO?","k":["Main IRR drivers:","Lower purchase price / higher entry leverage","Faster EBITDA growth","Margin expansion via cost cuts","Quicker debt pay‑down","Sell at a higher exit multiple","Dividend recap or partial exit to return capital early"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Jefferies Interview","SA 2026","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1470","t":"deal","l":"Basic","s":90,"q":"Explain a leveraged buyout (LBO) as if you were explaining it to a grandparent.","k":["An LBO is like buying a house with a mortgage. An investment firm buys an entire company, but instead of paying all cash, they put down a small portion of their own money and borrow the rest from banks.","The company they buy then uses its own profits to pay off that borrowed money over time, just like you would use your salary to pay your mortgage. After a few years, the investment firm sells the company. Since most of the debt has been paid off, the firm keeps the profit, which is much larger than the small amount they originally put in."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Jefferies Interview","SA 2027, Aerospace & Defense group, Charlotte Office, First round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1471","t":"deal","l":"Basic","s":90,"q":"How does the usage of an LBO analysis differ between private equity firms and investment banks?","k":["PE firms use an LBO model as a decision-making tool to determine the maximum price they can pay while achieving their target return (typically 20%+ IRR). It is the core of their investment thesis.","Investment banks use an LBO analysis as one valuation methodology alongside comps, precedent transactions, and DCFs. It establishes a floor valuation representing what financial buyers can afford, and is presented in the football field chart."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Jefferies Interview","SA 2026, First round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1472","t":"deal","l":"Basic","s":90,"q":"EBITDA is $100. What debt level can this company take in an LBO? What other information do you need?","k":["Typical leverage might be 4–6x EBITDA, so $400–$600 million. But to be sure, you need information about the company’s free cash flow, industry norms, interest coverage, and the lender’s appetite.","Also, sponsor experience and market conditions matter. You might check DSCR (debt service coverage ratio) or interest coverage ratio to ensure the company can handle interest payments."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Lazard Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1473","t":"deal","l":"Basic","s":90,"q":"You are working on a valuation for a company and your manager tells you to include an LBO analysis. Why would you include it in the valuation?","k":["An LBO analysis is included because it establishes a valuation floor: the maximum price a financial buyer (PE firm) can pay while achieving a target return. This is useful for several reasons:","It provides a lower bound on the valuation range, complementing the higher values from comps, precedent transactions, and DCFs.","In a sell-side M&A process, it helps set expectations for what financial sponsors can bid.","If the LBO price exceeds the current share price, it may indicate the company is undervalued and could be a take-private candidate.","It provides a different perspective since it is based on achievable returns rather than market multiples or projections."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Lazard Interview","SA 2025, SF Office, First round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1474","t":"deal","l":"Basic","s":90,"q":"What is an LBO, intuitively?","k":["A purchase financed mostly with debt where the target’s cash flows service that debt.","Equity investors aim for outsized IRR by leveraging returns and exiting once debt is repaid and value has grown.","The common analogy is buying a house with a mortgage.","You put down a small down payment (equity) and borrow the rest (debt).","Then, you use the rental income from the house (cash flows) to pay off the loan.","If the house value goes up and you sell it later, your return on the small down payment is much higher — because you used leverage."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Leerink Partners Interview","SA 2026, Healthcare Services group, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1475","t":"deal","l":"Basic","s":90,"q":"What are the considerations from the seller's perspective in an LBO transaction?","k":["Valuation and proceeds: The seller wants to maximize the total purchase price. They will compare the PE firm's offer to strategic buyer bids and standalone value.","Deal certainty: PE firms typically offer high certainty of close because financing is pre-committed. Sellers value this, especially in volatile markets.","Management retention: PE buyers usually retain the existing management team and offer equity rollover or incentive packages. This is attractive for founder-owners who want to stay involved.","Equity rollover: The seller may be asked to roll a portion of their equity into the new entity (typically 10-30%), giving them a \"second bite of the apple\" at exit.","Post-close operations: PE firms generally pursue operational improvements and may push for cost cuts, headcount reductions, or add-on acquisitions. Sellers should understand the buyer's value creation plan.","Timeline: PE buyers often have strict fund deployment timelines, which can accelerate or constrain deal timing.","Reps & warranties: The seller should understand indemnification obligations and the potential for post-close clawbacks."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Lincoln International Interview","SA 2025, SF Office, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1476","t":"deal","l":"Basic","s":90,"q":"What are the key considerations when evaluating financial sponsors on the sell side of an M&A process?","k":["Price and valuation: What multiple and total consideration is the sponsor willing to pay? How does it compare to other bids?","Certainty of close: Does the sponsor have committed financing? How likely is the deal to close without retrading on price?","Speed of execution: Can the sponsor close quickly? Is their diligence process efficient?","Track record: Has the sponsor successfully completed similar transactions? Do they have relevant sector expertise?","Management rollover: What terms are offered to management? A sponsor that aligns with management's interests may be preferred.","Portfolio company conflicts: Does the sponsor own competing businesses that could create antitrust or conflict issues?","Reputation and relationship: How is the sponsor perceived in the market? Will they be a good steward of the business and its employees?","Financing structure: How much leverage will the sponsor put on the company? Excessive leverage could endanger the business."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Lincoln International Interview","SA 2025, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1477","t":"deal","l":"Basic","s":90,"q":"How would you rank the factors associated with a good LBO candidate?","k":["From most to least important:","Strong, predictable cash flows: The company must generate sufficient free cash flow to service debt. This is the single most critical factor.","Low capital expenditure requirements: Low CapEx means more FCF is available for debt repayment.","Defensible market position: Strong competitive moat, high barriers to entry, and recurring revenue reduce downside risk.","Operational improvement opportunities: Room for margin expansion through cost cuts, pricing optimization, or efficiency gains drives EBITDA growth.","Hard asset base: Tangible assets provide collateral for secured debt, enabling higher leverage at lower borrowing costs.","Experienced management team: Capable operators who can execute the value creation plan under a leveraged capital structure.","Clear exit path: Viable exit options (IPO, strategic sale, secondary buyout) within the target hold period."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Lincoln International Interview","SA 2025, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1478","t":"deal","l":"Basic","s":90,"q":"What is the difference between a syndicated loan and a private credit facility?","k":["Origination: A syndicated loan is arranged by one or more lead banks and then distributed (syndicated) to a group of institutional investors. A private credit facility is provided by a single direct lender or a small club of non-bank lenders (e.g., private credit funds).","Speed and certainty: Private credit offers faster execution and greater certainty of close, since there is no syndication process or market flex risk.","Pricing: Private credit typically carries a higher spread (premium) to compensate for illiquidity and concentration risk. Syndicated loans benefit from competitive pricing driven by broader investor demand.","Size: Syndicated loans can be very large ($1B+). Private credit has grown significantly but individual facilities are often smaller, though unitranche deals can now exceed $5B.","Flexibility: Private credit lenders often offer more flexible terms and structures. Syndicated loans are more standardized with market-driven documentation.","Covenants: Private credit often includes maintenance covenants. Syndicated TLBs are increasingly covenant-lite (incurrence only).","Relationship: Private credit involves a direct, ongoing lender relationship. Syndicated loan holders may change as positions are traded in the secondary market."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Mizuho Interview","SA 2027, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1479","t":"deal","l":"Basic","s":90,"q":"What are the primary ways a private equity firm can exit its investment in an LBO?","k":["Strategic sale, secondary sale to another sponsor, IPO, or dividend recapitalization."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Moelis & Co. Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1480","t":"deal","l":"Basic","s":90,"q":"Conceptually, what is debt, and why do firms utilize different types of debt in their capital structures?","k":["Debt is a contractual obligation to repay borrowed funds with interest over time. It provides tax-deductible financing and allows owners to maintain control while leveraging returns.","Firms use different debt types to optimize their capital structure:","Cost vs. flexibility trade-off: Senior secured debt is cheaper but restrictive; junior/subordinated debt is more expensive but flexible.","Maturity matching: Short-term debt for working capital, long-term for fixed assets.","Covenant structure: Bank debt has tight covenants; bonds offer more operational freedom.","Market access: Different investor bases (banks, institutional, high yield) prefer different instruments.","Refinancing risk: Staggered maturities avoid large one-time repayments."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Moelis & Co. Interview","Chicago office","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1481","t":"deal","l":"Basic","s":90,"q":"If the IRR in an LBO is 12%, what actions can a Private Equity firm take to increase its return?","k":["Actions to increase IRR:","Increase Leverage: Higher debt magnifies equity returns (but increases risk).","Operational Improvements: Drive revenue growth, improve margins, reduce costs.","Multiple Expansion: Exit at higher multiple than entry (market timing, positioning).","Faster Exit: Shorter holding period accelerates cash-on-cash returns.","Lower Purchase Price: Negotiate better entry valuation.","Dividend Recaps: Extract cash early through debt-financed dividends.","Add-on Acquisitions: Build scale and synergies to enhance value."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Moelis & Co. Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1482","t":"deal","l":"Basic","s":90,"q":"What are the main differences between bank debt and high-yield debt?\n\n\n\n\nFollow-up 1: Which would an early-stage company with substantial capex requirements prefer?","k":["Main Differences","Bank Debt: Senior secured, floating rate (SOFR + spread), amortizing, stricter covenants, lower cost.","High-Yield Debt: Unsecured or junior, fixed rate, bullet maturity, looser covenants, higher cost.","Bank debt typically used for LBOs and stable businesses; high-yield for growth companies or refinancing.","Follow-up 1","High-yield debt.","Early-stage companies with heavy capex need flexible capital. High-yield bonds offer:","No mandatory amortization (bullet payment at maturity).","Looser covenants, allowing flexibility for capex spending.","No collateral requirements in many cases.","Bank debt's amortization and maintenance covenants would constrain cash flow needed for growth investments."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Moelis & Co. Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1483","t":"deal","l":"Basic","s":90,"q":"Where would you use the (EBITDA - CapEx) / Interest Expense ratio, and what does it tell you?","k":["This ratio is a Fixed Charge Coverage Ratio (or a variant of the debt service coverage ratio). It measures a company's ability to service its interest payments from its cash-generating capacity after accounting for necessary capital expenditures.","Used in: Credit analysis, leveraged finance, LBO models, and by lenders when setting debt covenants.","EBITDA - CapEx approximates the cash flow available to pay interest after maintaining the asset base.","A ratio above 1.0x means the company generates enough cash after CapEx to cover its interest payments. Below 1.0x signals potential distress.","Lenders typically require 1.5-2.0x+ as a covenant level, depending on industry and risk profile.","This ratio is more conservative than EBITDA / Interest Expense because it deducts CapEx, which is a real cash outflow that must be funded before debt service."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Piper Sandler Interview","SA 2026, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1484","t":"deal","l":"Basic","s":90,"q":"Walk through a dividend recapitalization and explain why it can be beneficial.","k":["In a dividend recap, the company raises additional debt and pays out the proceeds to its owners (PE firm) as a dividend. It doesn’t change ownership but increases leverage.","It’s beneficial for PE sponsors looking to “take money off the table” before exit, especially if the company’s cash flows can handle higher debt. It returns capital to investors sooner without selling the business."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Raine Group Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1485","t":"deal","l":"Basic","s":90,"q":"If you could ask a CFO for only one input to build an LBO model, what would it be and why?","k":["Probably the expected free cash flow (or breakouts of EBITDA minus capex, working capital, etc.). That drives debt paydown and the IRR outcome.","You want the best estimate of how much cash can be generated to repay debt and eventually deliver returns."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Rothschild Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1486","t":"deal","l":"Basic","s":90,"q":"How do you figure out how much debt should be used in an LBO?","k":["The amount of debt in an LBO is determined by the company's ability to service and repay it, constrained by lender requirements:","Leverage ratios: Total Debt/EBITDA typically ranges from 4-6x for most LBOs. Senior debt is usually 3-4x, with subordinated debt adding 1-2x.","Interest coverage: EBITDA/Interest Expense must meet minimum thresholds (typically 2.0x+).","Cash flow coverage: The company must generate enough FCF to service mandatory debt payments (interest + required amortization).","Lender appetite: Market conditions, credit markets, and the specific company's risk profile determine what lenders are willing to provide.","Debt capacity analysis: Model the company's projected cash flows under downside scenarios to ensure it can service debt even if performance deteriorates.","In practice, the PE sponsor works with investment banks to determine the maximum debt quantum that lenders will commit to, then sizes equity as the residual."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Solomon Partners Interview","SA 2027, Generalist group, New York Office, Second round","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1487","t":"deal","l":"Basic","s":90,"q":"Why and when would bankers use an LBO analysis?","k":["Why:","An LBO analysis determines the maximum price a financial sponsor (PE firm) would pay for a company based on a target IRR (typically 20-25%). This sets a floor valuation in sell-side processes.","It is also used to assess how much leverage a company can support, which informs financing structures.","When:","Sell-side M&A: To gauge potential PE interest and set price expectations. If PE buyers are likely bidders, the LBO price becomes the floor.","Buy-side M&A for PE: To determine the bid price and structure the financing.","Leveraged finance: To assess debt capacity and structure debt tranches.","Fairness opinions: As one of several valuation methodologies to support the opinion.","Restructuring: To evaluate whether a company's capital structure is sustainable under leveraged scenarios."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in TD Securities Interview","SA 2027","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1488","t":"deal","l":"Basic","s":90,"q":"Walk me through the mechanics of an LBO and why a PE firm would do one.","k":["Mechanics:","Acquire company using debt + equity (60‑80 % leverage typical).","Use target cash flow to service debt principal and interest.","Exit via sale or IPO 3‑7 years later, repaying remaining debt.","Rationale:","Debt amplifies equity returns via leverage.","Control allows operational improvements and multiple expansion.","Disciplined entry valuation due to IRR hurdle provides downside protection."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in UBS Interview","SA 2026, New York office, Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1489","t":"deal","l":"Basic","s":90,"q":"How do you determine the optimal mix of loans and bonds in a company's capital structure?","k":["Consider these factors:","Cost: Loans typically cheaper (secured, senior, floating) vs. bonds (unsecured, fixed, higher yield).","Flexibility: Loans have maintenance covenants and amortization; bonds offer more operational flexibility.","Market Access: Loan market capacity, bond investor appetite, and current spreads.","Company Needs: Cash flow stability, refinancing risk tolerance, interest rate view.","Maturity Profile: Stagger maturities to manage refinancing risk.","Covenants: Balance restrictiveness with cost savings.","Typical LBO structure: Senior secured loans for lowest-cost financing, supplemented by bonds for additional capacity and flexibility."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1490","t":"deal","l":"Basic","s":90,"q":"What are the key differences between high-yield bonds and term loans, and who are the typical investors for each instrument?","k":["High-Yield Bonds","Fixed interest rate, bullet maturity (no amortization).","Incurrence covenants (less restrictive).","Unsecured or subordinated.","Investors: Mutual funds, insurance companies, pension funds, hedge funds.","Term Loans","Floating interest rate (SOFR + spread), amortizing.","Maintenance covenants (more restrictive).","Secured, senior in capital structure.","Investors: CLOs, banks, institutional loan funds, hedge funds."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1491","t":"deal","l":"Basic","s":90,"q":"What is call protection on a bond?","k":["Call protection prevents the issuer from redeeming (calling) bonds before a specified date, protecting investors from reinvestment risk.","Common structures:","Hard non-call period: Bonds cannot be redeemed at all (e.g., first 3 years).","Call premium: After non-call period, issuer can redeem but pays premium above par (declining over time).","Make-whole provision: Issuer can call early but must compensate investors for lost future interest.","Benefits investors by ensuring yield for minimum period; costs issuers by limiting refinancing flexibility."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1492","t":"deal","l":"Basic","s":90,"q":"If you lend $100 at 8% interest and simultaneously borrow $50 at 4% interest, what is your net cash return and percentage return on your equity invested?\n\n\n\n\nWhat type of transaction does this resemble?","k":["Net cash return: $6. Percentage return on equity: 12%.","Calculation:","Interest earned on lending: $100 * 8% = $8","Interest paid on borrowing: $50 * 4% = $2","Net cash return: $8 - $2 = $6","Equity invested: $100 - $50 = $50","Return on equity: $6 / $50 = 12%","This resembles a leveraged buyout (LBO), where debt financing is used to amplify returns on equity invested."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1493","t":"deal","l":"Basic","s":90,"q":"If a private equity firm buys a company for $1 billion and sells it 5 years later for the same price, is it possible for them to have made a positive return?","k":["Yes, through debt paydown and interim distributions.","Mechanisms for positive returns:","Debt Paydown: Company uses FCF to repay debt, increasing equity value at exit","Dividend Recaps: PE firm takes special dividends during hold period","Management Fees: Though these reduce returns, not increase them","Example:","Entry: $1B EV = $400M Equity + $600M Debt","Exit: $1B EV = $700M Equity + $300M Debt (after $300M paydown)","Equity Return = ($700M / $400M) - 1 = 75% gross return"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1494","t":"deal","l":"Basic","s":90,"q":"Are software companies or industrial companies generally better LBO candidates, and why?","k":["Software companies are generally better LBO candidates.","Reasons:","Higher margins: SaaS models have 70-80%+ gross margins vs. 20-40% for industrials.","Predictable cash flows: Recurring subscription revenue provides stability.","Lower CapEx: Minimal capital requirements compared to manufacturing.","Scalability: Can grow without proportional cost increases.","Higher EBITDA margins: Enable greater debt service capacity.","Industrial companies face cyclicality, capital intensity, and working capital demands that make leverage riskier."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1495","t":"deal","l":"Basic","s":90,"q":"In an LBO where the entry and exit multiples are the same and no debt is paid down, how can the PE firm still generate a return?","k":["The PE firm generates returns through EBITDA growth.","Analysis:","If EBITDA increases from $100M to $150M and the multiple stays at 10x:","Entry EV = $100M * 10x = $1,000M.","Exit EV = $150M * 10x = $1,500M.","Even with no debt paydown, equity value increases $500M due to operating improvements.","Returns come from operational improvements increasing the absolute enterprise value, not just multiple expansion or deleveraging."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1496","t":"deal","l":"Basic","s":90,"q":"Discuss the meaning of the internal rate of return (IRR) and outline the pros and cons of using it as a performance metric.","k":["IRR is the discount rate that makes the net present value (NPV) of all cash flows equal to zero. It represents the annualized return on an investment.","Pros:","Intuitive percentage return that's easy to compare across investments.","Accounts for timing and magnitude of cash flows.","Time-weighted metric useful for performance measurement.","Cons:","Assumes reinvestment at the IRR itself, which may be unrealistic.","Can produce multiple solutions for non-conventional cash flows.","Doesn't reflect absolute value created (a 100% IRR on $1 vs. 20% on $100M).","Can favor smaller, shorter-duration investments over larger, value-creating ones.","Sensitive to timing of cash flows."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Wells Fargo Interview","Superday","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1497","t":"deal","l":"Basic","s":90,"q":"What are the two most important return metrics we look at in an LBO?","k":["The two key return metrics in an LBO are:","IRR (Internal Rate of Return): Measures the annualized return considering the timing of cash flows.","MOIC (Multiple on Invested Capital): Reflects total equity returns without accounting for the time value of money."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in William Blair Interview","Leveraged Buyouts (LBOs)","Basic"]},{"id":"q-1498","t":"deal","l":"Advanced","s":90,"q":"What are ways a private equity investor can increase their Internal Rate of Return (IRR)?","k":["Private equity investors can increase IRR by:","Improving operational efficiencies to boost profitability.","Implementing strategic growth initiatives to accelerate revenue.","Optimizing capital structure to reduce financing costs.","Enhancing management teams and governance.","Timing the exit strategically to maximize valuation multiples."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Ares Management Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1499","t":"deal","l":"Advanced","s":90,"q":"Pros and Cons of Capital Expenditures (Capex) in a Leveraged Buyout (LBO)?","k":["Pros:","Enhances operational efficiency and growth potential.","Can increase the value of the acquired company.","Cons:","Increases debt levels if financed through borrowing, potentially raising financial risk.","Requires careful cash flow management to ensure debt obligations can be met."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Ares Management Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1500","t":"deal","l":"Advanced","s":90,"q":"Walk me through Exit multiple drivers, ways to increase IRR, and ways to increase EBITDA margin.","k":["Exit Multiple Drivers:","Revenue and EBITDA growth rates.","Market conditions and industry trends.","Operational improvements and strategic positioning.","Ways to Increase IRR:","Accelerate revenue and profit growth.","Improve operational efficiencies to boost margins.","Strategically time the exit to maximize valuation.","Ways to Increase EBITDA Margin:","Reduce operating expenses.","Increase pricing power.","Enhance sales mix towards higher-margin products or services."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Ares Management Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1501","t":"deal","l":"Advanced","s":90,"q":"In an LBO model, which scenario creates more enterprise value at exit: a $1 increase in EBITDA or a $1 paydown of debt? Why?","k":["A $1 increase in EBITDA creates more enterprise value.","Exit Enterprise Value = Exit EBITDA * Exit Multiple. A $1 EBITDA increase generates value equal to $1 * Exit Multiple (e.g., 10x multiple = $10 value creation).","A $1 debt paydown reduces Net Debt by $1, increasing Equity Value by $1 but leaving Enterprise Value unchanged (EV = Equity Value + Net Debt).","However, for equity holders (the PE sponsor), both actions increase equity proceeds. But EBITDA growth is magnified by the exit multiple, creating substantially more value."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Bank of America Interview","Chicago office, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1502","t":"deal","l":"Advanced","s":90,"q":"Calculate the IRR for a leveraged buyout with the following assumptions:\n\n\n\nYear 0 EBITDA: $350m\nEntry Multiple: 6.0x EV/EBITDA\nLeverage Ratio: 5.0x Debt/EBITDA\nYear 5 EBITDA: $400m\nExit Multiple: 6.0x EV/EBITDA\nLeverage at Exit: 5.0x Debt/EBITDA","k":["Answer: ~3% IRR","Calculation:","Entry EV = $350m * 6.0x = $2,100m","Entry Debt = $350m * 5.0x = $1,750m","Initial Equity = $2,100m - $1,750m = $350m","Exit EV = $400m * 6.0x = $2,400m","Exit Debt = $400m * 5.0x = $2,000m","Exit Equity Proceeds = $2,400m - $2,000m = $400m","MOIC = $400m / $350m = 1.14x","IRR = (1.14)^(1/5) - 1 = 2.7% ≈ 3%","Note: With the same entry and exit multiples and leverage maintained, the return is driven primarily by EBITDA growth. The modest 14% growth over 5 years yields a low single-digit IRR."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Bank of America Interview","Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1503","t":"deal","l":"Advanced","s":90,"q":"You acquire a company with $80mm in EBITDA at a 10x multiple, funding the purchase with 60% debt. You hold the investment for 5 years.\n\n\n\n\nEBITDA remains flat at $80mm every year until the year of sale, when it is $90mm. Assume the company generates $30mm in free cash flow each year to pay down debt.\n\n\n\n\nIf you sell the company at the same 10x multiple, what is your approximate IRR and MoM multiple?","k":["Answer: ~12% IRR, ~1.8x MoM","Calculation:","Entry EV = $80m * 10x = $800m","Entry Debt = $800m * 60% = $480m","Initial Equity = $800m * 40% = $320m","Exit EV = $90m * 10x = $900m","Total Debt Paydown = $30m FCF * 5 years = $150m","Exit Debt = $480m - $150m = $330m","Exit Equity = $900m - $330m = $570m","MoM = $570m / $320m ≈ 1.78x","IRR ≈ (1.78)^(1/5) - 1 ≈ 12.2%","Note: This is rough interview math. The returns fall around ~12% IRR with a MOIC of ~1.8x depending on exact terminal rounding."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Bank of America Interview","Financial Sponsors group, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1504","t":"deal","l":"Advanced","s":90,"q":"In a 5-year LBO where the entry and exit multiples are the same, the sponsor's equity investment grows by 20%.\n\n\n\n\nWhat is the approximate IRR?","k":["Answer: ~3.7%","Calculation:","Final Value / Initial Investment = (1 + IRR)^n","1.20 = (1 + IRR)^5","IRR = (1.20)^(1/5) - 1","IRR = 1.0371 - 1 = 3.71%"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Bank of America Interview","FIG, Second round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1505","t":"deal","l":"Advanced","s":90,"q":"A company has $500 million of EBITDA, is leveraged 2x, and has a current average cost of debt of 5%. It then increases its leverage to 3x. As a result, the company's average cost of debt increases by 100 basis points. How much does interest expense change?","k":["Answer: Interest expense increases by $40 million.","Calculation:","Old debt = 2x x $500M = $1,000M at 5% = $50M interest","New total debt = 3x x $500M = $1,500M at 6% (5% + 100bps) = $90M interest","Change in interest expense = $90M - $50M = $40M","The $40M increase comes from two sources: (1) $500M of incremental debt at the new 6% rate = $30M, and (2) the 100bps rate increase on the original $1,000M of debt = $10M."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Bank of America Interview","SA 2025, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1506","t":"deal","l":"Advanced","s":90,"q":"How might a private equity firm return cash to its investors early, before a full exit?","k":["Dividend recapitalization: The portfolio company takes on additional debt and uses the proceeds to pay a special dividend to the PE sponsor.","Partial sale: Sell a minority stake to another investor or strategic partner.","IPO with partial exit: Take the company public and sell a portion of the sponsor's shares.","Sale of a division: Sell a non-core business unit and distribute proceeds.","Secondary sale: Sell a portion of the sponsor's LP interest to a secondary buyer."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Bank of America Interview","SA 2025, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1507","t":"deal","l":"Advanced","s":90,"q":"Paper LBO: Entry revenue is $200, the debt-to-equity ratio is 60:40, the EBITDA margin is 50%, and the entry multiple is 10x. Free cash flow over 5 years totals $300. Exit EBITDA is 1.5x the first year's EBITDA. All debt is paid down using 100% of free cash flow, and the exit multiple equals the entry multiple. Calculate the MOIC.","k":["Answer: MOIC = 3.0x","EBITDA = $200 x 50% = $100.","Entry EV = 10 x $100 = $1,000.","Debt = 60% x $1,000 = $600. Equity = 40% x $1,000 = $400.","FCF over 5 years = $300. All used to pay down debt.","Remaining Debt = $600 - $300 = $300.","Exit EBITDA = 1.5 x $100 = $150.","Exit EV = 10 x $150 = $1,500.","Exit Equity = $1,500 - $300 = $1,200.","MOIC = $1,200 / $400 = 3.0x.","Answer: MOIC = 3.0x."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Barclays Interview","SF Office, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1508","t":"deal","l":"Advanced","s":90,"q":"A company issues $120M of debt and $70M of equity and uses the proceeds to buy $120M of PP&E. Assume a 10-year useful life, a 5% interest rate on the debt, and a 25% tax rate. Walk me through the impact on the three financial statements in Year 1 and Year 2.","k":["Year 1 (Purchase)","Starting on the IS...","No change (purchase does not hit the IS)","Moving onto the SCF...","CFI -120 for PP&E","CFF +120 from debt, +70 from equity","Net change in cash is +70","Finally, on the BS...","A: PP&E +120, Cash +70, net +190","L: Debt +120","SE: +70 from equity issuance","...and the Balance Sheet balances","Year 2 (Ongoing)","D&A = $120M / 10 years = $12M/year. Interest = $120M x 5% = $6M/year.","Starting on the IS...","Depreciation expense: $12M","Interest expense: $6M","Pre-tax income down $18M","NI down $13.5M ($18M x 75%)","Moving onto the SCF...","NI -$13.5M","Add back depreciation +$12M (non-cash)","Net change in cash: -$1.5M","Finally, on the BS...","A: Cash -$1.5M, PP&E -$12M (depreciation), net -$13.5M","L: No change (assuming no debt repayment)","SE: -$13.5M from NI","...and the Balance Sheet balances (-$13.5M = $0 + -$13.5M)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Barclays Interview","SA 2025","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1509","t":"deal","l":"Advanced","s":90,"q":"Other than traditional textbook ways of boosting IRR, describe a more creative strategy you could use.","k":["Textbook levers include increasing leverage, cutting costs or reducing time to exit.","More creative strategies include:","Execute a dividend recap early in the hold period—refinance with cheap debt to return cash to equity holders, lifting IRR while maintaining ownership.","Early partial monetization via secondary sales or asset spinoffs. Rather than relying solely on a single exit at the end, consider selling a minority stake or non-core assets earlier in the holding period. This accelerates cash inflows, which carry more weight in IRR calculations due to the time value of money—ultimately increasing the IRR even if the total MOIC stays the same."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Brookfield Asset Management Interview","SA 2025, New York office, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1510","t":"deal","l":"Advanced","s":90,"q":"How does the presence of Payment-in-Kind (PIK) debt in a company's capital structure impact an LBO model?","k":["PIK improves early‑year cash flow by deferring interest payments, but increases exit debt and lowers equity returns if growth doesn’t outpace accrual.","Cash interest saved flows to amortize senior debt, boosting coverage ratios.","Accrued interest capitalizes, compounding leverage.","Exit equity value must overcome higher debt balance to meet target IRR."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Centerview Partners Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1511","t":"deal","l":"Advanced","s":90,"q":"If interest payments cannot be made in a company that has been purchased by a sponsor via LBO, what alternatives does the sponsor have?","k":["The sponsor could inject more equity, renegotiate the debt terms, recapitalize or restructure, or sell assets to generate cash to meet interest obligations. They might also consider a PIK toggle if the debt terms allow it."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Citi Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1512","t":"deal","l":"Advanced","s":90,"q":"In the final year of a leveraged buyout, which action creates more value: using $100 million of cash to repay debt, or reinvesting it to generate an additional $100 million in EBITDA?","k":["Reinvesting to generate $100M incremental EBITDA creates more value.","Analysis:","Debt repayment: Reduces net debt by $100M, increasing exit equity value by $100M.","EBITDA growth: Assuming an exit multiple of 8-12x, $100M additional EBITDA increases enterprise value by $800M-$1,200M. After deducting the $100M invested, net value creation is $700M-$1,100M.","The EBITDA growth significantly outweighs debt paydown due to multiple expansion effects.","However, this assumes the reinvestment actually generates the incremental EBITDA, whereas debt repayment is certain."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Citi Interview","New York Office","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1513","t":"deal","l":"Advanced","s":90,"q":"Company A has $100 in EBITDA and is acquiring Company B, which has $50 in EBITDA.\n\n\n\n\nThe combined company has $400 in existing debt and $100 in cash.\n\n\n\n\nIf the maximum leverage allowed is 5.0x Net Debt / EBITDA, how much additional debt can the combined firm raise?","k":["Answer: $450","Calculation:","Combined EBITDA = $100 + $50 = $150.","Maximum Net Debt = 5.0x * $150 = $750.","Current Net Debt = $400 debt - $100 cash = $300.","Additional Debt Capacity = $750 - $300 = $450."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Citi Interview","Chicago office, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1514","t":"deal","l":"Advanced","s":90,"q":"A private equity investor buys a company and later sells it for the exact same purchase price. The investor entered and exited at the same multiple, with no change in debt/equity proportions, revenue, or profit.\n\n\n\n\nHow is it possible that the investor is thrilled with this outcome?","k":["The investor generated strong returns through massive cash yield during the holding period.","Since the question explicitly states there was no change in the debt/equity proportions and the enterprise value stayed flat, meaningful debt paydown or dividend recapitalizations (which shift the capital structure) could not have occurred.","Therefore, the only way the sponsor generated high returns is if the business generated significant Free Cash Flow (FCF) each year, and distributed 100% of that FCF directly to the sponsor as ordinary dividends, resulting in an excellent IRR and MOIC despite a flat exit."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Citi Interview","New York Office, Second round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1515","t":"deal","l":"Advanced","s":90,"q":"Calculate the IRR based on the following assumptions for an LBO:\n\n\n\nYear 0 EBITDA: $350m\nEntry Multiple: 6.0x EV/EBITDA\nLeverage Ratio: 5.0x\nYear 5 EBITDA: $400m\nExit Multiple: 6.0x EV/EBITDA\nAssume the same leverage ratio at exit.","k":["Answer: ~2.7% IRR","Calculation:","Entry EV = $350m * 6.0x = $2,100m","Entry Debt = $350m * 5.0x = $1,750m","Initial Equity = $2,100m - $1,750m = $350m","Exit EV = $400m * 6.0x = $2,400m","Exit Debt = $400m * 5.0x = $2,000m","Exit Equity Proceeds = $2,400m - $2,000m = $400m","MOIC = $400m / $350m = 1.14x","IRR = (1.14)^(1/5) - 1 ≈ 2.7%","This low IRR reflects flat multiples and modest EBITDA growth with maintained leverage, resulting in minimal equity value creation."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Credit Suisse Interview","Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1516","t":"deal","l":"Advanced","s":90,"q":"Why is interest toggled off to avoid circularity in a financial model, and how does circularity arise in an LBO model?","k":["How Circularity Arises","In an LBO model, interest expense depends on the debt balance, but the debt balance depends on free cash flow available for debt repayment, which itself depends on interest expense. This creates a circular reference: Interest → NI → FCF → Debt Paydown → Debt Balance → Interest.","Why Toggle Off","Excel's iterative calculation can sometimes fail or produce unstable results with circular references.","A toggle switch (set to 0 or 1) lets you break the circularity for debugging. When off, interest is calculated on beginning debt balance only (no circularity). When on, it uses average debt balance (circular).","Most models use beginning-of-period debt for interest to avoid circularity entirely. Some use a mid-year convention with iterative calculations enabled.","If the model breaks, the toggle lets you quickly isolate whether the circularity is the source of the error."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in DC Advisory Interview","Generalist group, New York Office, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1517","t":"deal","l":"Advanced","s":90,"q":"You are advising a PE firm to monetize an investment in a company. What would be your advice, and what are the pros and cons of each option (IPO, sell to other PE, or sell to a strategic buyer)?","k":["IPO: Could yield a higher valuation multiple if the market is bullish, but it involves significant costs, regulatory burdens, and market volatility risk.","Sell to another PE: Typically quicker, less public scrutiny, but buyer might demand a strong IRR and leverage is key.","Sell to a strategic buyer: Possibly the highest price due to synergy potential, but the process can be longer, and you might face post-merger integration complexities."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Deutsche Bank Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1518","t":"deal","l":"Advanced","s":90,"q":"A Private Equity (PE) firm wants to double its equity stake.\n\n\n\n\nThe entry multiple is 10x EV/EBITDA, with the company generating $100M EBITDA.\n\n\n\n\n$500M debt is used to finance the transaction. At exit, EBITDA grows to $150M, the exit multiple remains 10x, and $300M debt is outstanding.\n\n\n\n\nDoes this transaction meet the PE firm's investment goals?","k":["The PE firm achieves a 2.4x return, satisfying its goal to double the equity stake.","Entry:","EV = 10x EV/EBITDA x $100M = $1,000M","Debt Used = $500M","Equity Invested = EV - Debt = $1,000M - $500M = $500M","Exit:","EV = 10x EV/EBITDA x $150M = $1,500M","Debt Remaining = $300M","Equity Proceeds = EV - Debt = $1,500M - $300M = $1,200M","Return:","Return Multiple = Equity Proceeds ÷ Equity Invested = $1,200M ÷ $500M = 2.4x"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Evercore Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1519","t":"deal","l":"Advanced","s":90,"q":"A PE firm wants to achieve a 3x multiple on invested capital (MOIC).\n\n\n\n\nEntry assumptions: $100M EBITDA, and $500M debt used.\n\n\n\n\nExit assumptions: EBITDA expands to $150M, $300M debt remains, and the exit multiple is 10x EV/EBITDA.\n\n\n\n\nWhat should the entry multiple be to achieve the goal?","k":["The required entry multiple is 9x EV/EBITDA to achieve a 3x MOIC.","Here’s the calculation:","Exit: EV = 10x EV/EBITDA x $150M = $1,500M","Equity Proceeds = EV - Debt Remaining = $1,500M - $300M = $1,200M","Investment Goal: MOIC = Equity Proceeds ÷ Equity Invested = 3x","Equity Invested = Equity Proceeds ÷ 3 = $1,200M ÷ 3 = $400M","Total EV at Entry = Equity Invested + Debt = $400M + $500M = $900M","EBITDA at Entry = $100M","Required Entry Multiple = EV ÷ EBITDA = $900M ÷ $100M = 9x EV/EBITDA"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Evercore Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1520","t":"deal","l":"Advanced","s":90,"q":"A financial sponsor is evaluating two otherwise identical companies for a potential acquisition. Would they prefer the company with higher or lower capital expenditures? Why?\n\n\n\n\nFollow-up: Now, make an argument for why they might prefer the opposite of your initial answer.","k":["Initial Answer: Lower CapEx Preferred","PE firms typically prefer lower CapEx because:","Higher Free Cash Flow available for debt paydown.","Better cash-on-cash returns.","Lower reinvestment requirements.","More predictable cash generation.","Counterargument: Higher CapEx Preferred","Higher CapEx could be attractive if:","It signals growth investments that drive future EBITDA expansion.","Maintenance CapEx is low, with incremental spend on high-return projects.","Creates barriers to entry and competitive moats.","Near-term CapEx will decline post-acquisition, improving future FCF."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Evercore Interview","New York Office, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1521","t":"deal","l":"Advanced","s":90,"q":"You buy an asset in 2010 for 10x EBITDA, and the EBITDA in 2010 is $10M. In 2011, the EBITDA grows to $11M.\n\n\n\n\nAnswer the following:\n\nWhat is your new Enterprise Value?\nWhat is your MOIC?\nHow can you improve your MOIC?","k":["Part 1: New Enterprise Value","Answer: $110M","Assuming the same 10x multiple applies","New EV = $11M * 10x = $110M","Part 2: MOIC","Answer: 1.1x (before considering debt paydown)","Entry EV = $10M * 10x = $100M","Exit EV = $110M","Simple MOIC = $110M / $100M = 1.1x","However, actual MOIC depends on leverage and debt paydown, which would increase equity returns","Part 3: Improve MOIC","Ways to improve MOIC:","Increase EBITDA through operational improvements or growth","Expand EBITDA multiple through strategic positioning or market conditions","Use leverage to amplify equity returns","Pay down debt with free cash flow to increase equity value at exit","Implement cost synergies or revenue enhancements","Execute value-creation initiatives (pricing, efficiency, etc.)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Evercore Interview","Houston office, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1522","t":"deal","l":"Advanced","s":90,"q":"You are buying Company ABC. It has $10M in EBITDA, a 5x purchase multiple, and 3x leverage. You pay down 50% of the debt at exit, and management receives 20% of the equity through options at exit. Assuming EBITDA remains constant, what does the exit multiple need to be for a 3x MOIC?","k":["Answer: 9.0x exit multiple","Calculation:","Purchase EV = 5x x $10M = $50M","Debt = 3x x $10M = $30M","Sponsor Equity = $50M - $30M = $20M","Target Sponsor Equity at exit = 3x MOIC x $20M = $60M","Management gets 20% of total equity at exit, so sponsor gets 80%","Total Exit Equity = $60M / 0.80 = $75M","Debt remaining at exit = $30M x 50% = $15M","Exit EV = Exit Equity + Remaining Debt = $75M + $15M = $90M","Exit Multiple = $90M / $10M = 9.0x"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Evercore Interview","SA 2027, New York Office, Second round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1523","t":"deal","l":"Advanced","s":90,"q":"Do this LBO in your head with no pen or paper. A company has a 10% EBITDA margin, trades at a 20x EBITDA multiple, uses 6x leverage, and is held for 3 years. What is the return? Now assume EBITDA margin doubles over the hold period. What is the IRR?","k":["Initial Setup (Assume $100 Revenue for simplicity):","EBITDA = 10% x $100 = $10","Entry EV = 20x x $10 = $200","Debt = 6x x $10 = $60","Equity = $200 - $60 = $140","Scenario 1: No EBITDA Growth, Same Multiple","Exit EV = 20x x $10 = $200","Assuming no debt paydown: Exit Equity = $200 - $60 = $140","MOIC = $140 / $140 = 1.0x. No return.","With some debt paydown the return would be marginal, driven only by deleveraging.","Scenario 2: EBITDA Margin Doubles to 20%","New EBITDA = 20% x $100 = $20 (assuming same revenue)","Exit EV = 20x x $20 = $400","Exit Equity = $400 - $60 = $340 (assuming no debt paydown for simplicity)","MOIC = $340 / $140 = ~2.4x","IRR over 3 years: ~2.4x in 3 years is approximately 34% IRR (since 1.34^3 = ~2.4x)."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Evercore Interview","SA 2025, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1524","t":"deal","l":"Advanced","s":90,"q":"Give me 8 ways to increase IRR in an LBO.","k":["Eight ways to increase IRR in an LBO:","Acquire at a lower purchase multiple.","Sell at a higher exit multiple.","Improve operational efficiency to boost margins.","Increase leverage (use more debt in the capital structure).","Execute a dividend recapitalization to return cash to equity holders.","Pay down debt faster to reduce interest expenses.","Exit the investment sooner to realize returns faster.","Achieve synergies to enhance cash flows or reduce costs."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Greenhill & Co. Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1525","t":"deal","l":"Advanced","s":90,"q":"Purchase value of $1B, 50% equity, exit in 5 years, 10x multiple, $1B in debt, and $2B in revenue at exit,\n\n\n\n\nwith a 10% EBITDA margin. Discuss the scenario.","k":["EBITDA at exit = 2 B × 10% = 200 m.","Enterprise Value exit = 200 m × 10 = $2 B.","Equity exit = 2 B – 1 B debt = $1 B.","MOIC = 1 B / 0.5 B = 2.0×.","IRR ≈ 15% (doubling money in 5 years)."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Greenhill & Co. Interview","First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1526","t":"deal","l":"Advanced","s":90,"q":"How can you increase IRR in an LBO?\n\n\n\n\nHow does a dividend recap affect IRR and MOIC?","k":["Boost IRR by:","Lower purchase price","Higher exit multiple","Faster EBITDA growth","Quicker debt pay‑down","Early cash distributions","A dividend recap pulls cash forward, raising IRR (earlier proceeds) but leaving MOIC unchanged because total dollars returned stay the same."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Greenhill & Co. Interview","First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1527","t":"deal","l":"Advanced","s":90,"q":"If you did an LBO at a 10x purchase multiple, what is the maximum multiple you would buy an add-on for?","k":["10× at most.","Paying at or below the blended entry multiple preserves multiple arbitrage; anything above dilutes value creation from the roll‑up."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Greenhill & Co. Interview","First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1528","t":"deal","l":"Advanced","s":90,"q":"What causes circularity in an LBO model, and how can you address it?","k":["Circularity in an LBO model typically arises from the interdependence between interest expense and cash flow available for debt repayment.","Interest expense depends on debt balances","Debt balances depend on cash available for repayment","Cash available for repayment depends on interest expense (since interest is subtracted from EBITDA to get to Net Income or FCF)","To address this, you can:","Use a circular reference breaker (e.g., Excel iteration): File → Options → Formulas → Enable iterative calculation. Excel will converge on a stable solution through iteration.","Use a plug or hardcode for interest: Create a simplified interest schedule, using prior-period debt balances to calculate interest (this removes forward-looking dependency). INterestInterest becomes an input, not a circular output."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Greenhill & Co. Interview","SA 2026, New York office, M&A group, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1529","t":"deal","l":"Advanced","s":90,"q":"All else being equal, what mix of amortizing loans and bonds would you recommend to a PE firm for its capital structure, and why?","k":["Typically, a PE firm prefers minimal mandatory amortization to maximize cash flow flexibility. So more bullet bonds or term loans with lighter amortization. However, some senior secured or revolver might have moderate amortization.","The trade-off is cost vs. flexibility: high-yield bonds often have higher interest but no principal repayment until maturity, while amortizing loans have lower rates but less flexibility."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Guggenheim Partners Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1530","t":"deal","l":"Advanced","s":90,"q":"LBO Case Study\n\n\n\n\nAssume a financial sponsor plans to acquire a company via LBO and has two options:\n\nOption 1: Raise a $100mm bank loan and use 100% of the company's cash flow available for debt service to pay down the outstanding loan balance each year.\nOption 2: Raise a $100mm bond and do not repay any of the bond until maturity at the end of 5 years; excess cash is retained on the balance sheet.\n\n\n\nIn both options, the interest rate of the debt is 10%, and the company generates $35 million of cash flow available for debt service (before interest and principal payments) per year over the next five years. EBITDA is $20mm each year. The purchase is funded with $100mm of debt and $50mm of equity (EV = $150mm), and the sponsor exits at the end of Year 5 at 10x EBITDA.\n\n\n\n\nQuestions\n\nAssuming the same initial investment, which option would likely deliver a higher return to the private equity firm at the end of 5 years? Why?\nIf the sponsor could earn 7% interest on cash balance in OPTION 2, would that change your answer?\nIn both options, what could the sponsor do to boost its returns?\nIf the sponsor chooses Option 2, and invests $50mm of equity into the deal, calculate the sponsor's return on investment expressed as a multiple of money invested (i.e. 1x, 2x).","k":["Question 1","Option 1 would deliver a higher return.","Amortizing debt lowers interest expense over time (since the principal balance drops), whereas Option 2 pays 10% on the full $100mm every year. Lower interest expense means more equity value.","Question 2","If you could earn 10% on cash → indifferent.","If lower than 10% on cash (e.g., 7%) → Option 1 more attractive (you save 10% on repaid debt while earning <10% on cash).","If higher than 10% on cash → Option 2 more attractive.","Question 3","Increase leverage, reduce costs/increase cash flow, pay out annual dividend to sponsor, etc.","Question 4","Answer: 4.5x MOIC","Calculation:","Exit EV: 10x * $20mm EBITDA = $200mm","Cash build: $35mm * 5 = $175mm less interest $10mm * 5 = $50mm → $125mm","Ending debt: $100mm","Exit equity value: $200mm + $125mm − $100mm = $225mm → MOIC = $225mm / $50mm = 4.5x"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Guggenheim Partners Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1531","t":"deal","l":"Advanced","s":90,"q":"A private equity firm acquired a company five years ago and now wants to exit its investment.\n\n\n\n\nPart 1: What are the primary exit options available to the PE firm?\n\n\n\n\nPart 2: Why might another private equity firm be interested in acquiring this company from the original sponsor?","k":["Part 1: Primary Exit Options","Sale to a Strategic Acquirer (Trade Sale): Sell to a corporate buyer in the same or adjacent industry.","Secondary Buyout: Sell to another PE firm.","IPO: Take the company public through an initial public offering.","Recapitalization: Dividend recap or partial sale while retaining some ownership.","Sale to Management: Management buyout (less common).","Part 2: Why Another PE Firm Would Buy","Different value creation thesis or operational improvements they believe they can implement.","Longer hold period allows further growth and margin expansion.","Access to add-on acquisition opportunities or platform for roll-up strategy.","Different cost of capital or financing environment.","Belief in continued multiple expansion or operational upside."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Guggenheim Partners Interview","New York Office, Pre-MBA Recruiting","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1532","t":"deal","l":"Advanced","s":90,"q":"What are the potential problems or risks associated with a dividend recapitalization?","k":["Key risks include:","Increased leverage reduces financial flexibility and covenant cushion.","Higher interest burden strains cash flow and limits operational investment.","Reduced ability to weather downturns or execute growth initiatives.","Potential covenant violations if performance deteriorates.","Higher borrowing costs due to increased credit risk.","May signal to market that sponsor lacks confidence in long-term prospects.","If deal performs poorly, amplified losses due to leverage."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Guggenheim Partners Interview","M&A group, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1533","t":"deal","l":"Advanced","s":90,"q":"A company is doing an LBO and has two options. Option 1: A $100 million bank loan with 100% of Free Cash Flow used to repay the debt. Option 2: A $100 million bond paid at maturity. Both options carry a 10% interest rate. The company has $35 million in Unlevered Free Cash Flow.\n\n\n\n\nWhich option would yield a higher return? Which option has a better interest expense profile?","k":["Higher Return: Option 1 (Bank Loan with Mandatory Amortization)","By using 100% of FCF to repay principal, the debt balance decreases each year, which reduces cumulative interest expense over the hold period. Lower total interest paid means more total equity value at exit. The earlier principal repayment also reduces risk.","Better Interest Expense Profile: Option 2 (Bond Paid at Maturity)","The bond has a constant $10M annual interest expense ($100M x 10%) throughout the hold period, since no principal is repaid until maturity. This creates a predictable, flat interest expense profile.","Under Option 1, interest expense starts at $10M but decreases each year as principal is paid down, resulting in lower total interest paid but a declining (not flat) profile.","Important Nuance: Cash Accumulation Offsets Most of the Difference","Under Option 2, although the full $100M of debt remains outstanding, the company's FCF accumulates as cash on the Balance Sheet each year (since it is not used for debt repayment). At exit, this accumulated cash reduces net debt. For example, over a 5-year hold with $35M in initial UFCF, the company may accumulate $125-150M+ in cash (after interest). At exit, Equity Value = Enterprise Value - Net Debt, where Net Debt = $100M debt - accumulated cash. So the return difference between the two options is much smaller than it first appears — it is driven only by the interest savings from earlier principal paydown in Option 1, not the full difference in ending debt balances.","For return maximization, Option 1 is modestly superior due to the cumulative interest savings. For cash flow flexibility (retaining cash for bolt-on acquisitions or other uses), Option 2 may be preferred."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Guggenheim Partners Interview","SA 2025","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1534","t":"deal","l":"Advanced","s":90,"q":"Two companies have the same financial profile. A PE firm is willing to pay 2x more for one of them. Give 3 to 4 reasons why.","k":["Stronger management team: A proven, experienced management team reduces execution risk and is more likely to drive value creation post-acquisition. PE firms are buying the team as much as the business.","Higher recurring revenue or customer retention: A company with subscription-based or contractual revenue has more predictable cash flows, making it easier to service debt and plan for growth.","Greater growth runway: Even with the same current financials, one company may operate in a faster-growing end market or have more whitespace for geographic or product expansion.","More operational improvement potential: If one company has inefficiencies (bloated cost structure, unoptimized pricing, underinvested sales team), a PE firm sees more margin expansion opportunity."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Harris Williams Interview","SA 2026, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1535","t":"deal","l":"Advanced","s":90,"q":"When analyzing precedent transactions, why might a financial sponsor's acquisition carry a higher multiple than a strategic buyer's transaction?","k":["Several reasons explain this phenomenon:","Competitive auction dynamics drive up prices for attractive assets.","Financial sponsors may have more flexible capital and faster decision-making.","Sponsors might see operational improvement opportunities not visible to strategics.","Strong debt markets enable higher leverage and thus higher equity returns at higher multiples.","Hot PE fundraising environment creates pressure to deploy capital.","Note: Strategics typically pay higher multiples due to synergies. If sponsors are paying more, it suggests unique market conditions."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in J.P. Morgan Interview","First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1536","t":"deal","l":"Advanced","s":90,"q":"You are valuing a company and have a set of 14 precedent transactions, split evenly between strategic and financial buyers.\n\n\n\n\nYour analysis reveals that the median multiple paid by financial sponsors is higher than that paid by strategic buyers. Why might this be the case?","k":["This is unusual but possible explanations include:","PE firms saw greater operational improvement potential.","Favorable debt markets enabled aggressive leverage and pricing.","Hot fundraising environment created deployment pressure.","Strategic buyers faced antitrust or integration concerns limiting bids.","PE transactions occurred during market peaks while strategic deals were timed differently.","Small sample size may not be statistically significant."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in J.P. Morgan Interview","Second round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1537","t":"deal","l":"Advanced","s":90,"q":"Would you ever use an LBO to value a pre-revenue company? Why or why not?","k":["No, an LBO would not be appropriate for a pre-revenue company.","The LBO model relies on the target generating stable, predictable free cash flows to service and pay down significant amounts of debt. A pre-revenue company has no cash flow to support debt repayment, making it unleverageable. Lenders would not provide financing because there is no proven revenue stream to underwrite.","Instead, pre-revenue companies (common in biotech or early-stage tech) are typically valued using a risk-adjusted DCF, comparable transactions based on pipeline or technology value, or venture capital methods based on expected future funding rounds and exit scenarios."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1538","t":"deal","l":"Advanced","s":90,"q":"How do the cash flows differ between an LBO model and a DCF model?","k":["DCF Model","Uses Unlevered Free Cash Flow (UFCF): Cash flow available to all capital providers, before debt service.","UFCF = NOPAT + D&A - CapEx - Change in NWC.","Discounted at WACC to arrive at Enterprise Value.","Capital structure is reflected in the discount rate, not the cash flows.","LBO Model","Uses Levered Free Cash Flow (or \"cash available for debt repayment\"): Cash flow after interest expense and taxes, used to pay down debt.","LFCF = Net Income + D&A - CapEx - Change in NWC (some also subtract mandatory amortization separately).","Cash flows are used to model debt paydown year by year, reducing the debt balance over the hold period.","The return is calculated from equity invested vs. equity received at exit (MOIC and IRR), not from discounting cash flows.","Key difference: DCF values the enterprise using unlevered cash flows and a discount rate. LBO models the equity return by tracking how debt is repaid from levered cash flows and how equity value grows."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in J.P. Morgan Interview","SA 2025, Healthcare group, SF Office, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1539","t":"deal","l":"Advanced","s":90,"q":"A client is looking to raise debt. Why would the client be interested in using PIK interest? How does PIK interest impact the three financial statements?","k":["PIK (Payment-in-Kind) interest allows the borrower to defer cash interest payments by adding the interest to the principal balance instead. A client would use PIK interest to preserve cash flow, especially if the company has limited near-term cash generation, is in a high-growth phase reinvesting all cash, or is in a leveraged situation where cash interest coverage is tight.","Three-Statement Impact (assume $10 PIK interest, 25% tax rate):","Starting on the IS...","Interest expense +10 (PIK is still expensed on the IS)","Pre-tax income down 10","NI down 7.5","Moving onto the SCF...","NI -7.5","Add back PIK interest +10 (non-cash expense)","Net change in cash is +2.5","Finally, on the BS...","A: Cash +2.5","L: Debt +10 (PIK accrues to principal)","SE: -7.5 from NI","...and the Balance Sheet balances"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1540","t":"deal","l":"Advanced","s":90,"q":"Part 1: You acquire a company for $1.8 billion using 50% debt and 50% equity. Over five years, $450 million of cash flow is used to pay down debt. You exit at 10x $200 million of EBITDA. What is the ending debt balance and exit equity value?\n\n\n\n\nFollow-up: Was this a good exit price, and why?","k":["Part 1: Ending Debt & Exit Equity","Entry EV = $1,800M. Debt = 50% x $1,800M = $900M. Equity = $900M.","Debt paydown = $450M, so ending debt = $900M - $450M = $450M","Exit EV = 10x x $200M = $2,000M","Exit Equity Value = $2,000M - $450M = $1,550M","MOIC = $1,550M / $900M = ~1.7x","Follow-up: Was This a Good Exit?","This was a mediocre outcome. The sponsor achieved a ~1.7x MOIC over 5 years (~11% IRR), below the typical PE target of 2.0-3.0x MOIC / 20-25% IRR. While EBITDA more than doubled and the exit multiple held at 10x, the high entry price ($1.8B) and limited debt paydown ($450M of $900M) constrained equity returns. The deal illustrates how entry valuation is the most critical driver of LBO returns."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Jefferies Interview","SA 2027, Aerospace & Defense group, Charlotte Office, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1541","t":"deal","l":"Advanced","s":90,"q":"Paper LBO: Entry assumptions are $100M in revenue, 20% EBITDA margin, 10x EBITDA entry multiple, and 4x leverage. No existing cash or debt at entry. After 5 years, revenue grows to $120M and the EBITDA margin expands to 30%. All excess cash flows are used to pay down debt, which is reduced to 25% of its original balance. The exit multiple equals the entry multiple. Calculate the MOIC and IRR.","k":["Entry:","EBITDA = $100M x 20% = $20M.","Entry EV = 10x x $20M = $200M.","Debt = 4x x $20M = $80M.","Entry Equity = $200M - $80M = $120M.","Exit (Year 5):","Exit EBITDA = $120M x 30% = $36M.","Exit EV = 10x x $36M = $360M.","Remaining Debt = $80M x 25% = $20M.","Exit Equity = $360M - $20M = $340M.","Returns:","MOIC = $340M / $120M = 2.83x.","IRR: Using the Rule of 72 approximation, ~2.83x in 5 years is roughly 23% IRR. More precisely, (2.83)^(1/5) - 1 = ~23.1%."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Jefferies Interview","SA 2025, TMT group, SF Office, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1542","t":"deal","l":"Advanced","s":90,"q":"Paper LBO: It is year-end 2025. The company you are modeling has a 10x LTM EBITDA entry/exit multiple, 5x leverage, EBITDA of $100M in 2025 (assume EBITDA stays constant throughout the holding period), a 10% interest rate on beginning debt, a 20% tax rate, $10M in capital expenditures every year, $10M in D&A every year, and no change in net working capital. All free cash flow is used to pay down debt. Assuming a 5-year holding period, calculate the MOIC.","k":["Answer: ~1.4x MOIC","Step 1: Entry Sources & Uses","Entry EV = 10x x $100M EBITDA = $1,000M","Debt = 5x x $100M = $500M","Sponsor Equity = $1,000M - $500M = $500M","Step 2: Year 1 Levered Free Cash Flow","EBITDA: $100M","Less D&A: ($10M) → EBIT: $90M","Less Interest: ($50M) → i.e., $500M x 10%","EBT: $40M","Less Taxes at 20%: ($8M)","Net Income: $32M","Plus D&A: $10M","Less CapEx: ($10M)","Levered FCF (available for debt paydown): $32M","Step 3: Debt Paydown Schedule","Each year, recompute interest on beginning debt, then calculate levered FCF to pay down debt:","Year 1: Interest = $50.0M, Levered FCF = $32.0M. End Debt = $468.0M","Year 2: Interest = $46.8M, Levered FCF = $34.6M. End Debt = $433.4M","Year 3: Interest = $43.3M, Levered FCF = $37.3M. End Debt = $396.1M","Year 4: Interest = $39.6M, Levered FCF = $40.3M. End Debt = $355.8M","Year 5: Interest = $35.6M, Levered FCF = $43.5M. End Debt = $312.3M","Step 4: Exit & Returns","Exit EV = 10x x $100M = $1,000M","Exit Equity = $1,000M - $312.3M = $687.7M","MOIC = $687.7M / $500M = ~1.4x"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Jefferies Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1543","t":"deal","l":"Advanced","s":90,"q":"How would a sell-side LBO look different from a buy-side LBO?","k":["Sell-Side LBO","Built by the sell-side advisor to determine the maximum price a financial sponsor could pay.","Uses more aggressive (optimistic) assumptions: higher growth, lower CapEx, greater leverage capacity.","Goal is to show the seller that a PE buyer can afford a higher price, supporting negotiations.","Typically uses a lower target IRR (~15-18%) to maximize the implied valuation.","Buy-Side LBO","Built by the PE sponsor or their advisor to determine the right price to pay.","Uses more conservative assumptions: base case and downside scenarios.","Goal is to determine the entry price that achieves the fund's target IRR (typically 20-25%+).","Includes detailed diligence on operations, debt capacity, and exit assumptions."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1544","t":"deal","l":"Advanced","s":90,"q":"How would you LBO a farm?\n\n\n\n\nFollow-up 1: Would a DCF be a suitable valuation method?\n\n\n\n\nFollow-up 2: What valuation multiples would you consider using?","k":["Approach","Model operations: acres × yield × commodity price, input costs, seasonal working capital, maintenance capex.","Add LBO overlay: purchase price, debt tranches, interest, amortization, exit year; test sponsor IRR and covenants.","Stress-test downside scenarios (drought, price shocks) and check asset coverage (land + equipment liquidation values).","DCF Suitability","Unlevered DCF can frame intrinsic value, but pair with asset and multiple methods due to volatile cash flows.","Valuation Multiples","EV / EBITDA to benchmark against agribusiness peers.","EV / acre (adjusted for quality and location) to align with recent farmland transactions."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Lazard Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1545","t":"deal","l":"Advanced","s":90,"q":"What's the IRR if an investment doubles in 3 years? What about if it triples over that same period?\n\n\n\n\nFollow-up: OK, what if it doubles in 5 years? And what if it triples in the same period?","k":["Commit the following rules of thumb for IRR to memory:","If a PE firm doubles its money in 3 years, that’s a 26% IRR","If a PE firm triples its money in 3 years, that’s a 44% IRR","If a PE firm doubles its money in 5 years, that’s a 15% IRR","If a PE firm triples its money in 5 years, that’s a 25% IRR"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Lazard Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1546","t":"deal","l":"Advanced","s":90,"q":"Case study: A direct-to-consumer soap company also sells through Walmart and Amazon. It has $150 million in sales, $50 million in EBITDA, and $5 million in CapEx.\n\n\n\n\nPart 1: What are the pros and cons of Walmart acquiring this company? What other type of company might be a buyer?\n\n\n\n\nPart 2: Would this be a good LBO target? Why or why not?","k":["Part 1: Walmart Acquisition","Pros:","Vertical integration: Walmart gains a proprietary brand and margin on a product it already distributes.","DTC data and customer relationships: Access to direct-to-consumer insights and digital capabilities.","Cost synergies: Eliminate distribution markups and consolidate supply chain.","Cons:","Channel conflict: Other retailers (Target, Amazon) may reduce shelf space for a Walmart-owned brand.","Cultural mismatch: DTC brand identity may clash with Walmart's mass-market positioning.","Small acquisition relative to Walmart's scale, limiting strategic impact.","Other potential buyers: A consumer staples company (e.g., P&G, Unilever) seeking DTC capabilities, or a private equity firm.","Part 2: LBO Candidacy","Strong LBO candidate:","33% EBITDA margin is healthy and supports debt service.","Low CapEx intensity ($5M on $50M EBITDA = strong FCF conversion).","Consumer staples are recession-resistant with predictable cash flows.","Multiple growth avenues (DTC expansion, retail partnerships, new products) to drive EBITDA growth."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Lincoln International Interview","SA 2026, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1547","t":"deal","l":"Advanced","s":90,"q":"Assume the same purchase and exit multiple in an LBO. If you raise both purchase and exit multiples equivalently, how does that affect IRR compared to the original scenario?","k":["IRR falls.","You pay more at entry, invest more equity, yet exit proceeds rise by the same multiple uplift you already paid. Net effect is a lower return on the larger upfront equity check."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in LionTree Interview","SA 2026","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1548","t":"deal","l":"Advanced","s":90,"q":"If you use 100% equity and get an 18% IRR, should you issue debt at 22% interest (with a 30% tax shield) to increase IRR?\n\n\n\n\nFollow-up: What if interest is 20%?","k":["Yes. 22% × (1−30%) = 15.4%, which is <18% IRR, so debt boosts returns.","At 20%: 20% × (1−30%) = 14% is < 18% → still accretive.","Guidance: multiply the debt rate by (1−tax rate) to get its after-tax cost, then compare to your unlevered IRR; if it’s lower, adding debt raises your IRR."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in LionTree Interview","SA 2026","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1549","t":"deal","l":"Advanced","s":90,"q":"Company X is acquired by a PE firm at a 10x entry multiple. X has $100 EBITDA, $200 of existing bonds that are rolled over, and total leverage of 4x. Organize the sources & uses schedule.\n\n\n\n\nFollow-up: Calculate MOIC and IRR assuming a 5-year hold, $140 EBITDA, 10x exit multiple, and only new debt is paid down.","k":["Entry Facts & Assumptions","EBITDA = $100","Target leverage 4× ⇒ total debt = $400","Existing bonds rolled = $200","New debt raised = $200 (plug to hit 4×)","Entry multiple of 10× ⇒ EV = $1,000","Ignore fees and working-capital tweaks for simplicity","Sources & Uses","Uses (cash out)","Purchase of equity: $1,000 − $200 = $800","Total uses: $800","Sources","New debt: $200","Sponsor equity (plug): $600","Total sources: $800","Note: Rolled bonds ($200) stay on the balance sheet; they are neither a cash use nor a source.","MOIC & IRR (5-year hold)","Exit EBITDA = $140","Exit multiple 10× ⇒ EV exit = $1,400","Debt at exit = $200 (rolled bonds; new debt repaid)","Equity proceeds = $1,400 − $200 = $1,200","MOIC = $1,200 ÷ $600 = 2.0×","IRR ≈ 15% (Rule of thumb: 2x in 5 years is ~15% IRR; exact IRR would be ~14.87% using the formula (2.0)^(1⁄5) − 1)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in LionTree Interview","SA 2026","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1550","t":"deal","l":"Advanced","s":90,"q":"If a company issues debt to buy back shares, what is the effect on EPS?","k":["Issuing debt to buy back shares reduces the number of outstanding shares, which can increase Earnings Per Share (EPS), assuming net income remains constant.","However, the additional interest expense from the debt can decrease net income, partially offsetting the EPS increase."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in M. Klein & Co. Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1551","t":"deal","l":"Advanced","s":90,"q":"Two companies, A and B, both generate $500 in cash flows over 5 years. Company A earns more in the earlier years, while Company B earns more in the later years. Which company has the higher IRR and which has the higher MOIC? What if the cash flows are reinvested?","k":["MOIC:","Both have the same MOIC. MOIC = Total Cash Received / Initial Investment. Since both generate $500 in total cash flows, MOIC is identical (assuming same entry investment).","IRR:","Company A has the higher IRR. IRR is time-weighted, so receiving cash earlier increases the return rate. Earlier cash flows are more valuable due to the time value of money.","If Cash Flows Are Reinvested:","Company A still wins if reinvestment returns are positive, since it can reinvest earlier cash flows for longer, generating additional returns. However, if reinvestment returns are low or negative, the advantage diminishes."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, Second round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1552","t":"deal","l":"Advanced","s":90,"q":"You are performing an LBO on two companies bought for the same price, sold for the same price, and with the same EBITDA. Why would one have a higher IRR?","k":["Reasons one company may have a higher IRR:","Better working capital management frees up cash for debt repayment.","Lower CapEx results in higher free cash flow.","Favorable depreciation or tax rates improve cash flow.","Operational efficiencies increase EBITDA and cash flow.","Faster cash flow timing enhances reinvestment opportunities.","More aggressive debt repayment reduces interest expenses.","In short, this could be due to better working capital management, lower CapEx, favorable depreciation or tax rates, operational efficiencies, better cash flow timing, or aggressive debt repayment."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Moelis & Co. Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1553","t":"deal","l":"Advanced","s":90,"q":"A PE firm purchases a company with $200 in EBITDA for a 15x multiple (and sells for the same multiple),\n\n\n\n\nusing 3x leverage and applying all FCF to pay down 50% of the debt over the hold period.\n\n\n\n\nWhat exit EBITDA is needed to achieve a 3x MOIC?","k":["500.","Entry EV = 3,000; Debt = 600 ⇒ Equity = 2,400.","Debt at exit = 300.","Target Equity = 2,400 × 3 = 7,200.","Exit EV = 7,500.","Exit EBITDA = 7,500/15 = 500."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Moelis & Co. Interview","SA 2026","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1554","t":"deal","l":"Advanced","s":90,"q":"Company A purchases Company B in 2015 at 5x EBITDA using 60% debt and 40% cash.\n\n\n\n\nThe Target’s EBITDA is $20.\n\n\n\n\nIn 2020, Company A sells Company B at 5x EBITDA. Over the 5-year holding period, a total of $20 in debt was repaid, and Company B’s EBITDA is $40 at exit.\n\n\n\n\nCalculate the MOIC.","k":["4× MOIC.","Entry EV = 100; Debt = 60; Equity = 40.","Exit EV = 200; Debt = 40.","Equity proceeds = 160.","MOIC = 160/40 = 4×."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Moelis & Co. Interview","SA 2026","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1555","t":"deal","l":"Advanced","s":90,"q":"EBITDA is 50, EV/EBITDA is 12x, leverage is 8x.\n\n\n\n\nIf you were the debt investor, how many warrants would you demand for a 1.5x MOIC?","k":["100% warrant coverage — warrants equal to the full equity upside.","EV = 50 × 12 = 600.","Debt raised = 8 × 50 = 400.","Equity at entry = 600 − 400 = 200.","To earn 1.5×, lenders need 400 × 1.5 = 600 back; principal returns 400, leaving a 200 gap.","Exit equity value is exactly 200, so lenders must own 100% of the equity via warrants."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Moelis & Co. Interview","SA 2026","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1556","t":"deal","l":"Advanced","s":90,"q":"Potential investment with initial EBITDA of $100M, Debt/EBITDA = 5x, EV/EBITDA = 10x, annual interest expense $25M, 5-year horizon, same 10x exit multiple.\n\n\n\n\nWhat final-year EBITDA is needed for a 3.0x MOIC?","k":["$200 million","Entry EV = 10 × 100 = $1 B.","Entry debt = 5 × 100 = $500 M; equity = $500 M.","Target exit equity = 3 × $500 M = $1.5 B.","If debt remains $500 M, exit EV must be $2.0 B → $2.0 B / 10 = $200 M EBITDA."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Moelis & Co. Interview","First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1557","t":"deal","l":"Advanced","s":90,"q":"Walk through all tranches of debt from most senior to most junior.","k":["Revolver: most senior, floating rate (typically SOFR + spread), cheapest financing, functions like a corporate credit card","Term Loan A (TLA): senior secured, amortizing over time, floating rate (SOFR + spread), prepayable","Term Loan B (TLB): senior secured, bullet maturity, floating rate (SOFR + higher spread than TLA)","Senior Notes: senior unsecured, bullet maturity, fixed rate, coupon above TLB pricing","Subordinated/Junior Notes: subordinated to senior debt, bullet maturity, fixed rate, coupon above senior notes","Mezzanine Debt: most junior, bullet maturity, often PIK or cash interest, typically non-prepayable"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Moelis & Co. Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1558","t":"deal","l":"Advanced","s":90,"q":"Company A has the following financials:\n\n\n\nEBITDA = $25\nD&A = $5\nIncrease in Working Capital = $5\nCapEx = $8\nInterest Rate = 10%\nTax Rate = 20%\n\n\n\nPart 1: What is the unlevered FCF?\n\n\n\n\nPart 2: If a PE firm purchased Company A for $125 with debt at 4.0x EBITDA, holds it for 3 years, and sells for a 3.0x cash-on-cash return, what is the transaction value at year 3?","k":["Part 1: Unlevered FCF","Answer: $8","EBIT = EBITDA - D&A = $25 - $5 = $20.","Taxes = EBIT * Tax Rate = $20 * 20% = $4.","NOPAT = EBIT - Taxes = $20 - $4 = $16.","Unlevered FCF = NOPAT + D&A - CapEx - Increase in NWC.","Unlevered FCF = $16 + $5 - $8 - $5 = $8.","Part 2: Exit Transaction Value","Answer: $175","Debt = 4.0x * $25 EBITDA = $100. Interest = $10/year.","Equity Investment = $125 - $100 = $25.","3.0x cash-on-cash return means Equity Proceeds = $25 * 3.0x = $75.","Levered FCF = UFCF - Interest*(1-t) = $8 - $10*(0.8) = $0.","Debt Paydown = $0 (LFCF is 0). Exit Debt = $100.","Exit EV = Equity Proceeds + Exit Debt = $75 + $100 = $175."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Moelis & Co. Interview","Chicago office, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1559","t":"deal","l":"Advanced","s":90,"q":"The goal of an LBO is to maximize IRR over a 5-year holding period.\n\n\n\n\nPart 1: Would you prefer a $1 increase in EBITDA or a $1 decrease in debt each year?\n\n\n\n\nPart 2: Now assume an entry multiple of 12x and an exit multiple of 12x with a 10% interest rate. Would your answer change?","k":["Part 1","$1 increase in EBITDA is more valuable. At exit, the $1 EBITDA increase is multiplied by the exit multiple (e.g., 10x), creating $10 of enterprise value. A $1 decrease in debt only increases equity value by $1. The multiple effect makes EBITDA growth far more impactful.","Part 2","The answer does not change. With a 12x exit multiple, $1 of EBITDA growth creates $12 of exit enterprise value per year of compounding. Even with a 10% interest rate making debt expensive, $1 of debt paydown still only increases equity by $1. The multiple amplification effect on EBITDA always dominates dollar-for-dollar debt reduction."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Moelis & Co. Interview","SA 2026, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1560","t":"deal","l":"Advanced","s":90,"q":"Part 1: You purchase a business with $200 million of EBITDA at a 15x multiple. You sell it in 5 years at the same multiple, using 3x leverage and paying down 50% of the debt over that period. How much does EBITDA need to grow to achieve a 3x MOIC?\n\n\n\n\nPart 2: Pick an industry and explain some specific operational initiatives that could drive the EBITDA growth you just calculated.","k":["Part 1: LBO Math","Entry EV = $200M x 15x = $3,000M","Debt = 3x x $200M = $600M","Entry Equity = $3,000M - $600M = $2,400M","Target Exit Equity = 3x MOIC x $2,400M = $7,200M","Debt remaining at exit = $600M x 50% = $300M","Required Exit EV = $7,200M + $300M = $7,500M","Required Exit EBITDA = $7,500M / 15x = $500M","EBITDA must grow from $200M to $500M, an increase of $300M or 150% (roughly 20% annual growth).","Part 2: Example Industry - Healthcare Services","Tuck-in acquisitions: Roll up smaller clinics or practices at lower multiples (6-8x) to grow EBITDA through multiple arbitrage.","Revenue cycle optimization: Improve billing and collections to reduce revenue leakage by 5-10%.","Payor mix shift: Negotiate better reimbursement rates and shift toward higher-acuity, higher-margin services.","Operational efficiency: Centralize back-office functions (HR, IT, procurement) across locations to reduce SG&A.","De novo expansion: Open new locations in underserved markets with favorable demographics."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Moelis & Co. Interview","SA 2027, New York Office","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1561","t":"deal","l":"Advanced","s":90,"q":"Paper LBO: A target has a purchase Enterprise Value of $500 million, financed with $300 million of debt at an 8% interest rate and $200 million of sponsor equity. EBITDA is $100 million and grows 10% each year. The company pays $20 million in dividends each year, has constant CapEx of $10 million, interest is split half PIK and half cash, the tax rate is 25%, and all remaining free cash flow is used to pay down the principal. The hold period is 7 years. Assume the exit multiple equals the entry multiple. Calculate the MOIC and IRR.","k":["Setup","Entry EV = $500M, Entry Multiple = 500 / 100 = 5.0x","Debt = $300M at 8%, Sponsor Equity = $200M","Interest is computed on beginning debt balance each year, split half cash / half PIK","Taxes = 25% of EBT (EBITDA - Total Interest, since both cash and PIK interest are tax-deductible)","FCF = EBITDA - Cash Interest - Taxes - CapEx - Dividends. All remaining FCF pays down debt. PIK interest adds to the debt balance.","Year-by-Year Debt Schedule","Y1: EBITDA = $110M. Beg Debt = $300M. Total Int = $24M (Cash $12M, PIK $12M). Taxes = 25% x ($110 - $24) = $21.5M. FCF = $110 - $12 - $21.5 - $10 - $20 = $46.5M. End Debt = $300 + $12 - $46.5 = $265.5M.","Y2: EBITDA = $121M. Beg Debt = $265.5M. Total Int = $21.2M (Cash $10.6M, PIK $10.6M). Taxes = 25% x ($121 - $21.2) = $25.0M. FCF = $121 - $10.6 - $25.0 - $10 - $20 = $55.4M. End Debt = $265.5 + $10.6 - $55.4 = $220.7M.","Y3: EBITDA = $133.1M. Beg Debt = $220.7M. Total Int = $17.7M (Cash $8.8M, PIK $8.8M). Taxes = 25% x ($133.1 - $17.7) = $28.9M. FCF = $133.1 - $8.8 - $28.9 - $10 - $20 = $65.4M. End Debt = $220.7 + $8.8 - $65.4 = $164.1M.","Y4: EBITDA = $146.4M. Beg Debt = $164.1M. Total Int = $13.1M (Cash $6.6M, PIK $6.6M). Taxes = 25% x ($146.4 - $13.1) = $33.3M. FCF = $146.4 - $6.6 - $33.3 - $10 - $20 = $76.5M. End Debt = $164.1 + $6.6 - $76.5 = $94.2M.","Y5: EBITDA = $161.1M. Beg Debt = $94.2M. Total Int = $7.5M (Cash $3.8M, PIK $3.8M). Taxes = 25% x ($161.1 - $7.5) = $38.4M. FCF = $161.1 - $3.8 - $38.4 - $10 - $20 = $88.9M. End Debt = $94.2 + $3.8 - $88.9 = $9.1M.","Y6: EBITDA = $177.2M. Beg Debt = $9.1M. Total Int = $0.7M (Cash $0.4M, PIK $0.4M). Taxes = 25% x ($177.2 - $0.7) = $44.1M. FCF = $177.2 - $0.4 - $44.1 - $10 - $20 = $102.7M. Debt fully repaid; excess cash = ~$93.6M.","Y7: EBITDA = $194.9M. No debt. Taxes = 25% x $194.9 = $48.7M. FCF = $194.9 - $48.7 - $10 - $20 = $116.2M.","Cash Accumulation","Excess cash from Y6 onward: ~$93.6 + $116.2 = ~$210M","Exit (Year 7)","Exit EBITDA = ~$195M, Exit Multiple = 5.0x","Exit EV = 5.0x x $195M = ~$975M","Exit Equity = $975M - $0 debt + ~$210M cash = ~$1,185M","Total dividends = 7 x $20M = $140M","Total proceeds = ~$1,185M + $140M = ~$1,325M","Returns","MOIC = ~$1,325M / $200M = ~6.6x","IRR = ~30% (approximated; 6.6x over 7 years with interim dividend cash flows)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Morgan Stanley Interview","SA 2027, TMT group, Menlo Park Office, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1562","t":"deal","l":"Advanced","s":90,"q":"A company does an LBO at a purchase price of 175, with 75 in equity.\n\n\n\n\nThey hold it 5 years, have 20 in EBITDA at exit, exit at a 10x multiple, and end with equity value of 150 at exit.\n\n\n\n\nThey pay a dividend of 25 to the sponsor.\n\n\n\n\nWhat is the total free cash flow generated over the course of the business?","k":["$75.","Debt paid down: Start 100 (175–75) → End 50 (200 EV –150 Eq) → 50","Dividend to sponsor: 25","Operational cash available to service debt and equity = 50 + 25 = 75."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Perella Weinberg Interview","Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1563","t":"deal","l":"Advanced","s":90,"q":"A private equity firm acquires a company for $1 million and sells it for $1 million five years later.\n\n\n\n\nAssuming the entry and exit multiples were the same, is it possible for the firm to have generated a positive return on its investment?","k":["Yes, it is possible for the firm to have generated a positive return.","The premises of the question—identical entry and exit enterprise value ($1M) and identical entry and exit multiples—mean that the company's EBITDA must have remained flat during the holding period. Therefore, any returns must have come from changes to the capital structure or cash distributions, not operational growth.","The two primary ways to generate a return are:","Debt Paydown: If the acquisition was financed with debt (a leveraged buyout), the company's free cash flow could be used to pay down the principal balance of that debt over the five years. This reduces net debt, and since Enterprise Value remained constant, the Equity Value portion must increase, generating a positive return for the sponsor.","Dividends / Dividend Recapitalization: The company could have used its cash flow or raised additional debt to issue dividends to the private equity owner during the holding period. These distributions represent a return of capital that would result in a positive return, even if the exit equity value is the same as the entry equity investment."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Perella Weinberg Interview","SF Office","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1564","t":"deal","l":"Advanced","s":90,"q":"Who would pay more for the same target in private equity: a firm with a 15% IRR requirement or a firm with a 21% IRR requirement? Why?","k":["The firm with the 15% IRR requirement would pay more.","A lower required return means the firm is willing to accept a lower annualized return on its equity investment. Since the target's cash flows and exit value are the same regardless of the buyer, a lower IRR hurdle allows the firm to pay a higher entry price and still meet its return threshold.","Conversely, the firm requiring 21% needs a bigger spread between its entry equity and exit equity, which constrains how much it can pay upfront. The higher the IRR hurdle, the lower the maximum purchase price."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Piper Sandler Interview","SA 2025","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1565","t":"deal","l":"Advanced","s":90,"q":"Please answer the following as if you were a private equity sponsor:\n\n\n\nWhat are the key drivers of returns in an LBO model?\nIf you acquire a capital-intensive business, what actions could you take to boost its short-term cash flow?\nHow might those actions impact the company's exit multiple?","k":["Part 1: Key LBO Return Drivers","Multiple expansion: Buying low, selling high (entry vs. exit multiple).","EBITDA growth: Revenue growth and margin improvement.","Deleveraging: Debt paydown from cash generation increases equity value.","Leverage: Magnifies returns through financial engineering.","Part 2: Boosting Short-Term Cash Flow","Reduce CapEx: Defer maintenance or growth capital spending.","Working capital optimization: Accelerate collections, extend payables, reduce inventory.","Cost cutting: Reduce SG&A, streamline operations.","Asset sales: Divest non-core or underutilized assets.","Part 3: Impact on Exit Multiple","Short-term cash flow actions may harm long-term value. Reduced CapEx can impair growth prospects and competitiveness. Buyers recognize underinvestment, potentially lowering exit multiples. Optimal strategy balances near-term cash generation with maintaining business quality and growth trajectory."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in PJT Partners Interview","New York Office","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1566","t":"deal","l":"Advanced","s":90,"q":"Beyond EBITDA growth and debt paydown, what are other ways a private equity firm can boost IRR on an investment?\n\n\n\n\nFor example, how does a dividend recap impact returns?","k":["Additional IRR drivers:","Multiple expansion (selling at higher exit multiple).","Operational improvements (margin expansion, efficiency gains).","Strategic repositioning (entering higher-growth markets, new product lines).","Add-on acquisitions (buy-and-build strategy).","Working capital optimization.","Dividend Recap Impact:","Company issues new debt to pay special dividend to PE sponsor.","Reduces sponsor's invested equity capital while maintaining ownership.","Boosts IRR and MOIC by recovering capital early without exiting.","Increases leverage, which amplifies returns (but also increases risk)."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in PJT Partners Interview","Second round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1567","t":"deal","l":"Advanced","s":90,"q":"You are given the following LBO case study. Company ABC was purchased for $1.5 billion in 2025, financed with 1/3 debt at a 10% interest rate and 2/3 equity. ABC is cash-free and debt-free at acquisition.\n\n\n\n\nAssumptions:\n\n2024 Revenue: $300 million\nRevenue Growth: 20% annually\nOperating Expenses (including D&A): 60% of revenue\nTax Rate: 25%\nD&A: 5% of revenue\nStock-Based Compensation: $5 million\nMandatory Debt Amortization: $20 million per year ($100 million total over 5 years)\nCash sits on the balance sheet, no CapEx\nExit Multiple in Year 5: 10x LTM EBITDA\n\n\n\nPlease answer the following:\n\nWhat are the adjusted EBITDA multiple and EV/Revenue multiple at entry for 2024 and 2025?\nWhat is the Free Cash Flow?\nWhat is the Money-on-Money (MoM) return?\nWhat is the IRR?","k":["Setup","Entry EV = $1,500M. Debt = $500M (1/3). Equity = $1,000M (2/3).","Interest at 10% on beginning debt balance. Debt paydown = $100M total ($20M/year over 5 years), so interest declines each year.","Revenue Build:","2024: $300M","2025: $360M (300 x 1.2)","2026: $432M","2027: $518.4M","2028: $622.1M","2029: $746.5M","EBITDA (Revenue x 40%, since OpEx incl. D&A = 60%, EBIT margin = 40%, add back D&A of 5%):","EBIT = 40% of revenue. EBITDA = EBIT + D&A = 40% + 5% = 45% of revenue.","Adjusted EBITDA = EBITDA + SBC = (45% x Revenue) + $5M","2024: $300M x 45% + $5M = $135M + $5M = $140M","2025: $360M x 45% + $5M = $162M + $5M = $167M","Q1: Entry Multiples","2024 Adj. EBITDA Multiple = $1,500M / $140M = 10.7x","2025 Adj. EBITDA Multiple = $1,500M / $167M = 9.0x","2024 EV/Revenue = $1,500M / $300M = 5.0x","2025 EV/Revenue = $1,500M / $360M = 4.2x","Q2: Free Cash Flow (year-by-year with declining interest)","FCF = NI + D&A + SBC (no CapEx). Interest declines as $20M/year of debt is repaid.","Y1 (2025): Beg Debt = $500M. Interest = $50M. EBIT = $144M. EBT = $94M. Tax = $23.5M. NI = $70.5M. D&A = $18M. FCF = $70.5 + $18 + $5 = $93.5M.","Y2 (2026): Beg Debt = $480M. Interest = $48M. EBIT = $172.8M. EBT = $124.8M. Tax = $31.2M. NI = $93.6M. D&A = $21.6M. FCF = $93.6 + $21.6 + $5 = $120.2M.","Y3 (2027): Beg Debt = $460M. Interest = $46M. EBIT = $207.4M. EBT = $161.4M. Tax = $40.3M. NI = $121.0M. D&A = $25.9M. FCF = $121.0 + $25.9 + $5 = $151.9M.","Y4 (2028): Beg Debt = $440M. Interest = $44M. EBIT = $248.8M. EBT = $204.8M. Tax = $51.2M. NI = $153.6M. D&A = $31.1M. FCF = $153.6 + $31.1 + $5 = $189.7M.","Y5 (2029): Beg Debt = $420M. Interest = $42M. EBIT = $298.6M. EBT = $256.6M. Tax = $64.2M. NI = $192.5M. D&A = $37.3M. FCF = $192.5 + $37.3 + $5 = $234.8M.","Q3 & Q4: Exit, MoM, and IRR","Year 5 (2029) EBITDA = 45% x $746.5M = $335.9M. Adj. EBITDA = $335.9M + $5M = $340.9M","Exit EV = 10x x $340.9M = $3,409M","Remaining Debt = $500M - $100M = $400M","Cumulative FCF = $93.5 + $120.2 + $151.9 + $189.7 + $234.8 = ~$790M. After $100M paydown, cash on BS = ~$690M.","Exit Equity = $3,409M - $400M + $690M = $3,699M","MoM = $3,699M / $1,000M = ~3.7x","IRR: ~30% (3.7x over 5 years)"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in RBC Interview","SA 2025, SF Office, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1568","t":"deal","l":"Advanced","s":90,"q":"Other than Debt to EBITDA and Interest Coverage Ratio, what metric tells you how much debt a company can hold in an LBO?","k":["You could look at Fixed Charge Coverage Ratio (FCCR), Debt Service Coverage Ratio (DSCR), or measure FCF after mandatory payments.","Essentially, any ratio showing the ability to cover principal and interest can indicate leverage capacity."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Rothschild Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1569","t":"deal","l":"Advanced","s":90,"q":"What is the difference between committed capital and best-efforts financing?","k":["Committed Capital","Banks legally commit to provide financing regardless of market conditions.","Provides certainty of funding for the transaction.","Higher fees due to the commitment risk banks assume.","Common in large, competitive M&A processes.","Best-Efforts Financing","Banks agree to use their best efforts to arrange financing but don't guarantee it.","Less certainty - financing depends on market conditions and investor demand.","Lower fees since banks don't take balance sheet risk.","More common when market conditions are favorable or deal is less competitive."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1570","t":"deal","l":"Advanced","s":90,"q":"What topics and analyses would you include in a detailed internal credit memorandum for a sponsor-backed LBO, and in what order should they be presented?","k":["Key sections in order:","Executive Summary: Transaction overview, structure, and key credit highlights.","Sponsor & Management: Track record, industry expertise, value creation thesis.","Business Overview: Products/services, competitive position, industry dynamics.","Transaction Structure: Sources & uses, debt structure, pricing, covenants.","Financial Analysis: Historical performance, projections, key metrics, sensitivities.","Credit Analysis: Leverage ratios, coverage ratios, debt capacity, downside scenarios.","Collateral & Security: Asset coverage, priority of claims, guarantees.","Risk Factors: Industry, operational, financial, and market risks.","Recommendation: Credit decision and rationale."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1571","t":"deal","l":"Advanced","s":90,"q":"You buy a company for $1 million and later sell it for $1 million.\n\n\n\n\nPart 1: Why might you still be happy with this investment?\n\n\n\n\nPart 2: What if you bought it with all cash and no debt? Could you still be happy?","k":["Part 1","You could still be happy because:","If you used leverage, cash flows during holding period may have paid down debt, generating positive equity returns despite flat purchase/sale price.","Dividend recaps extracted cash during ownership.","Operational cash flows provided returns even without price appreciation.","Part 2","Even with all cash and no debt, you could be happy if:","Company distributed significant dividends during ownership period.","You achieved non-financial objectives (strategic, learning, access to technology/talent).","You broke even rather than losing money in difficult market.","However, an all-cash, flat return would generally be disappointing as it represents 0% IRR and opportunity cost of deploying capital elsewhere."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1572","t":"deal","l":"Advanced","s":90,"q":"How is stock-based compensation (SBC) treated in the calculation of Levered Free Cash Flow (LFCF) for an LBO model?","k":["Stock-based compensation is a non-cash expense added back to Net Income when calculating Levered Free Cash Flow, similar to depreciation and amortization.","In an LBO context, SBC is typically minimal or eliminated post-transaction, as the company becomes private and equity-based compensation programs are restructured.","For pre-LBO financials, SBC is added back in CFO to reflect actual cash generation, though it represents real economic dilution to shareholders."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1573","t":"deal","l":"Advanced","s":90,"q":"In an LBO model, rank the following changes from highest to lowest impact on IRR:\n\n\n\nGrowing revenue by 10% instead of 5%\nGrowing EBITDA by 7% instead of 6%\nIncreasing the exit EBITDA multiple from 9x to 10x\nDecreasing the interest rate on debt from 8% to 6%","k":["Ranking from highest to lowest impact on IRR: (3), (2), (4), (1).","Exit multiple expansion has the largest impact as it directly increases exit proceeds on the entire enterprise value","EBITDA growth directly improves exit value and debt paydown capacity","Lower interest rates improve cash flow for debt paydown, modestly boosting returns","Revenue growth has the smallest impact unless it drives EBITDA margin expansion; without margin improvement, incremental revenue has limited effect"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1574","t":"deal","l":"Advanced","s":90,"q":"Calculate the Multiple on Invested Capital (MoM) for an LBO with the following assumptions:\n\n\n\nEntry & Exit Multiple: 10x EBITDA\nInitial EBITDA: $50m\nInitial Capital Structure: 60% Debt, 40% Equity\nEBITDA Growth: 15% CAGR over a 5-year hold period\nDebt Paydown: 1/3 of the initial debt balance is paid down over the hold period.","k":["Answer: 4.03x MoM","Calculation:","Initial EV: $50m * 10x = $500m","Initial Debt: $500m * 60% = $300m","Initial Equity: $500m * 40% = $200m","Exit EBITDA: $50m * (1.15)^5 = $50m * 2.011 = $100.6m","Exit EV: $100.6m * 10x = $1,006m","Debt Paydown: $300m * (1/3) = $100m","Exit Debt: $300m - $100m = $200m","Exit Equity: $1,006m - $200m = $806m","Equity Proceeds: $806m","MoM: $806m / $200m = 4.03x"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1575","t":"deal","l":"Advanced","s":90,"q":"Answer the following questions regarding valuation in a sale process:\n\nHow does a private equity firm typically value a business?\nHow does the presence of staple financing affect this valuation?\nHow would a DCM team approach valuing the business in the context of providing that staple financing?\nBetween the PE firm and the DCM team, who would likely arrive at a higher valuation and why?","k":["Part 1: PE Valuation Approach","PE firms use an LBO model to determine maximum price that achieves target returns (e.g., 20%+ IRR, 3x MOIC). They work backward from exit assumptions.","Part 2: Staple Financing Impact","Staple financing (pre-arranged debt from seller's banks) increases valuation by providing certainty and attractive terms, enabling more aggressive leverage and higher purchase price.","Part 3: DCM Valuation Approach","DCM values the business based on debt capacity: sustainable leverage multiples (typically 4-6x EBITDA) given credit metrics, industry risk, and market conditions.","Part 4: Comparison","PE firm likely values higher.","DCM is conservative (focused on downside protection, credit quality)","PE optimizes for equity returns with operational improvements","PE can use additional equity if debt capacity is constrained"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1576","t":"deal","l":"Advanced","s":90,"q":"You acquire a company with $200M in EBITDA at a 6x multiple, using 50% debt. In 3 years, you sell it when it has $300M in EBITDA at a 6x multiple.\n\n\n\n\nAssume all free cash flow is used to pay down debt. What is the approximate IRR?","k":["Answer: ~36% IRR","Calculation:","Entry EV = $200M * 6x = $1,200M","Equity Investment = $1,200M * 50% = $600M","Initial Debt = $600M","Exit EV = $300M * 6x = $1,800M","Average EBITDA over 3 years ≈ ($200M + $300M) / 2 = $250M","FCF conversion at ~40% of average EBITDA = $250M * 40% = $100M/year","Total debt paydown over 3 years = $100M * 3 = $300M","Exit Debt = $600M - $300M = $300M","Exit Equity Value = $1,800M - $300M = $1,500M","MOIC = $1,500M / $600M = 2.5x","IRR = (2.5x)^(1/3) - 1 ≈ 35.7%"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1577","t":"deal","l":"Advanced","s":90,"q":"What would you think if I told you a company was bought and sold by 3-4 different private equity firms over its lifetime?","k":["This suggests a strong, PE-friendly business with several positives:","Stable, predictable cash flows attractive to financial sponsors","Fragmented industry conducive to add-on acquisitions and roll-up strategy","Proven value creation playbook that multiple sponsors executed","Strong management team or operational improvements realized","Secondary/continuation deals allowed earlier sponsors to exit while business still had upside","Potential concerns:","Already optimized - limited remaining value creation levers","High leverage over time may constrain flexibility or increase risk","Overall, this pattern is common in industries like healthcare services, business services, and industrials."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1578","t":"deal","l":"Advanced","s":90,"q":"Please walk me through the following paper LBO:\n\n\n\n\nEntry Assumptions:\n\n$100M Revenue, 20% EBITDA Margin\n10x LTM EV/EBITDA Purchase Multiple\nLevered 4x LTM EBITDA\n\n\n\nExit Assumptions (5-Year Hold):\n\n$120M Revenue, 30% EBITDA Margin\nAssume same 10x EV/EBITDA Exit Multiple\nFree cash flow generated was used to pay down 50% of the initial debt balance.\n\n\n\nDetermine the Cash-on-Cash multiple and the approximate IRR.","k":["Answer: 2.67x MOIC, ~22% IRR","Entry:","Entry EBITDA = $100M * 20% = $20M","Entry EV = $20M * 10x = $200M","Entry Debt = $20M * 4x = $80M","Entry Equity = $200M - $80M = $120M","Exit:","Exit EBITDA = $120M * 30% = $36M","Exit EV = $36M * 10x = $360M","Debt Paydown = $80M * 50% = $40M","Exit Debt = $80M - $40M = $40M","Exit Equity = $360M - $40M = $320M","Returns:","MOIC = $320M / $120M = 2.67x","IRR = (2.67x)^(1/5) - 1 = 21.7% ≈ 22%"],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1579","t":"deal","l":"Advanced","s":90,"q":"In an LBO model, which has a greater impact on equity value at exit: a $1 increase in EBITDA or a $1 decrease in net debt?","k":["A $1 increase in EBITDA has a greater impact.","Analysis:","$1 increase in EBITDA: Multiplied by exit multiple (e.g., 8x), creating $8 in additional EV and thus equity value.","$1 decrease in net debt: Creates only $1 in additional equity value (dollar-for-dollar).","The multiple effect on EBITDA makes it significantly more impactful than debt paydown."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1580","t":"deal","l":"Advanced","s":90,"q":"A PE firm acquires a company with $100M in EBITDA for a 10x multiple, using 60% debt.\n\n\n\n\nThe firm exits in 5 years when EBITDA is $150M at a 9x multiple. Over the hold period, $250M of debt is paid down.\n\n\n\n\nWhat is the approximate IRR?","k":["Answer: ~20%","Calculation:","Entry EV = $100M * 10x = $1,000M.","Initial Equity = $1,000M * 40% = $400M.","Exit EV = $150M * 9x = $1,350M.","Initial Debt = $1,000M * 60% = $600M.","Exit Debt = $600M - $250M = $350M.","Exit Equity = $1,350M - $350M = $1,000M.","MOIC = $1,000M / $400M = 2.5x.","IRR = (2.5)^(1/5) - 1 ≈ 20%."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1581","t":"deal","l":"Advanced","s":90,"q":"A private equity firm acquires a company with $100M in EBITDA at a 5x multiple. The deal is financed with 3x Debt/EBITDA leverage.\n\n\n\n\nThe firm holds the investment for 5 years, during which the company generates a total of $150M in free cash flow, all used to pay down debt.\n\n\n\n\nAt exit, the company's EBITDA has grown to $150M, and it is sold at the same 5x multiple.\n\n\n\n\nCalculate the Multiple on Invested Capital (MOIC) and the approximate Internal Rate of Return (IRR).","k":["Entry","Purchase Price (EV) = $100M EBITDA * 5x = $500M.","Debt = 3x * $100M = $300M.","Equity = $500M - $300M = $200M.","Exit","Exit EV = $150M EBITDA * 5x = $750M.","Remaining Debt = $300M - $150M (FCF used for paydown) = $150M.","Exit Equity Value = $750M - $150M = $600M.","Returns","MOIC = Exit Equity / Initial Equity = $600M / $200M = 3.0x.","IRR: $200M grows to $600M over 5 years. Using IRR formula: (3.0)^(1/5) - 1 ≈ 24.6%."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in Unspecified Interview","Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1582","t":"deal","l":"Advanced","s":90,"q":"In an LBO, would you rather have an increase in EBITDA, an increase in the exit multiple, or an increase in cash flow? Why?","k":["An increase in EBITDA is the most valuable lever.","EBITDA has a double benefit: it directly increases exit enterprise value (EBITDA x exit multiple), and the incremental cash flow from higher EBITDA also allows for more debt paydown, increasing equity value further. An increase in exit multiple only affects the valuation at exit, and an increase in cash flow helps with debt paydown but does not affect the exit valuation directly unless it flows through higher EBITDA.","Put differently, a $1 increase in EBITDA at an 8x exit multiple creates $8 of additional enterprise value, plus the accumulated cash flow benefit over the hold period. That compounding effect makes EBITDA growth the most powerful lever in an LBO."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Unspecified Interview","SA 2027, Superday","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1583","t":"deal","l":"Advanced","s":90,"q":"What are the ways a private equity firm can generate returns in an LBO? Specifically, if the entry and exit multiples are the same and there is no EBITDA growth, how can the firm still generate a return?","k":["The three main return drivers in an LBO are:","EBITDA Growth (operational improvement)","Multiple Expansion (buying low, selling high)","Debt Paydown (deleveraging)","If both EBITDA growth and multiple expansion are zero, the only remaining lever is debt paydown. Over the hold period, the company uses its free cash flow to pay down debt. Since Enterprise Value stays constant (same EBITDA x same multiple), but debt decreases, equity value increases by the amount of debt repaid.","For example: Buy at 10x EBITDA ($100M EBITDA = $1B EV), 60% debt ($600M) and 40% equity ($400M). Over 5 years, pay down $200M of debt. At exit, EV is still $1B but debt is $400M, so equity = $600M. MOIC = $600M / $400M = 1.5x, which equates to roughly an 8.4% IRR purely from deleveraging."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in Unspecified Interview","SF Office, First round","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1584","t":"deal","l":"Advanced","s":90,"q":"What is a bolt-on acquisition?","k":["A bolt-on (or tuck-in) acquisition is when a PE sponsor acquires a smaller company to “bolt on” to an existing platform portfolio company, leveraging synergies, cross-selling, or cost savings. It’s typically at a lower multiple, creating immediate accretion in the combined entity’s valuation."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["Reported in William Blair Interview","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1585","t":"deal","l":"Advanced","s":90,"q":"You acquire a company with $150M of EBITDA at a 10.0x EV/EBITDA multiple, using 60% debt financing. You exit after 5 years at an 8.0x multiple and have paid down $400M of debt by exit. What exit EBITDA do you need to achieve a 2.5x MOIC?","k":["Answer: $250M exit EBITDA.","Entry EV = $150M x 10.0x = $1,500M.","Debt = 60% x $1,500M = $900M. Equity check = $1,500M - $900M = $600M.","Target exit equity = $600M x 2.5 = $1,500M.","Remaining debt at exit = $900M - $400M = $500M.","Exit EV = Exit Equity + Remaining Debt = $1,500M + $500M = $2,000M.","Exit EBITDA = $2,000M / 8.0x = $250M.","That is EBITDA growth from $150M to $250M, or approximately 11% CAGR over 5 years — a realistic LBO growth profile."],"collection":"practice","topic":"Leveraged Buyouts (LBOs)","tags":["New","Reported in William Blair Interview","SA 2027, Chicago Office","Leveraged Buyouts (LBOs)","Advanced"]},{"id":"q-1586","t":"mkt","l":"Basic","s":90,"q":"What is the difference between earnings and free cash flow?","k":["Earnings: Represent net income after all expenses, taxes, and depreciation. It's reported on the Income Statement.","Free Cash Flow (FCF): Represents the cash generated by the company after accounting for capital expenditures. It indicates the company's ability to generate cash to expand, pay dividends, or reduce debt. Reported on the Cash Flow Statement."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Ares Management Interview","Finance Brain Teasers","Basic"]},{"id":"q-1587","t":"mkt","l":"Basic","s":90,"q":"What is the difference between free cash flow for equity holders and debt holders?","k":["Free Cash Flow to Equity (FCFE): The cash available to equity shareholders after all expenses, taxes, reinvestment, and debt repayments.","Free Cash Flow to Debt (FCFD): The cash available to service debt obligations, including interest and principal repayments.","In other words, FCFE is levered and accounts for debt servicing, while FCFF is unlevered and does not deduct interest payments."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Ares Management Interview","Finance Brain Teasers","Basic"]},{"id":"q-1588","t":"mkt","l":"Basic","s":90,"q":"What are some operating metrics of a company that a private equity investor would be interested in?","k":["Private equity investors typically focus on metrics such as EBITDA, revenue growth, profit margins, return on invested capital (ROIC), cash flow generation, customer acquisition costs, churn rates, and operational efficiency ratios."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Ares Management Interview","Finance Brain Teasers","Basic"]},{"id":"q-1589","t":"mkt","l":"Basic","s":90,"q":"Would you rather have a 10% increase in volume, a 10% increase in price, or a 10% decrease in costs?","k":["Absent any demand elasticity concerns, the 10% price increase yields the largest absolute improvement in profits. However, in a real scenario, higher prices might reduce volume, so the decision depends on pricing power and market response.","Example (assuming no demand elasticity): Assume Revenue = 100 and Costs = 80, so Net Income (NI) = 20.","A 10% price increase raises Revenue to 110 while Costs remain 80, pushing NI to 30 (a 50% increase).","A 10% volume increase might only raise NI to around 22 (a 10% increase), assuming proportional cost increases.","A 10% cost reduction would yield NI of 28 (a 40% increase), still less than the price-increase scenario."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Ares Management Interview","Finance Brain Teasers","Basic"]},{"id":"q-1590","t":"mkt","l":"Basic","s":90,"q":"With $100M in revenue, 20% Gross Margin (GM), what is the impact of a 10% increase in volume, a 2% increase in price, or a $1M decrease in overhead?","k":["The impact under each scenario (assuming volume and price changes do not affect overhead) is:","10% Increase in Volume: Revenue becomes $110M. With a 20% GM, COGS is $88M, yielding a gross profit of $22M → up $2M from $20M.","2% Increase in Price: Revenue becomes $102M. COGS remains $80M (same volume), yielding a gross profit of $22M → also up $2M from $20M.","$1M Decrease in Overhead: This reduction is a direct $1M increase in operating profit (below the gross margin line).","Thus, both a 10% increase in volume and a 2% increase in price yield a $2M improvement in gross profit, while a $1M reduction in overhead leads to a $1M improvement in operating profit."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Ares Management Interview","Finance Brain Teasers","Basic"]},{"id":"q-1591","t":"mkt","l":"Basic","s":90,"q":"How would you explain the concept of Internal Rate of Return (IRR) to a child?","k":["IRR is like figuring out how good an investment is by finding the interest rate that makes all your money in and money out equal to zero.","Imagine you buy a lemonade stand for $100, earn $30 each year for 3 years, then sell it for $50. IRR tells you what annual return you earned on your $100 - similar to how a bank account pays you interest.","The higher the IRR, the better the investment performed."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Bank of America Interview","New York Office, Second round","Finance Brain Teasers","Basic"]},{"id":"q-1592","t":"mkt","l":"Basic","s":90,"q":"How much money will I have in 7 years if I invest $100 and earn 10% a year?","k":["Using compound interest: Future Value = Present Value * (1 + r)^n.","So here, FV = $100 * (1 + 0.10)^7 ≈ $100 * 1.9487 = ~$195."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Barclays Interview","Finance Brain Teasers","Basic"]},{"id":"q-1593","t":"mkt","l":"Basic","s":90,"q":"If I gave you $100,000 right now, what would you do with it?","k":["Structure your answer to show financial literacy and thoughtfulness:","Diversify across asset classes: Allocate a portion to a low-cost S&P 500 index fund for long-term equity exposure.","Fixed income allocation: Put some in investment-grade bonds or Treasury securities for stability.","Emergency reserve: Keep 3-6 months of expenses in a high-yield savings account.","Growth allocation: Invest a small portion in individual stocks or sectors with strong secular tailwinds (e.g., AI/technology infrastructure).","Education/career: Consider investing in skills or certifications that compound earning power.","The key is demonstrating awareness of risk-return tradeoffs, diversification, and time horizon -- not picking a single stock."],"collection":"practice","topic":"Finance Brain Teasers","tags":["New","Reported in Barclays Interview","SA 2025","Finance Brain Teasers","Basic"]},{"id":"q-1594","t":"mkt","l":"Basic","s":90,"q":"Which is greater: a 1% change in the discount rate or a 1% change in the terminal growth rate, in terms of its impact on a DCF valuation?","k":["A 1% shift in the discount rate moves NPV more than a 1% shift in g.","Key Drivers:","Discount rate: Re-prices every CF and TV.","Growth: Only tweaks the terminal value.","Scope: Multiple periods vs. one back-end lever."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Centerview Partners Interview","Finance Brain Teasers","Basic"]},{"id":"q-1595","t":"mkt","l":"Basic","s":90,"q":"How would you reduce (Debt – Cash) / EBITDA immediately without issuing more equity?","k":["One of the most direct ways is to generate net new cash and use it to pay down debt. Since you cannot issue more equity, you could:","Sell non-core assets and use the proceeds to repay outstanding debt.","Monetize working capital, for example by factoring receivables, accelerating collections, or reducing inventory levels.","Divest a non-strategic business unit to generate liquidity and allocate proceeds to debt reduction.","These steps reduce net debt (Debt – Cash) in the near term and improve (Debt – Cash) / EBITDA immediately without issuing new equity."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Citi Interview","Finance Brain Teasers","Basic"]},{"id":"q-1596","t":"mkt","l":"Basic","s":90,"q":"What is the fundamental difference between valuing a race horse and an apple tree?","k":["Speculative vs. Predictable: Race horses are valued speculatively, based on potential wins or breeding fees; apple trees have predictable, annuity-like cash flows from fruit sales.","Duration and Stability: Horses have short, volatile earning periods (injury, performance, span of career), while apple trees yield steady returns over many years."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Citi Interview","Finance Brain Teasers","Basic"]},{"id":"q-1597","t":"mkt","l":"Basic","s":90,"q":"Which has higher margins – a distribution company or a manufacturing company, and why?","k":["Typically, a manufacturing company has higher gross margins if it owns proprietary processes or brands. Distribution companies often have lower margins because they’re essentially middlemen, though it varies with industry specifics."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Citi Interview","Finance Brain Teasers","Basic"]},{"id":"q-1598","t":"mkt","l":"Basic","s":90,"q":"Pitch a stock idea.","k":["While this question is rare in investment banking interviews, it still comes up time to time.","For an interview, pick a company you know well, with a clear growth story, competitive advantage, stable cash flow, or undervaluation.","Summarize its business model, key metrics (P/E, EV/EBITDA), catalyst, and potential upside. Also outline the risk factors and why you still like it despite those risks.","Sample answer: Duolingo (DUOL) in 2025","Duolingo (NASDAQ: DUOL) leverages a freemium, AI-driven platform to scale language and emerging subject learning globally.","Strong growth drivers include a +49% year-over-year increase in daily active users, rapid international expansion (particularly strong in Latin America), and significant traction for its premium Max subscription tier (now accounting for 7% of subscribers). These factors are boosting revenue beyond expectations and improving margins, prompting Duolingo to raise its 2025 revenue guidance above consensus estimates, with gross margin improvements anticipated in the second half of the year.","Key upcoming catalysts are the introduction of new immersive AI experiences (like 3D video calls and DuoRadio), the launch of additional courses in areas such as math and chess, and increased penetration among English learners. While risks exist from intensified competition (particularly aggressive expansions from Big Tech players such as Google and specialized edtech startups), Duolingo's strong brand, proprietary data, and unmatched scale in AI-generated content substantially mitigate these threats."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Citi Interview","Finance Brain Teasers","Basic"]},{"id":"q-1599","t":"mkt","l":"Basic","s":90,"q":"From a financial perspective, how would you decide whether to buy a house or rent it?","k":["Compare the present value of all costs and benefits for each option:","Buying:","Upfront: Down payment, closing costs.","Ongoing: Mortgage payments (principal + interest), property taxes, maintenance, insurance, HOA fees.","Benefits: Build equity, potential appreciation, tax deductions (mortgage interest, property taxes).","Exit: Selling costs, capital gains tax (if applicable).","Renting:","Upfront: Security deposit.","Ongoing: Monthly rent, renter's insurance.","Benefits: Flexibility, no maintenance costs, liquidity of down payment invested elsewhere.","Use a discount rate (opportunity cost of capital) to calculate NPV of each option over your expected holding period. Consider non-financial factors: lifestyle, mobility, risk tolerance."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Credit Suisse Interview","Chicago office, First round","Finance Brain Teasers","Basic"]},{"id":"q-1600","t":"mkt","l":"Basic","s":90,"q":"Which is better: a 10% increase in volume, a 10% decrease in costs, or a 10% decrease in working capital?","k":["A 10% decrease in costs typically offers the greatest impact on net income (and recurring FCF).","Example (assuming no taxes for simplicity): Assume Revenue = 100 and Costs = 80, so Net Income (NI) = 20.","A 10% decrease in Costs makes them 72, so NI = 28, which is a 40% jump in NI.","A 10% increase in volume boosts Revenue to 110 but also increases Costs proportionally to 88, leading to NI of 22 (a 10% increase in NI).","A 10% decrease in working capital increases cash flow once but does not improve Net Income or recurring EBITDA.","Thus, reducing Costs by 10% is generally the most beneficial among the options given."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Evercore Interview","Finance Brain Teasers","Basic"]},{"id":"q-1601","t":"mkt","l":"Basic","s":90,"q":"Why would two companies that do the same thing have different betas?","k":["Differences in capital structure, operational leverage, and business models can cause companies in the same industry to have different betas.","Additionally, factors like geographic diversification and management effectiveness can influence systematic risk."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Evercore Interview","Finance Brain Teasers","Basic"]},{"id":"q-1602","t":"mkt","l":"Basic","s":90,"q":"You buy a company for $100 million with 100% equity and sell it 5 years later for the same price.\n\n\n\n\nWhy might you still earn an attractive return?","k":["You might have taken out dividends or distributions over time, or improved the balance sheet and extracted cash. Also, you may have reduced the company’s debt (and captured interest tax shields) if it previously had leveraged recap structures, effectively receiving value without changing final sale price."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Evercore Interview","Finance Brain Teasers","Basic"]},{"id":"q-1603","t":"mkt","l":"Basic","s":90,"q":"If a professor borrows $100 from you, how would you decide upon an interest rate?","k":["You’d assess the risk of default (likely low if she has stable employment), maybe set an interest rate just above risk-free or consider her credit profile.","Essentially, it’s a miniature credit decision: weigh the time frame, the borrower’s capacity to repay, and the opportunity cost of your capital."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Goldman Sachs Interview","Finance Brain Teasers","Basic"]},{"id":"q-1604","t":"mkt","l":"Basic","s":90,"q":"If I offer to give you $1 per year forever, how much would you pay me for that right now?","k":["The amount depends on your required rate of return.","Calculation:","This is a perpetuity","Present Value = Annual Payment / Discount Rate","PV = $1 / r","If r = 5%, PV = $1 / 0.05 = $20","If r = 10%, PV = $1 / 0.10 = $10","The answer depends on the risk-free rate, your opportunity cost of capital, and the creditworthiness of the payer. A reasonable answer might be $10-$20 assuming a 5-10% discount rate."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Goldman Sachs Interview","Superday","Finance Brain Teasers","Basic"]},{"id":"q-1605","t":"mkt","l":"Basic","s":90,"q":"If we give you an offer today, what will you choose: $200,000 upfront or the square root of $10 million paid monthly? How does your answer change depending on how long the payments last?","k":["It depends on how long the monthly payments last.","The square root of $10,000,000 = ~$3,162 per month.","Scenario 1: Finite payments (e.g., 5 years)","Breakeven on a nominal basis: $200,000 / $3,162 = ~63 months (~5.3 years). So if payments last 5 years or fewer, take the $200K upfront.","On a present-value basis with a 5% annual discount rate (~0.4% monthly), 63 months of $3,162/month has a PV of only ~$175K, so the breakeven is even longer.","Scenario 2: Perpetual payments","If the $3,162/month lasts forever, PV of a perpetuity = $3,162 / (5% / 12) = $3,162 / 0.00417 = ~$759K.","That is nearly 4x the $200K lump sum, making the monthly payments far more valuable.","Key insight:","The right answer hinges on the duration and the discount rate. For short durations (under ~5 years), take the $200K. For long or perpetual durations, the monthly payments dominate. In an interview, you should recognize this ambiguity and walk through both scenarios rather than jumping to one conclusion."],"collection":"practice","topic":"Finance Brain Teasers","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","Finance Brain Teasers","Basic"]},{"id":"q-1606","t":"mkt","l":"Basic","s":90,"q":"What are some ways a company can de-lever? What are some ways a company can raise liquidity?","k":["De-levering:","Paying down existing debt.","Converting debt to equity.","Using cash reserves to reduce debt levels.","Raising Liquidity:","Issuing new equity or debt.","Selling non-core assets.","Improving operational cash flows."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Greenhill & Co. Interview","Finance Brain Teasers","Basic"]},{"id":"q-1607","t":"mkt","l":"Basic","s":90,"q":"What are the types of covenants?","k":["Financial Covenants: Require the borrower to maintain certain financial metrics, such as debt-to-equity ratio or interest coverage ratio.","Negative Covenants: Restrict the borrower from undertaking specific actions, like incurring additional debt or selling key assets.","Positive Covenants: Require the borrower to perform certain actions, such as maintaining insurance or providing regular financial statements."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Greenhill & Co. Interview","Finance Brain Teasers","Basic"]},{"id":"q-1608","t":"mkt","l":"Basic","s":90,"q":"Rank these assets’ betas from lowest to highest: a utilities company, a technology company, a $1 slot machine with the chance to win $5.","k":["Ranked betas from lowest to highest:","A slot machine has a beta of zero because it has no market correlation.","A utilities company has a beta less than 1, as it moves more slowly than market averages.","A technology company has the highest beta, reflecting higher volatility and expected returns."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Greenhill & Co. Interview","Finance Brain Teasers","Basic"]},{"id":"q-1609","t":"mkt","l":"Basic","s":90,"q":"You are offered two choices:\n\n\n\n$100 today\n$110 in one year\n\n\n\nWhich option is preferable and why?\n\n\n\n\nFollow‑up: Using a 10% required return, how much would you accept today instead of receiving $100 in one year? (Round to the nearest dollar.)","k":["You are indifferent at exactly a 10% required return; if you can reinvest at >10% you prefer $100 today, otherwise take $110 in one year.","Follow-up:","Present value of $100 in one year at 10% is roughly $91.","PV = 100 / (1 + 10%) ≈ 91","Trial and error can help make an informed guess: 90 * 1.1 = 99 (too low) while 92 * 1.1 = 101 (too high)"],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Guggenheim Partners Interview","Finance Brain Teasers","Basic"]},{"id":"q-1610","t":"mkt","l":"Basic","s":90,"q":"Would you rather have $100 today or $110 one year from now?","k":["It depends on the discount rate (your opportunity cost of capital). If your discount rate is below 10%, the $110 in one year is worth more than $100 today. If your discount rate is above 10%, $100 today is worth more.","At a 10% discount rate: PV of $110 = $110 / 1.10 = $100, so you are indifferent.","In most practical contexts (current risk-free rates around 4-5%), $110 in one year has a present value of ~$105, so you would prefer the $110 in one year. However, if you have a high-return investment opportunity or face significant inflation/risk, you might prefer $100 today."],"collection":"practice","topic":"Finance Brain Teasers","tags":["New","Reported in Guggenheim Partners Interview","SA 2025","Finance Brain Teasers","Basic"]},{"id":"q-1611","t":"mkt","l":"Basic","s":90,"q":"Is an increase in inventory a cash source or cash outflow? What about an increase in payables?","k":["Increase in Inventory: It is a cash outflow. When inventory increases, the company spends cash to purchase more inventory, reducing available cash.","Increase in Payables: It is a cash source. When payables increase, the company delays paying its suppliers, thereby retaining cash longer."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Houlihan Lokey Interview","Finance Brain Teasers","Basic"]},{"id":"q-1612","t":"mkt","l":"Basic","s":90,"q":"What is the current prime rate?","k":["This changes over time, often tied to the Fed Funds Rate plus a certain spread (commonly 3%). You’d quote the latest figure (e.g., if the Fed Funds Rate is 5%, the prime might be around 8%).","Always check a reliable financial source (e.g., Fed data or a financial news site) for the most recent update."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in J.P. Morgan Interview","Finance Brain Teasers","Basic"]},{"id":"q-1613","t":"mkt","l":"Basic","s":90,"q":"What issues typically keep a CEO awake at night?","k":["Strategy, competition, talent retention, supply chain disruptions, market volatility, reputation, regulatory changes, and macroeconomic conditions often concern CEOs."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in J.P. Morgan Interview","Finance Brain Teasers","Basic"]},{"id":"q-1614","t":"mkt","l":"Basic","s":90,"q":"Imagine you are a CFO with $10mm in cash. What are some ways to create shareholder value with it?","k":["Repurchase shares.","Increase or issue dividends.","Invest in positive‑NPV projects.","Pursue bolt‑on acquisitions.","Pay down high‑cost debt.","Fund R&D or capex that raises ROIC."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in J.P. Morgan Interview","SA 2025, New York office, Superday","Finance Brain Teasers","Basic"]},{"id":"q-1615","t":"mkt","l":"Basic","s":90,"q":"What are some ways the market is impacted by an increase in interest rates?","k":["Higher discount rates compress equity and bond valuations.","Borrowing costs rise, slowing capex and M&A.","Sector rotation toward value and short‑duration assets.","Stronger domestic currency through yield differentials.","Curve shifts may pressure bank NIMs and mortgage demand."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in J.P. Morgan Interview","SA 2025, New York office, Superday","Finance Brain Teasers","Basic"]},{"id":"q-1616","t":"mkt","l":"Basic","s":90,"q":"Would you rather receive $1 million today or $100,000 per year for the rest of your life?\n\n\n\n\nWhat does your decision depend on?","k":["The decision depends on:","Life Expectancy: If you live > 10 years, $100k/year totals more than $1M.","Discount Rate / Time Value of Money: $1M today can be invested to potentially earn > $100k annually.","Investment Returns: If you can earn > 10% annually on $1M, take lump sum. If not, annuity may be better.","Risk Tolerance: Lump sum carries investment risk; annuity provides certainty but inflation risk.","Liquidity Needs: Lump sum offers immediate access for large purchases or investments.","Tax Considerations: Lump sum taxed immediately; annuity spreads tax burden over time.","Generally, if you're young, healthy, and can invest effectively, the $1M lump sum is preferable. Break-even is ~10 years of $100k payments."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in J.P. Morgan Interview","SA 2025","Finance Brain Teasers","Basic"]},{"id":"q-1617","t":"mkt","l":"Basic","s":90,"q":"If you were to build a new company, where would you put it and why?","k":["Considerations for location:","Talent Pool: Access to skilled labor (e.g., tech hubs like SF, Austin, or Boston).","Cost of Operations: Real estate, labor costs, tax environment (e.g., Texas, Florida for lower taxes).","Customer Proximity: Near target customers or distribution channels.","Infrastructure: Transportation, logistics, technology infrastructure.","Regulatory Environment: Business-friendly regulations, ease of incorporation.","Ecosystem: Presence of investors, suppliers, partners, and industry peers.","Quality of Life: Attract and retain talent with lifestyle appeal.","Example: A software startup might choose Austin for talent, low taxes, and thriving tech ecosystem. A manufacturing company might choose a state with logistics infrastructure and lower labor costs."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in J.P. Morgan Interview","SA 2026, New York Office","Finance Brain Teasers","Basic"]},{"id":"q-1618","t":"mkt","l":"Basic","s":90,"q":"Can you name a company or an asset with a beta of zero?","k":["A 3‑month U.S. Treasury bill is effectively β ≈ 0.","Explanation:","Beta measures covariance with the market portfolio.","Risk‑free assets are uncorrelated with market movements by definition, yielding a beta of ~0."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Moelis & Co. Interview","Finance Brain Teasers","Basic"]},{"id":"q-1619","t":"mkt","l":"Basic","s":90,"q":"How would you invest a stock portfolio?","k":["Sample answer","I would use a simple, ultra-low-cost three-fund Bogleheads portfolio anchored by VOO.","Allocation:","VOO – 50%: US large-cap core via low-cost S&P 500.","VXUS – 25%: international equities for style, size, and country diversification.","BND – 25%: total US bond market for stability and income.","Why it works:","Diversifies across >10,000 global securities.","Ultra-low fees and tax-efficient structure.","No manager risk, style drift, overlap, or front running.","Low turnover, easy quarterly rebalancing.","Mathematically likely to outperform most active investors."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Moelis & Co. Interview","Finance Brain Teasers","Basic"]},{"id":"q-1620","t":"mkt","l":"Basic","s":90,"q":"Would you be more or less likely to use your credit card if interest rates went down?\n\n\n\n\nWhy?","k":["More likely.","Lower policy rates flow through to lower card APRs, reducing the cost of carrying a balance and making revolving credit cheaper relative to cash or debit."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Morgan Stanley Interview","SA 2026, New York office, First round","Finance Brain Teasers","Basic"]},{"id":"q-1621","t":"mkt","l":"Basic","s":90,"q":"MULTI-STEP:\n\n\n\n\nWould you rather get $1mm right now or $100k every year indefinitely? Why?\n\n\n\n\nFollow-up: What if it's $100k for 10 years? Why?","k":["Indefinite stream wins at discount rates > 0 % and < 10 %; one‑time wins for higher rates or short stream.","Perpetuity math:","PV = $100 k ÷ r. At r = 8 % → PV ≈ $1.25 mm > $1 mm.","Breakeven r = 10 % (100 k ÷ 0.10 = 1 mm).","Ten‑year annuity:","PV at 8 % ≈ $100 k × 6.71 = $671 k < $1 mm → choose lump sum.","The choice hinges on discount rate and stream length—core time‑value‑of‑money intuition."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Morgan Stanley Interview","SA 2026, New York office, First round","Finance Brain Teasers","Basic"]},{"id":"q-1622","t":"mkt","l":"Basic","s":90,"q":"How would you explain the concept of cost of equity to a child?","k":["Cost of equity is what investors expect to earn for taking the risk of owning a piece of the company.","It's like when you lend your friend money for their lemonade stand - you want them to pay you back more than you gave them because there's a chance they might not succeed.","The riskier the lemonade stand (maybe it's in a bad location or faces competition), the more extra money you'd want back. That \"extra\" is the cost of equity."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Morgan Stanley Interview","New York Office, First round","Finance Brain Teasers","Basic"]},{"id":"q-1623","t":"mkt","l":"Basic","s":90,"q":"Would the beta for a technology company or a furniture manufacturing company likely be higher? Why?\n\n\n\n\nAs a follow-up, what would be the beta of a lottery ticket?","k":["Tech β > Furniture because tech revenues are more volatile and growth‑dependent on market sentiment; a lottery ticket’s beta is ~0 as pay‑offs are independent of economic cycles.","Explanation:","High‑growth sectors swing with risk appetite, boosting covariance with the market.","Staple manufacturers have steadier demand and lower operating leverage.","Lottery outcomes are random, not market‑driven, so systematic risk is negligible."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in PJT Partners Interview","Finance Brain Teasers","Basic"]},{"id":"q-1624","t":"mkt","l":"Basic","s":90,"q":"You are analyzing a bond that matures in exactly one year. It has a face value of $100, a coupon rate of 5%, and is currently trading at a price of $90. What is its yield to maturity?","k":["≈ 16.7%.","For a one-period bond, YTM = (coupon + redemption – price) / price.","Calculation:","Total return = $5 coupon + $10 price accretion = $15.","Yield = $15 / $90 = 1 / 6 = 0.1667."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in PJT Partners Interview","Finance Brain Teasers","Basic"]},{"id":"q-1625","t":"mkt","l":"Basic","s":90,"q":"You buy a share for $20. The company issues $1 in dividend before you sell the share for $25. What is the total return?","k":["The gain is $5 from the stock price appreciation (25 – 20) plus $1 in dividend, for $6 total.","Return = $6 / $20 initial investment = 30%."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in RBC Interview","Finance Brain Teasers","Basic"]},{"id":"q-1626","t":"mkt","l":"Basic","s":90,"q":"What is the yield of an investment that costs $100 today, provides a $2 payment each year for 19 years, and returns $102 in the 20th year?","k":["The yield is slightly higher than 2%.","This investment is similar to a bond with a 2% coupon, but it includes an additional $2 capital gain at maturity ($102 repayment vs. $100 cost). Therefore, the total return must be greater than the 2% coupon rate.","The precise Yield to Maturity (YTM) is the discount rate 'r' that solves the equation:","$100 = Σ [$2 / (1+r)^t] for t=1 to 19 + [$102 / (1+r)^20]","Because the final payment is greater than par, the YTM will be slightly above 2%."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Unspecified Interview","Finance Brain Teasers","Basic"]},{"id":"q-1627","t":"mkt","l":"Basic","s":90,"q":"You have three companies with EBITDA margins of 50%, 15%, and 5%.\n\n\n\n\nMatch these margins to the following business types and explain your rationale:\n\n\n\nA branded retailer\nA telecom player\nA mom & pop supplier","k":["Telecom player: 50% EBITDA margin","Branded retailer: 15% EBITDA margin","Mom & pop supplier: 5% EBITDA margin","Telecom companies have high margins due to significant infrastructure investment creating barriers to entry, recurring revenue models, and high operating leverage once networks are built.","Branded retailers achieve moderate margins through brand pricing power and scale, but face inventory costs, retail operations, and marketing expenses.","Mom & pop suppliers operate with thin margins due to limited scale, intense competition, minimal pricing power, and high operating costs relative to revenue."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Unspecified Interview","Finance Brain Teasers","Basic"]},{"id":"q-1628","t":"mkt","l":"Basic","s":90,"q":"If you were given $1 billion, what would you do with it?","k":["This is an open-ended question testing investment philosophy and creativity. Sample framework:","Personal vs. Investment decision:","Acknowledge you'd secure personal financial stability first (conservative allocation)","Then deploy the remainder strategically","Investment approach:","Diversified portfolio: Public equities, PE/VC funds, real estate, alternatives","Active investing: Specific sector thesis (e.g., AI infrastructure, climate tech)","Operating business: Acquire and improve a platform company with roll-up strategy","Support your answer with clear reasoning about risk/return, time horizon, and value creation."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Unspecified Interview","Finance Brain Teasers","Basic"]},{"id":"q-1629","t":"mkt","l":"Basic","s":90,"q":"If a project's Net Present Value (NPV) is zero when using a 10% discount rate, what is its Internal Rate of Return (IRR)?","k":["Answer: 10%","The IRR is the discount rate that makes NPV equal to zero. If NPV = 0 at a 10% discount rate, then the IRR is 10%."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Unspecified Interview","Finance Brain Teasers","Basic"]},{"id":"q-1630","t":"mkt","l":"Advanced","s":90,"q":"Would you rather have a 25% IRR over five years or a 3x Multiple on Invested Capital (MOIC)?","k":["It depends on the investment horizon and risk preference. A 25% IRR over five years indicates strong annual growth, effectively multiplying the investment by approximately 3x (compound).","However, a straightforward 3x MOIC might offer certainty without the time value considerations. Generally, a 25% IRR is preferable as it implies a higher return rate."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Ares Management Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1631","t":"mkt","l":"Advanced","s":90,"q":"Would you rather have a 35% IRR over 2 years or a 20% IRR over 4 years?","k":["Answer: Ignoring reinvestment or risk differences, a 20 % IRR held for four years compounds to a higher MOIC (~2.07×) than a 35 % IRR held for two years (~1.82×), even though the latter returns cash sooner and boasts a higher annualized rate.","Explanation:","While a 35% IRR over 2 years feels very attractive on an annualized basis, in absolute dollar‐multiple terms the 20% IRR over 4 years actually delivers a higher total return.","Here’s the calculation for total multiples:","For a 35% IRR over 2 years: (1 + 0.35)2 = 1.352 = 1.8225 ≈ 1.82× return.","For a 20% IRR over 4 years: (1 + 0.20)4 = 1.24 = 2.0736 ≈ 2.07× return.","Therefore, the 20% IRR over 4 years yields a higher total cash‐on‐cash multiple (2.07× vs. 1.82×), whereas the 35% IRR over 2 years gives you a faster return and higher annualized rate.","Note that this comparison assumes isolated investments (i.e. assumes that you can’t immediately reinvest the 2-year proceeds at 35%). In reality, ability to redeploy funds, differing risk profiles, interim cash flows, or fund-level liquidity considerations can materially affect which option is superior."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Ares Management Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1632","t":"mkt","l":"Advanced","s":90,"q":"How would you estimate your personal Beta?","k":["Conceptual approach to personal beta:","Beta measures systematic risk relative to the market.","Your \"returns\" would be income/wealth changes over time.","Compare your income volatility to overall economic/market performance.","Stable government job = low beta (<1). Tech startup employee = high beta (>1).","Diversified income streams lower personal beta.","Exposure to cyclical industries increases beta.","Essentially, assess how correlated your financial outcomes are to broader economic cycles."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Bank of America Interview","New York Office, First round","Finance Brain Teasers","Advanced"]},{"id":"q-1633","t":"mkt","l":"Advanced","s":90,"q":"A company's Debt/EBITDA ratio is currently 6.0x. If EBITDA increases by 20%, by what percentage must debt decrease to achieve a target Debt/EBITDA ratio of 4.0x?","k":["Answer: 20%","Calculation:","Initial: Debt/EBITDA = 6.0x, so Debt = 6.0 × EBITDA","New EBITDA = 1.20 × EBITDA","Target: New Debt / (1.20 × EBITDA) = 4.0x","New Debt = 4.0 × 1.20 × EBITDA = 4.8 × EBITDA","Debt reduction = (6.0 - 4.8) / 6.0 = 1.2 / 6.0 = 20%"],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Citi Interview","New York Office","Finance Brain Teasers","Advanced"]},{"id":"q-1634","t":"mkt","l":"Advanced","s":90,"q":"From a debt investor's perspective, which is a better credit risk:\n\n\n\nA company with a 10-year government contract.\nAn early-stage tech company with 1-year software subscriptions.\n\n\n\nFollow-up: How does your answer change if the tech company's subscriptions are guaranteed to renew?","k":["The company with the 10-year government contract is the better credit risk.","Reasoning:","Revenue Visibility: 10-year contract provides certainty.","Counterparty Risk: Government has minimal default risk vs. corporate customers.","Cash Flow Stability: Predictable, contracted cash flows.","Tech Company Risk: Early-stage with 1-year subscriptions has high churn risk, execution risk, and limited track record.","Follow-up:","If the tech company's subscriptions are guaranteed to renew, it improves credit quality significantly but likely still inferior to the government contract due to counterparty concentration risk and business model maturity questions."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Credit Suisse Interview","FSG group, First round","Finance Brain Teasers","Advanced"]},{"id":"q-1635","t":"mkt","l":"Advanced","s":90,"q":"You are a debt investor evaluating two companies:\n\n\n\nAn enterprise software company.\nA copper wire manufacturer.\n\n\n\nAnswer the following:\n\nWhich is more attractive for a debt investor and why?\nWhat criteria would you use to evaluate these two businesses?\nWhich company is likely to have more stable cash flows?\nHow would their working capital cycles differ, and what is the impact on cash flow?","k":["Part 1: More Attractive","Enterprise software is generally more attractive due to recurring revenue, high margins, negative working capital, and asset-light model.","Part 2: Evaluation Criteria","Revenue predictability and growth.","Margin profile and cash generation.","Working capital requirements.","Cyclicality and economic sensitivity.","Customer concentration and retention.","Asset intensity and CapEx needs.","Part 3: Stable Cash Flows","Enterprise software has more stable cash flows due to subscription model and high retention rates. Copper manufacturer faces commodity price volatility and cyclical demand.","Part 4: Working Capital Cycles","Software: Negative WC cycle (upfront subscription payments before service delivery). Improves cash flow.","Manufacturer: Positive WC cycle (must purchase raw materials, hold inventory, extend receivables). Consumes cash as growth accelerates."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Credit Suisse Interview","FSG group, Superday","Finance Brain Teasers","Advanced"]},{"id":"q-1636","t":"mkt","l":"Advanced","s":90,"q":"Assume a bond is trading at $80, has a face value of $100, a 10% coupon, and has 1 year to maturity. What's its YTM?","k":["For a bond with one year to maturity, the exact Yield to Maturity (YTM) is its total return divided by the current price. The approximate formula is not needed.","The total return is the coupon payment plus the capital gain from the price appreciating to its face value.","YTM = (Coupon Payment + Face Value - Current Price) / Current Price","YTM = ($10 + $100 - $80) / $80 = $30 / $80 = 37.5%"],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Evercore Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1637","t":"mkt","l":"Advanced","s":90,"q":"Company A is a refrigerator company in Vegas, and Company B has a 50% chance of making either $1M or $0M of FCF every year. Which company has a higher beta and why?","k":["Company A, the refrigerator company in Vegas, is likely to have a higher beta.","Company A (Refrigerators in Vegas): Demand for refrigerators will typically rise and fall with the broader economy (more housing starts, more hospitality spending, and so on). In other words, its cash flows should be positively correlated with the overall market cycle.","Company B (50% chance of $1M or $0): While this is a risky company (cash flows are quite volatile), that volatility may be uncorrelated with the general economy. If the outcome is essentially a coin toss every year, it may have little to do with whether the stock market or the broader business cycle is up or down.","Despite Company B’s earnings being riskier in absolute terms, Company A’s cash flows are more tied to the economy, so it’s likely to have the higher beta."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Evercore Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1638","t":"mkt","l":"Advanced","s":90,"q":"Rank the following in terms of impact on Free Cash Flow (FCF): $10 million increase in Revenue (assuming 100% margin on incremental revenue), $10 million decrease in Depreciation & Amortization (D&A), and $10 million decrease in Capital Expenditures (CapEx).\n\n\n\n\nThen, rank them in terms of impact on Terminal Value.","k":["Assume a tax rate of T.","Ranking (Impact on FCF):","Decrease in CapEx: Directly increases FCF by +$10M.","Increase in Revenue: Increases FCF by +$10M * (1 - T).","Decrease in D&A: Decreases FCF by -$10M * (T) due to the lost tax shield.","Impact on Terminal Value:","Multiples Method (EBITDA-based):","Revenue increase directly boosts EBITDA, thus increasing TV.","CapEx and D&A changes do not affect EBITDA, resulting in no direct TV impact.","Perpetuity Growth Method (FCF-based):","Decrease in CapEx: Highest positive impact (+$10M to FCF).","Increase in Revenue: Moderate positive impact (+$10M * (1 - T)).","Decrease in D&A: Negative impact (-$10M * T)."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Evercore Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1639","t":"mkt","l":"Advanced","s":90,"q":"You have $100 million in Revenue and $20 million in EBITDA. What happens to EBITDA if Revenue increases by 10%? Ask any questions necessary to gain clarity.","k":["Question to Ask: What is the operating leverage? (Fixed vs Variable cost split).","Assumption: Fixed Costs and Variable Costs are equal (50/50 split of total costs).","Calculation:","Total Costs = $100M Rev - $20M EBITDA = $80M.","Split: $40M Fixed, $40M Variable.","Revenue increases 10% to $110M.","Variable costs increase 10% to $44M. Fixed stays at $40M.","New EBITDA = $110M - $44M - $40M = $26M.","Therefore, EBITDA increases by $6 million to $26 million."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Evercore Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1640","t":"mkt","l":"Advanced","s":90,"q":"What are some factors that could lead to decreasing margins?","k":["Margins may be decreasing due to several factors:","Increased Costs: Rising costs of goods sold (COGS) or operating expenses without a corresponding increase in revenue.","Price Pressure: Competitive pressures forcing the company to lower prices.","Operational Inefficiencies: Production issues leading to higher costs.","Change in Product Mix: A shift towards lower-margin products.","External Factors: Inflation, regulatory changes, or supply chain disruptions.","(Note: Depreciation changes Operating Margins but not EBITDA margins)."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Evercore Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1641","t":"mkt","l":"Advanced","s":90,"q":"Why might a company willingly decrease its margins?","k":["A company might willingly decrease its margins for strategic reasons, such as:","Market Share Expansion: Lowering prices to increase sales volume and capture greater market share, making it harder for competitors to compete.","Economies of Scale: Investing in growth opportunities that may initially reduce margins but lead to higher efficiencies and profitability in the long run.","Competitive Positioning: Differentiating products or services through pricing strategies to position the company as a cost leader.","Entry into New Markets: Reducing margins to establish a presence in new geographic or product markets.","Product Penetration: Encouraging adoption of new products or services by offering them at lower margins initially.","Strategic Acquisitions: Lowering margins to fund acquisitions or other strategic investments.","For example, companies like Uber and Lyft initially operated with low or negative margins to rapidly grow their user base and establish dominance in the market before focusing on profitability."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Evercore Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1642","t":"mkt","l":"Advanced","s":90,"q":"A bond with $100 face value trades at $80 today.\n\n\n\n\nIt has a 10% annual coupon and matures in 2 years.\n\n\n\n\nWhat is its yield to maturity?","k":["Answer: ~22.22% (2/9)","YTM = [C + ((F - P) / n)] / [(F + P) / 2]","YTM = [10 + ((100 - 80) / 2)] / [(100 + 80) / 2]","YTM = [10 + 10] / 90 = 2 / 9 = ~22.22%","Note that this (standard) formula is an approximation as opposed to a precise figure. The standard YTM calculation assumes all coupon payments occur on time and that each coupon is reinvested at the same rate (prone to error)."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Evercore Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1643","t":"mkt","l":"Advanced","s":90,"q":"You have a bond with a face value of $100 and 10% PIK interest, and you hold it for 3 years. If you want a 25% IRR, how much can you pay for the bond?","k":["Answer: $68.15","Calculation:","PIK interest accrues to the principal, so no cash is received until maturity.","After 3 years, the bond pays: $100 x (1.10)^3 = $133.10","To earn a 25% IRR: Price x (1.25)^3 = $133.10","Price = $133.10 / 1.953125 = $68.15"],"collection":"practice","topic":"Finance Brain Teasers","tags":["New","Reported in Evercore Interview","SA 2027, New York Office, Second round","Finance Brain Teasers","Advanced"]},{"id":"q-1644","t":"mkt","l":"Advanced","s":90,"q":"How much would you pay for an investment that pays you one dollar per day, forever?\n\n\n\n\nDoes it matter if the payments come from a private individual versus a financial institution?","k":["This is a perpetuity: PV = Annual Payment / Discount Rate","Annual payment = $365. If discount rate is 5%, PV = $365 / 0.05 = $7,300.","Yes, the source matters significantly:","Financial institution: Lower risk, lower discount rate, higher valuation.","Private individual: Higher default risk, higher discount rate, lower valuation.","You would pay more for institutional payments due to creditworthiness and reliability."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Goldman Sachs Interview","New York Office, First round","Finance Brain Teasers","Advanced"]},{"id":"q-1645","t":"mkt","l":"Advanced","s":90,"q":"You have two identical companies with prices always increasing. One has higher operating leverage and the other has lower operating leverage. Which one would you invest in?","k":["Investing in the company with higher operating leverage can lead to greater profitability during periods of increasing sales due to higher fixed costs being spread over more units. Therefore, if prices are consistently increasing, the higher operating leverage company may offer better returns."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Greenhill & Co. Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1646","t":"mkt","l":"Advanced","s":90,"q":"A company has had positive EBITDA for 10 years. At the end of year 10, they file for bankruptcy. How is this possible?","k":["Despite having positive EBITDA, a company can still file for bankruptcy due to several reasons:","High Debt Levels: Excessive debt obligations can lead to significant interest payments, draining cash flow.","Negative Net Cash Flow: High capital expenditures or working capital needs can result in negative free cash flow.","Declining Revenue or Profit Margins: Even with positive EBITDA, declining sales or margins can erode profitability.","Operational Issues: Inefficiencies, increased costs, or poor management decisions can impact financial stability.","External Factors: Economic downturns, regulatory changes, or loss of key customers can force a company into bankruptcy."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Greenhill & Co. Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1647","t":"mkt","l":"Advanced","s":90,"q":"What is the market capitalization of a company with the following attributes?\n\n$2 billion in assets\nDebt-to-Equity ratio of 3x\nPrice-to-Book Value ratio (P/BV) of 2x","k":["The market capitalization is $1 billion.","Here’s the calculation:","Assets = Liabilities + Shareholders' Equity.","If Assets = $2 billion, then Liabilities + Shareholders' Equity = $2 billion.","With a Debt-to-Equity ratio of 3x, Liabilities = $1.5 billion and Shareholders' Equity = $0.5 billion.","Book Value (BV) is equal to Shareholders' Equity, which is $0.5 billion.","Given a Price-to-Book Value ratio (P/BV) of 2x, the market capitalization = 2 x $0.5 billion = $1 billion."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in J.P. Morgan Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1648","t":"mkt","l":"Advanced","s":90,"q":"What is your personal beta?","k":["This is a creative question that uses a finance concept metaphorically. Beta measures volatility relative to a benchmark. The interviewer wants to understand your temperament and how you respond to external pressure.","A strong answer is a beta close to or slightly below 1.0 — meaning you are steady and reliable under pressure, not prone to extreme emotional swings, but still responsive and engaged.","Explain your reasoning. For example: \"I'd say my beta is around 0.8 — I stay calm and focused when things get chaotic, which allows me to make clear-headed decisions. But I'm not so low-beta that I lack urgency or energy.\"","Support it with a brief example that demonstrates your temperament in a high-pressure situation."],"collection":"practice","topic":"Finance Brain Teasers","tags":["New","Reported in Jefferies Interview","SA 2026, First round","Finance Brain Teasers","Advanced"]},{"id":"q-1649","t":"mkt","l":"Advanced","s":90,"q":"You have the opportunity to invest in three different companies using three different investment structures. You must use each structure exactly once.\n\n\n\n\nThe companies are a startup casino, a stable, mature technology company, and a fast-growing, pre-profitability technology company.\n\n\n\n\nThe investment structures are preferred equity, convertible debt, and senior secured debt.\n\n\n\n\nMatch each investment structure to one company and justify your reasoning.","k":["Answer:","Startup casino → preferred equity","Mature tech → senior secured debt","Fast‑growing tech → convertible debt","Explanation:","Preferred equity absorbs casino risk while ranking ahead of common for downside protection.","Senior secured debt suits mature tech because predictable cash flows service interest and collateralize debt.","Convertible debt offers lenders fixed income today and equity upside once the high‑growth tech firm turns profitable."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Lazard Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1650","t":"mkt","l":"Advanced","s":90,"q":"A bond with a par value of $100 and a 10% annual coupon is maturing in 3 years. It is currently trading at $70.\n\n\n\n\nWhat is its approximate Yield to Maturity (YTM)? No calculator, just pen and paper.","k":["Answer: Approximately 23.5%","To approximate the Yield to Maturity (YTM), we use the following formula:","YTM ≈ [Annual Coupon + ((Face Value - Price) / Years to Maturity)] / [(Face Value + Price) / 2]","Calculation:","C = $10 (10% of $100)","F = $100","P = $70","n = 3","YTM ≈ [$10 + (($100 - $70) / 3)] / [($100 + $70) / 2]","YTM ≈ [$10 + ($30 / 3)] / [$170 / 2]","YTM ≈ [$10 + $10] / $85","YTM ≈ $20 / $85 ≈ 23.53%"],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Lazard Interview","New York office","Finance Brain Teasers","Advanced"]},{"id":"q-1651","t":"mkt","l":"Advanced","s":90,"q":"You are analyzing a bond with a face value of $100 that is due in two years. It has a 10% annual coupon and is currently trading at $90.\n\n\n\n\nAnswer the following:\n\nConceptually, how do you determine the Yield to Maturity (YTM)? Is it greater or less than the 10% coupon rate?\nOne year passes, and the bond is still trading at $90. What has happened to its YTM and why?\nHow could you derive a market-based proxy for changes in the issuer's default risk over that year?","k":["Part 1: YTM Concept","YTM is the discount rate that equates the present value of all future cash flows to the current bond price.","Since the bond trades at $90 (below par), the YTM must be greater than the 10% coupon rate to compensate for the discount.","Part 2: YTM After One Year","The YTM has increased significantly.","After one year at $90, there's only one year until maturity. The bond will still pay $10 coupon plus $100 principal, but the holding period is shorter, so the effective yield has risen.","Part 3: Default Risk Proxy","Compare the credit spread (YTM minus risk-free rate) at both points in time.","An increasing spread suggests higher perceived default risk; a decreasing spread suggests improving credit quality."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Lazard Interview","New York Office, First round","Finance Brain Teasers","Advanced"]},{"id":"q-1652","t":"mkt","l":"Advanced","s":90,"q":"A company has a leverage ratio of 5x and an interest coverage ratio of 6x. What is the cost of debt?","k":["Answer: 3.33%","Leverage Ratio = Debt / EBITDA = 5x, so Debt = 5 * EBITDA.","Interest Coverage Ratio = EBITDA / Interest Expense = 6x, so Interest Expense = EBITDA / 6.","Cost of Debt = Interest Expense / Debt = (EBITDA / 6) / (5 * EBITDA) = 1 / 30 = 3.33%."],"collection":"practice","topic":"Finance Brain Teasers","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, First round","Finance Brain Teasers","Advanced"]},{"id":"q-1653","t":"mkt","l":"Advanced","s":90,"q":"A U.S. lottery ticket has a 50% chance of paying out $100 and a 50% chance of paying out $0. The cash flows are received one year in the future. How much would you pay for this ticket?","k":["Answer: Less than $50, but the exact amount depends on the discount rate and risk preference.","Expected Value = 50% x $100 + 50% x $0 = $50.","Since cash is received in one year, discount to present: PV = $50 / (1 + r).","Using the risk-free rate (~4-5%): PV = $50 / 1.05 = ~$47.62.","However, a risk-averse investor would apply a higher discount rate to account for the binary risk, paying less (e.g., $40-45).","Also consider: lottery winnings may be taxable, further reducing the expected after-tax payout."],"collection":"practice","topic":"Finance Brain Teasers","tags":["New","Reported in M. Klein & Co. Interview","SA 2027, Second round","Finance Brain Teasers","Advanced"]},{"id":"q-1654","t":"mkt","l":"Advanced","s":90,"q":"A bond with a face value of $100 is currently trading at $80 and has a 10% coupon.\n\n\n\n\nIf you sell the bond in 4 years at par, what is the approximate IRR?","k":["Answer: ~18.9%","Calculation:","Initial investment = $80","Annual coupon = $100 * 10% = $10","Total coupons over 4 years = $10 * 4 = $40","Sale proceeds at par = $100","Total cash received = $40 + $100 = $140","Using IRR formula: $80 = $10/(1+r) + $10/(1+r)² + $10/(1+r)³ + $110/(1+r)⁴","Solving: r ≈ 18.9%","Quick approximation: Average annual gain = ($140 - $80) / 4 = $15. Average capital = ($80 + $100) / 2 = $90. IRR ≈ $15 / $90 = 16.7% (understates true IRR due to compounding)."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Miller Buckfire Interview","First round","Finance Brain Teasers","Advanced"]},{"id":"q-1655","t":"mkt","l":"Advanced","s":90,"q":"Two companies, a technology company with no revenue now but future cash flows, and a coal-drilling company with strong current revenue but future going to zero. Both are valued at $6B.\n\n\n\n\nIf the Fed raises rates by 100 bps, how do their valuations change? Which is more affected?","k":["Higher discount rates hurt long‑duration cash‑flow streams more, so the tech company’s valuation falls materially, while the coal company—whose value is concentrated in near‑term cash flows—sees a smaller impact."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Moelis & Co. Interview","First round","Finance Brain Teasers","Advanced"]},{"id":"q-1656","t":"mkt","l":"Advanced","s":90,"q":"Can you give me an example of two assets that would likely have a negative beta?","k":["Physical gold and long‑duration U.S. Treasury bonds generally exhibit β < 0 because they appreciate when equity markets sell off.","Rationale: Both act as safe‑haven hedges, moving inversely to cyclical risk assets."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Moelis & Co. Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1657","t":"mkt","l":"Advanced","s":90,"q":"How would you value a hot dog stand in New York City?\n\n\n\n\nFollow-up: What would you estimate the EBITDA margin to be?","k":["Valuation","Trading Comps: identify comparable food carts / quick-service kiosks, normalize for location, seasonality, and permit scarcity, apply median revenue and EBITDA multiples to the stand’s metrics.","Precedent Transactions: analyze recent sales of NYC vendor permits and cart businesses, adjust for scale and operating history, derive an implied valuation range.","DCF: project sales, operating costs, and working capital needs, build multi-year cash-flow model, discount with a small-business WACC, and use a market-based exit multiple.","Follow-up","EBITDA margin may be in the 25-30% range: low COGS, lean labor, minimal overhead, and limited capital expenditure."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Moelis & Co. Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1658","t":"mkt","l":"Advanced","s":90,"q":"The interviewer turns and looks out the window and points at a building and asks you, \"how much is that worth?\".","k":["Use the standard valuation approaches: trading market sentiment (comps), strategic deal pricing (precedents), intrinsic cash-flow potential (DCF), and financing-driven returns (LBO).","Comps: Analyze recent sales of comparable buildings in the area, applying relevant multiples like Cap Rate (NOI/Property Value) to recent income generated.","Precedents: Review prices at which similar buildings or properties have been recently acquired, considering deal terms and market conditions at the time of sale.","DCF: Project the building's future rental income and expenses to derive Net Operating Income (NOI), treat as Free Cash Flow, and discount back to present value, including a terminal value.","LBO: Determine the maximum purchase price a financial sponsor could pay for the building to achieve a target IRR, financed with a significant portion of debt."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Moelis & Co. Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1659","t":"mkt","l":"Advanced","s":90,"q":"Without using a calculator, if you invest $10 and four years later it is worth $50, what is the approximate average annual growth rate of the investment?","k":["≈50 % CAGR.","Estimation:","CAGR = (ending value/beginning value)^(1/n) - 1, where n is the number of years.","CAGR = (50/10)^(1/4) - 1 ≈ 5^0.25 - 1 ≈ 1.5 - 1 ≈ 0.5 ≈ 50% yearly"],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Moelis & Co. Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1660","t":"mkt","l":"Advanced","s":90,"q":"Value yourself using a DCF.","k":["Project \"Free Cash Flow\": Define your FCF as your projected post-tax discretionary income (earnings minus living expenses) over a forecast period (e.g., 5-10 years), making reasonable assumptions about salary growth and promotions.","Determine a \"Terminal Value\": Calculate a terminal value of your earnings power using either a modest perpetual growth rate (e.g., inflation) or an exit multiple approach.","Calculate a \"Discount Rate\": Your discount rate (or WACC) should reflect the riskiness of your future earnings. It can be thought of as your personal required rate of return or opportunity cost of capital.","Conclude and Summarize: Sum the present values of the projected cash flows and the terminal value to arrive at your intrinsic value, while acknowledging the high degree of subjectivity in the assumptions."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Morgan Stanley Interview","Superday","Finance Brain Teasers","Advanced"]},{"id":"q-1661","t":"mkt","l":"Advanced","s":90,"q":"Imagine a group of companies that all have the same Enterprise Value and the same EBITDA, but different EBITDA margins.\n\n\n\n\nIf you were to plot these companies on a graph with EV/Revenue on the Y-axis and EBITDA Margin on the X-axis, what would the graph look like?","k":["The graph is a straight line with positive slope passing through the origin.","As EBITDA Margin increases, Revenue decreases (since EBITDA is constant), causing EV/Revenue to increase linearly.","Relationship:","EV/Revenue = EV / Revenue.","EBITDA Margin = EBITDA / Revenue.","Since EV and EBITDA are constant: Revenue = EBITDA / EBITDA Margin.","Therefore: EV/Revenue = EV / (EBITDA / EBITDA Margin) = (EV * EBITDA Margin) / EBITDA.","Since EV and EBITDA are fixed, EV/Revenue is directly proportional to EBITDA Margin."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Perella Weinberg Interview","New York Office","Finance Brain Teasers","Advanced"]},{"id":"q-1662","t":"mkt","l":"Advanced","s":90,"q":"You invest $100 and receive $2 every year for the first 19 years. On Year 20, you receive $102. What is the IRR?","k":["Answer: 2%","This is a bond-like investment. You invest $100 and receive $2/year for 20 years, with the $100 principal returned at the end. This is equivalent to a bond with a 2% coupon paying par at maturity. The IRR equals the coupon rate when you buy at par: 2%.","Verification: PV of $2/year for 20 years at 2% + PV of $100 at year 20 at 2% = $100. The cash flows exactly match a 2% yield."],"collection":"practice","topic":"Finance Brain Teasers","tags":["New","Reported in Piper Sandler Interview","SA 2026, Superday","Finance Brain Teasers","Advanced"]},{"id":"q-1663","t":"mkt","l":"Advanced","s":90,"q":"Match the following three companies to their most likely EBITDA margins: 40%, 25%, and 15%.\n\n\n\nAn out-of-home advertising company\nA pipe installation company\nAn esports team","k":["Matching:","Out-of-home advertising: 40% (high fixed costs, scalable)","Pipe installation: 15% (labor-intensive, competitive bidding)","Esports team: 25% (mid-range, sponsorship-driven with some overhead)","Rationale:","Advertising has high incremental margins once billboards are installed","Construction/installation is low-margin due to labor costs and competition","Esports benefits from digital scalability but has player/event costs"],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Unspecified Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1664","t":"mkt","l":"Advanced","s":90,"q":"You run a regression of Market Cap (Y-axis) vs. P/E ratio (X-axis).\n\n\n\n\nAnswer the following questions:\n\n\n\nWhat does the R-Squared of the regression tell us?\nAssuming the regression has a slope coefficient of 1.2 and the company's P/E ratio is 10x, what is its implied market cap?\nPost-merger, the company's P/E ratio is now 15x. What is its new implied market cap?\nTo determine if this was a good deal, what key piece of information is missing?","k":["Part 1: R-Squared","R-squared measures what percentage of variation in market cap is explained by variation in P/E ratio.","Part 2: Initial Market Cap","Answer: $12","Implied Market Cap = Slope * P/E = 1.2 * 10 = $12.","Part 3: Post-Merger Market Cap","Answer: $18","New Implied Market Cap = 1.2 * 15 = $18.","Part 4: Missing Information","The purchase price paid. Without knowing what was paid versus the value created ($18 - $12 = $6 increase), we cannot assess deal quality."],"collection":"practice","topic":"Finance Brain Teasers","tags":["Reported in Unspecified Interview","Finance Brain Teasers","Advanced"]},{"id":"q-1665","t":"mkt","l":"Basic","s":90,"q":"What is 17 x 17?\n\n\n\n\nFeel free to talk me through your mental math.","k":["Answer: 289.","It's useful to break the 2-digit by 2-digit multiplication questions into more manageable parts, then add them together. Saying it loud helps you keep track.","Example:","I'll break this into 17 x 10 and 17 x 7, and then add it together.","First, 17 x 10 is 170","Second, 17 x 7 is 119","Finally, 170 + 119 = 289","If math like 17 x 7 is tough, you can break it down even further and add along the way to help you keep track:","17 x 10 = 170","10 x 7 = 70, so now I'm at 240","Finally, 7 x 7 = 49","So, 240 + 49 = 289","Bottom line: pick random numbers and try this out a few times to sharpen your mental math muscles; you'll get better with practice."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Bank of America Interview","General Brain Teasers","Basic"]},{"id":"q-1666","t":"mkt","l":"Basic","s":90,"q":"What is the square root of 0.01?\n\n\n\n\nNo paper or pen – talk me through your thinking.","k":["Note: The interviewer who asked this actually giggled and said something along the lines of, \"You seemed so confident, I just wanted to catch you off guard. Nobody else is going to ask you that.\" So don't stress too much about these.","Answer: 0.1","An easy way to find square root of a decimal like this is to convert it to a fraction, then take the square root of the numerator and denominator separately.","0.01 = 1/100","√(1/100) = √1 / √100 = 1/10 = 0.1"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Bank of America Interview","General Brain Teasers","Basic"]},{"id":"q-1667","t":"mkt","l":"Basic","s":90,"q":"What is the angle between the hour and minute hands of an analog clock at 3:15?","k":["Answer: 7.5 degrees","Calculation:","Minute hand at 15 minutes: 15 × 6° = 90° (at the 3).","Hour hand at 3:15: 3 × 30° + (15/60) × 30° = 90° + 7.5° = 97.5°.","Angle between hands = |97.5° - 90°| = 7.5°.","Formula: Hour hand moves 0.5° per minute (30° per hour / 60 minutes). At 3:15, it has moved an additional 7.5° beyond the 3."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Bank of America Interview","M&A, First round","General Brain Teasers","Basic"]},{"id":"q-1668","t":"mkt","l":"Basic","s":90,"q":"You have a jar with 62 socks: 20 are white and 42 are black. If you are blindfolded, how many socks do you need to pick out to guarantee you have a matching pair?","k":["Answer: 3 socks.","By the pigeonhole principle: there are 2 colors of socks. If you pick 3 socks, at least 2 must be the same color, regardless of which ones you pick. The worst case is picking one white and one black on the first two draws; the third sock must match one of them."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Bank of America Interview","EGRC group, Superday","General Brain Teasers","Basic"]},{"id":"q-1669","t":"mkt","l":"Basic","s":90,"q":"How many squares are there on a chessboard?","k":["Answer: 204","The total is the sum of squares of different sizes:","While the board has 64 individual small squares (8 rows x 8 columns), it also contains squares of larger sizes, formed by combining these smaller squares","The number of squares in each row increases by 1 as you move down the board.","The total number of squares is the sum of the squares in each row, which is 1^2 + 2^2 + 3^2 + 4^2 + 5^2 + 6^2 + 7^2 + 8^2 = 204."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Barclays Interview","General Brain Teasers","Basic"]},{"id":"q-1670","t":"mkt","l":"Basic","s":90,"q":"What is 27 multiplied by 33?","k":["Answer: 891","Calculation 1: Standard Logic","27 * 33 = 27 * (30 + 3)= (27 * 30) + (27 * 3)","= 810 + 81","= 891","Method 2: Difference of Squares","Difference of Squares = a^2 - b^2 = (a - b)(a + b)","27 * 33 = (30 - 3)(30 + 3)","= 30^2 - 3^2","= 900 - 9","= 891","Pro Tip: You can use the difference of squares whenever the two numbers are equally above and below the same base number (27 and 33 are both +/- 3 from 30)."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Barclays Interview","Superday","General Brain Teasers","Basic"]},{"id":"q-1671","t":"mkt","l":"Basic","s":90,"q":"Every day, a man takes the elevator down from his apartment on the 10th floor.\n\n\n\n\nWhen he comes home, if it is raining or there are others in the elevator, he goes all the way to 10.\n\n\n\n\nIf it is not raining and he's alone, he goes to 7 and walks up 3 floors.\n\n\n\n\nWhy?","k":["He is too short to reach the 10‑button; on rainy days or with company he can use an umbrella or ask someone to press it."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","SA 2026, New York office, Superday","General Brain Teasers","Basic"]},{"id":"q-1672","t":"mkt","l":"Basic","s":90,"q":"Estimate how many windows are on your university's main campus.","k":["As always with these questions, the exact answer doesn't matter; what matters is communicating a structured framework and thought process with somewhat reasonable estimates.","Framework:","Define scope: Which buildings count as “main campus”?","Break down the problem:","# of buildings","Avg stories per building","Avg windows per story","Compute a baseline: multiply those three","Refine: adjust for big lecture halls, labs, variations","Example (round numbers):","Buildings: 30","Stories/building: 4","Windows/story: 15","Baseline: 30 × 4 × 15 = 1,800","Adjust: +200 (large halls), +100 (administration) = ~2,100 windows"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","General Brain Teasers","Basic"]},{"id":"q-1673","t":"mkt","l":"Basic","s":90,"q":"If you had to remove one US state from the map, which one would it be and why?","k":["Centerview sure does like to ask some fun questions... here is a sample answer:","Alaska given its small population and least economic disruption to the other states.","Explanation:","No contiguous border—removal minimizes logistical complexity.","Resource assets could be federally managed to protect stakeholders."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","General Brain Teasers","Basic"]},{"id":"q-1674","t":"mkt","l":"Basic","s":90,"q":"A single lily pad is placed in a pond. It doubles in size every day. On the 30th day, it has completely covered the pond. On which day did the lily pad cover one-eighth (1/8) of the pond?","k":["Day 27.","Reason: Coverage halves each day backwards: Day 30 = 1, Day 29 = ½, Day 28 = ¼, Day 27 = ⅛."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","General Brain Teasers","Basic"]},{"id":"q-1675","t":"mkt","l":"Basic","s":90,"q":"Which is greater: 624 squared, or 623 multiplied by 625?","k":["The trick here is to know the identity (a-1)(a+1) = a^2 - 1","623 x 625 = 624^2 -1","Thus, 624^2 is greater than 623 x 625 by 1"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","General Brain Teasers","Basic"]},{"id":"q-1676","t":"mkt","l":"Basic","s":90,"q":"Estimate how many people in New York City get the flu each year.","k":["≈ 850,000 people.","Estimation method:","NYC population ≈ 8.5 million.","Typical annual flu incidence ≈ 10% of the population.","8.5 M × 10% = 0.85 M (850 k).","If incidence ranges 8–12%, result spans 680–1,020 k, so 850 k is a reasonable midpoint."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","General Brain Teasers","Basic"]},{"id":"q-1677","t":"mkt","l":"Basic","s":90,"q":"If the Earth started rotating in the opposite direction and also started orbiting the sun in the opposite direction, where would the sun rise?","k":["The sun would rise in the west.","The direction of sunrise is determined solely by the Earth's axial rotation, not its orbital direction around the sun. If the Earth reversed its rotation on its axis, the sun would appear to rise in the west instead of the east. The orbital direction around the sun does not affect where the sun appears to rise on Earth."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","General Brain Teasers","Basic"]},{"id":"q-1678","t":"mkt","l":"Basic","s":90,"q":"Two tennis serves: the first one has a 60% probability of success, and the second one has an 80% probability of success. What is the probability of getting a serve in?","k":["Answer: 92%","The easiest approach is to calculate the probability of getting NO serve in, then subtract from 1.","P(miss first serve) = 1 - 0.60 = 0.40","P(miss second serve) = 1 - 0.80 = 0.20","P(miss both) = 0.40 x 0.20 = 0.08","P(getting at least one serve in) = 1 - 0.08 = 0.92 = 92%"],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Centerview Partners Interview","SF Office, First round","General Brain Teasers","Basic"]},{"id":"q-1679","t":"mkt","l":"Basic","s":90,"q":"5 machines can produce 5 goods in 5 minutes. How long does it take 100 machines to make 100 goods?","k":["Answer: 5 minutes.","Each machine produces 1 good in 5 minutes (5 machines make 5 goods in 5 minutes, so each machine makes 1 good per 5 minutes). With 100 machines, each one produces 1 good in 5 minutes, so 100 machines produce 100 goods in 5 minutes."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Centerview Partners Interview","SF Office, First round","General Brain Teasers","Basic"]},{"id":"q-1680","t":"mkt","l":"Basic","s":90,"q":"James is looking at Ashley, and Ashley is looking at Grace. James is married and Grace is not married. Is a married person looking at an unmarried person?","k":["Yes, a married person is definitely looking at an unmarried person.","Ashley's marital status is unknown, but consider both cases. If Ashley is married, then Ashley (married) is looking at Grace (unmarried). If Ashley is unmarried, then James (married) is looking at Ashley (unmarried). In both cases, a married person is looking at an unmarried person. The answer is yes regardless of Ashley's status."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Centerview Partners Interview","New York Office, First round","General Brain Teasers","Basic"]},{"id":"q-1681","t":"mkt","l":"Basic","s":90,"q":"Mental math: What is 39 times 25?","k":["Answer: 975","How to solve it quickly:","Method 1 (Round and adjust): Round 39 up to 40. Calculate 40 x 25 = 1,000. Then subtract the extra 1 x 25 = 25. So 1,000 - 25 = 975. This is the fastest approach for numbers close to a round number.","Method 2 (Divide by 4): Multiplying by 25 is the same as multiplying by 100 and dividing by 4. So 39 x 100 = 3,900, then 3,900 / 4 = 975. This trick works for any multiplication by 25."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","General Brain Teasers","Basic"]},{"id":"q-1682","t":"mkt","l":"Basic","s":90,"q":"A grand slam tennis tournament starts with 128 players. How many matches are played in total throughout the tournament?","k":["Answer: 127 matches.","In a single-elimination tournament, every match eliminates exactly one player. To go from 128 players to 1 champion, you need to eliminate 127 players, so 127 matches are played."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","General Brain Teasers","Basic"]},{"id":"q-1683","t":"mkt","l":"Basic","s":90,"q":"Two buckets (5-gallon, 3-gallon). Measure exactly 4 gallons using a hose.","k":["Fill the 5‑gallon bucket.","Pour into the 3‑gallon bucket → 2 left in 5.","Empty the 3‑gallon bucket.","Transfer remaining 2 gallons into 3‑gallon bucket.","Refill the 5‑gallon bucket.","Top off the 3‑gallon bucket (needs 1 gallon) using the 5‑gallon bucket.","Exactly 4 gallons remain in the 5‑gallon bucket."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Greenhill & Co. Interview","SA 2026, New York office, M&A group, Superday","General Brain Teasers","Basic"]},{"id":"q-1684","t":"mkt","l":"Basic","s":90,"q":"Name five different ways you could use a pencil.","k":["Writing or drawing (primary purpose).","Bookmark or placeholder in a book.","Hair pin or hair tie holder.","Pointer or stick for pressing small buttons (elevator, reset buttons).","Drumstick or musical instrument (tapping rhythms).","The interviewer is testing creativity and quick thinking, not looking for a single correct answer. Give 5 answers confidently and without overthinking."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Greenhill & Co. Interview","SF Office, First round","General Brain Teasers","Basic"]},{"id":"q-1685","t":"mkt","l":"Basic","s":90,"q":"What is the sum of all integers from 1 to 100?","k":["Answer: 5,050","Formula: Sum = n(n + 1) / 2","Calculation: Sum = 100(101) / 2 = 10,100 / 2 = 5,050"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Guggenheim Partners Interview","M&A group, First round","General Brain Teasers","Basic"]},{"id":"q-1686","t":"mkt","l":"Basic","s":90,"q":"A lilypad in a pond doubles in size every minute. After 60 minutes, the pond is fully covered.\n\n\n\n\nAt which minute was the pond half covered?","k":["Answer: At minute 59","If the lilypad doubles in size every minute, then one minute before the pond is fully covered (minute 60), it must have been exactly half covered. At minute 59, the lilypad occupies half the pond, and after doubling once more, it covers the entire pond at minute 60."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Houlihan Lokey Interview","Chicago office","General Brain Teasers","Basic"]},{"id":"q-1687","t":"mkt","l":"Basic","s":90,"q":"A single water lily in a pond doubles in size every minute.\n\n\n\n\nIf the lily pad completely covers the pond in one hour, in how many minutes will it cover a quarter of the pond?","k":["Answer: 58 minutes","If the lily pad covers the entire pond at 60 minutes, it covered half the pond at 59 minutes (since it doubles each minute). It covered a quarter of the pond at 58 minutes (half of the half)."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Houlihan Lokey Interview","Chicago office, First round","General Brain Teasers","Basic"]},{"id":"q-1688","t":"mkt","l":"Basic","s":90,"q":"Part 1: What is 150 divided by 2.5?\n\n\n\n\nPart 2: What is 1% of $150 billion?","k":["Part 1","Answer: 60","150 / 2.5 = 1,500 / 25 = 60","Part 2","Answer: $1.5 billion","1% of $150B = $150B / 100 = $1.5B"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in J.P. Morgan Interview","Chicago office","General Brain Teasers","Basic"]},{"id":"q-1689","t":"mkt","l":"Basic","s":90,"q":"Part 1: What is 30 divided by 1.5?\n\n\n\n\nPart 2: What is 1% of 1.5 million?","k":["Part 1","Answer: 20","30 / 1.5 = 300 / 15 = 20","Part 2","Answer: $15,000","1% of $1.5M = $1.5M / 100 = $15,000"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in J.P. Morgan Interview","Chicago office, Superday","General Brain Teasers","Basic"]},{"id":"q-1690","t":"mkt","l":"Basic","s":90,"q":"There are 5 people in a room, and each person shakes every other person's hand exactly once. How many total handshakes happen?","k":["Answer: 10 handshakes","Calculation:","Person 1 shakes hands with 4 others.","Person 2 shakes hands with 3 remaining (already shook with 1).","Person 3 shakes hands with 2 remaining.","Person 4 shakes hands with 1 remaining.","Person 5 has already shaken hands with everyone.","Total: 4 + 3 + 2 + 1 = 10 handshakes.","Alternative Approach via Formula: n(n-1)/2 = 5(4)/2 = 10."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in J.P. Morgan Interview","Superday","General Brain Teasers","Basic"]},{"id":"q-1691","t":"mkt","l":"Basic","s":90,"q":"A single lilypad in a pond doubles in size every day. On day 10, the pond is completely full. On what day is the pond half-full?","k":["Answer: Day 9","If the lilypad doubles in size each day and covers the entire pond on day 10, then on day 9 it must have covered exactly half the pond (since it doubles from day 9 to day 10)."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in J.P. Morgan Interview","Superday","General Brain Teasers","Basic"]},{"id":"q-1692","t":"mkt","l":"Basic","s":90,"q":"Estimate the total value of chewing gum sold in the U.S. in one year.\n\n\n\n\nWhat demographic factors would you consider in your analysis?","k":["Estimation approach:","U.S. population: ~330 million.","Assume 50% chew gum regularly (165 million).","Average consumption: 1 pack per week = 52 packs/year.","Average price: $1.50 per pack.","Total market: 165M × 52 × $1.50 = ~$12.9 billion annually.","Demographic Factors","Age: Younger consumers (teens/young adults) chew more gum.","Income: Gum is affordable across income levels, but premium brands target higher income.","Geography: Urban vs. rural consumption patterns may differ.","Health Trends: Shift toward sugar-free options.","Cultural Preferences: Some cultures chew gum more frequently than others."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in J.P. Morgan Interview","SA 2025","General Brain Teasers","Basic"]},{"id":"q-1693","t":"mkt","l":"Basic","s":90,"q":"Brain teaser: You are a taxi driver at JFK airport. You can either wait for a $50 fare or drive back to the city immediately. What would you do and why?","k":["This is an opportunity cost problem. The answer depends on comparing the expected value of each option:","Option A (Wait): You earn $50 but incur the cost of waiting (lost time, no earnings during that period). If the wait is 2 hours, your effective hourly rate is $25/hr.","Option B (Drive back): You earn no fare now but can pick up passengers in the city immediately. If you can earn $30-40/hr in the city, driving back and picking up fares quickly may yield more over the same 2-hour window.","The key factors are: expected wait time, expected city earnings rate, fuel cost for the empty return trip, and time of day (rush hour vs. late night). If the wait is short (under 30 minutes), wait. If the wait is long (over an hour), drive back to the city where demand is more consistent."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in J.P. Morgan Interview","SA 2027","General Brain Teasers","Basic"]},{"id":"q-1694","t":"mkt","l":"Basic","s":90,"q":"How would you estimate the total number of iPhones sold in the United States each year?","k":["Bottom-up estimation:","U.S. population: ~335 million","Smartphone penetration: ~85%, so ~285 million smartphone users","Apple's U.S. market share: ~55%, so ~157 million iPhone users","Average upgrade cycle: ~3 years","Annual iPhone sales: 157M / 3 = ~52 million iPhones per year","This aligns with estimates of Apple selling roughly 50-60 million iPhones annually in the U.S."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in J.P. Morgan Interview","SA 2027, New York Office, Superday","General Brain Teasers","Basic"]},{"id":"q-1695","t":"mkt","l":"Basic","s":90,"q":"What is the angle of a clock at 2:35?","k":["Answer: 132.5 degrees","Calculation:","Minute hand at 35 minutes: 35 x 6 = 210 degrees from 12 o'clock","Hour hand at 2:35: At 2:00 the hour hand is at 60 degrees. It moves 0.5 degrees per minute, so after 35 minutes it is at 60 + 17.5 = 77.5 degrees.","Angle between hands = |210 - 77.5| = 132.5 degrees"],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in J.P. Morgan Interview","SA 2025","General Brain Teasers","Basic"]},{"id":"q-1696","t":"mkt","l":"Basic","s":90,"q":"Estimate the total number of gas stations in the United States.","k":["Getting the right answer here is less important than communicating a structured thought process.","Pick a driver: US population of ~340 million","# of people served per gas station: 2,000","340 million ÷ 2,000 = 170,000 gas stations","The key is to pick a driver that’s easy to estimate and has a straightforward relationship to the thing you’re trying to measure."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Lazard Interview","General Brain Teasers","Basic"]},{"id":"q-1697","t":"mkt","l":"Basic","s":90,"q":"How would you estimate the total amount of coffee sold at Starbucks in a year?","k":["Use a bottom-up estimation approach:","Starbucks has roughly 35,000 stores globally.","Assume the average store serves about 500 customers per day.","Assume 80% of customers order a coffee drink.","Average cup size is roughly 12-16 oz (call it 14 oz).","Daily coffee volume per store: 500 x 0.80 x 14 oz = 5,600 oz","Annual per store: 5,600 x 365 = ~2.04M oz","Total: 35,000 stores x 2.04M oz = ~71.5 billion oz, or roughly 560 million gallons of coffee per year.","Alternatively, in revenue terms: ~35,000 stores x 500 customers/day x 365 days x ~$5 average drink = ~$32B in annual coffee revenue, which aligns roughly with Starbucks' total revenue."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Moelis & Co. Interview","SA 2027","General Brain Teasers","Basic"]},{"id":"q-1698","t":"mkt","l":"Basic","s":90,"q":"How much annual revenue do you think the Starbucks on our ground floor generates?","k":["Sample Answer: ~$700K","The exact answer is less important then outlining your approach and logic. Here is an example of how you could break down this question:","Open 16 hours per day","20 customers per hour","$6 average spend per customer","$1,920 per day","$1,920 * 365 = $700,800 per year"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Morgan Stanley Interview","SA 2026, New York office, First round","General Brain Teasers","Basic"]},{"id":"q-1699","t":"mkt","l":"Basic","s":90,"q":"Mental math (no paper, answer in approximately 5 seconds): What is $3 billion divided by 4, plus $25 million?","k":["Answer: $775 million","$3 billion / 4 = $750 million. $750 million + $25 million = $775 million."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Superday","General Brain Teasers","Basic"]},{"id":"q-1700","t":"mkt","l":"Basic","s":90,"q":"Two boats are traveling toward each other, each at 10 mph, and they are 5 miles apart. How long until they collide?","k":["Answer: 15 minutes","Combined closing speed = 10 + 10 = 20 mph.","Time = 5 / 20 = 0.25 hours = 15 minutes."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Generalist group, New York Office, First round","General Brain Teasers","Basic"]},{"id":"q-1701","t":"mkt","l":"Basic","s":90,"q":"Without a calculator, what is the square root of 0.9?","k":["Answer: Approximately 0.95","Since 0.9 is slightly less than 1, its square root should be slightly less than 1. More precisely, 0.95 * 0.95 = 0.9025, which is very close to 0.9."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Perella Weinberg Interview","New York Office","General Brain Teasers","Basic"]},{"id":"q-1702","t":"mkt","l":"Basic","s":90,"q":"Brain Teaser: How many weddings were there in the US in the past year?","k":["Approximately 2.1 million weddings per year. Here is a structured approach:","Step 1: Start with the US Population","US population: ~330 million.","Step 2: Estimate the Marriage Rate","The US marriage rate is roughly 6-7 marriages per 1,000 people per year. Use 6.5 per 1,000 as a midpoint.","330 million x (6.5 / 1,000) = ~2.15 million marriages per year.","Sanity Check (Bottom-Up)","~165 million adults of prime marrying age (roughly 20-65).","If about 1.3% of that population gets married in a given year: 165M x 0.013 = ~2.15M marriages.","Each marriage involves two people but produces one wedding, so marriages = weddings.","The actual figure is approximately 2.0-2.3 million weddings per year in the US. Either approach gets you in the right range. The interviewer is testing your ability to break a large question into logical assumptions and arrive at a reasonable estimate."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Piper Sandler Interview","SA 2027, Minneapolis Office, Superday","General Brain Teasers","Basic"]},{"id":"q-1703","t":"mkt","l":"Basic","s":90,"q":"How far does a bumblebee travel in a typical day?","k":["This is an estimation question testing structured thinking. A reasonable approach:","Assumptions:","Bumblebees forage for 8-10 hours per day during active season.","Average flight speed around 10-15 mph.","They don't fly continuously - perhaps 30-50% of foraging time is actual flight.","Calculation:","Active time: 9 hours","Flight time: 9 hours * 40% = 3.6 hours","Distance: 3.6 hours * 12 mph = ~43 miles","Reasonable range: 20-50 miles per day. The key is showing logical assumptions and structured approach, not the exact number."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Unspecified Interview","General Brain Teasers","Basic"]},{"id":"q-1704","t":"mkt","l":"Basic","s":90,"q":"A fighter jet fires two missiles simultaneously at an enemy jet.\n\n\n\n\nEach missile has a 50% probability of hitting the target.\n\n\n\n\nWhat is the total probability of hitting the enemy jet?","k":["Answer: 75%","Calculation:","Probability of both missiles missing: 50% * 50% = 25%","Probability of at least one hit: 1 - 25% = 75%","Alternatively: P(Hit) = P(First hits) + P(First misses, Second hits) = 50% + (50% * 50%) = 75%"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Unspecified Interview","General Brain Teasers","Basic"]},{"id":"q-1705","t":"mkt","l":"Basic","s":90,"q":"If you own 100 square miles of water, what are 15 ways you could monetize it?","k":["Potential monetization strategies:","Sell water rights to municipalities or utilities.","Lease for commercial fishing operations.","Develop recreational facilities (marinas, water parks).","Hydroelectric power generation.","Aquaculture and fish farming.","Water bottling operations.","Industrial water supply contracts.","Tourism and eco-tourism activities.","Film location rentals.","Water sports events and competitions.","Floating solar panel installations.","Luxury waterfront real estate development.","Carbon credit sales from protecting wetlands.","Research facility leases for universities.","Desalination if saltwater."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Unspecified Interview","General Brain Teasers","Basic"]},{"id":"q-1706","t":"mkt","l":"Basic","s":90,"q":"What are eight ways to use a toothbrush?","k":["Brushing teeth (primary use).","Cleaning grout between tiles.","Scrubbing stains on clothing or shoes.","Applying hair dye or styling edges.","Cleaning jewelry or small watch parts.","Exfoliating lips or skin.","Cleaning the crevices of electronics (keyboard, phone port).","Painting or texturing in art projects."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Unspecified Interview","General Brain Teasers","Basic"]},{"id":"q-1707","t":"mkt","l":"Basic","s":90,"q":"How many cars are scrapped per month in the United States?","k":["Approximately 1 million cars per month.","Estimation:","~290 million registered vehicles in the U.S.","Average vehicle lifespan is roughly 12 years before being scrapped.","Annual scrappage = 290M / 12 = ~24 million per year, but not all are scrapped (some exported), so roughly 12-15 million scrapped per year.","Monthly = ~12M / 12 = ~1 million cars per month."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Unspecified Interview","General Brain Teasers","Basic"]},{"id":"q-1708","t":"mkt","l":"Basic","s":90,"q":"At 12:15 on a clock, what is the angle between the hour and minute hands?","k":["Minute hand at 3 (15 minutes), i.e. 90° from 12.","Hour hand is 1/4 of the way from 12 to 1. Each hour is 30° (360° / 12), so it's 30° x 0.25 = 7.5° from 12.","Angle between them = 90° - 7.5° = 82.5°."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Wells Fargo Interview","General Brain Teasers","Basic"]},{"id":"q-1709","t":"mkt","l":"Advanced","s":90,"q":"What is 54% of 110?\n\n\n\n\nFollow-up: What about 1008^2?","k":["Part 1: Break into parts","50% of 110 = 55 (just divide by 2)","4% of 110 = 4.4 (1% is 1.1, so 4% is 4 × 1.1)","55 + 4.4 = 59.4","Part 2: Use the identity (a+b)2 = a2 + 2ab + b2","Represent 1008 as 1000 + 8","Then, (1000 + 8)2 = 10002 + (2 × 1000 × 8) + 82","= 1000000 + 16000 + 64 = 1,016,064"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","SA 2026, New York office, Superday","General Brain Teasers","Advanced"]},{"id":"q-1710","t":"mkt","l":"Advanced","s":90,"q":"Back-to-back mental math questions:\n\n\n\nWhat is 21 multiplied by 23?\nWhat is 1004 multiplied by 1007?","k":["21 x 23","The trick here is to notice the \"difference of squares\" shortcut","Difference of Squares = a^2 - b^2 = (a - b) x (a + b)","21 x 23 = (22 - 1) x (22 + 1) = 22^2 - 1^2 = 484 - 1 = 483","1004 x 1007","General shortcut for (a+m)(a+n) = a^2 + (m+n)a + mn","The trick is to pick an \"a\" that makes a^2 easy (e.g. a round number or a known square), then add the cross-term and the small product.","1004 x 1007 = (1000 + 4)(1000 + 7) = 1000^2 + ((11) * 1000) + 4x7 = 1,000,000 + 11,000 + 28 = 1,011,028"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","General Brain Teasers","Advanced"]},{"id":"q-1711","t":"mkt","l":"Advanced","s":90,"q":"Estimate what percentage of the total land area of Chicago is covered in concrete.","k":["While you could estimate the square miles of Chicago, that is likely unrealistic for most candidates.","A more realistic approach may just be to voice outloud the following:","I'd ask myself: \"If I flew over Chicago, what would I see from the sky?\"","I'd break into 3 buckets: buildings & roads (concrete), parks & green spaces, and water (like the lake)","I'd imagine a pie chart and ballpark it visually: 50% concrete, 25% parks & green, 25% water","I'd sanity check: Chicago is dense and has big parks, but most of what you walk/drive on is concrete, so 50% doesn't feel crazy"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","General Brain Teasers","Advanced"]},{"id":"q-1712","t":"mkt","l":"Advanced","s":90,"q":"Over a 24-hour period, how many times does the minute hand on a standard 12-hour analog clock completely pass the hour hand?","k":["22 times.","Explanation:","The hands align every 65.4545 minutes (60 min ÷ 11).","24 hours ÷ 1.0909 hours per alignment ≈ 22.","The minute hand therefore laps the hour hand 22 times each day."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","General Brain Teasers","Advanced"]},{"id":"q-1713","t":"mkt","l":"Advanced","s":90,"q":"What are the estimated annual revenues from sweater sales in Minneapolis?","k":["≈ $30 million.","Estimation method:","Estimate the city population ≈ 500,000.","Assume 1.5 sweaters bought per person each year in a cold climate.","Average retail price ≈ $40 per sweater.","500,000 × 1.5 × $40 ≈ $30 M.","Keep in mind there is no way to expect someone to know the population of a city; so if you aren't comfortable estimating a population, you can just call out your main drivers (population * sweaters bought/person * average price). Identifying the drivers/framework is the most important piece. If they push for numbers, just come up with something you think is reasonable, though you can make clear you don't know the population of Minneapolis."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","General Brain Teasers","Advanced"]},{"id":"q-1714","t":"mkt","l":"Advanced","s":90,"q":"Part 1: How much would you pay to play a game where for each roll of a standard 6-sided die, you are paid the dollar amount of the roll's result?\n\n\n\n\nPart 2: What if you had the option to re-roll once? How would this change your answer?","k":["Part 1: Single Roll Game","Answer: $3.50","Expected Value = (1+2+3+4+5+6) / 6 = 21/6 = $3.50","You should pay up to $3.50 to play this game.","Part 2: Option to Re-roll Once","Answer: $4.25","Optimal strategy: Re-roll if initial result is 1, 2, or 3 (below $3.50).","If you roll 4, 5, or 6: Keep it. Probability = 1/2, Expected Value = (4+5+6)/3 = $5.00.","If you roll 1, 2, or 3: Re-roll. Probability = 1/2, Expected Value = $3.50.","Total EV = (1/2 × $5.00) + (1/2 × $3.50) = $4.25."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Centerview Partners Interview","New York Office","General Brain Teasers","Advanced"]},{"id":"q-1715","t":"mkt","l":"Advanced","s":90,"q":"What is the square root of 1,521?","k":["Answer: 39","How to solve it quickly:","Step 1 (Bracket it): Start with a round number. 40 x 40 = 1,600, which is close to 1,521. Since 1,521 is less than 1,600, the answer is just below 40.","Step 2 (Test 39): Use the algebraic shortcut (a - b)² = a² - 2ab + b². Here: (40 - 1)² = 1,600 - 2(40)(1) + 1 = 1,600 - 80 + 1 = 1,521. Confirmed.","General approach: For any square root, find the nearest perfect square you know (e.g., 40² = 1,600), then adjust up or down by 1 and verify."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Centerview Partners Interview","Generalist group, New York Office, Superday","General Brain Teasers","Advanced"]},{"id":"q-1716","t":"mkt","l":"Advanced","s":90,"q":"Name ten things you can do with a charger besides charging a device.","k":["This is a rapid-fire creativity test. The interviewer wants to see how quickly you can think on your feet and generate ideas under pressure. Do not overthink — start listing immediately.","Mix practical and imaginative uses. Examples: use it as a bookmark, a makeshift belt, a jump rope, a door latch holder, a cable organizer, a measuring tool, a hair tie, a picture hanging wire, a zipper pull replacement, or a tourniquet in an emergency.","Deliver your answers with energy and confidence. Pausing too long between ideas signals you are struggling.","The specific answers matter less than demonstrating creativity, composure, and the ability to perform under a time-pressured, ambiguous prompt — all skills relevant to banking."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Centerview Partners Interview","Generalist group, New York Office, Superday","General Brain Teasers","Advanced"]},{"id":"q-1717","t":"mkt","l":"Advanced","s":90,"q":"Can a chicken beat an elephant in a fight?","k":["This is an absurd question designed to test your poise, logical reasoning, and ability to engage with unconventional prompts without being flustered.","Take it seriously and build a structured argument. The obvious answer is no — but the interviewer wants to see if you can think creatively. Consider scenarios where the chicken might \"win\": if the fight is defined differently (endurance, agility, survival in a specific environment), the chicken could have an edge.","Alternatively, argue the case definitively: an elephant outmatches a chicken in every physical dimension, and no realistic scenario produces a different result. State your position with conviction.","The key is demonstrating structured thinking and confidence, not finding the \"right\" answer to an inherently absurd question."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Centerview Partners Interview","Generalist group, New York Office, Superday","General Brain Teasers","Advanced"]},{"id":"q-1718","t":"mkt","l":"Advanced","s":90,"q":"You are playing a game with a fair six-sided die where you can roll as many times as you like. Your payoff is the value of your final roll.\n\n\n\n\nWhat is the expected value of this game and how much would you be willing to pay to play it?","k":["Answer: $6.00","Since you can roll an unlimited number of times at no cost, the optimal strategy is to continue rolling until you achieve the maximum possible outcome (a 6).","Therefore, the expected value is $6.00.","Interview Note: If the interviewer imposes a cost to roll (e.g., $1 per roll) or limits the number of rolls, the expected value would be lower (often calculated recursively to be ~$4-5 depending on the exact cost). However, with \"unlimited rolls\" and \"no cost\", the rational answer is the maximum face value."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Evercore Interview","New York office","General Brain Teasers","Advanced"]},{"id":"q-1719","t":"mkt","l":"Advanced","s":90,"q":"You have a large 10x10x10 cube that is painted red on all of its outside faces. This large cube is composed of smaller 1x1x1 cubes. How many of the smaller 1x1x1 cubes have no red paint on them?","k":["512","Remove the 1‑cube border on every side > interior dimensions 8×8×8.","8³ = 512 small cubes remain unpainted."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Lazard Interview","General Brain Teasers","Advanced"]},{"id":"q-1720","t":"mkt","l":"Advanced","s":90,"q":"Find the missing number in the following series and explain the pattern:\n\n\n\n\n3, 12, 39, x, 363","k":["Answer: 120","Pattern:","3 * 3 + 3 = 12","12 * 3 + 3 = 39","39 * 3 + 3 = 120","120 * 3 + 3 = 363","Each term is obtained by multiplying the previous term by 3 and adding 3."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Lazard Interview","SF Office","General Brain Teasers","Advanced"]},{"id":"q-1721","t":"mkt","l":"Advanced","s":90,"q":"You have two empty bowls, 50 red marbles, and 50 blue marbles. You must place all 100 marbles into the bowls. An impartial person will then choose one bowl at random and then pick one marble from that bowl at random. How should you distribute the marbles to maximize the probability that a blue marble is chosen?","k":["Place 1 blue marble in Bowl 1 and the remaining 99 marbles (49 blue + 50 red) in Bowl 2.","Explanation:","P(Blue) = 0.5 × 1 (Bowl 1) + 0.5 × 49∕99 (Bowl 2) ≈ 74.75%.","Any other allocation yields a lower combined probability."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Moelis & Co. Interview","General Brain Teasers","Advanced"]},{"id":"q-1722","t":"mkt","l":"Advanced","s":90,"q":"You have nine identical-looking balls, one of which is slightly heavier than the other eight. Using a balance scale only twice, how can you determine which ball is the heavier one?","k":["First weigh 3 vs 3:","If equal, heavy ball is in the remaining 3.","If unequal, heavy ball is in the heavier side.","Second weigh 1 vs 1 from the suspect trio:","Heavier side reveals the ball; if equal, the un‑weighed ball is heavier."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Moelis & Co. Interview","General Brain Teasers","Advanced"]},{"id":"q-1723","t":"mkt","l":"Advanced","s":90,"q":"How many unique letter combinations can be formed from the word \"ABACUS\" if the three vowels (A, A, U) must stay together?","k":["Answer: 72","Calculation:","Treat the three vowels (A, A, U) as a single unit. So we have: (AAU) B C S = 4 units to arrange.","Number of ways to arrange 4 units = 4! = 24","Within the vowel unit (A, A, U), arrange the 3 letters = 3! / 2! = 3 (dividing by 2! because there are two A's)","Total combinations = 24 * 3 = 72"],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Piper Sandler Interview","FSG First round","General Brain Teasers","Advanced"]},{"id":"q-1724","t":"mkt","l":"Advanced","s":90,"q":"A client wants to know how many underground fuel storage tanks (the tanks under gas stations that hold fuel) there are in the world. As an investment banker, how would you figure it out?","k":["This is a market sizing question. Walk through a structured, top-down framework:","Step 1: Estimate Total Gas Stations Worldwide","Start with the US: ~150,000 gas stations (well-known benchmark). The US has ~330M people, so roughly 1 station per ~2,200 people.","Developed nations (EU, Japan, Australia — ~1B people combined) have comparable car ownership: ~450K stations. China (~1.4B people, lower car penetration): ~100K. India and the developing world (~5B+ people, much lower car ownership): ~400K stations.","Rough global total: ~1.0-1.1 million gas stations.","Step 2: Estimate Tanks per Station","A typical station carries regular, mid-grade, premium gasoline plus diesel — 3-4 fuel types, each needing at least 1 underground tank.","Average: ~4-6 underground tanks per station.","Step 3: Calculate","~1 million stations x ~5 tanks per station = approximately 5 million underground fuel storage tanks worldwide.","As a Banker, How You Would Verify","Pull industry reports from the EPA (which tracks registered underground storage tanks in the US — ~550K active USTs), trade associations like NACS, and global energy agencies (IEA).","Cross-reference with major fuel distributors' (Shell, BP, ExxonMobil) annual reports for station counts in key geographies.","Use equity research reports on the fuel retail or environmental services sector."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Rothschild Interview","SA 2027, Global Advisory group, New York Office, Superday","General Brain Teasers","Advanced"]},{"id":"q-1725","t":"mkt","l":"Advanced","s":90,"q":"A 6x6x6 Rubik's Cube is made up of smaller individual cubes. How many individual cubes are on the outside of the Rubik's Cube?","k":["Answer: 152","Calculation:","Total small cubes in a 6x6x6 cube = 216","Interior cubes (not on any face) form a 4x4x4 cube = 64","Outer cubes = 216 - 64 = 152","Alternatively: 6^3 - 4^3 = 216 - 64 = 152. The interior cube has dimensions (6-2) on each side because you remove one layer from each face."],"collection":"practice","topic":"General Brain Teasers","tags":["New","Reported in Unspecified Interview","SF Office, First round","General Brain Teasers","Advanced"]},{"id":"q-1726","t":"mkt","l":"Advanced","s":90,"q":"What is the angle between the hour-hand and minute-hand of a clock at 1:43?","k":["Answer: 153.5 degrees","Calculation:","Minute hand position: 43 minutes * 6 degrees/minute = 258 degrees from 12.","Hour hand position: (1 hour * 30 degrees/hour) + (43 minutes * 0.5 degrees/minute) = 30 + 21.5 = 51.5 degrees from 12.","Angle between hands: |258 - 51.5| = 206.5 degrees.","Since 206.5 > 180, take the smaller angle: 360 - 206.5 = 153.5 degrees."],"collection":"practice","topic":"General Brain Teasers","tags":["Reported in Wells Fargo Interview","Superday","General Brain Teasers","Advanced"]},{"id":"q-1727","t":"mkt","l":"Basic","s":90,"q":"What do you know about Bank of America's business model, and how is it different from other banks?","k":["Bank of America is a diversified financial services company operating across four segments: Consumer Banking, Global Wealth & Investment Management, Global Banking, and Global Markets.","Key differentiators:","Largest consumer deposit base in the U.S., providing stable, low-cost funding.","Strong wealth management presence through Merrill Lynch integration.","Significant digital banking capabilities with over 40 million active digital users.","Balanced revenue mix between net interest income and fee-based income."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Bank of America Interview","New York Office, First round","Market Knowledge","Basic"]},{"id":"q-1728","t":"mkt","l":"Basic","s":90,"q":"Walk me through the current major events and trends happening in the world right now.","k":["Key trends to discuss include geopolitical developments, central bank policy decisions, industry-specific disruptions, and macroeconomic indicators. Tailor your response to current events as of the interview date.","Framework for discussion:","Monetary policy: Federal Reserve rate decisions and inflation trends.","Geopolitics: Major conflicts, trade policies, and regulatory changes.","Technology: AI developments, sector disruptions, major tech earnings.","M&A activity: Notable transactions and industry consolidation.","Market volatility: Equity market performance and risk factors."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Bank of America Interview","New York Office","Market Knowledge","Basic"]},{"id":"q-1729","t":"mkt","l":"Basic","s":90,"q":"What are some of the largest private equity buyout funds and what are their approximate assets under management (AUM)?","k":["Largest PE buyout funds (approximate AUM as of 2024-2025):","Blackstone: ~$1 trillion total AUM","KKR: ~$550 billion total AUM","Apollo Global Management: ~$650 billion total AUM","Carlyle Group: ~$425 billion total AUM","TPG: ~$230 billion total AUM","Warburg Pincus: ~$80 billion total AUM","CVC Capital Partners: ~$180 billion total AUM","EQT: ~$225 billion total AUM","Note: These figures represent total AUM across all strategies, not just buyout funds. Actual buyout-specific AUM would be lower for each firm."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Bank of America Interview","Financial Sponsors group, Superday","Market Knowledge","Basic"]},{"id":"q-1730","t":"mkt","l":"Basic","s":90,"q":"What are the key differences between the NASDAQ and the NYSE?","k":["Key differences:","Trading System: NASDAQ is fully electronic (dealer market), NYSE uses hybrid system with designated market makers and electronic trading","Company Profile: NASDAQ historically heavy on tech companies, NYSE more diversified with traditional blue-chip firms","Listing Requirements: NYSE generally has higher listing requirements (market cap, revenue, shares outstanding)","Trading Hours: Both have same core hours (9:30 AM - 4:00 PM ET), but pre-market and after-hours differ slightly","Prestige: NYSE traditionally viewed as more prestigious","Speed: NASDAQ offers faster execution due to fully electronic platform"],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Bank of America Interview","Superday","Market Knowledge","Basic"]},{"id":"q-1731","t":"mkt","l":"Basic","s":90,"q":"What do you know about the current M&A market?\n\n\n\n\nWhat have been the key drivers, and where do you see the market heading?","k":["Sample framework for discussing M&A market conditions (adjust based on current date):","Key Drivers:","Interest rates and cost of capital.","Regulatory environment and antitrust scrutiny.","Private equity dry powder and deployment pressure.","Sector-specific trends (tech consolidation, energy transition).","Economic outlook and CEO confidence.","Market Outlook:","Discuss whether activity is expected to increase or decrease based on current conditions.","Mention specific sectors showing strength or weakness.","Reference recent major deals or trends you've researched."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Bank of America Interview","M&A, Second round","Market Knowledge","Basic"]},{"id":"q-1732","t":"mkt","l":"Basic","s":90,"q":"Tell me about a trend or deal you are following, but you cannot say the word AI.","k":["Structure your response around a specific trend or deal. Good topics that avoid the restricted term include:","Healthcare consolidation (e.g., payer-provider vertical integration).","Energy transition and infrastructure investment (renewables, grid modernization).","Private credit's expansion into investment-grade lending.","Reshoring and supply chain restructuring in manufacturing.","GLP-1 drug market growth and its impact on healthcare and consumer sectors.","For each, cover: what is driving the trend, a specific deal or data point, who the key players are, and your view on where it is headed. Prepare 2-3 options before your interview."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Bank of America Interview","SA 2026, First round","Market Knowledge","Basic"]},{"id":"q-1733","t":"mkt","l":"Basic","s":90,"q":"What is the price of crude oil and natural gas today?","k":["This is a market awareness question. You should check prices the morning of your interview. As a framework:","WTI crude oil: Quote the front-month futures price (typically trades in the $65-$80/bbl range in the current environment).","Henry Hub natural gas: Quote the front-month futures price (typically trades in the $2.50-$4.50/MMBtu range).","Mention the key drivers: OPEC+ production decisions, U.S. shale output, global demand outlook, geopolitical risks, and seasonal weather patterns for natural gas.","Always check the exact levels the morning of your interview. Be prepared to discuss why prices are at their current levels and what could move them."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Bank of America Interview","SA 2026, First round","Market Knowledge","Basic"]},{"id":"q-1734","t":"mkt","l":"Basic","s":90,"q":"What deals are you following in the technology space? What are the underlying currents supporting the AI trend? Share a recent IPO that happened in tech. Name a public company that should go private next.","k":["Structure your response with specific examples for each sub-question. You should have current, researched examples ready.","Deals in Tech:","Cite 2-3 specific transactions with acquirer, target, deal value, and strategic rationale. Strong categories include: large-cap software M&A, semiconductor consolidation, AI infrastructure deals, and cybersecurity roll-ups.","Example framework: \"[Acquirer] acquired [Target] for $[X]B at [Y]x EV/Revenue, primarily to [strategic rationale: expand TAM, acquire technology, consolidate market share].\"","AI Trend Drivers:","Massive CapEx spending by hyperscalers (Microsoft, Google, Amazon, Meta) on data centers and GPU infrastructure, with combined annual AI CapEx exceeding $200 billion.","Enterprise adoption of generative AI for productivity, customer service, and software development, driving a new software monetization cycle.","Continued advances in large language models and AI agents driving new use cases across industries.","Government investment in AI research and semiconductor manufacturing (CHIPS Act), plus growing AI regulation as a policy theme.","Recent Tech IPO:","Pick one IPO you have researched. State the company, offering size, valuation, trading performance, and your view on whether the market priced it correctly. Strong candidates include AI-native companies, cybersecurity platforms, or vertical SaaS businesses.","Go-Private Candidate:","Pick a public company trading at a depressed multiple relative to peers, with strong recurring cash flows and operational improvement opportunities. Explain why PE ownership would unlock value: away from quarterly earnings pressure, ability to invest in long-term initiatives, or potential for add-on acquisitions."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Bank of America Interview","SA 2025, Technology group, SF Office, Superday","Market Knowledge","Basic"]},{"id":"q-1735","t":"mkt","l":"Basic","s":90,"q":"How do investment bankers make money?","k":["Investment banks generate revenue primarily through advisory fees and underwriting fees.","Advisory fees are earned for M&A transactions — typically a percentage of the deal value, with a retainer fee upfront and a larger success fee upon closing.","Underwriting fees are earned when banks help clients issue debt or equity securities, taking a spread or commission on the total amount raised.","Additional revenue comes from restructuring advisory fees, fairness opinions, and in some cases proprietary trading or principal investments, depending on the bank's business model."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Bank of America Interview","LA Office, Superday","Market Knowledge","Basic"]},{"id":"q-1736","t":"mkt","l":"Basic","s":90,"q":"What does the term \"sub-prime\" mean in the context of lending?","k":["Sub-prime refers to borrowers with poor credit histories or low credit scores who present higher default risk.","Key characteristics:","Credit scores typically below 620-640","History of late payments, defaults, or bankruptcies","Higher interest rates to compensate for increased risk","Lower loan-to-value ratios and stricter terms","Common in mortgages, auto loans, and personal lending markets","Sub-prime lending played a central role in the 2008 financial crisis when widespread defaults on sub-prime mortgages triggered the collapse of mortgage-backed securities."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Barclays Interview","Superday","Market Knowledge","Basic"]},{"id":"q-1737","t":"mkt","l":"Basic","s":90,"q":"What are the current trends in the market right now?","k":["Structure your response around these key areas:","Equity Markets: Current index levels (S&P 500, Nasdaq), recent performance, and drivers (AI/tech, earnings growth).","Interest Rates & Monetary Policy: Fed funds rate, direction of rate cuts or hikes, and impact on deal activity.","M&A Activity: Deal volume trends, whether sponsor or strategic activity is picking up, and what sectors are most active.","IPO & Capital Markets: State of the IPO window, leveraged finance issuance, and investor appetite.","Key Themes: AI investment, geopolitical risks, regulatory environment, and sector-specific trends relevant to the group you are interviewing with.","Prepare 2-3 specific data points or recent examples for each area before your interview."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Barclays Interview","SA 2027, Superday","Market Knowledge","Basic"]},{"id":"q-1738","t":"mkt","l":"Basic","s":90,"q":"Where do you see interest rates heading?","k":["Structure your answer with a framework and support it with current data:","Current state: Where the Fed Funds rate stands today and recent actions by the Federal Reserve.","Direction: Whether the market expects further cuts, holds, or hikes based on Fed dot plots and futures pricing.","Key drivers: Inflation trends (CPI, PCE), employment data, GDP growth, and any geopolitical factors.","Implications for IB: How the rate environment affects M&A activity, leveraged finance, IPOs, and valuations.","Be prepared to cite specific recent Fed meetings, inflation readings, and market expectations. Always tie your view back to how it impacts deal activity in banking."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Barclays Interview","SA 2027, Superday","Market Knowledge","Basic"]},{"id":"q-1739","t":"mkt","l":"Basic","s":90,"q":"Tell me about a deal you are following and the key market trends surrounding it.","k":["Structure your response around these elements:","Deal overview: Acquirer, target, deal size, consideration type, announcement date.","Strategic rationale: Why the deal makes sense for both parties (synergies, scale, capabilities).","Market trends: Broader industry dynamics driving the transaction (consolidation, AI, regulation).","Valuation: Entry multiple, premium paid, how it compares to peers.","Your perspective: Whether the deal makes sense and any risks (integration, regulatory approval, financing).","Example: Capital One's ~$35B acquisition of Discover Financial is a transformative deal in consumer finance. The strategic rationale centers on combining Capital One's credit card lending platform with Discover's proprietary payments network, reducing reliance on Visa/Mastercard. The deal reflects a broader trend of financial services consolidation as companies seek scale and vertical integration. The key risk is regulatory approval given antitrust scrutiny of large bank mergers."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Barclays Interview","SA 2026, First round","Market Knowledge","Basic"]},{"id":"q-1740","t":"mkt","l":"Basic","s":90,"q":"What is the S&P 500 trading at today?","k":["Structure your answer by stating the current approximate level, the year-to-date performance, and a brief comment on what has driven recent moves.","Prepare by checking the exact level on the morning of your interview. Also know the approximate levels of the Dow and Nasdaq, the 10-year Treasury yield, and the Fed Funds rate. Being able to cite specific numbers and recent trends shows genuine market engagement."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Barclays Interview","SA 2025, SF Office, First round","Market Knowledge","Basic"]},{"id":"q-1741","t":"mkt","l":"Basic","s":90,"q":"Who is the Fed Chairman?\n\n\n\n\nFollow-up 1: What does Trump want to do with interest rates?\n\n\n\n\nFollow-up 2: Explain interest rates.\n\n\n\n\nFollow-up 3: Does Trump like Powell?","k":["Sample answer in 2025:","Jerome Powell.","He publicly advocates lower rates to stimulate growth.","Interest rates are the price of money, set by supply/demand for funds and central‑bank policy; higher rates cool inflation but slow growth, and vice‑versa.","He has historically criticized Powell for not cutting quickly, indicating strained relations."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Centerview Partners Interview","SA 2026, New York office, Superday","Market Knowledge","Basic"]},{"id":"q-1742","t":"mkt","l":"Basic","s":90,"q":"Pitch me a start-up company that I should invest in today.","k":["Sample answer (June 2025): ElevenLabs","Thesis:","Category-defining voice AI: hyper-realistic, near-instant synthesis across global languages.","End-to-end platform: TTS, cloning, dubbing, conversational AI, mobile.","Sticky adoption: majority of Fortune 500 and a thriving creator marketplace with revenue share.","Moat: proprietary data, rapid iteration, robust safety stack, creator network effects.","Backing: hundreds of millions raised and a multibillion valuation from top-tier investors driving global scale.","Risks & Mitigants:","Big-tech bundling (Google/Gemini, OpenAI) → counter with superior quality, singular focus on voice, and sticky end-to-end workflow-lock-in.","Deepfake misuse → consent-gated cloning, watermarking, real-time detection, and regulator engagement."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Centerview Partners Interview","Market Knowledge","Basic"]},{"id":"q-1743","t":"mkt","l":"Basic","s":90,"q":"Give two examples of a high-growth company that is less profitable, and two examples of a low-growth company that is more profitable.","k":["High-Growth, Less Profitable:","Uber: Grew rapidly through heavy subsidies and market expansion but was unprofitable for years as it prioritized market share over margins.","Snowflake: A high-growth cloud data platform company that has invested aggressively in sales and R&D, sacrificing near-term profitability for rapid revenue growth.","Low-Growth, More Profitable:","Coca-Cola: Mature consumer staples company with single-digit revenue growth but consistently high EBITDA margins (30%+) and strong free cash flow generation.","Altria (Philip Morris domestic): Tobacco is a declining industry with low/negative volume growth, but extremely high margins due to pricing power and addictive product characteristics."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Centerview Partners Interview","New York Office, First round","Market Knowledge","Basic"]},{"id":"q-1744","t":"mkt","l":"Basic","s":90,"q":"Imagine you are seated next to the CEO of a potential client on a plane. How would you approach the conversation to ultimately pitch them relevant advisory services?","k":["Effective approach for client development:","Build rapport: Start with genuine conversation about their business, industry trends, or recent news.","Listen actively: Understand their challenges, strategic priorities, and pain points.","Demonstrate expertise: Share relevant market insights or case studies without being overly promotional.","Identify opportunities: Connect their needs to specific services (M&A, capital raising, restructuring).","Offer value: Suggest a follow-up meeting to discuss ideas in detail.","Maintain professionalism: Exchange contact information and follow up promptly."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Citi Interview","Chicago Office","Market Knowledge","Basic"]},{"id":"q-1745","t":"mkt","l":"Basic","s":90,"q":"What is Citi's current stock price, ticker symbol, market cap, P/E ratio, and who is its CEO?","k":["Ticker: C","CEO: Jane Fraser (as of early 2021, first female CEO of a major U.S. bank)","Stock Price and Market Cap: This changes daily - you should check current market data before your interview. As of November 2025, Citi trades at ~$100 per share at a ~$180B market cap with a P/E ratio of ~14x.","Bonus: Be prepared to discuss recent stock performance drivers such as restructuring initiatives, regulatory developments, or earnings results."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Citi Interview","New York Office","Market Knowledge","Basic"]},{"id":"q-1746","t":"mkt","l":"Basic","s":90,"q":"If I gave you $1 billion to invest, where would you put it? You cannot invest in the industry for which you are interviewing.\n\n\n\n\nPlease explain your reasoning.","k":["This is an open-ended question testing market knowledge, investment thesis development, and communication skills. A strong answer should:","Identify a specific sector with clear investment thesis (e.g., renewable energy, AI/technology, healthcare innovation)","Discuss current market trends and tailwinds supporting the sector","Address valuation considerations and entry timing","Mention diversification strategy (specific companies vs. sector ETFs vs. mix)","Consider risk factors and potential headwinds","Reference recent news or data points supporting the thesis","Example: Invest in AI infrastructure and semiconductor companies due to exponential growth in AI compute demand, limited supply of advanced chips, and long lead times for new capacity. Despite recent run-up, secular trends support sustained growth."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Citi Interview","Houston office, Superday","Market Knowledge","Basic"]},{"id":"q-1747","t":"mkt","l":"Basic","s":90,"q":"If you were advising a company on how to improve its operations, what would you recommend?","k":["Framework for operational improvement recommendations:","Revenue growth: Expand into adjacent markets, launch new products, optimize pricing strategy, improve sales force effectiveness.","Margin improvement: Reduce COGS through supplier renegotiation or procurement optimization, automate processes, streamline the supply chain, reduce SG&A overhead.","Working capital optimization: Reduce inventory levels (lower DIO), accelerate collections (lower DSO), extend payables (higher DPO) to free up cash.","Capital allocation: Divest non-core or underperforming business segments, reduce unnecessary CapEx, and reinvest in highest-ROIC opportunities.","Organizational efficiency: Reduce management layers, consolidate facilities, outsource non-core functions.","Tailor the recommendation to the specific company's industry and pain points."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Citi Interview","SA 2026, New York Office, First round","Market Knowledge","Basic"]},{"id":"q-1748","t":"mkt","l":"Basic","s":90,"q":"A company has $10 billion in cash. What would you advise them to do with it?","k":["The optimal use depends on the company's growth stage, cost of capital, and strategic position. Options in order of typical consideration:","Reinvest in the business: Fund organic growth through R&D, CapEx, or new market expansion. Best option if returns exceed the cost of capital.","M&A: Acquire companies that provide strategic value -- new capabilities, customers, or geographies. Must be at a reasonable price with clear synergies.","Share buybacks: Return cash to shareholders by repurchasing stock, increasing EPS and signaling confidence. Most effective when the stock is undervalued.","Dividends: Initiate or increase a dividend, providing direct returns to shareholders. Preferred by income-oriented investors.","Pay down debt: Reduce leverage and interest expense, improving the balance sheet and credit rating.","Hold as a strategic reserve: Maintain flexibility for future opportunities or economic downturns.","In practice, most large companies use a combination of these approaches. The key is maximizing long-term shareholder value."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Citi Interview","SA 2027","Market Knowledge","Basic"]},{"id":"q-1749","t":"mkt","l":"Basic","s":90,"q":"What are the key drivers of the current market?\n\n\n\n\nHow do these trends affect private equity sponsors?\n\n\n\n\nWhich major stock index experienced the largest sell-off yesterday, and what are the likely reasons for it?","k":["This requires current market knowledge. Framework for answering (adapt to current conditions):","Current Market Drivers:","Interest rates and Fed policy.","Inflation and economic growth outlook.","Geopolitical risks.","Sector-specific trends.","Impact on PE Sponsors:","Higher rates increase cost of debt financing.","Valuation multiples compress in higher rate environment.","Exit market timing becomes more challenging.","Focus shifts to operational value creation.","Recent Market Movements:","Research and mention specific indices (S&P 500, Nasdaq, Dow) and reasons for recent volatility based on current events."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Credit Suisse Interview","Sponsors group","Market Knowledge","Basic"]},{"id":"q-1750","t":"mkt","l":"Basic","s":90,"q":"When the Federal Reserve announces an interest rate increase, why do high-growth technology stocks often decline more than the Dow Jones Industrial Average?","k":["High-growth tech stocks are more sensitive to interest rate changes due to valuation characteristics:","Duration: Tech companies have cash flows weighted toward the distant future, which are discounted more heavily when rates rise.","Higher Multiples: Tech stocks trade at higher multiples, making them more vulnerable to multiple compression when discount rates increase.","Growth Premium: Rising rates reduce the present value of future growth, disproportionately impacting high-growth stocks.","Dow Composition: The Dow contains mature, dividend-paying companies with nearer-term cash flows less sensitive to rate changes."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Credit Suisse Interview","FSG group, First round","Market Knowledge","Basic"]},{"id":"q-1751","t":"mkt","l":"Basic","s":90,"q":"What is the approximate current yield on the 10-year U.S. Treasury note?","k":["This requires current market knowledge. As of November 2025, the 10-year Treasury yield is approximately 4.3-4.5%.","Be prepared to discuss why it's at current levels (Fed policy, inflation expectations, economic outlook) and implications for valuations and financing costs."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Credit Suisse Interview","Financial Institutions group, First round","Market Knowledge","Basic"]},{"id":"q-1752","t":"mkt","l":"Basic","s":90,"q":"Discuss some of the major corporate winners and losers that emerged during the COVID-19 pandemic.","k":["Winners:","E-commerce: Amazon, Shopify (accelerated online shopping adoption).","Technology: Zoom, Microsoft, Slack (remote work enablement).","Cloud Services: AWS, Azure, Google Cloud (digital transformation).","Delivery: DoorDash, Instacart (food and grocery delivery demand).","Streaming: Netflix, Disney+ (stay-at-home entertainment).","Home Improvement: Lowe's, Home Depot (home upgrades).","Losers:","Airlines: United, Delta, American (travel restrictions).","Hospitality: Marriott, Hilton (hotel demand collapse).","Retail: Department stores, malls (accelerated decline).","Energy: Oil & gas companies (demand destruction).","Commercial Real Estate: Office REITs (remote work shift)."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Credit Suisse Interview","M&A group, Superday","Market Knowledge","Basic"]},{"id":"q-1753","t":"mkt","l":"Basic","s":90,"q":"What was the financial impact of COVID-19 on J.C. Penney and on USPS?","k":["Note: This is less about this exact event (COVID-19; which is only relevant for a specific time period) and more about thinking through the broader implications of macroevents on companies.","Still, here's a direct answer to this question: J.C. Penney faced decreased foot traffic, liquidity pressures, and eventually filed for Chapter 11. The USPS saw volume shifts (less letter mail, more packages), which partly offset declines, but it continued to struggle with funding and structural constraints."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Evercore Interview","Market Knowledge","Basic"]},{"id":"q-1754","t":"mkt","l":"Basic","s":90,"q":"Why did Germany experience negative interest rates?","k":["The ECB’s accommodative policies, low inflation, and global demand for safe assets pushed yields on German bonds below zero. Investors accepted negative rates for safety and liquidity."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Evercore Interview","Market Knowledge","Basic"]},{"id":"q-1755","t":"mkt","l":"Basic","s":90,"q":"Pitch me a stock or company you are following and explain your investment thesis.","k":["Structure your stock pitch using this framework:","Company overview: Name, sector, market cap, what they do in one sentence.","Thesis (Bull case): 2-3 key reasons why the stock is attractive. Focus on catalysts: revenue growth drivers, margin expansion, underappreciated assets, or upcoming events.","Valuation: Current trading multiples vs. historical and peer averages. Is it cheap relative to growth? What does a DCF imply?","Risks (Bear case): 1-2 key risks. Show you have considered the downside.","Catalyst and timeline: What will drive the stock higher and when?","Prepare 1-2 stock pitches before your interview. Know the numbers: revenue, EBITDA, margins, growth rate, P/E, EV/EBITDA. Be prepared for pushback on every point."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Evercore Interview","Insurance group, SF Office, Second round","Market Knowledge","Basic"]},{"id":"q-1756","t":"mkt","l":"Basic","s":90,"q":"What company are you following right now and why?","k":["Structure your response around these elements:","Company name and brief description of what it does.","Why it interests you: Tie it to a sector trend, recent deal, or personal interest. Show you understand the business model.","Key metrics: Know the market cap, recent revenue/earnings, and 1-2 key multiples.","Catalyst or thesis: What is happening with the company right now (earnings, product launch, M&A, regulatory event)?","Your view: Bullish or bearish, with 1-2 supporting data points.","Pick a company in an industry relevant to the group you are interviewing with. Be prepared for follow-up questions on valuation, competitive dynamics, and recent news."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Evercore Interview","SA 2025, Second round","Market Knowledge","Basic"]},{"id":"q-1757","t":"mkt","l":"Basic","s":90,"q":"Talk me through a recent restructuring transaction you have been following.","k":["Structure your response around these elements:","Company overview: What the company does, its size, and its capital structure.","What went wrong: The operational or financial issues that triggered distress (revenue decline, overleveraging, secular headwinds, liquidity crisis).","Restructuring process: In-court vs. out-of-court, key creditor negotiations, DIP financing, plan of reorganization.","Outcome: Debt reduction, new capital structure, change of control, asset sales.","Your perspective: What was interesting or unusual about the deal.","Example: Envision Healthcare's 2023 Chapter 11 filing was notable as one of the largest healthcare bankruptcies, driven by reimbursement pressures from the No Surprises Act and $7B+ of debt from its 2018 KKR LBO. The restructuring eliminated approximately $5.5 billion of debt and resulted in a transfer of ownership to creditors."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Evercore Interview","SA 2026, First round","Market Knowledge","Basic"]},{"id":"q-1758","t":"mkt","l":"Basic","s":90,"q":"Do you think the overall equity market is overvalued?\n\n\n\n\nWhich metrics or data would you examine to decide?","k":["Broad guidance:","You might look at forward P/E, market cap to GDP, corporate earnings growth vs. price levels, and interest rate environments for discount rates.","Whether it’s overvalued depends on how earnings, interest rates, and macro conditions evolve.","Sample answer (2025):","Forward P/E sits above its long-term average, implying prices may outpace near-term earnings.","Market-cap-to-GDP is elevated, echoing periods that preceded weaker long-run returns.","Earnings growth remains solid but hasn’t fully caught up to stretched multiples.","Stable Fed rates limit further multiple expansion; future cuts would be needed to justify current levels."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Goldman Sachs Interview","Market Knowledge","Basic"]},{"id":"q-1759","t":"mkt","l":"Basic","s":90,"q":"Identify a company where you see material growth-synergy potential.","k":["Broad guidance:","You’d pick a real example (e.g., a technology firm acquiring a smaller platform to cross-sell or expand distribution). You could argue how combining product lines or user bases yields incremental revenue or margin.","Sample answer (2025): Cash App (Block, Inc) Acquiring Chime","Combine user bases: merge Cash App’s and Chime’s millions of accounts to accelerate growth and network effects.","Cross-sell financial services: offer Chime’s banking features within Cash App and Cash App’s investing/crypto tools to Chime customers.","Leverage data insights: unify spending, saving, and investing data for personalized offers and higher engagement.","Boost monetization: drive increased interchange fees, lending volumes, and uptake of premium features across the combined user base.","Strengthen brand loyalty: reinforce both brands’ low-fee, consumer-first reputations to improve retention and reduce acquisition costs."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Goldman Sachs Interview","Market Knowledge","Basic"]},{"id":"q-1760","t":"mkt","l":"Basic","s":90,"q":"Tell me about a recent M&A deal that interests you.\n\n\n\n\nWhat were the industry trends that may have motivated the transaction?\n\n\n\n\nHow was the target company affected by those trends?","k":["Select a recent, relevant transaction and structure your response around these elements:","Deal overview: Acquirer, target, deal size, consideration type, announcement date.","Industry trends: Consolidation, technological disruption, regulatory changes, shift to digital/subscription models.","Target positioning: How the target was positioned relative to these trends (leader, laggard, innovator).","Strategic rationale: Scale benefits, capabilities acquisition, market expansion.","Your perspective: Whether valuation seemed reasonable, integration risks, likely synergies.","Prepare 2-3 deals before your interview with specific metrics and details."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Goldman Sachs Interview","New York office","Market Knowledge","Basic"]},{"id":"q-1761","t":"mkt","l":"Basic","s":90,"q":"What is happening in the global markets right now?\n\n\n\n\nWhat is your expectation for the Fed's actions over the next few months?","k":["Prepare a current markets overview before your interview covering:","Market Overview:","Equity market performance and drivers (tech, rates, earnings).","Bond yields and credit spreads.","Currency and commodity movements.","Sector rotation or notable trends.","Fed Expectations:","Current Fed Funds rate and recent policy decisions.","Inflation data trends (CPI, PCE).","Employment situation and GDP growth.","Market pricing of future rate cuts/hikes based on Fed Funds futures.","Your informed opinion on likely trajectory with supporting rationale."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Goldman Sachs Interview","New York office","Market Knowledge","Basic"]},{"id":"q-1762","t":"mkt","l":"Basic","s":90,"q":"Part 1: Walk me through the most important financial news stories around the world right now.\n\n\n\n\nPart 2: Now, do the same but exclude any financial news.","k":["Part 1: Financial News","Prepare current coverage of major financial stories such as:","Central bank decisions and policy statements.","Major corporate earnings surprises or warnings.","Significant M&A announcements or deal closings.","Banking sector developments or regulatory changes.","Market volatility events or trading anomalies.","Part 2: Non-Financial News","Demonstrate broader awareness with:","Geopolitical developments affecting markets.","Major elections or political transitions.","Technological breakthroughs or disruptions.","Environmental events or policy changes.","Public health or social developments.","Link non-financial news to potential market/business implications."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Goldman Sachs Interview","New York office","Market Knowledge","Basic"]},{"id":"q-1763","t":"mkt","l":"Basic","s":90,"q":"Besides mergers and acquisitions, what are the other primary ways a company can use its excess cash on hand?","k":["Primary uses of excess cash:","Share Buybacks: Repurchase stock to return cash to shareholders.","Dividends: Distribute cash directly to shareholders.","Debt Repayment: Reduce leverage and interest expense.","Capital Expenditures: Invest in growth, equipment, or facilities.","R&D Investment: Fund innovation and product development.","Working Capital: Improve operational efficiency."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Goldman Sachs Interview","New York Office, First round","Market Knowledge","Basic"]},{"id":"q-1764","t":"mkt","l":"Basic","s":90,"q":"If you expect interest rates to increase, would you want to finance your company with a longer or shorter duration bond portfolio?","k":["Shorter duration.","When interest rates rise, bond prices fall, with longer-duration bonds experiencing larger price declines. By using shorter duration bonds:","Less exposure to interest rate risk and price volatility","Ability to refinance sooner at prevailing (higher) market rates without large mark-to-market losses","Greater flexibility to adjust capital structure","However, this assumes you're thinking from an investor's perspective. From a borrower's perspective, you'd want to lock in longer duration debt before rates rise to avoid higher borrowing costs in the future."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Goldman Sachs Interview","Superday","Market Knowledge","Basic"]},{"id":"q-1765","t":"mkt","l":"Basic","s":90,"q":"Which company would you expect to have a higher Beta: General Motors or Procter & Gamble? Explain your reasoning.","k":["General Motors would have a higher Beta.","Reasoning:","GM is cyclical (automotive demand tied to economic cycles).","P&G sells consumer staples (toothpaste, detergent) with stable demand regardless of economic conditions.","Higher cyclicality means GM's stock is more sensitive to market movements, resulting in a higher Beta."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Goldman Sachs Interview","First round","Market Knowledge","Basic"]},{"id":"q-1766","t":"mkt","l":"Basic","s":90,"q":"How would you invest $100,000?","k":["Structure your answer as a portfolio allocation with clear reasoning:","Framework: Consider your time horizon, risk tolerance, and current market environment. A sample allocation for a long-term investor:","60% Equities ($60K): Diversified across U.S. large-cap (S&P 500 index fund), international developed markets, and a small allocation to high-conviction individual stocks. Equities provide the highest long-term real returns.","20% Fixed Income ($20K): Mix of investment-grade corporate bonds and Treasury bonds. With yields still attractive at ~4-5%, fixed income provides stable income and portfolio diversification.","10% Alternative Investments ($10K): REITs for real estate exposure, or a small allocation to commodities (gold) as an inflation hedge.","10% Cash / Short-Term ($10K): Money market fund or T-bills earning ~4%+ while maintaining liquidity for opportunistic investments.","Be prepared to discuss why you chose each allocation and how current market conditions (rate environment, equity valuations, geopolitical risks) inform your decisions."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Goldman Sachs Interview","SA 2025, First round","Market Knowledge","Basic"]},{"id":"q-1767","t":"mkt","l":"Basic","s":90,"q":"Give me one industry you would go long on and one industry you would short. Explain your reasoning.","k":["Structure your answer with a clear thesis for each:","Framework","Long thesis: Identify a secular tailwind, growing TAM, and improving fundamentals.","Short thesis: Identify a structural headwind, declining demand, or margin compression.","Support each with 1-2 specific data points or trends.","Example","Long: Data center infrastructure / power generation. AI adoption is driving unprecedented demand for compute capacity, and hyperscalers (AWS, Azure, GCP) are committing hundreds of billions in CapEx. Companies providing power, cooling, and electrical infrastructure benefit from this secular trend.","Short: Traditional linear TV / cable. Cord-cutting continues to accelerate, ad dollars are shifting to digital platforms, and subscriber counts are in structural decline. Legacy media companies face margin pressure from expensive content investments competing with well-capitalized streaming platforms."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Goldman Sachs Interview","SA 2027, New York Office, Superday","Market Knowledge","Basic"]},{"id":"q-1768","t":"mkt","l":"Basic","s":90,"q":"Describe a recent investment banking transaction you followed in the news. What was the strategic rationale behind the deal, and what were the most interesting aspects of it?","k":["Structure your response around these elements:","Deal overview: Acquirer, target, deal size, consideration type, and announcement date.","Strategic rationale: Why the acquirer pursued the target (scale, capabilities, market entry, vertical integration).","Interesting aspects: Valuation premium, competitive dynamics, regulatory hurdles, financing structure, or market reaction.","Your view: Whether the price was fair and what risks could derail the deal.","Example: Capital One's ~$35 billion all-stock acquisition of Discover Financial in early 2024 was notable for its strategic rationale of combining Capital One's lending scale with Discover's proprietary payments network, creating a vertically integrated consumer finance platform. The deal faced extended regulatory scrutiny but was ultimately approved, representing significant consolidation in consumer finance."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Goldman Sachs Interview","SA 2027, Hirevue","Market Knowledge","Basic"]},{"id":"q-1769","t":"mkt","l":"Basic","s":90,"q":"Discuss a current event and how you see it affecting the financial markets in the future.","k":["Structure your response around these elements:","The event: Clearly state the current event and its context.","Direct market impact: Which asset classes, sectors, or instruments are most affected.","Second-order effects: How the event cascades through the economy (consumer spending, corporate earnings, credit markets).","Investment implications: What opportunities or risks arise for specific sectors.","Example: The ongoing rollout of tariffs under the current administration creates uncertainty across global supply chains. This directly pressures import-heavy sectors like retail and autos through higher input costs, compresses margins, and could reignite inflationary pressures that force the Fed to hold rates higher for longer. On the flip side, domestic manufacturers and reshoring-focused industrials stand to benefit from reduced foreign competition."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Goldman Sachs Interview","SA 2027, Hirevue","Market Knowledge","Basic"]},{"id":"q-1770","t":"mkt","l":"Basic","s":90,"q":"If a company had excess cash on its balance sheet, how would you recommend they spend it?","k":["The main options, in rough order of priority depending on the company's situation:","Reinvest in the business: Fund organic growth, R&D, or CapEx if internal returns exceed the cost of capital.","M&A: Acquire companies that provide strategic value (new markets, capabilities, scale) at attractive valuations.","Pay down debt: Reduces interest expense, lowers leverage, and improves credit profile. Particularly attractive if the company is highly levered.","Share buybacks: Return capital to shareholders while reducing share count and boosting EPS. Best when the stock is undervalued.","Dividends: Provide a steady return to shareholders. More common for mature, cash-generative companies with limited reinvestment opportunities.","Special dividends: One-time distributions when excess cash is truly surplus and no better use exists.","The optimal choice depends on the company's growth stage, leverage, cost of capital, and shareholder base preferences."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Goldman Sachs Interview","SA 2026, First round","Market Knowledge","Basic"]},{"id":"q-1771","t":"mkt","l":"Basic","s":90,"q":"What technology trends do you see creating the most opportunities for bankers and deal-making activity?","k":["Structure your answer around the key themes driving M&A and capital markets activity in tech:","Artificial Intelligence / Generative AI: Driving massive CapEx investment in infrastructure (GPUs, data centers), strategic acquisitions of AI-native companies, and consolidation among AI startups. Creates advisory opportunities across semiconductor, cloud, and software sectors.","Cloud migration & SaaS consolidation: Continued shift to cloud creates roll-up opportunities in fragmented SaaS verticals.","Cybersecurity: Rising threats and regulatory mandates drive M&A consolidation and PE interest in the space.","Data center / digital infrastructure: Explosive demand for compute capacity is driving investment, JVs, and M&A in data center REITs, power providers, and cooling technology.","Vertical software: PE firms continue to acquire and consolidate niche vertical software platforms.","Prepare 1-2 specific deals or trends with concrete data points."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","Market Knowledge","Basic"]},{"id":"q-1772","t":"mkt","l":"Basic","s":90,"q":"What are the current levels of interest rates, the unemployment rate, and GDP growth?","k":["Structure your answer with specific, current data points. Look up the following before your interview:","Fed Funds Rate: Know the current target range, the direction of recent moves, and whether the Fed is in a cutting or hiking cycle.","10-Year Treasury Yield: Know the current level and how it compares to the Fed Funds Rate (yield curve shape).","Unemployment Rate: Know the current level and whether it is trending up or down relative to historical norms.","GDP Growth: Know the most recent quarterly annualized real GDP growth figure and the consensus outlook.","Always check the latest figures on the morning of your interview. Also know the S&P 500 level and CPI/PCE inflation readings."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Goldman Sachs Interview","SA 2027, Superday","Market Knowledge","Basic"]},{"id":"q-1773","t":"mkt","l":"Basic","s":90,"q":"Walk me through an industry of your choice. Teach me about it, including the key players, trends, and dynamics.","k":["Structure your answer using this framework (pick an industry you know well):","Industry overview: Size, growth rate, and what drives demand.","Key players: Name 3-5 major companies, their market positions, and approximate market share.","Business model: How companies in this space make money (subscription, transaction-based, project-based, etc.).","Key trends: 2-3 major trends reshaping the industry (technology disruption, consolidation, regulation, shifting consumer preferences).","Competitive dynamics: Barriers to entry, pricing power, customer switching costs, cyclicality.","IB relevance: What types of advisory work (M&A, IPOs, restructuring, debt financing) are active in this space?","Prepare 1-2 industries in depth before your interview. Know specific metrics, recent transactions, and be ready for follow-up questions on valuation multiples and industry-specific risks."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","Market Knowledge","Basic"]},{"id":"q-1774","t":"mkt","l":"Basic","s":90,"q":"Talk to me about the market right now.","k":["Use this five-part framework to structure a concise, well-informed response. You should have current data points ready for each:","Equity markets: Where is the S&P 500 trading? What has driven recent performance? Which sectors are leading or lagging?","Interest rates and monetary policy: Where is the Fed funds rate? What is the rate trajectory? How is this impacting valuations and financing conditions?","M&A and capital markets environment: How is deal volume trending? Is sponsor activity picking up or slowing? What does the IPO pipeline look like?","Key macro themes: Identify 2-3 dominant themes (e.g., AI investment cycle, trade policy, geopolitical risk, credit conditions, sector rotation).","Your view: Take a directional stance backed by 1-2 specific data points. Interviewers want to see conviction and analytical thinking, not a neutral recap.","Tips:","Keep your response to 60-90 seconds. Hit all five areas without going deep on any one.","Lead with the most topical or differentiated point to stand out from other candidates.","Be prepared for follow-ups: \"What is your biggest risk?\" or \"Where would you invest right now?\""],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Gordon Dyal & Co. Interview","SA 2027, Second round","Market Knowledge","Basic"]},{"id":"q-1775","t":"mkt","l":"Basic","s":90,"q":"How do firms create value for shareholders?","k":["Companies create shareholder value by:","Generating returns above cost of capital (positive NPV projects).","Growing revenues and improving margins.","Efficient capital allocation (optimal capex, M&A, buybacks).","Building competitive advantages and moats.","Improving operational efficiency and reducing costs.","Returning cash to shareholders (dividends, buybacks)."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Greenhill & Co. Interview","M&A group, First round","Market Knowledge","Basic"]},{"id":"q-1776","t":"mkt","l":"Basic","s":90,"q":"Walk me through your thoughts on the current interest rate environment, foreign exchange markets, and overall macroeconomic trends.","k":["Structure your response around three areas:","Interest Rate Environment:","Discuss where the Fed Funds rate currently stands and the trajectory of monetary policy (tightening, holding, or easing).","Comment on the yield curve shape (inverted, flat, or normal) and what it signals about economic expectations.","Note implications for M&A and LBO activity: higher rates increase borrowing costs, reduce leverage capacity, and compress deal valuations.","Foreign Exchange Markets:","Comment on the strength of the U.S. dollar relative to major currencies (EUR, GBP, JPY).","A strong dollar makes U.S. acquisitions of foreign targets cheaper but hurts U.S. exporters and multinationals reporting foreign earnings.","Note any major currency dislocations driven by geopolitical events or divergent central bank policies.","Macroeconomic Trends:","GDP growth trajectory, inflation trends, and labor market conditions.","Sector-specific trends: AI/technology investment, energy transition, healthcare consolidation.","Key risks: geopolitical uncertainty, trade policy, fiscal deficits.","Prepare specific data points (current Fed Funds rate, recent GDP print, dollar index level) before your interview."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Greenhill & Co. Interview","SF Office, Second round","Market Knowledge","Basic"]},{"id":"q-1777","t":"mkt","l":"Basic","s":90,"q":"What is the definition of volatility in a financial context?","k":["Volatility measures the degree of variation in an asset's price over time, typically expressed as standard deviation or variance of returns.","Key characteristics:","Higher volatility indicates greater price fluctuations and uncertainty.","Commonly measured using historical volatility (realized) or implied volatility (from options prices).","Used as a proxy for risk in portfolio management and valuation.","Important input for options pricing (Black-Scholes model) and risk assessment (VaR, beta)."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Guggenheim Partners Interview","New York office, Superday","Market Knowledge","Basic"]},{"id":"q-1778","t":"mkt","l":"Basic","s":90,"q":"If you were Jerome Powell and decided to cut the Federal Funds rate by 25 basis points tomorrow, how would that affect the 10-year Treasury yield?","k":["The impact is not straightforward. The Fed Funds rate is a short-term overnight rate, while the 10-year yield reflects long-term growth and inflation expectations.","Short end of the yield curve would likely decline, as it tracks the Fed Funds rate most directly.","The 10-year could decline if the market views the cut as signaling economic weakness, driving demand for safe-haven long-duration Treasuries.","The 10-year could stay flat or rise if the cut is seen as inflationary or was already priced in.","Key insight: the Fed controls the short end, but the long end is driven by market expectations for growth, inflation, and future policy."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Guggenheim Partners Interview","SA 2027, Business Services group, Atlanta Office, Phone screen","Market Knowledge","Basic"]},{"id":"q-1779","t":"mkt","l":"Basic","s":90,"q":"How do you define risk?","k":["In finance, risk is the uncertainty or variability of returns relative to expectations.","Key dimensions:","Systematic risk (market risk, cannot be diversified away, measured by beta).","Unsystematic risk (company-specific, can be diversified away).","Downside risk (potential for loss or underperformance).","Volatility (standard deviation of returns, often used as proxy for risk).","In investment banking, risk encompasses credit risk, operational risk, market risk, and execution risk in transactions."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Houlihan Lokey Interview","FIG Second round","Market Knowledge","Basic"]},{"id":"q-1780","t":"mkt","l":"Basic","s":90,"q":"What could derail the economy in the near term?","k":["Broad guidance:","Potential issues include interest rate hikes, geopolitical tensions, energy supply shocks, consumer demand slowdowns, or credit market stress.","Sample answer (US economy, 2025):","Trade-policy shock: steep tariffs and retaliatory measures disrupt supply chains, raise input costs, and curb business investment.","Consumer confidence slump: slipping sentiment leads to spending pullbacks that risk triggering layoffs and deeper contraction.","Inflation persistence: tariff-driven price pressures and sticky core inflation complicate Fed decisions and may force tighter policy.","Market volatility: sharp equity declines erode household wealth and dampen corporate financing activity.","Policy uncertainty: abrupt federal job cuts and erratic regulatory shifts undermine economic stability and planning."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in J.P. Morgan Interview","Market Knowledge","Basic"]},{"id":"q-1781","t":"mkt","l":"Basic","s":90,"q":"Tell me about some of the major economic and geopolitical events currently happening around the world.","k":["This is an open-ended market knowledge question requiring awareness of current events. Prepare by staying informed on:","Monetary policy developments (Fed rate decisions, inflation trends).","Geopolitical tensions (trade relations, conflicts, sanctions).","Major M&A activity or market volatility.","Regulatory changes affecting key industries.","Energy market dynamics and commodity price movements.","Frame your answer around 2-3 specific recent events with potential market or economic impact, demonstrating both breadth and depth of understanding."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in J.P. Morgan Interview","Chicago office, Superday","Market Knowledge","Basic"]},{"id":"q-1782","t":"mkt","l":"Basic","s":90,"q":"What is a potential major risk to the economy right now?","k":["This requires current market awareness. Frame your answer around a specific, timely risk such as:","Persistent inflation or potential recession from aggressive monetary tightening.","Geopolitical instability affecting supply chains or energy markets.","Banking sector stress or credit market deterioration.","Commercial real estate concerns.","Fiscal sustainability concerns (debt levels, deficits).","Support your answer with recent data or events and explain potential transmission mechanisms to the broader economy."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in J.P. Morgan Interview","Chicago office, Superday","Market Knowledge","Basic"]},{"id":"q-1783","t":"mkt","l":"Basic","s":90,"q":"If you had $1 million today, where would you invest it?","k":["This tests investment philosophy and market knowledge. Structure your answer with:","Your investment objectives (growth, income, preservation, time horizon).","Specific allocation across asset classes with rationale (e.g., 60% equities, 30% fixed income, 10% alternatives).","Sector or thematic preferences based on current market conditions.","Risk considerations and diversification strategy.","Demonstrate conviction in your thesis while acknowledging uncertainty and the importance of rebalancing based on changing conditions."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in J.P. Morgan Interview","Chicago office, Superday","Market Knowledge","Basic"]},{"id":"q-1784","t":"mkt","l":"Basic","s":90,"q":"Compare the financials of Apple and Amazon. What are the key differences in their financial profiles?","k":["Structure your comparison around key financial metrics:","Apple","Business model: Premium hardware (iPhone ~50% of revenue) + growing high-margin Services segment (App Store, iCloud, Apple Music).","Margins: Very high -- gross margin ~45%, EBITDA margin ~35%. Hardware margins are strong due to brand pricing power; Services margins are even higher (~70%+).","Capital allocation: Returns massive cash to shareholders via buybacks ($90B+ annually) and dividends. Minimal net debt.","Revenue growth: Moderate (~5-8%), driven by Services growth offsetting mature hardware cycles.","Amazon","Business model: Diversified -- e-commerce (retail), AWS (cloud computing), advertising, subscriptions (Prime).","Margins: Lower overall (~25% gross margin) due to low-margin retail. However, AWS has ~30%+ operating margins and is the primary profit driver.","Capital intensity: Very high CapEx (~$50-60B+ annually) for data centers, fulfillment infrastructure, and logistics.","Revenue growth: Higher (~10-12%), driven by AWS and advertising growth.","Key takeaway: Apple is a high-margin, capital-light cash machine focused on shareholder returns. Amazon is a high-growth, capital-intensive reinvestment machine prioritizing market share and infrastructure."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in J.P. Morgan Interview","SA 2027, Hirevue","Market Knowledge","Basic"]},{"id":"q-1785","t":"mkt","l":"Basic","s":90,"q":"Where do you think the M&A market is headed?","k":["Structure your answer around these key themes:","Interest rate environment: As the Fed has moved toward rate cuts, financing conditions are improving, lowering borrowing costs and supporting deal activity.","Sponsor activity: PE firms are sitting on record levels of dry powder (~$2T+) and face pressure from LPs to deploy capital and return proceeds. This should drive significant sponsor-backed M&A.","Corporate confidence: Improving CEO confidence and the need for scale, technology capabilities, and geographic expansion are driving strategic M&A.","Sector themes: AI and technology, healthcare consolidation, and energy transition are active deal sectors.","Regulatory environment: A more business-friendly regulatory posture is reducing antitrust uncertainty for large deals.","Overall, the M&A market is expected to accelerate from recent years, supported by improving financing conditions, robust sponsor dry powder, and pent-up deal demand."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in J.P. Morgan Interview","SA 2027, New York Office, Superday","Market Knowledge","Basic"]},{"id":"q-1786","t":"mkt","l":"Basic","s":90,"q":"What risk factors would you consider when analyzing a company as an investment?","k":["Industry/competitive risk: Competitive dynamics, market share trends, barriers to entry, and disruption threats.","Financial risk: Leverage levels, liquidity, cash flow stability, and ability to service debt.","Operational risk: Customer concentration, supply chain dependencies, management quality, and execution risk.","Regulatory/legal risk: Government regulation, litigation exposure, and compliance requirements.","Macroeconomic risk: Interest rate sensitivity, currency exposure, inflation, and recession vulnerability.","Geopolitical risk: Trade policy, tariffs, political instability in key markets.","Technology/obsolescence risk: How quickly the company's products or services could be disrupted.","ESG risk: Environmental liabilities, governance issues, social controversies."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in J.P. Morgan Interview","SA 2027, First round","Market Knowledge","Basic"]},{"id":"q-1787","t":"mkt","l":"Basic","s":90,"q":"What do you think the economy will do after a presidential regime change?","k":["Structure your response around key policy areas and their economic implications:","Fiscal policy: Tax reform (corporate/individual rate changes), government spending priorities, and deficit trajectory. Tax cuts may stimulate near-term growth but increase the deficit.","Trade policy: Tariffs, trade agreements, and supply chain implications. Protectionist policies can boost domestic manufacturing but raise consumer prices.","Regulatory environment: Deregulation may boost business investment and M&A activity, while increased regulation could constrain certain sectors.","Monetary policy interaction: The Fed operates independently, but fiscal policy affects inflation expectations, which influence rate decisions.","Market sentiment: Historically, markets rally on certainty regardless of party. The initial market reaction reflects expectations about business-friendly policies.","Ground your answer in the current administration's specific policy agenda and its likely economic effects."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in J.P. Morgan Interview","SA 2025","Market Knowledge","Basic"]},{"id":"q-1788","t":"mkt","l":"Basic","s":90,"q":"Part 1: Tell me about a recent deal or market news that interests you.\n\n\n\n\nFollow-up: How would you advise the seller's shareholders that the deal was worth taking?","k":["Part 1: Framework for Discussing a Recent Deal","Structure your response around:","Deal overview: Acquirer, target, deal size, consideration (cash/stock/mix), and date.","Strategic rationale: Why the acquirer pursued the target (scale, capabilities, market access).","Valuation: Premium paid, implied multiples, and how they compare to peers.","Your perspective: Whether the deal makes strategic and financial sense.","Follow-up: Advising Seller's Shareholders","To advise that the deal is worth taking, you would present:","Premium to unaffected share price (typically 20-40% in M&A)","Implied valuation multiples vs. comparable companies and precedent transactions","A DCF showing the offer price exceeds intrinsic value on a standalone basis","Certainty of value today vs. execution risk of remaining independent","A fairness opinion from the financial advisor confirming the price is fair"],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Jefferies Interview","SA 2027, Aerospace & Defense group, Charlotte Office, First round","Market Knowledge","Basic"]},{"id":"q-1789","t":"mkt","l":"Basic","s":90,"q":"Explain the basic concept of a call option and a put option, and when you would exercise each.","k":["Call Option","Gives the holder the right (not obligation) to buy an asset at a specified strike price before expiration. You exercise a call when the market price exceeds the strike price (in the money). Profit = Market Price - Strike Price - Premium Paid.","Put Option","Gives the holder the right (not obligation) to sell an asset at a specified strike price before expiration. You exercise a put when the market price is below the strike price (in the money). Profit = Strike Price - Market Price - Premium Paid."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Jefferies Interview","SA 2025, TMT group, SF Office, Superday","Market Knowledge","Basic"]},{"id":"q-1790","t":"mkt","l":"Basic","s":90,"q":"Tell me about the Pfizer-Metsera deal and walk me through the transaction structure.","k":["Structure your response around these elements:","Deal overview: Identify the acquirer (Pfizer), target (Metsera), deal size, and announcement date.","Strategic rationale: Why Pfizer pursued this acquisition -- likely related to expanding its pipeline in a therapeutic area (e.g., obesity/metabolic disease) where Metsera had promising assets.","Transaction structure: Cash vs. stock consideration, any CVRs (contingent value rights) or milestone payments, upfront vs. total deal value.","Valuation: Entry multiple, premium to pre-deal price (if public), how it compares to similar biotech acquisitions.","Industry context: Broader trend of large pharma acquiring smaller biotechs to replenish pipelines ahead of patent cliffs.","Prepare specific deal metrics and be ready to discuss whether the price was justified relative to the pipeline's risk-adjusted value."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Market Knowledge","Basic"]},{"id":"q-1791","t":"mkt","l":"Basic","s":90,"q":"What is the Fed going to do next month? Why? Do you agree with it?","k":["Structure your answer with three components:","What: State the expected Fed action (hold, cut, or hike) based on current Fed futures pricing and recent FOMC guidance.","Why: Cite the key data points driving the decision -- inflation trends (CPI, PCE), labor market conditions (unemployment, wage growth), and GDP growth.","Your view: State whether you agree, and provide one supporting reason.","Example: The Fed is widely expected to hold rates steady at its next meeting. Inflation has remained slightly above the 2% target, and the labor market is still relatively tight, giving the Fed little reason to cut. I agree with holding -- cutting prematurely risks reigniting inflation, while the economy is not showing signs of distress that would warrant emergency easing."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Market Knowledge","Basic"]},{"id":"q-1792","t":"mkt","l":"Basic","s":90,"q":"Do you think Pfizer has historically made good acquisition decisions?","k":["Mixed track record. Structure your answer with specific examples:","Successful Acquisitions","Pharmacia (2003, ~$60B): Brought in blockbuster drugs including Celebrex and expanded oncology presence.","Array BioPharma (2019, $11.4B): Added strong oncology assets that generated significant revenue.","Questionable Acquisitions","Wyeth (2009, $68B): Largest pharma deal at the time. Diversified the portfolio but came at a very high price with significant integration challenges.","Seagen (2023, $43B): Premium was steep for an ADC platform. The long-term return remains uncertain given the high purchase price relative to current revenues.","Pfizer has faced criticism for relying on M&A to replace revenue lost to patent cliffs rather than building through internal R&D."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Market Knowledge","Basic"]},{"id":"q-1793","t":"mkt","l":"Basic","s":90,"q":"Please discuss two to three recent deals Lazard has advised on within your group of interest.\n\n\n\n\nFor each deal, be prepared to discuss:\n\n\n\nThe strategic rationale for the buyer and seller.\nYour opinion on the transaction price and how it compared to peer valuations.\nYour assessment of how well Lazard represented its client.","k":["Research Lazard's recent transactions in your target sector using:","Lazard's website (league tables, transaction announcements).","Press releases and news articles on major deals in your industry.","SEC filings for public company transactions.","For each transaction, prepare:","Strategic rationale: Why did buyer acquire? Why did seller exit? (synergies, market access, portfolio optimization).","Valuation analysis: Compare transaction multiples to precedent transactions and public comps. Was premium justified?","Lazard's role: Did they secure favorable terms? Navigate complex situations? Demonstrate sector expertise?","Your perspective: Would you have advised differently? What risks or opportunities do you see?","Demonstrate genuine interest and analytical thinking, not just memorization."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Lazard Interview","New York office, Superday","Market Knowledge","Basic"]},{"id":"q-1794","t":"mkt","l":"Basic","s":90,"q":"What are the growth prospects, key trends, and main revenue drivers for a specific company you have been following closely?","k":["This is a personalized question that requires preparation on a specific company of your choice.","Structure your answer to cover:","Growth prospects: Market expansion, product launches, geographic diversification, M&A pipeline.","Key trends: Industry tailwinds/headwinds, competitive dynamics, regulatory changes, technological shifts.","Revenue drivers: Volume growth, pricing power, new revenue streams, customer acquisition, market share gains.","Support your points with recent data (earnings reports, management guidance, industry research) and demonstrate understanding of both the company and its sector."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Lazard Interview","New York Office","Market Knowledge","Basic"]},{"id":"q-1795","t":"mkt","l":"Basic","s":90,"q":"A company has excess cash on its balance sheet. How would you advise management to decide between paying a dividend or executing a share buyback?\n\n\n\n\nDiscuss this from both a corporate finance theory perspective and a market signaling perspective.","k":["Corporate Finance Perspective","Dividends: Provide regular cash to all shareholders, tax-inefficient for investors.","Buybacks: Tax-efficient (capital gains vs. ordinary income), flexible, accretive if shares undervalued.","Dividends create ongoing commitment; buybacks are discretionary.","Market Signaling Perspective","Dividends signal stable, sustainable cash flows and management confidence in future performance.","Dividend cuts are viewed very negatively by markets.","Buybacks signal management believes shares are undervalued.","Buybacks provide flexibility without creating expectations.","Recommendation depends on stock valuation, shareholder tax profile, growth opportunities, and desired capital allocation flexibility."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Lazard Interview","New York Office, First round","Market Knowledge","Basic"]},{"id":"q-1796","t":"mkt","l":"Basic","s":90,"q":"A CEO believes their company's stock is undervalued. What actions can they take to increase the company's value?","k":["Actions to increase perceived or actual value:","Share buyback program (signals confidence, reduces share count, increases EPS).","Improve investor communications (clearer guidance, investor relations).","Operational improvements (cost reduction, margin expansion).","Strategic initiatives (new products, market expansion, M&A).","Capital structure optimization (debt refinancing, dividends).","Increase transparency and disclosure to reduce information asymmetry.","Split or spin-off undervalued divisions (unlock hidden value)."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Lazard Interview","FIG First round","Market Knowledge","Basic"]},{"id":"q-1797","t":"mkt","l":"Basic","s":90,"q":"What do you think will happen to the healthcare M&A market over the next few years, and what will lead to an increase in deal activity?","k":["Healthcare M&A activity is expected to increase, driven by:","Patent cliffs: Major pharma companies face significant revenue losses as key drugs lose patent protection (e.g., Keytruda, Eliquis). This compels large pharma to acquire pipeline assets to replace lost revenue.","Lower interest rates: As the Fed eases, financing costs for large acquisitions decrease, making debt-funded deals more attractive.","Depressed biotech valuations: Many small and mid-cap biotech companies are trading well below their peak, making them attractive acquisition targets.","AI/technology integration: Pharma companies are acquiring or partnering with AI drug discovery companies to improve R&D productivity.","GLP-1/obesity market: Massive TAM expansion is driving M&A and licensing activity around obesity and metabolic disease assets.","Regulatory environment: An administration that is potentially more favorable to large deals (less aggressive antitrust enforcement) could support mega-mergers."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Lazard Interview","SA 2025, Healthcare group, SF Office, Superday","Market Knowledge","Basic"]},{"id":"q-1798","t":"mkt","l":"Basic","s":90,"q":"Give me an elevator pitch for both the bullish and bearish outlook on Lazard and its performance.","k":["Bull Case","Lazard is a pure-play advisory and asset management firm well-positioned to benefit from the M&A cycle recovery. As deal activity rebounds from 2023-2024 lows, Lazard's restructuring and advisory franchises capture upside without balance sheet risk.","The firm's independent advisory model is increasingly valued by boards seeking conflict-free advice, and its global presence across 25+ countries gives it an edge in cross-border M&A.","Asset management provides a recurring revenue base that smooths advisory cyclicality.","Bear Case","Lazard lacks the diversified revenue streams of bulge brackets. In a prolonged M&A downturn, the firm has no capital markets or lending businesses to offset advisory declines.","Competition from boutique advisory firms (Centerview, PJT, Evercore) has intensified, pressuring market share and compensation economics.","The asset management division has faced net outflows in certain periods, and fee compression in the industry is a secular headwind."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Lazard Interview","SA 2027, Generalist M&A group","Market Knowledge","Basic"]},{"id":"q-1799","t":"mkt","l":"Basic","s":90,"q":"How has WACC changed for companies in the past year?","k":["Sample answer (2025): WACC has generally risen.","Risk‑free rates moved higher → cost of equity and debt both up.","Credit spreads widened on macro uncertainty.","Volatility increased, nudging equity risk premiums upward.","Result: virtually all firms face a higher hurdle rate."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Moelis & Co. Interview","First round","Market Knowledge","Basic"]},{"id":"q-1800","t":"mkt","l":"Basic","s":90,"q":"Can you name a company or an industry that typically has a low beta (e.g., less than 1.0)?","k":["Regulated electric utilities such as Consolidated Edison (ED) usually post β < 1."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Moelis & Co. Interview","Market Knowledge","Basic"]},{"id":"q-1801","t":"mkt","l":"Basic","s":90,"q":"From a central bank's perspective, what are the primary reasons for maintaining low interest rates in an economy?","k":["To stimulate economic activity and safeguard price stability when growth or inflation is weak.","Mechanics:","Lower borrowing costs boost consumer spending and corporate capex.","Cheaper debt service stabilises highly levered sectors.","Weaker currency supports exports and import‑price inflation.","Higher asset prices (wealth effect) spur confidence.","Reduces unemployment by encouraging labour demand."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Moelis & Co. Interview","Market Knowledge","Basic"]},{"id":"q-1802","t":"mkt","l":"Basic","s":90,"q":"What is private equity?\n\n\n\n\nCan you describe some of the different private equity investment strategies?","k":["Private equity refers to capital injected into privately held businesses—or used to take public companies private—by external investors. Private equity firms typically acquire a controlling interest, drive operational and strategic improvements, and then sell their stake at a substantial gain.","Strategies:","Leveraged Buyouts (LBOs): Acquiring mature companies with a combination of debt and equity, using the target’s cash flows to service the debt.","Growth/Expansion Capital: Providing minority or majority equity to fund scaling initiatives, product launches, or geographic expansion in growing businesses.","Distressed/Turnaround Investing: Buying companies in financial distress at deep discounts and restructuring operations or balance sheets to restore profitability.","Venture Capital: Investing in early-stage companies with high growth potential in exchange for equity, often supporting product development and market entry.","Mezzanine/Structured Equity: Providing subordinated debt or preferred equity with higher yields and equity kickers, bridging the gap between senior debt and common equity.","Secondaries and Fund-of-Funds: Purchasing existing private equity stakes from other investors (secondaries) or investing in a diversified portfolio of PE funds (FoFs) for broader exposure."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Moelis & Co. Interview","Market Knowledge","Basic"]},{"id":"q-1803","t":"mkt","l":"Basic","s":90,"q":"Imagine the CFO of General Motors informs you they have a significant amount of excess cash. What are the potential uses for this cash, and what are the strategic reasons for each option?","k":["Potential uses for excess cash:","Dividends: Return cash to shareholders, signal financial strength, attract income investors.","Share Buybacks: Increase EPS through dilution reduction, return capital when shares undervalued, maintain flexibility.","Debt Reduction: Lower interest expense, improve credit rating, reduce financial risk.","M&A: Acquire competitors or new capabilities, achieve synergies, accelerate growth strategy.","R&D / Capex: Invest in EV technology, autonomous driving, or manufacturing efficiency to remain competitive.","Build Cash Reserves: Maintain liquidity for cyclical downturns (autos are highly cyclical).","Given GM's cyclical nature and capital intensity, a balanced approach prioritizing capex/R&D and reserves would be prudent."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Moelis & Co. Interview","Market Knowledge","Basic"]},{"id":"q-1804","t":"mkt","l":"Basic","s":90,"q":"Do you follow any stocks? What stock would you recommend and why?\n\n\n\n\nFollow-up 1: How did the stock market perform last week, and what does that performance signify to you?","k":["This question tests market awareness and investment judgment. Prepare a specific stock pitch with:","Company overview and why you follow it.","Investment thesis (growth drivers, competitive advantages, valuation).","Key risks and how you'd monitor the position.","Recent performance and catalysts.","Follow-up 1","Discuss recent market movements (check major indices before interview). Explain drivers such as:","Fed policy / interest rate expectations.","Economic data releases (jobs, inflation, GDP).","Geopolitical events or sector-specific news.","Earnings season trends.","Articulate what the performance signals about investor sentiment and economic outlook."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Moelis & Co. Interview","Market Knowledge","Basic"]},{"id":"q-1805","t":"mkt","l":"Basic","s":90,"q":"Tell me about a story you have been following in the Wall Street Journal.\n\n\n\n\nFollow-up 1: Describe a recent M&A deal you have read about. What was the strategic rationale for the merger?","k":["Prepare 2-3 recent financial news stories before interviews. For each, know:","Key facts and players involved.","Market implications and your perspective.","How it relates to broader economic or industry trends.","Follow-up 1","Research a recent notable M&A transaction. Discuss:","Acquirer and target overview, deal size, and structure.","Strategic rationale: synergies (cost/revenue), market consolidation, vertical integration, technology acquisition, geographic expansion.","Financing approach and why it was chosen.","Expected accretion/dilution and market reaction.","Potential risks or regulatory concerns."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Moelis & Co. Interview","Market Knowledge","Basic"]},{"id":"q-1806","t":"mkt","l":"Basic","s":90,"q":"Pick an industry that interests you. What is your view on that industry and what is its long-term outlook?","k":["Choose an industry you genuinely understand. Structure your answer:","Industry Overview: Size, key players, business model fundamentals.","Current State: Recent trends, challenges, and opportunities.","Long-term Outlook: Growth drivers, headwinds, technological disruption, regulatory changes.","Investment Implications: Which companies are positioned to win, valuation considerations.","Example industries to consider: Technology (AI, cloud, semiconductors), Healthcare (biotech, medtech), Energy (renewables, oil & gas), Consumer (e-commerce, retail), Financial Services.","Demonstrate depth of knowledge, critical thinking, and ability to synthesize macro trends with micro fundamentals."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Moelis & Co. Interview","Market Knowledge","Basic"]},{"id":"q-1807","t":"mkt","l":"Basic","s":90,"q":"If you had $10,000 to invest today, where would you invest it and why?","k":["Structure your answer with clear reasoning:","Investment Objective: Risk tolerance, time horizon, goals.","Asset Allocation: Stocks, bonds, alternatives, cash allocation and rationale.","Specific Picks: Name specific securities or funds with investment thesis.","Current Environment: How macro conditions (rates, inflation, growth) inform your decision.","Example approach:","60% equities (specific stocks or sector ETFs you believe in).","30% fixed income (treasuries or corporate bonds given rate environment).","10% alternatives or cash for flexibility.","Show investment knowledge, risk awareness, and ability to construct a coherent portfolio strategy."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Moelis & Co. Interview","Market Knowledge","Basic"]},{"id":"q-1808","t":"mkt","l":"Basic","s":90,"q":"If a company is looking to increase the amount of its liquid cash, what can it do? Give several options.","k":["Draw on an existing revolving credit facility.","Issue new debt (term loan, bonds, or commercial paper).","Issue equity (follow-on offering, private placement, or ATM program).","Sell non-core assets or business units.","Improve working capital management: collect receivables faster, extend payables, reduce inventory.","Reduce or eliminate dividends and share buybacks.","Defer or reduce capital expenditures.","Enter into a sale-leaseback of owned real estate or equipment.","Securitize receivables or other cash-flow-generating assets.","Negotiate prepayments or deposits from customers."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Moelis & Co. Interview","SA 2026, Superday","Market Knowledge","Basic"]},{"id":"q-1809","t":"mkt","l":"Basic","s":90,"q":"How does the price of oil influence inflation?","k":["Oil affects transportation, manufacturing, and energy costs. Higher oil prices typically raise production and shipping expenses, which can pass through to consumer prices, thus driving inflation."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Morgan Stanley Interview","Market Knowledge","Basic"]},{"id":"q-1810","t":"mkt","l":"Basic","s":90,"q":"What is the difference between fiscal policy and monetary policy?","k":["Fiscal policy = government budgets.","It uses spending and taxation to steer growth and employment, enacted by legislatures/executives.","Monetary policy = central‑bank money supply management.","It sets short‑term rates, conducts open‑market operations, and guides expectations to control inflation and liquidity."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Morgan Stanley Interview","SA 2026, New York office, First round","Market Knowledge","Basic"]},{"id":"q-1811","t":"mkt","l":"Basic","s":90,"q":"What is fiscal policy? Who sets it, and what happens if unemployment increases?\n\n\n\n\nAny examples?","k":["Fiscal policy is government taxing and spending.","It is set by the legislature and executive (e.g., U.S. Congress and the President).","If unemployment rises, policymakers typically enact expansionary fiscal policy—higher spending or tax cuts—to boost demand.","Example: the 2020 CARES Act, which delivered stimulus checks and enhanced unemployment benefits."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Morgan Stanley Interview","SA 2026","Market Knowledge","Basic"]},{"id":"q-1812","t":"mkt","l":"Basic","s":90,"q":"What is monetary policy? Who sets it, and what happens if inflation increases?\n\n\n\n\nAny examples?","k":["Monetary policy is central‑bank control of money supply and interest rates.","In the U.S. it is set by the Federal Reserve’s FOMC.","When inflation rises, the Fed tightens—raising the policy rate and shrinking its balance sheet—to cool demand.","Example: the 2022–2023 rate‑hike cycle that lifted the fed‑funds rate above 5%."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Morgan Stanley Interview","SA 2026","Market Knowledge","Basic"]},{"id":"q-1813","t":"mkt","l":"Basic","s":90,"q":"Please pitch a stock you are currently following.\n\n\n\n\nFollow up 1: What is the company's business model? How does it make money?\n\nFollow up 2: What's your investment thesis? Include key reasons why you would or would not invest in the company today.","k":["Sample answer (June 2025): Circle Internet Group (CRCL)","Circle Internet Group (CRCL) is a licensed, global stablecoin company that operates USDC; the second largest stablecoin in the world. They went public in June 2025, opening at $31 per share and trading up to $200 per share within 2 weeks of IPO.","Business model:","Earns interest on USDC reserves invested in short-term Treasuries","Generates API/transaction fees from payments, treasury, compliance services","Investment thesis (bearish):","Valuation stretched: +500% within 2 weeks of IPO on regulatory optimism is not justified by fundamentals","Interest-rate risk: 98% revenue tied to rates; 1% cut ≈ $441 M hit","Competition: Tether’s $150 B market cap and $13 B profit dwarfs USDC","Diversification unproven: API/business services still nascent","Crypto cyclicality: trading volumes drive stablecoin demand"],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Morgan Stanley Interview","Market Knowledge","Basic"]},{"id":"q-1814","t":"mkt","l":"Basic","s":90,"q":"What are seven things a company could spend its cash on?","k":["Seven uses of cash:","Dividends to shareholders.","Share buybacks (repurchasing stock).","Debt repayment or refinancing.","Capital expenditures (CapEx) for growth or maintenance.","Acquisitions (M&A activity).","R&D or other operating investments.","Building cash reserves or investing in marketable securities."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Morgan Stanley Interview","SF Office","Market Knowledge","Basic"]},{"id":"q-1815","t":"mkt","l":"Basic","s":90,"q":"Tell me about an industry you are interested in. What are the systemic risks to that industry?","k":["This is an open-ended question testing industry knowledge and critical thinking. Structure your answer:","Name a specific industry and explain your interest.","Identify 2-3 systemic risks (e.g., regulatory changes, technological disruption, macroeconomic sensitivity, supply chain vulnerabilities).","Explain how these risks could materially impact the industry's profitability or structure.","Optionally, discuss how companies are mitigating these risks.","Example: In semiconductors, systemic risks include geopolitical trade tensions, concentration of manufacturing in specific regions, and cyclical demand tied to broader tech spending."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Morgan Stanley Interview","SF Office","Market Knowledge","Basic"]},{"id":"q-1816","t":"mkt","l":"Basic","s":90,"q":"How have recent supply chain disruptions impacted companies' financial performance and valuations?","k":["This is a qualitative question with no single answer. Strong responses demonstrate current events awareness.","Key impacts:","Increased costs (higher shipping, raw materials, inventory carrying costs).","Margin compression from inability to fully pass costs to customers.","Revenue delays or lost sales from product unavailability.","Working capital strain (higher inventory, extended payment terms).","Valuation impact: Lower multiples for companies with supply chain vulnerabilities; premiums for vertically integrated or resilient supply chains.","Sector variance: Manufacturing and retail hit harder than services."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Morgan Stanley Interview","Generalist First round","Market Knowledge","Basic"]},{"id":"q-1817","t":"mkt","l":"Basic","s":90,"q":"What is the impact of a strengthening U.S. dollar on a global company with significant international operations?","k":["Key impacts of stronger USD:","Revenue headwind: Foreign revenues translate to fewer USD when repatriated.","Earnings pressure: If costs are USD-denominated but revenues are foreign, margins compress.","Competitive disadvantage: U.S. exports become more expensive for foreign buyers.","Potential benefits: If company has USD debt but foreign earnings, it may benefit from cheaper debt service in foreign currency terms.","Translation effect: Foreign assets and earnings appear smaller when converted to USD for reporting.","Net impact depends on exposure mix, hedging strategies, and whether company is net exporter or importer."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Morgan Stanley Interview","Generalist First round","Market Knowledge","Basic"]},{"id":"q-1818","t":"mkt","l":"Basic","s":90,"q":"Name some high-risk versus low-risk companies you would invest in and explain why.","k":["Structure your answer by defining risk (volatility, business model uncertainty, leverage, cyclicality) and then provide specific examples.","High-Risk Examples:","Tesla: High valuation multiple, execution risk on autonomy/robotics, heavy capital spending, and dependence on consumer discretionary demand.","Rivian or Lucid: Pre-profitability EV companies with cash burn, unproven at-scale manufacturing, and competitive pressure from legacy OEMs.","Palantir: High P/E multiple, concentrated government revenue base, and sensitivity to government budget cycles.","Low-Risk Examples:","Johnson & Johnson: Diversified healthcare conglomerate with recession-resistant demand, strong balance sheet (AAA-rated), and consistent dividends.","Waste Management: Essential service with long-term contracts, high barriers to entry, and predictable recurring revenue.","Costco: Membership-based model with highly loyal customer base, low margins offset by volume and membership fee predictability.","Pick companies you can speak to in depth and tie your reasoning to specific financial metrics."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Superday","Market Knowledge","Basic"]},{"id":"q-1819","t":"mkt","l":"Basic","s":90,"q":"Tell me about the market today, what is driving it, and where do you think it will be in a year?","k":["Structure your response around these key topics:","Equity markets: S&P 500 level, YTD performance, key sector drivers (tech/AI, healthcare, financials).","Interest rates: Fed funds rate, trajectory of rate cuts or holds, impact on valuations and deal activity.","M&A and capital markets: IPO pipeline, sponsor activity, deal volume trends.","Macro risks: Inflation, geopolitical tensions, trade policy, consumer spending.","Forward outlook: Your directional view supported by 1-2 data points.","Example: The S&P 500 is trading near the 6,000 level, driven largely by continued strength in mega-cap tech and AI-related names. The Fed has been gradually cutting rates from the 2023-2024 peak, which has supported equity valuations and begun to thaw the M&A and IPO markets. Looking ahead, I expect modest upside over the next year as lower rates support deal activity and earnings growth, though trade policy uncertainty and elevated valuations remain headwinds."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Morgan Stanley Interview","SA 2027, New York Office, Superday","Market Knowledge","Basic"]},{"id":"q-1820","t":"mkt","l":"Basic","s":90,"q":"Do you think the S&P 500 will go up, down, or stay the same in the next 12 months?","k":["Structure your response with a clear thesis supported by specific data points:","Framework:","State your directional view clearly (up, down, or flat).","Bull case factors: Earnings growth, AI-driven productivity, consumer resilience, potential rate cuts.","Bear case factors: Elevated valuations, geopolitical risk, trade policy uncertainty, potential margin compression.","Weigh the factors and state which you think dominates.","There is no single correct answer — the interviewer is testing whether you follow markets, can form a coherent thesis, and can defend it with data. Reference the current S&P 500 level, trailing P/E, and consensus earnings growth to support your view."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Morgan Stanley Interview","SA 2027, Hirevue","Market Knowledge","Basic"]},{"id":"q-1821","t":"mkt","l":"Basic","s":90,"q":"Where should your favorite company go from here? Would you recommend it pursue acquisitions, organic growth, share buybacks, or a different strategic direction?","k":["Structure your response around these elements:","Company overview: Briefly describe the company, its market position, and current financial profile.","Current situation: Where the company stands today (growth trajectory, competitive position, capital allocation).","Recommendation: Choose one or two strategic priorities and explain why.","Supporting rationale: Use specific metrics (ROIC, growth rates, leverage capacity, valuation) to justify the recommendation.","Risks: Acknowledge what could go wrong with your recommended strategy.","Have a specific company and recommendation prepared before your interview. Be ready to defend your thesis with data points."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Perella Weinberg Interview","SA 2026, Superday","Market Knowledge","Basic"]},{"id":"q-1822","t":"mkt","l":"Basic","s":90,"q":"What is your favorite stock, and how would you approach valuing it and identifying potential M&A targets?\n\n\n\n\nNote: This is not a stock pitch.","k":["This is a qualitative question designed to assess market knowledge and analytical thinking. There is no single correct answer.","Sample approach:","Select a company you genuinely follow and can discuss in detail.","Valuation: Apply DCF (project cash flows, calculate WACC, determine terminal value), comparable company analysis (identify trading multiples), and precedent transactions (recent deals in the sector).","M&A Targets: Identify companies that offer strategic fit (geographic expansion, product diversification, technology acquisition), revenue or cost synergies, or market consolidation opportunities.","Explain rationale for target selection based on industry trends, competitive positioning, and financial metrics."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in PJT Partners Interview","First round","Market Knowledge","Basic"]},{"id":"q-1823","t":"mkt","l":"Basic","s":90,"q":"Tell me about a company you are following. Who would be a potential acquisition target for them, and how might they finance the transaction?","k":["This is a qualitative question with no single correct answer. Strong responses demonstrate sector knowledge and financial acumen.","Sample framework:","Company Overview: Briefly describe the acquirer's business model, market position, and strategic priorities.","Target Rationale: Identify potential targets that offer strategic fit (adjacent markets, complementary products, technology capabilities) or financial benefits (revenue/cost synergies, market share consolidation).","Financing Structure: Consider acquirer's balance sheet strength, credit rating, and market conditions. Options include cash on hand, debt issuance (bank loans, bonds), equity issuance, or a combination. Justify based on cost of capital and leverage capacity."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in PJT Partners Interview","First round","Market Knowledge","Basic"]},{"id":"q-1824","t":"mkt","l":"Basic","s":90,"q":"What are your thoughts on current oil prices and broader market trends?","k":["Structure your answer around these elements:","Current oil price level and recent trend (WTI and Brent).","Supply-side drivers: OPEC+ production decisions, U.S. shale output, geopolitical disruptions.","Demand-side drivers: Global GDP growth, China recovery trajectory, energy transition trends.","Broader market context: Interest rate environment, inflation outlook, equity market performance.","Your view: Where you think oil is headed and why, supported by specific data points.","Prepare specific numbers before your interview (current WTI price, recent OPEC decisions, S&P 500 level, Fed funds rate)."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in PJT Partners Interview","SA 2026, Superday","Market Knowledge","Basic"]},{"id":"q-1825","t":"mkt","l":"Basic","s":90,"q":"Name an industry you believe will not exist in 10 years and explain why.","k":["Answers vary. The key is to demonstrate an understanding of technology trends, consumer behavior, and business model obsolescence.","Sample answer (2025):","Physical media rental stores, such as those offering DVDs and Blu-rays, will likely disappear within the next decade.","The convenience and accessibility of streaming services have quickly made physical rentals obsolete."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Raine Group Interview","Market Knowledge","Basic"]},{"id":"q-1826","t":"mkt","l":"Basic","s":90,"q":"Back-to-back \"current market event\" questions:\n\nWhat were the three most significant market events this week?\nWhich macroeconomic data points are currently supporting the inflation narrative?\nWhat is the prevailing trend in the broader financial markets right now?\nWhat are your predictions for future interest-rate movements?","k":["Sample answer (June 2025):","Key events: Fed kept policy steady but hinted at gradual easing; consumer sentiment improved sharply; energy and safe-haven metals rallied on renewed geopolitical tensions.","Inflation drivers: Core prices remain above target, energy costs are edging higher, and tariffs plus firm wage growth are feeding persistent price pressure.","Market trend: Risk assets are pushing higher while volatility lingers; credit spreads have tightened and U.S. markets continue to outpace international peers.","Rate outlook: Base-case calls for modest Fed cuts later in 2025, contingent on continued disinflation; policy rates should stay well above pre-pandemic norms, with sticky inflation or geopolitics posing upside risks."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in RBC Interview","SA 2026, Superday","Market Knowledge","Basic"]},{"id":"q-1827","t":"mkt","l":"Basic","s":90,"q":"What is the NASDAQ trading at right now? How much is it up?","k":["This is a market awareness question. Check the NASDAQ Composite level the morning of your interview.","Quote the current level and be specific (e.g., \"The NASDAQ Composite is at X, up Y% YTD\").","Know the YTD performance and the approximate level from the start of the year.","Mention key drivers: AI-related tech rally, interest rate expectations, mega-cap earnings performance, and sector rotation trends.","Be ready to discuss why the NASDAQ has outperformed or underperformed the S&P 500 (tech concentration, growth vs. value dynamics)."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in RBC Interview","SA 2025, SF Office, First round","Market Knowledge","Basic"]},{"id":"q-1828","t":"mkt","l":"Basic","s":90,"q":"How does the typical capital structure of a mature, stable company differ from that of a young, high-growth company?","k":["Mature, Stable Company:","Higher debt levels (predictable cash flows support leverage).","Regular dividends and share buybacks.","Lower equity financing (established, less need for capital).","Investment-grade credit ratings.","Young, High-Growth Company:","Lower debt or minimal leverage (uncertain cash flows, higher risk).","Equity-heavy capital structure (venture capital, growth equity, IPOs).","Retained earnings reinvested for growth (no dividends).","May use convertible debt or preferred equity (flexible, less dilutive)."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Rothschild Interview","First round","Market Knowledge","Basic"]},{"id":"q-1829","t":"mkt","l":"Basic","s":90,"q":"What are some cyclical sectors, and what are some defensive sectors?\n\n\n\n\nExplain your thought process.","k":["Cyclical = discretionary spending tied to GDP.","Autos","Luxury retail","Semiconductors","Industrial metals","Defensive = necessities with inelastic demand.","Utilities","Consumer staples","Healthcare","Telecom","Classification relies on revenue sensitivity to economic cycles and pricing power durability."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in UBS Interview","SA 2026, New York office, Superday","Market Knowledge","Basic"]},{"id":"q-1830","t":"mkt","l":"Basic","s":90,"q":"What is a sector you are bullish on? What about a sector you are bearish on?\n\n\n\n\nWhy?","k":["Example response:","Bullish – utility‑scale renewables.","Structural policy tailwinds (IRA, EU Green Deal).","Cost curves for solar / storage still falling.","Long‑term contracted cash flows.","Bearish – traditional broadcast media.","Cord‑cutting pressures ad and affiliate revenue.","Rising content costs squeeze margins.","Lower secular growth versus streaming peers.","Pick sectors you can defend with data on TAM, margin trends, and competitive dynamics."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in UBS Interview","SA 2026, New York office, Superday","Market Knowledge","Basic"]},{"id":"q-1831","t":"mkt","l":"Basic","s":90,"q":"How does the Federal Reserve lower interest rates, and what economic conditions typically lead to this policy?\n\n\n\n\nConversely, what conditions would prompt the Fed to raise rates?","k":["How the Fed Lowers Rates","Sets lower target for federal funds rate.","Conducts open market operations (buying securities to inject liquidity).","Can also lower discount rate and reserve requirements.","Conditions Prompting Rate Cuts","Economic slowdown or recession risk.","Low inflation or deflation concerns.","High unemployment.","Financial market stress.","Conditions Prompting Rate Increases","High inflation above target (typically 2%).","Overheating economy.","Low unemployment with wage pressure.","Asset bubbles or excessive risk-taking."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Basic"]},{"id":"q-1832","t":"mkt","l":"Basic","s":90,"q":"Do you believe the stock market is currently in a bubble? Why or why not?","k":["This requires a current market view. A strong answer would consider:","Signs of Potential Bubble","Elevated valuation multiples vs. historical averages.","Excessive speculation in certain sectors.","Retail investor exuberance and leverage.","Disconnect between fundamentals and prices.","Counterarguments","Strong corporate earnings growth justifying valuations.","Low interest rate environment supporting higher multiples.","Technological innovation creating genuine value.","Improving economic fundamentals.","Support your view with specific examples, data points, and sector-level analysis rather than making broad generalizations."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Basic"]},{"id":"q-1833","t":"mkt","l":"Basic","s":90,"q":"You have $10,000 to invest right now. You know with certainty that interest rates will increase significantly tomorrow. What do you invest in and why?","k":["Invest in floating-rate instruments or short-duration assets.","Rationale:","Floating-rate notes benefit immediately as rates reset higher.","Short-term bonds minimize duration risk and can be reinvested at higher rates soon.","Money market funds quickly reflect higher rates.","Avoid:","Long-duration fixed-rate bonds (prices fall as rates rise).","High-growth stocks (often valued on distant cash flows, hurt by higher discount rates).","You could also short long-duration bonds to profit directly from the rate increase."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Basic"]},{"id":"q-1834","t":"mkt","l":"Basic","s":90,"q":"What is your view on the current state of the IPO market, and when do you believe it will recover?","k":["This requires current market knowledge. A strong answer would address:","Current State Assessment","Recent IPO volumes and pricing trends.","Valuation multiples vs. private market comparables.","Investor appetite and aftermarket performance.","Backlog of companies waiting to go public.","Recovery Drivers","Stabilization of interest rates and economic outlook.","Improved public market valuations.","Successful IPO exits demonstrating viable path.","Private market pressures forcing liquidity events.","Support your timing prediction with macro factors and recent market indicators."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Basic"]},{"id":"q-1835","t":"mkt","l":"Basic","s":90,"q":"What are the reasons a company's share price might rise after announcing a share buyback?\n\n\n\n\nConversely, what are the reasons it might fall?","k":["Reasons Price Might Rise","Signal of undervaluation - management believes stock is cheap.","Reduces share count, increasing EPS.","Returns excess cash to shareholders efficiently.","Demonstrates confidence in future cash flows.","May indicate limited better investment opportunities (confidence in core business).","Reasons Price Might Fall","Viewed as poor capital allocation - should invest in growth instead.","Suggests lack of organic growth opportunities.","May be levering up balance sheet excessively to fund buyback.","Timing concerns - buying at peak valuations.","Could signal desperation to support stock price artificially."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Basic"]},{"id":"q-1836","t":"mkt","l":"Basic","s":90,"q":"How would you determine whether to recommend a growth-focused strategy versus a cost-reduction strategy to a company?","k":["Key considerations include:","Market Position: Growth strategies suit expanding markets with share opportunity; cost reduction fits mature/declining markets","Competitive Advantage: Strong differentiation supports growth; weak positioning favors efficiency","Financial Health: Strong balance sheet enables growth investment; distressed situations require cost focus","Return Profile: Compare incremental revenue ROI versus cost reduction ROI","Time Horizon: Growth requires longer payback; cost cuts deliver immediate impact","Stakeholder Priorities: Growth for market leadership; cost reduction for profitability/margin expansion","Often, a balanced approach combining both strategies is optimal."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Basic"]},{"id":"q-1837","t":"mkt","l":"Basic","s":90,"q":"Rank the following companies by their expected Beta, from lowest to highest, and explain your reasoning:\n\n\n\nBlackrock\nConEdison\nCostco\nA pre-revenue Biotech Startup","k":["From lowest to highest Beta:","ConEdison (Lowest Beta)","Costco","Blackrock","Pre-revenue Biotech Startup (Highest Beta)","Reasoning:","ConEdison: Regulated utility with stable, predictable cash flows and minimal economic sensitivity. Very low beta.","Costco: Defensive consumer staples retailer with recession-resistant business model. Low-to-moderate beta.","Blackrock: Asset manager with earnings tied to market performance and AUM fluctuations. Moderate-to-high beta.","Biotech Startup: Highly volatile with binary clinical outcomes, no revenue, and significant cash burn risk. Very high beta."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Basic"]},{"id":"q-1838","t":"mkt","l":"Basic","s":90,"q":"Is the S&P 500's forward P/E multiple higher or lower now than it was a year ago?\n\n\n\n\nExplain the drivers.","k":["This requires current market knowledge. Framework for your answer:","State the directional change based on recent data.","Key drivers to discuss:","Interest rate environment (Fed policy, Treasury yields)","Earnings growth expectations and revisions","Economic outlook (recession fears, soft landing scenarios)","Sector composition changes (Tech concentration effects)","Risk sentiment and market positioning","Support with specific examples (e.g., \"Multiple expanded despite rate hikes due to AI-driven earnings optimism in mega-cap Tech\")."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Basic"]},{"id":"q-1839","t":"mkt","l":"Basic","s":90,"q":"Compare and contrast home, student, and auto loans.\n\n\n\n\nWhat are the key drivers of their respective interest rates?","k":["Comparison:","Home (Mortgages): Long-term (15-30 yrs), secured by real estate, lowest rates","Auto: Medium-term (3-7 yrs), secured by vehicle, moderate rates","Student: Long-term (10-25 yrs), typically unsecured, variable rates","Interest Rate Drivers:","Collateral quality: Homes appreciate (lower rates), cars depreciate (higher rates)","Loan-to-Value (LTV): Higher LTV increases risk and rates","Credit risk: Student loans lack collateral (highest unsecured rates)","Government backing: Federal student loans have subsidized rates","Duration: Longer terms generally mean higher rates","Prepayment risk: Mortgages have refinancing risk"],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Basic"]},{"id":"q-1840","t":"mkt","l":"Basic","s":90,"q":"What are 2 or 3 of the most important things in the news right now that will impact the M&A market in the near term?","k":["This requires current market knowledge. Framework for your answer:","Select 2-3 major themes such as:","Interest rate environment and Fed policy (impacts financing costs, valuation multiples)","Regulatory environment (FTC/DOJ scrutiny, antitrust enforcement)","Geopolitical tensions (China relations, tariffs, CFIUS)","Industry-specific disruption (AI, energy transition, banking stability)","Credit market conditions (debt availability, covenant terms)","For each theme, explain the direct impact on deal volume, pricing, structure, or buyer/seller dynamics with recent examples."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Basic"]},{"id":"q-1841","t":"mkt","l":"Basic","s":90,"q":"What are the primary tools the Federal Reserve uses to influence interest rates?","k":["The Federal Reserve's primary tools:","Federal Funds Rate: Target rate for overnight interbank lending; influences all other rates.","Open Market Operations: Buying/selling government securities to manage money supply.","Discount Rate: Rate at which banks borrow directly from the Fed.","Reserve Requirements: Percentage of deposits banks must hold (rarely changed).","Quantitative Easing (QE): Large-scale asset purchases to inject liquidity and lower long-term rates.","Forward Guidance: Communicating future policy intentions to influence expectations."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Superday","Market Knowledge","Basic"]},{"id":"q-1842","t":"mkt","l":"Basic","s":90,"q":"Describe the general trajectory of the S&P 500 over the past 50 years, highlighting major bull and bear markets and the key events that drove them.","k":["Key periods over the past 50 years:","1970s: Stagflation, oil crises, high inflation. Weak performance.","1980s-1990s: Strong bull market driven by falling inflation, Reagan policies, tech boom.","2000-2002: Dot-com bubble burst. Major bear market.","2003-2007: Recovery and housing boom.","2008-2009: Financial crisis. S&P fell ~57% peak-to-trough.","2009-2020: Longest bull market in history, driven by QE, low rates, tech growth.","2020: COVID crash (33% decline in weeks), followed by rapid recovery.","2022: Bear market due to inflation and rate hikes.","2023-2024: Recovery driven by AI optimism and resilient economy.","Overall trajectory: Long-term upward trend despite periodic crises, reflecting economic growth and corporate earnings expansion."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Superday","Market Knowledge","Basic"]},{"id":"q-1843","t":"mkt","l":"Basic","s":90,"q":"Tell me about a company you are following.\n\n\n\nWhat is its strategy and why is it pursuing it?\nHow has its share price performed over the last year?\nHow is it valued compared to its peers and why?","k":["This is an open-ended question designed to test your market knowledge and ability to discuss companies intelligently.","Strong answers should:","Pick a company relevant to the interviewer's coverage area or current market trends.","Clearly articulate the company's strategic priorities (growth initiatives, cost reduction, M&A, etc.).","Discuss recent stock performance with context (market conditions, earnings, news events).","Compare valuation multiples (P/E, EV/EBITDA) to peers and explain drivers (growth, margins, risk).","Show genuine interest and understanding of the business model.","Prepare 2-3 companies in advance with detailed knowledge of their financials, strategy, and recent developments."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Superday","Market Knowledge","Basic"]},{"id":"q-1844","t":"mkt","l":"Basic","s":90,"q":"Over the past 10 years, would you expect SOFR to have been generally higher or lower than its current level? Why?\n\n\n\n\nFollow-up: Looking ahead to the next 10 years, do you expect SOFR to be higher or lower than today? Why?","k":["Past 10 Years","SOFR was generally lower than today.","From 2015-2021, the Fed kept rates near zero following the financial crisis and during COVID-19. SOFR averaged 0-2%. Since 2022, aggressive Fed hiking to combat inflation pushed SOFR to 5%+. Current levels are historically elevated compared to the past decade's average.","Next 10 Years","Likely lower than today, assuming inflation normalizes and the Fed cuts rates. Long-term equilibrium (neutral rate) is estimated at 2.5-3.5%, below current levels. However, structural factors (deficits, demographics) could keep rates higher than the 2010s."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Basic"]},{"id":"q-1845","t":"mkt","l":"Basic","s":90,"q":"Discuss current healthcare trends and their impact on healthcare M&A.","k":["While this specific question is likely to only be asked if interviewing with a Healthcare group, it's prudent to prepare to answer this question for whichever industry group you are interviewing for or most interested in.","Sample answer (2025):","Key trends: telehealth adoption, value-based care, consolidation among hospital systems, and pharma pipeline expansions. These create opportunities for vertical/horizontal integration.","M&A deals often aim for cost synergies, expanded patient reach, broader service offerings, or new R&D pipelines."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Wells Fargo Interview","Market Knowledge","Basic"]},{"id":"q-1846","t":"mkt","l":"Basic","s":90,"q":"What are your views on current economic conditions and how do they affect M&A and capital-raising markets?","k":["Broad guidance:","If the economy is expanding with low interest rates, M&A and financings are generally robust. If rates rise or a recession looms, valuations compress, deals slow, or become distressed-driven.","You’d tie in any real-time events (e.g., central bank policy, inflation, geopolitical changes) to the effect on deal-making.","Sample answer (2025):","With modest GDP growth and cooling inflation, the Fed’s pause (and expected rate cuts) keep financing accessible, supporting deals in AI and energy sectors.","Tariff uncertainty and tighter regulatory reviews steer most activity toward bolt-on and mid-market transactions rather than mega-mergers.","Compressed multiples amid stagflation fears are offset by an abundance of PE dry powder, sustaining mid-market deal flow.","Debt markets remain selective with elevated spreads, but refinancing and LBOs should rebound post-cut; equity issuance is strongest in high-growth tech IPO windows."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Wells Fargo Interview","Market Knowledge","Basic"]},{"id":"q-1847","t":"mkt","l":"Basic","s":90,"q":"What are some market metrics you should keep top of mind as an Investment Banker?","k":["Equity indices: S&P 500, Dow Jones, Nasdaq -- know the levels and YTD performance.","Interest rates: Fed Funds rate, 10-year Treasury yield, 2-year Treasury yield, yield curve shape (inverted vs. normal).","Credit spreads: Investment grade and high yield spreads over Treasuries -- indicate credit market health and borrowing costs.","Commodity prices: Oil (WTI/Brent), gold, natural gas -- especially relevant for energy and industrials coverage.","FX rates: USD/EUR, USD/JPY -- important for cross-border M&A.","Volatility: VIX (the \"fear index\") -- elevated VIX signals market uncertainty and can slow deal activity.","M&A and IPO volumes: YTD deal count and dollar volume vs. prior year -- signals market appetite for transactions.","Inflation: CPI and PCE readings -- drives Fed policy, which affects all of the above."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Wells Fargo Interview","SA 2026, First round","Market Knowledge","Basic"]},{"id":"q-1848","t":"mkt","l":"Advanced","s":90,"q":"A company is trading at 8x EBITDA with 6x leverage. It has three divisions with EBITDA margins of 12%, 8%, and 2%.\n\n\n\n\nThe CEO believes the stock is undervalued. What recommendations would you give to boost the share price?","k":["Recommendations:","Divest Low-Margin Division: Sell 2% EBITDA margin division. Proceeds can delever (reducing 6x leverage) or return capital to shareholders. Improves blended margins, likely expanding multiple.","Operational Improvements: Focus on expanding margins in 8% and 12% divisions through cost cuts or pricing power.","Deleveraging: Use FCF or divestiture proceeds to pay down debt. Lower leverage reduces financial risk, potentially expanding valuation multiple.","Strategic Communication: Articulate clear strategy and margin improvement plan to investors to re-rate the stock.","Share Buybacks: If stock is truly undervalued and after deleveraging, repurchase shares to boost EPS.","Priority: Divest the 2% margin division and use proceeds to delever. This improves both profitability and financial risk profile, likely expanding the multiple."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Bank of America Interview","M&A, First round","Market Knowledge","Advanced"]},{"id":"q-1849","t":"mkt","l":"Advanced","s":90,"q":"What were the primary causes of the 2008 financial crisis?","k":["Primary causes:","Excessive sub-prime mortgage lending with lax underwriting standards","Securitization of mortgages into complex MBS and CDOs, spreading risk throughout financial system","Rating agencies assigning AAA ratings to risky mortgage-backed securities","High leverage at financial institutions amplifying losses when housing prices declined","Lack of regulation and oversight of shadow banking system and derivatives","Housing bubble fueled by low interest rates and speculation","Interconnectedness of global financial institutions spreading contagion","Collapse of major institutions (Lehman Brothers, Bear Stearns) triggering panic","The crisis resulted in the Great Recession, massive government bailouts, and significant regulatory reforms including Dodd-Frank."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Barclays Interview","Superday","Market Knowledge","Advanced"]},{"id":"q-1850","t":"mkt","l":"Advanced","s":90,"q":"Tell me about a company you're interested in that you believe is undervalued. Why do you think it is undervalued?","k":["Choose a company you can speak about with genuine depth — ideally one you have followed closely, analyzed in a class, or encountered through prior work experience. Avoid overly obvious picks like Apple or Amazon unless you have a truly differentiated thesis.","Present a clear valuation argument. Reference specific metrics: the company trades at a discount to peers on EV/EBITDA or P/E, the market is mispricing its growth trajectory, or there is a catalyst (new product launch, regulatory change, activist involvement) that has not been reflected in the stock price.","Demonstrate that you understand the bear case and why the market may be undervaluing the company. Acknowledge the risks and explain why you believe they are overstated or already priced in.","Keep the pitch structured: (1) what the company does, (2) why it is undervalued with supporting data, (3) the catalyst that will unlock value, and (4) the key risks. This mirrors how a banker would frame a recommendation to a client."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Evercore Interview","SA 2027, M&A group, New York Office, First round","Market Knowledge","Advanced"]},{"id":"q-1851","t":"mkt","l":"Advanced","s":90,"q":"Can you provide an example of an asset or a type of company that might have a negative Beta?","k":["Gold mining companies or Treasury bonds can have negative Betas.","When the market declines, investors flee to safe-haven assets like gold or government bonds, driving their prices up while the broader market falls.","This inverse relationship to market movements creates a negative Beta."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Goldman Sachs Interview","First round","Market Knowledge","Advanced"]},{"id":"q-1852","t":"mkt","l":"Advanced","s":90,"q":"Can you give an example of a type of company that might have a Beta of zero? Explain the rationale.","k":["A money market fund or short-term Treasury bill fund could have a Beta near zero.","Rationale:","Beta of zero means no correlation with market movements.","These investments have virtually no volatility or market risk.","Returns are stable regardless of equity market performance.","Effectively represents the risk-free rate component of the market."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Goldman Sachs Interview","Market Knowledge","Advanced"]},{"id":"q-1853","t":"mkt","l":"Advanced","s":90,"q":"Why has inflation been relatively low despite strong wage growth and historically low unemployment rates?\n\n\n\n\nFollow up: Do you think inflation will go up this year? If so, what impact would that have on stock prices and P/E ratios?","k":["Part 1: Low Inflation Despite Strong Labor Market","Possible explanations:","Productivity gains offsetting wage increases, keeping unit labor costs in check.","Globalization and technology reducing pricing power for goods and services.","Anchored inflation expectations due to credible central banks.","Structural changes in the economy (e.g., rise of gig economy).","Part 2: Inflation Impact on Stocks and P/E","Rising inflation typically leads central banks to raise rates, increasing discount rates and lowering present value of future cash flows.","This generally compresses P/E ratios as investors demand higher returns. Growth stocks are often hit harder than value stocks due to longer-duration cash flows.","However, some companies with pricing power may maintain margins, partially offsetting negative valuation impact."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in J.P. Morgan Interview","Chicago office, Superday","Market Knowledge","Advanced"]},{"id":"q-1854","t":"mkt","l":"Advanced","s":90,"q":"How would you evaluate a business in diligence?","k":["Walk through a structured framework. Start with understanding the business model: revenue drivers, customer concentration, end-market dynamics, and competitive positioning.","Move to financial analysis: historical revenue growth trends, margin profile and trajectory, capital expenditure requirements, working capital dynamics, and free cash flow generation.","Discuss qualitative diligence: management team quality, key customer and supplier relationships, regulatory risks, and any pending litigation or contingent liabilities.","Highlight how you synthesized the quantitative and qualitative findings into an investment thesis — identifying key risks, mitigants, and the core value creation levers.","If possible, reference a specific example from your internship experience to make the framework concrete."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in J.P. Morgan Interview","SA 2027","Market Knowledge","Advanced"]},{"id":"q-1855","t":"mkt","l":"Advanced","s":90,"q":"What is the S&P 500 trading at?\n\n\n\n\nFollow-up 1: What is Bitcoin trading at?\n\n\n\n\nFollow-up 2: What is the P/E of the S&P 500?","k":["You should have a rough idea of where the S&P500, DJIA, Nasdaq Composite, Russell 2000 and Bitcoin are trading (price and P/E).","You should also know the same for the bank you are interviewing at, if they are a publicly traded company (price, P/E and name of CEO).","Sample answer in June 2025:","S&P 500: 6000 (28x P/E ratio)","Bitcoin: Trading at $105K"],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Jefferies Interview","SA 2026, New York office, M&A group","Market Knowledge","Advanced"]},{"id":"q-1856","t":"mkt","l":"Advanced","s":90,"q":"Why might an investor choose to purchase a AAA-rated bond that has a negative yield?","k":["Capital preservation and regulatory or mandate compliance.","Institutional investors may need high‑quality liquid assets for liquidity ratios, collateral, or central‑bank deposit requirements.","A slightly negative yield can still outperform deeper negative deposit rates or avoid risk of volatile alternatives.","Expectation of deflation or currency appreciation boosts real return despite negative nominal yield."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Lazard Interview","Market Knowledge","Advanced"]},{"id":"q-1857","t":"mkt","l":"Advanced","s":90,"q":"Why might a company choose to finance its organic growth with mezzanine debt instead of a traditional senior term loan?","k":["Flexibility without immediate dilution.","Mezzanine often has longer maturities, PIK options, and looser covenants.","It bridges a capital need when senior leverage ceiling is reached.","Can be structured with warrants or conversion features, lowering cash coupon.","Faster execution than an equity raise and preserves voting control."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Lazard Interview","Market Knowledge","Advanced"]},{"id":"q-1858","t":"mkt","l":"Advanced","s":90,"q":"What is the current state of the global economy?\n\n\n\n\nFollow-up 1: Why do you think there is a disconnect between consumer confidence and business leader sentiment?","k":["State of the Global Economy:","Discuss key macroeconomic themes: inflation trends, central bank policies (interest rates), and GDP growth forecasts for major regions (US, Europe, Asia).","Mention current capital markets environment (M&A, IPO activity) and key geopolitical or sector-specific risks.","Disconnect in Sentiment:","Consumer Confidence: Often driven by lagging indicators like current employment levels and wage growth.","Business Sentiment: Tends to be forward-looking, focusing on factors like future interest rate hikes, credit availability, input costs, and potential for a recession, which may not have fully impacted consumers yet."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Lazard Interview","New York office, First round","Market Knowledge","Advanced"]},{"id":"q-1859","t":"mkt","l":"Advanced","s":90,"q":"In a lowering interest rate environment, would you use a growth-based or value-based investing approach? Why?","k":["In a lowering interest rate environment, growth-based investing tends to outperform.","Lower rates reduce the discount rate applied to future cash flows. Growth companies derive most of their value from cash flows far in the future, so their valuations are more sensitive to changes in the discount rate. A lower discount rate disproportionately increases the present value of distant cash flows, boosting growth stock valuations.","Lower borrowing costs support growth companies' expansion plans, as they can raise capital more cheaply to fund R&D, customer acquisition, and market expansion.","Investor preference shifts toward growth in low-rate environments because fixed income yields become less attractive, pushing capital into higher-growth equities.","Conversely, value investing tends to outperform in rising rate environments, as higher rates compress growth stock valuations and make the stable, near-term cash flows of value companies relatively more attractive."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Mizuho Interview","SA 2027, Superday","Market Knowledge","Advanced"]},{"id":"q-1860","t":"mkt","l":"Advanced","s":90,"q":"Which companies have a negative beta? Do stocks have intrinsic value?","k":["True negative‑β equities are rare but include:","Gold‑linked royalty companies","Certain counter‑cyclical utilities","Inverse‑market ETFs (structurally short beta)","Stocks absolutely have intrinsic value — the PV of after‑tax cash flows — even if prices deviate from that value short‑term."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Moelis & Co. Interview","First round","Market Knowledge","Advanced"]},{"id":"q-1861","t":"mkt","l":"Advanced","s":90,"q":"2025 market outlook.\n\n\n\n\nFollow-up 1: Any rate cuts expected?\n\n\n\n\nFollow-up 2: How will tariffs affect the market?","k":["The 2025 market outlook is less important than knowing the market outlook for the next year and how major policy decisions (rate cuts, tariffs, etc). will affect the market.","Sample answer for 2025:","Consensus foresaw moderate global GDP growth (~2–3%) with inflation easing toward targets and corporate earnings up mid‑single digits.","Follow‑up 1: The market expected 50 bps of rate cuts for 2025, implying just two quarter-point reductions.","Follow‑up 2: New tariffs were expected to slow growth, raise inflation and volatility, and shift economic activity toward manufacturing at the expense of other sectors, while also increasing costs for consumers and businesses."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Morgan Stanley Interview","SA 2026","Market Knowledge","Advanced"]},{"id":"q-1862","t":"mkt","l":"Advanced","s":90,"q":"What is the impact of circular finance on investment banking?","k":["Circular finance refers to financial models and instruments that support the circular economy - an economic system focused on eliminating waste, extending product lifecycles, and recycling materials rather than the traditional linear \"make, use, dispose\" model.","Impact on Investment Banking:","New deal flow: M&A advisory for companies in recycling, waste-to-energy, remanufacturing, and sustainable materials is growing.","Green/sustainable debt issuance: Banks underwrite green bonds, sustainability-linked loans, and transition bonds for companies adopting circular models.","Valuation considerations: Circular business models (e.g., product-as-a-service) have different revenue recognition and asset profiles, requiring adapted valuation frameworks.","ESG integration: Institutional investors increasingly screen for circular economy alignment, affecting capital markets execution and investor targeting.","Regulatory tailwinds: EU regulations (e.g., Corporate Sustainability Reporting Directive) are driving corporate transitions, creating advisory opportunities."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Superday","Market Knowledge","Advanced"]},{"id":"q-1863","t":"mkt","l":"Advanced","s":90,"q":"In a financial context, what does 'firepower' mean?\n\n\n\n\nWhat are some ways a company can increase its firepower?","k":["Firepower refers to available capital or financial resources a company can deploy for strategic initiatives like acquisitions, investments, or growth.","Ways to increase firepower:","Raise debt or equity capital.","Improve cash flow generation through operational efficiency.","Divest non-core assets to raise cash.","Reduce dividend payments or share buybacks.","Establish credit facilities or revolvers.","Form strategic partnerships or joint ventures."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Perella Weinberg Interview","New York Office, First round","Market Knowledge","Advanced"]},{"id":"q-1864","t":"mkt","l":"Advanced","s":90,"q":"Part 1: Tell me about a company you have been following.\n\n\n\n\nFollow-up: If you were the CEO, what strategic levers would you focus on building out the most?\n\n\n\n\nFollow-up: What would a future acquirer of this company look like? Would it more likely be a financial sponsor or a strategic buyer? What industries would be most interested?","k":["Framework for structuring your answer:","Part 1: Company Overview","Brief description: What the company does, its market position, and recent performance.","Key metrics: Revenue, EBITDA, growth rate, valuation multiple.","Why it interests you: Sector trends, competitive dynamics, or recent developments.","Strategic Levers as CEO:","Identify 2-3 specific initiatives: product expansion, geographic growth, M&A, cost optimization, digital transformation.","Quantify the impact where possible.","Potential Acquirer:","Strategic vs. financial: Strategic if there are clear synergies; financial if the company has stable cash flows and LBO characteristics.","Which industries: Adjacent sectors seeking capabilities, technology, or market access.","Specific potential buyers and rationale.","Prepare a specific company with real data before your interview."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in PJT Partners Interview","SA 2027","Market Knowledge","Advanced"]},{"id":"q-1865","t":"mkt","l":"Advanced","s":90,"q":"How did the FRB's actions during the COVID-19 pandemic impact the markets?\n\n\n\n\nSpecifically, how would they impact M&A, ECM, DCM, and LevFin/LBO practices?","k":["The specific example here of COVID-19 is less important than understanding the implications of major global events on the capital markets.","Example response for the specific example of COVID-19:","Massive liquidity injection and rate cuts did four things:","DCM – record‑low yields → jumbo issuance and opportunistic refinancings.","LevFin/LBO – cheaper debt pushed sponsor IRRs up → surge in take‑private activity.","ECM – valuations expanded; issuers rushed SPACs, IPOs, and follow‑ons.","M A – initial pause, then boom as cheap capital and strong equity currency fueled strategic deals.","Policy backstop reduced credit risk premia, compressing spreads and encouraging risk‑on behavior across products."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in UBS Interview","SA 2026, New York office, Superday","Market Knowledge","Advanced"]},{"id":"q-1866","t":"mkt","l":"Advanced","s":90,"q":"Given the current market conditions, how do you view the leveraged loan market versus the high-yield bond market?","k":["This question requires a current market assessment. A strong answer would address:","Relative spreads and pricing in each market.","Issuance volumes and market accessibility.","Investor demand (CLOs for loans, mutual funds/insurance for bonds).","Covenant protections (loans typically have maintenance covenants, bonds have incurrence covenants).","Interest rate sensitivity (floating-rate loans vs. fixed-rate bonds).","Recent regulatory or macroeconomic factors affecting each market.","Your answer should reflect knowledge of recent transactions, spread levels, and Fed policy impact."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Advanced"]},{"id":"q-1867","t":"mkt","l":"Advanced","s":90,"q":"During a major economic downturn, such as the COVID-19 pandemic, what is the typical impact on interest rates?\n\n\n\n\nHow do these changes in interest rates affect a company's WACC and its overall valuation?","k":["Impact on Interest Rates","Central banks typically lower interest rates during downturns to stimulate economic activity and provide liquidity.","Impact on WACC","Cost of Debt: Decreases due to lower base rates.","Cost of Equity: May increase due to higher risk premiums and equity market volatility, or decrease if risk-free rate falls significantly.","Net Effect: WACC typically decreases, though the magnitude depends on capital structure and risk profile.","Impact on Valuation","Lower WACC (discount rate) increases present value of future cash flows, leading to higher valuations - all else equal. However, downturns also pressure cash flows, which can offset the discount rate benefit."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Advanced"]},{"id":"q-1868","t":"mkt","l":"Advanced","s":90,"q":"During a severe industry downturn, such as the COVID-19 pandemic for airlines, what strategic and financial advice would you give to an airline's management team?","k":["Immediate priorities:","Preserve liquidity: Draw credit lines, negotiate with creditors, defer capex","Reduce cash burn: Ground aircraft, furlough staff, renegotiate contracts","Access government support: Loans, grants, payroll support programs","Capital structure actions:","Raise emergency capital (debt/equity, even if dilutive)","Restructure existing debt (covenant relief, maturity extensions)","Consider Ch. 11 if balance sheet unsustainable","Strategic positioning:","Consolidate around profitable routes/hubs","Accelerate digital transformation and cost initiatives","Position for recovery (maintain critical assets/routes)"],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Advanced"]},{"id":"q-1869","t":"mkt","l":"Advanced","s":90,"q":"Tell me about a company you're following. Then, answer the following:\n\n\n\nWalk me through its Income Statement.\nWhat are its valuation multiples now and what were they a year ago?\nWhy have the multiples changed?\nHow do its multiples compare to its main competitors and why?\nWhat is its approximate cost of capital?","k":["This requires personal company research. Framework to structure your answer:","Part 1: Income Statement","Revenue → COGS → Gross Profit → OpEx → EBITDA → D&A → EBIT → Interest → EBT → Tax → Net Income. Include actual figures and margins.","Part 2: Valuation Multiples","State current and historical EV/EBITDA, EV/Revenue, P/E with specific numbers.","Part 3: Multiple Changes","Explain drivers: earnings growth, margin expansion/compression, sector rotation, company-specific events, rate environment.","Part 4: Peer Comparison","Compare to 2-3 competitors, explain premium/discount based on growth, margins, market position.","Part 5: Cost of Capital","Estimate WACC using beta, market risk premium, debt levels, tax rate."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Advanced"]},{"id":"q-1870","t":"mkt","l":"Advanced","s":90,"q":"What is your view on Tesla's current valuation?\n\n\n\n\nWhat special considerations would you include in a DCF model for the company?","k":["This is subjective and depends on current market conditions. A strong answer demonstrates knowledge of Tesla's business model and valuation drivers.","Special DCF considerations:","Multiple revenue streams: auto sales, energy storage, software (FSD), potential robotics.","High growth assumptions with significant uncertainty around adoption rates.","Capital intensity of manufacturing expansion vs. software margins.","Regulatory credits as declining revenue source.","Optionality value from autonomous driving and AI capabilities.","Scenario analysis for different penetration rates and timing."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Advanced"]},{"id":"q-1871","t":"mkt","l":"Advanced","s":90,"q":"Estimate the Total Addressable Market (TAM) for residential swimming pools in the United States.","k":["Estimation approach:","US Households: ~130M.","Homeownership Rate: ~65%, so ~85M owner-occupied homes.","Suitable Climate/Property: ~30% of homes (warm climates, sufficient yard) = ~25M homes.","Penetration Potential: Assume 20-30% could afford/desire pools = 5-7.5M potential pools.","Average Pool Cost: $50K (installation + equipment).","TAM = 6M homes * $50K = ~$300B (one-time installation).","Annual market is smaller (new builds, replacements), likely $10-20B annually."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Advanced"]},{"id":"q-1872","t":"mkt","l":"Advanced","s":90,"q":"What are the potential benefits and considerations of a merger between Apple and Tesla?\n\n\n\n\nWhat is your overall recommendation on the transaction?","k":["Potential Benefits:","Technology synergies: Apple's software/chip expertise with Tesla's autonomous driving.","Distribution leverage: Apple's retail footprint and brand loyalty.","Vertical integration: Control over hardware, software, and AI.","Battery technology: Shared R&D for energy storage.","Considerations:","Cultural fit: Different management styles and corporate cultures.","Regulatory scrutiny: Antitrust concerns given combined market power.","Integration complexity: Manufacturing vs. consumer electronics.","Valuation: Tesla's premium valuation makes deal expensive.","Recommendation:","Likely not advisable. Significant cultural and operational differences outweigh synergies. Strategic partnership more feasible than full merger."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Market Knowledge","Advanced"]},{"id":"q-1873","t":"mkt","l":"Advanced","s":90,"q":"Part 1: What is the yield curve and what can its shape (e.g., normal, inverted, flat) signal about the economy?\n\n\n\n\nPart 2: What is the Phillips curve and what relationship does it describe?","k":["Part 1: Yield Curve","The yield curve plots interest rates of bonds with equal credit quality but different maturity dates.","Normal (upward sloping): Longer-term rates higher than short-term. Signals healthy, growing economy.","Inverted: Short-term rates higher than long-term. Often precedes recession (market expects rate cuts).","Flat: Little difference between short and long-term rates. Signals economic uncertainty or transition.","Part 2: Phillips Curve","The Phillips curve describes an inverse relationship between unemployment and inflation: when unemployment is low, inflation tends to be high, and vice versa.","Modern economics recognizes this relationship can break down (e.g., stagflation in 1970s), and central banks target both low unemployment and low inflation."],"collection":"practice","topic":"Market Knowledge","tags":["Reported in Unspecified Interview","Superday","Market Knowledge","Advanced"]},{"id":"q-1874","t":"mkt","l":"Advanced","s":90,"q":"How would you guide a CFO on equity and debt issuance in the current inflation and interest rate environment?","k":["Structure your advice around the current macro backdrop and the company's specific needs:","Debt Issuance Considerations","With rates declining from the 2023-2024 peak but still elevated (~4.25-4.50% Fed Funds), borrowing costs remain above historical averages. Consider locking in fixed-rate debt now if you expect rates to stabilize or tick back up.","If the company can wait, further rate cuts expected in 2026 could reduce borrowing costs. However, timing the market carries risk.","Credit spreads are relatively tight, making it a favorable window for investment-grade issuers.","Equity Issuance Considerations","Equity markets are strong with the S&P 500 near all-time highs, making it a favorable window for equity issuance at elevated valuations.","If the stock is trading at a premium, issuing equity now locks in a high valuation and avoids the uncertainty of future market conditions.","Consider a follow-on offering if the company needs growth capital and wants to reduce leverage.","The recommendation depends on the company's current leverage, growth plans, and risk tolerance. A blended approach (some debt, some equity) may be optimal for capital structure flexibility."],"collection":"practice","topic":"Market Knowledge","tags":["New","Reported in Wells Fargo Interview","SA 2026, First round","Market Knowledge","Advanced"]},{"id":"q-1875","t":"deal","l":"Basic","s":90,"q":"What is a distressed situation you have been following?","k":["Broad guidance:","Provide a real example of a struggling company or industry in financial distress. Summarize capital structure, reasons for distress, and potential restructuring paths.","Sample answer (2025): Diamond Sports Group Restructuring","Filed Chapter 11 in early 2024 under heavy debt and cord-cutting pressures on its regional sports networks.","Restructuring plan streamlined operations, renegotiated broadcast rights, and converted debt to new equity under creditor support.","Plan confirmed by late 2024, enabling emergence in early 2025 as Main Street Sports Group with most legacy debt eliminated.","Secured new streaming partnerships while retaining core NBA and NHL local rights under the rebranded RSN platform.","Ongoing risk from expiring team rights and the shift toward digital distribution, requiring further strategic adjustments."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1876","t":"deal","l":"Basic","s":90,"q":"How can a company raise cash if it’s in distress?","k":["Options include DIP financing, asset sales (non-core units, real estate), raising rescue capital (junior debt, preferred equity), or a structured deal with existing creditors.","They might also refinance near-term maturities, negotiate covenant relief, or do a sale-leaseback transaction on tangible assets."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1877","t":"deal","l":"Basic","s":90,"q":"The company has $40 EV, $50 secured debt, and $50 unsecured debt.\n\n\n\n\nWhy might unsecured trade above zero?","k":["Sometimes intangible value or expected reorganization changes actual recoveries. Even if pure liquidation suggests no leftover for unsecured, you might expect:","Debtor-in-possession financing or additional injection from new capital","A higher going-concern value if restructured (management synergy, strategic buyer interest)","Potential compromise from senior lenders, e.g., partial payoff or equity swap that leaves unsecured some upside"],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1878","t":"deal","l":"Basic","s":90,"q":"How would you create a masterlist of companies in distress?","k":["Start with screening criteria: high leverage (e.g., Debt/EBITDA > 5x), upcoming maturities in 1-2 years, negative free cash flow, or poor interest coverage.","Then cross-check SEC filings (10-K, 10-Q risk factors), rating agency downgrades, credit default swap spreads, or market signals (bonds trading at distressed levels under 80–90)."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1879","t":"deal","l":"Basic","s":90,"q":"What do you know about restructuring?","k":["Restructuring involves advising financially distressed companies or their creditors on options to address unsustainable debt loads and operational challenges.","Key areas:","Out-of-court restructuring: Negotiating with creditors for amended terms, debt exchanges, or liability management transactions without bankruptcy.","In-court restructuring: Chapter 11 bankruptcy, which allows the company to reorganize while protected from creditors. Involves filing a plan of reorganization.","Distressed M&A: Section 363 asset sales, credit bids, and stalking horse processes.","Creditor-side advisory: Representing bondholders, lenders, or ad hoc creditor groups in negotiations.","Key concepts: Absolute Priority Rule, DIP financing, adequate protection, fulcrum security, and waterfall analysis."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2025","Restructuring / Distressed M&A","Basic"]},{"id":"q-1880","t":"deal","l":"Basic","s":90,"q":"What do you know about Chapter 11 bankruptcy?","k":["Chapter 11 is a form of bankruptcy that allows a company to reorganize its business and debts while continuing operations under court supervision.","Key features:","Automatic stay: Immediately halts all creditor collection actions and lawsuits.","Debtor-in-possession (DIP): The company typically continues operating under existing management.","DIP financing: New loans with super-priority status to fund operations during bankruptcy.","Plan of reorganization: Proposed by the debtor (with exclusivity period) detailing how creditors will be treated. Must be approved by creditor classes and the court.","Absolute Priority Rule: Senior creditors must be paid in full before junior creditors receive any recovery.","Section 363 sales: Allows the company to sell assets free and clear of liens during bankruptcy.","Goal: Emerge as a viable, restructured company with a sustainable capital structure."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2025","Restructuring / Distressed M&A","Basic"]},{"id":"q-1881","t":"deal","l":"Basic","s":90,"q":"What market trends do you follow that are related to restructuring activity?","k":["Structure your answer around macroeconomic and credit market factors that drive restructuring volume:","Interest rates: Higher rates increase debt service costs for leveraged companies, pushing distressed situations.","Debt maturity walls: Large amounts of debt maturing in the near term can trigger liquidity crises.","Credit spreads: Widening spreads indicate market stress and reduced access to refinancing.","Sector-specific distress: Industries facing structural decline (e.g., retail, media, fossil fuels) generate restructuring mandates.","Leveraged loan and high-yield markets: Covenant-lite structures and aggressive leverage from prior years create future restructuring pipelines.","PE-backed companies: Over-levered sponsor-backed companies facing covenant breaches or cash flow pressure.","Prepare a specific current example with data points to demonstrate market awareness."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2025","Restructuring / Distressed M&A","Basic"]},{"id":"q-1882","t":"deal","l":"Basic","s":90,"q":"What deals do you follow that are related to restructuring activity?","k":["Structure your answer around a specific recent restructuring deal. Framework:","Company name, industry, and what triggered the distress (overleveraging, revenue decline, industry disruption).","Capital structure: Key debt tranches, leverage ratio, and where value breaks.","Process: Was it out-of-court (exchange offer, amend and extend) or in-court (Chapter 11)? Who advised?","Outcome: Recovery rates for each creditor class, new capital structure, equity ownership post-emergence.","Your view: Was the outcome fair to all parties? What would you have done differently?","Prepare 1-2 specific restructuring situations with concrete details before your interview."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2025","Restructuring / Distressed M&A","Basic"]},{"id":"q-1883","t":"deal","l":"Basic","s":90,"q":"What is the difference between in-court and out-of-court restructuring?","k":["Out-of-Court Restructuring","Negotiations happen privately between the company and its creditors without court involvement.","Faster, cheaper, and less disruptive to operations.","Requires voluntary agreement from creditors (typically through exchange offers, amendments, or forbearance agreements).","Holdout problem: Dissenting creditors cannot be forced to accept the restructured terms.","In-Court Restructuring (Chapter 11 Bankruptcy)","Filed under Chapter 11 of the U.S. Bankruptcy Code; the court oversees the process.","Automatic stay halts all creditor collection actions immediately.","Cramdown provision allows the court to force a plan on dissenting creditors, solving the holdout problem.","More expensive (legal and advisory fees), time-consuming, and carries reputational stigma.","DIP financing is available to fund operations during the process."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2026, First round","Restructuring / Distressed M&A","Basic"]},{"id":"q-1884","t":"deal","l":"Basic","s":90,"q":"What strategic alternatives would you provide to a large company that has been struggling lately?","k":["Key strategic alternatives to present:","Operational restructuring: Cost cutting, margin improvement, management changes, and refocusing on core competencies.","Divestitures: Sell non-core or underperforming divisions to raise cash and sharpen focus.","Strategic M&A: Acquire a complementary business to accelerate growth, gain technology, or enter new markets.","Sale of the entire company: Explore a full sale to a strategic or financial buyer at a premium.","Capital structure optimization: Refinance debt, buy back shares, issue equity, or cut/suspend dividends to improve financial flexibility.","Joint ventures or partnerships: Access new markets or capabilities without a full acquisition.","Take-private / LBO: If public, explore going private to execute a turnaround away from public market scrutiny.","Financial restructuring: If in distress, negotiate with creditors, pursue an exchange offer, or consider Chapter 11.","The right recommendation depends on the root cause of the underperformance, the company's liquidity position, and its competitive positioning."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Goldman Sachs Interview","SA 2026, First round","Restructuring / Distressed M&A","Basic"]},{"id":"q-1885","t":"deal","l":"Basic","s":90,"q":"What are characteristics of a distressed company?","k":["Distressed companies often have high leverage or upcoming debt maturities with insufficient cash to service or refinance obligations.","They may also display consistent negative cash flow, covenant breaches, limited liquidity, and deteriorating fundamentals, making it tough to raise capital on favorable terms."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Greenhill & Co. Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1886","t":"deal","l":"Basic","s":90,"q":"Why does TSLA, a company that does well in the equity markets, have a B credit rating?","k":["Credit ratings focus on default risk and cash flow volatility rather than equity market performance. Tesla’s high investment in R&D and production, heavier leverage or limited free cash flow can elevate credit risk despite a high equity valuation."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Greenhill & Co. Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1887","t":"deal","l":"Basic","s":90,"q":"What are the types of covenants?","k":["Covenants are generally split into Affirmative vs. Negative, or Maintenance vs. Incurrence.","Incurrence (Negative): Prevent the company from taking specific actions (e.g., issuing more debt, paying dividends). Common in High Yield.","Maintenance (Financial): Require the company to maintain specific financial metrics (e.g., Debt/EBITDA below 4.0x). Common in Bank Debt."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Greenhill & Co. Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1888","t":"deal","l":"Basic","s":90,"q":"Walk me through the capital stack from most senior to most junior.","k":["From most senior (first in line for repayment) to most junior:","Senior Secured Debt (Revolver, Term Loan A/B): Secured by company assets. First priority in bankruptcy. Lowest interest rate.","Senior Unsecured Debt (Bonds): No collateral backing. Higher interest rate than secured debt.","Subordinated / Mezzanine Debt: Junior to senior debt. Higher interest rates, often includes PIK component or equity warrants.","Preferred Equity: Has priority over common equity for dividends and liquidation proceeds. Fixed dividend, no voting rights typically.","Common Equity: Most junior. Last in line for any residual value. Highest risk but unlimited upside.","In bankruptcy, claims are paid in this order. Senior secured holders are typically made whole first, with each subsequent tranche receiving less recovery."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1889","t":"deal","l":"Basic","s":90,"q":"What are covenants in debt agreements? Can you give examples of different types of covenants?","k":["Covenants are contractual provisions in debt agreements that restrict the borrower's actions or require them to maintain certain financial metrics. They protect lenders by limiting risk.","Two main types:","Maintenance Covenants: Tested periodically (e.g., quarterly). If breached, it triggers a default. Examples: Maximum Debt/EBITDA ratio (e.g., cannot exceed 5.0x), Minimum Interest Coverage Ratio (EBITDA/Interest must exceed 2.0x), Minimum Fixed Charge Coverage Ratio.","Incurrence Covenants: Only tested when the borrower takes a specific action (e.g., issuing more debt, paying a dividend). Examples: Cannot incur additional debt if pro forma leverage exceeds 4.0x, Restricted payments basket (limits dividends and buybacks), Limitations on asset sales or investments.","Maintenance covenants are more common in bank loans (Term Loan A, revolvers). Incurrence covenants are typical in high-yield bonds and covenant-lite Term Loan Bs."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, First round","Restructuring / Distressed M&A","Basic"]},{"id":"q-1890","t":"deal","l":"Basic","s":90,"q":"A company has an Enterprise Value of $100 million. Its capital structure consists of $50 million in senior secured debt and $50 million in high-yield debt. At what price would you expect each tranche of debt to be trading?","k":["Both tranches trade at par.","EV covers total debt in full; equity is ~0.","Recovery assumption ⇒ senior and high‑yield both receive full par."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Moelis & Co. Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1891","t":"deal","l":"Basic","s":90,"q":"If a company has an Enterprise Value of $600 million and total debt of $1,200 million, approximately what price would the debt be trading at (as a percentage of par)?","k":["≈ 50¢ on the dollar.","Implied recovery = 600 / 1,200 = 50%.","Debt holders would get paid back first and receive that money, so the debt would be trading at approximately $0.50 on the dollar."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Moelis & Co. Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1892","t":"deal","l":"Basic","s":90,"q":"How would you value a company that is on the verge of bankruptcy?","k":["Apply your standard valuation approaches—public comps, precedent transactions, and DCF—but tweak assumptions and ranges for a distressed scenario:","Focus on the bottom end of multiples and incorporate all necessary accounting adjustments.","Use more conservative forecasts in DCFs and other projection‐based models to account for a turnaround period.","If EBIT, EBITDA, or EPS are negative, give greater weight to revenue multiples.","Perform a liquidation valuation to estimate what fire-sale asset proceeds would cover against claims.","Calculate values both on an assets-only basis and on an assets-minus-current-liabilities basis to reflect large liability adjustments in distress."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Moelis & Co. Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1893","t":"deal","l":"Basic","s":90,"q":"What are the primary goals of a corporate restructuring, and what are the main options available to a distressed company?","k":["Goal: Stabilise liquidity, right‑size the balance sheet, and maximise stakeholder recovery while preserving going‑concern value.","Main options:","Out‑of‑court exchange, amend­‑and‑extend, or covenant relief.","Debt‑for‑equity swap or equitisation of junior claims.","New‑money DIP financing or rescue capital.","Section 363 / Chapter 11 sale or full Chapter 11 reorganisation.","Distressed M&A, asset divestitures, or structured minority investment.","Chapter 7 liquidation if going‑concern value is irretrievable."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Moelis & Co. Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1894","t":"deal","l":"Basic","s":90,"q":"What roles do amendments play if a firm wants to extend the maturity on some bonds?","k":["Amendments let a borrower tweak credit agreement terms: extending maturity, adjusting covenants, or modifying principal/interest. In distress, you often need lender consent and possibly fees or higher rates. This can buy time to avoid default or restructure more systematically."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1895","t":"deal","l":"Basic","s":90,"q":"When would a firm prefer to do out of court and in court?","k":["Out-of-court workouts avoid high legal costs, preserve reputation, and can be faster if creditors agree. In-court (Chapter 11) is used when stakeholders can’t reach consensus, or there’s a need for automatic stay protection and court-supervised restructuring to cram down holdouts."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1896","t":"deal","l":"Basic","s":90,"q":"What are some of the causes of a firm being financially distressed?","k":["Excess leverage, deteriorating profitability, poor working capital management, macro shocks (e.g., recession, commodity price swings), major litigation or operational crises, and inability to adapt to market changes all can lead to distress."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1897","t":"deal","l":"Basic","s":90,"q":"What if they’re otherwise a healthy company but they file – what could be going on?","k":["Even healthy companies might use bankruptcy to shed liabilities, rewrite burdensome contracts, or restructure pension/union obligations. Some also use it strategically to gain leverage in negotiations or to implement a quick sale (363 process) if no out-of-court buyer emerges."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1898","t":"deal","l":"Basic","s":90,"q":"Why do companies file for chapter 11?","k":["Chapter 11 allows companies to reorganize under court protection, staying creditor enforcement actions while they negotiate or implement a plan. This can preserve going-concern value, secure DIP financing, reject certain contracts, and restructure debt in a legally binding way."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1899","t":"deal","l":"Basic","s":90,"q":"What % of DIP financing is typically funded by existing debtholders?","k":["It varies widely, but frequently the majority (60–80%) of DIP financing comes from existing lenders. They have the strongest incentive to protect collateral and avoid a liquidation scenario. If that group refuses, new third-party DIP lenders may step in, often with strict terms."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1900","t":"deal","l":"Basic","s":90,"q":"What are some exogenous causes for why a company goes into bankruptcy?","k":["Macroeconomic downturns, unexpected regulatory changes, commodity price shocks, pandemics (COVID-19), or supply chain disruptions can rapidly erode a company’s liquidity and push it into distress or eventual bankruptcy."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1901","t":"deal","l":"Basic","s":90,"q":"In a restructuring scenario, what forms of consideration can unsecured creditors expect to receive?","k":["Typically a mix of cash, new debt, and most often new equity in the reorganized entity.","Explanation:","Cash: Usually limited, reflects available exit financing or asset sales.","New Debt: Often at a lower coupon / longer maturity to reduce cash burden.","Equity / Warrants: Primary recovery tool; shifts unsecured creditors into owners.","No Recovery: If enterprise value > collateralized claims only, unsecured may be wiped."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1902","t":"deal","l":"Basic","s":90,"q":"What is an 'automatic stay' in the context of a bankruptcy proceeding?","k":["An immediate, court‑ordered injunction that halts virtually all creditor collection and litigation actions once the bankruptcy petition is filed.","Explanation:","Gives the debtor “breathing room” to reorganize without asset grabs.","Applies to foreclosures, lawsuits, guaranty enforcement, etc.","Can be lifted only by court order for cause (e.g., lack of adequate protection)."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1903","t":"deal","l":"Basic","s":90,"q":"Explain what Debtor-in-Possession (DIP) financing is and why a company would use it during a restructuring.","k":["Super‑priority, post‑petition funding that keeps the bankrupt company operating through Chapter 11.","Explanation:","Ranks ahead of pre‑petition claims (often priming liens with court approval).","Funds payroll, suppliers, and restructuring expenses.","Signals creditor confidence, stabilizes liquidity, and maximizes going‑concern value."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1904","t":"deal","l":"Basic","s":90,"q":"What is a technical default, and how does it differ from other types of default, such as a payment default?","k":["Technical default = breach of a non‑payment covenant (e.g., leverage ratio, reporting). Payment default = missed interest or principal.","Key Points:","Technical defaults often give lenders rights to demand cures, higher pricing, or additional collateral.","Payment defaults trigger acceleration and can force bankruptcy much faster."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1905","t":"deal","l":"Basic","s":90,"q":"Discuss the key trade-offs between a company raising capital via debt versus equity, and when you would recommend each option.","k":["Debt is cheaper and non‑dilutive but increases fixed obligations and financial risk; equity is costlier and dilutive but strengthens the balance sheet and preserves flexibility.","Recommend Debt When:","Stable, predictable cash flows cover interest.","Leverage below sector norms, ample covenant headroom.","Tax shield is valuable.","Recommend Equity When:","High growth requires large, long‑dated capital.","Existing leverage is high or rating sensitive.","Valuation is rich—low relative cost of equity."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1906","t":"deal","l":"Basic","s":90,"q":"Given that debt is typically cheaper than equity, why would a company choose to issue equity to fund its operations or growth?","k":["To avoid over‑leverage, protect ratings, fund negative cash flow projects, and capitalize on a high stock price.","Details:","Preserves liquidity and covenant cushion.","Reduces bankruptcy risk in cyclical industries.","Provides permanent capital for R&D or acquisitions without mandatory repayments."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1907","t":"deal","l":"Basic","s":90,"q":"What fundamental characteristics make debt a less risky security than equity, resulting in its higher position in the capital structure?","k":["Contractual cash flows, collateral, covenants, senior legal claim, and priority in liquidation.","Explanation:","Interest/principal are legally enforceable.","Often secured by specific assets.","Covenants allow early intervention.","Debt holders get paid before equity in bankruptcy."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1908","t":"deal","l":"Basic","s":90,"q":"What tools and mechanisms do lenders use to control for risk when extending credit to a borrower?","k":["Collateral, covenants, pricing, guarantees, amortization schedules, and monitoring.","Details:","Maintenance / incurrence covenants flag deterioration early.","Security interests and guarantees improve recovery.","Variable margins and fees compensate for risk.","Reporting requirements enable ongoing oversight."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1909","t":"deal","l":"Basic","s":90,"q":"What are some ways a distressed company can raise liquidity?","k":["Ways to raise liquidity:","Asset sales: Sell non-core or underperforming assets for immediate cash.","DIP (Debtor-in-Possession) financing: Secured lending during bankruptcy, senior to existing debt.","Factoring/ABL: Borrow against accounts receivable or asset-based lending facilities.","Restructure existing debt: Extend maturities, reduce interest, convert debt to equity.","Sale-leaseback: Sell property/equipment, lease it back.","Operational improvements: Accelerate collections, reduce inventory, cut costs.","Rights offering: Existing shareholders buy new equity at discount."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","New York Office","Restructuring / Distressed M&A","Basic"]},{"id":"q-1910","t":"deal","l":"Basic","s":90,"q":"In a liquidation or bankruptcy scenario, what is the order of claims on the company's assets?","k":["Priority of claims (highest to lowest):","DIP Financing & Administrative expenses (legal fees, trustee costs).","Secured creditors (backed by specific collateral).","Priority unsecured claims (employee wages, taxes).","General unsecured creditors (trade payables, senior unsecured bonds).","Subordinated debt.","Preferred equity.","Common equity.","In bankruptcy, claims are satisfied in this order with common equity typically receiving nothing in liquidation."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Unspecified Interview","Superday","Restructuring / Distressed M&A","Basic"]},{"id":"q-1911","t":"deal","l":"Basic","s":90,"q":"What is the difference between secured and unsecured debt?","k":["Secured Debt","Backed by specific collateral (assets, property, inventory).","In default, lender can seize collateral.","Lower interest rates due to lower risk.","Higher priority in bankruptcy.","Unsecured Debt","Not backed by specific collateral.","In default, lender is a general creditor.","Higher interest rates due to higher risk.","Lower priority in bankruptcy."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Unspecified Interview","Superday","Restructuring / Distressed M&A","Basic"]},{"id":"q-1912","t":"deal","l":"Basic","s":90,"q":"What ratio would you look at to evaluate the debt worthiness of a company?","k":["Primary: Debt ⁄ EBITDA.","Also track Interest Coverage (EBIT ⁄ Interest); stronger credit = lower leverage and higher coverage."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Wells Fargo Interview","Restructuring / Distressed M&A","Basic"]},{"id":"q-1913","t":"deal","l":"Advanced","s":90,"q":"You are advising a client and a creditor requires the client to pay a debt due in 2 weeks. How would you advise your client?","k":["Framework for advising the client:","Assess liquidity: Can the company pay? Check cash on hand, revolver availability, and near-term cash inflows.","If the company can pay: Evaluate whether paying is the best use of capital, negotiate any concessions, and pay to maintain creditor relationships.","If the company cannot pay: Negotiate with the creditor for an extension, amended terms, or forbearance agreement. Explore alternative funding sources (asset sales, new financing, equity raise).","Evaluate the broader picture: Is this an isolated liquidity issue or a sign of deeper financial distress? If the latter, consider a comprehensive liability management exercise or restructuring.","Legal considerations: Understand the consequences of non-payment (default triggers, cross-acceleration clauses, enforcement rights) before making a decision."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Bank of America Interview","SA 2025, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1914","t":"deal","l":"Advanced","s":90,"q":"A business has reported positive EBITDA for years.\n\n\n\n\nIt now announces huge EBITDA growth but still files for bankruptcy.\n\n\n\n\nHow is that possible?","k":["Cash flow could be insufficient due to high interest payments, debt maturities, large capex, or working capital needs. EBITDA doesn’t capture debt service or liquidity constraints.","Even with EBITDA growth, if you can’t service debt or refinance, you can be forced into bankruptcy."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1915","t":"deal","l":"Advanced","s":90,"q":"A HoldCo owns two SubCos, each with $50 million EBITDA.\n\n\n\n\nComps trade at 8x.\n\n\n\n\nSubCo 1 has $200 million senior debt and $300 million junior debt.\n\n\n\n\nSubCo 2 has $200 million senior debt.\n\n\n\n\nHoldCo itself has $200 million senior debt.\n\n\n\n\nWhere does each tranche of debt trade?","k":["Each SubCo EV = 50 × 8 = $400 M.","SubCo 1: EV $400M covers $200M senior (par) and recovers $200M of $300M junior (~67 ¢), so junior trades at a discount and equity is wiped out.","Senior $200 M at par.","Junior $300 M recovers $200 M (~67 ¢), trades at a discount.","Equity = $0.","SubCo 2: EV $400M covers $200M senior (par) with $200M equity.","Senior $200 M at par.","Equity = $200 M.","HoldCo: Assets (equity from SubCos) = $200M, covers $200M senior (par), leaving $0 equity.","Assets = $0 + $200 M = $200 M.","Senior $200 M at par.","Equity = $0."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1916","t":"deal","l":"Advanced","s":90,"q":"A home is valued at $500K, financed with 80% debt. The home value declines by 50%. What is the recovery?\n\n\n\n\nFollow-up 1: How can a distressed investor make a return if they buy the debt at 70?","k":["Initial Scenario","Home value: $500K → declines by 50% → new value $250K","Debt: 80% of $500K = $400K","After decline, house is worth $250K vs. $400K debt","Potential recovery for the lender is $250K if the house is foreclosed/sold","Hence $150K shortfall if fully repaid from sale proceeds is the “loss”","Follow-up 1","If an investor buys that $400K mortgage at 70 cents on the dollar ($280K):","Value of collateral is $250K, so the real coverage is close to $250K.","The investor might restructure or work out a deal. If they ultimately recover $300K, for example, they profit $20K above the $280K purchase.","Distressed investors look for underpriced credit relative to collateral and potential loan modifications to boost ultimate recoveries beyond the purchase price."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1917","t":"deal","l":"Advanced","s":90,"q":"$1B total debt: $500M secured trading at 90, $500M unsecured trading at 40.\n\n\n\n\nWhat would you analyze as a distressed investor?","k":["Distressed investors examine collateral coverage, likelihood of restructuring vs. liquidation, subordination, covenants, and possible recovery for each debt tranche.","The secured debt at 90 suggests it is better covered by assets; the unsecured at 40 implies higher risk. You’d model expected outcomes under multiple scenarios:","Going-concern vs. liquidation analysis for collateral","Whether junior notes might convert to equity or recover partially in a restructuring","Potential for DIP financing, interest deferrals, covenant waivers, and senior lenders forcing harsher terms"],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1918","t":"deal","l":"Advanced","s":90,"q":"The company has $200 EV, with $100 secured, $150 unsecured, and $150 equity. What are the recoveries?\n\n\n\n\nFollow-up 1: Secured only has claims on $50 of assets. How does it change?\n\n\n\n\nFollow-up 2: What if debt was fully secured but it was trading just under 100. Why would that be?","k":["Initial Scenario","Enterprise Value (EV) = $200M","Capital Stack: $100M secured, $150M unsecured, $150M equity","Total claims = $400M, but EV is $200M, so not everyone is fully paid.","Recoveries (assuming waterfall):","Secured: $100M fully covered","Remaining EV: $100M for the $150M unsecured, ~67% recovery","Equity: wiped out or $0","Follow-up 1","If the secured debt is only secured by $50M of assets, then beyond $50M, that portion effectively ranks alongside unsecured. So secured recovers $50M, the remaining $50M of that “secured” piece is on par with unsecured. You’d recalculate the recovery across that new combined claim.","Follow-up 2","Even if debt is fully secured, it may trade below par (<100) if the market fears operational or liquidity risks, prolonged restructuring, or legal complexities that might delay or reduce actual recoveries."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1919","t":"deal","l":"Advanced","s":90,"q":"The company has 60 EBITDA, 5x multiple, and $100 cash. What are the payouts for FL, Unsecured, and equity?","k":["If total enterprise value = 5× 60 = 300, plus 100 cash could mean a total value of $400. If capital structure includes first-lien (FL), unsecured, and equity, you'd pay them in that order using the $400 combined. The exact distribution depends on amounts and priority:","1) Satisfy FL. 2) If any left, pay unsecured. 3) If anything remains, that goes to equity. If FL + unsecured exceed $400, equity is wiped out.","The question’s details on actual principal amounts are needed for a full breakdown, but that is the typical waterfall approach."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1920","t":"deal","l":"Advanced","s":90,"q":"A company has $50mm in EBITDA and is trading at a 4x multiple. The company also has $100mm Senior debt and $200mm Junior debt. What is the Equity Value of this company? What is each tranche of debt trading at?","k":["Equity Value","EV = $50mm EBITDA × 4 = $200mm. Since total debt is $300mm, equity portion = EV - Debt. That implies negative $100mm, so equity is basically $0 in a distress scenario.","Debt Trading","Senior debt ($100mm) is likely covered by some portion of that $200mm EV, so it might trade near par (100%).","Junior debt ($200mm) recovers the leftover, if any, after senior is paid. With $200mm total EV and $100mm senior, junior has coverage up to $100mm out of $200mm principal. That’s a 50% coverage ratio, translating to ~50 cents on the dollar."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1921","t":"deal","l":"Advanced","s":90,"q":"Part 1: Given a basic capital structure for a distressed company, walk through a waterfall analysis to calculate the recovery rates for each debt tranche.\n\n\n\n\nPart 2: How would your analysis and the recovery rates change if the value of the company's collateral decreased?","k":["Part 1: Waterfall Analysis","Steps:","Determine Enterprise Value (liquidation value or going-concern value).","Pay secured debt first (up to collateral value).","Remaining proceeds to senior unsecured debt (pro rata if insufficient).","Then subordinated debt.","Finally, equity (typically receives nothing in distress).","Recovery Rate = Proceeds Received / Outstanding Claim for each tranche.","Part 2: Collateral Decrease Impact","Secured creditors receive less (recovery rate falls if collateral value < secured claims).","Less proceeds flow to unsecured tranches, reducing their recovery rates further.","Junior tranches see disproportionate impact as they're last in line.","May trigger fights over collateral valuation and priority."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Evercore Interview","First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1922","t":"deal","l":"Advanced","s":90,"q":"A company has a $100 million revolving credit facility, $120 million in eligible assets, a 75% advance rate on eligible assets, $40 million in loan disbursements, $10 million in outstanding letters of credit, and $30 million in cash on hand. What is the company's total liquidity?","k":["Answer: $70 million","Calculation:","Borrowing base = $120M x 75% = $90M","Available revolver = min($100M facility, $90M borrowing base) = $90M","Less: Outstanding draws ($40M) and letters of credit ($10M) = $50M utilized","Remaining revolver availability = $90M - $50M = $40M","Total Liquidity = Revolver Availability + Cash = $40M + $30M = $70M"],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2025","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1923","t":"deal","l":"Advanced","s":90,"q":"A bond has a 5% coupon, 2 years to maturity, a bond price of $60, and a par value of $100. What is the estimated yield to maturity?","k":["Answer: approximately 37%","Approximation method:","Annual coupon = 5% x $100 = $5","Capital gain over 2 years = $100 - $60 = $40, or $20/year","Average annual return = $5 + $20 = $25","Average price = ($60 + $100) / 2 = $80","Approximate YTM = $25 / $80 = 31.25% (rough estimate)","Exact YTM requires solving: $60 = $5/(1+y) + $105/(1+y)^2, which gives approximately 37%."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2025","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1924","t":"deal","l":"Advanced","s":90,"q":"You want to capture a discount and extend maturities for a distressed company. You have unlimited basket capacity at the unrestricted subsidiary level. How would you coerce participation from creditors?","k":["This describes a liability management exercise (LME) using an \"uptier\" or \"drop-down\" transaction. The playbook:","Transfer valuable assets (IP, key operating subsidiaries) from the restricted group to an unrestricted subsidiary, moving them beyond the reach of existing creditors' collateral packages.","Issue new debt at the unrestricted subsidiary level, secured by the transferred assets, to a cooperating group of creditors at a discount to par in exchange for their existing claims.","Participating creditors get new priority debt secured by the best assets; non-participating creditors are left with structurally subordinated claims against an asset-stripped restricted group.","This creates a \"prisoner's dilemma\" for holdouts: if they don't participate, their recovery value drops significantly because the remaining collateral is worth far less.","The threat of being left behind with junior claims on a hollowed-out entity coerces broad participation.","This strategy has become common in recent LMEs (e.g., J. Crew, Serta Simmons) and has generated significant litigation around creditor-on-creditor violence."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2026, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1925","t":"deal","l":"Advanced","s":90,"q":"A distressed company receives two different offers for a $300 million term loan: one at 3% cash interest and 10% PIK interest, and the other at 8% all-cash interest. How would you evaluate these offers and advise the company?","k":["Offer 1: 3% Cash + 10% PIK = 13% Total","Annual cash outflow: $9M (3% x $300M)","PIK accrual: $30M in Year 1, compounding thereafter","After 5 years, the debt balance grows to ~$300M x 1.10^5 = ~$483M","Offer 2: 8% All-Cash = 8% Total","Annual cash outflow: $24M (8% x $300M)","Debt balance remains $300M (no PIK compounding)","Recommendation:","If the company is cash-constrained and needs to preserve liquidity for operations or a turnaround, Offer 1 is better. The $9M vs. $24M annual cash burden is significantly lower, giving the company breathing room.","If the company has adequate cash flow and expects a near-term recovery or exit, Offer 2 is better. The total cost of capital is much lower (8% vs. 13%), and the company avoids the compounding debt burden.","For a truly distressed company, preserving near-term cash flow is usually the priority, making Offer 1 preferable. However, the company must have a credible plan to address the ballooning PIK balance before maturity."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2026, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1926","t":"deal","l":"Advanced","s":90,"q":"You are pitching a financial sponsor on a liability management transaction, and the sponsor owns debt in its portfolio company. What would you do?","k":["This creates a conflict of interest because the sponsor sits on both sides: as equity owner and as a creditor.","First, identify the conflict: As equity owner, the sponsor wants to maximize equity value (potentially at creditors' expense). As debt holder, the sponsor wants to protect its recovery on the debt. These interests may directly oppose each other.","Propose a structure that aligns both interests: For example, a debt-for-equity swap where the sponsor converts its debt into additional equity at a favorable conversion rate, deleveraging the balance sheet while increasing the sponsor's ownership.","If the sponsor's debt position is small, they may be willing to subordinate or extend it as a show of confidence to other creditors, facilitating the broader LME.","If the sponsor's debt position is large, they could serve as the \"anchor\" in a new money deal, providing DIP or exit financing alongside their existing exposure.","Address governance: Ensure an independent committee evaluates the transaction to avoid fiduciary duty issues, and obtain fairness opinions as needed."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2026, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1927","t":"deal","l":"Advanced","s":90,"q":"Company A has a customer relationship with Company B, and Company B is in financial distress. What are two ways that Company B's distress would show up on Company A's financial statements?","k":["Bad debt expense / allowance for doubtful accounts: If Company B owes Company A money (accounts receivable), Company A must increase its allowance for doubtful accounts and record a bad debt expense on the income statement, reducing net income. On the balance sheet, AR decreases (net of the allowance).","Revenue decline / contract impairment: If Company B is a significant customer that reduces orders or goes bankrupt, Company A loses future revenue. Additionally, if Company A has long-term contracts with Company B, it may need to write down any related contract assets or recognize an impairment on assets tied to that customer relationship (such as customer-related intangibles from a prior acquisition)."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2026, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1928","t":"deal","l":"Advanced","s":90,"q":"A first lien term loan maturing in 2030 trades at $0.50 on the dollar, while another first lien term loan maturing in 2027 trades at $0.65 on the dollar. What is the reason for the price difference?","k":["Both are first lien (same priority), so the price difference is driven by maturity and recovery timing:","The 2027 loan matures sooner, meaning the lender recovers principal faster in a restructuring or refinancing scenario. Shorter duration reduces uncertainty.","The 2030 loan has more duration risk -- more time for the company's condition to deteriorate further, and longer until any recovery is realized.","In a distressed situation, the present value of expected recovery is higher for the shorter-dated loan because cash flows are discounted over fewer years.","The 2027 loan may also have a near-term maturity wall, creating urgency for the company to address it, which can improve recovery prospects for that tranche."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2026, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1929","t":"deal","l":"Advanced","s":90,"q":"What would you expect to see in the balance sheet of a supplier to a distressed company?","k":["Elevated Accounts Receivable: The distressed customer is likely paying slowly or not at all, causing AR to spike.","Allowance for doubtful accounts: The supplier would increase its bad debt reserve, reflecting the risk of non-collection.","Potential inventory build-up: If the supplier has produced goods for the distressed customer that have not been shipped or accepted.","Possible write-downs: If the supplier had advanced credit or made prepayments, these assets may need to be impaired.","Tighter liquidity: The supplier's own cash position may deteriorate due to non-payment, potentially straining its working capital and credit lines."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2026, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1930","t":"deal","l":"Advanced","s":90,"q":"If a supplier to a distressed company cannot collect its receivables, what would happen to the supplier?","k":["Cash flow squeeze: The supplier loses expected cash inflows, straining its own liquidity and ability to pay its own obligations.","Bad debt expense: The supplier must write off the uncollectible receivables, reducing net income.","Working capital deterioration: AR remains on the balance sheet as a worthless asset until written off, distorting liquidity metrics.","Potential credit issues: If the distressed customer was a significant portion of the supplier's revenue, the supplier may face its own covenant breaches or credit downgrades.","Contagion risk: In severe cases, the supplier could itself become distressed, particularly if it is highly concentrated in that customer and has limited liquidity reserves."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2026, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1931","t":"deal","l":"Advanced","s":90,"q":"What are the key liability management indicators you would look for when analyzing a distressed company?","k":["Debt maturity profile: Near-term maturities create refinancing risk and urgency for liability management.","Leverage ratios: Debt/EBITDA trending upward signals deteriorating credit quality.","Interest coverage: EBITDA/Interest falling below 1.0-1.5x indicates the company cannot service its debt from operations.","Liquidity runway: Cash on hand plus revolver availability versus near-term cash burn rate.","Debt trading levels: If debt trades significantly below par, the market is pricing in default or restructuring risk.","Covenant cushion: How close the company is to tripping maintenance covenants.","Credit rating trajectory: Downgrades or negative outlook from rating agencies.","Asset coverage: Whether secured debt exceeds the liquidation value of collateral."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Evercore Interview","SA 2026, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1932","t":"deal","l":"Advanced","s":90,"q":"Two companies, A and B, have the same fundamentals except capital structure.\n\n\n\n\nA has 200 in 1L and 100 in 2L.\n\n\n\n\nB has 100 in 1L and 200 in 2L.\n\n\n\n\nWhich company’s 1L trades higher, and which company’s 2L trades higher?","k":["B’s 1L trades higher; B’s 2L trades higher only when EV is between 100 and 300.","1L: Smaller 1L at B ⇒ higher per-dollar coverage (EV/1L), so B’s 1L ≥ A’s 1L.","2L: Between EV of 100 and 200, B's 2L recovers value while A's 2L gets nothing (blocked by A's large 1L). Between 200 and 300, B's 2L continues to have better coverage. They converge at par above 300."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Greenhill & Co. Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1933","t":"deal","l":"Advanced","s":90,"q":"Consider two companies with different capital structures:\n\n\n\nCompany A: $100M of First Lien debt and $200M of Second Lien debt.\nCompany B: $200M of First Lien debt and $100M of Second Lien debt.\n\n\n\nWhich company's First Lien debt trades at a higher price? What about its Second Lien debt?","k":["Company A's debt trades higher in both tranches. Both carry $300M of total debt, so at any enterprise value A is never worse off.","First Lien: A has $100M of senior claims against the same asset pool versus $200M at B, so a higher recovery per dollar.","Second Lien: what protects a tranche is the value below it, not the debt above it. Senior debt ranking ahead of you is a subtraction from recovery, not a cushion. A's Second Lien has $100M ahead of it; B's has $200M.","At a $250M distributable value:","A: First Lien $100M / $100M = 100%. Second Lien $150M / $200M = 75%.","B: First Lien $200M / $200M = 100%. Second Lien $50M / $100M = 50%.","The ranking holds throughout: at $150M, A's Second Lien recovers 25% versus 0% for B; at $300M and above both are whole. A is weakly better in every scenario."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Greenhill & Co. Interview","Restructuring group, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1934","t":"deal","l":"Advanced","s":90,"q":"Suppose there’s $700M 1L and $400M unsecured. What is Equity Value? What assumptions did you make there?\n\n\n\n\nFollow-up 1: How would it change if you had $400M cash?\n\n\n\n\nFollow-up 2: Now assume margin constriction of 5%. What is the debt trading at now?","k":["Initial Explanation","You typically assume an enterprise value based on a multiple of EBITDA or a reorganization scenario. Subtract net debt to find implied equity if any. For example, if EV is $900M and total debt is $1.1B, there's negative equity of $200M, implying zero equity value. Or if EV is $1.2B, equity is $100M. The assumptions revolve around:","EBITDA levels and multipliers","Any discount or premium for distress","Follow-up 1","If you add $400M cash, net debt falls. So effectively you have $700M 1L + $400M unsecured - $400M cash = $700M net debt. If the same EV holds, that leaves more equity.","Follow-up 2","If margin constricts 5%, EBITDA or free cash flow declines, lowering EV, making the debt riskier. Price for the 1L might drop slightly below par, and unsecured could drop more significantly if coverage is in doubt."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Houlihan Lokey Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1935","t":"deal","l":"Advanced","s":90,"q":"Walk me through the three financial statements if you pay off $200 of debt at 75 cents on the dollar. Assume a 25% tax rate.","k":["The company pays $150 in cash (200 x 0.75) to extinguish $200 of debt, resulting in a $50 gain on extinguishment of debt.","Starting on the IS...","Gain on extinguishment of debt of $50","Pre-tax income up $50","NI up $37.50","Moving onto the SCF...","NI +37.50","Subtract gain of 50 in CFO (non-cash reclassification to CFF)","CFF: -150 for debt repayment (or -200 repaid + 50 discount, net -150)","Net change in cash is down 162.50","Finally, on the BS...","A: Cash -162.50","L: Debt -200","SE: Retained Earnings +37.50","...and the Balance Sheet balances (A -162.50 = L -200 + SE +37.50 = -162.50)"],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1936","t":"deal","l":"Advanced","s":90,"q":"You are given the following financial data for a distressed company:\n\n\n\nCurrent EBITDA of $30M, growing by $5M per year\nCurrent CapEx of $10M, increasing by $10M per year\n$10M in Cash Taxes (constant)\n$100M Term Loan at 16% interest rate, half cash / half PIK\n$50M revolver capacity (undrawn; assume no interest on draws; draw only when cash flow is negative)\nCurrent cash balance: $15M\n\n\n\nAfter 5 years, what is the company's liquidity and ending cash balance? If there is no revolver, when would the company need to take action?","k":["Cash Flow = EBITDA − Cash Interest − CapEx − Cash Taxes. Cash interest = 8% of the term loan balance (half of 16%). PIK interest accretes to the term loan at 8% per year but does not use cash. The revolver is drawn only to cover negative cash flow and keep the cash balance at $15M.","Year 1:","EBITDA: $35M. Cash Interest: $8M (8% × $100M). CapEx: $20M. Taxes: $10M.","Cash Flow: 35 − 8 − 20 − 10 = −$3M","Draw $3M on revolver. Cash: $15M. Revolver drawn: $3M. Term Loan: $108M (PIK: +$8M).","Year 2:","EBITDA: $40M. Cash Interest: $8.64M (8% × $108M). CapEx: $30M. Taxes: $10M.","Cash Flow: 40 − 8.64 − 30 − 10 = −$8.64M","Draw $8.64M on revolver. Cash: $15M. Revolver drawn: $11.64M. Term Loan: $116.64M.","Year 3:","EBITDA: $45M. Cash Interest: $9.33M (8% × $116.64M). CapEx: $40M. Taxes: $10M.","Cash Flow: 45 − 9.33 − 40 − 10 = −$14.33M","Draw $14.33M on revolver. Cash: $15M. Revolver drawn: $25.97M. Term Loan: $125.97M.","Year 4:","EBITDA: $50M. Cash Interest: $10.08M (8% × $125.97M). CapEx: $50M. Taxes: $10M.","Cash Flow: 50 − 10.08 − 50 − 10 = −$20.08M","Draw $20.08M on revolver. Cash: $15M. Revolver drawn: $46.05M. Term Loan: $136.05M.","Year 5:","EBITDA: $55M. Cash Interest: $10.88M (8% × $136.05M). CapEx: $60M. Taxes: $10M.","Cash Flow: 55 − 10.88 − 60 − 10 = −$25.88M","Revolver capacity remaining: $50M − $46.05M = $3.95M. Cannot fully fund the −$25.88M shortfall.","Draw remaining $3.95M, then use cash: $15M − ($25.88 − $3.95) = −$6.93M. The company is $6.93M short.","The company runs out of liquidity in Year 5. Without additional action (asset sales, new financing, or a restructuring), the company cannot meet its obligations.","If there is no revolver, the company burns through its $15M cash cushion by Year 3: Year 1 cash flow of −$3M leaves $12M, Year 2 cash flow of −$8.64M leaves $3.36M, and Year 3's −$14.33M exceeds remaining cash. The company would need to take action during Year 3."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1937","t":"deal","l":"Advanced","s":90,"q":"Why would a company have to file for bankruptcy if it has no debt?","k":["A company with no debt can still file for bankruptcy if it cannot meet its non-debt obligations as they come due. These include:","Accounts payable to suppliers and vendors","Pension and employee benefit obligations","Lease obligations (operating and finance leases)","Legal judgments, litigation settlements, or regulatory fines","Tax liabilities owed to the government","Environmental remediation or product liability claims","Bankruptcy is fundamentally about the inability to pay obligations, not just debt. If a company runs out of cash and cannot meet any of these commitments, it may need to file Chapter 11 to restructure its obligations or Chapter 7 to liquidate."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, Second round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1938","t":"deal","l":"Advanced","s":90,"q":"A company has a leverage ratio such that EBITDA is $100 million and debt is $500 million. Would the company prefer a 20% decrease in EBITDA, or allowing its leverage ratio to increase to 6x?","k":["The company would prefer the leverage ratio increasing to 6x.","Currently, Debt/EBITDA = $500M / $100M = 5.0x.","Option 1: 20% EBITDA decline","New EBITDA = $80M. New leverage = $500M / $80M = 6.25x. EBITDA dropped by $20M.","Option 2: Leverage increases to 6.0x","At 6.0x with $100M EBITDA, debt = $600M. EBITDA stays at $100M and the company took on $100M more debt.","Option 2 is preferable because: (1) the resulting leverage ratio is lower (6.0x vs. 6.25x), (2) EBITDA is preserved at $100M, giving the company more cash flow to service its debt, and (3) the additional $100M of debt presumably came with additional cash proceeds that can be deployed productively, whereas a 20% EBITDA decline provides no offsetting benefit."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, Second round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1939","t":"deal","l":"Advanced","s":90,"q":"Given EV/EBITDA, interest coverage ratio, and interest expense, how do you calculate Loan-to-Enterprise-Value? Walk me through the algebra.","k":["Loan-to-Enterprise-Value (LTV) = Debt / Enterprise Value.","Algebra:","From Interest Coverage: EBITDA / Interest Expense = ICR, so EBITDA = ICR * Interest Expense","From EV/EBITDA: EV = (EV/EBITDA) * EBITDA = (EV/EBITDA) * ICR * Interest Expense","We need Debt. Debt = Interest Expense / Cost of Debt (r), so Debt = Interest Expense / r","LTV = Debt / EV = (Interest Expense / r) / [(EV/EBITDA) * ICR * Interest Expense]","Interest Expense cancels: LTV = 1 / (r * EV/EBITDA * ICR)","With all three given inputs (EV/EBITDA, ICR, Interest Expense), you can compute EV directly from step 2. You still need either the cost of debt or total debt outstanding to compute LTV. If total debt is given, simply divide: LTV = Debt / EV."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, Second round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1940","t":"deal","l":"Advanced","s":90,"q":"A company buys back $200 million of its own debt at 75 cents on the dollar. Assume a 40% tax rate. Walk me through the 3-statement impact.","k":["The company pays $150M in cash (75% of $200M face value) to retire $200M of debt, recognizing a $50M gain on extinguishment.","Starting on the IS...","Gain on debt extinguishment of $50M ($200M face - $150M purchase price)","Pre-tax income up $50M","NI up $30M (after 40% tax)","Moving onto the SCF...","NI +30","Subtract $50M gain in CFO (non-cash income)","CFF: -$150M cash paid for debt buyback","Net change in cash is -$170M","Finally, on the BS...","A: Cash -170","L: Debt -200","SE: Retained Earnings +30","...and the Balance Sheet balances (A: -170 = L + SE: -200 + 30 = -170)"],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, Second round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1941","t":"deal","l":"Advanced","s":90,"q":"What concessions might a company receive for toggling PIK (Payment in Kind) interest?","k":["PIK interest means interest is paid by adding to the principal balance rather than paying cash. In exchange for toggling to PIK, a company may receive:","Preservation of cash flow: The most direct benefit -- no cash outflow for interest, preserving liquidity during periods of stress.","Covenant relief: Lenders may agree to loosen or waive financial covenants in conjunction with a PIK toggle.","Extended maturity: Lenders may extend the debt maturity as part of the negotiation.","Operational flexibility: More cash available for working capital, CapEx, or turnaround investments.","However, the trade-off is a higher total interest cost (PIK interest compounds the principal) and lenders will typically charge a higher PIK rate than the cash pay rate (often 100-300 bps higher)."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1942","t":"deal","l":"Advanced","s":90,"q":"How do you identify the fulcrum security in a company's capital structure?","k":["The fulcrum security is the most senior security in the capital stack that is not expected to be fully repaid -- it is where value \"breaks\" in a restructuring.","Calculate the company's enterprise value (typically using a distressed valuation -- liquidation value or restructured going-concern value).","Waterfall the EV through the capital structure in order of seniority: secured debt first, then unsecured, then subordinated, then equity.","The tranche where the cumulative claims exceed the available enterprise value is the fulcrum security. This tranche receives a partial recovery.","All tranches senior to the fulcrum are fully covered (recover 100%). All tranches junior to it recover nothing.","The fulcrum security holders typically control the restructuring process and often receive the equity in the reorganized company."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1943","t":"deal","l":"Advanced","s":90,"q":"How do callable bonds behave in different interest rate environments?","k":["Falling Interest Rates","The issuer is likely to call (redeem) the bond and refinance at lower rates.","The bond's price appreciation is capped near the call price (negative convexity). Unlike non-callable bonds that would rise significantly, callable bonds plateau.","Investors face reinvestment risk -- they receive their principal back early and must reinvest at lower prevailing rates.","Rising Interest Rates","The issuer will not call the bond since refinancing would be more expensive.","The callable bond behaves similarly to a non-callable bond -- price declines as rates rise.","The call feature has minimal value to the issuer in this environment.","Key concept: Callable bonds exhibit negative convexity in falling rate environments because upside price appreciation is limited by the call provision, while downside exposure in rising rates is the same as regular bonds."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1944","t":"deal","l":"Advanced","s":90,"q":"What is embedded optionality in the context of restructuring, and why is it important?","k":["Embedded optionality refers to the option-like characteristics inherent in a distressed company's capital structure -- particularly for equity and junior debt holders.","In a restructuring context, equity can be thought of as a call option on the company's assets with a strike price equal to the face value of debt. If the company's value exceeds its debt obligations, equity holders capture the upside. If not, they receive nothing (limited downside to zero). Similarly, junior creditors hold option-like claims: they benefit from upside recovery but are wiped out if value does not extend to their tranche.","This matters because it means even deeply distressed securities can have meaningful value if there is sufficient volatility or time for the company's value to recover. It is why distressed investors often use option pricing models (like Black-Scholes) alongside traditional DCF to value fulcrum securities."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1945","t":"deal","l":"Advanced","s":90,"q":"Conceptually, how are bond yields versus term loan yields affected by rising or falling SOFR rates in different interest rate environments, given the distinction between floating and fixed rate instruments?","k":["Term Loans (Floating Rate -- SOFR + Spread):","Term loan yields move directly with SOFR. When SOFR rises, the all-in coupon (SOFR + spread) increases immediately, so the lender earns more. When SOFR falls, the coupon decreases. Because rates reset periodically, the price of a term loan stays near par -- there is minimal interest rate risk, so the market price does not fluctuate significantly with rate changes.","Bonds (Fixed Rate):","Bond coupons are fixed at issuance and do not change with SOFR. Instead, the market price adjusts. When rates rise, existing bonds with lower fixed coupons become less attractive, so their prices fall (yields rise to match market rates). When rates fall, existing bonds with higher coupons become more attractive, so prices rise (yields fall). The yield-to-maturity changes through price movement, not coupon changes.","In summary: term loans adjust through coupon changes, bonds adjust through price changes."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Houlihan Lokey Interview","Financial Restructuring group, LA Office, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1946","t":"deal","l":"Advanced","s":90,"q":"You are given a company's EBITDA, an EV/EBITDA multiple, and the full debt stack.\n\n\n\n\nWalk me through how you would perform a waterfall analysis to determine the recovery for each debt tranche.","k":["Steps for waterfall analysis:","Calculate Enterprise Value = EBITDA * EV/EBITDA multiple","Rank debt tranches by seniority (secured debt, unsecured debt, subordinated debt)","Start with most senior tranche and allocate EV to satisfy each tranche sequentially","If EV exceeds a tranche's face value, that tranche recovers 100% and remainder flows to next tranche","If EV is insufficient, calculate recovery percentage (EV remaining / Tranche face value)","Continue until EV is exhausted or all tranches are satisfied","Any residual value after debt accrues to equity holders"],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Miller Buckfire Interview","First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1947","t":"deal","l":"Advanced","s":90,"q":"A bond is trading at 60 cents on the dollar.\n\n\n\n\nWhy might that be the case? If the company's situation improves, then what?\n\n\n\n\nGiven the market landscape, what else might happen?","k":["At 60 c/$, the market prices in a high probability of default or a required yield well above coupon.","Deteriorating credit metrics ⇒ investors demand higher YTM, pushing price below par.","If fundamentals improve, spreads tighten and price gravitates toward par (or premium if covenants restrict calls).","In distress, bonds may exchange for equity, be repurchased at a discount, or become the fulcrum in Chapter 11."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Moelis & Co. Interview","First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1948","t":"deal","l":"Advanced","s":90,"q":"A company has $100 of EBITDA at a 10x multiple, with 2 tranches of debt:\n\n\n\n\n$1200 secured (backed by $700 in collateral) and $1000 unsecured.\n\n\n\n\nWhat is each tranche trading at?","k":["EV = $1,000 (100 × 10×).","Secured takes collateral: $700.","Secured deficiency ($500) pools with $1,000 unsecured → $1,500 total unsecured claims.","Residual EV: $300 ⇒ recovery rate = 300 / 1,500 = 20 c/$.","Secured recovery: 700 + 500 × 20 % = $800 ⇒ ≈ 67 c/$.","Unsecured recovery: 1,000 × 20 % = $200 ⇒ 20 c/$."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Moelis & Co. Interview","SA 2026","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1949","t":"deal","l":"Advanced","s":90,"q":"A distressed company has an Enterprise Value of $200 million and $400 million in net debt.\n\n\n\nWhat is the theoretical value of the company's common stock?\nAt what percentage of par value would you expect the debt to be trading?","k":["1) Equity ≈ $0 | 2) Debt ≈ 50¢.","Equity = EV − Net Debt = −$200 ⇒ worthless.","Debt price (assuming single tranche) = EV / Debt = 200 / 400 = 50%.","If multiple tranches, most senior gets paid in full until you reach a \"fulcrum\". The “fulcrum” tranche is the first to take losses and typically trades at the recovery value; senior debt above that recovery point trades closer to par, junior below."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Moelis & Co. Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1950","t":"deal","l":"Advanced","s":90,"q":"A company has an EBITDA of $50 million and net debt of $500 million. It is currently trading at an 8.0x EV/EBITDA multiple.\n\n\n\nWhat is its Enterprise Value and Equity Value?\nAt what price (cents on the dollar) are its bonds likely trading?","k":["EV $400 million | Equity ≈ $0 | Bonds ≈ 80¢.","EV = 50 × 8 = 400.","Equity = EV − Net Debt = 400 − 500 ≈ 0.","Bond price = EV / Debt = 400 / 500 = 80% of par."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Moelis & Co. Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1951","t":"deal","l":"Advanced","s":90,"q":"A company has a negative equity value. How would you solve for the market value of its debt?","k":["Value the operating business to get Enterprise Value (distressed DCF, comps, or liquidation).","Set Equity Value ≈ 0 because market cap cannot be less than zero (though book value of equity can be negative).","Back-solve: Market Value of Debt = EV + Cash ± other adjustments (preferred, minority interest).","Cross-check with any quoted bond or loan prices; override the residual if reliable market quotes exist."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Moelis & Co. Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1952","t":"deal","l":"Advanced","s":90,"q":"Given a company's EBITDA, an EV/EBITDA multiple, first lien debt, and unsecured debt, how do you calculate its equity value?\n\n\n\n\nFollow-up: Based on your calculation, what would you expect the trading price to be for the first lien and unsecured debt tranches?","k":["Equity Value Calculation:","EV = EBITDA * EV/EBITDA multiple","Equity Value = EV - Total Debt + Cash","Equity Value = EV - (First Lien Debt + Unsecured Debt) + Cash","Follow-up: Debt Trading Prices","If Equity Value > 0: Company is solvent. First lien recovers 100% (trades at/near par). Unsecured may trade at discount depending on coverage.","If Equity Value < 0 but EV > First Lien Debt: First lien recovers fully (trades near par). Unsecured trades at steep discount reflecting impairment.","If EV < First Lien Debt: First lien trades at discount (Recovery = EV / First Lien Debt). Unsecured likely worthless."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Moelis & Co. Interview","First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1953","t":"deal","l":"Advanced","s":90,"q":"A company has $100M in EBITDA and is trading at 12x EV/EBITDA. It has the following debt structure:\n\n\n\n$500M in 1st Lien Debt\n$600M in 2nd Lien Debt\n$200M in Unsecured Debt\n\n\n\nWhat is each tranche of debt trading at?","k":["Enterprise Value = $100M x 12x = $1,200M. Total Debt = $500M + $600M + $200M = $1,300M.","Since EV ($1,200M) < Total Debt ($1,300M), the company is insolvent -- there is not enough value to cover all the debt. The debt tranches trade based on recovery waterfall:","1st Lien ($500M): Fully covered. $1,200M > $500M. Trades at par (100 cents on the dollar).","2nd Lien ($600M): Remaining value after 1st Lien = $1,200M - $500M = $700M. 2nd Lien is $600M, so fully covered. Trades at par (100 cents on the dollar).","Unsecured ($200M): Remaining value = $700M - $600M = $100M. Only $100M available for $200M in claims. Trades at 50 cents on the dollar ($100M / $200M).","The Unsecured debt is the fulcrum security -- the tranche where value breaks, recovering only partial value."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Moelis & Co. Interview","SA 2026, Chicago Office, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1954","t":"deal","l":"Advanced","s":90,"q":"How might you be able to make a junior piece of debt more senior? What if the 1L refuses to cooperate?","k":["You can do an “uptiering transaction” or exchange offer, effectively rolling junior debt into a new super-senior facility. If the majority of the class consents, you can legally restructure priorities.","If 1L refuses, you might do an out-of-court deal with enough consenting lenders or wait to file Chapter 11, forcibly cramming down non-consenting parties—though this is more complex and time-consuming."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1955","t":"deal","l":"Advanced","s":90,"q":"What are 5 amendments that you can make to extend maturities?","k":["Common amendments might include:","Extending the principal repayment schedule or final maturity","Raising interest rates or adding a PIK (paid-in-kind) feature","Inserting or tightening financial covenants to satisfy lenders","Releasing or adding collateral to enhance security for the extended debt","Revising negative covenants that limit certain actions"],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1956","t":"deal","l":"Advanced","s":90,"q":"What are the differences between in court and out of court bankruptcies?","k":["In-court (Chapter 11) is overseen by a judge, has an automatic stay, higher legal fees, and can cram down dissenting creditors with majority support. Out-of-court relies on voluntary agreements with creditors, saving cost and time but requiring near-unanimous consent. If an out of court fails, in-court may be inevitable."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1957","t":"deal","l":"Advanced","s":90,"q":"What are some of the differences between distressed M&A and traditional M&A?","k":["Distressed M&A often occurs under tight timelines (liquidity crunch), involves insolvent or near-insolvent targets, and can use 363-sales in bankruptcy. Buyer may get assets “free and clear” of liabilities. Traditional M&A has lengthier diligence, less regulatory oversight from bankruptcy courts, and typically more stable financing."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1958","t":"deal","l":"Advanced","s":90,"q":"If I am a PE fund and want to buy into some of the assets of the company and the debt is trading at 30, what would you advise them to do?","k":["You could buy the debt cheaply to gain leverage in negotiations and potentially credit bid for assets in a restructuring or 363 sale. This approach might secure the assets at an effective discount if the debt position is converted to ownership or used to offset the purchase price.","Also, controlling the debt can influence the restructuring outcome: block or approve reorg plans, demand covenants or DIP terms, or selectively engage in an equitization (swap debt for equity)."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1959","t":"deal","l":"Advanced","s":90,"q":"Consider a distressed company where total assets are worth less than total debt. If some assets are unencumbered (not pledged as collateral), how does this affect the capital structure and recovery for various creditors?","k":["Secured creditors recover first up to collateral value; any shortfall becomes an unsecured deficiency claim that competes with existing unsecured debt, pushing their recovery lower.","Explanation:","Collateral “locks” value for secured lenders; excess value (if any) flows down.","Unencumbered assets add to the unsecured value pool—value is shared pro rata among all unsecured claims.","Because total asset value < total debt, the unsecured class—including deficiency claims—often receives minimal equity or nothing; equity holders are wiped out."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1960","t":"deal","l":"Advanced","s":90,"q":"What is a 'general assignment' for the benefit of creditors, and how does it compare to a Chapter 11 bankruptcy filing in the US?","k":["An out‑of‑court state law process in which a company transfers assets to an independent assignee who liquidates them and distributes proceeds to creditors.","Comparison:","Speed/Cost: Faster and cheaper than Chapter 11—no federal court oversight.","Control: Debtor loses operational control; assignee manages wind‑down.","Outcome: Generally a liquidation (like Chapter 7) vs. a potential reorganization under Chapter 11.","Automatic Stay: No automatic stay; protections vary by state."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1961","t":"deal","l":"Advanced","s":90,"q":"You are analyzing a company with $50 in EBITDA and $400 in debt. Comparable companies trade at an average of 6.0x EV/EBITDA.\n\n\n\nWhat is the company's Enterprise Value and Equity Value, assuming it has no cash?\nWhat does this imply about the price at which the company's debt is trading?\nNow, assume the CEO finds $100 in cash and contributes it to the business. What is the new Enterprise Value, Equity Value, and the new trading price of the debt?","k":["Part 1","EV = $300; Equity Value = 0 (−$100 theoretical value would reflect in debt trading below par).","Part 2","Debt trades at 75 cents / $1 par (300 EV available for 400 debt).","Part 3","New Net Debt = $300.","EV remains $300.","Equity Value = $0 (300 EV − 300 Net Debt).","Debt now covered 100% ⇒ trades at par."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1962","t":"deal","l":"Advanced","s":90,"q":"Why might a company with a negative or zero theoretical equity value still have a positive market capitalization?","k":["Equity markets price option value—investors pay for future upside not captured by a strict book or liquidation analysis.","Drivers:","Growth prospects or pending turnaround.","Strategic asset value (brands, IP) not on balance sheet.","Speculative trading and short‑covering."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1963","t":"deal","l":"Advanced","s":90,"q":"Why might two bonds from the same issuer, with a similar seniority in the capital structure, trade at different prices?","k":["Differences in covenants, coupon, call protection, liquidity, and embedded options drive price dispersion.","Tighter covenants, shorter time to maturity, or higher coupons raise price (lower yield).","Callable bonds price in call risk.","Smaller issue sizes may trade at liquidity discounts."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1964","t":"deal","l":"Advanced","s":90,"q":"Why might two bonds from the same issuer, with similar seniority but different maturities, trade at the same price?","k":["Two bonds from the same issuer with different maturities trading at the same price is uncommon. It usually means their yields differ and can be attributed to a number of factors:","Near-term event risk disproportionately affecting shorter bonds.","Technical supply/demand dynamics for a specific tenor.","Disparate coupon rates creating price convergence.","Market illiquidity or pricing anomalies."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1965","t":"deal","l":"Advanced","s":90,"q":"Part 1: In a restructuring, how might a senior secured lender seek to increase its recovery?\n\n\n\n\nPart 2: What actions might more junior creditors take to improve their own recoveries?","k":["Part 1: Senior Secured Lender Actions","Assert security interests: Enforce collateral claims, ensure proper perfection of liens.","Credit bid: Use debt claims to bid for assets in a sale, potentially acquiring at advantageous prices.","Push for liquidation: If going concern value is low, liquidation may maximize secured recovery.","DIP financing: Provide debtor-in-possession financing for super-priority claims.","Aggressive timelines: Accelerate process to minimize value deterioration.","Part 2: Junior Creditor Actions","Form creditor committee: Organize to gain voice and negotiate collectively.","Challenge senior lien validity: Contest perfection, valuation, or extent of collateral coverage.","Support reorganization: Advocate for going-concern plans that preserve value for unsecured claims.","Negotiate for new equity: Accept equity in reorganized company in exchange for debt forgiveness.","Buy senior debt: Purchase senior claims at discount to gain priority position."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","New York Office","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1966","t":"deal","l":"Advanced","s":90,"q":"From a market efficiency perspective, is it a good or bad thing that claims on a bankrupt company can be traded?","k":["It is generally positive for market efficiency. Trading bankruptcy claims allows:","Price discovery: Market determines fair value of distressed claims.","Liquidity: Creditors can exit positions, transferring risk to specialized distressed investors.","Capital allocation: Sophisticated investors acquire claims, often leading to more efficient restructuring outcomes.","Faster resolution: Active trading can consolidate claims and facilitate negotiations.","Potential downsides include holdout problems and increased complexity, but overall, tradability enhances market function and capital reallocation."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in PJT Partners Interview","New York Office","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1967","t":"deal","l":"Advanced","s":90,"q":"Two bonds are issued by the same company with the same financial backing.\n\n\n\nBond A has a 5% coupon.\nBond B has an 8% coupon.\n\n\n\nWhat could explain this difference in coupons? If the only difference was the covenant package, which bond would likely have lighter covenants?","k":["Possible explanations for different coupons:","Different seniority (Bond B is subordinated, requiring higher yield).","Different maturities (Bond B has longer maturity, commanding higher rate).","Different covenant packages (Bond B has fewer/lighter covenants).","Market timing (bonds issued at different times with different rate environments).","If the only difference is covenants: Bond B (8% coupon) would have lighter covenants. Investors demand higher compensation (higher coupon) for taking on more risk from weaker covenant protection."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Unspecified Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1968","t":"deal","l":"Advanced","s":90,"q":"Answer the following questions about bond covenants:\n\n\n\nDo high-yield bonds typically have maintenance or incurrence covenants?\nProvide an example of an incurrence covenant.\nAre maintenance or incurrence covenants generally more restrictive? Argue both sides of the case.","k":["Part 1","High-yield bonds typically have incurrence covenants.","Part 2","Example: Restrictions on additional debt if leverage exceeds 4.0x (only tested when incurring new debt).","Part 3","Maintenance covenants are generally more restrictive:","Tested quarterly regardless of company actions.","Violations trigger immediate default even if company takes no new action.","Provide earlier warning of deterioration.","Incurrence covenants can be more restrictive in specific situations:","May completely prohibit certain actions rather than just limiting them.","Can prevent value-destructive transactions even if ratios are healthy.","Offer less flexibility when company wants to act."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Unspecified Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1969","t":"deal","l":"Advanced","s":90,"q":"Given the following for a company:\n\n\n\nEBITDA: $50m\nEV/EBITDA Multiple: 4x\nSenior Debt: $100m\nJunior Debt: $200m\nCash: $0\n\n\n\nPart 1: What is the company's Enterprise Value and Equity Value?\n\n\n\n\nPart 2: What does the result suggest about the company's financial situation?","k":["Part 1:","Enterprise Value: $200m. Equity Value: -$100m.","Calculation:","EV = EBITDA * Multiple = $50m * 4x = $200m","Equity Value = EV - Total Debt + Cash","Equity Value = $200m - $300m + $0 = -$100m","Part 2:","The negative equity value indicates the company is insolvent or distressed. The enterprise value is insufficient to cover total debt obligations.","This suggests the junior debt holders face impairment and equity holders are likely wiped out. The company may be a candidate for restructuring or bankruptcy."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Unspecified Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1970","t":"deal","l":"Advanced","s":90,"q":"A company has $50M in EBITDA and an Enterprise Value of $300M (based on a 6.0x EV/EBITDA multiple).\n\n\n\n\nIts capital structure consists of a $150M Revolver and $300M in Unsecured Debt.\n\n\n\n\nIn a distressed scenario, what would you expect each debt tranche to be trading at?","k":["Analysis:","Total Debt = $150M + $300M = $450M.","EV = $300M, which represents recovery value.","Revolver ($150M): Senior claim, likely trades near par or 100% recovery.","Unsecured Debt ($300M): Subordinated claim. Recovery = ($300M EV - $150M Revolver) / $300M Unsecured = $150M / $300M = 50% of par.","Expected Trading: Revolver ~100¢, Unsecured Debt ~50¢ on the dollar."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Unspecified Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1971","t":"deal","l":"Advanced","s":90,"q":"A company has the following characteristics:\n\n\n\nEBITDA: $100\nEV/EBITDA Multiple: 7.5x\nCash: $0\nSenior Secured Debt: 1.5x EBITDA\nBank Debt: 1.0x EBITDA\nUnsecured Debt: 2.5x EBITDA\n\n\n\nPart 1: What is the Equity Value?\n\n\n\n\nPart 2 (Follow-up): Now assume EBITDA falls to $60. What is the new Equity Value, and at what percentage of par value does the Unsecured Debt trade?","k":["Part 1: Equity Value","Answer: $250","EV = 7.5x * $100 = $750","Total Debt = (1.5x + 1.0x + 2.5x) * $100 = $500","Equity Value = EV - Net Debt = $750 - $500 = $250","Part 2: New Equity Value & Unsecured Debt Recovery","New Equity Value: $0 (negative, but floors at zero)","Unsecured Debt trades at: 80% of par","New EV = 7.5x * $60 = $450","The company's debt balance does not change when EBITDA falls. The original debt amounts were:","Senior Secured Debt = 1.5x * $100 = $150","Bank Debt = 1.0x * $100 = $100","Unsecured Debt = 2.5x * $100 = $250","Total Debt = $500","Since Total Debt ($500) is greater than New EV ($450), Equity Value is theoretically negative, but in practice is $0","Value Available to Unsecured = $450 - $150 (Senior) - $100 (Bank) = $200","Unsecured Recovery = $200 / $250 = 80% of par"],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Unspecified Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1972","t":"deal","l":"Advanced","s":90,"q":"For a distressed company, what is the theoretical maximum WACC?","k":["There is no theoretical maximum WACC for a distressed company.","As distress increases, both cost of debt and cost of equity rise dramatically. Cost of equity can approach infinity as equity value approaches zero, and debt yields can exceed 50-100%+ in severe distress.","In practice, WACC becomes less meaningful for distressed companies, and valuation shifts to recovery analysis and liquidation values rather than DCF."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Unspecified Interview","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1973","t":"deal","l":"Advanced","s":90,"q":"A company is on the verge of bankruptcy.\n\n\n\n\nIt has $100M in bank debt (secured) and $250M in high-yield debt (unsecured).\n\n\n\n\nTo determine how much you would pay for each tranche of debt, what key information would you need?","k":["Key information needed to value distressed debt:","Liquidation value of assets (especially collateral securing bank debt).","Enterprise value under restructuring scenarios.","Full capital structure details (priority, covenants, maturity).","Company's cash burn rate and runway.","Debtor-in-possession (DIP) financing needs.","Recovery rates for comparable bankruptcies.","Equity value scenarios post-restructuring.","Potential for debt-to-equity conversion.","Legal structure and jurisdiction.","Secured debt likely recovers more due to collateral; unsecured may recover significantly less or nothing."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["Reported in Unspecified Interview","Superday","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1974","t":"deal","l":"Advanced","s":90,"q":"A company has an Enterprise Value of $300 million, $150 million in secured debt, and $300 million in unsecured debt. At what price would you expect the debt to trade?","k":["Total claims = $150M secured + $300M unsecured = $450M. Enterprise Value = $300M.","Secured debt ($150M): Secured creditors are paid first. EV of $300M fully covers the $150M secured debt. The secured debt trades at par (100 cents on the dollar).","Unsecured debt ($300M): After paying secured creditors, remaining value = $300M - $150M = $150M. Unsecured creditors have $300M in claims but only $150M of value to recover. Recovery = $150M / $300M = 50%. The unsecured debt trades at approximately 50 cents on the dollar.","The unsecured debt is the fulcrum security -- the class of debt where value breaks and recovery is less than 100%."],"collection":"practice","topic":"Restructuring / Distressed M&A","tags":["New","Reported in Unspecified Interview","SF Office, First round","Restructuring / Distressed M&A","Advanced"]},{"id":"q-1975","t":"sector","l":"Basic","s":90,"q":"How would you value a software company?","k":["Software companies are valued differently from traditional businesses due to their high growth, high margins, and asset-light models:","EV/Revenue is the most common multiple for high-growth SaaS companies, especially if they are not yet profitable. SaaS companies typically trade at 5-15x+ EV/Revenue depending on growth rate.","EV/ARR (Annual Recurring Revenue) is preferred over total revenue because it focuses on the recurring, subscription-based portion, which is more predictable and valuable.","EV/EBITDA is used for mature, profitable software companies (typically 15-25x+).","Rule of 40: Investors assess software companies using Revenue Growth % + EBITDA Margin %. Companies above 40% are considered strong performers and command premium multiples.","DCF: Used with a longer projection period (10+ years) to capture the growth ramp, with a higher WACC reflecting risk.","Key metrics to analyze: Net Revenue Retention (NRR), CAC payback, LTV/CAC ratio, gross margin (typically 70-85%+), and churn rate."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Barclays Interview","SF Office, First round","Technology Banking","Basic"]},{"id":"q-1976","t":"sector","l":"Basic","s":90,"q":"If an analyst told you a startup had a WACC of 8%, how would you react?","k":["That’s likely too low for a startup, which generally has higher risk and thus a higher required return.","You’d question how they arrived at such a low cost of equity, given limited operating history and potential volatility.","Typically, startups might have a WACC in the teens or higher, unless there’s a very low cost of debt or extremely stable business model."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Citi Interview","Technology Banking","Basic"]},{"id":"q-1977","t":"sector","l":"Basic","s":90,"q":"Why do earlier-stage or growth companies often issue convertible bonds instead of straight debt or equity?","k":["Convertible bonds offer advantages for growth companies:","Lower interest rates: Conversion option allows lower coupon vs. straight debt.","Less dilution upfront: Avoids immediate equity issuance and dilution compared to raising equity directly.","Delayed dilution: Dilution only occurs if stock price rises above conversion price (favorable for existing shareholders).","Tax benefits: Interest expense is tax-deductible, unlike equity.","Attractive to investors: Provides downside protection (debt floor) with upside participation (equity conversion).","Flexible capital: Suitable when company is uncertain about future equity valuations or doesn't want to raise equity at current prices."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Credit Suisse Interview","SF office, Second round","Technology Banking","Basic"]},{"id":"q-1978","t":"sector","l":"Basic","s":90,"q":"A software company shows higher EBITDA margins than all comps with similar growth.\n\n\n\n\nWhy might that be, and what concerns would you have about its long-term viability?","k":["Possible reasons: capitalizing expenses, under-investment in R&D or sales, artificially low salaries, or aggressive accounting recognition.","Concern: sustainability of growth and margins if they’re cutting corners on product development or artificially inflating short-term profitability."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Deutsche Bank Interview","Technology Banking","Basic"]},{"id":"q-1979","t":"sector","l":"Basic","s":90,"q":"What are unique internet multiples used to value internet companies?","k":["Internet companies often lack profitability, so traditional multiples like EV/EBITDA may not apply. Common internet-specific multiples include:","EV/Revenue: The most common for high-growth, pre-profit internet companies.","EV/Gross Profit: Useful when comparing companies with different cost structures (e.g., marketplace vs. direct sales).","EV/Monthly Active Users (MAU) or EV/Daily Active Users (DAU): Common for social media and consumer internet platforms.","EV/Subscribers or EV/Paid Users: Used for SaaS and subscription-based businesses.","EV/Gross Merchandise Value (GMV): Common for e-commerce marketplaces.","EV/Bookings or EV/ARR: Standard for SaaS companies where ARR (Annual Recurring Revenue) reflects contracted future revenue.","Price/Earnings-to-Growth (PEG Ratio): Used when comparing growth-stage companies with different growth rates.","The key principle is to find a metric that captures the company's scale and growth trajectory even when traditional profitability metrics are unavailable."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Deutsche Bank Interview","Technology group, SF Office, First round","Technology Banking","Basic"]},{"id":"q-1980","t":"sector","l":"Basic","s":90,"q":"How do you determine whether the tech sector is overvalued?","k":["Look at forward multiples (EV/Revenue, EV/EBITDA), PEG ratios, historical averages, overall market conditions, and company fundamentals vs. valuations. Compare growth rates to valuations to see if price is justified."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Goldman Sachs Interview","Technology Banking","Basic"]},{"id":"q-1981","t":"sector","l":"Basic","s":90,"q":"What is the SaaS Rule of 40, and why is it an important metric for evaluating software companies?","k":["The Rule of 40 states that a healthy SaaS company's revenue growth rate plus its profit margin (typically EBITDA or FCF margin) should exceed 40%.","For example, a company growing at 30% with a 15% EBITDA margin scores 45%, passing the rule. It matters because it captures the tradeoff between growth and profitability. A company can grow quickly at the expense of margins or be highly profitable but slow-growing -- the Rule of 40 ensures a balanced combination of both."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Houlihan Lokey Interview","SA 2027, Technology group, New York Office","Technology Banking","Basic"]},{"id":"q-1982","t":"sector","l":"Basic","s":90,"q":"What is negative working capital, and what level of working capital should a software company typically have?","k":["Negative working capital means current liabilities exceed current assets. This occurs when a company collects cash from customers before it needs to pay its own obligations.","SaaS companies often have negative or very low working capital because they collect annual or multi-year subscription payments upfront (recorded as deferred revenue, a current liability), while having minimal inventory and receivables. This is a positive sign -- it means the business is effectively funded by its customers."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Houlihan Lokey Interview","SA 2027, Technology group, New York Office","Technology Banking","Basic"]},{"id":"q-1983","t":"sector","l":"Basic","s":90,"q":"Why do technology companies typically use EV/Revenue as a valuation multiple, while industrial companies are more commonly valued using EV/EBITDA?","k":["Many technology companies, particularly high-growth SaaS and early-stage firms, are unprofitable or have minimal EBITDA, making EV/EBITDA meaningless or misleading. EV/Revenue allows comparison across companies regardless of profitability stage.","Industrial companies, by contrast, are typically mature with stable, positive EBITDA margins. EV/EBITDA is preferred because it normalizes for differences in cost structures, capital intensity, and D&A policies across industrial peers, giving a cleaner comparison of operating profitability."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Houlihan Lokey Interview","SA 2027, Technology group, New York Office","Technology Banking","Basic"]},{"id":"q-1984","t":"sector","l":"Basic","s":90,"q":"What is the average valuation multiple for tech companies?","k":["Tech company multiples vary widely by sub-sector and growth profile. As a general framework:","High-growth SaaS (30%+ revenue growth): 10-20x+ EV/Revenue.","Mature software: 5-10x EV/Revenue or 15-25x EV/EBITDA.","Hardware/semiconductor: 10-20x EV/EBITDA.","IT services: 10-15x EV/EBITDA.","Key drivers of tech multiples include revenue growth rate, margin profile, recurring revenue percentage, net retention rates, and TAM. Prepare specific current data points before your interview."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Lazard Interview","SA 2025, SF Office, First round","Technology Banking","Basic"]},{"id":"q-1985","t":"sector","l":"Basic","s":90,"q":"For an early-stage growth tech firm, is IRR or WACC higher?","k":["IRR.","Venture investors demand returns well above the company’s theoretical WACC to compensate for execution and funding risk."],"collection":"practice","topic":"Technology Banking","tags":["Reported in LionTree Interview","SA 2026","Technology Banking","Basic"]},{"id":"q-1986","t":"sector","l":"Basic","s":90,"q":"What are MRR and ARR?\n\n\n\n\nWhy do they matter for tech companies from both a company and valuation perspective?\n\n\n\n\nFollow-up: What are the three things that impact MRR?","k":["MRR is predictable subscription revenue each month; ARR = MRR × 12.","They signal growth quality and underpin EV/ARR valuation multiples.","Three MRR drivers:","New customer additions.","Account expansion/upsells.","Churn and downgrades."],"collection":"practice","topic":"Technology Banking","tags":["Reported in LionTree Interview","SA 2026","Technology Banking","Basic"]},{"id":"q-1987","t":"sector","l":"Basic","s":90,"q":"Is change in NWC usually positive or negative for tech companies?","k":["Negative (cash‑inflow).","SaaS firms often bill upfront, so deferred revenue outpaces current assets, driving a negative ΔNWC that boosts Free Cash Flow."],"collection":"practice","topic":"Technology Banking","tags":["Reported in LionTree Interview","SA 2026","Technology Banking","Basic"]},{"id":"q-1988","t":"sector","l":"Basic","s":90,"q":"What is LTV to CAC?\n\n\n\n\nWhat would be considered good vs. bad?","k":["The ratio of a customer’s projected lifetime gross profit (LTV) to the cost of acquiring that customer (CAC).","A common benchmark is 3-to-1 LTV-to-CAC — meaning the value you get from a customer should be roughly three times what you spent to acquire them. Ratios below ~1:1 suggest you’re spending more to acquire customers than the profit they generate, which is unsustainable, while significantly higher ratios (e.g., 4–5× or more) can imply under-investment in growth."],"collection":"practice","topic":"Technology Banking","tags":["Reported in LionTree Interview","SA 2026","Technology Banking","Basic"]},{"id":"q-1989","t":"sector","l":"Basic","s":90,"q":"Would you rather use EV/EBITDA or EV/Sales when valuing a tech company?","k":["Use EV/EBITDA when the firm has positive, normalised EBITDA.","Switch to EV/Sales if EBITDA is negative, distorted by one‑offs, or the model focuses on high‑growth, early‑stage tech where revenue is the most reliable metric."],"collection":"practice","topic":"Technology Banking","tags":["Reported in LionTree Interview","SA 2026","Technology Banking","Basic"]},{"id":"q-1990","t":"sector","l":"Basic","s":90,"q":"Why might some legacy companies be reluctant to transition to a SaaS business model?","k":["Reasons for reluctance:","Near-term revenue pressure: SaaS shifts upfront license revenue to recurring subscriptions, depressing short-term financials.","Cash flow impact: Delayed cash collection hurts liquidity initially.","Customer resistance: Existing customers may prefer perpetual licenses.","Internal disruption: Requires significant operational, organizational, and cultural changes.","Investor concerns: Wall Street may penalize near-term earnings declines during transition.","Execution risk: Uncertainty around successfully transitioning customer base and sales model."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Morgan Stanley Interview","SF Office","Technology Banking","Basic"]},{"id":"q-1991","t":"sector","l":"Basic","s":90,"q":"How does the market value SaaS companies differently from other types of software companies?","k":["SaaS companies typically command premium valuations due to several factors:","Recurring revenue: Predictable, subscription-based revenue streams reduce risk.","Higher growth rates: SaaS models often scale more efficiently than traditional software.","Better retention: High switching costs and customer lock-in improve lifetime value.","Lower customer acquisition costs over time with network effects.","Scalability: Lower incremental costs to serve additional customers.","Valuation metrics: Market focuses on ARR growth, net dollar retention, LTV/CAC ratio, and Rule of 40 (growth rate + profit margin). SaaS companies trade at higher EV/Revenue multiples than traditional software due to these characteristics."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Morgan Stanley Interview","SF Office","Technology Banking","Basic"]},{"id":"q-1992","t":"sector","l":"Basic","s":90,"q":"Could you differentiate between usage-based and subscription-based pricing models?\n\n\n\n\nHow does each model affect revenue recognition and revenue forecasting?","k":["In subscription-based pricing, customers pay a recurring, fixed fee over the contract term, making revenue recognition fairly predictable.","Usage-based (“pay as you go”) depends on actual consumption. Revenue can fluctuate monthly, requiring more careful revenue recognition aligned with usage. This is often more volatile but can provide upside if usage scales quickly.","Subscription models enable consistent forecasting. Usage-based models require historical usage trends or other demand indicators to project revenue, introducing more variability."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Qatalyst Partners Interview","Technology Banking","Basic"]},{"id":"q-1993","t":"sector","l":"Basic","s":90,"q":"Propose a technology-focused M&A deal you'd recommend.\n\n\n\n\nWhich company should acquire another, and why?\n\n\n\n\nWhat strategic rationale supports this transaction?","k":["Sample answer (2025): Salesforce buying Notion","Salesforce should acquire Notion, building on its recent collaboration acquisitions like Slack. This would strengthen Salesforce’s position against Microsoft’s Teams/Loop by integrating productivity tools effectively. Bundling Notion with Salesforce’s Einstein GPT and Data Cloud could expand their user base, driving higher seat expansion and ARR, while keeping the deal size manageable compared to previous acquisitions like Slack, valued at $27.7B","The acquisition would extend Salesforce’s well-trodden collaboration M&A strategy."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Qatalyst Partners Interview","Technology Banking","Basic"]},{"id":"q-1994","t":"sector","l":"Basic","s":90,"q":"What factors primarily drive or hinder M&A activity in today’s tech industry?\n\n\n\n\nConsider regulatory issues, competition, or technological change, among others.","k":["Key drivers include strong corporate balance sheets, cheap financing, and the need for rapid innovation or scale. Mature tech giants often acquire startups to expand their product ecosystem and preempt competitors.","Hurdles include heightened antitrust scrutiny (esp. with Big Tech), geopolitical tensions restricting cross-border deals, and the pace of tech disruption (which can make acquisitions riskier if synergy assumptions prove inaccurate)."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Qatalyst Partners Interview","Technology Banking","Basic"]},{"id":"q-1995","t":"sector","l":"Basic","s":90,"q":"Which tech vertical interests you most and why?\n\n\n\n\nWhat key trends are emerging, and how do these trends impact valuation?\n\n\n\n\nWhat strategic choices result from these trends?","k":["Choice: Cloud Infrastructure & AI","Reasons:","Rapid shift to cloud-based everything, from storage to computing power, fosters high recurring revenue","AI drives incremental demand for specialized compute at scale","High barriers to entry (massive capex in data centers, specialized chips)","Emerging trends & valuation impact:","LLMs (Large Language Models) need GPUs or TPUs, fueling premium valuations for providers (NVIDIA, AMD)","Next wave might revolve around distributed/fog computing, requiring capital-intensive expansions","Strategic choices: big players invest in proprietary hardware or exclusive AI partnerships to differentiate. Midsize players must specialize or risk being crushed by the hyperscalers (AWS, Azure, Google)."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Qatalyst Partners Interview","Technology Banking","Basic"]},{"id":"q-1996","t":"sector","l":"Basic","s":90,"q":"Which trading multiples are most relevant for valuing technology companies?","k":["EV/Revenue is common for early-stage or high-growth tech with low or negative earnings. For more mature tech, EV/EBITDA and P/E also matter. Sometimes EV/ARR (Annual Recurring Revenue) is used for SaaS models."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Raine Group Interview","Technology Banking","Basic"]},{"id":"q-1997","t":"sector","l":"Basic","s":90,"q":"What industry trends within TMT have you been following?","k":["Identify 2-3 specific trends in TMT, explain briefly why they're important to investors, and have one unique insight or example for each to demonstrate your understanding.","Sample answer (2025):","Two trends I've been following within AI are (1) AI Agents and (2) Multimodal AI.","Trend 1: AI agents now autonomously manage complex enterprise workflows, from customer support to supply chains, with minimal human intervention.","Valuation Impact: Companies with strong AI agent capabilities command premium valuations due to potential for cost savings and scalable automation.","Unique Insight: It's been interesting to see the emergence of vertically-specialized agents, such as Agents for Customer Support (Sierra AI, Decagon AI)","Trend 2: Multimodal AI integrates text, images, video, and audio, enabling more sophisticated applications beyond text-based chatbots.","Valuation Impact: Firms excelling in multimodal AI are achieving higher valuations as demand for cross-format solutions grows.","Unique Insight: Voice is a particularly interesting area, with companies like ElevenLabs leading the way. I could see voice becoming the future of digital interactions."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Raine Group Interview","Technology Banking","Basic"]},{"id":"q-1998","t":"sector","l":"Basic","s":90,"q":"How do you think market share in ridesharing will evolve?\n\n\n\n\nWill there still be two winners in a few years?\n\n\n\n\nFollow-up: What about delivery services?","k":["Likely some consolidation. Ridesharing often forms duopolies or triopolies with regional variants. Scale, network effects, and brand recognition are key.","Possibly two major players remain in the U.S. market (Uber, Lyft), though emerging autonomous-vehicle-first providers like Waymo represent a growing threat as they scale self-driving fleets, undercut traditional cost structures, and could bypass driver-based network effects.","Delivery services share similar scale and network effects but face even fiercer cost pressure. Alongside consolidation or niche plays, we’re seeing rapid experimentation with drones, sidewalk robots, and autonomous vans (e.g., Nuro), which (especially when combined with ghost kitchens and hyper-local dark stores) could reshape unit economics and force incumbents to innovate or partner."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Raine Group Interview","Technology Banking","Basic"]},{"id":"q-1999","t":"sector","l":"Basic","s":90,"q":"Which large tech company do you consider most attractive today, and why?","k":["Provide an example (e.g. Apple, Amazon, Google). Discuss revenue drivers, profitability, moats, growth prospects, or how the valuation compares to peers.","Sample answer: Google in 2025","Google (NASDAQ: GOOGL) is the most attractive large tech company today due to its strategic investments in and approach to AI, as well as its relative valuation. Google's competitive edge entering 2025 lies in vertical integration.","It's uniquely positioned with proprietary, top-tier chips: TPUs could potentially challenge NVIDIA's GPUs by 2025.","Additionally, Google constructs its own data centers, develops its models internally, and maintains an exceptionally robust research division.","In contrast to Microsoft and Amazon, which have partnered externally with OpenAI and Anthropic, Google aims to dominate by controlling the entire value chain.","Google also has an attractive relative valuation: 16× forward P/E vs. Microsoft’s 28× and Amazon’s 35×, with 29% operating margins outperforming peers."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Raine Group Interview","Technology Banking","Basic"]},{"id":"q-2000","t":"sector","l":"Basic","s":90,"q":"Part 1: For a SaaS business, what is considered a good recurring revenue percentage?\n\n\n\n\nPart 2: What is considered a good LTV / CAC multiple?","k":["Part 1:","A strong SaaS business typically has 80-95%+ recurring revenue, with best-in-class companies exceeding 90%. High recurring revenue indicates predictable cash flows and customer retention.","Part 2:","A good LTV / CAC ratio is generally 3:1 or higher. Ratios above 3x indicate efficient customer acquisition with strong unit economics. Ratios below 3x may signal unsustainable customer acquisition costs."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Unspecified Interview","Technology Banking","Basic"]},{"id":"q-2001","t":"sector","l":"Basic","s":90,"q":"What is a trend in FinTech that you are currently following?\n\n\n\n\nWhat is a company in that space you admire, and are there any recent deals worth noting?","k":["This requires a personal, researched answer. Sample framework to structure your response:","Identify a specific trend (e.g., embedded finance, AI in fraud detection, crypto infrastructure).","Name a leading company and explain why (business model, growth, competitive advantages).","Reference a recent transaction (M&A, IPO, or financing round) with key details: valuation, strategic rationale, and market implications.","Demonstrate genuine interest by discussing how the trend affects the broader financial services landscape."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Unspecified Interview","Technology Banking","Basic"]},{"id":"q-2002","t":"sector","l":"Basic","s":90,"q":"What are your thoughts on technology valuations right now?","k":["This requires current market knowledge. Framework for your answer:","Segment the market:","Mega-cap Tech: Discuss AI winners (NVIDIA, Microsoft) trading at premium multiples","Growth SaaS: Note compression from 2021 peaks but stabilization","Unprofitable Tech: Continued pressure, flight to quality","Key drivers to mention:","Interest rate environment and impact on growth stock valuations","AI theme and its effect on multiples","Profitability focus vs. growth-at-all-costs","Public vs. private valuation gap","Support with specific examples and recent data points."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Unspecified Interview","Technology Banking","Basic"]},{"id":"q-2003","t":"sector","l":"Basic","s":90,"q":"What has happened in the technology market so far this year, and where do you see it heading?","k":["This requires current market knowledge. Framework for your answer:","Recent developments to discuss:","AI infrastructure boom (chip demand, data center expansion, model development)","IPO market conditions (recent deals, pipeline, valuations)","M&A activity (strategic consolidation, regulatory environment)","Public market performance (tech index returns, multiple trends)","Venture funding environment (down rounds, later-stage crunch)","Forward outlook:","Interest rate trajectory and impact","Continued AI investment cycle","Regulatory headwinds (antitrust, data privacy)","Specific subsector opportunities"],"collection":"practice","topic":"Technology Banking","tags":["Reported in Unspecified Interview","Technology Banking","Basic"]},{"id":"q-2004","t":"sector","l":"Basic","s":90,"q":"Walk me through typical SaaS revenue multiples now.\n\n\n\n\nWhat are the ranges you're seeing? Are these historically low or high?","k":["Current SaaS revenue multiples vary significantly based on growth, profitability, and market conditions. Typical ranges:","High-growth SaaS (> 40% growth): 10-20x+ revenue","Mid-growth SaaS (20-40% growth): 5-10x revenue","Slower-growth SaaS (< 20% growth): 2-5x revenue","Rule of 40 companies (growth + margin > 40%) command premium multiples","These multiples are moderately high relative to historical averages but below the peaks seen in 2020-2021, when high-growth SaaS companies traded at 20-40x+ revenue. Current multiples reflect a more balanced market with greater emphasis on profitability and cash flow generation alongside growth."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Unspecified Interview","Technology Banking","Basic"]},{"id":"q-2005","t":"sector","l":"Advanced","s":90,"q":"What are the typical valuation multiples for technology companies, and how have they changed over the past five years?","k":["Framework for discussing tech multiples:","2020-2021 (low rates, pandemic boom): SaaS multiples expanded to 20-40x+ EV/Revenue for high-growth names. Driven by low interest rates and accelerated digital transformation.","2022-2023 (rate hikes): Significant multiple compression. High-growth SaaS fell to 5-15x EV/Revenue. Investors shifted focus from growth to profitability (the \"Rule of 40\").","2024-2025 (stabilization): Multiples partially recovered for profitable, AI-exposed companies. Bifurcation between AI winners (high multiples) and legacy software (lower multiples).","Current ranges: High-growth SaaS 10-20x EV/Revenue, mature software 5-10x EV/Revenue, hardware/semis 15-25x EV/EBITDA. Prepare specific current data points before your interview."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Bank of America Interview","EGRC group, Superday","Technology Banking","Advanced"]},{"id":"q-2006","t":"sector","l":"Advanced","s":90,"q":"What is NRR and GRR?\n\n\n\n\nIs logo expansion included in NRR? How about in GRR?","k":["NRR = Net Revenue Retention.","GRR = Gross Revenue Retention.","NRR factors downgrades, churn, and upsell / expansion.","GRR excludes expansion; it captures only starting revenue minus churn + downgrades.","Logo expansion sits in NRR, not GRR."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Centerview Partners Interview","SA 2026, San Francisco office, Technology M&A group","Technology Banking","Advanced"]},{"id":"q-2007","t":"sector","l":"Advanced","s":90,"q":"You have a 5-year-old tech company and a 10-year-old tech company.\n\n\n\n\nWhich valuation methods would you use and why?\n\n\n\n\nFollow-up 1: What if the 10-year-old still grows 35% per year?\n\n\n\n\nFollow-up 2: What challenges arise for different methods?","k":["5-Year-Old Tech","Because profits are thin or negative, valuation hinges on top-line-driven methods.","I would start with revenue-based Comps and Precedent Transactions (EV/Sales or EV/ARR for SaaS) using peers with similar growth and model types.","A DCF would be more challenging due to projection uncertainty.","10-Year-Old Tech","With a decade of history and steadier cash flow, I would prioritise profitability-based Comps (EV/EBITDA, P/E), cross-check with transactions, and build a shorter, more reliable DCF.","If cash flows are stable enough, I’d also test an LBO case to see how a PE buyer might price it.","Follow-up 1: If the 10-Year-Old Still Grows 35%","I would treat it like a high-growth firm: lean on revenue multiples, PEG ratios, and an extended DCF horizon, but retain earnings multiples for context given its longer track record.","Follow-up 2: Key Challenges","DCF: Small changes in long-term growth, margins, or WACC can swing value; terminal value often dominates.","Comps/Deals: “True” peers may be scarce, and multiples can be whipsawed by market sentiment or unique strategic premiums."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Deutsche Bank Interview","Technology Banking","Advanced"]},{"id":"q-2008","t":"sector","l":"Advanced","s":90,"q":"For high-growth fintech companies, do you use the Gordon Growth Model or exit multiples for terminal value in a DCF?","k":["Exit multiples are generally preferred for high-growth fintech companies.","The Gordon Growth Model assumes a constant perpetual growth rate, which is difficult to justify for companies growing 30-50%+ annually. You would need to project far enough into the future until growth normalizes to a sustainable rate (2-4%), which may require a 15-20 year forecast.","Exit multiples (EV/Revenue or EV/EBITDA) applied to the terminal year financials are more practical and market-grounded. They reflect what the market is likely to pay for a mature fintech at the end of the projection period.","For fintech specifically, EV/Revenue multiples are often used since many high-growth fintechs are not yet EBITDA-positive.","Best practice: Use both methods and triangulate. If the Gordon Growth Model produces an unreasonably high terminal value, that is a sign the assumptions are too aggressive."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in FT Partners Interview","Second round","Technology Banking","Advanced"]},{"id":"q-2009","t":"sector","l":"Advanced","s":90,"q":"How does depreciation affect a neocloud company? What assets are likely depreciating on its balance sheet?","k":["Neocloud companies (e.g., CoreWeave, Lambda Labs, Crusoe Energy) are GPU cloud providers that lease compute capacity, primarily for AI workloads.","Depreciation is a massive expense for neoclouds because their balance sheets are dominated by:","GPU servers (NVIDIA H100/B200 clusters): The single largest depreciable asset, typically depreciated over 3-5 years.","Networking equipment: High-speed interconnects (InfiniBand, Ethernet switches).","Data center infrastructure: If owned, the physical facility, power distribution, and cooling systems.","Leasehold improvements: Buildouts of leased data center space.","Depreciation significantly reduces EBIT and net income relative to EBITDA, making EV/EBITDA the preferred valuation metric. The rapid obsolescence cycle of GPUs (new generations every 1-2 years) creates risk that book value may overstate actual asset value."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Goldman Sachs Interview","SA 2026, Superday","Technology Banking","Advanced"]},{"id":"q-2010","t":"sector","l":"Advanced","s":90,"q":"A company signs a 5-year, $25 million software contract and collects the full amount upfront in cash. Revenue is recognized evenly at $5 million per year. Walk me through the impact on the three financial statements.\n\n\n\n\nAssume no associated COGS and a 20% tax rate.","k":["The company collects $25M in cash upfront but can only recognize $5M of revenue per year over 5 years. The remaining unrecognized amount sits in Deferred Revenue (a liability).","Year 1:","Starting on the IS...","Revenue: +$5M","Pre-tax income: +$5M","Taxes: $5M x 20% = $1M","NI: +$4M","Moving onto the SCF...","CFO: NI of +$4M","The company collected $25M in cash but only recognized $5M as revenue, so Deferred Revenue increases by $20M. This increase in a liability is a source of cash, so CFO adjusts +$20M","Total CFO: +$24M ($4M NI + $20M increase in Deferred Revenue)","Finally, on the BS...","A: Cash increases by $24M ($25M collected less $1M in taxes paid)","L: Deferred Revenue increases by $20M (the $25M collected minus $5M recognized)","SE: Retained Earnings +$4M from NI","Check: Assets +$24M = Liabilities +$20M + SE +$4M ✓","Years 2-5 (each year):","Starting on the IS...","Revenue: +$5M","Pre-tax income: +$5M","Taxes: $5M x 20% = $1M","NI: +$4M","Moving onto the SCF...","CFO: NI of +$4M","Deferred Revenue decreases by $5M as revenue is recognized (a use of cash in working capital), so CFO adjusts -$5M","Total CFO: -$1M ($4M NI - $5M decrease in Deferred Revenue)","Finally, on the BS...","A: Cash decreases by $1M (no new cash in, but $1M taxes paid)","L: Deferred Revenue decreases by $5M","SE: Retained Earnings +$4M from NI","Check: Assets -$1M = Liabilities -$5M + SE +$4M ✓"],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Houlihan Lokey Interview","SA 2027, Technology group, New York Office","Technology Banking","Advanced"]},{"id":"q-2011","t":"sector","l":"Advanced","s":90,"q":"What items are typically included in adjusted EBITDA for technology companies?","k":["Common adjusted EBITDA add-backs for tech companies:","Stock-based compensation: The largest and most debated add-back in tech. Added back because it is non-cash, though it represents real economic cost.","One-time restructuring or reorganization charges.","M&A transaction costs and integration expenses.","Non-recurring litigation or regulatory costs.","Deferred revenue fair value adjustments (in the context of an acquisition).","Capitalized software development costs (sometimes reclassified).","Non-cash purchase accounting adjustments."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Lazard Interview","SA 2025, SF Office, First round","Technology Banking","Advanced"]},{"id":"q-2012","t":"sector","l":"Advanced","s":90,"q":"How do interest rates particularly affect software companies?","k":["Interest rates disproportionately affect software companies because:","Long-duration assets: Software companies are valued primarily on future cash flows (many are pre-profit or have back-loaded earnings). Higher discount rates reduce the PV of these distant cash flows more than near-term cash flows.","Valuation multiple compression: Rising rates compress growth multiples. High-growth SaaS companies trading at 20x+ revenue are especially sensitive.","Customer behavior: Higher rates increase the cost of capital for enterprise customers, potentially slowing IT spending and deal cycles.","Acquisition financing: Rising rates make leveraged acquisitions more expensive, reducing PE demand for software targets and lowering deal multiples."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Lazard Interview","SA 2025, SF Office, First round","Technology Banking","Advanced"]},{"id":"q-2013","t":"sector","l":"Advanced","s":90,"q":"For a SaaS company, how would you organize customer info to optimize churn?","k":["Create cohort tables by signup month to track retention curves.","Segment by industry, contract size and product tier.","Store usage‑event data with timestamps to flag engagement drop‑offs.","Add fields for renewal date, primary contact and churn reasons.","Feed the structured dataset into predictive models that trigger save‑actions."],"collection":"practice","topic":"Technology Banking","tags":["Reported in LionTree Interview","SA 2026","Technology Banking","Advanced"]},{"id":"q-2014","t":"sector","l":"Advanced","s":90,"q":"How do you value a high-growth technology company that has negative EBITDA and FCF?\n\n\n\n\nWhat specific metrics would you look at?\n\n\n\n\nHow much weight would you assign to different valuation methods for this type of company?","k":["Valuation Approaches:","Comparable Company Analysis: Use revenue multiples (EV/Revenue) or forward multiples based on path to profitability.","DCF: Focus on long-term projections when company reaches profitability. Requires aggressive growth assumptions and higher discount rate.","Scenario Analysis: Model multiple outcomes (bull, base, bear cases).","Key Metrics:","Revenue growth rate and sustainability.","Gross margins and path to positive EBITDA.","Customer acquisition cost (CAC) vs. lifetime value (LTV) ratio.","Burn rate and cash runway.","Market opportunity (TAM/SAM).","Weighting:","Comparable Companies: 60-70% (most relevant for unprofitable tech).","DCF: 20-30% (high uncertainty, use as sanity check).","Precedent Transactions: 10-20% (if comparable deals exist)."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Moelis & Co. Interview","Chicago office, Superday","Technology Banking","Advanced"]},{"id":"q-2015","t":"sector","l":"Advanced","s":90,"q":"How would you calculate the Terminal Value for an internet company with negative EBITDA?","k":["Options for Terminal Value with negative EBITDA:","Exit Multiple on Revenue: Apply EV/Revenue multiple from comparable companies, assuming the company reaches profitability by exit.","Perpetuity Growth on Future Positive EBITDA: Project when EBITDA turns positive, then apply perpetuity growth formula from that point.","Exit Multiple on Positive EBITDA: Assume normalized positive EBITDA in terminal year and apply EV/EBITDA multiple.","For early-stage internet companies, EV/Revenue multiples are most common since profitability is distant. Ensure terminal year assumptions are realistic."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Moelis & Co. Interview","Technology Banking","Advanced"]},{"id":"q-2016","t":"sector","l":"Advanced","s":90,"q":"What valuation multiples should be used for a technology company?\n\n\n\n\nHow would your answer change if the company was in its early stages and generating negative earnings?","k":["Profitable Tech Company","EV/Revenue: Common for high-growth SaaS or software companies.","EV/EBITDA: Standard for mature tech with positive EBITDA.","P/E: Used for profitable companies with stable earnings.","EV/FCF: Relevant for cash-generative businesses.","Early-Stage / Negative Earnings","EV/Revenue: Primary multiple since no positive earnings/EBITDA.","EV/Gross Profit: Used to assess unit economics and margin potential.","Revenue Growth Rate: Market values growth; compare multiples to growth rate.","Customer Metrics: LTV/CAC, ARR growth, retention rates inform valuation.","Earnings-based multiples (P/E, EV/EBITDA) don't work for unprofitable companies. Focus shifts to revenue quality and path to profitability."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Moelis & Co. Interview","Technology Banking","Advanced"]},{"id":"q-2017","t":"sector","l":"Advanced","s":90,"q":"All else being equal, which company would likely have a worse credit rating: a software company or a semiconductor company?","k":["A semiconductor company would likely have a worse credit rating.","Semiconductors are capital-intensive with high CapEx requirements, cyclical demand, and longer cash conversion cycles. This results in higher leverage and less stable cash flows.","Software companies, especially SaaS, have lower CapEx, higher margins, more predictable recurring revenue, and stronger cash generation, leading to stronger credit profiles."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Morgan Stanley Interview","SF Office","Technology Banking","Advanced"]},{"id":"q-2018","t":"sector","l":"Advanced","s":90,"q":"If AI infrastructure is so essential, why can some Chinese companies build similar models with only one-tenth or less of the infrastructure?","k":["This question references companies like DeepSeek, which built competitive AI models using significantly less compute. Several factors explain this:","Algorithmic efficiency: Chinese labs have developed more efficient training techniques, including mixture-of-experts architectures and novel attention mechanisms that reduce compute requirements per parameter.","Necessity breeds innovation: U.S. export controls restricted China's access to leading-edge NVIDIA GPUs (A100, H100), forcing Chinese researchers to optimize for the hardware they could access (e.g., older NVIDIA chips or Huawei Ascend).","Distillation and open-source leverage: Some Chinese models benefit from distilling knowledge from larger Western open-source models, which is significantly cheaper than training from scratch.","Lower labor and operational costs: Researcher compensation and data center costs in China are lower.","Narrower scope: Some models achieve parity on specific benchmarks without matching the full generality of frontier models, reducing total training cost.","However, this does not necessarily mean massive infrastructure is unnecessary - frontier capabilities still require scale, and the sustainability of the efficiency gap is uncertain."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Superday","Technology Banking","Advanced"]},{"id":"q-2019","t":"sector","l":"Advanced","s":90,"q":"Discuss cybersecurity trends, how cybersecurity deals differ from other tech deals, and who could be the potential next acquisition targets in the cybersecurity space.","k":["Cybersecurity Trends:","Platform consolidation: Enterprises are moving from point solutions to integrated platforms, driving M&A among vendors seeking full-stack capabilities.","AI-powered security: Both offensive threats (AI-generated phishing, deepfakes) and defensive solutions (automated threat detection) are accelerating spending.","Zero-trust architecture adoption is becoming the standard framework for enterprise security.","Cloud security and identity/access management (IAM) are the fastest-growing subsectors.","How Cybersecurity Deals Differ:","Premium valuations: Cybersecurity companies trade at higher EV/Revenue multiples (8-15x) due to recurring revenue, high retention, and mission-critical nature.","National security considerations: Deals face heightened regulatory scrutiny (CFIUS) given the sensitivity of security products and government customer bases.","Revenue quality emphasis: Buyers focus heavily on ARR, net retention rates, and contract length rather than EBITDA, as many targets are not yet profitable.","Potential Acquisition Targets:","Mid-cap pure-play vendors with strong ARR growth in areas like cloud security, endpoint detection, or identity management.","Companies that fill capability gaps for large platform players like Palo Alto Networks, CrowdStrike, or Cisco.","Private companies backed by PE/VC that have reached scale and are ripe for strategic exits."],"collection":"practice","topic":"Technology Banking","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Superday","Technology Banking","Advanced"]},{"id":"q-2020","t":"sector","l":"Advanced","s":90,"q":"How would you approach valuing a rapidly growing, unprofitable SaaS or tech company?\n\n\n\n\nIf the company lacks revenue or profits, which alternative metrics would you consider?","k":["Typically, you consider forward-looking or unit-based metrics.","In the absence of positive earnings, you might use EV/Revenue or EV/ARR, focusing on growth, churn, and lifetime value of customers. Early-stage SaaS can also be valued on multiples of bookings, MRR (Monthly Recurring Revenue), or unique user/engagement metrics if relevant.","You still supplement with a DCF or venture-style method if you can forecast long-term cash flows, but you anchor on top-line growth and leading indicators of eventual profitability."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Qatalyst Partners Interview","Technology Banking","Advanced"]},{"id":"q-2021","t":"sector","l":"Advanced","s":90,"q":"Can you explain the difference between capitalizing and expensing software development costs?\n\n\n\n\nHow does each method impact the financial statements and ultimately the company's valuation?","k":["If you capitalize software development costs, they go on the balance sheet as an intangible (or PP&E-like) asset and get amortized over time. This means higher current earnings because you are deferring the expense.","If you expense those costs, they hit the income statement immediately, lowering earnings now but typically resulting in a “cleaner” reflection of current spend.","In valuation, capitalizing boosts near-term EBITDA but increases future amortization, while expensing lowers current EBITDA but can “smooth” future results. Analysts may recast expenses for comparability if different companies treat software development differently."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Qatalyst Partners Interview","Technology Banking","Advanced"]},{"id":"q-2022","t":"sector","l":"Advanced","s":90,"q":"What are the essential SaaS metrics investors should track?\n\n\n\n\nHow do these metrics affect valuation multiples?","k":["Investors focus on net dollar retention (the percentage of recurring revenue retained, including expansions and churn) and gross vs. net retention (how many customers stay, minus upsells).","CAC payback is how many months or quarters it takes to recoup customer acquisition cost from gross margin. LTV/CAC compares the total value of a customer over its lifetime to the cost of acquiring that customer.","High retention rates, short CAC payback, and large LTV/CAC generally command premium revenue multiples as they imply stable, predictable growth and strong unit economics."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Qatalyst Partners Interview","Technology Banking","Advanced"]},{"id":"q-2023","t":"sector","l":"Advanced","s":90,"q":"How are Net Operating Losses (NOLs) handled during a tech M&A transaction?","k":["NOLs can be valuable if they offset future taxable income. However, Section 382 limits usage if ownership changes significantly. In M&A, the combined entity must check the annual NOL usage cap, typically a function of the acquired company's equity value and federal rates.","If the target’s NOLs are large and the buyer can’t fully utilize them (due to these limits or insufficient profits), their value is reduced in the purchase price allocation."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Qatalyst Partners Interview","Technology Banking","Advanced"]},{"id":"q-2024","t":"sector","l":"Advanced","s":90,"q":"Select a private company you admire within a specific tech category (fintech, SaaS, semiconductors, etc.). Why do you find it compelling, and what metrics best highlight its strengths?\n\n\n\n\nFollow-up 1: Who might acquire this business, and what strategic value does it offer to each potential buyer?\n\n\n\n\nFollow-up 2: Which public companies serve as suitable comparables, and why?\n\n\n\n\nFollow-up 3: What is your second choice company within the same category, and what makes it appealing?","k":["Sample Answer (SaaS - Fintech):","I admire Stripe, a fintech payments platform with robust APIs that enable seamless online transactions for startups and enterprises.","Why compelling:","Massive transaction volume growth, especially in e-commerce","Simple developer integration fosters brand loyalty","Global expansion and new product lines (Stripe Capital, treasury services)","Key metrics:","TPV (Total Payment Volume), net revenue from fees","Net retention and churn among merchants","Gross margin (scales with volume and infrastructure efficiency)","Potential acquirers:","Stripe has a rich valuation, so direct payment comps may not be able to finance a full buyout","Among mega-caps with the requisite balance sheet, Amazon could make strategic sense given synergy with AWS + e-commerce flywheel","Comparable public companies:","PayPal (PYPL), Block (SQ) – digital payments & integrated commerce","Adyen – similarly developer-friendly global payments","Second choice (fintech SaaS): Brex","Corporate cards, expense management, real-time underwriting","Rapid growth in startup / mid-market space, strong brand"],"collection":"practice","topic":"Technology Banking","tags":["Reported in Qatalyst Partners Interview","Technology Banking","Advanced"]},{"id":"q-2025","t":"sector","l":"Advanced","s":90,"q":"Part 1: What is LTV / CAC and what does it measure?\n\n\n\n\nPart 2: If a customer has an expected lifetime of 5 years, what is the implied annual churn rate?","k":["Part 1:","LTV / CAC is the ratio of Customer Lifetime Value to Customer Acquisition Cost.","It measures the efficiency of acquiring customers by comparing the total profit generated from a customer over their lifetime to the cost of acquiring them. A higher ratio indicates more efficient customer acquisition and better unit economics.","Part 2:","Answer: 20%","Calculation:","Customer Lifetime = 1 / Annual Churn Rate","5 years = 1 / Churn Rate","Churn Rate = 1 / 5 = 20%"],"collection":"practice","topic":"Technology Banking","tags":["Reported in Unspecified Interview","Technology Banking","Advanced"]},{"id":"q-2026","t":"sector","l":"Advanced","s":90,"q":"How would you build a revenue model for a payments company?","k":["Key revenue streams to model:","Transaction-based fees: Volume x Take Rate (basis points per transaction)","Subscription/SaaS fees: Number of merchants x Monthly fee","Value-added services: Additional products like fraud protection, analytics","Build bottoms-up by forecasting:","Total Payment Volume (TPV) growth","Merchant acquisition and churn rates","Take rate trends (compress over time due to scale/competition)","Mix shift between payment types (card, ACH, crypto)","Validate with industry benchmarks and historical trends."],"collection":"practice","topic":"Technology Banking","tags":["Reported in Unspecified Interview","Technology Banking","Advanced"]},{"id":"q-2027","t":"sector","l":"Basic","s":90,"q":"How would you value a luxury retail company like Michael Kors (Capri Holdings)?","k":["Valuation approaches:","DCF: Project revenue based on comp store sales growth, new store openings, and international expansion. Model gross margins, operating leverage, and working capital (inventory-intensive). Use retailer-appropriate WACC.","Trading Comps: Compare to luxury peers (Tapestry, VF Corp, LVMH) on EV/EBITDA, EV/Sales, P/E. Adjust for brand strength, growth profile, and margin differences.","Precedent Transactions: Review recent luxury retail M&A for exit multiples and premiums paid.","Key Considerations:","Brand health and pricing power.","Same-store sales trends and customer traffic.","Geographic diversification and exposure to China.","E-commerce penetration and omnichannel strategy.","Inventory management and promotional activity.","Fashion cycle risks and brand relevance."],"collection":"practice","topic":"Consumer Retail Group","tags":["Reported in Evercore Interview","Superday","Consumer Retail Group","Basic"]},{"id":"q-2028","t":"sector","l":"Basic","s":90,"q":"Name two companies in each oil and gas vertical.","k":["Upstream (E&P): ExxonMobil, ConocoPhillips","Midstream: Enterprise Products Partners, Kinder Morgan","Downstream: Valero Energy, Marathon Petroleum","Oilfield Services: Schlumberger (SLB), Halliburton","Note that ExxonMobil and Chevron are integrated majors with operations across all verticals, but their primary revenue driver is upstream."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Bank of America Interview","SA 2026, First round","Energy, Power & Renewables Group","Basic"]},{"id":"q-2029","t":"sector","l":"Basic","s":90,"q":"What is a Master Limited Partnership (MLP)? Why is it relevant for oil and gas companies?","k":["An MLP is a publicly traded limited partnership that combines the tax benefits of a partnership with the liquidity of public markets.","Key Features:","MLPs have two classes of partners: a General Partner (GP) that manages operations and Limited Partners (LPs) who provide capital and receive distributions.","MLPs are pass-through entities, meaning income is taxed at the individual partner level, avoiding corporate double taxation.","They are required to distribute most of their cash flow to unitholders.","Relevance to Oil & Gas:","MLPs are most common in the midstream sector because midstream assets generate stable, fee-based cash flows from long-term contracts, supporting consistent distributions.","The tax-advantaged structure allows midstream companies to offer higher yields to investors, reducing their cost of capital for capital-intensive pipeline and storage infrastructure.","Examples: Enterprise Products Partners (EPD), Energy Transfer (ET)."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Bank of America Interview","SA 2026, First round","Energy, Power & Renewables Group","Basic"]},{"id":"q-2030","t":"sector","l":"Basic","s":90,"q":"Name five oil and gas exploration and production companies.","k":["ConocoPhillips","EOG Resources","Pioneer Natural Resources (now part of ExxonMobil)","Devon Energy","Diamondback Energy"],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Citi Interview","SA 2026, First round","Energy, Power & Renewables Group","Basic"]},{"id":"q-2031","t":"sector","l":"Basic","s":90,"q":"What are the basic market trends in energy, and where do you see the most opportunity in the energy sector in the near future?","k":["Structure your answer around key energy sector themes:","Energy transition: Growing investment in renewables, battery storage, and grid infrastructure alongside continued demand for hydrocarbons.","Capital discipline: E&P companies maintaining disciplined spending, returning cash via buybacks and dividends rather than aggressive drilling.","M&A consolidation: Wave of large-scale E&P mergers (e.g., Exxon-Pioneer, Chevron-Hess) to gain scale and premium acreage.","LNG and natural gas: Growing global demand for LNG as a transition fuel, with new export terminal capacity coming online.","AI/data center power demand: Massive electricity demand from AI data centers creating opportunities in natural gas, nuclear, and power generation infrastructure.","Prepare a specific current opportunity with data points demonstrating market awareness."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Piper Sandler Interview","SA 2025, Houston Office, Superday","Energy, Power & Renewables Group","Basic"]},{"id":"q-2032","t":"sector","l":"Advanced","s":90,"q":"What do we use instead of a DCF to value an oil and gas company, and how do you account for PDP and PUD reserves?","k":["The primary valuation method is a Net Asset Value (NAV) model.","How it works:","Project production volumes and cash flows from each reserve category based on engineering estimates and strip commodity prices.","Discount those cash flows to the present at a risk-adjusted rate (typically 10% for a standardized measure).","Sum the PV of all reserve categories, add non-reserve assets, and subtract liabilities to get NAV.","Reserve Categories:","PDP (Proved Developed Producing): Currently producing wells. Highest certainty, lowest discount rate, and valued most richly (often at $/boe).","PUD (Proved Undeveloped): Reserves from undrilled locations with high certainty of recovery but requiring future CapEx. Valued at a discount to PDP since capital must still be deployed and execution risk exists.","Probable and Possible reserves get progressively higher risk discounts (or lower $/boe multiples)."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Bank of America Interview","SA 2026, First round","Energy, Power & Renewables Group","Advanced"]},{"id":"q-2033","t":"sector","l":"Advanced","s":90,"q":"Part 1: Suppose for an oil and gas project, you calculate the IRR for a well to be 18% and the risk is 20%. Would you go forward with the project?\n\n\n\n\nPart 2: Suppose we did go forward with the project and oil is now being produced from the well. What will be the subsequent impact on the risk?","k":["Part 1","No, you should not proceed with the project.","If the risk (interpreted as the required rate of return / hurdle rate) is 20% and the IRR is only 18%, the project does not generate sufficient returns to compensate for its risk.","The NPV at a 20% discount rate would be negative, meaning the project destroys value.","You should only invest when the IRR exceeds the hurdle rate.","Part 2","The risk decreases once oil is being produced.","The biggest risk in upstream E&P is exploration / drilling risk (will the well actually produce?). Once the well is producing, that geological risk is eliminated.","Remaining risks are lower-magnitude: commodity price risk, decline rate uncertainty, and operational risk.","With lower risk, the required return drops. This means the same project that had an 18% IRR might now clear the new, lower hurdle rate, making it value-accretive on a go-forward basis."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Citi Interview","SA 2026, First round","Energy, Power & Renewables Group","Advanced"]},{"id":"q-2034","t":"sector","l":"Advanced","s":90,"q":"Name five independent oil companies operating in the Permian Basin.","k":["Diamondback Energy","Devon Energy","Permian Resources (formerly Centennial Resource Development)","Matador Resources","Vital Energy"],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Citi Interview","SA 2026, First round","Energy, Power & Renewables Group","Advanced"]},{"id":"q-2035","t":"sector","l":"Advanced","s":90,"q":"What are the typical P/E ratios for upstream, midstream, and downstream oil and gas companies, and why do they differ?","k":["Typical P/E Ranges:","Upstream (E&P): 8-15x. Most volatile due to direct commodity price exposure. Earnings swing significantly with oil and gas prices.","Midstream (Pipelines/Gathering): 12-20x. More stable, fee-based revenue models with long-term contracts. Earnings are less sensitive to commodity prices, supporting higher multiples.","Downstream (Refining): 6-12x. Refining margins (crack spreads) are cyclical and capital-intensive. Lower multiples reflect margin volatility and heavy CapEx requirements.","Why They Differ:","The primary driver is earnings stability and predictability. Midstream commands the highest multiples due to contracted, fee-based cash flows. Upstream is volatile because earnings depend directly on commodity prices. Downstream is affected by refining margin cycles and is capital-intensive. Investors pay higher multiples for predictable cash flows."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Lazard Interview","SA 2025, Houston Office, First round","Energy, Power & Renewables Group","Advanced"]},{"id":"q-2036","t":"sector","l":"Advanced","s":90,"q":"You are shown an LCOE (Levelized Cost of Energy) graph. What factors drive the LCOE to its current value? If you had $100 million to invest, what type of energy project would you build based on the information in the LCOE graph?","k":["LCOE (Levelized Cost of Energy) represents the per-unit cost of electricity over a project's lifetime, calculated as total lifetime costs divided by total lifetime energy production.","Key LCOE Drivers:","Capital costs (upfront construction and equipment)","Capacity factor (how often the plant operates at full output)","Fuel costs (zero for solar/wind, significant for gas/coal)","O&M costs (maintenance, labor, insurance)","Financing costs (cost of debt and equity, project tenor)","Government subsidies (ITC, PTC, tax credits)","Project lifetime and degradation rates","With $100M, utility-scale solar is the strongest investment today. Solar LCOE has fallen below $30/MWh unsubsidized in most US regions, making it the cheapest new-build generation source. It benefits from declining panel costs, high bankability, strong ITC/PTC incentives under the IRA, and predictable long-term cash flows via PPAs. Battery storage paired with solar further improves economics by capturing time-of-use arbitrage."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Marathon Capital Interview","SA 2025, Superday","Energy, Power & Renewables Group","Advanced"]},{"id":"q-2037","t":"sector","l":"Advanced","s":90,"q":"How would you project cash flows for a solar plant?","k":["Revenue Projection:","Start with nameplate capacity (MW DC or AC).","Multiply by capacity factor (typically 20-30% depending on location and irradiance).","Apply annual degradation (typically 0.5% per year for crystalline silicon panels).","Multiply by contracted PPA price or merchant price forecast to get revenue.","If applicable, add revenue from RECs, capacity payments, or ITC/PTC tax benefits.","Operating Expenses:","O&M costs (typically $8-15/kW/year), land lease, insurance, property taxes, asset management fees.","No fuel costs (key advantage over thermal generation).","Cash Flow Waterfall:","Revenue - OpEx = EBITDA","EBITDA - Debt Service (interest + principal) = Cash Flow to Equity","Account for debt sculpting, DSCR covenants (typically 1.2-1.4x), and cash sweep mechanisms.","Model over the project's useful life (25-35 years) and discount using project-level WACC or levered equity IRR."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Marathon Capital Interview","SA 2025, Superday","Energy, Power & Renewables Group","Advanced"]},{"id":"q-2038","t":"sector","l":"Advanced","s":90,"q":"If you have a single solar plant versus a portfolio of solar plants, how does that impact the valuation?","k":["A portfolio of solar plants commands a higher valuation multiple than a single plant due to diversification and scale benefits.","Key Differences:","Geographic diversification: A portfolio spread across regions reduces weather, irradiance, and curtailment risk. A single plant is fully exposed to local conditions.","Offtaker diversification: Multiple PPAs with different counterparties reduce credit concentration risk.","Lower cost of capital: Lenders and investors assign lower risk premiums to diversified portfolios, reducing WACC and increasing NPV.","Operational efficiencies: Shared O&M, asset management, and insurance costs create economies of scale.","Broader buyer universe: Larger portfolios attract institutional investors (infrastructure funds, pension funds) who have minimum check sizes, increasing competitive tension in a sale process.","Platform premium: A portfolio with a management team and pipeline may be valued as a platform rather than just a collection of assets, adding additional value."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Marathon Capital Interview","SA 2025, Superday","Energy, Power & Renewables Group","Advanced"]},{"id":"q-2039","t":"sector","l":"Advanced","s":90,"q":"If you develop and sell a solar project versus develop and operate a solar project, how are the income statements different? How about the balance sheets?","k":["Develop and Sell:","IS: Revenue is recognized at the time of sale as a lump sum (gain on sale). Development costs are capitalized during construction and flow through COGS at sale. Margins can be high but lumpy and episodic.","BS: During development, the project sits as an asset (construction-in-progress or inventory). After sale, the asset is removed and cash or a receivable replaces it. Minimal long-term assets remain.","Develop and Operate:","IS: Revenue is recurring over 20-30 years from PPA payments or merchant sales. Operating expenses (O&M, insurance, land lease) are ongoing. Depreciation is a significant non-cash expense. Revenue is stable and predictable but lower in any single year.","BS: The project remains as a long-lived asset (PP&E), depreciating over its useful life. Project debt (typically non-recourse) sits on the liability side. The balance sheet is asset-heavy with significant long-term debt.","Develop-and-sell businesses are valued more like homebuilders (earnings or NAV multiples), while develop-and-operate businesses are valued on DCF or EV/EBITDA, similar to utilities or infrastructure."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Marathon Capital Interview","SA 2025, Superday","Energy, Power & Renewables Group","Advanced"]},{"id":"q-2040","t":"sector","l":"Advanced","s":90,"q":"Rank the betas of the various energy sub-verticals from highest to lowest.","k":["From highest to lowest beta:","E&P (Exploration & Production) -- highest beta due to direct commodity price exposure and operational leverage.","Oilfield Services -- highly cyclical, tied to upstream CapEx spending.","Refining & Marketing -- moderate beta; refining margins add volatility but downstream exposure provides some stability.","Integrated Oil & Gas -- diversified across upstream, midstream, and downstream, dampening overall volatility.","Midstream / MLPs -- lower beta due to fee-based, contracted revenue streams.","Regulated Utilities -- lowest beta; regulated returns, stable demand, and predictable cash flows."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in Moelis & Co. Interview","SA 2026, Superday","Energy, Power & Renewables Group","Advanced"]},{"id":"q-2041","t":"sector","l":"Advanced","s":90,"q":"Name some different basins in the United States and at least one company operating in each.","k":["Permian Basin (West Texas/New Mexico): Pioneer Natural Resources, Diamondback Energy, ConocoPhillips.","Eagle Ford Shale (South Texas): EOG Resources, Marathon Oil.","Bakken Shale (North Dakota/Montana): Continental Resources, Hess Corporation.","Appalachian Basin / Marcellus & Utica Shale (PA/WV/OH): EQT Corporation, Range Resources, Antero Resources.","DJ Basin / Niobrara (Colorado): Civitas Resources, Occidental Petroleum.","Anadarko Basin (Oklahoma): Devon Energy, Continental Resources.","Haynesville Shale (Louisiana/Texas): Chesapeake Energy, Comstock Resources."],"collection":"practice","topic":"Energy, Power & Renewables Group","tags":["New","Reported in PJT Partners Interview","SA 2025, Houston Office, First round","Energy, Power & Renewables Group","Advanced"]},{"id":"q-2042","t":"sector","l":"Basic","s":90,"q":"What is a current trend you are following in the Financial Institutions Group (FIG) space?","k":["Structure your answer around one of these key FIG trends:","Deal overview: Name the specific trend and why it matters to FIG.","Key drivers: What macro or regulatory forces are behind it.","Impact on IB activity: How it drives M&A, capital raising, or advisory.","Concrete example: Name a specific company or deal.","Example: Insurance sector consolidation has accelerated, driven by the need for scale to manage rising reinsurance costs and climate-related losses. Marsh McLennan's acquisition of McGriff Insurance Services for ~$7.75B (announced late 2024) exemplifies this trend, as large brokers acquire specialty distributors to diversify revenue and lock in recurring commission streams. This creates significant IB advisory opportunity in both M&A and debt financing."],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in Barclays Interview","SA 2026, FIG group, New York Office, Superday","Financial Institutions Group","Basic"]},{"id":"q-2043","t":"sector","l":"Basic","s":90,"q":"Name a company in the Financial Institutions Group (FIG) space that you admire and explain why.","k":["Structure your answer as follows:","Name the company and its FIG sub-sector (banks, insurance, asset management, fintech).","Business model: What makes it distinctive or best-in-class.","Financial performance: Key metrics (ROE, efficiency ratio, AUM growth, etc.).","Strategic positioning: Competitive moat, market share, or growth runway.","Example: JPMorgan Chase stands out for its dominant franchise across consumer banking, investment banking, and asset management. It consistently generates ROE above 15%, has a best-in-class efficiency ratio, and has invested heavily in technology (~$15B+ annually), giving it a durable competitive advantage. Its ability to gain market share during periods of stress (e.g., acquiring First Republic in 2023) demonstrates both balance sheet strength and management quality."],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in Barclays Interview","SA 2026, FIG group, New York Office, Superday","Financial Institutions Group","Basic"]},{"id":"q-2044","t":"sector","l":"Basic","s":90,"q":"What types of companies fall within the Financial Institutions Group (FIG)?","k":["FIG covers companies in the financial services sector, including:","Commercial Banks (e.g., JPMorgan Chase, Bank of America)","Insurance Companies - Life, P&C, Reinsurance (e.g., MetLife, AIG, Berkshire Hathaway)","Asset & Wealth Managers (e.g., BlackRock, T. Rowe Price)","Specialty Finance & Consumer Lending (e.g., Capital One, SoFi)","Broker-Dealers & Exchanges (e.g., Charles Schwab, Nasdaq Inc.)","Fintech companies (e.g., PayPal, Block)","REITs (sometimes covered by FIG, sometimes by Real Estate group)","FIG companies are unique because they are highly regulated, use different financial metrics (book value, tangible book, ROE), and have different valuation approaches than traditional corporates."],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in Barclays Interview","SA 2026, FIG group, New York Office, First round","Financial Institutions Group","Basic"]},{"id":"q-2045","t":"sector","l":"Basic","s":90,"q":"Walk me through the Dividend Discount Model (DDM).","k":["The DDM values a company based on the present value of its expected future dividends.","Project dividends per share over a forecast period (typically 5-10 years), using estimated earnings and a target payout ratio.","Calculate a terminal value using the Gordon Growth Model: Terminal Value = DPS in final year x (1 + g) / (Ke - g), where g is the long-term dividend growth rate and Ke is the cost of equity.","Discount all projected dividends and the terminal value back to today using the cost of equity (not WACC, since dividends are an equity-level cash flow).","Sum the present values to get implied Equity Value per share.","The DDM is most commonly used for banks and insurance companies where free cash flow is difficult to define due to regulatory capital requirements."],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in Barclays Interview","SA 2026, FIG group, New York Office, First round","Financial Institutions Group","Basic"]},{"id":"q-2046","t":"sector","l":"Basic","s":90,"q":"Explain the Gordon Growth Model and why it's particularly relevant to valuing banks.","k":["The Gordon Growth Model (GGM) is a formula for valuing a perpetuity that grows at a constant rate:","Value = D1 / (Ke - g)","D1 = Expected dividend next period","Ke = Cost of equity (required return)","g = Perpetual dividend growth rate (must be less than Ke)","The GGM is central to FIG valuation because banks can't be valued with a traditional DCF (no clean FCF or capex definition). Instead, banks are valued via dividend discount models, with GGM as the terminal value.","In practice:","D1 reflects the bank's sustainable dividend, driven by net income, payout ratio, and regulatory capital constraints (CET1 requirements)","g is often derived from sustainable growth rate (ROE × retention ratio), typically 2-4% for mature banks","The GGM implies Value/Book = (ROE - g) / (Ke - g), which explains why banks with higher ROE trade at higher P/TBV multiples","Sensitivity analysis is critical since small changes in g or Ke dramatically affect the output"],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in Barclays Interview","SA 2026, FIG group, New York Office, First round","Financial Institutions Group","Basic"]},{"id":"q-2047","t":"sector","l":"Basic","s":90,"q":"How does a commercial bank generate income, and what are the primary valuation methods used for banks?","k":["Income Generation:","Net Interest Income: Spread between interest earned on loans and paid on deposits.","Fee Income: Service charges, overdraft fees, advisory fees, investment banking fees.","Trading Income: Proprietary trading and market-making.","Asset Management: Fees from managing client assets and wealth management.","Primary Valuation Methods:","P/TBV (Price-to-Tangible Book Value): Most common for banks given asset-heavy balance sheets.","P/E Multiple: Used but less relevant due to earnings volatility.","Dividend Discount Model (DDM): Appropriate given banks' high payout ratios.","Residual Income Model: Values excess returns above cost of equity."],"collection":"practice","topic":"Financial Institutions Group","tags":["Reported in Credit Suisse Interview","Financial Institutions group, First round","Financial Institutions Group","Basic"]},{"id":"q-2048","t":"sector","l":"Advanced","s":90,"q":"Walk me through the 3-statement impact for a bank that has a $100 loan on its books, collects 10% interest, and amortizes 10% of the principal.","k":["For a bank, loans are assets (not liabilities). The loan generates interest income.","Starting on the IS...","Interest Income = 10% x $100 = $10","Assuming a 25% tax rate, NI up $7.50","Moving onto the SCF...","NI +7.50","Principal repayment of $10 is a return of the loan asset (cash inflow from investing or operations depending on classification)","Net change in cash is up $17.50","Finally, on the BS...","A: Cash +17.50, Loans Receivable -10 (amortization), net assets up $7.50","L: No change","SE: Retained Earnings +7.50 from NI","...and the Balance Sheet balances (+7.50 = 0 + 7.50)"],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in Barclays Interview","SA 2026, FIG group, New York Office, First round","Financial Institutions Group","Advanced"]},{"id":"q-2049","t":"sector","l":"Advanced","s":90,"q":"Match different types of FIG companies with the most appropriate valuation method: the Dividend Discount Model (DDM) or a DCF.\n\n\n\nCommercial Banks\nInsurance Companies\nAsset Managers\nInsurance Brokers\nExchanges & Fintech","k":["DDM is preferred for:","Commercial Banks: Difficult to define FCF due to regulatory capital requirements and the nature of deposits/loans. DDM uses dividends (the actual cash returned to shareholders) as the cash flow proxy.","Insurance Companies: Similar issues with defining operating cash flow; dividends are a cleaner measure of distributable earnings.","DCF can be used for:","Asset Managers: Have identifiable revenue streams (management fees, performance fees) and more traditional cost structures, making FCF easier to project.","Insurance Brokers: Fee-based, asset-light businesses with predictable cash flows similar to traditional corporates.","Exchanges & Fintech: Transaction-based revenue models with clear cost structures, suitable for DCF analysis.","The key distinction: if the company's cash flows are heavily distorted by regulatory capital and reserve requirements (banks, insurers), use DDM. If the company has a more traditional, fee-based model, a DCF works."],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in Barclays Interview","SA 2026, FIG group, New York Office, First round","Financial Institutions Group","Advanced"]},{"id":"q-2050","t":"sector","l":"Advanced","s":90,"q":"How do you value a financial institution like a commercial bank?\n\n\n\n\nFollow-up: How do you calculate the terminal value using dividends in a Dividend Discount Model (DDM)?","k":["Part 1: Valuing Banks","Primary methods:","P/B Multiple (Price-to-Book): Since book value is more relevant for banks than for industrials.","P/E Multiple: Based on earnings power.","Dividend Discount Model (DDM): Projects future dividends and discounts to present value.","EV/EBITDA less applicable because debt is part of operations for banks, not financing.","Part 2: DDM Terminal Value","Terminal Value = Final Year Dividend × (1 + g) / (r - g)","Where g = perpetual dividend growth rate and r = cost of equity. This is the Gordon Growth Model formula."],"collection":"practice","topic":"Financial Institutions Group","tags":["Reported in J.P. Morgan Interview","Financial Institutions group, New York Office, Second round","Financial Institutions Group","Advanced"]},{"id":"q-2051","t":"sector","l":"Advanced","s":90,"q":"Walk me through an income statement for a traditional asset management firm. What are the valuation differences between valuing a bank and an asset management company?","k":["Asset Manager Income Statement","Revenue consists of management fees (% of AUM), performance/incentive fees, and advisory fees. The main expenses are compensation & benefits, distribution/marketing costs, fund administration, and G&A. The bottom line flows to net income attributable to the firm.","Valuation Differences: Bank vs. Asset Manager","Banks are valued on P/E, P/TBV (Price / Tangible Book Value), and dividend discount models because book value and net interest income drive their economics.","Asset managers are valued on P/FRE, P/DE, and EV/AUM because their value is driven by fee streams on AUM, not balance sheet assets.","You cannot use EV/EBITDA for banks (debt is an operating item), but you can for asset managers since they are asset-light.","Banks require regulatory capital (CET1, Tier 1), which constrains returns. Asset managers have no such capital requirements.","Banks carry significant credit risk on their balance sheet; asset managers carry market risk through fee variability but not direct credit risk."],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in J.P. Morgan Interview","SA 2027, FIG group, New York Office, First round","Financial Institutions Group","Advanced"]},{"id":"q-2052","t":"sector","l":"Advanced","s":90,"q":"Part 1: How do you value a bank?\n\n\n\n\nPart 2: How do you value a traditional asset management firm?\n\n\n\n\nPart 3: What multiples would you use for a bank?\n\n\n\n\nPart 4: What is the impact on the financial statements if a bank uses cash for an acquisition? How about the impact on its capital ratios?","k":["Part 1: Valuing a Bank","Use a dividend discount model (DDM), excess return model, or P/E and P/TBV multiples from comparable banks. EV-based multiples do not work because debt is an operating item for banks.","Part 2: Valuing an Asset Manager","Use P/FRE, P/DE, EV/AUM, and a DCF on fee-related cash flows. The focus is on AUM growth, fee rates, and margins on the recurring fee base.","Part 3: Bank Multiples","P/E (most common).","P/TBV (Price / Tangible Book Value).","P/BV (Price / Book Value).","Dividend yield.","Part 4: Bank Cash Acquisition Impact","On the financial statements: cash decreases, goodwill and target assets are added to the balance sheet, and the target's income flows through going forward. On capital ratios: goodwill is deducted from tangible common equity, so CET1 and Tier 1 ratios decline. Risk-weighted assets also increase from the acquired assets, further pressuring capital ratios. This is why bank M&A often requires regulatory approval and may necessitate a capital raise."],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in J.P. Morgan Interview","SA 2027, FIG group, New York Office, Superday","Financial Institutions Group","Advanced"]},{"id":"q-2053","t":"sector","l":"Advanced","s":90,"q":"What has a higher beta: management fees or performance fees?","k":["Performance fees have a higher beta.","Management fees are relatively stable because they are charged as a fixed percentage of AUM, which moves with market levels but in a dampened, predictable way. Performance fees, on the other hand, are tied to fund returns exceeding a hurdle rate and are highly sensitive to market conditions. In a strong market, performance fees surge; in a down market, they can drop to zero. This makes performance fee revenue far more volatile and correlated with equity markets, giving it a higher beta."],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in J.P. Morgan Interview","SA 2027, FIG group, New York Office","Financial Institutions Group","Advanced"]},{"id":"q-2054","t":"sector","l":"Advanced","s":90,"q":"How would you value a commercial bank? What are the key differences compared to valuing a standard industrial company?","k":["Use P/E, P/Tangible Book, Dividend Discount Model, and excess‑return methodology.","Banks’ cash flows are interest spread‑driven; debt is raw material, so EV/EBITDA is not meaningful.","Regulatory capital requirements make Book Value a key constraint; ROE versus Cost of Equity drives value.","Discount Dividends to Equity or Excess Earnings above required capital instead of unlevered FCF."],"collection":"practice","topic":"Financial Institutions Group","tags":["Reported in Lazard Interview","Financial Institutions Group","Advanced"]},{"id":"q-2055","t":"sector","l":"Advanced","s":90,"q":"Other than mutual funds, how would an alternative asset management firm raise capital?","k":["An alternative asset manager raises capital through several channels:","Commingled closed-end funds (flagship PE, credit, real estate, or infrastructure funds raised through LP commitments).","Separately managed accounts (SMAs) with large institutional investors like sovereign wealth funds or pension plans.","Co-investment vehicles alongside flagship funds.","Permanent capital vehicles such as publicly listed REITs, BDCs (Business Development Companies), or insurance subsidiaries.","CLOs (Collateralized Loan Obligations) and other structured credit vehicles.","Retail/wealth management channels through interval funds, non-traded REITs, or tender offer funds.","Secondary fund offerings (continuation vehicles or GP-led secondaries)."],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in Lazard Interview","SA 2027, FIG group, New York Office","Financial Institutions Group","Advanced"]},{"id":"q-2056","t":"sector","l":"Advanced","s":90,"q":"For an asset management firm, what is the single biggest driver of its P/E multiple?","k":["Assets Under Management (AUM) growth rate.","Asset managers earn fees based on AUM, so higher AUM growth directly translates to revenue and earnings growth. Firms demonstrating sustained net inflows and organic AUM growth command significantly higher multiples than those facing outflows or relying solely on market appreciation.","Other important drivers include:","Fee margins and mix (active vs. passive management).","Performance track record and investor retention rates.","Operating leverage and scalability."],"collection":"practice","topic":"Financial Institutions Group","tags":["Reported in Morgan Stanley Interview","FIG First round","Financial Institutions Group","Advanced"]},{"id":"q-2057","t":"sector","l":"Advanced","s":90,"q":"What are the key differences between the Income Statement of a bank versus that of a standard industrial company?","k":["Key differences:","Revenue: Banks earn net interest income (interest earned on loans minus interest paid on deposits) and non-interest income (fees, trading). Industrial companies have product/service revenue.","COGS/OpEx: Banks have minimal COGS. Main expenses are compensation, technology, and provision for credit losses. Industrials have COGS (materials, labor) and OpEx (SG&A, R&D).","Key Metrics: Banks focus on Net Interest Margin (NIM), efficiency ratio, and Return on Equity (ROE). Industrials focus on gross margin, EBITDA, and ROIC.","Credit Losses: Banks provision for loan losses, a critical expense line. Industrials have bad debt but not a primary expense."],"collection":"practice","topic":"Financial Institutions Group","tags":["Reported in Piper Sandler Interview","FSG First round","Financial Institutions Group","Advanced"]},{"id":"q-2058","t":"sector","l":"Advanced","s":90,"q":"Walk me through an income statement and a balance sheet for a traditional asset management firm. What items are different from regular companies?","k":["Income Statement","Revenue for an asset manager comes primarily from management fees (a % of AUM) and performance/incentive fees. COGS is replaced by compensation & benefits (the largest expense), along with distribution costs, fund administration, and G&A. There is no traditional manufacturing cost of goods sold line.","Balance Sheet","On the asset side, you see seed investments and co-investments in the firm's own funds, management fee receivables, and intangible assets like investment management contracts and client relationships. There is typically minimal PP&E. On the liability side, you may see fund-related obligations, deferred revenue from prepaid management fees, and contingent consideration from acquisitions. Equity often includes non-controlling interests representing minority stakes in fund GPs.","Key Differences from Regular Companies","Revenue is fee-based (tied to AUM) rather than product/service sales.","No inventory or traditional COGS.","Compensation is the dominant expense (often 40-60% of revenue).","Balance sheet is asset-light with minimal PP&E.","Seed/co-investments and intangible client relationships replace typical operating assets."],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in Wells Fargo Interview","SA 2027, FIG group, New York Office, First round","Financial Institutions Group","Advanced"]},{"id":"q-2059","t":"sector","l":"Advanced","s":90,"q":"How do you value a traditional asset management firm? What multiples would you use? What is Fee-Related Earnings (FRE)?","k":["You value a traditional asset manager primarily using a DCF on fee-related cash flows and comparable company multiples.","Common Multiples","Price / Fee-Related Earnings (P/FRE) - the most widely used.","Price / Distributable Earnings (P/DE).","EV / AUM - useful for quick benchmarking but less precise since it ignores fee rates and margins.","EV / EBITDA and P/E are also used but less standard for pure-play managers.","Fee-Related Earnings (FRE)","FRE = Management Fees + Other Recurring Fees - Compensation & Benefits - G&A Expenses. It strips out volatile performance/incentive fees and realized investment income, isolating the stable, recurring earnings stream. FRE is the preferred metric because it reflects the predictable, annuity-like portion of an asset manager's earnings."],"collection":"practice","topic":"Financial Institutions Group","tags":["New","Reported in Wells Fargo Interview","SA 2027, FIG group, New York Office, First round","Financial Institutions Group","Advanced"]},{"id":"q-2060","t":"sector","l":"Basic","s":90,"q":"Tell me about a company that interests you in the healthcare or biotech space. Walk me through their main lines of business, recent product launches, and competitive positioning.","k":["Structure your answer as follows:","Company overview: Name, market cap, sub-sector (large pharma, biotech, medtech, services).","Main lines of business: Key therapeutic areas, flagship products, revenue breakdown by segment.","Recent product launches: Name specific drugs or devices, approval dates, initial sales trajectory.","Pipeline: Key late-stage assets and expected catalysts (Phase 3 data readouts, FDA decisions).","Competitive positioning: Market share, differentiation vs. competitors, patent protection timeline.","Your view: Why this company is interesting from an IB perspective (M&A target/acquirer, capital markets activity, valuation).","Prepare 1-2 healthcare companies in detail before your interview. Know specific financial metrics (revenue, growth rate, margins, key multiples) and be ready for follow-up questions."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Centerview Partners Interview","SF Office, First round","Healthcare Group","Basic"]},{"id":"q-2061","t":"sector","l":"Basic","s":90,"q":"Why is large-scale M&A not happening this year in the healthcare space?","k":["Structure your answer around the key headwinds to large-scale healthcare M&A:","Antitrust scrutiny: The FTC and DOJ have become more aggressive in challenging large healthcare mergers, creating regulatory uncertainty and extended timelines (e.g., increased second requests and consent decree requirements).","Elevated valuations: Biotech and pharma targets are demanding high premiums, and acquirers are cautious about overpaying, especially given the uncertainty around pipeline clinical outcomes.","Integration challenges from recent deals: Many large pharma companies are still integrating recent acquisitions and may lack the bandwidth for another transformational deal.","Interest rate environment: Although rates have come down from peak levels, borrowing costs remain elevated compared to 2020-2021, making large debt-financed deals more expensive.","IRA drug pricing provisions: The Inflation Reduction Act's Medicare drug price negotiation provisions create uncertainty around long-term revenue projections for branded drugs, complicating deal valuations.","Despite these headwinds, bolt-on and mid-cap deals remain active as companies seek targeted pipeline additions."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Citi Interview","SA 2025, Healthcare group, SF Office, Superday","Healthcare Group","Basic"]},{"id":"q-2062","t":"sector","l":"Basic","s":90,"q":"Who do you think will win the GLP-1 space and why?","k":["Structure your answer with a clear thesis and supporting evidence:","Eli Lilly is best positioned to lead the GLP-1 market long-term. Key reasons:","Superior efficacy: Tirzepatide (Mounjaro/Zepbound) is a dual GIP/GLP-1 agonist that has shown greater weight loss (~22-26%) vs. semaglutide (~15-17%) in head-to-head trials.","Pipeline depth: Lilly has orforglipron (oral GLP-1) and retatrutide (triple agonist) in late-stage development, offering next-generation options with potentially even greater efficacy.","Manufacturing investment: Lilly has committed $10B+ to expand manufacturing capacity, positioning it to meet demand faster than competitors.","Label expansion: Pursuing indications beyond diabetes and obesity (sleep apnea, NASH, cardiovascular), expanding the addressable market.","Novo Nordisk (Ozempic/Wegovy) has first-mover advantage and strong brand recognition but faces supply constraints and a less differentiated pipeline. Amgen, Pfizer, and others are entering the space but are years behind in clinical development."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Citi Interview","SA 2025, Healthcare group, SF Office, Superday","Healthcare Group","Basic"]},{"id":"q-2063","t":"sector","l":"Basic","s":90,"q":"Part 1: Speak about current trends in the healthcare industry.\n\n\n\n\nPart 2: Name some recent deals that are following those trends and explain briefly what the targets offer to the acquirer.","k":["Part 1: Healthcare Industry Trends","Structure your answer around these key themes:","GLP-1 / obesity drug boom driving massive pharma M&A and licensing activity.","Patent cliffs forcing large pharma to acquire pipeline assets (Humira, Keytruda).","AI / digital health integration across diagnostics, drug discovery, and care delivery.","Value-based care shift pushing consolidation in healthcare services.","Biosimilar adoption creating pricing pressure and competitive dynamics.","Part 2: Recent Deals","Prepare 2-3 deals with specific metrics. Framework for each deal:","Acquirer, target, deal size, and strategic rationale.","What capability or asset the target provides (pipeline, technology, market access).","How the deal addresses one of the industry trends above."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Citi Interview","SA 2026, New York Office, First round","Healthcare Group","Basic"]},{"id":"q-2064","t":"sector","l":"Basic","s":90,"q":"What are the current trends in the healthcare and biotech industry?","k":["Key trends to discuss:","GLP-1 / Obesity: Novo Nordisk and Eli Lilly are leading a massive market with Ozempic/Wegovy and Mounjaro/Zepbound. Multiple competitors are entering with next-gen oral and injectable candidates.","Patent cliff-driven M&A: Large pharma is actively acquiring to replace revenue from expiring patents (Humira, Keytruda, Opdivo). This drives both large and bolt-on deal activity.","Cell & gene therapy commercialization: Approvals like Casgevy (CRISPR-based sickle cell therapy) mark the beginning of a wave of transformative one-time cures.","AI in drug discovery: Partnerships between tech and pharma accelerate lead identification and clinical trial optimization.","Regulatory reform: The IRA's drug price negotiation provisions are reshaping pharma economics, particularly for Medicare Part D drugs.","Biotech funding recovery: After the 2022-2023 downturn, capital is flowing back into the sector through IPOs, follow-ons, and private placements."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in J.P. Morgan Interview","SA 2025, Healthcare group, SF Office, Superday","Healthcare Group","Basic"]},{"id":"q-2065","t":"sector","l":"Basic","s":90,"q":"If you could make a strategic pitch to any healthcare company, which company would you choose and what would you pitch?","k":["This is a subjective question requiring a thoughtful, specific answer demonstrating healthcare industry knowledge.","Strong answer structure:","Choose a specific healthcare company you know well.","Identify a strategic gap or opportunity (M&A target, new market, technology).","Explain rationale: synergies, market dynamics, competitive positioning.","Outline value creation: revenue synergies, cost savings, strategic benefits.","Address key risks and mitigants.","Example: Pitch CVS acquiring a specialty pharmacy network to strengthen integrated care model."],"collection":"practice","topic":"Healthcare Group","tags":["Reported in Unspecified Interview","Healthcare Group","Basic"]},{"id":"q-2066","t":"sector","l":"Advanced","s":90,"q":"How would you value a biotech company using a DCF? What considerations are unique to biotech?","k":["For biotech, a risk-adjusted NPV (rNPV) is the standard approach rather than a traditional DCF:","Probability-weight each pipeline drug's cash flows by its likelihood of advancing to the next stage (Phase I ~10%, Phase II ~30%, Phase III ~60%, NDA/BLA ~90%). Note: these represent per-stage transition probabilities, not cumulative likelihood of eventual approval (LOA from Phase II is approximately 15-20%).","Project peak sales for each drug based on market size, pricing, and market share assumptions.","Apply a higher discount rate (12-15%) to reflect biotech-specific risk.","Include patent cliff / generic entry timing for revenue decline.","Add cash on hand and subtract debt for equity value.","Unique considerations: Binary outcomes (approval/rejection), limited or no current revenue, high R&D burn, long development timelines, and regulatory uncertainty."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Bank of America Interview","EGRC group, Superday","Healthcare Group","Advanced"]},{"id":"q-2067","t":"sector","l":"Advanced","s":90,"q":"Part 1: Which Terminal Value method do we typically use for a biotech company?\n\n\n\n\nPart 2: How would you discount the cash flows in Phase 1, Phase 2, and Phase 3 clinical trials? Would you discount more heavily in the market phase or in Phase 2 or Phase 3? Would you discount more heavily in Phase 2 or Phase 3?\n\n\n\n\nPart 3: Explain the concept of probability of success in biotech DCFs. If we use the Gordon Growth Method, what is the appropriate growth rate for a biopharma company past patent protection, assuming they have one asset in their pipeline and generics have moved in?","k":["Part 1","For single-asset biotech companies, a finite DCF with no terminal value (or a very small one) is typical, because the drug's revenue stream is limited to the patent life. If using a TV method, the Gordon Growth Method with a negative or zero growth rate is more appropriate than an exit multiple, since there is no clear set of comps and the business declines after patent expiry.","Part 2","Earlier clinical phases (Phase 1 and Phase 2) should be discounted more heavily than later phases because there is greater uncertainty about clinical success.","Phase 2 cash flows are discounted more than Phase 3 because Phase 2 has lower probability of success (~30-35%) vs. Phase 3 (~50-60%).","Market phase (post-approval) has the highest certainty, so it is discounted the least.","In practice, this is done using probability-weighted (risk-adjusted) DCF: multiply each phase's projected cash flows by the cumulative probability of reaching that stage.","Part 3","Probability of success (PoS) is the likelihood that a drug progresses through each clinical phase and reaches market. Cumulative PoS from Phase 1 to approval is typically ~10-15%.","In a risk-adjusted NPV (rNPV), each year's cash flow is multiplied by the cumulative probability of reaching that year, effectively probability-weighting the entire DCF.","For a biopharma company with one asset past patent protection and generics entering: the appropriate growth rate for the Gordon Growth Method is negative (e.g., -10% to -30% or more), reflecting rapid revenue erosion from generic competition. Many analysts avoid using a perpetuity entirely and instead model a finite decline to zero."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Centerview Partners Interview","SF Office, First round","Healthcare Group","Advanced"]},{"id":"q-2068","t":"sector","l":"Advanced","s":90,"q":"What are the discount rates you would use in comparison for a Biopharma company, a MedTech company, and a Healthcare Services company, and why do they differ?","k":["Discount rates differ across healthcare sub-sectors based on risk profiles:","Biopharma: Highest discount rate (~10-15%+). Binary pipeline risk, regulatory uncertainty (FDA approvals), high R&D spend, and volatile revenue streams make this the riskiest sub-sector.","MedTech: Moderate discount rate (~8-11%). More stable revenue with recurring device sales and consumables, but still faces regulatory risk and reimbursement pressures.","Healthcare Services: Lowest discount rate (~7-9%). Predictable, recurring revenue from patient volumes, insurance reimbursement, and long-term contracts. Lower R&D and regulatory risk.","The key driver is cash flow predictability and risk -- the more uncertain the future cash flows, the higher the required rate of return (and thus discount rate)."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Citi Interview","SA 2026, New York Office, First round","Healthcare Group","Advanced"]},{"id":"q-2069","t":"sector","l":"Advanced","s":90,"q":"What multiples would you use for a biotech or biopharma company in your terminal value calculation?","k":["For biotech/biopharma, the choice of multiple depends on the company's stage:","Commercial-stage biopharma: EV/EBITDA or EV/Revenue from comparable public biopharma companies.","Pre-revenue biotech: Risk-adjusted NPV (rNPV), comparable transactions, or EV per pipeline asset, which discount pipeline drugs by their probability of FDA approval at each clinical stage.","Mature pharma: P/E or EV/EBIT for stable, profitable companies.","For early-stage biotech, a sum-of-the-parts rNPV approach is often preferred over a traditional terminal value, since cash flows are tied to discrete pipeline assets with binary regulatory outcomes."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Evercore Interview","SA 2026, First round","Healthcare Group","Advanced"]},{"id":"q-2070","t":"sector","l":"Advanced","s":90,"q":"What does the P/E ratio look like for a pre-revenue biotech company?","k":["A pre-revenue biotech company does not have a meaningful P/E ratio. Since it has no revenue, it almost certainly has negative Net Income (burning cash on R&D and G&A), which means EPS is negative. A negative P/E ratio is not interpretable or useful for valuation.","Instead, pre-revenue biotech companies are valued using:","Risk-adjusted NPV (rNPV) of their pipeline, probability-weighting cash flows by clinical trial success rates.","EV/Pipeline Asset or per-program valuations based on comparable licensing deals.","Price/Book or market cap relative to cash on hand (measuring the \"cash runway\" vs. implied pipeline value)."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Healthcare Group","Advanced"]},{"id":"q-2071","t":"sector","l":"Advanced","s":90,"q":"How would you forecast revenue for a drug? What is the major sensitivity in the revenue forecast?","k":["Drug revenue is forecasted using a patient-based model:","Total Addressable Market: Estimate the total patient population with the target indication (e.g., prevalence data from epidemiological studies).","Diagnosed population: Not all patients are diagnosed. Apply a diagnosis rate.","Drug-eligible population: Filter for patients who meet the drug's label criteria.","Market share: Estimate the drug's share vs. competitors, ramping over time from launch.","Price per patient: Annual cost of therapy (list price net of rebates and discounts).","Revenue = Eligible Patients x Market Share x Net Price per Patient.","Major Sensitivity","Market share (or peak market penetration) is the most sensitive input. Small changes in market share assumptions have an outsized impact on peak revenue estimates, especially in large therapeutic categories. Pricing is also highly sensitive given payer negotiations and potential government intervention (e.g., IRA provisions)."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in J.P. Morgan Interview","SA 2025, Healthcare group, SF Office, Superday","Healthcare Group","Advanced"]},{"id":"q-2072","t":"sector","l":"Advanced","s":90,"q":"Would a biotech company use equity, debt, or cash for an M&A transaction? How is money raised in biotech (IPO, debt, divestitures)?","k":["M&A Financing for Biotech","Equity (stock) is most common for large biotech/pharma M&A. Pre-revenue or early-stage biotech companies have limited cash and cannot support debt, so stock-for-stock mergers or equity-funded acquisitions are typical.","Cash is used by large-cap pharma with strong balance sheets (e.g., Pfizer, J&J) for bolt-on acquisitions.","Debt is less common for pre-revenue biotech but is used by profitable pharma companies to fund large deals (e.g., AbbVie's debt-funded Allergan acquisition).","Capital Raising in Biotech","IPO: The primary way early-stage biotech companies access public capital. Typically done after Phase 1/2 clinical data provides a valuation basis.","Follow-on equity offerings: Secondary offerings and at-the-market (ATM) programs are common for clinical-stage companies that need additional funding.","Convertible debt: Common for biotech -- offers lower interest rates than straight debt and converts to equity upon certain triggers.","Licensing / collaboration deals: Biotech companies monetize pipeline assets through upfront payments, milestones, and royalties from pharma partners.","Divestitures: Selling non-core assets or pipeline programs to raise cash and focus resources."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in J.P. Morgan Interview","SA 2025, Healthcare group, SF Office, Superday","Healthcare Group","Advanced"]},{"id":"q-2073","t":"sector","l":"Advanced","s":90,"q":"How would you value a phase 2 Alzheimer's biotech company versus a large-cap pharma company like Gilead?","k":["Phase 2 Alzheimer's Biotech","Risk-adjusted DCF (rDCF): Project peak sales for the drug, then probability-weight cash flows by the likelihood of FDA approval at each clinical stage (Phase 2 success ~30-35%).","Sum-of-the-parts: Value each pipeline asset individually using rDCF, then add net cash.","Comparable transactions: Look at recent licensing deals, partnerships, or acquisitions for similar-stage Alzheimer's assets.","Cannot use traditional EV/EBITDA or P/E since the company likely has no earnings.","Large-Cap Pharma (Gilead)","Standard DCF using projected free cash flows from existing commercial products.","Trading comps: EV/EBITDA, P/E, EV/Revenue relative to peers (Pfizer, AbbVie, Merck).","Sum-of-the-parts for marketed drugs plus rDCF for pipeline assets.","Key consideration: patent cliff timing on major drugs (e.g., HIV franchise) and replacement revenue from pipeline."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in J.P. Morgan Interview","SA 2027, SF Office, Superday","Healthcare Group","Advanced"]},{"id":"q-2074","t":"sector","l":"Advanced","s":90,"q":"What diligence questions would you ask on behalf of your preclinical stage biotech client if they were interested in acquiring or partnering with an AI company?","k":["What specific drug discovery or development stages does the AI platform address (target identification, lead optimization, clinical trial design)?","What is the AI company's track record -- have any drugs discovered or optimized using the platform entered clinical trials or received FDA approval?","What is the proprietary data advantage? How differentiated is the training data, and does the company have exclusive datasets?","IP and licensing: Who owns the IP generated by the AI platform? What are the licensing terms for any resulting drug candidates?","Revenue model: Is it fee-for-service, milestone-based, or royalty-sharing? What is the cost structure?","Integration risk: Can the AI platform integrate with your client's existing R&D infrastructure?","Regulatory considerations: Has the AI platform been validated by any regulatory body?","Competitive landscape: How does it compare to other AI drug discovery platforms (e.g., Recursion, Insilico Medicine)?"],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Jefferies Interview","SA 2026, Superday","Healthcare Group","Advanced"]},{"id":"q-2075","t":"sector","l":"Advanced","s":90,"q":"For a healthcare company in a sell-side M&A process, what would you recommend to the client one day after they receive an unsolicited offer, and what would you advise after a week?","k":["Day 1","Do not respond or engage with the acquirer immediately.","Convene the board and engage financial and legal advisors.","Assess the offer terms: price, consideration type, conditionality, and regulatory risk.","Run a preliminary valuation (comps, precedent transactions, DCF) to assess whether the offer is in a reasonable range.","Determine if there are any information leaks or obligations under the company's charter/bylaws.","After One Week","Complete a thorough standalone valuation to establish the company's intrinsic value.","Assess strategic alternatives: Can we get a higher price by running a broader process? Are there other potential acquirers (strategic or financial)?","Evaluate the offer relative to the standalone plan (including pipeline value for healthcare companies).","If the offer is below intrinsic value, respond with a rejection or counteroffer. If compelling, consider engaging -- potentially after soliciting competing bids.","Consider adopting a poison pill if there is a risk of a hostile takeover."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Lazard Interview","SA 2025, Healthcare group, SF Office, Superday","Healthcare Group","Advanced"]},{"id":"q-2076","t":"sector","l":"Advanced","s":90,"q":"How would you value a healthcare company in a sell-side context? Discuss your assumptions around forecast duration, growth rate for the DCF, how to find patent expiry information, and whether a small molecule company versus a biosimilar company would have a different terminal growth rate.","k":["Valuation Approach","Use a DCF, trading comps (EV/EBITDA, EV/Revenue), and precedent transactions. For pipeline-heavy companies, use risk-adjusted DCF (rDCF).","Forecast Duration","Extend the forecast to cover the patent life of key drugs. For a company with patents expiring in 8-12 years, project through the patent cliff. Typically 10-15 years for pharma DCFs vs. 5-10 for most industries.","Growth Rate","Revenue growth should reflect product lifecycle: ramp-up phase, peak sales, and post-patent decline. Terminal growth rate should reflect the company's long-term positioning post-patent cliff.","Patent Expiry Information","FDA Orange Book (for small molecules), Purple Book (for biologics), company 10-K filings, and sell-side research reports.","Small Molecule vs. Biosimilar Terminal Growth","Small molecule: Lower terminal growth rate because generic competition post-patent is severe (price drops 80-90%).","Biosimilar company: Higher terminal growth rate because biosimilar competition is less intense than generics -- biologics are harder to replicate, uptake is slower, and branded biologics retain more market share."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Lazard Interview","SA 2025, Healthcare group, SF Office, Superday","Healthcare Group","Advanced"]},{"id":"q-2077","t":"sector","l":"Advanced","s":90,"q":"Why would a sell-side healthcare company pursue M&A instead of an IPO or licensing deal?\n\n\n\n\nFollow-up: Why is the IPO market currently bad, and what would make the market better?","k":["M&A vs. IPO vs. Licensing","M&A provides full and immediate liquidity at a premium, versus an IPO which offers partial liquidity with ongoing public market risk.","M&A includes a control premium (20-40%) that an IPO does not.","A licensing deal only monetizes specific assets -- M&A captures the full platform value.","M&A avoids the ongoing costs and regulatory burden of being a public company (SOX compliance, quarterly reporting).","If the company needs a partner with commercial infrastructure (e.g., a sales force), an acquisition by a larger pharma is more efficient than going public and building it independently.","Follow-up: IPO Market","The IPO market has been challenged due to elevated interest rates (reducing appetite for growth stocks), valuation uncertainty, and poor aftermarket performance of recent IPOs.","Improvement catalysts: Rate cuts from the Fed, improved equity market performance, several successful high-profile IPOs to restore investor confidence, and reduced volatility."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Lazard Interview","SA 2025, Healthcare group, SF Office, Superday","Healthcare Group","Advanced"]},{"id":"q-2078","t":"sector","l":"Advanced","s":90,"q":"If a buyer only wants to acquire a company's U.S. exclusive rights, what should the company consider? And if the company sells its U.S. rights, how will investors react to the overall firm?","k":["Considerations for Selling U.S. Rights","Valuation: What is the fair value of U.S. rights vs. ex-U.S. rights? The U.S. market often represents 40-60%+ of global pharma revenue.","Remaining business viability: Can the company sustain itself on ex-U.S. revenue alone, or will it become too small to be viable as a standalone?","Deal structure: Upfront payment vs. royalties/milestones. A royalty structure preserves upside participation.","Competitive dynamics: Does selling U.S. rights weaken the company's negotiating position for ex-U.S. deals?","Tax implications: Cross-border structuring and transfer pricing considerations.","Investor Reaction","Likely negative: Investors will view the remaining entity as less valuable, with reduced growth prospects and scale.","The stock may trade at a conglomerate discount or be re-rated to reflect the smaller, less diversified business.","However, if the proceeds are deployed effectively (reinvestment, pipeline, dividends), it could be viewed positively."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in Lazard Interview","SA 2025, Healthcare group, SF Office, Superday","Healthcare Group","Advanced"]},{"id":"q-2079","t":"sector","l":"Advanced","s":90,"q":"What do you do with terminal value in a biotech valuation?","k":["It depends entirely on the type of biotech company being valued.","Single-Asset / Early-Stage Biotech","Terminal value is often zero or negligible. A single-drug biotech has a finite revenue stream tied to its patent life (typically 10-15 years of exclusivity post-approval). Once the patent expires, generics or biosimilars enter and revenue collapses. There is no perpetuity to capitalize. The valuation is driven entirely by the risk-adjusted NPV (rNPV) of discrete, probability-weighted cash flows through patent expiry, with no traditional terminal value.","Multi-Asset / Platform Biotech","A terminal value may be appropriate if the company has a diversified pipeline, a proven discovery platform, or recurring licensing revenue that generates cash flows beyond any single patent. In this case, you could apply a Gordon Growth Model with a modest or zero growth rate, or an exit multiple on a normalized earnings year. The terminal value will still represent a much smaller share of total value than in a traditional DCF because near-term pipeline cash flows dominate.","Key Takeaway","In biotech, the rNPV model replaces the standard DCF. You probability-weight each pipeline asset's projected cash flows by cumulative likelihood of FDA approval, discount them back, and sum across all assets. Terminal value is either excluded entirely (single-asset) or heavily discounted (platform companies). This is fundamentally different from a traditional corporate DCF where terminal value often represents 60-80% of enterprise value."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in MTS Health Partners Interview","SA 2027, New York Office, Second round","Healthcare Group","Advanced"]},{"id":"q-2080","t":"sector","l":"Advanced","s":90,"q":"Other than industry and geography, what specifically would you look for in biotech company comparables?","k":["Biotech comps require a much more granular selection process than traditional comps because two biotech companies in the same therapeutic area can have wildly different risk profiles and value drivers. Key criteria beyond industry and geography:","Clinical Stage","Stage of development is the single most important filter: preclinical, Phase I, Phase II, Phase III, or commercial. A Phase III company with de-risked data is not comparable to a preclinical company.","Therapeutic Area & Mechanism of Action","Narrow beyond \"biotech\" to the specific disease (e.g., non-small cell lung cancer, not just \"oncology\") and drug modality (small molecule, monoclonal antibody, gene therapy, cell therapy). Mechanism of action drives differentiation and competitive positioning.","Target Market Size & Indication","Addressable patient population and pricing potential. A rare disease orphan drug with 10,000 patients at $300K/year is not comparable to a primary care drug with millions of patients at $5K/year.","IP & Patent Runway","Remaining patent life and exclusivity protections (orphan drug exclusivity, data exclusivity, patent term extensions). A company with 15 years of protection is worth more than one facing a near-term patent cliff.","Pipeline Depth","Single-asset vs. multi-asset pipeline. A one-drug company carries binary risk; a company with 5+ clinical-stage assets has diversification value.","Revenue Model","Direct commercialization vs. royalty/licensing model. A company that out-licenses its drug for royalties has a very different margin, risk, and cost structure than one building its own sales force.","Regulatory & Approval Probability","FDA designation (Breakthrough Therapy, Fast Track, Priority Review) and historical approval rates for the drug's class. Higher regulatory de-risking supports a higher valuation multiple."],"collection":"practice","topic":"Healthcare Group","tags":["New","Reported in MTS Health Partners Interview","SA 2027, New York Office, Second round","Healthcare Group","Advanced"]},{"id":"q-2081","t":"sector","l":"Advanced","s":90,"q":"Imagine a healthcare company with a negative net income that is trading at an extremely high revenue multiple.\n\n\n\n\nHow would you explain this valuation, and what other methods could you use to value it?","k":["Explanation for High Revenue Multiple:","High growth expectations: Market pricing in rapid revenue expansion","Path to profitability: Investors believe losses are temporary, investing for scale","Large TAM: Significant addressable market justifies growth investment","Strategic value: Potential M&A target or platform play","Comparable precedent: Similar companies trade at high multiples","Alternative Valuation Methods:","DCF: Project to profitability, model long-term cash flows despite near-term losses","Comparable Companies: Use EV/Revenue or other topline metrics for pre-profitable peers","Precedent Transactions: M&A multiples for similar growth-stage healthcare companies","Sum-of-the-Parts: Value different segments or products separately","Venture Capital Method: Stage-based valuation for early-stage firms"],"collection":"practice","topic":"Healthcare Group","tags":["Reported in Unspecified Interview","Healthcare Group","Advanced"]},{"id":"q-2082","t":"sector","l":"Advanced","s":90,"q":"Walk me through a DCF for a pre-revenue biotech company in detail.\n\n\n\n\nAddress the following follow-up questions:\n\n\n\nHow would you value the R&D teams on a standalone basis, separate from the drugs currently in development?\nHow do you account for the risk of failure for drug approval?\nWhat kind of growth rates are appropriate for the terminal value?","k":["A biotech DCF requires probability-weighted projections for each drug candidate based on clinical trial phases, launch timelines, peak sales estimates, and patent cliffs.","Part 1: Valuing R&D Teams","Use a replacement cost or market-based approach, estimating the cost to hire equivalent talent or using peer valuations for similar capabilities.","Part 2: Risk of Failure","Apply probability of success (PoS) rates by phase: Phase I (~10%), Phase II (~20%), Phase III (~60%), FDA approval (~90%). Multiply projected cash flows by cumulative PoS.","Part 3: Terminal Growth Rate","Use conservative rates (0-2%) given patent expirations and generic competition, or zero if no pipeline beyond forecast period."],"collection":"practice","topic":"Healthcare Group","tags":["Reported in Unspecified Interview","Healthcare Group","Advanced"]},{"id":"q-2083","t":"sector","l":"Advanced","s":90,"q":"When valuing a pre-revenue biotech company, address the following points:\n\n\n\nIf the company cannot issue debt, what non-equity securities can it issue?\nHow do expenses typically vary over time?\nWhat do revenue patterns look like post-launch?\nIf you use a multiples-based approach, what should you consider?","k":["Part 1: Non-Equity Securities","Convertible notes, SAFE agreements, royalty financing, or milestone-based financing tied to clinical trial success.","Part 2: Expense Patterns","Expenses increase through clinical trials (Phase I → III) as trials grow in scope, then moderate post-approval with manufacturing and marketing costs.","Part 3: Revenue Patterns","J-curve: slow initial uptake, rapid growth as drug gains adoption, plateau at peak sales, decline post-patent expiry.","Part 4: Multiples Considerations","Use stage-adjusted multiples, consider pipeline depth, probability of success, and comparable transactions at similar development stages."],"collection":"practice","topic":"Healthcare Group","tags":["Reported in Unspecified Interview","Healthcare Group","Advanced"]},{"id":"q-2084","t":"sector","l":"Advanced","s":90,"q":"How did the COVID-19 pandemic impact valuations in the following healthcare sub-sectors:\n\n\n\nLife Sciences\nHealthcare Services\nHCIT (Healthcare IT)","k":["Life Sciences:","Valuations surged for diagnostics, vaccines, and therapeutics companies. Biotech focused on COVID treatments saw significant multiples expansion.","Healthcare Services:","Mixed impact. Elective procedure providers saw declines, while urgent care and home health services gained. Telehealth exploded.","HCIT:","Major valuation increases for telemedicine platforms, remote patient monitoring, and digital health tools as adoption accelerated."],"collection":"practice","topic":"Healthcare Group","tags":["Reported in Unspecified Interview","Healthcare Group","Advanced"]},{"id":"q-2085","t":"sector","l":"Basic","s":90,"q":"What are your thoughts on the electric vehicle (EV) industry in the U.S.?","k":["The U.S. EV industry presents both opportunities and challenges. A strong answer demonstrates knowledge of industry dynamics, competitive landscape, and market trends.","Key considerations:","Growth drivers: Government incentives, environmental regulations, declining battery costs.","Competitive landscape: Tesla's dominance, traditional OEMs transitioning, new entrants.","Infrastructure challenges: Charging network buildout, grid capacity.","Supply chain: Battery materials, semiconductor availability, China dependence.","Profitability concerns: High capex requirements, margin pressure, price competition."],"collection":"practice","topic":"Industrials Group","tags":["Reported in Barclays Interview","New York Office, First round","Industrials Group","Basic"]},{"id":"q-2086","t":"sector","l":"Basic","s":90,"q":"Name a valuation method (besides LBO, transaction comps, public comps, or DCF) that can be used for large industrial conglomerates, and why is it used?","k":["Sum‑of‑the‑Parts (SOTP) / Break‑Up analysis.","Different divisions warrant different multiples; valuing each separately and adding yields a more accurate view than a single blended multiple."],"collection":"practice","topic":"Industrials Group","tags":["Reported in Greenhill & Co. Interview","SA 2024, Industrials M&A, Chicago office","Industrials Group","Basic"]},{"id":"q-2087","t":"sector","l":"Basic","s":90,"q":"What would you do with excess cash as an industrial company CEO?\n\n\n\n\nWhat market circumstances would you consider in making that decision?","k":["Choices: reinvest (capex/R&D), acquire, repay debt, repurchase shares, or pay dividends.","Consider cost of capital, economic cycle, share valuation, leverage targets, and macro factors such as interest rates and demand outlook."],"collection":"practice","topic":"Industrials Group","tags":["Reported in Greenhill & Co. Interview","SA 2024, Industrials M&A, Chicago office","Industrials Group","Basic"]},{"id":"q-2088","t":"sector","l":"Basic","s":90,"q":"Which company is most attractive to invest in: one that builds planes, one that buys planes and leases them, or one that provides airline services?","k":["The airline‑services provider.","It is asset‑light, enjoys recurring fee revenue, higher ROIC and less cyclicality than capital‑intensive manufacturing or leasing models."],"collection":"practice","topic":"Industrials Group","tags":["Reported in LionTree Interview","SA 2026","Industrials Group","Basic"]},{"id":"q-2089","t":"sector","l":"Advanced","s":90,"q":"How would you project a DCF for an auto manufacturing company over the next 5 years, given current interest rates and policy actions?","k":["Revenue Forecast: Model unit volumes by segment, pricing, and mix; adjust for policy-driven subsidies, EV mandates, and interest-sensitive consumer demand.","Margin Assumptions: Project gross and EBIT margins using historical trends, cost inflation (steel, labor), efficiency gains (automation), and policy impacts (tariffs, tax credits).","Working Capital: Forecast ΔWC via days receivable, inventory, and payables; incorporate extended payment terms from suppliers under new regulations.","Capital Expenditures: Estimate maintenance vs. growth CapEx for plants, tooling, and EV battery lines; factor in government grants or accelerated depreciation allowances.","Unlevered FCF: Calculate as EBIT*(1–tax rate) + D&A – CapEx – ΔWC for each of Years 1–5.","Discount Rate (WACC): Re-lever beta for auto D/E, use current risk-free rate + ERP for cost of equity; cost of debt reflects prevailing borrowing rates and policy-induced credit spreads.","Present Value: Discount each year’s FCF back to today at WACC.","Terminal Value: Choose an exit multiple (e.g., EV/EBIT) or a perpetuity growth rate in line with long-term GDP growth, adjusting for structural shifts from policy.","Enterprise Value: Sum PVs of Years 1–5 and terminal value to arrive at the DCF-implied EV."],"collection":"practice","topic":"Industrials Group","tags":["Reported in Bank of America Interview","Chicago office, Superday","Industrials Group","Advanced"]},{"id":"q-2090","t":"sector","l":"Advanced","s":90,"q":"What is your sell-side strategy for a regional boat manufacturer known for its high-quality workmanship?","k":["Key strategic considerations:","Positioning:","Emphasize premium brand, loyal customer base, craftsmanship","Highlight stable, recurring revenue from parts/service","Document barriers to entry (skilled labor, reputation)","Target Buyers:","Strategic: Larger boat manufacturers seeking premium segment or geographic expansion","PE: Firms focused on consumer/industrial roll-ups","Family offices: HNW individuals passionate about boating industry","Process:","Targeted auction to premium marine strategics and relevant PE","Emphasize growth through new geographies or product lines","Prepare detailed customer concentration and backlog analysis"],"collection":"practice","topic":"Industrials Group","tags":["Reported in Unspecified Interview","Industrials Group","Advanced"]},{"id":"q-2091","t":"sector","l":"Basic","s":90,"q":"If you were tasked with creating a comparable company analysis for The Walt Disney Company, which companies would you include in your list and why?","k":["Disney Peer List","Comcast (NBC‑Universal) - diversified media, parks.","Netflix - streaming pure‑play, subscriber economics.","Warner Bros. Discovery - content library and networks.","Paramount Global - studio and broadcast mix.","SeaWorld or Six Flags - for parks pure comps.","Universal Music Group - for IP monetization check.","Chosen for similar revenue drivers: content production, direct‑to‑consumer streaming, and experiential assets."],"collection":"practice","topic":"Media & Telecom Group","tags":["Reported in Lazard Interview","Media & Telecom Group","Basic"]},{"id":"q-2092","t":"sector","l":"Basic","s":90,"q":"Tell me about a trend in the TMT space.","k":["Framework: Pick one trend you can discuss in depth. Structure your answer around: (1) what the trend is, (2) why it is happening, (3) how it affects M&A and deal activity, and (4) specific companies involved.","Example: AI Infrastructure Buildout","Hyperscalers (Microsoft, Google, Amazon, Meta) are spending $200B+ annually on data center CapEx to support AI workloads.","This is driving consolidation in data center operators (e.g., Equinix, Digital Realty), semiconductor companies (NVIDIA's dominance in GPU supply), and power/energy providers to support massive electricity demand.","M&A implications: strategic acquisitions of AI startups, vertical integration by cloud providers, and infrastructure-focused PE deals.","Key recent deals include large-scale data center portfolio transactions and AI-focused acquisitions by major tech platforms.","Prepare 1-2 TMT trends with specific data points and deal examples before your interview."],"collection":"practice","topic":"Media & Telecom Group","tags":["New","Reported in LionTree Interview","SA 2027, New York Office, First round","Media & Telecom Group","Basic"]},{"id":"q-2093","t":"sector","l":"Basic","s":90,"q":"Pick a company in the TMT space and explain why you would invest in it.","k":["Framework for structuring a stock pitch:","Company overview: What the company does, market position, key metrics.","Investment thesis (2-3 catalysts): Why the stock is undervalued or has upside.","Valuation: Current multiples vs. peers and historical averages.","Risks and mitigants: What could go wrong and why it is manageable.","Choose a TMT company you follow closely and can discuss with conviction. Good candidates include mid-cap software companies (less covered, more differentiated thesis), streaming/media companies undergoing transformation, or semiconductor companies benefiting from secular trends like AI.","Prepare specific financial metrics: revenue growth, EBITDA margins, FCF yield, EV/EBITDA vs. comps, and a clear catalyst timeline."],"collection":"practice","topic":"Media & Telecom Group","tags":["New","Reported in LionTree Interview","SA 2027, New York Office, First round","Media & Telecom Group","Basic"]},{"id":"q-2094","t":"sector","l":"Basic","s":90,"q":"Where does most of the revenue come from for a sports franchise?","k":["Media and broadcast rights are usually the largest slice, followed by ticket sales, sponsorships, and merchandising."],"collection":"practice","topic":"Media & Telecom Group","tags":["Reported in Moelis & Co. Interview","Superday","Media & Telecom Group","Basic"]},{"id":"q-2095","t":"sector","l":"Basic","s":90,"q":"Do you believe traditional (AM/FM) radio will eventually become obsolete? Why or why not?","k":["This is an opinion question requiring supported reasoning. Consider both sides:","Arguments for Obsolescence:","Competition from streaming (Spotify, podcasts) and digital platforms offering personalization.","Declining listenership among younger demographics who prefer on-demand content.","Advertising dollars shifting to digital platforms with better targeting.","Arguments Against Obsolescence:","Local content and emergency broadcasting remain valuable (news, weather, traffic).","Free, accessible medium requiring no subscription or data plan.","Strong presence in cars (though declining with connected vehicles).","Loyal listener base in certain demographics and geographies.","Conclusion: Traditional radio will likely remain but in diminished form, serving niche audiences and evolving into hybrid digital-terrestrial models rather than becoming completely obsolete."],"collection":"practice","topic":"Media & Telecom Group","tags":["Reported in Morgan Stanley Interview","New York Office","Media & Telecom Group","Basic"]},{"id":"q-2096","t":"sector","l":"Advanced","s":90,"q":"You see a graph of a luxury company's P/E during the pandemic.\n\n\n\n\nIt spikes sharply because the stock price stayed flat while earnings dropped.\n\n\n\n\nExplain the significance and what it says about investor sentiment.","k":["P/E blew up because the “E” fell, not because the stock got expensive.","Investors kept bidding the shares at the pre‑shock level, signalling they viewed the earnings hit as temporary and expected a rebound.","In other words, the high multiple may reflect confidence in the brand’s pricing power, balance‑sheet strength, and ability to recover post‑crisis."],"collection":"practice","topic":"Media & Telecom Group","tags":["Reported in Centerview Partners Interview","SA 2025, off-cycle, London office","Media & Telecom Group","Advanced"]},{"id":"q-2097","t":"sector","l":"Advanced","s":90,"q":"If J.P. Morgan were to create and own a professional sports team, what are all the costs you would need to consider?","k":["Key cost categories:","Acquisition/Franchise Fee: Initial purchase price or league expansion fee.","Player Salaries & Contracts: Largest ongoing expense, including bonuses and guarantees.","Coaching & Staff: Coaches, trainers, medical staff, front office personnel.","Stadium/Arena: Lease payments, or construction/renovation costs if owned.","Operations: Game day expenses, travel, equipment, facilities maintenance.","Marketing & Sales: Advertising, ticket sales, sponsorships, merchandise.","League Fees & Revenue Sharing: Payments to league, revenue sharing with other teams.","Insurance: Player injury insurance, liability coverage.","Legal & Compliance: Contracts, labor negotiations, regulatory compliance.","Technology & Analytics: Data systems, scouting software, performance tracking."],"collection":"practice","topic":"Media & Telecom Group","tags":["Reported in J.P. Morgan Interview","SA 2025","Media & Telecom Group","Advanced"]},{"id":"q-2098","t":"sector","l":"Advanced","s":90,"q":"How would the WACC for the Denver Nuggets compare to that of the LA Lakers?","k":["The Nuggets should carry a higher WACC.","Smaller market ⇒ less‑diversified revenue, higher beta.","Lower brand value ⇒ higher credit spreads.","Lakers benefit from global brand and deeper capital access ⇒ lower cost of capital."],"collection":"practice","topic":"Media & Telecom Group","tags":["Reported in Moelis & Co. Interview","Superday","Media & Telecom Group","Advanced"]},{"id":"q-2099","t":"sector","l":"Advanced","s":90,"q":"What are some alternative valuation methods used specifically for oil and gas exploration and production (E&P) companies?","k":["E&P-specific valuation methods:","NAV (Net Asset Value): Present value of proved reserves using commodity price forecasts and decline curves","EV/Production: Enterprise value per barrel of oil equivalent per day (boe/d)","EV/Reserves: Enterprise value per barrel of proved reserves ($/boe)","EV/Acreage: Enterprise value per developed or undeveloped acre","Reserve-Based Lending: Value based on percentage of PV-10 (present value of proved reserves discounted at 10%)","Finding & Development Cost Multiples: Compare costs to develop reserves","These methods account for commodity price volatility, reserve quantities, production profiles, and drilling economics unique to E&P companies."],"collection":"practice","topic":"Natural Resources Group","tags":["Reported in Citi Interview","Oil & Gas group, Houston office, Superday","Natural Resources Group","Advanced"]},{"id":"q-2100","t":"sector","l":"Advanced","s":90,"q":"How would you model a company that owns and operates multiple gas-fired power plants?","k":["Key modeling considerations for gas-fired power plants:","Revenue: Model power price ($/MWh) * generation (MWh). Use forward power curves or merchant power price assumptions","COGS: Model natural gas costs (heat rate * gas price * generation) plus variable O&M","Capacity Factor: Forecast utilization rates based on dispatch economics and baseload vs. peaking role","Contract Structure: Separate contracted (PPA) vs. merchant exposure","CapEx: Maintenance capex for existing plants, growth capex for new builds","Asset Life: Model remaining useful life and terminal value assumptions","Environmental Costs: Factor in emissions credits, compliance costs","Build each plant separately then consolidate for portfolio view","Use DCF with WACC reflecting power market risk. Consider precedent transactions ($/kW or $/MW) and comparable company multiples for triangulation."],"collection":"practice","topic":"Natural Resources Group","tags":["Reported in Credit Suisse Interview","New York office, Superday","Natural Resources Group","Advanced"]},{"id":"q-2101","t":"sector","l":"Advanced","s":90,"q":"Walk me through a DCF valuation for a pipeline company. What specific considerations are important?\n\n\n\n\nSeparately, if your required rate of return is 12%, how long would it take to double your investment?","k":["Part 1: Pipeline Company DCF","Standard DCF framework applies, with specific considerations:","Revenue: Model fee-based contracts (take-or-pay) vs. commodity-exposed throughput","EBITDA: Pipelines have stable, predictable margins due to regulated/contracted nature","CapEx: Separate maintenance capex from growth capex (new pipeline builds)","Terminal Value: Use perpetuity growth or exit multiple, reflecting mature asset base","WACC: Typically lower due to stable cash flows; use utility-style betas","Regulatory Environment: Factor in rate regulations and tariff structures","Contract Rollovers: Model contract renewal risk and pricing","Part 2: Time to Double Investment","Answer: ~6 years","Use Rule of 72: 72 / Rate = Years to Double","72 / 12 = 6 years","More precisely: ln(2) / ln(1.12) = 6.12 years"],"collection":"practice","topic":"Natural Resources Group","tags":["Reported in J.P. Morgan Interview","Houston office, Superday","Natural Resources Group","Advanced"]},{"id":"q-2102","t":"sector","l":"Advanced","s":90,"q":"How would you value an oil and gas company differently than a technology company?\n\n\n\n\nWhat valuation method is particularly relevant for an oil and gas company, and why?","k":["Key Differences","Oil & Gas: Asset-heavy, commodity-driven, depleting reserves, cyclical cash flows.","Technology: Asset-light, recurring revenue, scalable, growth-focused.","O&G uses EV/EBITDA, P/Proven Reserves, DCF with commodity price sensitivity.","Tech uses EV/Revenue, P/E, growth-adjusted multiples.","NAV (Net Asset Value) Method","Particularly relevant for oil & gas companies. NAV values each asset (oil/gas reserves) based on:","Proven reserves (proved developed producing, proved developed non-producing, proved undeveloped).","Discounted cash flows from each reserve using commodity price assumptions.","Subtract debt to get equity NAV per share.","NAV captures the intrinsic value of physical reserves, critical for capital-intensive, reserve-driven businesses."],"collection":"practice","topic":"Natural Resources Group","tags":["Reported in J.P. Morgan Interview","SA 2025","Natural Resources Group","Advanced"]},{"id":"q-2103","t":"sector","l":"Advanced","s":90,"q":"Discuss the DRAM market and the chip supply chain.","k":["DRAM Market:","DRAM is a commodity memory chip used in PCs, servers, smartphones, and increasingly in AI/data center applications. The market is an oligopoly dominated by three players: Samsung (~40% share), SK Hynix (~30%), and Micron (~25%). Pricing is highly cyclical, driven by supply-demand dynamics.","The major growth driver is AI infrastructure, which requires HBM (High Bandwidth Memory) - a premium DRAM product stacked vertically for higher bandwidth. HBM commands significantly higher margins than conventional DRAM and is in severe shortage.","Chip Supply Chain:","Design: Fabless companies (NVIDIA, Qualcomm, AMD) design chips using EDA tools from Synopsys and Cadence.","Manufacturing: Foundries (TSMC, Samsung Foundry, Intel Foundry) fabricate the chips using equipment from ASML, Applied Materials, Lam Research, and Tokyo Electron.","Packaging & Testing: OSAT companies (ASE, Amkor) or foundries themselves handle assembly, packaging, and testing.","Distribution: Arrow Electronics, Avnet, and direct sales channels deliver chips to OEMs.","The supply chain is highly concentrated geographically in East Asia (Taiwan, South Korea), creating significant geopolitical risk."],"collection":"practice","topic":"Hardware & Semiconductors Group","tags":["New","Reported in Morgan Stanley Interview","SA 2026, Superday","Hardware & Semiconductors Group","Advanced"]},{"id":"q-2104","t":"sector","l":"Basic","s":90,"q":"What kind of valuation methods are not typically used in real estate?","k":["A standard DCF and EV/EBITDA comps are not typically used for REITs and real estate companies.","Reasons:","DCF: REITs distribute most of their income as dividends (required to pay out 90%+ of taxable income), so a Dividend Discount Model (DDM) is more appropriate than a traditional UFCF-based DCF.","EV/EBITDA: Real estate valuation relies on Net Asset Value (NAV), cap rates, and price-to-FFO (Funds From Operations) or price-to-AFFO rather than EBITDA multiples. EBITDA does not capture the capital-intensive nature of real estate or the value of the underlying assets.","Standard real estate valuation methods include: NAV, Cap Rate analysis, DDM, P/FFO, and P/AFFO."],"collection":"practice","topic":"Real Estate, Gaming, & Lodging Group","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Real Estate, Gaming, & Lodging Group","Basic"]},{"id":"q-2105","t":"sector","l":"Basic","s":90,"q":"How do you value a REIT?","k":["REITs are valued using specialized methodologies:","Net Asset Value (NAV): Value each property using NOI / cap rate, sum all property values, add other assets, subtract liabilities and debt. Compare NAV per share to the current stock price (premium/discount to NAV).","P/FFO (Funds From Operations): FFO = Net Income + Depreciation - Gains on Property Sales. The REIT equivalent of a P/E multiple. Industry standard per NAREIT.","P/AFFO (Adjusted Funds From Operations): AFFO = FFO - recurring CapEx (maintenance CapEx). A more conservative measure of recurring cash flow.","Dividend Yield: REITs are required to distribute 90%+ of taxable income. Dividend yield relative to peers indicates relative value.","Cap Rate Analysis: Implied cap rate = NOI / Property Value. Lower cap rates imply higher valuations."],"collection":"practice","topic":"Real Estate, Gaming, & Lodging Group","tags":["New","Reported in Jefferies Interview","SA 2026, First round","Real Estate, Gaming, & Lodging Group","Basic"]},{"id":"q-2106","t":"sector","l":"Basic","s":90,"q":"If you have a REIT's Net Operating Income (NOI) and its implied cap rate, what can you derive from these two inputs?","k":["Property Value = NOI / Cap Rate","This gives you the implied value of the REIT's property portfolio. From there, you can derive the NAV by subtracting debt and other liabilities, and compare the NAV per share to the stock price to assess whether the REIT trades at a premium or discount to its intrinsic asset value.","You can also sensitize the cap rate to see how small changes affect property value. For example, with $100M NOI: at a 5% cap rate, value = $2B; at a 6% cap rate, value = $1.67B -- a 100 bps change in cap rate has a significant impact on valuation."],"collection":"practice","topic":"Real Estate, Gaming, & Lodging Group","tags":["New","Reported in Jefferies Interview","SA 2026, First round","Real Estate, Gaming, & Lodging Group","Basic"]},{"id":"q-2107","t":"sector","l":"Basic","s":90,"q":"If a REIT is trading at a premium to its NAV, what does this mean? What about if it is trading at a discount?","k":["Premium to NAV:","The market values the REIT above the liquidation value of its properties. This implies investors believe the management team, platform, and growth pipeline create value beyond the current asset base (e.g., superior asset management, development upside, brand value).","Typically seen for REITs with strong growth prospects, high-quality portfolios, or favorable sector dynamics.","Discount to NAV:","The market values the REIT below its asset value. This could indicate concerns about management quality, upcoming lease expirations, high leverage, portfolio quality, or unfavorable sector headwinds.","It may also signal a buying opportunity if the discount is unwarranted.","A persistent discount may attract activist investors or privatization via LBO."],"collection":"practice","topic":"Real Estate, Gaming, & Lodging Group","tags":["New","Reported in Jefferies Interview","SA 2026, First round","Real Estate, Gaming, & Lodging Group","Basic"]},{"id":"q-2108","t":"sector","l":"Advanced","s":90,"q":"Walk me through a full Net Asset Value (NAV) model.","k":["Calculate Net Operating Income (NOI) for each property or property segment: Revenue - Operating Expenses (excluding depreciation and corporate overhead).","Apply a cap rate to each NOI stream to derive the gross asset value: NOI / Cap Rate = Property Value.","Sum all property values to get total real estate asset value.","Add the value of other assets (land held for development, joint ventures, cash).","Subtract all liabilities (mortgage debt, unsecured debt, preferred equity).","The result is Net Asset Value. Divide by shares outstanding for NAV per share.","Compare NAV per share to the current stock price to determine if the REIT trades at a premium or discount to NAV."],"collection":"practice","topic":"Real Estate, Gaming, & Lodging Group","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Real Estate, Gaming, & Lodging Group","Advanced"]},{"id":"q-2109","t":"sector","l":"Advanced","s":90,"q":"Part 1: How do you calculate an implied cap rate?\n\n\n\n\nPart 2: How do you calculate a nominal cap rate?\n\n\n\n\nPart 3: What is the difference between the two?\n\n\n\n\nPart 4: Where do you find a nominal cap rate?","k":["Part 1: Implied Cap Rate","Implied Cap Rate = NOI / Property Value (or Enterprise Value). This is derived from the market -- you take the property's NOI and divide by its current market value or transaction price.","Part 2: Nominal Cap Rate","A nominal cap rate is a benchmark rate observed from comparable property transactions. Nominal Cap Rate = Sale Price NOI / Sale Price for recent comparable transactions.","Part 3: Difference","The implied cap rate is specific to one property and derived from its current valuation. The nominal cap rate is a market-observed benchmark from comparable transactions or broker surveys, used to value properties when a direct market price is unavailable.","Part 4: Sources","Nominal cap rates are found in real estate brokerage reports (CBRE, JLL, Cushman & Wakefield), NCREIF data, Green Street Advisors research, and recent comparable property transaction data."],"collection":"practice","topic":"Real Estate, Gaming, & Lodging Group","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Real Estate, Gaming, & Lodging Group","Advanced"]},{"id":"q-2110","t":"sector","l":"Advanced","s":90,"q":"What are the components of a DCF? How do DCFs and NAV models intersect?","k":["DCF components: (1) Projected free cash flows during the forecast period, (2) terminal value (via perpetuity growth or exit multiple), (3) discount rate (WACC), and (4) the sum of present values yields enterprise value.","Intersection with NAV: Both models value assets based on their ability to generate future cash flows. In a NAV model, you capitalize NOI using a cap rate (which is essentially a simplified perpetuity formula: NOI / cap rate = value). A cap rate is conceptually equivalent to a discount rate minus a growth rate (Cap Rate = Discount Rate - Growth Rate). So a NAV model is effectively a series of single-property perpetuity DCFs. A full DCF projects detailed annual cash flows and applies a discount rate, while NAV uses the shortcut of capitalizing stabilized NOI."],"collection":"practice","topic":"Real Estate, Gaming, & Lodging Group","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Real Estate, Gaming, & Lodging Group","Advanced"]},{"id":"q-2111","t":"sector","l":"Advanced","s":90,"q":"How does a REIT close the gap when it is trading at a premium to NAV? How does it close the gap when it is trading at a discount to NAV?","k":["Premium to NAV (stock price > NAV per share):","Issue equity at the elevated share price and use proceeds to acquire properties at NAV or below -- this is accretive because you raise capital above the value of underlying assets.","Sell properties at or near NAV, proving that the premium is warranted through successful asset monetization.","Discount to NAV (stock price < NAV per share):","Buy back shares: Repurchasing stock below NAV is effectively buying assets at a discount.","Sell properties at or above NAV to demonstrate the hidden value and close the valuation gap.","Go private: A take-private transaction allows the sponsor to capture the discount to NAV.","Improve operational performance: Better NOI growth can lift the stock price toward NAV."],"collection":"practice","topic":"Real Estate, Gaming, & Lodging Group","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Real Estate, Gaming, & Lodging Group","Advanced"]},{"id":"q-2112","t":"sector","l":"Advanced","s":90,"q":"Why would cap rates for lodging in San Francisco be higher than in New York City?","k":["Higher cap rates imply higher risk and/or lower growth expectations. San Francisco lodging has higher cap rates than NYC because:","Demand concentration risk: SF relies heavily on tech conferences and business travel, making it more cyclical and sensitive to industry downturns.","Seasonal volatility: SF hotel demand is more seasonal compared to NYC's diversified year-round tourism, business, and cultural demand.","Supply dynamics: NYC has higher barriers to entry (limited land, zoning), supporting pricing power. SF has faced more new hotel supply.","Market depth: NYC is a deeper, more liquid real estate market with more institutional capital, which compresses cap rates.","Post-pandemic recovery: SF was slower to recover from COVID-era remote work trends, creating uncertainty about long-term demand levels."],"collection":"practice","topic":"Real Estate, Gaming, & Lodging Group","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Real Estate, Gaming, & Lodging Group","Advanced"]},{"id":"q-2113","t":"sector","l":"Advanced","s":90,"q":"Walk me through a \"back of the napkin\" Net Asset Value (NAV) model for a REIT.","k":["Start with the REIT's total Net Operating Income (NOI) from its property portfolio.","Divide NOI by an appropriate cap rate to get the gross asset value of the real estate portfolio. Cap rate can be derived from comparable property transactions.","Add the value of any other assets (cash, development pipeline, land bank) at estimated market value.","Subtract total debt (at market value or face value).","Subtract preferred equity and other claims senior to common equity.","The result is NAV attributable to common equity holders.","Divide by diluted shares outstanding to get NAV per share.","Compare to the current stock price to determine premium or discount to NAV."],"collection":"practice","topic":"Real Estate, Gaming, & Lodging Group","tags":["New","Reported in Jefferies Interview","SA 2026, First round","Real Estate, Gaming, & Lodging Group","Advanced"]},{"id":"q-2114","t":"sector","l":"Basic","s":90,"q":"Will a follow-on offering be accretive or dilutive?","k":["A primary follow-on offering is dilutive to existing shareholders on a per-share basis.","New shares are issued, increasing the total share count.","EPS decreases because net income is spread across more shares (assuming the capital raised is not immediately deployed to generate earnings).","However, if the proceeds are used for accretive investments (acquisitions, growth CapEx) that generate returns above the cost of capital, the offering could be accretive to EPS over time.","Follow-on offerings are also typically priced at a discount (1-5%) to the current share price, creating immediate dilution for existing holders."],"collection":"practice","topic":"Equity Capital Markets (ECM)","tags":["New","Reported in Bank of America Interview","SA 2025, Superday","Equity Capital Markets (ECM)","Basic"]},{"id":"q-2115","t":"sector","l":"Basic","s":90,"q":"How do Federal Reserve actions affect the equity capital markets (ECM)?","k":["Fed actions, primarily changes to the federal funds rate and quantitative easing/tightening, have significant impacts on ECM:","Rate cuts / dovish policy: Lower discount rates increase equity valuations, boosting IPO and secondary offering activity. Cheaper cost of capital encourages companies to go public. Investors rotate into equities for higher returns.","Rate hikes / hawkish policy: Higher discount rates compress equity valuations, reducing IPO windows. Higher cost of capital makes equity issuance less attractive. Investors rotate toward fixed income for yield.","Forward guidance: Signaling future rate paths affects market sentiment and the timing of ECM issuance. Companies rush to issue before anticipated tightening.","Quantitative easing: Increases liquidity in markets, supporting higher equity valuations and more ECM activity."],"collection":"practice","topic":"Equity Capital Markets (ECM)","tags":["New","Reported in UBS Interview","SA 2027","Equity Capital Markets (ECM)","Basic"]},{"id":"q-2116","t":"sector","l":"Advanced","s":90,"q":"A company has an IPO next year and is worried about its leverage ratio. How would you assess whether its leverage ratio is too high, and if so, what would you do to help the client?","k":["Assessing the Leverage Ratio:","Compare Debt/EBITDA to public comps in the same industry. If the company's leverage is materially above the peer median, it may concern public market investors.","Review credit rating thresholds - investment grade companies typically have Debt/EBITDA below 3-4x depending on sector.","Evaluate interest coverage ratio (EBITDA / Interest Expense) to ensure the company can comfortably service its debt.","Consider the IPO investor base - equity investors generally prefer lower leverage for stability.","Solutions if Leverage is Too High:","Use a portion of IPO proceeds to pay down debt.","Refinance expensive debt at lower rates pre-IPO.","Sell non-core assets to generate cash for deleveraging.","Convert debt to equity (e.g., debt-for-equity swap with existing creditors).","Grow into the leverage by demonstrating a credible EBITDA growth story in the IPO roadshow."],"collection":"practice","topic":"Equity Capital Markets (ECM)","tags":["New","Reported in J.P. Morgan Interview","SA 2026, First round","Equity Capital Markets (ECM)","Advanced"]},{"id":"q-2117","t":"sector","l":"Basic","s":90,"q":"Tell me about investment grade bonds versus non-investment grade bonds.","k":["Investment Grade (IG) Bonds:","Rated BBB- or higher by S&P / Baa3 or higher by Moody's.","Lower default risk, lower yields (tighter credit spreads).","Issued by large, stable companies with strong cash flows and balance sheets.","Broader investor base (insurance companies, pension funds, mutual funds).","Typically have fewer and less restrictive covenants.","Non-Investment Grade (High Yield / \"Junk\") Bonds:","Rated BB+ or lower by S&P / Ba1 or lower by Moody's.","Higher default risk, higher yields (wider credit spreads) to compensate investors.","Issued by smaller, more leveraged, or riskier companies.","Narrower investor base (hedge funds, high-yield mutual funds, CLOs).","Typically include more protective covenants (maintenance and incurrence tests).","Often used in LBO financing and leveraged recapitalizations."],"collection":"practice","topic":"Debt Capital Markets (DCM)","tags":["New","Reported in Bank of America Interview","LA Office, Superday","Debt Capital Markets (DCM)","Basic"]},{"id":"q-2118","t":"sector","l":"Basic","s":90,"q":"What is the difference between bonds and loans?","k":["Issuance: Bonds are issued in the public or 144A market to institutional investors; loans are originated by banks and may be syndicated to institutional lenders.","Interest rate: Bonds typically carry a fixed coupon; loans typically carry a floating rate (SOFR + spread).","Tradability: Bonds trade on secondary markets with relative ease; loans trade in the secondary market but with less liquidity and longer settlement times.","Prepayment: Loans can generally be prepaid at par without penalty; bonds often have call protection or make-whole provisions.","Covenants: Loans historically had maintenance covenants (tested periodically); bonds typically have incurrence covenants (tested only when an action is taken).","Seniority: Loans are usually senior secured; bonds can be senior secured, senior unsecured, or subordinated."],"collection":"practice","topic":"Debt Capital Markets (DCM)","tags":["New","Reported in Bank of America Interview","SA 2026, Superday","Debt Capital Markets (DCM)","Basic"]},{"id":"q-2119","t":"sector","l":"Basic","s":90,"q":"What are covenants in the context of debt agreements, and why are they important?","k":["Covenants are contractual restrictions in debt agreements that protect lenders by limiting the borrower's actions.","Two main types:","Maintenance covenants: Require the borrower to continuously meet financial thresholds (e.g., Debt/EBITDA below 6.0x, Interest Coverage above 2.0x). Tested quarterly. Common in revolving credit facilities.","Incurrence covenants: Only tested when the borrower takes a specific action (e.g., issuing new debt, paying a dividend, making an acquisition). Common in high-yield bonds and cov-lite loans.","Covenants are important because they provide early warning signals of financial distress and give lenders leverage to negotiate or accelerate the debt if the borrower's condition deteriorates."],"collection":"practice","topic":"Debt Capital Markets (DCM)","tags":["New","Reported in Bank of America Interview","SA 2026, Superday","Debt Capital Markets (DCM)","Basic"]},{"id":"q-2120","t":"sector","l":"Basic","s":90,"q":"What is the difference between a syndicated loan and a bond?","k":["Syndicated Loan:","Originated by a bank (or group of banks) and syndicated to institutional lenders.","Typically floating-rate (SOFR + spread).","Secured by company assets (senior in the capital structure).","Prepayable without penalty (or with minimal call protection).","Private instrument, negotiated terms with covenants (maintenance covenants).","Bond:","Issued in the public or private capital markets to a broad investor base.","Typically fixed-rate.","Can be secured or unsecured (high-yield bonds are often unsecured).","Non-callable for an initial period, then callable at a premium (call protection).","Governed by an indenture with incurrence covenants (less restrictive than maintenance covenants)."],"collection":"practice","topic":"Debt Capital Markets (DCM)","tags":["New","Reported in J.P. Morgan Interview","SA 2027, New York Office, Superday","Debt Capital Markets (DCM)","Basic"]},{"id":"q-2121","t":"sector","l":"Basic","s":90,"q":"What factors would you consider when deciding whether to raise capital with debt or equity?","k":["Current leverage: If the company is already highly levered, additional debt increases financial risk. Equity may be more appropriate.","Cost of capital: Debt is cheaper (tax-deductible interest), but excessive leverage increases the cost of both debt and equity.","Cash flow stability: Companies with stable, predictable cash flows can support more debt. Volatile businesses should lean toward equity.","Use of proceeds: If funding an acquisition, debt may be preferred (interest is tax-deductible). For long-term R&D or speculative investments, equity avoids mandatory repayment risk.","Market conditions: In low-rate environments, debt is attractive. If the stock price is high, equity issuance minimizes dilution.","Ownership dilution: Debt avoids diluting existing shareholders. Equity dilutes ownership and EPS.","Flexibility: Debt comes with covenants and fixed obligations. Equity provides more operational freedom.","Credit rating impact: Additional debt may trigger a ratings downgrade, increasing future borrowing costs."],"collection":"practice","topic":"Debt Capital Markets (DCM)","tags":["New","Reported in Mizuho Interview","SA 2027, Superday","Debt Capital Markets (DCM)","Basic"]},{"id":"q-2122","t":"sector","l":"Basic","s":90,"q":"What factors would you consider when advising a company on issuing debt?","k":["Current leverage: Existing Debt/EBITDA and interest coverage ratios — how much additional capacity exists before risking a downgrade or covenant breach.","Interest rate environment: Whether rates are favorable for locking in fixed-rate debt or if floating-rate debt is cheaper in the near term.","Use of proceeds: Whether the debt is funding an acquisition, refinancing existing obligations, share buybacks, or general corporate purposes affects the appropriate structure.","Credit rating impact: How much incremental debt the company can take on while maintaining its current investment-grade or high-yield rating.","Maturity profile: Matching the debt maturity to the asset life or cash flow profile, and avoiding a concentration of maturities.","Covenant structure: Whether to pursue covenant-lite terms (more flexibility) vs. tighter covenants (potentially lower cost).","Fixed vs. floating rate: The company's preference for interest rate certainty vs. potentially lower initial cost.","Market conditions: Current credit spreads, investor appetite, and recent comparable issuances.","Tax shield: Interest expense is tax-deductible, making debt cheaper on an after-tax basis relative to equity."],"collection":"practice","topic":"Debt Capital Markets (DCM)","tags":["New","Reported in Mizuho Interview","SA 2027, Superday","Debt Capital Markets (DCM)","Basic"]},{"id":"q-2123","t":"sector","l":"Basic","s":90,"q":"When a company is thinking about issuing debt and equity, what factors should it consider?","k":["Key factors a company should consider when choosing between debt and equity issuance:","Cost of capital: Debt is typically cheaper due to the tax deductibility of interest and lower required returns for lenders. Equity is more expensive but does not require mandatory payments.","Current leverage and credit profile: If the company is already highly leveraged, additional debt may be difficult to obtain or prohibitively expensive. Equity may be the only option.","Dilution: Issuing equity dilutes existing shareholders' ownership and EPS. Debt avoids dilution.","Cash flow stability: Companies with stable, predictable cash flows can support more debt. Cyclical or early-stage companies may prefer equity to avoid default risk.","Market conditions: Interest rate environment, credit spreads, and equity market valuations all influence timing and relative attractiveness.","Covenants and restrictions: Existing debt agreements may limit additional borrowing or require maintaining certain ratios.","Use of proceeds: Short-term needs may favor revolving credit, while permanent capital needs may favor equity or long-term debt.","Signal to the market: Equity issuance can signal that management believes the stock is overvalued, while debt issuance may signal confidence in future cash flows."],"collection":"practice","topic":"Debt Capital Markets (DCM)","tags":["New","Reported in Raymond James Interview","SA 2027, First round","Debt Capital Markets (DCM)","Basic"]},{"id":"q-2124","t":"sector","l":"Basic","s":90,"q":"A bond has a fixed coupon and interest rates are cut tomorrow. What is the impact on the value of the bond?","k":["The bond's value increases.","A bond's price and prevailing interest rates have an inverse relationship. When interest rates fall, new bonds are issued at lower coupon rates. The existing bond with its higher fixed coupon becomes more attractive to investors, driving up its price. Mathematically, the bond's cash flows (fixed coupons + principal) are discounted at a lower rate, increasing the present value.","The magnitude of the price increase depends on the bond's duration - longer-duration bonds are more sensitive to interest rate changes and will see a larger price increase."],"collection":"practice","topic":"Debt Capital Markets (DCM)","tags":["New","Reported in Unspecified Interview","SA 2027, Superday","Debt Capital Markets (DCM)","Basic"]},{"id":"q-2125","t":"sector","l":"Advanced","s":90,"q":"Why do you think financial sponsors are increasingly using large Term Loan Bs (TLBs) in their capital structures?","k":["Flexibility: TLBs are typically covenant-lite (cov-lite), giving sponsors more operational flexibility with fewer restrictions than traditional bank loans.","Prepayment: TLBs can be prepaid at par with minimal or no prepayment penalties, allowing sponsors to refinance opportunistically.","Size: The institutional leveraged loan market has grown significantly, enabling larger TLB issuances that can fund bigger deals.","Investor demand: CLOs and institutional loan funds have strong appetite for floating-rate assets, creating deep demand for TLBs.","Speed of execution: TLBs can be syndicated relatively quickly compared to high-yield bond issuances.","Floating rate benefit: In a declining rate environment, TLBs (SOFR-based) automatically reduce interest expense as rates fall."],"collection":"practice","topic":"Debt Capital Markets (DCM)","tags":["New","Reported in Bank of America Interview","SA 2026, Superday","Debt Capital Markets (DCM)","Advanced"]},{"id":"q-2126","t":"sector","l":"Advanced","s":90,"q":"Bond A trades at a higher price while Bond B trades at a lower price. Why might this be the case? What macroeconomic reasons could explain the difference in bond yields?","k":["Bond prices and yields are inversely related. Bond A trades at a higher price (lower yield) and Bond B at a lower price (higher yield). Possible reasons:","Bond-specific factors:","Credit quality: Bond A may have a higher credit rating (lower default risk), while Bond B is riskier.","Maturity: Bond A may have a shorter maturity, reducing duration and interest rate risk.","Coupon rate: Bond A may have a higher coupon relative to current market rates.","Seniority: Bond A may be senior secured while Bond B is subordinated or unsecured.","Liquidity: Bond A may be more liquid, trading at a tighter spread.","Macroeconomic factors:","Interest rate changes: Rising rates push bond prices down. If Bond B was issued when rates were lower, its fixed coupon is less attractive.","Inflation expectations: Higher expected inflation erodes bond returns, pushing prices down.","Economic outlook: In a weakening economy, investors flee to higher-quality bonds (flight to quality), pushing up Bond A's price if it is investment grade.","Monetary policy: Fed tightening increases yields across the board, disproportionately affecting lower-quality issuers."],"collection":"practice","topic":"Debt Capital Markets (DCM)","tags":["New","Reported in J.P. Morgan Interview","SA 2027, New York Office, Superday","Debt Capital Markets (DCM)","Advanced"]},{"id":"q-2127","t":"sector","l":"Advanced","s":90,"q":"Part 1: A 5-year bond is trading at par and the coupon rate is 4%. What is the Yield to Maturity (YTM)?\n\n\n\n\nPart 2: Assume the Fed raises rates to 5%. Where would the bond trade?\n\n\n\n\nPart 3: Assume the rate environment stays steady with the Fed keeping rates flat at 5%. How would you expect the bond's price to move as it gets closer to maturity?","k":["Part 1","YTM = 4%. When a bond trades at par, the YTM equals the coupon rate.","Part 2","The bond would trade below par (at a discount). New bonds yield 5%, so existing bonds with a 4% coupon must decline in price to offer a competitive yield. The price would drop to approximately $95.65 (the PV of the remaining 4% coupons and $100 par discounted at 5%).","Part 3","The bond's price would gradually increase (pull to par) as it approaches maturity. At maturity, the bondholder receives $100 par regardless of prevailing rates, so the discount narrows over time. This is called the pull-to-par effect."],"collection":"practice","topic":"Debt Capital Markets (DCM)","tags":["New","Reported in Lazard Interview","SA 2027, First round","Debt Capital Markets (DCM)","Advanced"]},{"id":"q-2128","t":"sector","l":"Basic","s":90,"q":"What are GP-led secondaries?","k":["GP-led secondaries (continuation vehicles) are transactions where a PE fund's GP transfers portfolio companies from an existing fund into a new vehicle. Existing LPs can cash out or roll into the new vehicle.","This allows the GP to hold high-performing assets beyond the original fund's life while providing liquidity to LPs who want to exit. A secondary buyer provides capital to purchase the cashing-out LPs' interests. GP-led secondaries have become a major portion of the secondary market, giving GPs more flexibility on exit timing."],"collection":"practice","topic":"Private Capital Advisory","tags":["New","Reported in Brown Brothers Harriman Interview","SA 2027, Cedar Street group, First round","Private Capital Advisory","Basic"]},{"id":"q-2129","t":"sector","l":"Basic","s":90,"q":"What are co-investments?","k":["Co-investments are direct investments by LPs alongside a PE fund in a specific deal, typically on the same terms. The GP offers co-invest when a deal is too large for the fund alone or for high-conviction opportunities.","Usually at reduced or zero fees/carry, making them attractive to LPs.","LPs get direct exposure to specific assets rather than a blind pool.","Allows the GP to pursue larger deals without exceeding concentration limits.","Trade-off: LPs take on single-asset concentration risk."],"collection":"practice","topic":"Private Capital Advisory","tags":["New","Reported in Brown Brothers Harriman Interview","SA 2027, Cedar Street group, First round","Private Capital Advisory","Basic"]},{"id":"q-2130","t":"sector","l":"Advanced","s":90,"q":"What is the difference between a firm like Cedar Street that focuses exclusively on GP-led secondaries and co-investing compared to traditional buyout firms like KKR or Blackstone? Why would you pursue this strategy?","k":["Key Differences","Buyout firms acquire controlling stakes, source proprietary deals, and drive operational improvements over a 3-7 year hold.","A GP-led secondaries/co-invest firm invests alongside or behind other GPs, evaluating existing portfolio companies rather than originating deals.","Secondaries invest in more mature, de-risked assets with established track records.","Deal sourcing relies on GP relationships and the secondary market, not traditional M&A processes.","Why Pursue This Strategy","Lower blind-pool risk - you evaluate specific assets with actual performance data.","Potential to acquire at a discount to NAV or with information advantages.","Shorter holding periods and faster return of capital.","Diversification across GPs, vintages, and strategies."],"collection":"practice","topic":"Private Capital Advisory","tags":["New","Reported in Brown Brothers Harriman Interview","SA 2027, Cedar Street group, First round","Private Capital Advisory","Advanced"]},{"id":"q-2131","t":"sector","l":"Advanced","s":90,"q":"If the existing LPs do not even believe in the investment themselves, why would someone pursue GP-led secondaries?","k":["LPs sell for reasons unrelated to asset quality:","Liquidity needs (pension payments, fund redemptions, rebalancing).","Portfolio management (overweight in a vintage, sector, or geography).","Regulatory or mandate constraints on fund life or illiquid allocations.","Change in strategy (exiting PE or shifting asset classes).","Fund life expiration - LP prefers liquidity over rolling into a continuation vehicle.","Selling does not mean the asset is bad. A secondary buyer with a longer time horizon and fresh capital can capture value the selling LP cannot afford to wait for."],"collection":"practice","topic":"Private Capital Advisory","tags":["New","Reported in Brown Brothers Harriman Interview","SA 2027, Cedar Street group, First round","Private Capital Advisory","Advanced"]},{"id":"q-2132","t":"sector","l":"Basic","s":90,"q":"What is shareholder activism?","k":["Shareholder activism is when an investor acquires a significant stake in a public company (typically 5-15%) and uses that ownership position to push for changes intended to increase shareholder value.","Common Activist Demands:","Operational improvements (cost-cutting, margin expansion)","Capital allocation changes (share buybacks, special dividends, divestitures)","Strategic alternatives (sale of the company, spin-offs, breakups)","Governance changes (board seats, executive compensation, management replacement)","Notable activist investors include Elliott Management, Carl Icahn, Starboard Value, and Third Point. Activists typically file a 13D with the SEC when they cross 5% ownership, signaling their intentions to the market."],"collection":"practice","topic":"Strategic Defense & Shareholder Advisory","tags":["New","Reported in Centerview Partners Interview","Generalist group, New York Office, Superday","Strategic Defense & Shareholder Advisory","Basic"]},{"id":"q-2133","t":"sector","l":"Basic","s":90,"q":"How would you ramp up on understanding a new industry or stock that you have no prior experience with?","k":["Structure your ramp in layers, moving from broad context to company-specific detail:","Step 1: Industry Overview (Day 1–2)","Read equity research initiation reports on the sector (Goldman, Morgan Stanley, or specialist brokers). These provide the competitive landscape, key drivers, and standard valuation frameworks.","Review trade publications and industry associations for secular trends, regulatory dynamics, and supply/demand structure.","Identify the 3–5 KPIs that matter most in this industry (e.g., same-store sales for retail, ARPU for telecom, reserve replacement ratio for E&P).","Step 2: Company Deep-Dive (Day 2–5)","Read the most recent 10-K front to back. Focus on the business description, risk factors, and MD&A sections. Build a mental model of how the company generates revenue and what drives margins.","Listen to the last 2–4 quarterly earnings calls. Pay attention to management tone, guidance changes, and analyst questions — these reveal what the market cares about.","Build a simple 3-statement model to understand the P&L structure, capital intensity, and cash conversion.","Step 3: Competitive and Variant View (Day 5–10)","Map the competitive landscape: who are the top 3–5 competitors, what is each company's positioning, and where are the margin differences?","Read sell-side and buy-side debates on the stock. Understand the bull case, the bear case, and what would have to change for each to play out.","Identify the 1–2 key variant perceptions that could drive outsized returns if the consensus is wrong."],"collection":"practice","topic":"Hedge Fund","tags":["New","Reported in Citadel Interview","SA 2027, Public Equities (L/S), Citadel Associate Program, New York Office","Hedge Fund","Basic"]},{"id":"q-2134","t":"sector","l":"Advanced","s":90,"q":"How do you think about earnings yield as a market-implied return using the Gordon Growth framework (E/P = r - g)? Specifically, when comparing stocks at 8x vs. 12x P/E, how do you determine whether the multiple reflects justified higher growth versus lower risk — and avoid falling into the trap of thinking in terms of what is \"optically cheap\" or \"expensive\"?","k":["The Gordon Growth Model implies P/E = 1 / (r - g), so inverting gives E/P = r - g, the market-implied real return above growth. This reframes multiples as the market's embedded assumptions about required return and long-term growth, not as a \"cheap vs. expensive\" label.","Decomposing the Two Stocks:","8x P/E → E/P = 12.5%. If you assume g = 3% (GDP-like growth), the market is pricing r = 15.5%. That high required return implies significant perceived risk (cyclicality, leverage, earnings volatility, or secular decline) rather than a bargain.","12x P/E → E/P = 8.3%. At the same g = 3%, the implied r = 11.3%. The lower required return reflects higher confidence in the durability and predictability of cash flows.","Distinguishing Growth vs. Risk:","Hold r constant: If both stocks have the same risk profile, a higher P/E implies the market is pricing in higher g. You need to underwrite whether that growth is realistic.","Hold g constant: If both stocks have similar growth, a lower P/E means a higher discount rate, signaling the market sees more risk. The \"cheap\" stock may be cheap for a reason.","In practice, both r and g differ simultaneously. The analytical discipline is to decompose the multiple into its risk and growth components rather than reacting to the headline number.","The trap is anchoring on the P/E level itself. An 8x stock is only a good investment if you believe the market is overestimating risk or underestimating growth — not simply because 8x is \"lower than\" 12x."],"collection":"practice","topic":"Hedge Fund","tags":["New","Reported in Citadel Interview","SA 2027, Public Equities (L/S), Citadel Associate Program, New York Office","Hedge Fund","Advanced"]},{"id":"q-2135","t":"sector","l":"Advanced","s":90,"q":"If I told you I am going to take all of your parents' money and invest it in one stock for 20 years, what stock would you choose? Do not pitch it — just name it and explain your reasoning.","k":["The key to this question is recognizing that the benchmark for a 20-year, single-stock, no-touch holding is not the equity market return of 7–8%. Instead, the bar is simply outpacing inflation (roughly 3%) with high certainty, because you are bearing full idiosyncratic risk with zero diversification and no ability to rebalance.","What to Optimize For:","Durability of the business model over a 20-year horizon. You need a company whose core product or service will still be essential two decades from now.","Pricing power: the ability to raise prices at or above inflation protects real purchasing power of the investment.","Low probability of permanent capital loss. This rules out high-leverage companies, single-product businesses, and anything subject to rapid technological disruption.","Strong governance and capital allocation track record — you are trusting management to compound value without your intervention for two decades.","Example Framework:","Name a specific company you genuinely believe in (e.g., Berkshire Hathaway, Costco, Visa, or a dominant platform business). Explain why its competitive moat, revenue diversification, and pricing power make permanent capital loss unlikely over a 20-year period. Avoid speculative names, recent IPOs, or high-growth companies with unproven unit economics."],"collection":"practice","topic":"Hedge Fund","tags":["New","Reported in Citadel Interview","SA 2027, Public Equities (L/S), Citadel Associate Program, New York Office","Hedge Fund","Advanced"]},{"id":"q-2136","t":"sector","l":"Advanced","s":90,"q":"What is the difference between a good company and a good stock? Beyond fundamentals, what else could make a fundamentally strong company a bad stock?","k":["A good company has strong fundamentals: durable competitive advantages, high returns on invested capital, capable management, and sustainable growth. A good stock is one that offers attractive risk-adjusted returns from the current price. These are not the same thing — a great company can be a terrible stock if the price already reflects all the good news and then some.","What Makes a Good Company a Bad Stock:","Valuation: If the stock trades at a P/E or EV/EBITDA multiple that already implies perfection, there is no margin of safety. The upside is capped while the downside from any earnings miss is severe.","Poor liquidity: Thin trading volumes mean wide bid-ask spreads, high market impact costs, and difficulty exiting the position. This matters especially for institutional portfolios.","Excessive retail speculation: Stocks with heavy retail flows or meme dynamics can trade detached from fundamentals. High short-term volatility driven by sentiment rather than earnings makes the position difficult to size and manage.","Capital structure issues: A strong operating business burdened with excessive leverage, upcoming maturities, or restrictive covenants can see its equity value impaired even if the core business performs well.","Poor capital allocation: A company that generates strong cash flow but deploys it into value-destroying acquisitions or excessive buybacks at peak valuations erodes shareholder value over time.","Governance or overhang risk: Dual-class share structures, insider selling, large secondary offerings, or regulatory headwinds can suppress the stock regardless of operating performance.","The bottom line: stock selection requires underwriting both the business quality and the price you pay, plus structural factors like liquidity and ownership dynamics that can decouple a stock's performance from the company's fundamentals."],"collection":"practice","topic":"Hedge Fund","tags":["New","Reported in Citadel Interview","SA 2027, Public Equities (L/S), Citadel Associate Program, New York Office","Hedge Fund","Advanced"]},{"id":"q-2137","t":"sector","l":"Advanced","s":90,"q":"What are the different ways to value a fitness-ring company (e.g., a consumer wearables business), and what are the pros and cons of each method?","k":["1. Comparable Company Analysis (Trading Comps)","Identify publicly traded peers in consumer electronics, wearable tech, or connected fitness (e.g., Apple wearables segment, Garmin, Peloton). Use EV/Revenue for high-growth or pre-profit companies; EV/EBITDA or P/E if profitable.","Pros: Market-based, easy to update, reflects current investor sentiment.","Cons: Few pure-play comps exist — most peers are diversified (Apple) or in adjacent categories (Peloton). Multiple selection is subjective. Does not capture unit economics or subscription economics unique to the fitness-ring model.","2. Precedent Transactions","Look at M&A deals in consumer tech, wearables, and connected fitness. Note control premiums and strategic premiums paid by acquirers seeking the customer base or technology.","Pros: Captures strategic value and control premiums.","Cons: Deal activity in this niche is sparse. Transactions may reflect synergies or strategic motivations that do not apply to a standalone valuation. Data may be stale if the last comparable deal was years ago.","3. DCF (Discounted Cash Flow)","Project hardware unit sales, average selling price, attach rate for subscription/membership revenue, and churn rates. Model COGS, R&D, and marketing spend. Discount FCFs at WACC and add terminal value.","Pros: Captures the full economics including hardware margins vs. recurring subscription revenue. Allows you to model growth scenarios explicitly.","Cons: Highly sensitive to assumptions on TAM penetration, churn, and long-term margin trajectory. Consumer hardware is notoriously difficult to forecast beyond 2–3 years due to product cycle risk and competitive dynamics.","4. Sum-of-the-Parts / Subscription Value","Value the hardware business separately (on a unit economics or EV/Revenue basis) and the recurring subscription base on a per-subscriber LTV/CAC framework or as a SaaS-like recurring revenue stream.","Pros: Captures the different margin profiles and growth characteristics of hardware vs. software. Useful if the market undervalues the subscription component.","Cons: Requires granular data on subscriber metrics that may not be publicly available. Interaction effects between hardware and subscription (e.g., hardware sold at a loss to drive subscriptions) make clean separation difficult."],"collection":"practice","topic":"Hedge Fund","tags":["New","Reported in Citadel Interview","SA 2027, Public Equities (L/S), Citadel Associate Program, New York Office","Hedge Fund","Advanced"]},{"id":"q-2138","t":"sector","l":"Advanced","s":90,"q":"If you have a company that you think is a home-run long, would you rather have a high short interest or a low short interest? Why?","k":["You would rather have a high short interest, for several reasons:","Short squeeze potential: If the thesis plays out and the stock rises, short sellers are forced to cover by buying shares. This forced buying creates additional upward pressure beyond the fundamental re-rating, amplifying your returns.","Contrarian signal: High short interest means the consensus is negative. If you have conviction in a differentiated view that proves correct, the upside is larger because you are starting from a more skeptical base of expectations.","Catalyst asymmetry: Any positive surprise (earnings beat, new product, favorable regulation) has an outsized impact because it forces both a fundamental re-rating and mechanical short covering simultaneously.","Caveats to Acknowledge:","High short interest is not inherently bullish — the shorts may be right. You need to have done the fundamental work to understand why you disagree with the bearish consensus.","Very high short interest can signal structural problems (fraud risk, broken balance sheet) that are difficult to diligence from public filings alone.","Borrowing costs and availability: In a crowded short, the stock may be hard to borrow, which can create volatility that works in your favor as a long but also makes the position harder to manage."],"collection":"practice","topic":"Hedge Fund","tags":["New","Reported in Citadel Interview","SA 2027, Public Equities (L/S), Citadel Associate Program, New York Office","Hedge Fund","Advanced"]},{"id":"q-2139","t":"sector","l":"Advanced","s":90,"q":"If I gave you $10 million of capital today, what 3 stocks would you allocate that capital to? Explain your sizing and reasoning.","k":["This is a portfolio construction and stock-pitching question. The interviewer is evaluating your ability to articulate investment theses, think about position sizing, and demonstrate awareness of risk management. Structure your answer as follows:","Framework:","Name 3 specific stocks you have genuine conviction in. Avoid generic mega-cap names unless you have a differentiated thesis. Each pick should have a clear catalyst or variant perception.","Size the positions based on conviction and risk. A common approach is to allocate more to your highest-conviction, lowest-risk idea and less to the more speculative or volatile positions (e.g., 40% / 35% / 25% or 50% / 30% / 20%).","For each stock, briefly cover: (1) what the company does, (2) the investment thesis in 2–3 sentences, (3) the key catalyst or inflection point, and (4) the primary risk.","What the Interviewer Is Looking For:","Intellectual curiosity and genuine market engagement — not textbook answers.","Awareness of risk: you should acknowledge what could go wrong with each pick, not just pitch the upside.","Portfolio-level thinking: Do the 3 stocks have correlated risk factors? A strong answer diversifies across sectors, market caps, or catalysts rather than putting all capital into the same macro bet.","Sizing rationale: Explain why you weighted the positions the way you did. This demonstrates discipline beyond just \"I like this stock.\"","Prepare 3 pitches in advance with specific data points (current valuation, recent earnings, upcoming catalysts). The quality of your preparation is itself a signal to the interviewer."],"collection":"practice","topic":"Hedge Fund","tags":["New","Reported in Citadel Interview","SA 2027, Public Equities (L/S), Citadel Associate Program, New York Office","Hedge Fund","Advanced"]},{"id":"q-2140","t":"sector","l":"Basic","s":90,"q":"Do you prefer equity or debt as an investment, and why?","k":["This is an opinion question. A strong answer picks a side and defends it:","Equity:","Higher upside potential through capital appreciation and dividends.","Ownership stake with voting rights and influence.","Benefits from EBITDA growth and multiple expansion.","Best when you have a strong conviction in the business's long-term growth.","Debt:","Priority claim on assets in bankruptcy.","Predictable, contractual cash flows (coupon payments).","Lower risk with defined downside.","Better in uncertain environments when capital preservation is key.","In a real estate context (given TPG REPE), debt may be preferred for stable, cash-flowing assets, while equity is preferred for value-add or development opportunities with upside."],"collection":"practice","topic":"Real Estate Private Equity (REPE)","tags":["New","Reported in TPG Interview","SA 2027","Real Estate Private Equity (REPE)","Basic"]},{"id":"q-2141","t":"sector","l":"Advanced","s":90,"q":"Which would have a higher yield: a multifamily property or a senior housing property?","k":["A senior housing property would have a higher yield (cap rate).","Senior housing is operationally intensive: requires specialized management, healthcare staffing, and regulatory compliance, increasing operating risk.","Higher vacancy and turnover risk due to the resident population's health needs.","Regulatory risk: Subject to healthcare regulations, licensing requirements, and potential changes in Medicare/Medicaid reimbursement.","Multifamily is considered a core, lower-risk property type with stable demand, lower operational complexity, and more predictable cash flows. Therefore it commands a lower yield (higher price relative to income).","Typical cap rates: Multifamily 4-6%, Senior Housing 6-9%, reflecting the risk differential."],"collection":"practice","topic":"Real Estate Private Equity (REPE)","tags":["New","Reported in TPG Interview","SA 2027","Real Estate Private Equity (REPE)","Advanced"]},{"id":"q-2142","t":"sector","l":"Advanced","s":90,"q":"Part 1: How do you get from Net Operating Income (NOI) to cash flows for a real estate property?\n\n\n\n\nPart 2: Suppose you have one property with low NOI and low margins, and another property with high NOI and high margins. If you increase revenue by 10% at both, which is more interesting from an investment perspective, and why?","k":["Part 1: NOI to Cash Flows","Net Operating Income (NOI) = Revenue (Rental Income + Other Income) - Operating Expenses (property taxes, insurance, maintenance, management fees)","Less: Capital Expenditures (tenant improvements, building improvements)","Less: Leasing Commissions","Less: Debt Service (interest + principal repayment)","= Levered Cash Flow (Cash Flow to Equity)","For unlevered cash flow, exclude debt service. NOI itself is an unlevered, pre-CapEx measure analogous to EBITDA in corporate finance.","Part 2: Low-Margin vs. High-Margin Property","The low-NOI, low-margin property is more interesting from an investment perspective.","A 10% revenue increase at the low-margin property creates a larger percentage increase in NOI because operating expenses are relatively fixed.","Example: If Property A has $100 revenue, $90 expenses, and $10 NOI (10% margin), a 10% revenue increase adds $10 revenue. With largely fixed costs, most flows to NOI, potentially doubling it to ~$20 (100% NOI increase).","Property B with $100 revenue, $30 expenses, and $70 NOI (70% margin) adds $10 revenue, increasing NOI to ~$80 (only ~14% NOI increase).","This is operating leverage — low-margin properties have higher sensitivity to revenue changes, creating more upside (and more downside risk)."],"collection":"practice","topic":"Real Estate Private Equity (REPE)","tags":["New","Reported in TPG Interview","SA 2027","Real Estate Private Equity (REPE)","Advanced"]},{"id":"q-2143","t":"sector","l":"Advanced","s":90,"q":"What are cap rates currently at for senior housing? How have they changed compared to a couple of months ago, and how is a property's valuation affected by increasing debt in the capital structure?","k":["Structure your response with current market data and the conceptual framework:","Current Cap Rates:","Look up current senior housing cap rates before your interview. In general, cap rates vary by asset quality, location, and operator — Class A properties in strong markets trade at the low end of the range, while older facilities in secondary markets trade at the high end. Know whether cap rates are expanding, compressing, or stabilizing, and be prepared to explain why (interest rate environment, transaction volume, capital flows).","Impact of Increasing Debt:","Adding debt to the capital structure does not directly change the property's cap rate or unlevered valuation (Property Value = NOI / Cap Rate). However, higher leverage increases financial risk, which may cause lenders and equity investors to demand higher returns. If the cap rate increases as a result of perceived risk, the property value declines. Additionally, higher interest costs reduce cash-on-cash returns to equity and increase the risk of default. From an equity return perspective, leverage amplifies returns on the upside but amplifies losses on the downside."],"collection":"practice","topic":"Real Estate Private Equity (REPE)","tags":["New","Reported in TPG Interview","SA 2027","Real Estate Private Equity (REPE)","Advanced"]},{"id":"q-2144","t":"beh","l":"Behavioral","s":90,"q":"Walk me through your background and how it led you to finance.","k":["Started with an interest or event that sparked finance curiosity","Connected academic and work experiences to that interest","Conclude by emphasizing why you see IB as the natural next step"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2145","t":"beh","l":"Behavioral","s":90,"q":"Why did you choose your university (or MBA program) and major?","k":["Highlight the school’s reputation for academic excellence","Mention relevant finance or business clubs and networks","Explain how the major aligned with career goals"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2146","t":"beh","l":"Behavioral","s":90,"q":"Why investment banking over other finance roles (like S&T or Asset Management)?","k":["Stress deal exposure and end-to-end transaction experience","Highlight client-centric, strategic nature of IB","Emphasize desire for rigorous modeling and valuation skills"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2147","t":"beh","l":"Behavioral","s":90,"q":"What do you find most appealing about our firm in particular?","k":["Mention conversations with current bankers and culture insights","Point out unique deals or notable industry expertise","Show how these strengths align with your career goals"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2148","t":"beh","l":"Behavioral","s":90,"q":"What industry focus or product group interests you most, and why?","k":["Reference recent market trends that fascinate you","Mention a high-profile transaction that piqued your interest","Connect the group’s specialty to your strengths and passions"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2149","t":"beh","l":"Behavioral","s":90,"q":"How does your past experience prepare you for the demands of banking?","k":["Highlight experiences with high-volume or high-pressure workloads","Stress time management and attention to detail from those roles","Explain how these skills seamlessly transfer to IB tasks"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2150","t":"beh","l":"Behavioral","s":90,"q":"Have you spoken with people at other banks? Where are you in the process?","k":["Admit you’ve explored options to stay informed","Emphasize that this bank stands out due to culture or deals","Highlight your genuine enthusiasm for this opportunity"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2151","t":"beh","l":"Behavioral","s":90,"q":"How would your friends describe you in one sentence?","k":["Pick a short descriptor like “hard-working and reliable”","Back it up with a quick example or anecdote","Ensure it aligns with qualities valued in IB"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2152","t":"beh","l":"Behavioral","s":90,"q":"Which of your previous experiences did you enjoy the most and why?","k":["Discuss a project where you thrived under pressure","Point to a measurable result and your personal impact","Relate how it parallels key IB deliverables"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2153","t":"beh","l":"Behavioral","s":90,"q":"What’s one surprising thing about you not on your resume?","k":["Offer a brief story or fun fact that highlights curiosity or drive","Ensure it's unique but not controversial","Tie it back to showing a well-rounded character"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2154","t":"beh","l":"Behavioral","s":90,"q":"Why did you leave (or why are you leaving) your current firm?","k":["Emphasize desire for larger or more complex transactions","Highlight need for faster learning or deeper deal exposure","Avoid negative statements about your previous company"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2155","t":"beh","l":"Behavioral","s":90,"q":"Why did you choose to work in [previous internship role]?","k":["Explain how that role honed skills you can use in IB","Mention your learning mindset at that stage","Show progression from that role to banking goals"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2156","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a defining moment in your life that set you on this path.","k":["Set the scene: what sparked your “aha” moment?","Explain how it shaped your decision toward finance","Conclude with how it drives your motivation now"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2157","t":"beh","l":"Behavioral","s":90,"q":"What do you hope to learn in your first year as an Analyst/Associate?","k":["Master technical fundamentals like DCF/M&A models","Gain real client-facing experience on transactions","Hone attention to detail and deal execution skills"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2158","t":"beh","l":"Behavioral","s":90,"q":"Describe an extracurricular or side project that influenced your career decision.","k":["Set the context: what project, and what was your role?","Show how it demanded collaboration or financial thinking","Explain how it confirmed your IB aspirations"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2159","t":"beh","l":"Behavioral","s":90,"q":"How do you think your unique background adds value to our team?","k":["Note a unique skill or perspective from your past","Connect it to how it benefits the group’s workflow","Emphasize complementing existing team capabilities"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2160","t":"beh","l":"Behavioral","s":90,"q":"If you couldn’t do banking, what else would you pursue?","k":["Possibly mention corporate finance or strategy roles","Reiterate that IB is your first choice","Keep it credible and still connected to finance"],"collection":"practice","topic":"Background & Fit","tags":["Background & Fit"]},{"id":"q-2161","t":"beh","l":"Behavioral","s":90,"q":"Where do you see yourself in 5 years?","k":["Express desire to advance within IB","Highlight potential leadership or specialization track","Keep the timeframe and goals realistic"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2162","t":"beh","l":"Behavioral","s":90,"q":"Why do you want to stay in banking long term? (For Associates or MBAs)","k":["Cite fascination with transaction work and strategy","Discuss building long-term client trust","Highlight your plan to become a senior dealmaker"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2163","t":"beh","l":"Behavioral","s":90,"q":"If offered a role in private equity or hedge funds in a year, would you leave?","k":["Acknowledge the temptation but reaffirm IB’s appeal","Emphasize variety and pace of deals in banking","Stress loyalty to the skill-building plan you set"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2164","t":"beh","l":"Behavioral","s":90,"q":"You’re overqualified for an Analyst/Associate role. Why take a step back?","k":["Clarify how you value foundational IB experience","Highlight your humility and readiness to absorb new skills","Stress the deal-centric path you want, not just title progression"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2165","t":"beh","l":"Behavioral","s":90,"q":"What’s your short-term goal after you finish this program (or within your first year)?","k":["Focus on becoming proficient in technical areas","Emphasize exposure to live deals","Mention developing professional relationships in the firm"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2166","t":"beh","l":"Behavioral","s":90,"q":"If you land this offer, will you be ready to accept on the spot?","k":["Express sincere excitement for the role","State you’ve done your homework and are prepared","Reconfirm commitment if it’s truly your top choice"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2167","t":"beh","l":"Behavioral","s":90,"q":"Suppose your plan for banking doesn’t work out. What’s next?","k":["Mention corporate finance, Big 4 advisory, or related fields","Reinforce that IB is your priority, but you’re realistic","Show passion remains in financial analysis or transactions"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2168","t":"beh","l":"Behavioral","s":90,"q":"How do you plan to grow once you’re done with the Analyst/Associate program?","k":["Envision a path to VP or specialized coverage group","Discuss refining leadership, winning your own clients","Mention desire to mentor incoming analysts"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2169","t":"beh","l":"Behavioral","s":90,"q":"Are you interviewing elsewhere? What makes this offer stand out for you?","k":["Acknowledge you’re exploring all good-fit options","Emphasize a unique aspect of their deals or culture","Reiterate top-choice position if you genuinely feel that way"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2170","t":"beh","l":"Behavioral","s":90,"q":"Would you consider an international assignment if it advanced your career?","k":["Show readiness to relocate for the right opportunity","Mention prior international exposure if applicable","Convey excitement to gain cross-border deal experience"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2171","t":"beh","l":"Behavioral","s":90,"q":"Which area of banking do you hope to specialize in over time?","k":["Name the specific sector or product (M&A, healthcare, etc.)","Explain personal interest or background reason","Highlight growth potential and skill synergy"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2172","t":"beh","l":"Behavioral","s":90,"q":"How does this role fit into your long-term personal goals?","k":["Link the position to your eventual leadership or entrepreneurial dreams","Emphasize the transaction experience and networking it offers","Show alignment between the firm’s trajectory and your career path"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2173","t":"beh","l":"Behavioral","s":90,"q":"Have you ever pivoted your career goals significantly? Why the change?","k":["Admit an earlier interest in a different field","Explain new experiences that altered your path","Emphasize lessons learned and present clarity of purpose"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2174","t":"beh","l":"Behavioral","s":90,"q":"What do you hope to accomplish by the time you’d be promoted to VP?","k":["Discuss solidifying modeling and deal execution capabilities","Highlight building a reputation for reliability and client rapport","Express desire to mentor analysts and associates"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2175","t":"beh","l":"Behavioral","s":90,"q":"10 years from now, do you see yourself more on the investing or advisory side?","k":["Express current preference for advisory or synergy with your skillset","Note that you see value in possibly transitioning if it aligns with your growth","Reassure them you’re focused on excelling in IB now"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2176","t":"beh","l":"Behavioral","s":90,"q":"Imagine you retire at 40 with enough money. What would you do next?","k":["Show you’d still be active, perhaps starting a philanthropic fund or mentoring","Mention staying engaged with finance in some capacity","Highlight ongoing passion for growth and helping others"],"collection":"practice","topic":"Career Vision & Future","tags":["Career Vision & Future"]},{"id":"q-2177","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you dealt with a conflict on your team.","k":["Context: the nature of the conflict","Process: your steps to mediate and clarify misunderstandings","Outcome: unity restored or improved collaboration"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2178","t":"beh","l":"Behavioral","s":90,"q":"Describe an instance where you had to give tough feedback to a peer.","k":["Emphasize respect and empathy when delivering the feedback","Point to the specific behavior or issue","Highlight the peer’s positive response and improved performance"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2179","t":"beh","l":"Behavioral","s":90,"q":"Have you ever disagreed with your manager’s approach? What did you do?","k":["Explain your rationale in a calm, data-driven manner","Listen to your manager’s reasoning too","Accept final decision while ensuring your concerns were heard"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2180","t":"beh","l":"Behavioral","s":90,"q":"When have you dealt with a co-worker who challenged your authority or expertise?","k":["Faced their doubts head-on, inviting them to discuss concerns","Used data or examples to clarify your position","Adopted a collaborative stance to find common ground"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2181","t":"beh","l":"Behavioral","s":90,"q":"Tell me about your biggest setback or failure at work.","k":["Describe the failure clearly—no excuses","Explain how you rectified the impact","Mention lessons learned for future prevention"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2182","t":"beh","l":"Behavioral","s":90,"q":"How do you handle a situation where you’re clearly in the wrong?","k":["Admit error promptly and genuinely","Offer a plan to fix the issue if possible","Reflect on how to avoid repeating it"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2183","t":"beh","l":"Behavioral","s":90,"q":"Describe a time you had to deliver bad news to your boss or client.","k":["Explain the context of the bad news (delay, budget overrun, etc.)","Communicated it factually and promptly","Offered at least one remedial plan or solution"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2184","t":"beh","l":"Behavioral","s":90,"q":"Give an example of a time you persuaded someone who strongly opposed your idea.","k":["Identified their core objections or concerns","Used data or examples to address those points","Found a compromise or middle ground to gain buy-in"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2185","t":"beh","l":"Behavioral","s":90,"q":"Have you ever been on a project that seemed impossible to complete?","k":["Illustrate the daunting scope or time constraint","Show how you reorganized tasks or got extra help","Resulted in at least partial success or a key lesson"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2186","t":"beh","l":"Behavioral","s":90,"q":"Talk about a time you worked with someone difficult. How did you cope?","k":["Address the difficult behavior calmly and early","Clarify roles and expectations to reduce friction","Kept overall team morale high by focusing on shared objectives"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2187","t":"beh","l":"Behavioral","s":90,"q":"How do you handle criticism in front of others?","k":["Stay calm and thank them for the perspective","Acknowledge if valid; clarify if misunderstandings exist","Discuss deeper details privately afterward"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2188","t":"beh","l":"Behavioral","s":90,"q":"Have you ever broken a commitment? What happened and what did you learn?","k":["Briefly explain the scenario and your initial promise","Why it was broken and how you took responsibility","Lesson learned on better planning or communication"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2189","t":"beh","l":"Behavioral","s":90,"q":"Describe a tough ethical decision you had to make.","k":["Set the stage: conflicting ethical vs. practical interests","Explain your decision path, referencing core principles","Discuss how you dealt with the outcome or fallout"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2190","t":"beh","l":"Behavioral","s":90,"q":"What’s the toughest piece of feedback you’ve ever received? How did you respond?","k":["Share the blunt or surprising feedback","Describe your immediate reaction and acceptance","Demonstrate a concrete step you took to change"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2191","t":"beh","l":"Behavioral","s":90,"q":"If a client or superior yelled at you unfairly, how would you handle it?","k":["Stay composed and avoid escalating","Clarify the underlying concern or misunderstanding","Follow up with a private, calm conversation if needed"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2192","t":"beh","l":"Behavioral","s":90,"q":"When have you felt overwhelmed, and how did you regain control of the situation?","k":["Admit feeling swamped and why","Strategize: reorder tasks, set deadlines, or delegate","Emphasize eventual successful delivery or lesson learned"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2193","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a crisis moment. How did you react under pressure?","k":["Outline the sudden crisis (system failure, urgent request)","Describe immediate steps to contain the impact","Share the outcome and how you prevented future repeats"],"collection":"practice","topic":"Conflict & Difficult Situations","tags":["Conflict & Difficult Situations"]},{"id":"q-2194","t":"beh","l":"Behavioral","s":90,"q":"What does our firm do?","k":["Mention the firm’s primary business lines (e.g., M&A, equity, debt, restructuring, etc.)","Highlight any notable industry verticals or niche areas they’re known for","Show awareness of the firm’s recent deals, rankings, or unique culture/approach"],"collection":"practice","topic":"General Banking Knowledge","tags":["General Banking Knowledge"]},{"id":"q-2195","t":"beh","l":"Behavioral","s":90,"q":"What typically goes in an investment banking pitch deck?","k":["Executive summary: outlines key points and potential transaction thesis","Company overview: historical performance, business model, and strategic highlights","Market and industry analysis: competition, trends, and growth opportunities","Valuation and financial analysis: comps, precedent transactions, DCF, synergy estimates","Transaction structure or recommendations: deal timeline, potential benefits, risks"],"collection":"practice","topic":"General Banking Knowledge","tags":["General Banking Knowledge"]},{"id":"q-2196","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a deal that you have followed recently.","k":["Start by identifying the target, acquirer, or transaction parties, plus basic transaction type (M&A, IPO, etc.)","Provide high-level financials: deal size, multiples, key valuation metrics","Discuss strategic rationale: synergy opportunities, market expansion goals","Offer your opinion on why it makes sense (or doesn’t), potential integration risks, or industry impact"],"collection":"practice","topic":"General Banking Knowledge","tags":["General Banking Knowledge"]},{"id":"q-2197","t":"beh","l":"Behavioral","s":90,"q":"Why do you want to work in the middle market?\n\n\n\n\nFollow-up 1: What qualities do you have that will make you successful in this job?","k":["Primary Question:","Highlight the unique advantages of the middle market: greater responsibility at the junior level, direct exposure to senior bankers and clients, and the opportunity to work on a wide variety of deals from start to finish.","Express interest in working with growing, dynamic companies that form the backbone of the economy.","Follow-up Question:","List 3-4 key qualities essential for an investment banking analyst.","Include a mix of technical ability (quantitative skills), work ethic (resilience, attention to detail), and soft skills (communication, teamwork, coachability).","Briefly provide an example from your experience for each quality you mention."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Baird Interview\nChicago office, First round"]},{"id":"q-2198","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you worked on a team.","k":["Situation: Briefly describe the team, its purpose, and the project or goal.","Task: Outline your specific role and responsibilities within the team.","Action: Detail specific actions you took to contribute to the team's success (e.g., collaborated, communicated, resolved conflict, supported others).","Result: Explain the positive outcome achieved by the team and any lessons you learned about teamwork."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview"]},{"id":"q-2199","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you had to disagree with someone.","k":["Situation: Describe the context of the disagreement and the parties involved.","Task: Explain the issue at hand and your objective.","Action: Detail how you handled the disagreement professionally (e.g., listened actively, presented your perspective calmly with evidence, sought common ground, or proposed a compromise).","Result: Explain the resolution of the disagreement and what you learned about navigating differences of opinion constructively."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview"]},{"id":"q-2200","t":"beh","l":"Behavioral","s":90,"q":"Name a time you improved a process.","k":["Situation: Describe an existing process that was inefficient or problematic.","Task: Explain your goal to improve it and the problem you aimed to solve.","Action: Detail the steps you took to analyze the process, propose changes, and implement the improvements (e.g., researched, designed a new system, educated others).","Result: Quantify the positive impact of your improvement (e.g., saved time, reduced errors, increased efficiency) and what you learned."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview"]},{"id":"q-2201","t":"beh","l":"Behavioral","s":90,"q":"What do investment bankers ACTUALLY do on a day to day?","k":["Analysts/Associates primarily support senior bankers on transactions.","Key tasks include: building and updating financial models (e.g., DCF, LBO), performing valuation analyses (comparable companies, precedent transactions).","They also conduct extensive industry and company research, and prepare client presentations (pitch books, confidential information memoranda).","Work involves significant attention to detail, long hours, and tight deadlines, often in a team-based environment."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview"]},{"id":"q-2202","t":"beh","l":"Behavioral","s":90,"q":"Name a time you had to take responsibility for something.","k":["Situation: Describe a scenario where an error occurred, a project went off track, or a negative outcome happened.","Action: Explain how you proactively acknowledged your role or responsibility, even if it was partial, and did not deflect blame.","Result: Detail the steps you took to rectify the situation, mitigate negative impacts, and learn from the experience to prevent recurrence.","Emphasize accountability and a solution-oriented mindset."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview"]},{"id":"q-2203","t":"beh","l":"Behavioral","s":90,"q":"Walk me through your resume, and for each transition, explain the rationale behind the change.","k":["Begin with a brief overview of your background, starting from your university and major.","Proceed chronologically through your experiences, briefly describing your role and key responsibilities at each position.","For each transition (e.g., from one internship to another, or from an academic pursuit to a professional one), clearly articulate the \"why.\" Explain what skills you aimed to gain, what you learned, and how that experience logically led you to the next step.","Conclude by connecting your cumulative experience to why you are now pursuing investment banking at this specific firm, framing it as the deliberate and ideal next step in your career path."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nNew York Office"]},{"id":"q-2204","t":"beh","l":"Behavioral","s":90,"q":"What do you think is the role of an Investment Banking Associate?","k":["The Associate acts as the bridge between junior and senior bankers.","Manages Analysts: They oversee the day-to-day work of analysts, ensure the quality and accuracy of financial models and presentations, and help manage team workflow.","Takes Ownership: They take primary responsibility for creating client materials and analyses, moving beyond pure execution to think more strategically about the content.","Client Interaction: They begin to have more direct client contact, supporting VPs and MDs in meetings and communications."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nNew York office, First round"]},{"id":"q-2205","t":"beh","l":"Behavioral","s":90,"q":"Imagine that all investment banks have cancelled their summer internship programs this year. What would you do over the summer instead?","k":["Propose a productive alternative that demonstrates initiative and a commitment to developing relevant skills.","Option 1: Pursue a finance-related project, like managing a personal portfolio with a detailed investment thesis or creating a valuation project on a public company.","Option 2: Seek experience in a related field such as corporate development, venture capital, or a finance role at a startup.","Option 3: Obtain a relevant certification or take online courses to deepen technical knowledge (e.g., financial modeling, data analysis)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nNew York Office, First round"]},{"id":"q-2206","t":"beh","l":"Behavioral","s":90,"q":"On a scale with hard skills on one end and soft skills on the other, where would you place yourself and why?","k":["Position yourself as balanced, but leaning slightly towards one side that you can strongly support with evidence.","Acknowledge the critical importance of both in investment banking.","Provide a brief, concrete example of you successfully applying a hard skill (e.g., a complex analysis or model you built).","Provide a brief, concrete example of you successfully applying a soft skill (e.g., persuading a team or resolving a conflict)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nNew York Office, First round"]},{"id":"q-2207","t":"beh","l":"Behavioral","s":90,"q":"Are you proficient in Excel? What's your favorite function and why?","k":["Confidently state that you are proficient in Excel.","Choose a function that is more advanced than basic SUM or VLOOKUP. Good choices include INDEX/MATCH, XLOOKUP, or SUMIFS.","Briefly explain what the function does (e.g., \"I prefer INDEX MATCH because it's more flexible and less error-prone than VLOOKUP for dynamic lookups\").","Provide a quick, practical example of how you've used it to solve a problem or increase efficiency."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nSuperday"]},{"id":"q-2208","t":"beh","l":"Behavioral","s":90,"q":"What have you been doing to bridge the gap between your past experience and investment banking?","k":["Mention specific, proactive self-study in core technical areas like accounting, valuation, and financial modeling, citing any courses or guides used.","Discuss your networking efforts, referencing informational interviews where you learned about the day-to-day role and culture of banking.","Highlight how you actively follow the markets and stay informed on relevant industry trends, connecting it to the group you're interviewing with.","Articulate how you have translated your existing skills (e.g., analytical thinking, work ethic, quantitative abilities) from your past experience to what is required of an analyst."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nConsumer and Retail Group, Superday"]},{"id":"q-2209","t":"beh","l":"Behavioral","s":90,"q":"What do you think is the best way to get the best work from your team?","k":["Set Clear Goals: Ensure every team member understands the objective, their individual role, and what success looks like from the start.","Lead by Example: Demonstrate the work ethic, attention to detail, and positive attitude you expect from others.","Empower and Trust: Delegate responsibilities to foster growth and ownership, providing support and guidance rather than micromanaging.","Foster Open Communication: Create an environment where asking questions, providing feedback, and raising concerns is encouraged."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nLevFin group, First round"]},{"id":"q-2210","t":"beh","l":"Behavioral","s":90,"q":"What's the most complex subject you are good at?","k":["Name the Subject: Choose a specific, complex academic or technical subject.","Explain the Complexity: Briefly describe what makes the subject challenging (e.g., abstract concepts, multi-variable problems, intricate logic).","Demonstrate Your Mastery: Provide a concise example of how you applied your knowledge to solve a difficult problem or achieve a goal.","Connect to Banking: Subtly link the skills needed to master that subject—such as pattern recognition, analytical depth, and persistence—to the skills required in finance."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nC&R group, First round"]},{"id":"q-2211","t":"beh","l":"Behavioral","s":90,"q":"You are an associate on a team. An analyst is leaving the firm and is not contributing to the team's work. How do you approach this situation?","k":["Address Directly and Privately: Have a one-on-one conversation to understand their perspective. Approach with empathy rather than accusation.","Realign on Professional Responsibility: Gently remind them of their commitments to the team and ongoing projects until their departure. Frame it around finishing strong and maintaining their reputation.","Focus on Project Continuity: If they remain disengaged, focus on reallocating their critical tasks among the team to ensure deadlines are met.","Escalate if Necessary: If their lack of contribution jeopardizes a critical deliverable, you have an obligation to inform your manager about the risk to the project, focusing on the work, not the person."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nPower & Utilities group, First round"]},{"id":"q-2212","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you had to make a decision with limited information.","k":["Situation: Describe a scenario that required an important decision but lacked complete data.","Task: Explain the decision that needed to be made and the potential consequences.","Action: Detail your logical process. This should include gathering all available facts, identifying and documenting key assumptions, consulting with others if possible, and weighing the potential outcomes.","Result: State the outcome of your decision and what you learned about making judgments under uncertainty."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nREGL group, First round"]},{"id":"q-2213","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you had to bring a significant issue to a manager's attention.","k":["Prepare Beforehand: Before approaching your manager, gather all the relevant facts, assess the potential impact, and think through 1-2 potential solutions.","Be Solution-Oriented: When you raise the issue, present both the problem and your proposed solutions or next steps. This shows initiative and respects their time.","Communicate Clearly: State the issue, its impact, and your recommendations calmly and concisely.","Focus on the Goal: Frame the conversation around the best interests of the project or the team."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nREGL group, First round"]},{"id":"q-2214","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you had to convince someone to see your point of view.","k":["Situation: Describe a scenario where you and a colleague or teammate had differing opinions on a project or decision.","Task: Explain the goal and why you believed your approach was the better option.","Action: Detail how you first listened to understand their perspective. Then, explain how you used data, research, or logical reasoning to respectfully make your case.","Result: Describe the outcome—whether you fully convinced them, reached a compromise, or agreed on a different path forward. Emphasize the collaborative nature of the resolution."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nM&A group, First round"]},{"id":"q-2215","t":"beh","l":"Behavioral","s":90,"q":"If you had $1 million, what would you do with it?\n\n\n\n\nFollow-up: If you had $1 million to invest for a client, where would you put it?","k":["Personal Investment:","Show a responsible approach: Pay off any high-interest debt, establish an emergency fund.","Outline a diversified, long-term strategy: Mention a mix of low-cost index funds/ETFs based on your personal risk tolerance and time horizon.","Client Investment:","Start by Asking Questions: State that your first step is always to understand the client's profile: risk tolerance, time horizon, liquidity needs, and financial goals.","Propose a Hypothetical Allocation: Based on a sample client profile (e.g., \"a moderate-risk client with a long-term goal\"), suggest a diversified portfolio across asset classes (e.g., equities, fixed income, alternatives) and briefly justify the strategy."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nC&R group, First round"]},{"id":"q-2216","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you let someone down.","k":["Situation: Choose a genuine professional or academic example where you failed to meet an expectation or made a mistake.","Action: Take clear ownership and explain what happened without making excuses or blaming others.","Resolution: Describe the immediate steps you took to apologize, correct the mistake, and mitigate any negative impact.","Learning: Most importantly, explain what you learned from the experience and how it changed your approach to ensure it would not happen again."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nPower & Utilities group, First round"]},{"id":"q-2217","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you didn't get along with a coworker.","k":["Situation: Briefly describe the project and your role relative to the coworker.","Task: Explain the source of the disagreement or friction (e.g., different work styles, conflicting ideas on the project).","Action: Detail the professional steps you took to resolve the issue. Focus on listening to their perspective, finding common ground, and prioritizing the team's goal over being right.","Result: Describe how you were able to move forward productively, the outcome of the project, and what you learned about managing professional disagreements."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Bank of America Interview\nFIG group, First round"]},{"id":"q-2218","t":"beh","l":"Behavioral","s":90,"q":"What was the most unique project you have worked on?","k":["Select a project that is genuinely distinctive and showcases skills transferable to banking, such as analytical thinking, creative problem-solving, or working under ambiguity.","Use the STAR method. Describe the Situation and what made the project unique: an unusual problem, a novel approach, or a challenging constraint.","Detail the specific Actions you took and the skills you applied. Highlight any initiative or creativity that went beyond standard expectations.","Explain the Result and its impact, then connect what you learned to how it prepares you for the dynamic, problem-solving nature of investment banking."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Bank of America Interview\nSA 2026, New York Office, Superday"]},{"id":"q-2219","t":"beh","l":"Behavioral","s":90,"q":"What will you do when you have a different opinion on the direction of a deal you are working on?","k":["Emphasize that as a junior banker, your role is to support the deal team while contributing thoughtful analysis. Having a different opinion is valuable — but how you express it matters.","First, ensure your viewpoint is well-supported: gather the data, run the analysis, and build a clear, fact-based case before raising your concern.","Raise it privately and respectfully with your immediate supervisor (VP or senior associate). Frame it as a question or observation rather than a challenge: \"I noticed X in the numbers — could you help me understand the thinking behind Y approach?\"","Ultimately, defer to the judgment of senior bankers who have broader context on the client relationship and deal dynamics. Even if your view is not adopted, the act of raising it thoughtfully demonstrates initiative and analytical rigor."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Bank of America Interview\nSA 2025, First round"]},{"id":"q-2220","t":"beh","l":"Behavioral","s":90,"q":"On a scale of 1 being intelligent and 10 being hard working, where do you belong?","k":["This is a test of self-awareness and humility. Avoid the extremes — do not claim to be purely a genius (1) or purely a grinder (10).","Choose a number in the 6-8 range and explain your reasoning. A strong answer might be: \"I would put myself around a 7. I believe I am analytically sharp, but what truly differentiates me is my willingness to outwork the competition. In banking, the smartest person in the room is not always the most successful — it is the person who combines strong analytical ability with relentless effort and attention to detail.\"","Emphasize that in banking, both qualities are essential — intelligence helps you work efficiently and solve problems creatively, while hard work ensures you deliver consistently excellent results under demanding conditions.","Whichever number you choose, back it with a brief example that demonstrates the trait you are emphasizing."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Bank of America Interview\nEmerging Growth & Regional Coverage group, SF Office, Superday"]},{"id":"q-2221","t":"beh","l":"Behavioral","s":90,"q":"What was your favorite and least favorite thing from your last internship?","k":["Favorite: Choose something specific and genuine that demonstrates your passion for the work. Strong answers include: the thrill of working on a live deal, the satisfaction of building a complex model that informed a client decision, or the mentorship and learning from senior bankers.","Least favorite: Frame this as a realistic challenge you handled maturely, not a complaint. Good examples: the steep learning curve on a new sector (which you overcame), the occasional tedium of formatting-intensive tasks (which you understand is part of the job), or wanting more client exposure (which showed ambition).","For your least favorite, explain how you approached it constructively and what you learned from it.","The goal is to show that you have a clear-eyed view of the job, that the positives far outweigh the negatives for you, and that you handle challenges with maturity."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Bank of America Interview\nEmerging Growth & Regional Coverage group, SF Office, Superday"]},{"id":"q-2222","t":"beh","l":"Behavioral","s":90,"q":"How would you deal with an analyst who is bypassing you and sharing materials with senior bankers without keeping you in the loop?","k":["Address it directly and privately with the analyst. Have a candid one-on-one conversation to understand why it is happening. It may be a misunderstanding of workflow expectations rather than intentional circumvention.","Clearly reestablish the process: all materials should be reviewed by the associate before going to senior bankers. Explain that this is not about control but about quality assurance and ensuring consistency in what the team presents.","Frame it constructively. Explain that your review protects the analyst as well. If an error reaches an MD directly, it reflects poorly on the analyst. Your role is to catch issues before they escalate.","If the behavior continues after the conversation, escalate to your VP to align on team norms. Avoid being punitive. The goal is to build a functional working relationship, not to assert authority."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Bank of America Interview\nSA 2025, SF Office, Superday"]},{"id":"q-2223","t":"beh","l":"Behavioral","s":90,"q":"How did you think about consulting versus banking?","k":["Acknowledge that both are rigorous, analytical career paths that attract similar talent, which shows you have done your research and are not dismissing consulting outright.","Differentiate the two clearly: consulting focuses on operational strategy and organizational improvements across a broad set of industries, while banking centers on executing high-stakes financial transactions such as M&A, capital raises, and restructurings.","Explain why banking won out for you. Focus on your passion for financial analysis, your desire to work on transactions with measurable outcomes (e.g., a deal closing, capital raised), and the direct impact bankers have on corporate strategy at the most critical inflection points.","Reference a specific experience or moment that cemented your decision, such as a finance class, a deal you followed, or an informational interview with a banker that resonated with you more than conversations with consultants."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Bank of America Interview\nSA 2026, Superday"]},{"id":"q-2224","t":"beh","l":"Behavioral","s":90,"q":"Tell me about an experience when you received pushback from your manager.","k":["Situation: Set the context of a project or proposal you were working on for your manager.","Task: Describe the specific idea you presented and the pushback or criticism you received.","Action: Explain how you responded professionally. Emphasize that you listened to understand their concerns, asked clarifying questions, and either incorporated the feedback to improve your work or respectfully presented data to support your original view.","Result: Explain the final outcome. The focus should be on collaboration and reaching a better solution, demonstrating that you are coachable and value constructive feedback."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Barclays Interview\nFirst round"]},{"id":"q-2225","t":"beh","l":"Behavioral","s":90,"q":"How are you thinking about fit for a given firm and team?","k":["Define 'fit' as a two-way street: It's about both your ability to contribute to their environment and the firm's ability to support your growth.","Discuss culture: Mention researching the firm's values (e.g., teamwork, integrity, excellence) and how they align with your own.","Talk about work style: Mention aspects like pace, level of collaboration, and communication style. Connect your own preferences to what you've learned about the firm.","Mention people: Stress the importance of working with smart, motivated individuals you can learn from, referencing any positive interactions you've had during the process."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Barclays Interview\nIndustrials - Auto group, First round"]},{"id":"q-2226","t":"beh","l":"Behavioral","s":90,"q":"Why did you major in what you studied for undergrad?","k":["Explain your initial interest or passion for the subject.","Describe what you enjoyed most about the curriculum or a specific area of focus.","Highlight 2-3 key skills you developed through your major (e.g., quantitative analysis, critical thinking, research, problem-solving).","Connect those skills directly to the requirements of an investment banking analyst role, showing a clear link between your academic background and your career choice."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Barclays Interview\nFirst round"]},{"id":"q-2227","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you had to present something complex. What was it? How did you go about it?","k":["Situation: Describe the complex topic and the audience for your presentation (e.g., technical concept to a non-technical audience).","Task: State the goal of the presentation – what did you want the audience to understand or do?","Action: Detail your preparation process. Explain how you structured the information logically, simplified jargon, used analogies or visuals, and anticipated questions.","Result: Describe the outcome of the presentation. Focus on the audience's positive reception, their understanding of the topic, and any positive feedback you received."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Barclays Interview\nSecond round"]},{"id":"q-2228","t":"beh","l":"Behavioral","s":90,"q":"How do you motivate a team?","k":["Start by establishing a clear, shared vision and ensuring every team member understands the overall objective and their specific role in achieving it.","Emphasize leading by example, demonstrating a strong work ethic, a positive attitude, and a commitment to quality.","Mention fostering an open and collaborative environment where team members feel empowered to contribute ideas and provide feedback.","Highlight the importance of recognizing individual and team achievements, providing constructive guidance, and offering support to remove any obstacles hindering progress."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in BMO Interview\nNew York Office, Superday"]},{"id":"q-2229","t":"beh","l":"Behavioral","s":90,"q":"Out of all the people you know, what percentage of them are not a fan of yours? Why?","k":["Acknowledge that it's impossible to please everyone and that some level of disagreement is natural.","Focus on scenarios where differing opinions or tough decisions might lead to friction, rather than personal dislike.","Example: \"Perhaps a small percentage, typically when I've had to make tough decisions for the greater good of a team or project, or when I've held firm on a principle that someone else disagreed with.\"","Emphasize your commitment to integrity, performance, and professional standards, even if it's not always popular."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Centerview Partners Interview"]},{"id":"q-2230","t":"beh","l":"Behavioral","s":90,"q":"If you were stranded on a boat, what three things would you take?","k":["Choose items that demonstrate practical thinking, resourcefulness, and a touch of personality.","Example 1 (Survival): A comprehensive survival kit (water purifier, first aid, fire starter) for immediate needs.","Example 2 (Rescue): A satellite phone or signal flare gun for communication/rescue.","Example 3 (Morale/Problem-Solving): A multi-tool or a comprehensive book on knots/sailing/navigation.","Briefly explain the rationale for each choice, focusing on their utility in the given scenario."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Centerview Partners Interview"]},{"id":"q-2231","t":"beh","l":"Behavioral","s":90,"q":"What were your favorite and least favorite classes?","k":["Favorite Class: Name one, explain *why* you enjoyed it (e.g., intellectual stimulation, practical application, skill development relevant to banking).","Least Favorite Class: Name one, but frame it positively. Explain *why* it was challenging (e.g., less intuitive subject, teaching style) but focus on what you learned or how you persevered.","Avoid complaining or criticizing; show self-awareness and a growth mindset."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Centerview Partners Interview"]},{"id":"q-2232","t":"beh","l":"Behavioral","s":90,"q":"You're at the airport with a VP and MD heading to a client meeting and the analyst with the books says he isn't going to make it. How do you resolve the situation, talk to your senior leaders and talk to the analyst?","k":["Step 1 (Assess & Communicate): First, calmly but immediately inform the MD and VP of the situation. Present it not just as a problem, but with an initial plan.","Step 2 (Problem-Solve): Tell the analyst to email you the latest versions of all materials immediately. Simultaneously, use your phone to find the nearest 24/7 print shop (e.g., FedEx, Staples) near the client's office or your hotel.","Step 3 (Execute): While en route from the destination airport, confirm the print shop can handle a high-quality, bound print job on a rush basis. Coordinate logistics for picking it up before the meeting.","Step 4 (Follow-up): Keep the senior bankers updated. This demonstrates ownership, calmness under pressure, and resourcefulness."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Centerview Partners Interview\nFirst round"]},{"id":"q-2233","t":"beh","l":"Behavioral","s":90,"q":"Would you rather be feared or loved?","k":["This is a test of your leadership philosophy and ability to think critically under pressure. There is no single right answer, but your reasoning matters more than your choice.","A strong approach: choose \"respected\" as a synthesis of both, and explain that the best leaders earn trust and loyalty through competence, fairness, and high standards — not through fear or popularity.","If you lean toward \"loved,\" frame it around building a collaborative, high-trust team. If you lean toward \"feared,\" frame it around accountability and maintaining standards.","Support your answer with a brief example of how you have led or worked under someone who embodied that approach effectively."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Centerview Partners Interview\nGeneralist group, New York Office, Superday"]},{"id":"q-2234","t":"beh","l":"Behavioral","s":90,"q":"What makes a good leader?","k":["Identify three to four core qualities of effective leadership: clear communication, decisiveness, the ability to empower and develop others, and leading by example through personal accountability.","For each quality, provide a brief explanation of why it matters. For example: \"Clear communication ensures everyone on the team understands objectives and priorities, which is critical in fast-paced deal environments.\"","Reference an example — either a leader you have observed or a time you demonstrated one of these qualities yourself.","Avoid generic, surface-level answers. Show depth of thought about what actually drives effective leadership in high-performance teams."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Centerview Partners Interview\nGeneralist group, New York Office, Superday"]},{"id":"q-2235","t":"beh","l":"Behavioral","s":90,"q":"If you had unlimited resources to invest in three things to either improve your skills or build up new skills, what would you invest in?","k":["Choose three areas that balance professional development with personal growth, showing you are thoughtful and self-aware about where you want to improve.","At least one should be directly relevant to banking — for example, deepening your expertise in financial modeling, learning a new programming language for data analysis, or studying Mandarin for cross-border deal work.","Another could be a broader leadership or communication skill — public speaking, negotiation, or executive presence.","The third can showcase intellectual curiosity or personal passion — learning an instrument, studying behavioral economics, or pursuing an advanced certification. This reveals your character beyond the office."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Centerview Partners Interview\nGeneralist group, New York Office, Superday"]},{"id":"q-2236","t":"beh","l":"Behavioral","s":90,"q":"Who are you when others are not around?","k":["This question tests authenticity and self-awareness. The interviewer wants to understand your character and values when there is no audience to perform for.","Describe qualities that remain consistent regardless of who is watching: discipline, intellectual curiosity, integrity, or a strong work ethic. The point is to show there is no gap between your public persona and your private character.","Provide a concrete example: \"When I'm working alone on a model at 2 AM, I still double-check every formula and cross-reference every source — not because someone will review it, but because my standard does not change when no one is watching.\"","The best answers convey that your performance and values are intrinsically motivated, not driven by external validation."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Centerview Partners Interview\nGeneralist group, New York Office, Superday"]},{"id":"q-2237","t":"beh","l":"Behavioral","s":90,"q":"If you were the CEO of a company, which company would you choose and what would you do?","k":["Choose a company you have genuine knowledge of and can speak about with authority. Ideally, select one facing an interesting strategic inflection point.","Briefly explain why you chose this company — what about its market position, competitive dynamics, or operational challenges makes it an interesting leadership challenge?","Outline two to three specific strategic actions you would take as CEO: potential M&A, cost restructuring, product innovation, geographic expansion, or capital allocation changes. Be specific and support each action with reasoning.","This question tests strategic thinking and business acumen — demonstrate that you can analyze a company holistically and formulate a coherent plan for value creation."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Centerview Partners Interview\nGeneralist group, New York Office, Superday"]},{"id":"q-2238","t":"beh","l":"Behavioral","s":90,"q":"If you could uninvent anything, what would it be and why?","k":["Choose something thoughtful that reveals your values and analytical thinking. Strong answers address inventions with significant negative externalities — social media algorithms, nuclear weapons, or single-use plastics are common but effective choices.","Explain your reasoning clearly: What harm has this invention caused? What would the world look like without it? Consider the second-order effects.","Acknowledge the counterargument — most inventions have both positive and negative impacts. Show nuanced thinking by briefly weighing both sides before arriving at your conclusion.","The question assesses your ability to form a clear thesis, support it with logic, and communicate it persuasively — core advisory skills."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Centerview Partners Interview\nGeneralist group, New York Office, Superday"]},{"id":"q-2239","t":"beh","l":"Behavioral","s":90,"q":"What are your goals for the next five and ten years?","k":["5-Year Goal: Master analyst/associate skills, contribute to deals, build expertise within the firm (mention Citi).","10-Year Goal: Progress to VP/Director, lead deal teams, develop client relationships, potentially specialize (mention Citi again if feasible).","Reinforce commitment to a long-term banking career path."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview"]},{"id":"q-2240","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time your team faced adversity and your role in solving it.","k":["Situation: Briefly describe the team and project context.","Adversity: Clearly state the challenge the team faced (e.g., unexpected obstacle, data issue, tight deadline).","Action: Detail the specific steps *you* took to address the adversity (e.g., proposed solution, took initiative, researched alternatives, reallocated tasks).","Result: Explain how your actions contributed to overcoming the adversity and the positive outcome for the team."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview"]},{"id":"q-2241","t":"beh","l":"Behavioral","s":90,"q":"What skills does an analyst need?","k":["Technical/Analytical: Financial modeling, valuation, quantitative skills.","Work Ethic/Execution: Attention to detail, resilience, time management, organization.","Soft Skills: Communication (written/verbal), teamwork, proactivity, coachability."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview"]},{"id":"q-2242","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you persevered through an obstacle.","k":["Situation: Describe the context and the specific task or goal.","Obstacle: Clearly define the difficulty encountered (e.g., steep learning curve, lack of resources, unexpected setback).","Action: Detail the persistent steps you took to overcome it (e.g., sought help, dedicated extra time, broke down the problem, tried different approaches).","Result: State the positive outcome achieved through your perseverance and any lessons learned."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview"]},{"id":"q-2243","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you had a really bad experience working on a team. What did you do?","k":["Situation: Briefly describe the team and project.","Bad Experience: Explain the specific issue (e.g., poor communication, lack of contribution, conflict).","Action: Detail your steps – attempt direct/private communication first, then focus on pragmatic solutions (redistribute work, document issues, inform supervisor factually if necessary).","Result: Explain how the project concluded and emphasize your focus on professionalism and achieving the team's goal despite difficulties."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview"]},{"id":"q-2244","t":"beh","l":"Behavioral","s":90,"q":"What’s a trend you think is cool?","k":["Identify a specific trend (e.g., Generative AI, sustainable investing, rise of creator economy).","Explain what makes it interesting or \"cool\" to you personally.","Briefly discuss its potential impact or significance (business, social, etc.).","Show genuine curiosity and ability to articulate thoughts on current events."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview"]},{"id":"q-2245","t":"beh","l":"Behavioral","s":90,"q":"What do you think will be the three biggest challenges that you'll face if you were to be part of Citi?","k":["Challenge 1: Steep Learning Curve (technical skills, products, processes).","Challenge 2: Managing Intensity and Workload (long hours, pressure, accuracy).","Challenge 3: Navigating a Large Organization (understanding structure, building network, leveraging resources).","Frame these as anticipated aspects you are prepared to tackle proactively."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview"]},{"id":"q-2246","t":"beh","l":"Behavioral","s":90,"q":"What do you think you will be able to transfer from your previous work experiences to Citi?","k":["Skill 1: Analytical Rigor (Example, i.e. Banking analysis).","Skill 2: Attention to Detail (Example, i.e. Error-free work).","Skill 3: Teamwork/Collaboration (Example, i.e. Team environment).","Skill 4: Proactive Learning/Adaptability (Example, i.e. Steep learning curve).","Skill 5: Work Ethic/Time Management (Example, i.e. Demanding role).","Express confidence these skills enable quick contribution at Citi."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview"]},{"id":"q-2247","t":"beh","l":"Behavioral","s":90,"q":"Pick one bullet point from your resume and tell me about it. Explain why you chose that particular one.","k":["Select a bullet point that showcases a significant accomplishment with quantifiable results, directly relevant to the skills required in banking (e.g., analysis, initiative, impact).","Use the STAR method to structure your response: Describe the Situation, the Task you were assigned, the specific Action you took, and the positive Result of your work.","Clearly articulate your individual contribution and the thought process behind your actions.","Explain *why* you chose this bullet: It might be because it demonstrates your analytical abilities, highlights your proactive approach, represents a challenge you successfully overcame, or was a pivotal learning experience that solidified your interest in finance."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview\nNew York Office, Superday"]},{"id":"q-2248","t":"beh","l":"Behavioral","s":90,"q":"Imagine I told you that we have already hired someone for this role and our conversation today is just a courtesy. How would you proceed with the rest of this interview?","k":["First, express your appreciation for their time and transparency, and firmly state your desire to continue the conversation.","Frame the interview as a valuable opportunity regardless of the outcome: a chance for you to learn more about the firm and for them to know you for potential future opportunities.","Demonstrate your genuine interest and preparation by proactively shifting the conversation. For example: \"In that case, I'd love to spend the time discussing a recent deal of yours that I was following...\" or \"Perhaps you could share some insights on the challenges and opportunities you see in your group right now.\"","This approach showcases resilience, professionalism, and a deep interest in the firm itself, not just the immediate job opening."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview\nNew York Office, Superday"]},{"id":"q-2249","t":"beh","l":"Behavioral","s":90,"q":"Who would write your biography?","k":["Choose an author whose work you genuinely admire and whose style reflects qualities you value.","Explain your choice. For example, you might choose Walter Isaacson for his ability to detail how innovation and personality intersect, or Michael Lewis for his skill in making complex financial topics engaging and character-driven.","Briefly connect the author's style or focus to an aspect of your own story or ambition you'd want highlighted, showing thoughtfulness and self-awareness."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview\nNew York office, Second round"]},{"id":"q-2250","t":"beh","l":"Behavioral","s":90,"q":"In 20 years, investment banking no longer exists. What do you do with your career?","k":["Your answer should connect to the core skills and interests that attract you to banking in the first place.","One path is corporate strategy or corporate development at a company in an industry you are passionate about, applying similar analytical and strategic skills to help a single business grow.","Another path could be on the buyside, such as venture capital or private equity, focusing on identifying and investing in promising companies.","This shows that your interest is rooted in strategic finance and business analysis, not just the title of \"investment banker.\""],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview\nNew York office, Second round"]},{"id":"q-2251","t":"beh","l":"Behavioral","s":90,"q":"What is the riskiest thing you have ever done?","k":["Focus on a calculated risk (professional, academic, or a significant personal project) rather than a reckless one.","Use the STAR method: Describe the situation and why a risk was necessary.","Explain your thought process, how you weighed the potential upside and downside, and what steps you took to mitigate the risk.","Conclude with the outcome and, most importantly, what you learned from the experience."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview\nNew York Office, Second round"]},{"id":"q-2252","t":"beh","l":"Behavioral","s":90,"q":"Which actor or actress would play you in a movie about your life, and why?","k":["Choose an actor/actress known for portraying specific, positive traits.","Explain your choice by linking their on-screen persona or notable roles to 1-2 professional qualities you possess (e.g., resilience, analytical thinking, integrity).","Keep the explanation brief and focused on the \"why,\" demonstrating self-awareness and creativity."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview\nNew York Office, Second round"]},{"id":"q-2253","t":"beh","l":"Behavioral","s":90,"q":"Tell me about how you handled client interactions in your last job. What were your roles and responsibilities?","k":["Situation: Briefly describe your previous role and its client-facing responsibilities.","Task: Outline a specific situation where you were tasked with managing a client request or relationship.","Action: Detail the steps you took, emphasizing active listening, managing expectations, clear communication, and delivering a solution.","Result: Explain the positive outcome for the client and your firm, reinforcing your ability to build and maintain client relationships."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview\nSuperday"]},{"id":"q-2254","t":"beh","l":"Behavioral","s":90,"q":"If you are in a situation where your client wants something but your VP/MD disagrees with your approach of delivering the solution, what would you do?","k":["Prioritize Internal Alignment: First, seek to understand the VP/MD's perspective. Ask clarifying questions to grasp their concerns, objectives, and reasoning.","Present Your Rationale: If you still believe in your approach, respectfully present your viewpoint, supported by data or logic. Acknowledge their perspective while explaining yours.","Accept the Final Decision: Ultimately, the VP/MD has final say due to their experience. Once a decision is made, commit to it fully and without reservation.","Present a Unified Front: Approach the client with the agreed-upon solution. It is critical to present a cohesive and unified message externally."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview\nSuperday"]},{"id":"q-2255","t":"beh","l":"Behavioral","s":90,"q":"What do you include in a pitchbook and how do you go about making one on the first day of your internship?","k":["Pitchbook Contents:","Bank/Team Introduction and Credentials.","Executive Summary and Situation Analysis.","Valuation Analysis (e.g., Comps, Precedents, DCF).","Strategic Alternatives / Recommendation.","Appendix with supporting data.","First Day Approach:","Seek Guidance: Immediately ask the Associate for clear instructions and, most importantly, for a recent, relevant precedent or template to follow.","Be Resourceful: Use the precedent to understand the structure, tone, and level of detail required.","Be Meticulous: Double-check all numbers and formatting. Pay extreme attention to detail.","Ask Smart Questions: After trying to find the answer yourself, ask targeted, thoughtful questions rather than general ones."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview\nFirst round"]},{"id":"q-2256","t":"beh","l":"Behavioral","s":90,"q":"An MD drops off a CIM, needs a valuation, and says it is due the next day, but they are going to be in the air and unreachable. What do you do?","k":["Clarify Before Departure: Use the few moments before the MD is unreachable to ask critical questions: \"What type of valuation is expected (e.g., DCF, LBO, comps)? Are there any key assumptions I should be aware of?\"","Review and Strategize: Thoroughly read the CIM to understand the business. Identify a preliminary list of comparable companies and precedent transactions.","Leverage Internal Resources: Search the firm's drive for valuation models of similar companies. Ask an Associate or another analyst if they have a relevant template you can use as a starting point.","Execute and Document: Begin building the valuation. Clearly document all assumptions you make (e.g., growth rates, margins, discount rate). This is crucial.","Prepare for Review: Aim to have a well-structured, fully functional model ready for when the MD is available. Have your list of assumptions ready to discuss."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview\nSecond round"]},{"id":"q-2257","t":"beh","l":"Behavioral","s":90,"q":"Imagine you are seated next to the CEO of a potential client on a plane. How would you approach the conversation to ultimately pitch them relevant advisory services?","k":["Effective approach for client development:","Build rapport: Start with genuine conversation about their business, industry trends, or recent news.","Listen actively: Understand their challenges, strategic priorities, and pain points.","Demonstrate expertise: Share relevant market insights or case studies without being overly promotional.","Identify opportunities: Connect their needs to specific services (M&A, capital raising, restructuring).","Offer value: Suggest a follow-up meeting to discuss ideas in detail.","Maintain professionalism: Exchange contact information and follow up promptly."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Citi Interview\nChicago Office"]},{"id":"q-2258","t":"beh","l":"Behavioral","s":90,"q":"What is something not on your resume that you wish you could have included?","k":["Choose a meaningful experience or quality that reveals a positive trait applicable to investment banking, such as resilience, creativity, or leadership in a non-traditional context.","Briefly narrate the story behind this experience. It could be a personal project you undertook, a significant challenge you overcame, or a skill you developed outside of formal work or academics.","Focus on the lesson learned or the quality it demonstrates. For example, overcoming a personal challenge shows perseverance and determination.","Conclude by explaining why this quality is important to you and how it would contribute to your success as an analyst."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nNew York Office, Superday"]},{"id":"q-2259","t":"beh","l":"Behavioral","s":90,"q":"For some people it is religion, for others it is family. What grounds you?","k":["Answer genuinely while maintaining a professional tone. This question assesses your stability, values, and ability to handle pressure.","Identify a core principle or source of stability that is meaningful to you. Examples could include a commitment to continuous learning, the discipline of a particular hobby or sport, or the perspective gained from mentors and family.","Explain *how* this principle or support system grounds you, especially during challenging or high-stress periods.","Subtly connect this back to the demanding nature of banking, demonstrating that you have a strong internal foundation to maintain balance and resilience."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nNew York Office, Superday"]},{"id":"q-2260","t":"beh","l":"Behavioral","s":90,"q":"It's late at night, and you're preparing a pitch deck for a sell-side M&A process due in the morning. You cannot reach your VP or MD, but you suspect there's a significant error in the client's valuation methodology. What do you do?","k":["First, do not send the deck. Your primary responsibility is to protect the firm from distributing potentially incorrect analysis.","Thoroughly double-check your own findings to be certain there is a likely error. Clearly document your reasoning, calculations, and the specific assumptions you are questioning.","Prepare two versions of the key slides: one reflecting the original numbers and another with your proposed corrections. Use footnotes to clearly explain the changes and the rationale behind them.","Draft a concise, professional email to your VP and MD summarizing the issue. Attach both versions for their review and state that you will await their guidance before proceeding. This demonstrates sound judgment, initiative, and analytical rigor."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nChicago Office"]},{"id":"q-2261","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you had to bring together people from different business units to achieve a goal.","k":["Use the STAR (Situation, Task, Action, Result) method to structure your answer.","Situation: Describe the project and why it required cross-functional collaboration.","Task: Clearly state the common goal that needed to be achieved.","Action: Detail the specific steps you took to facilitate communication, align objectives, and manage different perspectives to foster a collaborative environment.","Result: Explain the successful outcome of the project and what you learned about cross-functional teamwork."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nNew York office, First round"]},{"id":"q-2262","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you worked with a difficult subordinate.","k":["Situation: Describe the context, the team, and the subordinate's specific difficult behavior (e.g., missing deadlines, poor quality work, negative attitude).","Action: Detail the steps you took. Start with a private conversation to understand the root cause. Provide clear, constructive feedback and set specific, measurable expectations. Offer support and resources, and document your conversations.","Result: Explain the outcome. Ideally, the subordinate's performance improved. If not, describe the professional steps you took next. Emphasize lessons learned about leadership, communication, and performance management."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nNew York office, First round"]},{"id":"q-2263","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a cause that is important to you.","k":["Identify a specific cause you are genuinely passionate about.","Explain concisely why this cause resonates with you personally.","Describe your involvement, whether through volunteering, fundraising, or advocacy. Be specific about your actions and contributions.","Conclude by subtly linking a positive trait demonstrated through your involvement (e.g., commitment, empathy, initiative) to your character."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nNew York office, First round"]},{"id":"q-2264","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time when you had to deal with something being done that was unethical.","k":["Situation: Describe a specific situation where you observed an action that clearly crossed an ethical line (e.g., plagiarism, misrepresenting data, breaking a clear rule). Keep it professional and anonymous.","Task: Explain the dilemma you faced and your responsibility to act.","Action: Detail your response. A strong answer often involves addressing the person directly and privately first. If that fails or is inappropriate, explain your decision to escalate the issue to a manager, professor, or compliance officer.","Result: Conclude with the outcome and reinforce your commitment to integrity, explaining that it's a non-negotiable principle for you."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nEnergy & Infrastructure group, First round"]},{"id":"q-2265","t":"beh","l":"Behavioral","s":90,"q":"How do you build relationships?","k":["Show Genuine Interest: Ask thoughtful questions and actively listen to understand others' perspectives and responsibilities.","Be Reliable and Proactive: Consistently deliver high-quality work and look for opportunities to help teammates before being asked.","Maintain a Positive Attitude: Be approachable, coachable, and maintain composure under pressure.","Follow Through: Build trust by always doing what you say you will do."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nEnergy & Infrastructure group, First round"]},{"id":"q-2266","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you prioritized forming a relationship.","k":["Situation: Explain why building a specific relationship (e.g., with a team member on a different team, a key project stakeholder) was important for a project's success or your own development.","Task: Your goal was to build trust and establish a collaborative connection.","Action: Describe the specific, proactive steps you took, such as scheduling a coffee chat, offering assistance on one of their tasks, or making an effort to understand their work and challenges.","Result: Detail the positive outcome of your effort—a stronger working relationship that led to better collaboration, more efficient work, or a successful project outcome."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nSponsors group"]},{"id":"q-2267","t":"beh","l":"Behavioral","s":90,"q":"If you had an autobiography, what would you title it?","k":["Choose a title that reflects a core personal or professional theme, such as resilience, curiosity, or continuous improvement.","Example: \"Always Day One\" to show a commitment to constant learning and avoiding complacency.","Example: \"The Power of Preparation\" to highlight your work ethic and attention to detail.","Briefly explain the 'why' behind your title, connecting it to a key aspect of your character that would make you a good analyst."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nLFO group, First round"]},{"id":"q-2268","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time when you had to build team consensus.","k":["Situation: Describe a situation where your team had differing opinions on a significant decision.","Task: Your goal was to get everyone to agree on a single path forward to avoid stalling the project.","Action: Explain how you facilitated a discussion. This should include making sure all viewpoints were heard, using data or logic to evaluate options, and identifying common ground or a potential compromise.","Result: Describe how the team reached a consensus, even if it wasn't everyone's first choice. Emphasize the positive outcome of moving forward in a unified way."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nFSG group, First round"]},{"id":"q-2269","t":"beh","l":"Behavioral","s":90,"q":"What’s the dynamic between the associate and analyst and how will you handle that?","k":["The Dynamic:","The Associate acts as the project manager and first line of review. They delegate tasks to the Analyst, provide guidance, and are responsible for the quality of the Analyst's work product.","The Analyst is responsible for the execution of tasks—building models, creating slides, and conducting research—with speed and perfect accuracy.","How to Handle It:","Be reliable and detail-oriented to earn their trust.","Communicate proactively; provide updates on your progress and flag any potential issues early.","Be coachable and receptive to feedback, viewing it as a tool for improvement.","Your goal is to make your Associate's job easier by producing excellent, error-free work."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nGIG group, Second round"]},{"id":"q-2270","t":"beh","l":"Behavioral","s":90,"q":"What accounting and finance coursework have you completed or will you have completed prior to the role?","k":["Be specific and list the most relevant courses.","Group them logically: \"In accounting, I've taken Financial Accounting and Managerial Accounting. In finance, my coursework includes Corporate Finance, Investments, and Financial Statement Analysis.\"","If you have taken advanced courses like Valuation or Mergers & Acquisitions, highlight them.","Briefly mention one key takeaway or project from a particularly relevant class to demonstrate genuine understanding, e.g., \"In my Valuation class, I built a full DCF model for [Company], which gave me a strong practical foundation.\""],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nFSG group, Second round"]},{"id":"q-2271","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you had to take over another person's work.","k":["Situation: Explain the circumstances that required you to take over the work (e.g., a teammate was sick, left the project, or was falling behind).","Task: Describe the specific deliverable and the deadline you were now responsible for.","Action: Detail how you efficiently got up to speed. This includes reviewing the existing work, identifying gaps, and prioritizing the remaining tasks. Emphasize your positive, team-first attitude and avoidance of complaining.","Result: State that you successfully completed the work on time and to a high standard, ensuring the team's overall success."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Credit Suisse Interview\nM&C group, Second round"]},{"id":"q-2272","t":"beh","l":"Behavioral","s":90,"q":"Which group do you absolutely not want to be in and why?","k":["Recognize this as a test of your diplomacy and attitude. Avoid speaking negatively about any group.","Start by stating that you are genuinely open to and excited about learning from any group, as the core analytical skills are highly transferable and valuable across the bank.","Pivot from the negative framing. Instead of naming a group you dislike, highlight 2-3 groups you are particularly interested in and explain your reasoning (e.g., alignment with your studies, fascination with the industry's dynamics, the group's recent deal activity).","If pressed to name one, choose a sector that is furthest from your current knowledge base and frame it as, \"While I'd have the steepest learning curve in a group like [XYZ], I would still embrace the challenge and opportunity to build my knowledge from the ground up.\""],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Deutsche Bank Interview\nNew York Office, First round"]},{"id":"q-2273","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a topic that’s not on your resume that you’re passionate about.","k":["Identify a specific, genuine passion (hobby, subject, cause).","Briefly explain how you pursue or engage with this passion.","Articulate what draws you to it (e.g., challenge, creativity, learning).","Keep it concise and professional, showing you're a well-rounded individual."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview"]},{"id":"q-2274","t":"beh","l":"Behavioral","s":90,"q":"How did you prepare for this interview?","k":["Researched the firm: Website, deals, news, specific group focus (mention Evercore).","Networked: Spoke with current employees (mention names if appropriate) about culture and role.","Practiced for interviews: Studied and reviewed technical concepts relevant to the role and prepared to speak through my experiences.","Followed markets: Stayed updated on relevant news and trends."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview"]},{"id":"q-2275","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you overcame a conflict.","k":["Situation: Briefly describe the team/project and the source of the conflict/disagreement.","Action: Explain your specific steps to resolve it – active listening, identifying root cause, proposing compromises or objective criteria, facilitating discussion.","Result: Describe how the conflict was resolved, the positive outcome for the team/project, and lessons learned about conflict resolution."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview"]},{"id":"q-2276","t":"beh","l":"Behavioral","s":90,"q":"What are 3 qualities of a great analyst?","k":["Quality 1: Attention to Detail (explain importance for accuracy in models/materials).","Quality 2: Proactive Work Ethic / Resilience (explain need for initiative, handling pressure/hours).","Quality 3: Coachability / Intellectual Curiosity (explain importance for steep learning curve, seeking feedback)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview"]},{"id":"q-2277","t":"beh","l":"Behavioral","s":90,"q":"How would you react if someone basically yelled at you on the job?","k":["Remain calm and professional externally; avoid escalating.","Listen actively to understand the core issue, separating message from delivery.","If a mistake was made, acknowledge it and focus on the fix.","If unclear/unfair, seek clarification respectfully at a calmer moment.","Focus on de-escalation and resolving the underlying work issue."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview"]},{"id":"q-2278","t":"beh","l":"Behavioral","s":90,"q":"What three compliments and three areas for improvement would we hear from your former subordinates?","k":["For compliments, choose three that reflect strong leadership and teamwork skills. Examples: \"They were always approachable and willing to help,\" \"They provided clear context for tasks, which helped my development,\" and \"They were great at motivating the team toward a common goal.\"","For areas for improvement, be honest and self-aware, but avoid critical flaws. Frame them constructively. Examples: \"To empower the team earlier, I could have delegated certain tasks sooner,\" or \"I sometimes get very focused on perfecting a deliverable and could be more proactive in giving broader project updates.\"","For each area of improvement, briefly mention a step you are taking to address it. This demonstrates maturity and a commitment to personal growth."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview\nNew York Office"]},{"id":"q-2279","t":"beh","l":"Behavioral","s":90,"q":"We think you might be too smart for investment banking and should consider a top hedge fund instead. Why do you still want to pursue banking?","k":["Acknowledge the compliment gracefully but firmly state your specific interest in investment banking.","Differentiate the roles clearly. Explain that your interest lies in the client-service and strategic advisory nature of banking—helping companies execute complex, transformational transactions.","Contrast this with the role of a hedge fund, which is focused on generating investment theses and managing a portfolio for the fund's own capital.","Conclude by emphasizing your desire to build a foundational skillset in valuation, deal execution, and client management, which you believe is best achieved in an investment banking role at this stage of your career."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview\nNew York Office"]},{"id":"q-2280","t":"beh","l":"Behavioral","s":90,"q":"What are your top three choice firms?","k":["State clearly that the firm you are interviewing with (Evercore) is your top choice.","Provide 1-2 specific, well-researched reasons why (e.g., deal advisory focus, culture, specific deals, lean team structure).","Name two other comparable firms (e.g., other elite boutiques or bulge brackets with strong M&A groups).","Briefly and diplomatically explain what aspects attract you to them, while subtly reinforcing why your current interview is the best fit."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview\nNew York Office, First round"]},{"id":"q-2281","t":"beh","l":"Behavioral","s":90,"q":"As an Associate, how would you manage and motivate an analyst who has already accepted a private equity offer that begins in one year?","k":["Acknowledge their future career goal as a positive reflection of their ambition.","Frame their remaining time at the bank as critical preparation for their next role, emphasizing the value of the deal experience they will gain.","Appeal to their sense of professionalism and responsibility to the current team and the firm's clients.","Provide them with engaging, high-impact work to keep them invested and ensure they continue to develop their skills."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview\nNew York Office, First round"]},{"id":"q-2282","t":"beh","l":"Behavioral","s":90,"q":"How do you think Evercore is different from its competitors?","k":["Focus on the independent advisory model: Emphasize that Evercore provides pure, unconflicted advice since it lacks a large balance sheet or trading arms that bulge brackets have.","Mention its 'elite' status: Acknowledge its reputation for working on high-profile, complex M&A transactions and restructuring assignments.","Highlight the culture: Based on your research, mention its reputation for having a more entrepreneurial and collaborative culture with high levels of senior banker involvement on all deals.","Lean structure: Note that the leaner team structure provides analysts with greater responsibility and exposure to senior bankers and clients earlier in their careers."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview\nSecond round"]},{"id":"q-2283","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time when someone you were supervising wasn't pulling his or her weight.","k":["Situation: Describe the team, the project, and the specific instances of the individual's underperformance (e.g., missing deadlines, poor quality work).","Task: Your responsibility was to address the issue to ensure the project's success and maintain team morale.","Action: Explain that you initiated a private, one-on-one conversation. Your goal was to first understand the root cause of the issue (e.g., are they overwhelmed, unclear on the task?). You then reset expectations clearly and offered support, while establishing a plan for checking in on progress.","Result: Describe the outcome. Ideally, the person's performance improved. If not, explain the next logical step, such as providing more formal feedback or escalating to a manager. The key is to show a mature, constructive approach."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview\nSecond round"]},{"id":"q-2284","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time when you faced interpersonal issues among your team.","k":["Situation: Briefly set the scene of the team project and the nature of the interpersonal conflict (e.g., communication breakdown, disagreement over strategy).","Task: Your goal was to help resolve the friction so the team could refocus on its objective.","Action: Describe the steps you took to mediate. This could involve facilitating a conversation, encouraging active listening, or refocusing the discussion on objective data and the team's common goals rather than personal disagreements.","Result: Explain how your actions helped de-escalate the situation and get the team back on a productive track, leading to a successful project outcome."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview\nSecond round"]},{"id":"q-2285","t":"beh","l":"Behavioral","s":90,"q":"Tell me about the culture in your previous employer.","k":["Be objective and balanced. Start by highlighting 2-3 positive aspects of the culture (e.g., \"It was highly collaborative,\" \"There was a strong emphasis on training,\" \"The work was very fast-paced which taught me a lot\").","If asked about challenges, frame them constructively (e.g., \"As a large organization, it could sometimes be difficult to get quick decisions, which taught me the importance of proactive communication.\").","Keep it professional and avoid complaining.","Conclude by connecting your experience to the new opportunity, e.g., \"I enjoyed the collaborative aspects and am now looking for a similarly team-oriented but leaner environment like Evercore's, where I can have a more direct impact.\""],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Evercore Interview\nSecond round"]},{"id":"q-2286","t":"beh","l":"Behavioral","s":90,"q":"If you had 10 minutes to pitch to a CEO, how would you get your energy level up?","k":["This question tests self-awareness and your ability to perform under pressure. Be genuine about your preparation ritual.","Preparation is the foundation. Review the key talking points, the client's recent earnings, news, and any deal-relevant data. When you know the material cold, confidence and energy follow naturally.","Physically, do whatever resets your focus: take a brief walk, stand up, or do a quick mental rehearsal of your opening and the key value proposition. The goal is to walk in sharp and present.","Mentally, remind yourself of the stakes and the opportunity. You are representing the firm and have something valuable to offer. Channel that responsibility into enthusiasm and conviction, not anxiety."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Evercore Interview\nSA 2025, Superday"]},{"id":"q-2287","t":"beh","l":"Behavioral","s":90,"q":"What is the difference between an independent advisory model and a bulge bracket? What is your decision criteria for deciding between them if you received offers from all of them?","k":["Independent advisories (Evercore, Lazard, PJT, Centerview) are pure-play advisory firms. They do not have lending, trading, or underwriting businesses, which means their advice is free from conflicts of interest. They tend to have leaner teams, giving junior bankers more responsibility and direct client exposure.","Bulge brackets (Goldman Sachs, Morgan Stanley, J.P. Morgan) offer a full-service platform including M&A advisory, capital markets, lending, and trading. They provide access to a broader set of products and a larger global footprint, but junior roles may involve more process-oriented work with less direct client interaction.","For decision criteria, frame it around what matters most to you at this stage. If you prioritize advisory depth, client proximity, and a meritocratic culture, the independent model is the better fit.","Close by stating that Evercore specifically stands out because of [specific reason: deal quality, people you have met, sector strength]. This ties the analytical comparison back to your genuine preference for the firm."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Evercore Interview\nSA 2025, Superday"]},{"id":"q-2288","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time when you were unprepared.","k":["Use the STAR method. Choose a genuine example where you were caught off guard but handled it well and learned from it. This question tests honesty and adaptability.","Situation: Describe the context where you were unprepared. Perhaps a meeting was moved up, a question came from left field, or you underestimated the complexity of a task.","Task: Explain what was expected of you and the pressure you felt in the moment.","Action: Describe how you responded in real time. Did you ask clarifying questions to buy time, lean on foundational knowledge to improvise, or honestly acknowledge the gap and commit to following up? Show composure under pressure.","Result: Explain the outcome and, critically, the system you put in place to prevent it from happening again. The lesson learned is the most important part of this answer."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Evercore Interview\nSA 2025, Superday"]},{"id":"q-2289","t":"beh","l":"Behavioral","s":90,"q":"A senior banker asks you to do something using his outline, but you disagree with that approach and think doing it a different way is better. What do you do?","k":["First, execute the work the way the senior banker requested. Their outline likely incorporates context you do not have as a junior banker — client preferences, prior conversations, or strategic considerations that are not immediately visible to you.","While completing the requested deliverable, prepare your alternative approach separately if time permits. Build your case with data, analysis, or a concrete example — not just opinion.","Once you have delivered the original request, raise your alternative constructively and privately. Frame it as an additional option, not a challenge: \"I put together the deck using your outline. I also sketched out an alternative structure that I thought might be worth considering — would you like to take a look?\"","Accept the senior banker's final decision without pushback. If they prefer their original approach, execute it to the highest standard. Demonstrating that you can follow direction while also contributing thoughtful ideas is what distinguishes a strong analyst.","The key principle: always deliver what is asked first. Earning the right to influence comes from consistently executing well and showing sound judgment over time."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Evercore Interview\nSA 2027, M&A group, New York Office, Superday"]},{"id":"q-2290","t":"beh","l":"Behavioral","s":90,"q":"What do you think are the three most important qualities of an Evercore analyst?","k":["Choose three qualities that align with Evercore's identity as a leading independent advisory firm with lean deal teams and a meritocratic culture. Strong choices include intellectual rigor, an ownership mentality, and relentless attention to detail.","Intellectual rigor: the ability to think critically about complex strategic problems, analyze companies holistically, and ask the right questions rather than just execute tasks mechanically. Evercore's advisory-only model demands analysts who can contribute to the substance of client advice, not just process work.","Ownership mentality: treating every deliverable as if your name is on it. On lean deal teams, analysts carry significant responsibility early. You must take full accountability for the quality and accuracy of your work without waiting to be told what needs to be fixed.","Attention to detail: in a client-facing advisory firm, a single error in a model or presentation can undermine credibility with a CEO or board. Every number, every footnote, and every formatting choice must be flawless.","For each quality, briefly reference how it connects to your own strengths or experiences. The interviewer is assessing both your understanding of the role and your self-awareness about what it takes to succeed."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Evercore Interview\nSA 2027, M&A group, New York Office, Superday"]},{"id":"q-2291","t":"beh","l":"Behavioral","s":90,"q":"You've worked in mission-focused work all your career, and we don't do that here. Why do you think banking is the right move, and how do you think you'll manage that?","k":["Acknowledge the difference in explicit mission focus.","Connect underlying motivations: problem-solving, achieving goals, delivering value (transferable).","Reframe banking's mission: client success, enabling growth/innovation, economic impact.","Highlight transferable skills developed (analytical rigor, diligence, execution under pressure).","Express commitment to banking's demanding, results-driven environment."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2292","t":"beh","l":"Behavioral","s":90,"q":"Can you tell me something that has been hard for you?","k":["Identify a specific, genuine challenge (e.g., prioritizing, public speaking, mastering a complex topic).","Explain briefly why it was initially difficult.","Describe the concrete steps taken to address it and improve.","Highlight progress made and ongoing self-awareness/refinement.","Avoid critical job-related weaknesses."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2293","t":"beh","l":"Behavioral","s":90,"q":"What would your formal supervisors say are your greatest strengths and weaknesses?","k":["Strength 1: Name a key strength (e.g., analytical skills) with a brief example of positive feedback.","Strength 2: Name another strength (e.g., work ethic, initiative) with brief supporting evidence.","Weakness 1: Identify a genuine area for development based on past feedback (e.g., delegating, asking questions sooner).","Weakness Action: Briefly explain how you recognized and have worked on improving this area.","Maintain a balanced and self-aware perspective."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2294","t":"beh","l":"Behavioral","s":90,"q":"What are two things that scare you about banking? (i.e. what concerns do you have about your skill set that you do and don't have?)","k":["Challenge 1: Mention the high pace and pressure combined with the need for absolute accuracy (concern is meeting standards consistently).","Challenge 2: Mention the steep learning curve for specific technical/product/sector nuances beyond foundational skills (concern is time to proficiency).","Frame these as anticipated challenges you are prepared for, not deterrents.","Briefly state how you plan to address them (work ethic, learning quickly, seeking guidance)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2295","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you've failed.","k":["Situation: Describe the context (project, team, goal).","Failure: Clearly state what went wrong and acknowledge your role/responsibility.","Action: Explain how you analyzed the failure and identified the root cause(s).","Result/Learning: Articulate the key lesson learned and provide a brief example of how you applied that lesson to improve future performance."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2296","t":"beh","l":"Behavioral","s":90,"q":"I am a marine and we think a lot about teams. Tell me about a time when your team wasn't functioning.","k":["Situation: Set the context of the team and project.","Dysfunction: Describe the specific problems (e.g., unclear roles, poor communication, lack of direction).","Action: Explain the steps *you* took to improve functioning (e.g., initiated a process discussion, suggested clear roles/deadlines, facilitated communication).","Result: Describe how the team's functioning improved and the positive impact on the project outcome. Emphasize lessons on team structure/communication."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2297","t":"beh","l":"Behavioral","s":90,"q":"In your many informational chats, what questions did you ask?\n\n\n\n\nFollow-up 1: Ok - what is your understanding of the role and the skills that you will bring to it?","k":["Informational Chat Questions:","Categorize questions: Role-specific (typical day, projects), Culture (team dynamics, mentorship), Career Path (advice, experiences).","Provide a few specific example questions within these categories.","Role Understanding & Skills:","Define Analyst Role: Core tasks (modeling, valuation, research, preparing materials) supporting senior bankers on transactions.","Skill 1: Analytical/Quantitative (evidence: coursework, projects).","Skill 2: Work Ethic/Resilience (evidence: demanding experiences).","Skill 3: Attention to Detail (evidence: specific examples).","Skill 4: Teamwork/Communication (evidence: group work).","Skill 5: Learning Agility/Coachability (evidence: proactive learning)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2298","t":"beh","l":"Behavioral","s":90,"q":"From your work experience, what would be relevant for investment banking?","k":["Identify Skill 1 from your background (e.g., discipline/execution) and link to banking demands.","Identify Skill 2 (e.g., analytical problem-solving) and link to banking analysis.","Identify Skill 3 (e.g., teamwork/leadership) and link to deal team dynamics.","Identify Skill 4 (e.g., project management/attention to detail) and link to deal processes.","Conclude by summarizing the strong relevance of these core competencies."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2299","t":"beh","l":"Behavioral","s":90,"q":"What's your greatest achievement in your previous job?","k":["Situation/Task: Briefly describe the context and your objective/responsibility.","Action: Detail the key steps you took, emphasizing skills used (analytical, leadership, technical, etc.) and effort involved.","Result: State the positive, specific outcome (quantify if possible) and explain why it was significant for you or the team/company.","Focus on impact and personal contribution."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2300","t":"beh","l":"Behavioral","s":90,"q":"What were your greatest challenges in your previous job?","k":["Situation: Describe the context and the specific challenge faced.","Task: Explain what needed to be done despite the challenge.","Action: Detail the steps you took to navigate the challenge (prioritization, communication, seeking help, adapting).","Result/Learning: Explain how you managed the situation and what you learned about handling such challenges (e.g., improved time management, communication)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2301","t":"beh","l":"Behavioral","s":90,"q":"For associate interview: What's your leadership style? How would you manage analysts after joining banking?","k":["Leadership Style:","Define your core style (e.g., collaborative, supportive, lead-by-example).","List 3-4 key components (e.g., clear communication, thoughtful delegation, accessibility/support, constructive feedback, accountability).","Managing Analysts:","Apply style: Understand their background/goals.","Set clear expectations for tasks/projects.","Provide regular check-ins, guidance, and feedback.","Offer development opportunities and exposure.","Foster a supportive, productive team environment."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2302","t":"beh","l":"Behavioral","s":90,"q":"What are the transferable skills you can bring to banking?","k":["Skill 1: Analytical Problem-Solving (Example: complex analysis/problem deconstruction, i.e. Financial analysis).","Skill 2: Project Management/Execution (Example: managing timelines/teams, i.e. Deal execution).","Skill 3: Communication (Example: presentations/reports, i.e. Client materials/team interaction).","Skill 4: Work Ethic/Resilience (Example: demanding environment, i.e. Banking intensity).","Skill 5: Teamwork (Example: collaborative projects, i.e. Deal team contribution).","(Optional) Client/Stakeholder Management."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2303","t":"beh","l":"Behavioral","s":90,"q":"What are your grades for the current semester?","k":["State current status honestly (e.g., \"tracking well,\" mention cumulative GPA).","Confirm consistency with transcript/overall performance.","Optionally mention 1-2 relevant courses where performance is strong.","Be prepared to briefly explain any significant dips if necessary."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2304","t":"beh","l":"Behavioral","s":90,"q":"What motivates you?","k":["Motivator 1: Challenge / Problem-Solving (intellectual stimulation).","Motivator 2: Learning / Continuous Improvement (steep learning curve).","Motivator 3: Achieving Tangible Results / Impact (deal success, client goals).","Motivator 4: Teamwork / Collaboration (working with high-caliber people).","Align these with the perceived nature of the banking role."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2305","t":"beh","l":"Behavioral","s":90,"q":"What are you most proud of?","k":["Identify a specific, genuine accomplishment.","Briefly describe the context and challenge involved.","Highlight the effort, skills, or dedication required from you.","State the positive outcome achieved.","Explain *why* this makes you proud (e.g., represents perseverance, discipline, impact)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2306","t":"beh","l":"Behavioral","s":90,"q":"Is there anything else you would like us to know?","k":["Reiterate strong enthusiasm for this specific opportunity/firm.","Briefly highlight a key aspect that resonates (culture, deals, learning).","Express confidence in your fit and ability to contribute.","Thank the interviewer(s) for their time.","(Avoid introducing completely new topics unless crucial and missed earlier)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2307","t":"beh","l":"Behavioral","s":90,"q":"How do you stay up to date on the markets?","k":["Daily Routine: Mention specific publications read daily (WSJ, Bloomberg, FT headlines/summaries).","Regular Inputs: Include newsletters (general finance, sector-specific), podcasts.","Deeper Dives: Mention reading analyst reports, listening to earnings calls, following strategists.","Discussion: Note value of discussing trends with peers/mentors.","Convey a consistent and multi-source approach."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2308","t":"beh","l":"Behavioral","s":90,"q":"Hypothetical Behavioral: You've been staffed on an on-going project, where you know none of the team, and you know there is a history of dysfunction within the team. How would you handle this situation?","k":["Build Rapport: Proactively introduce self individually, focus on collaboration.","Understand Project: Quickly learn status, goals, priorities via materials and questions.","Avoid Dysfunction: Stay out of past conflicts/gossip; focus on tasks and positive contribution.","Execute Reliably: Deliver high-quality work on time; communicate clearly and promptly.","Observe & Suggest Carefully: Note dynamics; if needed, cautiously suggest process improvements to lead/manager."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2309","t":"beh","l":"Behavioral","s":90,"q":"Hypothetical Behavioral: You're in the consulting space and you provide a presentation to a client using competitor's data (which has been sanitized, confidential information removed) to show benchmarks of your client's performance against competition. After the presentation, the client asks for the competitor's data (unscrubbed version). What would you do and how would you handle that situation?","k":["Politely Decline: Clearly state you cannot share unscrubbed competitor data.","Explain Why: Reference confidentiality obligations, data usage agreements, proprietary nature.","Reiterate Value: Emphasize the usefulness of the sanitized benchmark insights already provided.","Offer Alternatives: Suggest walking through methodology, discussing insights further, or exploring additional analysis using permissible data.","Maintain Firmness & Escalate: Respectfully hold the line if pressed; inform manager/project lead internally."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2310","t":"beh","l":"Behavioral","s":90,"q":"Tell me about your favorite class.","k":["Choose a class you genuinely enjoyed, ideally one that showcases relevant skills (e.g., quantitative analysis, critical thinking, problem-solving, communication).","Explain *why* it was your favorite (e.g., stimulating content, engaging professor, challenging projects).","Describe what you learned or how it developed a particular skill applicable to investment banking.","Briefly discuss a specific project or concept from the class that resonated with you."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2311","t":"beh","l":"Behavioral","s":90,"q":"How would you handle a situation if your friend/classmate posted the answers to an exam on a local discussion board?","k":["Prioritize academic integrity and ethical conduct.","First, attempt to address the issue directly and privately with the friend, explaining the severity and consequences, urging them to remove the post.","If they refuse or if the situation is urgent, escalate the issue to the appropriate authority (professor, dean's office), clearly stating the facts.","Emphasize that while friendship is important, maintaining integrity and fairness is paramount."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview"]},{"id":"q-2312","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you had to make a decision from several suboptimal choices. What was your process, and did you seek advice?","k":["Use the STAR method. Start with the Situation, explaining the context and why all available options were flawed.","Describe your Task: what was the ultimate goal you needed to achieve despite the poor choices?","Detail the Action, which is the core of the answer. Describe your analytical process: how you gathered information, defined criteria for the \"least bad\" option, and weighed the pros and cons of each. Mention if you consulted a manager or mentor to get a second opinion.","Explain the Result: state the decision you made, your rationale, and the outcome. Reflect on what you learned about making decisions under difficult constraints."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview\nNew York Office"]},{"id":"q-2313","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you exceeded expectations.","k":["Structure your response using the STAR method.","Situation: Briefly provide the context of the project or task.","Task: Clearly define what was originally expected of you. This is crucial for demonstrating how you went above and beyond.","Action: Detail the specific steps you took that surpassed the initial requirements. This could involve conducting deeper analysis, identifying a new opportunity, creating a more user-friendly model, or taking greater initiative than asked.","Result: Describe the positive impact of your additional effort, quantifying it if possible. Mention any positive feedback you received from your manager or team."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview\nNew York Office"]},{"id":"q-2314","t":"beh","l":"Behavioral","s":90,"q":"What would you include in a quarterly update presentation for a corporate client?","k":["Start with an Executive Summary that includes a Market Update on macroeconomic trends and capital markets conditions.","Include a section on Industry and Peer Group Analysis, covering recent news, key trends, and the trading performance of the client's main competitors.","Provide a brief review of the Client's Performance, such as their recent stock performance and financial results relative to the peer group.","The core of the presentation should be Strategic and Financial Recommendations. This could include potential M&A opportunities (acquisitions or divestitures), capital structure considerations, or ideas for shareholder value enhancement.","Conclude with a clear summary of key takeaways and outline the next steps for discussion."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview\nNew York Office"]},{"id":"q-2315","t":"beh","l":"Behavioral","s":90,"q":"What do you anticipate being the best and worst parts of working at Goldman Sachs?","k":["Best Part: Be specific and tailor your answer to the firm. Focus on the caliber of the people, the complexity and significance of the deals you would work on, and the unparalleled learning opportunities that come from being at a top-tier global institution.","Worst Part: Frame this as a realistic challenge you are prepared for, not a complaint. Good examples include the demanding nature of the work and the high-pressure environment that requires consistent excellence.","Demonstrate that you have a clear understanding of the job's realities and possess the resilience and work ethic to thrive in such an environment."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview\nNew York Office"]},{"id":"q-2316","t":"beh","l":"Behavioral","s":90,"q":"A client requests specific competitor data for an industry report you are preparing, but including this data is against firm policy. How do you handle this situation?","k":["Your first step is to recognize that firm policy and client confidentiality are paramount. Do not break the rule.","Immediately and privately escalate the issue to your VP or deal team leader. Explain the client's request and the policy conflict, and align on a unified response strategy.","The response to the client should politely but firmly explain that you cannot provide the specific data requested due to confidentiality and policy restrictions.","Crucially, be proactive in offering an alternative solution. Suggest providing aggregated, anonymized, or publicly sourced data that still delivers the strategic insights the client needs without violating policy. Focus on what you *can* deliver."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview\nNew York Office"]},{"id":"q-2317","t":"beh","l":"Behavioral","s":90,"q":"You need to put together a quarterly presentation to a client. What goes in the presentation?","k":["Market Update: A summary of relevant macroeconomic trends, capital markets activity, and industry news.","Peer Group Analysis: A review of the client's competitors, including their recent performance, valuation multiples, and any significant strategic moves.","Company Performance: An overview of the client's own stock performance and valuation relative to the peer group.","Strategic Discussion: Updates on any ongoing projects and an introduction of potential new ideas or strategic opportunities (e.g., potential M&A targets, capital structure optimization).","Appendix: Detailed supporting data, models, and charts."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview\nNew York office, First round"]},{"id":"q-2318","t":"beh","l":"Behavioral","s":90,"q":"What part of the job do you think you would dislike?","k":["Be honest but frame your answer positively, showing you have a realistic view of the job.","Good examples include the frustration of working hard on a deal that ultimately falls apart for market reasons, or the repetitive nature of certain tasks like formatting presentations.","Avoid mentioning the long hours, stress, or difficulty of the work, as these are expected.","Conclude by emphasizing that you understand these aspects are part of the process and you are prepared to handle them to achieve the larger goals."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview\nNew York office, First round"]},{"id":"q-2319","t":"beh","l":"Behavioral","s":90,"q":"You are an associate on a team. Your VP assigns you a deck due in about a week. You bring the project to an analyst, but the analyst says, 'I am too busy to help right now.' How do you handle the situation?","k":["First, seek to understand. Ask the analyst about their current projects and deadlines to gauge their actual capacity.","Collaborate on a solution. See if you can help them with any of their work, if the task can be broken down, or if the timeline can be adjusted.","If the analyst is genuinely at capacity and the deadline is firm, your responsibility is to the VP. You should escalate the situation professionally.","Inform the VP of the staffing conflict and ask for guidance on how to prioritize the projects. This shows you are solution-oriented and respect the team's structure."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview\nNew York office, First round"]},{"id":"q-2320","t":"beh","l":"Behavioral","s":90,"q":"How would you handle a situation where a client asks for information about another client of the firm that they are thinking of acquiring? What information could you give them so as to provide useful advice?","k":["Uphold Confidentiality: State clearly and firmly that you cannot share any confidential or non-public information about any other client, as it would be a serious ethical and legal breach.","Explain the 'Why': Briefly explain that this strict confidentiality is what protects all clients, including the one asking the question.","Pivot to Public Information: Reassure them that you can provide comprehensive and valuable advice based entirely on publicly available information (e.g., SEC filings, investor presentations, equity research).","Reinforce Your Value-Add: Emphasize that the firm's true value is in its ability to analyze this public data to provide unique strategic insights, valuation perspectives, and transaction advice."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Goldman Sachs Interview\nSuperday"]},{"id":"q-2321","t":"beh","l":"Behavioral","s":90,"q":"How would you go about building missing skills?","k":["Outline a concrete, multi-pronged approach. This should not be vague — show you have already started.","Technical skills: reference specific courses, certifications, or self-study programs you are using (e.g., Wall Street Prep, Breaking Into Wall Street, or advanced Excel/VBA training). Mention hours spent practicing model builds.","Deal knowledge: describe how you are actively reading deal announcements, press releases, and proxy filings to build familiarity with transaction structures and terminology.","On-the-job learning: emphasize your plan to maximize the summer internship or training program by seeking feedback early and often, volunteering for challenging assignments, and asking thoughtful questions of senior bankers.","Mentorship: mention that you are building relationships with alumni and current bankers who can serve as resources and sounding boards as you develop."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Goldman Sachs Interview\nSA 2026, First round"]},{"id":"q-2322","t":"beh","l":"Behavioral","s":90,"q":"Are you excited to wake up at 4 AM to pick up a call?","k":["This is a stress-test question designed to gauge whether you truly understand the lifestyle and are not romanticizing the role. Answer with measured confidence, not excessive enthusiasm that sounds disingenuous.","Acknowledge the reality directly: yes, you understand that live deals operate on the client's timeline and that urgent requests do not follow a 9-to-5 schedule. Being available when the team and client need you is part of the job.","Reference a comparable experience where you operated under similar conditions, such as early-morning calls during a prior internship, managing a time-zone difference on a project, or a period where you had to be consistently responsive outside normal hours.","Convey that what makes these moments manageable is the nature of the work itself. When you are engaged in a meaningful, high-impact transaction, the early call is not a burden but a reflection of the urgency and importance of what you are contributing to."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Goldman Sachs Interview\nSA 2026, Superday"]},{"id":"q-2323","t":"beh","l":"Behavioral","s":90,"q":"How do you think analytically?","k":["Describe your analytical process in concrete terms. A strong framework: (1) define the problem clearly, (2) break it into component parts, (3) gather and organize relevant data, (4) analyze the data to identify patterns and draw conclusions, (5) pressure-test your conclusions by considering counterarguments.","Provide a specific example that illustrates this process in action. Choose a situation from a prior role, academic project, or extracurricular where you used structured analytical thinking to solve a real problem.","Emphasize that your approach is both quantitative and qualitative. In banking, analytical thinking is not just about running numbers; it is about synthesizing data with strategic context to form a defensible recommendation.","Connect it to why this skill makes you well-suited for banking, where every pitch book, model, and client recommendation requires rigorous, structured analysis."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Goldman Sachs Interview\nSA 2025, First round"]},{"id":"q-2324","t":"beh","l":"Behavioral","s":90,"q":"Part 1: Tell me about a time you had to change your way of thinking for a project.\n\n\n\n\nPart 2: How painful was it to do this?","k":["Part 1: Changing Your Thinking (STAR Method)","Situation: Describe a project where your initial approach or assumption turned out to be wrong or suboptimal. Set the context briefly.","Task: Explain what needed to change and why. What new information, feedback, or evidence forced you to reconsider your original approach?","Action: Detail how you pivoted. Did you seek input from others, conduct additional research, or scrap your original framework entirely? Emphasize intellectual humility and adaptability.","Result: Describe the improved outcome that resulted from changing your approach. Quantify if possible.","Part 2: How Painful Was It?","Be honest but frame it constructively. Acknowledge that abandoning an approach you invested time in is genuinely difficult, especially under time pressure. However, explain that the discomfort was outweighed by the commitment to getting the right answer. In banking, being attached to a wrong assumption is far more costly than the pain of pivoting."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Goldman Sachs Interview\nSA 2027, Superday"]},{"id":"q-2325","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you worked on a long-term project. How did you stay motivated and manage your time?","k":["Structure your response using the STAR method. Choose a project that spanned weeks or months and required sustained effort.","Situation: Describe the project, its duration, and its significance. What made it a long-term commitment?","Task: Define your specific role and the deliverables you were responsible for over the course of the project.","Action: Explain your time management and motivation strategies. Strong examples: breaking the project into milestones with intermediate deadlines, tracking progress systematically, maintaining accountability through regular check-ins, and staying connected to the project's purpose during monotonous stretches. Mention how you balanced this project with other responsibilities.","Result: Describe the successful outcome and what you learned about sustaining performance over long time horizons. This is directly applicable to banking, where deals can take months and require consistent output throughout."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Goldman Sachs Interview\nSA 2027, Superday"]},{"id":"q-2326","t":"beh","l":"Behavioral","s":90,"q":"What are some of your favorite classes?","k":["Name a relevant finance/economics/quantitative class and why it was engaging (e.g., foundational concepts, challenging analysis).","Mention another relevant class focusing on different skills (e.g., data analysis, strategy) and its value.","Optionally, name a non-major class that broadened your perspective and explain its appeal.","Connect enjoyment to skill development or intellectual curiosity relevant to banking."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Greenhill & Co. Interview"]},{"id":"q-2327","t":"beh","l":"Behavioral","s":90,"q":"Discuss a time when you found a mistake in a group project that wasn't yours. What did you do? What would you do differently?","k":["Situation: Group project context, identified error in peer's work.","Action: Verified error, approached peer privately/respectfully, focused on collaborative fix, not blame.","Result: Mistake corrected, team relationship maintained.","Differently: Suggest implementing earlier cross-checking or peer review process in future team projects."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Greenhill & Co. Interview"]},{"id":"q-2328","t":"beh","l":"Behavioral","s":90,"q":"What makes you stand out from other candidates?","k":["Factor 1: Unique skill combination (e.g., strong quant + practical problem-solving).","Factor 2: Demonstrated initiative (cite specific examples: certifications, club leadership, networking relevant to Greenhill).","Factor 3: Key qualities (e.g., resilience, coachability, proven through specific experiences).","Conclude by stating this combination makes you a strong, quick contributor to their team."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Greenhill & Co. Interview"]},{"id":"q-2329","t":"beh","l":"Behavioral","s":90,"q":"Walk me through a deep dive of one of the additional interests on your resume.","k":["Choose a genuine interest you can speak about with passion and depth.","Structure your response:","1. Briefly introduce the interest and how you got involved.","2. Provide specific details demonstrating commitment and knowledge.","3. Conclude by connecting 1-2 positive traits from this interest (e.g., discipline from a sport, creativity from music, strategic thinking from chess) to skills valuable in investment banking.","This shows you are a well-rounded person who pursues excellence outside of work."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Greenhill & Co. Interview\nM&A group, First round"]},{"id":"q-2330","t":"beh","l":"Behavioral","s":90,"q":"What were your grades during your first semester? What percentile would you estimate you are in, and where do you think you stand compared to your classmates?","k":["Be direct and honest. State your grades or GPA clearly.","When discussing your standing, be confident but not arrogant. If you have done well, you can state, \"Based on my performance, I believe I am in the top quartile of my class.\"","If your grades were not ideal, be prepared to briefly explain any context (e.g., adjustment to college, difficult course load) and, more importantly, highlight a strong upward trend in subsequent semesters.","Regardless of your rank, connect it to a strong work ethic and a drive for excellence, qualities essential for banking."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Guggenheim Partners Interview\nNew York Office, Superday"]},{"id":"q-2331","t":"beh","l":"Behavioral","s":90,"q":"How would you manage analysts, differentiating between brand new and experienced analysts?","k":["For new analysts: Focus on providing clear, detailed instructions, foundational training, and regular check-ins to ensure they are on the right track and to answer questions.","The goal for new analysts is to build their core technical skills and confidence.","For experienced analysts: Provide greater autonomy and more complex responsibilities. Focus on their career development by giving them exposure to clients and different parts of a transaction.","The goal for experienced analysts is to prepare them for the next level by empowering them to take ownership."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Guggenheim Partners Interview\nNew York Office, Pre-MBA"]},{"id":"q-2332","t":"beh","l":"Behavioral","s":90,"q":"You realize there is a mistake in a presentation that has already been sent to a client. What do you do?","k":["Act with urgency and take immediate ownership.","Step 1: Immediately notify your direct superior (e.g., Associate or VP), clearly explaining the mistake and its potential impact.","Step 2: Simultaneously work to correct the error and prepare a revised version of the presentation.","Step 3: Follow your superior's direction on how to communicate the correction to the client, which typically involves sending the updated version with a brief, professional note of explanation."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Guggenheim Partners Interview\nNew York Office, Pre-MBA"]},{"id":"q-2333","t":"beh","l":"Behavioral","s":90,"q":"What is the most difficult thing you have ever done?","k":["Choose a significant academic, professional, or personal challenge that required substantial effort and perseverance to overcome.","Use the STAR method: Describe the situation and the difficulty of the task.","Detail the specific actions you took over time to address the challenge.","Conclude with the positive result and, more importantly, the personal growth or skills you developed through the process."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Guggenheim Partners Interview\nNew York Office, Pre-MBA"]},{"id":"q-2334","t":"beh","l":"Behavioral","s":90,"q":"If you were to receive an offer from us and could ask for three things to ensure your success, what would they be?","k":["Focus your requests on resources for growth and contribution, not on compensation or perks.","1. Mentorship: Request a dedicated mentor who can provide guidance and support as you navigate the firm.","2. Exposure: Ask for the opportunity to work on a variety of transactions and with different teams to accelerate your learning.","3. Feedback: Express a desire for consistent and constructive feedback to help you develop your skills and contribute effectively."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Guggenheim Partners Interview\nNew York Office, Pre-MBA"]},{"id":"q-2335","t":"beh","l":"Behavioral","s":90,"q":"You open your computer and have 200 emails and three Managing Directors each asking you for something. How do you handle it?","k":["First, do a rapid triage of the 200 emails: scan subject lines and senders to identify anything urgent or time-sensitive, flagging client-facing deadlines and requests from senior bankers.","For the three MD requests, assess each one's urgency and complexity. Determine which deliverables have hard deadlines and which have flexibility.","Communicate proactively: reach out to each MD to confirm the priority and expected timeline for their request. This prevents assumptions and shows professionalism.","Execute in priority order, starting with the most time-sensitive deliverable. If there is a genuine conflict where you cannot meet all three deadlines, escalate to your VP or a senior associate to help coordinate resourcing."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Harris Williams Interview\nSA 2026, Superday"]},{"id":"q-2336","t":"beh","l":"Behavioral","s":90,"q":"What do you know about Houlihan Lokey?","k":["Begin by acknowledging its strong reputation as a leading global investment bank, particularly known for its middle-market focus.","Highlight its key business areas, mentioning its top-ranked M &A advisory practice and its world-class Financial Restructuring group, which is consistently ranked #1. Also, mention its Financial and Valuation Advisory Services.","Show deeper knowledge by mentioning its industry expertise in specific sectors that interest you. Referencing a recent, notable transaction shows you are actively following the firm.","If you've spoken with anyone from the firm, mention your positive impressions of the culture—often described as entrepreneurial, collegial, and highly analytical."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Houlihan Lokey Interview\nNew York Office"]},{"id":"q-2337","t":"beh","l":"Behavioral","s":90,"q":"How will you make a decision on which firm to join?","k":["Outline your key decision criteria, focusing on people, culture, deal experience, and learning opportunities.","People: Emphasize the importance of working with smart, collaborative, and supportive individuals who you can learn from.","Culture: Mention your desire for a specific environment (e.g., collegial, high-energy, intellectually rigorous).","Experience: Talk about the quality and type of deal flow, sector focus, and the level of responsibility given to junior bankers.","Conclude by tailoring your answer, explaining how Houlihan Lokey aligns with these criteria based on your research and conversations."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Houlihan Lokey Interview\nCFR group, Second round"]},{"id":"q-2338","t":"beh","l":"Behavioral","s":90,"q":"How do you learn?","k":["Start with foundational understanding (reading, lectures).","Apply concepts through practice (problems, projects, modeling).","Seek feedback and iterate (ask questions, refine based on input).","Reinforce understanding (summarize, explain to others).","Highlight adaptability and proactive approach to learning."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview"]},{"id":"q-2339","t":"beh","l":"Behavioral","s":90,"q":"Recommend a movie to me.","k":["Choose a movie you genuinely like and can speak about articulately. Avoid anything overly obscure, simplistic, or controversial.","Provide a very brief, one-sentence summary of the premise.","Explain *why* you are recommending it. Focus on what makes it compelling—perhaps its clever storytelling, interesting themes, or a particularly strong performance.","The goal is to demonstrate your ability to communicate clearly, articulate a point of view, and show that you are a well-rounded person."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nChicago office, Superday"]},{"id":"q-2340","t":"beh","l":"Behavioral","s":90,"q":"Recommend a book you have read recently.","k":["Select a book (fiction or non-fiction) that you can discuss intelligently. A non-fiction book related to business, economics, or strategy can be a strong choice, but any thoughtful book is acceptable.","Give a concise, one-sentence overview of the book's main idea or plot.","Explain your key takeaway or why you found it compelling. What insight did you gain? What did it make you think about?","This question assesses your intellectual curiosity and your ability to synthesize information and form an opinion."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nChicago office, Superday"]},{"id":"q-2341","t":"beh","l":"Behavioral","s":90,"q":"Are we your first choice and why or why not? Other candidates have shared that we are their first choice, so why should we give the offer to you?\n\n\n\n\nTalk through competitor banks and your thought process. How quickly would you accept our offer and how many days would you need to think it over?","k":["This is a stress test; remain calm and confident. Acknowledge their position without being defensive.","Reiterate your strong interest in J.P. Morgan with specific reasons (deal flow, platform, culture). If they are your top choice, state it clearly. If not, be diplomatic, emphasizing they are in your top tier of interest.","Differentiate yourself by highlighting a unique combination of skills, experiences, or perspectives that you bring.","When discussing competitors, provide a structured and analytical comparison, focusing on factors like culture, deal flow, and career development, showing you've done your homework.","Provide a professional and reasonable timeframe for your decision (e.g., \"I would be prepared to make a decision within the standard timeframe allotted\"), showing you are decisive but not reckless."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nChicago office, Superday"]},{"id":"q-2342","t":"beh","l":"Behavioral","s":90,"q":"Do you think there is an error on your resume?\n\n\n\n\nFollow-up 1: How sure are you? How much money would you bet?","k":["This is a test of your confidence and attention to detail. Maintain composure and be firm in your response.","State confidently that you have meticulously reviewed your resume and are certain it is accurate.","For the follow-up, handle it gracefully. You can state a high number metaphorically to show conviction (e.g., \"I'm as confident as one can be\") or politely decline to gamble on a certainty.","The goal is to show you are not easily rattled by pressure and stand behind your work."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nChicago office, Superday"]},{"id":"q-2343","t":"beh","l":"Behavioral","s":90,"q":"If you were to choose one person in the office to advocate for you, who would you choose and why?","k":["Choose an interviewer with whom you felt you had a strong connection or a particularly insightful conversation.","State their name clearly (it's crucial to remember your interviewers' names).","Justify your choice by referencing a specific part of your conversation. For example, \"I would choose [Interviewer's Name] because we had an in-depth discussion about [topic], and I feel they gained a clear understanding of my analytical approach and passion for the industry.\""],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nChicago office, Superday"]},{"id":"q-2344","t":"beh","l":"Behavioral","s":90,"q":"What is a secret of yours?","k":["Treat this as a creative behavioral question, not a request for a deep, personal secret.","Share something lighthearted, quirky, or a unique skill that is not on your resume but reflects a positive trait.","Example: \"My secret is that I'm a surprisingly good baker. I find the precision and chemistry of it to be a great way to de-stress, which I think shows my attention to detail and ability to follow a process.\"","The goal is to be memorable and personable while remaining professional."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nSuperday"]},{"id":"q-2345","t":"beh","l":"Behavioral","s":90,"q":"What's a recent book you read?\n\n\n\n\nFollow-up 1: Should we read it and why?","k":["Choose a book (non-fiction or fiction) that you can speak about intelligently and that reflects intellectual curiosity.","Briefly summarize the book's main theme or argument in a compelling way.","When recommending it, explain what makes it valuable. Focus on the perspective it offers, the insights it provides, or the way it challenges conventional thinking.","This is a chance to showcase your personality and ability to form and articulate a persuasive argument."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nChicago office, Superday"]},{"id":"q-2346","t":"beh","l":"Behavioral","s":90,"q":"If you could pick any person in history to have lunch with, who would you pick and why?","k":["Select a historical figure you genuinely admire and whose life or work is relevant to qualities like leadership, innovation, or strategy.","Clearly articulate why you chose this person, focusing on specific accomplishments or characteristics.","Prepare 2-3 insightful questions you would ask them. This demonstrates your intellectual curiosity and what you value.","Avoid overly common or cliché answers unless you have a very unique and compelling reason."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nChicago office, Superday"]},{"id":"q-2347","t":"beh","l":"Behavioral","s":90,"q":"What would be your biggest concern about joining J.P. Morgan?\n\n\n\n\nFollow-up 1: What would be our biggest concern about hiring you?","k":["Primary Question:","Frame your concern as a challenge you are eager to take on. For a large firm like J.P. Morgan, a good answer could be navigating the scale of the organization to build relationships or ensuring you get a broad range of experiences.","Show that you have thought about the realities of working at a bulge bracket firm.","Follow-up Question:","Choose a genuine, but manageable, weakness and explain how you are actively working to mitigate it.","Example: \"Given I don't come from a pure finance background, you might be concerned about my initial learning curve. However, I have proactively addressed this by [mentioning specific courses, self-study, or certifications] and have proven my ability to learn quickly in demanding environments.\""],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nNew York office"]},{"id":"q-2348","t":"beh","l":"Behavioral","s":90,"q":"Pick your favorite sport or hobby. Who's the greatest of all time in that sport or hobby?\n\n\n\n\nFollow-up 1: What is the analytical argument to support that?","k":["Choose a sport/hobby and a \"GOAT\" (Greatest Of All Time) that you can confidently discuss.","Structure your analytical argument with 3-4 clear points, using a mix of quantitative data (statistics, records) and qualitative factors (impact on the game, longevity, leadership).","This question tests your ability to build a logical, data-driven argument and articulate it persuasively, which is a core skill in banking."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nNew York office"]},{"id":"q-2349","t":"beh","l":"Behavioral","s":90,"q":"Who was the CEO of your old company?","k":["This is a straightforward factual question designed to test your attention to detail and awareness of your previous work environment.","Know the name of the CEO of every company listed on your resume.","State the name clearly and correctly. There is no need for additional elaboration unless prompted."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nNew York office"]},{"id":"q-2350","t":"beh","l":"Behavioral","s":90,"q":"Are you sure there's no mistake on your resume?\n\n\n\n\nFollow-up 1: How much are you willing to bet on that?","k":["This is a pressure test. Maintain composure and respond with calm confidence.","Reiterate that you have checked your resume thoroughly and are confident in its accuracy.","For the follow-up, avoid getting flustered. You can handle it with a touch of humor or by metaphorically expressing your certainty, for example, \"I'm confident enough that I wouldn't want to bet against it.\"","The goal is to demonstrate poise, not to actually place a bet."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nNew York office"]},{"id":"q-2351","t":"beh","l":"Behavioral","s":90,"q":"I see a lot of accomplishments on your resume. What is it that drives you?\n\n\n\n\nFollow-up 1: Expand on some examples of how this quality manifests itself outside of work.","k":["Primary Drivers:","Identify 2-3 core motivators that align with investment banking. Examples include the challenge of solving complex problems, the drive to achieve tangible results, a commitment to continuous learning, and the satisfaction of contributing to a high-performing team.","Outside Example:","Provide a concise, specific example from a hobby, sport, or volunteer activity that illustrates one of your stated drivers. For instance, if you are driven by achieving results, talk about the rigorous training regimen you followed to complete a marathon."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nNew York office, First round"]},{"id":"q-2352","t":"beh","l":"Behavioral","s":90,"q":"What are the main valuation methods you have used in the past, and how would you think about using them in the context of a transaction?","k":["List the primary valuation methodologies: Comparable Company Analysis, Precedent Transaction Analysis, and Discounted Cash Flow (DCF) Analysis.","Explain the context for each: Comps provide a view of current market sentiment, Precedents offer insight into M&A control premiums, and DCF provides an intrinsic value based on a company's future cash flows.","Emphasize that no single method is perfect. The key is to use them together to establish a valuation range and build a compelling narrative for the client, triangulating the different results to arrive at a conclusion."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nNew York office, First round, Lateral Associate"]},{"id":"q-2353","t":"beh","l":"Behavioral","s":90,"q":"Tell me about your upcoming summer internship. What do you think you will ACTUALLY be doing day-to-day?","k":["Demonstrate a clear, realistic understanding of the analyst role.","Core Tasks: Expect to spend significant time on financial modeling, valuation analysis, company and industry research, and preparing presentations like pitch books.","Process: Mention supporting deal teams, taking notes, managing data rooms, and handling various ad-hoc requests from associates and VPs.","Environment: Acknowledge the long hours, intense deadlines, and steep learning curve, emphasizing your eagerness to learn quickly and contribute by producing accurate, reliable work."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nNew York office, Second round"]},{"id":"q-2354","t":"beh","l":"Behavioral","s":90,"q":"What do you think are the qualities of a good investment banker?","k":["Technical Skills: A strong foundation in finance, accounting, and valuation, coupled with exceptional quantitative and analytical abilities.","Work Ethic and Execution: High attention to detail, resilience to handle pressure and long hours, proactivity, and excellent time management.","Soft Skills: Strong communication and interpersonal skills for teamwork, coachability and a desire to learn, and unwavering integrity."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nNew York office, Second round"]},{"id":"q-2355","t":"beh","l":"Behavioral","s":90,"q":"How do you gain the trust of a client as an investment banker?","k":["At the junior level, trust is built primarily through flawless execution. Consistently delivering accurate, thoughtful, and timely work shows reliability.","Develop deep knowledge. Becoming an expert on the client's company and industry demonstrates commitment and adds value.","Maintain absolute integrity and confidentiality. This is the bedrock of any client relationship.","Be proactive. Anticipating the client's or your senior banker's next question shows you are thinking ahead and are deeply engaged."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nNew York office, Second round"]},{"id":"q-2356","t":"beh","l":"Behavioral","s":90,"q":"What courses are you taking this semester, and what were some notable courses you took last semester?","k":["Be prepared to list 2-3 courses from the current and previous semesters honestly.","Highlight any finance, economics, or quantitative courses that are directly relevant to banking.","For one or two courses, briefly mention a key concept or project that you found particularly interesting or challenging.","Show genuine intellectual curiosity and an ability to connect academic learning to professional interests."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nNew York Office, First round"]},{"id":"q-2357","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you had to step up in a team and succeeded.","k":["Situation: Describe a team project that was facing a challenge, such as a lack of direction, a looming deadline, or an unexpected obstacle.","Task: Explain why leadership was needed and what the team's ultimate goal was.","Action: Detail the specific leadership actions you took, such as organizing a plan, motivating team members, delegating tasks, or taking on a difficult part of the project yourself.","Result: Describe how your actions helped the team overcome the challenge and achieve its goal. Mention what you learned about leadership."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nSA 2025"]},{"id":"q-2358","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you were working in a team and produced a poor quality product.","k":["Situation: Be honest and describe a team project where the final output did not meet the required standards.","Task: Explain what the team was supposed to achieve and where the product fell short.","Action: Take ownership of your role in the failure. Analyze and explain the root causes (e.g., poor communication, lack of planning, flawed analysis) without blaming teammates.","Result/Learning: Crucially, explain what you learned from the experience and how you applied those lessons to ensure a better outcome on a subsequent project."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nSA 2025"]},{"id":"q-2359","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you faced a situation that challenged your ethics or morals.","k":["Situation: Clearly and concisely describe a situation where there was a conflict between the 'easy' choice and the 'right' choice.","Task: Explain the ethical dilemma and the pressure you may have felt.","Action: Detail the steps you took to make the ethical decision. This could involve adhering to rules, refusing a request, or escalating the issue.","Result: Describe the outcome and reaffirm your unwavering commitment to integrity, regardless of the difficulty."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nSA 2025"]},{"id":"q-2360","t":"beh","l":"Behavioral","s":90,"q":"A client asks you to reach out to more potential buyers, despite an exclusivity agreement already being signed with one buyer. How do you proceed?","k":["Immediately recognize the serious legal, financial, and reputational risks of breaching a signed exclusivity agreement.","State clearly that you cannot and would not violate the agreement. Your primary duty is to act ethically and protect the firm.","Explain that you would immediately and privately escalate the client's request to your senior team members (VP, MD).","The senior banker should then communicate with the client, reinforcing the legal obligations of the exclusivity agreement and advising against a breach.","Focus on managing the client's concerns by discussing the current deal's status and preparing for the next steps should the exclusivity period end without a transaction."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in J.P. Morgan Interview\nSecond round"]},{"id":"q-2361","t":"beh","l":"Behavioral","s":90,"q":"Why should we choose you over other candidates? You cannot use the word \"leader\" in your answer.","k":["Identify 2-3 distinctive qualities that set you apart — a unique combination of experiences, technical skills, or perspectives that other candidates are unlikely to share.","Back each quality with a specific example. For instance: your prior work experience gave you exposure to live transactions, your quantitative background enables you to build complex models efficiently, or your ability to communicate complex ideas clearly sets you apart.","Emphasize your work ethic and reliability — you are someone who consistently delivers high-quality work on time and takes ownership of your responsibilities.","Conclude with conviction: you bring a combination of analytical rigor, coachability, and genuine passion for the work that will translate directly into value for the team from day one."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in J.P. Morgan Interview\nSA 2027"]},{"id":"q-2362","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time when you contributed to or navigated a situation involving diversity.","k":["Use the STAR method. Situation: Select an experience where you worked within a diverse team or actively contributed to an inclusive environment, such as a group project with members from different backgrounds or a leadership role in a diversity-focused organization.","Task: Describe the specific challenge or goal, such as bridging differing perspectives to reach a consensus, or creating an initiative to improve inclusion.","Action: Detail the concrete steps you took. Focus on active listening, seeking out underrepresented viewpoints, adapting your communication style, or organizing events that brought people together.","Result: Explain the positive outcome, whether it was a stronger team deliverable, a more inclusive culture, or a personal insight that changed how you approach collaboration. Connect this to the value of diverse perspectives in banking, where teams advise clients across industries and geographies."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in J.P. Morgan Interview\nSA 2027, New York Office, Superday"]},{"id":"q-2363","t":"beh","l":"Behavioral","s":90,"q":"What can you contribute on day one as an analyst/associate?","k":["Lead with your most transferable skills from prior experience. Identify 2-3 concrete capabilities you bring immediately: financial modeling, managing workstreams, reviewing deliverables for accuracy, or communicating effectively with senior stakeholders.","Reference a specific example from your past work that demonstrates you can hit the ground running. If you have built models, managed teams, or run processes in a high-pressure environment, say so.","Acknowledge the learning curve on firm-specific systems and processes, but frame it as something you are prepared to tackle aggressively. Emphasize your ability to learn quickly and ask the right questions.","Close with your work ethic and attitude. On day one, you are the person who shows up early, asks for work, and does whatever the team needs to keep deals moving forward."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in J.P. Morgan Interview\nSA 2025"]},{"id":"q-2364","t":"beh","l":"Behavioral","s":90,"q":"What is your philosophy in life?","k":["Choose a concise, authentic philosophy that reflects traits valued in banking: discipline, intellectual curiosity, resilience, or a commitment to continuous improvement.","Briefly explain the origin of this philosophy, whether it came from a personal experience, a mentor, or a formative challenge. Keep it to one or two sentences of context.","Illustrate how this philosophy has guided your decisions in practice. For example, if your philosophy centers on relentless preparation, describe how it shaped your approach to a demanding academic or professional project.","Connect it to why you are drawn to investment banking. Demonstrate that your personal values align with the demands of the role, such as thriving under pressure, pursuing excellence in your work, and valuing teamwork."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in J.P. Morgan Interview\nSA 2027, SF Office, Superday"]},{"id":"q-2365","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you managed up and down.","k":["Use the STAR method. Situation: Describe a scenario where you were in a middle position — responsible for delivering results to a senior stakeholder while also coordinating or directing the work of others.","Task: Explain the specific deliverable and the competing demands from above and below.","Action (Managing Up): Describe how you communicated proactively with senior stakeholders — setting expectations, providing regular updates, flagging potential issues early, and presenting solutions rather than just problems.","Action (Managing Down): Describe how you guided, motivated, or supported junior team members — providing clear direction, breaking tasks into manageable pieces, checking their work, and offering constructive feedback.","Result: Describe the successful outcome and how the experience prepared you for the associate role, which inherently requires managing both upward (to VPs/MDs) and downward (to analysts)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Jefferies Interview\nSA 2026, First round"]},{"id":"q-2366","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you worked on a demanding project and had to balance accuracy and quality versus speed of delivery.","k":["Use the STAR method. Situation: Describe a high-pressure project where time constraints created tension between thoroughness and speed of delivery.","Task: Explain the deliverable and the competing demands — the need for precision versus the pressure to deliver on time.","Action: Walk through how you managed the trade-off. In banking, accuracy is non-negotiable — so describe how you prioritized the most critical elements, built in quality checks at key stages, and communicated with stakeholders about realistic timelines when needed.","Result: Describe the outcome — ideally, you delivered an accurate, high-quality product on time. Explain what you learned about managing quality under pressure and how that lesson applies to banking, where a single error in a model can have significant consequences."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Jefferies Interview\nSA 2026, First round"]},{"id":"q-2367","t":"beh","l":"Behavioral","s":90,"q":"Imagine you have a tight deadline for a presentation deck, but your analyst is stubborn and demands work-life balance to hang out with his girlfriend on the weekend. He also tells you that he will be leaving for private equity anyway. How do you handle that situation?","k":["Acknowledge the analyst's perspective calmly and professionally. Do not react emotionally or escalate to confrontation.","Have a direct, private conversation. Clearly communicate the urgency and importance of the deadline, the impact on the team and the client, and the expectation that the work needs to get done.","Offer to help: propose splitting the remaining work, identify specific tasks you can take on yourself, or negotiate a reasonable schedule (e.g., \"Can you complete X by Saturday morning so you still have your evening?\").","If the analyst remains uncooperative after a good-faith effort, escalate to your VP to align on next steps. Do not let the deliverable slip. As an Associate, your job is to ensure the work product gets delivered on time regardless of team dynamics.","Regarding the PE comment, do not engage with it. His future plans are irrelevant to the immediate obligation. Focus entirely on solving the problem at hand."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Jefferies Interview\nSA 2025, TMT group, SF Office, Superday"]},{"id":"q-2368","t":"beh","l":"Behavioral","s":90,"q":"Imagine you are staffed on a new deal that you have never handled before, and your VP texts you \"Do you have any questions for me?\" What do you want to ask?","k":["Ask about the overall timeline and key milestones: \"What is the expected timeline, and what are the critical deliverables in the first week?\"","Ask about the client and context: \"Can you give me a brief overview of the client, the strategic rationale, and where we are in the process?\"","Ask about team structure and resources: \"Who else is on the deal team, and are there prior materials or comparable precedent transactions I should review to ramp up quickly?\"","Ask about the VP's expectations for you specifically: \"What do you need from me first, and what is the best way for us to communicate on this deal?\" This shows you are organized, proactive, and focused on delivering efficiently from day one."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Jefferies Interview\nSA 2025, TMT group, SF Office, Superday"]},{"id":"q-2369","t":"beh","l":"Behavioral","s":90,"q":"How do you feel about the generalist platform for the internship?","k":["Express genuine enthusiasm for the generalist model. Frame it as a significant advantage: it allows you to gain exposure to multiple industry groups and product teams before committing to a specialization.","Mention that the generalist structure lets you make a more informed decision about your long-term focus area, which ultimately benefits both you and the firm.","Acknowledge any sector interests you have, but emphasize that you are genuinely open-minded. Say something like, \"While I have a strong interest in [sector], the generalist platform is appealing because I may discover a passion for a group I had not previously considered.\"","Close by referencing the learning opportunity. Working across groups builds a broader analytical toolkit and a wider internal network, both of which make you a more effective banker long-term."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Jefferies Interview\nSA 2026, Superday"]},{"id":"q-2370","t":"beh","l":"Behavioral","s":90,"q":"What about \"advising companies\" do you want to do? Is the appeal advising shareholders, the board, the CEO, or the owners?","k":["Be specific about what excites you. The interviewer is testing whether you have genuinely thought about what advisory work entails beyond surface-level talking points.","Articulate that in investment banking, you are ultimately advising the decision-makers, which could be the CEO and management team on strategic alternatives, the board on fiduciary obligations to shareholders, or the owners (including PE sponsors) on value creation and exit strategies.","Demonstrate nuance: the audience depends on the transaction type. In a sell-side M&A process, you are advising the board and shareholders on maximizing value. In a leveraged buyout, you are advising the sponsor on acquisition terms. In a restructuring, you may be advising creditors.","Anchor your answer in what genuinely appeals to you. If you are drawn to the strategic dialogue with management teams, say so. If you find the fiduciary analysis and shareholder value framework compelling, explain why. Specificity and conviction matter more than the \"right\" answer."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Jefferies Interview\nSA 2026, Superday"]},{"id":"q-2371","t":"beh","l":"Behavioral","s":90,"q":"What is a red flag on your resume?","k":["Identify something the interviewer might question, such as a gap in employment, a short stint at a company, a non-traditional background, or a low GPA in a particular semester. Do not choose something that undermines your candidacy entirely.","Address it head-on with honesty and maturity. Briefly explain the context without making excuses. For example, if you had a short tenure at a role, explain that the opportunity did not align with your long-term goals and you made a deliberate decision to redirect your career toward finance.","Pivot to what you learned from the experience and how it strengthened your candidacy. Demonstrate that you extracted value from even a suboptimal situation.","This question tests self-awareness and composure. The interviewer already sees the red flag; they want to see if you can address it directly, take ownership, and reframe it constructively."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Jefferies Interview\nSA 2026, First round"]},{"id":"q-2372","t":"beh","l":"Behavioral","s":90,"q":"What skills would make you succeed as an analyst?","k":["Analytical & Quantitative Skills: Ability to build models, perform valuation, and synthesize complex data.","Attention to Detail: Crucial for accuracy in all deliverables (models, presentations).","Work Ethic & Resilience: Capacity to work long hours, meet tight deadlines, and handle pressure effectively.","Communication Skills: Clear and concise verbal and written communication for internal and external interactions.","Proactivity & Coachability: Eagerness to learn, take initiative, and incorporate feedback quickly."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview"]},{"id":"q-2373","t":"beh","l":"Behavioral","s":90,"q":"What feedback did you receive at your last job?","k":["Start with 1-2 positive pieces of feedback, with brief examples of how you demonstrated those strengths.","Mention 1 area for constructive feedback or development, framing it as an ongoing learning process.","Explain specific steps you have taken to address that feedback and improve.","Demonstrate self-awareness and a commitment to continuous growth."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview"]},{"id":"q-2374","t":"beh","l":"Behavioral","s":90,"q":"How did you get your job?","k":["Provide a brief, chronological narrative of how you secured your previous role.","Mention key steps like networking, application process, and interviews.","Highlight any specific initiatives you took or unique aspects of your journey.","Conclude with how that experience prepared you for this role."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview"]},{"id":"q-2375","t":"beh","l":"Behavioral","s":90,"q":"Give me an example of a time you acted with integrity.","k":["Situation: Describe a scenario where an ethical dilemma or choice arose.","Action: Detail the steps you took to uphold integrity, even if it was difficult or inconvenient.","Result: Explain the positive outcome of your actions or the lesson learned about maintaining ethical standards.","Emphasize your commitment to honesty and transparency."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview"]},{"id":"q-2376","t":"beh","l":"Behavioral","s":90,"q":"Give me an example of a time you failed.","k":["Situation: Describe a genuine instance where you did not achieve your desired outcome or made a mistake.","Action: Explain your role in the failure and how you took responsibility for it.","Result/Learning: Articulate the key lessons you learned from the experience.","Demonstrate how you applied those lessons to improve performance or approach in subsequent situations."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview"]},{"id":"q-2377","t":"beh","l":"Behavioral","s":90,"q":"Are there any aspects of this job you would struggle with?","k":["Reframe \"struggle\" as anticipated challenges that you are prepared to proactively manage.","Example challenges: managing multiple urgent deliverables, the initial steep learning curve for proprietary systems, or maintaining perfection under extreme pressure.","Explain *how* you would approach these challenges (e.g., hyper-organization, seeking guidance, asking clarifying questions, prioritization).","Avoid expressing doubts about your fundamental capabilities or willingness to do the work."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview"]},{"id":"q-2378","t":"beh","l":"Behavioral","s":90,"q":"CEOs who are embarking on a strategic review could be described as 'vulnerable'. To what extent is it an investment banker's duty to hold their hand throughout this process?","k":["Acknowledge the CEO's vulnerability and the critical nature of strategic reviews.","Emphasize the banker's duty to act as a trusted, objective advisor.","Discuss the importance of clear communication, consistent guidance, and anticipating client needs throughout the complex process.","Highlight Lazard's independent advisory model as inherently better positioned to avoid conflicts of interest compared to Bulge Brackets with lending/trading arms.","Stress that the relationship is built on trust and ensuring the best outcome for the client, free from internal pressures."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview"]},{"id":"q-2379","t":"beh","l":"Behavioral","s":90,"q":"Can you demonstrate a more numerate side?","k":["Provide a specific example of a time you applied quantitative skills (e.g., financial modeling, data analysis, statistical project).","Detail the challenge, the numerical analysis you performed, and the insights or outcomes derived.","Quantify results where possible (e.g., \"improved efficiency by X%\", \"identified Y% discrepancy\").","Connect the example directly to the analytical demands of investment banking."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview"]},{"id":"q-2380","t":"beh","l":"Behavioral","s":90,"q":"Describe a role model who displays integrity.","k":["Choose a role model, whether personal or professional.","Describe specific actions or decisions they made that exemplify integrity.","Explain *why* these actions demonstrated integrity and how they influenced you.","Link their integrity to the values you seek in a professional environment."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview"]},{"id":"q-2381","t":"beh","l":"Behavioral","s":90,"q":"What strengths and weaknesses would your friends say you had?","k":["Strengths: Mention 1-2 genuine strengths your friends would cite (e.g., reliability, problem-solving, active listening, supportive).","Connect these to how they translate into professional value (e.g., reliability means meeting deadlines).","Weakness: State 1 genuine weakness (e.g., being overly self-critical, difficulty delegating initially).","Crucially, explain steps you are taking to mitigate or improve upon this weakness."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview"]},{"id":"q-2382","t":"beh","l":"Behavioral","s":90,"q":"Tell me about your 2 favorite classes. What did you find interesting, and what did you learn from them?","k":["Class 1 (Relevant): Choose a finance, accounting, or quantitative course. Explain a specific concept that you found intellectually stimulating and connect the skills learned (e.g., analytical rigor, valuation) directly to investment banking.","Class 2 (Broadening): Choose a class outside of your core major that highlights another strength (e.g., communication, strategic thinking, problem-solving). Explain what you learned and how it provides you with a more well-rounded perspective."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview\nNew York office"]},{"id":"q-2383","t":"beh","l":"Behavioral","s":90,"q":"Tell me about the evolution of your role at your previous firm in terms of managing analysts or junior colleagues.","k":["Show a clear progression of responsibility.","Start with informal mentorship and being a go-to person for questions.","Describe the transition to formal responsibilities, such as delegating specific tasks, reviewing work, and managing parts of a workstream.","Highlight your focus on developing junior talent by providing context, giving constructive feedback, and advocating for their involvement in meaningful work."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview\nNew York office, Second round, Lateral Associate"]},{"id":"q-2384","t":"beh","l":"Behavioral","s":90,"q":"Pick a favorite analyst. What would that analyst say about your strengths and weaknesses?","k":["Strengths: Choose qualities a good analyst would value. They might say you are approachable, provide clear instructions and context, are a patient teacher, and are fair in distributing work.","Weaknesses: Frame it constructively. The analyst might say you were initially too hands-on but learned to delegate more effectively, or that you have very high standards which pushes them, but can be demanding. Show self-awareness and growth."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview\nNew York office, Second round, Lateral Associate"]},{"id":"q-2385","t":"beh","l":"Behavioral","s":90,"q":"Tell me about an experience of working with a difficult analyst.","k":["Situation: Describe the context and the specific challenges the analyst presented (e.g., responsiveness, quality of work, attitude).","Action: Explain your approach. First, seek to understand the root cause through a private conversation. Provide specific, actionable feedback. Offer support and clarify expectations. If necessary, adjust your management style or the tasks assigned.","Result: Detail the outcome, focusing on any improvement in the analyst's performance or behavior. Emphasize your goal of developing team members while ensuring the project's success."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview\nNew York office, Second round, Lateral Associate"]},{"id":"q-2386","t":"beh","l":"Behavioral","s":90,"q":"What is something you didn't like about your prior job?","k":["Frame your answer positively by focusing on what you are seeking in your next role, rather than complaining about the past.","Choose a neutral factor, such as the desire for a steeper learning curve, more direct exposure to transactions, or a more team-oriented and fast-paced environment.","Avoid criticizing former colleagues, managers, or the company itself.","Example: \"While I valued my experience, I'm now looking for a role with greater analytical depth and direct involvement in strategic transactions, which is what excites me about investment banking at Lazard.\""],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview\nFIG group, First round"]},{"id":"q-2387","t":"beh","l":"Behavioral","s":90,"q":"What is something that surprised you about the school you attend(ed)?","k":["Choose a genuine and positive surprise. This is a chance to show reflection and a positive attitude.","Focus on an academic, cultural, or resource-related aspect.","Examples: The unexpected level of collaboration among students, the accessibility of renowned professors, or the depth of a particular academic program.","Briefly explain your initial expectation and how the reality exceeded it, shaping your experience for the better."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview\nFIG group, First round"]},{"id":"q-2388","t":"beh","l":"Behavioral","s":90,"q":"What was your least favorite class?","k":["Choose a non-essential class, avoiding subjects core to your major or finance.","Frame the answer constructively. Explain *why* it was a challenge (e.g., the subject matter was less intuitive, the teaching style wasn't a fit) rather than simply saying you disliked it.","Crucially, focus on what you did to overcome the challenge and what you learned from the experience, such as developing a new study method or the importance of perseverance.","This demonstrates self-awareness and a growth mindset."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview\nFIG group, First round"]},{"id":"q-2389","t":"beh","l":"Behavioral","s":90,"q":"A CEO thinks their company is undervalued. How would you approach this conversation?","k":["Begin with empathy. Acknowledge and validate the CEO's perspective, as they know their business intimately.","Transition to a data-driven approach. Offer to walk through the valuation analysis (Comps, Precedents, DCF) to bridge the gap between their view and the market's perception.","Focus on assumptions. Discuss the key drivers in the model and where they might differ from the CEO's internal projections.","Explore qualitative factors that may not be fully captured in the numbers (e.g., management strength, IP, strategic positioning).","Conclude by shifting the conversation to actionable strategies to enhance and demonstrate value to the market."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview\nFIG group, First round"]},{"id":"q-2390","t":"beh","l":"Behavioral","s":90,"q":"What from your background will be most applicable to this role?","k":["Identify 3-4 key transferable skills and qualities from your resume.","Go beyond just listing them. For each skill, provide a brief, concrete example from your experience.","Focus on skills core to banking:","1. Analytical rigor (e.g., a complex research project).","2. Attention to detail (e.g., proofreading critical documents).","3. Work ethic/resilience (e.g., balancing a heavy course load with a job).","4. Teamwork (e.g., a successful group project).","Explicitly connect each skill to the demands of an analyst role."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lazard Interview\nPEI group, First round"]},{"id":"q-2391","t":"beh","l":"Behavioral","s":90,"q":"A junior team member made a mistake. How would you share that with a senior?","k":["First, assess and understand the mistake yourself. Before escalating, confirm the nature and impact of the error so you can present the issue clearly and propose a solution.","Approach the senior banker promptly and transparently. Do not try to hide the mistake or delay the conversation. In banking, senior bankers want to know about issues early, while there is still time to fix them.","Present the situation objectively: explain what happened, the potential impact, and the corrective steps you have already taken or plan to take. Avoid throwing the junior team member under the bus. Frame it as a team issue, not an individual failing.","Take responsibility as the Associate overseeing the work. Ultimately, it is your job to quality-control the team's output. Acknowledging this responsibility builds trust with senior bankers.","After the issue is resolved, debrief privately with the junior team member. Use it as a constructive coaching moment to help them understand the error and prevent recurrence."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Lazard Interview\nSA 2025, Healthcare group, SF Office, Superday"]},{"id":"q-2392","t":"beh","l":"Behavioral","s":90,"q":"What are the two most important skills you've developed in a prior role?","k":["Choose one \"hard\" skill and one \"soft\" skill that are highly relevant to investment banking.","Hard Skill Example: Financial analysis or quantitative problem-solving. Briefly describe a project where you used this skill and the outcome.","Soft Skill Example: Project management or communication. Provide an example of leading a team, managing a deadline, or presenting complex information clearly.","For each skill, explain not just what you did, but also why it's crucial for success as an analyst."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Lincoln International Interview\nFirst round"]},{"id":"q-2393","t":"beh","l":"Behavioral","s":90,"q":"Part 1: What is an activity outside of work or school you are working on, and what is your progress?\n\n\n\n\nPart 2: What would cause you to not pursue an interest outside of work?","k":["Part 1: Outside Activity","Choose an activity that demonstrates discipline, passion, or intellectual curiosity. Examples include training for a marathon, learning a new language, building an investment portfolio, or volunteering in a leadership capacity.","Be specific about your progress. State where you started, where you are now, and what your goal is. Measurable progress shows follow- through and drive.","Briefly explain why this activity matters to you and what it reveals about your character.","Part 2: What Would Stop You","Be honest but thoughtful. The interviewer is assessing whether you understand work-life trade-offs in banking.","A strong answer: you would not abandon the pursuit entirely, but you would adjust the pace if professional demands required full attention during a critical period (e.g., live deal execution). This shows maturity and prioritization skills without suggesting you have no outside identity."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Lincoln International Interview\nSA 2025, Superday"]},{"id":"q-2394","t":"beh","l":"Behavioral","s":90,"q":"Tell me about your internship experience last summer and a particular deal you worked on.","k":["Briefly outline the firm, group, and overall internship responsibilities.","Introduce a specific deal (anonymize if necessary): type, industry, your role.","Detail 2-3 key tasks you performed on that deal (e.g., modeling, research, deck prep).","Highlight a specific action or contribution you made and the outcome or what you learned."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in M. Klein & Co. Interview"]},{"id":"q-2395","t":"beh","l":"Behavioral","s":90,"q":"What other recruiting processes are you involved in, and what deadlines do you have if any?","k":["Acknowledge you are exploring opportunities at comparable firms.","Reiterate strong interest in this specific firm, citing 1-2 tailored reasons (culture, deals, people).","State your current status and any concrete deadlines transparently.","Emphasize this firm is a top choice (if true)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in M. Klein & Co. Interview"]},{"id":"q-2396","t":"beh","l":"Behavioral","s":90,"q":"What do you do for fun?","k":["Mention 2-3 specific activities (sports, creative pursuits, social activities).","Briefly explain why you enjoy them.","Keep it concise and appropriate for a professional context.","Convey balance and personality."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in M. Klein & Co. Interview"]},{"id":"q-2397","t":"beh","l":"Behavioral","s":90,"q":"What song would you sing at karaoke?","k":["Choose a song you genuinely enjoy and can speak about with enthusiasm. The specific song matters less than your ability to explain the choice with personality.","Pick something recognizable and crowd-pleasing rather than overly obscure or controversial.","Briefly explain why — perhaps it is a song that always energizes you, has a personal memory attached, or is just fun to sing. Show some personality.","The point of this question is to assess whether you are personable, confident, and someone people would enjoy spending long hours with. Be authentic and light-hearted."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Marathon Capital Interview\nSA 2025, Superday"]},{"id":"q-2398","t":"beh","l":"Behavioral","s":90,"q":"What place would you most like to travel to, and why?","k":["Choose a specific destination and explain your reasoning with genuine enthusiasm — what draws you to this place? History, culture, nature, architecture, cuisine?","Provide enough detail to show you have thought about it beyond a surface level. Mention something specific you would want to see or experience there.","This is a personality question designed to assess whether you are an interesting, curious person. Be authentic and show that you have interests outside of finance.","Keep it concise — two to three sentences of genuine enthusiasm is sufficient. Do not over-explain."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Marathon Capital Interview\nSA 2025, Superday"]},{"id":"q-2399","t":"beh","l":"Behavioral","s":90,"q":"You come into the office, and your associate is missing – you cannot call him or speak to him. You have questions about starting a deliverable due very soon because you have never done one before. What do you do?","k":["Assess Urgency & Check Resources: Confirm deadline, check email/drive for instructions/templates.","Seek Precedent: Look for examples of similar deliverables on drive; ask nearby analysts.","Seek Targeted Help: If precedents insufficient, politely ask another Associate/VP/Sr Analyst for specific guidance or example (explain situation briefly).","Start Working: Begin deliverable based on available info, tackle known parts first.","Document: Note any assumptions made or questions for when your Associate returns."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Moelis & Co. Interview"]},{"id":"q-2400","t":"beh","l":"Behavioral","s":90,"q":"If you are in a sell-side engagement with a client and you had to create a pitchbook for a client meeting what things would you add in the pitchbook?","k":["Executive Summary: High-level overview of the company, investment highlights, and transaction rationale.","Company Overview: Detailed description of the business, operations, management team, and market position.","Industry Analysis: Market trends, competitive landscape, growth drivers, and challenges.","Valuation Analysis: Summary of valuation methodologies (e.g., precedent transactions, comparable companies, DCF) and derived valuation ranges.","Potential Buyers: A list of strategic and financial buyers, with rationale for their interest.","Transaction Process & Timeline: Proposed steps, key milestones, and anticipated timeline for the sale.","Team Bios: Introductions to the advisory team members."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Moelis & Co. Interview"]},{"id":"q-2401","t":"beh","l":"Behavioral","s":90,"q":"Why should we pick you over a similar candidate with background in an undergraduate business school like Wharton or Stern?","k":["Acknowledge the strong backgrounds of other candidates.","Highlight unique strengths from your background (e.g., diverse academic perspective, specific project experience not common in business schools, exceptional problem-solving from your field).","Emphasize transferable skills like analytical rigor, intellectual curiosity, resilience, and a proven ability to learn quickly.","Express high motivation and a strong commitment to learning and contributing immediately, despite the non-traditional background.","Focus on your unique value proposition rather than denigrating others."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Moelis & Co. Interview"]},{"id":"q-2402","t":"beh","l":"Behavioral","s":90,"q":"Where does Moelis stand in your process?\n\n\n\n\nFollow-up 1: How do you make a decision on the bank you are going to join?","k":["Primary Question:","Be honest but diplomatic. Express that Moelis & Co. is a top choice for you.","Reinforce your interest with specific reasons, such as the firm's strong deal flow, lean team structure, and entrepreneurial culture.","Follow-up Question:","Outline a structured decision-making framework based on key factors.","Mention the quality of people and culture as a primary consideration.","Also include the quality of the learning experience (deal exposure, level of responsibility) and the firm's platform and reputation."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Moelis & Co. Interview\nChicago office, First round"]},{"id":"q-2403","t":"beh","l":"Behavioral","s":90,"q":"For associate interviews: what are the things you have done or will do at your MBA program that will prepare you for the associate job?","k":["Structure your answer around three pillars: academics, extracurricular activities, and recruiting/networking.","Academics: Mention specific, relevant coursework like Corporate Finance, Valuation, and M&A.","Extracurriculars: Highlight leadership roles in the investment banking or finance club, participation in case competitions, and any relevant projects.","Preparation: Discuss your proactive networking with alumni, attending firm information sessions, and dedicated technical preparation."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Moelis & Co. Interview\nChicago office, Superday"]},{"id":"q-2404","t":"beh","l":"Behavioral","s":90,"q":"What's the day-to-day job like as an associate?","k":["Demonstrate a clear understanding of the step-up in responsibility from the analyst role.","Key responsibilities include managing and mentoring analysts, taking ownership of financial models and presentations, and serving as the day-to-day project manager on deals.","Mention increased client interaction and supporting VPs and MDs in executing transactions and sourcing new business.","Emphasize the role's focus on both execution and team management."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Moelis & Co. Interview\nChicago office, Superday"]},{"id":"q-2405","t":"beh","l":"Behavioral","s":90,"q":"If you were given $1M today, how would you think about paying off your student loan vs. investing in a certain stock?\n\n\n\n\nFollow-up 1: If you'd invest in a stock, which would you pick?","k":["Primary Question:","Structure your answer as a financial analysis. Compare the interest rate on the student loan (a guaranteed, risk-free return if paid off) with the expected risk-adjusted return from investing in the market.","Mention other factors like the tax deductibility of student loan interest and your personal risk tolerance.","A sound conclusion would be to pay off high-interest debt and invest the remainder.","Follow-up Question:","Present a concise stock pitch. Start with a brief company overview.","Provide a clear investment thesis with 2-3 key drivers.","Mention valuation, briefly touching on key metrics and why the stock is attractively priced.","Conclude with potential catalysts and risks."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Moelis & Co. Interview\nChicago office, Superday"]},{"id":"q-2406","t":"beh","l":"Behavioral","s":90,"q":"How do you think about our model compared to a bulge bracket for your career?","k":["Demonstrate your understanding of the elite boutique model (e.g., Moelis & Co.) versus the bulge bracket model.","Highlight the advantages of the boutique model that appeal to you: leaner deal teams leading to more responsibility, direct exposure to senior bankers and clients, and a pure-advisory focus without the conflicts of a balance sheet.","Contrast this with the bulge bracket's strengths (global brand, broad product offering) but frame your preference for the boutique model as a better fit for your specific career goals of rapid learning and hands-on experience."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Moelis & Co. Interview\nChicago office, Superday"]},{"id":"q-2407","t":"beh","l":"Behavioral","s":90,"q":"Discuss a project you worked on with a high degree of quantitative rigor. Describe your role on this project.","k":["Situation: Describe the project and its objective, emphasizing why a quantitatively rigorous approach was necessary.","Task: Clearly define your specific role and the analytical responsibilities you were assigned.","Action: Detail the specific quantitative methods you used (e.g., financial modeling, statistical analysis, data science techniques). Explain your process and how you ensured accuracy.","Result: Explain the insights or conclusions derived from your analysis and how they contributed to the project's success or informed a key decision."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Moelis & Co. Interview"]},{"id":"q-2408","t":"beh","l":"Behavioral","s":90,"q":"Why do you want to do technology investment banking?","k":["Express genuine interest in the dynamic, innovative nature of the technology sector.","Connect this interest to personal experiences (coursework, news, prior roles).","Explain why advising tech companies on strategic finance (M&A, capital raising) is appealing.","Mention specific reasons for targeting Morgan Stanley's TMT group (deal flow, reputation, people)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview"]},{"id":"q-2409","t":"beh","l":"Behavioral","s":90,"q":"Who is your favorite CEO and why?","k":["Name a specific CEO.","Highlight 1-2 key strategic decisions or initiatives they led.","Explain the positive impact of these actions (financial, cultural, market position).","Mention specific leadership qualities demonstrated (e.g., vision, execution, adaptability)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview"]},{"id":"q-2410","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time working with a difficult person.","k":["Situation: Context of the team and project.","Difficult Behavior: Describe the specific actions objectively (unresponsive, missed deadlines, etc.).","Action: Detail your approach - attempt direct/private communication, maintain professionalism, focus on task completion, coordinate with others to ensure goals met.","Result: Explain how the situation was managed, the project outcome, and lessons learned about handling difficult team dynamics."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview"]},{"id":"q-2411","t":"beh","l":"Behavioral","s":90,"q":"What are you most concerned about regarding banking?","k":["Reframe 'concern' as 'challenge to manage proactively'.","Focus on aspects like: Maintaining high performance/accuracy long-term under pressure.","Or: Effectively managing workload and time for sustainable contribution.","Or: Integrating intense work demands with personal well-being.","Briefly mention approach: efficiency, seeking advice, discipline.","Avoid expressing doubts about willingness or core ability."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview"]},{"id":"q-2412","t":"beh","l":"Behavioral","s":90,"q":"Coming from a non-finance background, what skills have you developed that are applicable to this role?","k":["Skill 1: Analytical Rigor / Problem Solving (Example from your field , i.e. Financial analysis).","Skill 2: Quantitative Aptitude (Example from your field, i.e. Modeling/Valuation capacity).","Skill 3: Attention to Detail (Example from your field, i.e. Accuracy in banking).","Skill 4: Research / Info Synthesis (Example from your field, i.e. Industry/Company research).","Skill 5: Learning Agility (Example from your field, i.e. Mastering banking concepts).","Mention self-study efforts to bridge technical finance gap."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview"]},{"id":"q-2413","t":"beh","l":"Behavioral","s":90,"q":"What does an Investment Banking Analyst do, and why do you think you can be good at it?","k":["Analyst Role:","Core Tasks: Financial modeling, valuation analysis (Comps, Prec, DCF), industry/company research, preparing client materials (pitch books, CIMs).","Purpose: Support senior bankers in transaction execution (M&A, capital raising).","Why You'll Be Good:","Highlight relevant skill 1 (e.g., Analytical ability with example).","Highlight relevant skill 2 (e.g., Attention to detail with example).","Highlight relevant quality 3 (e.g., Work ethic/resilience with example).","Highlight relevant quality 4 (e.g., Eagerness to learn/team player).","Express confidence and link to the firm (Morgan Stanley)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview"]},{"id":"q-2414","t":"beh","l":"Behavioral","s":90,"q":"What's one thing about you that's not on your resume?","k":["Share a brief, positive anecdote or characteristic not immediately obvious from your resume.","It could be a unique hobby, a surprising talent, a personal challenge overcome, or a specific value.","Ensure it subtly reveals a positive trait relevant to work (e.g., curiosity, resilience, creativity, commitment).","Keep it concise and professional."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview"]},{"id":"q-2415","t":"beh","l":"Behavioral","s":90,"q":"What do you do outside of work?","k":["Mention 2-3 genuine hobbies or activities you enjoy.","Briefly explain what you like about each or what they involve.","Show that you are a well-rounded individual with interests beyond academics/work.","Keep it professional and avoid anything controversial or requiring extensive explanation."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview"]},{"id":"q-2416","t":"beh","l":"Behavioral","s":90,"q":"Tell me a time about you being a leader.","k":["Situation: Describe a scenario where you took on a leadership role or demonstrated leadership qualities.","Task: Outline the objective or challenge the team faced.","Action: Detail your specific actions as a leader (e.g., setting vision, motivating team, delegating tasks, resolving conflicts, leading by example).","Result: Explain the positive outcome achieved by your leadership and what you learned about effective leadership."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview"]},{"id":"q-2417","t":"beh","l":"Behavioral","s":90,"q":"Why you? What makes you better than the other tens of thousands of applicants?","k":["Acknowledge the strong competition and respect for other candidates.","Highlight 2-3 key unique selling points that differentiate you (e.g., a specific combination of analytical rigor and communication skills, unique experience with a relevant industry, exceptional resilience).","Provide concise evidence for each point.","Emphasize your strong fit with Morgan Stanley's culture and values, and your genuine passion for investment banking.","Conclude by confidently stating your ability to contribute immediately and significantly to the team."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview"]},{"id":"q-2418","t":"beh","l":"Behavioral","s":90,"q":"Besides yourself, who from your school should we hire?","k":["This question tests your confidence, maturity, and ability to recognize talent in others.","Do not say \"no one.\" Choose one or two peers who you genuinely respect and believe are strong candidates.","Briefly explain *why* you would recommend them. Focus on specific, relevant strengths. For example: \"I would recommend [Name]. I worked with them on a case competition, and their analytical rigor and ability to stay calm under pressure were truly impressive.\"","By confidently recommending a talented peer, you demonstrate that you are a secure, team-oriented individual, which is a highly valued trait."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview\nNew York Office"]},{"id":"q-2419","t":"beh","l":"Behavioral","s":90,"q":"Can you talk about a time you had to give negative feedback in the workplace?","k":["Situation: Describe the context and the specific behavior or performance issue that needed to be addressed.","Action: Explain how you delivered the feedback. Emphasize that it was done privately, respectfully, and focused on observable behaviors, not personality. Provide specific examples and explain the impact of the issue.","Result: Discuss the outcome. Ideally, the individual took the feedback constructively and their performance improved. Show that your goal was to help them develop, and mention what you learned about delivering feedback effectively."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview\nNew York office, Second round"]},{"id":"q-2420","t":"beh","l":"Behavioral","s":90,"q":"Who has been one of your role models?","k":["Select a specific role model (can be personal, historical, or a business leader) you genuinely admire.","Identify 2-3 specific qualities or achievements of this person that you respect (e.g., leadership style, integrity, strategic vision).","Provide a brief example of how they demonstrated these qualities.","Connect their influence to your own personal or professional aspirations."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview\nNew York Office, First round"]},{"id":"q-2421","t":"beh","l":"Behavioral","s":90,"q":"What are your thoughts on competition within investment banking? Do you believe it is healthy?","k":["Acknowledge that investment banking is an inherently competitive, performance-driven industry.","Define healthy competition as a force that drives excellence, innovation, and better outcomes for clients.","Distinguish it from unhealthy competition, which can be detrimental to teamwork and firm culture.","Emphasize your focus on collaboration and contributing to the team's collective success, while still being driven to perform at a high level."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview\nNew York Office, Second round"]},{"id":"q-2422","t":"beh","l":"Behavioral","s":90,"q":"What is your favorite book? Tell me about it and explain why it is your favorite.","k":["Choose a book you are genuinely passionate about and can discuss confidently.","Provide a very brief summary of the book's core theme or plot.","Explain *why* it resonates with you. Connect a key theme (e.g., perseverance, strategic thinking, leadership) to your own values or professional ambitions.","Demonstrate intellectual curiosity and the ability to articulate your thoughts clearly."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview\nNew York Office, Second round"]},{"id":"q-2423","t":"beh","l":"Behavioral","s":90,"q":"If you could pick one person from your recruiting class to work with, who would it be and why?","k":["This question tests your judgment of character and what you value in a teammate.","Choose a peer you genuinely respect and briefly describe a positive interaction you have had with them.","Focus on professional qualities such as their work ethic, collaborative nature, intellectual curiosity, or a specific skill they possess.","Explain how their strengths would complement yours in a team setting."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview\nNew York Office, First round"]},{"id":"q-2424","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time when, in hindsight, you feel you could've done a better job and did not meet your team's expectations.","k":["This is a \"failure\" question. Show accountability, self-awareness, and a growth mindset.","Use the STAR method:","- Situation: Briefly set the scene of a genuine instance of underperformance.","- Task: Clearly state what the expectation was.","- Action: Take ownership. Explain what you did and where you fell short.","- Result: Focus on the lessons learned. Explain what you would do differently today and provide a brief example of how you've applied that learning since."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Morgan Stanley Interview\nGeneralist, First round"]},{"id":"q-2425","t":"beh","l":"Behavioral","s":90,"q":"What type of deal would you most want to work on, and what has Morgan Stanley done in that area?","k":["Name a specific deal type (e.g., large-cap M&A, cross-border transactions, tech sector consolidation, restructuring) and explain why it excites you with genuine reasoning tied to your interests and background.","Reference one to two recent Morgan Stanley transactions in that area. Show you have done your research by briefly describing the deal and why it was strategically significant.","Explain what you would find most intellectually engaging about working on that type of transaction — the valuation complexity, the strategic dynamics, or the client advisory component.","Demonstrate awareness that Morgan Stanley's global platform and sector expertise position the firm well to execute these types of mandates."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Morgan Stanley Interview\nSA 2026, Superday"]},{"id":"q-2426","t":"beh","l":"Behavioral","s":90,"q":"What training or mentorship do you want the most from Morgan Stanley?","k":["Reference Morgan Stanley's structured training program and express enthusiasm for developing technical skills in financial modeling, valuation, and deal execution.","Highlight your desire for mentorship from senior bankers — the opportunity to learn how to think strategically about transactions, manage client relationships, and develop sound judgment through exposure to complex deals.","Mention a specific skill gap you want to close or an area where you want to deepen your expertise, showing self-awareness about where you are in your development.","Convey that you view the analyst or associate program as a two-year investment in building a world-class skillset, and that you intend to maximize every learning opportunity."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Morgan Stanley Interview\nSA 2026, Superday"]},{"id":"q-2427","t":"beh","l":"Behavioral","s":90,"q":"Explain investment banking to a five-year-old.","k":["Use a simple, relatable analogy. For example: \"Imagine you have a lemonade stand and you want to grow your business. You could buy your friend's lemonade stand next door to get bigger, or you could ask other people to give you money to help you grow. Investment bankers are like the helpers who figure out the best way to make that happen and help both sides agree on a fair price.\"","Keep it to 2-3 sentences maximum. The interviewer is testing your ability to distill a complex concept into clear, accessible language — a critical skill for client communication.","Avoid jargon entirely. If you cannot explain it simply, you do not understand it well enough."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Morgan Stanley Interview\nSA 2026, Generalist group, New York Office, First round"]},{"id":"q-2428","t":"beh","l":"Behavioral","s":90,"q":"When were you last frustrated?","k":["Choose a professional situation where your frustration was legitimate and relatable — such as a project that stalled due to factors outside your control, a team member not pulling their weight, or a process inefficiency that slowed progress.","Describe the situation briefly and honestly. Do not choose something trivial or something that reflects poorly on your temperament.","Focus the majority of your answer on how you handled the frustration: Did you take a step back and reassess? Did you address the issue directly and constructively? Did you channel the frustration into productive action?","Conclude with the resolution and the lesson learned. The goal is to show emotional intelligence, maturity, and the ability to remain composed and solution-oriented under pressure."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Morgan Stanley Interview\nSA 2026, Generalist group, New York Office, First round"]},{"id":"q-2429","t":"beh","l":"Behavioral","s":90,"q":"Where is the most interesting country you have ever been?","k":["Choose a country that you can speak about with genuine enthusiasm and detail. The specific country matters less than how articulately and engagingly you discuss it.","Briefly describe what made it interesting — the culture, history, geography, a specific experience, or the perspective it gave you.","Share a specific moment or observation that stood out. This makes your answer memorable and personal rather than generic.","This question assesses your ability to hold a conversation, your intellectual curiosity, and whether you are a well-rounded person. Be personable and concise."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Morgan Stanley Interview\nSA 2026, Generalist group, New York Office, First round"]},{"id":"q-2430","t":"beh","l":"Behavioral","s":90,"q":"What are some things that Morgan Stanley does well compared to other banks, and what are some things it could do better?","k":["What Morgan Stanley Does Well","Reference specific strengths: Morgan Stanley's leading equity franchise, its strong presence in technology and healthcare coverage, its integrated wealth management and institutional securities platform, and its collaborative culture consistently cited by employees.","Mention a recent transaction or league table ranking that demonstrates these strengths concretely.","Areas for Improvement","Be thoughtful and constructive, not critical. A strong approach is to reference an area where competitors have a marginal edge, not a fundamental flaw at Morgan Stanley. For example, you might note that some competitors have a larger leveraged finance or restructuring practice, and that expanding in those areas could further diversify the platform.","Frame it as an opportunity rather than a weakness. Show that you have done your research and can think critically about the firm in a respectful and informed way."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Morgan Stanley Interview\nSA 2025, Menlo Park Office, First round"]},{"id":"q-2431","t":"beh","l":"Behavioral","s":90,"q":"What is a subject they should teach at school that isn't currently being taught?","k":["Choose a subject you genuinely believe is missing and can discuss thoughtfully. Strong answers include: personal finance and investing, practical negotiation skills, data literacy and decision-making under uncertainty, or applied communication and persuasion.","Explain why this subject matters. Connect it to a real gap you have observed in your own education or among your peers.","Describe what the course would cover and why it would benefit students. Be specific enough to show you have thought about it beyond a surface level.","This question tests creativity, intellectual curiosity, and your ability to articulate a clear opinion. Take a definitive position and support it. Do not hedge."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Morgan Stanley Interview\nSA 2027"]},{"id":"q-2432","t":"beh","l":"Behavioral","s":90,"q":"What is your ideal team environment?","k":["Describe an environment that mirrors a banking deal team: collaborative, fast-paced, intellectually rigorous, and driven by shared commitment to delivering high-quality work for clients.","Highlight specific elements: open communication where junior team members can ask questions, clear expectations on deliverables and timelines, and a culture of constructive feedback that accelerates development.","Mention that you value working alongside motivated, high-caliber people who hold each other to a high standard. This signals that you will thrive in a demanding banking environment.","Reference a past team experience that exemplified your ideal environment and the positive outcome it produced."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Morgan Stanley Interview\nSA 2025, Healthcare group, SF Office, Superday"]},{"id":"q-2433","t":"beh","l":"Behavioral","s":90,"q":"What is the difference between a good manager and a bad manager?","k":["A good manager provides clear direction and context, ensuring their team understands not just what to do but why it matters. This enables junior team members to make better decisions independently.","A good manager gives timely, constructive feedback and invests in their team's development. They make themselves available for questions and create an environment where mistakes are learning opportunities.","A bad manager operates through unclear instructions, inconsistent expectations, or a lack of availability. This creates confusion, rework, and an environment where junior team members are afraid to ask for help.","Frame your answer around what you have observed or experienced. If you have had a great manager, describe what made them effective. This shows the interviewer the type of culture you value and your maturity in understanding professional dynamics."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Morgan Stanley Interview\nSA 2025, Healthcare group, SF Office, Superday"]},{"id":"q-2434","t":"beh","l":"Behavioral","s":90,"q":"You have two minutes to walk us through something you are an expert at. Go.","k":["Choose a topic you are genuinely passionate and knowledgeable about, whether academic, a hobby, or a skill.","Structure your explanation clearly: Start with a captivating opening, explain 2-3 key concepts or steps, and conclude with a memorable takeaway.","Focus on demonstrating your ability to communicate complex information concisely, articulately, and with enthusiasm.","This tests your poise and communication skills under pressure, not just the subject matter itself."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Perella Weinberg Interview\nChicago office"]},{"id":"q-2435","t":"beh","l":"Behavioral","s":90,"q":"What PJT deals have you been following?","k":["Name 2-3 specific and recent deals PJT has advised on, ideally from their restructuring (RSSG) or strategic advisory groups.","For each deal, briefly explain the strategic rationale: Why did the transaction make sense for the client?","Provide your own thoughtful opinion on the deal, discussing its potential impact, valuation, or challenges.","Connect the deals back to PJT's strengths, such as their expertise in complex restructurings or providing independent strategic advice."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in PJT Partners Interview\nNew York office, Superday"]},{"id":"q-2436","t":"beh","l":"Behavioral","s":90,"q":"What about this job worries you?\n\n\n\n\nFollow-up 1: How would you work with analysts?","k":["Primary Question:","Reframe \"worry\" as an anticipated challenge you are prepared to manage.","Focus on a realistic aspect of the job, such as the steep learning curve or maintaining a high level of precision under pressure.","Emphasize your proactive strategies for addressing this challenge, such as strong organizational skills, seeking feedback, and a dedicated work ethic.","Follow-up Question:","Describe a collaborative and supportive approach. For an Associate role, this means providing clear guidance, being accessible for questions, and mentoring.","Emphasize teamwork and mutual respect, fostering an environment where analysts can learn and develop."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in PJT Partners Interview\nNew York office, Superday"]},{"id":"q-2437","t":"beh","l":"Behavioral","s":90,"q":"What are your pastimes and hobbies?","k":["Mention 2-3 specific hobbies (e.g., sports, music, reading, cooking, volunteering).","Briefly explain your involvement or what you enjoy about each.","Keep descriptions concise and professional.","Show balance and interests outside of work/academics."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Raine Group Interview"]},{"id":"q-2438","t":"beh","l":"Behavioral","s":90,"q":"What is one thing that I should know that is not on your resume?","k":["Identify a positive trait or brief experience (e.g., self-taught skill, overcome challenge, unique perspective).","Provide a concise, concrete example illustrating this trait/experience.","Briefly connect it to why it adds value or reflects positively on your character/work ethic.","Keep it professional and memorable."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Raine Group Interview"]},{"id":"q-2439","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time when you delegated a responsibility to a junior team member.","k":["Situation: Set the context (project, team structure).","Task: Identify the specific responsibility delegated.","Action: Explain how you delegated – chose the right person, provided clear instructions, explained context/importance, offered support and check-ins.","Result: Describe the successful completion and benefits (task done well, junior member development, freed up your time)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Raine Group Interview"]},{"id":"q-2440","t":"beh","l":"Behavioral","s":90,"q":"If you had a weekend to yourself, how would you spend it?","k":["Outline a mix of activities: physical (exercise), social (friends/family), relaxing (reading/hobby), maybe practical (planning).","Keep the activities relatable and responsible.","Emphasize the goal of recharging and maintaining balance.","Avoid anything excessive or unprofessional."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Raine Group Interview"]},{"id":"q-2441","t":"beh","l":"Behavioral","s":90,"q":"What was the hardest part of your previous interview?","k":["Identify a specific challenging aspect of a previous interview (e.g., unexpected technical deep-dive, difficult brain teaser).","Briefly explain why it was challenging for you at that moment.","Frame it positively: emphasize what you learned from the experience.","Mention briefly how you addressed that gap afterwards (e.g., reviewed topic, practiced structuring)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Raine Group Interview"]},{"id":"q-2442","t":"beh","l":"Behavioral","s":90,"q":"What are the top 3 things that you hope to get out of a summer internship experience?","k":["Goal 1: Develop core technical skills (modeling, valuation, pitch decks) through hands-on work.","Goal 2: Gain real exposure to the lifecycle of deals and transaction processes.","Goal 3: Learn from experienced professionals, understand the firm culture (mention Raine Group), and contribute meaningfully to the team.","(Optional) Mention confirming interest and positioning for full-time."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Raine Group Interview"]},{"id":"q-2443","t":"beh","l":"Behavioral","s":90,"q":"You are in a meeting and a client is making sexist comments, with a female analyst also in the room. What do you do?","k":["Your primary goal is to protect your team member and uphold the firm's values, while navigating the client relationship carefully.","In the Moment: Do not engage with or validate the comment. Calmly and professionally redirect the conversation immediately back to the business at hand. \"That's an interesting point, but returning to the synergy analysis...\"","After the Meeting: Privately check in with your analyst to offer support and acknowledge that the behavior was unacceptable.","Escalate: Report the incident factually and promptly to your senior team member (VP/MD) and/or HR. This is not just a personal issue, but a firm-level risk."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in RBC Interview\nFirst round"]},{"id":"q-2444","t":"beh","l":"Behavioral","s":90,"q":"It's late at night and a valuation you are working on with another analyst is not producing the expected results. What do you do?","k":["First and foremost, maintain integrity. Never force the numbers to fit expectations.","Work systematically with your peer to troubleshoot. Double-check all inputs for errors, review key assumptions for reasonableness, and trace the formulas in the model to find any mechanical mistakes.","Sense-check the results. Compare the output to other valuation methodologies (e.g., if the DCF is off, how does it compare to the Comps?).","If the discrepancy persists after thorough checking, document the steps taken and the potential issues identified.","Prepare a concise summary and flag it for your associate or VP first thing in the morning, clearly explaining the issue and the diligence performed."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in RBC Interview\nFirst round"]},{"id":"q-2445","t":"beh","l":"Behavioral","s":90,"q":"Would you rather work on an IPO, a capital raise, or a sell-side M&A deal, and why?","k":["There is no single correct answer. The goal is to show you understand the differences and have a reasoned preference.","Briefly demonstrate your understanding of each process.","Choose one and provide 2-3 compelling reasons for your choice. For example, you might choose sell-side M&A for its deep strategic analysis and the tangible outcome of finding a company a new home.","Aligning your answer with the known strengths of the firm is a plus. For Rothschild, highlighting a preference for M&A advisory shows you have done your research."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Rothschild Interview\nFirst round"]},{"id":"q-2446","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time when you had to defend a decision.","k":["Use the STAR method. Situation: Choose an example where a decision you made was questioned or challenged.","Task: Explain the stakes and why the decision mattered.","Action: Describe how you defended your position with data and logic, listened to the opposing perspective, and either strengthened your case or incorporated valid feedback.","Result: Explain the outcome. Whether upheld or modified, focus on demonstrating conviction, analytical thinking, and professional composure under pressure."],"collection":"practice","topic":"Firm interview behaviorals","tags":["New\nReported in Stout Interview\nSA 2027, Second round"]},{"id":"q-2447","t":"beh","l":"Behavioral","s":90,"q":"Walk me through a typical day-to-day at your last job.","k":["Provide a structured, concise overview (2-3 minutes). A good structure is to walk through a typical day chronologically.","Focus on responsibilities and tasks that highlight skills relevant to banking: analytical work, attention to detail, project management, and communication.","Quantify your responsibilities and achievements where possible (e.g., \"I managed a portfolio of X clients,\" or \"I analyzed datasets with Y variables\").","Show enthusiasm and competence, ending on a forward-looking note about how these experiences prepared you for the analyst role."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in UBS Interview\nFirst round"]},{"id":"q-2448","t":"beh","l":"Behavioral","s":90,"q":"Tell me about your project management skills.","k":["Structure your answer around a specific project you managed.","Situation: Briefly describe the project's objective and scope.","Action: Explain the steps you took to manage it, highlighting key skills like organization (creating a timeline), time management (prioritizing tasks), communication (providing updates to stakeholders), and resourcefulness (solving problems).","Result: State the successful outcome of the project, quantifying the achievement if possible (e.g., delivered on time, under budget)."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2449","t":"beh","l":"Behavioral","s":90,"q":"You discover a mistake in a pitch deck after your deal lead has already left for the client meeting with the printed copies. What is your course of action?","k":["This is a test of problem-solving, proactivity, and communication under pressure.","Step 1 (Immediate Communication): Instantly try to contact your deal lead through multiple channels (text, email) to alert them to the mistake. Be concise and clear about the error and its location.","Step 2 (Provide Solution): Simultaneously, correct the error on the digital version of the deck.","Step 3 (Deliver Solution): Email the corrected slide or the full revised presentation to your deal lead, so they have it digitally before or during the meeting."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2450","t":"beh","l":"Behavioral","s":90,"q":"What is something intellectual that you do for fun?","k":["Choose a genuine intellectual hobby that showcases your curiosity (e.g., reading non-fiction on a specific topic, playing strategy games like chess, learning a new language or coding).","Briefly explain what you enjoy about the activity.","Mention a specific insight or skill you have gained from it. For example, how chess improved your strategic thinking.","This demonstrates a passion for learning and problem-solving outside of a formal academic or professional context."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2451","t":"beh","l":"Behavioral","s":90,"q":"Explain the most complicated thing you know.","k":["The goal is to demonstrate your ability to distill a complex topic into simple, understandable terms.","Choose a subject you understand deeply, whether it's from your academic field, a past job, or a personal interest.","Structure your explanation logically. Start with a high-level overview, then break it down into 2-3 core components.","Use an analogy if it helps clarify the concept. Avoid jargon and focus on clarity and conciseness."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2452","t":"beh","l":"Behavioral","s":90,"q":"If you had unlimited funds and no ethical constraints, what scientific experiment would you conduct?","k":["This question tests your creativity, ambition, and thought process.","Identify a major, unanswered question in a field that interests you (e.g., medicine, physics, psychology, economics).","Clearly state the hypothesis you would want to test.","Briefly outline the experimental design and explain why it would provide a definitive answer.","Conclude by describing the potential impact of your findings on science or humanity."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2453","t":"beh","l":"Behavioral","s":90,"q":"An associate is expected to be a manager, have strong attention to detail, and possess excellent financial skills. Which of these three are you best at? You can only pick one.","k":["Select one of the three qualities: management, attention to detail, or financial skills.","Provide a specific, concise example from your past experience that powerfully demonstrates your chosen strength in action.","Briefly explain why this skill is crucial for an associate role.","Acknowledge that while this is your strongest area, you recognize that all three are essential and interconnected for success in the role."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2454","t":"beh","l":"Behavioral","s":90,"q":"Would you ever advise a client to do a deal that destroys shareholder value?","k":["State clearly and unequivocally that you would not.","Explain that your primary duty as an investment banker is to the shareholders of the client company, who are represented by the Board of Directors.","Articulate that even if management (CEO/CFO) is pushing for a deal, your analysis and advice must be based on what is best for the shareholders.","Conclude that if your analysis proves a deal is value-destructive, it is your professional and ethical obligation to advise against it."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2455","t":"beh","l":"Behavioral","s":90,"q":"As a new associate, how would you manage an experienced analyst, especially when you are still learning the job yourself?","k":["Acknowledge the analyst's experience and state your intention to build a collaborative, respectful partnership.","Emphasize leveraging their technical expertise while you focus on the associate's role: managing the overall process, interfacing with seniors, and ensuring the final product meets the team's objectives.","State that you would foster an open environment, encouraging their input and ideas, viewing it as a team effort.","Mention your focus on learning quickly to complement their skills and effectively guide the workstream."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2456","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a project you've worked on. What was the goal and what were your specific contributions?","k":["Situation: Briefly describe the project and the team's overall objective.","Task: Explain the specific goal you were tasked with achieving.","Action: Detail the specific actions *you* took, focusing on the skills you used (e.g., analysis, modeling, research, communication).","Result: Describe the outcome of your actions, quantifying the impact if possible (e.g., \"identified a key risk,\" \"streamlined the analysis, saving X hours\")."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2457","t":"beh","l":"Behavioral","s":90,"q":"How do I know you can handle the hours of this job?","k":["Acknowledge the demanding nature of investment banking and state your readiness to meet the challenge.","Provide a specific example of a time you successfully managed a heavy workload, citing experiences from a previous demanding job, rigorous academic schedule, or intense extracurricular activity.","Highlight your time management and organizational skills, explaining how you prioritize tasks effectively under pressure.","Conclude by expressing your motivation and commitment to doing what it takes to get the job done."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2458","t":"beh","l":"Behavioral","s":90,"q":"What project are you most proud of and why?","k":["Situation: Briefly set the scene for the project and its objectives.","Task: Describe your specific role and the challenge you faced.","Action: Detail the steps you took, highlighting the skills and effort you applied.","Result: Explain the positive outcome and, most importantly, articulate *why* you are proud of it (e.g., \"It was the first time I led...\", \"The analysis had a direct impact on...\", \"I overcame a significant obstacle...\")."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2459","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a workflow or project where you were the primary owner or subject-matter expert.","k":["Situation: Describe the project or workflow and why you became the expert or owner.","Task: Explain your responsibilities and the goals you were expected to achieve.","Action: Detail the steps you took to manage the process, solve problems, and guide others, showcasing your expertise.","Result: Quantify the successful outcome and highlight how your ownership contributed to it."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2460","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you exceeded expectations.","k":["Situation/Task: Briefly describe the project and what was typically expected for that task.","Action: Detail the specific, additional steps you took that went above and beyond the standard requirement.","Result: Explain the positive outcome of your extra effort, using metrics or strong qualitative descriptions to show the added value you created."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2461","t":"beh","l":"Behavioral","s":90,"q":"A client asks you for confidential information about another client. What do you do?","k":["State that you would immediately and politely decline the request.","Explain clearly that sharing confidential client information is a violation of company policy and your professional duty.","Avoid being confrontational. You can frame it as, \"To protect all our clients, including yourself, we have a strict policy against sharing confidential information.\"","Mention that you would document the request and report it to your manager or compliance department to ensure the firm is aware."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2462","t":"beh","l":"Behavioral","s":90,"q":"You are joining a team where the Analyst, VP, and MD are all known to be difficult to work with. How do you approach this situation?","k":["State that you would start with a positive and open mindset, avoiding preconceived notions based on hearsay.","Focus on what you can control: the quality and timeliness of your work. Aim to be impeccably reliable and detail-oriented.","Proactively seek to understand each person's working style and expectations to minimize friction.","Maintain professionalism at all times, stay out of office gossip, and build relationships based on the quality of your contributions to the team."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2463","t":"beh","l":"Behavioral","s":90,"q":"A few weeks into the job, the VP from the difficult team says your work quality is poor and has not improved, despite your best efforts. What do you do?","k":["First, listen calmly and do not get defensive. Thank the VP for the direct feedback.","Ask for specific, concrete examples of where your work has fallen short to ensure you clearly understand the issues.","Reiterate your commitment to meeting their expectations and ask for guidance on how to improve or for an example of 'what good looks like'.","Propose a plan of action, such as reviewing work more thoroughly or requesting a brief check-in on the next assignment to ensure you're on the right track."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2464","t":"beh","l":"Behavioral","s":90,"q":"You join a new deal team, taking over for someone who has left. You quickly realize that the existing financial model and data analysis are incorrect. What is your course of action?","k":["First, double-check your own analysis to be certain the existing work is incorrect and you understand the source of the errors.","Do not broadcast the mistake. Schedule a private meeting with your immediate superior (likely the Associate or VP).","Present your findings factually and calmly. Frame it as \"I was reviewing the model and found some discrepancies I'd like to walk you through,\" rather than \"The previous analyst made huge mistakes.\"","Come prepared with a plan to fix the errors and an estimate of how long it will take, showing you are solution-oriented."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2465","t":"beh","l":"Behavioral","s":90,"q":"What is the biggest risk you have taken in your life? What are you most proud of?","k":["Biggest Risk:","Describe a situation where you stepped out of your comfort zone (professionally, academically, or personally).","Explain how you assessed the potential upside and downside, demonstrating a calculated, not reckless, approach.","Conclude with the outcome and what you learned from the experience, regardless of whether it was a success or failure.","Most Proud Of:","Use the STAR method to describe a specific achievement.","Focus on why it makes you proud – the dedication it required, the obstacle you overcame, or the impact you had on others."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2466","t":"beh","l":"Behavioral","s":90,"q":"Describe a time you exhibited entrepreneurial thinking or behavior.","k":["Describe a situation where you identified a problem, an inefficiency, or an unmet need.","Explain how you took the initiative to develop a solution or a new approach, even if it wasn't explicitly your responsibility.","Detail the steps you took to implement your idea and the outcome.","Connect this experience to the proactive and results-driven mindset required in investment banking."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2467","t":"beh","l":"Behavioral","s":90,"q":"Why are you interested in technology, specifically technology M&A, and why do you want to work in San Francisco?","k":["Why Technology: Express genuine interest in the sector's innovation, rapid growth, and transformative impact on other industries. Mention a specific sub-sector or trend that fascinates you.","Why Tech M&A: Explain your interest in advising tech companies on their most critical strategic decisions and the complex, analytical nature of M&A transactions.","Why San Francisco: State the clear advantage of being at the global center of the tech ecosystem, with proximity to the most innovative companies and key industry leaders."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview\nTechnology M&A group, SF Office"]},{"id":"q-2468","t":"beh","l":"Behavioral","s":90,"q":"What are your top three firms you are recruiting for and why?","k":["Name the firm you are interviewing with as your top choice.","Provide 2-3 specific reasons why they are your top choice (e.g., specific deals they've led, their reputation in a particular industry, conversations you've had with their employees, cultural fit).","Mention two other comparable firms, and for each, provide one brief, specific reason for your interest.","Subtly reiterate that the firm you are interviewing with is the best fit for your specific interests and goals."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2469","t":"beh","l":"Behavioral","s":90,"q":"What is the single most important skill for an investment banking associate?","k":["Choose a critical associate-level skill, such as project management, effective delegation, or serving as the communication bridge between junior and senior bankers.","Explain *why* this skill is the most important. For example, \"Effective project management is crucial because associates are the hub of the deal team, responsible for ensuring all workstreams are progressing correctly and deadlines are met.\"","Briefly contrast it with the analyst role (which is more focused on pure technical execution) to show you understand the progression of responsibilities."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2470","t":"beh","l":"Behavioral","s":90,"q":"If you could pick one person from your recruiting class to work with, who would it be and why?","k":["Think of a peer you genuinely respect (you don't need to use their name).","Describe the 2-3 key qualities that would make them a great teammate.","Focus on professional traits relevant to banking, such as a strong work ethic, intellectual curiosity, being a supportive team player, or having a calm demeanor under pressure.","Conclude by explaining that these are the qualities you also strive to embody as a team member."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2471","t":"beh","l":"Behavioral","s":90,"q":"If you were a company for sale, what would be the top three investment highlights about you as an associate candidate in a Confidential Information Memorandum (CIM)?","k":["Highlight 1: \"Exceptional Analytical Rigor and Technical Foundation.\" Briefly mention a complex project or skill (e.g., modeling) that demonstrates this.","Highlight 2: \"Proven Resilience and Work Ethic in High-Pressure Environments.\" Provide evidence from a past demanding experience (work, academic, etc.).","Highlight 3: \"Strong Interpersonal Skills and a Collaborative Mindset.\" Give an example of successful teamwork or communication."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview"]},{"id":"q-2472","t":"beh","l":"Behavioral","s":90,"q":"Your VP has a meeting with a management team in two hours. You and an analyst have been working on the presentation. Last night, you left the analyst to finish some instrumental slides. This morning, your analyst and the slide edits are nowhere to be found. What do you do?","k":["Inform the VP Immediately: Give your VP a calm, concise update. Manage their expectations by stating that the slides are not ready but you are working to finish them ASAP for their review.","Take Ownership and Execute: Do not blame the analyst. Your immediate focus is to complete the critical slides yourself to the best of your ability. Prioritize the most essential information for the meeting.","Deliver and Communicate Status: Send the presentation to the VP with enough time for them to review it. Clearly and briefly flag any areas that are still pending or assumptions you had to make.","Follow Up with the Analyst: After the immediate crisis is handled, attempt to contact the analyst to understand what happened."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Unspecified Interview\nSuperday"]},{"id":"q-2473","t":"beh","l":"Behavioral","s":90,"q":"Are you more technical or a better writer? Why are you less proficient at one than the other?","k":["Identify Your Primary Strength: State which skill you believe is stronger and provide a brief, concrete example of where you have excelled.","Frame the Other Skill as a Development Area: Avoid saying you are 'bad' at the other skill. Instead, frame it as an area you are actively developing (e.g., \"While I'm confident in my writing, I've focused more on honing my technical skills...\").","Show Proactive Improvement: Describe specific steps you are taking to improve your 'weaker' area, such as seeking feedback, taking courses, or practicing deliberately.","Reiterate the Importance of Both: Conclude by stating that you recognize both skills are critical for a successful analyst and you are committed to excelling in both."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Wells Fargo Interview\nSuperday"]},{"id":"q-2474","t":"beh","l":"Behavioral","s":90,"q":"Your managing director requests a deck to be compiled and turned in by 9 am. It is 11 pm and you and another analyst are the only ones in the office. What do you do?","k":["Assess and Strategize: Quickly evaluate the remaining work with the other analyst. Create a clear plan and timeline, dividing tasks based on each person's strengths.","Collaborate and Communicate: Work in parallel and maintain open communication. Schedule brief, periodic check-ins to ensure consistency and address any roadblocks.","Prioritize Quality Control: Build in a dedicated block of time before the deadline for both of you to review the entire presentation for accuracy and consistency.","Execute and Deliver: Focus on efficiently completing the work to a high standard and delivering the final product on time."],"collection":"practice","topic":"Firm interview behaviorals","tags":["Reported in Wells Fargo Interview\nSuperday"]},{"id":"q-2475","t":"beh","l":"Behavioral","s":90,"q":"What’s your biggest strength, and how do you apply it at work?","k":["Pick a clear, relevant skill (detail-orientation, teamwork, etc.)","Give a short anecdote of when you used it effectively","Highlight positive impact or achievements"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2476","t":"beh","l":"Behavioral","s":90,"q":"What’s your biggest weakness?","k":["Select a true weakness (e.g., delegating tasks, overthinking)","Explain how you recognized it","Mention the steps you’re taking to improve"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2477","t":"beh","l":"Behavioral","s":90,"q":"Tell me your three greatest strengths and three greatest weaknesses.","k":["Strengths: Pick three you’ve demonstrated (e.g. attention to detail, quick learner, strong communication). Give brief anecdotes.","Weaknesses: Mention real areas of growth (e.g. delegating too little, overcommitment) and your improvement plan.","Avoid clichés or weaknesses that raise serious red flags for IB (e.g. “poor under stress”)."],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2478","t":"beh","l":"Behavioral","s":90,"q":"How has feedback from a past review shaped your professional growth?","k":["Reference a formal or informal performance review","Detail the advice given","Show how you implemented it and the positive outcome"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2479","t":"beh","l":"Behavioral","s":90,"q":"Which skill do you want to improve the most this year?","k":["Pick a technical or soft skill crucial for banking","Explain why it’s important and how you plan to improve","Show enthusiasm for continuous learning"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2480","t":"beh","l":"Behavioral","s":90,"q":"If I asked your last manager about you, what would they praise and criticize?","k":["Highlight 1–2 strengths they would appreciate","Note a realistic area they’d say you can refine","Briefly show how you’re working on that area"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2481","t":"beh","l":"Behavioral","s":90,"q":"What do you do better than most of your peers?","k":["Focus on a skill that truly distinguishes you","Provide brief evidence or story","Avoid sounding arrogant—phrase it confidently but humbly"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2482","t":"beh","l":"Behavioral","s":90,"q":"How do you typically react when someone points out errors in your work?","k":["Thank them for catching the mistake","Fix it promptly and note the lesson learned","Prevent future recurrences by adjusting your process"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2483","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time your performance exceeded expectations.","k":["Identify the baseline expectation","Describe how you delivered more than required","Quantify or qualify the positive results"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2484","t":"beh","l":"Behavioral","s":90,"q":"What’s a skill you once struggled with but have now mastered?","k":["Explain initial difficulties and how you felt","Outline the resources or methods used to improve","Emphasize the noticeable improvements or success metrics"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2485","t":"beh","l":"Behavioral","s":90,"q":"Which area of finance do you feel least comfortable with?","k":["Admit an area that’s not your strongest yet","Detail resources or steps you’re taking to learn","Reinforce your passion to round out your skillset"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2486","t":"beh","l":"Behavioral","s":90,"q":"If your team gave you an award, what would it be for?","k":["Highlight the positive trait you’re known for","Include a short anecdote supporting it","Connect it back to high-impact IB roles"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2487","t":"beh","l":"Behavioral","s":90,"q":"How do you handle it if your best effort still isn’t good enough?","k":["Admit disappointment but accept reality","Seek feedback on gaps or mistakes","Plan how you’ll refine your approach moving forward"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2488","t":"beh","l":"Behavioral","s":90,"q":"What professional skill have you been praised for the most?","k":["Select the skill singled out by previous managers/peers","Offer a quick example or scenario where it shone","Show how it directly applies to IB work"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2489","t":"beh","l":"Behavioral","s":90,"q":"Can you share a time you got something seriously wrong in a project?","k":["Describe the error succinctly","Show how you corrected it once discovered","Explain your new process to avoid repeating it"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2490","t":"beh","l":"Behavioral","s":90,"q":"How would you rate your ability to take criticism on a scale of 1-10?","k":["Choose a high rating (8-9) but mention you’re always improving","Give an example of handling critique positively","Explain how feedback drives your growth"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2491","t":"beh","l":"Behavioral","s":90,"q":"Has anyone ever called you “uncoachable” or “inflexible”?","k":["If yes, explain the instance and your corrective actions","If no, share a story of your adaptability or willingness to learn","Underscore your open-minded attitude"],"collection":"practice","topic":"Strengths, Weaknesses & Feedback","tags":["Strengths, Weaknesses & Feedback"]},{"id":"q-2492","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you led a team under pressure.","k":["Describe the high-stakes context (tight deadline, major deliverable)","Explain your leadership approach (delegation, check-ins, motivation)","Quantify the outcome (successful completion, positive feedback)"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2493","t":"beh","l":"Behavioral","s":90,"q":"Describe a situation where you delegated tasks effectively.","k":["Identify team members’ distinct skills","Assign tasks aligning with those strengths","Track progress with regular updates to ensure accountability"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2494","t":"beh","l":"Behavioral","s":90,"q":"Have you ever influenced a senior leader’s decision? How did you do it?","k":["Gathered relevant data or evidence","Presented in a concise, solution-oriented manner","Addressed concerns and aligned decision with overall goals"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2495","t":"beh","l":"Behavioral","s":90,"q":"Talk about a time your team had low morale. What did you do?","k":["Acknowledged the team’s concerns and frustrations","Instilled a sense of purpose and set achievable short-term targets","Checked in individually to offer support and celebrate small victories"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2496","t":"beh","l":"Behavioral","s":90,"q":"When you’re in charge, how do you manage someone who isn’t pulling their weight?","k":["Address it one-on-one to understand obstacles","Set clear performance expectations and deadlines","If issues persist, escalate with documented feedback"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2497","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you took on a leadership role without formal authority.","k":["Identify the gap that needed leadership","Lead by example, offering solutions and rallying support","Ensured team recognized mutual benefits of your approach"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2498","t":"beh","l":"Behavioral","s":90,"q":"What’s the toughest leadership challenge you’ve faced, and how did you handle it?","k":["Set the stage: intense conflict or misalignment","Mediate by listening and clarifying shared goals","Implemented a fair compromise and monitored progress"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2499","t":"beh","l":"Behavioral","s":90,"q":"Have you ever managed someone older or more experienced than you?","k":["Recognized their expertise and sought their input","Clarified common objectives and roles","Maintained professionalism and respect for their experience"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2500","t":"beh","l":"Behavioral","s":90,"q":"Describe a time you replaced a failing leader or stepped in to clean up a messy situation.","k":["Identified immediate blockers and critical tasks","Reassigned roles, set realistic deadlines","Communicated progress regularly and celebrated quick wins"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2501","t":"beh","l":"Behavioral","s":90,"q":"How do you measure success within your team?","k":["Track quantitative metrics (deadlines met, error rates)","Assess team morale and collaboration","Check if responsibilities are distributed fairly"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2502","t":"beh","l":"Behavioral","s":90,"q":"When have you influenced the culture or atmosphere of a team for the better?","k":["Noticed low engagement or poor communication","Introduced a brief daily huddle or “weekly wins” discussion","Improved transparency and positive reinforcement"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2503","t":"beh","l":"Behavioral","s":90,"q":"Talk about a time you motivated someone struggling with a task.","k":["Identified gaps in their approach or understanding","Provided tailored support or guidance","Monitored progress and acknowledged improvements quickly"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2504","t":"beh","l":"Behavioral","s":90,"q":"How do you typically provide feedback to teammates?","k":["Give feedback soon after the event","Be specific: mention exact observations","Offer solutions or improvements, not just criticism"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2505","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you formed a team from scratch.","k":["Defined clear roles and responsibilities","Selected members with complementary skills","Set up early communication norms and goals"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2506","t":"beh","l":"Behavioral","s":90,"q":"Describe a successful team project. What was your role in making it successful?","k":["Set the context: project scope and goals","Highlight your specific contributions (analysis, leading calls, etc.)","Show the tangible results: numbers or client praise"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2507","t":"beh","l":"Behavioral","s":90,"q":"How do you balance being both a leader and a team player?","k":["Lead by empowering others and sharing credit","Listen actively to all viewpoints","Delegate appropriately, but own ultimate accountability"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2508","t":"beh","l":"Behavioral","s":90,"q":"Have you ever disagreed with a leadership mandate? What did you do?","k":["Privately requested clarity on the rationale","Offered an alternative perspective respectfully","Aligned with final decision once it was clearly explained"],"collection":"practice","topic":"Team & Leadership","tags":["Team & Leadership"]},{"id":"q-2509","t":"beh","l":"Behavioral","s":90,"q":"Tell me about a time you had to work extremely long hours. How did you cope?","k":["Detail the workload and deadlines","Show how you organized tasks and kept energy up","Mention the successful outcome or lessons learned"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2510","t":"beh","l":"Behavioral","s":90,"q":"What’s the toughest deadline you’ve faced, and how did you meet it?","k":["Describe the high-stress timeline","Explain how you broke tasks into manageable parts","Highlight on-time or early completion"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2511","t":"beh","l":"Behavioral","s":90,"q":"When did you go “above and beyond” for a project or client?","k":["Reference a specific scenario with tight constraints","Emphasize your extra initiative or late-night efforts","Note the positive impact on deliverables or client satisfaction"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2512","t":"beh","l":"Behavioral","s":90,"q":"How do you stay motivated during repetitive or mundane tasks?","k":["Focus on the end goal (a polished deliverable)","Set mini-deadlines to stay engaged","Remember that thoroughness is valued in banking"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2513","t":"beh","l":"Behavioral","s":90,"q":"This role requires 80-100 hours a week. How do you feel about that?","k":["Acknowledge it’s demanding and not for everyone","Cite a previous period of heavy workload you managed","Reiterate your commitment to the learning opportunity"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2514","t":"beh","l":"Behavioral","s":90,"q":"What activities or responsibilities have you given up to pursue IB?","k":["List personal hobbies or side commitments you scaled back","Demonstrate you’ve prioritized professional goals","Show seriousness about the demanding nature of IB"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2515","t":"beh","l":"Behavioral","s":90,"q":"Describe a time you balanced multiple major commitments successfully.","k":["Mention big academic, work, or extracurricular challenges","Explain your scheduling or priority-setting techniques","Highlight completion of all tasks without compromising quality"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2516","t":"beh","l":"Behavioral","s":90,"q":"Have you ever struggled to keep up with a demanding workload? What did you do?","k":["Admit the difficulty and the cause (time, complexity)","Explain how you recalibrated or delegated tasks","Outcome: how you improved output or avoided burnout"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2517","t":"beh","l":"Behavioral","s":90,"q":"How do you respond when teammates are not matching your level of effort?","k":["Discuss the importance of clarifying goals","Ask if they need resources or guidance","Give them a chance to step up before escalating"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2518","t":"beh","l":"Behavioral","s":90,"q":"Have you ever chosen work over social or personal events?","k":["Cite a specific example of missing an event for a deadline","Show acceptance of the trade-off","Confirm your willingness to do this in IB as needed"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2519","t":"beh","l":"Behavioral","s":90,"q":"When have you proactively taken on extra responsibilities without being asked?","k":["Reference a gap or opportunity you noticed","Explain how you took ownership and drove results","Highlight recognition or performance outcomes"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2520","t":"beh","l":"Behavioral","s":90,"q":"Talk about a time you had zero instructions but still made real progress.","k":["Describe the ambiguous situation","Explain your steps: research, stakeholder consultation, etc.","Underline the successful end result"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2521","t":"beh","l":"Behavioral","s":90,"q":"What keeps you going when work gets extremely intense?","k":["Reference your long-term career vision","Discuss motivation from teamwork and delivering results","Mention your personal work ethic or coping strategies"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2522","t":"beh","l":"Behavioral","s":90,"q":"Describe a scenario where you had to learn a complex task on the fly under time pressure.","k":["Give the context: unexpected assignment or short notice","Explain your approach to rapid learning (tutorials, mentors)","Highlight a successful implementation or timely delivery"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2523","t":"beh","l":"Behavioral","s":90,"q":"How do you respond when you see a gap in your team’s workflow?","k":["Describe the inefficiency or gap you noticed","Outline the solution you implemented","Show the positive effect on project outcomes"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2524","t":"beh","l":"Behavioral","s":90,"q":"Have you ever burned out? How did you bounce back?","k":["Be honest about feeling overwhelmed","Describe how you recovered (reassessing priorities, seeking help)","Mention strategies to prevent recurrence"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]},{"id":"q-2525","t":"beh","l":"Behavioral","s":90,"q":"In IB you may work holidays and weekends. Does that concern you?","k":["Show you’ve thought about the lifestyle trade-offs","Emphasize your career priorities at this stage","Express willingness to make those sacrifices"],"collection":"practice","topic":"Work Ethic & Commitment","tags":["Work Ethic & Commitment"]}];
